window.PV_BANK=[{"id":"licensing-001","scope":"FL","cat":"licensing","sign":null,"c":1,"en":{"q":"In Florida, what is the youngest age to get a learner license?","o":["14 years old","15 years old","16 years old","17 years old"],"h1":"It comes one year before the age for a regular Class E license.","h2":"You can get a Florida learner license when you are 15 years old, one year before you can get a Class E license at 16.","p":"Right. The learner license starts at age 15."},"es":{"q":"En Florida, ¿cuál es la edad mínima para obtener una licencia de aprendiz?","o":["14 años","15 años","16 años","17 años"],"h1":"Es un año antes de la edad para la licencia Clase E normal.","h2":"Usted puede obtener la licencia de aprendiz en Florida a los 15 años, un año antes de poder obtener la licencia Clase E a los 16.","p":"Correcto. La licencia de aprendiz empieza a los 15 años."},"zh":{"q":"在 Florida，最小几岁可以拿到学习驾照？","o":["14 岁","15 岁","16 岁","17 岁"],"h1":"它比普通 Class E 驾照的年龄早一年。","h2":"你 15 岁时可以拿到 Florida 学习驾照，比 16 岁可以拿到的 Class E 驾照早一年。","p":"对。学习驾照从 15 岁开始。"},"vi":{"q":"Ở Florida, tuổi nhỏ nhất để được cấp giấy phép tập lái là bao nhiêu?","o":["14 tuổi","15 tuổi","16 tuổi","17 tuổi"],"h1":"Tuổi này sớm hơn một năm so với tuổi được cấp bằng lái Class E thông thường.","h2":"Bạn có thể được cấp giấy phép tập lái ở Florida khi bạn 15 tuổi, sớm hơn một năm so với bằng lái Class E lúc 16 tuổi.","p":"Đúng. Giấy phép tập lái bắt đầu từ 15 tuổi."},"tl":{"q":"Sa Florida, ilang taon ang pinakabatang edad para makakuha ng learner license?","o":["14 taong gulang","15 taong gulang","16 taong gulang","17 taong gulang"],"h1":"Isang taon ito bago ang edad para sa karaniwang Class E license.","h2":"Puwede kang kumuha ng Florida learner license kapag 15 taong gulang ka na, isang taon bago ka puwedeng kumuha ng Class E license sa edad na 16.","p":"Tama. Nagsisimula ang learner license sa edad na 15."},"ar":{"q":"في Florida، ما أصغر عمر للحصول على رخصة متعلم؟","o":["14 سنة","15 سنة","16 سنة","17 سنة"],"h1":"هذا العمر يأتي قبل سنة واحدة من عمر الرخصة العادية Class E.","h2":"يمكنك الحصول على رخصة متعلم في Florida عندما يكون عمرك 15 سنة، أي قبل سنة من الحصول على رخصة Class E في عمر 16.","p":"صحيح. رخصة المتعلم تبدأ في عمر 15 سنة."},"ht":{"q":"Nan Florida, ki laj ki pi piti pou w ka jwenn yon lisans aprantisaj?","o":["14 an","15 an","16 an","17 an"],"h1":"Li vini yon ane anvan laj pou yon lisans Class E nòmal.","h2":"Ou ka jwenn yon lisans aprantisaj nan Florida lè ou gen 15 an, yon ane anvan ou ka jwenn yon lisans Class E a 16 an.","p":"Se sa. Lisans aprantisaj la kòmanse a 15 an."},"ref":{"doc":"FL","page":8}},{"id":"licensing-002","scope":"FL","cat":"licensing","sign":null,"c":3,"en":{"q":"In Florida, a driver with a learner license must have someone with them. How old must that person be?","o":["At least 16 years old","At least 18 years old","At least 25 years old","At least 21 years old"],"h1":"The helper must be an experienced adult, older than a new 18-year-old driver.","h2":"A learner must always drive with a licensed driver who is at least 21 years old, because that person needs adult experience to guide them.","p":"Right. The person with you must be a licensed driver age 21 or older."},"es":{"q":"En Florida, quien tiene licencia de aprendiz debe ir acompañado. ¿Qué edad debe tener esa persona?","o":["Por lo menos 16 años","Por lo menos 18 años","Por lo menos 25 años","Por lo menos 21 años"],"h1":"El acompañante debe ser un adulto con experiencia, mayor que un conductor nuevo de 18 años.","h2":"El aprendiz siempre debe manejar con un conductor con licencia que tenga por lo menos 21 años, porque esa persona necesita experiencia de adulto para guiarlo.","p":"Correcto. Su acompañante debe tener licencia y 21 años o más."},"zh":{"q":"在 Florida，持学习驾照的司机必须有人陪同。这个人必须几岁？","o":["至少 16 岁","至少 18 岁","至少 25 岁","至少 21 岁"],"h1":"陪同的人必须是有经验的成年人，比刚满 18 岁的新司机年龄大。","h2":"学习驾驶的人必须一直和一位至少 21 岁、有驾照的司机一起开车，因为这个人需要有成年人的经验来指导。","p":"对。陪你的人必须是 21 岁或以上、有驾照的司机。"},"vi":{"q":"Ở Florida, người có giấy phép tập lái phải có người đi cùng. Người đó phải bao nhiêu tuổi?","o":["Ít nhất 16 tuổi","Ít nhất 18 tuổi","Ít nhất 25 tuổi","Ít nhất 21 tuổi"],"h1":"Người đi cùng phải là người lớn có kinh nghiệm, lớn tuổi hơn một tài xế mới 18 tuổi.","h2":"Người tập lái luôn phải lái xe cùng một người có bằng lái và ít nhất 21 tuổi, vì người đó cần có kinh nghiệm của người lớn để hướng dẫn.","p":"Đúng. Người đi cùng bạn phải có bằng lái và từ 21 tuổi trở lên."},"tl":{"q":"Sa Florida, ang driver na may learner license ay dapat may kasama. Ilang taon dapat ang kasamang iyon?","o":["Hindi bababa sa 16 taong gulang","Hindi bababa sa 18 taong gulang","Hindi bababa sa 25 taong gulang","Hindi bababa sa 21 taong gulang"],"h1":"Ang kasama ay dapat isang adult na may karanasan, mas matanda pa sa bagong driver na 18 taong gulang.","h2":"Ang learner ay dapat laging magmaneho kasama ang isang lisensyadong driver na hindi bababa sa 21 taong gulang, dahil kailangan ng taong iyon ang karanasan ng adult para gabayan siya.","p":"Tama. Ang kasama mo ay dapat lisensyadong driver na 21 taong gulang o higit pa."},"ar":{"q":"في Florida، يجب أن يكون مع السائق الذي يحمل رخصة متعلم شخص آخر. كم يجب أن يكون عمر هذا الشخص؟","o":["16 سنة على الأقل","18 سنة على الأقل","25 سنة على الأقل","21 سنة على الأقل"],"h1":"يجب أن يكون المرافق شخصًا بالغًا له خبرة، وأكبر من سائق جديد عمره 18 سنة.","h2":"يجب على المتعلم أن يقود دائمًا مع سائق مرخّص عمره 21 سنة على الأقل، لأن هذا الشخص يحتاج إلى خبرة البالغين ليرشده.","p":"صحيح. يجب أن يكون الشخص الذي معك سائقًا مرخّصًا عمره 21 سنة أو أكثر."},"ht":{"q":"Nan Florida, yon chofè ki gen lisans aprantisaj dwe toujou gen yon moun avè l. Ki laj moun sa a dwe genyen?","o":["Omwen 16 an","Omwen 18 an","Omwen 25 an","Omwen 21 an"],"h1":"Moun ki ede w la dwe yon granmoun ki gen eksperyans, ki pi gran pase yon nouvo chofè 18 an.","h2":"Yon apranti dwe toujou kondi ak yon chofè ki gen lisans epi ki gen omwen 21 an, paske moun sa a bezwen eksperyans granmoun pou l gide l.","p":"Se sa. Moun ki avè w la dwe yon chofè ki gen lisans, ki gen 21 an oswa plis."},"ref":{"doc":"FL","page":25}},{"id":"licensing-003","scope":"FL","cat":"licensing","sign":null,"c":0,"en":{"q":"In Florida, where must the licensed adult sit when a learner is driving?","o":["In the front passenger seat","In any back seat","Behind the driver","Anywhere in the car"],"h1":"The adult must be able to see the road and help right away.","h2":"The licensed adult must sit in the front passenger seat, next to the learner, so they can watch the road and help quickly.","p":"Right. The adult sits in the front seat, next to you."},"es":{"q":"En Florida, ¿dónde debe sentarse el adulto con licencia cuando maneja un aprendiz?","o":["En el asiento delantero del pasajero","En cualquier asiento de atrás","Detrás del conductor","En cualquier lugar del carro"],"h1":"El adulto debe poder ver la calle y ayudar enseguida.","h2":"El adulto con licencia debe sentarse en el asiento delantero del pasajero, al lado del aprendiz, para ver la calle y ayudar rápido.","p":"Correcto. El adulto va en el asiento de adelante, a su lado."},"zh":{"q":"在 Florida，学习驾驶的人开车时，有驾照的成年人必须坐在哪里？","o":["前排乘客座位","任何后排座位","司机后面","车里任何地方"],"h1":"这个成年人必须能看到道路，并能马上帮忙。","h2":"有驾照的成年人必须坐在前排乘客座位，在学习驾驶的人旁边，这样才能看着道路并很快帮忙。","p":"对。成年人坐在前排，在你旁边。"},"vi":{"q":"Ở Florida, khi người tập lái đang lái xe, người lớn có bằng lái phải ngồi ở đâu?","o":["Ở ghế hành khách phía trước","Ở bất kỳ ghế sau nào","Ngồi sau lưng tài xế","Ở bất kỳ chỗ nào trong xe"],"h1":"Người lớn phải nhìn thấy đường và giúp được ngay lập tức.","h2":"Người lớn có bằng lái phải ngồi ở ghế hành khách phía trước, cạnh người tập lái, để họ quan sát đường và giúp đỡ nhanh chóng.","p":"Đúng. Người lớn ngồi ở ghế trước, cạnh bạn."},"tl":{"q":"Sa Florida, saan dapat umupo ang lisensyadong adult kapag nagmamaneho ang learner?","o":["Sa upuan ng pasahero sa harap","Sa kahit anong upuan sa likod","Sa likod ng driver","Kahit saan sa loob ng kotse"],"h1":"Dapat makita ng adult ang daan at makatulong agad.","h2":"Ang lisensyadong adult ay dapat umupo sa upuan ng pasahero sa harap, katabi ng learner, para mabantayan niya ang daan at makatulong agad.","p":"Tama. Ang adult ay umuupo sa harap, katabi mo."},"ar":{"q":"في Florida، أين يجب أن يجلس البالغ المرخّص عندما يقود المتعلم؟","o":["في المقعد الأمامي بجانب السائق","في أي مقعد خلفي","خلف السائق","في أي مكان في السيارة"],"h1":"يجب أن يستطيع البالغ رؤية الطريق والمساعدة فورًا.","h2":"يجب أن يجلس البالغ المرخّص في المقعد الأمامي بجانب المتعلم، حتى يراقب الطريق ويساعد بسرعة.","p":"صحيح. البالغ يجلس في المقعد الأمامي بجانبك."},"ht":{"q":"Nan Florida, ki kote granmoun ki gen lisans lan dwe chita lè yon apranti ap kondi?","o":["Sou chèz pasaje devan an","Sou nenpòt chèz dèyè","Dèyè chofè a","Nenpòt kote nan machin nan"],"h1":"Granmoun nan dwe ka wè wout la epi ede touswit.","h2":"Granmoun ki gen lisans lan dwe chita sou chèz pasaje devan an, bò kote apranti a, pou l ka gade wout la epi ede vit.","p":"Se sa. Granmoun nan chita devan, bò kote w."},"ref":{"doc":"FL","page":null}},{"id":"licensing-004","scope":"FL","cat":"licensing","sign":null,"c":2,"en":{"q":"In Florida, during the first 3 months with a learner license, when may you drive?","o":["Any time of day or night","Only until midnight","Only during daylight hours","Only on weekends"],"h1":"New learners start with the easiest light conditions.","h2":"For the first 3 months, a learner may drive only during daylight, because seeing well makes it easier to learn safely.","p":"Right. The first 3 months are daylight only."},"es":{"q":"En Florida, durante los primeros 3 meses con licencia de aprendiz, ¿cuándo puede manejar?","o":["A cualquier hora del día o de la noche","Solo hasta la medianoche","Solo durante las horas de luz del día","Solo los fines de semana"],"h1":"Los aprendices nuevos empiezan con la luz más fácil.","h2":"Durante los primeros 3 meses, el aprendiz solo puede manejar de día, porque ver bien hace más fácil aprender con seguridad.","p":"Correcto. Los primeros 3 meses son solo de día."},"zh":{"q":"在 Florida，持学习驾照的前 3 个月，你什么时候可以开车？","o":["白天晚上任何时间","只能开到午夜","只能在白天","只能在周末"],"h1":"新学员从光线最好、最容易的条件开始。","h2":"在前 3 个月，学习驾驶的人只能在白天开车，因为看得清楚更容易安全地学习。","p":"对。前 3 个月只能在白天开车。"},"vi":{"q":"Ở Florida, trong 3 tháng đầu có giấy phép tập lái, bạn được lái xe khi nào?","o":["Bất kỳ giờ nào, ngày hay đêm","Chỉ đến nửa đêm","Chỉ vào ban ngày","Chỉ vào cuối tuần"],"h1":"Người mới tập lái bắt đầu với điều kiện ánh sáng dễ nhất.","h2":"Trong 3 tháng đầu, người tập lái chỉ được lái xe vào ban ngày, vì nhìn rõ giúp việc học lái an toàn hơn.","p":"Đúng. 3 tháng đầu chỉ được lái vào ban ngày."},"tl":{"q":"Sa Florida, sa unang 3 buwan na may learner license, kailan ka puwedeng magmaneho?","o":["Kahit anong oras, araw man o gabi","Hanggang hatinggabi lang","Habang may liwanag ng araw lang","Tuwing weekend lang"],"h1":"Nagsisimula ang mga bagong learner sa pinakamadaling kondisyon ng liwanag.","h2":"Sa unang 3 buwan, ang learner ay puwedeng magmaneho habang may liwanag ng araw lang, dahil mas madaling matuto nang ligtas kapag malinaw ang nakikita.","p":"Tama. Sa unang 3 buwan, sa araw lang puwedeng magmaneho."},"ar":{"q":"في Florida، في أول 3 أشهر مع رخصة المتعلم، متى يُسمح لك بالقيادة؟","o":["في أي وقت من النهار أو الليل","حتى منتصف الليل فقط","في ساعات النهار فقط","في عطلة نهاية الأسبوع فقط"],"h1":"المتعلمون الجدد يبدؤون في أسهل ظروف الإضاءة.","h2":"في أول 3 أشهر، يُسمح للمتعلم بالقيادة في النهار فقط، لأن الرؤية الجيدة تجعل التعلم الآمن أسهل.","p":"صحيح. أول 3 أشهر للقيادة في النهار فقط."},"ht":{"q":"Nan Florida, pandan 3 premye mwa ou gen lisans aprantisaj la, ki lè ou ka kondi?","o":["Nenpòt lè, lajounen kou lannwit","Sèlman jiska minwi","Sèlman lajounen, lè gen limyè solèy","Sèlman nan wikenn"],"h1":"Nouvo apranti yo kòmanse ak limyè ki pi fasil la.","h2":"Pandan 3 premye mwa yo, yon apranti ka kondi sèlman lajounen, paske lè ou wè byen, li pi fasil pou aprann san danje.","p":"Se sa. 3 premye mwa yo, se lajounen sèlman."},"ref":{"doc":"FL","page":25}},{"id":"licensing-005","scope":"FL","cat":"licensing","sign":null,"c":1,"en":{"q":"In Florida, after 3 months with a learner license, until what time may you drive?","o":["Until 8 p.m.","Until 10 p.m.","Until midnight","Until 1 a.m."],"h1":"After 3 months, you may drive later, but not late into the night.","h2":"After the first 3 months, a learner may drive until 10 p.m., still with a licensed driver age 21 or older.","p":"Right. After 3 months, a learner may drive until 10 p.m."},"es":{"q":"En Florida, después de 3 meses con licencia de aprendiz, ¿hasta qué hora puede manejar?","o":["Hasta las 8 p.m.","Hasta las 10 p.m.","Hasta la medianoche","Hasta la 1 a.m."],"h1":"Después de 3 meses puede manejar más tarde, pero no hasta muy tarde en la noche.","h2":"Después de los primeros 3 meses, el aprendiz puede manejar hasta las 10 p.m., siempre con un conductor con licencia de 21 años o más.","p":"Correcto. Después de 3 meses, el aprendiz puede manejar hasta las 10 p.m."},"zh":{"q":"在 Florida，持学习驾照 3 个月以后，你可以开车到几点？","o":["到晚上 8 点","到晚上 10 点","到午夜","到凌晨 1 点"],"h1":"3 个月以后，你可以开得晚一些，但不能开到深夜。","h2":"前 3 个月以后，学习驾驶的人可以开车到晚上 10 点，但仍然要有一位 21 岁或以上、有驾照的司机陪同。","p":"对。3 个月以后，学习驾驶的人可以开车到晚上 10 点。"},"vi":{"q":"Ở Florida, sau 3 tháng có giấy phép tập lái, bạn được lái xe đến mấy giờ?","o":["Đến 8 giờ tối","Đến 10 giờ tối","Đến nửa đêm","Đến 1 giờ sáng"],"h1":"Sau 3 tháng, bạn được lái muộn hơn, nhưng không được lái khuya.","h2":"Sau 3 tháng đầu, người tập lái được lái xe đến 10 giờ tối, vẫn phải có người có bằng lái từ 21 tuổi trở lên đi cùng.","p":"Đúng. Sau 3 tháng, người tập lái được lái đến 10 giờ tối."},"tl":{"q":"Sa Florida, pagkalipas ng 3 buwan na may learner license, hanggang anong oras ka puwedeng magmaneho?","o":["Hanggang 8 p.m.","Hanggang 10 p.m.","Hanggang hatinggabi","Hanggang 1 a.m."],"h1":"Pagkalipas ng 3 buwan, puwede ka nang magmaneho nang mas gabi, pero hindi hanggang malalim na gabi.","h2":"Pagkalipas ng unang 3 buwan, ang learner ay puwedeng magmaneho hanggang 10 p.m., kasama pa rin ang lisensyadong driver na 21 taong gulang o higit pa.","p":"Tama. Pagkalipas ng 3 buwan, puwedeng magmaneho ang learner hanggang 10 p.m."},"ar":{"q":"في Florida، بعد 3 أشهر مع رخصة المتعلم، حتى أي ساعة يُسمح لك بالقيادة؟","o":["حتى الساعة 8 مساءً","حتى الساعة 10 مساءً","حتى منتصف الليل","حتى الساعة 1 بعد منتصف الليل"],"h1":"بعد 3 أشهر يمكنك القيادة لوقت أطول، لكن ليس حتى وقت متأخر من الليل.","h2":"بعد أول 3 أشهر، يُسمح للمتعلم بالقيادة حتى الساعة 10 مساءً، ويبقى معه سائق مرخّص عمره 21 سنة أو أكثر.","p":"صحيح. بعد 3 أشهر يُسمح للمتعلم بالقيادة حتى الساعة 10 مساءً."},"ht":{"q":"Nan Florida, apre 3 mwa ak lisans aprantisaj la, jiska ki lè ou ka kondi?","o":["Jiska 8 p.m.","Jiska 10 p.m.","Jiska minwi","Jiska 1 a.m."],"h1":"Apre 3 mwa, ou ka kondi pi ta, men pa twò ta nan nwit lan.","h2":"Apre 3 premye mwa yo, yon apranti ka kondi jiska 10 p.m., toujou ak yon chofè ki gen lisans epi ki gen 21 an oswa plis.","p":"Se sa. Apre 3 mwa, yon apranti ka kondi jiska 10 p.m."},"ref":{"doc":"FL","page":25}},{"id":"licensing-006","scope":"FL","cat":"licensing","sign":null,"c":3,"en":{"q":"In Florida, what course must a first-time driver finish before getting a license?","o":["A defensive driving course for truck drivers","A first aid and CPR course","A motorcycle safety course","The Traffic Law and Substance Abuse Education course (TLSAE)"],"h1":"The course covers traffic laws and the danger of alcohol and drugs.","h2":"First-time drivers must finish the Traffic Law and Substance Abuse Education course, called TLSAE, which teaches traffic laws and how alcohol and drugs affect driving.","p":"Right. First-time drivers must take the TLSAE course."},"es":{"q":"En Florida, ¿qué curso debe terminar una persona que saca su primera licencia?","o":["Un curso de manejo defensivo para camioneros","Un curso de primeros auxilios y RCP","Un curso de seguridad en motocicleta","El curso de Ley de Tránsito y Educación sobre Abuso de Sustancias (TLSAE)"],"h1":"El curso trata de las leyes de tránsito y del peligro del alcohol y las drogas.","h2":"Quien saca su primera licencia debe terminar el curso de Ley de Tránsito y Educación sobre Abuso de Sustancias, llamado TLSAE, que enseña las leyes de tránsito y cómo el alcohol y las drogas afectan al manejar.","p":"Correcto. Los conductores nuevos deben tomar el curso TLSAE."},"zh":{"q":"在 Florida，第一次考驾照的人拿驾照前必须完成什么课程？","o":["卡车司机的防御性驾驶课程","急救和心肺复苏 (CPR) 课程","摩托车安全课程","交通法规与药物酒精滥用教育课程 (TLSAE)"],"h1":"这个课程讲交通法规，以及酒精和毒品的危险。","h2":"第一次考驾照的人必须完成交通法规与药物酒精滥用教育课程，叫做 TLSAE，它教交通法规，以及酒精和毒品怎样影响开车。","p":"对。第一次考驾照的人必须上 TLSAE 课程。"},"vi":{"q":"Ở Florida, người lái xe lần đầu phải học xong khóa học nào trước khi được cấp bằng lái?","o":["Khóa lái xe phòng vệ cho tài xế xe tải","Khóa sơ cứu và hồi sức tim phổi (CPR)","Khóa an toàn lái xe máy","Khóa Luật Giao thông và Giáo dục về Lạm dụng Chất gây nghiện (TLSAE)"],"h1":"Khóa học này nói về luật giao thông và sự nguy hiểm của rượu bia và ma túy.","h2":"Người lái xe lần đầu phải học xong khóa Luật Giao thông và Giáo dục về Lạm dụng Chất gây nghiện, gọi là TLSAE, khóa này dạy luật giao thông và cách rượu bia, ma túy ảnh hưởng đến việc lái xe.","p":"Đúng. Người lái xe lần đầu phải học khóa TLSAE."},"tl":{"q":"Sa Florida, anong kurso ang dapat tapusin ng unang beses na driver bago kumuha ng lisensya?","o":["Kurso sa defensive driving para sa mga truck driver","Kurso sa first aid at CPR","Kurso sa kaligtasan sa motorsiklo","Ang Traffic Law and Substance Abuse Education course (TLSAE)"],"h1":"Tungkol ang kurso sa mga batas trapiko at sa panganib ng alak at droga.","h2":"Ang mga unang beses na driver ay dapat tumapos ng Traffic Law and Substance Abuse Education course, na tinatawag na TLSAE, na nagtuturo ng mga batas trapiko at kung paano naaapektuhan ng alak at droga ang pagmamaneho.","p":"Tama. Ang mga unang beses na driver ay dapat kumuha ng TLSAE course."},"ar":{"q":"في Florida، ما الدورة التي يجب أن يُنهيها السائق لأول مرة قبل الحصول على الرخصة؟","o":["دورة القيادة الدفاعية لسائقي الشاحنات","دورة الإسعافات الأولية والإنعاش القلبي","دورة السلامة لسائقي الدراجات النارية","دورة قوانين المرور والتوعية بالكحول والمخدرات (TLSAE)"],"h1":"الدورة تشرح قوانين المرور وخطر الكحول والمخدرات.","h2":"يجب على السائقين لأول مرة أن يُنهوا دورة قوانين المرور والتوعية بالكحول والمخدرات، واسمها TLSAE، وهي تعلّم قوانين المرور وتأثير الكحول والمخدرات على القيادة.","p":"صحيح. السائقون لأول مرة يجب أن يأخذوا دورة TLSAE."},"ht":{"q":"Nan Florida, ki kou yon moun k ap kondi pou premye fwa dwe fini anvan l jwenn yon lisans?","o":["Yon kou kondi pridan pou chofè kamyon","Yon kou premye swen ak CPR","Yon kou sekirite pou motosiklèt","Kou Traffic Law and Substance Abuse Education (TLSAE)"],"h1":"Kou a pale sou lwa wout yo ak danje alkòl ak dwòg.","h2":"Moun k ap kondi pou premye fwa dwe fini kou Traffic Law and Substance Abuse Education, yo rele TLSAE, ki aprann lwa wout yo ak jan alkòl ak dwòg chanje fason ou kondi.","p":"Se sa. Moun k ap kondi pou premye fwa dwe pran kou TLSAE a."},"ref":{"doc":"FL","page":17}},{"id":"licensing-007","scope":"FL","cat":"licensing","sign":null,"c":0,"en":{"q":"In Florida, the learner license knowledge test has 50 questions. How many must you answer correctly to pass?","o":["At least 40","At least 30","At least 35","All 50"],"h1":"You need 80 percent of the questions right.","h2":"You must answer at least 40 of the 50 questions correctly, which is 80 percent, to pass the knowledge test.","p":"Right. You need 40 correct answers out of 50."},"es":{"q":"En Florida, el examen de conocimientos para la licencia de aprendiz tiene 50 preguntas. ¿Cuántas debe contestar bien para aprobar?","o":["Por lo menos 40","Por lo menos 30","Por lo menos 35","Las 50"],"h1":"Necesita el 80 por ciento de las preguntas correctas.","h2":"Usted debe contestar bien por lo menos 40 de las 50 preguntas, que es el 80 por ciento, para aprobar el examen de conocimientos.","p":"Correcto. Necesita 40 respuestas correctas de 50."},"zh":{"q":"在 Florida，学习驾照的笔试有 50 道题。你必须答对多少道才能通过？","o":["至少 40 道","至少 30 道","至少 35 道","全部 50 道"],"h1":"你需要答对 80% 的题目。","h2":"你必须在 50 道题里至少答对 40 道，也就是 80%，才能通过笔试。","p":"对。50 道题里你需要答对 40 道。"},"vi":{"q":"Ở Florida, bài thi kiến thức để lấy giấy phép tập lái có 50 câu hỏi. Bạn phải trả lời đúng bao nhiêu câu để đậu?","o":["Ít nhất 40 câu","Ít nhất 30 câu","Ít nhất 35 câu","Cả 50 câu"],"h1":"Bạn cần trả lời đúng 80 phần trăm số câu hỏi.","h2":"Bạn phải trả lời đúng ít nhất 40 trên 50 câu hỏi, tức là 80 phần trăm, để đậu bài thi kiến thức.","p":"Đúng. Bạn cần 40 câu đúng trên 50 câu."},"tl":{"q":"Sa Florida, ang knowledge test para sa learner license ay may 50 tanong. Ilan ang dapat mong masagot nang tama para pumasa?","o":["Hindi bababa sa 40","Hindi bababa sa 30","Hindi bababa sa 35","Lahat ng 50"],"h1":"Kailangan mong makuha nang tama ang 80 porsyento ng mga tanong.","h2":"Dapat mong masagot nang tama ang hindi bababa sa 40 sa 50 tanong, na 80 porsyento, para pumasa sa knowledge test.","p":"Tama. Kailangan mo ng 40 tamang sagot sa 50."},"ar":{"q":"في Florida، اختبار المعرفة لرخصة المتعلم فيه 50 سؤالًا. كم سؤالًا يجب أن تجيب عنه إجابة صحيحة لتنجح؟","o":["40 على الأقل","30 على الأقل","35 على الأقل","كل الأسئلة الـ 50"],"h1":"تحتاج إلى إجابة صحيحة عن 80 بالمئة من الأسئلة.","h2":"يجب أن تجيب إجابة صحيحة عن 40 سؤالًا على الأقل من 50، أي 80 بالمئة، لتنجح في اختبار المعرفة.","p":"صحيح. تحتاج إلى 40 إجابة صحيحة من 50."},"ht":{"q":"Nan Florida, egzamen konesans pou lisans aprantisaj la gen 50 kesyon. Konbyen ou dwe reponn kòrèk pou w pase?","o":["Omwen 40","Omwen 30","Omwen 35","Tout 50 yo"],"h1":"Ou bezwen 80 pousan nan kesyon yo bon.","h2":"Ou dwe reponn omwen 40 nan 50 kesyon yo kòrèk, sa ki fè 80 pousan, pou w pase egzamen konesans lan.","p":"Se sa. Ou bezwen 40 bon repons sou 50."},"ref":{"doc":"FL","page":null}},{"id":"licensing-008","scope":"FL","cat":"licensing","sign":null,"c":2,"en":{"q":"In Florida, a 16-year-old wants a Class E license. How long must they first hold a learner license?","o":["3 months, with no traffic convictions","6 months, even with traffic convictions","12 months, or until age 18, with no traffic convictions","24 months, with no traffic convictions"],"h1":"Think about one full year of practice without breaking traffic laws.","h2":"A teen must hold the learner license for 12 months, or until turning 18, with no traffic convictions before getting a Class E license.","p":"Right. Hold the learner license 12 months with a clean record."},"es":{"q":"En Florida, una persona de 16 años quiere la licencia Clase E. ¿Cuánto tiempo debe tener antes la licencia de aprendiz?","o":["3 meses, sin condenas de tránsito","6 meses, aunque tenga condenas de tránsito","12 meses, o hasta cumplir 18, sin condenas de tránsito","24 meses, sin condenas de tránsito"],"h1":"Piense en un año completo de práctica sin violar las leyes de tránsito.","h2":"Un joven debe tener la licencia de aprendiz por 12 meses, o hasta cumplir 18 años, sin condenas de tránsito antes de obtener la licencia Clase E.","p":"Correcto. Tenga la licencia de aprendiz 12 meses con un récord limpio."},"zh":{"q":"在 Florida，一个 16 岁的人想拿 Class E 驾照。他必须先持有学习驾照多久？","o":["3 个月，没有交通违法定罪","6 个月，即使有交通违法定罪","12 个月，或者到 18 岁，没有交通违法定罪","24 个月，没有交通违法定罪"],"h1":"想一想整整一年的练习，而且不违反交通法规。","h2":"青少年必须持有学习驾照 12 个月，或者到满 18 岁，并且没有交通违法定罪，才能拿到 Class E 驾照。","p":"对。持有学习驾照 12 个月，记录要干净。"},"vi":{"q":"Ở Florida, một thiếu niên 16 tuổi muốn có bằng lái Class E. Trước đó, em phải giữ giấy phép tập lái trong bao lâu?","o":["3 tháng, không bị kết tội vi phạm giao thông","6 tháng, dù có bị kết tội vi phạm giao thông","12 tháng, hoặc đến khi 18 tuổi, không bị kết tội vi phạm giao thông","24 tháng, không bị kết tội vi phạm giao thông"],"h1":"Hãy nghĩ đến một năm tập lái trọn vẹn mà không vi phạm luật giao thông.","h2":"Thiếu niên phải giữ giấy phép tập lái trong 12 tháng, hoặc đến khi 18 tuổi, và không bị kết tội vi phạm giao thông, rồi mới được cấp bằng lái Class E.","p":"Đúng. Giữ giấy phép tập lái 12 tháng với hồ sơ sạch."},"tl":{"q":"Sa Florida, ang isang 16 taong gulang ay gustong kumuha ng Class E license. Gaano katagal muna niyang dapat hawak ang learner license?","o":["3 buwan, nang walang traffic conviction","6 na buwan, kahit may traffic conviction","12 buwan, o hanggang edad 18, nang walang traffic conviction","24 na buwan, nang walang traffic conviction"],"h1":"Isipin ang isang buong taon ng pagsasanay nang hindi lumalabag sa batas trapiko.","h2":"Ang teen ay dapat may hawak na learner license nang 12 buwan, o hanggang mag-18 taong gulang, nang walang traffic conviction bago makakuha ng Class E license.","p":"Tama. Hawakan ang learner license nang 12 buwan na malinis ang record."},"ar":{"q":"في Florida، شاب عمره 16 سنة يريد رخصة Class E. كم من الوقت يجب أن يحمل رخصة المتعلم أولًا؟","o":["3 أشهر، بدون مخالفات مرورية مُدان بها","6 أشهر، حتى مع مخالفات مرورية مُدان بها","12 شهرًا، أو حتى عمر 18، بدون مخالفات مرورية مُدان بها","24 شهرًا، بدون مخالفات مرورية مُدان بها"],"h1":"فكّر في سنة كاملة من التدريب بدون مخالفة قوانين المرور.","h2":"يجب على الشاب أن يحمل رخصة المتعلم 12 شهرًا، أو حتى يبلغ 18 سنة، بدون أي إدانة بمخالفة مرورية، قبل أن يحصل على رخصة Class E.","p":"صحيح. احمل رخصة المتعلم 12 شهرًا بسجل نظيف."},"ht":{"q":"Nan Florida, yon moun 16 an vle yon lisans Class E. Konbyen tan li dwe gen lisans aprantisaj la anvan?","o":["3 mwa, san okenn kondanasyon pou enfraksyon wout","6 mwa, menm si li gen kondanasyon pou enfraksyon wout","12 mwa, oswa jiskaske li gen 18 an, san okenn kondanasyon pou enfraksyon wout","24 mwa, san okenn kondanasyon pou enfraksyon wout"],"h1":"Panse ak yon ane konplè pratik san ou pa vyole lwa wout yo.","h2":"Yon jèn dwe gen lisans aprantisaj la pandan 12 mwa, oswa jiskaske li gen 18 an, san okenn kondanasyon pou enfraksyon wout, anvan li jwenn yon lisans Class E.","p":"Se sa. Kenbe lisans aprantisaj la 12 mwa ak yon dosye pwòp."},"ref":{"doc":"FL","page":8}},{"id":"licensing-009","scope":"FL","cat":"licensing","sign":null,"c":1,"en":{"q":"In Florida, how many hours of supervised driving must a teen complete before getting a Class E license?","o":["20 hours","50 hours","30 hours","100 hours"],"h1":"It is a large number, with some of the hours at night.","h2":"A teen must complete 50 hours of supervised driving, and 10 of those hours must be at night.","p":"Right. Teens need 50 hours of supervised driving."},"es":{"q":"En Florida, ¿cuántas horas de manejo supervisado debe completar un joven antes de obtener la licencia Clase E?","o":["20 horas","50 horas","30 horas","100 horas"],"h1":"Es un número grande, y algunas de las horas son de noche.","h2":"Un joven debe completar 50 horas de manejo supervisado, y 10 de esas horas deben ser de noche.","p":"Correcto. Los jóvenes necesitan 50 horas de manejo supervisado."},"zh":{"q":"在 Florida，青少年拿 Class E 驾照前，必须完成多少小时有人监督的驾驶？","o":["20 小时","50 小时","30 小时","100 小时"],"h1":"这是一个比较大的数字，其中有一些小时要在晚上。","h2":"青少年必须完成 50 小时有人监督的驾驶，其中 10 小时必须在晚上。","p":"对。青少年需要 50 小时有人监督的驾驶。"},"vi":{"q":"Ở Florida, thiếu niên phải lái xe có người giám sát bao nhiêu giờ trước khi được cấp bằng lái Class E?","o":["20 giờ","50 giờ","30 giờ","100 giờ"],"h1":"Đây là một con số lớn, và một phần số giờ phải lái vào ban đêm.","h2":"Thiếu niên phải lái xe có người giám sát đủ 50 giờ, và 10 giờ trong số đó phải lái vào ban đêm.","p":"Đúng. Thiếu niên cần 50 giờ lái xe có người giám sát."},"tl":{"q":"Sa Florida, ilang oras ng supervised driving (pagmamaneho na may kasamang lisensyadong adult) ang dapat tapusin ng teen bago makakuha ng Class E license?","o":["20 oras","50 oras","30 oras","100 oras"],"h1":"Malaking bilang ito, at ang ilan sa mga oras ay sa gabi.","h2":"Ang teen ay dapat tumapos ng 50 oras ng supervised driving, at 10 sa mga oras na iyon ay dapat sa gabi.","p":"Tama. Kailangan ng teen ang 50 oras ng supervised driving."},"ar":{"q":"في Florida، كم ساعة من القيادة تحت الإشراف يجب أن يُكملها الشاب قبل الحصول على رخصة Class E؟","o":["20 ساعة","50 ساعة","30 ساعة","100 ساعة"],"h1":"إنه عدد كبير، وبعض الساعات تكون في الليل.","h2":"يجب على الشاب أن يُكمل 50 ساعة من القيادة تحت الإشراف، ويجب أن تكون 10 ساعات منها في الليل.","p":"صحيح. يحتاج الشباب إلى 50 ساعة من القيادة تحت الإشراف."},"ht":{"q":"Nan Florida, konbyen èdtan kondi ak siveyans yon jèn dwe fè anvan li jwenn yon lisans Class E?","o":["20 èdtan","50 èdtan","30 èdtan","100 èdtan"],"h1":"Se yon gwo kantite, epi kèk nan èdtan yo dwe fèt lannwit.","h2":"Yon jèn dwe fè 50 èdtan kondi ak siveyans, epi 10 nan èdtan sa yo dwe fèt lannwit.","p":"Se sa. Jèn yo bezwen 50 èdtan kondi ak siveyans."},"ref":{"doc":"FL","page":8}},{"id":"licensing-010","scope":"FL","cat":"licensing","sign":null,"c":3,"en":{"q":"In Florida, of the supervised driving hours a teen needs, how many must be at night?","o":["5 hours","25 hours","50 hours","10 hours"],"h1":"It is a small part of the total supervised hours.","h2":"Of the 50 supervised hours, at least 10 must be at night, so the teen learns to drive in the dark before driving alone.","p":"Right. At least 10 of the hours must be at night."},"es":{"q":"En Florida, de las horas de manejo supervisado que necesita un joven, ¿cuántas deben ser de noche?","o":["5 horas","25 horas","50 horas","10 horas"],"h1":"Es una parte pequeña del total de horas supervisadas.","h2":"De las 50 horas supervisadas, por lo menos 10 deben ser de noche, para que el joven aprenda a manejar en la oscuridad antes de manejar solo.","p":"Correcto. Por lo menos 10 de las horas deben ser de noche."},"zh":{"q":"在 Florida，青少年需要的有人监督驾驶时间中，有多少小时必须在晚上？","o":["5 小时","25 小时","50 小时","10 小时"],"h1":"这只是全部监督时间里的一小部分。","h2":"在 50 小时有人监督的驾驶中，至少 10 小时必须在晚上，这样青少年在自己开车前就学会在黑暗中开车。","p":"对。至少 10 小时必须在晚上。"},"vi":{"q":"Ở Florida, trong số giờ lái xe có người giám sát mà thiếu niên cần có, bao nhiêu giờ phải lái vào ban đêm?","o":["5 giờ","25 giờ","50 giờ","10 giờ"],"h1":"Đây là một phần nhỏ trong tổng số giờ có người giám sát.","h2":"Trong 50 giờ có người giám sát, ít nhất 10 giờ phải lái vào ban đêm, để thiếu niên học lái trong bóng tối trước khi lái một mình.","p":"Đúng. Ít nhất 10 giờ phải lái vào ban đêm."},"tl":{"q":"Sa Florida, sa mga oras ng supervised driving na kailangan ng teen, ilan ang dapat sa gabi?","o":["5 oras","25 oras","50 oras","10 oras"],"h1":"Maliit na bahagi ito ng kabuuang supervised na oras.","h2":"Sa 50 supervised na oras, hindi bababa sa 10 ang dapat sa gabi, para matutong magmaneho ang teen sa dilim bago siya magmaneho nang mag-isa.","p":"Tama. Hindi bababa sa 10 sa mga oras ang dapat sa gabi."},"ar":{"q":"في Florida، من ساعات القيادة تحت الإشراف التي يحتاجها الشاب، كم ساعة يجب أن تكون في الليل؟","o":["5 ساعات","25 ساعة","50 ساعة","10 ساعات"],"h1":"إنه جزء صغير من مجموع ساعات الإشراف.","h2":"من الـ 50 ساعة تحت الإشراف، يجب أن تكون 10 ساعات على الأقل في الليل، حتى يتعلم الشاب القيادة في الظلام قبل أن يقود وحده.","p":"صحيح. 10 ساعات على الأقل يجب أن تكون في الليل."},"ht":{"q":"Nan Florida, nan èdtan kondi ak siveyans yon jèn bezwen, konbyen ladan yo dwe fèt lannwit?","o":["5 èdtan","25 èdtan","50 èdtan","10 èdtan"],"h1":"Se yon ti pati nan total èdtan siveyans yo.","h2":"Nan 50 èdtan siveyans yo, omwen 10 dwe fèt lannwit, pou jèn nan aprann kondi nan fènwa anvan li kondi pou kont li.","p":"Se sa. Omwen 10 nan èdtan yo dwe fèt lannwit."},"ref":{"doc":"FL","page":8}},{"id":"licensing-011","scope":"FL","cat":"licensing","sign":null,"c":0,"en":{"q":"In Florida, who certifies that a teen under 18 completed the supervised driving hours?","o":["A parent, legal guardian, or responsible adult","The teen alone","A police officer","The school principal"],"h1":"Think about the adult who is legally responsible for the teen.","h2":"A parent, legal guardian, or responsible adult must certify that the teen completed the supervised driving hours.","p":"Right. A parent or guardian certifies the driving hours."},"es":{"q":"En Florida, ¿quién certifica que un joven menor de 18 completó las horas de manejo supervisado?","o":["Un padre, tutor legal o adulto responsable","El joven solo","Un oficial de policía","El director de la escuela"],"h1":"Piense en el adulto que es legalmente responsable del joven.","h2":"Un padre, tutor legal o adulto responsable debe certificar que el joven completó las horas de manejo supervisado.","p":"Correcto. Un padre o tutor certifica las horas de manejo."},"zh":{"q":"在 Florida，谁来证明 18 岁以下的青少年完成了有人监督的驾驶时间？","o":["父母、法定监护人或负责任的成年人","青少年自己","警察","学校校长"],"h1":"想一想在法律上对这个青少年负责的成年人。","h2":"父母、法定监护人或负责任的成年人必须证明青少年完成了有人监督的驾驶时间。","p":"对。父母或监护人证明驾驶时间。"},"vi":{"q":"Ở Florida, ai xác nhận rằng một thiếu niên dưới 18 tuổi đã lái đủ số giờ có người giám sát?","o":["Cha mẹ, người giám hộ hợp pháp, hoặc một người lớn có trách nhiệm","Chỉ một mình thiếu niên đó","Một cảnh sát","Hiệu trưởng nhà trường"],"h1":"Hãy nghĩ đến người lớn chịu trách nhiệm pháp lý cho thiếu niên đó.","h2":"Cha mẹ, người giám hộ hợp pháp, hoặc một người lớn có trách nhiệm phải xác nhận rằng thiếu niên đã lái đủ số giờ có người giám sát.","p":"Đúng. Cha mẹ hoặc người giám hộ xác nhận số giờ lái xe."},"tl":{"q":"Sa Florida, sino ang nagpapatunay na natapos ng teen na wala pang 18 ang mga oras ng supervised driving?","o":["Isang magulang, legal na guardian, o responsableng adult","Ang teen lang mismo","Isang pulis","Ang principal ng paaralan"],"h1":"Isipin ang adult na may legal na pananagutan sa teen.","h2":"Isang magulang, legal na guardian, o responsableng adult ang dapat magpatunay na natapos ng teen ang mga oras ng supervised driving.","p":"Tama. Ang magulang o guardian ang nagpapatunay ng mga oras ng pagmamaneho."},"ar":{"q":"في Florida، من يشهد بأن الشاب تحت 18 سنة أكمل ساعات القيادة تحت الإشراف؟","o":["أحد الوالدين، أو الوصي القانوني، أو شخص بالغ مسؤول","الشاب وحده","شرطي","مدير المدرسة"],"h1":"فكّر في الشخص البالغ المسؤول قانونيًا عن الشاب.","h2":"يجب على أحد الوالدين، أو الوصي القانوني، أو شخص بالغ مسؤول، أن يشهد بأن الشاب أكمل ساعات القيادة تحت الإشراف.","p":"صحيح. أحد الوالدين أو الوصي يشهد على ساعات القيادة."},"ht":{"q":"Nan Florida, kiyès ki sètifye ke yon jèn ki poko gen 18 an fini èdtan kondi ak siveyans yo?","o":["Yon paran, yon gadyen legal, oswa yon granmoun ki responsab","Jèn nan pou kont li","Yon polis","Direktè lekòl la"],"h1":"Panse ak granmoun ki responsab jèn nan devan lalwa.","h2":"Yon paran, yon gadyen legal, oswa yon granmoun ki responsab dwe sètifye ke jèn nan fini èdtan kondi ak siveyans yo.","p":"Se sa. Yon paran oswa yon gadyen sètifye èdtan kondi yo."},"ref":{"doc":"FL","page":8}},{"id":"licensing-012","scope":"FL","cat":"licensing","sign":null,"c":2,"en":{"q":"In Florida, a 16-year-old with a Class E license may not drive alone during which hours?","o":["From 9 p.m. to 5 a.m.","From 1 a.m. to 5 a.m.","From 11 p.m. to 6 a.m.","From midnight to 8 a.m."],"h1":"The younger the driver, the longer the night hours they cannot drive alone.","h2":"A 16-year-old may not drive from 11 p.m. to 6 a.m. unless a licensed driver age 21 or older is with them or they are driving to or from work.","p":"Right. At 16, no driving alone from 11 p.m. to 6 a.m."},"es":{"q":"En Florida, una persona de 16 años con licencia Clase E, ¿durante qué horas no puede manejar sola?","o":["De 9 p.m. a 5 a.m.","De 1 a.m. a 5 a.m.","De 11 p.m. a 6 a.m.","De medianoche a 8 a.m."],"h1":"Mientras más joven es el conductor, más largas son las horas de la noche en que no puede manejar solo.","h2":"Una persona de 16 años no puede manejar de 11 p.m. a 6 a.m., a menos que vaya con un conductor con licencia de 21 años o más, o que maneje hacia o desde el trabajo.","p":"Correcto. A los 16, no se maneja solo de 11 p.m. a 6 a.m."},"zh":{"q":"在 Florida，持 Class E 驾照的 16 岁司机在哪段时间不能单独开车？","o":["晚上 9 点到早上 5 点","凌晨 1 点到早上 5 点","晚上 11 点到早上 6 点","午夜到早上 8 点"],"h1":"司机年龄越小，夜里不能单独开车的时间就越长。","h2":"16 岁的司机在晚上 11 点到早上 6 点不能开车，除非有一位 21 岁或以上、有驾照的司机陪同，或者他是在上班或下班的路上。","p":"对。16 岁时，晚上 11 点到早上 6 点不能单独开车。"},"vi":{"q":"Ở Florida, một thiếu niên 16 tuổi có bằng lái Class E không được lái xe một mình trong khoảng giờ nào?","o":["Từ 9 giờ tối đến 5 giờ sáng","Từ 1 giờ sáng đến 5 giờ sáng","Từ 11 giờ tối đến 6 giờ sáng","Từ nửa đêm đến 8 giờ sáng"],"h1":"Tài xế càng nhỏ tuổi thì khoảng giờ ban đêm không được lái một mình càng dài.","h2":"Thiếu niên 16 tuổi không được lái xe từ 11 giờ tối đến 6 giờ sáng, trừ khi có người có bằng lái từ 21 tuổi trở lên đi cùng hoặc em đang lái xe đi làm hay đi làm về.","p":"Đúng. Ở tuổi 16, không lái một mình từ 11 giờ tối đến 6 giờ sáng."},"tl":{"q":"Sa Florida, ang 16 taong gulang na may Class E license ay hindi puwedeng magmaneho nang mag-isa sa anong mga oras?","o":["Mula 9 p.m. hanggang 5 a.m.","Mula 1 a.m. hanggang 5 a.m.","Mula 11 p.m. hanggang 6 a.m.","Mula hatinggabi hanggang 8 a.m."],"h1":"Kapag mas bata ang driver, mas mahaba ang mga oras sa gabi na hindi siya puwedeng magmaneho nang mag-isa.","h2":"Ang 16 taong gulang ay hindi puwedeng magmaneho mula 11 p.m. hanggang 6 a.m. maliban kung kasama niya ang lisensyadong driver na 21 taong gulang o higit pa, o papunta o pauwi siya mula sa trabaho.","p":"Tama. Sa edad na 16, bawal magmaneho nang mag-isa mula 11 p.m. hanggang 6 a.m."},"ar":{"q":"في Florida، شاب عمره 16 سنة يحمل رخصة Class E. في أي ساعات لا يُسمح له بالقيادة وحده؟","o":["من 9 مساءً إلى 5 صباحًا","من 1 بعد منتصف الليل إلى 5 صباحًا","من 11 مساءً إلى 6 صباحًا","من منتصف الليل إلى 8 صباحًا"],"h1":"كلما كان السائق أصغر، كانت ساعات الليل التي لا يقود فيها وحده أطول.","h2":"لا يُسمح لمن عمره 16 سنة بالقيادة من 11 مساءً إلى 6 صباحًا، إلا إذا كان معه سائق مرخّص عمره 21 سنة أو أكثر، أو كان ذاهبًا إلى العمل أو عائدًا منه.","p":"صحيح. في عمر 16، لا قيادة وحدك من 11 مساءً إلى 6 صباحًا."},"ht":{"q":"Nan Florida, yon moun 16 an ki gen lisans Class E pa ka kondi pou kont li nan ki lè?","o":["Soti 9 p.m. rive 5 a.m.","Soti 1 a.m. rive 5 a.m.","Soti 11 p.m. rive 6 a.m.","Soti minwi rive 8 a.m."],"h1":"Plis chofè a jèn, plis lè nan nwit li pa ka kondi pou kont li yo long.","h2":"Yon moun 16 an pa ka kondi soti 11 p.m. rive 6 a.m., sof si yon chofè ki gen lisans epi ki gen 21 an oswa plis avè l, oswa si l ap ale oswa l ap soti travay.","p":"Se sa. A 16 an, ou pa kondi pou kont ou soti 11 p.m. rive 6 a.m."},"ref":{"doc":"FL","page":25}},{"id":"licensing-013","scope":"FL","cat":"licensing","sign":null,"c":1,"en":{"q":"In Florida, a 17-year-old with a Class E license may not drive alone during which hours?","o":["From 11 p.m. to 6 a.m.","From 1 a.m. to 5 a.m.","From 10 p.m. to 6 a.m.","From 2 a.m. to 7 a.m."],"h1":"A 17-year-old gets a shorter limit than a 16-year-old.","h2":"A 17-year-old may not drive from 1 a.m. to 5 a.m. unless a licensed driver age 21 or older is with them or they are driving to or from work.","p":"Right. At 17, no driving alone from 1 a.m. to 5 a.m."},"es":{"q":"En Florida, una persona de 17 años con licencia Clase E, ¿durante qué horas no puede manejar sola?","o":["De 11 p.m. a 6 a.m.","De 1 a.m. a 5 a.m.","De 10 p.m. a 6 a.m.","De 2 a.m. a 7 a.m."],"h1":"A los 17 años el límite es más corto que a los 16.","h2":"Una persona de 17 años no puede manejar de 1 a.m. a 5 a.m., a menos que vaya con un conductor con licencia de 21 años o más, o que maneje hacia o desde el trabajo.","p":"Correcto. A los 17, no se maneja solo de 1 a.m. a 5 a.m."},"zh":{"q":"在 Florida，持 Class E 驾照的 17 岁司机在哪段时间不能单独开车？","o":["晚上 11 点到早上 6 点","凌晨 1 点到早上 5 点","晚上 10 点到早上 6 点","凌晨 2 点到早上 7 点"],"h1":"17 岁的司机受到的限制比 16 岁的司机短。","h2":"17 岁的司机在凌晨 1 点到早上 5 点不能开车，除非有一位 21 岁或以上、有驾照的司机陪同，或者他是在上班或下班的路上。","p":"对。17 岁时，凌晨 1 点到早上 5 点不能单独开车。"},"vi":{"q":"Ở Florida, một thiếu niên 17 tuổi có bằng lái Class E không được lái xe một mình trong khoảng giờ nào?","o":["Từ 11 giờ tối đến 6 giờ sáng","Từ 1 giờ sáng đến 5 giờ sáng","Từ 10 giờ tối đến 6 giờ sáng","Từ 2 giờ sáng đến 7 giờ sáng"],"h1":"Thiếu niên 17 tuổi bị giới hạn ngắn hơn thiếu niên 16 tuổi.","h2":"Thiếu niên 17 tuổi không được lái xe từ 1 giờ sáng đến 5 giờ sáng, trừ khi có người có bằng lái từ 21 tuổi trở lên đi cùng hoặc em đang lái xe đi làm hay đi làm về.","p":"Đúng. Ở tuổi 17, không lái một mình từ 1 giờ sáng đến 5 giờ sáng."},"tl":{"q":"Sa Florida, ang 17 taong gulang na may Class E license ay hindi puwedeng magmaneho nang mag-isa sa anong mga oras?","o":["Mula 11 p.m. hanggang 6 a.m.","Mula 1 a.m. hanggang 5 a.m.","Mula 10 p.m. hanggang 6 a.m.","Mula 2 a.m. hanggang 7 a.m."],"h1":"Mas maikli ang limitasyon ng 17 taong gulang kaysa sa 16 taong gulang.","h2":"Ang 17 taong gulang ay hindi puwedeng magmaneho mula 1 a.m. hanggang 5 a.m. maliban kung kasama niya ang lisensyadong driver na 21 taong gulang o higit pa, o papunta o pauwi siya mula sa trabaho.","p":"Tama. Sa edad na 17, bawal magmaneho nang mag-isa mula 1 a.m. hanggang 5 a.m."},"ar":{"q":"في Florida، شاب عمره 17 سنة يحمل رخصة Class E. في أي ساعات لا يُسمح له بالقيادة وحده؟","o":["من 11 مساءً إلى 6 صباحًا","من 1 بعد منتصف الليل إلى 5 صباحًا","من 10 مساءً إلى 6 صباحًا","من 2 بعد منتصف الليل إلى 7 صباحًا"],"h1":"من عمره 17 سنة له وقت منع أقصر ممن عمره 16 سنة.","h2":"لا يُسمح لمن عمره 17 سنة بالقيادة من 1 بعد منتصف الليل إلى 5 صباحًا، إلا إذا كان معه سائق مرخّص عمره 21 سنة أو أكثر، أو كان ذاهبًا إلى العمل أو عائدًا منه.","p":"صحيح. في عمر 17، لا قيادة وحدك من 1 بعد منتصف الليل إلى 5 صباحًا."},"ht":{"q":"Nan Florida, yon moun 17 an ki gen lisans Class E pa ka kondi pou kont li nan ki lè?","o":["Soti 11 p.m. rive 6 a.m.","Soti 1 a.m. rive 5 a.m.","Soti 10 p.m. rive 6 a.m.","Soti 2 a.m. rive 7 a.m."],"h1":"Yon moun 17 an gen yon limit ki pi kout pase yon moun 16 an.","h2":"Yon moun 17 an pa ka kondi soti 1 a.m. rive 5 a.m., sof si yon chofè ki gen lisans epi ki gen 21 an oswa plis avè l, oswa si l ap ale oswa l ap soti travay.","p":"Se sa. A 17 an, ou pa kondi pou kont ou soti 1 a.m. rive 5 a.m."},"ref":{"doc":"FL","page":25}},{"id":"licensing-014","scope":"FL","cat":"licensing","sign":null,"c":3,"en":{"q":"In Florida, when may a 16-year-old drive alone during curfew hours?","o":["When driving to a friend's house","When the roads are empty","When the trip is under 5 miles","When driving to or from work"],"h1":"The law makes an exception for a job.","h2":"A 16-year-old may drive alone during curfew hours only when driving to or from work, or when a licensed driver age 21 or older is with them.","p":"Right. Driving to or from work is allowed during curfew."},"es":{"q":"En Florida, ¿cuándo puede una persona de 16 años manejar sola en las horas restringidas?","o":["Cuando va a la casa de un amigo","Cuando las calles están vacías","Cuando el viaje es de menos de 5 millas","Cuando maneja hacia o desde el trabajo"],"h1":"La ley hace una excepción por el empleo.","h2":"Una persona de 16 años puede manejar sola en las horas restringidas solo cuando va hacia o desde el trabajo, o cuando la acompaña un conductor con licencia de 21 años o más.","p":"Correcto. Se permite manejar hacia o desde el trabajo en esas horas."},"zh":{"q":"在 Florida，16 岁的司机在宵禁时间什么时候可以单独开车？","o":["开车去朋友家时","路上没有车时","路程少于 5 英里时","上班或下班的路上"],"h1":"法律对工作有一个例外。","h2":"16 岁的司机在宵禁时间只能在上班或下班的路上单独开车，或者有一位 21 岁或以上、有驾照的司机陪同。","p":"对。宵禁时间可以开车上班或下班。"},"vi":{"q":"Ở Florida, khi nào thiếu niên 16 tuổi được lái xe một mình trong giờ giới nghiêm?","o":["Khi lái xe đến nhà bạn","Khi đường vắng","Khi chuyến đi ngắn hơn 5 dặm","Khi lái xe đi làm hoặc đi làm về"],"h1":"Luật có một ngoại lệ dành cho công việc.","h2":"Thiếu niên 16 tuổi chỉ được lái xe một mình trong giờ giới nghiêm khi đi làm hoặc đi làm về, hoặc khi có người có bằng lái từ 21 tuổi trở lên đi cùng.","p":"Đúng. Được phép lái xe đi làm hoặc đi làm về trong giờ giới nghiêm."},"tl":{"q":"Sa Florida, kailan puwedeng magmaneho nang mag-isa ang 16 taong gulang sa oras ng curfew?","o":["Kapag papunta sa bahay ng kaibigan","Kapag walang laman ang mga daan","Kapag wala pang 5 milya ang biyahe","Kapag papunta o pauwi mula sa trabaho"],"h1":"May exception ang batas para sa trabaho.","h2":"Ang 16 taong gulang ay puwedeng magmaneho nang mag-isa sa oras ng curfew kapag papunta o pauwi lang siya mula sa trabaho, o kapag kasama niya ang lisensyadong driver na 21 taong gulang o higit pa.","p":"Tama. Puwede ang pagmamaneho papunta o pauwi mula sa trabaho sa oras ng curfew."},"ar":{"q":"في Florida، متى يُسمح لمن عمره 16 سنة بالقيادة وحده في ساعات المنع الليلي؟","o":["عندما يذهب إلى بيت صديق","عندما تكون الطرق فارغة","عندما تكون الرحلة أقل من 5 أميال","عندما يذهب إلى العمل أو يعود منه"],"h1":"القانون يسمح باستثناء من أجل الوظيفة.","h2":"يُسمح لمن عمره 16 سنة بالقيادة وحده في ساعات المنع فقط عندما يذهب إلى العمل أو يعود منه، أو عندما يكون معه سائق مرخّص عمره 21 سنة أو أكثر.","p":"صحيح. الذهاب إلى العمل أو العودة منه مسموح في ساعات المنع."},"ht":{"q":"Nan Florida, ki lè yon moun 16 an ka kondi pou kont li pandan lè kouvrefe a?","o":["Lè l ap kondi al lakay yon zanmi","Lè wout yo vid","Lè vwayaj la mwens pase 5 mil","Lè l ap ale oswa l ap soti travay"],"h1":"Lalwa fè yon eksepsyon pou yon travay.","h2":"Yon moun 16 an ka kondi pou kont li pandan lè kouvrefe a sèlman lè l ap ale oswa l ap soti travay, oswa lè yon chofè ki gen lisans epi ki gen 21 an oswa plis avè l.","p":"Se sa. Ou gen dwa kondi pou ale oswa soti travay pandan kouvrefe a."},"ref":{"doc":"FL","page":25}},{"id":"licensing-015","scope":"FL","cat":"licensing","sign":null,"c":0,"en":{"q":"In Florida, what happens if you get 12 points on your driving record within 12 months?","o":["Your license is suspended for 30 days","You get a warning letter only","Your license is suspended for 1 year","Nothing happens"],"h1":"This is the first and shortest point suspension.","h2":"If you get 12 points within 12 months, your license is suspended for 30 days.","p":"Right. 12 points in 12 months means a 30-day suspension."},"es":{"q":"En Florida, ¿qué pasa si acumula 12 puntos en su récord de manejo dentro de 12 meses?","o":["Le suspenden la licencia por 30 días","Solo recibe una carta de advertencia","Le suspenden la licencia por 1 año","No pasa nada"],"h1":"Es la primera suspensión por puntos y la más corta.","h2":"Si acumula 12 puntos dentro de 12 meses, le suspenden la licencia por 30 días.","p":"Correcto. 12 puntos en 12 meses significa 30 días de suspensión."},"zh":{"q":"在 Florida，如果你在 12 个月内驾驶记录被扣 12 分，会怎么样？","o":["你的驾照被暂停 30 天","你只会收到一封警告信","你的驾照被暂停 1 年","什么事也没有"],"h1":"这是第一种、也是最短的扣分暂停。","h2":"如果你在 12 个月内被扣 12 分，你的驾照会被暂停 30 天。","p":"对。12 个月内扣 12 分，驾照暂停 30 天。"},"vi":{"q":"Ở Florida, điều gì xảy ra nếu bạn bị 12 điểm trong hồ sơ lái xe trong vòng 12 tháng?","o":["Bằng lái của bạn bị đình chỉ 30 ngày","Bạn chỉ nhận một thư cảnh cáo","Bằng lái của bạn bị đình chỉ 1 năm","Không có gì xảy ra"],"h1":"Đây là mức đình chỉ do điểm đầu tiên và ngắn nhất.","h2":"Nếu bạn bị 12 điểm trong vòng 12 tháng, bằng lái của bạn bị đình chỉ 30 ngày.","p":"Đúng. 12 điểm trong 12 tháng nghĩa là bị đình chỉ 30 ngày."},"tl":{"q":"Sa Florida, ano ang mangyayari kung makakuha ka ng 12 points sa iyong driving record sa loob ng 12 buwan?","o":["Masususpinde ang lisensya mo nang 30 araw","Warning letter lang ang matatanggap mo","Masususpinde ang lisensya mo nang 1 taon","Walang mangyayari"],"h1":"Ito ang una at pinakamaikling suspensyon dahil sa points.","h2":"Kung makakuha ka ng 12 points sa loob ng 12 buwan, masususpinde ang lisensya mo nang 30 araw.","p":"Tama. Ang 12 points sa loob ng 12 buwan ay suspensyon nang 30 araw."},"ar":{"q":"في Florida، ماذا يحدث إذا حصلت على 12 نقطة في سجل القيادة خلال 12 شهرًا؟","o":["تُوقف رخصتك لمدة 30 يومًا","تحصل على رسالة تحذير فقط","تُوقف رخصتك لمدة سنة واحدة","لا يحدث شيء"],"h1":"هذا هو أول إيقاف بسبب النقاط، وهو الأقصر.","h2":"إذا حصلت على 12 نقطة خلال 12 شهرًا، تُوقف رخصتك لمدة 30 يومًا.","p":"صحيح. 12 نقطة في 12 شهرًا تعني إيقاف الرخصة 30 يومًا."},"ht":{"q":"Nan Florida, kisa k rive si ou jwenn 12 pwen sou dosye kondi ou nan 12 mwa?","o":["Yo sispann lisans ou pou 30 jou","Ou jwenn yon lèt avètisman sèlman","Yo sispann lisans ou pou 1 an","Anyen pa rive"],"h1":"Se premye sispansyon pou pwen yo, epi se li ki pi kout.","h2":"Si ou jwenn 12 pwen nan 12 mwa, yo sispann lisans ou pou 30 jou.","p":"Se sa. 12 pwen nan 12 mwa vle di yon sispansyon 30 jou."},"ref":{"doc":"FL","page":29}},{"id":"licensing-016","scope":"FL","cat":"licensing","sign":null,"c":2,"en":{"q":"In Florida, what happens if you get 18 points on your driving record within 18 months?","o":["Your license is suspended for 30 days","Your license is suspended for 5 years","Your license is suspended for 3 months","You must only pay a fine"],"h1":"It is longer than the 30-day suspension, but shorter than one year.","h2":"If you get 18 points within 18 months, your license is suspended for 3 months.","p":"Right. 18 points in 18 months means a 3-month suspension."},"es":{"q":"En Florida, ¿qué pasa si acumula 18 puntos en su récord de manejo dentro de 18 meses?","o":["Le suspenden la licencia por 30 días","Le suspenden la licencia por 5 años","Le suspenden la licencia por 3 meses","Solo tiene que pagar una multa"],"h1":"Es más larga que la suspensión de 30 días, pero más corta que un año.","h2":"Si acumula 18 puntos dentro de 18 meses, le suspenden la licencia por 3 meses.","p":"Correcto. 18 puntos en 18 meses significa 3 meses de suspensión."},"zh":{"q":"在 Florida，如果你在 18 个月内驾驶记录被扣 18 分，会怎么样？","o":["你的驾照被暂停 30 天","你的驾照被暂停 5 年","你的驾照被暂停 3 个月","你只需要交罚款"],"h1":"它比 30 天的暂停长，但比一年短。","h2":"如果你在 18 个月内被扣 18 分，你的驾照会被暂停 3 个月。","p":"对。18 个月内扣 18 分，驾照暂停 3 个月。"},"vi":{"q":"Ở Florida, điều gì xảy ra nếu bạn bị 18 điểm trong hồ sơ lái xe trong vòng 18 tháng?","o":["Bằng lái của bạn bị đình chỉ 30 ngày","Bằng lái của bạn bị đình chỉ 5 năm","Bằng lái của bạn bị đình chỉ 3 tháng","Bạn chỉ phải đóng tiền phạt"],"h1":"Thời gian này dài hơn mức đình chỉ 30 ngày, nhưng ngắn hơn một năm.","h2":"Nếu bạn bị 18 điểm trong vòng 18 tháng, bằng lái của bạn bị đình chỉ 3 tháng.","p":"Đúng. 18 điểm trong 18 tháng nghĩa là bị đình chỉ 3 tháng."},"tl":{"q":"Sa Florida, ano ang mangyayari kung makakuha ka ng 18 points sa iyong driving record sa loob ng 18 buwan?","o":["Masususpinde ang lisensya mo nang 30 araw","Masususpinde ang lisensya mo nang 5 taon","Masususpinde ang lisensya mo nang 3 buwan","Multa lang ang babayaran mo"],"h1":"Mas mahaba ito kaysa sa suspensyon nang 30 araw, pero mas maikli kaysa sa isang taon.","h2":"Kung makakuha ka ng 18 points sa loob ng 18 buwan, masususpinde ang lisensya mo nang 3 buwan.","p":"Tama. Ang 18 points sa loob ng 18 buwan ay suspensyon nang 3 buwan."},"ar":{"q":"في Florida، ماذا يحدث إذا حصلت على 18 نقطة في سجل القيادة خلال 18 شهرًا؟","o":["تُوقف رخصتك لمدة 30 يومًا","تُوقف رخصتك لمدة 5 سنوات","تُوقف رخصتك لمدة 3 أشهر","يجب أن تدفع غرامة فقط"],"h1":"المدة أطول من إيقاف الـ 30 يومًا، لكنها أقصر من سنة.","h2":"إذا حصلت على 18 نقطة خلال 18 شهرًا، تُوقف رخصتك لمدة 3 أشهر.","p":"صحيح. 18 نقطة في 18 شهرًا تعني إيقاف الرخصة 3 أشهر."},"ht":{"q":"Nan Florida, kisa k rive si ou jwenn 18 pwen sou dosye kondi ou nan 18 mwa?","o":["Yo sispann lisans ou pou 30 jou","Yo sispann lisans ou pou 5 an","Yo sispann lisans ou pou 3 mwa","Ou dwe peye yon amann sèlman"],"h1":"Li pi long pase sispansyon 30 jou a, men li pi kout pase yon ane.","h2":"Si ou jwenn 18 pwen nan 18 mwa, yo sispann lisans ou pou 3 mwa.","p":"Se sa. 18 pwen nan 18 mwa vle di yon sispansyon 3 mwa."},"ref":{"doc":"FL","page":29}},{"id":"licensing-017","scope":"FL","cat":"licensing","sign":null,"c":1,"en":{"q":"In Florida, what happens if you get 24 points on your driving record within 36 months?","o":["Your license is suspended for 3 months","Your license is suspended for 1 year","Your license is suspended for 30 days","You must retake only the vision test"],"h1":"This is the most points, so it brings the longest point suspension.","h2":"If you get 24 points within 36 months, your license is suspended for 1 year.","p":"Right. 24 points in 36 months means a 1-year suspension."},"es":{"q":"En Florida, ¿qué pasa si acumula 24 puntos en su récord de manejo dentro de 36 meses?","o":["Le suspenden la licencia por 3 meses","Le suspenden la licencia por 1 año","Le suspenden la licencia por 30 días","Solo tiene que repetir el examen de la vista"],"h1":"Son la mayor cantidad de puntos, así que traen la suspensión más larga.","h2":"Si acumula 24 puntos dentro de 36 meses, le suspenden la licencia por 1 año.","p":"Correcto. 24 puntos en 36 meses significa 1 año de suspensión."},"zh":{"q":"在 Florida，如果你在 36 个月内驾驶记录被扣 24 分，会怎么样？","o":["你的驾照被暂停 3 个月","你的驾照被暂停 1 年","你的驾照被暂停 30 天","你只需要重新考视力"],"h1":"这是最多的分数，所以扣分暂停的时间也最长。","h2":"如果你在 36 个月内被扣 24 分，你的驾照会被暂停 1 年。","p":"对。36 个月内扣 24 分，驾照暂停 1 年。"},"vi":{"q":"Ở Florida, điều gì xảy ra nếu bạn bị 24 điểm trong hồ sơ lái xe trong vòng 36 tháng?","o":["Bằng lái của bạn bị đình chỉ 3 tháng","Bằng lái của bạn bị đình chỉ 1 năm","Bằng lái của bạn bị đình chỉ 30 ngày","Bạn chỉ phải thi lại phần kiểm tra mắt"],"h1":"Đây là số điểm cao nhất, nên dẫn đến mức đình chỉ do điểm dài nhất.","h2":"Nếu bạn bị 24 điểm trong vòng 36 tháng, bằng lái của bạn bị đình chỉ 1 năm.","p":"Đúng. 24 điểm trong 36 tháng nghĩa là bị đình chỉ 1 năm."},"tl":{"q":"Sa Florida, ano ang mangyayari kung makakuha ka ng 24 points sa iyong driving record sa loob ng 36 na buwan?","o":["Masususpinde ang lisensya mo nang 3 buwan","Masususpinde ang lisensya mo nang 1 taon","Masususpinde ang lisensya mo nang 30 araw","Vision test lang ang uulitin mo"],"h1":"Ito ang pinakamaraming points, kaya ito ang pinakamahabang suspensyon dahil sa points.","h2":"Kung makakuha ka ng 24 points sa loob ng 36 na buwan, masususpinde ang lisensya mo nang 1 taon.","p":"Tama. Ang 24 points sa loob ng 36 na buwan ay suspensyon nang 1 taon."},"ar":{"q":"في Florida، ماذا يحدث إذا حصلت على 24 نقطة في سجل القيادة خلال 36 شهرًا؟","o":["تُوقف رخصتك لمدة 3 أشهر","تُوقف رخصتك لمدة سنة واحدة","تُوقف رخصتك لمدة 30 يومًا","يجب أن تعيد اختبار النظر فقط"],"h1":"هذا أكبر عدد من النقاط، لذلك يأتي معه أطول إيقاف بسبب النقاط.","h2":"إذا حصلت على 24 نقطة خلال 36 شهرًا، تُوقف رخصتك لمدة سنة واحدة.","p":"صحيح. 24 نقطة في 36 شهرًا تعني إيقاف الرخصة سنة واحدة."},"ht":{"q":"Nan Florida, kisa k rive si ou jwenn 24 pwen sou dosye kondi ou nan 36 mwa?","o":["Yo sispann lisans ou pou 3 mwa","Yo sispann lisans ou pou 1 an","Yo sispann lisans ou pou 30 jou","Ou dwe refè egzamen je a sèlman"],"h1":"Se plis pwen yo, kidonk li pote sispansyon pou pwen ki pi long lan.","h2":"Si ou jwenn 24 pwen nan 36 mwa, yo sispann lisans ou pou 1 an.","p":"Se sa. 24 pwen nan 36 mwa vle di yon sispansyon 1 an."},"ref":{"doc":"FL","page":29}},{"id":"licensing-018","scope":"FL","cat":"licensing","sign":null,"c":3,"en":{"q":"In Florida, a driver under 18 gets 6 points within 12 months. What happens?","o":["Nothing until they reach 12 points","They get a free extra license","They must only write a letter","Driving is limited to business purposes only"],"h1":"Young drivers face limits sooner than adults.","h2":"A driver under 18 who gets 6 points within 12 months may drive only for business purposes, such as school or work, for one year.","p":"Right. Six points before 18 limits driving to business purposes only."},"es":{"q":"En Florida, un conductor menor de 18 acumula 6 puntos dentro de 12 meses. ¿Qué pasa?","o":["Nada hasta que llegue a 12 puntos","Recibe una licencia extra gratis","Solo tiene que escribir una carta","Solo puede manejar por motivos de negocio"],"h1":"Los conductores jóvenes tienen límites antes que los adultos.","h2":"Un conductor menor de 18 que acumula 6 puntos dentro de 12 meses solo puede manejar por motivos de negocio, como ir a la escuela o al trabajo, durante un año.","p":"Correcto. Seis puntos antes de los 18 limitan el manejo a motivos de negocio."},"zh":{"q":"在 Florida，一个 18 岁以下的司机在 12 个月内被扣 6 分。会怎么样？","o":["要到 12 分才会有事","他会得到一张免费的额外驾照","他只需要写一封信","只能为了办正事开车"],"h1":"年轻司机比成年人更早受到限制。","h2":"18 岁以下的司机如果在 12 个月内被扣 6 分，一年内只能为了办正事开车，例如上学或上班。","p":"对。18 岁前扣 6 分，就只能为了办正事开车。"},"vi":{"q":"Ở Florida, một tài xế dưới 18 tuổi bị 6 điểm trong vòng 12 tháng. Điều gì xảy ra?","o":["Không có gì cho đến khi bị 12 điểm","Tài xế được thêm một bằng lái miễn phí","Tài xế chỉ phải viết một lá thư","Tài xế chỉ được lái xe cho mục đích công việc"],"h1":"Tài xế trẻ bị giới hạn sớm hơn người lớn.","h2":"Tài xế dưới 18 tuổi bị 6 điểm trong vòng 12 tháng thì chỉ được lái xe cho mục đích công việc, như đi học hoặc đi làm, trong một năm.","p":"Đúng. Bị sáu điểm trước 18 tuổi thì chỉ được lái xe cho mục đích công việc."},"tl":{"q":"Sa Florida, ang driver na wala pang 18 ay nakakuha ng 6 points sa loob ng 12 buwan. Ano ang mangyayari?","o":["Wala, hangga't hindi umaabot sa 12 points","Bibigyan siya ng libreng dagdag na lisensya","Kailangan lang niyang sumulat ng liham","Limitado ang pagmamaneho sa business purposes lang"],"h1":"Mas maaga nagkakaroon ng limitasyon ang mga batang driver kaysa sa mga adult.","h2":"Ang driver na wala pang 18 na nakakuha ng 6 points sa loob ng 12 buwan ay puwedeng magmaneho para sa business purposes lang, gaya ng paaralan o trabaho, nang isang taon.","p":"Tama. Ang anim na points bago mag-18 ay naglilimita ng pagmamaneho sa business purposes lang."},"ar":{"q":"في Florida، سائق عمره أقل من 18 سنة حصل على 6 نقاط خلال 12 شهرًا. ماذا يحدث؟","o":["لا شيء حتى يصل إلى 12 نقطة","يحصل على رخصة إضافية مجانية","يجب أن يكتب رسالة فقط","تصبح القيادة مسموحة لأغراض العمل والدراسة فقط"],"h1":"السائقون الصغار يواجهون القيود أسرع من البالغين.","h2":"السائق الذي عمره أقل من 18 سنة ويحصل على 6 نقاط خلال 12 شهرًا يُسمح له بالقيادة لأغراض العمل والدراسة فقط، مثل المدرسة أو العمل، لمدة سنة واحدة.","p":"صحيح. ست نقاط قبل عمر 18 تحدّ القيادة لأغراض العمل والدراسة فقط."},"ht":{"q":"Nan Florida, yon chofè ki poko gen 18 an jwenn 6 pwen nan 12 mwa. Kisa k rive?","o":["Anyen pa rive jiskaske li rive 12 pwen","Li jwenn yon lòt lisans gratis","Li dwe ekri yon lèt sèlman","Li ka kondi sèlman pou rezon biznis"],"h1":"Jèn chofè yo jwenn limit pi vit pase granmoun yo.","h2":"Yon chofè ki poko gen 18 an epi ki jwenn 6 pwen nan 12 mwa ka kondi sèlman pou rezon biznis, tankou lekòl oswa travay, pandan yon ane.","p":"Se sa. Sis pwen anvan 18 an limite w pou kondi sèlman pou rezon biznis."},"ref":{"doc":"FL","page":29}},{"id":"licensing-019","scope":"FL","cat":"licensing","sign":null,"c":0,"en":{"q":"In Florida, what is the minimum Personal Injury Protection (PIP) insurance a car owner must carry?","o":["$10,000","$5,000","$25,000","$50,000"],"h1":"It is the same amount as the minimum property damage coverage.","h2":"A Florida car owner must carry at least $10,000 of Personal Injury Protection, which helps pay for your own injuries after a crash.","p":"Right. The PIP minimum is $10,000."},"es":{"q":"En Florida, ¿cuál es el seguro mínimo de Protección contra Lesiones Personales (PIP) que debe tener el dueño de un carro?","o":["$10,000","$5,000","$25,000","$50,000"],"h1":"Es la misma cantidad que la cobertura mínima de daños a la propiedad.","h2":"El dueño de un carro en Florida debe tener por lo menos $10,000 de Protección contra Lesiones Personales, que ayuda a pagar sus propias lesiones después de un choque.","p":"Correcto. El mínimo de PIP es $10,000."},"zh":{"q":"在 Florida，车主必须买的个人伤害保障 (PIP) 保险最低是多少？","o":["$10,000","$5,000","$25,000","$50,000"],"h1":"它和财产损失保险的最低金额一样。","h2":"Florida 的车主必须买至少 $10,000 的个人伤害保障 (PIP)，它帮助支付你自己在车祸后的伤害费用。","p":"对。PIP 最低是 $10,000。"},"vi":{"q":"Ở Florida, chủ xe phải có bảo hiểm Bảo vệ Thương tích Cá nhân (PIP) tối thiểu là bao nhiêu?","o":["$10,000","$5,000","$25,000","$50,000"],"h1":"Số tiền này bằng với mức bảo hiểm tối thiểu cho thiệt hại tài sản.","h2":"Chủ xe ở Florida phải có ít nhất $10,000 bảo hiểm Bảo vệ Thương tích Cá nhân, giúp trả chi phí cho thương tích của chính bạn sau tai nạn.","p":"Đúng. Mức PIP tối thiểu là $10,000."},"tl":{"q":"Sa Florida, magkano ang pinakamababang Personal Injury Protection (PIP) insurance na dapat mayroon ang may-ari ng kotse?","o":["$10,000","$5,000","$25,000","$50,000"],"h1":"Pareho ito ng halaga ng pinakamababang coverage para sa pinsala sa ari-arian.","h2":"Ang may-ari ng kotse sa Florida ay dapat may hindi bababa sa $10,000 na Personal Injury Protection, na tumutulong magbayad para sa sarili mong mga pinsala sa katawan pagkatapos ng banggaan.","p":"Tama. Ang pinakamababang PIP ay $10,000."},"ar":{"q":"في Florida، ما أقل مبلغ لتأمين الحماية من الإصابات الشخصية (PIP) يجب أن يكون لدى مالك السيارة؟","o":["$10,000","$5,000","$25,000","$50,000"],"h1":"إنه نفس مبلغ أقل تغطية لأضرار الممتلكات.","h2":"يجب أن يكون لدى مالك السيارة في Florida تأمين حماية من الإصابات الشخصية بمبلغ $10,000 على الأقل، وهو يساعد في دفع تكاليف إصاباتك أنت بعد الحادث.","p":"صحيح. أقل مبلغ لتأمين PIP هو $10,000."},"ht":{"q":"Nan Florida, ki pi piti kantite asirans Personal Injury Protection (PIP) yon mèt machin dwe genyen?","o":["$10,000","$5,000","$25,000","$50,000"],"h1":"Se menm kantite ak pi piti kouvèti pou domaj sou byen moun.","h2":"Yon mèt machin nan Florida dwe gen omwen $10,000 asirans Personal Injury Protection, ki ede peye pou pwòp blesi pa w apre yon aksidan.","p":"Se sa. Minimòm PIP la se $10,000."},"ref":{"doc":"FL","page":23}},{"id":"licensing-020","scope":"FL","cat":"licensing","sign":null,"c":2,"en":{"q":"In Florida, what is the minimum Property Damage Liability (PDL) insurance a car owner must carry?","o":["$1,000","$100,000","$10,000","$2,500"],"h1":"It is the same amount as the minimum PIP coverage.","h2":"A Florida car owner must carry at least $10,000 of Property Damage Liability, which pays for damage you cause to other people's property.","p":"Right. The PDL minimum is $10,000."},"es":{"q":"En Florida, ¿cuál es el seguro mínimo de Responsabilidad por Daños a la Propiedad (PDL) que debe tener el dueño de un carro?","o":["$1,000","$100,000","$10,000","$2,500"],"h1":"Es la misma cantidad que la cobertura mínima de PIP.","h2":"El dueño de un carro en Florida debe tener por lo menos $10,000 de Responsabilidad por Daños a la Propiedad, que paga los daños que usted causa a la propiedad de otras personas.","p":"Correcto. El mínimo de PDL es $10,000."},"zh":{"q":"在 Florida，车主必须买的财产损失责任 (PDL) 保险最低是多少？","o":["$1,000","$100,000","$10,000","$2,500"],"h1":"它和 PIP 保险的最低金额一样。","h2":"Florida 的车主必须买至少 $10,000 的财产损失责任保险 (PDL)，它支付你给别人财产造成的损失。","p":"对。PDL 最低是 $10,000。"},"vi":{"q":"Ở Florida, chủ xe phải có bảo hiểm Trách nhiệm Thiệt hại Tài sản (PDL) tối thiểu là bao nhiêu?","o":["$1,000","$100,000","$10,000","$2,500"],"h1":"Số tiền này bằng với mức PIP tối thiểu.","h2":"Chủ xe ở Florida phải có ít nhất $10,000 bảo hiểm Trách nhiệm Thiệt hại Tài sản, giúp trả cho thiệt hại bạn gây ra cho tài sản của người khác.","p":"Đúng. Mức PDL tối thiểu là $10,000."},"tl":{"q":"Sa Florida, magkano ang pinakamababang Property Damage Liability (PDL) insurance na dapat mayroon ang may-ari ng kotse?","o":["$1,000","$100,000","$10,000","$2,500"],"h1":"Pareho ito ng halaga ng pinakamababang PIP coverage.","h2":"Ang may-ari ng kotse sa Florida ay dapat may hindi bababa sa $10,000 na Property Damage Liability, na nagbabayad para sa pinsalang nagawa mo sa ari-arian ng ibang tao.","p":"Tama. Ang pinakamababang PDL ay $10,000."},"ar":{"q":"في Florida، ما أقل مبلغ لتأمين المسؤولية عن أضرار الممتلكات (PDL) يجب أن يكون لدى مالك السيارة؟","o":["$1,000","$100,000","$10,000","$2,500"],"h1":"إنه نفس مبلغ أقل تغطية لتأمين PIP.","h2":"يجب أن يكون لدى مالك السيارة في Florida تأمين مسؤولية عن أضرار الممتلكات بمبلغ $10,000 على الأقل، وهو يدفع ثمن الضرر الذي تسببه لممتلكات الآخرين.","p":"صحيح. أقل مبلغ لتأمين PDL هو $10,000."},"ht":{"q":"Nan Florida, ki pi piti kantite asirans Property Damage Liability (PDL) yon mèt machin dwe genyen?","o":["$1,000","$100,000","$10,000","$2,500"],"h1":"Se menm kantite ak pi piti kouvèti PIP la.","h2":"Yon mèt machin nan Florida dwe gen omwen $10,000 asirans Property Damage Liability, ki peye pou domaj ou fè sou byen lòt moun.","p":"Se sa. Minimòm PDL la se $10,000."},"ref":{"doc":"FL","page":23}},{"id":"licensing-021","scope":"FL","cat":"licensing","sign":null,"c":1,"en":{"q":"In Florida, what should you do with your proof of insurance?","o":["Keep it at home in a safe place","Keep it in the car and show it when an officer asks","Show it only when you renew your license","Mail it to the police every year"],"h1":"An officer may ask for it at a traffic stop or after a crash.","h2":"You must keep proof of insurance with you in the car and show it when a law enforcement officer asks for it.","p":"Right. Keep proof of insurance in the car and show it when asked."},"es":{"q":"En Florida, ¿qué debe hacer con su comprobante de seguro?","o":["Guardarlo en casa en un lugar seguro","Tenerlo en el carro y mostrarlo cuando un oficial lo pida","Mostrarlo solo cuando renueve la licencia","Enviarlo por correo a la policía cada año"],"h1":"Un oficial se lo puede pedir en una parada de tránsito o después de un choque.","h2":"Usted debe tener el comprobante de seguro en el carro y mostrarlo cuando un oficial de la ley se lo pida.","p":"Correcto. Tenga el comprobante de seguro en el carro y muéstrelo cuando se lo pidan."},"zh":{"q":"在 Florida，你的保险证明应该怎么处理？","o":["放在家里安全的地方","放在车里，警察要的时候给他看","只在更新驾照时出示","每年寄给警察"],"h1":"在交通拦停或车祸后，警察可能会要看。","h2":"你必须把保险证明带在车里，执法人员要看的时候给他看。","p":"对。把保险证明放在车里，有人要看时出示。"},"vi":{"q":"Ở Florida, bạn nên làm gì với giấy chứng nhận bảo hiểm của mình?","o":["Cất ở nhà, ở một chỗ an toàn","Để trong xe và đưa ra khi cảnh sát yêu cầu","Chỉ đưa ra khi gia hạn bằng lái","Gửi qua bưu điện cho cảnh sát mỗi năm"],"h1":"Cảnh sát có thể yêu cầu xem giấy này khi chặn xe hoặc sau tai nạn.","h2":"Bạn phải để giấy chứng nhận bảo hiểm trong xe và đưa ra khi nhân viên công lực yêu cầu.","p":"Đúng. Để giấy chứng nhận bảo hiểm trong xe và đưa ra khi được yêu cầu."},"tl":{"q":"Sa Florida, ano ang dapat mong gawin sa iyong proof of insurance (patunay ng insurance)?","o":["Itago ito sa bahay sa ligtas na lugar","Itago ito sa kotse at ipakita kapag hiningi ng pulis","Ipakita lang ito kapag nagre-renew ka ng lisensya","Ipadala ito sa pulis bawat taon"],"h1":"Puwede itong hingin ng pulis kapag pinara ka o pagkatapos ng banggaan.","h2":"Dapat nasa kotse mo ang iyong proof of insurance at ipakita mo ito kapag hiningi ng law enforcement officer.","p":"Tama. Itago ang proof of insurance sa kotse at ipakita kapag hiningi."},"ar":{"q":"في Florida، ماذا يجب أن تفعل بإثبات التأمين؟","o":["احتفظ به في البيت في مكان آمن","احتفظ به في السيارة وأظهره عندما يطلبه الشرطي","أظهره فقط عندما تجدد رخصتك","أرسله بالبريد إلى الشرطة كل سنة"],"h1":"قد يطلبه الشرطي عند إيقافك في الطريق أو بعد حادث.","h2":"يجب أن تحتفظ بإثبات التأمين معك في السيارة، وأن تُظهره عندما يطلبه رجل الشرطة.","p":"صحيح. احتفظ بإثبات التأمين في السيارة وأظهره عند الطلب."},"ht":{"q":"Nan Florida, kisa ou dwe fè ak prèv asirans ou?","o":["Kenbe l lakay ou nan yon bon kote","Kenbe l nan machin nan epi montre l lè yon polis mande l","Montre l sèlman lè w ap renouvle lisans ou","Voye l bay lapolis pa lapòs chak ane"],"h1":"Yon polis ka mande l lè li kanpe w sou wout la oswa apre yon aksidan.","h2":"Ou dwe kenbe prèv asirans ou avè w nan machin nan epi montre l lè yon polis mande w li.","p":"Se sa. Kenbe prèv asirans lan nan machin nan epi montre l lè yo mande l."},"ref":{"doc":"FL","page":23}},{"id":"licensing-022","scope":"FL","cat":"licensing","sign":null,"c":3,"en":{"q":"In Florida, you are in a crash and someone is hurt. What must you do?","o":["Leave and call your insurance later","Drive the injured person home","Wait until the next day to report it","Stay at the scene and call the police"],"h1":"When someone is injured, the law requires an official report right away.","h2":"When a crash injures someone, you must stay at the scene, call the police, and help the injured person get medical care.","p":"Right. If someone is hurt, stay and call the police."},"es":{"q":"En Florida, usted tiene un choque y alguien está herido. ¿Qué debe hacer?","o":["Irse y llamar a su seguro después","Llevar al herido a su casa","Esperar al día siguiente para reportarlo","Quedarse en el lugar y llamar a la policía"],"h1":"Cuando alguien está herido, la ley exige un reporte oficial enseguida.","h2":"Cuando un choque deja a alguien herido, usted debe quedarse en el lugar, llamar a la policía y ayudar a que el herido reciba atención médica.","p":"Correcto. Si alguien está herido, quédese y llame a la policía."},"zh":{"q":"在 Florida，你发生车祸，有人受伤。你必须做什么？","o":["离开，以后再打电话给保险公司","开车送受伤的人回家","等到第二天再报告","留在现场，打电话报警"],"h1":"有人受伤时，法律要求马上做正式报告。","h2":"车祸让人受伤时，你必须留在现场，打电话报警，并帮助受伤的人得到医疗救助。","p":"对。有人受伤时，留下来并报警。"},"vi":{"q":"Ở Florida, bạn bị tai nạn và có người bị thương. Bạn phải làm gì?","o":["Rời đi và gọi cho công ty bảo hiểm sau","Chở người bị thương về nhà","Đợi đến ngày hôm sau mới báo","Ở lại hiện trường và gọi cảnh sát"],"h1":"Khi có người bị thương, luật yêu cầu phải báo cáo chính thức ngay.","h2":"Khi tai nạn làm có người bị thương, bạn phải ở lại hiện trường, gọi cảnh sát, và giúp người bị thương được chăm sóc y tế.","p":"Đúng. Nếu có người bị thương, hãy ở lại và gọi cảnh sát."},"tl":{"q":"Sa Florida, nabangga ka at may nasaktan. Ano ang dapat mong gawin?","o":["Umalis at tumawag sa insurance mo mamaya","Ihatid pauwi ang taong nasaktan","Maghintay hanggang kinabukasan bago i-report","Manatili sa lugar ng banggaan at tumawag sa pulis"],"h1":"Kapag may nasaktan, hinihingi ng batas ang opisyal na report agad.","h2":"Kapag may nasaktan sa banggaan, dapat kang manatili sa lugar, tumawag sa pulis, at tulungan ang nasaktan na makakuha ng medikal na tulong.","p":"Tama. Kapag may nasaktan, manatili at tumawag sa pulis."},"ar":{"q":"في Florida، وقع لك حادث وأصيب شخص. ماذا يجب أن تفعل؟","o":["اذهب واتصل بشركة التأمين لاحقًا","خذ المصاب بالسيارة إلى بيته","انتظر حتى اليوم التالي لتبلّغ عن الحادث","ابقَ في مكان الحادث واتصل بالشرطة"],"h1":"عندما يصاب شخص، يطلب القانون تقريرًا رسميًا فورًا.","h2":"عندما يصاب شخص في حادث، يجب أن تبقى في مكان الحادث، وأن تتصل بالشرطة، وأن تساعد المصاب في الحصول على علاج طبي.","p":"صحيح. إذا أصيب شخص، ابقَ واتصل بالشرطة."},"ht":{"q":"Nan Florida, ou fè yon aksidan epi gen yon moun ki blese. Kisa ou dwe fè?","o":["Ale, epi rele asirans ou pita","Mennen moun ki blese a lakay li","Tann jouk demen pou w deklare l","Rete kote aksidan an epi rele lapolis"],"h1":"Lè yon moun blese, lalwa mande yon rapò ofisyèl touswit.","h2":"Lè yon aksidan blese yon moun, ou dwe rete kote aksidan an, rele lapolis, epi ede moun ki blese a jwenn swen medikal.","p":"Se sa. Si yon moun blese, rete epi rele lapolis."},"ref":{"doc":"FL","page":77}},{"id":"licensing-023","scope":"FL","cat":"licensing","sign":null,"c":0,"en":{"q":"In Florida, what is true about leaving the scene of a crash where someone was hurt?","o":["It is a serious crime and can be a felony","It is allowed if you were not at fault","It is allowed if you are late for work","It is only a small parking fine"],"h1":"Think about how serious the law treats leaving a hurt person behind.","h2":"Leaving the scene of a crash where someone was hurt is a serious crime in Florida and can be a felony, with jail time and loss of your license.","p":"Right. Leaving a crash with injuries is a serious crime."},"es":{"q":"En Florida, ¿qué es cierto sobre irse del lugar de un choque donde alguien resultó herido?","o":["Es un delito grave y puede ser un delito mayor (felony)","Está permitido si usted no tuvo la culpa","Está permitido si va tarde al trabajo","Es solo una multa pequeña de estacionamiento"],"h1":"Piense en lo grave que la ley considera dejar atrás a una persona herida.","h2":"Irse del lugar de un choque donde alguien resultó herido es un delito grave en Florida y puede ser un delito mayor, con cárcel y pérdida de la licencia.","p":"Correcto. Irse de un choque con heridos es un delito grave."},"zh":{"q":"在 Florida，离开有人受伤的车祸现场，哪一个说法是对的？","o":["这是严重的犯罪，可能是重罪","如果不是你的错，就可以离开","如果你上班要迟到了，就可以离开","这只是一张小小的停车罚单"],"h1":"想一想法律怎样严肃地看待丢下受伤的人。","h2":"在 Florida，离开有人受伤的车祸现场是严重的犯罪，可能是重罪，会坐牢并失去驾照。","p":"对。离开有人受伤的车祸现场是严重的犯罪。"},"vi":{"q":"Ở Florida, điều nào đúng về việc bỏ đi khỏi hiện trường tai nạn có người bị thương?","o":["Đó là tội nghiêm trọng và có thể là trọng tội","Được phép nếu bạn không có lỗi","Được phép nếu bạn bị trễ giờ làm","Đó chỉ là một khoản phạt đậu xe nhỏ"],"h1":"Hãy nghĩ xem luật coi việc bỏ lại người bị thương nghiêm trọng đến mức nào.","h2":"Bỏ đi khỏi hiện trường tai nạn có người bị thương là tội nghiêm trọng ở Florida và có thể là trọng tội, có thể bị tù và mất bằng lái.","p":"Đúng. Bỏ đi khỏi tai nạn có người bị thương là tội nghiêm trọng."},"tl":{"q":"Sa Florida, ano ang totoo tungkol sa pag-alis sa lugar ng banggaan kung saan may nasaktan?","o":["Malubhang krimen ito at puwedeng maging felony","Puwede ito kung hindi ikaw ang may kasalanan","Puwede ito kung late ka na sa trabaho","Maliit na multa lang ito, gaya ng sa parking"],"h1":"Isipin kung gaano kabigat ang tingin ng batas sa pag-iwan sa taong nasaktan.","h2":"Ang pag-alis sa lugar ng banggaan kung saan may nasaktan ay malubhang krimen sa Florida at puwedeng maging felony, na may kulong at pagkawala ng lisensya.","p":"Tama. Malubhang krimen ang pag-alis sa banggaan na may nasaktan."},"ar":{"q":"في Florida، ما الصحيح عن ترك مكان حادث أصيب فيه شخص؟","o":["إنه جريمة خطيرة وقد يكون جناية","إنه مسموح إذا لم تكن أنت المخطئ","إنه مسموح إذا كنت متأخرًا عن العمل","إنه مجرد غرامة وقوف صغيرة"],"h1":"فكّر في مدى جدية القانون مع من يترك شخصًا مصابًا.","h2":"ترك مكان حادث أصيب فيه شخص هو جريمة خطيرة في Florida وقد يكون جناية، وعقوبته السجن وفقدان الرخصة.","p":"صحيح. ترك حادث فيه إصابات جريمة خطيرة."},"ht":{"q":"Nan Florida, kisa ki vre lè yon moun kite kote yon aksidan kote gen yon moun ki te blese?","o":["Se yon krim grav, epi li ka yon felony","Ou gen dwa fè l si se pa t fòt ou","Ou gen dwa fè l si ou an reta pou travay","Se sèlman yon ti amann pou pakin"],"h1":"Panse ak jan lalwa pran l oserye lè yon moun kite yon moun ki blese dèyè.","h2":"Kite kote yon aksidan kote yon moun te blese se yon krim grav nan Florida, epi li ka yon felony, ak prizon epi ou ka pèdi lisans ou.","p":"Se sa. Kite yon aksidan kote gen moun ki blese se yon krim grav."},"ref":{"doc":"FL","page":77}},{"id":"licensing-024","scope":"FL","cat":"licensing","sign":null,"c":2,"en":{"q":"In Florida, you hit a parked car and no one is around. What must you do?","o":["Drive away because no one saw it","Wait one hour, then leave","Find the owner or leave a note with your name and address, and report it to police","Report it only if the damage is large"],"h1":"The owner needs a way to contact you.","h2":"If you hit an unattended car, you must find the owner or leave a note with your name and address in a safe place on the car, and report the crash to the police.","p":"Right. Leave your name and address, and tell the police."},"es":{"q":"En Florida, usted choca un carro estacionado y no hay nadie. ¿Qué debe hacer?","o":["Irse porque nadie lo vio","Esperar una hora y luego irse","Buscar al dueño o dejar una nota con su nombre y dirección, y reportarlo a la policía","Reportarlo solo si el daño es grande"],"h1":"El dueño necesita una forma de comunicarse con usted.","h2":"Si choca un carro sin nadie adentro, debe buscar al dueño o dejar una nota con su nombre y dirección en un lugar seguro del carro, y reportar el choque a la policía.","p":"Correcto. Deje su nombre y dirección, y avise a la policía."},"zh":{"q":"在 Florida，你撞到一辆停着的车，周围没有人。你必须做什么？","o":["开走，因为没人看到","等一个小时，然后离开","找到车主，或留下写有你姓名和地址的纸条，并向警察报告","只有损坏很大时才报告"],"h1":"车主需要有办法联系你。","h2":"如果你撞到一辆没有人的车，你必须找到车主，或在车上安全的地方留下写有你姓名和地址的纸条，并向警察报告这次车祸。","p":"对。留下你的姓名和地址，并告诉警察。"},"vi":{"q":"Ở Florida, bạn đụng vào một xe đang đậu và không có ai xung quanh. Bạn phải làm gì?","o":["Lái đi vì không ai nhìn thấy","Đợi một giờ rồi rời đi","Tìm chủ xe hoặc để lại giấy ghi tên và địa chỉ của bạn, và báo cho cảnh sát","Chỉ báo nếu hư hỏng lớn"],"h1":"Chủ xe cần có cách để liên lạc với bạn.","h2":"Nếu bạn đụng vào một xe không có người trông, bạn phải tìm chủ xe hoặc để lại giấy ghi tên và địa chỉ của bạn ở chỗ an toàn trên xe, và báo tai nạn cho cảnh sát.","p":"Đúng. Để lại tên và địa chỉ, và báo cho cảnh sát."},"tl":{"q":"Sa Florida, nabangga mo ang isang nakaparadang kotse at walang tao sa paligid. Ano ang dapat mong gawin?","o":["Umalis dahil walang nakakita","Maghintay ng isang oras, saka umalis","Hanapin ang may-ari o mag-iwan ng sulat na may pangalan at address mo, at i-report sa pulis","I-report lang kung malaki ang sira"],"h1":"Kailangan ng may-ari ng paraan para makontak ka.","h2":"Kung nabangga mo ang kotseng walang tao, dapat mong hanapin ang may-ari o mag-iwan ng sulat na may pangalan at address mo sa ligtas na lugar sa kotse, at i-report ang banggaan sa pulis.","p":"Tama. Iwan ang pangalan at address mo, at sabihin sa pulis."},"ar":{"q":"في Florida، صدمت سيارة واقفة ولا يوجد أحد حولها. ماذا يجب أن تفعل؟","o":["اذهب لأن لا أحد رأى ذلك","انتظر ساعة واحدة ثم اذهب","ابحث عن المالك أو اترك ورقة فيها اسمك وعنوانك، وبلّغ الشرطة","بلّغ فقط إذا كان الضرر كبيرًا"],"h1":"المالك يحتاج إلى طريقة للتواصل معك.","h2":"إذا صدمت سيارة ليس فيها أحد، يجب أن تجد المالك أو تترك ورقة فيها اسمك وعنوانك في مكان آمن على السيارة، وأن تبلّغ الشرطة عن الحادث.","p":"صحيح. اترك اسمك وعنوانك، وأخبر الشرطة."},"ht":{"q":"Nan Florida, ou frape yon machin ki pake epi pa gen pèsonn la. Kisa ou dwe fè?","o":["Ale paske pèsonn pa wè sa","Tann inèdtan, epi ale","Chèche mèt la oswa kite yon nòt ak non ou ak adrès ou, epi deklare l bay lapolis","Deklare l sèlman si domaj la gwo"],"h1":"Mèt machin nan bezwen yon fason pou l kontakte w.","h2":"Si ou frape yon machin ki pa gen pèsonn ladan l, ou dwe chèche mèt la oswa kite yon nòt ak non ou ak adrès ou nan yon kote ki an sekirite sou machin nan, epi deklare aksidan an bay lapolis.","p":"Se sa. Kite non ou ak adrès ou, epi di lapolis sa."},"ref":{"doc":"FL","page":77}},{"id":"licensing-025","scope":"FL","cat":"licensing","sign":null,"c":1,"en":{"q":"In Florida, after a minor crash with no injuries, the cars can still be driven. What should you do?","o":["Leave the cars where they stopped","Move the cars out of the travel lanes","Drive home without talking to anyone","Stand in the road to direct traffic"],"h1":"Blocking traffic can cause a second crash.","h2":"If no one is hurt and the cars can be driven, move them out of the travel lanes to a safe place, then exchange information.","p":"Right. Move the cars out of traffic if no one is hurt."},"es":{"q":"En Florida, después de un choque leve sin heridos, los carros todavía pueden andar. ¿Qué debe hacer?","o":["Dejar los carros donde quedaron","Sacar los carros de los carriles de tránsito","Irse a casa sin hablar con nadie","Pararse en la calle para dirigir el tráfico"],"h1":"Bloquear el tráfico puede causar un segundo choque.","h2":"Si nadie está herido y los carros pueden andar, sáquelos de los carriles de tránsito a un lugar seguro y después intercambie información.","p":"Correcto. Si nadie está herido, saque los carros del tráfico."},"zh":{"q":"在 Florida，一次小车祸后没有人受伤，车还能开。你应该做什么？","o":["把车留在停下的地方","把车移出行车道","不和任何人说话就开回家","站在路中间指挥交通"],"h1":"挡住交通可能引起第二次车祸。","h2":"如果没有人受伤，车也还能开，就把车移出行车道，开到安全的地方，然后交换资料。","p":"对。没有人受伤时，把车移出车流。"},"vi":{"q":"Ở Florida, sau một tai nạn nhẹ không ai bị thương, các xe vẫn còn chạy được. Bạn nên làm gì?","o":["Để các xe ở nguyên chỗ dừng","Đưa các xe ra khỏi làn xe chạy","Lái về nhà mà không nói chuyện với ai","Đứng giữa đường để điều khiển giao thông"],"h1":"Chắn đường có thể gây ra tai nạn thứ hai.","h2":"Nếu không ai bị thương và các xe còn chạy được, hãy đưa xe ra khỏi làn xe chạy đến chỗ an toàn, rồi trao đổi thông tin.","p":"Đúng. Đưa xe ra khỏi dòng xe nếu không ai bị thương."},"tl":{"q":"Sa Florida, pagkatapos ng maliit na banggaan na walang nasaktan, puwede pang imaneho ang mga kotse. Ano ang dapat mong gawin?","o":["Iwan ang mga kotse kung saan sila huminto","Ilipat ang mga kotse palabas ng mga lane na dinadaanan","Umuwi nang hindi kumakausap ng kahit sino","Tumayo sa daan para ayusin ang trapiko"],"h1":"Ang pagharang sa trapiko ay puwedeng magdulot ng pangalawang banggaan.","h2":"Kung walang nasaktan at puwede pang imaneho ang mga kotse, ilipat ang mga ito palabas ng mga lane na dinadaanan papunta sa ligtas na lugar, saka magpalitan ng impormasyon.","p":"Tama. Ilipat ang mga kotse palabas ng trapiko kung walang nasaktan."},"ar":{"q":"في Florida، بعد حادث بسيط بدون إصابات، ما زالت السيارات تستطيع السير. ماذا يجب أن تفعل؟","o":["اترك السيارات حيث توقفت","أبعد السيارات عن مسارات السير","اذهب إلى البيت بدون أن تتكلم مع أحد","قف في الطريق لتنظّم حركة السير"],"h1":"إغلاق الطريق قد يسبب حادثًا ثانيًا.","h2":"إذا لم يُصب أحد وكانت السيارات تستطيع السير، أبعدها عن مسارات السير إلى مكان آمن، ثم تبادلوا المعلومات.","p":"صحيح. أبعد السيارات عن حركة السير إذا لم يُصب أحد."},"ht":{"q":"Nan Florida, apre yon ti aksidan san moun blese, machin yo ka toujou woule. Kisa ou ta dwe fè?","o":["Kite machin yo kote yo te kanpe a","Deplase machin yo soti nan liy kote machin ap pase yo","Kondi al lakay ou san w pa pale ak pèsonn","Kanpe nan mitan wout la pou dirije sikilasyon an"],"h1":"Bloke sikilasyon an ka lakòz yon dezyèm aksidan.","h2":"Si pèsonn pa blese epi machin yo ka woule, deplase yo soti nan liy kote machin ap pase yo pou ale nan yon kote ki an sekirite, epi apre sa, echanje enfòmasyon.","p":"Se sa. Si pèsonn pa blese, deplase machin yo soti nan sikilasyon an."},"ref":{"doc":"FL","page":77}},{"id":"licensing-026","scope":"FL","cat":"licensing","sign":null,"c":3,"en":{"q":"In Florida, after a crash, what information must you give to the other driver?","o":["Only your phone number","Your bank account number","Nothing, unless they are hurt","Your name, address, and vehicle registration, and show your license"],"h1":"The other driver needs to know who you are and which car was involved.","h2":"After a crash, you must give your name, address, and vehicle registration number, and show your driver license to the other driver.","p":"Right. Share your name, address, registration, and license."},"es":{"q":"En Florida, después de un choque, ¿qué información debe darle al otro conductor?","o":["Solo su número de teléfono","Su número de cuenta bancaria","Nada, a menos que esté herido","Su nombre, dirección y registro del vehículo, y mostrar su licencia"],"h1":"El otro conductor necesita saber quién es usted y qué carro estuvo involucrado.","h2":"Después de un choque, usted debe dar su nombre, dirección y número de registro del vehículo, y mostrar su licencia de conducir al otro conductor.","p":"Correcto. Dé su nombre, dirección, registro y licencia."},"zh":{"q":"在 Florida，车祸后你必须给另一位司机什么资料？","o":["只给你的电话号码","你的银行账号","什么都不用给，除非他受伤","你的姓名、地址和车辆登记，并出示你的驾照"],"h1":"另一位司机需要知道你是谁，以及是哪辆车。","h2":"车祸后，你必须把你的姓名、地址和车辆登记号码告诉另一位司机，并给他看你的驾照。","p":"对。告诉对方你的姓名、地址、车辆登记，并出示驾照。"},"vi":{"q":"Ở Florida, sau tai nạn, bạn phải đưa thông tin gì cho tài xế kia?","o":["Chỉ số điện thoại của bạn","Số tài khoản ngân hàng của bạn","Không đưa gì, trừ khi họ bị thương","Tên, địa chỉ, giấy đăng ký xe của bạn, và cho xem bằng lái"],"h1":"Tài xế kia cần biết bạn là ai và xe nào liên quan.","h2":"Sau tai nạn, bạn phải đưa tên, địa chỉ, và số đăng ký xe của bạn, và cho tài xế kia xem bằng lái của bạn.","p":"Đúng. Đưa tên, địa chỉ, giấy đăng ký xe, và bằng lái."},"tl":{"q":"Sa Florida, pagkatapos ng banggaan, anong impormasyon ang dapat mong ibigay sa kabilang driver?","o":["Ang phone number mo lang","Ang bank account number mo","Wala, maliban kung nasaktan siya","Ang pangalan, address, at vehicle registration mo, at ipakita ang lisensya mo"],"h1":"Kailangang malaman ng kabilang driver kung sino ka at kung aling kotse ang nasangkot.","h2":"Pagkatapos ng banggaan, dapat mong ibigay ang pangalan, address, at vehicle registration number mo, at ipakita ang iyong driver license sa kabilang driver.","p":"Tama. Ibigay ang pangalan, address, registration, at lisensya mo."},"ar":{"q":"في Florida، بعد حادث، ما المعلومات التي يجب أن تعطيها للسائق الآخر؟","o":["رقم هاتفك فقط","رقم حسابك في البنك","لا شيء، إلا إذا أصيب","اسمك وعنوانك وتسجيل السيارة، وأن تُظهر رخصتك"],"h1":"السائق الآخر يحتاج أن يعرف من أنت وأي سيارة كانت في الحادث.","h2":"بعد الحادث، يجب أن تعطي السائق الآخر اسمك وعنوانك ورقم تسجيل السيارة، وأن تُظهر له رخصة القيادة.","p":"صحيح. أعطِ اسمك وعنوانك وتسجيل السيارة ورخصتك."},"ht":{"q":"Nan Florida, apre yon aksidan, ki enfòmasyon ou dwe bay lòt chofè a?","o":["Nimewo telefòn ou sèlman","Nimewo kont labank ou","Anyen, sof si li blese","Non ou, adrès ou, ak anrejistreman machin nan, epi montre lisans ou"],"h1":"Lòt chofè a bezwen konnen kiyès ou ye ak ki machin ki te nan aksidan an.","h2":"Apre yon aksidan, ou dwe bay lòt chofè a non ou, adrès ou, ak nimewo anrejistreman machin nan, epi montre l lisans kondi ou.","p":"Se sa. Bay non ou, adrès ou, anrejistreman an, ak lisans ou."},"ref":{"doc":"FL","page":77}},{"id":"licensing-027","scope":"FL","cat":"licensing","sign":null,"c":0,"en":{"q":"In Florida, you had a crash, and the law did not require a police report. What must you do?","o":["Send a written crash report to the state within 10 days","Do nothing at all","Report it only when you renew your license","Wait a year, then report it"],"h1":"When no officer writes a report, the job falls to you, and there is a short deadline.","h2":"If no police report was required for your crash, you must send your own written crash report to the state within 10 days.","p":"Right. Send your own crash report within 10 days."},"es":{"q":"En Florida, usted tuvo un choque y la ley no exigía un reporte de la policía. ¿Qué debe hacer?","o":["Enviar un reporte escrito del choque al estado dentro de 10 días","No hacer nada","Reportarlo solo cuando renueve la licencia","Esperar un año y luego reportarlo"],"h1":"Cuando ningún oficial hace el reporte, la tarea es suya, y el plazo es corto.","h2":"Si su choque no necesitaba un reporte de la policía, usted debe enviar su propio reporte escrito del choque al estado dentro de 10 días.","p":"Correcto. Envíe su propio reporte del choque dentro de 10 días."},"zh":{"q":"在 Florida，你发生了车祸，法律没有要求警察报告。你必须做什么？","o":["10 天内向州政府寄一份书面车祸报告","什么都不用做","只在更新驾照时报告","等一年再报告"],"h1":"没有警察写报告时，这件事就由你来做，而且期限很短。","h2":"如果你的车祸不需要警察报告，你必须在 10 天内自己向州政府寄一份书面车祸报告。","p":"对。10 天内寄出你自己的车祸报告。"},"vi":{"q":"Ở Florida, bạn bị tai nạn, và luật không yêu cầu cảnh sát lập biên bản. Bạn phải làm gì?","o":["Gửi bản báo cáo tai nạn bằng văn bản cho tiểu bang trong vòng 10 ngày","Không cần làm gì cả","Chỉ báo khi gia hạn bằng lái","Đợi một năm rồi mới báo"],"h1":"Khi không có cảnh sát lập biên bản, việc này là của bạn, và thời hạn rất ngắn.","h2":"Nếu tai nạn của bạn không cần cảnh sát lập biên bản, bạn phải tự gửi bản báo cáo tai nạn bằng văn bản cho tiểu bang trong vòng 10 ngày.","p":"Đúng. Tự gửi báo cáo tai nạn trong vòng 10 ngày."},"tl":{"q":"Sa Florida, nagkaroon ka ng banggaan, at hindi hinihingi ng batas ang police report. Ano ang dapat mong gawin?","o":["Magpadala ng nakasulat na crash report sa estado sa loob ng 10 araw","Wala kang kailangang gawin","I-report lang ito kapag nagre-renew ka ng lisensya","Maghintay ng isang taon, saka i-report"],"h1":"Kapag walang pulis na gumawa ng report, ikaw ang may tungkulin, at maikli ang deadline.","h2":"Kung hindi kailangan ang police report para sa banggaan mo, dapat kang magpadala ng sarili mong nakasulat na crash report sa estado sa loob ng 10 araw.","p":"Tama. Magpadala ng sarili mong crash report sa loob ng 10 araw."},"ar":{"q":"في Florida، وقع لك حادث، والقانون لم يطلب تقريرًا من الشرطة. ماذا يجب أن تفعل؟","o":["أرسل تقريرًا مكتوبًا عن الحادث إلى الولاية خلال 10 أيام","لا تفعل أي شيء","بلّغ فقط عندما تجدد رخصتك","انتظر سنة ثم بلّغ"],"h1":"عندما لا يكتب الشرطي تقريرًا، تصبح المهمة عليك، والمهلة قصيرة.","h2":"إذا لم يكن تقرير الشرطة مطلوبًا لحادثك، يجب أن ترسل تقريرك المكتوب عن الحادث إلى الولاية خلال 10 أيام.","p":"صحيح. أرسل تقريرك عن الحادث خلال 10 أيام."},"ht":{"q":"Nan Florida, ou te fè yon aksidan, epi lalwa pa t mande yon rapò lapolis. Kisa ou dwe fè?","o":["Voye yon rapò aksidan ekri bay leta nan 10 jou","Pa fè anyen ditou","Deklare l sèlman lè w ap renouvle lisans ou","Tann yon ane, epi deklare l"],"h1":"Lè pa gen polis ki ekri yon rapò, se ou ki gen travay la, epi ou pa gen anpil tan.","h2":"Si yo pa t mande yon rapò lapolis pou aksidan ou a, ou dwe voye pwòp rapò aksidan ekri pa w bay leta nan 10 jou.","p":"Se sa. Voye pwòp rapò aksidan pa w nan 10 jou."},"ref":{"doc":"FL","page":77}},{"id":"licensing-028","scope":"FL","cat":"licensing","sign":null,"c":2,"en":{"q":"In Florida, what does the implied consent law mean?","o":["You must agree to let police search your phone","You agree to pay any ticket without going to court","By driving, you agree to be tested for alcohol or drugs if lawfully arrested","Your passengers agree to be tested too"],"h1":"You gave this agreement when you accepted your driver license.","h2":"Implied consent means that by driving in Florida, you agree to take a breath, blood, or urine test if you are lawfully arrested for impaired driving.","p":"Right. Driving means you agree to alcohol and drug testing."},"es":{"q":"En Florida, ¿qué significa la ley de consentimiento implícito?","o":["Debe permitir que la policía revise su teléfono","Acepta pagar cualquier multa sin ir a la corte","Al manejar, usted acepta hacerse pruebas de alcohol o drogas si lo arrestan legalmente","Sus pasajeros también aceptan hacerse pruebas"],"h1":"Usted dio este acuerdo cuando aceptó su licencia de conducir.","h2":"Consentimiento implícito significa que, al manejar en Florida, usted acepta hacerse una prueba de aliento, sangre u orina si lo arrestan legalmente por manejar bajo los efectos.","p":"Correcto. Manejar significa aceptar las pruebas de alcohol y drogas."},"zh":{"q":"在 Florida，“默示同意”法律是什么意思？","o":["你必须同意让警察搜查你的手机","你同意不上法庭就交任何罚单","只要开车，就表示你同意在被合法逮捕时接受酒精或毒品检测","你的乘客也同意接受检测"],"h1":"你在接受驾照时就已经做了这个同意。","h2":"默示同意的意思是：在 Florida 开车，就表示你同意在因酒后或药后驾驶被合法逮捕时，接受呼气、血液或尿液检测。","p":"对。开车就表示你同意接受酒精和毒品检测。"},"vi":{"q":"Ở Florida, luật đồng ý ngầm định (implied consent) có nghĩa là gì?","o":["Bạn phải đồng ý cho cảnh sát lục soát điện thoại của bạn","Bạn đồng ý trả mọi giấy phạt mà không ra tòa","Khi lái xe, bạn đồng ý được kiểm tra rượu bia hoặc ma túy nếu bị bắt hợp pháp","Hành khách của bạn cũng đồng ý được kiểm tra"],"h1":"Bạn đã đưa ra sự đồng ý này khi nhận bằng lái.","h2":"Luật đồng ý ngầm định có nghĩa là khi lái xe ở Florida, bạn đồng ý làm xét nghiệm hơi thở, máu, hoặc nước tiểu nếu bạn bị bắt hợp pháp vì lái xe khi bị ảnh hưởng.","p":"Đúng. Lái xe nghĩa là bạn đồng ý được kiểm tra rượu bia và ma túy."},"tl":{"q":"Sa Florida, ano ang ibig sabihin ng implied consent law?","o":["Dapat kang pumayag na halughugin ng pulis ang phone mo","Pumapayag kang magbayad ng kahit anong ticket nang hindi pumupunta sa korte","Sa pagmamaneho, pumapayag kang ma-test para sa alak o droga kung legal kang inaresto","Pumapayag din ang mga pasahero mo na ma-test"],"h1":"Ibinigay mo ang pagpayag na ito nang tanggapin mo ang iyong driver license.","h2":"Ang implied consent ay nangangahulugang sa pagmamaneho sa Florida, pumapayag kang kumuha ng breath, blood, o urine test kung legal kang inaresto dahil sa impaired driving.","p":"Tama. Ang pagmamaneho ay nangangahulugang pumapayag ka sa test para sa alak at droga."},"ar":{"q":"في Florida، ما معنى قانون الموافقة الضمنية؟","o":["يجب أن توافق على أن تفتش الشرطة هاتفك","توافق على دفع أي مخالفة بدون الذهاب إلى المحكمة","بمجرد أنك تقود، أنت توافق على فحص الكحول أو المخدرات إذا اعتُقلت بشكل قانوني","الركاب معك يوافقون على الفحص أيضًا"],"h1":"أنت أعطيت هذه الموافقة عندما قبلت رخصة القيادة.","h2":"الموافقة الضمنية تعني أنك بمجرد أن تقود في Florida، توافق على فحص النَّفَس أو الدم أو البول إذا اعتُقلت بشكل قانوني بسبب القيادة تحت التأثير.","p":"صحيح. القيادة تعني أنك توافق على فحص الكحول والمخدرات."},"ht":{"q":"Nan Florida, kisa lwa konsantman enplisit la (implied consent) vle di?","o":["Ou dwe kite lapolis fouye telefòn ou","Ou dakò peye nenpòt kontravansyon san w pa al nan tribinal","Lè ou kondi, ou dakò pou yo teste w pou alkòl oswa dwòg si yo arete w legalman","Pasaje ou yo dakò pou yo teste yo tou"],"h1":"Ou te bay akò sa a lè ou te aksepte lisans kondi ou.","h2":"Konsantman enplisit vle di ke lè ou kondi nan Florida, ou dakò pran yon tès souf, san, oswa pipi si yo arete w legalman paske ou t ap kondi sou enfliyans.","p":"Se sa. Lè ou kondi, ou dakò pou yo teste w pou alkòl ak dwòg."},"ref":{"doc":"FL","page":25}},{"id":"licensing-029","scope":"FL","cat":"licensing","sign":null,"c":1,"en":{"q":"In Florida, what happens the first time you refuse a lawful breath, blood, or urine test?","o":["Nothing, refusing is your right","Your license is suspended for 1 year","Your license is suspended for 10 days","You get a warning only"],"h1":"Refusing has a cost, even if you were not proven drunk.","h2":"If you refuse a lawful test for the first time, your license is suspended for 1 year.","p":"Right. A first refusal means a 1-year suspension."},"es":{"q":"En Florida, ¿qué pasa la primera vez que se niega a una prueba legal de aliento, sangre u orina?","o":["Nada, negarse es su derecho","Le suspenden la licencia por 1 año","Le suspenden la licencia por 10 días","Solo recibe una advertencia"],"h1":"Negarse tiene un costo, aunque no se pruebe que estaba borracho.","h2":"Si se niega por primera vez a una prueba legal, le suspenden la licencia por 1 año.","p":"Correcto. La primera negativa significa 1 año de suspensión."},"zh":{"q":"在 Florida，你第一次拒绝合法的呼气、血液或尿液检测，会怎么样？","o":["什么事也没有，拒绝是你的权利","你的驾照被暂停 1 年","你的驾照被暂停 10 天","你只会收到警告"],"h1":"拒绝是有代价的，即使没有证明你喝醉了。","h2":"如果你第一次拒绝合法的检测，你的驾照会被暂停 1 年。","p":"对。第一次拒绝，驾照暂停 1 年。"},"vi":{"q":"Ở Florida, điều gì xảy ra lần đầu tiên bạn từ chối xét nghiệm hơi thở, máu, hoặc nước tiểu hợp pháp?","o":["Không có gì, từ chối là quyền của bạn","Bằng lái của bạn bị đình chỉ 1 năm","Bằng lái của bạn bị đình chỉ 10 ngày","Bạn chỉ bị cảnh cáo"],"h1":"Từ chối sẽ có hậu quả, dù chưa chứng minh được bạn say.","h2":"Nếu bạn từ chối xét nghiệm hợp pháp lần đầu, bằng lái của bạn bị đình chỉ 1 năm.","p":"Đúng. Từ chối lần đầu nghĩa là bị đình chỉ 1 năm."},"tl":{"q":"Sa Florida, ano ang mangyayari sa unang beses na tumanggi ka sa legal na breath, blood, o urine test?","o":["Wala, karapatan mong tumanggi","Masususpinde ang lisensya mo nang 1 taon","Masususpinde ang lisensya mo nang 10 araw","Warning lang ang makukuha mo"],"h1":"May kapalit ang pagtanggi, kahit hindi napatunayang lasing ka.","h2":"Kung tumanggi ka sa legal na test sa unang beses, masususpinde ang lisensya mo nang 1 taon.","p":"Tama. Ang unang pagtanggi ay suspensyon nang 1 taon."},"ar":{"q":"في Florida، ماذا يحدث في المرة الأولى التي ترفض فيها فحصًا قانونيًا للنَّفَس أو الدم أو البول؟","o":["لا شيء، الرفض حقك","تُوقف رخصتك لمدة سنة واحدة","تُوقف رخصتك لمدة 10 أيام","تحصل على تحذير فقط"],"h1":"الرفض له ثمن، حتى إذا لم يثبت أنك كنت سكرانًا.","h2":"إذا رفضت فحصًا قانونيًا للمرة الأولى، تُوقف رخصتك لمدة سنة واحدة.","p":"صحيح. الرفض الأول يعني إيقاف الرخصة سنة واحدة."},"ht":{"q":"Nan Florida, kisa k rive premye fwa ou refize yon tès souf, san, oswa pipi ki legal?","o":["Anyen, ou gen dwa refize","Yo sispann lisans ou pou 1 an","Yo sispann lisans ou pou 10 jou","Ou jwenn yon avètisman sèlman"],"h1":"Refize gen yon pri, menm si yo pa pwouve ou te sou.","h2":"Si ou refize yon tès legal pou premye fwa, yo sispann lisans ou pou 1 an.","p":"Se sa. Yon premye refi vle di yon sispansyon 1 an."},"ref":{"doc":"FL","page":25}},{"id":"licensing-030","scope":"FL","cat":"licensing","sign":null,"c":3,"en":{"q":"In Florida, you already refused a test once before. What happens if you refuse again?","o":["A 30-day suspension only","Nothing more than the first time","A small fine only","An 18-month suspension, and the refusal is a crime"],"h1":"A second refusal is treated more harshly than the first.","h2":"If your license was suspended before for refusing, a second refusal brings an 18-month suspension, and the refusal itself is a misdemeanor crime.","p":"Right. A second refusal means 18 months and a criminal charge."},"es":{"q":"En Florida, usted ya se negó a una prueba antes. ¿Qué pasa si se niega otra vez?","o":["Solo una suspensión de 30 días","Nada más que la primera vez","Solo una multa pequeña","Una suspensión de 18 meses, y negarse es un delito"],"h1":"La segunda negativa se castiga más fuerte que la primera.","h2":"Si antes le suspendieron la licencia por negarse, una segunda negativa trae una suspensión de 18 meses, y negarse es en sí un delito menor.","p":"Correcto. La segunda negativa significa 18 meses y un cargo criminal."},"zh":{"q":"在 Florida，你以前已经拒绝过一次检测。如果你再拒绝，会怎么样？","o":["只暂停 30 天","和第一次一样，不会更多","只有一小笔罚款","暂停 18 个月，而且拒绝本身就是犯罪"],"h1":"第二次拒绝会比第一次处罚得更重。","h2":"如果你以前因为拒绝检测被暂停过驾照，第二次拒绝会让驾照暂停 18 个月，而且拒绝本身就是轻罪。","p":"对。第二次拒绝，驾照暂停 18 个月，还会被刑事起诉。"},"vi":{"q":"Ở Florida, bạn đã từng từ chối xét nghiệm một lần. Điều gì xảy ra nếu bạn từ chối lần nữa?","o":["Chỉ bị đình chỉ 30 ngày","Không nặng hơn lần đầu","Chỉ bị phạt tiền nhỏ","Bị đình chỉ 18 tháng, và việc từ chối là một tội"],"h1":"Từ chối lần thứ hai bị xử nặng hơn lần đầu.","h2":"Nếu bằng lái của bạn đã từng bị đình chỉ vì từ chối, lần từ chối thứ hai sẽ bị đình chỉ 18 tháng, và chính việc từ chối là một tội nhẹ (misdemeanor).","p":"Đúng. Từ chối lần thứ hai nghĩa là 18 tháng và bị buộc tội hình sự."},"tl":{"q":"Sa Florida, tumanggi ka na sa test minsan noon. Ano ang mangyayari kung tumanggi ka ulit?","o":["Suspensyon nang 30 araw lang","Wala nang higit pa sa unang beses","Maliit na multa lang","Suspensyon nang 18 buwan, at krimen ang pagtanggi"],"h1":"Mas mabigat ang parusa sa pangalawang pagtanggi kaysa sa una.","h2":"Kung nasuspinde na ang lisensya mo dati dahil sa pagtanggi, ang pangalawang pagtanggi ay magdudulot ng suspensyon nang 18 buwan, at ang pagtanggi mismo ay krimen na misdemeanor.","p":"Tama. Ang pangalawang pagtanggi ay 18 buwan at kasong kriminal."},"ar":{"q":"في Florida، أنت رفضت فحصًا مرة من قبل. ماذا يحدث إذا رفضت مرة أخرى؟","o":["إيقاف لمدة 30 يومًا فقط","لا شيء أكثر من المرة الأولى","غرامة صغيرة فقط","إيقاف لمدة 18 شهرًا، والرفض يصبح جريمة"],"h1":"الرفض الثاني يُعامل بشدة أكبر من الأول.","h2":"إذا أوقفت رخصتك من قبل بسبب الرفض، فإن الرفض الثاني يؤدي إلى إيقاف لمدة 18 شهرًا، والرفض نفسه يصبح جنحة.","p":"صحيح. الرفض الثاني يعني 18 شهرًا وتهمة جنائية."},"ht":{"q":"Nan Florida, ou te deja refize yon tès yon fwa anvan. Kisa k rive si ou refize ankò?","o":["Yon sispansyon 30 jou sèlman","Anyen plis pase premye fwa a","Yon ti amann sèlman","Yon sispansyon 18 mwa, epi refi a se yon krim"],"h1":"Yo trete yon dezyèm refi pi di pase premye a.","h2":"Si yo te deja sispann lisans ou paske ou te refize, yon dezyèm refi pote yon sispansyon 18 mwa, epi refi a li menm se yon krim (misdemeanor).","p":"Se sa. Yon dezyèm refi vle di 18 mwa ak yon akizasyon kriminèl."},"ref":{"doc":"FL","page":26}},{"id":"licensing-031","scope":"FL","cat":"licensing","sign":null,"c":0,"en":{"q":"In Florida, a driver age 21 or older is legally drunk at what blood alcohol level?","o":["0.08 or higher","0.02 or higher","0.04 or higher","0.15 or higher"],"h1":"This is the standard limit for adult drivers of regular cars.","h2":"A driver age 21 or older is driving under the influence with a blood alcohol level of 0.08 or higher, and can also be charged with less if impaired.","p":"Right. For adults, the limit is 0.08."},"es":{"q":"En Florida, ¿a qué nivel de alcohol en la sangre se considera legalmente borracho a un conductor de 21 años o más?","o":["0.08 o más","0.02 o más","0.04 o más","0.15 o más"],"h1":"Es el límite normal para adultos que manejan carros comunes.","h2":"Un conductor de 21 años o más maneja bajo los efectos del alcohol con un nivel de 0.08 o más, y también puede recibir un cargo con menos si está afectado.","p":"Correcto. Para adultos, el límite es 0.08."},"zh":{"q":"在 Florida，21 岁或以上的司机，血液酒精浓度达到多少在法律上算醉酒？","o":["0.08 或更高","0.02 或更高","0.04 或更高","0.15 或更高"],"h1":"这是成年人开普通汽车的标准上限。","h2":"21 岁或以上的司机，血液酒精浓度达到 0.08 或更高，就是酒后驾驶；如果已经受到影响，浓度更低也可能被起诉。","p":"对。成年人的上限是 0.08。"},"vi":{"q":"Ở Florida, tài xế từ 21 tuổi trở lên bị coi là say theo luật khi nồng độ cồn trong máu ở mức nào?","o":["0.08 trở lên","0.02 trở lên","0.04 trở lên","0.15 trở lên"],"h1":"Đây là giới hạn chuẩn cho người lớn lái xe thông thường.","h2":"Tài xế từ 21 tuổi trở lên bị coi là lái xe khi bị ảnh hưởng nếu nồng độ cồn trong máu từ 0.08 trở lên, và vẫn có thể bị buộc tội ở mức thấp hơn nếu khả năng lái bị suy giảm.","p":"Đúng. Với người lớn, giới hạn là 0.08."},"tl":{"q":"Sa Florida, ang driver na 21 taong gulang o higit pa ay legal na lasing sa anong blood alcohol level?","o":["0.08 o higit pa","0.02 o higit pa","0.04 o higit pa","0.15 o higit pa"],"h1":"Ito ang karaniwang limit para sa mga adult na driver ng ordinaryong kotse.","h2":"Ang driver na 21 taong gulang o higit pa ay nagmamaneho nang lasing (DUI) kapag ang blood alcohol level niya ay 0.08 o higit pa, at puwede rin siyang makasuhan kahit mas mababa kung apektado na siya.","p":"Tama. Para sa mga adult, ang limit ay 0.08."},"ar":{"q":"في Florida، السائق الذي عمره 21 سنة أو أكثر يُعتبر سكرانًا قانونيًا عند أي نسبة كحول في الدم؟","o":["0.08 أو أكثر","0.02 أو أكثر","0.04 أو أكثر","0.15 أو أكثر"],"h1":"هذا هو الحد العادي للسائقين البالغين في السيارات العادية.","h2":"السائق الذي عمره 21 سنة أو أكثر يقود تحت التأثير إذا كانت نسبة الكحول في دمه 0.08 أو أكثر، ويمكن أيضًا اتهامه بنسبة أقل إذا كانت قدرته على القيادة ضعيفة.","p":"صحيح. للبالغين، الحد هو 0.08."},"ht":{"q":"Nan Florida, a ki nivo alkòl nan san lalwa di yon chofè ki gen 21 an oswa plis sou?","o":["0.08 oswa plis","0.02 oswa plis","0.04 oswa plis","0.15 oswa plis"],"h1":"Sa a se limit nòmal pou granmoun k ap kondi machin òdinè.","h2":"Yon chofè ki gen 21 an oswa plis ap kondi sou enfliyans lè nivo alkòl nan san li se 0.08 oswa plis, epi yo ka akize l menm ak mwens si li pa an kondisyon pou kondi.","p":"Se sa. Pou granmoun, limit la se 0.08."},"ref":{"doc":"FL","page":25}},{"id":"licensing-032","scope":"FL","cat":"licensing","sign":null,"c":2,"en":{"q":"In Florida, a driver under 21 can lose their license at what blood alcohol level?","o":["0.08 or higher","0.10 or higher","0.02 or higher","0.05 or higher"],"h1":"Drivers under 21 may not legally drink, so the limit is very low.","h2":"A driver under 21 with a blood alcohol level of 0.02 or higher will have their license suspended, because people under 21 may not drink at all.","p":"Right. Under 21, the limit is 0.02."},"es":{"q":"En Florida, ¿con qué nivel de alcohol en la sangre puede perder la licencia un conductor menor de 21?","o":["0.08 o más","0.10 o más","0.02 o más","0.05 o más"],"h1":"Los menores de 21 no pueden tomar alcohol legalmente, así que el límite es muy bajo.","h2":"A un conductor menor de 21 con un nivel de alcohol de 0.02 o más le suspenden la licencia, porque los menores de 21 no pueden tomar nada.","p":"Correcto. Para menores de 21, el límite es 0.02."},"zh":{"q":"在 Florida，21 岁以下的司机血液酒精浓度达到多少会失去驾照？","o":["0.08 或更高","0.10 或更高","0.02 或更高","0.05 或更高"],"h1":"21 岁以下的人在法律上不能喝酒，所以上限很低。","h2":"21 岁以下的司机，血液酒精浓度达到 0.02 或更高，驾照就会被暂停，因为 21 岁以下的人完全不能喝酒。","p":"对。21 岁以下，上限是 0.02。"},"vi":{"q":"Ở Florida, tài xế dưới 21 tuổi có thể mất bằng lái khi nồng độ cồn trong máu ở mức nào?","o":["0.08 trở lên","0.10 trở lên","0.02 trở lên","0.05 trở lên"],"h1":"Tài xế dưới 21 tuổi không được phép uống rượu bia theo luật, nên giới hạn rất thấp.","h2":"Tài xế dưới 21 tuổi có nồng độ cồn trong máu từ 0.02 trở lên sẽ bị đình chỉ bằng lái, vì người dưới 21 tuổi hoàn toàn không được uống rượu bia.","p":"Đúng. Dưới 21 tuổi, giới hạn là 0.02."},"tl":{"q":"Sa Florida, ang driver na wala pang 21 ay puwedeng mawalan ng lisensya sa anong blood alcohol level?","o":["0.08 o higit pa","0.10 o higit pa","0.02 o higit pa","0.05 o higit pa"],"h1":"Bawal uminom ng alak ang mga driver na wala pang 21, kaya napakababa ng limit.","h2":"Ang driver na wala pang 21 na may blood alcohol level na 0.02 o higit pa ay masususpinde ang lisensya, dahil bawal talagang uminom ang mga taong wala pang 21.","p":"Tama. Kapag wala pang 21, ang limit ay 0.02."},"ar":{"q":"في Florida، السائق الذي عمره أقل من 21 سنة قد يخسر رخصته عند أي نسبة كحول في الدم؟","o":["0.08 أو أكثر","0.10 أو أكثر","0.02 أو أكثر","0.05 أو أكثر"],"h1":"السائقون تحت 21 سنة لا يُسمح لهم بشرب الكحول قانونيًا، لذلك الحد منخفض جدًا.","h2":"السائق الذي عمره أقل من 21 سنة ونسبة الكحول في دمه 0.02 أو أكثر تُوقف رخصته، لأن من هم تحت 21 سنة لا يُسمح لهم بالشرب أبدًا.","p":"صحيح. تحت 21 سنة، الحد هو 0.02."},"ht":{"q":"Nan Florida, yon chofè ki poko gen 21 an ka pèdi lisans li a ki nivo alkòl nan san?","o":["0.08 oswa plis","0.10 oswa plis","0.02 oswa plis","0.05 oswa plis"],"h1":"Chofè ki poko gen 21 an pa gen dwa bwè alkòl dapre lalwa, kidonk limit la ba anpil.","h2":"Yon chofè ki poko gen 21 an ki gen yon nivo alkòl nan san 0.02 oswa plis ap wè yo sispann lisans li, paske moun ki poko gen 21 an pa gen dwa bwè ditou.","p":"Se sa. Anba 21 an, limit la se 0.02."},"ref":{"doc":"FL","page":26}},{"id":"licensing-033","scope":"FL","cat":"licensing","sign":null,"c":1,"en":{"q":"In Florida, what is the blood alcohol limit for someone driving a commercial vehicle?","o":["0.08","0.04","0.10","0.02"],"h1":"Commercial drivers have a stricter limit than regular adult drivers.","h2":"A person driving a commercial motor vehicle is over the limit at a blood alcohol level of 0.04, which is half the limit for regular adult drivers.","p":"Right. For commercial drivers, the limit is 0.04."},"es":{"q":"En Florida, ¿cuál es el límite de alcohol en la sangre para quien maneja un vehículo comercial?","o":["0.08","0.04","0.10","0.02"],"h1":"Los conductores comerciales tienen un límite más estricto que los adultos comunes.","h2":"Una persona que maneja un vehículo motorizado comercial pasa el límite con un nivel de alcohol de 0.04, que es la mitad del límite para adultos comunes.","p":"Correcto. Para conductores comerciales, el límite es 0.04."},"zh":{"q":"在 Florida，驾驶商用车辆的人，血液酒精浓度上限是多少？","o":["0.08","0.04","0.10","0.02"],"h1":"商用车司机的上限比普通成年司机更严格。","h2":"驾驶商用机动车的人，血液酒精浓度达到 0.04 就超过上限，这是普通成年司机上限的一半。","p":"对。商用车司机的上限是 0.04。"},"vi":{"q":"Ở Florida, giới hạn nồng độ cồn trong máu cho người lái xe thương mại là bao nhiêu?","o":["0.08","0.04","0.10","0.02"],"h1":"Tài xế xe thương mại có giới hạn nghiêm hơn người lớn lái xe thông thường.","h2":"Người lái xe cơ giới thương mại bị coi là vượt giới hạn khi nồng độ cồn trong máu là 0.04, bằng một nửa giới hạn của người lớn lái xe thông thường.","p":"Đúng. Với tài xế xe thương mại, giới hạn là 0.04."},"tl":{"q":"Sa Florida, ano ang blood alcohol limit para sa taong nagmamaneho ng commercial vehicle?","o":["0.08","0.04","0.10","0.02"],"h1":"Mas mahigpit ang limit para sa mga commercial driver kaysa sa mga ordinaryong adult na driver.","h2":"Ang taong nagmamaneho ng commercial motor vehicle ay lampas na sa limit sa blood alcohol level na 0.04, na kalahati ng limit para sa mga ordinaryong adult na driver.","p":"Tama. Para sa mga commercial driver, ang limit ay 0.04."},"ar":{"q":"في Florida، ما حد الكحول في الدم لمن يقود مركبة تجارية؟","o":["0.08","0.04","0.10","0.02"],"h1":"سائقو المركبات التجارية لهم حد أشد من السائقين البالغين العاديين.","h2":"الشخص الذي يقود مركبة تجارية يكون فوق الحد عندما تصل نسبة الكحول في دمه إلى 0.04، وهذا نصف حد السائقين البالغين العاديين.","p":"صحيح. لسائقي المركبات التجارية، الحد هو 0.04."},"ht":{"q":"Nan Florida, ki limit alkòl nan san pou yon moun k ap kondi yon machin komèsyal?","o":["0.08","0.04","0.10","0.02"],"h1":"Chofè komèsyal yo gen yon limit ki pi sevè pase granmoun k ap kondi machin òdinè.","h2":"Yon moun k ap kondi yon machin komèsyal depase limit la lè nivo alkòl nan san li rive 0.04, sa ki mwatye limit pou granmoun k ap kondi machin òdinè.","p":"Se sa. Pou chofè komèsyal yo, limit la se 0.04."},"ref":{"doc":"FL","page":null}},{"id":"licensing-034","scope":"FL","cat":"licensing","sign":null,"c":3,"en":{"q":"In Florida, a driver under 21 is found with a blood alcohol level of 0.02. What happens to the license the first time?","o":["It is suspended for 5 years","It is not affected","It is suspended for 1 week","It is suspended for 6 months"],"h1":"It is a real suspension, longer than a few weeks but shorter than a year.","h2":"For a first offense, a driver under 21 with a blood alcohol level of 0.02 or higher has the license suspended for 6 months.","p":"Right. The first time, the license is suspended for 6 months."},"es":{"q":"En Florida, un conductor menor de 21 tiene un nivel de alcohol de 0.02. ¿Qué pasa con su licencia la primera vez?","o":["Se la suspenden por 5 años","No le pasa nada","Se la suspenden por 1 semana","Se la suspenden por 6 meses"],"h1":"Es una suspensión real, más larga que unas semanas pero más corta que un año.","h2":"La primera vez, a un conductor menor de 21 con un nivel de alcohol de 0.02 o más le suspenden la licencia por 6 meses.","p":"Correcto. La primera vez, la licencia se suspende por 6 meses."},"zh":{"q":"在 Florida，一个 21 岁以下的司机被发现血液酒精浓度是 0.02。第一次会对驾照怎么样？","o":["暂停 5 年","没有影响","暂停 1 个星期","暂停 6 个月"],"h1":"这是真正的暂停，比几个星期长，但比一年短。","h2":"第一次违法时，21 岁以下、血液酒精浓度 0.02 或更高的司机，驾照会被暂停 6 个月。","p":"对。第一次，驾照暂停 6 个月。"},"vi":{"q":"Ở Florida, một tài xế dưới 21 tuổi bị phát hiện có nồng độ cồn trong máu là 0.02. Lần đầu, bằng lái bị xử lý thế nào?","o":["Bị đình chỉ 5 năm","Không bị ảnh hưởng","Bị đình chỉ 1 tuần","Bị đình chỉ 6 tháng"],"h1":"Đây là đình chỉ thật sự, dài hơn vài tuần nhưng ngắn hơn một năm.","h2":"Với lần vi phạm đầu, tài xế dưới 21 tuổi có nồng độ cồn trong máu từ 0.02 trở lên bị đình chỉ bằng lái 6 tháng.","p":"Đúng. Lần đầu, bằng lái bị đình chỉ 6 tháng."},"tl":{"q":"Sa Florida, ang driver na wala pang 21 ay nakitaan ng blood alcohol level na 0.02. Ano ang mangyayari sa lisensya sa unang beses?","o":["Masususpinde ito nang 5 taon","Walang epekto rito","Masususpinde ito nang 1 linggo","Masususpinde ito nang 6 na buwan"],"h1":"Totoong suspensyon ito, mas mahaba sa ilang linggo pero mas maikli sa isang taon.","h2":"Sa unang offense, ang driver na wala pang 21 na may blood alcohol level na 0.02 o higit pa ay masususpinde ang lisensya nang 6 na buwan.","p":"Tama. Sa unang beses, masususpinde ang lisensya nang 6 na buwan."},"ar":{"q":"في Florida، وُجد سائق عمره أقل من 21 سنة ونسبة الكحول في دمه 0.02. ماذا يحدث لرخصته في المرة الأولى؟","o":["تُوقف لمدة 5 سنوات","لا تتأثر","تُوقف لمدة أسبوع واحد","تُوقف لمدة 6 أشهر"],"h1":"إنه إيقاف حقيقي، أطول من بضعة أسابيع وأقصر من سنة.","h2":"في المخالفة الأولى، السائق الذي عمره أقل من 21 سنة ونسبة الكحول في دمه 0.02 أو أكثر تُوقف رخصته لمدة 6 أشهر.","p":"صحيح. في المرة الأولى، تُوقف الرخصة لمدة 6 أشهر."},"ht":{"q":"Nan Florida, yo jwenn yon chofè ki poko gen 21 an ak yon nivo alkòl nan san 0.02. Kisa k rive lisans li premye fwa a?","o":["Yo sispann li pou 5 an","Pa gen anyen ki rive l","Yo sispann li pou 1 semèn","Yo sispann li pou 6 mwa"],"h1":"Se yon vrè sispansyon, pi long pase kèk semèn men pi kout pase yon ane.","h2":"Pou yon premye fwa, yon chofè ki poko gen 21 an ki gen yon nivo alkòl nan san 0.02 oswa plis ap wè yo sispann lisans li pou 6 mwa.","p":"Se sa. Premye fwa a, yo sispann lisans lan pou 6 mwa."},"ref":{"doc":"FL","page":26}},{"id":"licensing-035","scope":"FL","cat":"licensing","sign":null,"c":0,"en":{"q":"In Florida, who may have an open container of alcohol in a moving car?","o":["No one, not the driver and not the passengers","Only the passengers","Only the driver","Anyone over 21"],"h1":"The rule covers everyone inside a regular car.","h2":"In a regular car, neither the driver nor the passengers may have an open container of alcohol while the car is on the road.","p":"Right. No one in the car may have an open container."},"es":{"q":"En Florida, ¿quién puede tener un envase abierto de alcohol en un carro en movimiento?","o":["Nadie, ni el conductor ni los pasajeros","Solo los pasajeros","Solo el conductor","Cualquier persona mayor de 21"],"h1":"La regla aplica a todos los que van en un carro común.","h2":"En un carro común, ni el conductor ni los pasajeros pueden tener un envase abierto de alcohol mientras el carro está en la calle.","p":"Correcto. Nadie en el carro puede tener un envase abierto."},"zh":{"q":"在 Florida，在行驶的车里谁可以有打开的酒瓶或酒罐？","o":["没有人可以，司机和乘客都不行","只有乘客","只有司机","21 岁以上的任何人"],"h1":"这条规定适用于普通汽车里的每一个人。","h2":"在普通汽车里，车在路上时，司机和乘客都不能有打开的酒类容器。","p":"对。车里任何人都不能有打开的酒类容器。"},"vi":{"q":"Ở Florida, ai được để chai hoặc lon rượu bia đã mở trong xe đang chạy?","o":["Không ai cả, không phải tài xế và cũng không phải hành khách","Chỉ hành khách","Chỉ tài xế","Bất kỳ ai trên 21 tuổi"],"h1":"Quy định này áp dụng cho mọi người trong một chiếc xe thông thường.","h2":"Trong một chiếc xe thông thường, cả tài xế lẫn hành khách đều không được để chai hoặc lon rượu bia đã mở khi xe đang chạy trên đường.","p":"Đúng. Không ai trong xe được để rượu bia đã mở."},"tl":{"q":"Sa Florida, sino ang puwedeng may bukas na lalagyan ng alak sa umaandar na kotse?","o":["Wala, hindi ang driver at hindi ang mga pasahero","Ang mga pasahero lang","Ang driver lang","Kahit sino na lampas 21"],"h1":"Sakop ng patakaran ang lahat ng nasa loob ng ordinaryong kotse.","h2":"Sa ordinaryong kotse, hindi puwedeng may bukas na lalagyan ng alak ang driver o ang mga pasahero habang nasa daan ang kotse.","p":"Tama. Walang sinuman sa kotse ang puwedeng may bukas na lalagyan ng alak."},"ar":{"q":"في Florida، من يُسمح له بأن يكون معه وعاء كحول مفتوح في سيارة تسير؟","o":["لا أحد، لا السائق ولا الركاب","الركاب فقط","السائق فقط","أي شخص فوق 21 سنة"],"h1":"القاعدة تشمل كل من في داخل السيارة العادية.","h2":"في السيارة العادية، لا يُسمح للسائق ولا للركاب بأن يكون معهم وعاء كحول مفتوح عندما تكون السيارة على الطريق.","p":"صحيح. لا أحد في السيارة يُسمح له بوعاء كحول مفتوح."},"ht":{"q":"Nan Florida, kiyès ki gen dwa gen yon boutèy oswa yon bwat alkòl ki louvri nan yon machin k ap woule?","o":["Pèsonn, ni chofè a ni pasaje yo","Pasaje yo sèlman","Chofè a sèlman","Nenpòt moun ki gen plis pase 21 an"],"h1":"Règ la kouvri tout moun ki andedan yon machin òdinè.","h2":"Nan yon machin òdinè, ni chofè a ni pasaje yo pa gen dwa gen yon boutèy oswa yon bwat alkòl ki louvri pandan machin nan sou wout la.","p":"Se sa. Pèsonn nan machin nan pa gen dwa gen alkòl ki louvri."},"ref":{"doc":"FL","page":null}},{"id":"licensing-036","scope":"FL","cat":"licensing","sign":null,"c":2,"en":{"q":"In Florida, who must wear a seat belt?","o":["Only the driver","Only children under 5","The driver, front-seat passengers, and all passengers under 18","Only people on the highway"],"h1":"Think about the front of the car and about young people anywhere in the car.","h2":"The driver and all front-seat passengers must wear seat belts, and every passenger under 18 must be buckled in any seat.","p":"Right. Driver, front seat, and everyone under 18 must buckle up."},"es":{"q":"En Florida, ¿quién debe usar el cinturón de seguridad?","o":["Solo el conductor","Solo los niños menores de 5","El conductor, los pasajeros de adelante y todos los pasajeros menores de 18","Solo las personas en la autopista"],"h1":"Piense en la parte de adelante del carro y en los jóvenes en cualquier asiento.","h2":"El conductor y todos los pasajeros del asiento de adelante deben usar el cinturón, y todo pasajero menor de 18 debe ir abrochado en cualquier asiento.","p":"Correcto. El conductor, los de adelante y todos los menores de 18 deben abrocharse."},"zh":{"q":"在 Florida，谁必须系安全带？","o":["只有司机","只有 5 岁以下的儿童","司机、前排乘客，以及所有 18 岁以下的乘客","只有在高速公路上的人"],"h1":"想一想车的前排，以及坐在车里任何位置的年轻人。","h2":"司机和所有前排乘客都必须系安全带，每一位 18 岁以下的乘客不管坐在哪里都必须系好。","p":"对。司机、前排乘客和所有 18 岁以下的人都必须系安全带。"},"vi":{"q":"Ở Florida, ai phải thắt dây an toàn?","o":["Chỉ tài xế","Chỉ trẻ em dưới 5 tuổi","Tài xế, hành khách ngồi ghế trước, và mọi hành khách dưới 18 tuổi","Chỉ người đi trên xa lộ"],"h1":"Hãy nghĩ đến phía trước xe và đến người trẻ ở bất kỳ chỗ nào trong xe.","h2":"Tài xế và mọi hành khách ngồi ghế trước phải thắt dây an toàn, và mọi hành khách dưới 18 tuổi phải thắt dây ở bất kỳ ghế nào.","p":"Đúng. Tài xế, ghế trước, và mọi người dưới 18 tuổi phải thắt dây an toàn."},"tl":{"q":"Sa Florida, sino ang dapat magsuot ng seat belt?","o":["Ang driver lang","Ang mga batang wala pang 5 lang","Ang driver, mga pasahero sa harap, at lahat ng pasaherong wala pang 18","Ang mga tao sa highway lang"],"h1":"Isipin ang harap ng kotse at ang mga kabataan kahit saan sa loob ng kotse.","h2":"Ang driver at lahat ng pasahero sa harap ay dapat magsuot ng seat belt, at bawat pasaherong wala pang 18 ay dapat naka-seat belt sa kahit anong upuan.","p":"Tama. Ang driver, ang nasa harap, at lahat ng wala pang 18 ay dapat naka-seat belt."},"ar":{"q":"في Florida، من يجب أن يربط حزام الأمان؟","o":["السائق فقط","الأطفال تحت 5 سنوات فقط","السائق، وركاب المقعد الأمامي، وكل الركاب تحت 18 سنة","الناس على الطريق السريع فقط"],"h1":"فكّر في مقدمة السيارة، وفي الصغار في أي مكان في السيارة.","h2":"يجب على السائق وكل ركاب المقعد الأمامي أن يربطوا حزام الأمان، ويجب على كل راكب تحت 18 سنة أن يربط الحزام في أي مقعد.","p":"صحيح. السائق، والمقعد الأمامي، وكل من هو تحت 18 سنة يجب أن يربطوا الحزام."},"ht":{"q":"Nan Florida, kiyès ki dwe mete senti sekirite?","o":["Chofè a sèlman","Timoun ki poko gen 5 an sèlman","Chofè a, pasaje ki chita devan yo, ak tout pasaje ki poko gen 18 an","Moun ki sou otowout sèlman"],"h1":"Panse ak devan machin nan, epi ak jèn moun ki nenpòt kote nan machin nan.","h2":"Chofè a ak tout pasaje ki chita devan dwe mete senti sekirite, epi chak pasaje ki poko gen 18 an dwe mete senti l sou nenpòt chèz.","p":"Se sa. Chofè a, moun devan yo, ak tout moun ki poko gen 18 an dwe mete senti."},"ref":{"doc":"FL","page":27}},{"id":"licensing-037","scope":"FL","cat":"licensing","sign":null,"c":1,"en":{"q":"In Florida, how must a child age 3 or younger ride in a car?","o":["On an adult's lap","In a separate child carrier or a car's built-in child seat","With only a regular seat belt","In any seat without a belt"],"h1":"The youngest children need the most protection.","h2":"A child age 3 or younger must ride in a separate crash-tested child carrier or in a child seat built into the car.","p":"Right. Children 3 and under need a child carrier or built-in seat."},"es":{"q":"En Florida, ¿cómo debe viajar en el carro un niño de 3 años o menos?","o":["En las piernas de un adulto","En un asiento para niños aparte o en un asiento para niños integrado al carro","Solo con un cinturón de seguridad normal","En cualquier asiento sin cinturón"],"h1":"Los niños más pequeños necesitan la mayor protección.","h2":"Un niño de 3 años o menos debe viajar en un asiento para niños aparte, probado contra choques, o en un asiento para niños integrado al carro.","p":"Correcto. Los niños de 3 años o menos necesitan un asiento para niños."},"zh":{"q":"在 Florida，3 岁或以下的儿童坐车必须怎么坐？","o":["坐在大人腿上","坐在单独的儿童安全座椅里，或车上内置的儿童座椅里","只用普通安全带","坐在任何座位，不系安全带"],"h1":"年龄最小的孩子需要最多的保护。","h2":"3 岁或以下的儿童必须坐在单独的、经过碰撞测试的儿童安全座椅里，或车上内置的儿童座椅里。","p":"对。3 岁及以下的儿童需要儿童安全座椅或内置儿童座椅。"},"vi":{"q":"Ở Florida, trẻ em từ 3 tuổi trở xuống phải ngồi trong xe như thế nào?","o":["Ngồi trên đùi người lớn","Trong ghế an toàn trẻ em riêng hoặc ghế trẻ em gắn sẵn trong xe","Chỉ với dây an toàn thông thường","Ở bất kỳ ghế nào, không cần dây"],"h1":"Trẻ nhỏ nhất cần được bảo vệ nhiều nhất.","h2":"Trẻ em từ 3 tuổi trở xuống phải ngồi trong ghế an toàn trẻ em riêng đã được thử nghiệm va chạm, hoặc trong ghế trẻ em gắn sẵn trong xe.","p":"Đúng. Trẻ từ 3 tuổi trở xuống cần ghế an toàn trẻ em hoặc ghế gắn sẵn."},"tl":{"q":"Sa Florida, paano dapat sumakay sa kotse ang batang 3 taong gulang o mas bata?","o":["Sa kandungan ng adult","Sa hiwalay na child carrier o sa child seat na nakakabit na sa kotse","Sa ordinaryong seat belt lang","Sa kahit anong upuan nang walang seat belt"],"h1":"Ang pinakabatang mga bata ang nangangailangan ng pinakamalaking proteksyon.","h2":"Ang batang 3 taong gulang o mas bata ay dapat sumakay sa hiwalay na child carrier na na-crash test, o sa child seat na nakakabit na sa kotse.","p":"Tama. Ang mga batang 3 taon pababa ay nangangailangan ng child carrier o child seat na nakakabit sa kotse."},"ar":{"q":"في Florida، كيف يجب أن يركب الطفل الذي عمره 3 سنوات أو أقل في السيارة؟","o":["في حضن شخص بالغ","في مقعد أطفال منفصل أو في مقعد أطفال مدمج في السيارة","بحزام أمان عادي فقط","في أي مقعد بدون حزام"],"h1":"الأطفال الأصغر يحتاجون إلى أكثر حماية.","h2":"الطفل الذي عمره 3 سنوات أو أقل يجب أن يركب في مقعد أطفال منفصل مُختبَر في اختبارات التصادم، أو في مقعد أطفال مدمج في السيارة.","p":"صحيح. الأطفال بعمر 3 سنوات وأقل يحتاجون إلى مقعد أطفال منفصل أو مدمج."},"ht":{"q":"Nan Florida, kijan yon timoun ki gen 3 an oswa mwens dwe chita nan yon machin?","o":["Sou janm yon granmoun","Nan yon chèz timoun apa oswa nan yon chèz timoun ki fèt ladan machin nan","Ak yon senti sekirite òdinè sèlman","Sou nenpòt chèz san senti"],"h1":"Timoun ki pi piti yo bezwen plis pwoteksyon.","h2":"Yon timoun ki gen 3 an oswa mwens dwe chita nan yon chèz timoun apa ki te teste pou aksidan, oswa nan yon chèz timoun ki fèt ladan machin nan.","p":"Se sa. Timoun 3 an oswa mwens bezwen yon chèz timoun apa oswa yon chèz ki fèt ladan machin nan."},"ref":{"doc":"FL","page":28}},{"id":"licensing-038","scope":"FL","cat":"licensing","sign":null,"c":3,"en":{"q":"In Florida, what may a child age 4 or 5 use in a car?","o":["Nothing, they may ride free","Only an adult's lap","Only the front seat with no belt","A child carrier, a built-in child seat, or a booster seat"],"h1":"Children this age have one more choice than younger children.","h2":"A child age 4 or 5 must use a separate child carrier, a built-in child seat, or a booster seat.","p":"Right. Ages 4 and 5 may use a car seat or a booster seat."},"es":{"q":"En Florida, ¿qué puede usar en el carro un niño de 4 o 5 años?","o":["Nada, puede ir suelto","Solo las piernas de un adulto","Solo el asiento de adelante sin cinturón","Un asiento para niños, un asiento integrado o un asiento elevador (booster)"],"h1":"Los niños de esta edad tienen una opción más que los niños más pequeños.","h2":"Un niño de 4 o 5 años debe usar un asiento para niños aparte, un asiento para niños integrado al carro o un asiento elevador.","p":"Correcto. A los 4 y 5 años se usa un asiento para niños o un asiento elevador."},"zh":{"q":"在 Florida，4 岁或 5 岁的儿童坐车可以用什么？","o":["什么都不用，可以随便坐","只能坐在大人腿上","只能坐前排，不系安全带","儿童安全座椅、内置儿童座椅或增高座椅"],"h1":"这个年龄的孩子比更小的孩子多一个选择。","h2":"4 岁或 5 岁的儿童必须使用单独的儿童安全座椅、内置儿童座椅或增高座椅。","p":"对。4 岁和 5 岁的儿童可以用儿童安全座椅或增高座椅。"},"vi":{"q":"Ở Florida, trẻ em 4 hoặc 5 tuổi được dùng gì trong xe?","o":["Không cần gì, trẻ được ngồi tự do","Chỉ ngồi trên đùi người lớn","Chỉ ngồi ghế trước, không cần dây","Ghế an toàn trẻ em, ghế trẻ em gắn sẵn, hoặc ghế nâng (booster seat)"],"h1":"Trẻ ở tuổi này có thêm một lựa chọn so với trẻ nhỏ hơn.","h2":"Trẻ em 4 hoặc 5 tuổi phải dùng ghế an toàn trẻ em riêng, ghế trẻ em gắn sẵn, hoặc ghế nâng (booster seat).","p":"Đúng. Trẻ 4 và 5 tuổi được dùng ghế an toàn trẻ em hoặc ghế nâng."},"tl":{"q":"Sa Florida, ano ang puwedeng gamitin ng batang 4 o 5 taong gulang sa kotse?","o":["Wala, puwede silang sumakay nang malaya","Kandungan lang ng adult","Upuan lang sa harap nang walang seat belt","Child carrier, child seat na nakakabit sa kotse, o booster seat"],"h1":"May isa pang pagpipilian ang mga batang ganito ang edad kaysa sa mas batang mga bata.","h2":"Ang batang 4 o 5 taong gulang ay dapat gumamit ng hiwalay na child carrier, child seat na nakakabit sa kotse, o booster seat.","p":"Tama. Ang edad 4 at 5 ay puwedeng gumamit ng car seat o booster seat."},"ar":{"q":"في Florida، ماذا يمكن أن يستعمل الطفل الذي عمره 4 أو 5 سنوات في السيارة؟","o":["لا شيء، يمكنه الركوب بحرية","حضن شخص بالغ فقط","المقعد الأمامي فقط بدون حزام","مقعد أطفال منفصل، أو مقعد أطفال مدمج، أو مقعد رافع (booster)"],"h1":"الأطفال في هذا العمر لهم خيار واحد إضافي مقارنة بالأطفال الأصغر.","h2":"الطفل الذي عمره 4 أو 5 سنوات يجب أن يستعمل مقعد أطفال منفصلًا، أو مقعد أطفال مدمجًا، أو مقعدًا رافعًا (booster).","p":"صحيح. في عمر 4 و5 سنوات يمكن استعمال مقعد أطفال أو مقعد رافع."},"ht":{"q":"Nan Florida, kisa yon timoun 4 oswa 5 an ka itilize nan yon machin?","o":["Anyen, yo ka chita lib","Janm yon granmoun sèlman","Chèz devan an sèlman, san senti","Yon chèz timoun apa, yon chèz timoun ki fèt ladan machin nan, oswa yon chèz booster"],"h1":"Timoun laj sa a gen yon chwa anplis pase timoun ki pi piti yo.","h2":"Yon timoun 4 oswa 5 an dwe itilize yon chèz timoun apa, yon chèz timoun ki fèt ladan machin nan, oswa yon chèz booster.","p":"Se sa. Timoun 4 ak 5 an ka itilize yon chèz timoun oswa yon chèz booster."},"ref":{"doc":"FL","page":28}},{"id":"licensing-039","scope":"FL","cat":"licensing","sign":null,"c":0,"en":{"q":"In Florida, can a police officer stop you just for texting while driving?","o":["Yes, texting while driving is a primary offense","No, only if you also break another law","No, texting while driving is legal","Only on interstate highways"],"h1":"Think about whether the officer needs a second reason to stop you.","h2":"Texting while driving is a primary offense in Florida, so an officer can stop you for texting alone.","p":"Right. You can be stopped just for texting."},"es":{"q":"En Florida, ¿puede un policía detenerlo solo por enviar mensajes de texto mientras maneja?","o":["Sí, enviar textos mientras maneja es una infracción primaria","No, solo si también viola otra ley","No, enviar textos mientras maneja es legal","Solo en las autopistas interestatales"],"h1":"Piense si el oficial necesita una segunda razón para detenerlo.","h2":"Enviar textos mientras maneja es una infracción primaria en Florida, así que un oficial puede detenerlo solo por eso.","p":"Correcto. Lo pueden detener solo por enviar textos."},"zh":{"q":"在 Florida，警察可以只因为你开车时发短信就让你停车吗？","o":["可以，开车发短信是主要违法行为","不可以，除非你也违反了别的法律","不可以，开车发短信是合法的","只在州际高速公路上可以"],"h1":"想一想警察是否需要第二个理由才能让你停车。","h2":"在 Florida，开车发短信是主要违法行为，所以警察只因为你发短信就可以让你停车。","p":"对。只因为发短信，你就可能被拦下。"},"vi":{"q":"Ở Florida, cảnh sát có thể chặn xe bạn chỉ vì bạn nhắn tin khi lái xe không?","o":["Có, nhắn tin khi lái xe là vi phạm chính (primary offense)","Không, chỉ khi bạn vi phạm thêm luật khác","Không, nhắn tin khi lái xe là hợp pháp","Chỉ trên xa lộ liên bang"],"h1":"Hãy nghĩ xem cảnh sát có cần thêm lý do thứ hai để chặn xe bạn không.","h2":"Nhắn tin khi lái xe là vi phạm chính ở Florida, nên cảnh sát có thể chặn xe bạn chỉ vì nhắn tin.","p":"Đúng. Bạn có thể bị chặn xe chỉ vì nhắn tin."},"tl":{"q":"Sa Florida, puwede ka bang parahin ng pulis dahil lang nagte-text ka habang nagmamaneho?","o":["Oo, ang pag-text habang nagmamaneho ay primary offense","Hindi, kung may iba ka lang ding nilabag na batas","Hindi, legal ang pag-text habang nagmamaneho","Sa interstate highway lang"],"h1":"Isipin kung kailangan pa ng pulis ng pangalawang dahilan para parahin ka.","h2":"Ang pag-text habang nagmamaneho ay primary offense sa Florida, kaya puwede kang parahin ng pulis dahil lang sa pag-text.","p":"Tama. Puwede kang parahin dahil lang sa pag-text."},"ar":{"q":"في Florida، هل يمكن للشرطي أن يوقفك فقط لأنك تكتب رسائل أثناء القيادة؟","o":["نعم، كتابة الرسائل أثناء القيادة مخالفة أساسية","لا، فقط إذا خالفت قانونًا آخر أيضًا","لا، كتابة الرسائل أثناء القيادة مسموحة","فقط على الطرق السريعة بين الولايات"],"h1":"فكّر: هل يحتاج الشرطي إلى سبب ثانٍ ليوقفك؟","h2":"كتابة الرسائل أثناء القيادة مخالفة أساسية في Florida، لذلك يمكن للشرطي أن يوقفك بسبب كتابة الرسائل وحدها.","p":"صحيح. يمكن أن يوقفوك فقط بسبب كتابة الرسائل."},"ht":{"q":"Nan Florida, èske yon polis ka kanpe w sèlman paske w ap voye tèks pandan w ap kondi?","o":["Wi, voye tèks pandan w ap kondi se yon enfraksyon prensipal","Non, sèlman si ou vyole yon lòt lwa tou","Non, voye tèks pandan w ap kondi pa kont lalwa","Sèlman sou otowout entèeta yo"],"h1":"Panse si polis la bezwen yon dezyèm rezon pou l kanpe w.","h2":"Voye tèks pandan w ap kondi se yon enfraksyon prensipal nan Florida, kidonk yon polis ka kanpe w sèlman paske w ap voye tèks.","p":"Se sa. Yo ka kanpe w sèlman paske w ap voye tèks."},"ref":{"doc":"FL","page":null}},{"id":"licensing-040","scope":"FL","cat":"licensing","sign":null,"c":2,"en":{"q":"In Florida, how may you use a phone while driving in a school zone or an active work zone?","o":["Holding it in your hand","Only to read texts","Only hands-free","Any way you want"],"h1":"In these zones, your hands must stay off the phone.","h2":"In a school zone or an active work zone, you may not hold a phone in your hand, so you may use it only in hands-free mode.","p":"Right. In school and work zones, phones must be hands-free."},"es":{"q":"En Florida, ¿cómo puede usar el teléfono mientras maneja en una zona escolar o en una zona de construcción activa?","o":["Sosteniéndolo en la mano","Solo para leer mensajes","Solo con manos libres","Como usted quiera"],"h1":"En estas zonas, sus manos no deben tocar el teléfono.","h2":"En una zona escolar o en una zona de construcción activa, no puede tener el teléfono en la mano, así que solo puede usarlo con manos libres.","p":"Correcto. En zonas escolares y de construcción, el teléfono debe ser de manos libres."},"zh":{"q":"在 Florida，在学校区域或正在施工的工作区开车时，你可以怎样用手机？","o":["拿在手里","只能看短信","只能免提","想怎么用就怎么用"],"h1":"在这些区域，你的手不能碰手机。","h2":"在学校区域或正在施工的工作区，你不能手里拿着手机，所以只能用免提模式。","p":"对。在学校区域和工作区，手机只能免提。"},"vi":{"q":"Ở Florida, bạn được dùng điện thoại như thế nào khi lái xe trong khu vực trường học hoặc khu vực đang thi công?","o":["Cầm điện thoại trên tay","Chỉ để đọc tin nhắn","Chỉ ở chế độ rảnh tay (hands-free)","Dùng cách nào cũng được"],"h1":"Trong những khu vực này, tay bạn không được chạm vào điện thoại.","h2":"Trong khu vực trường học hoặc khu vực đang thi công, bạn không được cầm điện thoại trên tay, nên bạn chỉ được dùng ở chế độ rảnh tay.","p":"Đúng. Trong khu vực trường học và thi công, điện thoại phải ở chế độ rảnh tay."},"tl":{"q":"Sa Florida, paano mo puwedeng gamitin ang phone habang nagmamaneho sa school zone o sa active work zone?","o":["Hawak ito sa kamay mo","Para magbasa lang ng text","Hands-free lang","Kahit anong paraan na gusto mo"],"h1":"Sa mga zone na ito, hindi dapat hawak ng mga kamay mo ang phone.","h2":"Sa school zone o sa active work zone, bawal hawakan ang phone sa kamay mo, kaya puwede mo lang itong gamitin nang hands-free.","p":"Tama. Sa mga school at work zone, dapat hands-free ang phone."},"ar":{"q":"في Florida، كيف يمكنك استعمال الهاتف أثناء القيادة في منطقة مدرسة أو منطقة أعمال نشطة؟","o":["وأنت تمسكه بيدك","لقراءة الرسائل فقط","بدون استعمال اليدين فقط","بأي طريقة تريدها"],"h1":"في هذه المناطق، يجب أن تبقى يداك بعيدتين عن الهاتف.","h2":"في منطقة المدرسة أو منطقة الأعمال النشطة، لا يُسمح لك بإمساك الهاتف بيدك، لذلك يمكنك استعماله فقط بدون استعمال اليدين.","p":"صحيح. في مناطق المدارس والأعمال، الهاتف بدون استعمال اليدين فقط."},"ht":{"q":"Nan Florida, kijan ou ka itilize yon telefòn pandan w ap kondi nan yon zòn lekòl oswa nan yon zòn travay ki aktif?","o":["Kenbe l nan men ou","Sèlman pou li tèks","Sèlman san men (hands-free)","Jan ou vle"],"h1":"Nan zòn sa yo, men ou pa dwe touche telefòn nan.","h2":"Nan yon zòn lekòl oswa nan yon zòn travay ki aktif, ou pa gen dwa kenbe telefòn nan men ou, kidonk ou ka itilize l sèlman san men (hands-free).","p":"Se sa. Nan zòn lekòl ak zòn travay, telefòn nan dwe san men (hands-free)."},"ref":{"doc":"FL","page":34}},{"id":"licensing-041","scope":"FL","cat":"licensing","sign":null,"c":1,"en":{"q":"In Florida, you move to a new home. How soon must you update the address on your license?","o":["Within 1 year","Within 30 days","Only at your next renewal","Within 6 months"],"h1":"There is a deadline of about one month.","h2":"When you move, you must update the address on your driver license within 30 days.","p":"Right. Update your address within 30 days."},"es":{"q":"En Florida, usted se muda a una casa nueva. ¿En cuánto tiempo debe actualizar la dirección de su licencia?","o":["Dentro de 1 año","Dentro de 30 días","Solo en la próxima renovación","Dentro de 6 meses"],"h1":"Hay un plazo de más o menos un mes.","h2":"Cuando se muda, usted debe actualizar la dirección de su licencia de conducir dentro de 30 días.","p":"Correcto. Actualice su dirección dentro de 30 días."},"zh":{"q":"在 Florida，你搬了新家。你必须在多长时间内更新驾照上的地址？","o":["1 年内","30 天内","只在下次更新驾照时","6 个月内"],"h1":"期限大约是一个月。","h2":"你搬家后，必须在 30 天内更新驾照上的地址。","p":"对。30 天内更新你的地址。"},"vi":{"q":"Ở Florida, bạn chuyển đến nhà mới. Bạn phải cập nhật địa chỉ trên bằng lái trong bao lâu?","o":["Trong vòng 1 năm","Trong vòng 30 ngày","Chỉ khi gia hạn lần tới","Trong vòng 6 tháng"],"h1":"Có thời hạn khoảng một tháng.","h2":"Khi chuyển nhà, bạn phải cập nhật địa chỉ trên bằng lái trong vòng 30 ngày.","p":"Đúng. Cập nhật địa chỉ trong vòng 30 ngày."},"tl":{"q":"Sa Florida, lumipat ka sa bagong bahay. Gaano kabilis mo dapat palitan ang address sa lisensya mo?","o":["Sa loob ng 1 taon","Sa loob ng 30 araw","Sa susunod na renewal lang","Sa loob ng 6 na buwan"],"h1":"May deadline na mga isang buwan.","h2":"Kapag lumipat ka, dapat mong palitan ang address sa iyong driver license sa loob ng 30 araw.","p":"Tama. Palitan ang address mo sa loob ng 30 araw."},"ar":{"q":"في Florida، انتقلت إلى بيت جديد. خلال كم من الوقت يجب أن تغيّر العنوان في رخصتك؟","o":["خلال سنة واحدة","خلال 30 يومًا","فقط عند التجديد القادم","خلال 6 أشهر"],"h1":"المهلة حوالي شهر واحد.","h2":"عندما تنتقل، يجب أن تغيّر العنوان في رخصة القيادة خلال 30 يومًا.","p":"صحيح. غيّر عنوانك خلال 30 يومًا."},"ht":{"q":"Nan Florida, ou demenaje nan yon nouvo kay. Nan konbyen tan ou dwe chanje adrès ki sou lisans ou?","o":["Nan 1 an","Nan 30 jou","Sèlman lè w ap renouvle l pwochen fwa","Nan 6 mwa"],"h1":"Gen yon dènye dat ki se apeprè yon mwa.","h2":"Lè ou demenaje, ou dwe chanje adrès ki sou lisans kondi ou nan 30 jou.","p":"Se sa. Chanje adrès ou nan 30 jou."},"ref":{"doc":"FL","page":12}},{"id":"licensing-042","scope":"FL","cat":"licensing","sign":null,"c":3,"en":{"q":"In Florida, how long is a Class E license valid?","o":["2 years","4 years","20 years","6 to 8 years"],"h1":"It lasts many years, but not for life.","h2":"A Florida Class E license is valid for six to eight years, and then you must renew it.","p":"Right. A Class E license lasts six to eight years."},"es":{"q":"En Florida, ¿por cuánto tiempo es válida la licencia Clase E?","o":["2 años","4 años","20 años","De 6 a 8 años"],"h1":"Dura muchos años, pero no toda la vida.","h2":"La licencia Clase E de Florida es válida de seis a ocho años, y después usted debe renovarla.","p":"Correcto. La licencia Clase E dura de seis a ocho años."},"zh":{"q":"在 Florida，Class E 驾照的有效期是多久？","o":["2 年","4 年","20 年","6 到 8 年"],"h1":"它可以用很多年，但不是一辈子。","h2":"Florida 的 Class E 驾照有效期是六到八年，之后你必须更新。","p":"对。Class E 驾照有效六到八年。"},"vi":{"q":"Ở Florida, bằng lái Class E có giá trị trong bao lâu?","o":["2 năm","4 năm","20 năm","6 đến 8 năm"],"h1":"Bằng có giá trị nhiều năm, nhưng không phải suốt đời.","h2":"Bằng lái Class E ở Florida có giá trị từ sáu đến tám năm, sau đó bạn phải gia hạn.","p":"Đúng. Bằng lái Class E có giá trị từ sáu đến tám năm."},"tl":{"q":"Sa Florida, gaano katagal valid ang Class E license?","o":["2 taon","4 na taon","20 taon","6 hanggang 8 taon"],"h1":"Tumatagal ito nang maraming taon, pero hindi habambuhay.","h2":"Ang Florida Class E license ay valid nang anim hanggang walong taon, at pagkatapos ay dapat mo itong i-renew.","p":"Tama. Tumatagal ang Class E license nang anim hanggang walong taon."},"ar":{"q":"في Florida، كم مدة صلاحية رخصة Class E؟","o":["سنتان","4 سنوات","20 سنة","من 6 إلى 8 سنوات"],"h1":"إنها تبقى سنوات كثيرة، لكن ليس طوال الحياة.","h2":"رخصة Class E في Florida صالحة من ست إلى ثماني سنوات، ثم يجب أن تجددها.","p":"صحيح. رخصة Class E تبقى من ست إلى ثماني سنوات."},"ht":{"q":"Nan Florida, pandan konbyen tan yon lisans Class E bon?","o":["2 an","4 an","20 an","6 a 8 an"],"h1":"Li dire anpil ane, men se pa pou tout lavi.","h2":"Yon lisans Class E nan Florida bon pou sis a uit ane, epi apre sa ou dwe renouvle l.","p":"Se sa. Yon lisans Class E dire sis a uit ane."},"ref":{"doc":"FL","page":13}},{"id":"licensing-043","scope":"FL","cat":"licensing","sign":null,"c":0,"en":{"q":"In Florida, what must a driver age 80 or older pass when renewing a license?","o":["A vision test","A new road test every time","A written essay","A physical fitness test"],"h1":"Think about the sense you use most to drive safely.","h2":"Drivers age 80 or older must pass a vision test each time they renew their license, because good eyesight is needed to drive safely.","p":"Right. Drivers 80 and older must pass a vision test to renew."},"es":{"q":"En Florida, ¿qué debe aprobar un conductor de 80 años o más al renovar la licencia?","o":["Un examen de la vista","Un nuevo examen de manejo cada vez","Un ensayo escrito","Una prueba de condición física"],"h1":"Piense en el sentido que más usa para manejar con seguridad.","h2":"Los conductores de 80 años o más deben aprobar un examen de la vista cada vez que renuevan la licencia, porque se necesita buena vista para manejar con seguridad.","p":"Correcto. Los conductores de 80 años o más deben aprobar el examen de la vista para renovar."},"zh":{"q":"在 Florida，80 岁或以上的司机更新驾照时必须通过什么？","o":["视力检查","每次都要新的路考","书面作文","体能测试"],"h1":"想一想你安全开车时用得最多的感官。","h2":"80 岁或以上的司机每次更新驾照都必须通过视力检查，因为安全开车需要好的视力。","p":"对。80 岁及以上的司机更新驾照必须通过视力检查。"},"vi":{"q":"Ở Florida, tài xế từ 80 tuổi trở lên phải đậu bài kiểm tra nào khi gia hạn bằng lái?","o":["Bài kiểm tra mắt","Bài thi lái xe mới mỗi lần","Một bài luận viết","Bài kiểm tra thể lực"],"h1":"Hãy nghĩ đến giác quan bạn dùng nhiều nhất để lái xe an toàn.","h2":"Tài xế từ 80 tuổi trở lên phải đậu bài kiểm tra mắt mỗi lần gia hạn bằng lái, vì cần có mắt tốt để lái xe an toàn.","p":"Đúng. Tài xế từ 80 tuổi trở lên phải đậu bài kiểm tra mắt để gia hạn."},"tl":{"q":"Sa Florida, ano ang dapat ipasa ng driver na 80 taong gulang o higit pa kapag nagre-renew ng lisensya?","o":["Vision test (pagsusuri ng mata)","Bagong road test sa bawat renewal","Nakasulat na sanaysay","Physical fitness test"],"h1":"Isipin ang pandama na pinakaginagamit mo para magmaneho nang ligtas.","h2":"Ang mga driver na 80 taong gulang o higit pa ay dapat pumasa sa vision test sa bawat pag-renew ng lisensya, dahil kailangan ang malinaw na paningin para magmaneho nang ligtas.","p":"Tama. Ang mga driver na 80 pataas ay dapat pumasa sa vision test para mag-renew."},"ar":{"q":"في Florida، ما الاختبار الذي يجب أن ينجح فيه السائق الذي عمره 80 سنة أو أكثر عند تجديد الرخصة؟","o":["اختبار النظر","اختبار قيادة جديد في كل مرة","مقال مكتوب","اختبار لياقة بدنية"],"h1":"فكّر في الحاسة التي تستعملها أكثر شيء لتقود بأمان.","h2":"السائقون الذين عمرهم 80 سنة أو أكثر يجب أن ينجحوا في اختبار النظر في كل مرة يجددون فيها الرخصة، لأن النظر الجيد ضروري للقيادة الآمنة.","p":"صحيح. السائقون بعمر 80 وأكثر يجب أن ينجحوا في اختبار النظر للتجديد."},"ht":{"q":"Nan Florida, kisa yon chofè ki gen 80 an oswa plis dwe pase lè l ap renouvle lisans li?","o":["Yon egzamen je","Yon nouvo egzamen sou wout la chak fwa","Yon redaksyon ekri","Yon tès fòm fizik"],"h1":"Panse ak sans ou itilize plis pou kondi san danje.","h2":"Chofè ki gen 80 an oswa plis dwe pase yon egzamen je chak fwa y ap renouvle lisans yo, paske ou bezwen wè byen pou kondi san danje.","p":"Se sa. Chofè 80 an oswa plis dwe pase yon egzamen je pou renouvle."},"ref":{"doc":"FL","page":14}},{"id":"licensing-044","scope":"FL","cat":"licensing","sign":null,"c":2,"en":{"q":"In Florida, you just moved here and became a resident. How soon must you get a Florida driver license?","o":["Within 1 year","Only when your old license expires","Within 30 days","Within 90 days"],"h1":"New residents have about one month.","h2":"A new Florida resident must get a Florida driver license within 30 days of becoming a resident.","p":"Right. New residents must get a Florida license within 30 days."},"es":{"q":"En Florida, usted se acaba de mudar y ya es residente. ¿En cuánto tiempo debe obtener una licencia de conducir de Florida?","o":["Dentro de 1 año","Solo cuando se venza su licencia anterior","Dentro de 30 días","Dentro de 90 días"],"h1":"Los residentes nuevos tienen más o menos un mes.","h2":"Un nuevo residente de Florida debe obtener una licencia de conducir de Florida dentro de 30 días después de hacerse residente.","p":"Correcto. Los residentes nuevos deben obtener la licencia de Florida dentro de 30 días."},"zh":{"q":"在 Florida，你刚搬来这里，成为居民。你必须在多长时间内拿到 Florida 驾照？","o":["1 年内","只在旧驾照过期时","30 天内","90 天内"],"h1":"新居民大约有一个月的时间。","h2":"Florida 的新居民必须在成为居民后 30 天内拿到 Florida 驾照。","p":"对。新居民必须在 30 天内拿到 Florida 驾照。"},"vi":{"q":"Ở Florida, bạn mới chuyển đến đây và trở thành cư dân. Bạn phải lấy bằng lái Florida trong bao lâu?","o":["Trong vòng 1 năm","Chỉ khi bằng lái cũ hết hạn","Trong vòng 30 ngày","Trong vòng 90 ngày"],"h1":"Cư dân mới có khoảng một tháng.","h2":"Cư dân mới của Florida phải lấy bằng lái Florida trong vòng 30 ngày kể từ khi trở thành cư dân.","p":"Đúng. Cư dân mới phải lấy bằng lái Florida trong vòng 30 ngày."},"tl":{"q":"Sa Florida, kalilipat mo lang dito at naging residente ka na. Gaano kabilis ka dapat kumuha ng Florida driver license?","o":["Sa loob ng 1 taon","Kapag nag-expire na lang ang luma mong lisensya","Sa loob ng 30 araw","Sa loob ng 90 araw"],"h1":"May mga isang buwan ang mga bagong residente.","h2":"Ang bagong residente ng Florida ay dapat kumuha ng Florida driver license sa loob ng 30 araw mula nang maging residente siya.","p":"Tama. Ang mga bagong residente ay dapat kumuha ng Florida license sa loob ng 30 araw."},"ar":{"q":"في Florida، انتقلت إلى هنا للتو وأصبحت مقيمًا. خلال كم من الوقت يجب أن تحصل على رخصة قيادة من Florida؟","o":["خلال سنة واحدة","فقط عندما تنتهي رخصتك القديمة","خلال 30 يومًا","خلال 90 يومًا"],"h1":"المقيمون الجدد لديهم حوالي شهر واحد.","h2":"المقيم الجديد في Florida يجب أن يحصل على رخصة قيادة من Florida خلال 30 يومًا من أن يصبح مقيمًا.","p":"صحيح. المقيمون الجدد يجب أن يحصلوا على رخصة Florida خلال 30 يومًا."},"ht":{"q":"Nan Florida, ou fèk vin rete isit la epi ou vin yon rezidan. Nan konbyen tan ou dwe jwenn yon lisans kondi Florida?","o":["Nan 1 an","Sèlman lè ansyen lisans ou a ekspire","Nan 30 jou","Nan 90 jou"],"h1":"Nouvo rezidan yo gen apeprè yon mwa.","h2":"Yon nouvo rezidan Florida dwe jwenn yon lisans kondi Florida nan 30 jou apre li vin rezidan.","p":"Se sa. Nouvo rezidan yo dwe jwenn yon lisans Florida nan 30 jou."},"ref":{"doc":"FL","page":3}},{"id":"licensing-045","scope":"FL","cat":"licensing","sign":null,"c":1,"en":{"q":"In Florida, what kind of license do most people need to drive a regular car?","o":["A Class A license","A Class E license","A Class B license","A motorcycle endorsement"],"h1":"Classes A and B are for large commercial vehicles.","h2":"Most people need a Class E license to drive a regular car, because Classes A, B, and C are for commercial vehicles.","p":"Right. A regular car needs a Class E license."},"es":{"q":"En Florida, ¿qué tipo de licencia necesita la mayoría de las personas para manejar un carro común?","o":["Una licencia Clase A","Una licencia Clase E","Una licencia Clase B","Un endoso de motocicleta"],"h1":"Las Clases A y B son para vehículos comerciales grandes.","h2":"La mayoría de las personas necesita una licencia Clase E para manejar un carro común, porque las Clases A, B y C son para vehículos comerciales.","p":"Correcto. Un carro común requiere una licencia Clase E."},"zh":{"q":"在 Florida，大多数人开普通汽车需要哪种驾照？","o":["Class A 驾照","Class E 驾照","Class B 驾照","摩托车附加许可"],"h1":"Class A 和 Class B 是给大型商用车的。","h2":"大多数人开普通汽车需要 Class E 驾照，因为 Class A、B 和 C 是给商用车的。","p":"对。普通汽车需要 Class E 驾照。"},"vi":{"q":"Ở Florida, đa số người cần loại bằng lái nào để lái xe hơi thông thường?","o":["Bằng lái Class A","Bằng lái Class E","Bằng lái Class B","Chứng nhận lái xe máy"],"h1":"Class A và Class B dành cho xe thương mại lớn.","h2":"Đa số người cần bằng lái Class E để lái xe hơi thông thường, vì Class A, B và C dành cho xe thương mại.","p":"Đúng. Xe hơi thông thường cần bằng lái Class E."},"tl":{"q":"Sa Florida, anong klase ng lisensya ang kailangan ng karamihan para magmaneho ng ordinaryong kotse?","o":["Class A license","Class E license","Class B license","Motorcycle endorsement"],"h1":"Ang Class A at B ay para sa malalaking commercial vehicle.","h2":"Karamihan ng tao ay nangangailangan ng Class E license para magmaneho ng ordinaryong kotse, dahil ang Class A, B, at C ay para sa mga commercial vehicle.","p":"Tama. Ang ordinaryong kotse ay nangangailangan ng Class E license."},"ar":{"q":"في Florida، ما نوع الرخصة التي يحتاجها معظم الناس لقيادة سيارة عادية؟","o":["رخصة Class A","رخصة Class E","رخصة Class B","إضافة الدراجة النارية على الرخصة"],"h1":"الفئتان A وB للمركبات التجارية الكبيرة.","h2":"معظم الناس يحتاجون إلى رخصة Class E لقيادة سيارة عادية، لأن الفئات A وB وC للمركبات التجارية.","p":"صحيح. السيارة العادية تحتاج إلى رخصة Class E."},"ht":{"q":"Nan Florida, ki kalite lisans pifò moun bezwen pou kondi yon machin òdinè?","o":["Yon lisans Class A","Yon lisans Class E","Yon lisans Class B","Yon andòsman motosiklèt"],"h1":"Class A ak Class B se pou gwo machin komèsyal.","h2":"Pifò moun bezwen yon lisans Class E pou kondi yon machin òdinè, paske Class A, B, ak C se pou machin komèsyal.","p":"Se sa. Yon machin òdinè bezwen yon lisans Class E."},"ref":{"doc":"FL","page":4}},{"id":"right-of-way-001","scope":"FL","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Florida, at a four-way stop, which car goes first?","o":["The car that came to a full stop first","The largest vehicle at the stop","The car on the far left","The car that is going straight"],"h1":"Think about the order in which the cars arrived.","h2":"At a four-way stop, the driver who stopped first goes first, and the others follow in the order they arrived.","p":"Right. At a four-way stop, the first car to stop goes first."},"es":{"q":"En Florida, en un pare de cuatro vías, ¿qué carro sigue primero?","o":["El carro que hizo el alto total primero","El vehículo más grande en el pare","El carro que está más a la izquierda","El carro que va derecho"],"h1":"Piense en el orden en que llegaron los carros.","h2":"En un pare de cuatro vías, el conductor que paró primero sigue primero, y los demás siguen en el orden en que llegaron.","p":"Correcto. En un pare de cuatro vías, el primer carro en parar sigue primero."},"zh":{"q":"在 Florida，在四向停车路口，哪辆车先走？","o":["最先完全停下的车","路口最大的车","最左边的车","直行的车"],"h1":"想一想车辆到达的先后顺序。","h2":"在四向停车路口，最先停下的司机先走，其他车按到达的顺序跟着走。","p":"对。在四向停车路口，最先停下的车先走。"},"vi":{"q":"Ở Florida, tại ngã tư có biển \"STOP\" ở cả bốn phía, xe nào được đi trước?","o":["Xe dừng hẳn lại trước tiên","Xe lớn nhất tại chỗ dừng","Xe ở phía xa bên trái","Xe đang đi thẳng"],"h1":"Hãy nghĩ về thứ tự các xe đến nơi.","h2":"Tại ngã tư có biển \"STOP\" ở cả bốn phía, người lái dừng trước sẽ đi trước, và các xe khác đi theo thứ tự đã đến.","p":"Đúng. Tại ngã tư bốn biển \"STOP\", xe dừng trước được đi trước."},"tl":{"q":"Sa Florida, sa four-way stop, aling kotse ang unang aandar?","o":["Ang kotseng unang huminto nang buo","Ang pinakamalaking sasakyan sa hintuan","Ang kotseng nasa pinakakaliwa","Ang kotseng diretso ang punta"],"h1":"Isipin ang pagkakasunod-sunod ng pagdating ng mga kotse.","h2":"Sa four-way stop, ang drayber na unang huminto ang unang aandar, at susunod ang iba ayon sa pagkakasunod ng kanilang pagdating.","p":"Tama. Sa four-way stop, ang unang kotseng huminto ang unang aandar."},"ar":{"q":"في Florida، عند تقاطع فيه علامة توقف من أربع جهات، أي سيارة تمر أولًا؟","o":["السيارة التي توقفت توقفًا كاملًا أولًا","أكبر مركبة عند التقاطع","السيارة التي في أقصى اليسار","السيارة التي تسير إلى الأمام مباشرة"],"h1":"فكّر في الترتيب الذي وصلت به السيارات.","h2":"عند تقاطع فيه علامة توقف من أربع جهات، يمر أولًا السائق الذي توقف أولًا، ثم يمر الآخرون حسب ترتيب وصولهم.","p":"صحيح. عند علامة التوقف من أربع جهات، تمر أولًا السيارة التي توقفت أولًا."},"ht":{"q":"Nan Florida, nan yon kafou ki gen siy \"STOP\" sou kat bò, ki machin ki pase anvan?","o":["Machin ki te kanpe nèt an premye a","Pi gwo machin ki nan kafou a","Machin ki pi lwen sou bò gòch la","Machin k ap kontinye tou dwat la"],"h1":"Panse ak lòd machin yo te rive.","h2":"Nan yon kafou ki gen siy \"STOP\" sou kat bò, chofè ki te kanpe an premye a pase anvan, epi lòt yo swiv nan lòd yo te rive a.","p":"Wi, se sa. Nan yon kafou ki gen \"STOP\" sou kat bò, premye machin ki kanpe a pase anvan."},"ref":{"doc":"FL","page":47}},{"id":"right-of-way-002","scope":"FL","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Florida, two cars stop at a four-way stop at the same time. Who goes first?","o":["The driver who honks first","The driver on the left","The driver on the right","The driver who is in a hurry"],"h1":"Look at where the other car is, to your left or to your right.","h2":"When two cars stop at the same time, the driver on the left lets the driver on the right go first.","p":"Right. When you arrive together, the car on the right goes first."},"es":{"q":"En Florida, dos carros paran al mismo tiempo en un pare de cuatro vías. ¿Quién sigue primero?","o":["El conductor que toca la bocina primero","El conductor de la izquierda","El conductor de la derecha","El conductor que tiene prisa"],"h1":"Fíjese dónde está el otro carro, a su izquierda o a su derecha.","h2":"Cuando dos carros paran al mismo tiempo, el conductor de la izquierda deja pasar primero al conductor de la derecha.","p":"Correcto. Si llegan juntos, sigue primero el carro de la derecha."},"zh":{"q":"在 Florida，两辆车同时停在四向停车路口。谁先走？","o":["先按喇叭的司机","左边的司机","右边的司机","赶时间的司机"],"h1":"看看另一辆车在你的左边还是右边。","h2":"两辆车同时停下时，左边的司机让右边的司机先走。","p":"对。同时到达时，右边的车先走。"},"vi":{"q":"Ở Florida, hai xe dừng cùng lúc tại ngã tư có biển \"STOP\" ở cả bốn phía. Ai được đi trước?","o":["Người bấm còi trước","Người lái ở bên trái","Người lái ở bên phải","Người lái đang vội"],"h1":"Hãy xem xe kia ở đâu, bên trái hay bên phải của bạn.","h2":"Khi hai xe dừng cùng lúc, người lái bên trái phải để người lái bên phải đi trước.","p":"Đúng. Khi đến cùng lúc, xe bên phải được đi trước."},"tl":{"q":"Sa Florida, dalawang kotse ang sabay na huminto sa four-way stop. Sino ang unang aandar?","o":["Ang drayber na unang bumusina","Ang drayber na nasa kaliwa","Ang drayber na nasa kanan","Ang drayber na nagmamadali"],"h1":"Tingnan kung nasaan ang ibang kotse, sa kaliwa mo o sa kanan mo.","h2":"Kapag sabay na huminto ang dalawang kotse, pinauuna ng drayber na nasa kaliwa ang drayber na nasa kanan.","p":"Tama. Kapag sabay kayong dumating, ang kotse sa kanan ang unang aandar."},"ar":{"q":"في Florida، توقفت سيارتان عند تقاطع فيه علامة توقف من أربع جهات في الوقت نفسه. من يمر أولًا؟","o":["السائق الذي يستعمل البوق أولًا","السائق الذي على اليسار","السائق الذي على اليمين","السائق المستعجل"],"h1":"انظر أين السيارة الأخرى: على يسارك أم على يمينك؟","h2":"عندما تتوقف سيارتان في الوقت نفسه، يترك السائق الذي على اليسار السائقَ الذي على اليمين يمر أولًا.","p":"صحيح. عندما تصلان معًا، تمر السيارة التي على اليمين أولًا."},"ht":{"q":"Nan Florida, de machin kanpe nan yon kafou ki gen \"STOP\" sou kat bò an menm tan. Kiyès ki pase anvan?","o":["Chofè ki klaksonnen an premye a","Chofè ki sou bò gòch la","Chofè ki sou bò dwat la","Chofè ki prese a"],"h1":"Gade kote lòt machin nan ye, sou bò gòch ou oswa sou bò dwat ou.","h2":"Lè de machin kanpe an menm tan, chofè ki sou bò gòch la kite chofè ki sou bò dwat la pase anvan.","p":"Wi, se sa. Lè nou rive ansanm, machin ki sou bò dwat la pase anvan."},"ref":{"doc":"FL","page":47}},{"id":"right-of-way-003","scope":"FL","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Florida, you reach an intersection with no signs or lights. A car is already crossing it. What do you do?","o":["Go first, because you are on the wider road","Let the car that is already in the intersection go first","Honk and go at the same time","Speed up to cross before it"],"h1":"Think about who is already using the space.","h2":"At an intersection with no signs or lights, you must yield to a vehicle that is already in the intersection.","p":"Right. Yield to the car that is already in the intersection."},"es":{"q":"En Florida, usted llega a una intersección sin señales ni semáforos. Un carro ya la está cruzando. ¿Qué hace?","o":["Sigue primero, porque usted va por la calle más ancha","Deja pasar primero al carro que ya está en la intersección","Toca la bocina y sigue al mismo tiempo","Acelera para cruzar antes que él"],"h1":"Piense en quién ya está usando ese espacio.","h2":"En una intersección sin señales ni semáforos, usted debe ceder el paso al vehículo que ya está dentro de la intersección.","p":"Correcto. Ceda el paso al carro que ya está en la intersección."},"zh":{"q":"在 Florida，你来到一个没有标志也没有红绿灯的路口。有一辆车已经在通过路口。你该怎么做？","o":["你先走，因为你的路更宽","让已经在路口里的车先走","按喇叭，同时开过去","加速，抢在它前面通过"],"h1":"想一想谁已经在使用这个空间。","h2":"在没有标志也没有红绿灯的路口，你必须让已经在路口里的车先走。","p":"对。让已经在路口里的车先走。"},"vi":{"q":"Ở Florida, bạn đến một giao lộ không có biển báo hay đèn. Một xe đang chạy qua giao lộ. Bạn làm gì?","o":["Đi trước, vì đường của bạn rộng hơn","Để xe đang ở trong giao lộ đi trước","Bấm còi và đi cùng lúc","Tăng tốc để qua trước xe đó"],"h1":"Hãy nghĩ xem ai đang dùng chỗ đó rồi.","h2":"Tại giao lộ không có biển báo hay đèn, bạn phải nhường đường cho xe đã ở trong giao lộ.","p":"Đúng. Hãy nhường xe đã ở trong giao lộ."},"tl":{"q":"Sa Florida, dumating ka sa intersection na walang karatula o ilaw trapiko. May kotseng tumatawid na roon. Ano ang gagawin mo?","o":["Mauna ka, dahil mas malapad ang daan mo","Paunahin ang kotseng nasa loob na ng intersection","Bumusina at sabay na umandar","Bumilis para makatawid bago ito"],"h1":"Isipin kung sino na ang gumagamit ng lugar.","h2":"Sa intersection na walang karatula o ilaw, dapat kang magbigay-daan sa sasakyang nasa loob na ng intersection.","p":"Tama. Magbigay-daan sa kotseng nasa loob na ng intersection."},"ar":{"q":"في Florida، وصلت إلى تقاطع ليس فيه علامات ولا إشارات ضوئية. هناك سيارة تعبره الآن. ماذا تفعل؟","o":["أمر أولًا لأن طريقي أعرض","أترك السيارة التي في التقاطع تمر أولًا","أستعمل البوق وأمر في الوقت نفسه","أسرع لأعبر قبلها"],"h1":"فكّر في من يستعمل المكان الآن.","h2":"عند تقاطع ليس فيه علامات ولا إشارات ضوئية، يجب أن تعطي حق المرور للمركبة الموجودة داخل التقاطع.","p":"صحيح. أعطِ حق المرور للسيارة الموجودة داخل التقاطع."},"ht":{"q":"Nan Florida, ou rive nan yon kafou ki pa gen siy ni limyè. Gen yon machin ki deja ap travèse l. Kisa ou fè?","o":["Ou pase anvan, paske wout ou a pi laj","Ou kite machin ki deja nan kafou a pase anvan","Ou klaksonnen epi ou pase an menm tan","Ou akselere pou travèse anvan li"],"h1":"Panse ak kiyès ki deja ap sèvi ak espas la.","h2":"Nan yon kafou ki pa gen siy ni limyè, ou dwe kite yon machin ki deja nan kafou a pase anvan.","p":"Wi, se sa. Kite machin ki deja nan kafou a pase anvan."},"ref":{"doc":"FL","page":62}},{"id":"right-of-way-004","scope":"FL","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Florida, you and another car reach an intersection with no signs at the same time. The other car is on your right. Who goes first?","o":["You go first, because you are on the left","The faster car goes first","Both cars go at the same time","The car on your right goes first"],"h1":"The rule is the same as when two cars stop together at a stop sign.","h2":"When two cars reach an open intersection at the same time, the driver on the left yields, so the car on your right goes first.","p":"Right. At the same time, the car on the right goes first."},"es":{"q":"En Florida, usted y otro carro llegan al mismo tiempo a una intersección sin señales. El otro carro está a su derecha. ¿Quién sigue primero?","o":["Usted sigue primero, porque está a la izquierda","Sigue primero el carro más rápido","Los dos carros siguen al mismo tiempo","Sigue primero el carro que está a su derecha"],"h1":"La regla es igual que cuando dos carros paran juntos en un pare.","h2":"Cuando dos carros llegan al mismo tiempo a una intersección sin control, cede el paso el conductor de la izquierda, así que sigue primero el carro de su derecha.","p":"Correcto. Si llegan juntos, sigue primero el carro de la derecha."},"zh":{"q":"在 Florida，你和另一辆车同时来到一个没有标志的路口。另一辆车在你的右边。谁先走？","o":["你先走，因为你在左边","开得快的车先走","两辆车同时走","你右边的车先走"],"h1":"规则和两辆车同时停在停车标志前一样。","h2":"两辆车同时来到没有管制的路口时，左边的司机要让行，所以你右边的车先走。","p":"对。同时到达时，右边的车先走。"},"vi":{"q":"Ở Florida, bạn và một xe khác đến giao lộ không có biển báo cùng lúc. Xe kia ở bên phải bạn. Ai được đi trước?","o":["Bạn đi trước, vì bạn ở bên trái","Xe nhanh hơn đi trước","Cả hai xe đi cùng lúc","Xe bên phải bạn đi trước"],"h1":"Quy tắc giống như khi hai xe cùng dừng ở biển \"STOP\".","h2":"Khi hai xe đến giao lộ không có biển báo cùng lúc, người lái bên trái phải nhường, nên xe bên phải bạn được đi trước.","p":"Đúng. Khi đến cùng lúc, xe bên phải được đi trước."},"tl":{"q":"Sa Florida, sabay kayong dumating ng isa pang kotse sa intersection na walang karatula. Nasa kanan mo ang kotse. Sino ang mauuna?","o":["Ikaw ang mauuna, dahil nasa kaliwa ka","Ang mas mabilis na kotse ang mauuna","Sabay na aandar ang dalawang kotse","Ang kotse sa kanan mo ang mauuna"],"h1":"Pareho ang patakaran kapag sabay na huminto ang dalawang kotse sa stop sign.","h2":"Kapag sabay na dumating ang dalawang kotse sa bukas na intersection, nagbibigay-daan ang drayber sa kaliwa, kaya ang kotse sa kanan mo ang mauuna.","p":"Tama. Kapag sabay, ang kotse sa kanan ang mauuna."},"ar":{"q":"في Florida، وصلت أنت وسيارة أخرى إلى تقاطع ليس فيه علامات في الوقت نفسه. السيارة الأخرى على يمينك. من يمر أولًا؟","o":["أنت تمر أولًا لأنك على اليسار","السيارة الأسرع تمر أولًا","تمر السيارتان في الوقت نفسه","السيارة التي على يمينك تمر أولًا"],"h1":"القاعدة هي نفسها عندما تتوقف سيارتان معًا عند علامة توقف.","h2":"عندما تصل سيارتان إلى تقاطع مفتوح في الوقت نفسه، يعطي السائق الذي على اليسار حق المرور، لذلك تمر السيارة التي على يمينك أولًا.","p":"صحيح. إذا وصلتما في الوقت نفسه، تمر السيارة التي على اليمين أولًا."},"ht":{"q":"Nan Florida, ou menm ak yon lòt machin rive an menm tan nan yon kafou ki pa gen siy. Lòt machin nan sou bò dwat ou. Kiyès ki pase anvan?","o":["Ou pase anvan, paske ou sou bò gòch la","Machin ki pi vit la pase anvan","De machin yo pase an menm tan","Machin ki sou bò dwat ou a pase anvan"],"h1":"Règ la se menm jan ak lè de machin kanpe ansanm devan yon siy \"STOP\".","h2":"Lè de machin rive an menm tan nan yon kafou ki pa gen siy, chofè ki sou bò gòch la kite lòt la pase, kidonk machin ki sou bò dwat ou a pase anvan.","p":"Wi, se sa. Lè nou rive an menm tan, machin ki sou bò dwat la pase anvan."},"ref":{"doc":"FL","page":62}},{"id":"right-of-way-006","scope":"FL","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Florida, you want to turn left at a green light. A car is coming toward you. What do you do?","o":["Turn quickly before it gets close","Turn, because a green light gives you the right of way","Wait and let the oncoming car pass first","Flash your lights and turn"],"h1":"A green light lets you go, but it does not clear the road in front of you.","h2":"When you turn left, you must yield to oncoming traffic, so you wait until the car passes and the way is clear.","p":"Right. When turning left, let oncoming traffic go first."},"es":{"q":"En Florida, usted quiere doblar a la izquierda con luz verde. Viene un carro de frente. ¿Qué hace?","o":["Dobla rápido antes de que se acerque","Dobla, porque la luz verde le da el derecho de paso","Espera y deja pasar primero al carro que viene de frente","Hace cambio de luces y dobla"],"h1":"La luz verde le permite seguir, pero no despeja la calle delante de usted.","h2":"Cuando usted dobla a la izquierda, debe ceder el paso al tráfico que viene de frente, así que espera hasta que el carro pase y el camino esté libre.","p":"Correcto. Al doblar a la izquierda, deje pasar primero al tráfico de frente."},"zh":{"q":"在 Florida，绿灯时你想左转。对面有一辆车开过来。你该怎么做？","o":["趁它还没靠近，赶快转","转弯，因为绿灯给你先行权","等一等，让对面的车先过去","闪一下车灯，然后转弯"],"h1":"绿灯让你可以走，但不代表你前面的路是空的。","h2":"左转时，你必须让对面来的车先走，所以要等那辆车过去、路上安全了再转。","p":"对。左转时，让对面来的车先走。"},"vi":{"q":"Ở Florida, bạn muốn rẽ trái khi đèn xanh. Có một xe đang chạy ngược chiều về phía bạn. Bạn làm gì?","o":["Rẽ nhanh trước khi xe đó đến gần","Rẽ, vì đèn xanh cho bạn quyền ưu tiên","Chờ và để xe ngược chiều đi qua trước","Nháy đèn rồi rẽ"],"h1":"Đèn xanh cho phép bạn đi, nhưng không làm đường phía trước trống.","h2":"Khi rẽ trái, bạn phải nhường xe đi ngược chiều, nên bạn chờ xe đó đi qua và đường trống rồi mới rẽ.","p":"Đúng. Khi rẽ trái, hãy để xe ngược chiều đi trước."},"tl":{"q":"Sa Florida, gusto mong kumaliwa sa berdeng ilaw. May kotseng paparating mula sa harap mo. Ano ang gagawin mo?","o":["Kumaliwa agad bago ito makalapit","Kumaliwa, dahil binibigyan ka ng berdeng ilaw ng karapatan sa daan","Maghintay at paunahin ang paparating na kotse","Mag-flash ng ilaw at kumaliwa"],"h1":"Pinapayagan kang umandar ng berdeng ilaw, pero hindi nito nililinis ang daan sa harap mo.","h2":"Kapag kumakaliwa ka, dapat kang magbigay-daan sa paparating na trapiko, kaya maghihintay ka hanggang makalampas ang kotse at malinis ang daan.","p":"Tama. Kapag kumakaliwa, paunahin ang paparating na trapiko."},"ar":{"q":"في Florida، تريد أن تنعطف يسارًا والإشارة خضراء. هناك سيارة قادمة نحوك. ماذا تفعل؟","o":["أنعطف بسرعة قبل أن تقترب","أنعطف، لأن الإشارة الخضراء تعطيني حق المرور","أنتظر وأترك السيارة القادمة تمر أولًا","أومض بالأضواء وأنعطف"],"h1":"الإشارة الخضراء تسمح لك بالتحرك، لكنها لا تجعل الطريق أمامك فارغًا.","h2":"عندما تنعطف يسارًا، يجب أن تعطي حق المرور للسيارات القادمة نحوك، لذلك تنتظر حتى تمر السيارة ويصبح الطريق فارغًا.","p":"صحيح. عند الانعطاف يسارًا، اترك السيارات القادمة نحوك تمر أولًا."},"ht":{"q":"Nan Florida, ou vle vire agòch lè limyè a vèt. Gen yon machin k ap vin sou ou. Kisa ou fè?","o":["Ou vire vit anvan li rive pre","Ou vire, paske limyè vèt la ba ou dwa pou pase anvan","Ou tann epi ou kite machin k ap vin sou ou a pase anvan","Ou flache limyè ou epi ou vire"],"h1":"Yon limyè vèt kite ou ale, men li pa libere wout ki devan ou a.","h2":"Lè w ap vire agòch, ou dwe kite machin k ap vin sou ou yo pase anvan, kidonk ou tann machin nan pase epi wout la lib.","p":"Wi, se sa. Lè w ap vire agòch, kite machin k ap vin sou ou yo pase anvan."},"ref":{"doc":"FL","page":62}},{"id":"right-of-way-007","scope":"FL","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Florida, you are pulling out of a driveway onto a street. Who must you yield to?","o":["Only to large trucks","No one, if you use your signal","Only to cars on your left","All cars on the street and all people walking"],"h1":"You are joining a road that others are already using.","h2":"When you enter a street from a driveway or alley, you must yield to every vehicle on the street and to every pedestrian.","p":"Right. Coming out of a driveway, yield to cars and people walking."},"es":{"q":"En Florida, usted sale de una entrada de casa hacia la calle. ¿A quién debe ceder el paso?","o":["Solo a los camiones grandes","A nadie, si usa la direccional","Solo a los carros de su izquierda","A todos los carros de la calle y a todas las personas que caminan"],"h1":"Usted entra a una calle que otros ya están usando.","h2":"Cuando usted entra a una calle desde una entrada de casa o un callejón, debe ceder el paso a todos los vehículos de la calle y a todos los peatones.","p":"Correcto. Al salir de una entrada de casa, ceda el paso a carros y peatones."},"zh":{"q":"在 Florida，你正从私人车道开上街道。你必须给谁让行？","o":["只给大卡车","谁都不用，只要你打了转向灯","只给你左边的车","街上所有的车和所有走路的人"],"h1":"你要开上一条别人已经在用的路。","h2":"从私人车道或小巷开上街道时，你必须让街上的每一辆车和每一个行人先走。","p":"对。从私人车道出来时，要让车和行人先走。"},"vi":{"q":"Ở Florida, bạn đang lái xe từ lối vào nhà ra đường. Bạn phải nhường ai?","o":["Chỉ nhường xe tải lớn","Không ai cả, nếu bạn bật đèn xi nhan","Chỉ nhường xe bên trái","Mọi xe trên đường và mọi người đi bộ"],"h1":"Bạn đang đi vào con đường mà người khác đang dùng.","h2":"Khi bạn từ lối vào nhà hoặc hẻm đi ra đường, bạn phải nhường mọi xe trên đường và mọi người đi bộ.","p":"Đúng. Khi ra từ lối vào nhà, hãy nhường xe và người đi bộ."},"tl":{"q":"Sa Florida, lalabas ka mula sa driveway papunta sa kalye. Kanino ka dapat magbigay-daan?","o":["Sa malalaking trak lang","Wala, kung gagamit ka ng signal","Sa mga kotse lang sa kaliwa mo","Sa lahat ng kotse sa kalye at sa lahat ng taong naglalakad"],"h1":"Papasok ka sa daan na ginagamit na ng iba.","h2":"Kapag pumapasok ka sa kalye mula sa driveway o eskinita, dapat kang magbigay-daan sa bawat sasakyan sa kalye at sa bawat taong naglalakad.","p":"Tama. Paglabas sa driveway, magbigay-daan sa mga kotse at sa mga naglalakad."},"ar":{"q":"في Florida، تخرج بسيارتك من ممر خاص إلى الشارع. لمن يجب أن تعطي حق المرور؟","o":["للشاحنات الكبيرة فقط","لا أحد، إذا استعملت إشارة الانعطاف","للسيارات التي على يساري فقط","لكل السيارات في الشارع ولكل المشاة"],"h1":"أنت تدخل طريقًا يستعمله آخرون الآن.","h2":"عندما تدخل الشارع من ممر خاص أو من زقاق، يجب أن تعطي حق المرور لكل مركبة في الشارع ولكل شخص يمشي.","p":"صحيح. عند الخروج من ممر خاص، أعطِ حق المرور للسيارات وللمشاة."},"ht":{"q":"Nan Florida, w ap sòti nan antre yon kay pou antre nan yon lari. Kiyès ou dwe kite pase anvan?","o":["Sèlman gwo kamyon","Pèsonn, si ou mete siyal ou","Sèlman machin ki sou bò gòch ou","Tout machin ki nan lari a ak tout moun k ap mache a pye"],"h1":"W ap antre sou yon wout lòt moun deja ap sèvi.","h2":"Lè w ap antre nan yon lari sòti nan antre yon kay oswa nan yon ti ri, ou dwe kite tout machin ki nan lari a ak tout moun k ap mache a pye pase anvan.","p":"Wi, se sa. Lè w ap sòti nan antre yon kay, kite machin yo ak moun k ap mache yo pase anvan."},"ref":{"doc":"FL","page":62}},{"id":"right-of-way-008","scope":"FL","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Florida, you drive out of an alley. There is a sidewalk before the street. Where must you stop?","o":["Before you cross the sidewalk","In the middle of the sidewalk","At the edge of the street, past the sidewalk","You do not need to stop"],"h1":"Think about people who may be walking on the sidewalk.","h2":"When you come out of an alley or driveway, you must stop before the sidewalk, so you do not hit someone walking there.","p":"Right. Stop before the sidewalk when you leave an alley or driveway."},"es":{"q":"En Florida, usted sale de un callejón. Hay una acera antes de la calle. ¿Dónde debe parar?","o":["Antes de cruzar la acera","En medio de la acera","En el borde de la calle, después de la acera","No necesita parar"],"h1":"Piense en las personas que pueden ir caminando por la acera.","h2":"Cuando usted sale de un callejón o de una entrada de casa, debe parar antes de la acera, para no golpear a alguien que camina por ahí.","p":"Correcto. Pare antes de la acera al salir de un callejón o entrada."},"zh":{"q":"在 Florida，你从小巷开出来。到街道前有一段人行道。你必须在哪里停车？","o":["在穿过人行道之前","在人行道中间","在街道边上，过了人行道以后","你不需要停车"],"h1":"想一想可能正在人行道上走路的人。","h2":"从小巷或私人车道开出来时，你必须在人行道前停车，这样才不会撞到在那里走路的人。","p":"对。离开小巷或私人车道时，要在人行道前停车。"},"vi":{"q":"Ở Florida, bạn lái xe ra khỏi một con hẻm. Trước đường có vỉa hè. Bạn phải dừng ở đâu?","o":["Trước khi đi qua vỉa hè","Ở giữa vỉa hè","Ở mép đường, sau vỉa hè","Bạn không cần dừng"],"h1":"Hãy nghĩ đến những người có thể đang đi trên vỉa hè.","h2":"Khi ra khỏi hẻm hoặc lối vào nhà, bạn phải dừng trước vỉa hè, để không đụng vào người đang đi bộ ở đó.","p":"Đúng. Hãy dừng trước vỉa hè khi ra khỏi hẻm hoặc lối vào nhà."},"tl":{"q":"Sa Florida, lumabas ka mula sa eskinita. May bangketa bago ang kalye. Saan ka dapat huminto?","o":["Bago ka tumawid sa bangketa","Sa gitna ng bangketa","Sa gilid ng kalye, lampas sa bangketa","Hindi mo kailangang huminto"],"h1":"Isipin ang mga taong maaaring naglalakad sa bangketa.","h2":"Kapag lumalabas ka mula sa eskinita o driveway, dapat kang huminto bago ang bangketa, para hindi ka makabangga ng taong naglalakad doon.","p":"Tama. Huminto bago ang bangketa kapag lumalabas sa eskinita o driveway."},"ar":{"q":"في Florida، تخرج بسيارتك من زقاق. يوجد رصيف قبل الشارع. أين يجب أن تتوقف؟","o":["قبل أن أعبر الرصيف","في وسط الرصيف","عند طرف الشارع، بعد الرصيف","لا أحتاج إلى التوقف"],"h1":"فكّر في الناس الذين قد يمشون على الرصيف.","h2":"عندما تخرج من زقاق أو ممر خاص، يجب أن تتوقف قبل الرصيف، حتى لا تصدم شخصًا يمشي هناك.","p":"صحيح. توقف قبل الرصيف عندما تخرج من زقاق أو ممر خاص."},"ht":{"q":"Nan Florida, w ap sòti nan yon ti ri. Gen yon twotwa anvan lari a. Ki kote ou dwe kanpe?","o":["Anvan ou travèse twotwa a","Nan mitan twotwa a","Bò lari a, apre twotwa a","Ou pa bezwen kanpe"],"h1":"Panse ak moun ki ka ap mache sou twotwa a.","h2":"Lè w ap sòti nan yon ti ri oswa nan antre yon kay, ou dwe kanpe anvan twotwa a, pou ou pa frape yon moun k ap mache la.","p":"Wi, se sa. Kanpe anvan twotwa a lè w ap sòti nan yon ti ri oswa nan antre yon kay."},"ref":{"doc":"FL","page":62}},{"id":"right-of-way-009","scope":"FL","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Florida, a person is crossing at a corner with no painted crosswalk lines. Must you yield?","o":["No, only painted crosswalks count","Yes, the corner of an intersection is a crosswalk even without lines","Only if the person is a child","Only if a police officer is there"],"h1":"A crosswalk does not always have paint.","h2":"Every corner of an intersection has a crosswalk even when no lines are painted, so you must yield to the person crossing.","p":"Right. Yield to people crossing at a corner, with or without lines."},"es":{"q":"En Florida, una persona cruza en una esquina sin líneas pintadas de cruce peatonal. ¿Debe usted ceder el paso?","o":["No, solo cuentan los cruces pintados","Sí, la esquina de una intersección es un cruce peatonal aunque no tenga líneas","Solo si la persona es un niño","Solo si hay un policía"],"h1":"Un cruce peatonal no siempre tiene pintura.","h2":"Cada esquina de una intersección tiene un cruce peatonal aunque no tenga líneas pintadas, así que usted debe ceder el paso a la persona que cruza.","p":"Correcto. Ceda el paso a quien cruza en la esquina, con o sin líneas."},"zh":{"q":"在 Florida，有人在一个没有画人行横道线的路口拐角过马路。你必须让行吗？","o":["不用，只有画了线的人行横道才算","要，路口的拐角就算没有画线，也是人行横道","只有过马路的是小孩时才要","只有警察在场时才要"],"h1":"人行横道不一定都画了线。","h2":"路口的每个拐角都有人行横道，就算没有画线也一样，所以你必须让过马路的人先走。","p":"对。不管有没有画线，都要让在拐角过马路的人先走。"},"vi":{"q":"Ở Florida, một người đang băng qua đường ở góc giao lộ không có vạch kẻ cho người đi bộ. Bạn có phải nhường không?","o":["Không, chỉ chỗ có vạch kẻ mới tính","Có, góc giao lộ là lối qua đường dù không có vạch kẻ","Chỉ khi người đó là trẻ em","Chỉ khi có cảnh sát ở đó"],"h1":"Lối qua đường cho người đi bộ không phải lúc nào cũng có sơn.","h2":"Mỗi góc của giao lộ đều có lối qua đường dù không có vạch sơn, nên bạn phải nhường người đang băng qua.","p":"Đúng. Hãy nhường người băng qua ở góc giao lộ, có vạch hay không có vạch."},"tl":{"q":"Sa Florida, may taong tumatawid sa kanto na walang pinturang guhit ng crosswalk. Dapat ka bang magbigay-daan?","o":["Hindi, ang may pinturang crosswalk lang ang binibilang","Oo, ang kanto ng intersection ay crosswalk kahit walang guhit","Kung bata lang ang tao","Kung may pulis lang doon"],"h1":"Hindi laging may pintura ang crosswalk.","h2":"Bawat kanto ng intersection ay may crosswalk kahit walang pinturang guhit, kaya dapat kang magbigay-daan sa taong tumatawid.","p":"Tama. Magbigay-daan sa mga tumatawid sa kanto, may guhit man o wala."},"ar":{"q":"في Florida، شخص يعبر الشارع عند زاوية تقاطع ليس فيها خطوط ممر مشاة مرسومة. هل يجب أن تعطيه حق المرور؟","o":["لا، ممرات المشاة المرسومة فقط هي المهمة","نعم، زاوية التقاطع هي ممر مشاة حتى بدون خطوط","فقط إذا كان الشخص طفلًا","فقط إذا كان هناك شرطي"],"h1":"ممر المشاة ليس مرسومًا دائمًا.","h2":"عند كل زاوية من زوايا التقاطع يوجد ممر مشاة حتى لو لم تكن هناك خطوط مرسومة، لذلك يجب أن تعطي حق المرور للشخص الذي يعبر.","p":"صحيح. أعطِ حق المرور للناس الذين يعبرون عند الزاوية، مع خطوط أو بدونها."},"ht":{"q":"Nan Florida, yon moun ap travèse nan kwen yon kafou ki pa gen liy pasaj pyeton ki pentire. Èske ou dwe kite l pase?","o":["Non, se sèlman pasaj pyeton ki pentire ki konte","Wi, kwen yon kafou se yon pasaj pyeton menm si li pa gen liy","Sèlman si moun nan se yon timoun","Sèlman si gen yon polis la"],"h1":"Yon pasaj pyeton pa toujou gen penti.","h2":"Chak kwen yon kafou gen yon pasaj pyeton menm lè pa gen liy ki pentire, kidonk ou dwe kite moun k ap travèse a pase.","p":"Wi, se sa. Kite moun k ap travèse nan kwen kafou a pase, kit gen liy kit pa gen liy."},"ref":{"doc":"FL","page":87}},{"id":"right-of-way-010","scope":"FL","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Florida, you turn right on a green light. People are crossing the street you are turning into. What do you do?","o":["Drive slowly between them","Honk so they move faster","Stop and let them finish crossing","Turn, because your light is green"],"h1":"Your path crosses their path.","h2":"When you turn, you must yield to people walking in the crosswalk, so you stop and wait until they are out of your way.","p":"Right. When you turn, let people in the crosswalk cross first."},"es":{"q":"En Florida, usted dobla a la derecha con luz verde. Hay personas cruzando la calle a la que usted va a entrar. ¿Qué hace?","o":["Pasa despacio entre ellas","Toca la bocina para que caminen más rápido","Para y las deja terminar de cruzar","Dobla, porque su luz está en verde"],"h1":"Su camino se cruza con el camino de ellas.","h2":"Cuando usted dobla, debe ceder el paso a las personas que caminan en el cruce peatonal, así que para y espera hasta que salgan de su camino.","p":"Correcto. Al doblar, deje cruzar primero a las personas en el cruce peatonal."},"zh":{"q":"在 Florida，你在绿灯时右转。有人正在过你要转进去的那条街。你该怎么做？","o":["从他们中间慢慢开过去","按喇叭让他们走快一点","停车，让他们走完","转弯，因为你是绿灯"],"h1":"你的路线和他们的路线交叉。","h2":"转弯时，你必须让人行横道上的行人先走，所以你要停下来，等他们离开你的路线。","p":"对。转弯时，让人行横道上的人先过。"},"vi":{"q":"Ở Florida, bạn rẽ phải khi đèn xanh. Có người đang băng qua con đường bạn sắp rẽ vào. Bạn làm gì?","o":["Lái chậm len giữa họ","Bấm còi để họ đi nhanh hơn","Dừng lại và để họ qua hết đường","Rẽ, vì đèn của bạn là đèn xanh"],"h1":"Đường đi của bạn cắt ngang đường đi của họ.","h2":"Khi rẽ, bạn phải nhường người đi bộ trên lối qua đường, nên bạn dừng lại và chờ đến khi họ đi khỏi đường của bạn.","p":"Đúng. Khi rẽ, hãy để người trên lối qua đường đi trước."},"tl":{"q":"Sa Florida, kumanan ka sa berdeng ilaw. May mga taong tumatawid sa kalyeng papasukan mo. Ano ang gagawin mo?","o":["Dahan-dahang dumaan sa pagitan nila","Bumusina para bumilis sila","Huminto at hayaan silang matapos tumawid","Kumanan, dahil berde ang ilaw mo"],"h1":"Nagtatagpo ang daan mo at ang daan nila.","h2":"Kapag lumiliko ka, dapat kang magbigay-daan sa mga taong naglalakad sa crosswalk, kaya hihinto ka at maghihintay hanggang wala na sila sa daan mo.","p":"Tama. Kapag lumiliko, paunahing tumawid ang mga tao sa crosswalk."},"ar":{"q":"في Florida، تنعطف يمينًا والإشارة خضراء. هناك أشخاص يعبرون الشارع الذي تدخل إليه. ماذا تفعل؟","o":["أقود ببطء بينهم","أستعمل البوق ليسرعوا","أتوقف وأتركهم ينهون العبور","أنعطف، لأن الإشارة عندي خضراء"],"h1":"طريقك يقطع طريقهم.","h2":"عندما تنعطف، يجب أن تعطي حق المرور للمشاة في ممر المشاة، لذلك تتوقف وتنتظر حتى يبتعدوا عن طريقك.","p":"صحيح. عندما تنعطف، اترك الناس في ممر المشاة يعبرون أولًا."},"ht":{"q":"Nan Florida, ou vire adwat lè limyè a vèt. Gen moun k ap travèse lari kote w ap vire a. Kisa ou fè?","o":["Ou kondi dousman nan mitan yo","Ou klaksonnen pou yo mache pi vit","Ou kanpe epi ou kite yo fin travèse","Ou vire, paske limyè ou a vèt"],"h1":"Chemen pa w la kwaze chemen pa yo a.","h2":"Lè w ap vire, ou dwe kite moun k ap mache nan pasaj pyeton an pase anvan, kidonk ou kanpe epi ou tann yo sòti nan chemen ou.","p":"Wi, se sa. Lè w ap vire, kite moun ki nan pasaj pyeton an travèse anvan."},"ref":{"doc":"FL","page":87}},{"id":"right-of-way-011","scope":"FL","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Florida, a person with a white cane or a guide dog is crossing the street. What must you do?","o":["Honk to let the person know you are there","Drive around the person carefully","Go if your light is green","Stop and let the person cross"],"h1":"A white cane or guide dog tells you the person may not be able to see you.","h2":"A person who is blind and uses a white cane or a guide dog always has the right of way, so you must stop and let them cross.","p":"Right. Always stop for a person with a white cane or guide dog."},"es":{"q":"En Florida, una persona con bastón blanco o con perro guía está cruzando la calle. ¿Qué debe hacer usted?","o":["Tocar la bocina para avisar que usted está ahí","Pasar alrededor de la persona con cuidado","Seguir si su luz está en verde","Parar y dejar que la persona cruce"],"h1":"Un bastón blanco o un perro guía le indican que la persona tal vez no puede verlo.","h2":"Una persona ciega que usa bastón blanco o perro guía siempre tiene el derecho de paso, así que usted debe parar y dejarla cruzar.","p":"Correcto. Siempre pare por una persona con bastón blanco o perro guía."},"zh":{"q":"在 Florida，有一个拿白色手杖或带导盲犬的人正在过马路。你必须怎么做？","o":["按喇叭，让这个人知道你在那里","小心地绕过这个人","如果你是绿灯，就开过去","停车，让这个人过马路"],"h1":"白色手杖或导盲犬告诉你，这个人可能看不见你。","h2":"使用白色手杖或导盲犬的盲人永远有先行权，所以你必须停车，让他们过马路。","p":"对。看到拿白色手杖或带导盲犬的人，一定要停车。"},"vi":{"q":"Ở Florida, một người cầm gậy trắng hoặc có chó dẫn đường đang băng qua đường. Bạn phải làm gì?","o":["Bấm còi để người đó biết bạn ở đó","Lái vòng qua người đó một cách cẩn thận","Đi tiếp nếu đèn của bạn là đèn xanh","Dừng lại và để người đó băng qua"],"h1":"Gậy trắng hoặc chó dẫn đường cho bạn biết người đó có thể không nhìn thấy bạn.","h2":"Người khiếm thị dùng gậy trắng hoặc chó dẫn đường luôn có quyền ưu tiên, nên bạn phải dừng lại và để họ băng qua.","p":"Đúng. Luôn dừng lại cho người cầm gậy trắng hoặc có chó dẫn đường."},"tl":{"q":"Sa Florida, may taong may puting tungkod o guide dog na tumatawid sa kalye. Ano ang dapat mong gawin?","o":["Bumusina para malaman niyang nandiyan ka","Maingat na umiwas sa paligid niya","Umandar kung berde ang ilaw mo","Huminto at hayaan siyang tumawid"],"h1":"Ang puting tungkod o guide dog ay nagsasabing maaaring hindi ka nakikita ng tao.","h2":"Ang taong bulag na gumagamit ng puting tungkod o guide dog ay laging may karapatan sa daan, kaya dapat kang huminto at hayaan siyang tumawid.","p":"Tama. Laging huminto para sa taong may puting tungkod o guide dog."},"ar":{"q":"في Florida، شخص معه عصا بيضاء أو كلب مرشد يعبر الشارع. ماذا يجب أن تفعل؟","o":["أستعمل البوق حتى يعرف أنني هنا","أقود حوله بحذر","أتحرك إذا كانت الإشارة عندي خضراء","أتوقف وأترك الشخص يعبر"],"h1":"العصا البيضاء أو الكلب المرشد يخبرك أن الشخص قد لا يستطيع أن يراك.","h2":"الشخص الكفيف الذي يستعمل عصا بيضاء أو كلبًا مرشدًا له حق المرور دائمًا، لذلك يجب أن تتوقف وتتركه يعبر.","p":"صحيح. توقف دائمًا لشخص معه عصا بيضاء أو كلب مرشد."},"ht":{"q":"Nan Florida, yon moun ki gen yon baton blan oswa yon chen gid ap travèse lari a. Kisa ou dwe fè?","o":["Ou klaksonnen pou moun nan konnen ou la","Ou fè yon ti detou dousman bò kote moun nan","Ou pase si limyè ou a vèt","Ou kanpe epi ou kite moun nan travèse"],"h1":"Yon baton blan oswa yon chen gid montre ou moun nan ka pa ka wè ou.","h2":"Yon moun ki avèg epi ki sèvi ak yon baton blan oswa yon chen gid toujou gen dwa pou pase anvan, kidonk ou dwe kanpe epi kite l travèse.","p":"Wi, se sa. Toujou kanpe pou yon moun ki gen yon baton blan oswa yon chen gid."},"ref":{"doc":"FL","page":88}},{"id":"right-of-way-012","scope":"FL","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Florida, you are about to enter a roundabout. Who has the right of way?","o":["Traffic already moving inside the roundabout","You, because you are entering","The car on your right that is also entering","The driver who honks first"],"h1":"Think about who is already driving in the circle.","h2":"When you enter a roundabout, you must yield to traffic that is already in the circle, then enter when there is a safe gap.","p":"Right. Yield to cars already in the roundabout."},"es":{"q":"En Florida, usted va a entrar a una rotonda. ¿Quién tiene el derecho de paso?","o":["El tráfico que ya va dentro de la rotonda","Usted, porque está entrando","El carro de su derecha que también está entrando","El conductor que toca la bocina primero"],"h1":"Piense en quién ya va manejando dentro del círculo.","h2":"Cuando usted entra a una rotonda, debe ceder el paso al tráfico que ya está en el círculo, y luego entrar cuando haya un espacio seguro.","p":"Correcto. Ceda el paso a los carros que ya están en la rotonda."},"zh":{"q":"在 Florida，你马上要进入环岛。谁有先行权？","o":["已经在环岛里行驶的车","你，因为你正在进入","你右边也正在进入的车","先按喇叭的司机"],"h1":"想一想谁已经在环岛里开车。","h2":"进入环岛时，你必须让已经在环岛里的车先走，等有安全的空隙再进去。","p":"对。让已经在环岛里的车先走。"},"vi":{"q":"Ở Florida, bạn sắp đi vào vòng xuyến. Ai có quyền ưu tiên?","o":["Xe đang chạy bên trong vòng xuyến","Bạn, vì bạn đang đi vào","Xe bên phải bạn cũng đang đi vào","Người lái bấm còi trước"],"h1":"Hãy nghĩ xem ai đang chạy trong vòng xuyến rồi.","h2":"Khi đi vào vòng xuyến, bạn phải nhường xe đã ở trong vòng xuyến, rồi đi vào khi có khoảng trống an toàn.","p":"Đúng. Hãy nhường xe đã ở trong vòng xuyến."},"tl":{"q":"Sa Florida, papasok ka na sa roundabout. Sino ang may karapatan sa daan?","o":["Ang trapikong umaandar na sa loob ng roundabout","Ikaw, dahil papasok ka","Ang kotse sa kanan mo na papasok din","Ang drayber na unang bumusina"],"h1":"Isipin kung sino na ang nagmamaneho sa loob ng bilog.","h2":"Kapag pumapasok ka sa roundabout, dapat kang magbigay-daan sa trapikong nasa loob na ng bilog, at pumasok kapag may ligtas na puwang.","p":"Tama. Magbigay-daan sa mga kotseng nasa loob na ng roundabout."},"ar":{"q":"في Florida، أنت على وشك أن تدخل دوّارًا. من له حق المرور؟","o":["السيارات التي تسير الآن داخل الدوّار","أنت، لأنك تدخل","السيارة التي على يمينك وتدخل أيضًا","السائق الذي يستعمل البوق أولًا"],"h1":"فكّر في من يقود الآن داخل الدائرة.","h2":"عندما تدخل دوّارًا، يجب أن تعطي حق المرور للسيارات الموجودة داخل الدائرة، ثم تدخل عندما توجد مسافة آمنة.","p":"صحيح. أعطِ حق المرور للسيارات الموجودة داخل الدوّار."},"ht":{"q":"Nan Florida, ou pral antre nan yon wonpwen. Kiyès ki gen dwa pou pase anvan?","o":["Machin ki deja ap woule anndan wonpwen an","Ou menm, paske w ap antre","Machin ki sou bò dwat ou ki ap antre tou a","Chofè ki klaksonnen an premye a"],"h1":"Panse ak kiyès ki deja ap kondi nan wonn nan.","h2":"Lè w ap antre nan yon wonpwen, ou dwe kite machin ki deja nan wonn nan pase anvan, epi ou antre lè gen yon espas ki san danje.","p":"Wi, se sa. Kite machin ki deja nan wonpwen an pase anvan."},"ref":{"doc":"FL","page":63}},{"id":"right-of-way-013","scope":"US","cat":"right-of-way","sign":null,"c":1,"en":{"q":"Which way do cars travel in a roundabout in the United States?","o":["Clockwise, to the left","Counterclockwise, to the right","Either way the driver picks","Straight across the middle"],"h1":"In the United States, you drive on the right side of the road.","h2":"In a roundabout in the United States, you enter to the right and travel counterclockwise around the center.","p":"Right. In a roundabout, go to the right, counterclockwise."},"es":{"q":"¿Hacia qué lado van los carros en una rotonda en los Estados Unidos?","o":["En el sentido del reloj, hacia la izquierda","En contra del reloj, hacia la derecha","Hacia el lado que el conductor escoja","Derecho por el centro"],"h1":"En los Estados Unidos se maneja por el lado derecho de la calle.","h2":"En una rotonda en los Estados Unidos, usted entra hacia la derecha y da la vuelta en contra del sentido del reloj alrededor del centro.","p":"Correcto. En una rotonda, vaya hacia la derecha, en contra del reloj."},"zh":{"q":"在美国，车在环岛里朝哪个方向行驶？","o":["顺时针，向左","逆时针，向右","司机想走哪边都行","从中间直接穿过去"],"h1":"在美国，车靠道路右边行驶。","h2":"在美国的环岛里，你向右进入，然后绕着中心逆时针行驶。","p":"对。在环岛里，向右走，逆时针方向。"},"vi":{"q":"Ở Hoa Kỳ, xe chạy theo chiều nào trong vòng xuyến?","o":["Theo chiều kim đồng hồ, sang trái","Ngược chiều kim đồng hồ, sang phải","Theo chiều nào người lái chọn cũng được","Đi thẳng qua giữa"],"h1":"Ở Hoa Kỳ, bạn lái xe bên phải đường.","h2":"Trong vòng xuyến ở Hoa Kỳ, bạn đi vào về phía bên phải và chạy ngược chiều kim đồng hồ quanh tâm.","p":"Đúng. Trong vòng xuyến, đi sang phải, ngược chiều kim đồng hồ."},"tl":{"q":"Saang direksiyon umiikot ang mga kotse sa roundabout sa United States?","o":["Kasunod ng ikot ng orasan (clockwise), papuntang kaliwa","Salungat sa ikot ng orasan (counterclockwise), papuntang kanan","Kahit saan, depende sa drayber","Diretso sa gitna"],"h1":"Sa United States, sa kanang bahagi ng daan ka nagmamaneho.","h2":"Sa roundabout sa United States, papasok ka pakanan at iikot nang salungat sa ikot ng orasan (counterclockwise) sa paligid ng gitna.","p":"Tama. Sa roundabout, pumunta pakanan, salungat sa ikot ng orasan."},"ar":{"q":"في أي اتجاه تسير السيارات داخل الدوّار في الولايات المتحدة؟","o":["مع عقارب الساعة، إلى اليسار","عكس عقارب الساعة، إلى اليمين","في أي اتجاه يختاره السائق","مباشرة عبر الوسط"],"h1":"في الولايات المتحدة، تقود على الجانب الأيمن من الطريق.","h2":"في الدوّار في الولايات المتحدة، تدخل إلى اليمين وتسير عكس عقارب الساعة حول الوسط.","p":"صحيح. في الدوّار، اذهب إلى اليمين، عكس عقارب الساعة."},"ht":{"q":"Nan Etazini, nan ki direksyon machin yo woule nan yon wonpwen?","o":["Nan direksyon zegwi mont, sou bò gòch","Kont direksyon zegwi mont, sou bò dwat","Nan direksyon chofè a chwazi a","Tou dwat nan mitan an"],"h1":"Nan Etazini, ou kondi sou bò dwat wout la.","h2":"Nan yon wonpwen nan Etazini, ou antre sou bò dwat epi ou woule kont direksyon zegwi mont toutotou mitan an.","p":"Wi, se sa. Nan yon wonpwen, ale sou bò dwat, kont direksyon zegwi mont."},"ref":{"doc":"FL","page":63}},{"id":"right-of-way-014","scope":"FL","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Florida, an ambulance with a siren and flashing lights is coming behind you. What do you do?","o":["Speed up to stay ahead of it","Stop right where you are, in your lane","Pull to the nearest edge of the road and stop","Move to the left lane and keep driving"],"h1":"The ambulance needs a clear path. Think about where you can get out of its way.","h2":"When an emergency vehicle comes with a siren and flashing lights, you pull to the nearest edge of the road and stop until it passes.","p":"Right. Pull to the nearest edge and stop for emergency vehicles."},"es":{"q":"En Florida, una ambulancia con sirena y luces intermitentes viene detrás de usted. ¿Qué hace?","o":["Acelera para mantenerse delante","Para donde está, en su carril","Se orilla al borde más cercano de la calle y para","Se pasa al carril izquierdo y sigue manejando"],"h1":"La ambulancia necesita el camino libre. Piense dónde puede quitarse de su camino.","h2":"Cuando viene un vehículo de emergencia con sirena y luces intermitentes, usted se orilla al borde más cercano de la calle y para hasta que pase.","p":"Correcto. Oríllese al borde más cercano y pare para los vehículos de emergencia."},"zh":{"q":"在 Florida，一辆鸣着警笛、闪着灯的救护车从你后面开过来。你该怎么做？","o":["加速，保持在它前面","就在你的车道里原地停下","靠到离你最近的路边，然后停车","换到左边车道，继续开"],"h1":"救护车需要一条畅通的路。想一想你可以躲到哪里。","h2":"当急救车辆鸣着警笛、闪着灯开过来时，你要靠到最近的路边停车，等它过去。","p":"对。遇到急救车辆，靠到最近的路边停车。"},"vi":{"q":"Ở Florida, một xe cứu thương hú còi và nháy đèn đang đến từ phía sau bạn. Bạn làm gì?","o":["Tăng tốc để chạy trước xe đó","Dừng ngay tại chỗ, trong làn của bạn","Tấp vào mép đường gần nhất và dừng lại","Chuyển sang làn trái và tiếp tục chạy"],"h1":"Xe cứu thương cần đường trống. Hãy nghĩ xem bạn có thể tránh ra ở đâu.","h2":"Khi xe khẩn cấp đến với còi hú và đèn nháy, bạn tấp vào mép đường gần nhất và dừng lại cho đến khi xe đó đi qua.","p":"Đúng. Hãy tấp vào mép đường gần nhất và dừng lại cho xe khẩn cấp."},"tl":{"q":"Sa Florida, may ambulansiyang may sirena at kumikislap na ilaw na paparating sa likod mo. Ano ang gagawin mo?","o":["Bumilis para manatiling nauuna rito","Huminto kung nasaan ka, sa lane mo","Tumabi sa pinakamalapit na gilid ng daan at huminto","Lumipat sa kaliwang lane at magpatuloy"],"h1":"Kailangan ng ambulansiya ng malinis na daan. Isipin kung saan ka puwedeng umiwas.","h2":"Kapag may emergency vehicle na may sirena at kumikislap na ilaw, tatabi ka sa pinakamalapit na gilid ng daan at hihinto hanggang makalampas ito.","p":"Tama. Tumabi sa pinakamalapit na gilid at huminto para sa mga emergency vehicle."},"ar":{"q":"في Florida، سيارة إسعاف بصفارة وأضواء وامضة تأتي خلفك. ماذا تفعل؟","o":["أسرع لأبقى أمامها","أتوقف في مكاني، داخل مساري","أتحرك إلى أقرب طرف للطريق وأتوقف","أنتقل إلى المسار الأيسر وأستمر في القيادة"],"h1":"سيارة الإسعاف تحتاج إلى طريق فارغ. فكّر أين يمكنك أن تبتعد عن طريقها.","h2":"عندما تأتي مركبة طوارئ بصفارة وأضواء وامضة، تتحرك إلى أقرب طرف للطريق وتتوقف حتى تمر.","p":"صحيح. تحرك إلى أقرب طرف وتوقف لمركبات الطوارئ."},"ht":{"q":"Nan Florida, yon anbilans ki gen siren ak limyè k ap flache ap vini dèyè ou. Kisa ou fè?","o":["Ou akselere pou rete devan l","Ou kanpe la menm, nan liy ou a","Ou rale sou bò wout ki pi pre a epi ou kanpe","Ou ale nan liy gòch la epi ou kontinye kondi"],"h1":"Anbilans lan bezwen yon chemen ki lib. Panse ak ki kote ou ka sòti nan chemen l.","h2":"Lè yon machin ijans vini ak siren ak limyè k ap flache, ou rale sou bò wout ki pi pre a epi ou kanpe jiskaske li pase.","p":"Wi, se sa. Rale sou bò wout ki pi pre a epi kanpe pou machin ijans yo."},"ref":{"doc":"FL","page":84}},{"id":"right-of-way-015","scope":"FL","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Florida, you are in the middle of an intersection when you hear a fire truck siren behind you. What do you do?","o":["Drive through the intersection, then pull to the nearest edge and stop","Stop in the middle of the intersection","Back up out of the intersection","Turn left right away"],"h1":"Stopping inside the intersection can block the fire truck.","h2":"If you are already in an intersection, you keep going through it and then pull to the nearest edge and stop, so you do not block the emergency vehicle.","p":"Right. Clear the intersection first, then pull over and stop."},"es":{"q":"En Florida, usted está en medio de una intersección cuando oye la sirena de un camión de bomberos detrás. ¿Qué hace?","o":["Cruza la intersección y luego se orilla al borde más cercano y para","Para en medio de la intersección","Da reversa para salir de la intersección","Dobla a la izquierda de inmediato"],"h1":"Parar dentro de la intersección puede bloquear al camión de bomberos.","h2":"Si usted ya está en una intersección, sigue hasta cruzarla y luego se orilla al borde más cercano y para, para no bloquear al vehículo de emergencia.","p":"Correcto. Primero salga de la intersección, luego oríllese y pare."},"zh":{"q":"在 Florida，你正在路口中间，听到后面有消防车的警笛声。你该怎么做？","o":["开过路口，然后靠到最近的路边停车","停在路口中间","倒车退出路口","马上左转"],"h1":"停在路口里面可能会挡住消防车。","h2":"如果你已经在路口里，就继续开过去，然后靠到最近的路边停车，这样就不会挡住急救车辆。","p":"对。先开出路口，再靠边停车。"},"vi":{"q":"Ở Florida, bạn đang ở giữa giao lộ thì nghe tiếng còi xe cứu hỏa phía sau. Bạn làm gì?","o":["Chạy qua hết giao lộ, rồi tấp vào mép đường gần nhất và dừng lại","Dừng lại giữa giao lộ","Lùi xe ra khỏi giao lộ","Rẽ trái ngay lập tức"],"h1":"Dừng lại trong giao lộ có thể chắn đường xe cứu hỏa.","h2":"Nếu bạn đã ở trong giao lộ, bạn tiếp tục chạy qua, rồi tấp vào mép đường gần nhất và dừng lại, để không chắn đường xe khẩn cấp.","p":"Đúng. Hãy ra khỏi giao lộ trước, rồi tấp vào lề và dừng lại."},"tl":{"q":"Sa Florida, nasa gitna ka ng intersection nang marinig mo ang sirena ng trak ng bumbero sa likod mo. Ano ang gagawin mo?","o":["Tumawid sa intersection, saka tumabi sa pinakamalapit na gilid at huminto","Huminto sa gitna ng intersection","Umatras palabas ng intersection","Kumaliwa agad"],"h1":"Kapag huminto ka sa loob ng intersection, maaari mong maharangan ang trak ng bumbero.","h2":"Kung nasa intersection ka na, magpatuloy ka hanggang makalabas dito, saka tumabi sa pinakamalapit na gilid at huminto, para hindi mo maharangan ang emergency vehicle.","p":"Tama. Lumabas muna sa intersection, saka tumabi at huminto."},"ar":{"q":"في Florida، أنت في وسط التقاطع وتسمع صفارة سيارة إطفاء خلفك. ماذا تفعل؟","o":["أعبر التقاطع، ثم أتحرك إلى أقرب طرف وأتوقف","أتوقف في وسط التقاطع","أرجع إلى الخلف وأخرج من التقاطع","أنعطف يسارًا فورًا"],"h1":"إذا توقفت داخل التقاطع، قد تسد الطريق على سيارة الإطفاء.","h2":"إذا كنت داخل التقاطع، تستمر حتى تعبره، ثم تتحرك إلى أقرب طرف وتتوقف، حتى لا تسد الطريق على مركبة الطوارئ.","p":"صحيح. اعبر التقاطع أولًا، ثم ابتعد إلى الطرف وتوقف."},"ht":{"q":"Nan Florida, ou nan mitan yon kafou lè ou tande siren yon kamyon ponpye dèyè ou. Kisa ou fè?","o":["Ou travèse kafou a, apre sa ou rale sou bò ki pi pre a epi ou kanpe","Ou kanpe nan mitan kafou a","Ou fè bak pou sòti nan kafou a","Ou vire agòch touswit"],"h1":"Si ou kanpe anndan kafou a, ou ka bloke kamyon ponpye a.","h2":"Si ou deja nan yon kafou, ou kontinye travèse l, apre sa ou rale sou bò ki pi pre a epi ou kanpe, pou ou pa bloke machin ijans lan.","p":"Wi, se sa. Libere kafou a anvan, apre sa rale sou kote epi kanpe."},"ref":{"doc":"FL","page":84}},{"id":"right-of-way-016","scope":"FL","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Florida, a funeral procession is passing through an intersection. What should you do?","o":["Drive between the cars when there is a gap","Join the end of the line","Honk so they move faster","Yield and wait until the whole procession passes"],"h1":"The cars in the procession are traveling together as one group.","h2":"You must yield to a funeral procession and must not cut through it or join it, so you wait until all of it has passed.","p":"Right. Yield to a funeral procession and let it pass."},"es":{"q":"En Florida, un cortejo fúnebre está pasando por una intersección. ¿Qué debe hacer?","o":["Pasar entre los carros cuando haya un espacio","Unirse al final de la fila","Tocar la bocina para que avancen más rápido","Ceder el paso y esperar hasta que pase todo el cortejo"],"h1":"Los carros del cortejo viajan juntos como un solo grupo.","h2":"Usted debe ceder el paso a un cortejo fúnebre y no debe cruzarlo ni unirse a él, así que espera hasta que pase completo.","p":"Correcto. Ceda el paso al cortejo fúnebre y déjelo pasar."},"zh":{"q":"在 Florida，一支送葬车队正在通过路口。你应该怎么做？","o":["趁有空隙，从车队中间开过去","跟在车队最后面","按喇叭让他们走快一点","让行，等整个车队过去"],"h1":"送葬车队里的车是作为一个整体一起走的。","h2":"你必须给送葬车队让行，不能从中间穿过，也不能加入车队，所以要等整个车队都过去。","p":"对。给送葬车队让行，让它过去。"},"vi":{"q":"Ở Florida, một đoàn xe đưa tang đang đi qua giao lộ. Bạn nên làm gì?","o":["Chạy chen vào giữa các xe khi có khoảng trống","Nhập vào cuối đoàn xe","Bấm còi để họ đi nhanh hơn","Nhường đường và chờ cả đoàn xe đi qua"],"h1":"Các xe trong đoàn đưa tang đi cùng nhau như một nhóm.","h2":"Bạn phải nhường đoàn xe đưa tang và không được chen ngang hay nhập vào đoàn, nên bạn chờ đến khi cả đoàn đi qua.","p":"Đúng. Hãy nhường đoàn xe đưa tang và để đoàn đi qua."},"tl":{"q":"Sa Florida, may prusisyon ng libing na dumaraan sa intersection. Ano ang dapat mong gawin?","o":["Sumingit sa pagitan ng mga kotse kapag may puwang","Sumama sa dulo ng hanay","Bumusina para bumilis sila","Magbigay-daan at maghintay hanggang makalampas ang buong prusisyon"],"h1":"Magkakasamang bumibiyahe ang mga kotse sa prusisyon bilang isang grupo.","h2":"Dapat kang magbigay-daan sa prusisyon ng libing at hindi ka dapat sumingit o sumama rito, kaya maghihintay ka hanggang makalampas ang lahat ng ito.","p":"Tama. Magbigay-daan sa prusisyon ng libing at hayaan itong makalampas."},"ar":{"q":"في Florida، موكب جنازة يعبر التقاطع. ماذا يجب أن تفعل؟","o":["أقود بين السيارات عندما توجد فجوة","أنضم إلى آخر الموكب","أستعمل البوق ليسرعوا","أعطي حق المرور وأنتظر حتى يمر الموكب كله"],"h1":"السيارات في الموكب تسير معًا كمجموعة واحدة.","h2":"يجب أن تعطي حق المرور لموكب الجنازة، ولا يجوز أن تقطعه أو تنضم إليه، لذلك تنتظر حتى يمر كله.","p":"صحيح. أعطِ حق المرور لموكب الجنازة واتركه يمر."},"ht":{"q":"Nan Florida, yon kòtèj antèman ap travèse yon kafou. Kisa ou ta dwe fè?","o":["Ou pase nan mitan machin yo lè gen yon espas","Ou antre nan bout liy lan","Ou klaksonnen pou yo ale pi vit","Ou kite yo pase epi ou tann tout kòtèj la fin pase"],"h1":"Machin ki nan kòtèj la ap mache ansanm tankou yon sèl gwoup.","h2":"Ou dwe kite yon kòtèj antèman pase, ou pa dwe koupe l ni antre ladan l, kidonk ou tann jiskaske tout kòtèj la fin pase.","p":"Wi, se sa. Kite yon kòtèj antèman pase."},"ref":{"doc":"FL","page":84}},{"id":"right-of-way-017","scope":"FL","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Florida, a police car is stopped on the shoulder with its lights flashing. You are on a road with two lanes going your way. What must you do?","o":["Keep your speed and stay in your lane","Move out of the lane closest to the police car if it is safe","Stop next to the police car","Honk as you pass"],"h1":"Florida's Move Over law asks you to give stopped workers more space.","h2":"Under Florida's Move Over law, you must leave the lane closest to the stopped emergency vehicle when it is safe to change lanes.","p":"Right. Move over a lane for a stopped emergency vehicle."},"es":{"q":"En Florida, una patrulla de policía está parada en el acotamiento con las luces intermitentes. Usted va por una calle con dos carriles en su dirección. ¿Qué debe hacer?","o":["Mantener su velocidad y seguir en su carril","Salir del carril más cercano a la patrulla si es seguro","Parar al lado de la patrulla","Tocar la bocina al pasar"],"h1":"La ley Move Over de Florida le pide dar más espacio a quienes están parados trabajando.","h2":"Según la ley Move Over de Florida, usted debe salir del carril más cercano al vehículo de emergencia parado cuando sea seguro cambiar de carril.","p":"Correcto. Cámbiese de carril para un vehículo de emergencia parado."},"zh":{"q":"在 Florida，一辆警车停在路肩上，车灯在闪。你所在的路，你的方向有两条车道。你必须怎么做？","o":["保持车速，留在你的车道里","如果安全，离开最靠近警车的那条车道","停在警车旁边","经过时按喇叭"],"h1":"Florida 的 Move Over 法要求你给停在路边工作的人多留空间。","h2":"根据 Florida 的 Move Over 法，在可以安全换道时，你必须离开最靠近停着的急救车辆的那条车道。","p":"对。遇到停着的急救车辆，要让出一条车道。"},"vi":{"q":"Ở Florida, một xe cảnh sát đang dừng trên lề đường và nháy đèn. Đường của bạn có hai làn cùng chiều. Bạn phải làm gì?","o":["Giữ tốc độ và ở lại trong làn của bạn","Rời khỏi làn gần xe cảnh sát nhất nếu an toàn","Dừng lại cạnh xe cảnh sát","Bấm còi khi chạy qua"],"h1":"Luật \"Move Over\" của Florida yêu cầu bạn chừa thêm chỗ cho người đang làm việc bên đường.","h2":"Theo luật \"Move Over\" của Florida, bạn phải rời khỏi làn gần xe khẩn cấp đang dừng nhất khi đổi làn an toàn.","p":"Đúng. Hãy chuyển sang làn khác khi có xe khẩn cấp đang dừng."},"tl":{"q":"Sa Florida, may kotse ng pulis na nakahinto sa shoulder (gilid ng daan) na kumikislap ang ilaw. Nasa daan ka na may dalawang lane papunta sa direksiyon mo. Ano ang dapat mong gawin?","o":["Panatilihin ang bilis mo at manatili sa lane mo","Umalis sa lane na pinakamalapit sa kotse ng pulis kung ligtas","Huminto sa tabi ng kotse ng pulis","Bumusina habang dumaraan"],"h1":"Hinihiling ng Move Over law ng Florida na bigyan mo ng mas malaking espasyo ang mga nakahintong manggagawa.","h2":"Ayon sa Move Over law ng Florida, dapat mong iwan ang lane na pinakamalapit sa nakahintong emergency vehicle kapag ligtas lumipat ng lane.","p":"Tama. Lumipat ng isang lane para sa nakahintong emergency vehicle."},"ar":{"q":"في Florida، سيارة شرطة متوقفة على كتف الطريق وأضواؤها تومض. أنت على طريق فيه مساران في اتجاهك. ماذا يجب أن تفعل؟","o":["أحافظ على سرعتي وأبقى في مساري","أترك المسار الأقرب إلى سيارة الشرطة إذا كان ذلك آمنًا","أتوقف بجانب سيارة الشرطة","أستعمل البوق وأنا أمر"],"h1":"قانون Move Over في Florida يطلب منك أن تعطي العاملين المتوقفين مساحة أكبر.","h2":"حسب قانون Move Over في Florida، يجب أن تترك المسار الأقرب إلى مركبة الطوارئ المتوقفة عندما يكون تغيير المسار آمنًا.","p":"صحيح. ابتعد مسارًا واحدًا عن مركبة الطوارئ المتوقفة."},"ht":{"q":"Nan Florida, yon machin polis kanpe sou bò wout la ak limyè l ap flache. Ou sou yon wout ki gen de liy k ap ale nan menm direksyon ak ou. Kisa ou dwe fè?","o":["Ou kenbe menm vitès la epi ou rete nan liy ou","Ou sòti nan liy ki pi pre machin polis la si sa pa danjere","Ou kanpe bò kote machin polis la","Ou klaksonnen lè w ap pase"],"h1":"Lwa Move Over Florida a mande ou bay moun k ap travay epi ki kanpe yo plis espas.","h2":"Dapre lwa Move Over Florida a, ou dwe kite liy ki pi pre machin ijans ki kanpe a lè ou ka chanje liy san danje.","p":"Wi, se sa. Chanje liy pou yon machin ijans ki kanpe."},"ref":{"doc":"FL","page":65}},{"id":"right-of-way-018","scope":"FL","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Florida, you cannot safely move over for a stopped emergency vehicle. The speed limit is 55 mph. What must you do?","o":["Keep driving at 55 mph","Stop in your lane","Slow to 20 mph below the limit, so 35 mph","Speed up to pass it quickly"],"h1":"If you cannot move over, the law asks for a big cut in speed.","h2":"When you cannot move over, Florida law says you must slow to 20 mph below the posted speed limit, so on a 55 mph road you slow to 35 mph.","p":"Right. If you cannot move over, slow to 20 mph below the limit."},"es":{"q":"En Florida, usted no puede cambiarse de carril con seguridad para un vehículo de emergencia parado. El límite de velocidad es 55 mph. ¿Qué debe hacer?","o":["Seguir manejando a 55 mph","Parar en su carril","Bajar a 20 mph menos que el límite, o sea 35 mph","Acelerar para pasarlo rápido"],"h1":"Si no puede cambiarse de carril, la ley le pide bajar mucho la velocidad.","h2":"Cuando usted no puede cambiarse de carril, la ley de Florida dice que debe bajar a 20 mph menos que el límite marcado, así que en una calle de 55 mph baja a 35 mph.","p":"Correcto. Si no puede cambiarse de carril, baje 20 mph del límite."},"zh":{"q":"在 Florida，你没办法安全地给停着的急救车辆让出车道。限速是 55 英里/小时。你必须怎么做？","o":["继续以 55 英里/小时行驶","停在你的车道里","减速到比限速低 20 英里/小时，也就是 35 英里/小时","加速，快点开过去"],"h1":"如果你不能换道，法律要求你大幅减速。","h2":"不能换道时，Florida 法律规定你必须减速到比限速低 20 英里/小时，所以在限速 55 英里/小时的路上，你要减到 35 英里/小时。","p":"对。不能换道时，要减速到比限速低 20 英里/小时。"},"vi":{"q":"Ở Florida, bạn không thể chuyển làn an toàn để tránh một xe khẩn cấp đang dừng. Giới hạn tốc độ là 55 mph. Bạn phải làm gì?","o":["Tiếp tục chạy 55 mph","Dừng lại trong làn của bạn","Giảm xuống thấp hơn giới hạn 20 mph, tức là 35 mph","Tăng tốc để vượt qua nhanh"],"h1":"Nếu không thể chuyển làn, luật yêu cầu bạn giảm tốc độ nhiều.","h2":"Khi không thể chuyển làn, luật Florida nói bạn phải giảm xuống thấp hơn giới hạn tốc độ 20 mph, nên trên đường 55 mph bạn giảm xuống 35 mph.","p":"Đúng. Nếu không thể chuyển làn, hãy giảm xuống thấp hơn giới hạn 20 mph."},"tl":{"q":"Sa Florida, hindi ka ligtas na makalipat ng lane para sa nakahintong emergency vehicle. Ang speed limit ay 55 mph. Ano ang dapat mong gawin?","o":["Magpatuloy sa 55 mph","Huminto sa lane mo","Bumagal sa 20 mph na mas mababa sa limit, kaya 35 mph","Bumilis para madaanan ito agad"],"h1":"Kung hindi ka makalipat, malaking bawas sa bilis ang hinihingi ng batas.","h2":"Kapag hindi ka makalipat ng lane, sinasabi ng batas ng Florida na dapat kang bumagal sa 20 mph na mas mababa sa nakapaskil na speed limit, kaya sa daang 55 mph, bababa ka sa 35 mph.","p":"Tama. Kung hindi ka makalipat, bumagal sa 20 mph na mas mababa sa limit."},"ar":{"q":"في Florida، لا تستطيع أن تبتعد بأمان عن مركبة طوارئ متوقفة. حد السرعة 55 ميلًا في الساعة. ماذا يجب أن تفعل؟","o":["أستمر بسرعة 55 ميلًا في الساعة","أتوقف في مساري","أخفف السرعة إلى 20 ميلًا في الساعة أقل من الحد، أي 35 ميلًا في الساعة","أسرع لأتجاوزها بسرعة"],"h1":"إذا لم تستطع أن تبتعد، يطلب القانون تخفيضًا كبيرًا في السرعة.","h2":"عندما لا تستطيع أن تبتعد، يقول قانون Florida إنه يجب أن تخفف السرعة إلى 20 ميلًا في الساعة أقل من حد السرعة المكتوب، لذلك على طريق حده 55 ميلًا في الساعة تخفف إلى 35 ميلًا في الساعة.","p":"صحيح. إذا لم تستطع أن تبتعد، خفف السرعة إلى 20 ميلًا في الساعة أقل من الحد."},"ht":{"q":"Nan Florida, ou pa ka chanje liy san danje pou yon machin ijans ki kanpe. Limit vitès la se 55 mph. Kisa ou dwe fè?","o":["Ou kontinye kondi a 55 mph","Ou kanpe nan liy ou","Ou ralanti pou ou desann 20 mph anba limit la, sa vle di 35 mph","Ou akselere pou pase l vit"],"h1":"Si ou pa ka chanje liy, lwa a mande ou bese vitès ou anpil.","h2":"Lè ou pa ka chanje liy, lwa Florida di ou dwe ralanti pou ou desann 20 mph anba limit vitès ki afiche a, kidonk sou yon wout 55 mph ou desann a 35 mph.","p":"Wi, se sa. Si ou pa ka chanje liy, desann 20 mph anba limit la."},"ref":{"doc":"FL","page":65}},{"id":"right-of-way-019","scope":"FL","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Florida, the speed limit is 20 mph. A tow truck is stopped with its lights flashing, and you cannot move over. How fast may you pass it?","o":["5 mph","15 mph","20 mph","10 mph"],"h1":"Twenty below the limit would be zero, so the law gives a special number.","h2":"When the speed limit is 20 mph or less and you cannot move over, Florida law says you must slow to 5 mph.","p":"Right. On a road of 20 mph or less, slow to 5 mph."},"es":{"q":"En Florida, el límite de velocidad es 20 mph. Una grúa está parada con las luces intermitentes y usted no puede cambiarse de carril. ¿A qué velocidad puede pasarla?","o":["5 mph","15 mph","20 mph","10 mph"],"h1":"Veinte menos que el límite sería cero, así que la ley da un número especial.","h2":"Cuando el límite es 20 mph o menos y usted no puede cambiarse de carril, la ley de Florida dice que debe bajar a 5 mph.","p":"Correcto. En una calle de 20 mph o menos, baje a 5 mph."},"zh":{"q":"在 Florida，限速是 20 英里/小时。一辆拖车停着，车灯在闪，你又没办法换道。你最快可以用多少速度经过它？","o":["5 英里/小时","15 英里/小时","20 英里/小时","10 英里/小时"],"h1":"比限速低 20 就变成零了，所以法律给了一个特别的数字。","h2":"当限速是 20 英里/小时或更低，而你又不能换道时，Florida 法律规定你必须减速到 5 英里/小时。","p":"对。在限速 20 英里/小时或更低的路上，要减速到 5 英里/小时。"},"vi":{"q":"Ở Florida, giới hạn tốc độ là 20 mph. Một xe kéo đang dừng và nháy đèn, và bạn không thể chuyển làn. Bạn được chạy qua với tốc độ bao nhiêu?","o":["5 mph","15 mph","20 mph","10 mph"],"h1":"Thấp hơn giới hạn 20 thì sẽ là số không, nên luật đưa ra một con số riêng.","h2":"Khi giới hạn tốc độ là 20 mph hoặc thấp hơn và bạn không thể chuyển làn, luật Florida nói bạn phải giảm xuống 5 mph.","p":"Đúng. Trên đường 20 mph hoặc thấp hơn, hãy giảm xuống 5 mph."},"tl":{"q":"Sa Florida, 20 mph ang speed limit. May tow truck na nakahinto na kumikislap ang ilaw, at hindi ka makalipat ng lane. Gaano kabilis ka puwedeng dumaan?","o":["5 mph","15 mph","20 mph","10 mph"],"h1":"Kung babawasan ng dalawampu ang limit, magiging zero ito, kaya may espesyal na numero ang batas.","h2":"Kapag 20 mph o mas mababa ang speed limit at hindi ka makalipat ng lane, sinasabi ng batas ng Florida na dapat kang bumagal sa 5 mph.","p":"Tama. Sa daang 20 mph o mas mababa, bumagal sa 5 mph."},"ar":{"q":"في Florida، حد السرعة 20 ميلًا في الساعة. شاحنة سحب متوقفة وأضواؤها تومض، ولا تستطيع أن تبتعد عنها. بأي سرعة يمكنك أن تمر بجانبها؟","o":["5 أميال في الساعة","15 ميلًا في الساعة","20 ميلًا في الساعة","10 أميال في الساعة"],"h1":"عشرون أقل من الحد تساوي صفرًا، لذلك يعطي القانون رقمًا خاصًا.","h2":"عندما يكون حد السرعة 20 ميلًا في الساعة أو أقل ولا تستطيع أن تبتعد، يقول قانون Florida إنه يجب أن تخفف السرعة إلى 5 أميال في الساعة.","p":"صحيح. على طريق حده 20 ميلًا في الساعة أو أقل، خفف السرعة إلى 5 أميال في الساعة."},"ht":{"q":"Nan Florida, limit vitès la se 20 mph. Yon kamyon remòk kanpe ak limyè l ap flache, epi ou pa ka chanje liy. Ak ki vitès ou ka pase bò kote l?","o":["5 mph","15 mph","20 mph","10 mph"],"h1":"Ven anba limit la ta bay zewo, kidonk lwa a bay yon chif espesyal.","h2":"Lè limit vitès la se 20 mph oswa mwens epi ou pa ka chanje liy, lwa Florida di ou dwe desann a 5 mph.","p":"Wi, se sa. Sou yon wout 20 mph oswa mwens, desann a 5 mph."},"ref":{"doc":"FL","page":65}},{"id":"right-of-way-020","scope":"FL","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Florida, which of these stopped vehicles is covered by the Move Over law?","o":["A parked car with no lights on","A city bus at a bus stop","A delivery van at a store","A garbage truck with its warning lights flashing"],"h1":"The law covers workers on the road who show flashing warning lights.","h2":"Florida's Move Over law covers sanitation trucks, utility trucks, tow trucks, and road crews when they are stopped with warning lights flashing, so you must move over or slow down.","p":"Right. Move over for a stopped garbage truck with flashing lights."},"es":{"q":"En Florida, ¿cuál de estos vehículos parados está cubierto por la ley Move Over?","o":["Un carro estacionado sin luces encendidas","Un autobús de la ciudad en una parada","Una camioneta de reparto frente a una tienda","Un camión de basura con las luces de advertencia intermitentes"],"h1":"La ley cubre a trabajadores en la vía que muestran luces de advertencia intermitentes.","h2":"La ley Move Over de Florida cubre camiones de basura, de servicios públicos, grúas y equipos de carretera cuando están parados con luces de advertencia intermitentes, así que usted debe cambiarse de carril o bajar la velocidad.","p":"Correcto. Cámbiese de carril por un camión de basura parado con luces intermitentes."},"zh":{"q":"在 Florida，下面哪一辆停着的车受 Move Over 法保护？","o":["一辆没开灯的停放汽车","一辆停在车站的公交车","一辆停在商店门口的送货车","一辆闪着警示灯的垃圾车"],"h1":"这条法律保护在路上工作、并闪着警示灯的人。","h2":"Florida 的 Move Over 法保护停着并闪着警示灯的环卫车、公用事业车、拖车和道路施工人员，所以你必须换道或减速。","p":"对。遇到闪着灯停着的垃圾车，要让出车道。"},"vi":{"q":"Ở Florida, xe nào sau đây khi đang dừng thì thuộc luật \"Move Over\"?","o":["Xe hơi đậu không bật đèn","Xe buýt thành phố ở trạm xe buýt","Xe giao hàng ở cửa hàng","Xe rác đang nháy đèn cảnh báo"],"h1":"Luật này bảo vệ người làm việc trên đường có đèn cảnh báo nhấp nháy.","h2":"Luật \"Move Over\" của Florida áp dụng cho xe rác, xe của công ty điện nước, xe kéo và đội sửa đường khi họ dừng và nháy đèn cảnh báo, nên bạn phải chuyển làn hoặc giảm tốc.","p":"Đúng. Hãy chuyển làn khi có xe rác đang dừng và nháy đèn."},"tl":{"q":"Sa Florida, alin sa mga nakahintong sasakyang ito ang sakop ng Move Over law?","o":["Nakaparadang kotse na walang ilaw","Bus ng lungsod sa bus stop","Delivery van sa harap ng tindahan","Trak ng basura na kumikislap ang warning lights"],"h1":"Sakop ng batas ang mga manggagawa sa daan na nagpapakita ng kumikislap na warning lights.","h2":"Sakop ng Move Over law ng Florida ang mga trak ng basura, trak ng utility, tow truck, at mga road crew kapag nakahinto sila na kumikislap ang warning lights, kaya dapat kang lumipat ng lane o bumagal.","p":"Tama. Lumipat ng lane para sa nakahintong trak ng basura na kumikislap ang ilaw."},"ar":{"q":"في Florida، أي مركبة متوقفة من هذه المركبات يشملها قانون Move Over؟","o":["سيارة مركونة وأضواؤها مطفأة","حافلة مدينة عند محطة الحافلات","شاحنة توصيل صغيرة عند متجر","شاحنة نفايات أضواء التحذير فيها تومض"],"h1":"القانون يشمل العاملين على الطريق الذين يُظهرون أضواء تحذير وامضة.","h2":"قانون Move Over في Florida يشمل شاحنات النفايات، وشاحنات المرافق، وشاحنات السحب، وعمال الطرق عندما يتوقفون وأضواء التحذير تومض، لذلك يجب أن تبتعد أو تخفف السرعة.","p":"صحيح. ابتعد عن شاحنة نفايات متوقفة أضواؤها تومض."},"ht":{"q":"Nan Florida, kiyès nan machin ki kanpe sa yo lwa Move Over la kouvri?","o":["Yon machin ki pake san limyè limen","Yon bis vil ki kanpe nan yon arè bis","Yon kamyonèt livrezon devan yon magazen","Yon kamyon fatra ki gen limyè avètisman l ap flache"],"h1":"Lwa a kouvri moun k ap travay sou wout la ki montre limyè avètisman k ap flache.","h2":"Lwa Move Over Florida a kouvri kamyon fatra, kamyon sèvis piblik, kamyon remòk ak ekip k ap travay sou wout la lè yo kanpe ak limyè avètisman k ap flache, kidonk ou dwe chanje liy oswa ralanti.","p":"Wi, se sa. Chanje liy pou yon kamyon fatra ki kanpe ak limyè k ap flache."},"ref":{"doc":"FL","page":65}},{"id":"right-of-way-021","scope":"FL","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Florida, a car is stopped on the shoulder with its hazard lights flashing. Does the Move Over law apply?","o":["No, it is only for police and ambulances","Yes, move over or slow down as you would for an emergency vehicle","Only at night","Only on toll roads"],"h1":"Florida widened the Move Over law to protect more people stopped by the road.","h2":"Florida's Move Over law also covers a disabled vehicle that is stopped and showing hazard lights or other warning signs, so you must move over or slow down.","p":"Right. Move over or slow down for a stopped car with hazard lights."},"es":{"q":"En Florida, un carro está parado en el acotamiento con las luces de emergencia encendidas. ¿Se aplica la ley Move Over?","o":["No, es solo para policías y ambulancias","Sí, cámbiese de carril o baje la velocidad como para un vehículo de emergencia","Solo de noche","Solo en carreteras de peaje"],"h1":"Florida amplió la ley Move Over para proteger a más personas paradas en la orilla.","h2":"La ley Move Over de Florida también cubre a un vehículo descompuesto que está parado y muestra luces de emergencia u otras señales de advertencia, así que usted debe cambiarse de carril o bajar la velocidad.","p":"Correcto. Cámbiese de carril o baje la velocidad por un carro parado con luces de emergencia."},"zh":{"q":"在 Florida，一辆车停在路肩上，开着双闪灯。Move Over 法适用吗？","o":["不适用，它只针对警车和救护车","适用，要像遇到急救车辆一样换道或减速","只在晚上适用","只在收费公路上适用"],"h1":"Florida 扩大了 Move Over 法，保护更多停在路边的人。","h2":"Florida 的 Move Over 法也保护停着并开着双闪灯或有其他警示的故障车，所以你必须换道或减速。","p":"对。遇到开着双闪灯停着的车，要换道或减速。"},"vi":{"q":"Ở Florida, một xe hơi đang dừng trên lề và bật đèn khẩn cấp nhấp nháy. Luật \"Move Over\" có áp dụng không?","o":["Không, luật chỉ dành cho cảnh sát và xe cứu thương","Có, hãy chuyển làn hoặc giảm tốc như với xe khẩn cấp","Chỉ vào ban đêm","Chỉ trên đường thu phí"],"h1":"Florida đã mở rộng luật \"Move Over\" để bảo vệ thêm nhiều người dừng bên đường.","h2":"Luật \"Move Over\" của Florida cũng áp dụng cho xe bị hỏng đang dừng và bật đèn khẩn cấp hoặc dấu hiệu cảnh báo khác, nên bạn phải chuyển làn hoặc giảm tốc.","p":"Đúng. Hãy chuyển làn hoặc giảm tốc khi có xe dừng bật đèn khẩn cấp."},"tl":{"q":"Sa Florida, may kotseng nakahinto sa shoulder na kumikislap ang hazard lights. Sakop ba ito ng Move Over law?","o":["Hindi, para lang ito sa pulis at ambulansiya","Oo, lumipat ng lane o bumagal gaya ng gagawin mo para sa emergency vehicle","Sa gabi lang","Sa toll road lang"],"h1":"Pinalawak ng Florida ang Move Over law para protektahan ang mas maraming taong nakahinto sa tabi ng daan.","h2":"Sakop din ng Move Over law ng Florida ang sirang sasakyan na nakahinto at nagpapakita ng hazard lights o iba pang babala, kaya dapat kang lumipat ng lane o bumagal.","p":"Tama. Lumipat ng lane o bumagal para sa nakahintong kotse na may hazard lights."},"ar":{"q":"في Florida، سيارة متوقفة على كتف الطريق وأضواء الخطر فيها تومض. هل ينطبق قانون Move Over؟","o":["لا، هو للشرطة وسيارات الإسعاف فقط","نعم، ابتعد أو خفف السرعة كما تفعل لمركبة طوارئ","فقط في الليل","فقط على الطرق التي فيها رسوم"],"h1":"Florida وسّعت قانون Move Over لتحمي عددًا أكبر من الناس المتوقفين بجانب الطريق.","h2":"قانون Move Over في Florida يشمل أيضًا المركبة المعطلة المتوقفة التي تُظهر أضواء الخطر أو علامات تحذير أخرى، لذلك يجب أن تبتعد أو تخفف السرعة.","p":"صحيح. ابتعد أو خفف السرعة لسيارة متوقفة أضواء الخطر فيها تعمل."},"ht":{"q":"Nan Florida, yon machin kanpe sou bò wout la ak limyè ijans li (flachè) k ap flache. Èske lwa Move Over la aplike?","o":["Non, se sèlman pou polis ak anbilans","Wi, chanje liy oswa ralanti menm jan ou ta fè pou yon machin ijans","Sèlman lannwit","Sèlman sou wout peyan"],"h1":"Florida te elaji lwa Move Over la pou pwoteje plis moun ki kanpe bò wout la.","h2":"Lwa Move Over Florida a kouvri tou yon machin ki an pàn epi ki kanpe ak limyè ijans oswa lòt siy avètisman, kidonk ou dwe chanje liy oswa ralanti.","p":"Wi, se sa. Chanje liy oswa ralanti pou yon machin ki kanpe ak limyè ijans li."},"ref":{"doc":"FL","page":65}},{"id":"right-of-way-022","scope":"FL","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Florida, on a two-way road, a school bus ahead is stopped with its stop arm out. You are coming from the other direction. What do you do?","o":["Slow down and pass with care","Keep going, because you are on the other side","Stop and stay stopped","Honk and pass"],"h1":"On a two-way road with no median, the rule is the same for both directions.","h2":"On a two-way road, traffic going both ways must stop for a school bus that shows its stop signal, so you stop even when coming from the other side.","p":"Right. On a two-way road, both directions stop for a stopped school bus."},"es":{"q":"En Florida, en una calle de doble sentido, un autobús escolar adelante está parado con el brazo de pare afuera. Usted viene en la dirección contraria. ¿Qué hace?","o":["Baja la velocidad y pasa con cuidado","Sigue, porque usted va del otro lado","Para y se queda parado","Toca la bocina y pasa"],"h1":"En una calle de doble sentido sin división, la regla es igual para las dos direcciones.","h2":"En una calle de doble sentido, el tráfico de las dos direcciones debe parar ante un autobús escolar que muestra su señal de pare, así que usted para aunque venga del otro lado.","p":"Correcto. En calle de doble sentido, las dos direcciones paran por el autobús escolar."},"zh":{"q":"在 Florida，在一条双向道路上，前面一辆校车停着，伸出了停车臂。你从对面方向开过来。你该怎么做？","o":["减速，小心地开过去","继续开，因为你在另一边","停车，并保持停着","按喇叭，然后开过去"],"h1":"在没有中间隔离带的双向道路上，两个方向的规则是一样的。","h2":"在双向道路上，两个方向的车都必须为亮出停车信号的校车停车，所以就算你从对面来，也要停车。","p":"对。在双向道路上，两个方向都要为停着的校车停车。"},"vi":{"q":"Ở Florida, trên đường hai chiều, xe buýt trường học phía trước đang dừng và giơ cần biển \"STOP\". Bạn đến từ hướng ngược lại. Bạn làm gì?","o":["Giảm tốc và chạy qua cẩn thận","Tiếp tục chạy, vì bạn ở phía bên kia","Dừng lại và giữ nguyên ở đó","Bấm còi và chạy qua"],"h1":"Trên đường hai chiều không có dải phân cách, quy tắc giống nhau cho cả hai hướng.","h2":"Trên đường hai chiều, xe đi cả hai hướng đều phải dừng khi xe buýt trường học bật tín hiệu dừng, nên bạn phải dừng dù đến từ phía bên kia.","p":"Đúng. Trên đường hai chiều, cả hai hướng đều dừng cho xe buýt trường học đang dừng."},"tl":{"q":"Sa Florida, sa daang two-way, may school bus sa unahan na nakahinto at nakalabas ang stop arm. Galing ka sa kabilang direksiyon. Ano ang gagawin mo?","o":["Bumagal at dumaan nang maingat","Magpatuloy, dahil nasa kabilang panig ka","Huminto at manatiling nakahinto","Bumusina at dumaan"],"h1":"Sa daang two-way na walang median, pareho ang patakaran sa dalawang direksiyon.","h2":"Sa daang two-way, dapat huminto ang trapiko sa dalawang direksiyon para sa school bus na nagpapakita ng stop signal, kaya hihinto ka kahit galing ka sa kabilang panig.","p":"Tama. Sa daang two-way, humihinto ang dalawang direksiyon para sa nakahintong school bus."},"ar":{"q":"في Florida، على طريق باتجاهين، حافلة مدرسية أمامك متوقفة وذراع التوقف فيها مفتوح. أنت قادم من الاتجاه الآخر. ماذا تفعل؟","o":["أخفف السرعة وأمر بحذر","أستمر، لأنني على الجانب الآخر","أتوقف وأبقى متوقفًا","أستعمل البوق وأمر"],"h1":"على طريق باتجاهين بدون فاصل في الوسط، القاعدة هي نفسها في الاتجاهين.","h2":"على طريق باتجاهين، يجب على السيارات في الاتجاهين أن تتوقف لحافلة مدرسية تُظهر إشارة التوقف، لذلك تتوقف حتى لو كنت قادمًا من الجانب الآخر.","p":"صحيح. على طريق باتجاهين، يتوقف الاتجاهان لحافلة مدرسية متوقفة."},"ht":{"q":"Nan Florida, sou yon wout de sans, gen yon bis lekòl devan ki kanpe ak bra \"STOP\" li louvri. W ap vini nan lòt direksyon an. Kisa ou fè?","o":["Ou ralanti epi ou pase avèk atansyon","Ou kontinye, paske ou sou lòt bò a","Ou kanpe epi ou rete kanpe","Ou klaksonnen epi ou pase"],"h1":"Sou yon wout de sans ki pa gen separasyon nan mitan, règ la se menm pou de direksyon yo.","h2":"Sou yon wout de sans, machin k ap ale nan de direksyon yo dwe kanpe pou yon bis lekòl ki montre siyal \"STOP\" li, kidonk ou kanpe menm si w ap vini nan lòt bò a.","p":"Wi, se sa. Sou yon wout de sans, de direksyon yo kanpe pou yon bis lekòl ki kanpe."},"ref":{"doc":"FL","page":89}},{"id":"right-of-way-023","scope":"FL","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Florida, a school bus is stopped across a raised concrete median, on the other side of a divided highway. Must you stop?","o":["No, you may keep going, with care","Yes, you must always stop","Only if children are on your side","Only if the bus honks"],"h1":"A raised barrier keeps the two directions apart.","h2":"On a divided highway with a raised median, you do not have to stop when the school bus is on the other side, but you should still watch for children.","p":"Right. With a raised median, the opposite side does not have to stop."},"es":{"q":"En Florida, un autobús escolar está parado del otro lado de una división de concreto elevada en una carretera dividida. ¿Debe usted parar?","o":["No, puede seguir con cuidado","Sí, siempre debe parar","Solo si hay niños de su lado","Solo si el autobús toca la bocina"],"h1":"Una división elevada separa las dos direcciones.","h2":"En una carretera dividida con una división elevada, usted no tiene que parar cuando el autobús escolar está del otro lado, pero igual debe estar atento a los niños.","p":"Correcto. Con división elevada, el lado contrario no tiene que parar."},"zh":{"q":"在 Florida，一辆校车停在一条分隔公路的另一边，中间有凸起的水泥隔离带。你必须停车吗？","o":["不用，你可以小心地继续开","要，你永远必须停车","只有你这边有小孩时才要","只有校车按喇叭时才要"],"h1":"凸起的隔离带把两个方向分开了。","h2":"在有凸起隔离带的分隔公路上，校车在另一边时你不用停车，但你还是要注意小孩。","p":"对。有凸起隔离带时，对面方向不用停车。"},"vi":{"q":"Ở Florida, một xe buýt trường học đang dừng ở phía bên kia của xa lộ có dải phân cách bằng bê tông nổi cao. Bạn có phải dừng không?","o":["Không, bạn có thể tiếp tục chạy, nhưng cẩn thận","Có, bạn luôn phải dừng","Chỉ khi có trẻ em ở phía bên bạn","Chỉ khi xe buýt bấm còi"],"h1":"Một rào chắn nổi cao tách hai hướng xe ra.","h2":"Trên xa lộ có dải phân cách nổi cao, bạn không phải dừng khi xe buýt trường học ở phía bên kia, nhưng bạn vẫn nên để ý trẻ em.","p":"Đúng. Có dải phân cách nổi cao thì phía bên kia không phải dừng."},"tl":{"q":"Sa Florida, may school bus na nakahinto sa kabila ng nakataas na konkretong median, sa kabilang panig ng divided highway. Dapat ka bang huminto?","o":["Hindi, puwede kang magpatuloy, nang maingat","Oo, dapat kang laging huminto","Kung may mga bata lang sa panig mo","Kung bumusina lang ang bus"],"h1":"Pinaghihiwalay ng nakataas na harang ang dalawang direksiyon.","h2":"Sa divided highway na may nakataas na median, hindi mo kailangang huminto kapag nasa kabilang panig ang school bus, pero dapat ka pa ring magbantay sa mga bata.","p":"Tama. Kapag may nakataas na median, hindi kailangang huminto ang kabilang panig."},"ar":{"q":"في Florida، حافلة مدرسية متوقفة على الجانب الآخر من طريق سريع مقسوم بفاصل إسمنتي مرتفع. هل يجب أن تتوقف؟","o":["لا، يمكنني أن أستمر بحذر","نعم، يجب أن أتوقف دائمًا","فقط إذا كان هناك أطفال على جانبي","فقط إذا استعملت الحافلة البوق"],"h1":"الحاجز المرتفع يفصل بين الاتجاهين.","h2":"على طريق سريع مقسوم بفاصل مرتفع، لا يجب أن تتوقف عندما تكون الحافلة المدرسية على الجانب الآخر، لكن يجب أن تنتبه للأطفال.","p":"صحيح. مع فاصل مرتفع، لا يجب على الجانب المقابل أن يتوقف."},"ht":{"q":"Nan Florida, yon bis lekòl kanpe lòt bò yon separasyon an beton ki leve, sou lòt bò yon gran wout ki separe. Èske ou dwe kanpe?","o":["Non, ou ka kontinye, avèk atansyon","Wi, ou dwe toujou kanpe","Sèlman si gen timoun sou bò pa w la","Sèlman si bis la klaksonnen"],"h1":"Yon baryè ki leve kenbe de direksyon yo apa.","h2":"Sou yon gran wout ki separe ak yon separasyon ki leve, ou pa oblije kanpe lè bis lekòl la sou lòt bò a, men ou dwe toujou veye timoun yo.","p":"Wi, se sa. Lè gen yon separasyon ki leve, machin ki sou lòt bò a pa oblije kanpe."},"ref":{"doc":"FL","page":89}},{"id":"right-of-way-024","scope":"FL","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Florida, a highway has an unpaved grass median. How wide must it be so that traffic on the other side does not have to stop for a school bus?","o":["At least 2 feet","At least 10 feet","At least 20 feet","At least 5 feet"],"h1":"The number is small, about the length of a sofa.","h2":"Florida law says that if an unpaved median is at least 5 feet wide, traffic going the other way does not have to stop for a stopped school bus.","p":"Right. An unpaved median of at least 5 feet means the other side does not stop."},"es":{"q":"En Florida, una carretera tiene una división de césped sin pavimentar. ¿Qué ancho debe tener para que el tráfico del otro lado no tenga que parar por un autobús escolar?","o":["Por lo menos 2 pies","Por lo menos 10 pies","Por lo menos 20 pies","Por lo menos 5 pies"],"h1":"El número es pequeño, más o menos el largo de un sofá.","h2":"La ley de Florida dice que si una división sin pavimentar mide por lo menos 5 pies de ancho, el tráfico que va en la otra dirección no tiene que parar por un autobús escolar parado.","p":"Correcto. Con una división sin pavimentar de por lo menos 5 pies, el otro lado no para."},"zh":{"q":"在 Florida，一条公路中间有没铺路面的草地隔离带。它至少要多宽，对面方向的车才不用为校车停车？","o":["至少 2 英尺","至少 10 英尺","至少 20 英尺","至少 5 英尺"],"h1":"这个数字很小，大约是一张沙发的长度。","h2":"Florida 法律规定，如果没铺路面的隔离带至少有 5 英尺宽，对面方向的车就不用为停着的校车停车。","p":"对。没铺路面的隔离带至少 5 英尺宽，对面就不用停车。"},"vi":{"q":"Ở Florida, một xa lộ có dải phân cách bằng cỏ, không tráng nhựa. Dải đó phải rộng bao nhiêu để xe phía bên kia không phải dừng cho xe buýt trường học?","o":["Ít nhất 2 feet","Ít nhất 10 feet","Ít nhất 20 feet","Ít nhất 5 feet"],"h1":"Con số này nhỏ, khoảng bằng chiều dài một chiếc ghế sofa.","h2":"Luật Florida nói nếu dải phân cách không tráng nhựa rộng ít nhất 5 feet, xe đi hướng ngược lại không phải dừng cho xe buýt trường học đang dừng.","p":"Đúng. Dải phân cách không tráng nhựa rộng ít nhất 5 feet thì phía bên kia không phải dừng."},"tl":{"q":"Sa Florida, may median na damo at walang semento ang isang highway. Gaano ito dapat kalapad para hindi na kailangang huminto ng trapiko sa kabilang panig para sa school bus?","o":["Hindi bababa sa 2 feet","Hindi bababa sa 10 feet","Hindi bababa sa 20 feet","Hindi bababa sa 5 feet"],"h1":"Maliit ang numero, mga kasinghaba ng sofa.","h2":"Sinasabi ng batas ng Florida na kung ang median na walang semento ay hindi bababa sa 5 feet ang lapad, hindi kailangang huminto ng trapiko sa kabilang direksiyon para sa nakahintong school bus.","p":"Tama. Kapag ang median na walang semento ay hindi bababa sa 5 feet, hindi humihinto ang kabilang panig."},"ar":{"q":"في Florida، طريق سريع في وسطه فاصل من العشب غير مرصوف. كم يجب أن يكون عرضه حتى لا تتوقف السيارات على الجانب الآخر للحافلة المدرسية؟","o":["2 قدم على الأقل","10 أقدام على الأقل","20 قدمًا على الأقل","5 أقدام على الأقل"],"h1":"الرقم صغير، تقريبًا طول أريكة.","h2":"يقول قانون Florida إنه إذا كان عرض الفاصل غير المرصوف 5 أقدام على الأقل، فلا يجب على السيارات في الاتجاه الآخر أن تتوقف لحافلة مدرسية متوقفة.","p":"صحيح. فاصل غير مرصوف عرضه 5 أقدام على الأقل يعني أن الجانب الآخر لا يتوقف."},"ht":{"q":"Nan Florida, yon gran wout gen yon separasyon an zèb, ki pa asfalte, nan mitan l. Ki lajè separasyon an dwe genyen pou machin ki sou lòt bò a pa oblije kanpe pou yon bis lekòl?","o":["Omwen 2 pye","Omwen 10 pye","Omwen 20 pye","Omwen 5 pye"],"h1":"Chif la piti, apeprè longè yon kanape.","h2":"Lwa Florida di si yon separasyon ki pa asfalte gen omwen 5 pye lajè, machin k ap ale nan lòt direksyon an pa oblije kanpe pou yon bis lekòl ki kanpe.","p":"Wi, se sa. Yon separasyon ki pa asfalte ki gen omwen 5 pye vle di lòt bò a pa kanpe."},"ref":{"doc":"FL","page":89}},{"id":"right-of-way-025","scope":"FL","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Florida, a road has a paved center turn lane. A school bus is stopped on the other side with its stop arm out. What do you do?","o":["Keep going, because a turn lane divides the road","Stop, because a paved turn lane does not count as a divider","Pass using the turn lane","Slow down only"],"h1":"Only a raised barrier or a wide unpaved median lets the other side keep going.","h2":"A paved center turn lane is not a raised barrier or an unpaved median, so traffic in both directions must stop for the school bus.","p":"Right. A paved turn lane does not excuse you. Stop for the bus."},"es":{"q":"En Florida, una calle tiene un carril central pavimentado para doblar. Un autobús escolar está parado del otro lado con el brazo de pare afuera. ¿Qué hace?","o":["Sigue, porque el carril para doblar divide la calle","Para, porque un carril pavimentado para doblar no cuenta como división","Pasa usando el carril para doblar","Solo baja la velocidad"],"h1":"Solo una división elevada o una división ancha sin pavimentar permite que el otro lado siga.","h2":"Un carril central pavimentado para doblar no es una división elevada ni una división sin pavimentar, así que el tráfico de las dos direcciones debe parar por el autobús escolar.","p":"Correcto. Un carril para doblar no lo exime. Pare por el autobús."},"zh":{"q":"在 Florida，一条路中间有铺了路面的中央转弯车道。一辆校车停在另一边，伸出了停车臂。你该怎么做？","o":["继续开，因为转弯车道把路分开了","停车，因为铺了路面的转弯车道不算隔离带","从转弯车道开过去","只要减速就行"],"h1":"只有凸起的隔离带或很宽的没铺路面的隔离带，才能让对面继续开。","h2":"铺了路面的中央转弯车道不是凸起的隔离带，也不是没铺路面的隔离带，所以两个方向的车都必须为校车停车。","p":"对。铺了路面的转弯车道不能当理由。要为校车停车。"},"vi":{"q":"Ở Florida, một con đường có làn rẽ ở giữa được tráng nhựa. Một xe buýt trường học đang dừng ở phía bên kia và giơ cần biển \"STOP\". Bạn làm gì?","o":["Tiếp tục chạy, vì làn rẽ chia đôi con đường","Dừng lại, vì làn rẽ tráng nhựa không được tính là dải phân cách","Chạy qua bằng làn rẽ","Chỉ cần giảm tốc"],"h1":"Chỉ có rào chắn nổi cao hoặc dải phân cách không tráng nhựa đủ rộng mới cho phía bên kia tiếp tục chạy.","h2":"Làn rẽ ở giữa được tráng nhựa không phải là rào chắn nổi cao hay dải phân cách không tráng nhựa, nên xe cả hai hướng phải dừng cho xe buýt trường học.","p":"Đúng. Làn rẽ tráng nhựa không miễn cho bạn. Hãy dừng cho xe buýt."},"tl":{"q":"Sa Florida, may sementadong center turn lane ang daan. May school bus na nakahinto sa kabilang panig na nakalabas ang stop arm. Ano ang gagawin mo?","o":["Magpatuloy, dahil hinahati ng turn lane ang daan","Huminto, dahil hindi binibilang na harang ang sementadong turn lane","Dumaan gamit ang turn lane","Bumagal lang"],"h1":"Ang nakataas na harang lang o malapad na median na walang semento ang nagpapahintulot sa kabilang panig na magpatuloy.","h2":"Ang sementadong center turn lane ay hindi nakataas na harang o median na walang semento, kaya dapat huminto ang trapiko sa dalawang direksiyon para sa school bus.","p":"Tama. Hindi dahilan ang sementadong turn lane. Huminto para sa bus."},"ar":{"q":"في Florida، في وسط الطريق مسار مرصوف للانعطاف. حافلة مدرسية متوقفة على الجانب الآخر وذراع التوقف فيها مفتوح. ماذا تفعل؟","o":["أستمر، لأن مسار الانعطاف يقسم الطريق","أتوقف، لأن مسار الانعطاف المرصوف لا يُعتبر فاصلًا","أتجاوز الحافلة من مسار الانعطاف","أخفف السرعة فقط"],"h1":"فقط الحاجز المرتفع أو الفاصل العريض غير المرصوف يسمح للجانب الآخر بأن يستمر.","h2":"مسار الانعطاف المرصوف في الوسط ليس حاجزًا مرتفعًا ولا فاصلًا غير مرصوف، لذلك يجب على السيارات في الاتجاهين أن تتوقف للحافلة المدرسية.","p":"صحيح. مسار الانعطاف المرصوف لا يعفيك. توقف للحافلة."},"ht":{"q":"Nan Florida, yon wout gen yon liy pou vire nan mitan ki asfalte. Yon bis lekòl kanpe sou lòt bò a ak bra \"STOP\" li louvri. Kisa ou fè?","o":["Ou kontinye, paske liy pou vire a separe wout la","Ou kanpe, paske yon liy pou vire ki asfalte pa konte kòm separasyon","Ou pase nan liy pou vire a","Ou ralanti sèlman"],"h1":"Se sèlman yon baryè ki leve oswa yon separasyon laj ki pa asfalte ki kite lòt bò a kontinye.","h2":"Yon liy pou vire nan mitan ki asfalte pa yon baryè ki leve ni yon separasyon ki pa asfalte, kidonk machin nan de direksyon yo dwe kanpe pou bis lekòl la.","p":"Wi, se sa. Yon liy pou vire ki asfalte pa egzante ou. Kanpe pou bis la."},"ref":{"doc":"FL","page":89}},{"id":"right-of-way-026","scope":"FL","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Florida, you are driving behind a school bus on a divided highway. The bus stops and shows its stop arm. What do you do?","o":["Pass on the left","Keep going, because the highway is divided","Stop behind the bus","Pass on the right shoulder"],"h1":"The median only helps traffic on the other side.","h2":"Traffic going the same way as a stopped school bus must always stop, even on a divided highway.","p":"Right. If you are behind a stopped school bus, you always stop."},"es":{"q":"En Florida, usted maneja detrás de un autobús escolar en una carretera dividida. El autobús para y saca el brazo de pare. ¿Qué hace?","o":["Lo rebasa por la izquierda","Sigue, porque la carretera está dividida","Para detrás del autobús","Lo rebasa por el acotamiento derecho"],"h1":"La división solo ayuda al tráfico del otro lado.","h2":"El tráfico que va en la misma dirección que un autobús escolar parado siempre debe parar, aunque la carretera esté dividida.","p":"Correcto. Si va detrás de un autobús escolar parado, siempre para."},"zh":{"q":"在 Florida，你在一条分隔公路上跟在一辆校车后面。校车停下，伸出了停车臂。你该怎么做？","o":["从左边超过去","继续开，因为公路是分隔的","在校车后面停车","从右边路肩超过去"],"h1":"隔离带只对另一边的车有用。","h2":"和停着的校车同方向行驶的车永远必须停车，就算在分隔公路上也一样。","p":"对。如果你在停着的校车后面，一定要停车。"},"vi":{"q":"Ở Florida, bạn đang chạy sau một xe buýt trường học trên xa lộ có dải phân cách. Xe buýt dừng lại và giơ cần biển \"STOP\". Bạn làm gì?","o":["Vượt bên trái","Tiếp tục chạy, vì xa lộ có dải phân cách","Dừng lại phía sau xe buýt","Vượt bằng lề bên phải"],"h1":"Dải phân cách chỉ giúp xe ở phía bên kia.","h2":"Xe đi cùng hướng với xe buýt trường học đang dừng luôn phải dừng, kể cả trên xa lộ có dải phân cách.","p":"Đúng. Nếu bạn ở sau xe buýt trường học đang dừng, bạn luôn phải dừng."},"tl":{"q":"Sa Florida, nasa likod ka ng school bus sa divided highway. Huminto ang bus at inilabas ang stop arm. Ano ang gagawin mo?","o":["Lumampas sa kaliwa","Magpatuloy, dahil divided ang highway","Huminto sa likod ng bus","Lumampas sa kanang shoulder"],"h1":"Ang median ay tumutulong lang sa trapiko sa kabilang panig.","h2":"Ang trapikong papunta sa parehong direksiyon ng nakahintong school bus ay dapat laging huminto, kahit sa divided highway.","p":"Tama. Kung nasa likod ka ng nakahintong school bus, laging huminto."},"ar":{"q":"في Florida، تقود خلف حافلة مدرسية على طريق سريع مقسوم. توقفت الحافلة وفتحت ذراع التوقف. ماذا تفعل؟","o":["أتجاوزها من اليسار","أستمر، لأن الطريق السريع مقسوم","أتوقف خلف الحافلة","أتجاوزها من كتف الطريق الأيمن"],"h1":"الفاصل في الوسط يساعد فقط السيارات على الجانب الآخر.","h2":"السيارات التي تسير في نفس اتجاه الحافلة المدرسية المتوقفة يجب أن تتوقف دائمًا، حتى على طريق سريع مقسوم.","p":"صحيح. إذا كنت خلف حافلة مدرسية متوقفة، تتوقف دائمًا."},"ht":{"q":"Nan Florida, w ap kondi dèyè yon bis lekòl sou yon gran wout ki separe. Bis la kanpe epi li louvri bra \"STOP\" li. Kisa ou fè?","o":["Ou pase sou bò gòch","Ou kontinye, paske gran wout la separe","Ou kanpe dèyè bis la","Ou pase sou bò wout la adwat"],"h1":"Separasyon an ede sèlman machin ki sou lòt bò a.","h2":"Machin k ap ale nan menm direksyon ak yon bis lekòl ki kanpe dwe toujou kanpe, menm sou yon gran wout ki separe.","p":"Wi, se sa. Si ou dèyè yon bis lekòl ki kanpe, ou toujou kanpe."},"ref":{"doc":"FL","page":89}},{"id":"right-of-way-027","scope":"FL","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Florida, you stopped for a school bus. When may you start driving again?","o":["When the stop arm is pulled back and the children are clear","As soon as the door closes","After you count to ten","When the driver waves at you"],"h1":"Watch the bus signal and the children, not a timer.","h2":"You must stay stopped until the bus pulls back its stop signal and the children are out of the road.","p":"Right. Wait until the stop arm is back in and the children are clear."},"es":{"q":"En Florida, usted paró por un autobús escolar. ¿Cuándo puede volver a manejar?","o":["Cuando el brazo de pare se recoge y los niños están fuera del camino","Apenas se cierra la puerta","Después de contar hasta diez","Cuando el chofer le hace una seña"],"h1":"Fíjese en la señal del autobús y en los niños, no en el tiempo.","h2":"Usted debe quedarse parado hasta que el autobús recoja su señal de pare y los niños estén fuera de la calle.","p":"Correcto. Espere a que se recoja el brazo de pare y los niños estén a salvo."},"zh":{"q":"在 Florida，你为校车停了车。什么时候可以再开车？","o":["停车臂收回，而且小孩都离开了路面","车门一关就可以","数到十以后","司机向你挥手的时候"],"h1":"看校车的信号和小孩，不是看时间。","h2":"你必须一直停着，直到校车收回停车信号，而且小孩都离开了路面。","p":"对。等停车臂收回、小孩都离开了再走。"},"vi":{"q":"Ở Florida, bạn đã dừng cho xe buýt trường học. Khi nào bạn được chạy tiếp?","o":["Khi cần biển \"STOP\" đã thu lại và trẻ em đã ra khỏi đường","Ngay khi cửa xe buýt đóng lại","Sau khi bạn đếm đến mười","Khi tài xế xe buýt vẫy tay với bạn"],"h1":"Hãy nhìn tín hiệu của xe buýt và trẻ em, không phải đếm giờ.","h2":"Bạn phải dừng cho đến khi xe buýt thu tín hiệu dừng lại và trẻ em đã ra khỏi đường.","p":"Đúng. Hãy chờ đến khi cần biển \"STOP\" thu lại và trẻ em đã ra khỏi đường."},"tl":{"q":"Sa Florida, huminto ka para sa school bus. Kailan ka puwedeng umandar ulit?","o":["Kapag naibalik na ang stop arm at wala na ang mga bata sa daan","Pagsara pa lang ng pinto","Pagkatapos mong magbilang hanggang sampu","Kapag kinawayan ka ng drayber"],"h1":"Bantayan ang signal ng bus at ang mga bata, hindi ang orasan.","h2":"Dapat kang manatiling nakahinto hanggang maibalik ng bus ang stop signal nito at wala na ang mga bata sa daan.","p":"Tama. Maghintay hanggang maibalik ang stop arm at wala na ang mga bata sa daan."},"ar":{"q":"في Florida، توقفت لحافلة مدرسية. متى يمكنك أن تبدأ القيادة مرة أخرى؟","o":["عندما يُسحب ذراع التوقف ويبتعد الأطفال عن الطريق","مباشرة عندما يُغلق الباب","بعد أن أعدّ إلى عشرة","عندما يلوّح لي السائق"],"h1":"راقب إشارة الحافلة والأطفال، وليس الوقت.","h2":"يجب أن تبقى متوقفًا حتى تسحب الحافلة إشارة التوقف ويخرج الأطفال من الطريق.","p":"صحيح. انتظر حتى يرجع ذراع التوقف ويبتعد الأطفال."},"ht":{"q":"Nan Florida, ou te kanpe pou yon bis lekòl. Kilè ou ka kòmanse kondi ankò?","o":["Lè bra \"STOP\" la fèmen epi timoun yo fin sòti nan wout la","Depi pòt la fèmen","Apre ou fin konte jiska dis","Lè chofè a fè ou siy ak men l"],"h1":"Gade siyal bis la ak timoun yo, pa yon revèy.","h2":"Ou dwe rete kanpe jiskaske bis la fèmen siyal \"STOP\" li epi timoun yo fin sòti nan wout la.","p":"Wi, se sa. Tann bra \"STOP\" la fèmen epi timoun yo fin sòti nan wout la."},"ref":{"doc":"FL","page":89}},{"id":"right-of-way-028","scope":"FL","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Florida, the lights are flashing at a railroad crossing. Where must you stop?","o":["Right on the tracks","Between 15 and 50 feet from the nearest rail","More than 100 feet away","Within 5 feet of the nearest rail"],"h1":"You need a safe gap from the train, but not so far that you block the road behind you.","h2":"Florida law says you must stop no closer than 15 feet and no farther than 50 feet from the nearest rail when a train is coming.","p":"Right. Stop between 15 and 50 feet from the nearest rail."},"es":{"q":"En Florida, las luces están intermitentes en un cruce de tren. ¿Dónde debe parar?","o":["Encima de las vías","Entre 15 y 50 pies del riel más cercano","A más de 100 pies","A menos de 5 pies del riel más cercano"],"h1":"Necesita una distancia segura del tren, pero no tan lejos que bloquee la calle detrás de usted.","h2":"La ley de Florida dice que usted debe parar a no menos de 15 pies y no más de 50 pies del riel más cercano cuando viene un tren.","p":"Correcto. Pare entre 15 y 50 pies del riel más cercano."},"zh":{"q":"在 Florida，铁路道口的灯在闪。你必须在哪里停车？","o":["就停在铁轨上","离最近的铁轨 15 到 50 英尺之间","超过 100 英尺远","离最近的铁轨 5 英尺以内"],"h1":"你需要和火车保持安全距离，但也不能太远，挡住后面的路。","h2":"Florida 法律规定，有火车开来时，你必须停在离最近的铁轨不少于 15 英尺、不超过 50 英尺的地方。","p":"对。停在离最近的铁轨 15 到 50 英尺之间。"},"vi":{"q":"Ở Florida, đèn đang nháy tại chỗ giao nhau với đường sắt. Bạn phải dừng ở đâu?","o":["Ngay trên đường ray","Cách thanh ray gần nhất từ 15 đến 50 feet","Cách xa hơn 100 feet","Trong vòng 5 feet từ thanh ray gần nhất"],"h1":"Bạn cần khoảng cách an toàn với tàu hỏa, nhưng không quá xa để chắn đường phía sau.","h2":"Luật Florida nói khi có tàu đang đến, bạn phải dừng không gần hơn 15 feet và không xa hơn 50 feet từ thanh ray gần nhất.","p":"Đúng. Hãy dừng cách thanh ray gần nhất từ 15 đến 50 feet."},"tl":{"q":"Sa Florida, kumikislap ang mga ilaw sa railroad crossing. Saan ka dapat huminto?","o":["Mismo sa ibabaw ng riles","Sa pagitan ng 15 at 50 feet mula sa pinakamalapit na riles","Higit sa 100 feet ang layo","Sa loob ng 5 feet mula sa pinakamalapit na riles"],"h1":"Kailangan mo ng ligtas na layo mula sa tren, pero hindi gaanong malayo na mahaharangan mo ang daan sa likod mo.","h2":"Sinasabi ng batas ng Florida na kapag may paparating na tren, dapat kang huminto nang hindi lalapit sa 15 feet at hindi lalayo sa 50 feet mula sa pinakamalapit na riles.","p":"Tama. Huminto sa pagitan ng 15 at 50 feet mula sa pinakamalapit na riles."},"ar":{"q":"في Florida، الأضواء تومض عند تقاطع سكة حديد. أين يجب أن تتوقف؟","o":["على السكة نفسها","على مسافة بين 15 و50 قدمًا من أقرب قضيب","على مسافة أكثر من 100 قدم","على مسافة أقل من 5 أقدام من أقرب قضيب"],"h1":"تحتاج إلى مسافة آمنة من القطار، لكن ليس بعيدًا جدًا حتى لا تسد الطريق على من خلفك.","h2":"يقول قانون Florida إنه عندما يأتي قطار، يجب أن تتوقف على مسافة لا تقل عن 15 قدمًا ولا تزيد على 50 قدمًا من أقرب قضيب.","p":"صحيح. توقف على مسافة بين 15 و50 قدمًا من أقرب قضيب."},"ht":{"q":"Nan Florida, limyè yo ap flache nan yon kwazman tren. Ki kote ou dwe kanpe?","o":["Dirèkteman sou ray yo","Ant 15 ak 50 pye de ray ki pi pre a","Plis pase 100 pye lwen","Mwens pase 5 pye de ray ki pi pre a"],"h1":"Ou bezwen yon espas ki san danje ant ou ak tren an, men pa twò lwen pou ou pa bloke wout la dèyè ou.","h2":"Lwa Florida di lè yon tren ap vini, ou dwe kanpe pa pi pre pase 15 pye epi pa pi lwen pase 50 pye de ray ki pi pre a.","p":"Wi, se sa. Kanpe ant 15 ak 50 pye de ray ki pi pre a."},"ref":{"doc":"FL","page":56}},{"id":"right-of-way-029","scope":"FL","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Florida, the gates at a railroad crossing are down, but you do not see a train. What do you do?","o":["Drive around the gates carefully","Honk and cross slowly","Back up and look for another way, then cross","Wait until the gates go up and the lights stop"],"h1":"Trains can be closer and faster than they look.","h2":"You must never drive around lowered railroad gates, so you wait until the gates are all the way up and the lights stop flashing.","p":"Right. Never go around railroad gates. Wait until they go up."},"es":{"q":"En Florida, las barreras de un cruce de tren están abajo, pero usted no ve ningún tren. ¿Qué hace?","o":["Pasa alrededor de las barreras con cuidado","Toca la bocina y cruza despacio","Da reversa, busca otro camino y cruza","Espera hasta que suban las barreras y se apaguen las luces"],"h1":"Los trenes pueden estar más cerca y ser más rápidos de lo que parece.","h2":"Usted nunca debe pasar alrededor de las barreras bajas del tren, así que espera hasta que las barreras suban por completo y las luces dejen de parpadear.","p":"Correcto. Nunca pase alrededor de las barreras del tren. Espere a que suban."},"zh":{"q":"在 Florida，铁路道口的栏杆放下来了，但你没看到火车。你该怎么做？","o":["小心地绕过栏杆","按喇叭，慢慢开过去","倒车，找另一条路，然后过去","等栏杆升起、灯不再闪"],"h1":"火车可能比看起来更近、更快。","h2":"你永远不能绕过放下的铁路栏杆，所以要等栏杆完全升起、灯不再闪。","p":"对。永远不要绕过铁路栏杆。等它升起来。"},"vi":{"q":"Ở Florida, thanh chắn ở chỗ giao nhau với đường sắt đã hạ xuống, nhưng bạn không thấy tàu. Bạn làm gì?","o":["Lái vòng qua thanh chắn một cách cẩn thận","Bấm còi và chạy qua chậm","Lùi xe và tìm đường khác, rồi chạy qua","Chờ đến khi thanh chắn nâng lên và đèn ngừng nháy"],"h1":"Tàu có thể ở gần hơn và chạy nhanh hơn bạn nghĩ.","h2":"Bạn không bao giờ được lái vòng qua thanh chắn đường sắt đã hạ, nên bạn chờ đến khi thanh chắn nâng lên hết và đèn ngừng nháy.","p":"Đúng. Không bao giờ lái vòng qua thanh chắn đường sắt. Hãy chờ đến khi nó nâng lên."},"tl":{"q":"Sa Florida, nakababa ang mga harang sa railroad crossing, pero wala kang nakikitang tren. Ano ang gagawin mo?","o":["Maingat na umikot sa mga harang","Bumusina at dahan-dahang tumawid","Umatras at maghanap ng ibang daan, saka tumawid","Maghintay hanggang tumaas ang mga harang at tumigil ang mga ilaw"],"h1":"Maaaring mas malapit at mas mabilis ang tren kaysa sa tingin mo.","h2":"Hindi ka dapat kailanman umikot sa nakababang harang ng riles, kaya maghihintay ka hanggang tuluyang tumaas ang mga harang at tumigil sa pagkislap ang mga ilaw.","p":"Tama. Huwag kailanman umikot sa harang ng riles. Maghintay hanggang tumaas ito."},"ar":{"q":"في Florida، الحواجز عند تقاطع سكة الحديد نازلة، لكنك لا ترى قطارًا. ماذا تفعل؟","o":["ألتف حول الحواجز بحذر","أستعمل البوق وأعبر ببطء","أرجع إلى الخلف وأبحث عن طريق آخر، ثم أعبر","أنتظر حتى ترتفع الحواجز وتتوقف الأضواء"],"h1":"القطار قد يكون أقرب وأسرع مما يبدو.","h2":"لا يجوز أبدًا أن تلتف حول حواجز سكة الحديد النازلة، لذلك تنتظر حتى ترتفع الحواجز كليًا وتتوقف الأضواء عن الوميض.","p":"صحيح. لا تلتف أبدًا حول حواجز سكة الحديد. انتظر حتى ترتفع."},"ht":{"q":"Nan Florida, baryè kwazman tren an desann, men ou pa wè okenn tren. Kisa ou fè?","o":["Ou fè yon ti detou bò baryè yo avèk atansyon","Ou klaksonnen epi ou travèse dousman","Ou fè bak pou chèche yon lòt chemen, apre sa ou travèse","Ou tann baryè yo leve epi limyè yo sispann flache"],"h1":"Yon tren ka pi pre epi pi rapid pase sa ou kwè.","h2":"Ou pa dwe janm fè detou bò baryè tren ki desann, kidonk ou tann jiskaske baryè yo fin leve nèt epi limyè yo sispann flache.","p":"Wi, se sa. Pa janm fè detou bò baryè tren yo. Tann yo leve."},"ref":{"doc":"FL","page":56}},{"id":"right-of-way-030","scope":"FL","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Florida, traffic is backed up past a railroad crossing. When may you start across the tracks?","o":["When the car in front of you moves","Right away, if no train is in sight","Only when there is room for your whole car on the other side","When the driver behind you honks"],"h1":"Think about where your car will be if traffic stops again.","h2":"You may start across the tracks only when there is room for your whole vehicle on the other side, so you never get stuck on the rails.","p":"Right. Do not cross until your whole car fits on the other side."},"es":{"q":"En Florida, el tráfico está detenido más allá de un cruce de tren. ¿Cuándo puede empezar a cruzar las vías?","o":["Cuando avance el carro de adelante","De inmediato, si no se ve ningún tren","Solo cuando haya espacio para todo su carro del otro lado","Cuando el conductor de atrás toque la bocina"],"h1":"Piense dónde quedará su carro si el tráfico se detiene otra vez.","h2":"Usted puede empezar a cruzar las vías solo cuando haya espacio para todo su vehículo del otro lado, para nunca quedar atrapado sobre los rieles.","p":"Correcto. No cruce hasta que todo su carro quepa del otro lado."},"zh":{"q":"在 Florida，车流一直排到铁路道口的另一边。你什么时候可以开始过铁轨？","o":["前面的车一动就可以","马上，只要看不到火车","只有另一边有足够的空间放下你整辆车时","后面的司机按喇叭的时候"],"h1":"想一想，如果车流又停下来，你的车会在哪里。","h2":"只有另一边有足够的空间放下你整辆车时，你才可以开始过铁轨，这样你就永远不会被困在铁轨上。","p":"对。另一边放不下你整辆车时，不要过铁轨。"},"vi":{"q":"Ở Florida, xe đang kẹt kéo dài qua chỗ giao nhau với đường sắt. Khi nào bạn được bắt đầu chạy qua đường ray?","o":["Khi xe phía trước bạn chạy","Ngay lập tức, nếu không thấy tàu","Chỉ khi có đủ chỗ cho cả chiếc xe của bạn ở phía bên kia","Khi người lái phía sau bấm còi"],"h1":"Hãy nghĩ xem xe của bạn sẽ ở đâu nếu dòng xe lại dừng.","h2":"Bạn chỉ được bắt đầu chạy qua đường ray khi có đủ chỗ cho cả chiếc xe ở phía bên kia, để bạn không bao giờ bị kẹt trên đường ray.","p":"Đúng. Đừng chạy qua cho đến khi cả chiếc xe vừa chỗ ở phía bên kia."},"tl":{"q":"Sa Florida, nakapila ang trapiko hanggang lampas sa railroad crossing. Kailan ka puwedeng magsimulang tumawid sa riles?","o":["Kapag umandar ang kotse sa harap mo","Agad, kung walang tren na nakikita","Kapag may lugar lang para sa buong kotse mo sa kabilang panig","Kapag bumusina ang drayber sa likod mo"],"h1":"Isipin kung nasaan ang kotse mo kung huminto ulit ang trapiko.","h2":"Puwede kang magsimulang tumawid sa riles kapag may lugar lang para sa buong sasakyan mo sa kabilang panig, para hindi ka maipit sa ibabaw ng riles.","p":"Tama. Huwag tumawid hanggang kasya ang buong kotse mo sa kabilang panig."},"ar":{"q":"في Florida، الطريق مزدحم وطابور السيارات يصل إلى ما بعد تقاطع سكة الحديد. متى يمكنك أن تبدأ عبور السكة؟","o":["عندما تتحرك السيارة التي أمامي","فورًا، إذا لم أرَ قطارًا","فقط عندما يوجد مكان لسيارتي كلها على الجانب الآخر","عندما يستعمل السائق الذي خلفي البوق"],"h1":"فكّر أين ستكون سيارتك إذا توقفت السيارات مرة أخرى.","h2":"يمكنك أن تبدأ عبور السكة فقط عندما يوجد مكان لمركبتك كلها على الجانب الآخر، حتى لا تعلق أبدًا على القضبان.","p":"صحيح. لا تعبر حتى تجد مكانًا لسيارتك كلها على الجانب الآخر."},"ht":{"q":"Nan Florida, machin yo kanpe an liy rive pi lwen pase yon kwazman tren. Kilè ou ka kòmanse travèse ray yo?","o":["Lè machin ki devan ou a avanse","Touswit, si ou pa wè okenn tren","Sèlman lè gen plas pou tout machin ou sou lòt bò a","Lè chofè ki dèyè ou a klaksonnen"],"h1":"Panse ak ki kote machin ou ap ye si sikilasyon an kanpe ankò.","h2":"Ou ka kòmanse travèse ray yo sèlman lè gen plas pou tout machin ou sou lòt bò a, pou ou pa janm rete bloke sou ray yo.","p":"Wi, se sa. Pa travèse jiskaske tout machin ou ka antre sou lòt bò a."},"ref":{"doc":"FL","page":57}},{"id":"right-of-way-031","scope":"US","cat":"right-of-way","sign":{"shape":"crossbuck","text":"RAILROAD CROSSING"},"c":0,"en":{"q":"What does this white X-shaped sign mean?","o":["A railroad crossing. Yield to trains.","An intersection with four roads","A hospital is nearby","No parking in this area"],"h1":"This sign stands where a road meets something that cannot stop or swerve to miss you.","h2":"The white X-shaped sign, called a crossbuck, marks a railroad crossing, and you must yield to any train.","p":"Right. The crossbuck marks a railroad crossing. Yield to trains."},"es":{"q":"¿Qué significa esta señal blanca en forma de X?","o":["Un cruce de tren. Ceda el paso a los trenes.","Una intersección de cuatro calles","Hay un hospital cerca","No se permite estacionar en esta área"],"h1":"Esta señal está donde una calle se cruza con algo que no puede parar ni desviarse para no chocar con usted.","h2":"La señal blanca en forma de X, llamada crossbuck, marca un cruce de tren, y usted debe ceder el paso a cualquier tren.","p":"Correcto. La señal en X marca un cruce de tren. Ceda el paso a los trenes."},"zh":{"q":"这个白色 X 形的标志是什么意思？","o":["铁路道口。要给火车让行。","一个有四条路的路口","附近有医院","这里禁止停车"],"h1":"这个标志立在道路和一种无法停下、也无法躲开你的东西交叉的地方。","h2":"这个白色 X 形的标志叫做铁路交叉标志，它标出铁路道口，你必须给任何火车让行。","p":"对。白色 X 形标志表示铁路道口。要给火车让行。"},"vi":{"q":"Biển báo màu trắng hình chữ X này có nghĩa là gì?","o":["Chỗ giao nhau với đường sắt. Nhường đường cho tàu.","Giao lộ có bốn con đường","Gần đây có bệnh viện","Không được đậu xe ở khu vực này"],"h1":"Biển này đặt ở nơi con đường gặp một thứ không thể dừng lại hay tránh bạn.","h2":"Biển màu trắng hình chữ X, gọi là biển \"crossbuck\", đánh dấu chỗ giao nhau với đường sắt, và bạn phải nhường đường cho mọi đoàn tàu.","p":"Đúng. Biển \"crossbuck\" đánh dấu chỗ giao nhau với đường sắt. Hãy nhường tàu."},"tl":{"q":"Ano ang ibig sabihin ng puting karatulang hugis X na ito?","o":["Railroad crossing (tawiran ng tren). Magbigay-daan sa tren.","Intersection ng apat na daan","May ospital sa malapit","Bawal pumarada sa lugar na ito"],"h1":"Nakatayo ang karatulang ito kung saan nagtatagpo ang daan at isang bagay na hindi kayang huminto o umiwas sa iyo.","h2":"Ang puting karatulang hugis X, na tinatawag na crossbuck, ay nagmamarka ng railroad crossing, at dapat kang magbigay-daan sa anumang tren.","p":"Tama. Ang crossbuck ay nagmamarka ng railroad crossing. Magbigay-daan sa tren."},"ar":{"q":"ماذا تعني هذه العلامة البيضاء التي على شكل حرف X؟","o":["تقاطع سكة حديد. أعطِ حق المرور للقطارات.","تقاطع فيه أربعة طرق","يوجد مستشفى قريب","ممنوع الوقوف في هذه المنطقة"],"h1":"هذه العلامة موجودة حيث يلتقي الطريق بشيء لا يستطيع أن يتوقف أو يبتعد عنك.","h2":"العلامة البيضاء التي على شكل حرف X، واسمها crossbuck، تدل على تقاطع سكة حديد، ويجب أن تعطي حق المرور لأي قطار.","p":"صحيح. علامة crossbuck تدل على تقاطع سكة حديد. أعطِ حق المرور للقطارات."},"ht":{"q":"Kisa siy blan sa a ki gen fòm yon X vle di?","o":["Yon kwazman tren. Kite tren yo pase anvan.","Yon kafou ki gen kat wout","Gen yon lopital tou pre","Pa gen pakin nan zòn sa a"],"h1":"Siy sa a kanpe kote yon wout kwaze yon bagay ki pa ka kanpe ni vire pou evite ou.","h2":"Siy blan ki gen fòm yon X la, ki rele \"crossbuck\", make yon kwazman tren, epi ou dwe kite nenpòt tren pase anvan.","p":"Wi, se sa. Siy \"crossbuck\" la make yon kwazman tren. Kite tren yo pase anvan."},"ref":{"doc":"FL","page":56}},{"id":"right-of-way-032","scope":"US","cat":"right-of-way","sign":{"shape":"rr-advance","text":"RR"},"c":2,"en":{"q":"What does this round yellow sign with an X and the letters RR mean?","o":["A rest area is ahead","A road repair zone is ahead","A railroad crossing is ahead","You must turn right"],"h1":"This sign gives you a warning before you reach something.","h2":"The round yellow sign with an X and RR warns you that a railroad crossing is ahead, so you slow down, look, and listen.","p":"Right. The round yellow RR sign means a railroad crossing is ahead."},"es":{"q":"¿Qué significa esta señal amarilla redonda con una X y las letras RR?","o":["Hay un área de descanso adelante","Hay una zona de reparación de la calle adelante","Hay un cruce de tren adelante","Debe doblar a la derecha"],"h1":"Esta señal le avisa antes de que usted llegue a algo.","h2":"La señal amarilla redonda con una X y RR le avisa que hay un cruce de tren adelante, así que baje la velocidad, mire y escuche.","p":"Correcto. La señal amarilla redonda con RR significa cruce de tren adelante."},"zh":{"q":"这个圆形黄色、上面有一个 X 和字母 \"RR\" 的标志是什么意思？","o":["前面有休息区","前面有道路维修区","前面有铁路道口","你必须右转"],"h1":"这个标志是在你到达某个地方之前给你的警告。","h2":"这个圆形黄色、有 X 和 \"RR\" 的标志警告你前面有铁路道口，所以你要减速，看一看，听一听。","p":"对。圆形黄色的 \"RR\" 标志表示前面有铁路道口。"},"vi":{"q":"Biển báo tròn màu vàng có chữ X và hai chữ \"RR\" này có nghĩa là gì?","o":["Phía trước có trạm dừng nghỉ","Phía trước có khu vực sửa đường","Phía trước có chỗ giao nhau với đường sắt","Bạn phải rẽ phải"],"h1":"Biển này cảnh báo bạn trước khi bạn đến một nơi nào đó.","h2":"Biển tròn màu vàng có chữ X và \"RR\" cảnh báo phía trước có chỗ giao nhau với đường sắt, nên bạn giảm tốc, nhìn và lắng nghe.","p":"Đúng. Biển tròn màu vàng \"RR\" có nghĩa là phía trước có đường sắt."},"tl":{"q":"Ano ang ibig sabihin ng bilog na dilaw na karatulang ito na may X at mga letrang RR?","o":["May rest area sa unahan","May lugar ng pagkukumpuni ng daan sa unahan","May railroad crossing sa unahan","Dapat kang kumanan"],"h1":"Binabalaan ka ng karatulang ito bago ka dumating sa isang bagay.","h2":"Binabalaan ka ng bilog na dilaw na karatulang may X at RR na may railroad crossing sa unahan, kaya babagal ka, titingin, at makikinig.","p":"Tama. Ang bilog na dilaw na karatulang RR ay nangangahulugang may railroad crossing sa unahan."},"ar":{"q":"ماذا تعني هذه العلامة الصفراء المستديرة التي عليها X والحرفان \"RR\"؟","o":["توجد استراحة أمامك","توجد منطقة إصلاح طريق أمامك","يوجد تقاطع سكة حديد أمامك","يجب أن تنعطف يمينًا"],"h1":"هذه العلامة تحذرك قبل أن تصل إلى شيء ما.","h2":"العلامة الصفراء المستديرة التي عليها X و\"RR\" تحذرك أن تقاطع سكة حديد أمامك، لذلك تخفف السرعة وتنظر وتسمع.","p":"صحيح. العلامة الصفراء المستديرة \"RR\" تعني أن تقاطع سكة حديد أمامك."},"ht":{"q":"Kisa siy jòn won sa a ki gen yon X ak lèt \"RR\" yo vle di?","o":["Gen yon zòn repo devan","Gen yon zòn reparasyon wout devan","Gen yon kwazman tren devan","Ou dwe vire adwat"],"h1":"Siy sa a avèti ou anvan ou rive nan yon bagay.","h2":"Siy jòn won ki gen yon X ak \"RR\" a avèti ou gen yon kwazman tren devan, kidonk ou ralanti, ou gade epi ou koute.","p":"Wi, se sa. Siy jòn won \"RR\" a vle di gen yon kwazman tren devan."},"ref":{"doc":"FL","page":56}},{"id":"right-of-way-033","scope":"FL","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Florida, you want to turn right. Which lane should you be in?","o":["The left lane","The right lane, close to the curb","The center lane","Any lane, if you signal"],"h1":"Pick the lane on the same side as your turn.","h2":"To turn right, you get into the right lane near the curb and turn into the right lane of the new street.","p":"Right. Turn right from the right lane, near the curb."},"es":{"q":"En Florida, usted quiere doblar a la derecha. ¿En qué carril debe estar?","o":["En el carril izquierdo","En el carril derecho, cerca de la orilla","En el carril del centro","En cualquier carril, si pone la direccional"],"h1":"Escoja el carril del mismo lado de su vuelta.","h2":"Para doblar a la derecha, usted se coloca en el carril derecho cerca de la orilla y dobla al carril derecho de la nueva calle.","p":"Correcto. Doble a la derecha desde el carril derecho, cerca de la orilla."},"zh":{"q":"在 Florida，你想右转。你应该在哪条车道？","o":["左边车道","右边车道，靠近路缘","中间车道","哪条车道都行，只要打转向灯"],"h1":"选和你转弯方向同一边的车道。","h2":"要右转，你应该进入靠近路缘的右边车道，然后转进新街道的右边车道。","p":"对。从靠近路缘的右边车道右转。"},"vi":{"q":"Ở Florida, bạn muốn rẽ phải. Bạn nên ở làn nào?","o":["Làn bên trái","Làn bên phải, sát lề đường","Làn ở giữa","Làn nào cũng được, nếu bạn bật xi nhan"],"h1":"Hãy chọn làn ở cùng phía với hướng bạn rẽ.","h2":"Để rẽ phải, bạn vào làn bên phải gần lề đường và rẽ vào làn bên phải của con đường mới.","p":"Đúng. Rẽ phải từ làn bên phải, sát lề đường."},"tl":{"q":"Sa Florida, gusto mong kumanan. Saang lane ka dapat naroon?","o":["Sa kaliwang lane","Sa kanang lane, malapit sa curb (gilid ng bangketa)","Sa gitnang lane","Kahit anong lane, basta mag-signal ka"],"h1":"Piliin ang lane na nasa parehong panig ng liko mo.","h2":"Para kumanan, pumunta ka sa kanang lane malapit sa curb at kumanan papunta sa kanang lane ng bagong kalye.","p":"Tama. Kumanan mula sa kanang lane, malapit sa curb."},"ar":{"q":"في Florida، تريد أن تنعطف يمينًا. في أي مسار يجب أن تكون؟","o":["المسار الأيسر","المسار الأيمن، قريبًا من الرصيف","المسار الأوسط","أي مسار، إذا استعملت الإشارة"],"h1":"اختر المسار الذي في جهة انعطافك نفسها.","h2":"لكي تنعطف يمينًا، تدخل المسار الأيمن قرب الرصيف، وتنعطف إلى المسار الأيمن في الشارع الجديد.","p":"صحيح. انعطف يمينًا من المسار الأيمن، قرب الرصيف."},"ht":{"q":"Nan Florida, ou vle vire adwat. Nan ki liy ou ta dwe ye?","o":["Liy gòch la","Liy dwat la, pre rebò twotwa a","Liy mitan an","Nenpòt liy, si ou mete siyal"],"h1":"Chwazi liy ki sou menm bò ak kote w ap vire a.","h2":"Pou vire adwat, ou antre nan liy dwat la pre rebò twotwa a, epi ou vire nan liy dwat lari kote w ap antre a.","p":"Wi, se sa. Vire adwat sòti nan liy dwat la, pre rebò twotwa a."},"ref":{"doc":"FL","page":70}},{"id":"right-of-way-034","scope":"FL","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Florida, you turn left from a two-way street onto another two-way street. Which lane do you turn into?","o":["The bike lane","The lane for oncoming traffic","The center turn lane","Any lane going your way that you may legally use"],"h1":"Think about which lanes carry traffic in your direction.","h2":"When you turn left, you may finish in any lane going your way that you are allowed to use, and you never enter a lane for oncoming traffic.","p":"Right. Turn left into a lane going your way that you may legally use."},"es":{"q":"En Florida, usted dobla a la izquierda de una calle de doble sentido a otra calle de doble sentido. ¿A qué carril dobla?","o":["Al carril de bicicletas","Al carril del tráfico que viene de frente","Al carril central de vuelta","A cualquier carril en su misma dirección que usted pueda usar legalmente"],"h1":"Piense en qué carriles llevan el tráfico en su misma dirección.","h2":"Cuando usted dobla a la izquierda, puede terminar en cualquier carril en su misma dirección que tenga permitido usar, y nunca entra a un carril del tráfico que viene de frente.","p":"Correcto. Doble a la izquierda a un carril en su misma dirección que usted pueda usar legalmente."},"zh":{"q":"在 Florida，你从一条双向街道左转到另一条双向街道。你应该转进哪条车道？","o":["自行车道","对面来车的车道","中央转弯车道","任何和你同方向、而且你可以合法使用的车道"],"h1":"想一想哪些车道上的车和你同一个方向。","h2":"左转时，你可以转进任何和你同方向、而且你可以使用的车道，但永远不能进入对面来车的车道。","p":"对。左转进入和你同方向、你可以合法使用的车道。"},"vi":{"q":"Ở Florida, bạn rẽ trái từ một đường hai chiều sang một đường hai chiều khác. Bạn rẽ vào làn nào?","o":["Làn xe đạp","Làn của xe đi ngược chiều","Làn rẽ ở giữa","Bất kỳ làn nào cùng chiều với bạn mà bạn được phép dùng"],"h1":"Hãy nghĩ xem làn nào có xe chạy cùng hướng với bạn.","h2":"Khi rẽ trái, bạn có thể vào bất kỳ làn nào cùng chiều mà bạn được phép dùng, và bạn không bao giờ đi vào làn của xe ngược chiều.","p":"Đúng. Rẽ trái vào làn cùng chiều mà bạn được phép dùng."},"tl":{"q":"Sa Florida, kumaliwa ka mula sa kalyeng two-way papunta sa isa pang kalyeng two-way. Saang lane ka papasok?","o":["Sa bike lane","Sa lane ng paparating na trapiko","Sa center turn lane","Sa kahit anong lane na papunta sa direksiyon mo na legal mong magagamit"],"h1":"Isipin kung aling mga lane ang may trapiko sa direksiyon mo.","h2":"Kapag kumaliwa ka, puwede kang pumasok sa kahit anong lane na papunta sa direksiyon mo na pinapayagan kang gamitin, at hindi ka kailanman papasok sa lane ng paparating na trapiko.","p":"Tama. Kumaliwa papunta sa lane na papunta sa direksiyon mo na legal mong magagamit."},"ar":{"q":"في Florida، تنعطف يسارًا من شارع باتجاهين إلى شارع آخر باتجاهين. إلى أي مسار تنعطف؟","o":["مسار الدراجات","مسار السيارات القادمة نحوك","مسار الانعطاف في الوسط","أي مسار في اتجاهك يُسمح لك باستعماله"],"h1":"فكّر في المسارات التي تسير فيها السيارات في اتجاهك.","h2":"عندما تنعطف يسارًا، يمكنك أن تنهي الانعطاف في أي مسار في اتجاهك يُسمح لك باستعماله، ولا تدخل أبدًا مسار السيارات القادمة نحوك.","p":"صحيح. انعطف يسارًا إلى مسار في اتجاهك يُسمح لك قانونيًا باستعماله."},"ht":{"q":"Nan Florida, ou vire agòch sòti nan yon lari de sans pou antre nan yon lòt lari de sans. Nan ki liy ou antre?","o":["Liy pou bisiklèt la","Liy pou machin k ap vin sou ou yo","Liy pou vire nan mitan an","Nenpòt liy k ap ale nan direksyon pa w la ou gen dwa sèvi ak li"],"h1":"Panse ak ki liy ki pote machin nan direksyon pa w la.","h2":"Lè ou vire agòch, ou ka fini nan nenpòt liy k ap ale nan direksyon pa w la ou gen dwa sèvi ak li, epi ou pa janm antre nan yon liy pou machin k ap vin sou ou.","p":"Wi, se sa. Vire agòch nan yon liy k ap ale nan direksyon pa w la ou gen dwa sèvi ak li."},"ref":{"doc":"FL","page":70}},{"id":"right-of-way-035","scope":"FL","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Florida, how far before a turn should you turn on your signal?","o":["Only as you start to turn","At least 10 feet before","At least 25 feet before","At least 100 feet before"],"h1":"Other drivers need time to see what you plan to do.","h2":"In Florida you should signal at least 100 feet before you turn, so drivers and people walking know what you will do.","p":"Right. Signal at least 100 feet before you turn."},"es":{"q":"En Florida, ¿con cuánta anticipación debe poner la direccional antes de doblar?","o":["Solo cuando empieza a doblar","Por lo menos 10 pies antes","Por lo menos 25 pies antes","Por lo menos 100 pies antes"],"h1":"Los otros conductores necesitan tiempo para ver lo que usted va a hacer.","h2":"En Florida usted debe poner la direccional por lo menos 100 pies antes de doblar, para que los conductores y los peatones sepan lo que va a hacer.","p":"Correcto. Ponga la direccional por lo menos 100 pies antes de doblar."},"zh":{"q":"在 Florida，转弯前多远应该打开转向灯？","o":["只在开始转弯的时候","至少提前 10 英尺","至少提前 25 英尺","至少提前 100 英尺"],"h1":"其他司机需要时间看清你要做什么。","h2":"在 Florida，你应该在转弯前至少 100 英尺打转向灯，让司机和行人知道你要做什么。","p":"对。转弯前至少 100 英尺打转向灯。"},"vi":{"q":"Ở Florida, bạn nên bật xi nhan bao xa trước khi rẽ?","o":["Chỉ khi bạn bắt đầu rẽ","Ít nhất 10 feet trước đó","Ít nhất 25 feet trước đó","Ít nhất 100 feet trước đó"],"h1":"Người lái khác cần thời gian để thấy bạn định làm gì.","h2":"Ở Florida, bạn nên bật xi nhan ít nhất 100 feet trước khi rẽ, để người lái và người đi bộ biết bạn sẽ làm gì.","p":"Đúng. Hãy bật xi nhan ít nhất 100 feet trước khi rẽ."},"tl":{"q":"Sa Florida, gaano kalayo bago lumiko dapat mong buksan ang signal mo?","o":["Habang nagsisimula ka lang lumiko","Hindi bababa sa 10 feet bago lumiko","Hindi bababa sa 25 feet bago lumiko","Hindi bababa sa 100 feet bago lumiko"],"h1":"Kailangan ng ibang drayber ng oras para makita ang balak mong gawin.","h2":"Sa Florida, dapat kang mag-signal nang hindi bababa sa 100 feet bago ka lumiko, para malaman ng mga drayber at ng mga naglalakad ang gagawin mo.","p":"Tama. Mag-signal nang hindi bababa sa 100 feet bago ka lumiko."},"ar":{"q":"في Florida، قبل الانعطاف بكم مسافة يجب أن تشغّل إشارة الانعطاف؟","o":["فقط عندما أبدأ الانعطاف","10 أقدام على الأقل قبله","25 قدمًا على الأقل قبله","100 قدم على الأقل قبله"],"h1":"السائقون الآخرون يحتاجون إلى وقت ليروا ماذا تريد أن تفعل.","h2":"في Florida يجب أن تشغّل الإشارة قبل الانعطاف بمسافة 100 قدم على الأقل، حتى يعرف السائقون والمشاة ماذا ستفعل.","p":"صحيح. شغّل الإشارة قبل الانعطاف بمسافة 100 قدم على الأقل."},"ht":{"q":"Nan Florida, a ki distans anvan yon vire ou ta dwe limen siyal ou?","o":["Sèlman lè w ap kòmanse vire","Omwen 10 pye anvan","Omwen 25 pye anvan","Omwen 100 pye anvan"],"h1":"Lòt chofè yo bezwen tan pou yo wè sa ou vle fè.","h2":"Nan Florida ou ta dwe mete siyal omwen 100 pye anvan ou vire, pou chofè yo ak moun k ap mache yo konnen sa ou pral fè.","p":"Wi, se sa. Mete siyal omwen 100 pye anvan ou vire."},"ref":{"doc":"FL","page":69}},{"id":"right-of-way-036","scope":"FL","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Florida, when may you make a U-turn?","o":["Any time you miss your street","Only when it is safe and no sign forbids it","Only on a highway","Only at a railroad crossing"],"h1":"Think about signs and about traffic around you.","h2":"You may make a U-turn only where no sign forbids it and only when you can do it safely without getting in the way of other traffic.","p":"Right. Make a U-turn only when it is safe and allowed."},"es":{"q":"En Florida, ¿cuándo puede dar una vuelta en U?","o":["Cada vez que se pase de su calle","Solo cuando es seguro y ninguna señal lo prohíbe","Solo en la autopista","Solo en un cruce de tren"],"h1":"Piense en las señales y en el tráfico a su alrededor.","h2":"Usted puede dar una vuelta en U solo donde ninguna señal lo prohíba y solo cuando pueda hacerla con seguridad, sin estorbar a otros vehículos.","p":"Correcto. Dé vuelta en U solo cuando sea seguro y permitido."},"zh":{"q":"在 Florida，什么时候可以掉头（U-turn）？","o":["每次错过你要去的街道时","只有在安全、而且没有标志禁止时","只在高速公路上","只在铁路道口"],"h1":"想一想标志，也想一想你周围的车。","h2":"只有在没有标志禁止的地方，而且你能安全掉头、不妨碍其他车辆时，你才可以掉头。","p":"对。只有在安全而且允许的时候才掉头。"},"vi":{"q":"Ở Florida, khi nào bạn được quay đầu xe hình chữ U?","o":["Bất cứ lúc nào bạn đi lố con đường của mình","Chỉ khi an toàn và không có biển báo cấm","Chỉ trên xa lộ","Chỉ ở chỗ giao nhau với đường sắt"],"h1":"Hãy nghĩ đến biển báo và xe cộ xung quanh bạn.","h2":"Bạn chỉ được quay đầu chữ U ở nơi không có biển báo cấm và chỉ khi bạn làm được một cách an toàn mà không cản trở xe khác.","p":"Đúng. Chỉ quay đầu chữ U khi an toàn và được phép."},"tl":{"q":"Sa Florida, kailan ka puwedeng mag-U-turn?","o":["Anumang oras na nalampasan mo ang kalye mo","Kapag ligtas lang at walang karatulang nagbabawal","Sa highway lang","Sa railroad crossing lang"],"h1":"Isipin ang mga karatula at ang trapiko sa paligid mo.","h2":"Puwede ka lang mag-U-turn kung walang karatulang nagbabawal nito at kung magagawa mo ito nang ligtas, nang hindi nakaharang sa ibang trapiko.","p":"Tama. Mag-U-turn lang kapag ligtas at pinapayagan."},"ar":{"q":"في Florida، متى يمكنك أن تقوم بدوران كامل للخلف (U-turn)؟","o":["في أي وقت عندما يفوتني الشارع","فقط عندما يكون آمنًا ولا توجد علامة تمنعه","فقط على الطريق السريع","فقط عند تقاطع سكة حديد"],"h1":"فكّر في العلامات وفي السيارات حولك.","h2":"يمكنك أن تقوم بدوران كامل للخلف فقط حيث لا توجد علامة تمنعه، وفقط عندما تستطيع أن تقوم به بأمان بدون أن تعيق السيارات الأخرى.","p":"صحيح. قم بالدوران الكامل للخلف فقط عندما يكون آمنًا ومسموحًا."},"ht":{"q":"Nan Florida, kilè ou ka fè yon demi-tou (U-turn)?","o":["Nenpòt lè ou rate lari ou a","Sèlman lè li pa danjere epi pa gen okenn siy ki entèdi l","Sèlman sou yon gran wout","Sèlman nan yon kwazman tren"],"h1":"Panse ak siy yo ak machin ki bò kote ou yo.","h2":"Ou ka fè yon demi-tou sèlman kote pa gen okenn siy ki entèdi l epi sèlman lè ou ka fè l san danje san ou pa jennen lòt machin yo.","p":"Wi, se sa. Fè yon demi-tou sèlman lè li pa danjere epi li pèmèt."},"ref":{"doc":"FL","page":47}},{"id":"right-of-way-037","scope":"FL","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Florida, you stopped at a red light and want to turn right. A person is crossing in front of you. What do you do?","o":["Turn now, because right on red is allowed","Honk and turn","Wait for the person to cross, then turn when traffic is clear","Turn into the far lane to go around the person"],"h1":"A right turn on red is allowed only after you yield.","h2":"When you turn right on red, you must first stop and yield to people crossing and to traffic, so you wait until the way is clear.","p":"Right. On red, yield to people and traffic before you turn right."},"es":{"q":"En Florida, usted paró en una luz roja y quiere doblar a la derecha. Una persona está cruzando delante de usted. ¿Qué hace?","o":["Dobla ahora, porque se permite doblar a la derecha en rojo","Toca la bocina y dobla","Espera que la persona cruce y luego dobla cuando el tráfico esté libre","Dobla al carril lejano para pasar alrededor de la persona"],"h1":"Doblar a la derecha en rojo se permite solo después de ceder el paso.","h2":"Cuando usted dobla a la derecha en rojo, primero debe parar y ceder el paso a las personas que cruzan y al tráfico, así que espera hasta que el camino esté libre.","p":"Correcto. En rojo, ceda el paso a peatones y tráfico antes de doblar a la derecha."},"zh":{"q":"在 Florida，你在红灯前停下，想右转。有一个人正在你前面过马路。你该怎么做？","o":["现在就转，因为红灯可以右转","按喇叭，然后转","等这个人过完马路，路上没车了再转","转进最远的车道，绕过这个人"],"h1":"红灯右转只有在你让行以后才可以。","h2":"红灯右转时，你必须先停车，让过马路的人和其他车先走，所以要等路上安全了再转。","p":"对。红灯右转前，先让行人和车辆走。"},"vi":{"q":"Ở Florida, bạn đã dừng ở đèn đỏ và muốn rẽ phải. Có người đang băng qua đường trước mặt bạn. Bạn làm gì?","o":["Rẽ ngay, vì được phép rẽ phải khi đèn đỏ","Bấm còi và rẽ","Chờ người đó qua hết, rồi rẽ khi không có xe","Rẽ vào làn xa để vòng qua người đó"],"h1":"Rẽ phải khi đèn đỏ chỉ được phép sau khi bạn đã nhường đường.","h2":"Khi rẽ phải lúc đèn đỏ, trước tiên bạn phải dừng lại và nhường người đi bộ và xe cộ, nên bạn chờ đến khi đường trống.","p":"Đúng. Khi đèn đỏ, hãy nhường người đi bộ và xe cộ trước khi rẽ phải."},"tl":{"q":"Sa Florida, huminto ka sa pulang ilaw at gusto mong kumanan. May taong tumatawid sa harap mo. Ano ang gagawin mo?","o":["Kumanan na, dahil pinapayagan ang pagkanan sa pula","Bumusina at kumanan","Hintaying makatawid ang tao, saka kumanan kapag malinis na ang trapiko","Kumanan papunta sa malayong lane para iwasan ang tao"],"h1":"Pinapayagan ang pagkanan sa pula pagkatapos mo lang magbigay-daan.","h2":"Kapag kumakanan ka sa pula, dapat ka munang huminto at magbigay-daan sa mga tumatawid at sa trapiko, kaya maghihintay ka hanggang malinis ang daan.","p":"Tama. Sa pula, magbigay-daan sa mga tao at trapiko bago ka kumanan."},"ar":{"q":"في Florida، توقفت عند إشارة حمراء وتريد أن تنعطف يمينًا. شخص يعبر أمامك. ماذا تفعل؟","o":["أنعطف الآن، لأن الانعطاف يمينًا عند الإشارة الحمراء مسموح","أستعمل البوق وأنعطف","أنتظر حتى يعبر الشخص، ثم أنعطف عندما يكون الطريق فارغًا","أنعطف إلى المسار البعيد لألتف حول الشخص"],"h1":"الانعطاف يمينًا عند الإشارة الحمراء مسموح فقط بعد أن تعطي حق المرور.","h2":"عندما تنعطف يمينًا عند الإشارة الحمراء، يجب أولًا أن تتوقف وتعطي حق المرور للمشاة وللسيارات، لذلك تنتظر حتى يصبح الطريق فارغًا.","p":"صحيح. عند الإشارة الحمراء، أعطِ حق المرور للناس وللسيارات قبل أن تنعطف يمينًا."},"ht":{"q":"Nan Florida, ou kanpe nan yon limyè wouj epi ou vle vire adwat. Gen yon moun k ap travèse devan ou. Kisa ou fè?","o":["Ou vire kounye a, paske yo pèmèt vire adwat sou limyè wouj","Ou klaksonnen epi ou vire","Ou tann moun nan travèse, apre sa ou vire lè pa gen machin","Ou vire nan liy ki pi lwen an pou ou pase bò kote moun nan"],"h1":"Yo pèmèt ou vire adwat sou limyè wouj sèlman apre ou fin kite lòt yo pase.","h2":"Lè ou vire adwat sou limyè wouj, ou dwe kanpe anvan epi kite moun k ap travèse yo ak machin yo pase, kidonk ou tann jiskaske chemen an lib.","p":"Wi, se sa. Sou limyè wouj, kite moun yo ak machin yo pase anvan ou vire adwat."},"ref":{"doc":"FL","page":51}},{"id":"right-of-way-038","scope":"US","cat":"right-of-way","sign":{"shape":"yield","text":"YIELD"},"c":2,"en":{"q":"What does this red and white upside-down triangle sign tell you to do?","o":["Stop fully every time","Speed up and merge","Slow down and let other traffic go first, stopping if needed","Turn around"],"h1":"This sign does not always mean a full stop.","h2":"A yield sign means you slow down and let other traffic and people go first, and you stop only if you need to.","p":"Right. A yield sign means slow down and let others go first."},"es":{"q":"¿Qué le indica esta señal de triángulo rojo y blanco con la punta hacia abajo?","o":["Pare por completo siempre","Acelere y únase al tráfico","Baje la velocidad y deje pasar primero a los demás, parando si hace falta","Dé la vuelta"],"h1":"Esta señal no siempre significa un alto total.","h2":"Una señal de ceda el paso significa que usted baja la velocidad y deja pasar primero a otros vehículos y personas, y para solo si es necesario.","p":"Correcto. Ceda el paso significa bajar la velocidad y dejar pasar a los demás."},"zh":{"q":"这个红白色、倒三角形的标志告诉你要做什么？","o":["每次都要完全停车","加速并入车流","减速，让其他车先走，需要时停车","掉头"],"h1":"这个标志不一定是要你完全停车。","h2":"让行标志的意思是你要减速，让其他车和行人先走，只有在需要时才停车。","p":"对。让行标志的意思是减速，让别人先走。"},"vi":{"q":"Biển báo hình tam giác ngược màu đỏ và trắng này bảo bạn làm gì?","o":["Luôn luôn dừng hẳn","Tăng tốc và nhập làn","Giảm tốc và để xe khác đi trước, dừng lại nếu cần","Quay đầu xe"],"h1":"Biển này không phải lúc nào cũng có nghĩa là dừng hẳn.","h2":"Biển \"YIELD\" (Nhường đường) có nghĩa là bạn giảm tốc và để xe khác và người đi bộ đi trước, và bạn chỉ dừng lại nếu cần.","p":"Đúng. Biển \"YIELD\" có nghĩa là giảm tốc và để người khác đi trước."},"tl":{"q":"Ano ang sinasabi sa iyo ng pula at puting baligtad na tatsulok na karatulang ito?","o":["Huminto nang buo sa bawat pagkakataon","Bumilis at sumanib sa trapiko","Bumagal at paunahin ang ibang trapiko, at huminto kung kailangan","Umikot pabalik"],"h1":"Hindi laging buong paghinto ang ibig sabihin ng karatulang ito.","h2":"Ang \"YIELD\" sign (magbigay-daan) ay nangangahulugang babagal ka at paunahin ang ibang trapiko at mga tao, at hihinto ka lang kung kailangan.","p":"Tama. Ang \"YIELD\" sign ay nangangahulugang bumagal at paunahin ang iba."},"ar":{"q":"هذه العلامة مثلث أحمر وأبيض مقلوب. ماذا تطلب منك أن تفعل؟","o":["أتوقف توقفًا كاملًا كل مرة","أسرع وأندمج","أخفف السرعة وأترك السيارات الأخرى تمر أولًا، وأتوقف إذا لزم الأمر","أرجع من حيث جئت"],"h1":"هذه العلامة لا تعني دائمًا توقفًا كاملًا.","h2":"علامة \"YIELD\" (أعطِ حق المرور) تعني أن تخفف السرعة وتترك السيارات الأخرى والمشاة يمرون أولًا، وتتوقف فقط إذا احتجت إلى ذلك.","p":"صحيح. علامة \"YIELD\" (أعطِ حق المرور) تعني: خفف السرعة واترك الآخرين يمرون أولًا."},"ht":{"q":"Kisa siy wouj e blan sa a ki gen fòm yon triyang tèt anba di ou fè?","o":["Kanpe nèt chak fwa","Akselere epi antre nan sikilasyon an","Ralanti epi kite lòt machin yo pase anvan, kanpe si sa nesesè","Fè demi-tou"],"h1":"Siy sa a pa toujou vle di kanpe nèt.","h2":"Yon siy \"YIELD\" (kite pase) vle di ou ralanti epi ou kite lòt machin ak moun yo pase anvan, epi ou kanpe sèlman si ou bezwen.","p":"Wi, se sa. Yon siy \"YIELD\" vle di ralanti epi kite lòt yo pase anvan."},"ref":{"doc":"FL","page":47}},{"id":"right-of-way-039","scope":"FL","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Florida, you are on a ramp joining a highway. Who has the right of way?","o":["Traffic already on the highway","You, because you are on the ramp","The faster car","Whoever signals first"],"h1":"Think about who is already on the main road.","h2":"When you merge onto a highway, you must yield to the traffic already on it and find a safe gap.","p":"Right. When merging, yield to traffic already on the highway."},"es":{"q":"En Florida, usted va por una rampa para entrar a una carretera. ¿Quién tiene el derecho de paso?","o":["El tráfico que ya va por la carretera","Usted, porque va por la rampa","El carro más rápido","El que pone la direccional primero"],"h1":"Piense en quién ya está en la vía principal.","h2":"Cuando usted entra a una carretera, debe ceder el paso al tráfico que ya va por ella y buscar un espacio seguro.","p":"Correcto. Al entrar a la carretera, ceda el paso al tráfico que ya va por ella."},"zh":{"q":"在 Florida，你在匝道上，准备并入高速公路。谁有先行权？","o":["已经在高速公路上的车","你，因为你在匝道上","开得快的车","先打转向灯的人"],"h1":"想一想谁已经在主路上。","h2":"并入高速公路时，你必须让已经在高速公路上的车先走，并找到一个安全的空隙。","p":"对。并入时，让已经在高速公路上的车先走。"},"vi":{"q":"Ở Florida, bạn đang ở trên đường dẫn để nhập vào xa lộ. Ai có quyền ưu tiên?","o":["Xe đã ở trên xa lộ","Bạn, vì bạn đang ở trên đường dẫn","Xe chạy nhanh hơn","Người bật xi nhan trước"],"h1":"Hãy nghĩ xem ai đã ở trên đường chính rồi.","h2":"Khi nhập vào xa lộ, bạn phải nhường xe đã ở trên xa lộ và tìm khoảng trống an toàn.","p":"Đúng. Khi nhập làn, hãy nhường xe đã ở trên xa lộ."},"tl":{"q":"Sa Florida, nasa ramp ka papasok sa highway. Sino ang may karapatan sa daan?","o":["Ang trapikong nasa highway na","Ikaw, dahil nasa ramp ka","Ang mas mabilis na kotse","Kung sino ang unang mag-signal"],"h1":"Isipin kung sino na ang nasa pangunahing daan.","h2":"Kapag sumasanib ka sa highway, dapat kang magbigay-daan sa trapikong nasa highway na at maghanap ng ligtas na puwang.","p":"Tama. Kapag sumasanib, magbigay-daan sa trapikong nasa highway na."},"ar":{"q":"في Florida، أنت على منحدر الدخول إلى طريق سريع. من له حق المرور؟","o":["السيارات الموجودة على الطريق السريع","أنت، لأنك على منحدر الدخول","السيارة الأسرع","من يشغّل الإشارة أولًا"],"h1":"فكّر في من هو موجود الآن على الطريق الرئيسي.","h2":"عندما تندمج في طريق سريع، يجب أن تعطي حق المرور للسيارات الموجودة عليه وتجد مسافة آمنة.","p":"صحيح. عند الاندماج، أعطِ حق المرور للسيارات الموجودة على الطريق السريع."},"ht":{"q":"Nan Florida, ou sou yon ranp k ap antre sou yon gran wout. Kiyès ki gen dwa pou pase anvan?","o":["Machin ki deja sou gran wout la","Ou menm, paske ou sou ranp lan","Machin ki pi vit la","Moun ki mete siyal an premye a"],"h1":"Panse ak kiyès ki deja sou wout prensipal la.","h2":"Lè w ap antre sou yon gran wout, ou dwe kite machin ki deja sou li yo pase anvan epi chèche yon espas ki san danje.","p":"Wi, se sa. Lè w ap antre, kite machin ki deja sou gran wout la pase anvan."},"ref":{"doc":"FL","page":63}},{"id":"safe-driving-001","scope":"FL","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Florida, how much space must you leave when you pass a bicycle?","o":["At least 1 foot","At least 2 feet","At least 3 feet","At least 10 feet"],"h1":"Think about a safe gap between your car and the rider.","h2":"Florida law says you must leave at least 3 feet between your car and a bicycle when you pass it.","p":"Right. Give a bicycle at least 3 feet when you pass."},"es":{"q":"En Florida, ¿cuánto espacio debe dejar al rebasar una bicicleta?","o":["Al menos 1 pie","Al menos 2 pies","Al menos 3 pies","Al menos 10 pies"],"h1":"Piense en un espacio seguro entre su carro y el ciclista.","h2":"La ley de Florida dice que debe dejar al menos 3 pies entre su carro y una bicicleta cuando la rebasa.","p":"Correcto. Deje al menos 3 pies al rebasar una bicicleta."},"zh":{"q":"在 Florida，你超过自行车时必须留出多少空间？","o":["至少 1 英尺","至少 2 英尺","至少 3 英尺","至少 10 英尺"],"h1":"想一想你的车和骑车人之间安全的距离。","h2":"Florida 法律规定，你超过自行车时，你的车和自行车之间必须留出至少 3 英尺。","p":"对。超过自行车时，至少留出 3 英尺。"},"vi":{"q":"Ở Florida, khi vượt qua xe đạp, bạn phải chừa khoảng cách bao nhiêu?","o":["Ít nhất 1 foot","Ít nhất 2 feet","Ít nhất 3 feet","Ít nhất 10 feet"],"h1":"Hãy nghĩ đến một khoảng trống an toàn giữa xe bạn và người đi xe đạp.","h2":"Luật Florida nói rằng bạn phải chừa ít nhất 3 feet giữa xe bạn và xe đạp khi vượt qua.","p":"Đúng. Chừa cho xe đạp ít nhất 3 feet khi bạn vượt qua."},"tl":{"q":"Sa Florida, gaano kalaking espasyo ang dapat mong iwan kapag nag-overtake ka sa bisikleta?","o":["Hindi bababa sa 1 foot","Hindi bababa sa 2 feet","Hindi bababa sa 3 feet","Hindi bababa sa 10 feet"],"h1":"Isipin ang ligtas na pagitan ng kotse mo at ng nagbibisikleta.","h2":"Sinasabi ng batas ng Florida na dapat kang mag-iwan ng hindi bababa sa 3 feet sa pagitan ng kotse mo at ng bisikleta kapag nag-overtake ka rito.","p":"Tama. Bigyan ang bisikleta ng hindi bababa sa 3 feet kapag nag-overtake ka."},"ar":{"q":"في Florida، كم مسافة يجب أن تترك عندما تتجاوز دراجة هوائية؟","o":["قدم واحدة (1 foot) على الأقل","2 قدم (feet) على الأقل","3 أقدام (feet) على الأقل","10 أقدام (feet) على الأقل"],"h1":"فكّر في مسافة آمنة بين سيارتك وراكب الدراجة.","h2":"قانون Florida يقول إنه يجب أن تترك 3 أقدام (feet) على الأقل بين سيارتك والدراجة الهوائية عندما تتجاوزها.","p":"صحيح. اترك للدراجة 3 أقدام (feet) على الأقل عندما تتجاوزها."},"ht":{"q":"Nan Florida, konbyen espas ou dwe kite lè w ap pase yon bisiklèt?","o":["Omwen 1 pye","Omwen 2 pye","Omwen 3 pye","Omwen 10 pye"],"h1":"Panse ak yon espas ki an sekirite ant machin ou ak moun ki sou bisiklèt la.","h2":"Lalwa Florida di ou dwe kite omwen 3 pye ant machin ou ak yon bisiklèt lè w ap pase l.","p":"Se sa. Bay yon bisiklèt omwen 3 pye lè w ap pase l."},"ref":{"doc":"FL","page":81}},{"id":"safe-driving-002","scope":"FL","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Florida, you want to turn right. A bicycle is in the bike lane next to you. What should you do?","o":["Speed up and turn in front of it","Let the bicycle go by, then turn","Honk so the rider will stop","Turn from the left lane instead"],"h1":"Think about who is already moving straight in that lane.","h2":"The bicycle is going straight in its own lane, so you must let it pass before you turn right across the bike lane.","p":"Right. Let the bicycle go by first, then turn."},"es":{"q":"En Florida, usted quiere girar a la derecha. Hay una bicicleta en el carril de bicicletas a su lado. ¿Qué debe hacer?","o":["Acelerar y girar delante de ella","Dejar pasar la bicicleta y luego girar","Tocar la bocina para que pare","Girar desde el carril izquierdo"],"h1":"Piense en quién ya va derecho en ese carril.","h2":"La bicicleta va derecho en su propio carril, así que debe dejarla pasar antes de girar a la derecha y cruzar el carril de bicicletas.","p":"Correcto. Deje pasar la bicicleta primero y luego gire."},"zh":{"q":"在 Florida，你想右转。有一辆自行车在你旁边的自行车道上。你应该怎么做？","o":["加速，在它前面转弯","让自行车先过去，然后再转弯","按喇叭让骑车人停下","改从左边车道转弯"],"h1":"想一想谁已经在那条车道上直行。","h2":"自行车在自己的车道上直行，所以你必须让它先过去，然后再穿过自行车道右转。","p":"对。先让自行车过去，然后再转弯。"},"vi":{"q":"Ở Florida, bạn muốn rẽ phải. Có một xe đạp đang ở làn xe đạp cạnh bạn. Bạn nên làm gì?","o":["Tăng tốc và rẽ trước xe đạp","Để xe đạp đi qua, rồi mới rẽ","Bấm còi để người đi xe đạp dừng lại","Rẽ từ làn bên trái thay vào đó"],"h1":"Hãy nghĩ xem ai đang đi thẳng trong làn đó.","h2":"Xe đạp đang đi thẳng trong làn của nó, nên bạn phải để xe đạp đi qua trước khi rẽ phải cắt ngang làn xe đạp.","p":"Đúng. Để xe đạp đi qua trước, rồi mới rẽ."},"tl":{"q":"Sa Florida, gusto mong kumanan. May bisikleta sa bike lane sa tabi mo. Ano ang dapat mong gawin?","o":["Bumilis at kumanan sa harap nito","Hayaang dumaan muna ang bisikleta, saka kumanan","Bumusina para huminto ang nagbibisikleta","Kumanan na lang mula sa kaliwang lane"],"h1":"Isipin kung sino ang diretsong umaandar na sa lane na iyon.","h2":"Diretsong umaandar ang bisikleta sa sarili nitong lane, kaya dapat mo itong hayaang dumaan bago ka kumanan patawid sa bike lane.","p":"Tama. Hayaang dumaan muna ang bisikleta, saka kumanan."},"ar":{"q":"في Florida، تريد أن تنعطف يمينًا. توجد دراجة هوائية في مسار الدراجات بجانبك. ماذا يجب أن تفعل؟","o":["أسرع وانعطف أمامها","اترك الدراجة تمرّ، ثم انعطف","استعمل البوق حتى يتوقف راكب الدراجة","انعطف من المسار الأيسر بدلًا من ذلك"],"h1":"فكّر: من يسير إلى الأمام مباشرة في ذلك المسار الآن؟","h2":"الدراجة تسير إلى الأمام في مسارها، لذلك يجب أن تتركها تمرّ قبل أن تنعطف يمينًا وتقطع مسار الدراجات.","p":"صحيح. اترك الدراجة تمرّ أولًا، ثم انعطف."},"ht":{"q":"Nan Florida, ou vle vire adwat. Gen yon bisiklèt nan liy bisiklèt la bò kote w. Kisa ou ta dwe fè?","o":["Akselere epi vire devan l","Kite bisiklèt la pase, epi vire","Klaksonen pou moun nan kanpe","Vire soti nan liy goch la pito"],"h1":"Panse ak kiyès ki deja ap ale tou dwat nan liy sa a.","h2":"Bisiklèt la ap ale tou dwat nan pwòp liy pa l, kidonk ou dwe kite l pase anvan ou vire adwat travèse liy bisiklèt la.","p":"Se sa. Kite bisiklèt la pase anvan, epi vire."},"ref":{"doc":"FL","page":81}},{"id":"safe-driving-003","scope":"FL","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Florida, you parked on a busy street. What should you do before you open your door on the traffic side?","o":["Open it fast so you are quick","Turn on your wipers first","Honk the horn one time","Look back for bikes and cars"],"h1":"Think about who might be coming up beside your car.","h2":"A door that opens suddenly can hit a cyclist or a car, so you must look back and wait until it is safe to open it.","p":"Right. Look back for bikes and cars before you open your door."},"es":{"q":"En Florida, usted se estacionó en una calle con mucho tráfico. ¿Qué debe hacer antes de abrir la puerta del lado del tráfico?","o":["Abrirla rápido para no tardar","Encender los limpiaparabrisas","Tocar la bocina una vez","Mirar atrás por bicicletas y carros"],"h1":"Piense en quién podría venir al lado de su carro.","h2":"Una puerta que se abre de repente puede golpear a un ciclista o a un carro, así que debe mirar atrás y esperar hasta que sea seguro abrirla.","p":"Correcto. Mire atrás por bicicletas y carros antes de abrir la puerta."},"zh":{"q":"在 Florida，你把车停在一条车很多的街上。打开靠车流一侧的车门前，你应该做什么？","o":["快速打开，节省时间","先打开雨刷","按一下喇叭","回头看有没有自行车和汽车"],"h1":"想一想谁可能正从你的车旁边过来。","h2":"突然打开的车门可能撞到骑自行车的人或汽车，所以你必须回头看，等到安全时再开门。","p":"对。开门前回头看有没有自行车和汽车。"},"vi":{"q":"Ở Florida, bạn đậu xe trên một con đường đông xe. Bạn nên làm gì trước khi mở cửa xe ở phía có xe chạy?","o":["Mở nhanh cho kịp","Bật cần gạt nước trước","Bấm còi một lần","Nhìn ra sau xem có xe đạp và xe hơi không"],"h1":"Hãy nghĩ xem ai có thể đang đến gần bên cạnh xe bạn.","h2":"Cửa xe mở đột ngột có thể đụng vào người đi xe đạp hoặc xe hơi, nên bạn phải nhìn ra sau và chờ đến khi an toàn mới mở cửa.","p":"Đúng. Nhìn ra sau xem có xe đạp và xe hơi không trước khi mở cửa."},"tl":{"q":"Sa Florida, nag-park ka sa mataong kalye. Ano ang dapat mong gawin bago buksan ang pinto mo sa gilid ng trapiko?","o":["Buksan ito nang mabilis para mabilis ka","I-on muna ang wipers mo","Bumusina nang isang beses","Lumingon sa likod para tingnan kung may bisikleta o kotse"],"h1":"Isipin kung sino ang puwedeng paparating sa tabi ng kotse mo.","h2":"Ang pintong biglang bumukas ay puwedeng tumama sa nagbibisikleta o sa kotse, kaya dapat kang lumingon sa likod at maghintay hanggang ligtas nang buksan ito.","p":"Tama. Lumingon sa likod para sa bisikleta at kotse bago buksan ang pinto mo."},"ar":{"q":"في Florida، أوقفت سيارتك في شارع مزدحم. ماذا يجب أن تفعل قبل أن تفتح بابك من جهة السير؟","o":["افتحه بسرعة حتى تنتهي بسرعة","شغّل المساحات أولًا","استعمل البوق مرة واحدة","انظر إلى الخلف لترى الدراجات والسيارات"],"h1":"فكّر: من قد يقترب بجانب سيارتك؟","h2":"الباب الذي يُفتح فجأة قد يضرب راكب دراجة أو سيارة، لذلك يجب أن تنظر إلى الخلف وتنتظر حتى يصبح فتحه آمنًا.","p":"صحيح. انظر إلى الخلف لترى الدراجات والسيارات قبل أن تفتح بابك."},"ht":{"q":"Nan Florida, ou pake nan yon lari ki gen anpil machin. Kisa ou ta dwe fè anvan ou louvri pòt ou bò kote machin yo ap pase a?","o":["Louvri l vit pou w fè vit","Limen wipè ou anvan","Klaksonen yon fwa","Gade dèyè pou bisiklèt ak machin"],"h1":"Panse ak kiyès ki ka ap vini bò kote machin ou.","h2":"Yon pòt ki louvri sanzatann ka frape yon moun sou bisiklèt oswa yon machin, kidonk ou dwe gade dèyè epi tann jiskaske li an sekirite pou w louvri l.","p":"Se sa. Gade dèyè pou bisiklèt ak machin anvan ou louvri pòt ou."},"ref":{"doc":"FL","page":81}},{"id":"safe-driving-004","scope":"FL","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Florida, a person is walking across the street in a crosswalk in front of you. What must you do?","o":["Stop and let the person cross","Drive slowly around the person","Honk so the person hurries","Keep going if you have a green light"],"h1":"Think about who has the right to use the crosswalk first.","h2":"A person in a crosswalk has the right of way, so you must stop and wait until the person has crossed.","p":"Right. Stop and let people in the crosswalk cross."},"es":{"q":"En Florida, una persona cruza la calle por el paso peatonal frente a usted. ¿Qué debe hacer?","o":["Parar y dejar que la persona cruce","Pasar despacio alrededor de la persona","Tocar la bocina para que se apure","Seguir si tiene luz verde"],"h1":"Piense en quién tiene primero el derecho de usar el paso peatonal.","h2":"Una persona en el paso peatonal tiene el derecho de paso, así que debe parar y esperar a que termine de cruzar.","p":"Correcto. Pare y deje cruzar a las personas en el paso peatonal."},"zh":{"q":"在 Florida，有一个人正在你前面的人行横道上过马路。你必须做什么？","o":["停车，让这个人过马路","慢慢绕过这个人","按喇叭让这个人快点走","如果是绿灯就继续开"],"h1":"想一想谁有权先使用人行横道。","h2":"在人行横道上的人有先行权，所以你必须停车，等这个人过完马路。","p":"对。停车，让人行横道上的人过马路。"},"vi":{"q":"Ở Florida, có một người đang đi bộ qua đường trên vạch qua đường trước mặt bạn. Bạn phải làm gì?","o":["Dừng lại và để người đó đi qua","Lái chậm vòng qua người đó","Bấm còi để người đó đi nhanh hơn","Cứ đi tiếp nếu bạn có đèn xanh"],"h1":"Hãy nghĩ xem ai có quyền dùng vạch qua đường trước.","h2":"Người đi trên vạch qua đường có quyền ưu tiên, nên bạn phải dừng lại và chờ đến khi người đó đi qua hết.","p":"Đúng. Dừng lại và để người trên vạch qua đường đi qua."},"tl":{"q":"Sa Florida, may taong tumatawid sa crosswalk sa harap mo. Ano ang dapat mong gawin?","o":["Huminto at hayaang tumawid ang tao","Dahan-dahang lumihis sa paligid ng tao","Bumusina para magmadali ang tao","Tumuloy kung green light ka"],"h1":"Isipin kung sino ang unang may karapatang gumamit ng crosswalk.","h2":"Ang taong nasa crosswalk ang may right of way, kaya dapat kang huminto at maghintay hanggang makatawid ang tao.","p":"Tama. Huminto at hayaang tumawid ang mga tao sa crosswalk."},"ar":{"q":"في Florida، شخص يعبر الشارع على ممر المشاة أمامك. ماذا يجب أن تفعل؟","o":["توقف واترك الشخص يعبر","قُد ببطء حول الشخص","استعمل البوق حتى يُسرع الشخص","تابع السير إذا كانت الإشارة خضراء لك"],"h1":"فكّر: من له الحق في استعمال ممر المشاة أولًا؟","h2":"الشخص الذي على ممر المشاة له حق الأولوية، لذلك يجب أن تتوقف وتنتظر حتى يعبر.","p":"صحيح. توقف واترك الناس على ممر المشاة يعبرون."},"ht":{"q":"Nan Florida, yon moun ap travèse lari a nan pasaj pyeton an devan w. Kisa ou dwe fè?","o":["Kanpe epi kite moun nan travèse","Kondi dousman bò kote moun nan","Klaksonen pou moun nan fè vit","Kontinye si limyè a vèt pou ou"],"h1":"Panse ak kiyès ki gen dwa sèvi ak pasaj pyeton an anvan.","h2":"Yon moun ki nan pasaj pyeton an gen priyorite, kidonk ou dwe kanpe epi tann jiskaske moun nan fin travèse.","p":"Se sa. Kanpe epi kite moun ki nan pasaj pyeton an travèse."},"ref":{"doc":"FL","page":87}},{"id":"safe-driving-005","scope":"FL","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Florida, a person with a white cane or a guide dog is starting to cross the street. What should you do?","o":["Honk to warn the person","Drive around the person slowly","Stop and wait until the person crosses","Wave the person back to the curb"],"h1":"Think about a person who may not be able to see your car.","h2":"A white cane or a guide dog shows that the person may be blind, so you must stop and wait until the person is safely across.","p":"Right. Stop for a person with a white cane or a guide dog."},"es":{"q":"En Florida, una persona con un bastón blanco o un perro guía empieza a cruzar la calle. ¿Qué debe hacer?","o":["Tocar la bocina para avisarle","Pasar despacio alrededor de la persona","Parar y esperar a que la persona cruce","Hacerle señas para que vuelva a la acera"],"h1":"Piense en una persona que tal vez no puede ver su carro.","h2":"Un bastón blanco o un perro guía indica que la persona puede ser ciega, así que debe parar y esperar a que cruce con seguridad.","p":"Correcto. Pare para una persona con bastón blanco o perro guía."},"zh":{"q":"在 Florida，一个拿着白色手杖或带着导盲犬的人正要过马路。你应该怎么做？","o":["按喇叭提醒这个人","慢慢绕过这个人","停车，等这个人过完马路","挥手让这个人回到路边"],"h1":"想一想一个可能看不到你车的人。","h2":"白色手杖或导盲犬表示这个人可能看不见，所以你必须停车，等这个人安全过完马路。","p":"对。为拿白色手杖或带导盲犬的人停车。"},"vi":{"q":"Ở Florida, một người cầm gậy trắng hoặc đi cùng chó dẫn đường đang bắt đầu qua đường. Bạn nên làm gì?","o":["Bấm còi để báo cho người đó","Lái chậm vòng qua người đó","Dừng lại và chờ đến khi người đó qua hết đường","Vẫy tay bảo người đó quay lại lề đường"],"h1":"Hãy nghĩ đến một người có thể không nhìn thấy xe bạn.","h2":"Gậy trắng hoặc chó dẫn đường cho thấy người đó có thể bị mù, nên bạn phải dừng lại và chờ đến khi người đó qua đường an toàn.","p":"Đúng. Dừng lại cho người cầm gậy trắng hoặc đi cùng chó dẫn đường."},"tl":{"q":"Sa Florida, ang taong may puting tungkod o guide dog ay nagsisimulang tumawid sa kalye. Ano ang dapat mong gawin?","o":["Bumusina para bigyan ng babala ang tao","Dahan-dahang lumihis sa paligid ng tao","Huminto at maghintay hanggang makatawid ang tao","Senyasan ang tao na bumalik sa gilid ng kalsada"],"h1":"Isipin ang taong maaaring hindi nakakakita sa kotse mo.","h2":"Ang puting tungkod o guide dog ay nagpapakitang maaaring bulag ang tao, kaya dapat kang huminto at maghintay hanggang ligtas na siyang nakatawid.","p":"Tama. Huminto para sa taong may puting tungkod o guide dog."},"ar":{"q":"في Florida، شخص معه عصا بيضاء أو كلب مرشد يبدأ بعبور الشارع. ماذا يجب أن تفعل؟","o":["استعمل البوق لتحذّر الشخص","قُد ببطء حول الشخص","توقف وانتظر حتى يعبر الشخص","أشِر إلى الشخص ليعود إلى الرصيف"],"h1":"فكّر في شخص قد لا يستطيع أن يرى سيارتك.","h2":"العصا البيضاء أو الكلب المرشد تدل على أن الشخص قد يكون كفيفًا، لذلك يجب أن تتوقف وتنتظر حتى يعبر بأمان.","p":"صحيح. توقف لشخص معه عصا بيضاء أو كلب مرشد."},"ht":{"q":"Nan Florida, yon moun ki gen yon baton blan oswa yon chen gid ap kòmanse travèse lari a. Kisa ou ta dwe fè?","o":["Klaksonen pou avèti moun nan","Kondi dousman bò kote moun nan","Kanpe epi tann jiskaske moun nan fin travèse","Fè moun nan siy pou l retounen sou twotwa a"],"h1":"Panse ak yon moun ki ka pa ka wè machin ou.","h2":"Yon baton blan oswa yon chen gid montre ke moun nan ka avèg, kidonk ou dwe kanpe epi tann jiskaske moun nan fin travèse san danje.","p":"Se sa. Kanpe pou yon moun ki gen yon baton blan oswa yon chen gid."},"ref":{"doc":"FL","page":88}},{"id":"safe-driving-006","scope":"US","cat":"safe-driving","sign":null,"c":1,"en":{"q":"Why should you look twice for motorcycles before you turn or change lanes?","o":["Motorcycles must always use the right lane","Motorcycles are small and easy to miss","Motorcycles cannot use turn signals","Motorcycles always drive faster than cars"],"h1":"Think about how big a motorcycle looks next to a car.","h2":"A motorcycle is much smaller than a car, so it can hide in a blind spot or be easy to miss, and you should look twice.","p":"Right. Motorcycles are small and easy to miss, so look twice."},"es":{"q":"¿Por qué debe mirar dos veces por motocicletas antes de girar o cambiar de carril?","o":["Las motos siempre deben ir por la derecha","Las motos son pequeñas y fáciles de no ver","Las motos no pueden usar direccionales","Las motos siempre van más rápido que los carros"],"h1":"Piense en el tamaño de una moto al lado de un carro.","h2":"Una motocicleta es mucho más pequeña que un carro, así que puede esconderse en un punto ciego o pasar desapercibida, y debe mirar dos veces.","p":"Correcto. Las motos son pequeñas y fáciles de no ver; mire dos veces."},"zh":{"q":"为什么你在转弯或换车道前，应该看两次有没有摩托车？","o":["摩托车必须一直走右边车道","摩托车很小，很容易看漏","摩托车不能用转向灯","摩托车总是比汽车开得快"],"h1":"想一想摩托车在汽车旁边看起来有多大。","h2":"摩托车比汽车小很多，所以它可能藏在盲区里，或很容易被看漏，你应该看两次。","p":"对。摩托车很小，很容易看漏，所以要看两次。"},"vi":{"q":"Tại sao bạn nên nhìn hai lần để tìm xe máy trước khi rẽ hoặc đổi làn?","o":["Xe máy luôn phải đi làn bên phải","Xe máy nhỏ và dễ bị bỏ sót","Xe máy không thể dùng đèn xi-nhan","Xe máy luôn chạy nhanh hơn xe hơi"],"h1":"Hãy nghĩ xem một chiếc xe máy trông lớn cỡ nào khi ở cạnh xe hơi.","h2":"Xe máy nhỏ hơn xe hơi rất nhiều, nên nó có thể bị che trong điểm mù hoặc dễ bị bỏ sót, và bạn nên nhìn hai lần.","p":"Đúng. Xe máy nhỏ và dễ bị bỏ sót, nên hãy nhìn hai lần."},"tl":{"q":"Bakit dapat kang tumingin nang dalawang beses para sa motorsiklo bago kumanan o kumaliwa, o lumipat ng lane?","o":["Dapat laging gumamit ng kanang lane ang mga motorsiklo","Maliit ang mga motorsiklo at madaling hindi mapansin","Hindi puwedeng gumamit ng signal light ang mga motorsiklo","Laging mas mabilis ang mga motorsiklo kaysa sa mga kotse"],"h1":"Isipin kung gaano kalaki ang tingin sa motorsiklo kapag katabi ng kotse.","h2":"Mas maliit nang husto ang motorsiklo kaysa sa kotse, kaya puwede itong matago sa blind spot o madaling hindi mapansin, at dapat kang tumingin nang dalawang beses.","p":"Tama. Maliit ang mga motorsiklo at madaling hindi mapansin, kaya tumingin nang dalawang beses."},"ar":{"q":"لماذا يجب أن تنظر مرتين بحثًا عن الدراجات النارية قبل أن تنعطف أو تغيّر المسار؟","o":["الدراجات النارية يجب أن تستعمل المسار الأيمن دائمًا","الدراجات النارية صغيرة ومن السهل ألا تراها","الدراجات النارية لا تستطيع استعمال إشارات الانعطاف","الدراجات النارية تسير دائمًا أسرع من السيارات"],"h1":"فكّر في حجم الدراجة النارية بجانب السيارة.","h2":"الدراجة النارية أصغر بكثير من السيارة، لذلك قد تختفي في النقطة العمياء أو من السهل ألا تراها، ويجب أن تنظر مرتين.","p":"صحيح. الدراجات النارية صغيرة ومن السهل ألا تراها، لذلك انظر مرتين."},"ht":{"q":"Poukisa ou ta dwe gade de fwa pou motosiklèt anvan ou vire oswa chanje liy?","o":["Motosiklèt yo dwe toujou sèvi ak liy dwat la","Motosiklèt yo piti epi li fasil pou w pa wè yo","Motosiklèt yo pa ka sèvi ak siyal pou vire","Motosiklèt yo toujou kondi pi vit pase machin"],"h1":"Panse ak gwosè yon motosiklèt bò kote yon machin.","h2":"Yon motosiklèt pi piti anpil pase yon machin, kidonk li ka kache nan yon kote ou pa ka wè (blind spot) oswa li fasil pou w pa wè l, epi ou ta dwe gade de fwa.","p":"Se sa. Motosiklèt yo piti epi li fasil pou w pa wè yo, kidonk gade de fwa."},"ref":{"doc":"FL","page":85}},{"id":"safe-driving-007","scope":"FL","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Florida, may you share a lane side by side with a motorcycle?","o":["Yes, if the motorcycle is slow","Yes, on any multi-lane road","Yes, if you signal first","No, a motorcycle gets the full lane"],"h1":"Think about how much room a motorcycle needs to move safely.","h2":"In Florida a motorcycle has the right to use the full width of a lane, so you may not drive next to it in the same lane.","p":"Right. A motorcycle gets the full lane, so do not share it."},"es":{"q":"En Florida, ¿puede compartir un carril lado a lado con una motocicleta?","o":["Sí, si la moto va despacio","Sí, en cualquier vía de varios carriles","Sí, si pone la direccional antes","No, la moto tiene derecho a todo el carril"],"h1":"Piense en cuánto espacio necesita una moto para moverse con seguridad.","h2":"En Florida una motocicleta tiene derecho a usar todo el ancho del carril, así que usted no puede manejar a su lado en el mismo carril.","p":"Correcto. La moto tiene derecho a todo el carril; no lo comparta."},"zh":{"q":"在 Florida，你可以和摩托车在同一条车道上并排行驶吗？","o":["可以，如果摩托车开得慢","可以，在任何多车道的路上","可以，如果你先打转向灯","不可以，摩托车可以使用整条车道"],"h1":"想一想摩托车需要多少空间才能安全行驶。","h2":"在 Florida，摩托车有权使用整条车道的宽度，所以你不能在同一条车道上开在它旁边。","p":"对。摩托车可以使用整条车道，所以不要和它共用。"},"vi":{"q":"Ở Florida, bạn có được chạy song song với xe máy trong cùng một làn không?","o":["Có, nếu xe máy chạy chậm","Có, trên bất kỳ đường nhiều làn nào","Có, nếu bạn bật xi-nhan trước","Không, xe máy được dùng trọn cả làn"],"h1":"Hãy nghĩ xem xe máy cần bao nhiêu chỗ để di chuyển an toàn.","h2":"Ở Florida, xe máy có quyền dùng toàn bộ chiều rộng của một làn, nên bạn không được chạy cạnh xe máy trong cùng một làn.","p":"Đúng. Xe máy được dùng trọn cả làn, nên đừng chạy chung làn."},"tl":{"q":"Sa Florida, puwede ka bang makihati ng lane nang magkatabi sa isang motorsiklo?","o":["Oo, kung mabagal ang motorsiklo","Oo, sa kahit anong daan na maraming lane","Oo, kung mag-signal ka muna","Hindi, sa motorsiklo ang buong lane"],"h1":"Isipin kung gaano kalaking espasyo ang kailangan ng motorsiklo para umandar nang ligtas.","h2":"Sa Florida, may karapatan ang motorsiklo na gamitin ang buong lapad ng lane, kaya hindi ka puwedeng magmaneho sa tabi nito sa parehong lane.","p":"Tama. Sa motorsiklo ang buong lane, kaya huwag makihati rito."},"ar":{"q":"في Florida، هل يُسمح لك بأن تسير جنبًا إلى جنب مع دراجة نارية في نفس المسار؟","o":["نعم، إذا كانت الدراجة النارية بطيئة","نعم، على أي طريق فيه عدة مسارات","نعم، إذا استعملت الإشارة أولًا","لا، الدراجة النارية لها المسار كله"],"h1":"فكّر في المساحة التي تحتاجها الدراجة النارية لتتحرك بأمان.","h2":"في Florida، للدراجة النارية الحق في استعمال عرض المسار كله، لذلك لا يُسمح لك بالقيادة بجانبها في نفس المسار.","p":"صحيح. الدراجة النارية لها المسار كله، فلا تشاركها فيه."},"ht":{"q":"Nan Florida, èske ou ka pataje yon liy ak yon motosiklèt, kòt a kòt?","o":["Wi, si motosiklèt la ap mache dousman","Wi, sou nenpòt wout ki gen plizyè liy","Wi, si ou bay siyal anvan","Non, yon motosiklèt gen dwa sou tout liy lan"],"h1":"Panse ak konbyen espas yon motosiklèt bezwen pou l deplase san danje.","h2":"Nan Florida, yon motosiklèt gen dwa sèvi ak tout lajè yon liy, kidonk ou pa gen dwa kondi bò kote l nan menm liy lan.","p":"Se sa. Yon motosiklèt gen dwa sou tout liy lan, kidonk pa pataje l."},"ref":{"doc":"FL","page":85}},{"id":"safe-driving-008","scope":"US","cat":"safe-driving","sign":null,"c":0,"en":{"q":"You are driving next to a large truck. You cannot see the driver's face in the truck's side mirror. What does this mean?","o":["The driver probably cannot see you","The driver is not paying attention","The mirror is broken","You are at a safe distance"],"h1":"Think about how mirrors work in both directions.","h2":"If you cannot see the truck driver in the mirror, the driver cannot see you either, so you are in a blind spot and should move out of it.","p":"Right. If you cannot see the driver in the mirror, the driver cannot see you."},"es":{"q":"Usted maneja al lado de un camión grande. No puede ver la cara del chofer en el espejo lateral del camión. ¿Qué significa?","o":["El chofer probablemente no lo ve a usted","El chofer no está prestando atención","El espejo está roto","Usted está a una distancia segura"],"h1":"Piense en cómo funcionan los espejos en las dos direcciones.","h2":"Si usted no ve al chofer en el espejo, el chofer tampoco lo ve a usted, así que está en un punto ciego y debe salir de ahí.","p":"Correcto. Si no ve al chofer en el espejo, él no lo ve a usted."},"zh":{"q":"你开在一辆大卡车旁边。你在卡车的侧后视镜里看不到司机的脸。这是什么意思？","o":["司机很可能看不到你","司机没有注意","后视镜坏了","你在安全的距离"],"h1":"想一想镜子是两个方向都能看到的。","h2":"如果你在镜子里看不到卡车司机，司机也看不到你，所以你在盲区里，应该离开那里。","p":"对。如果你在镜子里看不到司机，司机也看不到你。"},"vi":{"q":"Bạn đang lái xe cạnh một xe tải lớn. Bạn không nhìn thấy mặt tài xế trong gương chiếu hậu bên hông của xe tải. Điều này có nghĩa là gì?","o":["Có lẽ tài xế không nhìn thấy bạn","Tài xế không chú ý","Gương bị hỏng","Bạn đang ở khoảng cách an toàn"],"h1":"Hãy nghĩ xem gương hoạt động theo cả hai chiều như thế nào.","h2":"Nếu bạn không nhìn thấy tài xế xe tải trong gương, thì tài xế cũng không nhìn thấy bạn, nên bạn đang ở điểm mù và nên ra khỏi đó.","p":"Đúng. Nếu bạn không thấy tài xế trong gương, tài xế cũng không thấy bạn."},"tl":{"q":"Nagmamaneho ka sa tabi ng malaking truck. Hindi mo makita ang mukha ng driver sa side mirror ng truck. Ano ang ibig sabihin nito?","o":["Malamang hindi ka rin nakikita ng driver","Hindi nag-iingat ang driver","Sira ang salamin","Nasa ligtas na layo ka"],"h1":"Isipin kung paano gumagana ang salamin sa magkabilang direksyon.","h2":"Kung hindi mo makita ang truck driver sa salamin, hindi ka rin niya nakikita, kaya nasa blind spot ka at dapat kang umalis doon.","p":"Tama. Kung hindi mo makita ang driver sa salamin, hindi ka rin nakikita ng driver."},"ar":{"q":"أنت تقود بجانب شاحنة كبيرة. لا تستطيع أن ترى وجه السائق في المرآة الجانبية للشاحنة. ماذا يعني هذا؟","o":["السائق على الأغلب لا يستطيع أن يراك","السائق لا ينتبه","المرآة مكسورة","أنت على مسافة آمنة"],"h1":"فكّر في أن المرايا تعمل في الاتجاهين.","h2":"إذا لم تستطع أن ترى سائق الشاحنة في المرآة، فالسائق أيضًا لا يستطيع أن يراك، لذلك أنت في النقطة العمياء ويجب أن تخرج منها.","p":"صحيح. إذا لم ترَ السائق في المرآة، فالسائق لا يراك."},"ht":{"q":"W ap kondi bò kote yon gwo kamyon. Ou pa ka wè figi chofè a nan retwovizè bò kamyon an. Kisa sa vle di?","o":["Chofè a pwobableman pa ka wè w","Chofè a pa fè atansyon","Retwovizè a kase","Ou nan yon distans ki an sekirite"],"h1":"Panse ak jan retwovizè yo mache nan de direksyon.","h2":"Si ou pa ka wè chofè kamyon an nan retwovizè a, chofè a pa ka wè w nonplis, kidonk ou nan yon kote li pa ka wè (blind spot) epi ou ta dwe soti la.","p":"Se sa. Si ou pa ka wè chofè a nan retwovizè a, chofè a pa ka wè w."},"ref":{"doc":"FL","page":82}},{"id":"safe-driving-009","scope":"US","cat":"safe-driving","sign":null,"c":2,"en":{"q":"A large truck ahead has its right turn signal on. It moves a little to the left first. What should you do?","o":["Pass it on the right side","Honk to tell the driver to hurry","Stay back and wait for it to turn","Move up close behind the truck"],"h1":"Think about how much room a long truck needs to turn a corner.","h2":"Large trucks often swing left to make a wide right turn, so you should stay back and never squeeze in between the truck and the curb.","p":"Right. Stay back and let the truck make its wide right turn."},"es":{"q":"Un camión grande adelante tiene puesta la direccional derecha. Primero se mueve un poco a la izquierda. ¿Qué debe hacer?","o":["Rebasarlo por el lado derecho","Tocar la bocina para que se apure","Quedarse atrás y esperar a que gire","Acercarse mucho detrás del camión"],"h1":"Piense en cuánto espacio necesita un camión largo para doblar una esquina.","h2":"Los camiones grandes a menudo se abren a la izquierda para hacer un giro amplio a la derecha, así que debe quedarse atrás y nunca meterse entre el camión y la acera.","p":"Correcto. Quédese atrás y deje que el camión haga su giro amplio."},"zh":{"q":"前面一辆大卡车打开了右转向灯。它先稍微往左移动。你应该怎么做？","o":["从它右边超过去","按喇叭让司机快点","留在后面，等它转弯","开到卡车后面很近的地方"],"h1":"想一想长卡车转过一个路口需要多少空间。","h2":"大卡车常常先往左摆，才能大弯右转，所以你应该留在后面，绝不要挤进卡车和路边之间。","p":"对。留在后面，让卡车大弯右转。"},"vi":{"q":"Một xe tải lớn phía trước đang bật xi-nhan phải. Nó lấn sang trái một chút trước. Bạn nên làm gì?","o":["Vượt qua nó ở bên phải","Bấm còi giục tài xế nhanh lên","Lùi lại phía sau và chờ nó rẽ","Chạy sát lên phía sau xe tải"],"h1":"Hãy nghĩ xem một xe tải dài cần bao nhiêu chỗ để rẽ ở góc đường.","h2":"Xe tải lớn thường lấn sang trái để rẽ phải một vòng rộng, nên bạn nên lùi lại phía sau và không bao giờ chen vào giữa xe tải và lề đường.","p":"Đúng. Lùi lại phía sau và để xe tải rẽ phải một vòng rộng."},"tl":{"q":"Ang malaking truck sa unahan ay naka-signal pakanan. Kumikilos muna ito nang kaunti pakaliwa. Ano ang dapat mong gawin?","o":["Lampasan ito sa kanang bahagi","Bumusina para magmadali ang driver","Manatili sa likod at hintayin itong kumanan","Lumapit nang husto sa likod ng truck"],"h1":"Isipin kung gaano kalaking espasyo ang kailangan ng mahabang truck para lumiko sa kanto.","h2":"Madalas lumihis pakaliwa ang malalaking truck para makagawa ng malapad na pagkanan, kaya dapat kang manatili sa likod at huwag kailanman sumingit sa pagitan ng truck at ng gilid ng kalsada.","p":"Tama. Manatili sa likod at hayaang gawin ng truck ang malapad nitong pagkanan."},"ar":{"q":"شاحنة كبيرة أمامك شغّلت إشارة الانعطاف اليمنى. لكنها تتحرك قليلًا إلى اليسار أولًا. ماذا يجب أن تفعل؟","o":["تجاوزها من الجهة اليمنى","استعمل البوق لتقول للسائق أن يُسرع","ابقَ في الخلف وانتظر حتى تنعطف","اقترب كثيرًا خلف الشاحنة"],"h1":"فكّر في المساحة التي تحتاجها شاحنة طويلة لتنعطف عند الزاوية.","h2":"الشاحنات الكبيرة تميل غالبًا إلى اليسار لتنعطف يمينًا انعطافًا واسعًا، لذلك يجب أن تبقى في الخلف ولا تدخل أبدًا بين الشاحنة والرصيف.","p":"صحيح. ابقَ في الخلف واترك الشاحنة تنعطف يمينًا انعطافها الواسع."},"ht":{"q":"Yon gwo kamyon devan w limen siyal pou vire adwat. Li deplase yon ti kras agoch anvan. Kisa ou ta dwe fè?","o":["Pase l sou bò dwat la","Klaksonen pou di chofè a fè vit","Rete dèyè epi tann li vire","Vin kole dèyè kamyon an"],"h1":"Panse ak konbyen espas yon kamyon long bezwen pou l vire nan yon kwen.","h2":"Gwo kamyon yo souvan ale agoch pou yo ka fè yon gwo vire adwat, kidonk ou ta dwe rete dèyè epi pa janm foure kò w ant kamyon an ak bò twotwa a.","p":"Se sa. Rete dèyè epi kite kamyon an fè gwo vire adwat li."},"ref":{"doc":"FL","page":83}},{"id":"safe-driving-010","scope":"US","cat":"safe-driving","sign":null,"c":1,"en":{"q":"You just passed a large truck. When should you move back in front of it?","o":["Right away, as soon as you pass its bumper","When you can see the whole truck front in your mirror","After you slow down a little","Only after the truck flashes its lights"],"h1":"Think about how long it takes a heavy truck to stop.","h2":"A heavy truck needs a long distance to stop, so you should wait until you can see its whole front in your rearview mirror before you move in.","p":"Right. Move in only when you can see the whole truck front in your mirror."},"es":{"q":"Usted acaba de rebasar un camión grande. ¿Cuándo debe volver a ponerse delante de él?","o":["De inmediato, al pasar su parachoques","Cuando vea todo el frente del camión en su espejo","Después de bajar un poco la velocidad","Solo cuando el camión le haga cambio de luces"],"h1":"Piense en cuánto le toma a un camión pesado frenar.","h2":"Un camión pesado necesita mucha distancia para frenar, así que debe esperar hasta ver todo su frente en el espejo retrovisor antes de ponerse delante.","p":"Correcto. Póngase delante solo cuando vea todo el frente del camión en el espejo."},"zh":{"q":"你刚超过一辆大卡车。什么时候可以回到它前面？","o":["马上，一超过它的保险杠就回去","当你在后视镜里能看到整个卡车车头时","在你稍微减速以后","只在卡车闪灯以后"],"h1":"想一想重型卡车需要多久才能停下来。","h2":"重型卡车需要很长的距离才能停下来，所以你应该等到在车内后视镜里能看到它整个车头，再回到它前面。","p":"对。只有在后视镜里能看到整个卡车车头时才回到前面。"},"vi":{"q":"Bạn vừa vượt qua một xe tải lớn. Khi nào bạn nên quay lại làn phía trước nó?","o":["Ngay lập tức, khi vừa qua khỏi cản xe của nó","Khi bạn nhìn thấy toàn bộ đầu xe tải trong gương","Sau khi bạn giảm tốc một chút","Chỉ sau khi xe tải nháy đèn"],"h1":"Hãy nghĩ xem một xe tải nặng cần bao lâu để dừng lại.","h2":"Xe tải nặng cần một quãng đường dài để dừng lại, nên bạn nên chờ đến khi nhìn thấy toàn bộ đầu xe tải trong gương chiếu hậu rồi mới quay vào làn.","p":"Đúng. Chỉ quay vào làn khi bạn nhìn thấy toàn bộ đầu xe tải trong gương."},"tl":{"q":"Kalalampas mo lang sa isang malaking truck. Kailan ka dapat bumalik sa harap nito?","o":["Agad-agad, pagkalampas mo sa bumper nito","Kapag nakikita mo na ang buong harap ng truck sa salamin mo","Pagkatapos mong bumagal nang kaunti","Pagkatapos lang mag-flash ng ilaw ang truck"],"h1":"Isipin kung gaano katagal bago makahinto ang mabigat na truck.","h2":"Kailangan ng mabigat na truck ng mahabang distansya para huminto, kaya dapat kang maghintay hanggang makita mo ang buong harap nito sa iyong rearview mirror bago ka bumalik sa lane.","p":"Tama. Bumalik lang sa lane kapag nakikita mo na ang buong harap ng truck sa salamin mo."},"ar":{"q":"تجاوزت شاحنة كبيرة الآن. متى يجب أن تعود إلى المسار أمامها؟","o":["فورًا، بمجرد أن تتجاوز مقدمتها","عندما ترى مقدمة الشاحنة كلها في مرآتك","بعد أن تخفف سرعتك قليلًا","فقط بعد أن تومض الشاحنة بأضوائها"],"h1":"فكّر في الوقت الذي تحتاجه الشاحنة الثقيلة لتتوقف.","h2":"الشاحنة الثقيلة تحتاج إلى مسافة طويلة لتتوقف، لذلك يجب أن تنتظر حتى ترى مقدمتها كلها في المرآة الداخلية قبل أن تدخل أمامها.","p":"صحيح. ادخل أمامها فقط عندما ترى مقدمة الشاحنة كلها في مرآتك."},"ht":{"q":"Ou fèk pase yon gwo kamyon. Ki lè ou ta dwe retounen devan l?","o":["Touswit, depi ou pase defans li","Lè ou ka wè tout devan kamyon an nan retwovizè ou","Apre ou ralanti yon ti kras","Sèlman apre kamyon an limen limyè li plizyè fwa"],"h1":"Panse ak konbyen tan yon kamyon lou pran pou l kanpe.","h2":"Yon kamyon lou bezwen yon long distans pou l kanpe, kidonk ou ta dwe tann jiskaske ou ka wè tout devan l nan retwovizè mitan an anvan ou retounen devan l.","p":"Se sa. Retounen devan l sèlman lè ou ka wè tout devan kamyon an nan retwovizè ou."},"ref":{"doc":"FL","page":83}},{"id":"safe-driving-011","scope":"FL","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Florida, a school bus on a two-lane road stops. Its red lights flash and its stop arm is out. You are coming from the other direction. What must you do?","o":["Slow down and pass with care","Keep going because you are on the other side","Honk and then pass slowly","Stop and wait until the stop arm is pulled in"],"h1":"Think about children who may cross the road to reach the bus.","h2":"On a road without a divider, drivers in both directions must stop for a school bus with its stop arm out, and wait until the arm is pulled back in.","p":"Right. Stop for the school bus, even from the other direction."},"es":{"q":"En Florida, un autobús escolar para en una carretera de dos carriles. Sus luces rojas parpadean y tiene el brazo de pare afuera. Usted viene en dirección contraria. ¿Qué debe hacer?","o":["Bajar la velocidad y pasar con cuidado","Seguir porque va del otro lado","Tocar la bocina y pasar despacio","Parar y esperar a que recojan el brazo de pare"],"h1":"Piense en los niños que pueden cruzar la calle para llegar al autobús.","h2":"En una vía sin división, los conductores de las dos direcciones deben parar ante un autobús escolar con el brazo de pare afuera, y esperar hasta que lo recojan.","p":"Correcto. Pare ante el autobús escolar, aunque venga en dirección contraria."},"zh":{"q":"在 Florida，一辆校车在双车道的路上停下。它的红灯在闪，停车臂也伸出来了。你从对面方向开过来。你必须做什么？","o":["减速，小心地开过去","继续开，因为你在另一边","按喇叭，然后慢慢开过去","停车，等到停车臂收回去"],"h1":"想一想孩子们可能会过马路去坐校车。","h2":"在没有隔离带的路上，两个方向的司机都必须为伸出停车臂的校车停车，并等到停车臂收回去。","p":"对。即使你从对面方向来，也要为校车停车。"},"vi":{"q":"Ở Florida, một xe buýt trường học dừng lại trên đường hai làn. Đèn đỏ nhấp nháy và tay chắn STOP đang mở ra. Bạn đang đi từ hướng ngược lại. Bạn phải làm gì?","o":["Giảm tốc và cẩn thận vượt qua","Cứ đi tiếp vì bạn ở phía bên kia","Bấm còi rồi chạy chậm qua","Dừng lại và chờ đến khi tay chắn STOP được thu vào"],"h1":"Hãy nghĩ đến trẻ em có thể băng qua đường để lên xe buýt.","h2":"Trên đường không có dải phân cách, tài xế ở cả hai chiều phải dừng lại khi xe buýt trường học mở tay chắn STOP, và chờ đến khi tay chắn được thu vào.","p":"Đúng. Dừng lại cho xe buýt trường học, dù bạn đi từ hướng ngược lại."},"tl":{"q":"Sa Florida, huminto ang school bus sa daang may dalawang lane. Kumikislap ang pulang ilaw nito at nakalabas ang stop arm. Galing ka sa kabilang direksyon. Ano ang dapat mong gawin?","o":["Bumagal at lumampas nang maingat","Tumuloy dahil nasa kabilang bahagi ka","Bumusina at saka lumampas nang dahan-dahan","Huminto at maghintay hanggang maibalik ang stop arm"],"h1":"Isipin ang mga batang maaaring tumawid sa daan para makarating sa bus.","h2":"Sa daang walang divider, dapat huminto ang mga driver sa magkabilang direksyon para sa school bus na nakalabas ang stop arm, at maghintay hanggang maibalik ang arm.","p":"Tama. Huminto para sa school bus, kahit galing ka sa kabilang direksyon."},"ar":{"q":"في Florida، حافلة مدرسية تتوقف على طريق فيه مساران. أضواؤها الحمراء تومض وذراع التوقف مفتوح. أنت قادم من الاتجاه الآخر. ماذا يجب أن تفعل؟","o":["خفّف السرعة وتجاوزها بحذر","تابع السير لأنك في الجهة الأخرى","استعمل البوق ثم تجاوز ببطء","توقف وانتظر حتى يُغلق ذراع التوقف"],"h1":"فكّر في الأطفال الذين قد يعبرون الطريق ليصلوا إلى الحافلة.","h2":"على طريق بدون فاصل، يجب على السائقين في الاتجاهين أن يتوقفوا للحافلة المدرسية عندما يكون ذراع التوقف مفتوحًا، وأن ينتظروا حتى يُغلق الذراع.","p":"صحيح. توقف للحافلة المدرسية، حتى إذا كنت في الاتجاه الآخر."},"ht":{"q":"Nan Florida, yon bis lekòl kanpe sou yon wout ki gen de liy. Limyè wouj li yo ap flache epi bra STOP li a louvri. W ap vini nan lòt direksyon an. Kisa ou dwe fè?","o":["Ralanti epi pase ak prekosyon","Kontinye paske ou sou lòt bò a","Klaksonen epi pase dousman","Kanpe epi tann jiskaske yo rantre bra STOP la"],"h1":"Panse ak timoun ki ka travèse wout la pou yo rive nan bis la.","h2":"Sou yon wout ki pa gen separasyon nan mitan, chofè nan tou de direksyon yo dwe kanpe pou yon bis lekòl ki gen bra STOP li louvri, epi tann jiskaske yo rantre bra a.","p":"Se sa. Kanpe pou bis lekòl la, menm si w ap vini nan lòt direksyon an."},"ref":{"doc":"FL","page":89}},{"id":"safe-driving-012","scope":"FL","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Florida, you are on a divided highway with a raised median. A school bus stops on the other side of the median. What should you do?","o":["You do not have to stop, but drive with care","Stop until the bus drives away","Stop, then pass at walking speed","Change to the lane closest to the bus"],"h1":"Think about what the raised median does between you and the bus.","h2":"When a raised barrier or wide median separates you from the bus, you do not have to stop, but you should still watch for children.","p":"Right. With a raised median between you, you do not have to stop, but stay alert."},"es":{"q":"En Florida, usted va por una carretera dividida con una mediana elevada. Un autobús escolar para del otro lado de la mediana. ¿Qué debe hacer?","o":["No tiene que parar, pero maneje con cuidado","Parar hasta que el autobús se vaya","Parar y luego pasar muy despacio","Cambiarse al carril más cerca del autobús"],"h1":"Piense en lo que hace la mediana elevada entre usted y el autobús.","h2":"Cuando una barrera elevada o una mediana ancha lo separa del autobús, no tiene que parar, pero debe seguir atento a los niños.","p":"Correcto. Con una mediana elevada entre ustedes, no tiene que parar, pero esté atento."},"zh":{"q":"在 Florida，你在一条有凸起中央隔离带的分隔公路上。一辆校车在隔离带的另一边停下。你应该怎么做？","o":["你不必停车，但要小心开","停车，直到校车开走","停车，然后用走路的速度开过去","换到离校车最近的车道"],"h1":"想一想凸起的隔离带在你和校车之间起了什么作用。","h2":"当凸起的护栏或很宽的中央隔离带把你和校车分开时，你不必停车，但仍然要注意孩子。","p":"对。你们之间有凸起的隔离带时，你不必停车，但要保持警觉。"},"vi":{"q":"Ở Florida, bạn đang đi trên xa lộ có dải phân cách nhô cao ở giữa. Một xe buýt trường học dừng lại ở phía bên kia dải phân cách. Bạn nên làm gì?","o":["Bạn không phải dừng lại, nhưng hãy lái cẩn thận","Dừng lại đến khi xe buýt chạy đi","Dừng lại, rồi vượt qua với tốc độ đi bộ","Chuyển sang làn gần xe buýt nhất"],"h1":"Hãy nghĩ xem dải phân cách nhô cao có tác dụng gì giữa bạn và xe buýt.","h2":"Khi có rào chắn nhô cao hoặc dải phân cách rộng ngăn cách bạn với xe buýt, bạn không phải dừng lại, nhưng vẫn nên để ý trẻ em.","p":"Đúng. Khi có dải phân cách nhô cao ở giữa, bạn không phải dừng lại, nhưng hãy luôn cảnh giác."},"tl":{"q":"Sa Florida, nasa divided highway ka na may nakataas na median. Huminto ang school bus sa kabilang bahagi ng median. Ano ang dapat mong gawin?","o":["Hindi mo kailangang huminto, pero magmaneho nang maingat","Huminto hanggang umalis ang bus","Huminto, saka lumampas sa bilis ng paglalakad","Lumipat sa lane na pinakamalapit sa bus"],"h1":"Isipin kung ano ang ginagawa ng nakataas na median sa pagitan mo at ng bus.","h2":"Kapag may nakataas na harang o malapad na median sa pagitan mo at ng bus, hindi mo kailangang huminto, pero dapat ka pa ring magbantay sa mga bata.","p":"Tama. Kapag may nakataas na median sa pagitan ninyo, hindi mo kailangang huminto, pero manatiling alerto."},"ar":{"q":"في Florida، أنت على طريق سريع مقسوم بجزيرة وسطية مرتفعة. حافلة مدرسية تتوقف في الجهة الأخرى من الجزيرة. ماذا يجب أن تفعل؟","o":["لا يجب أن تتوقف، لكن قُد بحذر","توقف حتى تذهب الحافلة","توقف، ثم تجاوز بسرعة المشي","انتقل إلى المسار الأقرب إلى الحافلة"],"h1":"فكّر في ما تفعله الجزيرة المرتفعة بينك وبين الحافلة.","h2":"عندما يفصلك حاجز مرتفع أو جزيرة وسطية عريضة عن الحافلة، لا يجب أن تتوقف، لكن يجب أن تنتبه للأطفال.","p":"صحيح. مع جزيرة مرتفعة بينكما، لا يجب أن تتوقف، لكن ابقَ منتبهًا."},"ht":{"q":"Nan Florida, ou sou yon otowout ki gen yon separasyon wo nan mitan an. Yon bis lekòl kanpe sou lòt bò separasyon an. Kisa ou ta dwe fè?","o":["Ou pa oblije kanpe, men kondi ak prekosyon","Kanpe jiskaske bis la ale","Kanpe, epi pase menm vitès ak yon moun k ap mache","Ale nan liy ki pi pre bis la"],"h1":"Panse ak sa separasyon wo a fè ant ou menm ak bis la.","h2":"Lè yon separasyon wo oswa yon separasyon ki laj nan mitan wout la separe w ak bis la, ou pa oblije kanpe, men ou ta dwe toujou veye timoun yo.","p":"Se sa. Avèk yon separasyon wo ant nou, ou pa oblije kanpe, men rete veyatif."},"ref":{"doc":"FL","page":89}},{"id":"safe-driving-013","scope":"FL","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Florida, what is the rule for holding a phone while driving in an active school zone?","o":["You may hold it for short calls","You may hold it if you drive slowly","You may not hold it; hands-free only","You may hold it only at a red light"],"h1":"Think about the extra danger near schools when children are present.","h2":"In Florida you may not hold a phone while driving in an active school zone, so you may only use it hands-free.","p":"Right. In an active school zone, no handheld phone, hands-free only."},"es":{"q":"En Florida, ¿cuál es la regla para sostener el teléfono mientras maneja en una zona escolar activa?","o":["Puede sostenerlo para llamadas cortas","Puede sostenerlo si maneja despacio","No puede sostenerlo; solo manos libres","Puede sostenerlo solo en luz roja"],"h1":"Piense en el peligro extra cerca de las escuelas cuando hay niños.","h2":"En Florida no puede sostener el teléfono mientras maneja en una zona escolar activa, así que solo puede usarlo con manos libres.","p":"Correcto. En una zona escolar activa, nada de teléfono en la mano; solo manos libres."},"zh":{"q":"在 Florida，在正在生效的学校区域开车时，拿着手机的规定是什么？","o":["打短电话时可以拿着","开得慢就可以拿着","不能拿在手里，只能免提","只在红灯时可以拿着"],"h1":"想一想有孩子在学校附近时多出来的危险。","h2":"在 Florida，在正在生效的学校区域开车时，你不能手拿手机，所以只能用免提。","p":"对。在正在生效的学校区域，不能手拿手机，只能免提。"},"vi":{"q":"Ở Florida, quy định về việc cầm điện thoại khi lái xe trong khu vực trường học đang hoạt động là gì?","o":["Bạn được cầm để gọi nhanh","Bạn được cầm nếu lái chậm","Bạn không được cầm; chỉ được dùng rảnh tay (hands-free)","Bạn chỉ được cầm khi dừng đèn đỏ"],"h1":"Hãy nghĩ đến mối nguy hiểm thêm gần trường học khi có trẻ em.","h2":"Ở Florida, bạn không được cầm điện thoại khi lái xe trong khu vực trường học đang hoạt động, nên bạn chỉ được dùng ở chế độ rảnh tay.","p":"Đúng. Trong khu vực trường học đang hoạt động, không cầm điện thoại, chỉ dùng rảnh tay."},"tl":{"q":"Sa Florida, ano ang patakaran sa paghawak ng phone habang nagmamaneho sa active school zone?","o":["Puwede mo itong hawakan para sa maiikling tawag","Puwede mo itong hawakan kung mabagal ka","Bawal itong hawakan; hands-free lang","Puwede mo itong hawakan sa red light lang"],"h1":"Isipin ang dagdag na panganib malapit sa paaralan kapag may mga bata.","h2":"Sa Florida, bawal kang humawak ng phone habang nagmamaneho sa active school zone, kaya puwede mo lang itong gamitin nang hands-free.","p":"Tama. Sa active school zone, bawal ang phone na hawak sa kamay; hands-free lang."},"ar":{"q":"في Florida، ما القاعدة عن إمساك الهاتف أثناء القيادة في منطقة مدرسة نشطة؟","o":["يمكنك أن تمسكه لمكالمات قصيرة","يمكنك أن تمسكه إذا كنت تقود ببطء","لا يُسمح لك بإمساكه؛ بدون استعمال اليدين فقط","يمكنك أن تمسكه فقط عند الإشارة الحمراء"],"h1":"فكّر في الخطر الزائد قرب المدارس عندما يكون الأطفال موجودين.","h2":"في Florida، لا يُسمح لك بإمساك الهاتف أثناء القيادة في منطقة مدرسة نشطة، لذلك يمكنك استعماله فقط بدون استعمال اليدين.","p":"صحيح. في منطقة مدرسة نشطة، لا هاتف في اليد، بدون استعمال اليدين فقط."},"ht":{"q":"Nan Florida, ki règ la pou kenbe yon telefòn nan men pandan w ap kondi nan yon zòn lekòl ki aktif?","o":["Ou ka kenbe l pou ti apèl kout","Ou ka kenbe l si w ap kondi dousman","Ou pa ka kenbe l; san men (hands-free) sèlman","Ou ka kenbe l sèlman nan limyè wouj"],"h1":"Panse ak danje anplis toupre lekòl yo lè gen timoun.","h2":"Nan Florida, ou pa gen dwa kenbe yon telefòn nan men pandan w ap kondi nan yon zòn lekòl ki aktif, kidonk ou ka itilize l sèlman san men (hands-free).","p":"Se sa. Nan yon zòn lekòl ki aktif, pa gen telefòn nan men, san men (hands-free) sèlman."},"ref":{"doc":"FL","page":34}},{"id":"safe-driving-014","scope":"FL","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Florida, can a police officer stop you only because you are texting while driving?","o":["No, only if you also break another rule","Yes, texting while driving is enough","No, texting is only a warning","Yes, but only on the interstate"],"h1":"Think about how serious Florida treats texting at the wheel.","h2":"In Florida, texting while driving is a primary offense, so an officer may stop you for that reason alone.","p":"Right. In Florida you can be stopped just for texting while driving."},"es":{"q":"En Florida, ¿puede un policía detenerlo solo porque está enviando mensajes de texto mientras maneja?","o":["No, solo si también rompe otra regla","Sí, enviar mensajes al manejar es suficiente","No, los mensajes solo reciben una advertencia","Sí, pero solo en la autopista interestatal"],"h1":"Piense en qué tan en serio toma Florida los mensajes de texto al volante.","h2":"En Florida, enviar mensajes de texto mientras maneja es una infracción principal, así que un policía puede detenerlo solo por eso.","p":"Correcto. En Florida lo pueden detener solo por enviar mensajes al manejar."},"zh":{"q":"在 Florida，警察可以只因为你开车时发短信就让你停车吗？","o":["不可以，除非你也违反了别的规定","可以，开车发短信就足够了","不可以，发短信只会被警告","可以，但只在州际公路上"],"h1":"想一想 Florida 对开车时发短信有多严肃。","h2":"在 Florida，开车发短信是主要违法行为，所以警察只因为这个原因就可以让你停车。","p":"对。在 Florida，你可能只因为开车发短信就被拦下。"},"vi":{"q":"Ở Florida, cảnh sát có thể chặn xe bạn chỉ vì bạn nhắn tin khi lái xe không?","o":["Không, chỉ khi bạn vi phạm thêm quy định khác","Có, nhắn tin khi lái xe là đủ lý do","Không, nhắn tin chỉ bị cảnh cáo","Có, nhưng chỉ trên xa lộ liên bang"],"h1":"Hãy nghĩ xem Florida coi việc nhắn tin khi cầm lái nghiêm trọng đến mức nào.","h2":"Ở Florida, nhắn tin khi lái xe là vi phạm chính (primary offense), nên cảnh sát có thể chặn xe bạn chỉ vì lý do đó.","p":"Đúng. Ở Florida, bạn có thể bị chặn xe chỉ vì nhắn tin khi lái xe."},"tl":{"q":"Sa Florida, puwede ka bang parahin ng pulis dahil lang nagte-text ka habang nagmamaneho?","o":["Hindi, kung may iba ka lang ding nilabag na patakaran","Oo, sapat na ang pag-text habang nagmamaneho","Hindi, warning lang ang pag-text","Oo, pero sa interstate lang"],"h1":"Isipin kung gaano kabigat ang tingin ng Florida sa pag-text habang nagmamaneho.","h2":"Sa Florida, ang pag-text habang nagmamaneho ay primary offense, kaya puwede kang parahin ng pulis dahil lang doon.","p":"Tama. Sa Florida, puwede kang parahin dahil lang sa pag-text habang nagmamaneho."},"ar":{"q":"في Florida، هل يمكن للشرطي أن يوقفك فقط لأنك تكتب رسائل أثناء القيادة؟","o":["لا، فقط إذا خالفت قاعدة أخرى أيضًا","نعم، كتابة الرسائل أثناء القيادة سبب كافٍ","لا، كتابة الرسائل تعطي تحذيرًا فقط","نعم، لكن فقط على الطريق السريع بين الولايات"],"h1":"فكّر في مدى جدية Florida مع كتابة الرسائل وأنت خلف المقود.","h2":"في Florida، كتابة الرسائل أثناء القيادة مخالفة أساسية، لذلك يمكن للشرطي أن يوقفك لهذا السبب وحده.","p":"صحيح. في Florida يمكن أن يوقفوك فقط لأنك تكتب رسائل أثناء القيادة."},"ht":{"q":"Nan Florida, èske yon polis ka kanpe w sèlman paske w ap voye tèks pandan w ap kondi?","o":["Non, sèlman si ou vyole yon lòt règ tou","Wi, voye tèks pandan w ap kondi ase","Non, voye tèks se yon avètisman sèlman","Wi, men sèlman sou otowout entèeta a"],"h1":"Panse ak jan Florida pran voye tèks nan volan an oserye.","h2":"Nan Florida, voye tèks pandan w ap kondi se yon enfraksyon prensipal, kidonk yon polis ka kanpe w pou rezon sa a sèlman.","p":"Se sa. Nan Florida, yo ka kanpe w sèlman paske w ap voye tèks pandan w ap kondi."},"ref":{"doc":"FL","page":null}},{"id":"safe-driving-015","scope":"FL","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Florida, what happens to a speeding fine in a work zone when workers are present?","o":["The fine is doubled","The fine is cut in half","There is no fine, only a warning","The fine is the same as anywhere else"],"h1":"Think about how the law protects people working on the road.","h2":"In Florida, the fine for speeding in a work zone is doubled when workers are present, to protect the people working there.","p":"Right. Speeding fines in a work zone are doubled when workers are present."},"es":{"q":"En Florida, ¿qué pasa con la multa por exceso de velocidad en una zona de construcción cuando hay trabajadores?","o":["La multa se duplica","La multa se reduce a la mitad","No hay multa, solo una advertencia","La multa es igual que en otro lugar"],"h1":"Piense en cómo la ley protege a las personas que trabajan en la carretera.","h2":"En Florida, la multa por exceso de velocidad en una zona de construcción se duplica cuando hay trabajadores presentes, para proteger a quienes trabajan ahí.","p":"Correcto. Las multas por exceso de velocidad en zona de construcción se duplican cuando hay trabajadores."},"zh":{"q":"在 Florida，在有工人在场的工作区超速，罚款会怎么样？","o":["罚款加倍","罚款减半","没有罚款，只有警告","罚款和其他地方一样"],"h1":"想一想法律怎样保护在路上工作的人。","h2":"在 Florida，有工人在场时，在工作区超速的罚款会加倍，这是为了保护在那里工作的人。","p":"对。有工人在场时，工作区的超速罚款加倍。"},"vi":{"q":"Ở Florida, tiền phạt chạy quá tốc độ trong khu vực thi công thay đổi thế nào khi có công nhân đang làm việc?","o":["Tiền phạt tăng gấp đôi","Tiền phạt giảm một nửa","Không bị phạt, chỉ bị cảnh cáo","Tiền phạt giống như ở nơi khác"],"h1":"Hãy nghĩ xem luật bảo vệ người làm việc trên đường như thế nào.","h2":"Ở Florida, tiền phạt chạy quá tốc độ trong khu vực thi công tăng gấp đôi khi có công nhân đang làm việc, để bảo vệ những người làm việc ở đó.","p":"Đúng. Tiền phạt chạy quá tốc độ trong khu vực thi công tăng gấp đôi khi có công nhân."},"tl":{"q":"Sa Florida, ano ang nangyayari sa multa sa overspeeding sa work zone kapag may mga trabahador?","o":["Dinodoble ang multa","Hinahati sa dalawa ang multa","Walang multa, warning lang","Pareho ang multa sa ibang lugar"],"h1":"Isipin kung paano pinoprotektahan ng batas ang mga taong nagtatrabaho sa daan.","h2":"Sa Florida, dinodoble ang multa sa overspeeding sa work zone kapag may mga trabahador, para protektahan ang mga taong nagtatrabaho roon.","p":"Tama. Dinodoble ang multa sa overspeeding sa work zone kapag may mga trabahador."},"ar":{"q":"في Florida، ماذا يحدث لغرامة السرعة في منطقة أعمال عندما يكون العمال موجودين؟","o":["الغرامة تتضاعف","الغرامة تنقص إلى النصف","لا توجد غرامة، فقط تحذير","الغرامة نفسها كما في أي مكان آخر"],"h1":"فكّر في كيف يحمي القانون الناس الذين يعملون على الطريق.","h2":"في Florida، غرامة السرعة في منطقة الأعمال تتضاعف عندما يكون العمال موجودين، لحماية الناس الذين يعملون هناك.","p":"صحيح. غرامات السرعة في منطقة الأعمال تتضاعف عندما يكون العمال موجودين."},"ht":{"q":"Nan Florida, kisa k rive amann pou vitès nan yon zòn travay lè gen travayè ki la?","o":["Amann nan double","Amann nan koupe an de","Pa gen amann, se yon avètisman sèlman","Amann nan menm jan ak nenpòt lòt kote"],"h1":"Panse ak jan lalwa pwoteje moun k ap travay sou wout la.","h2":"Nan Florida, amann pou vitès nan yon zòn travay double lè gen travayè ki la, pou pwoteje moun k ap travay la.","p":"Se sa. Amann pou vitès nan yon zòn travay double lè gen travayè ki la."},"ref":{"doc":"FL","page":29}},{"id":"safe-driving-016","scope":"US","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In a work zone, a flagger holds up a sign and signals you. What should you do?","o":["Follow the posted speed sign instead","Drive past if the lane looks clear","Honk so the flagger lets you go","Follow the flagger's signals"],"h1":"Think about who controls traffic in a work zone right now.","h2":"A flagger directs traffic in a work zone, so you must follow the flagger's signals even if other signs say something else.","p":"Right. In a work zone, follow the flagger's signals."},"es":{"q":"En una zona de construcción, un abanderado muestra una señal y le hace indicaciones. ¿Qué debe hacer?","o":["Seguir la señal de velocidad en su lugar","Pasar si el carril parece libre","Tocar la bocina para que lo deje pasar","Seguir las indicaciones del abanderado"],"h1":"Piense en quién controla el tráfico en la zona de construcción en este momento.","h2":"Un abanderado dirige el tráfico en una zona de construcción, así que debe seguir sus indicaciones aunque otras señales digan otra cosa.","p":"Correcto. En una zona de construcción, siga las indicaciones del abanderado."},"zh":{"q":"在工作区，一位旗手举起一块牌子向你打信号。你应该怎么做？","o":["改为按照路边的限速牌开","如果车道看起来没人就开过去","按喇叭让旗手放你过去","按照旗手的信号做"],"h1":"想一想现在是谁在工作区指挥交通。","h2":"旗手在工作区指挥交通，所以即使其他标志写的不一样，你也必须按照旗手的信号做。","p":"对。在工作区，按照旗手的信号做。"},"vi":{"q":"Trong khu vực thi công, một người cầm cờ điều khiển giao thông giơ biển và ra hiệu cho bạn. Bạn nên làm gì?","o":["Làm theo biển tốc độ được cắm thay vào đó","Chạy qua nếu làn đường có vẻ trống","Bấm còi để người cầm cờ cho bạn đi","Làm theo hiệu lệnh của người cầm cờ"],"h1":"Hãy nghĩ xem ai đang điều khiển giao thông trong khu vực thi công lúc này.","h2":"Người cầm cờ điều khiển giao thông trong khu vực thi công, nên bạn phải làm theo hiệu lệnh của người cầm cờ, dù các biển báo khác nói khác.","p":"Đúng. Trong khu vực thi công, hãy làm theo hiệu lệnh của người cầm cờ."},"tl":{"q":"Sa work zone, may flagger na nagtataas ng karatula at sumesenyas sa iyo. Ano ang dapat mong gawin?","o":["Sundin na lang ang nakapaskil na speed sign","Lumampas kung mukhang maluwag ang lane","Bumusina para paraanin ka ng flagger","Sundin ang mga senyas ng flagger"],"h1":"Isipin kung sino ang kumokontrol sa trapiko sa work zone ngayon.","h2":"Ang flagger ang nagdidirekta ng trapiko sa work zone, kaya dapat mong sundin ang mga senyas ng flagger kahit iba ang sinasabi ng ibang karatula.","p":"Tama. Sa work zone, sundin ang mga senyas ng flagger."},"ar":{"q":"في منطقة أعمال، عامل تنظيم السير يرفع لافتة ويعطيك إشارة. ماذا يجب أن تفعل؟","o":["اتبع لافتة السرعة المكتوبة بدلًا من ذلك","تجاوزه إذا بدا المسار فارغًا","استعمل البوق حتى يتركك تمرّ","اتبع إشارات عامل تنظيم السير"],"h1":"فكّر: من ينظّم حركة السير في منطقة الأعمال الآن؟","h2":"عامل تنظيم السير يوجّه الحركة في منطقة الأعمال، لذلك يجب أن تتبع إشاراته حتى إذا كانت اللافتات الأخرى تقول شيئًا آخر.","p":"صحيح. في منطقة الأعمال، اتبع إشارات عامل تنظيم السير."},"ht":{"q":"Nan yon zòn travay, yon travayè ki gen drapo leve yon pankat epi li fè w siy. Kisa ou ta dwe fè?","o":["Swiv pankat vitès ki poste a pito","Pase si liy lan sanble li vid","Klaksonen pou travayè a kite w pase","Swiv siy travayè ki gen drapo a"],"h1":"Panse ak kiyès ki dirije sikilasyon an nan zòn travay la kounye a.","h2":"Yon travayè ki gen drapo dirije sikilasyon an nan yon zòn travay, kidonk ou dwe swiv siy li fè yo menm si lòt pankat di yon lòt bagay.","p":"Se sa. Nan yon zòn travay, swiv siy travayè ki gen drapo a."},"ref":{"doc":"FL","page":54}},{"id":"safe-driving-017","scope":"US","cat":"safe-driving","sign":{"shape":"diamond-orange"},"c":1,"en":{"q":"What does an orange diamond-shaped sign usually warn you about?","o":["A school zone ahead","A work zone ahead","A railroad crossing ahead","A hospital ahead"],"h1":"Think about the color used for road work.","h2":"Orange warning signs are used for work zones, so an orange diamond tells you that road work is ahead.","p":"Right. An orange diamond sign warns of a work zone ahead."},"es":{"q":"¿Sobre qué le advierte normalmente una señal anaranjada en forma de rombo?","o":["Una zona escolar adelante","Una zona de construcción adelante","Un cruce de tren adelante","Un hospital adelante"],"h1":"Piense en el color que se usa para trabajos en la vía.","h2":"Las señales de advertencia anaranjadas se usan para zonas de construcción, así que un rombo anaranjado le dice que hay trabajos en la vía adelante.","p":"Correcto. Un rombo anaranjado advierte una zona de construcción adelante."},"zh":{"q":"橙色菱形标志通常提醒你注意什么？","o":["前面有学校区域","前面有工作区","前面有铁路道口","前面有医院"],"h1":"想一想道路施工用的是什么颜色。","h2":"橙色警告标志用于工作区，所以橙色菱形标志告诉你前面有道路施工。","p":"对。橙色菱形标志提醒你前面有工作区。"},"vi":{"q":"Biển báo màu cam hình thoi thường cảnh báo bạn về điều gì?","o":["Phía trước có khu vực trường học","Phía trước có khu vực thi công","Phía trước có đường ray xe lửa cắt ngang","Phía trước có bệnh viện"],"h1":"Hãy nghĩ đến màu được dùng cho công việc sửa đường.","h2":"Biển cảnh báo màu cam được dùng cho khu vực thi công, nên biển màu cam hình thoi cho bạn biết phía trước có công việc sửa đường.","p":"Đúng. Biển màu cam hình thoi cảnh báo phía trước có khu vực thi công."},"tl":{"q":"Ano ang karaniwang babala ng karatulang kulay orange na hugis diamond?","o":["May school zone sa unahan","May work zone sa unahan","May tawiran ng tren sa unahan","May ospital sa unahan"],"h1":"Isipin ang kulay na ginagamit para sa trabaho sa daan.","h2":"Ang mga karatulang babala na kulay orange ay ginagamit para sa mga work zone, kaya ang orange na diamond ay nagsasabing may trabaho sa daan sa unahan.","p":"Tama. Ang orange na diamond na karatula ay babala na may work zone sa unahan."},"ar":{"q":"لافتة برتقالية على شكل معيّن (مثل الماسة). مِمّ تحذّرك عادةً؟","o":["منطقة مدرسة أمامك","منطقة أعمال أمامك","تقاطع سكة حديد أمامك","مستشفى أمامك"],"h1":"فكّر في اللون المستعمل لأعمال الطرق.","h2":"لافتات التحذير البرتقالية تُستعمل لمناطق الأعمال، لذلك اللافتة البرتقالية على شكل معيّن تخبرك بأن هناك أعمال طرق أمامك.","p":"صحيح. اللافتة البرتقالية على شكل معيّن تحذّر من منطقة أعمال أمامك."},"ht":{"q":"Kisa yon pankat oranj ki gen fòm dyaman (lozanj) konn avèti w?","o":["Yon zòn lekòl devan","Yon zòn travay devan","Yon kwazman tren devan","Yon lopital devan"],"h1":"Panse ak koulè yo itilize pou travay sou wout.","h2":"Yo itilize pankat avètisman oranj pou zòn travay, kidonk yon dyaman oranj di w gen travay sou wout la devan.","p":"Se sa. Yon pankat dyaman oranj avèti w gen yon zòn travay devan."},"ref":{"doc":"FL","page":54}},{"id":"safe-driving-018","scope":"FL","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Florida, a police car is stopped on the shoulder with its lights flashing. You are on a highway with two lanes going your way. What should you do?","o":["Keep your speed and stay in your lane","Stop next to the police car","Move over a lane if safe; if not, slow down","Speed up to pass the area quickly"],"h1":"Think about giving space to people working beside the road.","h2":"Florida's Move Over law says you must move out of the lane next to the stopped vehicle when it is safe, and if you cannot, you must slow down.","p":"Right. Move over a lane if you safely can, or slow down."},"es":{"q":"En Florida, un carro de policía está parado en el acotamiento con las luces encendidas. Usted va por una carretera con dos carriles en su dirección. ¿Qué debe hacer?","o":["Mantener su velocidad y su carril","Parar al lado del carro de policía","Cambiarse de carril si es seguro; si no, bajar la velocidad","Acelerar para pasar rápido"],"h1":"Piense en dar espacio a las personas que trabajan al lado de la vía.","h2":"La ley Move Over de Florida dice que debe salir del carril junto al vehículo detenido cuando sea seguro, y si no puede, debe bajar la velocidad.","p":"Correcto. Cámbiese de carril si es seguro, o baje la velocidad."},"zh":{"q":"在 Florida，一辆警车停在路肩上，灯在闪。你在一条你这个方向有两条车道的公路上。你应该怎么做？","o":["保持速度，留在你的车道","停在警车旁边","安全的话就换开一条车道；不行的话就减速","加速，快点开过这个地方"],"h1":"想一想给在路边工作的人留出空间。","h2":"Florida 的 Move Over 法律规定，安全时你必须离开紧挨停着的车辆的那条车道；如果不能，你就必须减速。","p":"对。安全的话就换开一条车道，不行就减速。"},"vi":{"q":"Ở Florida, một xe cảnh sát đang dừng trên lề đường và nháy đèn. Bạn đang đi trên xa lộ có hai làn cùng chiều với bạn. Bạn nên làm gì?","o":["Giữ tốc độ và ở yên trong làn","Dừng lại cạnh xe cảnh sát","Chuyển sang làn khác nếu an toàn; nếu không, hãy giảm tốc","Tăng tốc để đi qua khu vực đó thật nhanh"],"h1":"Hãy nghĩ đến việc chừa chỗ cho những người đang làm việc bên đường.","h2":"Luật Move Over của Florida nói rằng bạn phải rời khỏi làn sát xe đang dừng khi an toàn, và nếu không thể, bạn phải giảm tốc.","p":"Đúng. Chuyển sang làn khác nếu an toàn, hoặc giảm tốc."},"tl":{"q":"Sa Florida, may police car na nakahinto sa shoulder at kumikislap ang mga ilaw nito. Nasa highway ka na may dalawang lane papunta sa direksyon mo. Ano ang dapat mong gawin?","o":["Panatilihin ang bilis mo at manatili sa lane mo","Huminto sa tabi ng police car","Lumipat ng isang lane kung ligtas; kung hindi, bumagal","Bumilis para mabilis na malampasan ang lugar"],"h1":"Isipin ang pagbibigay ng espasyo sa mga taong nagtatrabaho sa tabi ng daan.","h2":"Sinasabi ng Move Over law ng Florida na dapat kang umalis sa lane na katabi ng nakahintong sasakyan kapag ligtas, at kung hindi mo kaya, dapat kang bumagal.","p":"Tama. Lumipat ng isang lane kung ligtas mong magagawa, o bumagal."},"ar":{"q":"في Florida، سيارة شرطة متوقفة على كتف الطريق وأضواؤها تومض. أنت على طريق سريع فيه مساران في اتجاهك. ماذا يجب أن تفعل؟","o":["حافظ على سرعتك وابقَ في مسارك","توقف بجانب سيارة الشرطة","انتقل مسارًا واحدًا بعيدًا إذا كان ذلك آمنًا؛ وإذا لم يكن آمنًا، خفّف السرعة","أسرع لتمرّ من المكان بسرعة"],"h1":"فكّر في إعطاء مساحة للناس الذين يعملون بجانب الطريق.","h2":"قانون Move Over في Florida يقول إنه يجب أن تخرج من المسار المجاور للمركبة المتوقفة عندما يكون ذلك آمنًا، وإذا لم تستطع، يجب أن تخفّف السرعة.","p":"صحيح. انتقل مسارًا واحدًا إذا استطعت بأمان، أو خفّف السرعة."},"ht":{"q":"Nan Florida, yon machin polis kanpe bò wout la ak limyè l ap flache. Ou sou yon otowout ki gen de liy nan direksyon pa w. Kisa ou ta dwe fè?","o":["Kenbe menm vitès la epi rete nan liy ou","Kanpe bò kote machin polis la","Chanje liy si li an sekirite; si se pa sa, ralanti","Akselere pou pase zòn nan vit"],"h1":"Panse ak bay moun k ap travay bò wout la espas.","h2":"Lwa Move Over Florida a di ou dwe soti nan liy ki bò kote machin ki kanpe a lè li an sekirite, epi si ou pa kapab, ou dwe ralanti.","p":"Se sa. Chanje liy si ou ka fè l san danje, oswa ralanti."},"ref":{"doc":"FL","page":65}},{"id":"safe-driving-019","scope":"FL","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Florida, you cannot move over for a stopped emergency vehicle on a road with a 55 mph limit. How slow must you go?","o":["20 mph below the limit","5 mph below the limit","10 mph below the limit","Exactly 25 mph"],"h1":"Think about a big drop in speed, not a small one.","h2":"Under Florida's Move Over law, if you cannot change lanes you must slow to 20 mph below the posted limit, so on a 55 mph road you go 35 mph.","p":"Right. If you cannot move over, slow to 20 mph below the limit."},"es":{"q":"En Florida, usted no puede cambiarse de carril ante un vehículo de emergencia detenido en una vía con límite de 55 mph. ¿A qué velocidad debe ir?","o":["20 mph por debajo del límite","5 mph por debajo del límite","10 mph por debajo del límite","Exactamente 25 mph"],"h1":"Piense en una reducción grande de velocidad, no pequeña.","h2":"Según la ley Move Over de Florida, si no puede cambiarse de carril debe bajar a 20 mph por debajo del límite, así que en una vía de 55 mph va a 35 mph.","p":"Correcto. Si no puede cambiarse de carril, baje 20 mph por debajo del límite."},"zh":{"q":"在 Florida，在限速 55 mph 的路上，你不能为停着的紧急车辆换车道。你必须减到多慢？","o":["比限速低 20 mph","比限速低 5 mph","比限速低 10 mph","正好 25 mph"],"h1":"想一想大幅度减速，而不是一点点。","h2":"按照 Florida 的 Move Over 法律，如果你不能换车道，就必须减到比标示的限速低 20 mph，所以在 55 mph 的路上你要开 35 mph。","p":"对。如果不能换车道，就减到比限速低 20 mph。"},"vi":{"q":"Ở Florida, bạn không thể chuyển làn để tránh một xe cấp cứu đang dừng trên đường có giới hạn 55 mph. Bạn phải chạy chậm đến mức nào?","o":["Thấp hơn giới hạn 20 mph","Thấp hơn giới hạn 5 mph","Thấp hơn giới hạn 10 mph","Đúng 25 mph"],"h1":"Hãy nghĩ đến việc giảm tốc độ nhiều, không phải chỉ một chút.","h2":"Theo luật Move Over của Florida, nếu không thể chuyển làn, bạn phải giảm xuống thấp hơn giới hạn được cắm biển 20 mph, nên trên đường 55 mph bạn chạy 35 mph.","p":"Đúng. Nếu không thể chuyển làn, hãy giảm xuống thấp hơn giới hạn 20 mph."},"tl":{"q":"Sa Florida, hindi ka makalipat ng lane para sa nakahintong emergency vehicle sa daang may 55 mph na limit. Gaano ka dapat kabagal?","o":["20 mph na mas mababa sa limit","5 mph na mas mababa sa limit","10 mph na mas mababa sa limit","Eksaktong 25 mph"],"h1":"Isipin ang malaking pagbaba ng bilis, hindi maliit.","h2":"Ayon sa Move Over law ng Florida, kung hindi ka makalipat ng lane, dapat kang bumagal sa 20 mph na mas mababa sa nakapaskil na limit, kaya sa daang 55 mph ay 35 mph ang takbo mo.","p":"Tama. Kung hindi ka makalipat, bumagal sa 20 mph na mas mababa sa limit."},"ar":{"q":"في Florida، لا تستطيع أن تبتعد عن مركبة طوارئ متوقفة، على طريق حد السرعة فيه 55 mph (ميلًا في الساعة). إلى أي سرعة يجب أن تخفّف؟","o":["20 mph أقل من الحد","5 mph أقل من الحد","10 mph أقل من الحد","25 mph بالضبط"],"h1":"فكّر في نقص كبير في السرعة، وليس نقصًا صغيرًا.","h2":"حسب قانون Move Over في Florida، إذا لم تستطع تغيير المسار يجب أن تخفّف سرعتك إلى 20 mph أقل من الحد المكتوب، فعلى طريق حده 55 mph تسير بسرعة 35 mph.","p":"صحيح. إذا لم تستطع الابتعاد، خفّف سرعتك إلى 20 mph أقل من الحد."},"ht":{"q":"Nan Florida, ou pa ka chanje liy pou yon machin ijans ki kanpe sou yon wout kote limit la se 55 mph. Ki vitès ou dwe desann?","o":["20 mph anba limit la","5 mph anba limit la","10 mph anba limit la","Egzakteman 25 mph"],"h1":"Panse ak yon gwo bès nan vitès, pa yon ti bès.","h2":"Dapre lwa Move Over Florida a, si ou pa ka chanje liy, ou dwe ralanti pou w kondi 20 mph anba limit ki poste a, kidonk sou yon wout 55 mph ou kondi a 35 mph.","p":"Se sa. Si ou pa ka chanje liy, ralanti a 20 mph anba limit la."},"ref":{"doc":"FL","page":65}},{"id":"safe-driving-020","scope":"US","cat":"safe-driving","sign":null,"c":3,"en":{"q":"Your car starts to skid on a slippery road. What should you do?","o":["Slam on the brakes hard","Turn the wheel sharply the other way","Press the gas to get control back","Ease off the gas and steer where you want to go"],"h1":"Think about gentle moves, not sudden ones.","h2":"In a skid, sudden braking or sharp steering makes it worse, so you should ease off the gas and gently steer in the direction you want the car to go.","p":"Right. Ease off the gas and steer where you want to go."},"es":{"q":"Su carro empieza a patinar en una vía resbalosa. ¿Qué debe hacer?","o":["Frenar de golpe con fuerza","Girar el volante bruscamente al otro lado","Acelerar para recuperar el control","Soltar el acelerador y dirigir hacia donde quiere ir"],"h1":"Piense en movimientos suaves, no bruscos.","h2":"Al patinar, frenar de golpe o girar bruscamente lo empeora, así que debe soltar el acelerador y dirigir suavemente hacia donde quiere que vaya el carro.","p":"Correcto. Suelte el acelerador y dirija hacia donde quiere ir."},"zh":{"q":"你的车在很滑的路上开始打滑。你应该怎么做？","o":["用力猛踩刹车","把方向盘猛地往反方向转","踩油门来重新控制车","慢慢松开油门，把方向盘转向你想去的方向"],"h1":"想一想轻柔的动作，而不是突然的动作。","h2":"打滑时，突然刹车或猛转方向盘会让情况更糟，所以你应该慢慢松开油门，轻轻地把方向盘转向你想让车去的方向。","p":"对。慢慢松开油门，转向你想去的方向。"},"vi":{"q":"Xe của bạn bắt đầu bị trượt trên đường trơn. Bạn nên làm gì?","o":["Đạp phanh thật mạnh","Đánh tay lái gắt sang hướng ngược lại","Nhấn ga để lấy lại kiểm soát","Nhả ga từ từ và lái về hướng bạn muốn đi"],"h1":"Hãy nghĩ đến những động tác nhẹ nhàng, không đột ngột.","h2":"Khi xe bị trượt, phanh gấp hoặc đánh lái gắt sẽ làm tệ hơn, nên bạn nên nhả ga từ từ và nhẹ nhàng lái về hướng bạn muốn xe đi.","p":"Đúng. Nhả ga từ từ và lái về hướng bạn muốn đi."},"tl":{"q":"Nagsisimulang dumulas ang kotse mo sa madulas na daan. Ano ang dapat mong gawin?","o":["Tapakan nang malakas ang preno","Biglang iikot ang manibela sa kabilang direksyon","Tapakan ang gas para makontrol ulit","Dahan-dahang bitawan ang gas at imaneho kung saan mo gustong pumunta"],"h1":"Isipin ang mahinahong galaw, hindi ang biglaan.","h2":"Sa pagdulas, lumalala ito kapag biglang nagpreno o biglang iniikot ang manibela, kaya dapat mong dahan-dahang bitawan ang gas at marahang imaneho ang kotse sa direksyong gusto mo.","p":"Tama. Dahan-dahang bitawan ang gas at imaneho kung saan mo gustong pumunta."},"ar":{"q":"سيارتك تبدأ بالانزلاق على طريق زلق. ماذا يجب أن تفعل؟","o":["اضغط على الفرامل بقوة","أدِر المقود بقوة إلى الجهة الأخرى","اضغط على البنزين لتستعيد السيطرة","ارفع قدمك عن البنزين بهدوء ووجّه السيارة إلى حيث تريد أن تذهب"],"h1":"فكّر في حركات هادئة، وليس حركات مفاجئة.","h2":"أثناء الانزلاق، الفرملة المفاجئة أو إدارة المقود بقوة تجعل الوضع أسوأ، لذلك يجب أن ترفع قدمك عن البنزين بهدوء وتوجّه السيارة بلطف إلى الاتجاه الذي تريده.","p":"صحيح. ارفع قدمك عن البنزين بهدوء ووجّه السيارة إلى حيث تريد أن تذهب."},"ht":{"q":"Machin ou kòmanse glise sou yon wout ki glise. Kisa ou ta dwe fè?","o":["Peze fren an fò sanzatann","Vire volan an rapid nan lòt direksyon an","Peze gaz la pou w reprann kontwòl","Leve pye ou dousman sou gaz la epi dirije machin nan kote ou vle ale"],"h1":"Panse ak mouvman dous, pa mouvman sanzatann.","h2":"Lè machin nan ap glise, frennen sanzatann oswa vire volan an rapid fè l pi mal, kidonk ou ta dwe leve pye ou dousman sou gaz la epi dirije machin nan dousman nan direksyon ou vle l ale.","p":"Se sa. Leve pye ou sou gaz la epi dirije machin nan kote ou vle ale."},"ref":{"doc":"FL","page":79}},{"id":"safe-driving-021","scope":"US","cat":"safe-driving","sign":null,"c":1,"en":{"q":"Your tires start to ride on top of water on a wet road (hydroplaning). What should you do?","o":["Brake hard right away","Ease off the gas and steer where you want to go","Speed up to get through the water","Turn the wheel quickly left and right"],"h1":"Think about letting the tires touch the road again.","h2":"When you hydroplane, the tires lose their grip on the road, so you should ease off the gas, stay off the brakes, and gently steer where you want to go.","p":"Right. Ease off the gas, avoid the brakes, and steer where you want to go."},"es":{"q":"Sus llantas empiezan a deslizarse sobre el agua en una vía mojada (hidroplaneo). ¿Qué debe hacer?","o":["Frenar fuerte de inmediato","Soltar el acelerador y dirigir hacia donde quiere ir","Acelerar para pasar el agua","Mover el volante rápido a los lados"],"h1":"Piense en dejar que las llantas vuelvan a tocar la vía.","h2":"En el hidroplaneo las llantas pierden el agarre con la vía, así que debe soltar el acelerador, no usar los frenos y dirigir suavemente hacia donde quiere ir.","p":"Correcto. Suelte el acelerador, no frene y dirija hacia donde quiere ir."},"zh":{"q":"在湿的路上，你的轮胎开始浮在水面上（水滑）。你应该怎么做？","o":["马上用力刹车","慢慢松开油门，把方向盘转向你想去的方向","加速冲过水","把方向盘快速地左右转"],"h1":"想一想让轮胎重新接触路面。","h2":"发生水滑时，轮胎失去了对路面的抓地力，所以你应该慢慢松开油门，不要踩刹车，轻轻地把方向盘转向你想去的方向。","p":"对。慢慢松开油门，不要踩刹车，转向你想去的方向。"},"vi":{"q":"Bánh xe của bạn bắt đầu lướt trên mặt nước trên đường ướt (hydroplaning). Bạn nên làm gì?","o":["Phanh mạnh ngay lập tức","Nhả ga từ từ và lái về hướng bạn muốn đi","Tăng tốc để đi qua vùng nước","Đánh tay lái nhanh qua trái qua phải"],"h1":"Hãy nghĩ đến việc để bánh xe chạm lại mặt đường.","h2":"Khi xe lướt nước, bánh xe mất độ bám đường, nên bạn nên nhả ga từ từ, không đạp phanh, và nhẹ nhàng lái về hướng bạn muốn đi.","p":"Đúng. Nhả ga từ từ, tránh đạp phanh, và lái về hướng bạn muốn đi."},"tl":{"q":"Nagsisimulang lumutang sa ibabaw ng tubig ang mga gulong mo sa basang daan (hydroplaning). Ano ang dapat mong gawin?","o":["Magpreno nang malakas agad","Dahan-dahang bitawan ang gas at imaneho kung saan mo gustong pumunta","Bumilis para malampasan ang tubig","Mabilis na iikot ang manibela pakaliwa at pakanan"],"h1":"Isipin kung paano muling dadampi sa daan ang mga gulong.","h2":"Kapag nag-hydroplane ka, nawawalan ng kapit sa daan ang mga gulong, kaya dapat mong dahan-dahang bitawan ang gas, huwag magpreno, at marahang imaneho kung saan mo gustong pumunta.","p":"Tama. Dahan-dahang bitawan ang gas, iwasan ang preno, at imaneho kung saan mo gustong pumunta."},"ar":{"q":"إطاراتك بدأت تسير فوق الماء على طريق مبلل (انزلاق مائي). ماذا يجب أن تفعل؟","o":["اضغط على الفرامل بقوة فورًا","ارفع قدمك عن البنزين بهدوء ووجّه السيارة إلى حيث تريد أن تذهب","أسرع لتعبر الماء","أدِر المقود بسرعة يمينًا ويسارًا"],"h1":"فكّر في أن تترك الإطارات تلمس الطريق مرة أخرى.","h2":"في الانزلاق المائي، الإطارات تفقد تماسكها مع الطريق، لذلك يجب أن ترفع قدمك عن البنزين بهدوء، وألا تستعمل الفرامل، وأن توجّه السيارة بلطف إلى حيث تريد أن تذهب.","p":"صحيح. ارفع قدمك عن البنزين، وتجنّب الفرامل، ووجّه السيارة إلى حيث تريد أن تذهب."},"ht":{"q":"Kawotchou ou yo kòmanse woule sou dlo a sou yon wout mouye (hydroplaning). Kisa ou ta dwe fè?","o":["Frennen fò touswit","Leve pye ou dousman sou gaz la epi dirije machin nan kote ou vle ale","Akselere pou w travèse dlo a","Vire volan an vit agoch ak adwat"],"h1":"Panse ak kite kawotchou yo touche wout la ankò.","h2":"Lè kawotchou yo ap glise sou dlo (hydroplaning), yo pèdi kenbe yo sou wout la, kidonk ou ta dwe leve pye ou dousman sou gaz la, pa touche fren an, epi dirije machin nan dousman kote ou vle ale.","p":"Se sa. Leve pye ou sou gaz la, pa touche fren an, epi dirije machin nan kote ou vle ale."},"ref":{"doc":"FL","page":79}},{"id":"safe-driving-022","scope":"US","cat":"safe-driving","sign":null,"c":0,"en":{"q":"A front tire suddenly blows out while you are driving. What should you do first?","o":["Hold the wheel firmly and ease off the gas","Brake hard to stop right away","Steer quickly onto the shoulder","Speed up to keep the car straight"],"h1":"Think about keeping control of the car before you stop.","h2":"A blowout can pull the car to one side, so you should hold the wheel firmly, ease off the gas, and brake gently only after the car is under control.","p":"Right. Hold the wheel firmly and ease off the gas."},"es":{"q":"Una llanta delantera revienta de repente mientras maneja. ¿Qué debe hacer primero?","o":["Sostener firme el volante y soltar el acelerador","Frenar fuerte para parar de inmediato","Girar rápido hacia el acotamiento","Acelerar para mantener el carro derecho"],"h1":"Piense en mantener el control del carro antes de parar.","h2":"Una llanta reventada puede jalar el carro hacia un lado, así que debe sostener firme el volante, soltar el acelerador y frenar suave solo cuando tenga el control.","p":"Correcto. Sostenga firme el volante y suelte el acelerador."},"zh":{"q":"你开车时，一个前轮突然爆胎。你首先应该做什么？","o":["紧紧握住方向盘，慢慢松开油门","用力刹车，马上停下","快速转到路肩上","加速让车保持直行"],"h1":"想一想在停车前先控制住车。","h2":"爆胎可能会把车拉向一边，所以你应该紧紧握住方向盘，慢慢松开油门，等车被控制住以后再轻轻刹车。","p":"对。紧紧握住方向盘，慢慢松开油门。"},"vi":{"q":"Một bánh xe trước đột nhiên bị nổ khi bạn đang lái. Bạn nên làm gì trước tiên?","o":["Giữ chặt tay lái và nhả ga từ từ","Phanh mạnh để dừng ngay","Lái nhanh vào lề đường","Tăng tốc để giữ xe đi thẳng"],"h1":"Hãy nghĩ đến việc giữ kiểm soát xe trước khi dừng lại.","h2":"Nổ lốp có thể kéo xe lệch sang một bên, nên bạn nên giữ chặt tay lái, nhả ga từ từ, và chỉ phanh nhẹ sau khi đã kiểm soát được xe.","p":"Đúng. Giữ chặt tay lái và nhả ga từ từ."},"tl":{"q":"Biglang pumutok ang gulong sa harap habang nagmamaneho ka. Ano ang una mong dapat gawin?","o":["Hawakan nang mahigpit ang manibela at dahan-dahang bitawan ang gas","Magpreno nang malakas para huminto agad","Mabilis na lumihis papunta sa shoulder","Bumilis para manatiling diretso ang kotse"],"h1":"Isipin ang pagkontrol sa kotse bago ka huminto.","h2":"Ang pagputok ng gulong ay puwedeng humila sa kotse sa isang tabi, kaya dapat mong hawakan nang mahigpit ang manibela, dahan-dahang bitawan ang gas, at marahang magpreno pagkatapos lang makontrol ang kotse.","p":"Tama. Hawakan nang mahigpit ang manibela at dahan-dahang bitawan ang gas."},"ar":{"q":"إطار أمامي انفجر فجأة وأنت تقود. ماذا يجب أن تفعل أولًا؟","o":["أمسك المقود بقوة وارفع قدمك عن البنزين بهدوء","اضغط على الفرامل بقوة لتتوقف فورًا","وجّه السيارة بسرعة إلى كتف الطريق","أسرع لتبقى السيارة مستقيمة"],"h1":"فكّر في السيطرة على السيارة قبل أن تتوقف.","h2":"انفجار الإطار قد يسحب السيارة إلى جهة واحدة، لذلك يجب أن تمسك المقود بقوة، وترفع قدمك عن البنزين بهدوء، وتضغط الفرامل بلطف فقط بعد أن تسيطر على السيارة.","p":"صحيح. أمسك المقود بقوة وارفع قدمك عن البنزين بهدوء."},"ht":{"q":"Yon kawotchou devan pete sanzatann pandan w ap kondi. Kisa ou ta dwe fè anvan?","o":["Kenbe volan an fèm epi leve pye ou dousman sou gaz la","Frennen fò pou kanpe touswit","Vire vit pou w ale bò wout la","Akselere pou kenbe machin nan dwat"],"h1":"Panse ak kenbe kontwòl machin nan anvan ou kanpe.","h2":"Yon kawotchou ki pete ka rale machin nan sou yon bò, kidonk ou ta dwe kenbe volan an fèm, leve pye ou dousman sou gaz la, epi frennen dousman sèlman apre ou gen kontwòl machin nan.","p":"Se sa. Kenbe volan an fèm epi leve pye ou dousman sou gaz la."},"ref":{"doc":"FL","page":80}},{"id":"safe-driving-023","scope":"US","cat":"safe-driving","sign":null,"c":2,"en":{"q":"You press the brake pedal and your brakes do not work. What should you try first?","o":["Turn off the engine right away","Open the door and drag your foot","Pump the brake pedal fast","Shift into reverse"],"h1":"Think about trying to build up brake pressure again.","h2":"Pumping the brake pedal may build up pressure again, and if that fails you can use the parking brake slowly and shift to a lower gear.","p":"Right. Pump the brake pedal first, then use the parking brake."},"es":{"q":"Usted pisa el freno y los frenos no funcionan. ¿Qué debe intentar primero?","o":["Apagar el motor de inmediato","Abrir la puerta y arrastrar el pie","Bombear el pedal del freno rápido","Poner la reversa"],"h1":"Piense en volver a crear presión en los frenos.","h2":"Bombear el pedal del freno puede volver a crear presión, y si no funciona, puede usar el freno de mano poco a poco y cambiar a una velocidad más baja.","p":"Correcto. Bombee el pedal primero y luego use el freno de mano."},"zh":{"q":"你踩刹车踏板，可是刹车不灵。你首先应该试什么？","o":["马上关掉引擎","打开车门，用脚拖地","快速地连续踩刹车踏板","挂倒挡"],"h1":"想一想怎样让刹车重新产生压力。","h2":"快速连续踩刹车踏板可能会让压力重新建立起来；如果不行，你可以慢慢拉手刹，并换到低挡。","p":"对。先连续踩刹车踏板，然后用手刹。"},"vi":{"q":"Bạn đạp bàn đạp phanh nhưng phanh không ăn. Bạn nên thử làm gì trước tiên?","o":["Tắt máy xe ngay lập tức","Mở cửa và kéo chân xuống đất","Đạp nhấp bàn đạp phanh liên tục và nhanh","Chuyển sang số lùi"],"h1":"Hãy nghĩ đến việc cố tạo lại áp lực phanh.","h2":"Đạp nhấp bàn đạp phanh có thể tạo lại áp lực, và nếu không được, bạn có thể kéo phanh tay từ từ và chuyển xuống số thấp hơn.","p":"Đúng. Đạp nhấp bàn đạp phanh trước, rồi dùng phanh tay."},"tl":{"q":"Tinapakan mo ang preno at hindi gumagana ang preno mo. Ano ang una mong dapat subukan?","o":["Patayin agad ang makina","Buksan ang pinto at ikaskas ang paa mo sa daan","Mabilis na tapak-tapakan ang preno nang paulit-ulit","Ilagay sa reverse"],"h1":"Isipin ang pagsubok na muling magkaroon ng pressure sa preno.","h2":"Ang paulit-ulit at mabilis na pagtapak sa preno ay puwedeng magbalik ng pressure, at kung hindi ito gumana, puwede mong dahan-dahang gamitin ang parking brake at ilipat sa mas mababang gear.","p":"Tama. Tapak-tapakan muna ang preno, saka gamitin ang parking brake."},"ar":{"q":"تضغط على دواسة الفرامل والفرامل لا تعمل. ماذا يجب أن تجرّب أولًا؟","o":["أطفئ المحرك فورًا","افتح الباب واسحب قدمك على الأرض","اضغط على دواسة الفرامل مرات سريعة متتالية","انقل الغيار إلى الخلف (reverse)"],"h1":"فكّر في محاولة بناء ضغط الفرامل مرة أخرى.","h2":"الضغط على دواسة الفرامل مرات متتالية قد يبني الضغط مرة أخرى، وإذا لم ينجح ذلك يمكنك استعمال فرامل اليد ببطء والنقل إلى غيار أدنى.","p":"صحيح. اضغط على دواسة الفرامل مرات متتالية أولًا، ثم استعمل فرامل اليد."},"ht":{"q":"Ou peze pedal fren an epi fren yo pa mache. Kisa ou ta dwe eseye anvan?","o":["Fèmen motè a touswit","Louvri pòt la epi trennen pye ou atè","Peze pedal fren an plizyè fwa vit","Mete machin nan an mach aryè"],"h1":"Panse ak eseye fè presyon fren an monte ankò.","h2":"Lè ou peze pedal fren an plizyè fwa vit, sa ka fè presyon an monte ankò, epi si sa pa mache, ou ka sèvi ak fren a men an dousman epi mete yon vitès ki pi ba.","p":"Se sa. Peze pedal fren an plizyè fwa anvan, epi sèvi ak fren a men an."}},{"id":"safe-driving-024","scope":"US","cat":"safe-driving","sign":null,"c":3,"en":{"q":"Your gas pedal gets stuck and the car keeps speeding up. What should you do?","o":["Pull the key out while moving","Turn the wheel hard to the side","Pump the gas pedal many times","Shift to neutral and brake"],"h1":"Think about how to stop the engine from pushing the wheels.","h2":"Shifting to neutral stops the engine from driving the wheels, so you can brake, pull off the road, and then turn off the engine.","p":"Right. Shift to neutral and brake to a safe stop."},"es":{"q":"Su pedal del acelerador se traba y el carro sigue acelerando. ¿Qué debe hacer?","o":["Sacar la llave mientras se mueve","Girar el volante fuerte hacia un lado","Bombear el acelerador muchas veces","Poner neutro y frenar"],"h1":"Piense en cómo impedir que el motor siga empujando las ruedas.","h2":"Al poner neutro el motor deja de mover las ruedas, así que puede frenar, salir de la vía y luego apagar el motor.","p":"Correcto. Ponga neutro y frene hasta parar con seguridad."},"zh":{"q":"你的油门踏板卡住了，车一直在加速。你应该怎么做？","o":["开车时把钥匙拔出来","把方向盘用力转向一边","连续踩很多次油门","换到空挡并刹车"],"h1":"想一想怎样让引擎不再推动车轮。","h2":"换到空挡后，引擎就不再带动车轮，所以你可以刹车，把车开离道路，然后关掉引擎。","p":"对。换到空挡，刹车，安全地停下来。"},"vi":{"q":"Bàn đạp ga của bạn bị kẹt và xe cứ tăng tốc. Bạn nên làm gì?","o":["Rút chìa khóa ra khi xe đang chạy","Đánh tay lái mạnh sang một bên","Đạp nhấp bàn đạp ga nhiều lần","Chuyển sang số N (số mo) và phanh"],"h1":"Hãy nghĩ cách để động cơ không đẩy bánh xe nữa.","h2":"Chuyển sang số N làm động cơ không còn đẩy bánh xe, nên bạn có thể phanh, tấp vào lề, rồi tắt máy.","p":"Đúng. Chuyển sang số N và phanh để dừng an toàn."},"tl":{"q":"Naipit ang gas pedal mo at patuloy na bumibilis ang kotse. Ano ang dapat mong gawin?","o":["Bunutin ang susi habang umaandar","Iikot nang malakas ang manibela sa gilid","Tapak-tapakan ang gas nang maraming beses","Ilagay sa neutral at magpreno"],"h1":"Isipin kung paano pipigilan ang makina sa pagtulak sa mga gulong.","h2":"Kapag inilagay sa neutral, hindi na itinutulak ng makina ang mga gulong, kaya puwede kang magpreno, tumabi sa daan, at saka patayin ang makina.","p":"Tama. Ilagay sa neutral at magpreno hanggang ligtas na huminto."},"ar":{"q":"دواسة البنزين علقت والسيارة تستمر في زيادة السرعة. ماذا يجب أن تفعل؟","o":["اسحب المفتاح والسيارة تتحرك","أدِر المقود بقوة إلى الجانب","اضغط على دواسة البنزين مرات كثيرة","انقل الغيار إلى المحايد (neutral) واضغط الفرامل"],"h1":"فكّر في كيف تمنع المحرك من دفع العجلات.","h2":"النقل إلى المحايد (neutral) يمنع المحرك من تحريك العجلات، فتستطيع أن تضغط الفرامل، وتخرج من الطريق، ثم تطفئ المحرك.","p":"صحيح. انقل الغيار إلى المحايد (neutral) واضغط الفرامل حتى تتوقف بأمان."},"ht":{"q":"Pedal gaz ou a bloke epi machin nan kontinye ap akselere. Kisa ou ta dwe fè?","o":["Rale kle a pandan machin nan ap woule","Vire volan an fò sou kote","Peze pedal gaz la anpil fwa","Mete machin nan an netral (N) epi frennen"],"h1":"Panse ak kijan pou w anpeche motè a pouse wou yo.","h2":"Lè ou mete machin nan an netral (N), motè a pa pouse wou yo ankò, kidonk ou ka frennen, soti sou bò wout la, epi apre sa fèmen motè a.","p":"Se sa. Mete machin nan an netral (N) epi frennen pou w kanpe san danje."},"ref":{"doc":"FL","page":79}},{"id":"safe-driving-025","scope":"US","cat":"safe-driving","sign":null,"c":1,"en":{"q":"Your right wheels drift off the pavement onto the dirt edge. What should you do?","o":["Jerk the wheel back onto the road","Ease off the gas, slow down, then steer back gently","Brake hard right away","Speed up and steer back fast"],"h1":"Think about slowing down before you return to the road.","h2":"Turning back too fast can make you lose control, so ease off the gas, slow down, and then steer gently back onto the pavement when it is safe.","p":"Right. Slow down first, then steer back gently."},"es":{"q":"Sus ruedas derechas se salen del pavimento a la orilla de tierra. ¿Qué debe hacer?","o":["Jalar el volante de golpe hacia la vía","Soltar el acelerador, bajar la velocidad y volver suavemente","Frenar fuerte de inmediato","Acelerar y volver rápido a la vía"],"h1":"Piense en bajar la velocidad antes de volver a la vía.","h2":"Volver demasiado rápido puede hacerle perder el control, así que suelte el acelerador, baje la velocidad y vuelva suavemente al pavimento cuando sea seguro.","p":"Correcto. Primero baje la velocidad y luego vuelva suavemente."},"zh":{"q":"你右边的车轮偏出了路面，开到了泥土路边上。你应该怎么做？","o":["猛地把方向盘转回路上","慢慢松开油门，减速，然后轻轻地转回去","马上用力刹车","加速，快速转回去"],"h1":"想一想在回到路上之前先减速。","h2":"转回去太快会让你失去控制，所以要慢慢松开油门，减速，然后在安全时轻轻地把车转回路面。","p":"对。先减速，然后轻轻地转回去。"},"vi":{"q":"Bánh xe bên phải của bạn trôi ra khỏi mặt đường nhựa xuống lề đất. Bạn nên làm gì?","o":["Giật mạnh tay lái để quay lại đường","Nhả ga từ từ, giảm tốc, rồi nhẹ nhàng lái trở lại","Phanh mạnh ngay lập tức","Tăng tốc và lái trở lại thật nhanh"],"h1":"Hãy nghĩ đến việc giảm tốc trước khi quay lại đường.","h2":"Quay lại quá nhanh có thể làm bạn mất kiểm soát, nên hãy nhả ga từ từ, giảm tốc, rồi nhẹ nhàng lái trở lại mặt đường nhựa khi an toàn.","p":"Đúng. Giảm tốc trước, rồi nhẹ nhàng lái trở lại."},"tl":{"q":"Lumabas ang mga gulong mo sa kanan mula sa sementadong daan papunta sa lupang gilid. Ano ang dapat mong gawin?","o":["Biglang ibalik ang manibela papunta sa daan","Dahan-dahang bitawan ang gas, bumagal, saka marahang ibalik sa daan","Magpreno nang malakas agad","Bumilis at mabilis na ibalik sa daan"],"h1":"Isipin ang pagbagal bago ka bumalik sa daan.","h2":"Ang masyadong mabilis na pagbalik ay puwedeng magpawala ng kontrol mo, kaya dahan-dahang bitawan ang gas, bumagal, at saka marahang ibalik ang kotse sa sementadong daan kapag ligtas na.","p":"Tama. Bumagal muna, saka marahang bumalik sa daan."},"ar":{"q":"عجلاتك اليمنى خرجت عن الطريق المعبّد إلى الحافة الترابية. ماذا يجب أن تفعل؟","o":["أدِر المقود بقوة مفاجئة لتعود إلى الطريق","ارفع قدمك عن البنزين بهدوء، وخفّف السرعة، ثم عُد بلطف","اضغط على الفرامل بقوة فورًا","أسرع وعُد بسرعة"],"h1":"فكّر في تخفيف السرعة قبل أن تعود إلى الطريق.","h2":"العودة بسرعة كبيرة قد تجعلك تفقد السيطرة، لذلك ارفع قدمك عن البنزين بهدوء، وخفّف السرعة، ثم عُد بلطف إلى الطريق المعبّد عندما يكون ذلك آمنًا.","p":"صحيح. خفّف السرعة أولًا، ثم عُد بلطف."},"ht":{"q":"Wou dwat ou yo soti sou asfalt la epi yo tonbe sou bò tè a. Kisa ou ta dwe fè?","o":["Vire volan an sèk pou retounen sou wout la","Leve pye ou sou gaz la, ralanti, epi retounen dousman","Frennen fò touswit","Akselere epi retounen vit"],"h1":"Panse ak ralanti anvan ou retounen sou wout la.","h2":"Si ou retounen twò vit, ou ka pèdi kontwòl, kidonk leve pye ou sou gaz la, ralanti, epi dirije machin nan dousman pou l retounen sou asfalt la lè li an sekirite.","p":"Se sa. Ralanti anvan, epi retounen dousman."},"ref":{"doc":"FL","page":79}},{"id":"safe-driving-026","scope":"US","cat":"safe-driving","sign":null,"c":2,"en":{"q":"Your car stalls on railroad tracks and a train is coming. What should you do?","o":["Stay in the car and keep trying to start it","Get out and stand next to the car","Get everyone out and move away from the tracks toward the train at an angle","Get out and run straight down the tracks"],"h1":"Think about where pieces of the car could fly if the train hits it.","h2":"Get everyone out right away and move away from the tracks at an angle toward the train, so flying parts from the crash do not hit you.","p":"Right. Get out fast and move away at an angle toward the train."},"es":{"q":"Su carro se apaga sobre las vías del tren y viene un tren. ¿Qué debe hacer?","o":["Quedarse en el carro y tratar de encenderlo","Salir y quedarse al lado del carro","Sacar a todos y alejarse de las vías en diagonal hacia el tren","Salir y correr por encima de las vías"],"h1":"Piense en hacia dónde podrían volar las piezas del carro si el tren lo golpea.","h2":"Saque a todos de inmediato y aléjense de las vías en diagonal hacia donde viene el tren, para que las piezas que vuelen en el choque no los golpeen.","p":"Correcto. Salga rápido y aléjese en diagonal hacia el tren."},"zh":{"q":"你的车在铁轨上熄火了，有火车开过来。你应该怎么做？","o":["留在车里，一直试着发动","下车，站在车旁边","让所有人下车，朝火车来的方向斜着离开铁轨","下车，沿着铁轨直着跑"],"h1":"想一想火车撞到车时，车的碎片可能飞到哪里。","h2":"马上让所有人下车，朝火车来的方向斜着离开铁轨，这样撞击时飞出来的碎片才不会打到你。","p":"对。快点下车，朝火车来的方向斜着离开。"},"vi":{"q":"Xe của bạn bị chết máy trên đường ray xe lửa và có tàu đang tới. Bạn nên làm gì?","o":["Ở trong xe và tiếp tục cố nổ máy","Ra khỏi xe và đứng cạnh xe","Đưa mọi người ra ngoài và đi xa khỏi đường ray, chéo về phía tàu đang tới","Ra khỏi xe và chạy thẳng dọc theo đường ray"],"h1":"Hãy nghĩ xem các mảnh vỡ của xe có thể văng đi đâu nếu tàu đâm vào.","h2":"Đưa mọi người ra ngoài ngay và đi xa khỏi đường ray theo hướng chéo về phía tàu đang tới, để các mảnh vỡ văng ra từ vụ va chạm không trúng bạn.","p":"Đúng. Ra ngoài thật nhanh và đi xa theo hướng chéo về phía tàu."},"tl":{"q":"Namatay ang makina ng kotse mo sa riles ng tren at may paparating na tren. Ano ang dapat mong gawin?","o":["Manatili sa kotse at patuloy na subukang paandarin ito","Lumabas at tumayo sa tabi ng kotse","Palabasin ang lahat at lumayo sa riles nang pahilis, papunta sa direksyon ng tren","Lumabas at tumakbo nang diretso sa riles"],"h1":"Isipin kung saan puwedeng tumilapon ang mga piraso ng kotse kapag nabangga ito ng tren.","h2":"Palabasin agad ang lahat at lumayo sa riles nang pahilis papunta sa direksyon ng tren, para hindi kayo tamaan ng mga piraso na tumitilapon mula sa banggaan.","p":"Tama. Lumabas agad at lumayo nang pahilis papunta sa direksyon ng tren."},"ar":{"q":"سيارتك توقفت على سكة القطار والقطار قادم. ماذا يجب أن تفعل؟","o":["ابقَ في السيارة واستمر في محاولة تشغيلها","اخرج وقف بجانب السيارة","أخرِج الجميع وابتعدوا عن السكة بشكل مائل في اتجاه القطار","اخرج واركض على طول السكة مباشرة"],"h1":"فكّر: إلى أين قد تطير قطع السيارة إذا صدمها القطار؟","h2":"أخرِج الجميع فورًا وابتعدوا عن السكة بشكل مائل في اتجاه القطار، حتى لا تصيبكم القطع التي تطير من الاصطدام.","p":"صحيح. اخرج بسرعة وابتعد بشكل مائل في اتجاه القطار."},"ht":{"q":"Machin ou mouri sou ray tren an epi gen yon tren k ap vini. Kisa ou ta dwe fè?","o":["Rete nan machin nan epi kontinye eseye estat li","Desann epi kanpe bò kote machin nan","Fè tout moun desann epi kouri lwen ray yo an bivè, nan direksyon tren an","Desann epi kouri tou dwat sou ray yo"],"h1":"Panse ak ki kote moso machin nan ka vole si tren an frape l.","h2":"Fè tout moun desann touswit epi deplase lwen ray yo an bivè, nan direksyon tren k ap vini an, pou moso ki vole nan aksidan an pa frape w.","p":"Se sa. Desann vit epi ale lwen an bivè, nan direksyon tren an."},"ref":{"doc":"FL","page":79}},{"id":"safe-driving-027","scope":"US","cat":"safe-driving","sign":null,"c":0,"en":{"q":"Your car is stuck on railroad tracks, and no train is in sight. After everyone is out, who should you call?","o":["The number on the blue sign at the crossing, or 911","Your car insurance company","A tow truck, then wait in the car","Nobody, just keep trying to start the car"],"h1":"Think about who can warn the train before it arrives.","h2":"Get everyone out, then call the number on the blue emergency sign at the crossing or 911, so the railroad can stop or slow trains.","p":"Right. Call the number on the blue sign at the crossing, or 911."},"es":{"q":"Su carro está atascado en las vías del tren y no se ve ningún tren. Después de que todos salen, ¿a quién debe llamar?","o":["Al número del letrero azul del cruce, o al 911","A su compañía de seguros","A una grúa, y esperar dentro del carro","A nadie, solo seguir tratando de encenderlo"],"h1":"Piense en quién puede avisar al tren antes de que llegue.","h2":"Saque a todos y luego llame al número del letrero azul de emergencia del cruce o al 911, para que el ferrocarril pueda parar o frenar los trenes.","p":"Correcto. Llame al número del letrero azul del cruce, o al 911."},"zh":{"q":"你的车卡在铁轨上，看不到火车。所有人下车以后，你应该打电话给谁？","o":["道口蓝色牌子上的电话号码，或 911","你的汽车保险公司","拖车公司，然后在车里等","谁都不用打，只要一直试着发动车"],"h1":"想一想谁能在火车到来之前提醒火车。","h2":"让所有人下车，然后打道口蓝色紧急牌子上的电话号码或 911，这样铁路公司就能让火车停下或减速。","p":"对。打道口蓝色牌子上的电话号码，或 911。"},"vi":{"q":"Xe của bạn bị kẹt trên đường ray xe lửa, và chưa thấy tàu nào. Sau khi mọi người đã ra ngoài, bạn nên gọi cho ai?","o":["Số điện thoại trên biển màu xanh dương ở chỗ đường ray cắt ngang, hoặc 911","Công ty bảo hiểm xe của bạn","Xe kéo, rồi ngồi chờ trong xe","Không gọi ai, cứ tiếp tục cố nổ máy"],"h1":"Hãy nghĩ xem ai có thể báo cho tàu trước khi tàu tới.","h2":"Đưa mọi người ra ngoài, rồi gọi số điện thoại trên biển khẩn cấp màu xanh dương ở chỗ đường ray cắt ngang hoặc gọi 911, để công ty đường sắt có thể dừng hoặc làm chậm tàu.","p":"Đúng. Gọi số trên biển màu xanh dương ở chỗ đường ray cắt ngang, hoặc 911."},"tl":{"q":"Naipit ang kotse mo sa riles ng tren, at walang tren na tanaw. Pagkalabas ng lahat, sino ang dapat mong tawagan?","o":["Ang numero sa asul na karatula sa tawiran, o 911","Ang car insurance company mo","Isang tow truck, saka maghintay sa loob ng kotse","Wala, patuloy lang na subukang paandarin ang kotse"],"h1":"Isipin kung sino ang makakapagbabala sa tren bago ito dumating.","h2":"Palabasin ang lahat, saka tawagan ang numero sa asul na emergency sign sa tawiran o ang 911, para mapahinto o mapabagal ng riles ang mga tren.","p":"Tama. Tawagan ang numero sa asul na karatula sa tawiran, o 911."},"ar":{"q":"سيارتك عالقة على سكة القطار، ولا يوجد قطار في الأفق. بعد أن يخرج الجميع، بمن يجب أن تتصل؟","o":["بالرقم المكتوب على اللافتة الزرقاء عند التقاطع، أو 911","بشركة تأمين سيارتك","بشاحنة سحب، ثم انتظر في السيارة","لا أحد، فقط استمر في محاولة تشغيل السيارة"],"h1":"فكّر: من يستطيع أن يحذّر القطار قبل أن يصل؟","h2":"أخرِج الجميع، ثم اتصل بالرقم المكتوب على لافتة الطوارئ الزرقاء عند التقاطع أو بـ 911، حتى تستطيع شركة السكة الحديد أن توقف القطارات أو تخفّف سرعتها.","p":"صحيح. اتصل بالرقم المكتوب على اللافتة الزرقاء عند التقاطع، أو بـ 911."},"ht":{"q":"Machin ou bloke sou ray tren an, epi ou pa wè okenn tren. Apre tout moun fin desann, kiyès ou ta dwe rele?","o":["Nimewo ki sou pankat ble nan kwazman an, oswa 911","Konpayi asirans machin ou","Yon remòkè, epi tann nan machin nan","Pèsonn, jis kontinye eseye estat machin nan"],"h1":"Panse ak kiyès ki ka avèti tren an anvan li rive.","h2":"Fè tout moun desann, epi rele nimewo ki sou pankat ijans ble nan kwazman an oswa 911, pou konpayi tren an ka fè tren yo kanpe oswa ralanti.","p":"Se sa. Rele nimewo ki sou pankat ble nan kwazman an, oswa 911."},"ref":{"doc":"FL","page":80}},{"id":"safe-driving-028","scope":"US","cat":"safe-driving","sign":null,"c":3,"en":{"q":"Your car goes into a canal or lake. What should you do first?","o":["Call for help and wait inside","Wait until the car fills with water","Turn on the hazard lights","Unbuckle, open a window and get out"],"h1":"Think about how fast you need to leave the car.","h2":"You should act right away: unbuckle your seat belt, open or break a window, and get out before the water gets too high.","p":"Right. Unbuckle, open a window and get out fast."},"es":{"q":"Su carro cae a un canal o a un lago. ¿Qué debe hacer primero?","o":["Pedir ayuda y esperar adentro","Esperar a que el carro se llene de agua","Encender las luces de emergencia","Quitarse el cinturón, abrir una ventana y salir"],"h1":"Piense en qué tan rápido debe salir del carro.","h2":"Debe actuar de inmediato: quítese el cinturón, abra o rompa una ventana y salga antes de que el agua suba demasiado.","p":"Correcto. Quítese el cinturón, abra una ventana y salga rápido."},"zh":{"q":"你的车开进了运河或湖里。你首先应该做什么？","o":["打电话求救，在车里等","等到车里灌满水","打开危险警示灯","解开安全带，打开车窗，出去"],"h1":"想一想你需要多快离开车。","h2":"你应该马上行动：解开安全带，打开或打破车窗，在水变得太高之前出去。","p":"对。解开安全带，打开车窗，快点出去。"},"vi":{"q":"Xe của bạn lao xuống kênh hoặc hồ. Bạn nên làm gì trước tiên?","o":["Gọi cứu giúp và chờ trong xe","Chờ đến khi xe đầy nước","Bật đèn khẩn cấp","Tháo dây an toàn, mở cửa sổ và ra ngoài"],"h1":"Hãy nghĩ xem bạn cần rời xe nhanh đến mức nào.","h2":"Bạn nên hành động ngay: tháo dây an toàn, mở hoặc đập vỡ cửa sổ, và ra ngoài trước khi nước dâng quá cao.","p":"Đúng. Tháo dây an toàn, mở cửa sổ và ra ngoài thật nhanh."},"tl":{"q":"Nahulog ang kotse mo sa kanal o lawa. Ano ang una mong dapat gawin?","o":["Tumawag ng tulong at maghintay sa loob","Maghintay hanggang mapuno ng tubig ang kotse","I-on ang hazard lights","Tanggalin ang seat belt, buksan ang bintana, at lumabas"],"h1":"Isipin kung gaano ka kabilis dapat umalis sa kotse.","h2":"Dapat kang kumilos agad: tanggalin ang seat belt mo, buksan o basagin ang bintana, at lumabas bago tumaas nang husto ang tubig.","p":"Tama. Tanggalin ang seat belt, buksan ang bintana, at lumabas agad."},"ar":{"q":"سيارتك وقعت في قناة ماء أو بحيرة. ماذا يجب أن تفعل أولًا؟","o":["اطلب المساعدة وانتظر في الداخل","انتظر حتى تمتلئ السيارة بالماء","شغّل أضواء التحذير","فُك الحزام، وافتح النافذة، واخرج"],"h1":"فكّر في السرعة التي تحتاجها لتترك السيارة.","h2":"يجب أن تتصرف فورًا: فُك حزام الأمان، وافتح النافذة أو اكسرها، واخرج قبل أن يرتفع الماء كثيرًا.","p":"صحيح. فُك الحزام، وافتح النافذة، واخرج بسرعة."},"ht":{"q":"Machin ou tonbe nan yon kanal oswa nan yon lak. Kisa ou ta dwe fè anvan?","o":["Rele pou èd epi tann andedan","Tann jiskaske machin nan plen dlo","Limen limyè ijans yo","Retire senti ou, louvri yon fenèt epi soti"],"h1":"Panse ak konbyen vit ou bezwen kite machin nan.","h2":"Ou ta dwe aji touswit: retire senti sekirite ou, louvri oswa kase yon fenèt, epi soti anvan dlo a monte twò wo.","p":"Se sa. Retire senti ou, louvri yon fenèt epi soti vit."},"ref":{"doc":"FL","page":80}},{"id":"safe-driving-029","scope":"US","cat":"safe-driving","sign":null,"c":1,"en":{"q":"After a hurricane, water covers the road ahead and you cannot see how deep it is. What should you do?","o":["Drive through it slowly","Turn around and find another way","Drive through it fast","Follow the car in front of you"],"h1":"Think about how little moving water it takes to move a car.","h2":"Even shallow moving water can sweep a car away, and you cannot see what is under it, so turn around and find another way.","p":"Right. Turn around and do not drive into flooded roads."},"es":{"q":"Después de un huracán, el agua cubre la calle adelante y no puede ver qué tan profunda es. ¿Qué debe hacer?","o":["Pasar despacio por el agua","Dar la vuelta y buscar otro camino","Pasar rápido por el agua","Seguir al carro de adelante"],"h1":"Piense en qué poca agua en movimiento basta para mover un carro.","h2":"Aun el agua poco profunda en movimiento puede arrastrar un carro, y usted no ve lo que hay debajo, así que dé la vuelta y busque otro camino.","p":"Correcto. Dé la vuelta y no maneje por calles inundadas."},"zh":{"q":"飓风过后，前面的路被水淹了，你看不出水有多深。你应该怎么做？","o":["慢慢开过去","掉头，找别的路","快速开过去","跟着前面的车开"],"h1":"想一想只要很少的流动的水就能冲走一辆车。","h2":"即使是很浅的流动的水也可能把车冲走，而且你看不到水下有什么，所以要掉头找别的路。","p":"对。掉头，不要开进被水淹的路。"},"vi":{"q":"Sau một cơn bão, nước ngập đường phía trước và bạn không thấy nước sâu bao nhiêu. Bạn nên làm gì?","o":["Lái chậm qua","Quay đầu và tìm đường khác","Lái nhanh qua","Đi theo xe phía trước"],"h1":"Hãy nghĩ xem chỉ cần một ít nước chảy là có thể cuốn trôi xe.","h2":"Ngay cả nước chảy nông cũng có thể cuốn trôi xe, và bạn không thấy được bên dưới có gì, nên hãy quay đầu và tìm đường khác.","p":"Đúng. Quay đầu và đừng lái vào đường bị ngập."},"tl":{"q":"Pagkatapos ng bagyo, may tubig na tumatakip sa daan sa unahan at hindi mo makita kung gaano ito kalalim. Ano ang dapat mong gawin?","o":["Dumaan dito nang dahan-dahan","Bumalik at maghanap ng ibang daan","Dumaan dito nang mabilis","Sundan ang kotse sa harap mo"],"h1":"Isipin kung gaano kaunting umaagos na tubig ang kailangan para matangay ang kotse.","h2":"Kahit mababaw na umaagos na tubig ay puwedeng tumangay ng kotse, at hindi mo nakikita kung ano ang nasa ilalim nito, kaya bumalik at maghanap ng ibang daan.","p":"Tama. Bumalik at huwag dumaan sa bahang daan."},"ar":{"q":"بعد إعصار، الماء يغطي الطريق أمامك ولا تستطيع أن ترى عمقه. ماذا يجب أن تفعل؟","o":["اعبره ببطء","ارجع وابحث عن طريق آخر","اعبره بسرعة","اتبع السيارة التي أمامك"],"h1":"فكّر: كم قليلًا من الماء الجاري يكفي لتحريك سيارة؟","h2":"حتى الماء الجاري غير العميق يمكن أن يجرف السيارة، ولا تستطيع أن ترى ما تحته، لذلك ارجع وابحث عن طريق آخر.","p":"صحيح. ارجع ولا تدخل الطرق المغمورة بالماء."},"ht":{"q":"Apre yon siklòn, dlo kouvri wout la devan w epi ou pa ka wè ki fon li ye. Kisa ou ta dwe fè?","o":["Travèse l dousman","Vire tounen epi chèche yon lòt chemen","Travèse l vit","Swiv machin ki devan w lan"],"h1":"Panse ak jan yon ti kras dlo k ap koule ase pou deplase yon machin.","h2":"Menm yon dlo ki pa fon, si l ap koule, ka pote yon machin ale, epi ou pa ka wè sa ki anba l, kidonk vire tounen epi chèche yon lòt chemen.","p":"Se sa. Vire tounen epi pa kondi antre nan wout ki inonde."},"ref":{"doc":"FL","page":72}},{"id":"safe-driving-030","scope":"FL","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Florida, after a storm, you reach an intersection where the traffic light is dark because the power is out. What should you do?","o":["Drive through without stopping","Stop only if a car is coming","Treat it like a four-way stop","Wait until the light works again"],"h1":"Think about how drivers take turns when there is no signal.","h2":"In Florida, a traffic light that is out works like a four-way stop, so you stop fully and take turns with the other drivers.","p":"Right. A dark traffic light works like a four-way stop."},"es":{"q":"En Florida, después de una tormenta, llega a un cruce donde el semáforo está apagado porque no hay luz. ¿Qué debe hacer?","o":["Pasar sin parar","Parar solo si viene un carro","Tratarlo como un pare de cuatro vías","Esperar hasta que el semáforo funcione"],"h1":"Piense en cómo se turnan los conductores cuando no hay semáforo.","h2":"En Florida, un semáforo apagado funciona como un pare de cuatro vías, así que debe parar por completo y turnarse con los otros conductores.","p":"Correcto. Un semáforo apagado funciona como un pare de cuatro vías."},"zh":{"q":"在 Florida，暴风雨过后，你到了一个路口，因为停电，红绿灯不亮了。你应该怎么做？","o":["不停车，直接开过去","只有在有车过来时才停车","把它当作四向停车路口","等到红绿灯恢复正常"],"h1":"想一想没有信号灯时，司机们怎样轮流通过。","h2":"在 Florida，不亮的红绿灯就像四向停车路口一样，所以你要完全停下，和其他司机轮流通过。","p":"对。不亮的红绿灯就像四向停车路口。"},"vi":{"q":"Ở Florida, sau một cơn bão, bạn đến một ngã tư mà đèn giao thông bị tắt vì mất điện. Bạn nên làm gì?","o":["Chạy qua mà không dừng","Chỉ dừng nếu có xe đang tới","Xem như ngã tư có biển STOP ở cả bốn hướng","Chờ đến khi đèn hoạt động lại"],"h1":"Hãy nghĩ xem các tài xế thay phiên nhau đi như thế nào khi không có đèn tín hiệu.","h2":"Ở Florida, đèn giao thông bị tắt được xem như ngã tư có biển STOP ở cả bốn hướng, nên bạn dừng hẳn lại và thay phiên đi với các tài xế khác.","p":"Đúng. Đèn giao thông bị tắt được xem như ngã tư có biển STOP ở cả bốn hướng."},"tl":{"q":"Sa Florida, pagkatapos ng bagyo, nakarating ka sa intersection kung saan patay ang traffic light dahil walang kuryente. Ano ang dapat mong gawin?","o":["Dumaan nang hindi humihinto","Huminto lang kung may paparating na kotse","Ituring itong four-way stop","Maghintay hanggang gumana ulit ang ilaw"],"h1":"Isipin kung paano nagsasalitan ang mga driver kapag walang signal.","h2":"Sa Florida, ang patay na traffic light ay gumagana na parang four-way stop, kaya huminto ka nang buo at makipagsalitan sa ibang mga driver.","p":"Tama. Ang patay na traffic light ay gumagana na parang four-way stop."},"ar":{"q":"في Florida، بعد عاصفة، وصلت إلى تقاطع إشارة المرور فيه مطفأة لأن الكهرباء مقطوعة. ماذا يجب أن تفعل؟","o":["مُرّ بدون أن تتوقف","توقف فقط إذا كانت هناك سيارة قادمة","تعامل معه مثل تقاطع فيه توقف من أربع جهات","انتظر حتى تعمل الإشارة مرة أخرى"],"h1":"فكّر في كيف يتناوب السائقون عندما لا توجد إشارة.","h2":"في Florida، إشارة المرور المطفأة تعمل مثل تقاطع فيه توقف من أربع جهات، لذلك تتوقف توقفًا كاملًا وتتناوب مع السائقين الآخرين.","p":"صحيح. إشارة المرور المطفأة تعمل مثل توقف من أربع جهات."},"ht":{"q":"Nan Florida, apre yon tanpèt, ou rive nan yon kafou kote limyè trafik la etenn paske kouran an koupe. Kisa ou ta dwe fè?","o":["Pase san ou pa kanpe","Kanpe sèlman si gen yon machin k ap vini","Fè tankou se yon kafou ki gen STOP nan kat bò","Tann jiskaske limyè a mache ankò"],"h1":"Panse ak jan chofè yo pran tou yo lè pa gen siyal.","h2":"Nan Florida, yon limyè trafik ki pa mache travay tankou yon STOP nan kat bò, kidonk ou kanpe nèt epi ou pran tou pa w ak lòt chofè yo.","p":"Se sa. Yon limyè trafik ki etenn travay tankou yon STOP nan kat bò."},"ref":{"doc":"FL","page":79}},{"id":"safe-driving-031","scope":"US","cat":"safe-driving","sign":null,"c":0,"en":{"q":"At night, a car coming toward you has very bright headlights. Where should you look?","o":["Toward the right edge of your lane","Straight into the other car's lights","At the center line","Down at your dashboard"],"h1":"Think about a guide that keeps you in your lane without looking at the glare.","h2":"Looking toward the right edge of your lane keeps you on the road while you avoid looking straight into the glare.","p":"Right. Look toward the right edge of your lane to avoid glare."},"es":{"q":"De noche, un carro que viene hacia usted tiene las luces muy fuertes. ¿Hacia dónde debe mirar?","o":["Hacia la orilla derecha de su carril","Directo a las luces del otro carro","A la línea del centro","Hacia abajo, al tablero"],"h1":"Piense en una guía que lo mantenga en su carril sin mirar el resplandor.","h2":"Mirar hacia la orilla derecha de su carril lo mantiene en la vía mientras evita mirar directo al resplandor.","p":"Correcto. Mire hacia la orilla derecha de su carril para evitar el resplandor."},"zh":{"q":"晚上，对面开来的车车灯很亮。你应该看哪里？","o":["看向你车道的右边边缘","直直看着对面车的灯","看中线","往下看仪表板"],"h1":"想一想有什么能让你留在车道上，又不用看刺眼的光。","h2":"看向你车道的右边边缘，可以让你留在路上，同时避免直接看刺眼的光。","p":"对。看向你车道的右边边缘，避开刺眼的光。"},"vi":{"q":"Ban đêm, một xe đi ngược chiều có đèn pha rất sáng. Bạn nên nhìn về đâu?","o":["Về phía mép phải làn đường của bạn","Nhìn thẳng vào đèn của xe kia","Vào vạch giữa đường","Nhìn xuống bảng đồng hồ"],"h1":"Hãy nghĩ đến một điểm giúp bạn giữ đúng làn mà không phải nhìn vào ánh chói.","h2":"Nhìn về phía mép phải làn đường giúp bạn giữ xe trên đường mà không phải nhìn thẳng vào ánh chói.","p":"Đúng. Nhìn về phía mép phải làn đường để tránh ánh chói."},"tl":{"q":"Sa gabi, napakaliwanag ng headlights ng kotseng paparating sa iyo. Saan ka dapat tumingin?","o":["Sa kanang gilid ng lane mo","Diretso sa ilaw ng kabilang kotse","Sa center line (gitnang guhit)","Pababa sa dashboard mo"],"h1":"Isipin ang gabay na nagpapanatili sa iyo sa lane mo nang hindi tumitingin sa nakasisilaw na ilaw.","h2":"Ang pagtingin sa kanang gilid ng lane mo ay nagpapanatili sa iyo sa daan habang iniiwasan mong tumingin nang diretso sa nakasisilaw na ilaw.","p":"Tama. Tumingin sa kanang gilid ng lane mo para iwasan ang silaw."},"ar":{"q":"في الليل، سيارة قادمة نحوك أضواؤها قوية جدًا. إلى أين يجب أن تنظر؟","o":["نحو الحافة اليمنى لمسارك","مباشرة إلى أضواء السيارة الأخرى","إلى الخط الأوسط","إلى الأسفل نحو لوحة العدادات"],"h1":"فكّر في دليل يُبقيك في مسارك بدون أن تنظر إلى الضوء الساطع.","h2":"النظر نحو الحافة اليمنى لمسارك يُبقيك على الطريق، وفي نفس الوقت تتجنب النظر مباشرة إلى الضوء الساطع.","p":"صحيح. انظر نحو الحافة اليمنى لمسارك لتتجنب الضوء الساطع."},"ht":{"q":"Lannwit, yon machin k ap vini sou ou gen limyè devan ki klere anpil. Ki kote ou ta dwe gade?","o":["Bò dwat liy ou a","Dirèkteman nan limyè lòt machin nan","Liy ki nan mitan wout la","Anba, sou tablodbò ou"],"h1":"Panse ak yon gid ki kenbe w nan liy ou san ou pa gade nan limyè a ki ap avegle w.","h2":"Lè ou gade bò dwat liy ou a, ou rete sou wout la pandan ou evite gade dirèkteman nan limyè ki ap avegle w la.","p":"Se sa. Gade bò dwat liy ou a pou evite limyè a avegle w."},"ref":{"doc":"FL","page":73}},{"id":"safe-driving-032","scope":"FL","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Florida, you are using high beams at night. When must you switch to low beams for a car coming toward you?","o":["Within 100 feet of it","Within 200 feet of it","Only when it flashes its lights","Within 500 feet of it"],"h1":"Think about a long distance, because bright lights reach far.","h2":"In Florida you must dim your high beams when an oncoming car is within 500 feet, so its driver is not blinded.","p":"Right. Dim your high beams within 500 feet of an oncoming car."},"es":{"q":"En Florida, usted usa las luces altas de noche. ¿Cuándo debe cambiar a luces bajas por un carro que viene de frente?","o":["A 100 pies de él","A 200 pies de él","Solo cuando le haga cambio de luces","A 500 pies de él"],"h1":"Piense en una distancia larga, porque las luces altas llegan lejos.","h2":"En Florida debe bajar las luces altas cuando un carro que viene de frente está a 500 pies o menos, para no encandilar al conductor.","p":"Correcto. Baje las luces altas a 500 pies de un carro que viene de frente."},"zh":{"q":"在 Florida，你晚上开着远光灯。对面来车时，你必须在多远的距离内换成近光灯？","o":["在 100 英尺内","在 200 英尺内","只在它闪灯时","在 500 英尺内"],"h1":"想一想一个很长的距离，因为亮的灯照得很远。","h2":"在 Florida，对面来车在 500 英尺以内时，你必须把远光灯调暗，这样对面的司机才不会被照得看不见。","p":"对。对面来车在 500 英尺内时，把远光灯调暗。"},"vi":{"q":"Ở Florida, bạn đang bật đèn pha (đèn chiếu xa) vào ban đêm. Khi nào bạn phải chuyển sang đèn cốt (đèn chiếu gần) vì có xe đi ngược chiều?","o":["Khi cách xe đó trong vòng 100 feet","Khi cách xe đó trong vòng 200 feet","Chỉ khi xe đó nháy đèn","Khi cách xe đó trong vòng 500 feet"],"h1":"Hãy nghĩ đến một khoảng cách xa, vì đèn sáng chiếu được rất xa.","h2":"Ở Florida, bạn phải hạ đèn pha khi xe đi ngược chiều cách bạn trong vòng 500 feet, để tài xế kia không bị chói mắt.","p":"Đúng. Hạ đèn pha khi cách xe đi ngược chiều trong vòng 500 feet."},"tl":{"q":"Sa Florida, gumagamit ka ng high beams sa gabi. Kailan ka dapat lumipat sa low beams para sa kotseng paparating sa iyo?","o":["Sa loob ng 100 feet mula rito","Sa loob ng 200 feet mula rito","Kapag nag-flash lang ito ng ilaw","Sa loob ng 500 feet mula rito"],"h1":"Isipin ang mahabang distansya, dahil malayo ang naaabot ng maliwanag na ilaw.","h2":"Sa Florida, dapat mong ibaba ang high beams mo kapag ang paparating na kotse ay nasa loob ng 500 feet, para hindi masilaw ang driver nito.","p":"Tama. Ibaba ang high beams mo sa loob ng 500 feet mula sa paparating na kotse."},"ar":{"q":"في Florida، تستعمل الأضواء العالية في الليل. متى يجب أن تنتقل إلى الأضواء المنخفضة بسبب سيارة قادمة نحوك؟","o":["عندما تكون على بعد 100 قدم (feet) منها","عندما تكون على بعد 200 قدم (feet) منها","فقط عندما تومض بأضوائها","عندما تكون على بعد 500 قدم (feet) منها"],"h1":"فكّر في مسافة طويلة، لأن الأضواء القوية تصل بعيدًا.","h2":"في Florida يجب أن تخفّض أضواءك العالية عندما تكون السيارة القادمة على بعد 500 قدم (feet)، حتى لا يُبهَر سائقها.","p":"صحيح. خفّض أضواءك العالية على بعد 500 قدم (feet) من السيارة القادمة."},"ht":{"q":"Nan Florida, w ap sèvi ak gwo limyè (high beams) lannwit. Ki lè ou dwe mete ti limyè (low beams) pou yon machin k ap vini sou ou?","o":["Lè li nan 100 pye","Lè li nan 200 pye","Sèlman lè li limen limyè li plizyè fwa","Lè li nan 500 pye"],"h1":"Panse ak yon long distans, paske limyè ki klere fò rive lwen.","h2":"Nan Florida, ou dwe bese gwo limyè ou yo lè yon machin k ap vini sou ou nan 500 pye, pou chofè li a pa avegle.","p":"Se sa. Bese gwo limyè ou yo lè yon machin k ap vini sou ou nan 500 pye."},"ref":{"doc":"FL","page":73}},{"id":"safe-driving-033","scope":"FL","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Florida, you are following another car at night. When must you use low beams?","o":["Within 100 feet of it","Within 300 feet of it","Within 1,000 feet of it","Only in the city"],"h1":"Think about your lights shining into the other driver's mirrors.","h2":"In Florida you must use low beams when you are within 300 feet behind another car, so your lights do not blind its driver in the mirrors.","p":"Right. Use low beams within 300 feet of the car ahead."},"es":{"q":"En Florida, usted va detrás de otro carro de noche. ¿Cuándo debe usar luces bajas?","o":["A 100 pies de él","A 300 pies de él","A 1,000 pies de él","Solo en la ciudad"],"h1":"Piense en sus luces brillando en los espejos del otro conductor.","h2":"En Florida debe usar luces bajas cuando está a 300 pies o menos detrás de otro carro, para que sus luces no encandilen al conductor en los espejos.","p":"Correcto. Use luces bajas a 300 pies del carro de adelante."},"zh":{"q":"在 Florida，你晚上跟在另一辆车后面。你必须在多远的距离内用近光灯？","o":["在 100 英尺内","在 300 英尺内","在 1,000 英尺内","只在城市里"],"h1":"想一想你的车灯照进前面司机的后视镜。","h2":"在 Florida，当你在另一辆车后面 300 英尺以内时，必须用近光灯，这样你的灯光才不会通过后视镜晃到那位司机的眼睛。","p":"对。离前车 300 英尺以内时用近光灯。"},"vi":{"q":"Ở Florida, bạn đang chạy sau một xe khác vào ban đêm. Khi nào bạn phải dùng đèn cốt (đèn chiếu gần)?","o":["Khi cách xe đó trong vòng 100 feet","Khi cách xe đó trong vòng 300 feet","Khi cách xe đó trong vòng 1,000 feet","Chỉ trong thành phố"],"h1":"Hãy nghĩ đến đèn của bạn chiếu vào gương của tài xế kia.","h2":"Ở Florida, bạn phải dùng đèn cốt khi chạy sau một xe khác trong vòng 300 feet, để đèn của bạn không làm tài xế đó chói mắt qua gương.","p":"Đúng. Dùng đèn cốt khi cách xe phía trước trong vòng 300 feet."},"tl":{"q":"Sa Florida, sumusunod ka sa ibang kotse sa gabi. Kailan ka dapat gumamit ng low beams?","o":["Sa loob ng 100 feet mula rito","Sa loob ng 300 feet mula rito","Sa loob ng 1,000 feet mula rito","Sa lungsod lang"],"h1":"Isipin ang ilaw mo na tumatama sa mga salamin ng kabilang driver.","h2":"Sa Florida, dapat kang gumamit ng low beams kapag nasa loob ka ng 300 feet sa likod ng ibang kotse, para hindi masilaw ang driver nito sa mga salamin.","p":"Tama. Gumamit ng low beams sa loob ng 300 feet mula sa kotse sa unahan."},"ar":{"q":"في Florida، أنت تسير خلف سيارة أخرى في الليل. متى يجب أن تستعمل الأضواء المنخفضة؟","o":["عندما تكون على بعد 100 قدم (feet) منها","عندما تكون على بعد 300 قدم (feet) منها","عندما تكون على بعد 1,000 قدم (feet) منها","في المدينة فقط"],"h1":"فكّر في أضوائك وهي تلمع في مرايا السائق الآخر.","h2":"في Florida يجب أن تستعمل الأضواء المنخفضة عندما تكون على بعد 300 قدم (feet) خلف سيارة أخرى، حتى لا تُبهر أضواؤك سائقها في المرايا.","p":"صحيح. استعمل الأضواء المنخفضة على بعد 300 قدم (feet) من السيارة التي أمامك."},"ht":{"q":"Nan Florida, w ap swiv yon lòt machin lannwit. Ki lè ou dwe sèvi ak ti limyè (low beams)?","o":["Lè ou nan 100 pye dèyè l","Lè ou nan 300 pye dèyè l","Lè ou nan 1,000 pye dèyè l","Sèlman nan vil la"],"h1":"Panse ak limyè ou k ap klere nan retwovizè lòt chofè a.","h2":"Nan Florida, ou dwe sèvi ak ti limyè lè ou nan 300 pye dèyè yon lòt machin, pou limyè ou yo pa avegle chofè a nan retwovizè li yo.","p":"Se sa. Sèvi ak ti limyè lè ou nan 300 pye dèyè machin ki devan w lan."},"ref":{"doc":"FL","page":73}},{"id":"safe-driving-034","scope":"US","cat":"safe-driving","sign":null,"c":2,"en":{"q":"What does it mean to \"overdrive your headlights\" at night?","o":["Using high beams in the city","Driving with only parking lights on","Driving too fast to stop within the area your lights show","Leaving your lights on after you park"],"h1":"Think about how far ahead you can see at night.","h2":"If you drive so fast that you cannot stop within the distance your headlights light up, you are overdriving them, so slow down at night.","p":"Right. Drive slow enough to stop within what your headlights show."},"es":{"q":"¿Qué significa manejar más rápido de lo que alcanzan sus luces de noche?","o":["Usar luces altas en la ciudad","Manejar solo con luces de estacionamiento","Ir tan rápido que no puede parar dentro de lo que alumbran sus luces","Dejar las luces encendidas al estacionar"],"h1":"Piense en qué tan lejos puede ver de noche.","h2":"Si maneja tan rápido que no puede parar dentro de la distancia que alumbran sus faros, va más rápido de lo que alcanzan sus luces, así que baje la velocidad de noche.","p":"Correcto. Maneje a una velocidad que le permita parar dentro de lo que alumbran sus luces."},"zh":{"q":"晚上“开得比车灯照得更远”是什么意思？","o":["在城市里用远光灯","只开着停车灯开车","开得太快，无法在车灯照亮的范围内停下","停车后没有关车灯"],"h1":"想一想晚上你能看到前面多远。","h2":"如果你开得太快，在车头灯照亮的距离内停不下来，你就是开得比车灯照得更远，所以晚上要减速。","p":"对。开慢一点，要能在车头灯照到的范围内停下。"},"vi":{"q":"Ban đêm, \"chạy vượt tầm đèn pha\" (overdrive your headlights) có nghĩa là gì?","o":["Bật đèn pha trong thành phố","Lái xe chỉ bật đèn đậu xe","Lái quá nhanh nên không thể dừng trong vùng đèn chiếu tới","Để đèn sáng sau khi đậu xe"],"h1":"Hãy nghĩ xem ban đêm bạn nhìn thấy được xa đến đâu.","h2":"Nếu bạn lái nhanh đến mức không thể dừng trong khoảng đèn pha chiếu sáng, bạn đang chạy vượt tầm đèn pha, nên hãy chạy chậm lại vào ban đêm.","p":"Đúng. Lái đủ chậm để dừng được trong vùng đèn pha chiếu tới."},"tl":{"q":"Ano ang ibig sabihin ng \"overdrive your headlights\" sa gabi?","o":["Paggamit ng high beams sa lungsod","Pagmamaneho na parking lights lang ang nakabukas","Pagmamaneho nang masyadong mabilis para huminto sa loob ng lugar na naiilawan ng ilaw mo","Pag-iwan na nakabukas ang ilaw pagka-park mo"],"h1":"Isipin kung gaano kalayo sa unahan ang nakikita mo sa gabi.","h2":"Kung masyado kang mabilis kaya hindi ka makahinto sa loob ng distansyang naiilawan ng headlights mo, ikaw ay nag-o-overdrive ng headlights, kaya bumagal sa gabi.","p":"Tama. Magmaneho nang sapat na bagal para makahinto sa loob ng naiilawan ng headlights mo."},"ar":{"q":"ماذا يعني أن \"تسبق أضواءك\" في الليل؟","o":["أن تستعمل الأضواء العالية في المدينة","أن تقود وأضواء الوقوف فقط مشغّلة","أن تقود بسرعة كبيرة لا تسمح لك بالتوقف داخل المسافة التي تضيئها أضواؤك","أن تترك أضواءك مشغّلة بعد أن توقف السيارة"],"h1":"فكّر: إلى أي مسافة أمامك تستطيع أن ترى في الليل؟","h2":"إذا قُدت بسرعة كبيرة لا تسمح لك بالتوقف داخل المسافة التي تضيئها أضواؤك الأمامية، فأنت تسبق أضواءك، لذلك خفّف السرعة في الليل.","p":"صحيح. قُد ببطء كافٍ لتتوقف داخل ما تُظهره أضواؤك الأمامية."},"ht":{"q":"Kisa sa vle di lè yo di w ap \"kondi pi vit pase limyè ou\" (overdrive your headlights) lannwit?","o":["Sèvi ak gwo limyè nan vil la","Kondi ak limyè pakin sèlman","Kondi twò vit pou w ka kanpe nan espas limyè ou montre w la","Kite limyè ou limen apre ou pake"],"h1":"Panse ak konbyen lwen devan ou ka wè lannwit.","h2":"Si w ap kondi tèlman vit ke ou pa ka kanpe nan distans limyè devan ou yo klere a, w ap kondi pi vit pase limyè ou, kidonk ralanti lannwit.","p":"Se sa. Kondi dousman ase pou w ka kanpe nan espas limyè devan ou yo montre w."},"ref":{"doc":"FL","page":73}},{"id":"safe-driving-035","scope":"US","cat":"safe-driving","sign":null,"c":0,"en":{"q":"You are driving in thick fog. Which lights should you use?","o":["Low beams","High beams","Parking lights only","No lights"],"h1":"Think about how bright light bounces back off fog.","h2":"High beams reflect off the fog and make it harder to see, so you should use low beams and slow down.","p":"Right. Use low beams in fog."},"es":{"q":"Usted maneja con neblina espesa. ¿Qué luces debe usar?","o":["Luces bajas","Luces altas","Solo luces de estacionamiento","Ninguna luz"],"h1":"Piense en cómo la luz fuerte rebota en la neblina.","h2":"Las luces altas rebotan en la neblina y hacen más difícil ver, así que debe usar luces bajas y bajar la velocidad.","p":"Correcto. Use luces bajas con neblina."},"zh":{"q":"你在浓雾里开车。你应该用哪种灯？","o":["近光灯","远光灯","只开停车灯","不开灯"],"h1":"想一想亮光碰到雾会怎样反射回来。","h2":"远光灯会被雾反射回来，让你更难看清，所以你应该用近光灯并减速。","p":"对。雾天用近光灯。"},"vi":{"q":"Bạn đang lái xe trong sương mù dày. Bạn nên dùng đèn nào?","o":["Đèn cốt (đèn chiếu gần)","Đèn pha (đèn chiếu xa)","Chỉ đèn đậu xe","Không bật đèn"],"h1":"Hãy nghĩ xem ánh sáng mạnh bị sương mù phản chiếu lại như thế nào.","h2":"Đèn pha phản chiếu lại từ sương mù và làm bạn khó nhìn hơn, nên bạn nên dùng đèn cốt và chạy chậm lại.","p":"Đúng. Dùng đèn cốt khi có sương mù."},"tl":{"q":"Nagmamaneho ka sa makapal na fog (hamog). Anong ilaw ang dapat mong gamitin?","o":["Low beams","High beams","Parking lights lang","Walang ilaw"],"h1":"Isipin kung paano tumatalbog pabalik ang maliwanag na ilaw mula sa fog.","h2":"Tumatalbog ang high beams sa fog at nagpapahirap makakita, kaya dapat kang gumamit ng low beams at bumagal.","p":"Tama. Gumamit ng low beams sa fog."},"ar":{"q":"أنت تقود في ضباب كثيف. أي أضواء يجب أن تستعمل؟","o":["الأضواء المنخفضة","الأضواء العالية","أضواء الوقوف فقط","بدون أضواء"],"h1":"فكّر في كيف يرتد الضوء القوي عن الضباب.","h2":"الأضواء العالية ترتد عن الضباب وتجعل الرؤية أصعب، لذلك يجب أن تستعمل الأضواء المنخفضة وتخفّف السرعة.","p":"صحيح. استعمل الأضواء المنخفضة في الضباب."},"ht":{"q":"W ap kondi nan yon bwouya ki epè. Ki limyè ou ta dwe sèvi?","o":["Ti limyè (low beams)","Gwo limyè (high beams)","Limyè pakin sèlman","Okenn limyè"],"h1":"Panse ak jan limyè ki klere fò tounen sou bwouya a.","h2":"Gwo limyè yo frape bwouya a epi tounen sou ou, sa ki fè li pi difisil pou w wè, kidonk ou ta dwe sèvi ak ti limyè epi ralanti.","p":"Se sa. Sèvi ak ti limyè nan bwouya."},"ref":{"doc":"FL","page":71}},{"id":"safe-driving-036","scope":"FL","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Florida, it is raining and your wipers are on. What must you also turn on?","o":["Your hazard lights","Your high beams","Your inside dome light","Your headlights"],"h1":"Think about helping other drivers see your car in the rain.","h2":"In Florida you must turn on your headlights when you drive in rain, smoke or fog, so other drivers can see you.","p":"Right. In the rain, turn on your headlights."},"es":{"q":"En Florida, está lloviendo y tiene los limpiaparabrisas encendidos. ¿Qué más debe encender?","o":["Las luces de emergencia","Las luces altas","La luz interior del techo","Los faros delanteros"],"h1":"Piense en ayudar a otros conductores a ver su carro en la lluvia.","h2":"En Florida debe encender los faros delanteros cuando maneja con lluvia, humo o neblina, para que otros conductores lo vean.","p":"Correcto. Con lluvia, encienda los faros delanteros."},"zh":{"q":"在 Florida，正在下雨，你的雨刷开着。你还必须打开什么？","o":["你的危险警示灯","你的远光灯","车内顶灯","你的车头灯"],"h1":"想一想怎样帮助其他司机在雨中看到你的车。","h2":"在 Florida，你在雨中、烟中或雾中开车时，必须打开车头灯，这样其他司机才能看到你。","p":"对。下雨时，打开车头灯。"},"vi":{"q":"Ở Florida, trời đang mưa và cần gạt nước của bạn đang bật. Bạn còn phải bật gì nữa?","o":["Đèn khẩn cấp","Đèn pha (đèn chiếu xa)","Đèn trần trong xe","Đèn trước của xe"],"h1":"Hãy nghĩ đến việc giúp các tài xế khác nhìn thấy xe bạn trong mưa.","h2":"Ở Florida, bạn phải bật đèn trước khi lái xe trong mưa, khói hoặc sương mù, để các tài xế khác nhìn thấy bạn.","p":"Đúng. Khi trời mưa, hãy bật đèn trước."},"tl":{"q":"Sa Florida, umuulan at nakabukas ang wipers mo. Ano pa ang dapat mong i-on?","o":["Ang hazard lights mo","Ang high beams mo","Ang ilaw sa loob ng kotse","Ang headlights mo"],"h1":"Isipin ang pagtulong sa ibang driver na makita ang kotse mo sa ulan.","h2":"Sa Florida, dapat mong i-on ang headlights mo kapag nagmamaneho ka sa ulan, usok, o fog, para makita ka ng ibang mga driver.","p":"Tama. Sa ulan, i-on ang headlights mo."},"ar":{"q":"في Florida، المطر ينزل والمساحات تعمل. ماذا يجب أن تشغّل أيضًا؟","o":["أضواء التحذير","الأضواء العالية","الضوء الداخلي في السقف","الأضواء الأمامية"],"h1":"فكّر في مساعدة السائقين الآخرين على رؤية سيارتك في المطر.","h2":"في Florida يجب أن تشغّل الأضواء الأمامية عندما تقود في المطر أو الدخان أو الضباب، حتى يراك السائقون الآخرون.","p":"صحيح. في المطر، شغّل الأضواء الأمامية."},"ht":{"q":"Nan Florida, lapli ap tonbe epi wipè ou yo limen. Kisa ou dwe limen tou?","o":["Limyè ijans ou yo","Gwo limyè ou yo","Limyè andedan machin nan","Limyè devan ou yo"],"h1":"Panse ak ede lòt chofè yo wè machin ou nan lapli a.","h2":"Nan Florida, ou dwe limen limyè devan ou yo lè w ap kondi nan lapli, lafimen oswa bwouya, pou lòt chofè yo ka wè w.","p":"Se sa. Nan lapli, limen limyè devan ou yo."},"ref":{"doc":"FL","page":72}},{"id":"safe-driving-037","scope":"US","cat":"safe-driving","sign":null,"c":1,"en":{"q":"When is a road often most slippery during a rain?","o":["After it has rained for hours","In the first few minutes of rain","Only at night","Only when the sun comes out"],"h1":"Think about oil on the road mixing with the first water.","h2":"At the start of a rain, water mixes with oil on the road and makes it very slippery, so slow down as soon as it starts to rain.","p":"Right. Roads are often most slippery in the first minutes of rain."},"es":{"q":"¿Cuándo está la vía a menudo más resbalosa durante la lluvia?","o":["Después de horas de lluvia","En los primeros minutos de lluvia","Solo de noche","Solo cuando sale el sol"],"h1":"Piense en el aceite de la vía mezclándose con la primera agua.","h2":"Al comenzar la lluvia, el agua se mezcla con el aceite de la vía y la pone muy resbalosa, así que baje la velocidad en cuanto empiece a llover.","p":"Correcto. La vía suele estar más resbalosa en los primeros minutos de lluvia."},"zh":{"q":"下雨时，路面通常什么时候最滑？","o":["下了几个小时雨以后","下雨的头几分钟","只在晚上","只在太阳出来时"],"h1":"想一想路上的油和最先落下的雨水混在一起。","h2":"刚开始下雨时，雨水和路上的油混在一起，让路面非常滑，所以一开始下雨就要减速。","p":"对。路面通常在下雨的头几分钟最滑。"},"vi":{"q":"Khi trời mưa, mặt đường thường trơn nhất vào lúc nào?","o":["Sau khi mưa đã nhiều giờ","Trong vài phút đầu của cơn mưa","Chỉ vào ban đêm","Chỉ khi mặt trời ló ra"],"h1":"Hãy nghĩ đến dầu trên mặt đường trộn với lượng nước đầu tiên.","h2":"Lúc bắt đầu mưa, nước trộn với dầu trên mặt đường và làm đường rất trơn, nên hãy chạy chậm lại ngay khi trời bắt đầu mưa.","p":"Đúng. Mặt đường thường trơn nhất trong những phút đầu của cơn mưa."},"tl":{"q":"Kailan kadalasang pinakamadulas ang daan kapag umuulan?","o":["Pagkatapos umulan nang ilang oras","Sa unang ilang minuto ng ulan","Sa gabi lang","Kapag lumabas na ang araw lang"],"h1":"Isipin ang langis sa daan na humahalo sa unang tubig.","h2":"Sa simula ng ulan, humahalo ang tubig sa langis sa daan at nagiging napakadulas ito, kaya bumagal agad kapag nagsimulang umulan.","p":"Tama. Kadalasang pinakamadulas ang daan sa unang mga minuto ng ulan."},"ar":{"q":"متى يكون الطريق غالبًا أكثر انزلاقًا أثناء المطر؟","o":["بعد أن يمطر لساعات","في الدقائق الأولى من المطر","في الليل فقط","فقط عندما تخرج الشمس"],"h1":"فكّر في الزيت على الطريق عندما يختلط بأول ماء.","h2":"في بداية المطر، يختلط الماء بالزيت على الطريق ويجعله زلقًا جدًا، لذلك خفّف السرعة بمجرد أن يبدأ المطر.","p":"صحيح. الطرق غالبًا تكون أكثر انزلاقًا في الدقائق الأولى من المطر."},"ht":{"q":"Ki lè yon wout souvan pi glise pandan lapli?","o":["Apre lapli fin tonbe pandan plizyè èdtan","Nan premye minit lapli a","Sèlman lannwit","Sèlman lè solèy la parèt"],"h1":"Panse ak lwil ki sou wout la k ap melanje ak premye dlo a.","h2":"Lè lapli a kòmanse, dlo a melanje ak lwil ki sou wout la epi li fè wout la glise anpil, kidonk ralanti depi lapli a kòmanse tonbe.","p":"Se sa. Wout yo souvan pi glise nan premye minit lapli a."},"ref":{"doc":"FL","page":72}},{"id":"safe-driving-038","scope":"US","cat":"safe-driving","sign":null,"c":2,"en":{"q":"You feel very sleepy while driving. What is the best thing to do?","o":["Open the window and keep going","Turn the radio up loud","Pull off safely and rest","Drink coffee and drive faster"],"h1":"Think about what really fixes being tired.","h2":"Cold air, loud music or coffee do not cure sleepiness, so the safe choice is to pull off the road safely and rest or sleep.","p":"Right. When you are sleepy, pull off safely and rest."},"es":{"q":"Siente mucho sueño mientras maneja. ¿Qué es lo mejor que puede hacer?","o":["Abrir la ventana y seguir","Subir el volumen de la radio","Salir de la vía con seguridad y descansar","Tomar café y manejar más rápido"],"h1":"Piense en lo que de verdad quita el cansancio.","h2":"El aire frío, la música fuerte o el café no quitan el sueño, así que lo seguro es salir de la vía con cuidado y descansar o dormir.","p":"Correcto. Si tiene sueño, salga de la vía con seguridad y descanse."},"zh":{"q":"你开车时觉得非常困。最好的做法是什么？","o":["打开车窗，继续开","把收音机开得很大声","安全地把车开到路边休息","喝咖啡，开快一点"],"h1":"想一想什么才能真正解决疲劳。","h2":"冷风、大声的音乐或咖啡都不能解决困倦，所以安全的做法是把车安全地开离道路，休息或睡一觉。","p":"对。困的时候，把车安全地开到路边休息。"},"vi":{"q":"Bạn thấy rất buồn ngủ khi đang lái xe. Điều tốt nhất nên làm là gì?","o":["Mở cửa sổ và lái tiếp","Mở radio thật lớn","Tấp vào lề an toàn và nghỉ ngơi","Uống cà phê và lái nhanh hơn"],"h1":"Hãy nghĩ xem điều gì thật sự giải quyết được sự mệt mỏi.","h2":"Không khí lạnh, nhạc lớn hay cà phê không chữa được buồn ngủ, nên cách an toàn là tấp vào lề an toàn và nghỉ ngơi hoặc ngủ.","p":"Đúng. Khi buồn ngủ, hãy tấp vào lề an toàn và nghỉ ngơi."},"tl":{"q":"Inaantok ka nang husto habang nagmamaneho. Ano ang pinakamabuting gawin?","o":["Buksan ang bintana at tumuloy","Lakasan ang radyo","Tumabi nang ligtas at magpahinga","Uminom ng kape at magmaneho nang mas mabilis"],"h1":"Isipin kung ano talaga ang nakakapagpawala ng pagod.","h2":"Hindi nagagamot ng malamig na hangin, malakas na musika, o kape ang antok, kaya ang ligtas na gawin ay tumabi nang ligtas sa daan at magpahinga o matulog.","p":"Tama. Kapag inaantok ka, tumabi nang ligtas at magpahinga."},"ar":{"q":"تشعر بنعاس شديد وأنت تقود. ما أفضل شيء تفعله؟","o":["افتح النافذة وتابع السير","ارفع صوت الراديو","اخرج من الطريق بأمان واسترح","اشرب قهوة وقُد بسرعة أكبر"],"h1":"فكّر في الشيء الذي يعالج التعب حقًا.","h2":"الهواء البارد أو الموسيقى العالية أو القهوة لا تعالج النعاس، لذلك الخيار الآمن هو أن تخرج من الطريق بأمان وتستريح أو تنام.","p":"صحيح. عندما تشعر بالنعاس، اخرج من الطريق بأمان واسترح."},"ht":{"q":"Ou santi w gen anpil dòmi pandan w ap kondi. Kisa ki pi bon bagay pou w fè?","o":["Louvri fenèt la epi kontinye","Mete radyo a fò","Soti sou bò wout la san danje epi repoze w","Bwè kafe epi kondi pi vit"],"h1":"Panse ak sa ki vrèman retire fatig.","h2":"Lè frèt, mizik fò oswa kafe pa retire dòmi, kidonk bon chwa a se soti sou bò wout la san danje epi repoze w oswa dòmi.","p":"Se sa. Lè ou gen dòmi, soti sou bò wout la san danje epi repoze w."},"ref":{"doc":"FL","page":35}},{"id":"safe-driving-039","scope":"FL","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Florida, what is the legal blood alcohol limit for drivers age 21 and older?","o":["0.08 percent","0.10 percent","0.05 percent","0.15 percent"],"h1":"Think about the limit used for adult drivers in Florida.","h2":"In Florida an adult driver with a blood alcohol level of 0.08 percent or more is driving under the influence.","p":"Right. For drivers 21 and older, the limit is 0.08 percent."},"es":{"q":"En Florida, ¿cuál es el límite legal de alcohol en la sangre para conductores de 21 años o más?","o":["0.08 por ciento","0.10 por ciento","0.05 por ciento","0.15 por ciento"],"h1":"Piense en el límite que se usa para conductores adultos en Florida.","h2":"En Florida un conductor adulto con 0.08 por ciento o más de alcohol en la sangre está manejando bajo la influencia.","p":"Correcto. Para conductores de 21 años o más, el límite es 0.08 por ciento."},"zh":{"q":"在 Florida，21 岁及以上司机的法定血液酒精浓度上限是多少？","o":["0.08%","0.10%","0.05%","0.15%"],"h1":"想一想 Florida 成年司机用的上限。","h2":"在 Florida，成年司机的血液酒精浓度达到 0.08% 或更高，就是酒后驾驶。","p":"对。21 岁及以上的司机，上限是 0.08%。"},"vi":{"q":"Ở Florida, giới hạn nồng độ cồn trong máu theo luật cho tài xế từ 21 tuổi trở lên là bao nhiêu?","o":["0.08 phần trăm","0.10 phần trăm","0.05 phần trăm","0.15 phần trăm"],"h1":"Hãy nghĩ đến giới hạn dùng cho tài xế người lớn ở Florida.","h2":"Ở Florida, tài xế người lớn có nồng độ cồn trong máu từ 0.08 phần trăm trở lên là đang lái xe khi bị ảnh hưởng.","p":"Đúng. Với tài xế từ 21 tuổi trở lên, giới hạn là 0.08 phần trăm."},"tl":{"q":"Sa Florida, ano ang legal na blood alcohol limit para sa mga driver na 21 taong gulang pataas?","o":["0.08 porsyento","0.10 porsyento","0.05 porsyento","0.15 porsyento"],"h1":"Isipin ang limit na ginagamit para sa mga adult na driver sa Florida.","h2":"Sa Florida, ang adult na driver na may blood alcohol level na 0.08 porsyento o higit pa ay nagmamaneho nang lasing (DUI).","p":"Tama. Para sa mga driver na 21 pataas, ang limit ay 0.08 porsyento."},"ar":{"q":"في Florida، ما الحد القانوني لنسبة الكحول في الدم للسائقين الذين عمرهم 21 سنة أو أكثر؟","o":["0.08 بالمئة","0.10 بالمئة","0.05 بالمئة","0.15 بالمئة"],"h1":"فكّر في الحد المستعمل للسائقين البالغين في Florida.","h2":"في Florida، السائق البالغ الذي نسبة الكحول في دمه 0.08 بالمئة أو أكثر يقود تحت التأثير.","p":"صحيح. للسائقين بعمر 21 وأكثر، الحد هو 0.08 بالمئة."},"ht":{"q":"Nan Florida, ki limit legal alkòl nan san pou chofè ki gen 21 an oswa plis?","o":["0.08 pousan","0.10 pousan","0.05 pousan","0.15 pousan"],"h1":"Panse ak limit yo itilize pou chofè granmoun nan Florida.","h2":"Nan Florida, yon chofè granmoun ki gen yon nivo alkòl nan san 0.08 pousan oswa plis ap kondi sou enfliyans.","p":"Se sa. Pou chofè 21 an oswa plis, limit la se 0.08 pousan."},"ref":{"doc":"FL","page":25}},{"id":"safe-driving-040","scope":"FL","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Florida, a driver under age 21 has a blood alcohol level of 0.02 percent. What happens?","o":["Nothing, it is below the adult limit","Only a warning is given","The car is taken away","The driver's license is suspended"],"h1":"Think about the stricter rule for young drivers.","h2":"Florida has a zero tolerance rule for drivers under 21, so a level of 0.02 percent or more leads to a license suspension.","p":"Right. Under 21, a 0.02 percent level means a license suspension."},"es":{"q":"En Florida, un conductor menor de 21 años tiene 0.02 por ciento de alcohol en la sangre. ¿Qué pasa?","o":["Nada, está por debajo del límite de adultos","Solo recibe una advertencia","Le quitan el carro","Le suspenden la licencia de conducir"],"h1":"Piense en la regla más estricta para conductores jóvenes.","h2":"Florida tiene una regla de cero tolerancia para menores de 21 años, así que un nivel de 0.02 por ciento o más lleva a la suspensión de la licencia.","p":"Correcto. Menor de 21, un nivel de 0.02 por ciento significa suspensión de la licencia."},"zh":{"q":"在 Florida，一位 21 岁以下的司机血液酒精浓度是 0.02%。会怎么样？","o":["什么事也没有，因为低于成年人的上限","只会给一个警告","车会被拿走","司机的驾照会被暂停"],"h1":"想一想对年轻司机更严格的规定。","h2":"Florida 对 21 岁以下的司机实行零容忍规定，所以浓度达到 0.02% 或更高，驾照就会被暂停。","p":"对。21 岁以下，浓度 0.02% 就会暂停驾照。"},"vi":{"q":"Ở Florida, một tài xế dưới 21 tuổi có nồng độ cồn trong máu là 0.02 phần trăm. Điều gì xảy ra?","o":["Không có gì, vì thấp hơn giới hạn của người lớn","Chỉ bị cảnh cáo","Xe bị tịch thu","Bằng lái của tài xế bị đình chỉ"],"h1":"Hãy nghĩ đến quy định nghiêm hơn cho tài xế trẻ.","h2":"Florida có quy định không khoan nhượng với tài xế dưới 21 tuổi, nên mức 0.02 phần trăm trở lên sẽ dẫn đến bị đình chỉ bằng lái.","p":"Đúng. Dưới 21 tuổi, mức 0.02 phần trăm nghĩa là bị đình chỉ bằng lái."},"tl":{"q":"Sa Florida, ang driver na wala pang 21 taong gulang ay may blood alcohol level na 0.02 porsyento. Ano ang mangyayari?","o":["Wala, mas mababa ito sa limit ng adult","Warning lang ang ibibigay","Kukunin ang kotse","Masususpinde ang lisensya ng driver"],"h1":"Isipin ang mas mahigpit na patakaran para sa mga batang driver.","h2":"May zero tolerance rule ang Florida para sa mga driver na wala pang 21, kaya ang level na 0.02 porsyento o higit pa ay nauuwi sa suspensyon ng lisensya.","p":"Tama. Kapag wala pang 21, ang level na 0.02 porsyento ay suspensyon ng lisensya."},"ar":{"q":"في Florida، سائق عمره أقل من 21 سنة ونسبة الكحول في دمه 0.02 بالمئة. ماذا يحدث؟","o":["لا شيء، النسبة أقل من حد البالغين","يُعطى تحذيرًا فقط","تُؤخذ منه السيارة","تُوقف رخصة السائق"],"h1":"فكّر في القاعدة الأشد للسائقين الصغار.","h2":"في Florida قاعدة عدم التسامح مطلقًا للسائقين تحت 21 سنة، لذلك نسبة 0.02 بالمئة أو أكثر تؤدي إلى إيقاف الرخصة.","p":"صحيح. تحت 21 سنة، نسبة 0.02 بالمئة تعني إيقاف الرخصة."},"ht":{"q":"Nan Florida, yon chofè ki poko gen 21 an gen yon nivo alkòl nan san 0.02 pousan. Kisa k rive?","o":["Anyen, li anba limit granmoun yo","Yo ba l yon avètisman sèlman","Yo pran machin nan","Yo sispann lisans kondi chofè a"],"h1":"Panse ak règ ki pi sevè pou jèn chofè yo.","h2":"Florida gen yon règ zewo tolerans pou chofè ki poko gen 21 an, kidonk yon nivo 0.02 pousan oswa plis mennen nan yon sispansyon lisans.","p":"Se sa. Anba 21 an, yon nivo 0.02 pousan vle di yo sispann lisans ou."},"ref":{"doc":"FL","page":26}},{"id":"safe-driving-041","scope":"FL","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Florida, you are lawfully arrested for DUI and refuse a breath test for the first time. What happens to your license?","o":["Nothing happens to it","It is suspended for one year","It is suspended for one week","You get a warning letter only"],"h1":"Think about what you agreed to when you got a Florida license.","h2":"By driving in Florida you agree to be tested, so a first refusal after a lawful DUI arrest suspends your license for one year.","p":"Right. A first refusal suspends your license for one year."},"es":{"q":"En Florida, usted es arrestado legalmente por DUI y se niega por primera vez a una prueba de aliento. ¿Qué pasa con su licencia?","o":["No le pasa nada","La suspenden por un año","La suspenden por una semana","Solo recibe una carta de advertencia"],"h1":"Piense en lo que aceptó cuando recibió una licencia de Florida.","h2":"Al manejar en Florida usted acepta hacerse la prueba, así que negarse por primera vez después de un arresto legal por DUI suspende su licencia por un año.","p":"Correcto. Negarse la primera vez suspende su licencia por un año."},"zh":{"q":"在 Florida，你因酒后驾驶 (DUI) 被合法逮捕，第一次拒绝呼气检测。你的驾照会怎么样？","o":["没有任何影响","被暂停一年","被暂停一个星期","你只会收到一封警告信"],"h1":"想一想你拿到 Florida 驾照时同意了什么。","h2":"在 Florida 开车，就表示你同意接受检测，所以在因 DUI 被合法逮捕后第一次拒绝，你的驾照会被暂停一年。","p":"对。第一次拒绝，驾照暂停一年。"},"vi":{"q":"Ở Florida, bạn bị bắt hợp pháp vì lái xe khi say (DUI) và từ chối thổi nồng độ cồn lần đầu. Bằng lái của bạn bị xử lý thế nào?","o":["Không có gì xảy ra","Bị đình chỉ một năm","Bị đình chỉ một tuần","Bạn chỉ nhận một thư cảnh cáo"],"h1":"Hãy nghĩ xem bạn đã đồng ý điều gì khi nhận bằng lái Florida.","h2":"Khi lái xe ở Florida, bạn đồng ý được kiểm tra, nên từ chối lần đầu sau khi bị bắt hợp pháp vì DUI sẽ làm bằng lái của bạn bị đình chỉ một năm.","p":"Đúng. Từ chối lần đầu làm bằng lái bị đình chỉ một năm."},"tl":{"q":"Sa Florida, legal kang inaresto dahil sa DUI at tumanggi ka sa breath test sa unang beses. Ano ang mangyayari sa lisensya mo?","o":["Walang mangyayari rito","Masususpinde ito nang isang taon","Masususpinde ito nang isang linggo","Warning letter lang ang matatanggap mo"],"h1":"Isipin kung ano ang pinayagan mo nang makakuha ka ng Florida license.","h2":"Sa pagmamaneho sa Florida, pumapayag kang ma-test, kaya ang unang pagtanggi pagkatapos ng legal na pag-aresto dahil sa DUI ay magsususpinde sa lisensya mo nang isang taon.","p":"Tama. Ang unang pagtanggi ay magsususpinde sa lisensya mo nang isang taon."},"ar":{"q":"في Florida، اعتُقلت بشكل قانوني بسبب القيادة تحت التأثير (DUI) ورفضت فحص النَّفَس للمرة الأولى. ماذا يحدث لرخصتك؟","o":["لا يحدث لها شيء","تُوقف لمدة سنة واحدة","تُوقف لمدة أسبوع واحد","تحصل على رسالة تحذير فقط"],"h1":"فكّر في ما وافقت عليه عندما حصلت على رخصة Florida.","h2":"بمجرد أنك تقود في Florida أنت توافق على الفحص، لذلك الرفض الأول بعد اعتقال قانوني بسبب DUI يوقف رخصتك لمدة سنة واحدة.","p":"صحيح. الرفض الأول يوقف رخصتك لمدة سنة واحدة."},"ht":{"q":"Nan Florida, yo arete w legalman pou DUI (kondi sou enfliyans) epi ou refize yon tès souf pou premye fwa. Kisa k rive lisans ou?","o":["Anyen pa rive l","Yo sispann li pou yon ane","Yo sispann li pou yon semèn","Ou jwenn yon lèt avètisman sèlman"],"h1":"Panse ak sa ou te dakò lè ou te jwenn yon lisans Florida.","h2":"Lè ou kondi nan Florida, ou dakò pou yo teste w, kidonk yon premye refi apre yon arestasyon legal pou DUI fè yo sispann lisans ou pou yon ane.","p":"Se sa. Yon premye refi fè yo sispann lisans ou pou yon ane."},"ref":{"doc":"FL","page":25}},{"id":"safe-driving-042","scope":"US","cat":"safe-driving","sign":null,"c":2,"en":{"q":"Which is the first thing alcohol harms in a driver?","o":["Hearing","Hand strength","Judgment","Eyesight in daylight"],"h1":"Think about making good choices, like deciding whether to drive.","h2":"Alcohol affects judgment first, so a driver may feel fine and still make bad choices, like speeding or deciding to drive at all.","p":"Right. Alcohol harms judgment first."},"es":{"q":"¿Qué es lo primero que el alcohol afecta en un conductor?","o":["El oído","La fuerza de las manos","El juicio","La vista de día"],"h1":"Piense en tomar buenas decisiones, como decidir si manejar.","h2":"El alcohol afecta primero el juicio, así que un conductor puede sentirse bien y aun así tomar malas decisiones, como ir rápido o decidir manejar.","p":"Correcto. El alcohol afecta primero el juicio."},"zh":{"q":"酒精首先伤害司机的哪一方面？","o":["听力","手的力气","判断力","白天的视力"],"h1":"想一想做出好的决定，例如决定要不要开车。","h2":"酒精首先影响判断力，所以司机可能觉得自己没事，但还是会做出坏的决定，例如超速，或者决定开车。","p":"对。酒精首先伤害判断力。"},"vi":{"q":"Rượu bia ảnh hưởng đến điều gì của tài xế đầu tiên?","o":["Thính giác","Sức mạnh của tay","Khả năng phán đoán","Thị lực vào ban ngày"],"h1":"Hãy nghĩ đến việc đưa ra lựa chọn đúng, như quyết định có nên lái xe hay không.","h2":"Rượu bia ảnh hưởng đến khả năng phán đoán đầu tiên, nên tài xế có thể thấy mình vẫn ổn mà vẫn đưa ra lựa chọn sai, như chạy quá tốc độ hoặc quyết định lái xe.","p":"Đúng. Rượu bia ảnh hưởng đến khả năng phán đoán đầu tiên."},"tl":{"q":"Ano ang unang napipinsala ng alak sa isang driver?","o":["Pandinig","Lakas ng kamay","Paghuhusga (judgment)","Paningin sa araw"],"h1":"Isipin ang paggawa ng mabuting desisyon, gaya ng pagpapasya kung magmamaneho ka.","h2":"Ang paghuhusga ang unang naaapektuhan ng alak, kaya puwedeng pakiramdam ng driver ay ayos lang siya pero gumagawa pa rin siya ng maling desisyon, gaya ng pag-overspeed o ng pagpapasyang magmaneho pa.","p":"Tama. Ang paghuhusga ang unang napipinsala ng alak."},"ar":{"q":"ما أول شيء يضرّه الكحول عند السائق؟","o":["السمع","قوة اليدين","حُسن التقدير","النظر في ضوء النهار"],"h1":"فكّر في اتخاذ القرارات الجيدة، مثل أن تقرر هل تقود أم لا.","h2":"الكحول يؤثر أولًا على حُسن التقدير، لذلك قد يشعر السائق أنه بخير ومع ذلك يتخذ قرارات سيئة، مثل السرعة أو أن يقرر القيادة أصلًا.","p":"صحيح. الكحول يضرّ حُسن التقدير أولًا."},"ht":{"q":"Ki premye bagay alkòl fè mal nan yon chofè?","o":["Zòrèy li (tande)","Fòs men li","Jijman li","Je li lajounen"],"h1":"Panse ak fè bon chwa, tankou deside si pou w kondi.","h2":"Alkòl touche jijman an anvan, kidonk yon chofè ka santi l byen epi li toujou fè move chwa, tankou kouri twò vit oswa deside kondi ditou.","p":"Se sa. Alkòl fè jijman an mal anvan."},"ref":{"doc":"FL","page":35}},{"id":"safe-driving-043","scope":"US","cat":"safe-driving","sign":null,"c":0,"en":{"q":"After drinking, what is the only thing that makes you sober?","o":["Time","Black coffee","A cold shower","Fresh air"],"h1":"Think about how the body gets rid of alcohol.","h2":"Your body removes alcohol slowly on its own, so only time makes you sober; coffee, showers and fresh air do not.","p":"Right. Only time makes you sober."},"es":{"q":"Después de tomar alcohol, ¿qué es lo único que le quita la borrachera?","o":["El tiempo","El café negro","Una ducha fría","El aire fresco"],"h1":"Piense en cómo el cuerpo elimina el alcohol.","h2":"Su cuerpo elimina el alcohol poco a poco por sí solo, así que solo el tiempo le quita la borrachera; el café, la ducha y el aire fresco no.","p":"Correcto. Solo el tiempo le quita la borrachera."},"zh":{"q":"喝酒以后，唯一能让你清醒的是什么？","o":["时间","黑咖啡","冷水澡","新鲜空气"],"h1":"想一想身体怎样排出酒精。","h2":"你的身体会自己慢慢排出酒精，所以只有时间能让你清醒；咖啡、洗澡和新鲜空气都不行。","p":"对。只有时间能让你清醒。"},"vi":{"q":"Sau khi uống rượu bia, điều duy nhất làm bạn tỉnh lại là gì?","o":["Thời gian","Cà phê đen","Tắm nước lạnh","Không khí trong lành"],"h1":"Hãy nghĩ xem cơ thể loại bỏ rượu bia như thế nào.","h2":"Cơ thể bạn tự loại bỏ rượu bia một cách chậm rãi, nên chỉ có thời gian mới làm bạn tỉnh; cà phê, tắm và không khí trong lành thì không.","p":"Đúng. Chỉ có thời gian mới làm bạn tỉnh."},"tl":{"q":"Pagkatapos uminom ng alak, ano lang ang tanging nakakapagpawala ng pagkalasing?","o":["Oras","Black coffee","Malamig na paligo","Sariwang hangin"],"h1":"Isipin kung paano inaalis ng katawan ang alak.","h2":"Dahan-dahang inaalis ng katawan mo ang alak nang kusa, kaya oras lang ang nakakapagpawala ng pagkalasing; hindi ito nagagawa ng kape, paligo, o sariwang hangin.","p":"Tama. Oras lang ang nakakapagpawala ng pagkalasing."},"ar":{"q":"بعد شرب الكحول، ما الشيء الوحيد الذي يجعلك تصحو؟","o":["الوقت","القهوة السوداء","الاستحمام بماء بارد","الهواء النقي"],"h1":"فكّر في كيف يتخلص الجسم من الكحول.","h2":"جسمك يتخلص من الكحول ببطء وحده، لذلك الوقت فقط يجعلك تصحو؛ القهوة والاستحمام والهواء النقي لا تفعل ذلك.","p":"صحيح. الوقت فقط يجعلك تصحو."},"ht":{"q":"Apre ou fin bwè, ki sèl bagay ki fè w pa sou ankò?","o":["Tan","Kafe nwa","Yon douch frèt","Bon lè fre"],"h1":"Panse ak jan kò a retire alkòl la.","h2":"Kò ou retire alkòl la dousman pou kont li, kidonk se sèlman tan ki fè w pa sou ankò; kafe, douch ak bon lè fre pa fè sa.","p":"Se sa. Se sèlman tan ki fè w pa sou ankò."}},{"id":"safe-driving-044","scope":"US","cat":"safe-driving","sign":null,"c":3,"en":{"q":"You took a cold medicine you bought at the store. What should you do before you drive?","o":["Nothing, store medicines are always safe","Drive only on small streets","Drink coffee to stay awake","Read the label for warnings about drowsiness"],"h1":"Think about side effects that can make you sleepy.","h2":"Many medicines you buy without a prescription can make you sleepy or slow, so read the label and do not drive if it warns about drowsiness.","p":"Right. Read the label and do not drive if the medicine makes you drowsy."},"es":{"q":"Usted tomó una medicina para el resfriado que compró en la tienda. ¿Qué debe hacer antes de manejar?","o":["Nada, las medicinas de tienda siempre son seguras","Manejar solo por calles pequeñas","Tomar café para no dormirse","Leer la etiqueta por advertencias de sueño"],"h1":"Piense en efectos que le pueden dar sueño.","h2":"Muchas medicinas que se compran sin receta pueden darle sueño o hacerlo más lento, así que lea la etiqueta y no maneje si advierte que causa sueño.","p":"Correcto. Lea la etiqueta y no maneje si la medicina le da sueño."},"zh":{"q":"你吃了在商店买的感冒药。开车前你应该做什么？","o":["什么都不用做，商店买的药都是安全的","只在小街上开","喝咖啡保持清醒","看标签上有没有会让人犯困的警告"],"h1":"想一想可能让你犯困的副作用。","h2":"很多不用处方就能买的药会让你犯困或反应变慢，所以要看标签，如果警告会犯困，就不要开车。","p":"对。看标签，如果药会让你犯困，就不要开车。"},"vi":{"q":"Bạn đã uống thuốc cảm mua ở cửa hàng. Bạn nên làm gì trước khi lái xe?","o":["Không cần gì, thuốc mua ở cửa hàng luôn an toàn","Chỉ lái trên đường nhỏ","Uống cà phê để tỉnh táo","Đọc nhãn thuốc xem có cảnh báo gây buồn ngủ không"],"h1":"Hãy nghĩ đến tác dụng phụ có thể làm bạn buồn ngủ.","h2":"Nhiều loại thuốc mua không cần toa có thể làm bạn buồn ngủ hoặc chậm chạp, nên hãy đọc nhãn và đừng lái xe nếu nhãn cảnh báo gây buồn ngủ.","p":"Đúng. Đọc nhãn thuốc và đừng lái xe nếu thuốc làm bạn buồn ngủ."},"tl":{"q":"Uminom ka ng gamot sa sipon na binili mo sa tindahan. Ano ang dapat mong gawin bago magmaneho?","o":["Wala, laging ligtas ang mga gamot sa tindahan","Magmaneho lang sa maliliit na kalye","Uminom ng kape para manatiling gising","Basahin ang label para sa babala tungkol sa pag-aantok"],"h1":"Isipin ang mga side effect na puwedeng magpaantok sa iyo.","h2":"Maraming gamot na nabibili nang walang reseta ang puwedeng magpaantok o magpabagal sa iyo, kaya basahin ang label at huwag magmaneho kung may babala ito tungkol sa pag-aantok.","p":"Tama. Basahin ang label at huwag magmaneho kung nakakaantok ang gamot."},"ar":{"q":"أخذت دواءً للزكام اشتريته من المتجر. ماذا يجب أن تفعل قبل أن تقود؟","o":["لا شيء، أدوية المتجر آمنة دائمًا","قُد في الشوارع الصغيرة فقط","اشرب قهوة لتبقى مستيقظًا","اقرأ الملصق لترى تحذيرات عن النعاس"],"h1":"فكّر في الآثار الجانبية التي قد تجعلك نعسانًا.","h2":"أدوية كثيرة تشتريها بدون وصفة طبية قد تجعلك نعسانًا أو بطيئًا، لذلك اقرأ الملصق ولا تقُد إذا كان يحذّر من النعاس.","p":"صحيح. اقرأ الملصق ولا تقُد إذا كان الدواء يجعلك نعسانًا."},"ht":{"q":"Ou pran yon remèd pou grip ou te achte nan magazen. Kisa ou ta dwe fè anvan ou kondi?","o":["Anyen, remèd magazen toujou san danje","Kondi sèlman nan ti lari","Bwè kafe pou w rete reveye","Li etikèt la pou wè si gen avètisman sou dòmi"],"h1":"Panse ak efè segondè ki ka ba w dòmi.","h2":"Anpil remèd ou achte san preskripsyon ka ba w dòmi oswa fè w vin lan, kidonk li etikèt la epi pa kondi si li avèti w sou dòmi.","p":"Se sa. Li etikèt la epi pa kondi si remèd la ba w dòmi."},"ref":{"doc":"FL","page":36}},{"id":"safe-driving-045","scope":"US","cat":"safe-driving","sign":null,"c":1,"en":{"q":"An angry driver is tailgating you and making rude gestures. What should you do?","o":["Brake suddenly to teach a lesson","Avoid eye contact and let the driver pass","Make the same gestures back","Speed up to get away"],"h1":"Think about how to calm the situation, not make it bigger.","h2":"Reacting can make an angry driver more dangerous, so stay calm, avoid eye contact, and let the driver go by when it is safe.","p":"Right. Stay calm, avoid eye contact and let the driver pass."},"es":{"q":"Un conductor enojado lo sigue muy de cerca y le hace gestos groseros. ¿Qué debe hacer?","o":["Frenar de repente para darle una lección","Evitar mirarlo a los ojos y dejarlo pasar","Hacerle los mismos gestos","Acelerar para alejarse"],"h1":"Piense en cómo calmar la situación, no en hacerla más grande.","h2":"Responder puede hacer más peligroso a un conductor enojado, así que mantenga la calma, evite mirarlo a los ojos y déjelo pasar cuando sea seguro.","p":"Correcto. Mantenga la calma, no lo mire a los ojos y déjelo pasar."},"zh":{"q":"一个生气的司机紧跟在你后面，还做粗鲁的手势。你应该怎么做？","o":["突然刹车给他一个教训","避免和他对视，让他超过去","也对他做同样的手势","加速开走"],"h1":"想一想怎样让情况冷静下来，而不是变得更糟。","h2":"作出反应可能会让生气的司机更危险，所以要保持冷静，避免对视，在安全时让他过去。","p":"对。保持冷静，避免对视，让那位司机超过去。"},"vi":{"q":"Một tài xế đang tức giận bám sát đuôi xe bạn và làm cử chỉ thô lỗ. Bạn nên làm gì?","o":["Phanh gấp để dạy cho họ một bài học","Tránh nhìn vào mắt và để tài xế đó vượt qua","Làm lại cử chỉ giống vậy","Tăng tốc để chạy thoát"],"h1":"Hãy nghĩ cách làm tình huống dịu đi, không làm nó lớn hơn.","h2":"Phản ứng lại có thể làm tài xế đang tức giận nguy hiểm hơn, nên hãy giữ bình tĩnh, tránh nhìn vào mắt, và để tài xế đó đi qua khi an toàn.","p":"Đúng. Giữ bình tĩnh, tránh nhìn vào mắt và để tài xế đó vượt qua."},"tl":{"q":"Isang galit na driver ang dikit na dikit sa likod mo at gumagawa ng bastos na senyas. Ano ang dapat mong gawin?","o":["Biglang magpreno para turuan siya ng leksyon","Iwasang tumingin sa mata niya at hayaan siyang lumampas","Gumawa rin ng parehong senyas pabalik","Bumilis para makalayo"],"h1":"Isipin kung paano pakakalmahin ang sitwasyon, hindi palalakihin.","h2":"Ang pagpatol ay puwedeng gawing mas mapanganib ang galit na driver, kaya manatiling kalmado, iwasang tumingin sa mata niya, at hayaan siyang lumampas kapag ligtas.","p":"Tama. Manatiling kalmado, iwasang tumingin sa mata niya, at hayaan siyang lumampas."},"ar":{"q":"سائق غاضب يلتصق بك من الخلف ويقوم بحركات وقحة. ماذا يجب أن تفعل؟","o":["اضغط الفرامل فجأة لتعلّمه درسًا","تجنّب النظر في عينيه واتركه يتجاوزك","قُم بنفس الحركات له","أسرع لتبتعد عنه"],"h1":"فكّر في كيف تهدّئ الموقف، لا كيف تجعله أكبر.","h2":"الرد قد يجعل السائق الغاضب أخطر، لذلك ابقَ هادئًا، وتجنّب النظر في عينيه، واتركه يمرّ عندما يكون ذلك آمنًا.","p":"صحيح. ابقَ هادئًا، وتجنّب النظر في عينيه، واتركه يتجاوزك."},"ht":{"q":"Yon chofè ki fache ap kole dèyè w epi l ap fè move jès. Kisa ou ta dwe fè?","o":["Frennen sanzatann pou ba l yon leson","Pa gade l nan je epi kite chofè a pase","Fè l menm jès yo tou","Akselere pou w chape"],"h1":"Panse ak kijan pou w kalme sitiyasyon an, pa fè l vin pi gwo.","h2":"Si ou reyaji, yon chofè ki fache ka vin pi danjere, kidonk rete kalm, pa gade l nan je, epi kite chofè a pase lè li an sekirite.","p":"Se sa. Rete kalm, pa gade l nan je epi kite chofè a pase."},"ref":{"doc":"FL","page":36}},{"id":"safe-driving-046","scope":"US","cat":"safe-driving","sign":null,"c":2,"en":{"q":"An angry driver keeps following you. Where should you drive?","o":["Straight to your home","To a quiet dead-end street","To a police station or busy public place","Onto the shoulder to stop and talk"],"h1":"Think about a place where people can help you.","h2":"You should not lead an angry driver to your home, so drive to a police station or a busy public place and call 911 if needed.","p":"Right. Drive to a police station or a busy public place."},"es":{"q":"Un conductor enojado lo sigue y no lo deja. ¿Hacia dónde debe manejar?","o":["Directo a su casa","A una calle sin salida y tranquila","A una estación de policía o un lugar público con gente","Al acotamiento para parar y hablar"],"h1":"Piense en un lugar donde la gente pueda ayudarle.","h2":"No debe llevar a un conductor enojado hasta su casa, así que maneje a una estación de policía o a un lugar público con gente y llame al 911 si hace falta.","p":"Correcto. Maneje a una estación de policía o a un lugar público con gente."},"zh":{"q":"一个生气的司机一直跟着你。你应该开到哪里？","o":["直接开回家","开到安静的死胡同","开到警察局或人多的公共场所","开到路肩停下来和他说话"],"h1":"想一想有人能帮你的地方。","h2":"你不应该把生气的司机带到你家，所以要开到警察局或人多的公共场所，需要时打 911。","p":"对。开到警察局或人多的公共场所。"},"vi":{"q":"Một tài xế đang tức giận cứ bám theo bạn. Bạn nên lái đến đâu?","o":["Thẳng về nhà bạn","Đến một con hẻm cụt vắng vẻ","Đến đồn cảnh sát hoặc nơi công cộng đông người","Vào lề đường để dừng lại nói chuyện"],"h1":"Hãy nghĩ đến một nơi có người có thể giúp bạn.","h2":"Bạn không nên dẫn tài xế đang tức giận về nhà mình, nên hãy lái đến đồn cảnh sát hoặc nơi công cộng đông người và gọi 911 nếu cần.","p":"Đúng. Lái đến đồn cảnh sát hoặc nơi công cộng đông người."},"tl":{"q":"Patuloy kang sinusundan ng isang galit na driver. Saan ka dapat magmaneho?","o":["Diretso sa bahay mo","Sa tahimik na dead-end na kalye","Sa police station o mataong pampublikong lugar","Sa shoulder para huminto at makipag-usap"],"h1":"Isipin ang lugar kung saan may mga taong makakatulong sa iyo.","h2":"Hindi mo dapat dalhin ang galit na driver sa bahay mo, kaya magmaneho papunta sa police station o mataong pampublikong lugar at tumawag sa 911 kung kailangan.","p":"Tama. Magmaneho papunta sa police station o mataong pampublikong lugar."},"ar":{"q":"سائق غاضب يستمر في اللحاق بك. إلى أين يجب أن تقود؟","o":["مباشرة إلى بيتك","إلى شارع هادئ مسدود","إلى مركز شرطة أو مكان عام مزدحم","إلى كتف الطريق لتتوقف وتتكلم معه"],"h1":"فكّر في مكان فيه ناس يستطيعون مساعدتك.","h2":"لا يجب أن تقود السائق الغاضب إلى بيتك، لذلك قُد إلى مركز شرطة أو مكان عام مزدحم، واتصل بـ 911 إذا احتجت.","p":"صحيح. قُد إلى مركز شرطة أو مكان عام مزدحم."},"ht":{"q":"Yon chofè ki fache kontinye ap swiv ou. Ki kote ou ta dwe kondi ale?","o":["Tou dwat lakay ou","Nan yon ti lari trankil ki pa gen sòti","Nan yon estasyon polis oswa yon kote piblik ki gen anpil moun","Sou bò wout la pou kanpe pale avè l"],"h1":"Panse ak yon kote moun ka ede w.","h2":"Ou pa ta dwe mennen yon chofè ki fache lakay ou, kidonk kondi ale nan yon estasyon polis oswa yon kote piblik ki gen anpil moun, epi rele 911 si sa nesesè.","p":"Se sa. Kondi ale nan yon estasyon polis oswa yon kote piblik ki gen anpil moun."}},{"id":"safe-driving-047","scope":"US","cat":"safe-driving","sign":null,"c":0,"en":{"q":"Why is carbon monoxide from a car's exhaust so dangerous?","o":["You cannot see it or smell it","It always makes a loud sound","It only harms the engine","It turns the air black"],"h1":"Think about how you would notice a gas in the car.","h2":"Carbon monoxide has no color and no smell, so it can make you sleepy or sick without warning; never run the engine in a closed garage.","p":"Right. Carbon monoxide cannot be seen or smelled."},"es":{"q":"¿Por qué es tan peligroso el monóxido de carbono del escape del carro?","o":["No se puede ver ni oler","Siempre hace un ruido fuerte","Solo daña el motor","Pone el aire negro"],"h1":"Piense en cómo notaría un gas dentro del carro.","h2":"El monóxido de carbono no tiene color ni olor, así que puede darle sueño o enfermarlo sin aviso; nunca deje el motor encendido en un garaje cerrado.","p":"Correcto. El monóxido de carbono no se puede ver ni oler."},"zh":{"q":"为什么汽车尾气里的一氧化碳这么危险？","o":["你看不到，也闻不到","它总是发出很大的声音","它只伤害引擎","它让空气变黑"],"h1":"想一想你怎样才能发现车里有一种气体。","h2":"一氧化碳没有颜色，也没有气味，所以它可能在没有任何提醒的情况下让你犯困或生病；绝不要在关着的车库里让引擎运转。","p":"对。一氧化碳看不到，也闻不到。"},"vi":{"q":"Tại sao khí carbon monoxide từ ống xả xe lại rất nguy hiểm?","o":["Bạn không thể nhìn thấy hay ngửi thấy nó","Nó luôn phát ra tiếng động lớn","Nó chỉ làm hại động cơ","Nó làm không khí biến thành màu đen"],"h1":"Hãy nghĩ xem bạn sẽ nhận ra có khí trong xe bằng cách nào.","h2":"Carbon monoxide không màu và không mùi, nên nó có thể làm bạn buồn ngủ hoặc bị bệnh mà không có dấu hiệu báo trước; đừng bao giờ nổ máy xe trong ga-ra đóng kín.","p":"Đúng. Carbon monoxide không thể nhìn thấy hay ngửi thấy."},"tl":{"q":"Bakit napakamapanganib ng carbon monoxide mula sa usok ng tambutso ng kotse?","o":["Hindi mo ito nakikita o naaamoy","Laging may malakas itong tunog","Makina lang ang napipinsala nito","Pinaiitim nito ang hangin"],"h1":"Isipin kung paano mo mapapansin ang isang gas sa loob ng kotse.","h2":"Walang kulay at walang amoy ang carbon monoxide, kaya puwede ka nitong antukin o pasamain ang pakiramdam mo nang walang babala; huwag kailanman paandarin ang makina sa saradong garahe.","p":"Tama. Hindi nakikita o naaamoy ang carbon monoxide."},"ar":{"q":"لماذا أول أكسيد الكربون الخارج من عادم السيارة خطير جدًا؟","o":["لا تستطيع أن تراه أو تشمّه","يُصدر دائمًا صوتًا عاليًا","يضرّ المحرك فقط","يجعل الهواء أسود"],"h1":"فكّر: كيف ستلاحظ وجود غاز في السيارة؟","h2":"أول أكسيد الكربون ليس له لون ولا رائحة، لذلك قد يجعلك نعسانًا أو مريضًا بدون تحذير؛ لا تشغّل المحرك أبدًا في مرآب مغلق.","p":"صحيح. أول أكسيد الكربون لا يُرى ولا يُشمّ."},"ht":{"q":"Poukisa monoksid kabòn ki soti nan tiyo echapman yon machin danjere konsa?","o":["Ou pa ka wè l ni santi l","Li toujou fè yon gwo bri","Li fè motè a sèlman mal","Li fè lè a vin nwa"],"h1":"Panse ak kijan ou ta remake yon gaz nan machin nan.","h2":"Monoksid kabòn pa gen koulè ni odè, kidonk li ka ba w dòmi oswa rann ou malad san avètisman; pa janm kite motè a limen nan yon garaj ki fèmen.","p":"Se sa. Ou pa ka wè ni santi monoksid kabòn."}},{"id":"safe-driving-048","scope":"US","cat":"safe-driving","sign":null,"c":3,"en":{"q":"While driving, you get a headache and feel sleepy. You think it may be exhaust fumes. What should you do?","o":["Close all windows to stay warm","Turn the heater up high","Keep driving to get home fast","Open the windows and pull off safely"],"h1":"Think about getting fresh air right away.","h2":"A headache and sleepiness can be signs of carbon monoxide, so open the windows for fresh air, pull off safely, and have the exhaust checked.","p":"Right. Open the windows and pull off safely."},"es":{"q":"Mientras maneja, le da dolor de cabeza y sueño. Cree que pueden ser gases del escape. ¿Qué debe hacer?","o":["Cerrar todas las ventanas para no tener frío","Subir la calefacción al máximo","Seguir manejando para llegar rápido","Abrir las ventanas y salir de la vía con seguridad"],"h1":"Piense en conseguir aire fresco de inmediato.","h2":"El dolor de cabeza y el sueño pueden ser señales de monóxido de carbono, así que abra las ventanas, salga de la vía con seguridad y haga revisar el escape.","p":"Correcto. Abra las ventanas y salga de la vía con seguridad."},"zh":{"q":"开车时，你头痛，还觉得困。你觉得可能是尾气。你应该怎么做？","o":["关上所有车窗保暖","把暖气开得很大","继续开，快点回家","打开车窗，安全地把车开到路边"],"h1":"想一想马上得到新鲜空气。","h2":"头痛和犯困可能是一氧化碳的信号，所以要打开车窗换新鲜空气，安全地把车开到路边，并找人检查排气系统。","p":"对。打开车窗，安全地把车开到路边。"},"vi":{"q":"Khi đang lái xe, bạn bị nhức đầu và thấy buồn ngủ. Bạn nghĩ có thể là do khói ống xả. Bạn nên làm gì?","o":["Đóng hết cửa sổ để giữ ấm","Mở máy sưởi thật lớn","Lái tiếp để về nhà nhanh","Mở cửa sổ và tấp vào lề an toàn"],"h1":"Hãy nghĩ đến việc lấy không khí trong lành ngay lập tức.","h2":"Nhức đầu và buồn ngủ có thể là dấu hiệu của carbon monoxide, nên hãy mở cửa sổ để có không khí trong lành, tấp vào lề an toàn, và cho kiểm tra ống xả.","p":"Đúng. Mở cửa sổ và tấp vào lề an toàn."},"tl":{"q":"Habang nagmamaneho, sumakit ang ulo mo at inaantok ka. Sa tingin mo, baka usok ito ng tambutso. Ano ang dapat mong gawin?","o":["Isara ang lahat ng bintana para manatiling mainit","Lakasan ang heater","Tumuloy sa pagmamaneho para mabilis makauwi","Buksan ang mga bintana at tumabi nang ligtas"],"h1":"Isipin ang pagkuha agad ng sariwang hangin.","h2":"Ang sakit ng ulo at antok ay puwedeng senyales ng carbon monoxide, kaya buksan ang mga bintana para sa sariwang hangin, tumabi nang ligtas, at ipasuri ang tambutso.","p":"Tama. Buksan ang mga bintana at tumabi nang ligtas."},"ar":{"q":"وأنت تقود، تشعر بصداع ونعاس. تظن أن السبب قد يكون غازات العادم. ماذا يجب أن تفعل؟","o":["أغلق كل النوافذ لتبقى دافئًا","ارفع التدفئة إلى أعلى درجة","تابع القيادة لتصل إلى البيت بسرعة","افتح النوافذ واخرج من الطريق بأمان"],"h1":"فكّر في الحصول على هواء نقي فورًا.","h2":"الصداع والنعاس قد يكونان علامات على أول أكسيد الكربون، لذلك افتح النوافذ ليدخل هواء نقي، واخرج من الطريق بأمان، وافحص العادم.","p":"صحيح. افتح النوافذ واخرج من الطريق بأمان."},"ht":{"q":"Pandan w ap kondi, ou gen tèt fè mal epi ou santi w gen dòmi. Ou panse se ka lafimen tiyo echapman an. Kisa ou ta dwe fè?","o":["Fèmen tout fenèt yo pou w rete cho","Mete chofaj la fò","Kontinye kondi pou w rive lakay vit","Louvri fenèt yo epi soti sou bò wout la san danje"],"h1":"Panse ak jwenn bon lè fre touswit.","h2":"Tèt fè mal ak dòmi ka siy monoksid kabòn, kidonk louvri fenèt yo pou bon lè fre antre, soti sou bò wout la san danje, epi fè yo tcheke tiyo echapman an.","p":"Se sa. Louvri fenèt yo epi soti sou bò wout la san danje."}},{"id":"safe-driving-049","scope":"US","cat":"safe-driving","sign":null,"c":1,"en":{"q":"Why are worn tires with little tread dangerous?","o":["They make the radio louder","They grip the road poorly, mostly when wet","They use less gas","They make the steering heavier"],"h1":"Think about what the grooves in a tire do with water.","h2":"Tire tread moves water away so the tire can grip, so worn tires slip more and are more likely to hydroplane on wet roads.","p":"Right. Worn tires grip poorly, mostly on wet roads."},"es":{"q":"¿Por qué son peligrosas las llantas gastadas con poco dibujo?","o":["Hacen que la radio suene más fuerte","Agarran mal la vía, sobre todo mojada","Gastan menos gasolina","Hacen el volante más pesado"],"h1":"Piense en lo que hacen las ranuras de la llanta con el agua.","h2":"El dibujo de la llanta saca el agua para que la llanta agarre, así que las llantas gastadas resbalan más y es más fácil que hidroplaneen en vías mojadas.","p":"Correcto. Las llantas gastadas agarran mal, sobre todo en vías mojadas."},"zh":{"q":"为什么磨损、花纹很浅的轮胎很危险？","o":["它们让收音机更大声","它们抓地力差，尤其是在湿路上","它们更省油","它们让方向盘更重"],"h1":"想一想轮胎上的沟槽对水起什么作用。","h2":"轮胎花纹会把水排开，让轮胎能抓住路面，所以磨损的轮胎更容易打滑，在湿路上也更容易发生水滑。","p":"对。磨损的轮胎抓地力差，尤其是在湿路上。"},"vi":{"q":"Tại sao lốp xe bị mòn, còn ít gai, lại nguy hiểm?","o":["Chúng làm radio kêu to hơn","Chúng bám đường kém, nhất là khi đường ướt","Chúng tốn ít xăng hơn","Chúng làm tay lái nặng hơn"],"h1":"Hãy nghĩ xem các rãnh trên lốp xe làm gì với nước.","h2":"Gai lốp đẩy nước ra để lốp bám được đường, nên lốp bị mòn dễ trượt hơn và dễ bị lướt nước hơn trên đường ướt.","p":"Đúng. Lốp bị mòn bám đường kém, nhất là trên đường ướt."},"tl":{"q":"Bakit mapanganib ang mga gasgas na gulong na kaunti na lang ang tread (ukit)?","o":["Pinalalakas nila ang radyo","Mahina ang kapit nila sa daan, lalo na kapag basa","Mas kaunti ang gas na nagagamit nila","Pinabibigat nila ang manibela"],"h1":"Isipin kung ano ang ginagawa ng mga ukit ng gulong sa tubig.","h2":"Inaalis ng tread ng gulong ang tubig para makakapit ang gulong, kaya mas dumudulas ang mga gasgas na gulong at mas malamang mag-hydroplane sa basang daan.","p":"Tama. Mahina ang kapit ng mga gasgas na gulong, lalo na sa basang daan."},"ar":{"q":"لماذا الإطارات المستهلكة التي فيها نقوش قليلة خطيرة؟","o":["تجعل صوت الراديو أعلى","تتماسك مع الطريق بشكل ضعيف، خاصة عندما يكون مبللًا","تستهلك بنزينًا أقل","تجعل المقود أثقل"],"h1":"فكّر في ما تفعله الأخاديد في الإطار مع الماء.","h2":"نقوش الإطار تُبعد الماء حتى يتماسك الإطار مع الطريق، لذلك الإطارات المستهلكة تنزلق أكثر، ومن المرجح أن يحدث معها انزلاق مائي على الطرق المبللة.","p":"صحيح. الإطارات المستهلكة تتماسك بشكل ضعيف، خاصة على الطرق المبللة."},"ht":{"q":"Poukisa kawotchou ki fin use, ki pa gen anpil kannal ankò, danjere?","o":["Yo fè radyo a pi fò","Yo pa kenbe wout la byen, sitou lè li mouye","Yo itilize mwens gaz","Yo fè volan an pi lou"],"h1":"Panse ak sa ti kannal ki nan yon kawotchou fè ak dlo.","h2":"Kannal kawotchou yo pouse dlo a ale pou kawotchou a ka kenbe wout la, kidonk kawotchou ki fin use glise plis epi yo gen plis chans glise sou dlo (hydroplaning) sou wout mouye.","p":"Se sa. Kawotchou ki fin use pa kenbe wout la byen, sitou sou wout mouye."},"ref":{"doc":"FL","page":39}},{"id":"safe-driving-050","scope":"US","cat":"safe-driving","sign":null,"c":2,"en":{"q":"When should you adjust your seat and mirrors?","o":["While driving on the highway","At the first red light","Before you start driving","Only when someone else drove your car"],"h1":"Think about when your hands and eyes are free to do it safely.","h2":"Adjusting mirrors while moving takes your attention off the road, so you should set your seat and mirrors before you start driving.","p":"Right. Adjust your seat and mirrors before you start driving."},"es":{"q":"¿Cuándo debe ajustar el asiento y los espejos?","o":["Mientras maneja en la autopista","En el primer semáforo en rojo","Antes de empezar a manejar","Solo si otra persona usó su carro"],"h1":"Piense en cuándo tiene las manos y los ojos libres para hacerlo con seguridad.","h2":"Ajustar los espejos en movimiento le quita la atención de la vía, así que debe ajustar el asiento y los espejos antes de empezar a manejar.","p":"Correcto. Ajuste el asiento y los espejos antes de empezar a manejar."},"zh":{"q":"你应该什么时候调整座椅和后视镜？","o":["在高速公路上开车时","在第一个红灯时","在你开始开车之前","只在别人开过你的车以后"],"h1":"想一想什么时候你的手和眼睛有空，可以安全地做这件事。","h2":"车在动的时候调整后视镜会让你不注意道路，所以你应该在开始开车之前调好座椅和后视镜。","p":"对。在开始开车之前调整座椅和后视镜。"},"vi":{"q":"Khi nào bạn nên chỉnh ghế ngồi và gương?","o":["Khi đang lái trên xa lộ","Ở đèn đỏ đầu tiên","Trước khi bạn bắt đầu lái xe","Chỉ khi có người khác đã lái xe của bạn"],"h1":"Hãy nghĩ xem khi nào tay và mắt bạn rảnh để làm việc này an toàn.","h2":"Chỉnh gương khi xe đang chạy làm bạn mất tập trung vào đường, nên bạn nên chỉnh ghế ngồi và gương trước khi bắt đầu lái xe.","p":"Đúng. Chỉnh ghế ngồi và gương trước khi bắt đầu lái xe."},"tl":{"q":"Kailan mo dapat ayusin ang upuan at mga salamin mo?","o":["Habang nagmamaneho sa highway","Sa unang red light","Bago ka magsimulang magmaneho","Kapag may ibang nagmaneho lang ng kotse mo"],"h1":"Isipin kung kailan malaya ang mga kamay at mata mo para gawin ito nang ligtas.","h2":"Ang pag-aayos ng salamin habang umaandar ay nag-aalis ng atensyon mo sa daan, kaya dapat mong ayusin ang upuan at mga salamin mo bago ka magsimulang magmaneho.","p":"Tama. Ayusin ang upuan at mga salamin mo bago ka magsimulang magmaneho."},"ar":{"q":"متى يجب أن تضبط مقعدك ومراياك؟","o":["وأنت تقود على الطريق السريع","عند أول إشارة حمراء","قبل أن تبدأ القيادة","فقط عندما يقود شخص آخر سيارتك"],"h1":"فكّر في الوقت الذي تكون فيه يداك وعيناك حرة لتفعل ذلك بأمان.","h2":"ضبط المرايا أثناء الحركة يُبعد انتباهك عن الطريق، لذلك يجب أن تضبط مقعدك ومراياك قبل أن تبدأ القيادة.","p":"صحيح. اضبط مقعدك ومراياك قبل أن تبدأ القيادة."},"ht":{"q":"Ki lè ou ta dwe ranje chèz ou ak retwovizè ou yo?","o":["Pandan w ap kondi sou otowout la","Nan premye limyè wouj la","Anvan ou kòmanse kondi","Sèlman lè yon lòt moun te kondi machin ou"],"h1":"Panse ak ki lè men ou ak je ou lib pou w fè l san danje.","h2":"Ranje retwovizè yo pandan machin nan ap woule retire atansyon ou sou wout la, kidonk ou ta dwe ranje chèz ou ak retwovizè ou yo anvan ou kòmanse kondi.","p":"Se sa. Ranje chèz ou ak retwovizè ou yo anvan ou kòmanse kondi."},"ref":{"doc":"FL","page":59}},{"id":"safe-driving-051","scope":"US","cat":"safe-driving","sign":null,"c":0,"en":{"q":"What is the right way to use your car horn?","o":["To warn others of danger","To show you are angry","To greet friends you pass","To make slow drivers hurry"],"h1":"Think about safety, not feelings.","h2":"The horn is a safety tool, so use it to warn others of danger and not to show anger or rush people.","p":"Right. Use the horn to warn others of danger."},"es":{"q":"¿Cuál es la forma correcta de usar la bocina?","o":["Para avisar a otros de un peligro","Para mostrar que está enojado","Para saludar a amigos que pasa","Para que los lentos se apuren"],"h1":"Piense en la seguridad, no en los sentimientos.","h2":"La bocina es una herramienta de seguridad, así que úsela para avisar a otros de un peligro y no para mostrar enojo ni apurar a la gente.","p":"Correcto. Use la bocina para avisar a otros de un peligro."},"zh":{"q":"使用汽车喇叭的正确方法是什么？","o":["提醒别人有危险","表示你很生气","和路过的朋友打招呼","让开得慢的司机快点"],"h1":"想一想安全，而不是情绪。","h2":"喇叭是一个安全工具，所以要用它提醒别人有危险，而不是用来表示生气或催促别人。","p":"对。用喇叭提醒别人有危险。"},"vi":{"q":"Cách đúng để dùng còi xe là gì?","o":["Để cảnh báo người khác về nguy hiểm","Để cho thấy bạn đang tức giận","Để chào bạn bè khi chạy ngang qua","Để giục tài xế chạy chậm đi nhanh hơn"],"h1":"Hãy nghĩ đến sự an toàn, không phải cảm xúc.","h2":"Còi xe là một công cụ an toàn, nên hãy dùng còi để cảnh báo người khác về nguy hiểm, không phải để thể hiện sự tức giận hay giục người khác.","p":"Đúng. Dùng còi để cảnh báo người khác về nguy hiểm."},"tl":{"q":"Ano ang tamang paraan ng paggamit ng busina ng kotse mo?","o":["Para bigyan ng babala ang iba tungkol sa panganib","Para ipakitang galit ka","Para batiin ang mga kaibigang nadaraanan mo","Para magmadali ang mabagal na mga driver"],"h1":"Isipin ang kaligtasan, hindi ang damdamin.","h2":"Ang busina ay kasangkapan para sa kaligtasan, kaya gamitin ito para bigyan ng babala ang iba tungkol sa panganib at hindi para ipakita ang galit o madaliin ang mga tao.","p":"Tama. Gamitin ang busina para bigyan ng babala ang iba tungkol sa panganib."},"ar":{"q":"ما الطريقة الصحيحة لاستعمال بوق السيارة؟","o":["لتحذير الآخرين من خطر","لتُظهر أنك غاضب","لتحيّي أصدقاء تمرّ بجانبهم","لتجعل السائقين البطيئين يُسرعون"],"h1":"فكّر في السلامة، وليس في المشاعر.","h2":"البوق أداة للسلامة، لذلك استعمله لتحذير الآخرين من خطر، وليس لتُظهر الغضب أو لتستعجل الناس.","p":"صحيح. استعمل البوق لتحذير الآخرين من خطر."},"ht":{"q":"Ki bon fason pou w sèvi ak klaksonn machin ou?","o":["Pou avèti lòt moun gen danje","Pou montre ou fache","Pou salye zanmi ou pase","Pou fè chofè ki dousman yo fè vit"],"h1":"Panse ak sekirite, pa ak santiman.","h2":"Klaksonn nan se yon zouti sekirite, kidonk sèvi avè l pou avèti lòt moun gen danje, epi pa pou montre ou fache oswa pou prese moun.","p":"Se sa. Sèvi ak klaksonn nan pou avèti lòt moun gen danje."}},{"id":"safe-driving-052","scope":"US","cat":"safe-driving","sign":null,"c":3,"en":{"q":"Your wiper blades leave streaks and you cannot see well in the rain. What should you do?","o":["Drive with your head out the window","Use them only on the highway","Turn on your high beams","Replace the wiper blades soon"],"h1":"Think about what you need to see clearly in the rain.","h2":"Worn wiper blades do not clear the glass, so you should replace them soon to see the road clearly in the rain.","p":"Right. Replace worn wiper blades so you can see in the rain."},"es":{"q":"Sus limpiaparabrisas dejan rayas y no ve bien en la lluvia. ¿Qué debe hacer?","o":["Manejar con la cabeza afuera de la ventana","Usarlos solo en la autopista","Encender las luces altas","Cambiar las plumas del limpiaparabrisas pronto"],"h1":"Piense en lo que necesita para ver bien en la lluvia.","h2":"Las plumas gastadas no limpian bien el vidrio, así que debe cambiarlas pronto para ver la vía con claridad en la lluvia.","p":"Correcto. Cambie las plumas gastadas para ver bien en la lluvia."},"zh":{"q":"你的雨刷片留下条纹，下雨时你看不清楚。你应该怎么做？","o":["把头伸出窗外开车","只在高速公路上用","打开远光灯","尽快更换雨刷片"],"h1":"想一想下雨时你需要什么才能看清楚。","h2":"磨损的雨刷片擦不干净玻璃，所以你应该尽快更换，这样下雨时才能看清道路。","p":"对。更换磨损的雨刷片，下雨时才能看清楚。"},"vi":{"q":"Lưỡi gạt nước để lại vệt trên kính và bạn không nhìn rõ khi trời mưa. Bạn nên làm gì?","o":["Lái xe và thò đầu ra ngoài cửa sổ","Chỉ dùng gạt nước trên xa lộ","Bật đèn pha (đèn chiếu xa)","Thay lưỡi gạt nước sớm"],"h1":"Hãy nghĩ xem bạn cần gì để nhìn rõ khi trời mưa.","h2":"Lưỡi gạt nước bị mòn không làm sạch được kính, nên bạn nên thay chúng sớm để nhìn rõ đường khi trời mưa.","p":"Đúng. Thay lưỡi gạt nước bị mòn để nhìn rõ khi trời mưa."},"tl":{"q":"Nag-iiwan ng guhit ang wiper blades mo at hindi ka makakita nang maayos sa ulan. Ano ang dapat mong gawin?","o":["Magmaneho na nakalabas ang ulo sa bintana","Gamitin lang ang mga ito sa highway","I-on ang high beams mo","Palitan agad ang wiper blades"],"h1":"Isipin kung ano ang kailangan mo para makakita nang malinaw sa ulan.","h2":"Hindi nalilinis ng gasgas na wiper blades ang salamin, kaya dapat mo itong palitan agad para malinaw mong makita ang daan sa ulan.","p":"Tama. Palitan ang gasgas na wiper blades para makakita ka sa ulan."},"ar":{"q":"شفرات المساحات تترك خطوطًا ولا تستطيع أن ترى جيدًا في المطر. ماذا يجب أن تفعل؟","o":["قُد ورأسك خارج النافذة","استعملها على الطريق السريع فقط","شغّل الأضواء العالية","غيّر شفرات المساحات قريبًا"],"h1":"فكّر في ما تحتاجه لترى بوضوح في المطر.","h2":"شفرات المساحات المستهلكة لا تنظّف الزجاج، لذلك يجب أن تغيّرها قريبًا حتى ترى الطريق بوضوح في المطر.","p":"صحيح. غيّر شفرات المساحات المستهلكة حتى ترى في المطر."},"ht":{"q":"Wipè ou yo kite tras sou vit la epi ou pa ka wè byen nan lapli a. Kisa ou ta dwe fè?","o":["Kondi ak tèt ou deyò fenèt la","Sèvi ak yo sèlman sou otowout la","Limen gwo limyè ou yo","Chanje wipè yo byento"],"h1":"Panse ak sa ou bezwen pou w wè klè nan lapli a.","h2":"Wipè ki fin use pa netwaye vit la, kidonk ou ta dwe chanje yo byento pou w ka wè wout la klè nan lapli a.","p":"Se sa. Chanje wipè ki fin use yo pou w ka wè nan lapli a."}},{"id":"safe-driving-053","scope":"US","cat":"safe-driving","sign":null,"c":1,"en":{"q":"Your brake pedal feels soft and sinks close to the floor. What should you do?","o":["Keep driving and press harder","Have the brakes checked right away","Wait until the next oil change","Use only the parking brake from now on"],"h1":"Think about what a soft pedal can say about your brakes.","h2":"A soft or sinking brake pedal is a warning sign of a brake problem, so you should have the brakes checked right away.","p":"Right. A soft brake pedal means get the brakes checked now."},"es":{"q":"El pedal del freno se siente blando y baja casi hasta el piso. ¿Qué debe hacer?","o":["Seguir manejando y pisar más fuerte","Hacer revisar los frenos de inmediato","Esperar hasta el próximo cambio de aceite","Usar solo el freno de mano desde ahora"],"h1":"Piense en lo que un pedal blando puede decir de sus frenos.","h2":"Un pedal de freno blando o que se hunde es una señal de un problema en los frenos, así que debe hacerlos revisar de inmediato.","p":"Correcto. Un pedal blando significa revisar los frenos ya."},"zh":{"q":"你的刹车踏板踩起来软软的，还会沉到快碰到地板。你应该怎么做？","o":["继续开，用力踩","马上找人检查刹车","等到下次换机油时再说","从现在起只用手刹"],"h1":"想一想软的踏板可能说明你的刹车有什么问题。","h2":"刹车踏板变软或往下沉是刹车有问题的警告信号，所以你应该马上找人检查刹车。","p":"对。刹车踏板变软，就要马上检查刹车。"},"vi":{"q":"Bàn đạp phanh của bạn có cảm giác mềm và lún xuống gần sàn xe. Bạn nên làm gì?","o":["Lái tiếp và đạp mạnh hơn","Cho kiểm tra phanh ngay","Chờ đến lần thay dầu tới","Từ giờ chỉ dùng phanh tay"],"h1":"Hãy nghĩ xem bàn đạp mềm có thể cho biết điều gì về phanh của bạn.","h2":"Bàn đạp phanh mềm hoặc bị lún là dấu hiệu cảnh báo phanh có vấn đề, nên bạn nên cho kiểm tra phanh ngay.","p":"Đúng. Bàn đạp phanh mềm nghĩa là phải cho kiểm tra phanh ngay."},"tl":{"q":"Malambot ang pakiramdam ng preno mo at lumulubog ito malapit sa sahig. Ano ang dapat mong gawin?","o":["Tumuloy sa pagmamaneho at diinan pa","Ipasuri agad ang preno","Maghintay hanggang sa susunod na change oil","Parking brake na lang ang gamitin mula ngayon"],"h1":"Isipin kung ano ang puwedeng sabihin ng malambot na preno tungkol sa preno mo.","h2":"Ang malambot o lumulubog na preno ay babala ng problema sa preno, kaya dapat mong ipasuri agad ang preno.","p":"Tama. Kapag malambot ang preno, ipasuri agad ang preno."},"ar":{"q":"دواسة الفرامل تبدو لينة وتنزل قريبًا من الأرض. ماذا يجب أن تفعل؟","o":["تابع القيادة واضغط بقوة أكبر","افحص الفرامل فورًا","انتظر حتى تغيير الزيت القادم","استعمل فرامل اليد فقط من الآن"],"h1":"فكّر في ما تقوله الدواسة اللينة عن فراملك.","h2":"دواسة الفرامل اللينة أو التي تنزل كثيرًا علامة تحذير على مشكلة في الفرامل، لذلك يجب أن تفحص الفرامل فورًا.","p":"صحيح. دواسة الفرامل اللينة تعني أن تفحص الفرامل الآن."},"ht":{"q":"Pedal fren ou a mou epi li desann prèske rive atè. Kisa ou ta dwe fè?","o":["Kontinye kondi epi peze pi fò","Fè tcheke fren yo touswit","Tann pwochen fwa w ap chanje lwil","Sèvi ak fren a men an sèlman depi kounye a"],"h1":"Panse ak sa yon pedal mou ka di sou fren ou yo.","h2":"Yon pedal fren ki mou oswa ki desann se yon siy avètisman ke gen yon pwoblèm fren, kidonk ou ta dwe fè tcheke fren yo touswit.","p":"Se sa. Yon pedal fren mou vle di fè tcheke fren yo kounye a."}},{"id":"safe-driving-054","scope":"US","cat":"safe-driving","sign":null,"c":2,"en":{"q":"You are stopped behind a large truck on an uphill road. Why should you leave extra space?","o":["So you can read its license plate","So other cars can pass you","The truck may roll back a little when it starts","So the truck driver can see your lights"],"h1":"Think about what a heavy vehicle can do on a hill when it starts to move.","h2":"A heavy truck can roll back a little on a hill before it moves forward, so leave extra space in front of you.","p":"Right. Leave extra space because a truck may roll back on a hill."},"es":{"q":"Usted está parado detrás de un camión grande en una subida. ¿Por qué debe dejar más espacio?","o":["Para poder leer su placa","Para que otros carros lo rebasen","El camión puede rodar un poco hacia atrás al arrancar","Para que el chofer vea sus luces"],"h1":"Piense en lo que puede hacer un vehículo pesado en una subida al empezar a moverse.","h2":"Un camión pesado puede rodar un poco hacia atrás en una subida antes de avanzar, así que deje más espacio delante de usted.","p":"Correcto. Deje más espacio porque el camión puede rodar hacia atrás."},"zh":{"q":"你在上坡路上停在一辆大卡车后面。为什么你应该多留一些空间？","o":["这样你才能看清它的车牌","这样其他车才能超过你","卡车起步时可能会往后溜一点","这样卡车司机才能看到你的车灯"],"h1":"想一想重型车辆在坡上开始移动时可能会怎样。","h2":"重型卡车在坡上往前开之前，可能会往后溜一点，所以要在你前面多留一些空间。","p":"对。多留空间，因为卡车在坡上可能会往后溜。"},"vi":{"q":"Bạn đang dừng sau một xe tải lớn trên đường lên dốc. Tại sao bạn nên chừa thêm khoảng cách?","o":["Để bạn đọc được biển số xe của nó","Để các xe khác vượt qua bạn","Xe tải có thể bị trôi lùi một chút khi bắt đầu chạy","Để tài xế xe tải nhìn thấy đèn của bạn"],"h1":"Hãy nghĩ xem một xe nặng có thể làm gì trên dốc khi bắt đầu chạy.","h2":"Xe tải nặng có thể trôi lùi một chút trên dốc trước khi chạy tới, nên hãy chừa thêm khoảng cách phía trước bạn.","p":"Đúng. Chừa thêm khoảng cách vì xe tải có thể trôi lùi trên dốc."},"tl":{"q":"Nakahinto ka sa likod ng malaking truck sa paakyat na daan. Bakit dapat kang mag-iwan ng dagdag na espasyo?","o":["Para mabasa mo ang plate number nito","Para makalampas sa iyo ang ibang kotse","Puwedeng umatras nang kaunti ang truck kapag umandar ito","Para makita ng truck driver ang ilaw mo"],"h1":"Isipin kung ano ang puwedeng gawin ng mabigat na sasakyan sa paakyat kapag nagsisimula itong umandar.","h2":"Ang mabigat na truck ay puwedeng umatras nang kaunti sa paakyat bago ito umabante, kaya mag-iwan ng dagdag na espasyo sa harap mo.","p":"Tama. Mag-iwan ng dagdag na espasyo dahil puwedeng umatras ang truck sa paakyat."},"ar":{"q":"أنت متوقف خلف شاحنة كبيرة على طريق صاعد. لماذا يجب أن تترك مسافة إضافية؟","o":["حتى تستطيع قراءة لوحة أرقامها","حتى تستطيع السيارات الأخرى تجاوزك","الشاحنة قد ترجع إلى الخلف قليلًا عندما تبدأ بالتحرك","حتى يستطيع سائق الشاحنة رؤية أضوائك"],"h1":"فكّر في ما قد تفعله مركبة ثقيلة على طريق صاعد عندما تبدأ بالتحرك.","h2":"الشاحنة الثقيلة قد ترجع إلى الخلف قليلًا على الطريق الصاعد قبل أن تتقدم إلى الأمام، لذلك اترك مسافة إضافية أمامك.","p":"صحيح. اترك مسافة إضافية لأن الشاحنة قد ترجع إلى الخلف على الطريق الصاعد."},"ht":{"q":"Ou kanpe dèyè yon gwo kamyon sou yon wout k ap monte. Poukisa ou ta dwe kite plis espas?","o":["Pou w ka li plak li","Pou lòt machin ka pase w","Kamyon an ka fè bak yon ti kras lè l ap demare","Pou chofè kamyon an ka wè limyè ou"],"h1":"Panse ak sa yon machin lou ka fè sou yon mòn lè li kòmanse deplase.","h2":"Yon kamyon lou ka fè bak yon ti kras sou yon mòn anvan li avanse, kidonk kite plis espas devan w.","p":"Se sa. Kite plis espas paske yon kamyon ka fè bak sou yon mòn."},"ref":{"doc":"FL","page":82}},{"id":"signals-001","scope":"US","cat":"signals","sign":null,"c":2,"en":{"q":"What does a steady red traffic light mean?","o":["Slow down and go if no one is coming","Stop only if a police officer is there","Stop and stay stopped until it is safe and legal to go","Speed up to clear the intersection"],"h1":"Think about the strongest color on a traffic light.","h2":"A steady red light means you must stop and stay stopped, because cross traffic has the right to go.","p":"Right. A steady red light means stop and wait."},"es":{"q":"¿Qué significa una luz roja fija en el semáforo?","o":["Baje la velocidad y siga si no viene nadie","Pare solo si hay un policía","Pare y quédese parado hasta que sea seguro y legal seguir","Acelere para salir de la intersección"],"h1":"Piense en el color más fuerte del semáforo.","h2":"Una luz roja fija significa que usted debe parar y quedarse parado, porque el tráfico que cruza tiene el derecho a pasar.","p":"Correcto. Una luz roja fija significa pare y espere."},"zh":{"q":"一直亮着的红灯是什么意思？","o":["减速，没有来车就走","只有警察在场时才停","停车，一直停到安全且合法时再走","加速，快快开过路口"],"h1":"想一想：红绿灯上最强烈的颜色。","h2":"一直亮着的红灯表示你必须停车并保持停住，因为横向的车有权通行。","p":"对。一直亮着的红灯表示停车等待。"},"vi":{"q":"Đèn đỏ sáng đứng yên (không nhấp nháy) có nghĩa là gì?","o":["Chạy chậm lại và đi nếu không có ai tới","Chỉ dừng nếu có cảnh sát ở đó","Dừng lại và đứng yên tới khi được đi an toàn và đúng luật","Tăng tốc để qua khỏi giao lộ"],"h1":"Hãy nghĩ đến màu mạnh nhất trên đèn giao thông.","h2":"Đèn đỏ sáng đứng yên nghĩa là bạn phải dừng lại và đứng yên, vì xe ở hướng cắt ngang đang được quyền đi.","p":"Đúng rồi. Đèn đỏ sáng đứng yên nghĩa là dừng lại và chờ."},"tl":{"q":"Ano ang ibig sabihin ng tuloy-tuloy na pulang ilaw trapiko?","o":["Bumagal at umandar kung walang dumarating","Huminto lang kung may pulis doon","Huminto at manatiling nakahinto hanggang ligtas at legal nang umandar","Bumilis para malampasan ang interseksyon"],"h1":"Isipin ang pinakamalakas na kulay sa ilaw trapiko.","h2":"Ang tuloy-tuloy na pulang ilaw ay nangangahulugang dapat kang huminto at manatiling nakahinto, dahil ang trapiko sa kabilang daan ang may karapatang umandar.","p":"Tama. Ang tuloy-tuloy na pulang ilaw ay nangangahulugang huminto at maghintay."},"ar":{"q":"ماذا يعني الضوء الأحمر الثابت في إشارة المرور؟","o":["خفف السرعة وانطلق إذا لم يأتِ أحد","توقف فقط إذا كان هناك شرطي","توقف وابقَ متوقفًا حتى يصبح الانطلاق آمنًا ومسموحًا","زد السرعة لتخرج من التقاطع"],"h1":"فكّر في أقوى لون في إشارة المرور.","h2":"الضوء الأحمر الثابت يعني أنه يجب أن تتوقف وتبقى متوقفًا، لأن السيارات في الاتجاه المتقاطع لها الحق في المرور.","p":"صحيح. الضوء الأحمر الثابت يعني: توقف وانتظر."},"ht":{"q":"Kisa yon limyè trafik wouj fiks vle di?","o":["Ralanti epi pase si pa gen moun k ap vini","Kanpe sèlman si gen yon polis la","Kanpe epi rete kanpe jiskaske li an sekirite epi lalwa pèmèt ou pase","Akselere pou kite kafou a"],"h1":"Panse ak koulè ki pi fò sou yon limyè trafik.","h2":"Yon limyè wouj fiks vle di ou dwe kanpe epi rete kanpe, paske machin ki sou lòt lari a gen dwa pou pase.","p":"Se sa. Yon limyè wouj fiks vle di kanpe epi tann."},"ref":{"doc":"FL","page":51}},{"id":"signals-002","scope":"US","cat":"signals","sign":null,"c":0,"en":{"q":"The light turns steady yellow as you come near. What should you do?","o":["Stop if you can do it safely","Speed up to beat the red light","Stop suddenly, no matter what","Keep going at the same speed always"],"h1":"Yellow is a warning. Think about what color comes next.","h2":"A steady yellow light warns that the light will soon turn red, so you should stop if you can do it safely.","p":"Right. Steady yellow means red is coming, so stop if it is safe."},"es":{"q":"La luz cambia a amarillo fijo cuando usted se acerca. ¿Qué debe hacer?","o":["Parar si lo puede hacer con seguridad","Acelerar para pasar antes de la roja","Frenar de golpe, pase lo que pase","Seguir siempre a la misma velocidad"],"h1":"El amarillo es una advertencia. Piense qué color viene después.","h2":"Una luz amarilla fija avisa que pronto cambiará a roja, así que usted debe parar si lo puede hacer con seguridad.","p":"Correcto. Amarillo fijo significa que viene la roja, así que pare si es seguro."},"zh":{"q":"你快到路口时，灯变成一直亮着的黄灯。你应该怎么做？","o":["如果能安全停下，就停车","加速，抢在红灯前过去","不管怎样都马上急停","总是保持同样的速度继续开"],"h1":"黄灯是警告。想一想接下来是什么颜色。","h2":"一直亮着的黄灯提醒你马上要变红灯，所以如果能安全停下，你就应该停车。","p":"对。黄灯表示红灯要来了，安全的话就停车。"},"vi":{"q":"Khi bạn tới gần, đèn chuyển sang vàng sáng đứng yên. Bạn nên làm gì?","o":["Dừng lại nếu bạn có thể dừng an toàn","Tăng tốc để qua trước khi đèn đỏ","Dừng gấp, dù thế nào đi nữa","Lúc nào cũng giữ nguyên tốc độ mà chạy tiếp"],"h1":"Màu vàng là lời cảnh báo. Hãy nghĩ xem màu nào sẽ tới sau đó.","h2":"Đèn vàng sáng đứng yên cảnh báo rằng đèn sắp chuyển sang đỏ, nên bạn cần dừng lại nếu có thể dừng an toàn.","p":"Đúng rồi. Đèn vàng nghĩa là sắp đỏ, nên hãy dừng nếu an toàn."},"tl":{"q":"Naging tuloy-tuloy na dilaw ang ilaw habang papalapit ka. Ano ang dapat mong gawin?","o":["Huminto kung kaya mong gawin ito nang ligtas","Bumilis para maunahan ang pulang ilaw","Huminto nang biglaan, kahit ano pa ang mangyari","Magpatuloy sa parehong bilis palagi"],"h1":"Ang dilaw ay isang babala. Isipin kung anong kulay ang susunod.","h2":"Ang tuloy-tuloy na dilaw na ilaw ay babala na malapit nang maging pula ang ilaw, kaya dapat kang huminto kung kaya mong gawin ito nang ligtas.","p":"Tama. Ang tuloy-tuloy na dilaw ay nangangahulugang paparating na ang pula, kaya huminto kung ligtas."},"ar":{"q":"الإشارة تصبح صفراء ثابتة وأنت تقترب. ماذا يجب أن تفعل؟","o":["توقف إذا استطعت أن تفعل ذلك بأمان","زد السرعة لتسبق الضوء الأحمر","توقف فجأة مهما كان الوضع","استمر بنفس السرعة دائمًا"],"h1":"الأصفر تحذير. فكّر في اللون الذي يأتي بعده.","h2":"الضوء الأصفر الثابت يحذّر من أن الإشارة ستصبح حمراء قريبًا، لذلك يجب أن تتوقف إذا استطعت أن تفعل ذلك بأمان.","p":"صحيح. الأصفر الثابت يعني أن الأحمر قادم، لذلك توقف إذا كان ذلك آمنًا."},"ht":{"q":"Limyè a vin jòn fiks pandan w ap pwoche. Kisa ou dwe fè?","o":["Kanpe si ou ka fè l an sekirite","Akselere pou pase anvan limyè wouj la","Kanpe sèk, kèlkeswa sa k rive","Toujou kontinye ak menm vitès la"],"h1":"Jòn se yon avètisman. Panse ak ki koulè ki vini apre.","h2":"Yon limyè jòn fiks avèti ou limyè a pral vin wouj talè, kidonk ou dwe kanpe si ou ka fè l an sekirite.","p":"Se sa. Jòn fiks vle di wouj ap vini, kidonk kanpe si sa an sekirite."},"ref":{"doc":"FL","page":51}},{"id":"signals-003","scope":"US","cat":"signals","sign":null,"c":3,"en":{"q":"You are already in the intersection when the light turns yellow. What should you do?","o":["Stop in the middle of the intersection","Back up to the stop line","Turn around in the intersection","Carefully finish going through the intersection"],"h1":"Think about where it is safest for your car to be when the light turns red.","h2":"If you are already in the intersection when the light turns yellow, you should carefully keep going, because stopping there would block traffic.","p":"Right. If you are already in the intersection, carefully clear it."},"es":{"q":"Usted ya está dentro de la intersección cuando la luz cambia a amarillo. ¿Qué debe hacer?","o":["Parar en medio de la intersección","Dar marcha atrás hasta la línea de pare","Dar la vuelta dentro de la intersección","Terminar de cruzar la intersección con cuidado"],"h1":"Piense dónde es más seguro estar cuando la luz cambie a roja.","h2":"Si usted ya está dentro de la intersección cuando la luz cambia a amarillo, debe seguir con cuidado, porque parar ahí bloquearía el tráfico.","p":"Correcto. Si ya está dentro de la intersección, termine de cruzar con cuidado."},"zh":{"q":"灯变黄时，你已经在路口里面了。你应该怎么做？","o":["停在路口中间","倒车回到停车线","在路口里掉头","小心地继续开出路口"],"h1":"想一想：变红灯时，你的车在哪里最安全。","h2":"如果灯变黄时你已经在路口里面，你应该小心地继续开，因为停在那里会挡住交通。","p":"对。如果你已经在路口里，就小心地开出去。"},"vi":{"q":"Bạn đã ở trong giao lộ thì đèn chuyển sang vàng. Bạn nên làm gì?","o":["Dừng lại ở giữa giao lộ","Lùi xe về vạch dừng","Quay đầu xe trong giao lộ","Cẩn thận chạy tiếp cho qua hết giao lộ"],"h1":"Hãy nghĩ xem xe bạn ở đâu là an toàn nhất khi đèn chuyển sang đỏ.","h2":"Nếu bạn đã ở trong giao lộ khi đèn chuyển sang vàng, bạn cần cẩn thận chạy tiếp, vì dừng ở đó sẽ chắn đường xe khác.","p":"Đúng rồi. Nếu bạn đã ở trong giao lộ, hãy cẩn thận chạy qua cho hết."},"tl":{"q":"Nasa loob ka na ng interseksyon nang maging dilaw ang ilaw. Ano ang dapat mong gawin?","o":["Huminto sa gitna ng interseksyon","Umatras pabalik sa stop line","Umikot pabalik sa loob ng interseksyon","Maingat na tapusin ang pagdaan sa interseksyon"],"h1":"Isipin kung saan pinakaligtas ang sasakyan mo kapag naging pula ang ilaw.","h2":"Kung nasa loob ka na ng interseksyon nang maging dilaw ang ilaw, dapat kang magpatuloy nang maingat, dahil kapag huminto ka doon ay haharangan mo ang trapiko.","p":"Tama. Kung nasa loob ka na ng interseksyon, maingat na lumabas dito."},"ar":{"q":"أنت داخل التقاطع بالفعل عندما تصبح الإشارة صفراء. ماذا يجب أن تفعل؟","o":["توقف في وسط التقاطع","ارجع إلى الخلف حتى خط التوقف","استدر عائدًا داخل التقاطع","أكمل عبور التقاطع بحذر"],"h1":"فكّر في أكثر مكان آمن لسيارتك عندما تصبح الإشارة حمراء.","h2":"إذا كنت داخل التقاطع بالفعل عندما تصبح الإشارة صفراء، يجب أن تكمل طريقك بحذر، لأن توقفك هناك سيغلق الطريق أمام السيارات.","p":"صحيح. إذا كنت داخل التقاطع بالفعل، اخرج منه بحذر."},"ht":{"q":"Ou deja nan kafou a lè limyè a vin jòn. Kisa ou dwe fè?","o":["Kanpe nan mitan kafou a","Fè bak jiska liy pou kanpe a","Vire tounen nan kafou a","Fini travèse kafou a avèk prekosyon"],"h1":"Panse ki kote li pi an sekirite pou machin ou ye lè limyè a vin wouj.","h2":"Si ou deja nan kafou a lè limyè a vin jòn, ou dwe kontinye avèk prekosyon, paske si ou kanpe la a ou ta bloke trafik la.","p":"Se sa. Si ou deja nan kafou a, fini travèse l avèk prekosyon."},"ref":{"doc":"FL","page":51}},{"id":"signals-004","scope":"US","cat":"signals","sign":null,"c":1,"en":{"q":"What does a flashing red light mean?","o":["Slow down, but you do not need to stop","Stop fully, then go when the way is clear","The light is about to turn green","Only trucks must stop"],"h1":"A flashing red light works like a sign you already know.","h2":"A flashing red light works like a stop sign, so you must stop fully and then go when the way is clear.","p":"Right. A flashing red light means stop, then go when safe."},"es":{"q":"¿Qué significa una luz roja intermitente?","o":["Baje la velocidad, pero no tiene que parar","Pare por completo y luego siga cuando el camino esté libre","La luz está por cambiar a verde","Solo los camiones deben parar"],"h1":"Una luz roja intermitente funciona como una señal que usted ya conoce.","h2":"Una luz roja intermitente funciona como una señal de pare, así que usted debe parar por completo y luego seguir cuando el camino esté libre.","p":"Correcto. Luz roja intermitente significa pare y luego siga cuando sea seguro."},"zh":{"q":"闪烁的红灯是什么意思？","o":["减速，但不用停车","完全停车，没车时再走","灯马上要变绿了","只有卡车要停"],"h1":"闪烁的红灯和一个你已经知道的标志作用一样。","h2":"闪烁的红灯和停车标志作用一样，所以你必须完全停车，没车时再走。","p":"对。闪烁的红灯表示停车，安全时再走。"},"vi":{"q":"Đèn đỏ nhấp nháy có nghĩa là gì?","o":["Chạy chậm lại, nhưng không cần dừng","Dừng hẳn, rồi đi khi đường đã trống","Đèn sắp chuyển sang xanh","Chỉ xe tải phải dừng"],"h1":"Đèn đỏ nhấp nháy giống như một biển báo bạn đã biết.","h2":"Đèn đỏ nhấp nháy giống như biển “STOP” (Dừng lại), nên bạn phải dừng hẳn rồi mới đi khi đường đã trống.","p":"Đúng rồi. Đèn đỏ nhấp nháy nghĩa là dừng lại, rồi đi khi an toàn."},"tl":{"q":"Ano ang ibig sabihin ng kumikislap na pulang ilaw?","o":["Bumagal, pero hindi mo kailangang huminto","Huminto nang buo, saka umandar kapag maluwag na ang daan","Malapit nang maging berde ang ilaw","Mga trak lang ang dapat huminto"],"h1":"Ang kumikislap na pulang ilaw ay gumagana na parang karatula na kilala mo na.","h2":"Ang kumikislap na pulang ilaw ay gumagana na parang “STOP” sign, kaya dapat kang huminto nang buo at saka umandar kapag maluwag na ang daan.","p":"Tama. Ang kumikislap na pulang ilaw ay nangangahulugang huminto, saka umandar kapag ligtas."},"ar":{"q":"ماذا يعني الضوء الأحمر الوامض؟","o":["خفف السرعة، لكن لا تحتاج إلى التوقف","توقف تمامًا، ثم انطلق عندما يكون الطريق خاليًا","الإشارة ستصبح خضراء بعد قليل","الشاحنات فقط يجب أن تتوقف"],"h1":"الضوء الأحمر الوامض يعمل مثل لافتة تعرفها بالفعل.","h2":"الضوء الأحمر الوامض يعمل مثل لافتة «STOP» (قف)، لذلك يجب أن تتوقف تمامًا ثم تنطلق عندما يكون الطريق خاليًا.","p":"صحيح. الضوء الأحمر الوامض يعني: توقف، ثم انطلق عندما يكون الطريق آمنًا."},"ht":{"q":"Kisa yon limyè wouj k ap kliyote vle di?","o":["Ralanti, men ou pa bezwen kanpe","Kanpe nèt, epi pase lè wout la lib","Limyè a pral vin vèt talè","Se sèlman kamyon ki dwe kanpe"],"h1":"Yon limyè wouj k ap kliyote mache tankou yon siy ou deja konnen.","h2":"Yon limyè wouj k ap kliyote mache tankou yon siy “STOP”, kidonk ou dwe kanpe nèt epi pase lè wout la lib.","p":"Se sa. Yon limyè wouj k ap kliyote vle di kanpe, epi pase lè sa an sekirite."},"ref":{"doc":"FL","page":52}},{"id":"signals-005","scope":"US","cat":"signals","sign":null,"c":0,"en":{"q":"What does a flashing yellow light mean?","o":["Slow down and go ahead with care","Stop fully and wait for green","The road is closed ahead","You must turn right"],"h1":"A flashing yellow light is a warning, not an order to stop.","h2":"A flashing yellow light means you should slow down and go ahead with care, because there may be danger ahead.","p":"Right. A flashing yellow light means slow down and be careful."},"es":{"q":"¿Qué significa una luz amarilla intermitente?","o":["Baje la velocidad y siga con cuidado","Pare por completo y espere la verde","La calle está cerrada más adelante","Usted debe girar a la derecha"],"h1":"Una luz amarilla intermitente es una advertencia, no una orden de parar.","h2":"Una luz amarilla intermitente significa que usted debe bajar la velocidad y seguir con cuidado, porque puede haber peligro más adelante.","p":"Correcto. Luz amarilla intermitente significa baje la velocidad y tenga cuidado."},"zh":{"q":"闪烁的黄灯是什么意思？","o":["减速，小心往前开","完全停车，等绿灯","前方道路封闭","你必须右转"],"h1":"闪烁的黄灯是警告，不是要你停车。","h2":"闪烁的黄灯表示你应该减速，小心往前开，因为前方可能有危险。","p":"对。闪烁的黄灯表示减速，要小心。"},"vi":{"q":"Đèn vàng nhấp nháy có nghĩa là gì?","o":["Chạy chậm lại và đi tiếp một cách cẩn thận","Dừng hẳn và chờ đèn xanh","Phía trước đường bị đóng","Bạn phải rẽ phải"],"h1":"Đèn vàng nhấp nháy là lời cảnh báo, không phải lệnh dừng.","h2":"Đèn vàng nhấp nháy nghĩa là bạn cần chạy chậm lại và đi tiếp một cách cẩn thận, vì phía trước có thể có nguy hiểm.","p":"Đúng rồi. Đèn vàng nhấp nháy nghĩa là chạy chậm và cẩn thận."},"tl":{"q":"Ano ang ibig sabihin ng kumikislap na dilaw na ilaw?","o":["Bumagal at magpatuloy nang maingat","Huminto nang buo at hintayin ang berde","Sarado ang kalsada sa unahan","Dapat kang kumanan"],"h1":"Ang kumikislap na dilaw na ilaw ay babala, hindi utos na huminto.","h2":"Ang kumikislap na dilaw na ilaw ay nangangahulugang dapat kang bumagal at magpatuloy nang maingat, dahil maaaring may panganib sa unahan.","p":"Tama. Ang kumikislap na dilaw na ilaw ay nangangahulugang bumagal at mag-ingat."},"ar":{"q":"ماذا يعني الضوء الأصفر الوامض؟","o":["خفف السرعة وتابع بحذر","توقف تمامًا وانتظر الأخضر","الطريق مغلق في الأمام","يجب أن تنعطف يمينًا"],"h1":"الضوء الأصفر الوامض تحذير، وليس أمرًا بالتوقف.","h2":"الضوء الأصفر الوامض يعني أنه يجب أن تخفف السرعة وتتابع بحذر، لأنه قد يكون هناك خطر في الأمام.","p":"صحيح. الضوء الأصفر الوامض يعني: خفف السرعة وكن حذرًا."},"ht":{"q":"Kisa yon limyè jòn k ap kliyote vle di?","o":["Ralanti epi kontinye avèk prekosyon","Kanpe nèt epi tann limyè vèt la","Wout la fèmen pi devan","Ou dwe vire adwat"],"h1":"Yon limyè jòn k ap kliyote se yon avètisman, se pa yon lòd pou kanpe.","h2":"Yon limyè jòn k ap kliyote vle di ou dwe ralanti epi kontinye avèk prekosyon, paske ka gen danje pi devan.","p":"Se sa. Yon limyè jòn k ap kliyote vle di ralanti epi fè atansyon."},"ref":{"doc":"FL","page":52}},{"id":"signals-006","scope":"US","cat":"signals","sign":null,"c":2,"en":{"q":"The light is steady green. A person is still crossing in the crosswalk. What should you do?","o":["Go, because green gives you the right of way","Honk so the person moves faster","Wait and let the person finish crossing","Drive around the person"],"h1":"A green light lets you go, but think about who was there first.","h2":"A green light lets you go only when the way is clear, so you must wait for people and cars that are already in the intersection.","p":"Right. On green, you still let people finish crossing."},"es":{"q":"La luz está en verde fijo. Una persona todavía está cruzando por el paso peatonal. ¿Qué debe hacer?","o":["Seguir, porque la verde le da el derecho de paso","Tocar la bocina para que la persona se apure","Esperar y dejar que la persona termine de cruzar","Pasar por un lado de la persona"],"h1":"La luz verde le permite seguir, pero piense en quién estaba ahí primero.","h2":"La luz verde le permite seguir solo cuando el camino está libre, así que usted debe esperar a las personas y los carros que ya están en la intersección.","p":"Correcto. Con luz verde, igual deje que las personas terminen de cruzar."},"zh":{"q":"灯是一直亮着的绿灯。有一个人还在人行横道上过马路。你应该怎么做？","o":["开走，因为绿灯给你优先通行权","按喇叭让那个人走快点","等一等，让那个人走完","绕过那个人开过去"],"h1":"绿灯让你走，但想一想谁先在那里。","h2":"绿灯只有在路上没有人和车时才让你走，所以你必须等已经在路口里的行人和车辆。","p":"对。绿灯时，你仍然要让行人走完。"},"vi":{"q":"Đèn xanh sáng đứng yên. Có một người vẫn đang đi qua vạch qua đường. Bạn nên làm gì?","o":["Cứ đi, vì đèn xanh cho bạn quyền đi trước","Bấm còi để người đó đi nhanh hơn","Chờ và để người đó đi qua hết","Chạy vòng qua người đó"],"h1":"Đèn xanh cho bạn đi, nhưng hãy nghĩ xem ai đã ở đó trước.","h2":"Đèn xanh chỉ cho bạn đi khi đường đã trống, nên bạn phải chờ người đi bộ và xe đang ở trong giao lộ.","p":"Đúng rồi. Khi đèn xanh, bạn vẫn phải để người đi bộ qua hết."},"tl":{"q":"Tuloy-tuloy na berde ang ilaw. May tao pang tumatawid sa tawiran. Ano ang dapat mong gawin?","o":["Umandar, dahil ang berde ay nagbibigay sa iyo ng karapatang mauna","Bumusina para bilisan ng tao ang paglakad","Maghintay at hayaang matapos ng tao ang pagtawid","Lumihis paikot sa tao"],"h1":"Pinapayagan ka ng berdeng ilaw na umandar, pero isipin kung sino ang naunang nandoon.","h2":"Pinapayagan ka ng berdeng ilaw na umandar lang kapag maluwag na ang daan, kaya dapat mong hintayin ang mga tao at sasakyang nasa loob na ng interseksyon.","p":"Tama. Kahit berde, hayaan mo pa ring matapos tumawid ang mga tao."},"ar":{"q":"الإشارة خضراء ثابتة. شخص ما زال يعبر في ممر المشاة. ماذا يجب أن تفعل؟","o":["انطلق، لأن الأخضر يعطيك حق المرور","استخدم البوق لكي يسرع الشخص","انتظر ودع الشخص يكمل العبور","قُد حول الشخص"],"h1":"الضوء الأخضر يسمح لك بالانطلاق، لكن فكّر في من كان هناك أولًا.","h2":"الضوء الأخضر يسمح لك بالانطلاق فقط عندما يكون الطريق خاليًا، لذلك يجب أن تنتظر الأشخاص والسيارات الموجودين داخل التقاطع بالفعل.","p":"صحيح. عند الأخضر، ما زلت تترك الناس يكملون العبور."},"ht":{"q":"Limyè a vèt fiks. Gen yon moun ki toujou ap travèse nan pasaj pyeton an. Kisa ou dwe fè?","o":["Pase, paske limyè vèt la ba ou dwa pou pase","Klaksonen pou moun nan mache pi vit","Tann epi kite moun nan fini travèse","Pase bò kote moun nan"],"h1":"Yon limyè vèt kite ou pase, men panse ak kiyès ki te la anvan.","h2":"Yon limyè vèt kite ou pase sèlman lè wout la lib, kidonk ou dwe tann moun ak machin ki deja nan kafou a.","p":"Se sa. Sou limyè vèt, ou toujou kite moun yo fini travèse."},"ref":{"doc":"FL","page":51}},{"id":"signals-007","scope":"US","cat":"signals","sign":null,"c":3,"en":{"q":"You see a steady green arrow pointing left. What does it mean?","o":["You may not turn left","You must yield to all oncoming cars first","Only buses may turn left","You may turn left, and oncoming traffic should be stopped"],"h1":"A green arrow gives a special turn. Think about what the other traffic sees.","h2":"A steady green arrow means you may turn in the direction of the arrow, because oncoming traffic should be facing a red light.","p":"Right. A green arrow means you may make that turn."},"es":{"q":"Usted ve una flecha verde fija que apunta a la izquierda. ¿Qué significa?","o":["No puede girar a la izquierda","Debe ceder el paso primero a todos los carros de frente","Solo los autobuses pueden girar a la izquierda","Puede girar a la izquierda, y el tráfico de frente debe estar parado"],"h1":"Una flecha verde da un giro especial. Piense qué ve el otro tráfico.","h2":"Una flecha verde fija significa que usted puede girar en la dirección de la flecha, porque el tráfico de frente debe tener luz roja.","p":"Correcto. Una flecha verde significa que puede hacer ese giro."},"zh":{"q":"你看到一个一直亮着、指向左边的绿色箭头。它是什么意思？","o":["你不能左转","你必须先让所有对面来车","只有公交车可以左转","你可以左转，对面来车应该在停着"],"h1":"绿色箭头给你一个专门的转弯时间。想一想其他车看到的是什么。","h2":"一直亮着的绿色箭头表示你可以按箭头方向转弯，因为对面来车这时应该是红灯。","p":"对。绿色箭头表示你可以这样转弯。"},"vi":{"q":"Bạn thấy mũi tên xanh sáng đứng yên chỉ sang trái. Điều đó có nghĩa là gì?","o":["Bạn không được rẽ trái","Bạn phải nhường tất cả xe ngược chiều trước","Chỉ xe buýt được rẽ trái","Bạn được rẽ trái, và xe ngược chiều lẽ ra đang phải dừng"],"h1":"Mũi tên xanh cho phép một lượt rẽ riêng. Hãy nghĩ xem xe bên kia đang thấy đèn gì.","h2":"Mũi tên xanh sáng đứng yên nghĩa là bạn được rẽ theo hướng mũi tên, vì xe ngược chiều lẽ ra đang gặp đèn đỏ.","p":"Đúng rồi. Mũi tên xanh nghĩa là bạn được rẽ theo hướng đó."},"tl":{"q":"May nakita kang tuloy-tuloy na berdeng arrow na nakaturo pakaliwa. Ano ang ibig sabihin nito?","o":["Hindi ka puwedeng kumaliwa","Dapat mo munang paunahin ang lahat ng paparating na sasakyan","Mga bus lang ang puwedeng kumaliwa","Puwede kang kumaliwa, at dapat nakahinto ang paparating na trapiko"],"h1":"Ang berdeng arrow ay nagbibigay ng espesyal na pagliko. Isipin kung ano ang nakikita ng ibang trapiko.","h2":"Ang tuloy-tuloy na berdeng arrow ay nangangahulugang puwede kang lumiko sa direksyon ng arrow, dahil dapat nakaharap sa pulang ilaw ang paparating na trapiko.","p":"Tama. Ang berdeng arrow ay nangangahulugang puwede kang lumiko sa direksyong iyon."},"ar":{"q":"ترى سهمًا أخضر ثابتًا يشير إلى اليسار. ماذا يعني؟","o":["ممنوع أن تنعطف يسارًا","يجب أن تعطي الأولوية لكل السيارات القادمة أولًا","الحافلات فقط يمكنها أن تنعطف يسارًا","يمكنك أن تنعطف يسارًا، والسيارات القادمة يجب أن تكون متوقفة"],"h1":"السهم الأخضر يعطي انعطافًا خاصًا. فكّر في ما تراه السيارات الأخرى.","h2":"السهم الأخضر الثابت يعني أنه يمكنك أن تنعطف في اتجاه السهم، لأن السيارات القادمة يجب أن تكون أمام ضوء أحمر.","p":"صحيح. السهم الأخضر يعني أنه يمكنك أن تقوم بهذا الانعطاف."},"ht":{"q":"Ou wè yon flèch vèt fiks ki montre agoch. Kisa li vle di?","o":["Ou pa ka vire agoch","Ou dwe kite tout machin k ap vin sou ou pase anvan","Se sèlman bis ki ka vire agoch","Ou ka vire agoch, epi machin k ap vin sou ou yo ta dwe kanpe"],"h1":"Yon flèch vèt bay yon vire espesyal. Panse ak sa lòt machin yo wè.","h2":"Yon flèch vèt fiks vle di ou ka vire nan direksyon flèch la, paske machin k ap vin sou ou yo ta dwe gen yon limyè wouj devan yo.","p":"Se sa. Yon flèch vèt vle di ou ka fè vire sa a."},"ref":{"doc":"FL","page":52}},{"id":"signals-008","scope":"US","cat":"signals","sign":null,"c":1,"en":{"q":"What does a flashing yellow arrow pointing left mean?","o":["You may turn left, and oncoming traffic is stopped","You may turn left, but you must yield to oncoming traffic and people walking","You must stop and wait for a green arrow","Left turns are not allowed here"],"h1":"Flashing yellow is a warning. Think about whether oncoming cars can still come.","h2":"A flashing yellow arrow means you may turn left, but you must first yield to oncoming traffic and to people walking, because they may still have a green light.","p":"Right. A flashing yellow arrow means turn only after you yield."},"es":{"q":"¿Qué significa una flecha amarilla intermitente que apunta a la izquierda?","o":["Puede girar a la izquierda, y el tráfico de frente está parado","Puede girar a la izquierda, pero debe ceder el paso al tráfico de frente y a los peatones","Debe parar y esperar una flecha verde","No se permite girar a la izquierda aquí"],"h1":"El amarillo intermitente es una advertencia. Piense si los carros de frente todavía pueden venir.","h2":"Una flecha amarilla intermitente significa que usted puede girar a la izquierda, pero primero debe ceder el paso al tráfico de frente y a los peatones, porque ellos pueden tener luz verde.","p":"Correcto. Flecha amarilla intermitente significa gire solo después de ceder el paso."},"zh":{"q":"闪烁的黄色左转箭头是什么意思？","o":["你可以左转，对面来车已经停了","你可以左转，但必须让对面来车和行人先走","你必须停车，等绿色箭头","这里不准左转"],"h1":"闪烁的黄色是警告。想一想对面的车是不是还可能开过来。","h2":"闪烁的黄色箭头表示你可以左转，但必须先让对面来车和行人先走，因为他们可能还是绿灯。","p":"对。闪烁的黄色箭头表示先让行，再转弯。"},"vi":{"q":"Mũi tên vàng nhấp nháy chỉ sang trái có nghĩa là gì?","o":["Bạn được rẽ trái, và xe ngược chiều đang dừng","Bạn được rẽ trái, nhưng phải nhường xe ngược chiều và người đi bộ","Bạn phải dừng và chờ mũi tên xanh","Ở đây cấm rẽ trái"],"h1":"Màu vàng nhấp nháy là lời cảnh báo. Hãy nghĩ xem xe ngược chiều có còn chạy tới không.","h2":"Mũi tên vàng nhấp nháy nghĩa là bạn được rẽ trái, nhưng trước hết phải nhường xe ngược chiều và người đi bộ, vì họ có thể vẫn đang có đèn xanh.","p":"Đúng rồi. Mũi tên vàng nhấp nháy nghĩa là chỉ rẽ sau khi đã nhường đường."},"tl":{"q":"Ano ang ibig sabihin ng kumikislap na dilaw na arrow na nakaturo pakaliwa?","o":["Puwede kang kumaliwa, at nakahinto ang paparating na trapiko","Puwede kang kumaliwa, pero dapat mong paunahin ang paparating na trapiko at ang mga taong naglalakad","Dapat kang huminto at maghintay ng berdeng arrow","Bawal kumaliwa dito"],"h1":"Ang kumikislap na dilaw ay babala. Isipin kung puwede pa ring dumating ang mga paparating na sasakyan.","h2":"Ang kumikislap na dilaw na arrow ay nangangahulugang puwede kang kumaliwa, pero dapat mo munang paunahin ang paparating na trapiko at ang mga taong naglalakad, dahil maaaring berde pa rin ang ilaw nila.","p":"Tama. Ang kumikislap na dilaw na arrow ay nangangahulugang lumiko lang pagkatapos mong magbigay-daan."},"ar":{"q":"ماذا يعني سهم أصفر وامض يشير إلى اليسار؟","o":["يمكنك أن تنعطف يسارًا، والسيارات القادمة متوقفة","يمكنك أن تنعطف يسارًا، لكن يجب أن تعطي الأولوية للسيارات القادمة وللمشاة","يجب أن تتوقف وتنتظر سهمًا أخضر","الانعطاف يسارًا ممنوع هنا"],"h1":"الأصفر الوامض تحذير. فكّر: هل ما زالت السيارات القادمة يمكن أن تأتي؟","h2":"السهم الأصفر الوامض يعني أنه يمكنك أن تنعطف يسارًا، لكن يجب أولًا أن تعطي الأولوية للسيارات القادمة وللمشاة، لأن الإشارة قد تكون ما زالت خضراء لهم.","p":"صحيح. السهم الأصفر الوامض يعني: انعطف فقط بعد أن تعطي الأولوية."},"ht":{"q":"Kisa yon flèch jòn k ap kliyote ki montre agoch vle di?","o":["Ou ka vire agoch, epi machin k ap vin sou ou yo kanpe","Ou ka vire agoch, men ou dwe kite machin k ap vin sou ou ak moun k ap mache pase anvan","Ou dwe kanpe epi tann yon flèch vèt","Ou pa gen dwa vire agoch la a"],"h1":"Jòn k ap kliyote se yon avètisman. Panse si machin k ap vin sou ou yo ka toujou vini.","h2":"Yon flèch jòn k ap kliyote vle di ou ka vire agoch, men ou dwe kite machin k ap vin sou ou ak moun k ap mache pase anvan, paske yo ka toujou gen yon limyè vèt.","p":"Se sa. Yon flèch jòn k ap kliyote vle di vire sèlman apre ou fin bay pasaj."},"ref":{"doc":"FL","page":52}},{"id":"signals-009","scope":"US","cat":"signals","sign":null,"c":0,"en":{"q":"What does a steady yellow arrow mean?","o":["The protected turn is ending, so stop if you can do it safely","You may now turn without looking","Wait for the cars behind you","The turn lane is closed for the day"],"h1":"A steady yellow arrow works like a steady yellow light, but for a turn.","h2":"A steady yellow arrow means the arrow will soon turn red, so you should stop if you can do it safely.","p":"Right. A steady yellow arrow means the turn time is ending."},"es":{"q":"¿Qué significa una flecha amarilla fija?","o":["El giro protegido está terminando, así que pare si lo puede hacer con seguridad","Ahora puede girar sin mirar","Espere a los carros que vienen detrás","El carril de giro está cerrado todo el día"],"h1":"Una flecha amarilla fija funciona como una luz amarilla fija, pero para un giro.","h2":"Una flecha amarilla fija significa que la flecha pronto cambiará a roja, así que usted debe parar si lo puede hacer con seguridad.","p":"Correcto. Una flecha amarilla fija significa que el tiempo del giro se acaba."},"zh":{"q":"一直亮着的黄色箭头是什么意思？","o":["专用转弯时间要结束了，能安全停下就停车","你现在可以不看就转弯","等你后面的车","转弯车道今天关闭"],"h1":"一直亮着的黄色箭头和一直亮着的黄灯一样，只是用于转弯。","h2":"一直亮着的黄色箭头表示箭头马上要变红，所以如果能安全停下，你就应该停车。","p":"对。一直亮着的黄色箭头表示转弯时间要结束了。"},"vi":{"q":"Mũi tên vàng sáng đứng yên có nghĩa là gì?","o":["Lượt rẽ được bảo vệ sắp hết, nên hãy dừng nếu bạn có thể dừng an toàn","Bây giờ bạn được rẽ mà không cần nhìn","Chờ các xe phía sau bạn","Làn rẽ bị đóng cả ngày"],"h1":"Mũi tên vàng sáng đứng yên giống như đèn vàng sáng đứng yên, nhưng dành cho lượt rẽ.","h2":"Mũi tên vàng sáng đứng yên nghĩa là mũi tên sắp chuyển sang đỏ, nên bạn cần dừng lại nếu có thể dừng an toàn.","p":"Đúng rồi. Mũi tên vàng sáng đứng yên nghĩa là thời gian rẽ sắp hết."},"tl":{"q":"Ano ang ibig sabihin ng tuloy-tuloy na dilaw na arrow?","o":["Matatapos na ang protektadong pagliko, kaya huminto kung kaya mong gawin ito nang ligtas","Puwede ka nang lumiko nang hindi tumitingin","Hintayin ang mga sasakyan sa likod mo","Sarado ang turn lane sa buong araw"],"h1":"Ang tuloy-tuloy na dilaw na arrow ay gumagana na parang tuloy-tuloy na dilaw na ilaw, pero para sa pagliko.","h2":"Ang tuloy-tuloy na dilaw na arrow ay nangangahulugang malapit nang maging pula ang arrow, kaya dapat kang huminto kung kaya mong gawin ito nang ligtas.","p":"Tama. Ang tuloy-tuloy na dilaw na arrow ay nangangahulugang matatapos na ang oras ng pagliko."},"ar":{"q":"ماذا يعني السهم الأصفر الثابت؟","o":["وقت الانعطاف المحمي ينتهي، لذلك توقف إذا استطعت أن تفعل ذلك بأمان","الآن يمكنك أن تنعطف بدون أن تنظر","انتظر السيارات التي خلفك","مسار الانعطاف مغلق لبقية اليوم"],"h1":"السهم الأصفر الثابت يعمل مثل الضوء الأصفر الثابت، لكن للانعطاف.","h2":"السهم الأصفر الثابت يعني أن السهم سيصبح أحمر قريبًا، لذلك يجب أن تتوقف إذا استطعت أن تفعل ذلك بأمان.","p":"صحيح. السهم الأصفر الثابت يعني أن وقت الانعطاف ينتهي."},"ht":{"q":"Kisa yon flèch jòn fiks vle di?","o":["Tan pou vire ki pwoteje a ap fini, kidonk kanpe si ou ka fè l an sekirite","Kounye a ou ka vire san ou pa gade","Tann machin ki dèyè ou yo","Koulwa pou vire a fèmen pou jounen an"],"h1":"Yon flèch jòn fiks mache tankou yon limyè jòn fiks, men pou yon vire.","h2":"Yon flèch jòn fiks vle di flèch la pral vin wouj talè, kidonk ou dwe kanpe si ou ka fè l an sekirite.","p":"Se sa. Yon flèch jòn fiks vle di tan pou vire a ap fini."},"ref":{"doc":"FL","page":52}},{"id":"signals-010","scope":"FL","cat":"signals","sign":null,"c":2,"en":{"q":"In Florida, you are on a two-way street. A steady red arrow points left. What must you do?","o":["Turn left after a full stop if no one is coming","Turn left slowly without stopping","Stop and do not turn left until the signal allows it","Use the next lane to turn left instead"],"h1":"Think about what a red signal means, even when it is shaped like an arrow.","h2":"In Florida, on a two-way street, a steady red arrow pointing left means you must stop and must not turn left until a green arrow or green light lets you.","p":"Right. A red left arrow means no left turn yet."},"es":{"q":"En Florida, usted está en una calle de doble sentido. Una flecha roja fija apunta a la izquierda. ¿Qué debe hacer?","o":["Girar a la izquierda después de parar por completo si no viene nadie","Girar a la izquierda despacio sin parar","Parar y no girar a la izquierda hasta que la señal lo permita","Usar el otro carril para girar a la izquierda"],"h1":"Piense qué significa una señal roja, aunque tenga forma de flecha.","h2":"En Florida, en una calle de doble sentido, una flecha roja fija que apunta a la izquierda significa que usted debe parar y no puede girar a la izquierda hasta que una flecha verde o luz verde se lo permita.","p":"Correcto. Una flecha roja a la izquierda significa que todavía no puede girar."},"zh":{"q":"在 Florida，你在一条双向街道上。一个一直亮着的红色箭头指向左边。你必须怎么做？","o":["完全停车后，没车就左转","不停车，慢慢左转","停车，在信号允许前不要左转","改用旁边的车道左转"],"h1":"想一想红色信号的意思，就算它是箭头的形状。","h2":"在 Florida 的双向街道上，指向左边、一直亮着的红色箭头表示你必须停车，在绿色箭头或绿灯允许之前不能左转。","p":"对。红色左转箭头表示现在还不能左转。"},"vi":{"q":"Ở Florida, bạn đang ở trên đường hai chiều. Một mũi tên đỏ sáng đứng yên chỉ sang trái. Bạn phải làm gì?","o":["Rẽ trái sau khi dừng hẳn nếu không có ai tới","Rẽ trái chậm mà không cần dừng","Dừng lại và không rẽ trái cho tới khi đèn cho phép","Dùng làn bên cạnh để rẽ trái"],"h1":"Hãy nghĩ xem tín hiệu màu đỏ có nghĩa là gì, ngay cả khi nó có hình mũi tên.","h2":"Ở Florida, trên đường hai chiều, mũi tên đỏ sáng đứng yên chỉ sang trái nghĩa là bạn phải dừng lại và không được rẽ trái cho tới khi có mũi tên xanh hoặc đèn xanh cho phép.","p":"Đúng rồi. Mũi tên đỏ chỉ trái nghĩa là chưa được rẽ trái."},"tl":{"q":"Sa Florida, nasa kalyeng dalawa ang direksyon ka. May tuloy-tuloy na pulang arrow na nakaturo pakaliwa. Ano ang dapat mong gawin?","o":["Kumaliwa pagkatapos huminto nang buo kung walang dumarating","Kumaliwa nang dahan-dahan nang hindi humihinto","Huminto at huwag kumaliwa hanggang payagan ka ng ilaw","Gamitin ang katabing linya para kumaliwa"],"h1":"Isipin kung ano ang ibig sabihin ng pulang ilaw, kahit hugis arrow pa ito.","h2":"Sa Florida, sa kalyeng dalawa ang direksyon, ang tuloy-tuloy na pulang arrow na nakaturo pakaliwa ay nangangahulugang dapat kang huminto at hindi ka puwedeng kumaliwa hanggang payagan ka ng berdeng arrow o berdeng ilaw.","p":"Tama. Ang pulang arrow pakaliwa ay nangangahulugang hindi pa puwedeng kumaliwa."},"ar":{"q":"في Florida، أنت في شارع باتجاهين. سهم أحمر ثابت يشير إلى اليسار. ماذا يجب أن تفعل؟","o":["انعطف يسارًا بعد توقف تام إذا لم يأتِ أحد","انعطف يسارًا ببطء بدون أن تتوقف","توقف ولا تنعطف يسارًا حتى تسمح لك الإشارة","استخدم المسار المجاور لتنعطف يسارًا بدلًا من ذلك"],"h1":"فكّر في معنى الإشارة الحمراء، حتى لو كانت على شكل سهم.","h2":"في Florida، في شارع باتجاهين، السهم الأحمر الثابت إلى اليسار يعني أنه يجب أن تتوقف ولا تنعطف يسارًا حتى يسمح لك سهم أخضر أو ضوء أخضر.","p":"صحيح. السهم الأحمر إلى اليسار يعني: لا تنعطف يسارًا بعد."},"ht":{"q":"Nan Florida, ou sou yon lari ki gen de direksyon. Yon flèch wouj fiks montre agoch. Kisa ou dwe fè?","o":["Vire agoch apre ou fin kanpe nèt si pa gen moun k ap vini","Vire agoch dousman san ou pa kanpe","Kanpe epi pa vire agoch jiskaske siyal la pèmèt ou","Sèvi ak lòt koulwa a pou vire agoch pito"],"h1":"Panse ak sa yon siyal wouj vle di, menm lè li gen fòm yon flèch.","h2":"Nan Florida, sou yon lari ki gen de direksyon, yon flèch wouj fiks ki montre agoch vle di ou dwe kanpe epi ou pa dwe vire agoch jiskaske yon flèch vèt oswa yon limyè vèt kite ou pase.","p":"Se sa. Yon flèch wouj agoch vle di ou pa ka vire agoch ankò."},"ref":{"doc":"FL","page":52}},{"id":"signals-011","scope":"FL","cat":"signals","sign":null,"c":1,"en":{"q":"In Florida, may you turn right on a steady red light?","o":["Yes, without stopping, if no one is coming","Yes, after a full stop, if no sign forbids it and the way is clear","No, never","Only between midnight and 6 a.m."],"h1":"Think about two things: a full stop, and any sign at the corner.","h2":"In Florida, you may turn right on a red light after you stop fully and yield, unless a sign says no turn on red.","p":"Right. Stop fully, yield, and then you may turn right on red unless a sign forbids it."},"es":{"q":"En Florida, ¿puede girar a la derecha con luz roja fija?","o":["Sí, sin parar, si no viene nadie","Sí, después de parar por completo, si ninguna señal lo prohíbe y el camino está libre","No, nunca","Solo entre la medianoche y las 6 a.m."],"h1":"Piense en dos cosas: parar por completo y cualquier señal en la esquina.","h2":"En Florida, usted puede girar a la derecha con luz roja después de parar por completo y ceder el paso, a menos que una señal prohíba girar con luz roja.","p":"Correcto. Pare por completo, ceda el paso, y luego puede girar a la derecha con roja si ninguna señal lo prohíbe."},"zh":{"q":"在 Florida，一直亮着红灯时，你可以右转吗？","o":["可以，没有来车就不用停","可以，完全停车后，没有标志禁止，而且路上没车","不可以，永远不行","只在午夜到早上 6 点之间可以"],"h1":"想两件事：完全停车，和路口有没有标志。","h2":"在 Florida，你完全停车并让行后，可以在红灯时右转，除非有标志写着红灯禁止转弯。","p":"对。完全停车，让行，然后可以红灯右转，除非有标志禁止。"},"vi":{"q":"Ở Florida, bạn có được rẽ phải khi đèn đỏ sáng đứng yên không?","o":["Có, không cần dừng, nếu không có ai tới","Có, sau khi dừng hẳn, nếu không có biển cấm và đường đã trống","Không, không bao giờ","Chỉ từ nửa đêm tới 6 giờ sáng"],"h1":"Hãy nghĩ đến hai điều: dừng hẳn, và biển báo ở góc đường.","h2":"Ở Florida, bạn được rẽ phải khi đèn đỏ sau khi đã dừng hẳn và nhường đường, trừ khi có biển “NO TURN ON RED” (Cấm rẽ khi đèn đỏ).","p":"Đúng rồi. Dừng hẳn, nhường đường, rồi bạn được rẽ phải khi đèn đỏ, trừ khi có biển cấm."},"tl":{"q":"Sa Florida, puwede ka bang kumanan kapag tuloy-tuloy na pula ang ilaw?","o":["Oo, nang hindi humihinto, kung walang dumarating","Oo, pagkatapos huminto nang buo, kung walang karatulang nagbabawal at maluwag ang daan","Hindi, kailanman","Mula hatinggabi hanggang 6 a.m. lang"],"h1":"Isipin ang dalawang bagay: ang paghinto nang buo, at kung may karatula sa kanto.","h2":"Sa Florida, puwede kang kumanan kapag pula ang ilaw pagkatapos mong huminto nang buo at magbigay-daan, maliban kung may karatulang “NO TURN ON RED”.","p":"Tama. Huminto nang buo, magbigay-daan, at saka puwede kang kumanan sa pula maliban kung may karatulang nagbabawal."},"ar":{"q":"في Florida، هل يمكنك أن تنعطف يمينًا عند ضوء أحمر ثابت؟","o":["نعم، بدون توقف، إذا لم يأتِ أحد","نعم، بعد توقف تام، إذا لم تمنع ذلك لافتة وكان الطريق خاليًا","لا، أبدًا","فقط بين منتصف الليل والساعة 6 صباحًا"],"h1":"فكّر في أمرين: التوقف التام، وأي لافتة عند الزاوية.","h2":"في Florida، يمكنك أن تنعطف يمينًا عند الضوء الأحمر بعد أن تتوقف تمامًا وتعطي الأولوية، إلا إذا كانت هناك لافتة تقول «NO TURN ON RED» (ممنوع الانعطاف عند الأحمر).","p":"صحيح. توقف تمامًا، وأعطِ الأولوية، ثم يمكنك أن تنعطف يمينًا عند الأحمر إلا إذا منعت ذلك لافتة."},"ht":{"q":"Nan Florida, èske ou ka vire adwat sou yon limyè wouj fiks?","o":["Wi, san ou pa kanpe, si pa gen moun k ap vini","Wi, apre ou fin kanpe nèt, si pa gen siy ki entèdi sa epi wout la lib","Non, janm","Sèlman ant minwi ak 6 è dimaten"],"h1":"Panse ak de bagay: kanpe nèt, ak nenpòt siy ki nan kwen an.","h2":"Nan Florida, ou ka vire adwat sou limyè wouj apre ou fin kanpe nèt epi bay pasaj, sof si yon siy di “NO TURN ON RED”.","p":"Se sa. Kanpe nèt, bay pasaj, epi ou ka vire adwat sou wouj sof si yon siy entèdi sa."},"ref":{"doc":"FL","page":51}},{"id":"signals-012","scope":"FL","cat":"signals","sign":null,"c":3,"en":{"q":"In Florida, when may you turn left on a red light?","o":["From any street, if no one is coming","Never, under any condition","Only when you are in a hurry","From a one-way street onto another one-way street going left, after a full stop"],"h1":"Think about which streets have no oncoming traffic.","h2":"In Florida, you may turn left on red only from a one-way street onto a one-way street that goes left, and only after a full stop when the way is clear and no sign forbids it.","p":"Right. Left on red is only from one-way to one-way, after a full stop."},"es":{"q":"En Florida, ¿cuándo puede girar a la izquierda con luz roja?","o":["Desde cualquier calle, si no viene nadie","Nunca, en ningún caso","Solo cuando tiene prisa","De una calle de un solo sentido a otra calle de un solo sentido que va a la izquierda, después de parar por completo"],"h1":"Piense en qué calles no tienen tráfico de frente.","h2":"En Florida, usted puede girar a la izquierda con luz roja solo de una calle de un solo sentido a otra de un solo sentido que va a la izquierda, y solo después de parar por completo, con el camino libre y sin una señal que lo prohíba.","p":"Correcto. Izquierda con roja solo de un solo sentido a un solo sentido, después de parar."},"zh":{"q":"在 Florida，什么时候可以在红灯时左转？","o":["从任何街道都行，只要没有来车","不行，什么情况都不行","只在你赶时间的时候","从单行道左转进入另一条往左走的单行道，并且要先完全停车"],"h1":"想一想：哪些街道没有对面来车。","h2":"在 Florida，只有从单行道左转进入往左走的单行道时，才可以在红灯时左转，而且要先完全停车，路上没车，也没有标志禁止。","p":"对。红灯左转只能从单行道到单行道，并且要先完全停车。"},"vi":{"q":"Ở Florida, khi nào bạn được rẽ trái lúc đèn đỏ?","o":["Từ bất cứ đường nào, nếu không có ai tới","Không bao giờ, trong bất cứ trường hợp nào","Chỉ khi bạn đang vội","Từ đường một chiều rẽ trái vào một đường một chiều khác, sau khi dừng hẳn"],"h1":"Hãy nghĩ xem đường nào không có xe chạy ngược chiều.","h2":"Ở Florida, bạn chỉ được rẽ trái khi đèn đỏ từ đường một chiều vào một đường một chiều chạy về phía trái, và chỉ sau khi dừng hẳn, khi đường đã trống và không có biển cấm.","p":"Đúng rồi. Rẽ trái khi đèn đỏ chỉ được từ đường một chiều sang đường một chiều, sau khi dừng hẳn."},"tl":{"q":"Sa Florida, kailan ka puwedeng kumaliwa kapag pula ang ilaw?","o":["Mula sa kahit anong kalye, kung walang dumarating","Hindi kailanman, sa anumang sitwasyon","Kapag nagmamadali ka lang","Mula sa one-way na kalye papunta sa isa pang one-way na kalye na papunta sa kaliwa, pagkatapos huminto nang buo"],"h1":"Isipin kung aling mga kalye ang walang paparating na trapiko.","h2":"Sa Florida, puwede kang kumaliwa sa pula mula lang sa one-way na kalye papunta sa one-way na kalye na papunta sa kaliwa, at pagkatapos lang huminto nang buo kapag maluwag ang daan at walang karatulang nagbabawal.","p":"Tama. Ang pagkaliwa sa pula ay mula lang sa one-way papunta sa one-way, pagkatapos huminto nang buo."},"ar":{"q":"في Florida، متى يمكنك أن تنعطف يسارًا عند ضوء أحمر؟","o":["من أي شارع، إذا لم يأتِ أحد","أبدًا، في أي حال","فقط عندما تكون مستعجلًا","من شارع باتجاه واحد إلى شارع آخر باتجاه واحد يسير نحو اليسار، بعد توقف تام"],"h1":"فكّر في الشوارع التي لا تأتي فيها سيارات من الاتجاه المقابل.","h2":"في Florida، يمكنك أن تنعطف يسارًا عند الأحمر فقط من شارع باتجاه واحد إلى شارع باتجاه واحد يسير نحو اليسار، وفقط بعد توقف تام عندما يكون الطريق خاليًا ولا تمنع ذلك لافتة.","p":"صحيح. الانعطاف يسارًا عند الأحمر مسموح فقط من اتجاه واحد إلى اتجاه واحد، بعد توقف تام."},"ht":{"q":"Nan Florida, ki lè ou ka vire agoch sou yon limyè wouj?","o":["Sou nenpòt lari, si pa gen moun k ap vini","Janm, nan okenn kondisyon","Sèlman lè ou prese","Soti sou yon lari yon sèl direksyon pou antre sou yon lòt lari yon sèl direksyon ki ale agoch, apre ou fin kanpe nèt"],"h1":"Panse ak ki lari ki pa gen machin k ap vin sou ou.","h2":"Nan Florida, ou ka vire agoch sou wouj sèlman soti sou yon lari yon sèl direksyon pou antre sou yon lari yon sèl direksyon ki ale agoch, epi sèlman apre ou fin kanpe nèt lè wout la lib epi pa gen siy ki entèdi sa.","p":"Se sa. Vire agoch sou wouj se sèlman soti sou yon sèl direksyon pou antre sou yon sèl direksyon, apre ou fin kanpe nèt."},"ref":{"doc":"FL","page":51}},{"id":"signals-013","scope":"FL","cat":"signals","sign":null,"c":0,"en":{"q":"In Florida, the traffic lights at an intersection are dark because the power is out. What should you do?","o":["Treat it as an all-way stop","Go through without stopping","Honk and go first","Treat it as a yield for you only"],"h1":"With no signal working, think about which sign makes every driver take turns.","h2":"In Florida, when traffic lights are not working, you treat the intersection as an all-way stop, so every driver stops and then goes in turn.","p":"Right. A dark signal means an all-way stop."},"es":{"q":"En Florida, los semáforos de una intersección están apagados porque no hay electricidad. ¿Qué debe hacer?","o":["Tratarla como una parada en todas las direcciones","Pasar sin parar","Tocar la bocina y pasar primero","Tratarla como un ceda el paso solo para usted"],"h1":"Si ninguna señal funciona, piense qué señal hace que todos los conductores tomen turnos.","h2":"En Florida, cuando los semáforos no funcionan, usted trata la intersección como una parada en todas las direcciones, así que cada conductor para y luego sigue por turno.","p":"Correcto. Un semáforo apagado significa parada en todas las direcciones."},"zh":{"q":"在 Florida，因为停电，路口的红绿灯不亮了。你应该怎么做？","o":["把它当作全向停车路口","不停车直接开过去","按喇叭，自己先走","当作只有你要让行"],"h1":"信号灯坏了时，想一想哪种标志让每个司机轮流走。","h2":"在 Florida，红绿灯不工作时，你要把路口当作全向停车路口，所以每个司机都先停车，然后轮流走。","p":"对。信号灯不亮表示全向停车。"},"vi":{"q":"Ở Florida, đèn giao thông ở một giao lộ bị tắt vì mất điện. Bạn nên làm gì?","o":["Xem đó là giao lộ mọi hướng đều phải dừng","Chạy qua mà không dừng","Bấm còi và đi trước","Xem như chỉ mình bạn phải nhường đường"],"h1":"Khi đèn không hoạt động, hãy nghĩ xem biển nào khiến mọi tài xế phải đi lần lượt.","h2":"Ở Florida, khi đèn giao thông không hoạt động, bạn xem giao lộ đó là nơi mọi hướng đều phải dừng, nên mọi tài xế đều dừng rồi đi lần lượt.","p":"Đúng rồi. Đèn tắt nghĩa là mọi hướng đều phải dừng."},"tl":{"q":"Sa Florida, patay ang mga ilaw trapiko sa isang interseksyon dahil walang kuryente. Ano ang dapat mong gawin?","o":["Ituring itong all-way stop (lahat ay hihinto)","Dumaan nang hindi humihinto","Bumusina at mauna","Ituring itong yield para sa iyo lang"],"h1":"Kapag walang gumaganang ilaw, isipin kung aling karatula ang nagpapasalitan sa lahat ng driver.","h2":"Sa Florida, kapag hindi gumagana ang mga ilaw trapiko, ituring mo ang interseksyon bilang all-way stop, kaya bawat driver ay hihinto at saka aandar nang salitan.","p":"Tama. Ang patay na ilaw trapiko ay nangangahulugang all-way stop."},"ar":{"q":"في Florida، إشارات المرور في تقاطع مطفأة لأن الكهرباء مقطوعة. ماذا يجب أن تفعل؟","o":["تعامل معه كتقاطع يتوقف فيه الجميع","اعبر بدون توقف","استخدم البوق وانطلق أولًا","تعامل معه كإعطاء أولوية لك وحدك"],"h1":"عندما لا تعمل الإشارة، فكّر في اللافتة التي تجعل كل سائق ينتظر دوره.","h2":"في Florida، عندما لا تعمل إشارات المرور، تتعامل مع التقاطع كتقاطع يتوقف فيه الجميع، لذلك كل سائق يتوقف ثم ينطلق حسب دوره.","p":"صحيح. الإشارة المطفأة تعني أن الجميع يتوقفون."},"ht":{"q":"Nan Florida, limyè trafik yo nan yon kafou etenn paske kouran an koupe. Kisa ou dwe fè?","o":["Fè l tankou yon kafou kote tout moun kanpe","Travèse san ou pa kanpe","Klaksonen epi pase anvan","Fè l tankou yon siy “YIELD” pou ou sèlman"],"h1":"Lè pa gen siyal k ap mache, panse ak ki siy ki fè chak chofè pase youn apre lòt.","h2":"Nan Florida, lè limyè trafik yo pa mache, ou fè kafou a tankou yon kafou kote tout moun kanpe, kidonk chak chofè kanpe epi pase youn apre lòt.","p":"Se sa. Yon limyè ki etenn vle di tout moun kanpe."},"ref":{"doc":"FL","page":51}},{"id":"signals-014","scope":"FL","cat":"signals","sign":null,"c":2,"en":{"q":"In Florida, your light is green, but the traffic ahead is backed up into the intersection. What should you do?","o":["Go in anyway, because the light is green","Drive into the intersection and wait there","Wait before the intersection until there is room on the other side","Drive on the shoulder around the line"],"h1":"Think about what happens to cross traffic if your car is stuck in the middle.","h2":"In Florida, you must not enter an intersection unless there is room for your car on the other side, even on green, because a stuck car blocks cross traffic.","p":"Right. Do not enter unless you can get all the way through."},"es":{"q":"En Florida, su luz está en verde, pero el tráfico de adelante está detenido hasta la intersección. ¿Qué debe hacer?","o":["Entrar de todos modos, porque la luz está en verde","Entrar a la intersección y esperar ahí","Esperar antes de la intersección hasta que haya espacio del otro lado","Manejar por el paseo para pasar la fila"],"h1":"Piense qué le pasa al tráfico que cruza si su carro queda atrapado en el medio.","h2":"En Florida, usted no debe entrar a una intersección si no hay espacio para su carro del otro lado, aunque tenga verde, porque un carro atrapado bloquea el tráfico que cruza.","p":"Correcto. No entre si no puede pasar por completo."},"zh":{"q":"在 Florida，你这边是绿灯，但前面的车已经堵到路口里了。你应该怎么做？","o":["照样开进去，因为是绿灯","开进路口，在里面等","在路口前等，等到路口另一边有空位","从路肩绕过排队的车"],"h1":"想一想：如果你的车卡在路口中间，横向的车会怎样。","h2":"在 Florida，就算是绿灯，路口另一边没有空位放你的车时，你也不能开进路口，因为卡住的车会挡住横向交通。","p":"对。除非能完全开过去，否则不要进入路口。"},"vi":{"q":"Ở Florida, đèn của bạn đang xanh, nhưng xe phía trước bị kẹt dồn vào tới giao lộ. Bạn nên làm gì?","o":["Cứ chạy vào, vì đèn đang xanh","Chạy vào giao lộ và chờ ở đó","Chờ trước giao lộ tới khi phía bên kia có chỗ trống","Chạy trên lề đường để vượt qua hàng xe"],"h1":"Hãy nghĩ xem xe ở hướng cắt ngang sẽ ra sao nếu xe bạn bị kẹt ở giữa.","h2":"Ở Florida, bạn không được chạy vào giao lộ nếu phía bên kia không có chỗ cho xe bạn, kể cả khi đèn xanh, vì xe bị kẹt sẽ chắn đường xe cắt ngang.","p":"Đúng rồi. Đừng chạy vào nếu bạn không thể qua hết giao lộ."},"tl":{"q":"Sa Florida, berde ang ilaw mo, pero ang trapiko sa unahan ay umaabot na hanggang sa interseksyon. Ano ang dapat mong gawin?","o":["Pumasok pa rin, dahil berde ang ilaw","Pumasok sa interseksyon at maghintay doon","Maghintay bago ang interseksyon hanggang may puwang sa kabilang bahagi","Magmaneho sa gilid ng kalsada para lampasan ang pila"],"h1":"Isipin kung ano ang mangyayari sa trapiko sa kabilang daan kapag naipit ang sasakyan mo sa gitna.","h2":"Sa Florida, hindi ka dapat pumasok sa interseksyon maliban kung may puwang para sa sasakyan mo sa kabilang bahagi, kahit berde, dahil ang naipit na sasakyan ay humaharang sa trapiko sa kabilang daan.","p":"Tama. Huwag pumasok maliban kung kaya mong makatawid nang buo."},"ar":{"q":"في Florida، إشارتك خضراء، لكن السيارات أمامك متكدسة حتى داخل التقاطع. ماذا يجب أن تفعل؟","o":["ادخل على أي حال، لأن الإشارة خضراء","ادخل إلى التقاطع وانتظر هناك","انتظر قبل التقاطع حتى يكون هناك مكان في الجهة الأخرى","قُد على كتف الطريق حول الطابور"],"h1":"فكّر في ما يحدث للسيارات المتقاطعة إذا علقت سيارتك في الوسط.","h2":"في Florida، يجب ألا تدخل التقاطع إلا إذا كان هناك مكان لسيارتك في الجهة الأخرى، حتى عند الأخضر، لأن السيارة العالقة تغلق الطريق أمام السيارات المتقاطعة.","p":"صحيح. لا تدخل إلا إذا كنت تستطيع أن تعبر إلى الجهة الأخرى بالكامل."},"ht":{"q":"Nan Florida, limyè ou a vèt, men machin devan yo bloke jous nan kafou a. Kisa ou dwe fè?","o":["Antre kanmèm, paske limyè a vèt","Antre nan kafou a epi tann la","Tann anvan kafou a jiskaske gen plas lòt bò a","Kondui sou arebò wout la pou pase bò kote liy machin yo"],"h1":"Panse ak sa k ap rive machin sou lòt lari a si machin ou bloke nan mitan an.","h2":"Nan Florida, ou pa dwe antre nan yon kafou sof si gen plas pou machin ou lòt bò a, menm lè limyè a vèt, paske yon machin ki bloke anpeche lòt machin yo pase.","p":"Se sa. Pa antre sof si ou ka travèse nèt."},"ref":{"doc":"FL","page":51}},{"id":"signals-015","scope":"US","cat":"signals","sign":null,"c":1,"en":{"q":"A pedestrian signal shows a walking person. What does it mean for people on foot?","o":["They must not start crossing","They may start crossing the street","Only bicycles may cross","Cars may turn without looking"],"h1":"The walking person is a picture of what people may do.","h2":"A walking person signal means people on foot may start crossing, so drivers who turn must yield to them.","p":"Right. The walking person means people may cross."},"es":{"q":"Una señal para peatones muestra una persona caminando. ¿Qué significa para las personas a pie?","o":["No deben empezar a cruzar","Pueden empezar a cruzar la calle","Solo las bicicletas pueden cruzar","Los carros pueden girar sin mirar"],"h1":"La persona caminando es un dibujo de lo que la gente puede hacer.","h2":"La señal de la persona caminando significa que las personas a pie pueden empezar a cruzar, así que los conductores que giran deben cederles el paso.","p":"Correcto. La persona caminando significa que pueden cruzar."},"zh":{"q":"行人信号灯显示一个走路的人。这对行人是什么意思？","o":["他们不能开始过马路","他们可以开始过马路","只有自行车可以过","汽车可以不看就转弯"],"h1":"走路的人这个图，就是行人可以做的事。","h2":"走路的人的信号表示行人可以开始过马路，所以转弯的司机必须让他们先走。","p":"对。走路的人表示行人可以过马路。"},"vi":{"q":"Đèn cho người đi bộ hiện hình một người đang đi. Điều đó có nghĩa là gì với người đi bộ?","o":["Họ không được bắt đầu băng qua","Họ được bắt đầu băng qua đường","Chỉ xe đạp được băng qua","Xe được rẽ mà không cần nhìn"],"h1":"Hình người đang đi cho thấy điều người đi bộ được làm.","h2":"Đèn có hình người đang đi nghĩa là người đi bộ được bắt đầu băng qua, nên tài xế đang rẽ phải nhường đường cho họ.","p":"Đúng rồi. Hình người đang đi nghĩa là người đi bộ được băng qua."},"tl":{"q":"Ang ilaw para sa tumatawid ay nagpapakita ng taong naglalakad. Ano ang ibig sabihin nito para sa mga naglalakad?","o":["Hindi sila dapat magsimulang tumawid","Puwede na silang magsimulang tumawid sa kalye","Mga bisikleta lang ang puwedeng tumawid","Puwedeng lumiko ang mga sasakyan nang hindi tumitingin"],"h1":"Ang taong naglalakad ay larawan ng kung ano ang puwedeng gawin ng mga tao.","h2":"Ang ilaw na may taong naglalakad ay nangangahulugang puwede nang magsimulang tumawid ang mga naglalakad, kaya ang mga driver na lumiliko ay dapat magbigay-daan sa kanila.","p":"Tama. Ang taong naglalakad ay nangangahulugang puwedeng tumawid ang mga tao."},"ar":{"q":"إشارة المشاة تُظهر شخصًا يمشي. ماذا تعني للمشاة؟","o":["يجب ألا يبدؤوا العبور","يمكنهم أن يبدؤوا عبور الشارع","الدراجات فقط يمكنها العبور","السيارات يمكنها أن تنعطف بدون أن تنظر"],"h1":"الشخص الذي يمشي صورة لما يُسمح للناس أن يفعلوه.","h2":"إشارة الشخص الذي يمشي تعني أن المشاة يمكنهم أن يبدؤوا العبور، لذلك السائقون الذين ينعطفون يجب أن يعطوهم الأولوية.","p":"صحيح. الشخص الذي يمشي يعني أن الناس يمكنهم العبور."},"ht":{"q":"Yon siyal pou pyeton montre yon moun k ap mache. Kisa li vle di pou moun ki a pye?","o":["Yo pa dwe kòmanse travèse","Yo ka kòmanse travèse lari a","Se sèlman bisiklèt ki ka travèse","Machin yo ka vire san yo pa gade"],"h1":"Moun k ap mache a se yon foto sa moun yo ka fè.","h2":"Yon siyal ak yon moun k ap mache vle di moun ki a pye ka kòmanse travèse, kidonk chofè k ap vire dwe kite yo pase.","p":"Se sa. Moun k ap mache a vle di moun yo ka travèse."},"ref":{"doc":"FL","page":55}},{"id":"signals-016","scope":"US","cat":"signals","sign":null,"c":3,"en":{"q":"A pedestrian signal shows a flashing raised hand. What does it mean?","o":["Anyone may start crossing now","People must run back to the curb","Drivers must stop for the whole cycle","Do not start crossing, but people already crossing may finish"],"h1":"Think about the difference between starting to cross and finishing.","h2":"A flashing hand means people should not start crossing, but anyone already in the street may finish crossing.","p":"Right. A flashing hand means do not start, but finish if you already started."},"es":{"q":"Una señal para peatones muestra una mano levantada intermitente. ¿Qué significa?","o":["Cualquiera puede empezar a cruzar ahora","Las personas deben correr de vuelta a la acera","Los conductores deben parar todo el ciclo","No empiece a cruzar, pero quien ya está cruzando puede terminar"],"h1":"Piense en la diferencia entre empezar a cruzar y terminar de cruzar.","h2":"Una mano intermitente significa que las personas no deben empezar a cruzar, pero quien ya está en la calle puede terminar de cruzar.","p":"Correcto. Mano intermitente significa no empiece, pero termine si ya empezó."},"zh":{"q":"行人信号灯显示一只闪烁的举起的手。它是什么意思？","o":["任何人现在都可以开始过马路","行人必须跑回路边","司机在整个周期都必须停车","不要开始过马路，但已经在过的人可以走完"],"h1":"想一想 “开始过马路” 和 “走完” 有什么不同。","h2":"闪烁的手表示行人不应该开始过马路，但已经在马路上的人可以走完。","p":"对。闪烁的手表示不要开始，已经开始的人可以走完。"},"vi":{"q":"Đèn cho người đi bộ hiện hình bàn tay giơ lên đang nhấp nháy. Điều đó có nghĩa là gì?","o":["Bây giờ ai cũng được bắt đầu băng qua","Người đi bộ phải chạy về lại lề đường","Tài xế phải dừng suốt cả chu kỳ đèn","Không được bắt đầu băng qua, nhưng ai đang băng qua thì được đi tiếp cho hết"],"h1":"Hãy nghĩ đến sự khác nhau giữa bắt đầu băng qua và đi cho hết.","h2":"Bàn tay nhấp nháy nghĩa là không ai nên bắt đầu băng qua, nhưng người đang ở giữa đường thì được đi tiếp cho hết.","p":"Đúng rồi. Bàn tay nhấp nháy nghĩa là đừng bắt đầu, nhưng đi cho hết nếu đã bắt đầu."},"tl":{"q":"Ang ilaw para sa tumatawid ay nagpapakita ng kumikislap na nakataas na kamay. Ano ang ibig sabihin nito?","o":["Puwede nang magsimulang tumawid ang kahit sino","Dapat tumakbo pabalik sa bangketa ang mga tao","Dapat huminto ang mga driver sa buong ikot ng ilaw","Huwag magsimulang tumawid, pero puwedeng tapusin ng mga tumatawid na"],"h1":"Isipin ang pagkakaiba ng pagsisimulang tumawid at pagtatapos ng pagtawid.","h2":"Ang kumikislap na kamay ay nangangahulugang hindi dapat magsimulang tumawid ang mga tao, pero ang sinumang nasa kalye na ay puwedeng tapusin ang pagtawid.","p":"Tama. Ang kumikislap na kamay ay nangangahulugang huwag magsimula, pero tapusin kung nagsimula ka na."},"ar":{"q":"إشارة المشاة تُظهر يدًا مرفوعة تومض. ماذا تعني؟","o":["أي شخص يمكنه أن يبدأ العبور الآن","يجب أن يركض الناس عائدين إلى الرصيف","يجب أن يتوقف السائقون طوال الدورة كلها","لا تبدأ العبور، لكن من يعبر بالفعل يمكنه أن يكمل"],"h1":"فكّر في الفرق بين أن تبدأ العبور وأن تكمله.","h2":"اليد الوامضة تعني أن الناس يجب ألا يبدؤوا العبور، لكن أي شخص موجود في الشارع بالفعل يمكنه أن يكمل العبور.","p":"صحيح. اليد الوامضة تعني: لا تبدأ، لكن أكمل إذا كنت قد بدأت."},"ht":{"q":"Yon siyal pou pyeton montre yon men leve k ap kliyote. Kisa li vle di?","o":["Nenpòt moun ka kòmanse travèse kounye a","Moun yo dwe kouri tounen sou twotwa a","Chofè yo dwe kanpe pandan tout sik la","Pa kòmanse travèse, men moun ki deja ap travèse ka fini"],"h1":"Panse ak diferans ant kòmanse travèse ak fini travèse.","h2":"Yon men k ap kliyote vle di moun pa dwe kòmanse travèse, men nenpòt moun ki deja nan lari a ka fini travèse.","p":"Se sa. Yon men k ap kliyote vle di pa kòmanse, men fini si ou te deja kòmanse."},"ref":{"doc":"FL","page":55}},{"id":"signals-017","scope":"US","cat":"signals","sign":null,"c":0,"en":{"q":"A pedestrian signal shows a number counting down next to a hand. What does the number show?","o":["How many seconds are left to finish crossing","How many people may cross","The speed limit for the street","How many cars may turn"],"h1":"The number gets smaller every second.","h2":"The countdown number shows how many seconds are left for people to finish crossing before the signal changes.","p":"Right. The countdown shows the seconds left to cross."},"es":{"q":"Una señal para peatones muestra un número que baja al lado de una mano. ¿Qué indica el número?","o":["Cuántos segundos quedan para terminar de cruzar","Cuántas personas pueden cruzar","El límite de velocidad de la calle","Cuántos carros pueden girar"],"h1":"El número se hace más pequeño cada segundo.","h2":"El número de cuenta regresiva muestra cuántos segundos les quedan a las personas para terminar de cruzar antes de que cambie la señal.","p":"Correcto. La cuenta regresiva muestra los segundos que quedan para cruzar."},"zh":{"q":"行人信号灯在手的旁边显示一个倒数的数字。这个数字表示什么？","o":["还剩多少秒可以走完马路","可以有多少人过马路","这条街的限速","可以有多少辆车转弯"],"h1":"这个数字每秒都在变小。","h2":"倒数数字表示信号变化前，行人还剩多少秒可以走完马路。","p":"对。倒数数字表示过马路还剩几秒。"},"vi":{"q":"Đèn cho người đi bộ hiện một con số đếm ngược bên cạnh bàn tay. Con số đó cho biết gì?","o":["Còn bao nhiêu giây để đi qua hết","Bao nhiêu người được băng qua","Giới hạn tốc độ của con đường","Bao nhiêu xe được rẽ"],"h1":"Con số nhỏ đi mỗi giây.","h2":"Con số đếm ngược cho biết người đi bộ còn bao nhiêu giây để đi qua hết trước khi đèn đổi.","p":"Đúng rồi. Con số đếm ngược cho biết số giây còn lại để băng qua."},"tl":{"q":"Ang ilaw para sa tumatawid ay nagpapakita ng numerong nagbibilang pababa sa tabi ng kamay. Ano ang ipinapakita ng numero?","o":["Ilang segundo na lang ang natitira para matapos ang pagtawid","Ilang tao ang puwedeng tumawid","Ang speed limit ng kalye","Ilang sasakyan ang puwedeng lumiko"],"h1":"Lumiliit ang numero bawat segundo.","h2":"Ang numerong nagbibilang pababa ay nagpapakita kung ilang segundo na lang ang natitira para matapos tumawid ang mga tao bago magbago ang ilaw.","p":"Tama. Ipinapakita ng countdown ang natitirang segundo para tumawid."},"ar":{"q":"إشارة المشاة تُظهر رقمًا يعدّ تنازليًا بجانب يد. ماذا يُظهر الرقم؟","o":["كم ثانية بقيت لإكمال العبور","كم شخصًا يمكنه العبور","حد السرعة في الشارع","كم سيارة يمكنها أن تنعطف"],"h1":"الرقم يصغر كل ثانية.","h2":"رقم العد التنازلي يُظهر كم ثانية بقيت للناس لكي يكملوا العبور قبل أن تتغير الإشارة.","p":"صحيح. العد التنازلي يُظهر الثواني الباقية للعبور."},"ht":{"q":"Yon siyal pou pyeton montre yon nimewo k ap desann bò kote yon men. Kisa nimewo a montre?","o":["Konbyen segonn ki rete pou fini travèse","Konbyen moun ki ka travèse","Limit vitès nan lari a","Konbyen machin ki ka vire"],"h1":"Nimewo a vin pi piti chak segonn.","h2":"Nimewo k ap desann nan montre konbyen segonn ki rete pou moun yo fini travèse anvan siyal la chanje.","p":"Se sa. Nimewo k ap desann nan montre segonn ki rete pou travèse."},"ref":{"doc":"FL","page":55}},{"id":"signals-018","scope":"US","cat":"signals","sign":null,"c":2,"en":{"q":"What do yellow center lines on a road tell you?","o":["All lanes go the same direction","The road is a school zone","Traffic on each side of the line moves in opposite directions","Parking is allowed on the line"],"h1":"Think about where yellow lines usually are: between the two sides of the road.","h2":"Yellow center lines separate traffic moving in opposite directions, so cars on the other side come toward you.","p":"Right. Yellow lines separate traffic going opposite ways."},"es":{"q":"¿Qué le indican las líneas amarillas en el centro de la calle?","o":["Todos los carriles van en la misma dirección","La calle es una zona escolar","El tráfico de cada lado de la línea va en direcciones opuestas","Se permite estacionar sobre la línea"],"h1":"Piense dónde suelen estar las líneas amarillas: entre los dos lados de la calle.","h2":"Las líneas amarillas del centro separan el tráfico que va en direcciones opuestas, así que los carros del otro lado vienen hacia usted.","p":"Correcto. Las líneas amarillas separan el tráfico que va en sentidos opuestos."},"zh":{"q":"道路上的黄色中心线告诉你什么？","o":["所有车道都往同一个方向","这条路是学校区","线两边的车往相反方向开","可以在线上停车"],"h1":"想一想黄线通常在哪里：在道路两边之间。","h2":"黄色中心线把相反方向的车流分开，所以线另一边的车是朝你开过来的。","p":"对。黄线把相反方向的车分开。"},"vi":{"q":"Vạch kẻ màu vàng ở giữa đường cho bạn biết điều gì?","o":["Tất cả các làn đều đi cùng một chiều","Con đường là khu vực trường học","Xe ở hai bên vạch chạy ngược chiều nhau","Được đỗ xe trên vạch"],"h1":"Hãy nghĩ xem vạch vàng thường nằm ở đâu: giữa hai bên của con đường.","h2":"Vạch vàng ở giữa đường tách xe chạy ngược chiều nhau, nên xe ở bên kia vạch đang chạy về phía bạn.","p":"Đúng rồi. Vạch vàng tách xe chạy ngược chiều nhau."},"tl":{"q":"Ano ang sinasabi sa iyo ng mga dilaw na linya sa gitna ng kalsada?","o":["Lahat ng linya ay papunta sa iisang direksyon","School zone ang kalsada","Ang trapiko sa magkabilang bahagi ng linya ay papunta sa magkasalungat na direksyon","Puwedeng pumarada sa linya"],"h1":"Isipin kung saan karaniwang nakalagay ang mga dilaw na linya: sa pagitan ng dalawang bahagi ng kalsada.","h2":"Ang mga dilaw na linya sa gitna ay naghihiwalay sa trapikong papunta sa magkasalungat na direksyon, kaya ang mga sasakyan sa kabilang bahagi ay papunta sa iyo.","p":"Tama. Ang dilaw na linya ay naghihiwalay sa trapikong magkasalungat ang direksyon."},"ar":{"q":"ماذا تخبرك الخطوط الصفراء في وسط الطريق؟","o":["كل المسارات تسير في نفس الاتجاه","الطريق منطقة مدرسة","السيارات على كل جانب من الخط تسير في اتجاهين متعاكسين","الوقوف مسموح على الخط"],"h1":"فكّر أين توجد الخطوط الصفراء عادةً: بين جانبي الطريق.","h2":"الخطوط الصفراء في الوسط تفصل بين السيارات التي تسير في اتجاهين متعاكسين، لذلك السيارات على الجانب الآخر تأتي نحوك.","p":"صحيح. الخطوط الصفراء تفصل بين السيارات التي تسير في اتجاهين متعاكسين."},"ht":{"q":"Kisa liy jòn nan mitan yon wout di ou?","o":["Tout koulwa yo ale nan menm direksyon","Wout la se yon zòn lekòl","Machin sou chak bò liy la ale nan direksyon opoze","Ou ka pake sou liy la"],"h1":"Panse ki kote liy jòn yo konn ye: ant de bò wout la.","h2":"Liy jòn nan mitan wout la separe machin k ap ale nan direksyon opoze, kidonk machin sou lòt bò a ap vin sou ou.","p":"Se sa. Liy jòn yo separe machin k ap ale nan direksyon opoze."},"ref":{"doc":"FL","page":43}},{"id":"signals-019","scope":"US","cat":"signals","sign":null,"c":1,"en":{"q":"What do white lines between lanes tell you?","o":["The lanes carry traffic going opposite directions","The lanes carry traffic going the same direction","The lane is only for buses","You are near a railroad crossing"],"h1":"Compare white lines with yellow lines.","h2":"White lines between lanes show that the traffic in those lanes moves in the same direction.","p":"Right. White lines separate lanes going the same way."},"es":{"q":"¿Qué le indican las líneas blancas entre los carriles?","o":["Los carriles llevan tráfico en direcciones opuestas","Los carriles llevan tráfico en la misma dirección","El carril es solo para autobuses","Usted está cerca de un cruce de tren"],"h1":"Compare las líneas blancas con las amarillas.","h2":"Las líneas blancas entre carriles muestran que el tráfico de esos carriles va en la misma dirección.","p":"Correcto. Las líneas blancas separan carriles que van en el mismo sentido."},"zh":{"q":"车道之间的白线告诉你什么？","o":["这些车道的车往相反方向开","这些车道的车往同一个方向开","这条车道只给公交车","你在铁路道口附近"],"h1":"把白线和黄线比一比。","h2":"车道之间的白线表示这些车道的车往同一个方向开。","p":"对。白线分开同方向的车道。"},"vi":{"q":"Vạch trắng giữa các làn cho bạn biết điều gì?","o":["Các làn có xe chạy ngược chiều nhau","Các làn có xe chạy cùng một chiều","Làn này chỉ dành cho xe buýt","Bạn đang ở gần chỗ băng qua đường sắt"],"h1":"Hãy so sánh vạch trắng với vạch vàng.","h2":"Vạch trắng giữa các làn cho thấy xe trong các làn đó chạy cùng một chiều.","p":"Đúng rồi. Vạch trắng tách các làn đi cùng một chiều."},"tl":{"q":"Ano ang sinasabi sa iyo ng mga puting linya sa pagitan ng mga lane?","o":["Ang mga lane ay may trapikong papunta sa magkasalungat na direksyon","Ang mga lane ay may trapikong papunta sa iisang direksyon","Para sa bus lang ang lane","Malapit ka sa tawiran ng tren"],"h1":"Ihambing ang mga puting linya sa mga dilaw na linya.","h2":"Ang mga puting linya sa pagitan ng mga lane ay nagpapakita na ang trapiko sa mga lane na iyon ay papunta sa iisang direksyon.","p":"Tama. Ang puting linya ay naghihiwalay sa mga lane na papunta sa iisang direksyon."},"ar":{"q":"ماذا تخبرك الخطوط البيضاء بين المسارات؟","o":["المسارات فيها سيارات تسير في اتجاهين متعاكسين","المسارات فيها سيارات تسير في نفس الاتجاه","المسار للحافلات فقط","أنت قريب من تقاطع سكة حديد"],"h1":"قارن الخطوط البيضاء بالخطوط الصفراء.","h2":"الخطوط البيضاء بين المسارات تُظهر أن السيارات في هذه المسارات تسير في نفس الاتجاه.","p":"صحيح. الخطوط البيضاء تفصل بين مسارات تسير في نفس الاتجاه."},"ht":{"q":"Kisa liy blan ant koulwa yo di ou?","o":["Machin nan koulwa yo ale nan direksyon opoze","Machin nan koulwa yo ale nan menm direksyon","Koulwa a se pou bis sèlman","Ou toupre yon kote tren travèse"],"h1":"Konpare liy blan yo ak liy jòn yo.","h2":"Liy blan ant koulwa yo montre machin nan koulwa sa yo ale nan menm direksyon.","p":"Se sa. Liy blan yo separe koulwa k ap ale nan menm direksyon."},"ref":{"doc":"FL","page":43}},{"id":"signals-020","scope":"US","cat":"signals","sign":null,"c":3,"en":{"q":"The yellow center line on your side is broken (dashed). What does that allow?","o":["You may never pass","You may park on the line","You may drive on the line for a long time","You may pass when it is safe"],"h1":"A broken line has gaps. Think about what gaps let you do.","h2":"A broken yellow line on your side means you may pass another car, but only when the way ahead is clear and safe.","p":"Right. A broken yellow line on your side means you may pass when safe."},"es":{"q":"La línea amarilla del centro de su lado es discontinua (con espacios). ¿Qué le permite?","o":["No puede rebasar nunca","Puede estacionar sobre la línea","Puede manejar sobre la línea por mucho rato","Puede rebasar cuando sea seguro"],"h1":"Una línea discontinua tiene espacios. Piense qué le permiten esos espacios.","h2":"Una línea amarilla discontinua de su lado significa que usted puede rebasar a otro carro, pero solo cuando el camino adelante esté libre y sea seguro.","p":"Correcto. Línea amarilla discontinua de su lado significa que puede rebasar si es seguro."},"zh":{"q":"你这一边的黄色中心线是虚线（断开的）。它允许你做什么？","o":["你永远不能超车","你可以在线上停车","你可以长时间压线开","安全时你可以超车"],"h1":"虚线有空隙。想一想空隙让你做什么。","h2":"你这一边的黄色虚线表示你可以超车，但只能在前方路上没车、安全的时候。","p":"对。你这边是黄色虚线，表示安全时可以超车。"},"vi":{"q":"Vạch vàng ở giữa đường, phía bên bạn, là vạch đứt (nét đứt). Vạch này cho phép điều gì?","o":["Bạn không bao giờ được vượt","Bạn được đỗ xe trên vạch","Bạn được chạy trên vạch trong thời gian dài","Bạn được vượt khi an toàn"],"h1":"Vạch đứt có những khoảng trống. Hãy nghĩ xem khoảng trống cho bạn làm gì.","h2":"Vạch vàng đứt ở phía bên bạn nghĩa là bạn được vượt xe khác, nhưng chỉ khi đường phía trước trống và an toàn.","p":"Đúng rồi. Vạch vàng đứt ở phía bạn nghĩa là được vượt khi an toàn."},"tl":{"q":"Putol-putol (dashed) ang dilaw na linya sa gitna sa bahagi mo. Ano ang pinapayagan nito?","o":["Hindi ka kailanman puwedeng mag-overtake","Puwede kang pumarada sa linya","Puwede kang magmaneho sa ibabaw ng linya nang matagal","Puwede kang mag-overtake kapag ligtas"],"h1":"May mga puwang ang putol-putol na linya. Isipin kung ano ang ipinapagawa sa iyo ng mga puwang.","h2":"Ang putol-putol na dilaw na linya sa bahagi mo ay nangangahulugang puwede kang lumampas sa ibang sasakyan, pero kapag maluwag at ligtas lang ang daan sa unahan.","p":"Tama. Ang putol-putol na dilaw na linya sa bahagi mo ay nangangahulugang puwede kang mag-overtake kapag ligtas."},"ar":{"q":"خط الوسط الأصفر على جانبك متقطع. بماذا يسمح ذلك؟","o":["لا يمكنك أن تتجاوز أبدًا","يمكنك أن تقف على الخط","يمكنك أن تقود على الخط وقتًا طويلًا","يمكنك أن تتجاوز عندما يكون ذلك آمنًا"],"h1":"الخط المتقطع فيه فراغات. فكّر في ما تسمح لك به الفراغات.","h2":"الخط الأصفر المتقطع على جانبك يعني أنه يمكنك أن تتجاوز سيارة أخرى، لكن فقط عندما يكون الطريق أمامك خاليًا وآمنًا.","p":"صحيح. الخط الأصفر المتقطع على جانبك يعني أنه يمكنك أن تتجاوز عندما يكون ذلك آمنًا."},"ht":{"q":"Liy jòn nan mitan an sou bò ou a koupe koupe (an tirè). Kisa sa pèmèt?","o":["Ou pa janm ka double","Ou ka pake sou liy la","Ou ka kondui sou liy la pou lontan","Ou ka double lè sa an sekirite"],"h1":"Yon liy koupe gen espas vid. Panse ak sa espas sa yo kite ou fè.","h2":"Yon liy jòn koupe sou bò ou a vle di ou ka double yon lòt machin, men sèlman lè wout la devan lib epi an sekirite.","p":"Se sa. Yon liy jòn koupe sou bò ou vle di ou ka double lè sa an sekirite."},"ref":{"doc":"FL","page":44}},{"id":"signals-021","scope":"US","cat":"signals","sign":null,"c":0,"en":{"q":"You see a solid yellow line on your side and a broken yellow line on the other side. Who may pass?","o":["Only drivers on the side with the broken line","Only drivers on your side","Drivers on both sides","No one, at any time"],"h1":"Look at the line closest to your car. It is the one that counts for you.","h2":"The line closest to you is the one you follow, so a solid yellow line on your side means you may not pass, while drivers next to the broken line may pass when safe.","p":"Right. A solid line on your side means you may not pass."},"es":{"q":"Usted ve una línea amarilla continua de su lado y una línea amarilla discontinua del otro lado. ¿Quién puede rebasar?","o":["Solo los conductores del lado de la línea discontinua","Solo los conductores de su lado","Los conductores de los dos lados","Nadie, en ningún momento"],"h1":"Mire la línea más cerca de su carro. Esa es la que cuenta para usted.","h2":"Usted sigue la línea más cerca de su carro, así que una línea amarilla continua de su lado significa que no puede rebasar, mientras que los conductores junto a la línea discontinua pueden rebasar si es seguro.","p":"Correcto. Una línea continua de su lado significa que no puede rebasar."},"zh":{"q":"你这一边是黄色实线，另一边是黄色虚线。谁可以超车？","o":["只有虚线那一边的司机","只有你这一边的司机","两边的司机都可以","任何时候谁都不行"],"h1":"看离你的车最近的那条线。那条线才是给你的。","h2":"你要遵守离你最近的那条线，所以你这一边是黄色实线，表示你不能超车，而靠近虚线一边的司机在安全时可以超车。","p":"对。你这边是实线，表示你不能超车。"},"vi":{"q":"Bạn thấy vạch vàng liền ở phía bên bạn và vạch vàng đứt ở phía bên kia. Ai được vượt?","o":["Chỉ tài xế ở phía có vạch đứt","Chỉ tài xế ở phía bên bạn","Tài xế ở cả hai phía","Không ai cả, vào bất cứ lúc nào"],"h1":"Hãy nhìn vạch gần xe bạn nhất. Đó là vạch áp dụng cho bạn.","h2":"Bạn làm theo vạch gần bạn nhất, nên vạch vàng liền ở phía bạn nghĩa là bạn không được vượt, còn tài xế ở phía vạch đứt được vượt khi an toàn.","p":"Đúng rồi. Vạch liền ở phía bạn nghĩa là bạn không được vượt."},"tl":{"q":"May tuloy-tuloy na dilaw na linya sa bahagi mo at putol-putol na dilaw na linya sa kabilang bahagi. Sino ang puwedeng mag-overtake?","o":["Ang mga driver lang sa bahaging may putol-putol na linya","Ang mga driver lang sa bahagi mo","Ang mga driver sa magkabilang bahagi","Walang sinuman, kailanman"],"h1":"Tingnan ang linyang pinakamalapit sa sasakyan mo. Iyon ang linyang para sa iyo.","h2":"Ang linyang pinakamalapit sa iyo ang sinusunod mo, kaya ang tuloy-tuloy na dilaw na linya sa bahagi mo ay nangangahulugang hindi ka puwedeng mag-overtake, habang ang mga driver na katabi ng putol-putol na linya ay puwedeng mag-overtake kapag ligtas.","p":"Tama. Ang tuloy-tuloy na linya sa bahagi mo ay nangangahulugang hindi ka puwedeng mag-overtake."},"ar":{"q":"ترى خطًا أصفر متصلًا على جانبك وخطًا أصفر متقطعًا على الجانب الآخر. من يمكنه أن يتجاوز؟","o":["فقط السائقون على الجانب الذي فيه الخط المتقطع","فقط السائقون على جانبك","السائقون على الجانبين","لا أحد، في أي وقت"],"h1":"انظر إلى الخط الأقرب إلى سيارتك. هو الخط المهم بالنسبة لك.","h2":"الخط الأقرب إليك هو الذي تتبعه، لذلك الخط الأصفر المتصل على جانبك يعني أنه لا يمكنك أن تتجاوز، أما السائقون بجانب الخط المتقطع فيمكنهم أن يتجاوزوا عندما يكون ذلك آمنًا.","p":"صحيح. الخط المتصل على جانبك يعني أنه لا يمكنك أن تتجاوز."},"ht":{"q":"Ou wè yon liy jòn plen sou bò ou ak yon liy jòn koupe sou lòt bò a. Kiyès ki ka double?","o":["Sèlman chofè ki sou bò liy koupe a","Sèlman chofè ki sou bò ou a","Chofè sou toude bò yo","Pèsonn, nan okenn moman"],"h1":"Gade liy ki pi pre machin ou a. Se li ki konte pou ou.","h2":"Liy ki pi pre ou a se li ou swiv, kidonk yon liy jòn plen sou bò ou vle di ou pa ka double, men chofè ki bò liy koupe a ka double lè sa an sekirite.","p":"Se sa. Yon liy plen sou bò ou vle di ou pa ka double."},"ref":{"doc":"FL","page":44}},{"id":"signals-022","scope":"US","cat":"signals","sign":null,"c":2,"en":{"q":"What do two solid yellow lines in the center of the road mean?","o":["Passing is allowed in both directions","Only trucks may pass","No one may cross them to pass, in either direction","The road ends ahead"],"h1":"Two solid lines are stronger than one. Think about both sides.","h2":"Two solid yellow lines mean drivers on both sides may not cross them to pass another car.","p":"Right. Double solid yellow means no passing for anyone."},"es":{"q":"¿Qué significan dos líneas amarillas continuas en el centro de la calle?","o":["Se permite rebasar en las dos direcciones","Solo los camiones pueden rebasar","Nadie puede cruzarlas para rebasar, en ninguna dirección","La calle se termina más adelante"],"h1":"Dos líneas continuas son más fuertes que una. Piense en los dos lados.","h2":"Dos líneas amarillas continuas significan que los conductores de los dos lados no pueden cruzarlas para rebasar a otro carro.","p":"Correcto. Doble línea amarilla continua significa que nadie puede rebasar."},"zh":{"q":"道路中间的两条黄色实线是什么意思？","o":["两个方向都可以超车","只有卡车可以超车","两个方向的车都不能越线超车","前方道路结束"],"h1":"两条实线比一条更严格。想一想两边。","h2":"两条黄色实线表示两边的司机都不能越过它们去超车。","p":"对。双黄实线表示任何人都不能超车。"},"vi":{"q":"Hai vạch vàng liền ở giữa đường có nghĩa là gì?","o":["Được vượt ở cả hai chiều","Chỉ xe tải được vượt","Không ai được lấn qua để vượt, ở cả hai chiều","Phía trước đường hết"],"h1":"Hai vạch liền mạnh hơn một vạch. Hãy nghĩ đến cả hai phía.","h2":"Hai vạch vàng liền nghĩa là tài xế ở cả hai phía đều không được lấn qua chúng để vượt xe khác.","p":"Đúng rồi. Hai vạch vàng liền nghĩa là không ai được vượt."},"tl":{"q":"Ano ang ibig sabihin ng dalawang tuloy-tuloy na dilaw na linya sa gitna ng kalsada?","o":["Puwedeng mag-overtake sa magkabilang direksyon","Mga trak lang ang puwedeng mag-overtake","Walang puwedeng tumawid sa mga ito para mag-overtake, sa alinmang direksyon","Matatapos ang kalsada sa unahan"],"h1":"Mas malakas ang dalawang tuloy-tuloy na linya kaysa sa isa. Isipin ang magkabilang bahagi.","h2":"Ang dalawang tuloy-tuloy na dilaw na linya ay nangangahulugang hindi puwedeng tumawid sa mga ito ang mga driver sa magkabilang bahagi para lumampas sa ibang sasakyan.","p":"Tama. Ang dobleng tuloy-tuloy na dilaw ay nangangahulugang bawal mag-overtake ang lahat."},"ar":{"q":"ماذا يعني خطان أصفران متصلان في وسط الطريق؟","o":["التجاوز مسموح في الاتجاهين","الشاحنات فقط يمكنها أن تتجاوز","لا أحد يمكنه أن يعبرهما ليتجاوز، في أي اتجاه","الطريق ينتهي في الأمام"],"h1":"خطان متصلان أقوى من خط واحد. فكّر في الجانبين.","h2":"الخطان الأصفران المتصلان يعنيان أن السائقين على الجانبين لا يمكنهم أن يعبروهما ليتجاوزوا سيارة أخرى.","p":"صحيح. الخط الأصفر المزدوج المتصل يعني ممنوع التجاوز على الجميع."},"ht":{"q":"Kisa de liy jòn plen nan mitan wout la vle di?","o":["Ou ka double nan toude direksyon","Se sèlman kamyon ki ka double","Pèsonn pa ka travèse yo pou double, nan okenn direksyon","Wout la fini pi devan"],"h1":"De liy plen pi fò pase youn. Panse ak toude bò yo.","h2":"De liy jòn plen vle di chofè sou toude bò yo pa ka travèse yo pou double yon lòt machin.","p":"Se sa. De liy jòn plen vle di pèsonn pa ka double."},"ref":{"doc":"FL","page":44}},{"id":"signals-023","scope":"US","cat":"signals","sign":null,"c":1,"en":{"q":"What does a solid white line between two lanes going the same way mean?","o":["You must change lanes now","Stay in your lane; changing lanes is discouraged there","Traffic in the next lane comes toward you","You may park along the line"],"h1":"A solid line asks you to stay where you are.","h2":"A solid white line between lanes means you should stay in your lane and change lanes only if you really must and it is safe.","p":"Right. A solid white line means stay in your lane."},"es":{"q":"¿Qué significa una línea blanca continua entre dos carriles que van en el mismo sentido?","o":["Usted debe cambiar de carril ahora","Quédese en su carril; no se recomienda cambiar de carril ahí","El tráfico del otro carril viene hacia usted","Puede estacionar junto a la línea"],"h1":"Una línea continua le pide quedarse donde está.","h2":"Una línea blanca continua entre carriles significa que usted debe quedarse en su carril y cambiar solo si de verdad lo necesita y es seguro.","p":"Correcto. Una línea blanca continua significa quédese en su carril."},"zh":{"q":"同方向两条车道之间的白色实线是什么意思？","o":["你现在必须换车道","待在你的车道里，这里最好不要换车道","旁边车道的车朝你开过来","你可以沿着这条线停车"],"h1":"实线是要你待在原来的地方。","h2":"车道之间的白色实线表示你应该待在自己的车道里，只有真的必须换道而且安全时才换。","p":"对。白色实线表示待在你的车道里。"},"vi":{"q":"Vạch trắng liền giữa hai làn đi cùng một chiều có nghĩa là gì?","o":["Bạn phải đổi làn ngay bây giờ","Hãy ở trong làn của bạn; không nên đổi làn ở đó","Xe ở làn bên cạnh chạy ngược về phía bạn","Bạn được đỗ xe dọc theo vạch"],"h1":"Vạch liền muốn bạn ở yên chỗ của mình.","h2":"Vạch trắng liền giữa các làn nghĩa là bạn nên ở trong làn của mình, và chỉ đổi làn khi thật sự cần và an toàn.","p":"Đúng rồi. Vạch trắng liền nghĩa là ở trong làn của bạn."},"tl":{"q":"Ano ang ibig sabihin ng tuloy-tuloy na puting linya sa pagitan ng dalawang lane na papunta sa iisang direksyon?","o":["Dapat kang lumipat ng lane ngayon","Manatili sa lane mo; hindi hinihikayat ang paglipat ng lane doon","Ang trapiko sa katabing lane ay papunta sa iyo","Puwede kang pumarada sa tabi ng linya"],"h1":"Hinihiling ng tuloy-tuloy na linya na manatili ka kung nasaan ka.","h2":"Ang tuloy-tuloy na puting linya sa pagitan ng mga lane ay nangangahulugang dapat kang manatili sa lane mo at lumipat lang ng lane kung talagang kailangan at ligtas.","p":"Tama. Ang tuloy-tuloy na puting linya ay nangangahulugang manatili sa lane mo."},"ar":{"q":"ماذا يعني خط أبيض متصل بين مسارين يسيران في نفس الاتجاه؟","o":["يجب أن تغيّر المسار الآن","ابقَ في مسارك؛ تغيير المسار غير مستحب هناك","السيارات في المسار المجاور تأتي نحوك","يمكنك أن تقف على طول الخط"],"h1":"الخط المتصل يطلب منك أن تبقى حيث أنت.","h2":"الخط الأبيض المتصل بين المسارات يعني أنه يجب أن تبقى في مسارك، وتغيّر المسار فقط إذا كنت مضطرًا حقًا وكان ذلك آمنًا.","p":"صحيح. الخط الأبيض المتصل يعني: ابقَ في مسارك."},"ht":{"q":"Kisa yon liy blan plen ant de koulwa k ap ale nan menm direksyon vle di?","o":["Ou dwe chanje koulwa kounye a","Rete nan koulwa ou; yo pa konseye chanje koulwa la a","Machin nan lòt koulwa a ap vin sou ou","Ou ka pake sou kote liy la"],"h1":"Yon liy plen mande ou rete kote ou ye a.","h2":"Yon liy blan plen ant koulwa yo vle di ou dwe rete nan koulwa ou epi chanje koulwa sèlman si ou vrèman oblije epi si sa an sekirite.","p":"Se sa. Yon liy blan plen vle di rete nan koulwa ou."},"ref":{"doc":"FL","page":43}},{"id":"signals-024","scope":"US","cat":"signals","sign":null,"c":3,"en":{"q":"A center lane has a solid yellow line and a broken yellow line on each side. What is this lane for?","o":["Passing slow cars","Driving long distances","Parking and loading","Left turns by drivers from both directions"],"h1":"Cars from both directions can use this lane, but only for one kind of move.","h2":"A center lane marked with solid and broken yellow lines on both sides is a two-way left-turn lane, so drivers from either direction use it only to turn left.","p":"Right. That center lane is only for left turns from both directions."},"es":{"q":"Un carril del centro tiene una línea amarilla continua y una línea amarilla discontinua en cada lado. ¿Para qué es este carril?","o":["Para rebasar a carros lentos","Para manejar distancias largas","Para estacionar y cargar","Para girar a la izquierda, para conductores de las dos direcciones"],"h1":"Carros de las dos direcciones pueden usar este carril, pero solo para un tipo de maniobra.","h2":"Un carril del centro con líneas amarillas continuas y discontinuas en los dos lados es un carril de giro a la izquierda en ambos sentidos, así que los conductores de cualquier dirección lo usan solo para girar a la izquierda.","p":"Correcto. Ese carril del centro es solo para girar a la izquierda, desde las dos direcciones."},"zh":{"q":"一条中间车道的两边各有一条黄色实线和一条黄色虚线。这条车道是做什么用的？","o":["超过慢车","开长途","停车和装卸货","两个方向的司机左转用"],"h1":"两个方向的车都能用这条车道，但只能做一种动作。","h2":"两边都画着黄色实线和黄色虚线的中间车道是双向左转车道，所以两个方向的司机都只能用它来左转。","p":"对。这条中间车道只给两个方向的车左转用。"},"vi":{"q":"Một làn ở giữa đường có vạch vàng liền và vạch vàng đứt ở mỗi bên. Làn này dùng để làm gì?","o":["Vượt xe chạy chậm","Chạy đường dài","Đỗ xe và bốc dỡ hàng","Rẽ trái cho tài xế từ cả hai chiều"],"h1":"Xe từ cả hai chiều đều được dùng làn này, nhưng chỉ cho một loại di chuyển.","h2":"Làn ở giữa có vạch vàng liền và vạch vàng đứt ở hai bên là làn rẽ trái hai chiều, nên tài xế từ chiều nào cũng chỉ dùng nó để rẽ trái.","p":"Đúng rồi. Làn giữa đó chỉ để rẽ trái, cho xe từ cả hai chiều."},"tl":{"q":"May gitnang lane na may tuloy-tuloy na dilaw na linya at putol-putol na dilaw na linya sa bawat gilid. Para saan ang lane na ito?","o":["Para lampasan ang mabagal na sasakyan","Para sa malayuang pagmamaneho","Para sa pagparada at pagkarga","Para sa pagkaliwa ng mga driver mula sa magkabilang direksyon"],"h1":"Puwedeng gamitin ng mga sasakyan mula sa magkabilang direksyon ang lane na ito, pero para lang sa isang uri ng galaw.","h2":"Ang gitnang lane na may tuloy-tuloy at putol-putol na dilaw na linya sa magkabilang gilid ay two-way left-turn lane, kaya ginagamit lang ito ng mga driver mula sa alinmang direksyon para kumaliwa.","p":"Tama. Ang gitnang lane na iyon ay para lang sa pagkaliwa mula sa magkabilang direksyon."},"ar":{"q":"مسار في الوسط له خط أصفر متصل وخط أصفر متقطع على كل جانب. ما الغرض من هذا المسار؟","o":["لتجاوز السيارات البطيئة","للقيادة لمسافات طويلة","للوقوف والتحميل","للانعطاف يسارًا للسائقين من الاتجاهين"],"h1":"السيارات من الاتجاهين يمكنها أن تستخدم هذا المسار، لكن لنوع واحد فقط من الحركة.","h2":"المسار الأوسط الذي عليه خطوط صفراء متصلة ومتقطعة على الجانبين هو مسار للانعطاف يسارًا في الاتجاهين، لذلك السائقون من أي اتجاه يستخدمونه فقط للانعطاف يسارًا.","p":"صحيح. هذا المسار الأوسط فقط للانعطاف يسارًا من الاتجاهين."},"ht":{"q":"Yon koulwa nan mitan an gen yon liy jòn plen ak yon liy jòn koupe sou chak bò. Pou kisa koulwa sa a ye?","o":["Pou double machin ki dousman","Pou kondui long distans","Pou pake ak pou chaje","Pou chofè ki soti nan toude direksyon vire agoch"],"h1":"Machin ki soti nan toude direksyon ka sèvi ak koulwa sa a, men pou yon sèl kalite mouvman.","h2":"Yon koulwa nan mitan an ki gen liy jòn plen ak liy jòn koupe sou toude bò se yon koulwa pou vire agoch nan de direksyon, kidonk chofè ki soti nan nenpòt direksyon sèvi avè l sèlman pou vire agoch.","p":"Se sa. Koulwa nan mitan sa a se sèlman pou vire agoch soti nan toude direksyon."},"ref":{"doc":"FL","page":45}},{"id":"signals-025","scope":"US","cat":"signals","sign":null,"c":0,"en":{"q":"Where should you stop when there is a wide white line painted across your lane at a red light?","o":["Before the white line","On top of the white line","Past the white line, at the corner","Anywhere in the intersection"],"h1":"This line shows the place where your front bumper should stop.","h2":"A wide white line across your lane is a stop line, so you must stop before it when you need to stop.","p":"Right. Stop before the white stop line."},"es":{"q":"¿Dónde debe parar cuando hay una línea blanca ancha pintada a lo ancho de su carril en una luz roja?","o":["Antes de la línea blanca","Encima de la línea blanca","Después de la línea blanca, en la esquina","En cualquier parte de la intersección"],"h1":"Esta línea muestra el lugar donde debe quedar el frente de su carro.","h2":"Una línea blanca ancha a lo ancho de su carril es la línea de pare, así que usted debe parar antes de ella cuando tiene que parar.","p":"Correcto. Pare antes de la línea blanca de pare."},"zh":{"q":"红灯时，你的车道上画着一条横过车道的宽白线。你应该停在哪里？","o":["白线前面","压在白线上","过了白线，停在路口拐角","路口里随便哪里"],"h1":"这条线表示你的前保险杠应该停在哪里。","h2":"横过你车道的宽白线是停车线，所以需要停车时，你必须停在它前面。","p":"对。停在白色停车线前面。"},"vi":{"q":"Khi đèn đỏ, có một vạch trắng rộng sơn ngang làn của bạn. Bạn nên dừng ở đâu?","o":["Trước vạch trắng","Ngay trên vạch trắng","Qua khỏi vạch trắng, ở góc đường","Bất cứ chỗ nào trong giao lộ"],"h1":"Vạch này cho thấy chỗ cản trước của xe bạn nên dừng lại.","h2":"Vạch trắng rộng ngang làn của bạn là vạch dừng, nên khi cần dừng, bạn phải dừng trước vạch đó.","p":"Đúng rồi. Hãy dừng trước vạch dừng màu trắng."},"tl":{"q":"Saan ka dapat huminto kapag may malapad na puting linyang nakapinta sa kabila ng lane mo sa pulang ilaw?","o":["Bago ang puting linya","Sa ibabaw ng puting linya","Lampas sa puting linya, sa may kanto","Kahit saan sa interseksyon"],"h1":"Ipinapakita ng linyang ito ang lugar kung saan dapat huminto ang harapang bumper mo.","h2":"Ang malapad na puting linya sa kabila ng lane mo ay stop line, kaya dapat kang huminto bago ito kapag kailangan mong huminto.","p":"Tama. Huminto bago ang puting stop line."},"ar":{"q":"أين يجب أن تتوقف عند ضوء أحمر عندما يكون هناك خط أبيض عريض مرسوم عرض مسارك؟","o":["قبل الخط الأبيض","فوق الخط الأبيض","بعد الخط الأبيض، عند الزاوية","في أي مكان داخل التقاطع"],"h1":"هذا الخط يُظهر المكان الذي يجب أن يتوقف عنده المصد الأمامي لسيارتك.","h2":"الخط الأبيض العريض عرض مسارك هو خط التوقف، لذلك يجب أن تتوقف قبله عندما تحتاج إلى التوقف.","p":"صحيح. توقف قبل خط التوقف الأبيض."},"ht":{"q":"Ki kote ou dwe kanpe lè gen yon gwo liy blan penti atravè koulwa ou nan yon limyè wouj?","o":["Anvan liy blan an","Sou liy blan an","Apre liy blan an, nan kwen an","Nenpòt kote nan kafou a"],"h1":"Liy sa a montre kote pare-chòk devan machin ou dwe kanpe.","h2":"Yon gwo liy blan atravè koulwa ou se yon liy pou kanpe, kidonk ou dwe kanpe anvan li lè ou bezwen kanpe.","p":"Se sa. Kanpe anvan liy blan pou kanpe a."},"ref":{"doc":"FL","page":45}},{"id":"signals-026","scope":"US","cat":"signals","sign":null,"c":2,"en":{"q":"You must stop at an intersection. There is a marked crosswalk but no stop line. Where do you stop?","o":["In the middle of the crosswalk","Past the crosswalk, in the intersection","Before the crosswalk","Only if a person is in the crosswalk"],"h1":"Think about keeping the path clear for people walking.","h2":"When there is no stop line, you stop before the crosswalk, so people on foot have a clear path.","p":"Right. With no stop line, stop before the crosswalk."},"es":{"q":"Usted debe parar en una intersección. Hay un paso peatonal marcado, pero no hay línea de pare. ¿Dónde para?","o":["En medio del paso peatonal","Después del paso peatonal, dentro de la intersección","Antes del paso peatonal","Solo si hay una persona en el paso peatonal"],"h1":"Piense en dejar libre el camino de las personas que caminan.","h2":"Cuando no hay línea de pare, usted para antes del paso peatonal, para que las personas a pie tengan el camino libre.","p":"Correcto. Sin línea de pare, pare antes del paso peatonal."},"zh":{"q":"你必须在路口停车。那里有画好的人行横道，但没有停车线。你停在哪里？","o":["人行横道中间","过了人行横道，停在路口里","人行横道前面","只有人行横道上有人时才停"],"h1":"想一想：要给走路的人留出畅通的路。","h2":"没有停车线时，你要停在人行横道前面，这样行人有畅通的路可以走。","p":"对。没有停车线时，停在人行横道前面。"},"vi":{"q":"Bạn phải dừng ở một giao lộ. Có vạch qua đường cho người đi bộ nhưng không có vạch dừng. Bạn dừng ở đâu?","o":["Ở giữa vạch qua đường","Qua khỏi vạch qua đường, trong giao lộ","Trước vạch qua đường","Chỉ khi có người trên vạch qua đường"],"h1":"Hãy nghĩ đến việc để trống lối đi cho người đi bộ.","h2":"Khi không có vạch dừng, bạn dừng trước vạch qua đường, để người đi bộ có lối đi trống.","p":"Đúng rồi. Khi không có vạch dừng, hãy dừng trước vạch qua đường."},"tl":{"q":"Dapat kang huminto sa isang interseksyon. May minarkahang tawiran pero walang stop line. Saan ka hihinto?","o":["Sa gitna ng tawiran","Lampas sa tawiran, sa loob ng interseksyon","Bago ang tawiran","Kung may tao lang sa tawiran"],"h1":"Isipin ang pagpapanatiling maluwag ng daanan ng mga naglalakad.","h2":"Kapag walang stop line, huminto ka bago ang tawiran, para maluwag ang daanan ng mga naglalakad.","p":"Tama. Kapag walang stop line, huminto bago ang tawiran."},"ar":{"q":"يجب أن تتوقف عند تقاطع. هناك ممر مشاة مرسوم لكن لا يوجد خط توقف. أين تتوقف؟","o":["في وسط ممر المشاة","بعد ممر المشاة، داخل التقاطع","قبل ممر المشاة","فقط إذا كان هناك شخص في ممر المشاة"],"h1":"فكّر في إبقاء الطريق خاليًا للمشاة.","h2":"عندما لا يوجد خط توقف، تتوقف قبل ممر المشاة، لكي يكون طريق المشاة خاليًا.","p":"صحيح. بدون خط توقف، توقف قبل ممر المشاة."},"ht":{"q":"Ou dwe kanpe nan yon kafou. Gen yon pasaj pyeton ki make, men pa gen liy pou kanpe. Ki kote ou kanpe?","o":["Nan mitan pasaj pyeton an","Apre pasaj pyeton an, nan kafou a","Anvan pasaj pyeton an","Sèlman si gen yon moun nan pasaj pyeton an"],"h1":"Panse ak kite chemen an lib pou moun k ap mache.","h2":"Lè pa gen liy pou kanpe, ou kanpe anvan pasaj pyeton an, pou moun ki a pye yo gen yon chemen lib.","p":"Se sa. Lè pa gen liy pou kanpe, kanpe anvan pasaj pyeton an."},"ref":{"doc":"FL","page":45}},{"id":"signals-027","scope":"US","cat":"signals","sign":null,"c":1,"en":{"q":"You see a bicycle symbol with two arrow shapes (chevrons) painted in your lane. What does it mean?","o":["Only bicycles may use this lane","Bicycles and cars share this lane","Bicycles are not allowed here","This lane is for parking bicycles"],"h1":"The marking is in a regular traffic lane, not in a separate bike lane.","h2":"A bicycle with chevrons is a shared lane marking, which means bicycles and cars share the lane, so watch for riders and give them room.","p":"Right. That marking means bikes and cars share the lane."},"es":{"q":"Usted ve un dibujo de bicicleta con dos flechas en forma de ángulo pintado en su carril. ¿Qué significa?","o":["Solo las bicicletas pueden usar este carril","Las bicicletas y los carros comparten este carril","No se permiten bicicletas aquí","Este carril es para estacionar bicicletas"],"h1":"La marca está en un carril normal de tráfico, no en un carril aparte para bicicletas.","h2":"Una bicicleta con flechas en ángulo es una marca de carril compartido, lo que significa que bicicletas y carros comparten el carril, así que fíjese en los ciclistas y deles espacio.","p":"Correcto. Esa marca significa que bicicletas y carros comparten el carril."},"zh":{"q":"你看到你的车道上画着一个自行车图案和两个箭头形状（V 形符号）。它是什么意思？","o":["只有自行车可以用这条车道","自行车和汽车共用这条车道","这里不准骑自行车","这条车道是停自行车的"],"h1":"这个标记在普通车道上，不在单独的自行车道上。","h2":"自行车加 V 形符号是共用车道标记，表示自行车和汽车共用这条车道，所以要注意骑车的人，给他们留出空间。","p":"对。这个标记表示自行车和汽车共用车道。"},"vi":{"q":"Bạn thấy hình xe đạp với hai hình mũi tên (chevron) được sơn trong làn của bạn. Điều đó có nghĩa là gì?","o":["Chỉ xe đạp được dùng làn này","Xe đạp và xe hơi dùng chung làn này","Ở đây cấm xe đạp","Làn này để đỗ xe đạp"],"h1":"Dấu này nằm trong làn xe bình thường, không phải trong làn riêng cho xe đạp.","h2":"Hình xe đạp có chevron là dấu làn dùng chung, nghĩa là xe đạp và xe hơi dùng chung làn, nên bạn cần chú ý người đi xe đạp và chừa chỗ cho họ.","p":"Đúng rồi. Dấu đó nghĩa là xe đạp và xe hơi dùng chung làn."},"tl":{"q":"May nakita kang simbolo ng bisikleta na may dalawang hugis-arrow (chevron) na nakapinta sa lane mo. Ano ang ibig sabihin nito?","o":["Mga bisikleta lang ang puwedeng gumamit ng lane na ito","Magkasamang ginagamit ng bisikleta at sasakyan ang lane na ito","Bawal ang bisikleta dito","Ang lane na ito ay paradahan ng bisikleta"],"h1":"Ang marka ay nasa karaniwang lane ng trapiko, hindi sa hiwalay na bike lane.","h2":"Ang bisikletang may chevron ay marka ng shared lane, na nangangahulugang magkasamang ginagamit ng bisikleta at sasakyan ang lane, kaya mag-ingat sa mga nagbibisikleta at bigyan sila ng puwang.","p":"Tama. Ang markang iyon ay nangangahulugang magkasama sa lane ang bisikleta at sasakyan."},"ar":{"q":"ترى رمز دراجة هوائية مع شكلين على هيئة سهم مرسومين في مسارك. ماذا يعني؟","o":["الدراجات فقط يمكنها أن تستخدم هذا المسار","الدراجات والسيارات تتشارك هذا المسار","الدراجات ممنوعة هنا","هذا المسار لوقوف الدراجات"],"h1":"العلامة موجودة في مسار سير عادي، وليست في مسار منفصل للدراجات.","h2":"الدراجة مع شكلي السهم هي علامة مسار مشترك، وتعني أن الدراجات والسيارات تتشارك المسار، لذلك انتبه لراكبي الدراجات واترك لهم مسافة.","p":"صحيح. هذه العلامة تعني أن الدراجات والسيارات تتشارك المسار."},"ht":{"q":"Ou wè yon foto bisiklèt ak de flèch an fòm V (chevwon) penti nan koulwa ou. Kisa li vle di?","o":["Se sèlman bisiklèt ki ka sèvi ak koulwa sa a","Bisiklèt ak machin pataje koulwa sa a","Bisiklèt pa gen dwa la a","Koulwa sa a se pou pake bisiklèt"],"h1":"Mak la nan yon koulwa trafik nòmal, se pa nan yon koulwa bisiklèt apa.","h2":"Yon bisiklèt ak chevwon se yon mak koulwa pataje, sa vle di bisiklèt ak machin pataje koulwa a, kidonk veye moun sou bisiklèt epi ba yo plas.","p":"Se sa. Mak sa a vle di bisiklèt ak machin pataje koulwa a."},"ref":{"doc":"FL","page":45}},{"id":"signals-028","scope":"US","cat":"signals","sign":null,"c":3,"en":{"q":"A white diamond is painted in a lane. What does it usually mean?","o":["The lane is a school zone","The lane ends soon","The lane is for slow trucks only","The lane is reserved for certain vehicles, like carpools or buses, at posted times"],"h1":"Look for a sign near the lane that tells who may use it.","h2":"A white diamond marks a reserved lane, such as a high-occupancy (HOV) lane for carpools, so you may use it only if you meet the rules posted on the signs.","p":"Right. The diamond marks a reserved lane, like a carpool lane."},"es":{"q":"Hay un diamante blanco pintado en un carril. ¿Qué suele significar?","o":["El carril es una zona escolar","El carril se termina pronto","El carril es solo para camiones lentos","El carril está reservado para ciertos vehículos, como carros compartidos o autobuses, en los horarios indicados"],"h1":"Busque una señal cerca del carril que diga quién puede usarlo.","h2":"Un diamante blanco marca un carril reservado, como un carril para vehículos con varios ocupantes (HOV), así que usted solo puede usarlo si cumple las reglas de las señales.","p":"Correcto. El diamante marca un carril reservado, como el de carros compartidos."},"zh":{"q":"车道上画着一个白色菱形。它通常是什么意思？","o":["这条车道是学校区","这条车道很快结束","这条车道只给慢速卡车","在标明的时间内，这条车道只给某些车辆用，比如拼车或公交车"],"h1":"找一找车道旁边说明谁可以用的标志。","h2":"白色菱形表示专用车道，比如给拼车用的多乘员车道（HOV），所以只有符合标志上的规定，你才可以用它。","p":"对。菱形表示专用车道，比如拼车车道。"},"vi":{"q":"Một hình thoi màu trắng được sơn trong làn. Điều đó thường có nghĩa là gì?","o":["Làn này là khu vực trường học","Làn này sắp hết","Làn này chỉ cho xe tải chạy chậm","Làn này dành riêng cho một số loại xe, như xe đi chung hoặc xe buýt, vào giờ được ghi trên biển"],"h1":"Hãy tìm biển báo gần làn cho biết ai được dùng nó.","h2":"Hình thoi màu trắng đánh dấu làn dành riêng, như làn HOV cho xe chở nhiều người đi chung, nên bạn chỉ được dùng nó nếu đúng với quy định ghi trên biển.","p":"Đúng rồi. Hình thoi đánh dấu làn dành riêng, như làn cho xe đi chung."},"tl":{"q":"May puting diyamanteng nakapinta sa isang lane. Ano ang karaniwang ibig sabihin nito?","o":["School zone ang lane","Matatapos na ang lane","Para sa mabagal na trak lang ang lane","Nakalaan ang lane para sa ilang sasakyan, tulad ng carpool o bus, sa mga oras na nakasulat sa karatula"],"h1":"Maghanap ng karatula malapit sa lane na nagsasabi kung sino ang puwedeng gumamit nito.","h2":"Ang puting diyamante ay nagmamarka ng nakalaang lane, tulad ng high-occupancy (HOV) lane para sa carpool, kaya puwede mo lang itong gamitin kung pasok ka sa mga patakarang nakasulat sa mga karatula.","p":"Tama. Ang diyamante ay nagmamarka ng nakalaang lane, tulad ng carpool lane."},"ar":{"q":"معيّن (ماسة) أبيض مرسوم في مسار. ماذا يعني عادةً؟","o":["المسار منطقة مدرسة","المسار ينتهي قريبًا","المسار للشاحنات البطيئة فقط","المسار مخصص لمركبات معيّنة، مثل السيارات المشتركة أو الحافلات، في الأوقات المكتوبة"],"h1":"ابحث عن لافتة قرب المسار تخبرك من يمكنه أن يستخدمه.","h2":"المعيّن الأبيض يدل على مسار مخصص، مثل مسار المركبات عالية الإشغال (HOV) للسيارات المشتركة، لذلك يمكنك أن تستخدمه فقط إذا كنت تتبع القواعد المكتوبة على اللافتات.","p":"صحيح. المعيّن يدل على مسار مخصص، مثل مسار السيارات المشتركة."},"ht":{"q":"Gen yon dyaman blan penti nan yon koulwa. Kisa li konn vle di?","o":["Koulwa a se yon zòn lekòl","Koulwa a ap fini talè","Koulwa a se pou kamyon ki dousman sèlman","Koulwa a rezève pou kèk machin, tankou machin ki pote plizyè moun oswa bis, nan lè ki make yo"],"h1":"Chèche yon siy toupre koulwa a ki di kiyès ki ka sèvi avè l.","h2":"Yon dyaman blan make yon koulwa rezève, tankou yon koulwa HOV pou machin ki pote plizyè moun, kidonk ou ka sèvi avè l sèlman si ou respekte règ ki ekri sou siy yo.","p":"Se sa. Dyaman an make yon koulwa rezève, tankou yon koulwa pou machin ki pote plizyè moun."},"ref":{"doc":"FL","page":69}},{"id":"signals-029","scope":"US","cat":"signals","sign":null,"c":0,"en":{"q":"A white arrow painted in your lane points only to the right. What should you do?","o":["Turn right from this lane","Go straight from this lane","Turn left from this lane","Make a U-turn from this lane"],"h1":"Arrows in a lane show which way that lane must go.","h2":"A lane arrow that points only to the right means drivers in that lane must turn right.","p":"Right. A right arrow in your lane means turn right."},"es":{"q":"Una flecha blanca pintada en su carril apunta solo a la derecha. ¿Qué debe hacer?","o":["Girar a la derecha desde este carril","Seguir derecho desde este carril","Girar a la izquierda desde este carril","Dar una vuelta en U desde este carril"],"h1":"Las flechas en un carril muestran hacia dónde debe ir ese carril.","h2":"Una flecha en el carril que apunta solo a la derecha significa que los conductores en ese carril deben girar a la derecha.","p":"Correcto. Una flecha a la derecha en su carril significa gire a la derecha."},"zh":{"q":"你的车道上画着一个只指向右边的白色箭头。你应该怎么做？","o":["从这条车道右转","从这条车道直行","从这条车道左转","从这条车道掉头"],"h1":"车道上的箭头表示这条车道必须往哪里走。","h2":"只指向右边的车道箭头表示这条车道上的司机必须右转。","p":"对。你的车道上有右转箭头，表示要右转。"},"vi":{"q":"Một mũi tên trắng sơn trong làn của bạn chỉ chỉ sang phải. Bạn nên làm gì?","o":["Rẽ phải từ làn này","Đi thẳng từ làn này","Rẽ trái từ làn này","Quay đầu xe từ làn này"],"h1":"Mũi tên trong làn cho biết làn đó phải đi hướng nào.","h2":"Mũi tên trong làn chỉ chỉ sang phải nghĩa là tài xế trong làn đó phải rẽ phải.","p":"Đúng rồi. Mũi tên phải trong làn của bạn nghĩa là rẽ phải."},"tl":{"q":"Ang puting arrow na nakapinta sa lane mo ay nakaturo lang pakanan. Ano ang dapat mong gawin?","o":["Kumanan mula sa lane na ito","Dumiretso mula sa lane na ito","Kumaliwa mula sa lane na ito","Mag-U-turn mula sa lane na ito"],"h1":"Ipinapakita ng mga arrow sa lane kung saan dapat pumunta ang lane na iyon.","h2":"Ang arrow sa lane na nakaturo lang pakanan ay nangangahulugang dapat kumanan ang mga driver sa lane na iyon.","p":"Tama. Ang arrow pakanan sa lane mo ay nangangahulugang kumanan."},"ar":{"q":"سهم أبيض مرسوم في مسارك يشير إلى اليمين فقط. ماذا يجب أن تفعل؟","o":["انعطف يمينًا من هذا المسار","سِر مستقيمًا من هذا المسار","انعطف يسارًا من هذا المسار","استدر للخلف من هذا المسار"],"h1":"الأسهم في المسار تُظهر الاتجاه الذي يجب أن يسير فيه هذا المسار.","h2":"سهم المسار الذي يشير إلى اليمين فقط يعني أن السائقين في هذا المسار يجب أن ينعطفوا يمينًا.","p":"صحيح. سهم إلى اليمين في مسارك يعني: انعطف يمينًا."},"ht":{"q":"Yon flèch blan penti nan koulwa ou montre sèlman adwat. Kisa ou dwe fè?","o":["Vire adwat nan koulwa sa a","Ale tou dwat nan koulwa sa a","Vire agoch nan koulwa sa a","Vire tounen nan koulwa sa a"],"h1":"Flèch nan yon koulwa montre ki bò koulwa sa a dwe ale.","h2":"Yon flèch nan koulwa a ki montre sèlman adwat vle di chofè nan koulwa sa a dwe vire adwat.","p":"Se sa. Yon flèch adwat nan koulwa ou vle di vire adwat."},"ref":{"doc":"FL","page":45}},{"id":"signals-030","scope":"US","cat":"signals","sign":null,"c":2,"en":{"q":"A row of white triangles is painted across your lane, pointing at you. What does it mean?","o":["Speed up to merge","The lane is for bicycles only","Yield here to traffic and people walking","You are on a one-way street the wrong way"],"h1":"The triangles look like a sign with the same shape.","h2":"A row of white triangles pointing toward you is a yield line, so you must slow down and be ready to stop there for other traffic and people walking.","p":"Right. The row of triangles is a yield line."},"es":{"q":"Una fila de triángulos blancos está pintada a lo ancho de su carril, apuntando hacia usted. ¿Qué significa?","o":["Acelere para incorporarse","El carril es solo para bicicletas","Ceda el paso aquí al tráfico y a los peatones","Usted va en contra en una calle de un solo sentido"],"h1":"Los triángulos se parecen a una señal que tiene la misma forma.","h2":"Una fila de triángulos blancos que apuntan hacia usted es una línea de ceda el paso, así que usted debe bajar la velocidad y estar listo para parar ahí por otro tráfico y por los peatones.","p":"Correcto. La fila de triángulos es una línea de ceda el paso."},"zh":{"q":"你的车道上横着画了一排白色三角形，尖角指向你。它是什么意思？","o":["加速并道","这条车道只给自行车","在这里给车辆和行人让行","你在单行道上逆行"],"h1":"这些三角形像一个形状相同的标志。","h2":"一排尖角指向你的白色三角形是让行线，所以你必须减速，准备在那里为其他车辆和行人停车。","p":"对。这排三角形是让行线。"},"vi":{"q":"Một hàng hình tam giác trắng được sơn ngang làn của bạn, mũi nhọn chỉ về phía bạn. Điều đó có nghĩa là gì?","o":["Tăng tốc để nhập làn","Làn này chỉ dành cho xe đạp","Nhường đường ở đây cho xe khác và người đi bộ","Bạn đang chạy ngược chiều trên đường một chiều"],"h1":"Các hình tam giác giống một biển báo có cùng hình dạng.","h2":"Hàng tam giác trắng chỉ về phía bạn là vạch nhường đường, nên bạn phải chạy chậm lại và sẵn sàng dừng ở đó cho xe khác và người đi bộ.","p":"Đúng rồi. Hàng tam giác đó là vạch nhường đường."},"tl":{"q":"May hanay ng mga puting tatsulok na nakapinta sa kabila ng lane mo, na nakaturo sa iyo. Ano ang ibig sabihin nito?","o":["Bumilis para makasingit","Para sa bisikleta lang ang lane","Magbigay-daan dito sa trapiko at sa mga taong naglalakad","Nasa one-way na kalye ka sa maling direksyon"],"h1":"Kamukha ng mga tatsulok ang isang karatula na may parehong hugis.","h2":"Ang hanay ng mga puting tatsulok na nakaturo sa iyo ay yield line, kaya dapat kang bumagal at maging handang huminto doon para sa ibang trapiko at sa mga taong naglalakad.","p":"Tama. Ang hanay ng mga tatsulok ay yield line."},"ar":{"q":"صف من المثلثات البيضاء مرسوم عرض مسارك، ورؤوسها تشير نحوك. ماذا يعني؟","o":["زد السرعة لتندمج","المسار للدراجات فقط","أعطِ الأولوية هنا للسيارات وللمشاة","أنت في شارع باتجاه واحد في الاتجاه الخاطئ"],"h1":"المثلثات تشبه لافتة لها نفس الشكل.","h2":"صف المثلثات البيضاء التي تشير نحوك هو خط إعطاء الأولوية، لذلك يجب أن تخفف السرعة وتكون مستعدًا للتوقف هناك من أجل السيارات الأخرى والمشاة.","p":"صحيح. صف المثلثات هو خط إعطاء الأولوية."},"ht":{"q":"Gen yon ranje ti triyang blan penti atravè koulwa ou, ak pwent yo vire sou ou. Kisa li vle di?","o":["Akselere pou antre","Koulwa a se pou bisiklèt sèlman","Bay machin ak moun k ap mache pasaj la a","Ou nan move direksyon sou yon lari yon sèl direksyon"],"h1":"Triyang yo sanble ak yon siy ki gen menm fòm nan.","h2":"Yon ranje triyang blan ki vire sou ou se yon liy pou bay pasaj, kidonk ou dwe ralanti epi pare pou kanpe la a pou lòt machin ak moun k ap mache.","p":"Se sa. Ranje triyang yo se yon liy pou bay pasaj."}},{"id":"signals-031","scope":"US","cat":"signals","sign":null,"c":1,"en":{"q":"Over a reversible lane, you see a green arrow pointing down. What does it mean?","o":["You must leave this lane","You may drive in this lane","You may not drive in this lane","The lane is only for left turns"],"h1":"Green on a lane signal means the same thing as green on a traffic light.","h2":"A green arrow pointing down over a lane means you may drive in that lane.","p":"Right. A green arrow over the lane means you may use it."},"es":{"q":"Sobre un carril reversible, usted ve una flecha verde que apunta hacia abajo. ¿Qué significa?","o":["Debe salir de este carril","Puede manejar en este carril","No puede manejar en este carril","El carril es solo para girar a la izquierda"],"h1":"El verde en una señal de carril significa lo mismo que en un semáforo.","h2":"Una flecha verde que apunta hacia abajo sobre un carril significa que usted puede manejar en ese carril.","p":"Correcto. Una flecha verde sobre el carril significa que puede usarlo."},"zh":{"q":"在可变方向车道上方，你看到一个向下的绿色箭头。它是什么意思？","o":["你必须离开这条车道","你可以在这条车道上开","你不能在这条车道上开","这条车道只能左转"],"h1":"车道信号上的绿色和红绿灯上的绿色意思一样。","h2":"车道上方向下的绿色箭头表示你可以在这条车道上开。","p":"对。车道上方的绿色箭头表示你可以用这条车道。"},"vi":{"q":"Phía trên một làn đổi chiều, bạn thấy mũi tên xanh chỉ xuống. Điều đó có nghĩa là gì?","o":["Bạn phải rời khỏi làn này","Bạn được chạy trong làn này","Bạn không được chạy trong làn này","Làn này chỉ để rẽ trái"],"h1":"Màu xanh trên đèn báo làn có nghĩa giống như màu xanh trên đèn giao thông.","h2":"Mũi tên xanh chỉ xuống phía trên một làn nghĩa là bạn được chạy trong làn đó.","p":"Đúng rồi. Mũi tên xanh phía trên làn nghĩa là bạn được dùng làn đó."},"tl":{"q":"Sa itaas ng isang reversible lane, may nakita kang berdeng arrow na nakaturo pababa. Ano ang ibig sabihin nito?","o":["Dapat kang umalis sa lane na ito","Puwede kang magmaneho sa lane na ito","Hindi ka puwedeng magmaneho sa lane na ito","Para sa pagkaliwa lang ang lane"],"h1":"Pareho ang ibig sabihin ng berde sa ilaw ng lane at ng berde sa ilaw trapiko.","h2":"Ang berdeng arrow na nakaturo pababa sa itaas ng lane ay nangangahulugang puwede kang magmaneho sa lane na iyon.","p":"Tama. Ang berdeng arrow sa itaas ng lane ay nangangahulugang puwede mo itong gamitin."},"ar":{"q":"فوق مسار متغيّر الاتجاه، ترى سهمًا أخضر يشير إلى الأسفل. ماذا يعني؟","o":["يجب أن تخرج من هذا المسار","يمكنك أن تقود في هذا المسار","لا يمكنك أن تقود في هذا المسار","المسار للانعطاف يسارًا فقط"],"h1":"الأخضر في إشارة المسار يعني نفس ما يعنيه الأخضر في إشارة المرور.","h2":"السهم الأخضر الذي يشير إلى الأسفل فوق مسار يعني أنه يمكنك أن تقود في هذا المسار.","p":"صحيح. السهم الأخضر فوق المسار يعني أنه يمكنك أن تستخدمه."},"ht":{"q":"Anwo yon koulwa ki ka chanje direksyon, ou wè yon flèch vèt ki montre anba. Kisa li vle di?","o":["Ou dwe kite koulwa sa a","Ou ka kondui nan koulwa sa a","Ou pa ka kondui nan koulwa sa a","Koulwa a se pou vire agoch sèlman"],"h1":"Vèt sou yon siyal koulwa vle di menm bagay ak vèt sou yon limyè trafik.","h2":"Yon flèch vèt ki montre anba anwo yon koulwa vle di ou ka kondui nan koulwa sa a.","p":"Se sa. Yon flèch vèt anwo koulwa a vle di ou ka sèvi avè l."},"ref":{"doc":"FL","page":53}},{"id":"signals-032","scope":"US","cat":"signals","sign":null,"c":3,"en":{"q":"Over a reversible lane, you see a red X. What does it mean?","o":["You may drive in this lane","You may pass in this lane","The lane is for buses only","Do not drive in this lane"],"h1":"Think about what a red X means anywhere.","h2":"A red X over a lane means you must not drive in that lane, because traffic may be coming the other way.","p":"Right. A red X means do not use that lane."},"es":{"q":"Sobre un carril reversible, usted ve una X roja. ¿Qué significa?","o":["Puede manejar en este carril","Puede rebasar en este carril","El carril es solo para autobuses","No maneje en este carril"],"h1":"Piense qué significa una X roja en cualquier lugar.","h2":"Una X roja sobre un carril significa que usted no debe manejar en ese carril, porque el tráfico puede venir en el otro sentido.","p":"Correcto. Una X roja significa no use ese carril."},"zh":{"q":"在可变方向车道上方，你看到一个红色的 X。它是什么意思？","o":["你可以在这条车道上开","你可以在这条车道上超车","这条车道只给公交车","不要在这条车道上开"],"h1":"想一想红色 X 在任何地方是什么意思。","h2":"车道上方的红色 X 表示你不能在这条车道上开，因为可能有车从对面开过来。","p":"对。红色 X 表示不要用这条车道。"},"vi":{"q":"Phía trên một làn đổi chiều, bạn thấy chữ X màu đỏ. Điều đó có nghĩa là gì?","o":["Bạn được chạy trong làn này","Bạn được vượt trong làn này","Làn này chỉ dành cho xe buýt","Không được chạy trong làn này"],"h1":"Hãy nghĩ xem chữ X màu đỏ ở đâu cũng có nghĩa là gì.","h2":"Chữ X đỏ phía trên một làn nghĩa là bạn không được chạy trong làn đó, vì có thể có xe đang chạy tới từ chiều ngược lại.","p":"Đúng rồi. Chữ X đỏ nghĩa là không được dùng làn đó."},"tl":{"q":"Sa itaas ng isang reversible lane, may nakita kang pulang X. Ano ang ibig sabihin nito?","o":["Puwede kang magmaneho sa lane na ito","Puwede kang mag-overtake sa lane na ito","Para sa bus lang ang lane","Huwag magmaneho sa lane na ito"],"h1":"Isipin kung ano ang ibig sabihin ng pulang X saanman.","h2":"Ang pulang X sa itaas ng lane ay nangangahulugang hindi ka dapat magmaneho sa lane na iyon, dahil maaaring may trapikong papunta mula sa kabilang direksyon.","p":"Tama. Ang pulang X ay nangangahulugang huwag gamitin ang lane na iyon."},"ar":{"q":"فوق مسار متغيّر الاتجاه، ترى حرف X أحمر. ماذا يعني؟","o":["يمكنك أن تقود في هذا المسار","يمكنك أن تتجاوز في هذا المسار","المسار للحافلات فقط","لا تقُد في هذا المسار"],"h1":"فكّر في معنى X الأحمر في أي مكان.","h2":"حرف X الأحمر فوق مسار يعني أنه يجب ألا تقود في هذا المسار، لأن السيارات قد تأتي من الاتجاه الآخر.","p":"صحيح. X الأحمر يعني: لا تستخدم هذا المسار."},"ht":{"q":"Anwo yon koulwa ki ka chanje direksyon, ou wè yon X wouj. Kisa li vle di?","o":["Ou ka kondui nan koulwa sa a","Ou ka double nan koulwa sa a","Koulwa a se pou bis sèlman","Pa kondui nan koulwa sa a"],"h1":"Panse ak sa yon X wouj vle di nenpòt kote.","h2":"Yon X wouj anwo yon koulwa vle di ou pa dwe kondui nan koulwa sa a, paske ka gen machin k ap vini nan lòt direksyon an.","p":"Se sa. Yon X wouj vle di pa sèvi ak koulwa sa a."},"ref":{"doc":"FL","page":53}},{"id":"signals-033","scope":"US","cat":"signals","sign":null,"c":0,"en":{"q":"Over a reversible lane, you see a steady yellow X. What should you do?","o":["Move out of this lane safely, because it is about to change","Stay in the lane as long as you like","Speed up in this lane","Stop in the lane and wait"],"h1":"A steady yellow X works like a steady yellow light: something is about to change.","h2":"A steady yellow X over a lane means the lane is about to close to your direction, so you should safely move out of it.","p":"Right. A steady yellow X means leave the lane safely."},"es":{"q":"Sobre un carril reversible, usted ve una X amarilla fija. ¿Qué debe hacer?","o":["Salir del carril con seguridad, porque está por cambiar","Quedarse en el carril todo el tiempo que quiera","Acelerar en este carril","Parar en el carril y esperar"],"h1":"Una X amarilla fija funciona como una luz amarilla fija: algo está por cambiar.","h2":"Una X amarilla fija sobre un carril significa que el carril se va a cerrar para su dirección, así que usted debe salir de él con seguridad.","p":"Correcto. Una X amarilla fija significa salga del carril con seguridad."},"zh":{"q":"在可变方向车道上方，你看到一个一直亮着的黄色 X。你应该怎么做？","o":["安全地离开这条车道，因为它马上要变","想在这条车道开多久就开多久","在这条车道上加速","在车道里停车等待"],"h1":"一直亮着的黄色 X 和一直亮着的黄灯一样：马上有变化。","h2":"车道上方一直亮着的黄色 X 表示这条车道马上要对你的方向关闭，所以你应该安全地离开它。","p":"对。一直亮着的黄色 X 表示要安全地离开这条车道。"},"vi":{"q":"Phía trên một làn đổi chiều, bạn thấy chữ X màu vàng sáng đứng yên. Bạn nên làm gì?","o":["Ra khỏi làn này một cách an toàn, vì làn sắp đổi","Ở trong làn bao lâu tùy thích","Tăng tốc trong làn này","Dừng lại trong làn và chờ"],"h1":"Chữ X vàng sáng đứng yên giống như đèn vàng sáng đứng yên: sắp có điều gì đó thay đổi.","h2":"Chữ X vàng sáng đứng yên phía trên một làn nghĩa là làn đó sắp đóng với chiều xe của bạn, nên bạn cần ra khỏi làn một cách an toàn.","p":"Đúng rồi. Chữ X vàng nghĩa là hãy rời khỏi làn một cách an toàn."},"tl":{"q":"Sa itaas ng isang reversible lane, may nakita kang tuloy-tuloy na dilaw na X. Ano ang dapat mong gawin?","o":["Lumabas nang ligtas sa lane na ito, dahil malapit na itong magbago","Manatili sa lane hangga't gusto mo","Bumilis sa lane na ito","Huminto sa lane at maghintay"],"h1":"Ang tuloy-tuloy na dilaw na X ay gumagana na parang tuloy-tuloy na dilaw na ilaw: may malapit nang magbago.","h2":"Ang tuloy-tuloy na dilaw na X sa itaas ng lane ay nangangahulugang malapit nang isara ang lane para sa direksyon mo, kaya dapat kang lumabas dito nang ligtas.","p":"Tama. Ang tuloy-tuloy na dilaw na X ay nangangahulugang umalis nang ligtas sa lane."},"ar":{"q":"فوق مسار متغيّر الاتجاه، ترى حرف X أصفر ثابتًا. ماذا يجب أن تفعل؟","o":["اخرج من هذا المسار بأمان، لأنه سيتغيّر بعد قليل","ابقَ في المسار كما تريد","زد السرعة في هذا المسار","توقف في المسار وانتظر"],"h1":"X الأصفر الثابت يعمل مثل الضوء الأصفر الثابت: شيء ما سيتغيّر بعد قليل.","h2":"حرف X الأصفر الثابت فوق مسار يعني أن المسار سيُغلق قريبًا أمام اتجاهك، لذلك يجب أن تخرج منه بأمان.","p":"صحيح. X الأصفر الثابت يعني: اخرج من المسار بأمان."},"ht":{"q":"Anwo yon koulwa ki ka chanje direksyon, ou wè yon X jòn fiks. Kisa ou dwe fè?","o":["Kite koulwa sa a an sekirite, paske li pral chanje","Rete nan koulwa a otan ou vle","Akselere nan koulwa sa a","Kanpe nan koulwa a epi tann"],"h1":"Yon X jòn fiks mache tankou yon limyè jòn fiks: yon bagay pral chanje.","h2":"Yon X jòn fiks anwo yon koulwa vle di koulwa a pral fèmen pou direksyon ou a, kidonk ou dwe kite l an sekirite.","p":"Se sa. Yon X jòn fiks vle di kite koulwa a an sekirite."},"ref":{"doc":"FL","page":53}},{"id":"signals-034","scope":"US","cat":"signals","sign":null,"c":2,"en":{"q":"A police officer is directing traffic at an intersection. The light is green, but the officer signals you to stop. What do you do?","o":["Go, because the light is green","Honk to get the officer to move","Stop and follow the officer","Turn right to go around the officer"],"h1":"Think about who sees the real situation at that moment.","h2":"You must follow the directions of a police officer directing traffic, even when they are different from the traffic light.","p":"Right. A police officer’s directions come before the traffic light."},"es":{"q":"Un policía está dirigiendo el tráfico en una intersección. La luz está en verde, pero el policía le indica que pare. ¿Qué hace?","o":["Seguir, porque la luz está en verde","Tocar la bocina para que el policía se mueva","Parar y seguir las indicaciones del policía","Girar a la derecha para pasar al policía"],"h1":"Piense quién ve la situación real en ese momento.","h2":"Usted debe seguir las indicaciones de un policía que dirige el tráfico, aunque sean diferentes a las del semáforo.","p":"Correcto. Las indicaciones del policía van antes que el semáforo."},"zh":{"q":"一名警察在路口指挥交通。灯是绿的，但警察示意你停车。你怎么做？","o":["开走，因为是绿灯","按喇叭让警察让开","停车，听警察的指挥","右转绕过警察"],"h1":"想一想：谁能看到当时的真实情况。","h2":"你必须服从指挥交通的警察，就算警察的指挥和红绿灯不一样也要服从。","p":"对。警察的指挥比红绿灯优先。"},"vi":{"q":"Một cảnh sát đang điều khiển giao thông ở giao lộ. Đèn đang xanh, nhưng cảnh sát ra hiệu cho bạn dừng. Bạn làm gì?","o":["Cứ đi, vì đèn đang xanh","Bấm còi để cảnh sát tránh ra","Dừng lại và làm theo cảnh sát","Rẽ phải để đi vòng qua cảnh sát"],"h1":"Hãy nghĩ xem ai đang thấy rõ tình hình thật lúc đó.","h2":"Bạn phải làm theo hướng dẫn của cảnh sát đang điều khiển giao thông, kể cả khi hướng dẫn đó khác với đèn giao thông.","p":"Đúng rồi. Hướng dẫn của cảnh sát được ưu tiên hơn đèn giao thông."},"tl":{"q":"May pulis na nagdidirekta ng trapiko sa isang interseksyon. Berde ang ilaw, pero sinesenyasan ka ng pulis na huminto. Ano ang gagawin mo?","o":["Umandar, dahil berde ang ilaw","Bumusina para umalis ang pulis","Huminto at sundin ang pulis","Kumanan para lumihis paikot sa pulis"],"h1":"Isipin kung sino ang nakakakita ng tunay na sitwasyon sa sandaling iyon.","h2":"Dapat mong sundin ang utos ng pulis na nagdidirekta ng trapiko, kahit iba ito sa sinasabi ng ilaw trapiko.","p":"Tama. Mas nauuna ang utos ng pulis kaysa sa ilaw trapiko."},"ar":{"q":"شرطي ينظّم السير في تقاطع. الإشارة خضراء، لكن الشرطي يشير لك أن تتوقف. ماذا تفعل؟","o":["انطلق، لأن الإشارة خضراء","استخدم البوق لكي يتحرك الشرطي","توقف واتبع تعليمات الشرطي","انعطف يمينًا لتمر من حول الشرطي"],"h1":"فكّر في من يرى الوضع الحقيقي في تلك اللحظة.","h2":"يجب أن تتبع تعليمات الشرطي الذي ينظّم السير، حتى عندما تكون مختلفة عن إشارة المرور.","p":"صحيح. تعليمات الشرطي تأتي قبل إشارة المرور."},"ht":{"q":"Yon polis ap dirije trafik nan yon kafou. Limyè a vèt, men polis la fè ou siy pou kanpe. Kisa ou fè?","o":["Pase, paske limyè a vèt","Klaksonen pou polis la deplase","Kanpe epi swiv polis la","Vire adwat pou pase bò kote polis la"],"h1":"Panse ak kiyès ki wè sa k ap pase vre nan moman an.","h2":"Ou dwe swiv sa yon polis k ap dirije trafik di ou, menm lè sa diferan ak limyè trafik la.","p":"Se sa. Sa polis la di pase anvan limyè trafik la."},"ref":{"doc":"FL","page":51}},{"id":"signals-035","scope":"US","cat":"signals","sign":null,"c":1,"en":{"q":"In a work zone, a flagger holds up a sign that says SLOW. What should you do?","o":["Stop and wait for a police officer","Slow down and go ahead with care, watching for workers","Keep your normal speed","Turn around and find another road"],"h1":"Think about who may be working close to the road.","h2":"A flagger showing a SLOW sign means you should slow down and go ahead with care, because workers and equipment may be near the road.","p":"Right. A SLOW paddle means slow down and drive with care."},"es":{"q":"En una zona de trabajo, un abanderado levanta un letrero que dice SLOW (despacio). ¿Qué debe hacer?","o":["Parar y esperar a un policía","Bajar la velocidad y seguir con cuidado, fijándose en los trabajadores","Mantener su velocidad normal","Dar la vuelta y buscar otra calle"],"h1":"Piense en quién puede estar trabajando cerca de la calle.","h2":"Un abanderado que muestra el letrero SLOW significa que usted debe bajar la velocidad y seguir con cuidado, porque puede haber trabajadores y máquinas cerca de la calle.","p":"Correcto. El letrero SLOW significa baje la velocidad y maneje con cuidado."},"zh":{"q":"在施工区，一名旗手举起一个写着 “SLOW”（慢行）的牌子。你应该怎么做？","o":["停车，等警察来","减速，小心往前开，注意工人","保持平常的速度","掉头另找一条路"],"h1":"想一想：谁可能在路边很近的地方工作。","h2":"旗手举着 “SLOW”（慢行）牌子，表示你应该减速，小心往前开，因为路边可能有工人和机械。","p":"对。“SLOW” 牌子表示减速，小心开车。"},"vi":{"q":"Trong khu vực thi công, người cầm biển điều khiển giao thông giơ biển ghi “SLOW” (Chạy chậm). Bạn nên làm gì?","o":["Dừng lại và chờ cảnh sát","Chạy chậm lại và đi tiếp cẩn thận, chú ý công nhân","Giữ tốc độ bình thường","Quay đầu và tìm đường khác"],"h1":"Hãy nghĩ xem ai có thể đang làm việc sát bên đường.","h2":"Người cầm biển giơ biển “SLOW” nghĩa là bạn cần chạy chậm lại và đi tiếp cẩn thận, vì công nhân và máy móc có thể ở gần đường.","p":"Đúng rồi. Biển “SLOW” nghĩa là chạy chậm lại và lái cẩn thận."},"tl":{"q":"Sa work zone, may flagger na nagtataas ng karatulang nakasulat ang “SLOW” (Bumagal). Ano ang dapat mong gawin?","o":["Huminto at maghintay ng pulis","Bumagal at magpatuloy nang maingat, habang nagbabantay sa mga trabahador","Panatilihin ang karaniwan mong bilis","Umikot pabalik at maghanap ng ibang daan"],"h1":"Isipin kung sino ang maaaring nagtatrabaho malapit sa kalsada.","h2":"Ang flagger na nagpapakita ng “SLOW” na karatula ay nangangahulugang dapat kang bumagal at magpatuloy nang maingat, dahil maaaring may mga trabahador at kagamitan malapit sa kalsada.","p":"Tama. Ang “SLOW” na paddle ay nangangahulugang bumagal at magmaneho nang maingat."},"ar":{"q":"في منطقة عمل، عامل تنظيم السير يرفع لافتة مكتوب عليها «SLOW» (ببطء). ماذا يجب أن تفعل؟","o":["توقف وانتظر شرطيًا","خفف السرعة وتابع بحذر، وانتبه للعمال","حافظ على سرعتك العادية","استدر عائدًا وابحث عن طريق آخر"],"h1":"فكّر في من قد يعمل قريبًا من الطريق.","h2":"عندما يُظهر عامل تنظيم السير لافتة «SLOW»، يجب أن تخفف السرعة وتتابع بحذر، لأن العمال والمعدات قد يكونون قرب الطريق.","p":"صحيح. لوحة «SLOW» تعني: خفف السرعة وقُد بحذر."},"ht":{"q":"Nan yon zòn travay, yon travayè ki dirije trafik la leve yon pankat ki di “SLOW” (ralanti). Kisa ou dwe fè?","o":["Kanpe epi tann yon polis","Ralanti epi kontinye avèk prekosyon, pandan w ap veye travayè yo","Kenbe vitès nòmal ou","Vire tounen epi chèche yon lòt wout"],"h1":"Panse ak kiyès ki ka ap travay toupre wout la.","h2":"Yon travayè ki montre yon pankat “SLOW” vle di ou dwe ralanti epi kontinye avèk prekosyon, paske ka gen travayè ak machin travay toupre wout la.","p":"Se sa. Yon pankat “SLOW” vle di ralanti epi kondui avèk prekosyon."},"ref":{"doc":"FL","page":54}},{"id":"signals-036","scope":"US","cat":"signals","sign":null,"c":3,"en":{"q":"A flagger in a work zone holds up a STOP sign, but the traffic light ahead is green. What should you do?","o":["Follow the green light and go","Slow down but keep moving","Pass the flagger on the shoulder","Stop and wait until the flagger lets you go"],"h1":"Think about who is in charge of traffic in a work zone.","h2":"You must obey a flagger in a work zone, so you stop when the flagger shows STOP, even if a traffic light is green.","p":"Right. A flagger’s STOP sign comes before a green light."},"es":{"q":"Un abanderado en una zona de trabajo levanta un letrero de STOP (pare), pero el semáforo de adelante está en verde. ¿Qué debe hacer?","o":["Seguir la luz verde y pasar","Bajar la velocidad pero seguir","Pasar al abanderado por el paseo","Parar y esperar hasta que el abanderado le deje pasar"],"h1":"Piense quién dirige el tráfico en una zona de trabajo.","h2":"Usted debe obedecer al abanderado en una zona de trabajo, así que para cuando el abanderado muestra STOP, aunque el semáforo esté en verde.","p":"Correcto. El letrero STOP del abanderado va antes que la luz verde."},"zh":{"q":"施工区的一名旗手举起 “STOP”（停）牌子，但前面的红绿灯是绿灯。你应该怎么做？","o":["按绿灯开走","减速但继续开","从路肩超过旗手","停车，等旗手让你走"],"h1":"想一想：在施工区里是谁在管交通。","h2":"在施工区你必须服从旗手，所以旗手举起 “STOP” 时你要停车，就算红绿灯是绿灯也一样。","p":"对。旗手的 “STOP” 牌子比绿灯优先。"},"vi":{"q":"Người cầm biển trong khu vực thi công giơ biển “STOP”, nhưng đèn giao thông phía trước đang xanh. Bạn nên làm gì?","o":["Làm theo đèn xanh và đi","Chạy chậm lại nhưng vẫn tiếp tục chạy","Vượt qua người cầm biển bằng lề đường","Dừng lại và chờ tới khi người cầm biển cho bạn đi"],"h1":"Hãy nghĩ xem ai là người điều khiển giao thông trong khu vực thi công.","h2":"Bạn phải làm theo người cầm biển trong khu vực thi công, nên bạn dừng lại khi người đó giơ biển “STOP”, kể cả khi đèn giao thông đang xanh.","p":"Đúng rồi. Biển “STOP” của người cầm biển được ưu tiên hơn đèn xanh."},"tl":{"q":"May flagger sa work zone na nagtataas ng “STOP” na karatula, pero berde ang ilaw trapiko sa unahan. Ano ang dapat mong gawin?","o":["Sundin ang berdeng ilaw at umandar","Bumagal pero magpatuloy sa pag-andar","Lampasan ang flagger sa gilid ng kalsada","Huminto at maghintay hanggang payagan ka ng flagger na umandar"],"h1":"Isipin kung sino ang namamahala sa trapiko sa work zone.","h2":"Dapat mong sundin ang flagger sa work zone, kaya huminto ka kapag ipinakita ng flagger ang “STOP”, kahit berde pa ang ilaw trapiko.","p":"Tama. Mas nauuna ang “STOP” na karatula ng flagger kaysa sa berdeng ilaw."},"ar":{"q":"عامل تنظيم السير في منطقة عمل يرفع لافتة «STOP» (قف)، لكن إشارة المرور أمامك خضراء. ماذا يجب أن تفعل؟","o":["اتبع الضوء الأخضر وانطلق","خفف السرعة لكن استمر في التحرك","تجاوز العامل من كتف الطريق","توقف وانتظر حتى يسمح لك العامل بالمرور"],"h1":"فكّر في من المسؤول عن السير في منطقة العمل.","h2":"يجب أن تطيع عامل تنظيم السير في منطقة العمل، لذلك تتوقف عندما يُظهر العامل «STOP»، حتى لو كانت إشارة المرور خضراء.","p":"صحيح. لافتة «STOP» التي يحملها العامل تأتي قبل الضوء الأخضر."},"ht":{"q":"Yon travayè ki dirije trafik nan yon zòn travay leve yon pankat “STOP”, men limyè trafik devan an vèt. Kisa ou dwe fè?","o":["Swiv limyè vèt la epi pase","Ralanti men kontinye avanse","Pase bò kote travayè a sou arebò wout la","Kanpe epi tann jiskaske travayè a kite ou pase"],"h1":"Panse ak kiyès ki responsab trafik la nan yon zòn travay.","h2":"Ou dwe obeyi travayè ki dirije trafik nan yon zòn travay, kidonk ou kanpe lè li montre “STOP”, menm si yon limyè trafik vèt.","p":"Se sa. Pankat “STOP” travayè a pase anvan yon limyè vèt."},"ref":{"doc":"FL","page":54}},{"id":"signals-037","scope":"US","cat":"signals","sign":null,"c":0,"en":{"q":"Which should you obey first: a traffic light, a stop sign, or a police officer directing traffic?","o":["The police officer","The traffic light","The stop sign","Whichever is closest to you"],"h1":"Signs and lights are set ahead of time. Think about who can react to what is happening now.","h2":"A police officer directing traffic comes first, before any traffic light or sign, because the officer is handling what is happening right now.","p":"Right. An officer directing traffic comes before lights and signs."},"es":{"q":"¿A quién debe obedecer primero: a un semáforo, a una señal de pare o a un policía que dirige el tráfico?","o":["Al policía","Al semáforo","A la señal de pare","Al que esté más cerca de usted"],"h1":"Las señales y los semáforos se ponen con anticipación. Piense quién puede reaccionar a lo que pasa ahora.","h2":"Un policía que dirige el tráfico va primero, antes que cualquier semáforo o señal, porque el policía maneja lo que está pasando en ese momento.","p":"Correcto. Un policía que dirige el tráfico va antes que los semáforos y las señales."},"zh":{"q":"红绿灯、停车标志、指挥交通的警察，你应该先服从哪一个？","o":["警察","红绿灯","停车标志","离你最近的那一个"],"h1":"标志和灯是提前设定好的。想一想谁能对眼前发生的事做出反应。","h2":"指挥交通的警察最优先，比任何红绿灯或标志都优先，因为警察在处理眼前正在发生的情况。","p":"对。指挥交通的警察比灯和标志优先。"},"vi":{"q":"Bạn nên làm theo điều nào trước tiên: đèn giao thông, biển dừng, hay cảnh sát đang điều khiển giao thông?","o":["Cảnh sát","Đèn giao thông","Biển dừng","Cái nào gần bạn nhất"],"h1":"Biển và đèn được cài đặt từ trước. Hãy nghĩ xem ai có thể phản ứng với điều đang xảy ra ngay lúc này.","h2":"Cảnh sát đang điều khiển giao thông được ưu tiên trước, hơn mọi đèn giao thông hay biển báo, vì cảnh sát đang xử lý điều đang xảy ra ngay lúc đó.","p":"Đúng rồi. Cảnh sát điều khiển giao thông được ưu tiên hơn đèn và biển báo."},"tl":{"q":"Alin ang dapat mong unang sundin: ang ilaw trapiko, ang “STOP” sign, o ang pulis na nagdidirekta ng trapiko?","o":["Ang pulis","Ang ilaw trapiko","Ang “STOP” sign","Kung alin ang pinakamalapit sa iyo"],"h1":"Ang mga karatula at ilaw ay nakatakda na nang maaga. Isipin kung sino ang nakakatugon sa nangyayari ngayon.","h2":"Ang pulis na nagdidirekta ng trapiko ang nauuna, bago ang anumang ilaw trapiko o karatula, dahil hinaharap ng pulis ang nangyayari mismo sa sandaling iyon.","p":"Tama. Mas nauuna ang pulis na nagdidirekta ng trapiko kaysa sa mga ilaw at karatula."},"ar":{"q":"أيها يجب أن تطيع أولًا: إشارة المرور، أم لافتة «STOP» (قف)، أم شرطي ينظّم السير؟","o":["الشرطي","إشارة المرور","لافتة «STOP»","أيها أقرب إليك"],"h1":"اللافتات والإشارات مضبوطة مسبقًا. فكّر في من يستطيع أن يتصرف حسب ما يحدث الآن.","h2":"الشرطي الذي ينظّم السير يأتي أولًا، قبل أي إشارة مرور أو لافتة، لأنه يتعامل مع ما يحدث الآن.","p":"صحيح. الشرطي الذي ينظّم السير يأتي قبل الإشارات واللافتات."},"ht":{"q":"Kiyès ou dwe obeyi anvan: yon limyè trafik, yon siy “STOP”, oswa yon polis k ap dirije trafik?","o":["Polis la","Limyè trafik la","Siy “STOP” la","Sa ki pi pre ou a"],"h1":"Siy ak limyè yo regle davans. Panse ak kiyès ki ka reyaji ak sa k ap pase kounye a.","h2":"Yon polis k ap dirije trafik pase anvan, devan nenpòt limyè trafik oswa siy, paske polis la ap jere sa k ap pase kounye a menm.","p":"Se sa. Yon polis k ap dirije trafik pase anvan limyè ak siy yo."},"ref":{"doc":"FL","page":51}},{"id":"signals-038","scope":"US","cat":"signals","sign":null,"c":2,"en":{"q":"On a divided highway, what color is the solid line along the left edge of your lanes?","o":["White","Blue","Yellow","Red"],"h1":"Think about which color is used for the side closest to traffic going the other way.","h2":"On a divided highway, the left edge line is yellow and the right edge line is white, which helps you see the side toward opposite traffic.","p":"Right. The left edge line is yellow; the right edge line is white."},"es":{"q":"En una autopista dividida, ¿de qué color es la línea continua del borde izquierdo de sus carriles?","o":["Blanca","Azul","Amarilla","Roja"],"h1":"Piense qué color se usa para el lado más cerca del tráfico que va en sentido contrario.","h2":"En una autopista dividida, la línea del borde izquierdo es amarilla y la del borde derecho es blanca, lo que le ayuda a ver el lado del tráfico contrario.","p":"Correcto. La línea del borde izquierdo es amarilla; la del derecho es blanca."},"zh":{"q":"在分隔公路上，你的车道左边缘的实线是什么颜色？","o":["白色","蓝色","黄色","红色"],"h1":"想一想：靠近对向车流的那一边用什么颜色。","h2":"在分隔公路上，左边缘线是黄色，右边缘线是白色，这能帮你看清哪一边靠近对向车流。","p":"对。左边缘线是黄色，右边缘线是白色。"},"vi":{"q":"Trên đường có dải phân cách, vạch liền dọc theo mép trái các làn của bạn có màu gì?","o":["Trắng","Xanh dương","Vàng","Đỏ"],"h1":"Hãy nghĩ xem màu nào được dùng cho phía gần xe chạy ngược chiều nhất.","h2":"Trên đường có dải phân cách, vạch mép trái màu vàng và vạch mép phải màu trắng, giúp bạn nhận ra phía có xe chạy ngược chiều.","p":"Đúng rồi. Vạch mép trái màu vàng; vạch mép phải màu trắng."},"tl":{"q":"Sa divided highway, anong kulay ang tuloy-tuloy na linya sa kaliwang gilid ng mga lane mo?","o":["Puti","Asul","Dilaw","Pula"],"h1":"Isipin kung aling kulay ang ginagamit para sa bahaging pinakamalapit sa trapikong papunta sa kabilang direksyon.","h2":"Sa divided highway, dilaw ang linya sa kaliwang gilid at puti ang linya sa kanang gilid, na tumutulong sa iyo na makita ang bahaging nakaharap sa kasalungat na trapiko.","p":"Tama. Dilaw ang linya sa kaliwang gilid; puti ang linya sa kanang gilid."},"ar":{"q":"في طريق سريع مقسوم، ما لون الخط المتصل على الحافة اليسرى لمساراتك؟","o":["أبيض","أزرق","أصفر","أحمر"],"h1":"فكّر في اللون الذي يُستخدم للجانب الأقرب إلى السيارات التي تسير في الاتجاه الآخر.","h2":"في الطريق السريع المقسوم، خط الحافة اليسرى أصفر وخط الحافة اليمنى أبيض، وهذا يساعدك على رؤية الجانب القريب من السيارات المعاكسة.","p":"صحيح. خط الحافة اليسرى أصفر، وخط الحافة اليمنى أبيض."},"ht":{"q":"Sou yon wout ki gen separasyon, ki koulè liy plen ki sou bò goch koulwa ou yo?","o":["Blan","Ble","Jòn","Wouj"],"h1":"Panse ak ki koulè yo sèvi pou bò ki pi pre machin k ap ale nan lòt direksyon an.","h2":"Sou yon wout ki gen separasyon, liy bò goch la jòn epi liy bò dwat la blan, sa ki ede ou wè bò ki vire sou machin k ap ale nan direksyon opoze a.","p":"Se sa. Liy bò goch la jòn; liy bò dwat la blan."},"ref":{"doc":"FL","page":43}},{"id":"signs-001","scope":"US","cat":"signs","sign":{"shape":"stop","text":"STOP"},"c":0,"en":{"q":"A red sign has eight sides. What must you do?","o":["Stop fully, then go when it is safe","Slow down, and stop only if cars come","Get ready for road work ahead","Watch for a school zone ahead"],"h1":"Think about the only sign with eight sides.","h2":"An eight-sided red sign is a stop sign, so you must come to a full stop and go only when the way is clear.","p":"Right. Eight sides means stop fully, then go when safe."},"es":{"q":"Una señal roja tiene ocho lados. ¿Qué debe hacer?","o":["Pararse por completo y seguir cuando sea seguro","Bajar la velocidad y pararse solo si vienen carros","Prepararse para obras en la vía","Estar atento a una zona escolar"],"h1":"Piense en la única señal que tiene ocho lados.","h2":"Una señal roja de ocho lados es la señal de pare, así que usted debe pararse por completo y seguir solo cuando el camino esté libre.","p":"Correcto. Ocho lados significa pararse por completo y seguir cuando sea seguro."},"zh":{"q":"一个红色标志有八条边。你必须怎么做？","o":["完全停车，安全时再走","减速，只有来车时才停","准备好，前方有道路施工","注意，前方有学校区"],"h1":"想一想：只有一种标志有八条边。","h2":"八边形的红色标志是停车标志，所以你必须完全停车，路上没有车和人时才能走。","p":"对。八条边表示完全停车，安全时再走。"},"vi":{"q":"Một biển báo màu đỏ có tám cạnh. Bạn phải làm gì?","o":["Dừng hẳn, rồi đi khi an toàn","Chạy chậm lại, và chỉ dừng nếu có xe tới","Chuẩn bị cho đoạn đường đang sửa phía trước","Chú ý khu vực trường học phía trước"],"h1":"Hãy nghĩ đến biển báo duy nhất có tám cạnh.","h2":"Biển báo đỏ có tám cạnh là biển “STOP” (Dừng lại), nên bạn phải dừng hẳn và chỉ đi khi đường đã trống.","p":"Đúng rồi. Tám cạnh nghĩa là dừng hẳn, rồi đi khi an toàn."},"tl":{"q":"May pulang karatula na may walong gilid. Ano ang dapat mong gawin?","o":["Huminto nang buo, saka umandar kapag ligtas na","Bumagal, at huminto lang kung may dumarating na sasakyan","Maghanda sa ginagawang kalsada sa unahan","Mag-ingat sa school zone sa unahan"],"h1":"Isipin ang nag-iisang karatula na may walong gilid.","h2":"Ang pulang karatula na may walong gilid ay “STOP” sign (Huminto), kaya dapat kang huminto nang buo at umandar lang kapag maluwag na ang daan.","p":"Tama. Ang walong gilid ay nangangahulugang huminto nang buo, saka umandar kapag ligtas."},"ar":{"q":"لافتة حمراء لها ثمانية أضلاع. ماذا يجب أن تفعل؟","o":["توقف تمامًا، ثم انطلق عندما يكون الطريق آمنًا","خفف السرعة، وتوقف فقط إذا جاءت سيارات","استعد لأعمال طرق في الأمام","انتبه لمنطقة مدرسة في الأمام"],"h1":"فكّر في اللافتة الوحيدة التي لها ثمانية أضلاع.","h2":"اللافتة الحمراء ذات الأضلاع الثمانية هي لافتة «STOP» (قف)، لذلك يجب أن تتوقف تمامًا ولا تنطلق إلا عندما يكون الطريق خاليًا.","p":"صحيح. ثمانية أضلاع تعني: توقف تمامًا، ثم انطلق عندما يكون الطريق آمنًا."},"ht":{"q":"Gen yon siy wouj ki gen uit kote. Kisa ou dwe fè?","o":["Kanpe nèt, epi pati lè sa an sekirite","Ralanti, epi kanpe sèlman si gen machin k ap vini","Prepare ou pou travay sou wout la pi devan","Veye yon zòn lekòl pi devan"],"h1":"Panse ak sèl siy ki gen uit kote a.","h2":"Yon siy wouj ki gen uit kote se yon siy “STOP” (kanpe), kidonk ou dwe kanpe nèt epi pati sèlman lè wout la lib.","p":"Se sa. Uit kote vle di kanpe nèt, epi pati lè sa an sekirite."},"ref":{"doc":"FL","page":47}},{"id":"signs-002","scope":"US","cat":"signs","sign":{"shape":"yield","text":"YIELD"},"c":1,"en":{"q":"What does a red and white triangle pointing down mean?","o":["Stop every time, even if the road is clear","Slow down, let others go first, stop if needed","Speed up so you can merge quickly","The road ends just ahead"],"h1":"This sign is about who goes first.","h2":"The upside-down triangle is a yield sign, so you slow down, let other traffic go first, and stop if you need to.","p":"Right. Yield means slow down and let others go first."},"es":{"q":"¿Qué significa un triángulo rojo y blanco con la punta hacia abajo?","o":["Pararse siempre, aunque la vía esté libre","Bajar la velocidad, dejar pasar a otros y parar si hace falta","Acelerar para entrar rápido al tráfico","La vía se termina más adelante"],"h1":"Esta señal trata de quién pasa primero.","h2":"El triángulo con la punta hacia abajo es la señal de ceda el paso, así que usted baja la velocidad, deja pasar a los demás y se para si hace falta.","p":"Correcto. Ceda el paso significa bajar la velocidad y dejar pasar a otros."},"zh":{"q":"一个尖角朝下的红白三角形标志是什么意思？","o":["每次都要停车，路上没车也要停","减速，让别人先走，需要时停车","加速，以便快速并道","道路就在前方结束"],"h1":"这个标志说的是谁先走。","h2":"倒三角形是让行标志，所以你要减速，让其他车先走，需要时停车。","p":"对。让行表示减速，让别人先走。"},"vi":{"q":"Biển hình tam giác đỏ trắng, mũi nhọn chỉ xuống, có nghĩa là gì?","o":["Lúc nào cũng phải dừng, dù đường trống","Chạy chậm lại, nhường người khác đi trước, dừng nếu cần","Tăng tốc để nhập làn cho nhanh","Con đường sắp hết ngay phía trước"],"h1":"Biển này nói về việc ai được đi trước.","h2":"Tam giác chỉ xuống là biển “YIELD” (Nhường đường), nên bạn chạy chậm lại, để xe khác đi trước, và dừng nếu cần.","p":"Đúng rồi. Nhường đường nghĩa là chạy chậm lại và để người khác đi trước."},"tl":{"q":"Ano ang ibig sabihin ng pula at puting tatsulok na nakaturo pababa?","o":["Huminto palagi, kahit maluwag ang daan","Bumagal, paunahin ang iba, huminto kung kailangan","Bumilis para mabilis kang makasingit","Matatapos na ang kalsada sa unahan"],"h1":"Ang karatulang ito ay tungkol sa kung sino ang mauuna.","h2":"Ang baligtad na tatsulok ay “YIELD” sign (Magbigay-daan), kaya babagal ka, paunahin mo ang ibang sasakyan, at huminto ka kung kailangan.","p":"Tama. Ang “YIELD” ay nangangahulugang bumagal at paunahin ang iba."},"ar":{"q":"ماذا يعني مثلث أحمر وأبيض رأسه إلى الأسفل؟","o":["توقف في كل مرة، حتى لو كان الطريق خاليًا","خفف السرعة، ودع الآخرين يمرون أولًا، وتوقف إذا لزم الأمر","زد السرعة لكي تندمج بسرعة","الطريق ينتهي بعد قليل"],"h1":"هذه اللافتة تتعلق بمن يمر أولًا.","h2":"المثلث المقلوب هو لافتة «YIELD» (أعطِ الأولوية)، لذلك تخفف السرعة، وتترك السيارات الأخرى تمر أولًا، وتتوقف إذا احتجت إلى ذلك.","p":"صحيح. «YIELD» تعني: خفف السرعة ودع الآخرين يمرون أولًا."},"ht":{"q":"Kisa yon triyang wouj ak blan ki gen pwent li anba vle di?","o":["Kanpe chak fwa, menm si wout la lib","Ralanti, kite lòt yo pase anvan, kanpe si sa nesesè","Akselere pou ou ka antre vit","Wout la fini touprè"],"h1":"Siy sa a pale de kiyès ki pase anvan.","h2":"Triyang ki tèt anba a se yon siy “YIELD” (bay pasaj), kidonk ou ralanti, ou kite lòt machin yo pase anvan, epi ou kanpe si ou bezwen.","p":"Se sa. “YIELD” vle di ralanti epi kite lòt yo pase anvan."},"ref":{"doc":"FL","page":47}},{"id":"signs-003","scope":"US","cat":"signs","sign":{"shape":"school","text":"SCHOOL"},"c":2,"en":{"q":"What does a sign with five sides warn you about?","o":["A railroad crossing ahead","A hospital nearby","A school zone or school crossing","A no-passing zone"],"h1":"Think about who you may see walking near this sign.","h2":"A five-sided sign marks a school zone or a school crossing, so you should slow down and watch for children.","p":"Right. Five sides means a school is near."},"es":{"q":"¿Sobre qué le avisa una señal de cinco lados?","o":["Un cruce de tren más adelante","Un hospital cerca","Una zona escolar o un cruce escolar","Una zona donde no se puede rebasar"],"h1":"Piense en quiénes podrían caminar cerca de esta señal.","h2":"Una señal de cinco lados marca una zona escolar o un cruce escolar, así que usted debe bajar la velocidad y estar atento a los niños.","p":"Correcto. Cinco lados significa que hay una escuela cerca."},"zh":{"q":"有五条边的标志提醒你注意什么？","o":["前方有铁路道口","附近有医院","学校区或学校人行横道","禁止超车区"],"h1":"想一想：你在这个标志附近可能看到谁在走路。","h2":"五边形标志表示学校区或学校人行横道，所以你要减速，注意儿童。","p":"对。五条边表示附近有学校。"},"vi":{"q":"Biển báo có năm cạnh cảnh báo bạn về điều gì?","o":["Có chỗ băng qua đường sắt phía trước","Có bệnh viện gần đây","Khu vực trường học hoặc chỗ học sinh qua đường","Khu vực cấm vượt"],"h1":"Hãy nghĩ xem ai có thể đang đi bộ gần biển này.","h2":"Biển có năm cạnh báo hiệu khu vực trường học hoặc chỗ học sinh qua đường, nên bạn cần chạy chậm lại và chú ý trẻ em.","p":"Đúng rồi. Năm cạnh nghĩa là gần trường học."},"tl":{"q":"Tungkol saan ang babala ng karatula na may limang gilid?","o":["Tawiran ng tren sa unahan","May ospital sa malapit","School zone o tawiran ng mga estudyante","Lugar na bawal mag-overtake"],"h1":"Isipin kung sino ang maaaring makita mong naglalakad malapit sa karatulang ito.","h2":"Ang karatula na may limang gilid ay nagmamarka ng school zone o tawiran ng mga estudyante, kaya dapat kang bumagal at mag-ingat sa mga bata.","p":"Tama. Ang limang gilid ay nangangahulugang may paaralan sa malapit."},"ar":{"q":"ممّ تحذّرك لافتة لها خمسة أضلاع؟","o":["من تقاطع مع سكة حديد في الأمام","من مستشفى قريب","من منطقة مدرسة أو معبر مدرسة","من منطقة ممنوع فيها التجاوز"],"h1":"فكّر في من قد تراه يمشي قرب هذه اللافتة.","h2":"اللافتة ذات الأضلاع الخمسة تدل على منطقة مدرسة أو معبر مدرسة، لذلك يجب أن تخفف السرعة وتنتبه للأطفال.","p":"صحيح. خمسة أضلاع تعني أن هناك مدرسة قريبة."},"ht":{"q":"Yon siy ki gen senk kote avèti ou pou kisa?","o":["Yon kote tren travèse pi devan","Yon lopital touprè","Yon zòn lekòl oswa yon kote timoun lekòl travèse","Yon zòn kote ou pa ka double"],"h1":"Panse ak kiyès ou ka wè k ap mache toupre siy sa a.","h2":"Yon siy ki gen senk kote make yon zòn lekòl oswa yon kote timoun lekòl travèse, kidonk ou dwe ralanti epi veye timoun yo.","p":"Se sa. Senk kote vle di gen yon lekòl toupre."},"ref":{"doc":"FL","page":57}},{"id":"signs-004","scope":"US","cat":"signs","sign":{"shape":"rr-advance","text":"RR"},"c":3,"en":{"q":"What does a round yellow sign with an X and two R letters mean?","o":["A traffic circle is ahead","A bus stop is ahead","A rest area is ahead","A railroad crossing is ahead"],"h1":"The two letters stand for a kind of track.","h2":"The round yellow sign warns that a railroad crossing is ahead, so you should slow down, look, listen, and be ready to stop.","p":"Right. The round yellow sign warns of a railroad crossing ahead."},"es":{"q":"¿Qué significa una señal amarilla y redonda con una X y dos letras R?","o":["Hay una rotonda más adelante","Hay una parada de autobús más adelante","Hay un área de descanso más adelante","Hay un cruce de tren más adelante"],"h1":"Las dos letras se refieren a un tipo de vía.","h2":"La señal amarilla y redonda avisa que hay un cruce de tren más adelante, así que usted debe bajar la velocidad, mirar, escuchar y estar listo para parar.","p":"Correcto. La señal amarilla y redonda avisa de un cruce de tren."},"zh":{"q":"一个黄色圆形标志，上面有一个 X 和两个字母 R，是什么意思？","o":["前方有环形交叉路口","前方有公交车站","前方有休息区","前方有铁路道口"],"h1":"这两个字母代表一种轨道。","h2":"黄色圆形标志提醒你前方有铁路道口，所以你要减速，看一看，听一听，准备停车。","p":"对。黄色圆形标志提醒你前方有铁路道口。"},"vi":{"q":"Biển tròn màu vàng có chữ X và hai chữ R có nghĩa là gì?","o":["Phía trước có vòng xuyến","Phía trước có trạm xe buýt","Phía trước có trạm dừng nghỉ","Phía trước có chỗ băng qua đường sắt"],"h1":"Hai chữ cái này nói về một loại đường ray.","h2":"Biển tròn màu vàng cảnh báo phía trước có chỗ băng qua đường sắt, nên bạn cần chạy chậm lại, nhìn, nghe, và sẵn sàng dừng.","p":"Đúng rồi. Biển tròn màu vàng cảnh báo phía trước có đường sắt."},"tl":{"q":"Ano ang ibig sabihin ng bilog na dilaw na karatula na may X at dalawang letrang R?","o":["May rotonda sa unahan","May hintuan ng bus sa unahan","May pahingahan sa unahan","May tawiran ng tren sa unahan"],"h1":"Ang dalawang letra ay tumutukoy sa isang uri ng riles.","h2":"Ang bilog na dilaw na karatula ay babala na may tawiran ng tren sa unahan, kaya dapat kang bumagal, tumingin, makinig, at maging handang huminto.","p":"Tama. Ang bilog na dilaw na karatula ay babala na may tawiran ng tren sa unahan."},"ar":{"q":"ماذا تعني لافتة صفراء مستديرة عليها حرف X وحرفا R؟","o":["دوّار مروري في الأمام","موقف حافلات في الأمام","استراحة في الأمام","تقاطع مع سكة حديد في الأمام"],"h1":"الحرفان يرمزان إلى نوع من القضبان.","h2":"اللافتة الصفراء المستديرة تحذّر من تقاطع مع سكة حديد في الأمام، لذلك يجب أن تخفف السرعة، وتنظر، وتستمع، وتستعد للتوقف.","p":"صحيح. اللافتة الصفراء المستديرة تحذّر من تقاطع مع سكة حديد في الأمام."},"ht":{"q":"Kisa yon siy jòn won ki gen yon X ak de lèt R vle di?","o":["Gen yon wonpwen pi devan","Gen yon arè bis pi devan","Gen yon zòn repo pi devan","Gen yon kote tren travèse pi devan"],"h1":"De lèt yo kanpe pou yon kalite ray.","h2":"Siy jòn won an avèti ou gen yon kote tren travèse pi devan, kidonk ou dwe ralanti, gade, koute, epi pare pou kanpe.","p":"Se sa. Siy jòn won an avèti ou gen yon kote tren travèse pi devan."},"ref":{"doc":"FL","page":56}},{"id":"signs-005","scope":"US","cat":"signs","sign":{"shape":"crossbuck","text":"RAILROAD CROSSING"},"c":0,"en":{"q":"At the tracks you see a white X-shaped sign. What should you do?","o":["Treat it like a yield sign and look for trains","Speed up to get across the tracks fast","Change lanes before you reach the tracks","Ignore it unless it is dark outside"],"h1":"Think about what could be coming down the tracks.","h2":"The white X sign is a railroad crossbuck, and it works like a yield sign, so you slow down, look both ways, and stop if a train is coming.","p":"Right. The crossbuck means yield to trains."},"es":{"q":"En la vía del tren ve una señal blanca en forma de X. ¿Qué debe hacer?","o":["Tratarla como un ceda el paso y buscar trenes","Acelerar para cruzar la vía rápido","Cambiar de carril antes de la vía","No hacerle caso a menos que sea de noche"],"h1":"Piense en lo que podría venir por la vía.","h2":"La señal blanca en forma de X es la cruz de ferrocarril, y funciona como un ceda el paso, así que usted baja la velocidad, mira a ambos lados y se para si viene un tren.","p":"Correcto. La cruz de ferrocarril significa ceder el paso a los trenes."},"zh":{"q":"在铁轨旁，你看到一个白色 X 形标志。你应该怎么做？","o":["把它当作让行标志，注意火车","加速，快快穿过铁轨","到铁轨前先换车道","不用管它，除非天黑"],"h1":"想一想：铁轨上可能开来什么。","h2":"白色 X 形标志是铁路交叉标志，它的作用和让行标志一样，所以你要减速，看两边，如果有火车开来就停车。","p":"对。铁路交叉标志表示给火车让行。"},"vi":{"q":"Tại đường ray, bạn thấy một biển màu trắng hình chữ X. Bạn nên làm gì?","o":["Làm như gặp biển nhường đường và nhìn xem có tàu không","Tăng tốc để qua đường ray thật nhanh","Đổi làn trước khi tới đường ray","Bỏ qua biển, trừ khi trời tối"],"h1":"Hãy nghĩ xem cái gì có thể đang chạy tới trên đường ray.","h2":"Biển chữ X màu trắng là biển báo đường sắt (crossbuck), và nó giống như biển nhường đường, nên bạn chạy chậm lại, nhìn cả hai phía, và dừng nếu có tàu đang tới.","p":"Đúng rồi. Biển chữ X nghĩa là phải nhường đường cho tàu."},"tl":{"q":"Sa may riles, may nakita kang puting karatula na hugis X. Ano ang dapat mong gawin?","o":["Ituring itong parang “YIELD” sign at tumingin kung may tren","Bumilis para mabilis na makatawid sa riles","Lumipat ng linya bago ka umabot sa riles","Huwag pansinin maliban kung madilim na"],"h1":"Isipin kung ano ang puwedeng dumaan sa riles.","h2":"Ang puting karatulang X ay tinatawag na crossbuck ng riles, at gumagana ito na parang “YIELD” sign, kaya babagal ka, titingin sa magkabilang direksyon, at hihinto kung may paparating na tren.","p":"Tama. Ang crossbuck ay nangangahulugang magbigay-daan sa tren."},"ar":{"q":"عند سكة الحديد ترى لافتة بيضاء على شكل حرف X. ماذا يجب أن تفعل؟","o":["تعامل معها مثل لافتة إعطاء الأولوية وانظر هل يأتي قطار","زد السرعة لتعبر السكة بسرعة","غيّر المسار قبل أن تصل إلى السكة","تجاهلها إلا إذا كان الجو مظلمًا"],"h1":"فكّر في ما قد يأتي على السكة.","h2":"اللافتة البيضاء على شكل X هي علامة تقاطع سكة الحديد، وهي تعمل مثل لافتة إعطاء الأولوية، لذلك تخفف السرعة، وتنظر في الاتجاهين، وتتوقف إذا كان قطار قادمًا.","p":"صحيح. علامة X عند السكة تعني: أعطِ الأولوية للقطارات."},"ht":{"q":"Bò ray tren an, ou wè yon siy blan ki gen fòm yon X. Kisa ou dwe fè?","o":["Fè l tankou yon siy “YIELD” epi gade si gen tren","Akselere pou travèse ray yo vit","Chanje koulwa anvan ou rive nan ray yo","Pa okipe l sof si fè nwa deyò"],"h1":"Panse ak sa ki ka ap vini sou ray yo.","h2":"Siy blan an fòm X la se yon kwa tren (crossbuck), e li mache tankou yon siy “YIELD”, kidonk ou ralanti, ou gade de bò yo, epi ou kanpe si gen yon tren k ap vini.","p":"Se sa. Kwa tren an vle di bay tren yo pasaj."},"ref":{"doc":"FL","page":56}},{"id":"signs-006","scope":"US","cat":"signs","sign":{"shape":"diamond-yellow"},"c":1,"en":{"q":"What does a yellow diamond-shaped sign usually do?","o":["Gives you directions to a city","Warns you about a hazard or change ahead","Tells you the speed limit","Shows you a place to eat"],"h1":"Think about why a sign would use a bright yellow color.","h2":"A yellow diamond is a warning sign, so it tells you about a hazard or a change in the road ahead.","p":"Right. A yellow diamond warns you about something ahead."},"es":{"q":"¿Qué hace normalmente una señal amarilla en forma de rombo?","o":["Le da direcciones hacia una ciudad","Le avisa de un peligro o un cambio más adelante","Le dice el límite de velocidad","Le muestra un lugar para comer"],"h1":"Piense en por qué una señal usaría un amarillo fuerte.","h2":"Un rombo amarillo es una señal de advertencia, así que le avisa de un peligro o de un cambio en la vía más adelante.","p":"Correcto. Un rombo amarillo le avisa de algo más adelante."},"zh":{"q":"黄色菱形标志通常有什么作用？","o":["告诉你去某个城市的方向","提醒你前方有危险或变化","告诉你限速","告诉你哪里可以吃饭"],"h1":"想一想：标志为什么要用很亮的黄色。","h2":"黄色菱形标志是警告标志，它告诉你前方道路有危险或变化。","p":"对。黄色菱形标志提醒你注意前方。"},"vi":{"q":"Biển hình thoi màu vàng thường dùng để làm gì?","o":["Chỉ đường tới một thành phố","Cảnh báo nguy hiểm hoặc thay đổi phía trước","Cho biết tốc độ tối đa","Chỉ chỗ ăn uống"],"h1":"Hãy nghĩ xem vì sao một biển báo lại dùng màu vàng tươi.","h2":"Biển hình thoi màu vàng là biển cảnh báo, nên nó cho bạn biết có nguy hiểm hoặc đường thay đổi ở phía trước.","p":"Đúng rồi. Biển hình thoi màu vàng cảnh báo điều gì đó phía trước."},"tl":{"q":"Ano ang karaniwang ginagawa ng dilaw na karatula na hugis diyamante?","o":["Nagbibigay ng direksyon papunta sa isang lungsod","Nagbababala tungkol sa panganib o pagbabago sa unahan","Nagsasabi ng speed limit","Nagpapakita ng lugar na makakainan"],"h1":"Isipin kung bakit gagamit ang karatula ng matingkad na dilaw na kulay.","h2":"Ang dilaw na diyamante ay karatula ng babala, kaya sinasabi nito sa iyo na may panganib o pagbabago sa kalsada sa unahan.","p":"Tama. Ang dilaw na diyamante ay nagbababala tungkol sa isang bagay sa unahan."},"ar":{"q":"ما الذي تفعله عادةً لافتة صفراء على شكل معيّن (ماسة)؟","o":["تعطيك الاتجاه إلى مدينة","تحذّرك من خطر أو تغيير في الأمام","تخبرك بالحد الأقصى للسرعة","تدلّك على مكان للأكل"],"h1":"فكّر لماذا تستخدم اللافتة لونًا أصفر لامعًا.","h2":"المعيّن الأصفر هو لافتة تحذير، فهو يخبرك بوجود خطر أو تغيير في الطريق أمامك.","p":"صحيح. المعيّن الأصفر يحذّرك من شيء في الأمام."},"ht":{"q":"Kisa yon siy jòn ki gen fòm dyaman (lozanj) konn fè?","o":["Li ba ou direksyon pou yon vil","Li avèti ou gen yon danje oswa yon chanjman pi devan","Li di ou limit vitès la","Li montre ou yon kote pou manje"],"h1":"Panse poukisa yon siy ta sèvi ak yon koulè jòn klè.","h2":"Yon dyaman jòn se yon siy avètisman, kidonk li di ou gen yon danje oswa yon chanjman sou wout la pi devan.","p":"Se sa. Yon dyaman jòn avèti ou pou yon bagay pi devan."},"ref":{"doc":"FL","page":49}},{"id":"signs-007","scope":"US","cat":"signs","sign":{"shape":"diamond-orange","text":"ROAD WORK AHEAD"},"c":2,"en":{"q":"Orange signs tell you about what?","o":["School zones","Parks and campgrounds","Road work and work zones","Gas and food"],"h1":"Think about where you see orange cones and workers.","h2":"Orange signs are used for road work and work zones, so you should slow down and watch for workers and changes.","p":"Right. Orange signs mean road work."},"es":{"q":"¿De qué le avisan las señales anaranjadas?","o":["De zonas escolares","De parques y campamentos","De obras y zonas de trabajo en la vía","De gasolina y comida"],"h1":"Piense en dónde ve conos anaranjados y trabajadores.","h2":"Las señales anaranjadas se usan para obras y zonas de trabajo en la vía, así que usted debe bajar la velocidad y estar atento a los trabajadores y a los cambios.","p":"Correcto. Las señales anaranjadas significan obras en la vía."},"zh":{"q":"橙色标志告诉你什么？","o":["学校区","公园和露营地","道路施工和施工区","加油和吃饭"],"h1":"想一想：你在哪里会看到橙色锥桶和工人。","h2":"橙色标志用于道路施工和施工区，所以你要减速，注意工人和道路变化。","p":"对。橙色标志表示道路施工。"},"vi":{"q":"Biển báo màu cam cho bạn biết về điều gì?","o":["Khu vực trường học","Công viên và khu cắm trại","Đường đang sửa và khu vực thi công","Xăng và đồ ăn"],"h1":"Hãy nghĩ xem bạn thấy cọc màu cam và công nhân ở đâu.","h2":"Biển màu cam dùng cho đường đang sửa và khu vực thi công, nên bạn cần chạy chậm lại và chú ý công nhân cùng những thay đổi trên đường.","p":"Đúng rồi. Biển màu cam nghĩa là đường đang sửa."},"tl":{"q":"Tungkol saan ang sinasabi ng mga karatulang kulay orange?","o":["Mga school zone","Mga parke at campground","Ginagawang kalsada at work zone","Gasolina at pagkain"],"h1":"Isipin kung saan mo nakikita ang mga orange na cone at mga trabahador.","h2":"Ang mga karatulang kulay orange ay ginagamit para sa ginagawang kalsada at work zone, kaya dapat kang bumagal at mag-ingat sa mga trabahador at mga pagbabago.","p":"Tama. Ang orange na karatula ay nangangahulugang may ginagawang kalsada."},"ar":{"q":"عن أي شيء تخبرك اللافتات البرتقالية؟","o":["مناطق المدارس","الحدائق وأماكن التخييم","أعمال الطرق ومناطق العمل","الوقود والطعام"],"h1":"فكّر في المكان الذي ترى فيه الأقماع البرتقالية والعمال.","h2":"اللافتات البرتقالية تُستخدم لأعمال الطرق ومناطق العمل، لذلك يجب أن تخفف السرعة وتنتبه للعمال وللتغييرات.","p":"صحيح. اللافتات البرتقالية تعني أعمال طرق."},"ht":{"q":"Siy zoranj yo pale ou de kisa?","o":["Zòn lekòl","Pak ak kan","Travay sou wout ak zòn travay","Gaz ak manje"],"h1":"Panse kote ou wè kòn zoranj ak travayè.","h2":"Siy zoranj yo sèvi pou travay sou wout ak zòn travay, kidonk ou dwe ralanti epi veye travayè yo ak chanjman yo.","p":"Se sa. Siy zoranj yo vle di gen travay sou wout la."},"ref":{"doc":"FL","page":46}},{"id":"signs-008","scope":"US","cat":"signs","sign":{"shape":"no-passing","text":"NO PASSING ZONE"},"c":3,"en":{"q":"What does a yellow sign shaped like a long, sideways triangle mean?","o":["A merge is ahead on the right","Trucks have the right of way","The road gets narrow ahead","A no-passing zone begins here"],"h1":"This is the only sign with this flag-like shape.","h2":"The sideways yellow triangle, called a pennant, means a no-passing zone begins, so you must not pass other cars here.","p":"Right. The pennant means no passing."},"es":{"q":"¿Qué significa una señal amarilla en forma de triángulo largo y acostado?","o":["Hay una incorporación más adelante a la derecha","Los camiones tienen el derecho de paso","La vía se hace angosta más adelante","Aquí empieza una zona donde no se puede rebasar"],"h1":"Es la única señal con esta forma de banderín.","h2":"El triángulo amarillo acostado, llamado banderín, significa que empieza una zona donde no se puede rebasar, así que usted no debe rebasar a otros carros aquí.","p":"Correcto. El banderín significa que no se puede rebasar."},"zh":{"q":"一个横着放的长三角形黄色标志是什么意思？","o":["右前方有车辆并入","卡车有优先通行权","前方道路变窄","这里开始是禁止超车区"],"h1":"只有这一种标志是这种小旗子的形状。","h2":"横着的黄色三角形叫三角旗标志，表示禁止超车区开始，所以你在这里不能超车。","p":"对。三角旗标志表示禁止超车。"},"vi":{"q":"Biển màu vàng hình tam giác dài, nằm ngang có nghĩa là gì?","o":["Phía trước có làn nhập vào bên phải","Xe tải được quyền đi trước","Đường hẹp lại phía trước","Khu vực cấm vượt bắt đầu từ đây"],"h1":"Đây là biển duy nhất có hình giống lá cờ này.","h2":"Biển tam giác vàng nằm ngang, gọi là biển cờ đuôi nheo, nghĩa là khu vực cấm vượt bắt đầu, nên bạn không được vượt xe khác ở đây.","p":"Đúng rồi. Biển cờ đuôi nheo nghĩa là cấm vượt."},"tl":{"q":"Ano ang ibig sabihin ng dilaw na karatula na hugis mahabang tatsulok na nakatagilid?","o":["May sasama sa daan mula sa kanan sa unahan","Ang mga trak ang may karapatang mauna","Kikitid ang kalsada sa unahan","Dito nagsisimula ang lugar na bawal mag-overtake"],"h1":"Ito lang ang karatula na may ganitong hugis na parang bandila.","h2":"Ang nakatagilid na dilaw na tatsulok, na tinatawag na pennant, ay nangangahulugang nagsisimula ang lugar na bawal mag-overtake, kaya hindi ka dapat lumampas sa ibang sasakyan dito.","p":"Tama. Ang pennant ay nangangahulugang bawal mag-overtake."},"ar":{"q":"ماذا تعني لافتة صفراء على شكل مثلث طويل مائل إلى الجانب؟","o":["اندماج طريق في الأمام من اليمين","الشاحنات لها حق المرور","الطريق يضيق في الأمام","هنا تبدأ منطقة ممنوع فيها التجاوز"],"h1":"هذه هي اللافتة الوحيدة التي لها هذا الشكل الذي يشبه العلم.","h2":"المثلث الأصفر المائل إلى الجانب يسمى «الراية»، وهو يعني أن منطقة ممنوع فيها التجاوز تبدأ هنا، لذلك يجب ألا تتجاوز السيارات الأخرى هنا.","p":"صحيح. الراية تعني ممنوع التجاوز."},"ht":{"q":"Kisa yon siy jòn ki gen fòm yon triyang long ki kouche vle di?","o":["Gen machin k ap antre sou bò dwat pi devan","Kamyon yo gen dwa pou pase anvan","Wout la vin pi etwat pi devan","Yon zòn kote ou pa ka double kòmanse la a"],"h1":"Se sèl siy ki gen fòm sa a, tankou yon ti drapo.","h2":"Triyang jòn ki kouche a, yo rele l fanyon, vle di yon zòn kote ou pa ka double kòmanse, kidonk ou pa dwe double lòt machin la a.","p":"Se sa. Fanyon an vle di ou pa ka double."},"ref":{"doc":"FL","page":48}},{"id":"signs-009","scope":"US","cat":"signs","sign":null,"c":0,"en":{"q":"On which side of the road is the no-passing pennant sign placed?","o":["The left side","The right side","Over the middle lane","Painted on the road"],"h1":"Think about where your eyes look when you plan to pass.","h2":"The no-passing pennant is placed on the left side of the road, because that is the side you look at when you think about passing.","p":"Right. The pennant is on the left side of the road."},"es":{"q":"¿En qué lado de la vía se pone la señal de banderín de no rebasar?","o":["En el lado izquierdo","En el lado derecho","Encima del carril del medio","Pintada en el pavimento"],"h1":"Piense hacia dónde mira cuando planea rebasar.","h2":"El banderín de no rebasar se pone en el lado izquierdo de la vía, porque ese es el lado que usted mira cuando piensa rebasar.","p":"Correcto. El banderín está en el lado izquierdo de la vía."},"zh":{"q":"禁止超车的三角旗标志放在道路的哪一边？","o":["左边","右边","中间车道的上方","画在路面上"],"h1":"想一想：你打算超车时，眼睛会看向哪一边。","h2":"禁止超车的三角旗标志放在道路的左边，因为你想超车时会看那一边。","p":"对。三角旗标志在道路的左边。"},"vi":{"q":"Biển cờ đuôi nheo cấm vượt được đặt ở bên nào của đường?","o":["Bên trái","Bên phải","Phía trên làn giữa","Được sơn trên mặt đường"],"h1":"Hãy nghĩ xem mắt bạn nhìn về phía nào khi định vượt xe.","h2":"Biển cờ đuôi nheo cấm vượt được đặt ở bên trái đường, vì đó là phía bạn nhìn khi nghĩ đến việc vượt xe.","p":"Đúng rồi. Biển cờ đuôi nheo nằm ở bên trái đường."},"tl":{"q":"Sa aling bahagi ng kalsada inilalagay ang pennant na karatula ng bawal mag-overtake?","o":["Sa kaliwang bahagi","Sa kanang bahagi","Sa ibabaw ng gitnang linya","Nakapinta sa kalsada"],"h1":"Isipin kung saan tumitingin ang mata mo kapag balak mong mag-overtake.","h2":"Ang pennant ng bawal mag-overtake ay inilalagay sa kaliwang bahagi ng kalsada, dahil iyon ang bahaging tinitingnan mo kapag iniisip mong mag-overtake.","p":"Tama. Ang pennant ay nasa kaliwang bahagi ng kalsada."},"ar":{"q":"على أي جانب من الطريق توضع لافتة الراية التي تمنع التجاوز؟","o":["على الجانب الأيسر","على الجانب الأيمن","فوق المسار الأوسط","مرسومة على الطريق"],"h1":"فكّر إلى أين تنظر عيناك عندما تخطط للتجاوز.","h2":"لافتة الراية التي تمنع التجاوز توضع على الجانب الأيسر من الطريق، لأنه الجانب الذي تنظر إليه عندما تفكر في التجاوز.","p":"صحيح. الراية توضع على الجانب الأيسر من الطريق."},"ht":{"q":"Sou ki bò wout la yo mete siy fanyon ki di ou pa ka double a?","o":["Bò goch","Bò dwat","Anwo koulwa ki nan mitan an","Penti sou wout la"],"h1":"Panse ki kote je ou gade lè ou vle double.","h2":"Siy fanyon an yo mete l sou bò goch wout la, paske se bò sa a ou gade lè ou panse pou double.","p":"Se sa. Fanyon an sou bò goch wout la."}},{"id":"signs-010","scope":"US","cat":"signs","sign":{"shape":"rect-white"},"c":1,"en":{"q":"A white rectangle sign with black letters usually shows what?","o":["A warning about a curve","A traffic law you must obey","Directions to a city","A place to camp"],"h1":"Think about signs like the speed limit sign.","h2":"White rectangle signs with black letters are regulatory signs, so they show a traffic law that you must obey.","p":"Right. White rectangle signs show rules you must follow."},"es":{"q":"¿Qué muestra normalmente una señal blanca y rectangular con letras negras?","o":["Un aviso de una curva","Una ley de tránsito que debe obedecer","Direcciones hacia una ciudad","Un lugar para acampar"],"h1":"Piense en señales como la del límite de velocidad.","h2":"Las señales blancas y rectangulares con letras negras son señales reglamentarias, así que muestran una ley de tránsito que usted debe obedecer.","p":"Correcto. Las señales blancas rectangulares muestran reglas que debe seguir."},"zh":{"q":"白色长方形、黑色字的标志通常表示什么？","o":["提醒你前方有弯道","你必须遵守的交通法规","去某个城市的方向","可以露营的地方"],"h1":"想一想限速标志这样的标志。","h2":"白色长方形、黑色字的标志是禁令和指示标志，它告诉你必须遵守的交通法规。","p":"对。白色长方形标志告诉你必须遵守的规定。"},"vi":{"q":"Biển hình chữ nhật màu trắng, chữ đen thường cho biết điều gì?","o":["Cảnh báo về khúc cua","Một luật giao thông bạn phải tuân theo","Đường đi tới một thành phố","Chỗ để cắm trại"],"h1":"Hãy nghĩ đến những biển như biển giới hạn tốc độ.","h2":"Biển chữ nhật màu trắng, chữ đen là biển quy định, nên nó cho biết một luật giao thông mà bạn phải tuân theo.","p":"Đúng rồi. Biển chữ nhật màu trắng cho biết luật bạn phải theo."},"tl":{"q":"Ano ang karaniwang ipinapakita ng puting parihabang karatula na may itim na letra?","o":["Babala tungkol sa kurba","Batas trapiko na dapat mong sundin","Direksyon papunta sa isang lungsod","Lugar na puwedeng mag-camping"],"h1":"Isipin ang mga karatula tulad ng karatula ng speed limit.","h2":"Ang puting parihabang karatula na may itim na letra ay karatula ng regulasyon, kaya nagpapakita ito ng batas trapiko na dapat mong sundin.","p":"Tama. Ang puting parihabang karatula ay nagpapakita ng mga patakarang dapat sundin."},"ar":{"q":"لافتة بيضاء مستطيلة بحروف سوداء، ماذا تُظهر عادةً؟","o":["تحذيرًا من منعطف","قانون مرور يجب أن تطيعه","الاتجاه إلى مدينة","مكانًا للتخييم"],"h1":"فكّر في لافتات مثل لافتة حد السرعة.","h2":"اللافتات البيضاء المستطيلة بالحروف السوداء هي لافتات تنظيمية، فهي تُظهر قانون مرور يجب أن تطيعه.","p":"صحيح. اللافتات البيضاء المستطيلة تُظهر قواعد يجب أن تتبعها."},"ht":{"q":"Yon siy blan ki gen fòm rektang ak lèt nwa, kisa li konn montre?","o":["Yon avètisman pou yon koub","Yon lwa trafik ou dwe respekte","Direksyon pou yon vil","Yon kote pou kanpe tant"],"h1":"Panse ak siy tankou siy limit vitès la.","h2":"Siy blan an rektang ak lèt nwa yo se siy règleman, kidonk yo montre yon lwa trafik ou dwe respekte.","p":"Se sa. Siy blan an rektang yo montre règ ou dwe swiv."},"ref":{"doc":"FL","page":46}},{"id":"signs-011","scope":"US","cat":"signs","sign":{"shape":"rect-green","text":"Orlando 25"},"c":2,"en":{"q":"What do green signs show you?","o":["Where the hospital is","Where road work starts","Directions and distances","Where a school zone is"],"h1":"Think about signs that help you find your way.","h2":"Green signs are guide signs, so they show directions, exits, and how far it is to places.","p":"Right. Green signs show directions and distances."},"es":{"q":"¿Qué le muestran las señales verdes?","o":["Dónde está el hospital","Dónde empiezan las obras","Direcciones y distancias","Dónde hay una zona escolar"],"h1":"Piense en señales que le ayudan a encontrar el camino.","h2":"Las señales verdes son señales de guía, así que muestran direcciones, salidas y qué tan lejos están los lugares.","p":"Correcto. Las señales verdes muestran direcciones y distancias."},"zh":{"q":"绿色标志告诉你什么？","o":["医院在哪里","道路施工从哪里开始","方向和距离","学校区在哪里"],"h1":"想一想：哪些标志帮你找路。","h2":"绿色标志是指路标志，它告诉你方向、出口，以及到各地还有多远。","p":"对。绿色标志告诉你方向和距离。"},"vi":{"q":"Biển màu xanh lá cây cho bạn biết điều gì?","o":["Bệnh viện ở đâu","Đoạn đường sửa bắt đầu ở đâu","Hướng đi và khoảng cách","Khu vực trường học ở đâu"],"h1":"Hãy nghĩ đến những biển giúp bạn tìm đường.","h2":"Biển màu xanh lá cây là biển chỉ dẫn, nên nó cho biết hướng đi, lối ra, và còn bao xa nữa tới các nơi.","p":"Đúng rồi. Biển xanh lá cây cho biết hướng đi và khoảng cách."},"tl":{"q":"Ano ang ipinapakita sa iyo ng mga berdeng karatula?","o":["Kung nasaan ang ospital","Kung saan nagsisimula ang ginagawang kalsada","Mga direksyon at layo","Kung nasaan ang school zone"],"h1":"Isipin ang mga karatulang tumutulong sa iyo na mahanap ang daan.","h2":"Ang mga berdeng karatula ay gabay na karatula, kaya ipinapakita nito ang mga direksyon, mga exit, at kung gaano kalayo ang mga lugar.","p":"Tama. Ang berdeng karatula ay nagpapakita ng direksyon at layo."},"ar":{"q":"ماذا تُظهر لك اللافتات الخضراء؟","o":["مكان المستشفى","مكان بداية أعمال الطرق","الاتجاهات والمسافات","مكان منطقة المدرسة"],"h1":"فكّر في اللافتات التي تساعدك على معرفة طريقك.","h2":"اللافتات الخضراء هي لافتات إرشاد، فهي تُظهر الاتجاهات والمخارج وكم تبعد الأماكن.","p":"صحيح. اللافتات الخضراء تُظهر الاتجاهات والمسافات."},"ht":{"q":"Kisa siy vèt yo montre ou?","o":["Kote lopital la ye","Kote travay sou wout la kòmanse","Direksyon ak distans","Kote yon zòn lekòl ye"],"h1":"Panse ak siy ki ede ou jwenn chemen ou.","h2":"Siy vèt yo se siy gid, kidonk yo montre direksyon, sòti yo, ak konbyen distans ki genyen pou rive kèk kote.","p":"Se sa. Siy vèt yo montre direksyon ak distans."},"ref":{"doc":"FL","page":46}},{"id":"signs-012","scope":"US","cat":"signs","sign":{"shape":"rect-blue","text":"GAS FOOD LODGING"},"c":3,"en":{"q":"What do blue signs along the road show?","o":["Speed laws","Road work","Parks and lakes","Services like gas, food, and lodging"],"h1":"Think about what you need on a long trip.","h2":"Blue signs show motorist services, so they point you to things like gas, food, lodging, and hospitals.","p":"Right. Blue signs show services like gas and food."},"es":{"q":"¿Qué muestran las señales azules en la carretera?","o":["Leyes de velocidad","Obras en la vía","Parques y lagos","Servicios como gasolina, comida y hospedaje"],"h1":"Piense en lo que necesita en un viaje largo.","h2":"Las señales azules muestran servicios para conductores, así que le indican lugares como gasolineras, comida, hospedaje y hospitales.","p":"Correcto. Las señales azules muestran servicios como gasolina y comida."},"zh":{"q":"路边的蓝色标志告诉你什么？","o":["限速法规","道路施工","公园和湖泊","加油、吃饭、住宿等服务"],"h1":"想一想：长途开车时你需要什么。","h2":"蓝色标志告诉你司机服务的地点，比如加油站、餐馆、住宿和医院。","p":"对。蓝色标志告诉你加油、吃饭等服务。"},"vi":{"q":"Biển màu xanh dương bên đường cho biết điều gì?","o":["Luật về tốc độ","Đường đang sửa","Công viên và hồ","Dịch vụ như xăng, đồ ăn, và chỗ ngủ"],"h1":"Hãy nghĩ xem bạn cần gì trong một chuyến đi xa.","h2":"Biển màu xanh dương cho biết các dịch vụ cho người lái xe, nên nó chỉ bạn tới những nơi như trạm xăng, chỗ ăn, chỗ ngủ, và bệnh viện.","p":"Đúng rồi. Biển xanh dương cho biết dịch vụ như xăng và đồ ăn."},"tl":{"q":"Ano ang ipinapakita ng mga asul na karatula sa tabi ng kalsada?","o":["Mga batas sa bilis","Ginagawang kalsada","Mga parke at lawa","Mga serbisyo tulad ng gasolina, pagkain, at matutuluyan"],"h1":"Isipin kung ano ang kailangan mo sa mahabang biyahe.","h2":"Ang mga asul na karatula ay nagpapakita ng mga serbisyo para sa motorista, kaya itinuturo nito ang mga bagay tulad ng gasolina, pagkain, matutuluyan, at ospital.","p":"Tama. Ang asul na karatula ay nagpapakita ng mga serbisyo tulad ng gasolina at pagkain."},"ar":{"q":"ماذا تُظهر اللافتات الزرقاء على جانب الطريق؟","o":["قوانين السرعة","أعمال الطرق","الحدائق والبحيرات","خدمات مثل الوقود والطعام والمبيت"],"h1":"فكّر في ما تحتاجه في رحلة طويلة.","h2":"اللافتات الزرقاء تُظهر خدمات السائقين، فهي تدلّك على أشياء مثل الوقود والطعام والمبيت والمستشفيات.","p":"صحيح. اللافتات الزرقاء تُظهر خدمات مثل الوقود والطعام."},"ht":{"q":"Kisa siy ble yo sou bò wout la montre?","o":["Lwa sou vitès","Travay sou wout","Pak ak lak","Sèvis tankou gaz, manje, ak kote pou dòmi"],"h1":"Panse ak sa ou bezwen nan yon long vwayaj.","h2":"Siy ble yo montre sèvis pou chofè, kidonk yo montre ou kote ki gen gaz, manje, kote pou dòmi, ak lopital.","p":"Se sa. Siy ble yo montre sèvis tankou gaz ak manje."},"ref":{"doc":"FL","page":46}},{"id":"signs-013","scope":"US","cat":"signs","sign":{"shape":"rect-brown","text":"STATE PARK"},"c":0,"en":{"q":"What do brown signs point you to?","o":["Parks, campgrounds, and places to visit","Gas stations and hotels","Exits and city names","Road work zones"],"h1":"Think about places you go for fun or nature.","h2":"Brown signs point to recreation and cultural places, such as parks, campgrounds, and historic sites.","p":"Right. Brown signs point to parks and places to visit."},"es":{"q":"¿Hacia dónde le indican las señales color café?","o":["Parques, campamentos y lugares para visitar","Gasolineras y hoteles","Salidas y nombres de ciudades","Zonas de obras"],"h1":"Piense en lugares a los que va para divertirse o estar en la naturaleza.","h2":"Las señales color café indican lugares de recreación y cultura, como parques, campamentos y sitios históricos.","p":"Correcto. Las señales color café indican parques y lugares para visitar."},"zh":{"q":"棕色标志指向哪里？","o":["公园、露营地和游览地点","加油站和酒店","出口和城市名","道路施工区"],"h1":"想一想：你为了玩或看大自然会去的地方。","h2":"棕色标志指向休闲和文化地点，比如公园、露营地和历史古迹。","p":"对。棕色标志指向公园和游览地点。"},"vi":{"q":"Biển màu nâu chỉ bạn tới đâu?","o":["Công viên, khu cắm trại, và nơi tham quan","Trạm xăng và khách sạn","Lối ra và tên thành phố","Khu vực đường đang sửa"],"h1":"Hãy nghĩ đến những nơi bạn đi chơi hoặc đi ngắm thiên nhiên.","h2":"Biển màu nâu chỉ tới nơi giải trí và văn hóa, như công viên, khu cắm trại, và di tích lịch sử.","p":"Đúng rồi. Biển màu nâu chỉ tới công viên và nơi tham quan."},"tl":{"q":"Saan ka itinuturo ng mga brown na karatula?","o":["Mga parke, campground, at mga lugar na mapapasyalan","Mga gasolinahan at hotel","Mga exit at pangalan ng lungsod","Mga lugar na may ginagawang kalsada"],"h1":"Isipin ang mga lugar na pinupuntahan mo para maglibang o para sa kalikasan.","h2":"Ang mga brown na karatula ay nagtuturo sa mga lugar ng libangan at kultura, tulad ng mga parke, campground, at makasaysayang lugar.","p":"Tama. Ang brown na karatula ay nagtuturo sa mga parke at mga lugar na mapapasyalan."},"ar":{"q":"إلى ماذا ترشدك اللافتات البنية؟","o":["الحدائق وأماكن التخييم والأماكن التي تستحق الزيارة","محطات الوقود والفنادق","المخارج وأسماء المدن","مناطق أعمال الطرق"],"h1":"فكّر في الأماكن التي تذهب إليها للمتعة أو للطبيعة.","h2":"اللافتات البنية ترشدك إلى أماكن الترفيه والثقافة، مثل الحدائق وأماكن التخييم والمواقع التاريخية.","p":"صحيح. اللافتات البنية ترشدك إلى الحدائق والأماكن التي تستحق الزيارة."},"ht":{"q":"Siy mawon yo montre ou ki kote?","o":["Pak, kan, ak kote pou vizite","Estasyon gaz ak otèl","Sòti ak non vil","Zòn travay sou wout"],"h1":"Panse ak kote ou ale pou pran plezi oswa pou wè lanati.","h2":"Siy mawon yo montre kote pou amizman ak kilti, tankou pak, kan, ak kote istorik.","p":"Se sa. Siy mawon yo montre pak ak kote pou vizite."},"ref":{"doc":"FL","page":46}},{"id":"signs-014","scope":"US","cat":"signs","sign":{"shape":"do-not-enter","text":"DO NOT ENTER"},"c":1,"en":{"q":"What does a red circle with a white bar across it mean?","o":["Stop, then go when clear","Do not enter this road","Hospital ahead","Two-way traffic ahead"],"h1":"Think about a road where all the cars come toward you.","h2":"The red circle with a white bar means do not enter, because traffic on that road comes toward you.","p":"Right. The red circle with a white bar means do not enter."},"es":{"q":"¿Qué significa un círculo rojo con una barra blanca en el medio?","o":["Pararse y seguir cuando esté libre","No entre a esta vía","Hospital más adelante","Tráfico en dos sentidos más adelante"],"h1":"Piense en una vía donde todos los carros vienen hacia usted.","h2":"El círculo rojo con una barra blanca significa no entre, porque el tráfico en esa vía viene hacia usted.","p":"Correcto. El círculo rojo con barra blanca significa no entre."},"zh":{"q":"红色圆形中间有一条白色横杠，是什么意思？","o":["停车，没车时再走","禁止驶入这条路","前方有医院","前方是双向交通"],"h1":"想一想：一条路上所有车都朝你开过来。","h2":"红色圆形中间有白色横杠，意思是禁止驶入，因为这条路上的车是朝你开过来的。","p":"对。红色圆形加白色横杠表示禁止驶入。"},"vi":{"q":"Hình tròn màu đỏ có một vạch trắng ngang qua có nghĩa là gì?","o":["Dừng lại, rồi đi khi đường trống","Không được đi vào con đường này","Phía trước có bệnh viện","Phía trước là đường hai chiều"],"h1":"Hãy nghĩ đến con đường mà mọi xe đều chạy ngược về phía bạn.","h2":"Hình tròn đỏ có vạch trắng nghĩa là cấm đi vào (“DO NOT ENTER”), vì xe trên con đường đó đang chạy ngược về phía bạn.","p":"Đúng rồi. Hình tròn đỏ có vạch trắng nghĩa là cấm đi vào."},"tl":{"q":"Ano ang ibig sabihin ng pulang bilog na may puting guhit sa gitna?","o":["Huminto, saka umandar kapag maluwag na","Bawal pumasok sa daang ito","May ospital sa unahan","May dalawang-direksyong trapiko sa unahan"],"h1":"Isipin ang isang daan kung saan lahat ng sasakyan ay papunta sa iyo.","h2":"Ang pulang bilog na may puting guhit ay nangangahulugang “DO NOT ENTER” (Bawal pumasok), dahil ang trapiko sa daang iyon ay papunta sa iyo.","p":"Tama. Ang pulang bilog na may puting guhit ay nangangahulugang bawal pumasok."},"ar":{"q":"ماذا تعني دائرة حمراء يقطعها خط أبيض؟","o":["توقف، ثم انطلق عندما يكون الطريق خاليًا","لا تدخل هذا الطريق","مستشفى في الأمام","حركة مرور في الاتجاهين في الأمام"],"h1":"فكّر في طريق تأتي فيه كل السيارات نحوك.","h2":"الدائرة الحمراء التي يقطعها خط أبيض تعني «DO NOT ENTER» (ممنوع الدخول)، لأن السيارات في ذلك الطريق تأتي نحوك.","p":"صحيح. الدائرة الحمراء التي يقطعها خط أبيض تعني ممنوع الدخول."},"ht":{"q":"Kisa yon sèk wouj ki gen yon ba blan ki travèse l vle di?","o":["Kanpe, epi pati lè wout la lib","Pa antre nan wout sa a","Gen yon lopital pi devan","Gen machin k ap ale nan de direksyon pi devan"],"h1":"Panse ak yon wout kote tout machin yo ap vin sou ou.","h2":"Sèk wouj ki gen ba blan an vle di “DO NOT ENTER” (pa antre), paske machin sou wout sa a ap vin sou ou.","p":"Se sa. Sèk wouj ki gen ba blan an vle di pa antre."},"ref":{"doc":"FL","page":47}},{"id":"signs-015","scope":"US","cat":"signs","sign":{"shape":"wrong-way","text":"WRONG WAY"},"c":2,"en":{"q":"A red sign facing you says WRONG WAY. What should you do?","o":["Keep going with your hazard lights on","Speed up to reach the next exit","Pull over safely and turn around","Keep driving on the shoulder"],"h1":"The sign means you are going against traffic.","h2":"A WRONG WAY sign means you are driving against traffic, so you should pull over safely and turn around as soon as you can.","p":"Right. WRONG WAY means pull over safely and turn around."},"es":{"q":"Una señal roja frente a usted dice WRONG WAY (sentido contrario). ¿Qué debe hacer?","o":["Seguir con las luces de emergencia prendidas","Acelerar para llegar a la próxima salida","Orillarse con cuidado y dar la vuelta","Seguir manejando por el acotamiento"],"h1":"La señal quiere decir que usted va contra el tráfico.","h2":"Una señal de sentido contrario quiere decir que usted maneja contra el tráfico, así que debe orillarse con cuidado y dar la vuelta lo antes posible.","p":"Correcto. Sentido contrario significa orillarse con cuidado y dar la vuelta."},"zh":{"q":"一个面向你的红色标志写着 “WRONG WAY”（逆行）。你应该怎么做？","o":["打开危险警示灯，继续开","加速，开到下一个出口","安全靠边，然后掉头","继续在路肩上开"],"h1":"这个标志表示你在逆着车流开。","h2":"“WRONG WAY”（逆行）标志表示你在逆着车流开车，所以你要安全靠边，尽快掉头。","p":"对。“WRONG WAY” 表示安全靠边并掉头。"},"vi":{"q":"Một biển màu đỏ hướng về phía bạn ghi “WRONG WAY” (Đi sai chiều). Bạn nên làm gì?","o":["Cứ chạy tiếp và bật đèn khẩn cấp","Tăng tốc để tới lối ra kế tiếp","Tấp vào lề an toàn và quay đầu lại","Chạy tiếp trên lề đường"],"h1":"Biển này nghĩa là bạn đang chạy ngược chiều xe khác.","h2":"Biển “WRONG WAY” nghĩa là bạn đang chạy ngược chiều, nên bạn cần tấp vào lề an toàn và quay đầu lại càng sớm càng tốt.","p":"Đúng rồi. “WRONG WAY” nghĩa là tấp vào lề an toàn và quay đầu lại."},"tl":{"q":"May pulang karatula na nakaharap sa iyo at nakasulat ang “WRONG WAY” (Maling direksyon). Ano ang dapat mong gawin?","o":["Tuloy lang habang nakabukas ang hazard lights","Bumilis para maabot ang susunod na exit","Tumabi nang ligtas at umikot pabalik","Magpatuloy sa pagmamaneho sa gilid ng kalsada"],"h1":"Ang karatula ay nangangahulugang salungat ka sa daloy ng trapiko.","h2":"Ang “WRONG WAY” na karatula ay nangangahulugang salungat ka sa daloy ng trapiko, kaya dapat kang tumabi nang ligtas at umikot pabalik sa lalong madaling panahon.","p":"Tama. Ang “WRONG WAY” ay nangangahulugang tumabi nang ligtas at umikot pabalik."},"ar":{"q":"لافتة حمراء أمامك مكتوب عليها «WRONG WAY» (اتجاه خاطئ). ماذا يجب أن تفعل؟","o":["تابع السير مع تشغيل أضواء التحذير","زد السرعة لتصل إلى المخرج التالي","توقف على جانب الطريق بأمان واستدر عائدًا","تابع القيادة على كتف الطريق"],"h1":"اللافتة تعني أنك تسير عكس اتجاه السير.","h2":"لافتة «WRONG WAY» تعني أنك تقود عكس اتجاه السير، لذلك يجب أن تتوقف على جانب الطريق بأمان وتستدير عائدًا في أسرع وقت ممكن.","p":"صحيح. «WRONG WAY» تعني: توقف على الجانب بأمان واستدر عائدًا."},"ht":{"q":"Yon siy wouj ki fè fas ak ou di “WRONG WAY” (move direksyon). Kisa ou dwe fè?","o":["Kontinye ak limyè ijans ou limen","Akselere pou rive nan pwochen sòti a","Rale sou kote an sekirite epi vire tounen","Kontinye kondui sou arebò wout la"],"h1":"Siy la vle di w ap kondui kont trafik la.","h2":"Yon siy “WRONG WAY” vle di w ap kondui kont trafik la, kidonk ou dwe rale sou kote an sekirite epi vire tounen pi vit ou kapab.","p":"Se sa. “WRONG WAY” vle di rale sou kote an sekirite epi vire tounen."},"ref":{"doc":"FL","page":47}},{"id":"signs-016","scope":"US","cat":"signs","sign":{"shape":"rect-white","text":"SPEED LIMIT 55"},"c":3,"en":{"q":"What does this sign tell you?","o":["The lowest speed you may drive","The speed you must always drive","A suggested speed for curves","The top legal speed in good conditions"],"h1":"Think about whether you may go faster, or slower.","h2":"A speed limit sign shows the highest legal speed when conditions are good, so you may need to drive slower in rain, fog, or heavy traffic.","p":"Right. The speed limit is the top speed in good conditions."},"es":{"q":"¿Qué le dice esta señal?","o":["La velocidad más baja permitida","La velocidad a la que siempre debe ir","Una velocidad sugerida para curvas","La velocidad máxima legal en buenas condiciones"],"h1":"Piense si puede ir más rápido o más despacio.","h2":"Una señal de límite de velocidad muestra la velocidad máxima legal cuando las condiciones son buenas, así que puede tener que ir más despacio con lluvia, neblina o mucho tráfico.","p":"Correcto. El límite es la velocidad máxima en buenas condiciones."},"zh":{"q":"这个标志告诉你什么？","o":["你可以开的最低速度","你必须一直保持的速度","弯道的建议速度","在良好条件下的最高合法速度"],"h1":"想一想：你可以开得更快，还是要开得更慢。","h2":"限速标志表示在良好条件下的最高合法速度，所以下雨、有雾或车多时，你可能要开得更慢。","p":"对。限速是在良好条件下的最高速度。"},"vi":{"q":"Biển này cho bạn biết điều gì?","o":["Tốc độ thấp nhất bạn được chạy","Tốc độ bạn lúc nào cũng phải chạy","Tốc độ nên chạy ở khúc cua","Tốc độ cao nhất theo luật khi điều kiện tốt"],"h1":"Hãy nghĩ xem bạn được chạy nhanh hơn, hay chậm hơn.","h2":"Biển giới hạn tốc độ cho biết tốc độ cao nhất theo luật khi điều kiện tốt, nên bạn có thể cần chạy chậm hơn khi mưa, có sương mù, hoặc kẹt xe.","p":"Đúng rồi. Giới hạn tốc độ là tốc độ cao nhất khi điều kiện tốt."},"tl":{"q":"Ano ang sinasabi sa iyo ng karatulang ito?","o":["Ang pinakamababang bilis na puwede mong takbuhin","Ang bilis na dapat mong takbuhin palagi","Mungkahing bilis para sa mga kurba","Ang pinakamataas na legal na bilis kapag maayos ang kondisyon"],"h1":"Isipin kung puwede kang bumilis pa, o bumagal.","h2":"Ang karatula ng speed limit ay nagpapakita ng pinakamataas na legal na bilis kapag maayos ang kondisyon, kaya maaaring kailangan mong bumagal kapag umuulan, may hamog, o mabigat ang trapiko.","p":"Tama. Ang speed limit ay ang pinakamataas na bilis kapag maayos ang kondisyon."},"ar":{"q":"ماذا تخبرك هذه اللافتة؟","o":["أقل سرعة مسموح لك أن تقود بها","السرعة التي يجب أن تقود بها دائمًا","سرعة مقترحة للمنعطفات","أعلى سرعة قانونية عندما تكون الظروف جيدة"],"h1":"فكّر: هل يُسمح لك أن تسير أسرع، أم أبطأ؟","h2":"لافتة حد السرعة تُظهر أعلى سرعة قانونية عندما تكون الظروف جيدة، لذلك قد تحتاج إلى القيادة أبطأ في المطر أو الضباب أو الزحام الشديد.","p":"صحيح. حد السرعة هو أعلى سرعة عندما تكون الظروف جيدة."},"ht":{"q":"Kisa siy sa a di ou?","o":["Vitès ki pi ba ou ka kondui","Vitès ou dwe toujou kondui","Yon vitès yo konseye pou koub yo","Vitès ki pi wo lalwa pèmèt lè kondisyon yo bon"],"h1":"Panse si ou ka ale pi vit, oswa pi dousman.","h2":"Yon siy limit vitès montre vitès ki pi wo lalwa pèmèt lè kondisyon yo bon, kidonk ou ka bezwen kondui pi dousman lè gen lapli, bwouya, oswa anpil machin.","p":"Se sa. Limit vitès la se vitès ki pi wo a lè kondisyon yo bon."},"ref":{"doc":"FL","page":47}},{"id":"signs-017","scope":"US","cat":"signs","sign":{"shape":"rect-white","text":"ONE WAY"},"c":1,"en":{"q":"What does a ONE WAY sign with an arrow mean?","o":["Only one lane is open ahead","Traffic moves only in the arrow's direction","Only one car may pass at a time","You may make only one turn"],"h1":"Look at where the arrow points.","h2":"A ONE WAY sign means all traffic on that street moves only in the direction of the arrow.","p":"Right. One way means drive only in the arrow's direction."},"es":{"q":"¿Qué significa una señal ONE WAY (un solo sentido) con una flecha?","o":["Solo hay un carril abierto más adelante","El tráfico va solo en la dirección de la flecha","Solo puede pasar un carro a la vez","Solo puede dar una vuelta"],"h1":"Mire hacia dónde apunta la flecha.","h2":"Una señal de un solo sentido quiere decir que todo el tráfico en esa calle va solo en la dirección de la flecha.","p":"Correcto. Un solo sentido significa manejar solo hacia donde apunta la flecha."},"zh":{"q":"带箭头的 “ONE WAY”（单行道）标志是什么意思？","o":["前方只有一条车道开放","车辆只能按箭头方向行驶","一次只能过一辆车","你只能转一次弯"],"h1":"看看箭头指向哪里。","h2":"“ONE WAY”（单行道）标志表示这条街上所有车辆只能按箭头的方向行驶。","p":"对。单行道表示只能按箭头方向开。"},"vi":{"q":"Biển “ONE WAY” (Một chiều) có mũi tên có nghĩa là gì?","o":["Phía trước chỉ còn một làn mở","Xe chỉ được chạy theo hướng mũi tên","Mỗi lần chỉ một xe được đi qua","Bạn chỉ được rẽ một lần"],"h1":"Hãy nhìn xem mũi tên chỉ về đâu.","h2":"Biển “ONE WAY” nghĩa là mọi xe trên con đường đó chỉ được chạy theo hướng mũi tên.","p":"Đúng rồi. Một chiều nghĩa là chỉ chạy theo hướng mũi tên."},"tl":{"q":"Ano ang ibig sabihin ng “ONE WAY” na karatula na may arrow?","o":["Isang linya lang ang bukas sa unahan","Ang trapiko ay dumadaloy lang sa direksyon ng arrow","Isang sasakyan lang ang puwedeng dumaan bawat oras","Isang beses ka lang puwedeng lumiko"],"h1":"Tingnan kung saan nakaturo ang arrow.","h2":"Ang “ONE WAY” na karatula (Isang direksyon) ay nangangahulugang lahat ng trapiko sa kalyeng iyon ay dumadaloy lang sa direksyon ng arrow.","p":"Tama. Ang “ONE WAY” ay nangangahulugang magmaneho lang sa direksyon ng arrow."},"ar":{"q":"ماذا تعني لافتة «ONE WAY» (اتجاه واحد) التي عليها سهم؟","o":["مسار واحد فقط مفتوح في الأمام","السيارات تسير فقط في اتجاه السهم","سيارة واحدة فقط تمر في كل مرة","مسموح لك بمنعطف واحد فقط"],"h1":"انظر إلى أين يشير السهم.","h2":"لافتة «ONE WAY» تعني أن كل السيارات في ذلك الشارع تسير فقط في اتجاه السهم.","p":"صحيح. اتجاه واحد يعني: قُد فقط في اتجاه السهم."},"ht":{"q":"Kisa yon siy “ONE WAY” (yon sèl direksyon) ak yon flèch vle di?","o":["Se yon sèl koulwa ki louvri pi devan","Machin yo ale sèlman nan direksyon flèch la","Se yon sèl machin ki ka pase alafwa","Ou ka fè yon sèl vire sèlman"],"h1":"Gade ki bò flèch la montre.","h2":"Yon siy “ONE WAY” vle di tout machin nan lari sa a ale sèlman nan direksyon flèch la.","p":"Se sa. Yon sèl direksyon vle di kondui sèlman nan direksyon flèch la."},"ref":{"doc":"FL","page":48}},{"id":"signs-018","scope":"US","cat":"signs","sign":{"shape":"rect-white","text":"NO U-TURN"},"c":2,"en":{"q":"What does a NO U-TURN sign mean?","o":["You may not turn left here","You may not turn right here","You may not turn around here","You may not change lanes here"],"h1":"A U-turn makes the shape of the letter U.","h2":"A NO U-TURN sign means you may not turn your car around to go back the other way at that place.","p":"Right. No U-turn means you may not turn around here."},"es":{"q":"¿Qué significa una señal de NO U-TURN (prohibido dar vuelta en U)?","o":["No puede doblar a la izquierda aquí","No puede doblar a la derecha aquí","No puede dar la vuelta para regresar aquí","No puede cambiar de carril aquí"],"h1":"Una vuelta en U tiene la forma de la letra U.","h2":"Una señal de prohibido dar vuelta en U quiere decir que usted no puede dar la vuelta con su carro para regresar en ese lugar.","p":"Correcto. Prohibido vuelta en U significa que no puede dar la vuelta aquí."},"zh":{"q":"“NO U-TURN”（禁止掉头）标志是什么意思？","o":["这里不能左转","这里不能右转","这里不能掉头","这里不能换车道"],"h1":"掉头时车走的路线像字母 U。","h2":"“NO U-TURN”（禁止掉头）标志表示你在这里不能把车调过头往回开。","p":"对。禁止掉头表示这里不能掉头。"},"vi":{"q":"Biển “NO U-TURN” (Cấm quay đầu) có nghĩa là gì?","o":["Bạn không được rẽ trái ở đây","Bạn không được rẽ phải ở đây","Bạn không được quay đầu xe ở đây","Bạn không được đổi làn ở đây"],"h1":"Khi quay đầu, xe chạy theo hình chữ U.","h2":"Biển “NO U-TURN” nghĩa là ở chỗ đó bạn không được quay đầu xe để đi ngược lại.","p":"Đúng rồi. Cấm quay đầu nghĩa là bạn không được quay đầu xe ở đây."},"tl":{"q":"Ano ang ibig sabihin ng “NO U-TURN” na karatula?","o":["Hindi ka puwedeng kumaliwa dito","Hindi ka puwedeng kumanan dito","Hindi ka puwedeng umikot pabalik dito","Hindi ka puwedeng lumipat ng linya dito"],"h1":"Ang U-turn ay may hugis ng letrang U.","h2":"Ang “NO U-TURN” na karatula ay nangangahulugang hindi mo puwedeng iikot ang sasakyan mo para bumalik sa kabilang direksyon sa lugar na iyon.","p":"Tama. Ang “NO U-TURN” ay nangangahulugang hindi ka puwedeng umikot pabalik dito."},"ar":{"q":"ماذا تعني لافتة «NO U-TURN» (ممنوع الدوران للخلف)؟","o":["ممنوع أن تنعطف يسارًا هنا","ممنوع أن تنعطف يمينًا هنا","ممنوع أن تستدير عائدًا هنا","ممنوع أن تغيّر المسار هنا"],"h1":"الدوران للخلف يرسم شكل الحرف U.","h2":"لافتة «NO U-TURN» تعني أنه ممنوع أن تدير سيارتك لتعود في الاتجاه الآخر في ذلك المكان.","p":"صحيح. ممنوع الدوران للخلف يعني أنك لا تستطيع أن تستدير عائدًا هنا."},"ht":{"q":"Kisa yon siy “NO U-TURN” vle di?","o":["Ou pa ka vire agoch la a","Ou pa ka vire adwat la a","Ou pa ka vire tounen la a","Ou pa ka chanje koulwa la a"],"h1":"Yon “U-turn” fè fòm lèt U a.","h2":"Yon siy “NO U-TURN” vle di ou pa ka vire machin ou pou tounen nan lòt direksyon an kote sa a.","p":"Se sa. “NO U-TURN” vle di ou pa ka vire tounen la a."},"ref":{"doc":"FL","page":48}},{"id":"signs-019","scope":"US","cat":"signs","sign":{"shape":"rect-white","text":"NO TURN ON RED"},"c":3,"en":{"q":"What does a NO TURN ON RED sign mean?","o":["Turn right only after a full stop","Turn only when no cars are coming","Turn on red only at night","Wait for the green light before you turn"],"h1":"The sign changes what you may do while the light is red.","h2":"A NO TURN ON RED sign means you may not turn while the light is red, so you must wait for the green light.","p":"Right. No turn on red means wait for green."},"es":{"q":"¿Qué significa una señal de NO TURN ON RED (no doblar con luz roja)?","o":["Doblar a la derecha solo después de parar por completo","Doblar solo cuando no vengan carros","Doblar con luz roja solo de noche","Esperar la luz verde antes de doblar"],"h1":"La señal cambia lo que puede hacer mientras la luz está en rojo.","h2":"Una señal de no doblar con luz roja quiere decir que usted no puede doblar mientras la luz está en rojo, así que debe esperar la luz verde.","p":"Correcto. No doblar con luz roja significa esperar la luz verde."},"zh":{"q":"“NO TURN ON RED”（红灯禁止转弯）标志是什么意思？","o":["完全停车后才可以右转","没有来车时才可以转弯","只有晚上才可以红灯转弯","等绿灯亮了再转弯"],"h1":"这个标志改变了红灯时你可以做的事。","h2":"“NO TURN ON RED”（红灯禁止转弯）标志表示红灯时你不能转弯，所以你必须等绿灯。","p":"对。红灯禁止转弯表示要等绿灯。"},"vi":{"q":"Biển “NO TURN ON RED” (Cấm rẽ khi đèn đỏ) có nghĩa là gì?","o":["Chỉ rẽ phải sau khi dừng hẳn","Chỉ rẽ khi không có xe tới","Chỉ được rẽ khi đèn đỏ vào ban đêm","Chờ đèn xanh rồi mới rẽ"],"h1":"Biển này thay đổi điều bạn được làm khi đèn đang đỏ.","h2":"Biển “NO TURN ON RED” nghĩa là bạn không được rẽ khi đèn đang đỏ, nên bạn phải chờ đèn xanh.","p":"Đúng rồi. Cấm rẽ khi đèn đỏ nghĩa là chờ đèn xanh."},"tl":{"q":"Ano ang ibig sabihin ng “NO TURN ON RED” na karatula?","o":["Kumanan lang pagkatapos huminto nang buo","Lumiko lang kapag walang dumarating na sasakyan","Lumiko sa pula lang kapag gabi","Hintayin ang berdeng ilaw bago ka lumiko"],"h1":"Binabago ng karatula kung ano ang puwede mong gawin habang pula ang ilaw.","h2":"Ang “NO TURN ON RED” na karatula ay nangangahulugang hindi ka puwedeng lumiko habang pula ang ilaw, kaya dapat mong hintayin ang berdeng ilaw.","p":"Tama. Ang “NO TURN ON RED” ay nangangahulugang hintayin ang berde."},"ar":{"q":"ماذا تعني لافتة «NO TURN ON RED» (ممنوع الانعطاف عند الإشارة الحمراء)؟","o":["انعطف يمينًا فقط بعد توقف تام","انعطف فقط عندما لا تأتي سيارات","انعطف عند الإشارة الحمراء في الليل فقط","انتظر الإشارة الخضراء قبل أن تنعطف"],"h1":"اللافتة تغيّر ما يُسمح لك به عندما تكون الإشارة حمراء.","h2":"لافتة «NO TURN ON RED» تعني أنه ممنوع أن تنعطف والإشارة حمراء، لذلك يجب أن تنتظر الإشارة الخضراء.","p":"صحيح. ممنوع الانعطاف عند الأحمر يعني: انتظر الأخضر."},"ht":{"q":"Kisa yon siy “NO TURN ON RED” vle di?","o":["Vire adwat sèlman apre ou fin kanpe nèt","Vire sèlman lè pa gen machin k ap vini","Vire sou limyè wouj sèlman lannwit","Tann limyè vèt la anvan ou vire"],"h1":"Siy la chanje sa ou ka fè pandan limyè a wouj.","h2":"Yon siy “NO TURN ON RED” vle di ou pa ka vire pandan limyè a wouj, kidonk ou dwe tann limyè vèt la.","p":"Se sa. “NO TURN ON RED” vle di tann limyè vèt la."},"ref":{"doc":"FL","page":51}},{"id":"signs-020","scope":"US","cat":"signs","sign":{"shape":"rect-white","text":"KEEP RIGHT"},"c":0,"en":{"q":"A KEEP RIGHT sign stands at the front of a median. What does it mean?","o":["Stay to the right of the median or island","Move to the right lane to exit","The right lane ends ahead","Use the right lane only to pass"],"h1":"Think about which side of the median your car should go.","h2":"A KEEP RIGHT sign means you must drive on the right side of the median or island ahead.","p":"Right. Keep right means pass the median on its right side."},"es":{"q":"Una señal KEEP RIGHT (manténgase a la derecha) está al inicio de una isla. ¿Qué significa?","o":["Pasar por la derecha de la isla o el divisor","Cambiarse al carril derecho para salir","El carril derecho se termina más adelante","Usar el carril derecho solo para rebasar"],"h1":"Piense por qué lado de la isla debe pasar su carro.","h2":"Una señal de manténgase a la derecha quiere decir que usted debe pasar por el lado derecho de la isla o el divisor que está adelante.","p":"Correcto. Manténgase a la derecha significa pasar la isla por su lado derecho."},"zh":{"q":"一个 “KEEP RIGHT”（靠右行驶）标志立在中央隔离带的前端。它是什么意思？","o":["从隔离带或安全岛的右边通过","换到右车道准备出口","右车道在前方结束","只能用右车道超车"],"h1":"想一想：你的车应该走隔离带的哪一边。","h2":"“KEEP RIGHT”（靠右行驶）标志表示你必须从前方隔离带或安全岛的右边开过去。","p":"对。靠右行驶表示从隔离带的右边通过。"},"vi":{"q":"Biển “KEEP RIGHT” (Đi bên phải) đặt ở đầu một dải phân cách. Biển này có nghĩa là gì?","o":["Đi ở bên phải dải phân cách hoặc đảo giao thông","Chuyển sang làn phải để ra khỏi đường","Làn bên phải sắp hết","Chỉ dùng làn bên phải để vượt"],"h1":"Hãy nghĩ xem xe bạn nên đi ở bên nào của dải phân cách.","h2":"Biển “KEEP RIGHT” nghĩa là bạn phải chạy ở bên phải của dải phân cách hoặc đảo giao thông phía trước.","p":"Đúng rồi. Đi bên phải nghĩa là chạy qua bên phải dải phân cách."},"tl":{"q":"May “KEEP RIGHT” na karatula sa harap ng isang median. Ano ang ibig sabihin nito?","o":["Manatili sa kanan ng median o isla","Lumipat sa kanang linya para lumabas","Matatapos ang kanang linya sa unahan","Gamitin ang kanang linya para lang mag-overtake"],"h1":"Isipin kung sa aling bahagi ng median dapat dumaan ang sasakyan mo.","h2":"Ang “KEEP RIGHT” na karatula (Manatili sa kanan) ay nangangahulugang dapat kang magmaneho sa kanang bahagi ng median o isla sa unahan.","p":"Tama. Ang “KEEP RIGHT” ay nangangahulugang dumaan sa kanang bahagi ng median."},"ar":{"q":"لافتة «KEEP RIGHT» (الزم اليمين) موجودة في بداية جزيرة وسطية. ماذا تعني؟","o":["ابقَ على يمين الجزيرة الوسطية أو الجزيرة","انتقل إلى المسار الأيمن لتخرج","المسار الأيمن ينتهي في الأمام","استخدم المسار الأيمن للتجاوز فقط"],"h1":"فكّر في أي جانب من الجزيرة الوسطية يجب أن تمر سيارتك.","h2":"لافتة «KEEP RIGHT» تعني أنه يجب أن تقود على الجانب الأيمن من الجزيرة الوسطية أو الجزيرة التي أمامك.","p":"صحيح. الزم اليمين يعني: مُرّ على يمين الجزيرة الوسطية."},"ht":{"q":"Yon siy “KEEP RIGHT” (rete adwat) kanpe devan yon separasyon nan mitan wout la. Kisa li vle di?","o":["Rete sou bò dwat separasyon an oswa zile a","Ale nan koulwa dwat la pou sòti","Koulwa dwat la fini pi devan","Sèvi ak koulwa dwat la sèlman pou double"],"h1":"Panse sou ki bò separasyon an machin ou dwe pase.","h2":"Yon siy “KEEP RIGHT” vle di ou dwe kondui sou bò dwat separasyon an oswa zile ki devan an.","p":"Se sa. “KEEP RIGHT” vle di pase sou bò dwat separasyon an."},"ref":{"doc":"FL","page":48}},{"id":"signs-021","scope":"US","cat":"signs","sign":{"shape":"rect-white","text":"ONLY"},"c":1,"en":{"q":"A sign over your lane shows only a left arrow. What must you do?","o":["You may go straight or turn left","You must turn left from this lane","You may turn left or right","You must change lanes at the light"],"h1":"The arrows show what each lane is allowed to do.","h2":"When the sign over your lane shows only a left arrow, that lane is for left turns, so you must turn left.","p":"Right. A left-only arrow means you must turn left."},"es":{"q":"Una señal encima de su carril muestra solo una flecha a la izquierda. ¿Qué debe hacer?","o":["Puede seguir derecho o doblar a la izquierda","Debe doblar a la izquierda desde este carril","Puede doblar a la izquierda o a la derecha","Debe cambiar de carril en el semáforo"],"h1":"Las flechas muestran lo que se permite en cada carril.","h2":"Cuando la señal encima de su carril muestra solo una flecha a la izquierda, ese carril es para doblar a la izquierda, así que usted debe doblar a la izquierda.","p":"Correcto. Una flecha solo a la izquierda significa que debe doblar a la izquierda."},"zh":{"q":"你车道上方的标志只有一个左转箭头。你必须怎么做？","o":["你可以直行或左转","你必须从这条车道左转","你可以左转或右转","你必须在红绿灯处换车道"],"h1":"箭头告诉你每条车道可以怎么走。","h2":"当你车道上方的标志只有左转箭头时，这条车道是左转车道，所以你必须左转。","p":"对。只有左转箭头表示你必须左转。"},"vi":{"q":"Biển phía trên làn của bạn chỉ có một mũi tên rẽ trái. Bạn phải làm gì?","o":["Bạn được đi thẳng hoặc rẽ trái","Bạn phải rẽ trái từ làn này","Bạn được rẽ trái hoặc rẽ phải","Bạn phải đổi làn ở chỗ đèn"],"h1":"Các mũi tên cho biết mỗi làn được phép đi hướng nào.","h2":"Khi biển trên làn của bạn chỉ có mũi tên rẽ trái, làn đó dành cho xe rẽ trái, nên bạn phải rẽ trái.","p":"Đúng rồi. Chỉ có mũi tên trái nghĩa là bạn phải rẽ trái."},"tl":{"q":"Ang karatula sa itaas ng linya mo ay nagpapakita lang ng arrow pakaliwa. Ano ang dapat mong gawin?","o":["Puwede kang dumiretso o kumaliwa","Dapat kang kumaliwa mula sa linyang ito","Puwede kang kumaliwa o kumanan","Dapat kang lumipat ng linya sa may ilaw"],"h1":"Ipinapakita ng mga arrow kung ano ang pinapayagan sa bawat linya.","h2":"Kapag ang karatula sa itaas ng linya mo ay nagpapakita lang ng arrow pakaliwa, ang linyang iyon ay para sa pagkaliwa, kaya dapat kang kumaliwa.","p":"Tama. Ang arrow na pakaliwa lang ay nangangahulugang dapat kang kumaliwa."},"ar":{"q":"لافتة فوق مسارك تُظهر سهمًا إلى اليسار فقط. ماذا يجب أن تفعل؟","o":["يمكنك أن تسير مستقيمًا أو تنعطف يسارًا","يجب أن تنعطف يسارًا من هذا المسار","يمكنك أن تنعطف يسارًا أو يمينًا","يجب أن تغيّر المسار عند الإشارة"],"h1":"الأسهم تُظهر ما هو مسموح في كل مسار.","h2":"عندما تُظهر اللافتة فوق مسارك سهمًا إلى اليسار فقط، فهذا المسار للانعطاف يسارًا، لذلك يجب أن تنعطف يسارًا.","p":"صحيح. سهم إلى اليسار فقط يعني أنه يجب أن تنعطف يسارًا."},"ht":{"q":"Yon siy anwo koulwa ou montre sèlman yon flèch agoch. Kisa ou dwe fè?","o":["Ou ka ale tou dwat oswa vire agoch","Ou dwe vire agoch nan koulwa sa a","Ou ka vire agoch oswa adwat","Ou dwe chanje koulwa nan limyè a"],"h1":"Flèch yo montre sa chak koulwa gen dwa fè.","h2":"Lè siy anwo koulwa ou montre sèlman yon flèch agoch, koulwa sa a se pou vire agoch, kidonk ou dwe vire agoch.","p":"Se sa. Yon flèch agoch sèlman vle di ou dwe vire agoch."},"ref":{"doc":"FL","page":47}},{"id":"signs-022","scope":"US","cat":"signs","sign":{"shape":"diamond-yellow","text":"35 MPH"},"c":2,"en":{"q":"A curve warning sign has a small yellow sign below it with a speed. What is that speed?","o":["The lowest speed you may drive","The new speed limit for the road","A safe speed for the curve","A speed for trucks only"],"h1":"It is a yellow sign, not a white one.","h2":"The small yellow speed sign under a curve sign gives a safe speed for the curve in good conditions, so slow down to that speed or less.","p":"Right. The yellow speed plate gives a safe speed for the curve."},"es":{"q":"Una señal de curva tiene abajo una señal amarilla pequeña con una velocidad. ¿Qué es esa velocidad?","o":["La velocidad más baja permitida","El nuevo límite de velocidad de la vía","Una velocidad segura para la curva","Una velocidad solo para camiones"],"h1":"Es una señal amarilla, no blanca.","h2":"La señal amarilla pequeña debajo de una señal de curva le da una velocidad segura para la curva en buenas condiciones, así que baje a esa velocidad o menos.","p":"Correcto. La placa amarilla le da una velocidad segura para la curva."},"zh":{"q":"弯道警告标志下面有一个写着速度的黄色小牌子。这个速度是什么？","o":["你可以开的最低速度","这条路的新限速","过弯道的安全速度","只给卡车的速度"],"h1":"它是黄色的牌子，不是白色的。","h2":"弯道标志下面的黄色小速度牌，给出在良好条件下过这个弯道的安全速度，所以你要减速到这个速度或更低。","p":"对。黄色速度牌给出过弯道的安全速度。"},"vi":{"q":"Dưới biển báo khúc cua có một biển nhỏ màu vàng ghi tốc độ. Tốc độ đó là gì?","o":["Tốc độ thấp nhất bạn được chạy","Giới hạn tốc độ mới của con đường","Tốc độ an toàn cho khúc cua","Tốc độ chỉ dành cho xe tải"],"h1":"Đây là biển màu vàng, không phải biển màu trắng.","h2":"Biển nhỏ màu vàng dưới biển khúc cua cho biết tốc độ an toàn để qua khúc cua khi điều kiện tốt, nên bạn cần chạy chậm lại bằng hoặc thấp hơn tốc độ đó.","p":"Đúng rồi. Biển tốc độ màu vàng cho biết tốc độ an toàn qua khúc cua."},"tl":{"q":"May maliit na dilaw na karatula na may bilis sa ilalim ng karatula ng babala sa kurba. Ano ang bilis na iyon?","o":["Ang pinakamababang bilis na puwede mong takbuhin","Ang bagong speed limit ng kalsada","Isang ligtas na bilis para sa kurba","Bilis para sa mga trak lang"],"h1":"Ito ay dilaw na karatula, hindi puti.","h2":"Ang maliit na dilaw na karatula ng bilis sa ilalim ng karatula ng kurba ay nagbibigay ng ligtas na bilis para sa kurba kapag maayos ang kondisyon, kaya bumagal ka sa bilis na iyon o mas mababa pa.","p":"Tama. Ang dilaw na plaka ng bilis ay nagbibigay ng ligtas na bilis para sa kurba."},"ar":{"q":"تحت لافتة تحذير من منعطف توجد لافتة صفراء صغيرة عليها سرعة. ما هذه السرعة؟","o":["أقل سرعة مسموح لك أن تقود بها","حد السرعة الجديد للطريق","سرعة آمنة للمنعطف","سرعة للشاحنات فقط"],"h1":"إنها لافتة صفراء، وليست بيضاء.","h2":"لافتة السرعة الصفراء الصغيرة تحت لافتة المنعطف تعطي سرعة آمنة للمنعطف عندما تكون الظروف جيدة، لذلك خفف سرعتك إلى هذه السرعة أو أقل.","p":"صحيح. لوحة السرعة الصفراء تعطي سرعة آمنة للمنعطف."},"ht":{"q":"Yon siy avètisman pou koub gen yon ti siy jòn anba l ak yon vitès. Ki vitès sa a ye?","o":["Vitès ki pi ba ou ka kondui","Nouvo limit vitès pou wout la","Yon vitès ki an sekirite pou koub la","Yon vitès pou kamyon sèlman"],"h1":"Se yon siy jòn, se pa yon siy blan.","h2":"Ti siy vitès jòn anba siy koub la bay yon vitès ki an sekirite pou koub la lè kondisyon yo bon, kidonk ralanti rive nan vitès sa a oswa mwens.","p":"Se sa. Ti siy jòn nan bay yon vitès ki an sekirite pou koub la."},"ref":{"doc":"FL","page":49}},{"id":"signs-023","scope":"US","cat":"signs","sign":{"shape":"diamond-yellow","text":"MERGE"},"c":3,"en":{"q":"A yellow sign shows a side line joining the main road. What should you expect?","o":["A railroad crossing","A dead end","A stop sign ahead","Cars entering your road from the side"],"h1":"Think about two roads becoming one.","h2":"This merge sign warns that cars will enter your road from the side, so be ready to adjust your speed or make room.","p":"Right. The merge sign means cars will join your road."},"es":{"q":"Una señal amarilla muestra una línea lateral que se une a la vía principal. ¿Qué debe esperar?","o":["Un cruce de tren","Una calle sin salida","Una señal de pare más adelante","Carros que entran a su vía desde un lado"],"h1":"Piense en dos vías que se vuelven una.","h2":"Esta señal de incorporación avisa que entrarán carros a su vía desde un lado, así que esté listo para ajustar su velocidad o darles espacio.","p":"Correcto. La señal de incorporación significa que entrarán carros a su vía."},"zh":{"q":"一个黄色标志上画着一条旁边的线并入主路。你应该预料到什么？","o":["铁路道口","死路","前方有停车标志","有车从旁边开进你的路"],"h1":"想一想：两条路变成一条路。","h2":"这个并道标志提醒你会有车从旁边开进你的路，所以要准备调整车速或让出空间。","p":"对。并道标志表示有车会开进你的路。"},"vi":{"q":"Một biển màu vàng có hình một đường nhánh nhập vào đường chính. Bạn nên chờ đợi điều gì?","o":["Chỗ băng qua đường sắt","Đường cụt","Biển dừng phía trước","Xe từ bên hông nhập vào đường của bạn"],"h1":"Hãy nghĩ đến hai con đường nhập lại thành một.","h2":"Biển nhập làn này cảnh báo rằng xe sẽ từ bên hông đi vào đường của bạn, nên bạn cần sẵn sàng đổi tốc độ hoặc chừa chỗ cho họ.","p":"Đúng rồi. Biển nhập làn nghĩa là xe khác sẽ vào đường của bạn."},"tl":{"q":"Ang dilaw na karatula ay nagpapakita ng isang guhit sa gilid na sumasama sa pangunahing kalsada. Ano ang dapat mong asahan?","o":["Tawiran ng tren","Dulo ng daan (dead end)","May “STOP” sign sa unahan","Mga sasakyang papasok sa daan mo mula sa gilid"],"h1":"Isipin ang dalawang daan na nagiging isa.","h2":"Ang karatulang ito ng merge ay babala na may mga sasakyang papasok sa daan mo mula sa gilid, kaya maging handa na ayusin ang bilis mo o magbigay ng puwang.","p":"Tama. Ang karatula ng merge ay nangangahulugang may mga sasakyang sasama sa daan mo."},"ar":{"q":"لافتة صفراء تُظهر خطًا جانبيًا ينضم إلى الطريق الرئيسي. ماذا يجب أن تتوقع؟","o":["تقاطعًا مع سكة حديد","طريقًا مسدودًا","لافتة «STOP» (قف) في الأمام","سيارات تدخل طريقك من الجانب"],"h1":"فكّر في طريقين يصبحان طريقًا واحدًا.","h2":"لافتة الاندماج هذه تحذّر من أن سيارات ستدخل طريقك من الجانب، لذلك كن مستعدًا لتغيير سرعتك أو لترك مكان لها.","p":"صحيح. لافتة الاندماج تعني أن سيارات ستنضم إلى طريقك."},"ht":{"q":"Yon siy jòn montre yon liy sou kote k ap kole ak wout prensipal la. Kisa ou dwe atann?","o":["Yon kote tren travèse","Yon wout ki bloke","Yon siy “STOP” pi devan","Machin k ap antre sou wout ou a sou kote"],"h1":"Panse ak de wout k ap vin tounen yon sèl.","h2":"Siy sa a avèti ou gen machin ki pral antre sou wout ou a sou kote, kidonk pare pou chanje vitès ou oswa fè plas pou yo.","p":"Se sa. Siy sa a vle di gen machin ki pral antre sou wout ou a."},"ref":{"doc":"FL","page":49}},{"id":"signs-024","scope":"US","cat":"signs","sign":{"shape":"diamond-yellow","text":"RIGHT LANE ENDS"},"c":0,"en":{"q":"You are in the right lane. A sign says RIGHT LANE ENDS. What should you do?","o":["Move left when it is safe","Speed up to stay ahead of others","Stop at the end of the lane","Drive on the shoulder"],"h1":"Your lane will soon be gone.","h2":"When the sign says your lane ends, you should signal and move into the next lane when it is safe.","p":"Right. When your lane ends, move over safely."},"es":{"q":"Usted va en el carril derecho. Una señal dice RIGHT LANE ENDS (el carril derecho termina). ¿Qué debe hacer?","o":["Pasarse a la izquierda cuando sea seguro","Acelerar para quedar delante de los demás","Pararse al final del carril","Manejar por el acotamiento"],"h1":"Su carril pronto desaparece.","h2":"Cuando la señal dice que su carril termina, usted debe poner la direccional y pasarse al otro carril cuando sea seguro.","p":"Correcto. Cuando su carril termina, cámbiese con cuidado."},"zh":{"q":"你在右车道。一个标志写着 “RIGHT LANE ENDS”（右车道结束）。你应该怎么做？","o":["安全时换到左边车道","加速，开到别的车前面","在车道尽头停车","在路肩上开"],"h1":"你的车道很快就没有了。","h2":"当标志说你的车道要结束时，你应该打转向灯，在安全时换到旁边的车道。","p":"对。你的车道结束时，要安全地换道。"},"vi":{"q":"Bạn đang ở làn bên phải. Một biển ghi “RIGHT LANE ENDS” (Làn phải sắp hết). Bạn nên làm gì?","o":["Chuyển sang trái khi an toàn","Tăng tốc để chạy trước xe khác","Dừng lại ở cuối làn","Chạy trên lề đường"],"h1":"Làn của bạn sắp không còn nữa.","h2":"Khi biển báo làn của bạn sắp hết, bạn cần bật xi-nhan và chuyển sang làn bên cạnh khi an toàn.","p":"Đúng rồi. Khi làn của bạn hết, hãy chuyển làn an toàn."},"tl":{"q":"Nasa kanang linya ka. Nakasulat sa karatula ang “RIGHT LANE ENDS” (Matatapos ang kanang linya). Ano ang dapat mong gawin?","o":["Lumipat sa kaliwa kapag ligtas na","Bumilis para mauna sa iba","Huminto sa dulo ng linya","Magmaneho sa gilid ng kalsada"],"h1":"Mawawala na sa lalong madaling panahon ang linya mo.","h2":"Kapag sinasabi ng karatula na matatapos ang linya mo, dapat kang mag-signal at lumipat sa katabing linya kapag ligtas na.","p":"Tama. Kapag natatapos ang linya mo, lumipat nang ligtas."},"ar":{"q":"أنت في المسار الأيمن. لافتة مكتوب عليها «RIGHT LANE ENDS» (المسار الأيمن ينتهي). ماذا يجب أن تفعل؟","o":["انتقل إلى اليسار عندما يكون ذلك آمنًا","زد السرعة لتبقى أمام الآخرين","توقف في نهاية المسار","قُد على كتف الطريق"],"h1":"مسارك سيختفي قريبًا.","h2":"عندما تقول اللافتة إن مسارك ينتهي، يجب أن تشغّل الإشارة وتنتقل إلى المسار المجاور عندما يكون ذلك آمنًا.","p":"صحيح. عندما ينتهي مسارك، انتقل إلى مسار آخر بأمان."},"ht":{"q":"Ou nan koulwa dwat la. Yon siy di “RIGHT LANE ENDS” (koulwa dwat la fini). Kisa ou dwe fè?","o":["Pase agoch lè sa an sekirite","Akselere pou rete devan lòt yo","Kanpe nan bout koulwa a","Kondui sou arebò wout la"],"h1":"Koulwa ou a pral disparèt talè.","h2":"Lè siy la di koulwa ou a fini, ou dwe mete siyal epi pase nan lòt koulwa a lè sa an sekirite.","p":"Se sa. Lè koulwa ou fini, chanje koulwa an sekirite."},"ref":{"doc":"FL","page":49}},{"id":"signs-025","scope":"US","cat":"signs","sign":{"shape":"diamond-yellow","text":"DIVIDED HIGHWAY"},"c":1,"en":{"q":"A warning sign says a divided highway begins. What changes ahead?","o":["The road comes to an end","A median will separate the two directions","The speed limit goes up","Two lanes become one lane"],"h1":"Think about what divides the road.","h2":"A divided highway begins sign means a median will soon separate traffic going each way, so keep to the right of it.","p":"Right. A median will separate the two directions."},"es":{"q":"Una señal de advertencia dice que empieza una carretera dividida. ¿Qué cambia más adelante?","o":["La vía se termina","Una isla o divisor va a separar los dos sentidos","El límite de velocidad sube","Dos carriles se vuelven uno"],"h1":"Piense en qué divide la vía.","h2":"La señal de que empieza una carretera dividida significa que pronto un divisor va a separar el tráfico de cada sentido, así que manténgase a la derecha de él.","p":"Correcto. Un divisor va a separar los dos sentidos."},"zh":{"q":"一个警告标志说分隔公路开始了。前方有什么变化？","o":["道路到头了","中央隔离带会把两个方向的车分开","限速提高","两条车道变成一条"],"h1":"想一想：是什么把道路分开。","h2":"“分隔公路开始” 标志表示很快会有中央隔离带把两个方向的车流分开，所以要从隔离带右边行驶。","p":"对。中央隔离带会把两个方向的车分开。"},"vi":{"q":"Một biển cảnh báo cho biết đường có dải phân cách bắt đầu. Phía trước có gì thay đổi?","o":["Con đường sắp hết","Một dải phân cách sẽ chia hai chiều xe ra","Giới hạn tốc độ tăng lên","Hai làn nhập thành một làn"],"h1":"Hãy nghĩ xem cái gì chia con đường ra.","h2":"Biển báo đường có dải phân cách bắt đầu nghĩa là sắp có một dải phân cách tách xe chạy mỗi chiều, nên bạn cần đi ở bên phải của nó.","p":"Đúng rồi. Một dải phân cách sẽ chia hai chiều xe ra."},"tl":{"q":"Sinasabi ng isang karatula ng babala na nagsisimula ang divided highway. Ano ang magbabago sa unahan?","o":["Matatapos na ang kalsada","May median na maghihiwalay sa dalawang direksyon","Tataas ang speed limit","Ang dalawang linya ay magiging isang linya"],"h1":"Isipin kung ano ang naghahati sa kalsada.","h2":"Ang karatula na nagsisimula ang divided highway ay nangangahulugang may median na maghihiwalay sa trapikong papunta sa magkabilang direksyon, kaya manatili ka sa kanan nito.","p":"Tama. May median na maghihiwalay sa dalawang direksyon."},"ar":{"q":"لافتة تحذير تقول إن طريقًا سريعًا مقسومًا يبدأ. ما الذي يتغيّر في الأمام؟","o":["الطريق ينتهي","جزيرة وسطية ستفصل بين الاتجاهين","حد السرعة يرتفع","مساران يصبحان مسارًا واحدًا"],"h1":"فكّر في ما يقسم الطريق.","h2":"لافتة بداية الطريق السريع المقسوم تعني أن جزيرة وسطية ستفصل قريبًا بين السيارات في كل اتجاه، لذلك ابقَ على يمينها.","p":"صحيح. جزيرة وسطية ستفصل بين الاتجاهين."},"ht":{"q":"Yon siy avètisman di yon wout ki gen separasyon kòmanse. Kisa ki chanje pi devan?","o":["Wout la fini","Yon separasyon pral separe de direksyon yo","Limit vitès la monte","De koulwa vin tounen yon sèl"],"h1":"Panse ak sa ki separe wout la.","h2":"Siy sa a vle di talè gen yon separasyon nan mitan wout la k ap separe machin k ap ale nan chak direksyon, kidonk rete sou bò dwat li.","p":"Se sa. Yon separasyon pral separe de direksyon yo."},"ref":{"doc":"FL","page":49}},{"id":"signs-026","scope":"US","cat":"signs","sign":{"shape":"diamond-yellow","text":"DIVIDED HIGHWAY ENDS"},"c":2,"en":{"q":"A sign says the divided highway ends. What should you expect?","o":["You may now pass on the right","The road becomes one-way","Cars coming toward you with no divider","A bridge is just ahead"],"h1":"Think about what happens when the median is gone.","h2":"When the divided highway ends, there is no median anymore, so cars going the other way will be right beside you and you must keep right.","p":"Right. With no divider, oncoming cars share the road with you."},"es":{"q":"Una señal dice que termina la carretera dividida. ¿Qué debe esperar?","o":["Ahora puede rebasar por la derecha","La vía se vuelve de un solo sentido","Carros que vienen de frente sin divisor","Un puente justo adelante"],"h1":"Piense en lo que pasa cuando ya no hay divisor.","h2":"Cuando termina la carretera dividida, ya no hay divisor, así que los carros que van en el otro sentido pasarán a su lado y usted debe mantenerse a la derecha.","p":"Correcto. Sin divisor, los carros de frente comparten la vía con usted."},"zh":{"q":"一个标志说分隔公路结束了。你应该预料到什么？","o":["现在可以从右边超车","道路变成单行道","对面来车，中间没有隔离","前方马上有一座桥"],"h1":"想一想：没有中央隔离带后会怎样。","h2":"分隔公路结束后就没有中央隔离带了，所以对面开来的车就在你旁边，你必须靠右行驶。","p":"对。没有隔离带，对面来车和你共用道路。"},"vi":{"q":"Một biển cho biết đường có dải phân cách kết thúc. Bạn nên chờ đợi điều gì?","o":["Bây giờ bạn được vượt bên phải","Con đường trở thành đường một chiều","Xe chạy ngược chiều về phía bạn mà không có gì ngăn cách","Ngay phía trước có cây cầu"],"h1":"Hãy nghĩ xem điều gì xảy ra khi không còn dải phân cách.","h2":"Khi đường có dải phân cách kết thúc, không còn dải phân cách nữa, nên xe chạy ngược chiều sẽ ở ngay cạnh bạn và bạn phải đi bên phải.","p":"Đúng rồi. Không có dải phân cách, xe ngược chiều chạy chung đường với bạn."},"tl":{"q":"Sinasabi ng isang karatula na matatapos na ang divided highway. Ano ang dapat mong asahan?","o":["Puwede ka nang mag-overtake sa kanan","Magiging one-way ang kalsada","Mga sasakyang paparating sa iyo na walang harang sa gitna","May tulay sa unahan"],"h1":"Isipin kung ano ang mangyayari kapag wala na ang median.","h2":"Kapag natapos ang divided highway, wala nang median, kaya ang mga sasakyang papunta sa kabilang direksyon ay nasa tabi mo na mismo at dapat kang manatili sa kanan.","p":"Tama. Kapag walang harang, kasama mo sa kalsada ang mga paparating na sasakyan."},"ar":{"q":"لافتة تقول إن الطريق السريع المقسوم ينتهي. ماذا يجب أن تتوقع؟","o":["الآن يمكنك أن تتجاوز من اليمين","الطريق يصبح باتجاه واحد","سيارات تأتي نحوك بدون فاصل","جسر قريب جدًا في الأمام"],"h1":"فكّر في ما يحدث عندما تختفي الجزيرة الوسطية.","h2":"عندما ينتهي الطريق السريع المقسوم لا توجد جزيرة وسطية بعد ذلك، لذلك ستكون السيارات القادمة من الاتجاه الآخر بجانبك مباشرة، ويجب أن تلزم اليمين.","p":"صحيح. بدون فاصل، السيارات القادمة تشاركك الطريق."},"ht":{"q":"Yon siy di wout ki gen separasyon an fini. Kisa ou dwe atann?","o":["Kounye a ou ka double sou bò dwat","Wout la vin yon sèl direksyon","Machin k ap vin sou ou san anyen pou separe nou","Gen yon pon touprè"],"h1":"Panse ak sa k ap pase lè separasyon an pa la ankò.","h2":"Lè wout ki gen separasyon an fini, pa gen separasyon ankò, kidonk machin k ap ale nan lòt direksyon an ap pase bò kote ou, e ou dwe rete adwat.","p":"Se sa. San separasyon, machin k ap vin sou ou pataje wout la avè ou."},"ref":{"doc":"FL","page":49}},{"id":"signs-027","scope":"US","cat":"signs","sign":{"shape":"diamond-yellow","text":"SLIPPERY WHEN WET"},"c":0,"en":{"q":"A sign says SLIPPERY WHEN WET. It is raining. What should you do?","o":["Slow down and avoid sudden moves","Turn on cruise control","Speed up to get past the area","Brake hard if the car slides"],"h1":"Think about how tires grip a wet road.","h2":"A wet road can be slick, so you should slow down and avoid quick turns or hard braking.","p":"Right. On a slippery road, slow down and move smoothly."},"es":{"q":"Una señal dice SLIPPERY WHEN WET (resbaloso cuando está mojado). Está lloviendo. ¿Qué debe hacer?","o":["Bajar la velocidad y evitar movimientos bruscos","Prender el control de velocidad","Acelerar para pasar rápido esa zona","Frenar fuerte si el carro resbala"],"h1":"Piense en cómo agarran las llantas en una vía mojada.","h2":"Una vía mojada puede estar resbalosa, así que usted debe bajar la velocidad y evitar vueltas rápidas o frenazos.","p":"Correcto. En una vía resbalosa, baje la velocidad y maneje con suavidad."},"zh":{"q":"一个标志写着 “SLIPPERY WHEN WET”（路湿易滑）。现在正在下雨。你应该怎么做？","o":["减速，避免突然的动作","打开定速巡航","加速，快快开过这一段","车打滑时用力刹车"],"h1":"想一想：轮胎在湿路上抓地怎么样。","h2":"湿的路面可能很滑，所以你要减速，避免急转弯或急刹车。","p":"对。路滑时要减速，动作要平稳。"},"vi":{"q":"Một biển ghi “SLIPPERY WHEN WET” (Trơn khi ướt). Trời đang mưa. Bạn nên làm gì?","o":["Chạy chậm lại và tránh cử động đột ngột","Bật chế độ tự giữ tốc độ (cruise control)","Tăng tốc để qua khu vực này","Đạp thắng mạnh nếu xe bị trượt"],"h1":"Hãy nghĩ xem bánh xe bám đường ướt như thế nào.","h2":"Đường ướt có thể trơn, nên bạn cần chạy chậm lại và tránh rẽ gấp hoặc đạp thắng mạnh.","p":"Đúng rồi. Trên đường trơn, hãy chạy chậm và lái nhẹ nhàng."},"tl":{"q":"Nakasulat sa karatula ang “SLIPPERY WHEN WET” (Madulas kapag basa). Umuulan. Ano ang dapat mong gawin?","o":["Bumagal at iwasan ang biglang galaw","Buksan ang cruise control","Bumilis para malampasan ang lugar","Pumreno nang malakas kapag dumulas ang sasakyan"],"h1":"Isipin kung paano kumakapit ang gulong sa basang kalsada.","h2":"Ang basang kalsada ay maaaring madulas, kaya dapat kang bumagal at iwasan ang mabilis na pagliko o malakas na pagpreno.","p":"Tama. Sa madulas na kalsada, bumagal at gumalaw nang maayos at dahan-dahan."},"ar":{"q":"لافتة مكتوب عليها «SLIPPERY WHEN WET» (زلق عند البلل). المطر ينزل. ماذا يجب أن تفعل؟","o":["خفف السرعة وتجنّب الحركات المفاجئة","شغّل مثبّت السرعة","زد السرعة لتتجاوز المنطقة","اضغط الفرامل بقوة إذا انزلقت السيارة"],"h1":"فكّر في كيف تمسك الإطارات بالطريق المبلل.","h2":"الطريق المبلل قد يكون زلقًا، لذلك يجب أن تخفف السرعة وتتجنب الانعطاف السريع أو الضغط القوي على الفرامل.","p":"صحيح. على الطريق الزلق، خفف السرعة وتحرك بهدوء."},"ht":{"q":"Yon siy di “SLIPPERY WHEN WET” (glise lè l mouye). Lapli ap tonbe. Kisa ou dwe fè?","o":["Ralanti epi evite fè mouvman brid sou kou","Limen kontwòl vitès otomatik la","Akselere pou pase zòn nan vit","Frennen fò si machin nan glise"],"h1":"Panse ki jan kawotchou yo kenbe sou yon wout mouye.","h2":"Yon wout mouye ka glise, kidonk ou dwe ralanti epi evite vire vit oswa frennen fò.","p":"Se sa. Sou yon wout ki glise, ralanti epi kondui dousman."},"ref":{"doc":"FL","page":50}},{"id":"signs-028","scope":"US","cat":"signs","sign":{"shape":"diamond-yellow","text":"SIGNAL AHEAD"},"c":1,"en":{"q":"A yellow sign shows a traffic light. What does it warn you about?","o":["A stop sign is ahead","A traffic signal is ahead","A railroad is ahead","A police checkpoint is ahead"],"h1":"Look at the picture on the sign.","h2":"This sign warns that a traffic signal is ahead, so be ready to slow down or stop.","p":"Right. The sign warns that a traffic light is ahead."},"es":{"q":"Una señal amarilla muestra un semáforo. ¿De qué le avisa?","o":["Hay una señal de pare más adelante","Hay un semáforo más adelante","Hay un tren más adelante","Hay un retén de policía más adelante"],"h1":"Mire el dibujo en la señal.","h2":"Esta señal avisa que hay un semáforo más adelante, así que esté listo para bajar la velocidad o pararse.","p":"Correcto. La señal avisa que hay un semáforo más adelante."},"zh":{"q":"一个黄色标志上画着红绿灯。它提醒你什么？","o":["前方有停车标志","前方有交通信号灯","前方有铁路","前方有警察检查站"],"h1":"看看标志上的图。","h2":"这个标志提醒你前方有交通信号灯，所以要准备减速或停车。","p":"对。这个标志提醒你前方有红绿灯。"},"vi":{"q":"Một biển màu vàng có hình đèn giao thông. Biển này cảnh báo bạn về điều gì?","o":["Phía trước có biển dừng","Phía trước có đèn giao thông","Phía trước có đường sắt","Phía trước có trạm kiểm tra của cảnh sát"],"h1":"Hãy nhìn hình vẽ trên biển.","h2":"Biển này cảnh báo phía trước có đèn giao thông, nên bạn cần sẵn sàng chạy chậm lại hoặc dừng.","p":"Đúng rồi. Biển này cảnh báo phía trước có đèn giao thông."},"tl":{"q":"Ang dilaw na karatula ay nagpapakita ng ilaw trapiko. Tungkol saan ang babala nito?","o":["May “STOP” sign sa unahan","May ilaw trapiko sa unahan","May riles ng tren sa unahan","May checkpoint ng pulis sa unahan"],"h1":"Tingnan ang larawan sa karatula.","h2":"Ang karatulang ito ay babala na may ilaw trapiko sa unahan, kaya maging handang bumagal o huminto.","p":"Tama. Ang karatula ay babala na may ilaw trapiko sa unahan."},"ar":{"q":"لافتة صفراء تُظهر إشارة مرور ضوئية. ممّ تحذّرك؟","o":["لافتة «STOP» (قف) في الأمام","إشارة مرور ضوئية في الأمام","سكة حديد في الأمام","نقطة تفتيش للشرطة في الأمام"],"h1":"انظر إلى الصورة على اللافتة.","h2":"هذه اللافتة تحذّر من أن إشارة مرور ضوئية في الأمام، لذلك كن مستعدًا لتخفيف السرعة أو للتوقف.","p":"صحيح. اللافتة تحذّر من أن إشارة ضوئية في الأمام."},"ht":{"q":"Yon siy jòn montre yon limyè trafik. Pou kisa li avèti ou?","o":["Gen yon siy “STOP” pi devan","Gen yon limyè trafik pi devan","Gen yon ray tren pi devan","Gen yon baryè polis pi devan"],"h1":"Gade foto ki sou siy la.","h2":"Siy sa a avèti ou gen yon limyè trafik pi devan, kidonk pare pou ralanti oswa kanpe.","p":"Se sa. Siy la avèti ou gen yon limyè trafik pi devan."},"ref":{"doc":"FL","page":49}},{"id":"signs-029","scope":"US","cat":"signs","sign":{"shape":"diamond-yellow","text":"DEER CROSSING"},"c":2,"en":{"q":"A yellow sign shows a deer. What should you do?","o":["Look for a nearby zoo","Pull over and wait","Watch for deer near or on the road","Speed up through the area"],"h1":"Animals may run onto the road with no warning.","h2":"A deer crossing sign means deer often cross there, so you should slow down and watch the sides of the road, especially at dawn and dusk.","p":"Right. Watch for deer near the road."},"es":{"q":"Una señal amarilla muestra un venado. ¿Qué debe hacer?","o":["Buscar un zoológico cerca","Orillarse y esperar","Estar atento a venados cerca o en la vía","Acelerar para pasar la zona"],"h1":"Los animales pueden salir a la vía sin aviso.","h2":"Una señal de cruce de venados quiere decir que los venados cruzan seguido por ahí, así que usted debe bajar la velocidad y mirar los lados de la vía, sobre todo al amanecer y al anochecer.","p":"Correcto. Esté atento a los venados cerca de la vía."},"zh":{"q":"一个黄色标志上画着一只鹿。你应该怎么做？","o":["找找附近的动物园","靠边停车等待","注意路边或路上的鹿","加速开过这一段"],"h1":"动物可能突然跑到路上。","h2":"鹿出没标志表示鹿常在这里过马路，所以你要减速，注意路的两边，特别是在清晨和傍晚。","p":"对。注意路边的鹿。"},"vi":{"q":"Một biển màu vàng có hình con nai. Bạn nên làm gì?","o":["Tìm sở thú gần đó","Tấp vào lề và chờ","Chú ý nai ở gần hoặc trên đường","Tăng tốc qua khu vực này"],"h1":"Thú vật có thể chạy ra đường mà không báo trước.","h2":"Biển nai băng qua đường nghĩa là nai thường đi qua chỗ đó, nên bạn cần chạy chậm lại và nhìn hai bên đường, nhất là lúc bình minh và hoàng hôn.","p":"Đúng rồi. Hãy chú ý nai ở gần đường."},"tl":{"q":"Ang dilaw na karatula ay nagpapakita ng usa. Ano ang dapat mong gawin?","o":["Hanapin ang zoo sa malapit","Tumabi at maghintay","Mag-ingat sa mga usa malapit o nasa kalsada","Bumilis sa lugar na iyon"],"h1":"Maaaring tumakbo ang mga hayop papunta sa kalsada nang walang babala.","h2":"Ang karatula ng tawiran ng usa ay nangangahulugang madalas tumawid ang mga usa doon, kaya dapat kang bumagal at bantayan ang gilid ng kalsada, lalo na sa madaling-araw at takipsilim.","p":"Tama. Mag-ingat sa mga usa malapit sa kalsada."},"ar":{"q":"لافتة صفراء تُظهر غزالًا. ماذا يجب أن تفعل؟","o":["ابحث عن حديقة حيوانات قريبة","توقف على جانب الطريق وانتظر","انتبه للغزلان قرب الطريق أو عليه","زد السرعة في هذه المنطقة"],"h1":"الحيوانات قد تركض إلى الطريق بدون إنذار.","h2":"لافتة عبور الغزلان تعني أن الغزلان تعبر هناك كثيرًا، لذلك يجب أن تخفف السرعة وتراقب جانبي الطريق، خاصة عند الفجر وعند الغروب.","p":"صحيح. انتبه للغزلان قرب الطريق."},"ht":{"q":"Yon siy jòn montre yon sèf. Kisa ou dwe fè?","o":["Chèche yon zoo ki toupre","Rale sou kote epi tann","Veye si gen sèf toupre wout la oswa sou wout la","Akselere pou travèse zòn nan"],"h1":"Bèt ka kouri antre sou wout la san avètisman.","h2":"Yon siy sèf vle di sèf konn travèse la a, kidonk ou dwe ralanti epi gade de bò wout la, sitou lè solèy ap leve ak lè l ap kouche.","p":"Se sa. Veye si gen sèf toupre wout la."},"ref":{"doc":"FL","page":50}},{"id":"signs-030","scope":"US","cat":"signs","sign":{"shape":"diamond-yellow","text":"LOW CLEARANCE"},"c":3,"en":{"q":"A sign warns of LOW CLEARANCE ahead. What does it mean?","o":["The road gets narrow","The shoulder is soft","A steep hill is ahead","A low bridge or overpass is ahead"],"h1":"Clearance is the space above your vehicle.","h2":"A low clearance sign means a bridge or overpass ahead is low, so tall vehicles may not fit under it.","p":"Right. Low clearance means a low bridge or overpass is ahead."},"es":{"q":"Una señal avisa LOW CLEARANCE (altura baja) más adelante. ¿Qué significa?","o":["La vía se hace angosta","El acotamiento está blando","Hay una cuesta empinada","Hay un puente o paso elevado bajo"],"h1":"Piense en el espacio que hay encima de su vehículo.","h2":"Una señal de altura baja quiere decir que un puente o paso elevado más adelante es bajo, así que los vehículos altos podrían no caber.","p":"Correcto. Altura baja significa que hay un puente o paso elevado bajo."},"zh":{"q":"一个标志提醒前方 “LOW CLEARANCE”（限高）。它是什么意思？","o":["道路变窄","路肩很软","前方有陡坡","前方有很低的桥或天桥"],"h1":"“Clearance” 是你的车上方的空间。","h2":"限高标志表示前方的桥或天桥很低，所以高的车辆可能过不去。","p":"对。限高表示前方有很低的桥或天桥。"},"vi":{"q":"Một biển cảnh báo “LOW CLEARANCE” (Chiều cao thấp) phía trước. Biển này có nghĩa là gì?","o":["Đường hẹp lại","Lề đường bị mềm","Phía trước có dốc cao","Phía trước có cầu hoặc cầu vượt thấp"],"h1":"Chiều cao ở đây là khoảng trống phía trên xe của bạn.","h2":"Biển chiều cao thấp nghĩa là cây cầu hoặc cầu vượt phía trước thấp, nên xe cao có thể không chui qua được.","p":"Đúng rồi. Chiều cao thấp nghĩa là phía trước có cầu hoặc cầu vượt thấp."},"tl":{"q":"May karatula na nagbababala ng “LOW CLEARANCE” (Mababang puwang sa itaas) sa unahan. Ano ang ibig sabihin nito?","o":["Kikitid ang kalsada","Malambot ang gilid ng kalsada","May matarik na burol sa unahan","May mababang tulay o overpass sa unahan"],"h1":"Ang clearance ay ang puwang sa itaas ng sasakyan mo.","h2":"Ang “LOW CLEARANCE” na karatula ay nangangahulugang mababa ang tulay o overpass sa unahan, kaya maaaring hindi kumasya sa ilalim nito ang matataas na sasakyan.","p":"Tama. Ang “LOW CLEARANCE” ay nangangahulugang may mababang tulay o overpass sa unahan."},"ar":{"q":"لافتة تحذّر من «LOW CLEARANCE» (ارتفاع منخفض) في الأمام. ماذا تعني؟","o":["الطريق يضيق","كتف الطريق طري","منحدر حاد في الأمام","جسر منخفض أو جسر علوي منخفض في الأمام"],"h1":"الارتفاع هنا هو المسافة فوق سيارتك.","h2":"لافتة الارتفاع المنخفض تعني أن جسرًا أو جسرًا علويًا في الأمام منخفض، لذلك قد لا تستطيع المركبات العالية أن تمر تحته.","p":"صحيح. الارتفاع المنخفض يعني جسرًا أو جسرًا علويًا منخفضًا في الأمام."},"ht":{"q":"Yon siy avèti “LOW CLEARANCE” (wotè ba) pi devan. Kisa li vle di?","o":["Wout la vin etwat","Arebò wout la mou","Gen yon mòn ki apik pi devan","Gen yon pon oswa yon pasaj anlè ki ba pi devan"],"h1":"Wotè a se espas ki anwo machin ou.","h2":"Yon siy “LOW CLEARANCE” vle di yon pon oswa yon pasaj anlè pi devan ba, kidonk machin ki wo yo ka pa pase anba l.","p":"Se sa. “LOW CLEARANCE” vle di gen yon pon oswa yon pasaj anlè ki ba pi devan."},"ref":{"doc":"FL","page":50}},{"id":"signs-031","scope":"US","cat":"signs","sign":{"shape":"school","text":"SCHOOL"},"c":0,"en":{"q":"You see a school crossing sign. What should you do?","o":["Slow down and watch for children","Honk to warn the children","Speed up to clear the area","Change lanes to go around"],"h1":"Children can be hard to see and may move fast.","h2":"A school crossing sign means children may be crossing, so you should slow down and be ready to stop.","p":"Right. At a school crossing, slow down and watch for children."},"es":{"q":"Usted ve una señal de cruce escolar. ¿Qué debe hacer?","o":["Bajar la velocidad y estar atento a los niños","Tocar la bocina para avisar a los niños","Acelerar para pasar la zona","Cambiar de carril para rodear"],"h1":"Los niños pueden ser difíciles de ver y moverse rápido.","h2":"Una señal de cruce escolar quiere decir que puede haber niños cruzando, así que usted debe bajar la velocidad y estar listo para parar.","p":"Correcto. En un cruce escolar, baje la velocidad y esté atento a los niños."},"zh":{"q":"你看到一个学校人行横道标志。你应该怎么做？","o":["减速，注意儿童","按喇叭提醒孩子们","加速快快开过","换车道绕过去"],"h1":"儿童不容易看到，而且可能动得很快。","h2":"学校人行横道标志表示可能有儿童过马路，所以你要减速，准备停车。","p":"对。在学校人行横道，要减速并注意儿童。"},"vi":{"q":"Bạn thấy biển báo chỗ học sinh qua đường. Bạn nên làm gì?","o":["Chạy chậm lại và chú ý trẻ em","Bấm còi để báo cho trẻ em","Tăng tốc để qua khu vực này","Đổi làn để chạy vòng qua"],"h1":"Trẻ em có thể khó thấy và có thể chạy rất nhanh.","h2":"Biển chỗ học sinh qua đường nghĩa là trẻ em có thể đang băng qua, nên bạn cần chạy chậm lại và sẵn sàng dừng.","p":"Đúng rồi. Ở chỗ học sinh qua đường, hãy chạy chậm và chú ý trẻ em."},"tl":{"q":"May nakita kang karatula ng tawiran ng mga estudyante. Ano ang dapat mong gawin?","o":["Bumagal at mag-ingat sa mga bata","Bumusina para bigyang-babala ang mga bata","Bumilis para malampasan ang lugar","Lumipat ng linya para lumihis"],"h1":"Mahirap makita ang mga bata at maaari silang gumalaw nang mabilis.","h2":"Ang karatula ng tawiran ng mga estudyante ay nangangahulugang maaaring may mga batang tumatawid, kaya dapat kang bumagal at maging handang huminto.","p":"Tama. Sa tawiran ng mga estudyante, bumagal at mag-ingat sa mga bata."},"ar":{"q":"ترى لافتة معبر مدرسة. ماذا يجب أن تفعل؟","o":["خفف السرعة وانتبه للأطفال","استخدم البوق لتحذير الأطفال","زد السرعة لتخرج من المنطقة","غيّر المسار لتمر من حولهم"],"h1":"الأطفال قد يكون من الصعب رؤيتهم، وقد يتحركون بسرعة.","h2":"لافتة معبر المدرسة تعني أن أطفالًا قد يعبرون، لذلك يجب أن تخفف السرعة وتكون مستعدًا للتوقف.","p":"صحيح. عند معبر المدرسة، خفف السرعة وانتبه للأطفال."},"ht":{"q":"Ou wè yon siy kote timoun lekòl travèse. Kisa ou dwe fè?","o":["Ralanti epi veye timoun yo","Klaksonen pou avèti timoun yo","Akselere pou kite zòn nan","Chanje koulwa pou pase bò kote yo"],"h1":"Timoun ka difisil pou wè epi yo ka deplase vit.","h2":"Yon siy kote timoun lekòl travèse vle di timoun ka ap travèse, kidonk ou dwe ralanti epi pare pou kanpe.","p":"Se sa. Kote timoun lekòl travèse, ralanti epi veye timoun yo."},"ref":{"doc":"FL","page":57}},{"id":"signs-032","scope":"US","cat":"signs","sign":{"shape":"rect-white","text":"SPEED LIMIT WHEN FLASHING"},"c":1,"en":{"q":"A school zone speed sign has yellow lights that are flashing. What does that mean?","o":["The lower speed is only a suggestion","The lower school speed limit is in effect now","School is closed today","Only school buses must slow down"],"h1":"The lights tell you when the sign applies.","h2":"When the lights on a school zone sign are flashing, the lower school speed limit is the law right now, so you must slow down to it.","p":"Right. Flashing lights mean the school speed limit applies now."},"es":{"q":"Una señal de velocidad en zona escolar tiene luces amarillas intermitentes. ¿Qué significa?","o":["La velocidad baja es solo una sugerencia","El límite escolar más bajo está vigente ahora","Hoy no hay clases","Solo los autobuses escolares deben ir más despacio"],"h1":"Las luces le dicen cuándo aplica la señal.","h2":"Cuando las luces de una señal de zona escolar están intermitentes, el límite escolar más bajo es la ley en ese momento, así que usted debe bajar a esa velocidad.","p":"Correcto. Las luces intermitentes significan que el límite escolar aplica ahora."},"zh":{"q":"学校区限速标志上的黄灯在闪。这是什么意思？","o":["较低的速度只是建议","较低的学校区限速现在生效","学校今天放假","只有校车要减速"],"h1":"灯告诉你这个标志什么时候有效。","h2":"学校区标志上的灯在闪时，较低的学校区限速现在就是法律，所以你必须减速到这个速度。","p":"对。灯在闪表示学校区限速现在生效。"},"vi":{"q":"Biển tốc độ khu vực trường học có đèn vàng đang nhấp nháy. Điều đó có nghĩa là gì?","o":["Tốc độ thấp hơn chỉ là lời khuyên","Giới hạn tốc độ thấp hơn của trường học đang có hiệu lực ngay bây giờ","Hôm nay trường nghỉ học","Chỉ xe buýt trường học phải chạy chậm"],"h1":"Đèn cho bạn biết khi nào biển có hiệu lực.","h2":"Khi đèn trên biển khu vực trường học nhấp nháy, giới hạn tốc độ thấp hơn của trường học là luật ngay lúc đó, nên bạn phải chạy chậm lại theo tốc độ đó.","p":"Đúng rồi. Đèn nhấp nháy nghĩa là giới hạn tốc độ trường học có hiệu lực ngay bây giờ."},"tl":{"q":"Ang karatula ng bilis sa school zone ay may dilaw na ilaw na kumikislap. Ano ang ibig sabihin nito?","o":["Mungkahi lang ang mas mababang bilis","Ipinapatupad na ngayon ang mas mababang speed limit sa paaralan","Sarado ang paaralan ngayong araw","Mga school bus lang ang dapat bumagal"],"h1":"Sinasabi ng mga ilaw kung kailan ipinapatupad ang karatula.","h2":"Kapag kumikislap ang mga ilaw sa karatula ng school zone, ang mas mababang speed limit sa paaralan ay batas na sa oras na iyon, kaya dapat kang bumagal sa bilis na iyon.","p":"Tama. Ang kumikislap na ilaw ay nangangahulugang ipinapatupad na ngayon ang speed limit sa paaralan."},"ar":{"q":"لافتة سرعة في منطقة مدرسة عليها أضواء صفراء تومض. ماذا يعني ذلك؟","o":["السرعة المنخفضة مجرد اقتراح","حد السرعة المنخفض للمدرسة مطبّق الآن","المدرسة مغلقة اليوم","حافلات المدارس فقط يجب أن تخفف السرعة"],"h1":"الأضواء تخبرك متى تكون اللافتة مطبّقة.","h2":"عندما تومض الأضواء على لافتة منطقة المدرسة، يكون حد السرعة المنخفض للمدرسة هو القانون الآن، لذلك يجب أن تخفف سرعتك إليه.","p":"صحيح. الأضواء الوامضة تعني أن حد سرعة المدرسة مطبّق الآن."},"ht":{"q":"Yon siy vitès zòn lekòl gen limyè jòn k ap kliyote. Kisa sa vle di?","o":["Vitès ki pi ba a se yon konsèy sèlman","Limit vitès lekòl ki pi ba a an aplikasyon kounye a","Lekòl la fèmen jodi a","Se sèlman bis lekòl ki dwe ralanti"],"h1":"Limyè yo di ou ki lè siy la an aplikasyon.","h2":"Lè limyè ki sou siy zòn lekòl la ap kliyote, limit vitès lekòl ki pi ba a se lalwa kounye a, kidonk ou dwe ralanti rive nan vitès sa a.","p":"Se sa. Limyè k ap kliyote vle di limit vitès lekòl la an aplikasyon kounye a."},"ref":{"doc":"FL","page":57}},{"id":"signs-033","scope":"US","cat":"signs","sign":{"shape":"crossbuck","text":"RAILROAD CROSSING"},"c":2,"en":{"q":"At a railroad crossing, the red lights are flashing. What must you do?","o":["Slow down and cross with care","Go if you do not see a train","Stop and wait until the lights stop","Drive around the gate"],"h1":"Flashing red lights at the tracks mean a train is coming.","h2":"Flashing red lights at a railroad crossing mean a train is near, so you must stop and wait until the lights stop flashing.","p":"Right. Flashing red lights at the tracks mean stop and wait."},"es":{"q":"En un cruce de tren, las luces rojas están intermitentes. ¿Qué debe hacer?","o":["Bajar la velocidad y cruzar con cuidado","Seguir si no ve un tren","Pararse y esperar hasta que las luces se apaguen","Rodear la barrera"],"h1":"Las luces rojas intermitentes en la vía del tren significan que viene un tren.","h2":"Las luces rojas intermitentes en un cruce de tren quieren decir que un tren está cerca, así que usted debe pararse y esperar hasta que las luces dejen de parpadear.","p":"Correcto. Luces rojas intermitentes en la vía significan parar y esperar."},"zh":{"q":"在铁路道口，红灯在闪。你必须怎么做？","o":["减速，小心通过","没看到火车就走","停车，等灯不闪了再走","绕过栏杆开过去"],"h1":"铁轨旁的红灯在闪，表示火车要来了。","h2":"铁路道口的红灯在闪，表示火车就在附近，所以你必须停车，等灯不闪了再走。","p":"对。铁轨旁红灯闪表示停车等待。"},"vi":{"q":"Tại chỗ băng qua đường sắt, đèn đỏ đang nhấp nháy. Bạn phải làm gì?","o":["Chạy chậm lại và băng qua cẩn thận","Đi nếu bạn không thấy tàu","Dừng lại và chờ tới khi đèn hết nhấp nháy","Chạy vòng qua thanh chắn"],"h1":"Đèn đỏ nhấp nháy ở đường ray nghĩa là có tàu đang tới.","h2":"Đèn đỏ nhấp nháy ở chỗ băng qua đường sắt nghĩa là tàu đang ở gần, nên bạn phải dừng lại và chờ tới khi đèn hết nhấp nháy.","p":"Đúng rồi. Đèn đỏ nhấp nháy ở đường ray nghĩa là dừng lại và chờ."},"tl":{"q":"Sa tawiran ng tren, kumikislap ang mga pulang ilaw. Ano ang dapat mong gawin?","o":["Bumagal at tumawid nang maingat","Tumawid kung wala kang nakikitang tren","Huminto at maghintay hanggang tumigil ang mga ilaw","Lumihis paikot sa harang"],"h1":"Ang kumikislap na pulang ilaw sa riles ay nangangahulugang may paparating na tren.","h2":"Ang kumikislap na pulang ilaw sa tawiran ng tren ay nangangahulugang malapit na ang tren, kaya dapat kang huminto at maghintay hanggang tumigil sa pagkislap ang mga ilaw.","p":"Tama. Ang kumikislap na pulang ilaw sa riles ay nangangahulugang huminto at maghintay."},"ar":{"q":"عند تقاطع سكة حديد، الأضواء الحمراء تومض. ماذا يجب أن تفعل؟","o":["خفف السرعة واعبر بحذر","انطلق إذا لم ترَ قطارًا","توقف وانتظر حتى تتوقف الأضواء","قُد حول الحاجز"],"h1":"الأضواء الحمراء الوامضة عند السكة تعني أن قطارًا قادم.","h2":"الأضواء الحمراء الوامضة عند تقاطع سكة الحديد تعني أن قطارًا قريب، لذلك يجب أن تتوقف وتنتظر حتى تتوقف الأضواء عن الوميض.","p":"صحيح. الأضواء الحمراء الوامضة عند السكة تعني: توقف وانتظر."},"ht":{"q":"Kote tren travèse a, limyè wouj yo ap kliyote. Kisa ou dwe fè?","o":["Ralanti epi travèse avèk prekosyon","Pase si ou pa wè tren","Kanpe epi tann jiskaske limyè yo sispann","Pase bò kote baryè a"],"h1":"Limyè wouj k ap kliyote bò ray yo vle di gen yon tren k ap vini.","h2":"Limyè wouj k ap kliyote kote tren travèse vle di gen yon tren toupre, kidonk ou dwe kanpe epi tann jiskaske limyè yo sispann kliyote.","p":"Se sa. Limyè wouj k ap kliyote bò ray yo vle di kanpe epi tann."},"ref":{"doc":"FL","page":56}},{"id":"signs-034","scope":"US","cat":"signs","sign":null,"c":3,"en":{"q":"The railroad gates are down, but you do not see a train. What should you do?","o":["Drive around the gates if it looks clear","Cross slowly with hazard lights on","Use the other lane to get past","Stay stopped until the gates go up"],"h1":"A train can be closer and faster than it looks.","h2":"When the gates are down, a train is coming even if you cannot see it, so you must stay stopped until the gates go all the way up.","p":"Right. Never go around the gates. Wait until they go up."},"es":{"q":"Las barreras del tren están abajo, pero usted no ve ningún tren. ¿Qué debe hacer?","o":["Rodear las barreras si parece libre","Cruzar despacio con las luces de emergencia","Usar el otro carril para pasar","Quedarse parado hasta que suban las barreras"],"h1":"Un tren puede estar más cerca y venir más rápido de lo que parece.","h2":"Cuando las barreras están abajo, viene un tren aunque usted no lo vea, así que debe quedarse parado hasta que las barreras suban por completo.","p":"Correcto. Nunca rodee las barreras. Espere a que suban."},"zh":{"q":"铁路道口的栏杆放下了，但你没看到火车。你应该怎么做？","o":["看起来没车就绕过栏杆","打开危险警示灯慢慢通过","用另一条车道开过去","一直停着，等栏杆升起"],"h1":"火车可能比看起来更近、更快。","h2":"栏杆放下时，就算你看不到火车，火车也正在开来，所以你必须一直停着，等栏杆完全升起。","p":"对。绝不要绕过栏杆。等栏杆升起。"},"vi":{"q":"Thanh chắn đường sắt đã hạ xuống, nhưng bạn không thấy tàu. Bạn nên làm gì?","o":["Chạy vòng qua thanh chắn nếu thấy đường trống","Băng qua chậm và bật đèn khẩn cấp","Dùng làn bên kia để đi qua","Đứng yên tới khi thanh chắn nâng lên"],"h1":"Tàu có thể ở gần hơn và chạy nhanh hơn bạn tưởng.","h2":"Khi thanh chắn đã hạ xuống, nghĩa là có tàu đang tới dù bạn không thấy, nên bạn phải đứng yên tới khi thanh chắn nâng lên hết.","p":"Đúng rồi. Không bao giờ chạy vòng qua thanh chắn. Hãy chờ tới khi nó nâng lên."},"tl":{"q":"Nakababa ang mga harang sa riles, pero wala kang nakikitang tren. Ano ang dapat mong gawin?","o":["Lumihis paikot sa mga harang kung mukhang walang tren","Tumawid nang dahan-dahan habang nakabukas ang hazard lights","Gamitin ang kabilang linya para makalampas","Manatiling nakahinto hanggang tumaas ang mga harang"],"h1":"Maaaring mas malapit at mas mabilis ang tren kaysa sa inaakala mo.","h2":"Kapag nakababa ang mga harang, may paparating na tren kahit hindi mo ito nakikita, kaya dapat kang manatiling nakahinto hanggang tuluyang tumaas ang mga harang.","p":"Tama. Huwag kailanman lumihis paikot sa mga harang. Maghintay hanggang tumaas ang mga ito."},"ar":{"q":"حواجز سكة الحديد نازلة، لكنك لا ترى قطارًا. ماذا يجب أن تفعل؟","o":["قُد حول الحواجز إذا بدا الطريق خاليًا","اعبر ببطء مع تشغيل أضواء التحذير","استخدم المسار الآخر لتمر","ابقَ متوقفًا حتى ترتفع الحواجز"],"h1":"القطار قد يكون أقرب وأسرع مما يبدو.","h2":"عندما تكون الحواجز نازلة فهناك قطار قادم حتى لو لم تره، لذلك يجب أن تبقى متوقفًا حتى ترتفع الحواجز بالكامل.","p":"صحيح. لا تمر أبدًا حول الحواجز. انتظر حتى ترتفع."},"ht":{"q":"Baryè tren yo desann, men ou pa wè okenn tren. Kisa ou dwe fè?","o":["Pase bò kote baryè yo si sanble pa gen anyen","Travèse dousman ak limyè ijans ou limen","Sèvi ak lòt koulwa a pou pase","Rete kanpe jiskaske baryè yo monte"],"h1":"Yon tren ka pi pre epi pi rapid pase jan li sanble.","h2":"Lè baryè yo desann, gen yon tren k ap vini menm si ou pa ka wè l, kidonk ou dwe rete kanpe jiskaske baryè yo monte nèt.","p":"Se sa. Pa janm pase bò kote baryè yo. Tann jiskaske yo monte."},"ref":{"doc":"FL","page":56}},{"id":"signs-035","scope":"US","cat":"signs","sign":{"shape":"crossbuck","text":"2 TRACKS"},"c":0,"en":{"q":"A small sign under the crossbuck says 2 TRACKS. What does it warn you about?","o":["After one train passes, another may come","Trains pass only two times a day","Two lanes of cars cross the tracks","You must wait two minutes to cross"],"h1":"Think about what could hide behind the first train.","h2":"The tracks sign tells you there is more than one track, so after one train passes you must look again, because a second train may be coming.","p":"Right. More than one track means another train may come."},"es":{"q":"Una señal pequeña debajo de la cruz de ferrocarril dice 2 TRACKS (2 vías). ¿De qué le avisa?","o":["Después de que pase un tren, puede venir otro","Los trenes pasan solo dos veces al día","Dos carriles de carros cruzan la vía","Debe esperar dos minutos para cruzar"],"h1":"Piense en lo que podría estar escondido detrás del primer tren.","h2":"La señal de vías le dice que hay más de una vía, así que después de que pase un tren usted debe volver a mirar, porque puede venir un segundo tren.","p":"Correcto. Más de una vía significa que puede venir otro tren."},"zh":{"q":"铁路交叉标志下面有一个小牌子写着 “2 TRACKS”（两条铁轨）。它提醒你什么？","o":["一列火车过去后，可能还有另一列","火车一天只过两次","有两条车道的车穿过铁轨","你必须等两分钟才能过"],"h1":"想一想：第一列火车后面可能藏着什么。","h2":"这个牌子告诉你这里不止一条铁轨，所以一列火车过去后，你必须再看一看，因为可能还有第二列火车开来。","p":"对。不止一条铁轨，表示可能还有另一列火车。"},"vi":{"q":"Một biển nhỏ dưới biển chữ X ghi “2 TRACKS” (2 đường ray). Biển này cảnh báo bạn về điều gì?","o":["Sau khi một tàu chạy qua, có thể có tàu khác tới","Tàu chỉ chạy qua hai lần mỗi ngày","Có hai làn xe hơi băng qua đường ray","Bạn phải chờ hai phút mới được băng qua"],"h1":"Hãy nghĩ xem cái gì có thể bị che khuất sau chiếc tàu đầu tiên.","h2":"Biển này cho biết có nhiều hơn một đường ray, nên sau khi một tàu chạy qua bạn phải nhìn lại, vì có thể có tàu thứ hai đang tới.","p":"Đúng rồi. Nhiều hơn một đường ray nghĩa là có thể có tàu khác tới."},"tl":{"q":"May maliit na karatula sa ilalim ng crossbuck na nakasulat ang “2 TRACKS” (2 riles). Tungkol saan ang babala nito?","o":["Pagkalampas ng isang tren, maaaring may dumating pang isa","Dalawang beses lang dumadaan ang tren sa isang araw","Dalawang linya ng sasakyan ang tumatawid sa riles","Dapat kang maghintay ng dalawang minuto bago tumawid"],"h1":"Isipin kung ano ang puwedeng nakatago sa likod ng unang tren.","h2":"Sinasabi ng karatulang ito na may higit sa isang riles, kaya pagkalampas ng isang tren ay dapat kang tumingin ulit, dahil maaaring may paparating na pangalawang tren.","p":"Tama. Kapag higit sa isa ang riles, maaaring may dumating pang ibang tren."},"ar":{"q":"لافتة صغيرة تحت علامة X مكتوب عليها «2 TRACKS» (سكتان). ممّ تحذّرك؟","o":["بعد أن يمر قطار، قد يأتي قطار آخر","القطارات تمر مرتين فقط في اليوم","مساران للسيارات يعبران السكة","يجب أن تنتظر دقيقتين قبل أن تعبر"],"h1":"فكّر في ما قد يكون مختبئًا خلف القطار الأول.","h2":"لافتة عدد السكك تخبرك بأن هناك أكثر من سكة واحدة، لذلك بعد أن يمر قطار يجب أن تنظر مرة أخرى، لأن قطارًا ثانيًا قد يكون قادمًا.","p":"صحيح. أكثر من سكة واحدة يعني أن قطارًا آخر قد يأتي."},"ht":{"q":"Yon ti siy anba kwa tren an di “2 TRACKS” (2 ray). Pou kisa li avèti ou?","o":["Apre yon tren fin pase, yon lòt ka vini","Tren pase sèlman de fwa pa jou","De koulwa machin travèse ray yo","Ou dwe tann de minit pou travèse"],"h1":"Panse ak sa ki ka kache dèyè premye tren an.","h2":"Siy sa a di ou gen plis pase yon ray, kidonk apre yon tren fin pase ou dwe gade ankò, paske yon dezyèm tren ka ap vini.","p":"Se sa. Plis pase yon ray vle di yon lòt tren ka vini."},"ref":{"doc":"FL","page":56}},{"id":"signs-036","scope":"FL","cat":"signs","sign":null,"c":1,"en":{"q":"In Florida, when you must stop for a train, where should you stop?","o":["Right on top of the first rail","Between 15 and 50 feet from the nearest rail","At least 100 feet from the tracks","Anywhere you like before the crossing"],"h1":"You need space between you and the train, but not too much.","h2":"In Florida, you must stop no closer than 15 feet and no farther than 50 feet from the nearest rail, so the train has room and you can still see it.","p":"Right. Stop between 15 and 50 feet from the nearest rail."},"es":{"q":"En Florida, cuando debe pararse por un tren, ¿dónde debe pararse?","o":["Justo encima del primer riel","Entre 15 y 50 pies del riel más cercano","Por lo menos a 100 pies de la vía","Donde quiera antes del cruce"],"h1":"Necesita espacio entre usted y el tren, pero no demasiado.","h2":"En Florida, usted debe pararse a no menos de 15 pies y no más de 50 pies del riel más cercano, para que el tren tenga espacio y usted todavía pueda verlo.","p":"Correcto. Párese entre 15 y 50 pies del riel más cercano."},"zh":{"q":"在 Florida，你必须为火车停车时，应该停在哪里？","o":["就停在第一条铁轨上","离最近的铁轨 15 到 50 feet（英尺）之间","离铁轨至少 100 feet（英尺）","过道口前随便哪里都行"],"h1":"你和火车之间要有空间，但不能太远。","h2":"在 Florida，你停车的位置离最近的铁轨不能少于 15 feet（英尺），也不能超过 50 feet（英尺），这样火车有空间通过，你也还能看见火车。","p":"对。停在离最近的铁轨 15 到 50 feet（英尺）之间。"},"vi":{"q":"Ở Florida, khi bạn phải dừng chờ tàu, bạn nên dừng ở đâu?","o":["Ngay trên thanh ray đầu tiên","Cách thanh ray gần nhất từ 15 tới 50 feet","Cách đường ray ít nhất 100 feet","Bất cứ chỗ nào bạn muốn trước chỗ băng qua"],"h1":"Bạn cần có khoảng cách với tàu, nhưng không quá xa.","h2":"Ở Florida, bạn phải dừng cách thanh ray gần nhất không dưới 15 feet và không quá 50 feet, để tàu có chỗ đi qua và bạn vẫn nhìn thấy tàu.","p":"Đúng rồi. Hãy dừng cách thanh ray gần nhất từ 15 tới 50 feet."},"tl":{"q":"Sa Florida, kapag kailangan mong huminto para sa tren, saan ka dapat huminto?","o":["Mismo sa ibabaw ng unang riles","Sa pagitan ng 15 at 50 feet mula sa pinakamalapit na riles","Hindi bababa sa 100 feet mula sa riles","Kahit saan mo gusto bago ang tawiran"],"h1":"Kailangan mo ng puwang sa pagitan mo at ng tren, pero hindi sobrang layo.","h2":"Sa Florida, dapat kang huminto nang hindi lalapit sa 15 feet at hindi lalayo sa 50 feet mula sa pinakamalapit na riles, para may puwang ang tren at nakikita mo pa rin ito.","p":"Tama. Huminto sa pagitan ng 15 at 50 feet mula sa pinakamalapit na riles."},"ar":{"q":"في Florida، عندما يجب أن تتوقف من أجل قطار، أين يجب أن تتوقف؟","o":["فوق القضيب الأول مباشرة","على مسافة بين 15 و50 قدمًا (feet) من أقرب قضيب","على بعد 100 قدم (feet) على الأقل من السكة","في أي مكان تريده قبل التقاطع"],"h1":"تحتاج إلى مسافة بينك وبين القطار، لكن ليست كبيرة جدًا.","h2":"في Florida، يجب أن تتوقف على مسافة لا تقل عن 15 قدمًا (feet) ولا تزيد عن 50 قدمًا من أقرب قضيب، لكي يكون للقطار مكان وتبقى قادرًا على رؤيته.","p":"صحيح. توقف على مسافة بين 15 و50 قدمًا (feet) من أقرب قضيب."},"ht":{"q":"Nan Florida, lè ou dwe kanpe pou yon tren, ki kote ou dwe kanpe?","o":["Dirèkteman sou premye ray la","Ant 15 ak 50 pye de ray ki pi pre a","Omwen 100 pye de ray yo","Nenpòt kote ou vle anvan kote tren travèse a"],"h1":"Ou bezwen espas ant ou menm ak tren an, men pa twòp.","h2":"Nan Florida, ou dwe kanpe pa pi pre pase 15 pye epi pa pi lwen pase 50 pye de ray ki pi pre a, pou tren an gen plas epi pou ou ka toujou wè l.","p":"Se sa. Kanpe ant 15 ak 50 pye de ray ki pi pre a."},"ref":{"doc":"FL","page":56}},{"id":"signs-037","scope":"US","cat":"signs","sign":{"shape":"diamond-orange","text":"ROAD WORK AHEAD"},"c":2,"en":{"q":"An orange sign says ROAD WORK AHEAD. What should you do?","o":["Find another road, this one is closed","Keep your speed, workers are done","Slow down and be ready for workers and changes","Speed up to get through the work fast"],"h1":"Think about people working near moving cars.","h2":"A road work sign means workers, equipment, or lane changes may be ahead, so you should slow down and pay close attention.","p":"Right. In road work, slow down and stay alert."},"es":{"q":"Una señal anaranjada dice ROAD WORK AHEAD (obras más adelante). ¿Qué debe hacer?","o":["Buscar otra vía, esta está cerrada","Mantener su velocidad, los trabajadores ya terminaron","Bajar la velocidad y estar listo para trabajadores y cambios","Acelerar para pasar las obras rápido"],"h1":"Piense en personas trabajando cerca de carros en movimiento.","h2":"Una señal de obras quiere decir que puede haber trabajadores, máquinas o cambios de carril más adelante, así que usted debe bajar la velocidad y poner mucha atención.","p":"Correcto. En zona de obras, baje la velocidad y esté alerta."},"zh":{"q":"一个橙色标志写着 “ROAD WORK AHEAD”（前方道路施工）。你应该怎么做？","o":["另找一条路，这条路封了","保持车速，工人已经完工了","减速，准备好面对工人和道路变化","加速，快快开过施工区"],"h1":"想一想：有人在行驶的车旁边工作。","h2":"道路施工标志表示前方可能有工人、机械或车道变化，所以你要减速，非常注意。","p":"对。在道路施工区，要减速并保持警觉。"},"vi":{"q":"Một biển màu cam ghi “ROAD WORK AHEAD” (Phía trước đang sửa đường). Bạn nên làm gì?","o":["Tìm đường khác, đường này đã đóng","Giữ nguyên tốc độ, công nhân đã làm xong","Chạy chậm lại và sẵn sàng gặp công nhân và thay đổi trên đường","Tăng tốc để qua chỗ sửa đường cho nhanh"],"h1":"Hãy nghĩ đến những người đang làm việc gần xe đang chạy.","h2":"Biển sửa đường nghĩa là phía trước có thể có công nhân, máy móc, hoặc làn đường thay đổi, nên bạn cần chạy chậm lại và chú ý kỹ.","p":"Đúng rồi. Ở chỗ sửa đường, hãy chạy chậm và luôn tỉnh táo."},"tl":{"q":"Nakasulat sa orange na karatula ang “ROAD WORK AHEAD” (May ginagawang kalsada sa unahan). Ano ang dapat mong gawin?","o":["Maghanap ng ibang daan, sarado ang daang ito","Panatilihin ang bilis mo, tapos na ang mga trabahador","Bumagal at maging handa sa mga trabahador at mga pagbabago","Bumilis para mabilis na malampasan ang ginagawa"],"h1":"Isipin ang mga taong nagtatrabaho malapit sa mga umaandar na sasakyan.","h2":"Ang karatula ng ginagawang kalsada ay nangangahulugang maaaring may mga trabahador, kagamitan, o pagbabago ng linya sa unahan, kaya dapat kang bumagal at magbigay ng buong atensyon.","p":"Tama. Kapag may ginagawang kalsada, bumagal at manatiling alerto."},"ar":{"q":"لافتة برتقالية مكتوب عليها «ROAD WORK AHEAD» (أعمال طرق في الأمام). ماذا يجب أن تفعل؟","o":["ابحث عن طريق آخر، فهذا الطريق مغلق","حافظ على سرعتك، فالعمال انتهوا","خفف السرعة واستعد للعمال وللتغييرات","زد السرعة لتعبر منطقة العمل بسرعة"],"h1":"فكّر في أشخاص يعملون قرب سيارات تتحرك.","h2":"لافتة أعمال الطرق تعني أن هناك عمالًا أو معدات أو تغييرات في المسارات في الأمام، لذلك يجب أن تخفف السرعة وتنتبه جيدًا.","p":"صحيح. في أعمال الطرق، خفف السرعة وابقَ منتبهًا."},"ht":{"q":"Yon siy zoranj di “ROAD WORK AHEAD” (travay sou wout pi devan). Kisa ou dwe fè?","o":["Chèche yon lòt wout, wout sa a fèmen","Kenbe vitès ou, travayè yo fini","Ralanti epi pare pou travayè ak chanjman","Akselere pou pase travay la vit"],"h1":"Panse ak moun k ap travay toupre machin k ap woule.","h2":"Yon siy travay sou wout vle di ka gen travayè, machin travay, oswa chanjman koulwa pi devan, kidonk ou dwe ralanti epi fè anpil atansyon.","p":"Se sa. Nan travay sou wout, ralanti epi rete vijilan."},"ref":{"doc":"FL","page":54}},{"id":"signs-038","scope":"US","cat":"signs","sign":null,"c":3,"en":{"q":"In a work zone, a flagger holds a STOP paddle toward you. What should you do?","o":["Slow down and drive around the flagger","Honk and keep going slowly","Stop only if workers are close to you","Stop and wait until the flagger lets you go"],"h1":"The flagger is directing traffic like a signal.","h2":"A flagger's STOP paddle has the same force as a stop sign, so you must stop and wait until the flagger signals you to go.","p":"Right. Obey the flagger and wait for the signal to go."},"es":{"q":"En una zona de obras, un banderero le muestra un letrero de STOP (pare). ¿Qué debe hacer?","o":["Bajar la velocidad y rodear al banderero","Tocar la bocina y seguir despacio","Pararse solo si hay trabajadores cerca","Pararse y esperar hasta que el banderero le deje pasar"],"h1":"El banderero dirige el tráfico como un semáforo.","h2":"El letrero de pare del banderero vale igual que una señal de pare, así que usted debe pararse y esperar hasta que el banderero le indique que siga.","p":"Correcto. Obedezca al banderero y espere su señal para seguir."},"zh":{"q":"在施工区，一名旗手把 “STOP”（停）牌子朝向你。你应该怎么做？","o":["减速，绕过旗手开过去","按喇叭，慢慢继续开","只有工人离你很近时才停","停车，等旗手让你走"],"h1":"旗手像信号灯一样指挥交通。","h2":"旗手的 “STOP” 牌子和停车标志有一样的效力，所以你必须停车，等旗手示意你走。","p":"对。服从旗手，等他示意你走。"},"vi":{"q":"Trong khu vực thi công, người cầm biển điều khiển giao thông giơ biển “STOP” về phía bạn. Bạn nên làm gì?","o":["Chạy chậm lại và chạy vòng qua người cầm biển","Bấm còi và tiếp tục chạy chậm","Chỉ dừng nếu công nhân ở gần bạn","Dừng lại và chờ tới khi người cầm biển cho bạn đi"],"h1":"Người cầm biển đang điều khiển giao thông giống như đèn tín hiệu.","h2":"Biển “STOP” của người cầm biển có hiệu lực giống như biển dừng, nên bạn phải dừng lại và chờ tới khi người đó ra hiệu cho bạn đi.","p":"Đúng rồi. Hãy làm theo người cầm biển và chờ hiệu lệnh cho đi."},"tl":{"q":"Sa work zone, may flagger na nakaharap sa iyo ang hawak na “STOP” na paddle. Ano ang dapat mong gawin?","o":["Bumagal at lumihis paikot sa flagger","Bumusina at magpatuloy nang dahan-dahan","Huminto lang kung malapit sa iyo ang mga trabahador","Huminto at maghintay hanggang payagan ka ng flagger na umandar"],"h1":"Ang flagger ay nagdidirekta ng trapiko na parang ilaw trapiko.","h2":"Ang “STOP” na paddle ng flagger ay may parehong bisa ng “STOP” sign, kaya dapat kang huminto at maghintay hanggang senyasan ka ng flagger na umandar.","p":"Tama. Sundin ang flagger at hintayin ang senyas na umandar."},"ar":{"q":"في منطقة عمل، عامل تنظيم السير يرفع نحوك لوحة «STOP» (قف). ماذا يجب أن تفعل؟","o":["خفف السرعة وقُد حول العامل","استخدم البوق واستمر ببطء","توقف فقط إذا كان العمال قريبين منك","توقف وانتظر حتى يسمح لك العامل بالمرور"],"h1":"عامل تنظيم السير يوجّه السيارات مثل الإشارة الضوئية.","h2":"لوحة «STOP» التي يحملها عامل تنظيم السير لها نفس قوة لافتة «STOP»، لذلك يجب أن تتوقف وتنتظر حتى يشير لك العامل بالمرور.","p":"صحيح. أطِع عامل تنظيم السير وانتظر إشارته لتمر."},"ht":{"q":"Nan yon zòn travay, yon travayè ki dirije trafik la kenbe yon pankat “STOP” bò kote ou. Kisa ou dwe fè?","o":["Ralanti epi pase bò kote travayè a","Klaksonen epi kontinye dousman","Kanpe sèlman si travayè yo toupre ou","Kanpe epi tann jiskaske travayè a kite ou pase"],"h1":"Travayè a ap dirije trafik la tankou yon limyè trafik.","h2":"Pankat “STOP” travayè a gen menm fòs ak yon siy “STOP”, kidonk ou dwe kanpe epi tann jiskaske travayè a fè ou siy pou pase.","p":"Se sa. Obeyi travayè a epi tann siyal pou pase a."},"ref":{"doc":"FL","page":54}},{"id":"signs-039","scope":"US","cat":"signs","sign":null,"c":0,"en":{"q":"An orange sign says DETOUR. What does it mean?","o":["Follow the signs on a different route","The road is closed forever","Only trucks must leave the road","Park and wait for the road to open"],"h1":"A detour is a way around something.","h2":"A detour sign means the normal road is closed for now, so you follow the detour signs on another route.","p":"Right. Detour means follow the signs on another route."},"es":{"q":"Una señal anaranjada dice DETOUR (desvío). ¿Qué significa?","o":["Seguir las señales por otra ruta","La vía está cerrada para siempre","Solo los camiones deben salir de la vía","Estacionarse y esperar a que abran la vía"],"h1":"Un desvío es un camino para rodear algo.","h2":"Una señal de desvío quiere decir que la vía normal está cerrada por ahora, así que usted sigue las señales de desvío por otra ruta.","p":"Correcto. Desvío significa seguir las señales por otra ruta."},"zh":{"q":"一个橙色标志写着 “DETOUR”（绕行）。它是什么意思？","o":["按标志走另一条路线","这条路永远封了","只有卡车要离开这条路","停车等道路开放"],"h1":"绕行就是绕过某个地方的路。","h2":"绕行标志表示平常的路暂时封闭，所以你要按绕行标志走另一条路线。","p":"对。绕行表示按标志走另一条路线。"},"vi":{"q":"Một biển màu cam ghi “DETOUR” (Đường vòng). Biển này có nghĩa là gì?","o":["Đi theo các biển chỉ dẫn sang một đường khác","Con đường bị đóng vĩnh viễn","Chỉ xe tải phải rời khỏi đường","Đỗ xe và chờ đường mở lại"],"h1":"Đường vòng là cách đi vòng qua một chỗ nào đó.","h2":"Biển đường vòng nghĩa là đường bình thường đang tạm đóng, nên bạn đi theo các biển “DETOUR” sang một đường khác.","p":"Đúng rồi. Đường vòng nghĩa là đi theo biển chỉ dẫn sang đường khác."},"tl":{"q":"Nakasulat sa orange na karatula ang “DETOUR” (Lihis na daan). Ano ang ibig sabihin nito?","o":["Sundan ang mga karatula sa ibang ruta","Sarado na ang kalsada habambuhay","Mga trak lang ang dapat umalis sa kalsada","Pumarada at hintaying magbukas ang kalsada"],"h1":"Ang detour ay isang paraan para makaiwas o makadaan paikot sa isang bagay.","h2":"Ang “DETOUR” na karatula ay nangangahulugang sarado muna ang karaniwang daan, kaya susundan mo ang mga karatula ng detour sa ibang ruta.","p":"Tama. Ang “DETOUR” ay nangangahulugang sundan ang mga karatula sa ibang ruta."},"ar":{"q":"لافتة برتقالية مكتوب عليها «DETOUR» (تحويلة). ماذا تعني؟","o":["اتبع اللافتات على طريق مختلف","الطريق مغلق إلى الأبد","الشاحنات فقط يجب أن تخرج من الطريق","أوقف السيارة وانتظر حتى يُفتح الطريق"],"h1":"التحويلة طريق يلتف حول شيء ما.","h2":"لافتة التحويلة تعني أن الطريق العادي مغلق الآن، لذلك تتبع لافتات التحويلة على طريق آخر.","p":"صحيح. التحويلة تعني: اتبع اللافتات على طريق آخر."},"ht":{"q":"Yon siy zoranj di “DETOUR” (devyasyon). Kisa li vle di?","o":["Swiv siy yo sou yon lòt wout","Wout la fèmen pou toutan","Se sèlman kamyon ki dwe kite wout la","Pake epi tann wout la louvri"],"h1":"Yon devyasyon se yon fason pou fè wonn yon bagay.","h2":"Yon siy “DETOUR” vle di wout nòmal la fèmen pou kounye a, kidonk ou swiv siy devyasyon yo sou yon lòt wout.","p":"Se sa. “DETOUR” vle di swiv siy yo sou yon lòt wout."}},{"id":"signs-040","scope":"FL","cat":"signs","sign":null,"c":1,"en":{"q":"In Florida, what happens to a speeding fine in a work zone when workers are there?","o":["It is cut in half","It is doubled","It stays the same","It becomes only a warning"],"h1":"Florida wants to protect the people working on the road.","h2":"In Florida, the fine for speeding in a work zone is doubled when workers are present, because workers near traffic are at great risk.","p":"Right. Speeding fines double in a work zone with workers present."},"es":{"q":"En Florida, ¿qué pasa con la multa por exceso de velocidad en una zona de obras cuando hay trabajadores?","o":["Se reduce a la mitad","Se duplica","Se queda igual","Se vuelve solo una advertencia"],"h1":"Florida quiere proteger a las personas que trabajan en la vía.","h2":"En Florida, la multa por exceso de velocidad en una zona de obras se duplica cuando hay trabajadores presentes, porque los trabajadores cerca del tráfico corren mucho peligro.","p":"Correcto. La multa por velocidad se duplica en zona de obras con trabajadores."},"zh":{"q":"在 Florida，有工人在场时，在施工区超速的罚款会怎样？","o":["减半","加倍","不变","只给警告"],"h1":"Florida 想保护在路上工作的人。","h2":"在 Florida，有工人在场时，在施工区超速的罚款会加倍，因为在车流旁边工作的工人非常危险。","p":"对。有工人在场时，施工区超速罚款加倍。"},"vi":{"q":"Ở Florida, tiền phạt chạy quá tốc độ trong khu vực thi công sẽ ra sao khi có công nhân ở đó?","o":["Giảm một nửa","Tăng gấp đôi","Giữ nguyên","Chỉ bị cảnh cáo"],"h1":"Florida muốn bảo vệ những người đang làm việc trên đường.","h2":"Ở Florida, tiền phạt chạy quá tốc độ trong khu vực thi công bị tăng gấp đôi khi có công nhân, vì công nhân làm việc gần xe chạy rất nguy hiểm.","p":"Đúng rồi. Tiền phạt quá tốc độ tăng gấp đôi trong khu vực thi công có công nhân."},"tl":{"q":"Sa Florida, ano ang nangyayari sa multa sa sobrang bilis sa work zone kapag may mga trabahador doon?","o":["Nababawasan ito ng kalahati","Nadodoble ito","Nananatili itong pareho","Nagiging babala lang ito"],"h1":"Gustong protektahan ng Florida ang mga taong nagtatrabaho sa kalsada.","h2":"Sa Florida, nadodoble ang multa sa sobrang bilis sa work zone kapag may mga trabahador, dahil malaki ang panganib sa mga trabahador na malapit sa trapiko.","p":"Tama. Nadodoble ang multa sa sobrang bilis sa work zone na may mga trabahador."},"ar":{"q":"في Florida، ماذا يحدث لغرامة السرعة في منطقة عمل عندما يكون العمال موجودين؟","o":["تُخفض إلى النصف","تُضاعف","تبقى كما هي","تصبح مجرد تحذير"],"h1":"Florida تريد أن تحمي الأشخاص الذين يعملون على الطريق.","h2":"في Florida، تُضاعف غرامة السرعة في منطقة العمل عندما يكون العمال موجودين، لأن العمال القريبين من السيارات في خطر كبير.","p":"صحيح. غرامات السرعة تُضاعف في منطقة العمل عندما يكون العمال موجودين."},"ht":{"q":"Nan Florida, kisa k ap pase ak amann pou vitès nan yon zòn travay lè gen travayè la?","o":["Li diminye mwatye","Li double","Li rete menm jan an","Li vin yon avètisman sèlman"],"h1":"Florida vle pwoteje moun k ap travay sou wout la.","h2":"Nan Florida, amann pou vitès nan yon zòn travay double lè gen travayè la, paske travayè ki toupre machin yo an gwo danje.","p":"Se sa. Amann pou vitès double nan yon zòn travay lè gen travayè la."},"ref":{"doc":"FL","page":29}},{"id":"signs-041","scope":"US","cat":"signs","sign":{"shape":"interstate","text":"95"},"c":2,"en":{"q":"What kind of road does a blue and red shield with a number mark?","o":["A state park road","A private toll road","An Interstate highway","A county road"],"h1":"This shield is used across the whole country.","h2":"The blue and red shield marks an Interstate highway, which is part of the national highway system.","p":"Right. The blue and red shield marks an Interstate."},"es":{"q":"¿Qué tipo de vía marca un escudo azul y rojo con un número?","o":["Una vía de parque estatal","Una vía privada de peaje","Una autopista interestatal","Una vía del condado"],"h1":"Este escudo se usa en todo el país.","h2":"El escudo azul y rojo marca una autopista interestatal, que es parte del sistema nacional de carreteras.","p":"Correcto. El escudo azul y rojo marca una interestatal."},"zh":{"q":"带数字的蓝红色盾形标志表示哪种道路？","o":["州立公园道路","私人收费公路","州际公路（Interstate）","县级公路"],"h1":"这种盾形标志在全国都用。","h2":"蓝红色盾形标志表示州际公路（Interstate），它是全国公路系统的一部分。","p":"对。蓝红色盾形标志表示州际公路。"},"vi":{"q":"Tấm khiên màu xanh dương và đỏ có ghi số đánh dấu loại đường nào?","o":["Đường trong công viên của tiểu bang","Đường thu phí tư nhân","Đường cao tốc liên bang (Interstate)","Đường của quận"],"h1":"Tấm khiên này được dùng trên khắp cả nước.","h2":"Tấm khiên xanh dương và đỏ đánh dấu đường cao tốc liên bang (Interstate), là một phần của hệ thống đường cao tốc quốc gia.","p":"Đúng rồi. Tấm khiên xanh dương và đỏ đánh dấu đường Interstate."},"tl":{"q":"Anong uri ng kalsada ang minamarkahan ng asul at pulang kalasag na may numero?","o":["Daan sa parke ng estado","Pribadong toll road","Interstate highway","Daan ng county"],"h1":"Ginagamit ang kalasag na ito sa buong bansa.","h2":"Ang asul at pulang kalasag ay nagmamarka ng Interstate highway, na bahagi ng pambansang sistema ng mga highway.","p":"Tama. Ang asul at pulang kalasag ay nagmamarka ng Interstate."},"ar":{"q":"أي نوع من الطرق يدل عليه درع أزرق وأحمر عليه رقم؟","o":["طريق حديقة تابعة للولاية","طريق خاص برسوم","طريق سريع بين الولايات (Interstate)","طريق تابع للمقاطعة"],"h1":"هذا الدرع يُستخدم في البلد كله.","h2":"الدرع الأزرق والأحمر يدل على طريق سريع بين الولايات (Interstate)، وهو جزء من شبكة الطرق السريعة الوطنية.","p":"صحيح. الدرع الأزرق والأحمر يدل على طريق Interstate."},"ht":{"q":"Ki kalite wout yon plak ble ak wouj ki gen yon nimewo make?","o":["Yon wout pak eta","Yon wout prive ki gen peyaj","Yon gran wout Interstate","Yon wout konte"],"h1":"Yo sèvi ak plak sa a nan tout peyi a.","h2":"Plak ble ak wouj la make yon gran wout Interstate, ki fè pati sistèm gran wout nasyonal la.","p":"Se sa. Plak ble ak wouj la make yon Interstate."}},{"id":"signs-042","scope":"US","cat":"signs","sign":{"shape":"interstate","text":"95"},"c":3,"en":{"q":"Interstates with odd numbers, like I-95, usually run which way?","o":["East and west","In a loop around a city","Only inside one state","North and south"],"h1":"Odd and even numbers are used for two different directions.","h2":"Interstates with odd numbers usually run north and south, like I-95 along the east coast.","p":"Right. Odd numbers usually run north and south."},"es":{"q":"Las interestatales con número impar, como la I-95, ¿hacia dónde van normalmente?","o":["De este a oeste","En círculo alrededor de una ciudad","Solo dentro de un estado","De norte a sur"],"h1":"Los números pares e impares se usan para dos direcciones diferentes.","h2":"Las interestatales con número impar normalmente van de norte a sur, como la I-95 por la costa este.","p":"Correcto. Los números impares normalmente van de norte a sur."},"zh":{"q":"编号是单数的州际公路，比如 I-95，通常是什么走向？","o":["东西走向","绕着城市一圈","只在一个州里面","南北走向"],"h1":"单数和双数用于两个不同的方向。","h2":"编号是单数的州际公路通常是南北走向，比如沿着东海岸的 I-95。","p":"对。单数编号通常是南北走向。"},"vi":{"q":"Đường Interstate có số lẻ, như I-95, thường chạy theo hướng nào?","o":["Đông và tây","Vòng quanh một thành phố","Chỉ trong một tiểu bang","Bắc và nam"],"h1":"Số lẻ và số chẵn được dùng cho hai hướng khác nhau.","h2":"Đường Interstate có số lẻ thường chạy theo hướng bắc và nam, như I-95 dọc bờ biển phía đông.","p":"Đúng rồi. Số lẻ thường chạy theo hướng bắc và nam."},"tl":{"q":"Ang mga Interstate na may odd na numero, tulad ng I-95, ay karaniwang papunta sa aling direksyon?","o":["Silangan at kanluran","Paikot sa isang lungsod","Sa loob lang ng isang estado","Hilaga at timog"],"h1":"Ginagamit ang odd at even na numero para sa dalawang magkaibang direksyon.","h2":"Ang mga Interstate na may odd na numero ay karaniwang papunta sa hilaga at timog, tulad ng I-95 sa kahabaan ng silangang baybayin.","p":"Tama. Ang odd na numero ay karaniwang papunta sa hilaga at timog."},"ar":{"q":"طرق Interstate ذات الأرقام الفردية، مثل I-95، في أي اتجاه تمتد عادةً؟","o":["من الشرق إلى الغرب","في دائرة حول مدينة","داخل ولاية واحدة فقط","من الشمال إلى الجنوب"],"h1":"الأرقام الفردية والزوجية تُستخدم لاتجاهين مختلفين.","h2":"طرق Interstate ذات الأرقام الفردية تمتد عادةً من الشمال إلى الجنوب، مثل I-95 على طول الساحل الشرقي.","p":"صحيح. الأرقام الفردية تمتد عادةً من الشمال إلى الجنوب."},"ht":{"q":"Interstate ki gen nimewo enpè, tankou I-95, nan ki direksyon yo konn ale?","o":["Lès ak lwès","An wonn alantou yon vil","Sèlman andedan yon sèl eta","Nò ak sid"],"h1":"Nimewo enpè ak nimewo pè sèvi pou de direksyon diferan.","h2":"Interstate ki gen nimewo enpè yo konn ale nò ak sid, tankou I-95 sou kòt lès la.","p":"Se sa. Nimewo enpè yo konn ale nò ak sid."},"ref":{"doc":"FL","page":46}},{"id":"signs-043","scope":"US","cat":"signs","sign":{"shape":"interstate","text":"10"},"c":0,"en":{"q":"I-10 has an even number. Which way does it usually run?","o":["East and west","North and south","Around a city","Along the coast only"],"h1":"Even and odd numbers go in different directions.","h2":"Interstates with even numbers usually run east and west, like I-10 across north Florida.","p":"Right. Even numbers usually run east and west."},"es":{"q":"La I-10 tiene un número par. ¿Hacia dónde va normalmente?","o":["De este a oeste","De norte a sur","Alrededor de una ciudad","Solo por la costa"],"h1":"Los números pares e impares van en direcciones distintas.","h2":"Las interestatales con número par normalmente van de este a oeste, como la I-10 por el norte de Florida.","p":"Correcto. Los números pares normalmente van de este a oeste."},"zh":{"q":"I-10 的编号是双数。它通常是什么走向？","o":["东西走向","南北走向","绕着城市","只沿着海岸"],"h1":"双数和单数代表不同的方向。","h2":"编号是双数的州际公路通常是东西走向，比如横穿 Florida 北部的 I-10。","p":"对。双数编号通常是东西走向。"},"vi":{"q":"I-10 có số chẵn. Đường này thường chạy theo hướng nào?","o":["Đông và tây","Bắc và nam","Vòng quanh một thành phố","Chỉ dọc theo bờ biển"],"h1":"Số chẵn và số lẻ chạy theo những hướng khác nhau.","h2":"Đường Interstate có số chẵn thường chạy theo hướng đông và tây, như I-10 băng ngang miền bắc Florida.","p":"Đúng rồi. Số chẵn thường chạy theo hướng đông và tây."},"tl":{"q":"Ang I-10 ay may even na numero. Saang direksyon ito karaniwang papunta?","o":["Silangan at kanluran","Hilaga at timog","Paikot sa isang lungsod","Sa kahabaan lang ng baybayin"],"h1":"Ang even at odd na numero ay papunta sa magkaibang direksyon.","h2":"Ang mga Interstate na may even na numero ay karaniwang papunta sa silangan at kanluran, tulad ng I-10 na tumatawid sa hilagang Florida.","p":"Tama. Ang even na numero ay karaniwang papunta sa silangan at kanluran."},"ar":{"q":"الطريق I-10 رقمه زوجي. في أي اتجاه يمتد عادةً؟","o":["من الشرق إلى الغرب","من الشمال إلى الجنوب","حول مدينة","على طول الساحل فقط"],"h1":"الأرقام الزوجية والفردية تسير في اتجاهات مختلفة.","h2":"طرق Interstate ذات الأرقام الزوجية تمتد عادةً من الشرق إلى الغرب، مثل I-10 عبر شمال Florida.","p":"صحيح. الأرقام الزوجية تمتد عادةً من الشرق إلى الغرب."},"ht":{"q":"I-10 gen yon nimewo pè. Nan ki direksyon li konn ale?","o":["Lès ak lwès","Nò ak sid","Alantou yon vil","Sèlman bò lanmè a"],"h1":"Nimewo pè ak nimewo enpè ale nan direksyon diferan.","h2":"Interstate ki gen nimewo pè yo konn ale lès ak lwès, tankou I-10 ki travèse nò Florida.","p":"Se sa. Nimewo pè yo konn ale lès ak lwès."},"ref":{"doc":"FL","page":46}},{"id":"signs-045","scope":"FL","cat":"signs","sign":{"shape":"rect-green","text":"EXIT"},"c":2,"en":{"q":"In Florida, how are exit numbers on Interstates chosen?","o":["In order, 1, 2, 3, from the state line","By the name of the nearest city","By the nearest mile marker","By the number of the crossing road"],"h1":"Think about the small green signs that count the miles.","h2":"In Florida, Interstate exit numbers match the nearest mile marker, so the exit number also tells you about how far you are along the road.","p":"Right. Florida exit numbers follow the mile markers."},"es":{"q":"En Florida, ¿cómo se escogen los números de salida en las interestatales?","o":["En orden, 1, 2, 3, desde la frontera del estado","Por el nombre de la ciudad más cercana","Por el marcador de milla más cercano","Por el número de la vía que cruza"],"h1":"Piense en las señales verdes pequeñas que cuentan las millas.","h2":"En Florida, los números de salida en las interestatales corresponden al marcador de milla más cercano, así que el número de salida también le dice más o menos qué tan lejos va en la vía.","p":"Correcto. En Florida, los números de salida siguen los marcadores de milla."},"zh":{"q":"在 Florida，州际公路的出口编号是怎么定的？","o":["从州界开始按 1、2、3 排列","按最近城市的名字","按最近的里程标","按交叉道路的编号"],"h1":"想一想计算英里数的绿色小标志。","h2":"在 Florida，州际公路的出口编号和最近的里程标一致，所以出口编号也告诉你大约在这条路上走了多远。","p":"对。Florida 的出口编号按里程标来定。"},"vi":{"q":"Ở Florida, số lối ra trên đường Interstate được đặt như thế nào?","o":["Theo thứ tự 1, 2, 3, tính từ ranh giới tiểu bang","Theo tên thành phố gần nhất","Theo cột mốc dặm gần nhất","Theo số của con đường cắt ngang"],"h1":"Hãy nghĩ đến những biển nhỏ màu xanh lá cây đếm số dặm.","h2":"Ở Florida, số lối ra trên đường Interstate trùng với cột mốc dặm gần nhất, nên số lối ra cũng cho bạn biết khoảng bao xa bạn đã đi trên con đường đó.","p":"Đúng rồi. Số lối ra ở Florida theo các cột mốc dặm."},"tl":{"q":"Sa Florida, paano pinipili ang mga numero ng exit sa mga Interstate?","o":["Sunod-sunod, 1, 2, 3, mula sa hangganan ng estado","Ayon sa pangalan ng pinakamalapit na lungsod","Ayon sa pinakamalapit na mile marker","Ayon sa numero ng kalsadang tumatawid"],"h1":"Isipin ang maliliit na berdeng karatula na nagbibilang ng milya.","h2":"Sa Florida, ang numero ng exit sa Interstate ay tugma sa pinakamalapit na mile marker, kaya sinasabi rin ng numero ng exit kung humigit-kumulang gaano na kalayo ang narating mo sa kalsada.","p":"Tama. Sinusunod ng mga numero ng exit sa Florida ang mga mile marker."},"ar":{"q":"في Florida، كيف تُختار أرقام المخارج على طرق Interstate؟","o":["بالترتيب، 1، 2، 3، من حدود الولاية","حسب اسم أقرب مدينة","حسب أقرب علامة ميل","حسب رقم الطريق الذي يتقاطع معه"],"h1":"فكّر في اللافتات الخضراء الصغيرة التي تعدّ الأميال.","h2":"في Florida، أرقام المخارج على طرق Interstate تطابق أقرب علامة ميل، لذلك رقم المخرج يخبرك أيضًا تقريبًا بالمسافة التي قطعتها على الطريق.","p":"صحيح. أرقام المخارج في Florida تتبع علامات الأميال."},"ht":{"q":"Nan Florida, ki jan yo chwazi nimewo sòti yo sou Interstate yo?","o":["Youn apre lòt, 1, 2, 3, depi fwontyè eta a","Dapre non vil ki pi pre a","Dapre ti siy mil ki pi pre a","Dapre nimewo wout ki travèse a"],"h1":"Panse ak ti siy vèt ki konte mil yo.","h2":"Nan Florida, nimewo sòti Interstate yo menm ak ti siy mil ki pi pre a, kidonk nimewo sòti a di ou apeprè ki distans ou fè sou wout la.","p":"Se sa. Nimewo sòti Florida yo swiv ti siy mil yo."},"ref":{"doc":"FL","page":46}},{"id":"signs-046","scope":"US","cat":"signs","sign":{"shape":"rect-green","text":"MILE 120"},"c":3,"en":{"q":"How do small green mile marker signs help you?","o":["They show the speed limit","They point to gas stations","They tell you where to pay tolls","They tell your location in an emergency"],"h1":"Think about what you would tell a 911 operator.","h2":"Mile markers show where you are on the highway, so you can tell emergency helpers your exact location.","p":"Right. Mile markers help you tell where you are."},"es":{"q":"¿Cómo le ayudan las señales verdes pequeñas de marcador de milla?","o":["Muestran el límite de velocidad","Indican dónde hay gasolineras","Le dicen dónde pagar el peaje","Le ayudan a decir dónde está en una emergencia"],"h1":"Piense en lo que le diría a la operadora del 911.","h2":"Los marcadores de milla muestran dónde está usted en la carretera, así que puede decirle a la ayuda de emergencia su ubicación exacta.","p":"Correcto. Los marcadores de milla le ayudan a decir dónde está."},"zh":{"q":"绿色的小里程标对你有什么帮助？","o":["它们显示限速","它们指向加油站","它们告诉你在哪里付过路费","在紧急情况下，它们告诉你在哪里"],"h1":"想一想你会告诉 911 接线员什么。","h2":"里程标显示你在公路上的位置，所以你能把准确位置告诉急救人员。","p":"对。里程标帮你说出你在哪里。"},"vi":{"q":"Những biển nhỏ màu xanh lá cây ghi cột mốc dặm giúp bạn thế nào?","o":["Cho biết giới hạn tốc độ","Chỉ tới trạm xăng","Cho biết chỗ trả phí đường","Cho biết vị trí của bạn khi có trường hợp khẩn cấp"],"h1":"Hãy nghĩ xem bạn sẽ nói gì với người trực tổng đài 911.","h2":"Cột mốc dặm cho biết bạn đang ở đâu trên đường cao tốc, nên bạn có thể nói cho người cứu hộ biết chính xác vị trí của bạn.","p":"Đúng rồi. Cột mốc dặm giúp bạn nói được mình đang ở đâu."},"tl":{"q":"Paano ka natutulungan ng maliliit na berdeng karatula ng mile marker?","o":["Ipinapakita nila ang speed limit","Itinuturo nila ang mga gasolinahan","Sinasabi nila kung saan magbabayad ng toll","Sinasabi nila ang lokasyon mo kapag may emergency"],"h1":"Isipin kung ano ang sasabihin mo sa operator ng 911.","h2":"Ipinapakita ng mga mile marker kung nasaan ka sa highway, kaya masasabi mo sa mga tagatulong sa emergency ang eksaktong lokasyon mo.","p":"Tama. Tinutulungan ka ng mga mile marker na sabihin kung nasaan ka."},"ar":{"q":"كيف تساعدك لافتات علامات الأميال الخضراء الصغيرة؟","o":["تُظهر حد السرعة","تدلّك على محطات الوقود","تخبرك أين تدفع رسوم الطريق","تخبرك بمكانك في حالة الطوارئ"],"h1":"فكّر في ما ستقوله لموظف الطوارئ على الرقم 911.","h2":"علامات الأميال تُظهر مكانك على الطريق السريع، لذلك تستطيع أن تخبر فرق الطوارئ بمكانك بالضبط.","p":"صحيح. علامات الأميال تساعدك على معرفة مكانك."},"ht":{"q":"Ki jan ti siy mil vèt yo ede ou?","o":["Yo montre limit vitès la","Yo montre kote estasyon gaz yo ye","Yo di ou ki kote pou peye peyaj","Yo di ki kote ou ye lè gen yon ijans"],"h1":"Panse ak sa ou ta di yon moun nan 911.","h2":"Ti siy mil yo montre ki kote ou ye sou gran wout la, kidonk ou ka di moun k ap vin ede ou nan yon ijans kote egzak ou ye.","p":"Se sa. Ti siy mil yo ede ou di ki kote ou ye."},"ref":{"doc":"FL","page":46}},{"id":"signs-047","scope":"US","cat":"signs","sign":{"shape":"rect-blue","text":"H"},"c":0,"en":{"q":"A blue sign shows a big white letter H. What does it mean?","o":["A hospital is nearby","A hotel is nearby","A helicopter pad is nearby","The highway ends here"],"h1":"Blue signs show services you may need.","h2":"A blue sign with a white H points to a hospital, so you can find medical help nearby.","p":"Right. The blue H sign means a hospital is near."},"es":{"q":"Una señal azul muestra una letra H grande y blanca. ¿Qué significa?","o":["Hay un hospital cerca","Hay un hotel cerca","Hay un helipuerto cerca","La autopista termina aquí"],"h1":"Las señales azules muestran servicios que podría necesitar.","h2":"Una señal azul con una H blanca indica un hospital, así que usted puede encontrar ayuda médica cerca.","p":"Correcto. La señal azul con H significa que hay un hospital cerca."},"zh":{"q":"一个蓝色标志上有一个很大的白色字母 H。它是什么意思？","o":["附近有医院","附近有酒店","附近有直升机停机坪","公路到这里结束"],"h1":"蓝色标志告诉你可能需要的服务。","h2":"有白色字母 H 的蓝色标志指向医院，所以你能在附近找到医疗帮助。","p":"对。蓝色 H 标志表示附近有医院。"},"vi":{"q":"Một biển màu xanh dương có chữ H lớn màu trắng. Biển này có nghĩa là gì?","o":["Gần đây có bệnh viện","Gần đây có khách sạn","Gần đây có bãi đáp trực thăng","Đường cao tốc kết thúc ở đây"],"h1":"Biển màu xanh dương cho biết những dịch vụ bạn có thể cần.","h2":"Biển màu xanh dương có chữ H trắng chỉ tới bệnh viện, để bạn tìm được chỗ chữa bệnh gần đó.","p":"Đúng rồi. Biển chữ H màu xanh dương nghĩa là gần đây có bệnh viện."},"tl":{"q":"Ang asul na karatula ay nagpapakita ng malaking puting letrang H. Ano ang ibig sabihin nito?","o":["May ospital sa malapit","May hotel sa malapit","May helipad sa malapit","Dito natatapos ang highway"],"h1":"Ang mga asul na karatula ay nagpapakita ng mga serbisyong maaaring kailanganin mo.","h2":"Ang asul na karatula na may puting H ay nagtuturo sa ospital, kaya makakahanap ka ng tulong medikal sa malapit.","p":"Tama. Ang asul na karatulang H ay nangangahulugang may ospital sa malapit."},"ar":{"q":"لافتة زرقاء عليها حرف H أبيض كبير. ماذا تعني؟","o":["مستشفى قريب","فندق قريب","مهبط طائرات مروحية قريب","الطريق السريع ينتهي هنا"],"h1":"اللافتات الزرقاء تُظهر خدمات قد تحتاجها.","h2":"اللافتة الزرقاء التي عليها حرف H أبيض ترشدك إلى مستشفى، لكي تجد مساعدة طبية قريبة.","p":"صحيح. لافتة H الزرقاء تعني أن هناك مستشفى قريبًا."},"ht":{"q":"Yon siy ble montre yon gwo lèt H blan. Kisa li vle di?","o":["Gen yon lopital toupre","Gen yon otèl toupre","Gen yon kote elikoptè ateri toupre","Gran wout la fini la a"],"h1":"Siy ble yo montre sèvis ou ka bezwen.","h2":"Yon siy ble ak yon H blan montre yon lopital, kidonk ou ka jwenn swen medikal toupre.","p":"Se sa. Siy ble ak H la vle di gen yon lopital toupre."},"ref":{"doc":"FL","page":46}},{"id":"signs-048","scope":"US","cat":"signs","sign":null,"c":1,"en":{"q":"On traffic signs, what does the color red usually mean?","o":["A warning about the road ahead","Stop, yield, or something is not allowed","Directions to a place","Services like gas and food"],"h1":"Think of the stop sign and the do not enter sign.","h2":"Red on a sign usually means stop, yield, or that something is not allowed, like on the stop sign and the do not enter sign.","p":"Right. Red means stop, yield, or not allowed."},"es":{"q":"En las señales de tránsito, ¿qué significa normalmente el color rojo?","o":["Un aviso sobre la vía más adelante","Pare, ceda el paso o algo no está permitido","Direcciones hacia un lugar","Servicios como gasolina y comida"],"h1":"Piense en la señal de pare y en la de no entre.","h2":"El rojo en una señal normalmente quiere decir pare, ceda el paso o que algo no está permitido, como en la señal de pare y la de no entre.","p":"Correcto. El rojo significa pare, ceda el paso o no está permitido."},"zh":{"q":"在交通标志上，红色通常表示什么？","o":["提醒前方道路的情况","停车、让行，或某件事不允许","去某个地方的方向","加油、吃饭等服务"],"h1":"想一想停车标志和禁止驶入标志。","h2":"标志上的红色通常表示停车、让行，或某件事不允许，比如停车标志和禁止驶入标志。","p":"对。红色表示停车、让行或不允许。"},"vi":{"q":"Trên biển báo giao thông, màu đỏ thường có nghĩa là gì?","o":["Cảnh báo về con đường phía trước","Dừng lại, nhường đường, hoặc có điều gì đó bị cấm","Chỉ đường tới một nơi","Dịch vụ như xăng và đồ ăn"],"h1":"Hãy nghĩ đến biển dừng và biển cấm đi vào.","h2":"Màu đỏ trên biển báo thường có nghĩa là dừng lại, nhường đường, hoặc có điều gì đó bị cấm, như trên biển “STOP” và biển “DO NOT ENTER”.","p":"Đúng rồi. Màu đỏ nghĩa là dừng lại, nhường đường, hoặc bị cấm."},"tl":{"q":"Sa mga karatula ng trapiko, ano ang karaniwang ibig sabihin ng kulay pula?","o":["Babala tungkol sa kalsada sa unahan","Huminto, magbigay-daan, o may bagay na hindi pinapayagan","Direksyon papunta sa isang lugar","Mga serbisyo tulad ng gasolina at pagkain"],"h1":"Isipin ang “STOP” sign at ang “DO NOT ENTER” sign.","h2":"Ang pula sa karatula ay karaniwang nangangahulugang huminto, magbigay-daan, o may bagay na hindi pinapayagan, tulad ng sa “STOP” sign at sa “DO NOT ENTER” sign.","p":"Tama. Ang pula ay nangangahulugang huminto, magbigay-daan, o hindi pinapayagan."},"ar":{"q":"على لافتات المرور، ماذا يعني اللون الأحمر عادةً؟","o":["تحذير من الطريق في الأمام","قف، أو أعطِ الأولوية، أو أن شيئًا ممنوع","الاتجاه إلى مكان ما","خدمات مثل الوقود والطعام"],"h1":"فكّر في لافتة «STOP» ولافتة «DO NOT ENTER».","h2":"اللون الأحمر على اللافتة يعني عادةً قف، أو أعطِ الأولوية، أو أن شيئًا ممنوع، مثل لافتة «STOP» (قف) ولافتة «DO NOT ENTER» (ممنوع الدخول).","p":"صحيح. الأحمر يعني قف، أو أعطِ الأولوية، أو ممنوع."},"ht":{"q":"Sou siy trafik yo, kisa koulè wouj la konn vle di?","o":["Yon avètisman sou wout la pi devan","Kanpe, bay pasaj, oswa yon bagay ki pa pèmèt","Direksyon pou yon kote","Sèvis tankou gaz ak manje"],"h1":"Panse ak siy “STOP” la ak siy “DO NOT ENTER” la.","h2":"Wouj sou yon siy konn vle di kanpe, bay pasaj, oswa yon bagay ki pa pèmèt, tankou sou siy “STOP” la ak siy “DO NOT ENTER” la.","p":"Se sa. Wouj vle di kanpe, bay pasaj, oswa sa pa pèmèt."},"ref":{"doc":"FL","page":46}},{"id":"signs-049","scope":"US","cat":"signs","sign":null,"c":2,"en":{"q":"A bright yellow-green sign shows a person walking. What should you watch for?","o":["People on bicycles only","Animals crossing","People crossing the road","Road workers"],"h1":"Look at the picture on the sign.","h2":"A yellow-green sign with a walking person warns that people may be crossing the road, so slow down and be ready to stop for them.","p":"Right. Watch for people crossing the road."},"es":{"q":"Una señal verde amarillenta brillante muestra a una persona caminando. ¿A qué debe estar atento?","o":["Solo a personas en bicicleta","A animales cruzando","A personas cruzando la vía","A trabajadores de la vía"],"h1":"Mire el dibujo en la señal.","h2":"Una señal verde amarillenta con una persona caminando avisa que puede haber personas cruzando la vía, así que baje la velocidad y esté listo para pararse por ellas.","p":"Correcto. Esté atento a personas cruzando la vía."},"zh":{"q":"一个亮黄绿色标志上画着一个走路的人。你应该注意什么？","o":["只注意骑自行车的人","动物过马路","行人过马路","道路工人"],"h1":"看看标志上的图。","h2":"画着走路的人的黄绿色标志提醒你可能有行人过马路，所以要减速，准备为他们停车。","p":"对。注意过马路的行人。"},"vi":{"q":"Một biển màu vàng chanh có hình người đang đi bộ. Bạn nên chú ý điều gì?","o":["Chỉ người đi xe đạp","Thú vật băng qua đường","Người đi bộ băng qua đường","Công nhân sửa đường"],"h1":"Hãy nhìn hình vẽ trên biển.","h2":"Biển màu vàng chanh có hình người đi bộ cảnh báo rằng có thể có người băng qua đường, nên bạn cần chạy chậm lại và sẵn sàng dừng cho họ.","p":"Đúng rồi. Hãy chú ý người đi bộ băng qua đường."},"tl":{"q":"Ang matingkad na dilaw-berdeng karatula ay nagpapakita ng taong naglalakad. Ano ang dapat mong bantayan?","o":["Mga taong nakabisikleta lang","Mga hayop na tumatawid","Mga taong tumatawid sa kalsada","Mga trabahador sa kalsada"],"h1":"Tingnan ang larawan sa karatula.","h2":"Ang dilaw-berdeng karatula na may taong naglalakad ay babala na maaaring may mga taong tumatawid sa kalsada, kaya bumagal at maging handang huminto para sa kanila.","p":"Tama. Mag-ingat sa mga taong tumatawid sa kalsada."},"ar":{"q":"لافتة بلون أصفر مخضر لامع تُظهر شخصًا يمشي. ما الذي يجب أن تنتبه له؟","o":["أشخاص على الدراجات فقط","حيوانات تعبر","أشخاص يعبرون الطريق","عمال الطرق"],"h1":"انظر إلى الصورة على اللافتة.","h2":"اللافتة الصفراء المخضرة التي عليها شخص يمشي تحذّر من أن أشخاصًا قد يعبرون الطريق، لذلك خفف السرعة وكن مستعدًا للتوقف من أجلهم.","p":"صحيح. انتبه للأشخاص الذين يعبرون الطريق."},"ht":{"q":"Yon siy jòn-vèt klè montre yon moun k ap mache. Kisa ou dwe veye?","o":["Moun sou bisiklèt sèlman","Bèt k ap travèse","Moun k ap travèse wout la","Travayè sou wout la"],"h1":"Gade foto ki sou siy la.","h2":"Yon siy jòn-vèt ak yon moun k ap mache avèti ou ka gen moun k ap travèse wout la, kidonk ralanti epi pare pou kanpe pou yo.","p":"Se sa. Veye moun k ap travèse wout la."},"ref":{"doc":"FL","page":46}},{"id":"speed-lanes-001","scope":"FL","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Florida, what is the speed limit in a business or residential area when no sign says otherwise?","o":["25 mph","35 mph","30 mph","40 mph"],"h1":"Think of streets with homes and shops, where people walk a lot.","h2":"The speed limit in a Florida business or residential area is 30 mph unless a sign shows a different limit.","p":"Right. Business and residential areas in Florida are 30 mph unless posted."},"es":{"q":"En Florida, ¿cuál es el límite de velocidad en una zona comercial o residencial si no hay letrero que diga otra cosa?","o":["25 mph","35 mph","30 mph","40 mph"],"h1":"Piense en calles con casas y tiendas, donde camina mucha gente.","h2":"El límite de velocidad en una zona comercial o residencial de Florida es 30 mph, a menos que un letrero indique otro límite.","p":"Correcto. En Florida, las zonas comerciales y residenciales son de 30 mph si no hay otro letrero."},"zh":{"q":"在 Florida，在商业区或住宅区，如果没有标志另外规定，限速是多少？","o":["25 英里/小时","35 英里/小时","30 英里/小时","40 英里/小时"],"h1":"想一想有住家和商店、很多人走路的街道。","h2":"在 Florida 的商业区或住宅区，限速是 30 英里/小时，除非有标志写着别的限速。","p":"对。Florida 的商业区和住宅区限速 30 英里/小时，除非另有标志。"},"vi":{"q":"Ở Florida, giới hạn tốc độ trong khu kinh doanh hoặc khu dân cư là bao nhiêu khi không có biển báo khác?","o":["25 mph","35 mph","30 mph","40 mph"],"h1":"Hãy nghĩ đến những con đường có nhà ở và cửa hàng, nơi có nhiều người đi bộ.","h2":"Giới hạn tốc độ trong khu kinh doanh hoặc khu dân cư ở Florida là 30 mph, trừ khi có biển báo giới hạn khác.","p":"Đúng. Khu kinh doanh và khu dân cư ở Florida là 30 mph nếu không có biển báo khác."},"tl":{"q":"Sa Florida, ano ang speed limit sa lugar ng negosyo o tirahan kapag walang karatulang nagsasabi ng iba?","o":["25 mph","35 mph","30 mph","40 mph"],"h1":"Isipin ang mga kalyeng may bahay at tindahan, kung saan maraming naglalakad.","h2":"Ang speed limit sa lugar ng negosyo o tirahan sa Florida ay 30 mph, maliban kung may karatulang nagpapakita ng ibang limit.","p":"Tama. 30 mph ang limit sa mga lugar ng negosyo at tirahan sa Florida, maliban kung may nakapaskil na iba."},"ar":{"q":"في Florida، ما حد السرعة في منطقة تجارية أو سكنية عندما لا توجد علامة تقول غير ذلك؟","o":["25 ميلًا في الساعة","35 ميلًا في الساعة","30 ميلًا في الساعة","40 ميلًا في الساعة"],"h1":"فكّر في شوارع فيها بيوت ومحلات، ويمشي فيها الناس كثيرًا.","h2":"حد السرعة في المنطقة التجارية أو السكنية في Florida هو 30 ميلًا في الساعة، إلا إذا كانت هناك علامة تُظهر حدًا آخر.","p":"صحيح. في المناطق التجارية والسكنية في Florida الحد 30 ميلًا في الساعة، إلا إذا كُتب غير ذلك."},"ht":{"q":"Nan Florida, ki limit vitès la nan yon zòn biznis oswa yon zòn kote moun rete, lè pa gen siy ki di lòt bagay?","o":["25 mph","35 mph","30 mph","40 mph"],"h1":"Panse ak lari ki gen kay ak magazen, kote anpil moun ap mache.","h2":"Limit vitès la nan yon zòn biznis oswa yon zòn kote moun rete nan Florida se 30 mph, sòf si yon siy montre yon lòt limit.","p":"Wi, se sa. Nan Florida, zòn biznis ak zòn kote moun rete se 30 mph, sòf si gen siy."},"ref":{"doc":"FL","page":68}},{"id":"speed-lanes-002","scope":"FL","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Florida, what is the highest speed limit allowed on a rural interstate highway?","o":["70 mph","65 mph","75 mph","60 mph"],"h1":"This is the fastest limit you will see on any Florida road.","h2":"The top speed limit on a Florida rural interstate is 70 mph, and you must still follow the posted sign.","p":"Right. Rural interstates in Florida can be posted up to 70 mph."},"es":{"q":"En Florida, ¿cuál es el límite de velocidad más alto permitido en una autopista interestatal rural?","o":["70 mph","65 mph","75 mph","60 mph"],"h1":"Es el límite más alto que verá en cualquier carretera de Florida.","h2":"El límite más alto en una interestatal rural de Florida es 70 mph, y siempre debe seguir el letrero que esté puesto.","p":"Correcto. Las interestatales rurales de Florida pueden tener un límite de hasta 70 mph."},"zh":{"q":"在 Florida，乡村州际公路上允许的最高限速是多少？","o":["70 英里/小时","65 英里/小时","75 英里/小时","60 英里/小时"],"h1":"这是你在 Florida 任何道路上会看到的最高限速。","h2":"Florida 乡村州际公路的最高限速是 70 英里/小时，而且你还是要遵守路上标出的限速。","p":"对。Florida 的乡村州际公路限速最高可以标到 70 英里/小时。"},"vi":{"q":"Ở Florida, giới hạn tốc độ cao nhất được phép trên xa lộ liên bang (interstate) ở vùng nông thôn là bao nhiêu?","o":["70 mph","65 mph","75 mph","60 mph"],"h1":"Đây là giới hạn nhanh nhất bạn sẽ thấy trên mọi con đường ở Florida.","h2":"Giới hạn tốc độ cao nhất trên xa lộ liên bang vùng nông thôn ở Florida là 70 mph, và bạn vẫn phải theo biển báo trên đường.","p":"Đúng. Xa lộ liên bang vùng nông thôn ở Florida có thể có giới hạn đến 70 mph."},"tl":{"q":"Sa Florida, ano ang pinakamataas na speed limit na pinapayagan sa rural interstate highway (interstate sa labas ng lungsod)?","o":["70 mph","65 mph","75 mph","60 mph"],"h1":"Ito ang pinakamabilis na limit na makikita mo sa anumang daan sa Florida.","h2":"Ang pinakamataas na speed limit sa rural interstate sa Florida ay 70 mph, at dapat mo pa ring sundin ang nakapaskil na karatula.","p":"Tama. Ang mga rural interstate sa Florida ay puwedeng may limit hanggang 70 mph."},"ar":{"q":"في Florida، ما أعلى حد سرعة مسموح به على طريق سريع بين الولايات (interstate) في منطقة ريفية؟","o":["70 ميلًا في الساعة","65 ميلًا في الساعة","75 ميلًا في الساعة","60 ميلًا في الساعة"],"h1":"هذا أعلى حد سرعة ستراه على أي طريق في Florida.","h2":"أعلى حد سرعة على طريق interstate ريفي في Florida هو 70 ميلًا في الساعة، ويجب أن تتبع أيضًا العلامة المكتوبة.","p":"صحيح. على طرق interstate الريفية في Florida يمكن أن يصل الحد المكتوب إلى 70 ميلًا في الساعة."},"ht":{"q":"Nan Florida, ki limit vitès ki pi wo yo pèmèt sou yon gran wout entèeta (interstate) nan zòn andeyò?","o":["70 mph","65 mph","75 mph","60 mph"],"h1":"Se limit ki pi rapid ou ap wè sou nenpòt wout nan Florida.","h2":"Limit vitès ki pi wo sou yon gran wout entèeta nan zòn andeyò nan Florida se 70 mph, epi ou dwe toujou swiv siy ki afiche a.","p":"Wi, se sa. Gran wout entèeta nan zòn andeyò nan Florida ka gen yon limit jiska 70 mph."},"ref":{"doc":"FL","page":68}},{"id":"speed-lanes-003","scope":"FL","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Florida, what is the speed limit on a highway outside a city when no sign is posted?","o":["45 mph","65 mph","70 mph","55 mph"],"h1":"It is lower than the interstate limit, but higher than city streets.","h2":"When no speed limit sign is posted on a Florida highway outside a city, the limit is 55 mph.","p":"Right. With no sign on other Florida highways, the limit is 55 mph."},"es":{"q":"En Florida, ¿cuál es el límite de velocidad en una carretera fuera de la ciudad cuando no hay letrero?","o":["45 mph","65 mph","70 mph","55 mph"],"h1":"Es más bajo que en la interestatal, pero más alto que en las calles de la ciudad.","h2":"Cuando no hay letrero de límite en una carretera de Florida fuera de la ciudad, el límite es 55 mph.","p":"Correcto. Sin letrero en otras carreteras de Florida, el límite es 55 mph."},"zh":{"q":"在 Florida，城市以外的公路上没有限速标志时，限速是多少？","o":["45 英里/小时","65 英里/小时","70 英里/小时","55 英里/小时"],"h1":"它比州际公路的限速低，但比城市街道高。","h2":"在 Florida 城市以外的公路上，如果没有限速标志，限速是 55 英里/小时。","p":"对。Florida 其他公路上没有标志时，限速是 55 英里/小时。"},"vi":{"q":"Ở Florida, giới hạn tốc độ trên xa lộ ngoài thành phố là bao nhiêu khi không có biển báo?","o":["45 mph","65 mph","70 mph","55 mph"],"h1":"Nó thấp hơn giới hạn trên xa lộ liên bang, nhưng cao hơn đường trong thành phố.","h2":"Khi không có biển giới hạn tốc độ trên xa lộ ngoài thành phố ở Florida, giới hạn là 55 mph.","p":"Đúng. Không có biển báo trên các xa lộ khác ở Florida thì giới hạn là 55 mph."},"tl":{"q":"Sa Florida, ano ang speed limit sa highway sa labas ng lungsod kapag walang nakapaskil na karatula?","o":["45 mph","65 mph","70 mph","55 mph"],"h1":"Mas mababa ito sa limit ng interstate, pero mas mataas sa mga kalye ng lungsod.","h2":"Kapag walang nakapaskil na speed limit sign sa highway ng Florida sa labas ng lungsod, 55 mph ang limit.","p":"Tama. Kapag walang karatula sa ibang highway sa Florida, 55 mph ang limit."},"ar":{"q":"في Florida، ما حد السرعة على طريق سريع خارج المدينة عندما لا توجد علامة؟","o":["45 ميلًا في الساعة","65 ميلًا في الساعة","70 ميلًا في الساعة","55 ميلًا في الساعة"],"h1":"هو أقل من حد طرق interstate، لكنه أعلى من حد شوارع المدينة.","h2":"عندما لا توجد علامة حد سرعة على طريق سريع خارج المدينة في Florida، يكون الحد 55 ميلًا في الساعة.","p":"صحيح. على الطرق السريعة الأخرى في Florida بدون علامة، الحد 55 ميلًا في الساعة."},"ht":{"q":"Nan Florida, ki limit vitès la sou yon gran wout deyò vil, lè pa gen okenn siy?","o":["45 mph","65 mph","70 mph","55 mph"],"h1":"Li pi ba pase limit gran wout entèeta a, men li pi wo pase lari nan vil.","h2":"Lè pa gen okenn siy limit vitès sou yon gran wout deyò vil nan Florida, limit la se 55 mph.","p":"Wi, se sa. Lè pa gen siy sou lòt gran wout nan Florida, limit la se 55 mph."},"ref":{"doc":"FL","page":68}},{"id":"speed-lanes-004","scope":"FL","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Florida, on an interstate where the speed limit is 70 mph, what is the lowest speed you may drive in good conditions?","o":["40 mph","50 mph","45 mph","30 mph"],"h1":"Driving too slow on a fast road is also unsafe. There is a minimum.","h2":"On a Florida interstate posted at 70 mph, the minimum speed is 50 mph when the weather and traffic are normal.","p":"Right. The minimum speed on a 70 mph Florida interstate is 50 mph."},"es":{"q":"En Florida, en una interestatal con límite de 70 mph, ¿cuál es la velocidad más baja permitida con buenas condiciones?","o":["40 mph","50 mph","45 mph","30 mph"],"h1":"Manejar muy despacio en una vía rápida también es peligroso. Hay un mínimo.","h2":"En una interestatal de Florida con límite de 70 mph, la velocidad mínima es 50 mph cuando el clima y el tráfico son normales.","p":"Correcto. La velocidad mínima en una interestatal de Florida de 70 mph es 50 mph."},"zh":{"q":"在 Florida，在限速 70 英里/小时的州际公路上，天气和路况好的时候，你最慢可以开多快？","o":["40 英里/小时","50 英里/小时","45 英里/小时","30 英里/小时"],"h1":"在快速道路上开得太慢也不安全。有一个最低速度。","h2":"在 Florida 限速 70 英里/小时的州际公路上，天气和交通正常时，最低速度是 50 英里/小时。","p":"对。Florida 限速 70 英里/小时的州际公路，最低速度是 50 英里/小时。"},"vi":{"q":"Ở Florida, trên xa lộ liên bang có giới hạn tốc độ 70 mph, tốc độ thấp nhất bạn được chạy khi điều kiện tốt là bao nhiêu?","o":["40 mph","50 mph","45 mph","30 mph"],"h1":"Chạy quá chậm trên đường nhanh cũng không an toàn. Có một tốc độ tối thiểu.","h2":"Trên xa lộ liên bang ở Florida có giới hạn 70 mph, tốc độ tối thiểu là 50 mph khi thời tiết và giao thông bình thường.","p":"Đúng. Tốc độ tối thiểu trên xa lộ liên bang 70 mph ở Florida là 50 mph."},"tl":{"q":"Sa Florida, sa interstate na 70 mph ang speed limit, ano ang pinakamababang bilis na puwede mong takbuhin kapag maayos ang kondisyon?","o":["40 mph","50 mph","45 mph","30 mph"],"h1":"Delikado rin ang sobrang bagal sa mabilis na daan. May minimum.","h2":"Sa interstate sa Florida na 70 mph ang limit, 50 mph ang minimum na bilis kapag normal ang panahon at trapiko.","p":"Tama. 50 mph ang minimum na bilis sa interstate sa Florida na 70 mph ang limit."},"ar":{"q":"في Florida، على طريق interstate حد السرعة فيه 70 ميلًا في الساعة، ما أقل سرعة يمكنك أن تقود بها عندما تكون الظروف جيدة؟","o":["40 ميلًا في الساعة","50 ميلًا في الساعة","45 ميلًا في الساعة","30 ميلًا في الساعة"],"h1":"القيادة ببطء شديد على طريق سريع خطيرة أيضًا. هناك حد أدنى.","h2":"على طريق interstate في Florida حده المكتوب 70 ميلًا في الساعة، الحد الأدنى للسرعة هو 50 ميلًا في الساعة عندما يكون الطقس والسير عاديين.","p":"صحيح. الحد الأدنى على طريق interstate في Florida حده 70 ميلًا في الساعة هو 50 ميلًا في الساعة."},"ht":{"q":"Nan Florida, sou yon gran wout entèeta kote limit vitès la se 70 mph, ki vitès ki pi ba ou ka kondi lè kondisyon yo bon?","o":["40 mph","50 mph","45 mph","30 mph"],"h1":"Kondi twò dousman sou yon wout rapid danjere tou. Gen yon vitès minimòm.","h2":"Sou yon gran wout entèeta nan Florida ki gen limit 70 mph, vitès minimòm lan se 50 mph lè tan an ak sikilasyon an nòmal.","p":"Wi, se sa. Vitès minimòm sou yon gran wout entèeta 70 mph nan Florida se 50 mph."},"ref":{"doc":"FL","page":68}},{"id":"speed-lanes-005","scope":"FL","cat":"speed-lanes","sign":{"shape":"school","text":"SCHOOL"},"c":1,"en":{"q":"In Florida, when must you obey the lower speed limit in a school zone?","o":["Only when you see children on the road","When the lights flash or during the times shown on the sign","Only on Monday mornings","Only when a police car is nearby"],"h1":"Look at the sign. It tells you when the lower limit is active.","h2":"You must obey the school zone speed limit when its lights are flashing or during the hours shown on the sign, even if you do not see children.","p":"Right. Follow the school zone limit when the lights flash or during the posted times."},"es":{"q":"En Florida, ¿cuándo debe respetar el límite de velocidad más bajo en una zona escolar?","o":["Solo cuando ve niños en la calle","Cuando las luces parpadean o en las horas que indica el letrero","Solo los lunes por la mañana","Solo cuando hay un carro de policía cerca"],"h1":"Mire el letrero. Le dice cuándo aplica el límite más bajo.","h2":"Debe respetar el límite de la zona escolar cuando las luces parpadean o en las horas que indica el letrero, aunque no vea niños.","p":"Correcto. Respete el límite escolar cuando las luces parpadean o en las horas indicadas."},"zh":{"q":"在 Florida，什么时候必须遵守学校区较低的限速？","o":["只有看到路上有小孩时","灯在闪的时候，或标志上写的时间内","只在星期一早上","只有附近有警车时"],"h1":"看标志。它会告诉你较低的限速什么时候生效。","h2":"当学校区的灯在闪，或在标志上写的时间内，你必须遵守学校区限速，就算你没看到小孩也一样。","p":"对。灯在闪或在标出的时间内，要遵守学校区限速。"},"vi":{"q":"Ở Florida, khi nào bạn phải tuân theo giới hạn tốc độ thấp hơn trong khu vực trường học?","o":["Chỉ khi bạn thấy trẻ em trên đường","Khi đèn nháy hoặc trong khung giờ ghi trên biển báo","Chỉ vào sáng thứ Hai","Chỉ khi có xe cảnh sát gần đó"],"h1":"Hãy nhìn biển báo. Biển cho bạn biết khi nào giới hạn thấp hơn có hiệu lực.","h2":"Bạn phải tuân theo giới hạn tốc độ khu vực trường học khi đèn đang nháy hoặc trong khung giờ ghi trên biển, kể cả khi bạn không thấy trẻ em.","p":"Đúng. Hãy theo giới hạn khu vực trường học khi đèn nháy hoặc trong giờ ghi trên biển."},"tl":{"q":"Sa Florida, kailan mo dapat sundin ang mas mababang speed limit sa school zone?","o":["Kapag may nakikita ka lang na mga bata sa daan","Kapag kumikislap ang mga ilaw o sa mga oras na nakasulat sa karatula","Tuwing Lunes ng umaga lang","Kapag may kotse lang ng pulis sa malapit"],"h1":"Tingnan ang karatula. Sinasabi nito kung kailan umiiral ang mas mababang limit.","h2":"Dapat mong sundin ang speed limit sa school zone kapag kumikislap ang mga ilaw nito o sa mga oras na nakasulat sa karatula, kahit wala kang nakikitang bata.","p":"Tama. Sundin ang limit sa school zone kapag kumikislap ang ilaw o sa mga nakapaskil na oras."},"ar":{"q":"في Florida، متى يجب أن تلتزم بحد السرعة الأقل في منطقة المدرسة؟","o":["فقط عندما أرى أطفالًا في الطريق","عندما تومض الأضواء أو في الأوقات المكتوبة على العلامة","فقط صباح يوم الاثنين","فقط عندما تكون سيارة شرطة قريبة"],"h1":"انظر إلى العلامة. هي تخبرك متى يبدأ العمل بالحد الأقل.","h2":"يجب أن تلتزم بحد السرعة في منطقة المدرسة عندما تومض أضواؤها أو في الساعات المكتوبة على العلامة، حتى لو لم ترَ أطفالًا.","p":"صحيح. اتبع حد منطقة المدرسة عندما تومض الأضواء أو في الأوقات المكتوبة."},"ht":{"q":"Nan Florida, kilè ou dwe respekte limit vitès ki pi ba a nan yon zòn lekòl?","o":["Sèlman lè ou wè timoun sou wout la","Lè limyè yo ap flache oswa pandan lè ki ekri sou siy la","Sèlman lendi maten","Sèlman lè gen yon machin polis tou pre"],"h1":"Gade siy la. Li di ou kilè limit ki pi ba a an vigè.","h2":"Ou dwe respekte limit vitès zòn lekòl la lè limyè li yo ap flache oswa pandan lè ki ekri sou siy la, menm si ou pa wè timoun.","p":"Wi, se sa. Swiv limit zòn lekòl la lè limyè yo ap flache oswa pandan lè ki ekri sou siy la."},"ref":{"doc":"FL","page":57}},{"id":"speed-lanes-006","scope":"FL","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Florida, it is raining hard and you are on a road posted at 55 mph. How fast should you drive?","o":["Exactly 55 mph, because that is the limit","A little faster than 55 mph to get out of the rain","Any speed, because rain does not change the rules","Slower than 55 mph, at a speed that is safe for the rain"],"h1":"A speed limit is the most you may drive in good conditions.","h2":"You must never drive faster than is safe for the conditions, so in heavy rain you should drive slower than the posted 55 mph.","p":"Right. In bad weather, slow down below the limit to a safe speed."},"es":{"q":"En Florida, está lloviendo fuerte y usted va por una carretera con límite de 55 mph. ¿A qué velocidad debe manejar?","o":["Exactamente a 55 mph, porque ese es el límite","Un poco más rápido que 55 mph para salir de la lluvia","A cualquier velocidad, porque la lluvia no cambia las reglas","Más despacio que 55 mph, a una velocidad segura para la lluvia"],"h1":"El límite de velocidad es lo máximo que puede manejar con buenas condiciones.","h2":"Nunca debe manejar más rápido de lo que es seguro para las condiciones, así que con lluvia fuerte debe ir más despacio que 55 mph.","p":"Correcto. Con mal clima, baje la velocidad por debajo del límite a una velocidad segura."},"zh":{"q":"在 Florida，雨下得很大，你在一条限速 55 英里/小时的路上。你应该开多快？","o":["正好 55 英里/小时，因为那是限速","比 55 英里/小时快一点，好赶快离开大雨","什么速度都行，因为下雨不改变规则","比 55 英里/小时慢，用适合下雨的安全速度"],"h1":"限速是路况好的时候你最多可以开的速度。","h2":"你永远不能开得比路况允许的安全速度更快，所以下大雨时，你应该开得比标出的 55 英里/小时更慢。","p":"对。天气不好时，要减速到低于限速的安全速度。"},"vi":{"q":"Ở Florida, trời đang mưa to và bạn đang chạy trên đường có biển giới hạn 55 mph. Bạn nên chạy nhanh bao nhiêu?","o":["Đúng 55 mph, vì đó là giới hạn","Nhanh hơn 55 mph một chút để ra khỏi cơn mưa","Tốc độ nào cũng được, vì mưa không thay đổi luật","Chậm hơn 55 mph, ở tốc độ an toàn khi trời mưa"],"h1":"Giới hạn tốc độ là mức cao nhất bạn được chạy khi điều kiện tốt.","h2":"Bạn không bao giờ được chạy nhanh hơn mức an toàn cho điều kiện lúc đó, nên khi mưa to bạn nên chạy chậm hơn 55 mph ghi trên biển.","p":"Đúng. Khi thời tiết xấu, hãy giảm tốc xuống dưới giới hạn đến mức an toàn."},"tl":{"q":"Sa Florida, malakas ang ulan at nasa daan ka na 55 mph ang nakapaskil na limit. Gaano ka kabilis dapat magmaneho?","o":["Eksaktong 55 mph, dahil iyon ang limit","Medyo mas mabilis sa 55 mph para makaalis sa ulan","Kahit anong bilis, dahil hindi binabago ng ulan ang patakaran","Mas mabagal sa 55 mph, sa bilis na ligtas sa ulan"],"h1":"Ang speed limit ay ang pinakamabilis na puwede mong takbuhin kapag maayos ang kondisyon.","h2":"Hindi ka dapat kailanman magmaneho nang mas mabilis kaysa sa ligtas para sa kondisyon, kaya sa malakas na ulan dapat kang magmaneho nang mas mabagal sa nakapaskil na 55 mph.","p":"Tama. Kapag masama ang panahon, bumagal sa ilalim ng limit, sa ligtas na bilis."},"ar":{"q":"في Florida، المطر شديد وأنت على طريق حده المكتوب 55 ميلًا في الساعة. بأي سرعة يجب أن تقود؟","o":["55 ميلًا في الساعة بالضبط، لأن هذا هو الحد","أسرع قليلًا من 55 ميلًا في الساعة لأخرج من المطر","بأي سرعة، لأن المطر لا يغيّر القواعد","أبطأ من 55 ميلًا في الساعة، بسرعة آمنة في المطر"],"h1":"حد السرعة هو أعلى سرعة مسموحة عندما تكون الظروف جيدة.","h2":"لا يجوز أبدًا أن تقود أسرع مما هو آمن في الظروف الموجودة، لذلك في المطر الشديد يجب أن تقود أبطأ من الحد المكتوب 55 ميلًا في الساعة.","p":"صحيح. في الطقس السيئ، خفف السرعة إلى أقل من الحد، إلى سرعة آمنة."},"ht":{"q":"Nan Florida, lapli ap tonbe fò epi ou sou yon wout ki gen limit 55 mph. Ak ki vitès ou ta dwe kondi?","o":["Egzakteman 55 mph, paske se limit la","Yon ti kras pi vit pase 55 mph pou sòti anba lapli a","Nenpòt vitès, paske lapli pa chanje règ yo","Pi dousman pase 55 mph, a yon vitès ki san danje pou lapli a"],"h1":"Yon limit vitès se maksimòm ou ka kondi lè kondisyon yo bon.","h2":"Ou pa dwe janm kondi pi vit pase sa ki san danje pou kondisyon yo, kidonk lè gen gwo lapli ou ta dwe kondi pi dousman pase 55 mph ki afiche a.","p":"Wi, se sa. Lè tan an move, desann anba limit la pou yon vitès ki san danje."},"ref":{"doc":"FL","page":null}},{"id":"speed-lanes-007","scope":"FL","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Florida, can you get a ticket for driving too slowly?","o":["Yes, if you block the normal flow of traffic","No, driving slowly is always legal","Only if you drive slower than 10 mph","Only on dirt roads"],"h1":"Think about what happens to the cars behind a very slow driver.","h2":"Yes. In Florida you can get a ticket if you drive so slowly that you block the normal and safe flow of traffic.","p":"Right. Driving so slowly that you block traffic is against the law."},"es":{"q":"En Florida, ¿le pueden dar una multa por manejar demasiado despacio?","o":["Sí, si bloquea el flujo normal del tráfico","No, manejar despacio siempre es legal","Solo si maneja a menos de 10 mph","Solo en caminos de tierra"],"h1":"Piense en lo que les pasa a los carros que van detrás de alguien muy lento.","h2":"Sí. En Florida le pueden poner una multa si maneja tan despacio que bloquea el flujo normal y seguro del tráfico.","p":"Correcto. Manejar tan despacio que bloquea el tráfico va contra la ley."},"zh":{"q":"在 Florida，开得太慢会被开罚单吗？","o":["会，如果你挡住了正常的车流","不会，开得慢永远是合法的","只有开得比 10 英里/小时还慢时才会","只在土路上才会"],"h1":"想一想，跟在很慢的司机后面的车会怎么样。","h2":"会。在 Florida，如果你开得太慢，挡住了正常、安全的车流，你可能会被开罚单。","p":"对。开得太慢、挡住车流是违法的。"},"vi":{"q":"Ở Florida, bạn có thể bị phạt vì lái xe quá chậm không?","o":["Có, nếu bạn cản trở dòng xe bình thường","Không, lái chậm luôn hợp pháp","Chỉ khi bạn chạy chậm hơn 10 mph","Chỉ trên đường đất"],"h1":"Hãy nghĩ xem chuyện gì xảy ra với các xe phía sau một người lái rất chậm.","h2":"Có. Ở Florida bạn có thể bị phạt nếu lái chậm đến mức cản trở dòng xe bình thường và an toàn.","p":"Đúng. Lái chậm đến mức cản trở giao thông là trái luật."},"tl":{"q":"Sa Florida, puwede ka bang matiketan dahil sa sobrang bagal na pagmamaneho?","o":["Oo, kung naharangan mo ang normal na daloy ng trapiko","Hindi, laging legal ang mabagal na pagmamaneho","Kung mas mabagal ka lang sa 10 mph","Sa mga daang lupa lang"],"h1":"Isipin ang nangyayari sa mga kotse sa likod ng sobrang bagal na drayber.","h2":"Oo. Sa Florida, puwede kang matiketan kung napakabagal mong magmaneho na naharangan mo ang normal at ligtas na daloy ng trapiko.","p":"Tama. Labag sa batas ang sobrang bagal na pagmamaneho na humaharang sa trapiko."},"ar":{"q":"في Florida، هل يمكن أن تحصل على مخالفة لأنك تقود ببطء شديد؟","o":["نعم، إذا كنت أعيق حركة السير العادية","لا، القيادة البطيئة مسموحة دائمًا","فقط إذا كنت أقود أبطأ من 10 أميال في الساعة","فقط على الطرق الترابية"],"h1":"فكّر ماذا يحدث للسيارات التي خلف سائق بطيء جدًا.","h2":"نعم. في Florida يمكن أن تحصل على مخالفة إذا كنت تقود ببطء شديد حتى تعيق حركة السير العادية والآمنة.","p":"صحيح. القيادة ببطء شديد حتى تعيق السير مخالفة للقانون."},"ht":{"q":"Nan Florida, èske ou ka pran yon kontravansyon paske ou kondi twò dousman?","o":["Wi, si ou bloke sikilasyon nòmal la","Non, kondi dousman toujou legal","Sèlman si ou kondi pi dousman pase 10 mph","Sèlman sou wout tè"],"h1":"Panse ak sa k ap rive machin ki dèyè yon chofè ki kondi trè dousman.","h2":"Wi. Nan Florida ou ka pran yon kontravansyon si ou kondi tèlman dousman ou bloke sikilasyon nòmal ki san danje a.","p":"Wi, se sa. Kondi tèlman dousman ou bloke sikilasyon an se kont lalwa."},"ref":{"doc":"FL","page":68}},{"id":"speed-lanes-008","scope":"US","cat":"speed-lanes","sign":{"shape":"rect-white","text":"SPEED LIMIT 55"},"c":2,"en":{"q":"What does this white sign tell you?","o":["You must drive exactly 55 mph","The slowest speed allowed is 55 mph","The fastest speed allowed in good conditions is 55 mph","The suggested speed for a curve is 55 mph"],"h1":"White signs with black letters are rules. Is this number a top or a bottom?","h2":"A white speed limit sign shows the highest legal speed when conditions are good, so you may not drive faster than 55 mph there.","p":"Right. The speed limit sign shows the top legal speed in good conditions."},"es":{"q":"¿Qué le indica este letrero blanco?","o":["Debe manejar exactamente a 55 mph","La velocidad más baja permitida es 55 mph","La velocidad más alta permitida con buenas condiciones es 55 mph","La velocidad sugerida para una curva es 55 mph"],"h1":"Los letreros blancos con letras negras son reglas. ¿Este número es un máximo o un mínimo?","h2":"Un letrero blanco de límite de velocidad muestra la velocidad legal más alta con buenas condiciones, así que no puede manejar a más de 55 mph allí.","p":"Correcto. El letrero de límite muestra la velocidad legal más alta con buenas condiciones."},"zh":{"q":"这个白色标志告诉你什么？","o":["你必须正好开 55 英里/小时","允许的最低速度是 55 英里/小时","路况好时允许的最高速度是 55 英里/小时","弯道的建议速度是 55 英里/小时"],"h1":"白底黑字的标志是规定。这个数字是最高还是最低？","h2":"白色的限速标志显示路况好时的最高合法速度，所以在那里你不能开得比 55 英里/小时更快。","p":"对。限速标志显示路况好时的最高合法速度。"},"vi":{"q":"Biển báo màu trắng này cho bạn biết điều gì?","o":["Bạn phải chạy đúng 55 mph","Tốc độ chậm nhất được phép là 55 mph","Tốc độ nhanh nhất được phép khi điều kiện tốt là 55 mph","Tốc độ đề nghị khi vào khúc cua là 55 mph"],"h1":"Biển trắng chữ đen là luật. Con số này là mức cao nhất hay thấp nhất?","h2":"Biển trắng \"SPEED LIMIT\" (Giới hạn tốc độ) cho biết tốc độ hợp pháp cao nhất khi điều kiện tốt, nên ở đó bạn không được chạy nhanh hơn 55 mph.","p":"Đúng. Biển \"SPEED LIMIT\" cho biết tốc độ hợp pháp cao nhất khi điều kiện tốt."},"tl":{"q":"Ano ang sinasabi sa iyo ng puting karatulang ito?","o":["Dapat kang magmaneho nang eksaktong 55 mph","Ang pinakamabagal na pinapayagang bilis ay 55 mph","Ang pinakamabilis na pinapayagang bilis kapag maayos ang kondisyon ay 55 mph","Ang iminumungkahing bilis sa kurbada ay 55 mph"],"h1":"Ang mga puting karatulang may itim na letra ay mga patakaran. Pinakamataas ba o pinakamababa ang numerong ito?","h2":"Ang puting speed limit sign ay nagpapakita ng pinakamataas na legal na bilis kapag maayos ang kondisyon, kaya hindi ka puwedeng magmaneho nang mas mabilis sa 55 mph doon.","p":"Tama. Ipinapakita ng speed limit sign ang pinakamataas na legal na bilis kapag maayos ang kondisyon."},"ar":{"q":"ماذا تخبرك هذه العلامة البيضاء؟","o":["يجب أن أقود بسرعة 55 ميلًا في الساعة بالضبط","أقل سرعة مسموحة هي 55 ميلًا في الساعة","أعلى سرعة مسموحة في الظروف الجيدة هي 55 ميلًا في الساعة","السرعة المقترحة للمنعطف هي 55 ميلًا في الساعة"],"h1":"العلامات البيضاء ذات الحروف السوداء هي قواعد. هل هذا الرقم حد أعلى أم حد أدنى؟","h2":"علامة \"SPEED LIMIT\" (حد السرعة) البيضاء تُظهر أعلى سرعة قانونية عندما تكون الظروف جيدة، لذلك لا يجوز أن تقود هناك أسرع من 55 ميلًا في الساعة.","p":"صحيح. علامة حد السرعة تُظهر أعلى سرعة قانونية في الظروف الجيدة."},"ht":{"q":"Kisa siy blan sa a di ou?","o":["Ou dwe kondi egzakteman 55 mph","Vitès ki pi dousman yo pèmèt la se 55 mph","Vitès ki pi rapid yo pèmèt lè kondisyon yo bon an se 55 mph","Vitès yo konseye pou yon koub se 55 mph"],"h1":"Siy blan ak lèt nwa se règ. Èske chif sa a se yon maksimòm oswa yon minimòm?","h2":"Yon siy limit vitès blan montre vitès legal ki pi wo a lè kondisyon yo bon, kidonk ou pa ka kondi pi vit pase 55 mph la.","p":"Wi, se sa. Siy limit vitès la montre vitès legal ki pi wo a lè kondisyon yo bon."},"ref":{"doc":"FL","page":47}},{"id":"speed-lanes-009","scope":"US","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"What is a good way to check if you are following too closely?","o":["Count the car lengths in your mirror","Watch the speed of the car behind you","Count the seconds after the car ahead passes a fixed object","Check if you can read the license plate ahead"],"h1":"Pick something that does not move, like a sign or a pole.","h2":"When the car ahead passes a fixed object, count the seconds until you reach it, and if you reach it too soon, you are following too closely.","p":"Right. Counting seconds past a fixed object shows your following distance."},"es":{"q":"¿Cuál es una buena forma de saber si va demasiado cerca del carro de adelante?","o":["Contar los largos de carro en el espejo","Mirar la velocidad del carro que va detrás","Contar los segundos después de que el carro de adelante pasa un objeto fijo","Ver si puede leer la placa del carro de adelante"],"h1":"Escoja algo que no se mueva, como un letrero o un poste.","h2":"Cuando el carro de adelante pasa un objeto fijo, cuente los segundos hasta que usted llegue allí; si llega muy pronto, va demasiado cerca.","p":"Correcto. Contar segundos desde un objeto fijo muestra su distancia de seguimiento."},"zh":{"q":"用什么好方法可以检查你是不是跟车太近？","o":["在后视镜里数有几个车身长度","看你后面那辆车的速度","前车经过一个固定的东西后，数几秒","看你能不能看清前车的车牌"],"h1":"选一个不会动的东西，比如一个标志或一根柱子。","h2":"当前车经过一个固定的东西时，数一数你几秒后到达那里，如果你太快就到了，说明你跟车太近。","p":"对。数经过固定物体的秒数，就能知道你的跟车距离。"},"vi":{"q":"Cách nào tốt để kiểm tra xem bạn có đang chạy quá sát xe phía trước không?","o":["Đếm số chiều dài xe trong gương","Xem tốc độ của xe phía sau bạn","Đếm số giây sau khi xe phía trước chạy qua một vật đứng yên","Xem bạn có đọc được biển số xe phía trước không"],"h1":"Hãy chọn một vật không di chuyển, như biển báo hoặc cột điện.","h2":"Khi xe phía trước chạy qua một vật đứng yên, bạn đếm số giây cho đến khi bạn đến vật đó, và nếu bạn đến quá sớm thì bạn đang chạy quá sát.","p":"Đúng. Đếm số giây qua một vật đứng yên cho biết khoảng cách của bạn với xe trước."},"tl":{"q":"Ano ang magandang paraan para malaman kung masyado kang malapit sa sinusundan mo?","o":["Bilangin ang haba ng mga kotse sa salamin mo","Bantayan ang bilis ng kotse sa likod mo","Bilangin ang mga segundo matapos dumaan ang kotse sa unahan sa isang bagay na hindi gumagalaw","Tingnan kung nababasa mo ang plaka sa unahan"],"h1":"Pumili ng bagay na hindi gumagalaw, gaya ng karatula o poste.","h2":"Kapag dumaan ang kotse sa unahan sa isang bagay na hindi gumagalaw, bilangin ang mga segundo hanggang marating mo ito, at kung masyadong maaga mo itong narating, masyado kang malapit.","p":"Tama. Ipinapakita ng pagbilang ng segundo sa isang bagay na hindi gumagalaw ang layo mo sa sinusundan."},"ar":{"q":"ما الطريقة الجيدة لتعرف إن كنت تقترب كثيرًا من السيارة التي أمامك؟","o":["أعدّ أطوال السيارات في المرآة","أراقب سرعة السيارة التي خلفي","أعدّ الثواني بعد أن تمر السيارة التي أمامي بجانب شيء ثابت","أرى إن كنت أستطيع قراءة لوحة السيارة التي أمامي"],"h1":"اختر شيئًا لا يتحرك، مثل علامة أو عمود.","h2":"عندما تمر السيارة التي أمامك بجانب شيء ثابت، عدّ الثواني حتى تصل أنت إليه، وإذا وصلت إليه بسرعة كبيرة، فأنت قريب جدًا منها.","p":"صحيح. عدّ الثواني بعد شيء ثابت يُظهر لك مسافة الأمان خلف السيارة."},"ht":{"q":"Ki bon fason pou tcheke si w ap swiv twò pre?","o":["Konte longè machin nan retwovizè ou","Gade vitès machin ki dèyè ou a","Konte segonn yo apre machin devan an fin pase yon bagay ki pa bouje","Tcheke si ou ka li plak machin devan an"],"h1":"Chwazi yon bagay ki pa bouje, tankou yon siy oswa yon poto.","h2":"Lè machin devan an pase yon bagay ki pa bouje, konte segonn yo jiskaske ou rive la, epi si ou rive twò vit, sa vle di w ap swiv twò pre.","p":"Wi, se sa. Konte segonn apre yon bagay ki pa bouje montre distans ou kite dèyè lòt machin nan."},"ref":{"doc":"FL","page":61}},{"id":"speed-lanes-010","scope":"US","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"When should you leave more space between you and the car ahead?","o":["When the road is wet or slippery","When the road is dry and clear","When you are driving slower than usual in town","When the car ahead is a small car"],"h1":"Think about when your car needs more distance to stop.","h2":"You should leave more space when the road is wet or slippery, because your car needs a longer distance to stop.","p":"Right. On wet or slippery roads, leave extra space ahead."},"es":{"q":"¿Cuándo debe dejar más espacio entre usted y el carro de adelante?","o":["Cuando la carretera está mojada o resbalosa","Cuando la carretera está seca y despejada","Cuando maneja más despacio de lo normal en la ciudad","Cuando el carro de adelante es pequeño"],"h1":"Piense en cuándo su carro necesita más distancia para frenar.","h2":"Debe dejar más espacio cuando la carretera está mojada o resbalosa, porque su carro necesita más distancia para detenerse.","p":"Correcto. En carretera mojada o resbalosa, deje más espacio adelante."},"zh":{"q":"什么时候你应该和前车留更多距离？","o":["路面湿或滑的时候","路面干燥、视线清楚的时候","在城里开得比平时慢的时候","前车是小车的时候"],"h1":"想一想，什么时候你的车需要更长的距离才能停下。","h2":"路面湿或滑时，你应该留更多距离，因为你的车需要更长的距离才能停下。","p":"对。路面湿或滑时，和前车多留一些距离。"},"vi":{"q":"Khi nào bạn nên để khoảng cách lớn hơn giữa bạn và xe phía trước?","o":["Khi đường ướt hoặc trơn","Khi đường khô và thông thoáng","Khi bạn chạy chậm hơn thường lệ trong thành phố","Khi xe phía trước là xe nhỏ"],"h1":"Hãy nghĩ xem khi nào xe của bạn cần quãng đường dài hơn để dừng lại.","h2":"Bạn nên để khoảng cách lớn hơn khi đường ướt hoặc trơn, vì xe của bạn cần quãng đường dài hơn để dừng lại.","p":"Đúng. Khi đường ướt hoặc trơn, hãy để thêm khoảng cách phía trước."},"tl":{"q":"Kailan ka dapat mag-iwan ng mas malaking espasyo sa pagitan mo at ng kotse sa unahan?","o":["Kapag basa o madulas ang daan","Kapag tuyo at malinis ang daan","Kapag mas mabagal ka kaysa karaniwan sa bayan","Kapag maliit na kotse ang nasa unahan"],"h1":"Isipin kung kailan kailangan ng kotse mo ng mas mahabang layo para huminto.","h2":"Dapat kang mag-iwan ng mas malaking espasyo kapag basa o madulas ang daan, dahil kailangan ng kotse mo ng mas mahabang layo para huminto.","p":"Tama. Sa basa o madulas na daan, mag-iwan ng dagdag na espasyo sa unahan."},"ar":{"q":"متى يجب أن تترك مسافة أكبر بينك وبين السيارة التي أمامك؟","o":["عندما يكون الطريق مبللًا أو زلقًا","عندما يكون الطريق جافًا وواضحًا","عندما أقود في المدينة أبطأ من العادة","عندما تكون السيارة التي أمامي صغيرة"],"h1":"فكّر متى تحتاج سيارتك إلى مسافة أكبر لتتوقف.","h2":"يجب أن تترك مسافة أكبر عندما يكون الطريق مبللًا أو زلقًا، لأن سيارتك تحتاج إلى مسافة أطول لتتوقف.","p":"صحيح. على الطرق المبللة أو الزلقة، اترك مسافة إضافية أمامك."},"ht":{"q":"Kilè ou ta dwe kite plis espas ant ou ak machin ki devan ou a?","o":["Lè wout la mouye oswa li glise","Lè wout la sèk epi li klè","Lè w ap kondi pi dousman pase dabitid nan vil","Lè machin devan an se yon ti machin"],"h1":"Panse ak kilè machin ou bezwen plis distans pou l kanpe.","h2":"Ou ta dwe kite plis espas lè wout la mouye oswa li glise, paske machin ou bezwen yon distans pi long pou l kanpe.","p":"Wi, se sa. Sou wout ki mouye oswa ki glise, kite plis espas devan ou."},"ref":{"doc":"FL","page":61}},{"id":"speed-lanes-011","scope":"US","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"Your total stopping distance is made of which parts?","o":["Only the distance you travel while braking","Only the time it takes you to see the danger","The length of your car plus one car length","The distance you travel while you notice, react, and brake"],"h1":"Your car keeps moving before your foot even touches the brake.","h2":"Total stopping distance includes the distance you travel while you see the danger, while you move your foot, and while the brakes slow the car.","p":"Right. Stopping distance adds noticing, reacting, and braking."},"es":{"q":"¿De qué partes se forma la distancia total para detenerse?","o":["Solo la distancia que recorre mientras frena","Solo el tiempo que tarda en ver el peligro","El largo de su carro más el largo de otro carro","La distancia que recorre mientras nota el peligro, reacciona y frena"],"h1":"Su carro sigue avanzando antes de que su pie toque el freno.","h2":"La distancia total para detenerse incluye lo que recorre mientras ve el peligro, mientras mueve el pie y mientras los frenos paran el carro.","p":"Correcto. La distancia para detenerse suma notar, reaccionar y frenar."},"zh":{"q":"你的总停车距离由哪些部分组成？","o":["只有刹车时开过的距离","只有你看到危险所用的时间","你的车长再加一个车身长度","你注意到危险、做出反应和刹车时开过的距离"],"h1":"你的脚还没碰到刹车，车就一直在往前走。","h2":"总停车距离包括你看到危险时、你移动脚时，以及刹车让车慢下来时开过的距离。","p":"对。停车距离包括注意、反应和刹车这三部分。"},"vi":{"q":"Tổng quãng đường dừng xe của bạn gồm những phần nào?","o":["Chỉ quãng đường bạn chạy trong lúc đạp phanh","Chỉ thời gian bạn cần để thấy nguy hiểm","Chiều dài xe của bạn cộng thêm một chiều dài xe","Quãng đường bạn chạy trong lúc bạn nhận ra, phản ứng và đạp phanh"],"h1":"Xe của bạn vẫn chạy tiếp trước khi chân bạn chạm vào phanh.","h2":"Tổng quãng đường dừng xe gồm quãng đường bạn chạy trong lúc thấy nguy hiểm, trong lúc bạn di chuyển chân, và trong lúc phanh làm xe chậm lại.","p":"Đúng. Quãng đường dừng xe gồm lúc nhận ra, lúc phản ứng và lúc phanh."},"tl":{"q":"Ano-anong bahagi ang bumubuo sa kabuuang layo ng paghinto mo (total stopping distance)?","o":["Ang layong tinatakbo mo habang nagpepreno lang","Ang oras lang na kailangan mo para makita ang panganib","Ang haba ng kotse mo dagdag ang haba ng isang kotse","Ang layong tinatakbo mo habang napapansin mo, tumutugon ka, at nagpepreno"],"h1":"Umaandar pa ang kotse mo bago pa man dumampi ang paa mo sa preno.","h2":"Kasama sa kabuuang layo ng paghinto ang layong tinatakbo mo habang nakikita mo ang panganib, habang inililipat mo ang paa mo, at habang pinababagal ng preno ang kotse.","p":"Tama. Pinagsasama ng layo ng paghinto ang pagpansin, pagtugon, at pagpreno."},"ar":{"q":"من أي أجزاء تتكون مسافة التوقف الكاملة؟","o":["فقط المسافة التي تقطعها وأنت تضغط على الفرامل","فقط الوقت الذي تحتاجه لترى الخطر","طول سيارتك وطول سيارة أخرى","المسافة التي تقطعها وأنت تلاحظ الخطر، وتتفاعل، وتضغط على الفرامل"],"h1":"سيارتك تستمر في الحركة قبل أن تلمس قدمك الفرامل.","h2":"مسافة التوقف الكاملة تشمل المسافة التي تقطعها في ثلاث مراحل: وأنت ترى الخطر، ثم وأنت تحرك قدمك، ثم بينما تبطئ الفرامل السيارة.","p":"صحيح. مسافة التوقف تجمع الملاحظة والتفاعل والفرملة."},"ht":{"q":"Ak ki pati distans total pou ou kanpe a fèt?","o":["Sèlman distans ou fè pandan w ap fren","Sèlman tan ou pran pou wè danje a","Longè machin ou plis longè yon machin","Distans ou fè pandan ou remake danje a, ou reyaji epi ou fren"],"h1":"Machin ou kontinye avanse menm anvan pye ou touche fren an.","h2":"Distans total pou kanpe a gen ladan l distans ou fè pandan ou wè danje a, pandan ou deplase pye ou, ak pandan fren yo ap ralanti machin nan.","p":"Wi, se sa. Distans pou kanpe a se remake, reyaji, epi fren, tout ansanm."},"ref":{"doc":"FL","page":60}},{"id":"speed-lanes-012","scope":"US","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"If you drive twice as fast, what happens to the distance your brakes need to stop the car?","o":["It stays the same","It becomes about four times longer","It becomes about two times longer","It becomes shorter"],"h1":"Speed makes stopping harder very quickly, not just a little.","h2":"When your speed doubles, your braking distance becomes about four times longer, because the car carries much more energy.","p":"Right. Double the speed means about four times the braking distance."},"es":{"q":"Si maneja al doble de velocidad, ¿qué pasa con la distancia que necesitan los frenos para parar el carro?","o":["Se queda igual","Se vuelve unas cuatro veces más larga","Se vuelve unas dos veces más larga","Se vuelve más corta"],"h1":"La velocidad hace que frenar sea mucho más difícil, no solo un poco.","h2":"Cuando su velocidad se duplica, la distancia de frenado se vuelve unas cuatro veces más larga, porque el carro lleva mucha más energía.","p":"Correcto. El doble de velocidad significa unas cuatro veces la distancia de frenado."},"zh":{"q":"如果你的车速变成两倍，刹车停下需要的距离会怎么样？","o":["保持不变","变成大约四倍长","变成大约两倍长","变短"],"h1":"速度会让停车变得难很多，不只是难一点。","h2":"车速变成两倍时，刹车距离会变成大约四倍长，因为车带着多得多的能量。","p":"对。车速两倍，刹车距离大约是四倍。"},"vi":{"q":"Nếu bạn chạy nhanh gấp đôi, quãng đường phanh cần để dừng xe sẽ thay đổi thế nào?","o":["Vẫn như cũ","Dài hơn khoảng bốn lần","Dài hơn khoảng hai lần","Ngắn hơn"],"h1":"Tốc độ làm việc dừng xe khó hơn rất nhanh, không chỉ một chút.","h2":"Khi tốc độ tăng gấp đôi, quãng đường phanh của bạn dài hơn khoảng bốn lần, vì xe mang nhiều năng lượng hơn rất nhiều.","p":"Đúng. Tốc độ gấp đôi thì quãng đường phanh dài khoảng gấp bốn."},"tl":{"q":"Kung doble ang bilis mo, ano ang nangyayari sa layong kailangan ng preno mo para mapahinto ang kotse?","o":["Hindi ito nagbabago","Nagiging mga apat na beses itong mas mahaba","Nagiging mga dalawang beses itong mas mahaba","Umiikli ito"],"h1":"Napakabilis na pinahihirap ng bilis ang paghinto, hindi lang nang kaunti.","h2":"Kapag dumoble ang bilis mo, nagiging mga apat na beses na mas mahaba ang layo ng pagpreno, dahil mas malaki ang lakas (enerhiya) na dala ng kotse.","p":"Tama. Ang dobleng bilis ay nangangahulugang mga apat na beses ang layo ng pagpreno."},"ar":{"q":"إذا قدت بضعف السرعة، ماذا يحدث للمسافة التي تحتاجها الفرامل لتوقف السيارة؟","o":["تبقى كما هي","تصبح أطول بحوالي أربع مرات","تصبح أطول بحوالي مرتين","تصبح أقصر"],"h1":"السرعة تجعل التوقف أصعب بكثير وبسرعة، وليس قليلًا فقط.","h2":"عندما تتضاعف سرعتك، تصبح مسافة الفرملة أطول بحوالي أربع مرات، لأن السيارة تحمل طاقة أكبر بكثير.","p":"صحيح. ضعف السرعة يعني حوالي أربعة أضعاف مسافة الفرملة."},"ht":{"q":"Si ou kondi de fwa pi vit, kisa ki rive distans fren ou bezwen pou kanpe machin nan?","o":["Li rete menm jan an","Li vin apeprè kat fwa pi long","Li vin apeprè de fwa pi long","Li vin pi kout"],"h1":"Vitès fè li vin pi difisil pou kanpe trè vit, se pa yon ti kras sèlman.","h2":"Lè vitès ou double, distans fren ou vin apeprè kat fwa pi long, paske machin nan pote anpil plis enèji.","p":"Wi, se sa. De fwa vitès la vle di apeprè kat fwa distans fren an."},"ref":{"doc":"FL","page":60}},{"id":"speed-lanes-013","scope":"US","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"A driver is following very close behind you. What is the safest thing to do?","o":["Tap your brakes hard to warn the driver","Leave more space ahead of you and let the driver pass","Speed up to get away from the driver","Stop in your lane until the driver goes around"],"h1":"If you must stop suddenly, the driver behind may hit you. How can you avoid sudden stops?","h2":"The safest choice is to leave extra space ahead of you, so you can slow down gently, and to let the close driver pass.","p":"Right. Give yourself more space ahead and let a tailgater pass."},"es":{"q":"Un conductor va muy pegado detrás de usted. ¿Qué es lo más seguro?","o":["Frenar fuerte para avisarle al conductor","Dejar más espacio adelante y dejar que el conductor lo rebase","Acelerar para alejarse del conductor","Detenerse en su carril hasta que el conductor lo rodee"],"h1":"Si tiene que frenar de golpe, el de atrás puede chocarlo. ¿Cómo puede evitar frenadas de golpe?","h2":"Lo más seguro es dejar más espacio adelante para poder frenar suavemente, y dejar que el conductor que va pegado lo rebase.","p":"Correcto. Deje más espacio adelante y deje que el conductor pegado lo rebase."},"zh":{"q":"有一个司机紧紧跟在你后面。最安全的做法是什么？","o":["用力点一下刹车，警告那个司机","在你前面留更多空间，让那个司机超过去","加速，甩开那个司机","在你的车道里停车，等那个司机绕过去"],"h1":"如果你必须突然停车，后面的司机可能会撞上你。怎样才能避免突然停车？","h2":"最安全的做法是在你前面多留空间，这样你可以慢慢减速，并让跟得很近的司机超过去。","p":"对。在前面多留空间，让跟车太近的司机超过去。"},"vi":{"q":"Một người lái đang chạy rất sát phía sau bạn. Điều an toàn nhất nên làm là gì?","o":["Đạp phanh mạnh để cảnh báo người đó","Để thêm khoảng cách phía trước và để người đó vượt qua","Tăng tốc để tránh xa người đó","Dừng lại trong làn cho đến khi người đó vòng qua"],"h1":"Nếu bạn phải dừng gấp, người phía sau có thể đâm vào bạn. Làm sao để tránh phải dừng gấp?","h2":"Điều an toàn nhất là để thêm khoảng cách phía trước, để bạn có thể giảm tốc nhẹ nhàng, và để người lái bám sát vượt qua.","p":"Đúng. Hãy để thêm khoảng cách phía trước và để người bám sát vượt qua."},"tl":{"q":"May drayber na sobrang lapit sa likod mo. Ano ang pinakaligtas na gawin?","o":["Biglang tapakan ang preno para bigyan ng babala ang drayber","Mag-iwan ng mas malaking espasyo sa unahan mo at hayaang lumampas ang drayber","Bumilis para makalayo sa drayber","Huminto sa lane mo hanggang umikot ang drayber"],"h1":"Kung bigla kang hihinto, maaaring mabangga ka ng drayber sa likod. Paano mo maiiwasan ang biglang paghinto?","h2":"Ang pinakaligtas na gawin ay mag-iwan ng dagdag na espasyo sa unahan mo, para dahan-dahan kang makabagal, at hayaang lumampas ang drayber na sobrang lapit.","p":"Tama. Bigyan ang sarili ng mas malaking espasyo sa unahan at hayaang lumampas ang dumidikit sa likod mo."},"ar":{"q":"سائق يسير قريبًا جدًا خلفك. ما أكثر شيء آمن تفعله؟","o":["أضغط على الفرامل بقوة لأحذّر السائق","أترك مسافة أكبر أمامي وأترك السائق يتجاوزني","أسرع لأبتعد عن السائق","أتوقف في مساري حتى يلتف السائق حولي"],"h1":"إذا اضطررت إلى التوقف فجأة، قد يصدمك السائق الذي خلفك. كيف تتجنب التوقف المفاجئ؟","h2":"الخيار الأكثر أمانًا هو أن تترك مسافة إضافية أمامك، حتى تستطيع أن تخفف السرعة بهدوء، وأن تترك السائق القريب يتجاوزك.","p":"صحيح. اترك لنفسك مسافة أكبر أمامك واترك السائق الملاصق لك يتجاوزك."},"ht":{"q":"Yon chofè ap swiv ou trè pre dèyè. Kisa ki pi an sekirite pou ou fè?","o":["Peze fren an fò pou avèti chofè a","Kite plis espas devan ou epi kite chofè a pase","Akselere pou ale lwen chofè a","Kanpe nan liy ou jiskaske chofè a pase bò kote ou"],"h1":"Si ou oblije kanpe sou kou, chofè ki dèyè a ka frape ou. Kijan ou ka evite kanpe sou kou?","h2":"Pi bon chwa a se kite plis espas devan ou, pou ou ka ralanti dousman, epi kite chofè ki twò pre a pase.","p":"Wi, se sa. Kite plis espas devan ou epi kite chofè ki twò pre dèyè ou a pase."}},{"id":"speed-lanes-014","scope":"FL","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Florida, on a two-lane road, how close to an intersection or railroad crossing may you pass another car?","o":["Not within 25 feet","Not within 50 feet","Passing is allowed right up to it","Not within 100 feet"],"h1":"Cars and trains may enter the road there. You need a clear stretch.","h2":"In Florida you may not pass on a two-lane road within 100 feet of an intersection or a railroad crossing, because traffic may enter or stop there.","p":"Right. Do not pass within 100 feet of an intersection or railroad crossing."},"es":{"q":"En Florida, en una carretera de dos carriles, ¿qué tan cerca de una intersección o un cruce de tren puede rebasar a otro carro?","o":["No a menos de 25 pies","No a menos de 50 pies","Se puede rebasar hasta llegar allí","No a menos de 100 pies"],"h1":"Allí pueden entrar carros o trenes. Necesita un tramo despejado.","h2":"En Florida no puede rebasar en una carretera de dos carriles a menos de 100 pies de una intersección o de un cruce de tren, porque el tráfico puede entrar o detenerse allí.","p":"Correcto. No rebase a menos de 100 pies de una intersección o un cruce de tren."},"zh":{"q":"在 Florida，在双车道道路上，离路口或铁路道口多近时不能超车？","o":["25 英尺以内不能超车","50 英尺以内不能超车","可以一直超车到路口","100 英尺以内不能超车"],"h1":"车和火车可能在那里开进来。你需要一段畅通的路。","h2":"在 Florida，在双车道道路上，离路口或铁路道口 100 英尺以内不能超车，因为车辆可能在那里开进来或停下。","p":"对。离路口或铁路道口 100 英尺以内不要超车。"},"vi":{"q":"Ở Florida, trên đường hai làn, bạn được vượt xe khác gần giao lộ hoặc chỗ giao nhau với đường sắt đến mức nào?","o":["Không được trong vòng 25 feet","Không được trong vòng 50 feet","Được vượt sát đến tận đó","Không được trong vòng 100 feet"],"h1":"Xe hơi và tàu hỏa có thể đi vào đường ở đó. Bạn cần một đoạn đường trống.","h2":"Ở Florida, bạn không được vượt trên đường hai làn trong vòng 100 feet trước giao lộ hoặc chỗ giao nhau với đường sắt, vì xe cộ có thể đi vào hoặc dừng ở đó.","p":"Đúng. Không vượt trong vòng 100 feet trước giao lộ hoặc chỗ giao nhau với đường sắt."},"tl":{"q":"Sa Florida, sa daang may dalawang lane, gaano kalapit sa intersection o railroad crossing ka puwedeng lumampas sa ibang kotse?","o":["Hindi sa loob ng 25 feet","Hindi sa loob ng 50 feet","Puwedeng lumampas hanggang mismong doon","Hindi sa loob ng 100 feet"],"h1":"Maaaring pumasok sa daan ang mga kotse at tren doon. Kailangan mo ng malinis na bahagi ng daan.","h2":"Sa Florida, hindi ka puwedeng lumampas sa daang may dalawang lane sa loob ng 100 feet mula sa intersection o railroad crossing, dahil maaaring pumasok o huminto ang trapiko roon.","p":"Tama. Huwag lumampas sa loob ng 100 feet mula sa intersection o railroad crossing."},"ar":{"q":"في Florida، على طريق فيه مساران، كم يمكنك أن تقترب من تقاطع أو من تقاطع سكة حديد وأنت تتجاوز سيارة أخرى؟","o":["ليس في حدود 25 قدمًا","ليس في حدود 50 قدمًا","التجاوز مسموح حتى الوصول إليه","ليس في حدود 100 قدم"],"h1":"السيارات والقطارات قد تدخل الطريق هناك. تحتاج إلى مسافة فارغة.","h2":"في Florida لا يجوز أن تتجاوز على طريق فيه مساران في حدود 100 قدم من تقاطع أو من تقاطع سكة حديد، لأن السيارات قد تدخل أو تتوقف هناك.","p":"صحيح. لا تتجاوز في حدود 100 قدم من تقاطع أو من تقاطع سكة حديد."},"ht":{"q":"Nan Florida, sou yon wout ki gen de liy, a ki distans de yon kafou oswa yon kwazman tren ou ka double yon lòt machin?","o":["Pa nan mwens pase 25 pye","Pa nan mwens pase 50 pye","Ou ka double jis rive bò kote l","Pa nan mwens pase 100 pye"],"h1":"Machin ak tren ka antre sou wout la la. Ou bezwen yon bout wout ki lib.","h2":"Nan Florida ou pa ka double sou yon wout ki gen de liy nan mwens pase 100 pye de yon kafou oswa yon kwazman tren, paske machin ka antre oswa kanpe la.","p":"Wi, se sa. Pa double nan mwens pase 100 pye de yon kafou oswa yon kwazman tren."},"ref":{"doc":"FL","page":67}},{"id":"speed-lanes-015","scope":"FL","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Florida, when may you pass another car on the right?","o":["When the car ahead is turning left and there is a lane to pass in","When the car ahead is going a little slow on a two-lane road","When you can use the paved shoulder","Whenever the left lane is busy"],"h1":"You must stay on the road itself, not on the shoulder.","h2":"You may pass on the right when the car ahead is turning left and there is a full lane for you, but you may never drive on the shoulder to pass.","p":"Right. Pass on the right only with a real lane, like when a car is turning left."},"es":{"q":"En Florida, ¿cuándo puede rebasar a otro carro por la derecha?","o":["Cuando el carro de adelante va a girar a la izquierda y hay un carril para rebasar","Cuando el carro de adelante va un poco lento en una carretera de dos carriles","Cuando puede usar el acotamiento pavimentado","Siempre que el carril izquierdo esté ocupado"],"h1":"Debe quedarse en la vía, no en el acotamiento.","h2":"Puede rebasar por la derecha cuando el carro de adelante va a girar a la izquierda y hay un carril completo para usted, pero nunca puede usar el acotamiento para rebasar.","p":"Correcto. Rebase por la derecha solo si hay un carril de verdad, como cuando un carro gira a la izquierda."},"zh":{"q":"在 Florida，什么时候可以从右边超车？","o":["前车正在左转，而且有一条车道可以超车时","在双车道道路上，前车开得有点慢时","你可以用铺了路面的路肩时","左边车道车很多的时候"],"h1":"你必须留在道路上，不能开到路肩上。","h2":"当前车正在左转，而且有一整条车道给你时，你可以从右边超车，但你永远不能开上路肩去超车。","p":"对。只有在有真正车道时才从右边超车，比如前车正在左转时。"},"vi":{"q":"Ở Florida, khi nào bạn được vượt xe khác bên phải?","o":["Khi xe phía trước đang rẽ trái và có làn để bạn vượt","Khi xe phía trước chạy hơi chậm trên đường hai làn","Khi bạn có thể dùng lề đường tráng nhựa","Bất cứ khi nào làn trái đông xe"],"h1":"Bạn phải ở trên mặt đường, không phải trên lề.","h2":"Bạn được vượt bên phải khi xe phía trước đang rẽ trái và có một làn đầy đủ cho bạn, nhưng bạn không bao giờ được chạy trên lề để vượt.","p":"Đúng. Chỉ vượt bên phải khi có làn thật sự, như khi xe phía trước đang rẽ trái."},"tl":{"q":"Sa Florida, kailan ka puwedeng lumampas sa ibang kotse sa kanan?","o":["Kapag kumakaliwa ang kotse sa unahan at may lane na madadaanan mo","Kapag medyo mabagal ang kotse sa unahan sa daang may dalawang lane","Kapag puwede mong gamitin ang sementadong shoulder","Tuwing masikip ang kaliwang lane"],"h1":"Dapat kang manatili sa mismong daan, hindi sa shoulder.","h2":"Puwede kang lumampas sa kanan kapag kumakaliwa ang kotse sa unahan at may buong lane para sa iyo, pero hindi ka kailanman puwedeng magmaneho sa shoulder para lumampas.","p":"Tama. Lumampas sa kanan lang kapag may tunay na lane, gaya ng kapag kumakaliwa ang isang kotse."},"ar":{"q":"في Florida، متى يمكنك أن تتجاوز سيارة أخرى من اليمين؟","o":["عندما تنعطف السيارة التي أمامي يسارًا ويوجد مسار أتجاوز فيه","عندما تسير السيارة التي أمامي ببطء قليلًا على طريق فيه مساران","عندما أستطيع أن أستعمل كتف الطريق المرصوف","كلما كان المسار الأيسر مزدحمًا"],"h1":"يجب أن تبقى على الطريق نفسه، وليس على كتف الطريق.","h2":"يمكنك أن تتجاوز من اليمين عندما تنعطف السيارة التي أمامك يسارًا ويوجد مسار كامل لك، لكن لا يجوز أبدًا أن تقود على كتف الطريق لتتجاوز.","p":"صحيح. تجاوز من اليمين فقط عندما يوجد مسار حقيقي، مثل عندما تنعطف سيارة يسارًا."},"ht":{"q":"Nan Florida, kilè ou ka double yon lòt machin sou bò dwat?","o":["Lè machin devan an ap vire agòch epi gen yon liy pou ou pase","Lè machin devan an ap kondi yon ti kras dousman sou yon wout ki gen de liy","Lè ou ka sèvi ak bò wout ki asfalte a","Chak fwa liy gòch la chaje"],"h1":"Ou dwe rete sou wout la menm, pa sou bò wout la.","h2":"Ou ka double sou bò dwat lè machin devan an ap vire agòch epi gen yon liy konplè pou ou, men ou pa janm ka kondi sou bò wout la pou double.","p":"Wi, se sa. Double sou bò dwat sèlman lè gen yon vrè liy, tankou lè yon machin ap vire agòch."},"ref":{"doc":"FL","page":67}},{"id":"speed-lanes-016","scope":"FL","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Florida, another car is passing you. What should you do?","o":["Speed up so the other car cannot pass","Move to the left to block the other car","Stay in your lane and do not speed up","Brake hard to let the other car in"],"h1":"Make it easy and safe for the other driver to finish passing.","h2":"When another car passes you, you must stay in your lane and not speed up, so the other driver can finish passing safely.","p":"Right. When someone passes you, keep your lane and do not speed up."},"es":{"q":"En Florida, otro carro lo está rebasando. ¿Qué debe hacer?","o":["Acelerar para que el otro carro no lo rebase","Moverse a la izquierda para bloquear al otro carro","Quedarse en su carril y no acelerar","Frenar fuerte para dejar entrar al otro carro"],"h1":"Hágale fácil y seguro al otro conductor terminar de rebasar.","h2":"Cuando otro carro lo rebasa, debe quedarse en su carril y no acelerar, para que el otro conductor termine de rebasar con seguridad.","p":"Correcto. Cuando alguien lo rebasa, quédese en su carril y no acelere."},"zh":{"q":"在 Florida，另一辆车正在超你的车。你应该怎么做？","o":["加速，不让对方超过去","向左移，挡住对方","留在你的车道里，不要加速","用力刹车，让对方进来"],"h1":"让对方司机能轻松、安全地完成超车。","h2":"别的车超你时，你必须留在你的车道里，不要加速，让对方司机能安全地完成超车。","p":"对。有人超你时，保持在你的车道，不要加速。"},"vi":{"q":"Ở Florida, một xe khác đang vượt bạn. Bạn nên làm gì?","o":["Tăng tốc để xe kia không vượt được","Lấn sang trái để chặn xe kia","Ở lại trong làn của bạn và không tăng tốc","Phanh gấp để cho xe kia vào"],"h1":"Hãy giúp người lái kia vượt xong một cách dễ dàng và an toàn.","h2":"Khi có xe khác vượt bạn, bạn phải ở lại trong làn và không tăng tốc, để người lái kia vượt xong an toàn.","p":"Đúng. Khi có người vượt bạn, hãy giữ làn và không tăng tốc."},"tl":{"q":"Sa Florida, may ibang kotseng lumalampas sa iyo. Ano ang dapat mong gawin?","o":["Bumilis para hindi makalampas ang ibang kotse","Lumipat pakaliwa para harangan ang ibang kotse","Manatili sa lane mo at huwag bumilis","Biglang magpreno para makapasok ang ibang kotse"],"h1":"Gawing madali at ligtas para sa ibang drayber ang pagtatapos ng paglampas.","h2":"Kapag may kotseng lumalampas sa iyo, dapat kang manatili sa lane mo at huwag bumilis, para ligtas na matapos ng ibang drayber ang paglampas.","p":"Tama. Kapag may lumalampas sa iyo, manatili sa lane mo at huwag bumilis."},"ar":{"q":"في Florida، سيارة أخرى تتجاوزك. ماذا يجب أن تفعل؟","o":["أسرع حتى لا تستطيع السيارة الأخرى أن تتجاوزني","أتحرك إلى اليسار لأمنع السيارة الأخرى","أبقى في مساري ولا أسرع","أضغط على الفرامل بقوة لأترك السيارة الأخرى تدخل"],"h1":"اجعل إنهاء التجاوز سهلًا وآمنًا للسائق الآخر.","h2":"عندما تتجاوزك سيارة أخرى، يجب أن تبقى في مسارك ولا تسرع، حتى يستطيع السائق الآخر أن ينهي التجاوز بأمان.","p":"صحيح. عندما يتجاوزك أحد، ابقَ في مسارك ولا تسرع."},"ht":{"q":"Nan Florida, yon lòt machin ap double ou. Kisa ou ta dwe fè?","o":["Akselere pou lòt machin nan pa ka double","Deplase sou bò gòch pou bloke lòt machin nan","Rete nan liy ou epi pa akselere","Peze fren an fò pou kite lòt machin nan antre"],"h1":"Fè li fasil epi san danje pou lòt chofè a fin double.","h2":"Lè yon lòt machin ap double ou, ou dwe rete nan liy ou epi pa akselere, pou lòt chofè a ka fin double san danje.","p":"Wi, se sa. Lè yon moun ap double ou, rete nan liy ou epi pa akselere."},"ref":{"doc":"FL","page":67}},{"id":"speed-lanes-017","scope":"US","cat":"speed-lanes","sign":{"shape":"no-passing","text":"NO PASSING ZONE"},"c":2,"en":{"q":"What does this yellow pennant-shaped sign mean?","o":["A school zone starts here","The road ends ahead","A no-passing zone starts here","You may pass on the right"],"h1":"This sign is on the left side of the road, where drivers look before they pass.","h2":"The yellow pennant sign marks the start of a no-passing zone, so you may not pass other cars from that point.","p":"Right. The pennant sign shows where a no-passing zone begins."},"es":{"q":"¿Qué significa este letrero amarillo en forma de banderín?","o":["Aquí empieza una zona escolar","La carretera termina más adelante","Aquí empieza una zona donde no se puede rebasar","Puede rebasar por la derecha"],"h1":"Este letrero está al lado izquierdo de la carretera, donde miran los conductores antes de rebasar.","h2":"El letrero amarillo en forma de banderín marca el inicio de una zona donde no se puede rebasar, así que desde allí no puede rebasar a otros carros.","p":"Correcto. El banderín muestra dónde empieza la zona sin rebase."},"zh":{"q":"这个黄色三角旗形的标志是什么意思？","o":["学校区从这里开始","前面道路到头了","禁止超车区从这里开始","你可以从右边超车"],"h1":"这个标志在道路的左边，就是司机超车前会看的地方。","h2":"黄色三角旗形标志表示禁止超车区的开始，所以从那里开始你不能超车。","p":"对。三角旗形标志表示禁止超车区从哪里开始。"},"vi":{"q":"Biển báo màu vàng hình cờ đuôi nheo này có nghĩa là gì?","o":["Khu vực trường học bắt đầu ở đây","Phía trước hết đường","Khu vực cấm vượt bắt đầu ở đây","Bạn được vượt bên phải"],"h1":"Biển này nằm ở bên trái đường, nơi người lái nhìn trước khi vượt.","h2":"Biển màu vàng hình cờ đuôi nheo đánh dấu nơi bắt đầu khu vực cấm vượt, nên từ điểm đó bạn không được vượt xe khác.","p":"Đúng. Biển hình cờ đuôi nheo cho biết nơi bắt đầu khu vực cấm vượt."},"tl":{"q":"Ano ang ibig sabihin ng dilaw na karatulang hugis pennant (mahabang tatsulok na bandila) na ito?","o":["Dito nagsisimula ang school zone","Nagtatapos ang daan sa unahan","Dito nagsisimula ang no-passing zone (bawal lumampas)","Puwede kang lumampas sa kanan"],"h1":"Nasa kaliwang gilid ng daan ang karatulang ito, kung saan tumitingin ang mga drayber bago lumampas.","h2":"Ang dilaw na pennant na karatula ay nagmamarka ng simula ng no-passing zone, kaya hindi ka puwedeng lumampas sa ibang kotse mula sa puntong iyon.","p":"Tama. Ipinapakita ng pennant na karatula kung saan nagsisimula ang no-passing zone."},"ar":{"q":"ماذا تعني هذه العلامة الصفراء التي على شكل راية مثلثة؟","o":["تبدأ منطقة مدرسة هنا","الطريق ينتهي أمامك","تبدأ منطقة ممنوع فيها التجاوز هنا","يمكنك أن تتجاوز من اليمين"],"h1":"هذه العلامة على الجانب الأيسر من الطريق، حيث ينظر السائقون قبل أن يتجاوزوا.","h2":"العلامة الصفراء التي على شكل راية تدل على بداية منطقة ممنوع فيها التجاوز، لذلك لا يجوز أن تتجاوز السيارات الأخرى من تلك النقطة.","p":"صحيح. علامة الراية تُظهر أين تبدأ منطقة ممنوع فيها التجاوز."},"ht":{"q":"Kisa siy jòn sa a ki gen fòm yon drapo pwenti (pennant) vle di?","o":["Yon zòn lekòl kòmanse la","Wout la fini devan","Yon zòn kote ou pa ka double kòmanse la","Ou ka double sou bò dwat"],"h1":"Siy sa a sou bò gòch wout la, kote chofè yo gade anvan yo double.","h2":"Siy jòn ki gen fòm drapo pwenti a make kote yon zòn ou pa ka double kòmanse, kidonk ou pa ka double lòt machin depi kote sa a.","p":"Wi, se sa. Siy drapo pwenti a montre kote yon zòn ou pa ka double kòmanse."},"ref":{"doc":"FL","page":48}},{"id":"speed-lanes-018","scope":"US","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"There is a solid yellow line on your side of the center line. What does it mean?","o":["You may not pass","You may pass when it is safe","The road is one-way","You must stop ahead"],"h1":"Look closely: is the line on your side broken or solid?","h2":"A solid yellow line on your side of the center means you may not cross it to pass other cars.","p":"Right. A solid yellow line on your side means no passing."},"es":{"q":"Hay una línea amarilla continua de su lado de la línea central. ¿Qué significa?","o":["No puede rebasar","Puede rebasar cuando sea seguro","La calle es de un solo sentido","Debe detenerse más adelante"],"h1":"Mire bien: ¿la línea de su lado es cortada o continua?","h2":"Una línea amarilla continua de su lado de la línea central significa que no puede cruzarla para rebasar a otros carros.","p":"Correcto. Una línea amarilla continua de su lado significa que no puede rebasar."},"zh":{"q":"在中心线你这一边有一条黄色实线。这是什么意思？","o":["你不能超车","安全时你可以超车","这条路是单行道","你前面必须停车"],"h1":"仔细看：你这一边的线是虚线还是实线？","h2":"中心线你这一边的黄色实线表示你不能越过它去超车。","p":"对。你这一边是黄色实线，表示不能超车。"},"vi":{"q":"Có một vạch vàng liền ở phía bên bạn của vạch giữa đường. Vạch đó có nghĩa là gì?","o":["Bạn không được vượt","Bạn được vượt khi an toàn","Đường này là đường một chiều","Bạn phải dừng ở phía trước"],"h1":"Hãy nhìn kỹ: vạch ở phía bên bạn là vạch đứt hay vạch liền?","h2":"Vạch vàng liền ở phía bên bạn của vạch giữa đường có nghĩa là bạn không được vượt qua vạch đó để vượt xe khác.","p":"Đúng. Vạch vàng liền ở phía bên bạn có nghĩa là cấm vượt."},"tl":{"q":"May tuloy-tuloy na dilaw na guhit sa panig mo ng center line (guhit sa gitna). Ano ang ibig sabihin nito?","o":["Bawal kang lumampas","Puwede kang lumampas kapag ligtas","One-way ang daan","Dapat kang huminto sa unahan"],"h1":"Tingnang mabuti: putol-putol ba o tuloy-tuloy ang guhit sa panig mo?","h2":"Ang tuloy-tuloy na dilaw na guhit sa panig mo ng gitna ay nangangahulugang hindi mo ito puwedeng tawirin para lumampas sa ibang kotse.","p":"Tama. Ang tuloy-tuloy na dilaw na guhit sa panig mo ay nangangahulugang bawal lumampas."},"ar":{"q":"يوجد خط أصفر متصل في جهتك من خط الوسط. ماذا يعني؟","o":["لا يجوز أن أتجاوز","يمكنني أن أتجاوز عندما يكون آمنًا","الطريق باتجاه واحد","يجب أن أتوقف أمامي"],"h1":"انظر جيدًا: هل الخط في جهتك متقطع أم متصل؟","h2":"الخط الأصفر المتصل في جهتك من خط الوسط يعني أنه لا يجوز أن تعبره لتتجاوز السيارات الأخرى.","p":"صحيح. الخط الأصفر المتصل في جهتك يعني ممنوع التجاوز."},"ht":{"q":"Gen yon liy jòn ki pa koupe sou bò pa w la nan liy mitan an. Kisa li vle di?","o":["Ou pa ka double","Ou ka double lè li pa danjere","Wout la se yon sèl sans","Ou dwe kanpe devan"],"h1":"Gade byen: èske liy ki sou bò pa w la koupe oswa li pa koupe?","h2":"Yon liy jòn ki pa koupe sou bò pa w la nan mitan wout la vle di ou pa ka travèse l pou double lòt machin.","p":"Wi, se sa. Yon liy jòn ki pa koupe sou bò pa w la vle di ou pa ka double."},"ref":{"doc":"FL","page":44}},{"id":"speed-lanes-019","scope":"FL","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Florida, how far before a turn must you start using your turn signal?","o":["At least 25 feet","At least 50 feet","Only when you begin to turn","At least 100 feet"],"h1":"Give other drivers enough warning before you move.","h2":"In Florida you must turn on your signal at least 100 feet before you turn, so other drivers know what you plan to do.","p":"Right. Signal at least 100 feet before you turn."},"es":{"q":"En Florida, ¿con cuánta anticipación debe poner la direccional antes de girar?","o":["Al menos 25 pies antes","Al menos 50 pies antes","Solo cuando empieza a girar","Al menos 100 pies antes"],"h1":"Avise a los demás conductores con suficiente tiempo antes de moverse.","h2":"En Florida debe poner la direccional al menos 100 pies antes de girar, para que los demás sepan lo que va a hacer.","p":"Correcto. Ponga la direccional al menos 100 pies antes de girar."},"zh":{"q":"在 Florida，转弯前多远必须开始打转向灯？","o":["至少 25 英尺","至少 50 英尺","只在开始转弯时","至少 100 英尺"],"h1":"在你移动之前，给其他司机足够的提醒。","h2":"在 Florida，你必须在转弯前至少 100 英尺打开转向灯，让其他司机知道你要做什么。","p":"对。转弯前至少 100 英尺打转向灯。"},"vi":{"q":"Ở Florida, bạn phải bắt đầu bật xi nhan bao xa trước khi rẽ?","o":["Ít nhất 25 feet","Ít nhất 50 feet","Chỉ khi bạn bắt đầu rẽ","Ít nhất 100 feet"],"h1":"Hãy báo trước đủ cho người lái khác trước khi bạn di chuyển.","h2":"Ở Florida, bạn phải bật xi nhan ít nhất 100 feet trước khi rẽ, để người lái khác biết bạn định làm gì.","p":"Đúng. Hãy bật xi nhan ít nhất 100 feet trước khi rẽ."},"tl":{"q":"Sa Florida, gaano kalayo bago lumiko dapat mong simulang gamitin ang turn signal mo?","o":["Hindi bababa sa 25 feet","Hindi bababa sa 50 feet","Kapag nagsisimula ka lang lumiko","Hindi bababa sa 100 feet"],"h1":"Bigyan ang ibang drayber ng sapat na babala bago ka gumalaw.","h2":"Sa Florida, dapat mong buksan ang signal mo nang hindi bababa sa 100 feet bago ka lumiko, para malaman ng ibang drayber ang balak mong gawin.","p":"Tama. Mag-signal nang hindi bababa sa 100 feet bago ka lumiko."},"ar":{"q":"في Florida، قبل الانعطاف بكم مسافة يجب أن تبدأ باستعمال إشارة الانعطاف؟","o":["25 قدمًا على الأقل","50 قدمًا على الأقل","فقط عندما أبدأ الانعطاف","100 قدم على الأقل"],"h1":"أعطِ السائقين الآخرين تحذيرًا كافيًا قبل أن تتحرك.","h2":"في Florida يجب أن تشغّل الإشارة قبل الانعطاف بمسافة 100 قدم على الأقل، حتى يعرف السائقون الآخرون ماذا تنوي أن تفعل.","p":"صحيح. شغّل الإشارة قبل الانعطاف بمسافة 100 قدم على الأقل."},"ht":{"q":"Nan Florida, a ki distans anvan yon vire ou dwe kòmanse mete siyal ou?","o":["Omwen 25 pye","Omwen 50 pye","Sèlman lè ou kòmanse vire","Omwen 100 pye"],"h1":"Bay lòt chofè yo ase tan pou yo konnen anvan ou deplase.","h2":"Nan Florida ou dwe limen siyal ou omwen 100 pye anvan ou vire, pou lòt chofè yo konnen sa ou vle fè.","p":"Wi, se sa. Mete siyal omwen 100 pye anvan ou vire."},"ref":{"doc":"FL","page":69}},{"id":"speed-lanes-020","scope":"US","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"You want to change lanes. What should you do right after checking your mirrors?","o":["Change lanes right away","Turn your head and look over your shoulder","Honk your horn","Slow down to a stop"],"h1":"Your mirrors cannot show every place next to your car.","h2":"After you check your mirrors, turn your head and look over your shoulder, because a car may be hiding in your blind spot.","p":"Right. Look over your shoulder to check your blind spot."},"es":{"q":"Quiere cambiar de carril. ¿Qué debe hacer justo después de revisar los espejos?","o":["Cambiar de carril enseguida","Voltear la cabeza y mirar por encima del hombro","Tocar la bocina","Frenar hasta detenerse"],"h1":"Los espejos no muestran todos los lugares al lado de su carro.","h2":"Después de revisar los espejos, voltee la cabeza y mire por encima del hombro, porque puede haber un carro escondido en su punto ciego.","p":"Correcto. Mire por encima del hombro para revisar su punto ciego."},"zh":{"q":"你想换车道。看完后视镜以后，紧接着应该做什么？","o":["马上换道","转头，从肩膀上方往后看","按喇叭","减速停下"],"h1":"后视镜不能照到你车旁边的每个地方。","h2":"看完后视镜后，要转头从肩膀上方往后看，因为可能有车藏在你的盲区里。","p":"对。转头往后看，检查你的盲区。"},"vi":{"q":"Bạn muốn đổi làn. Ngay sau khi nhìn gương, bạn nên làm gì?","o":["Đổi làn ngay","Quay đầu và nhìn qua vai","Bấm còi","Giảm tốc cho đến khi dừng"],"h1":"Gương của bạn không thể cho thấy mọi chỗ bên cạnh xe.","h2":"Sau khi nhìn gương, bạn quay đầu và nhìn qua vai, vì có thể có xe đang khuất trong điểm mù của bạn.","p":"Đúng. Hãy nhìn qua vai để kiểm tra điểm mù."},"tl":{"q":"Gusto mong lumipat ng lane. Ano ang dapat mong gawin pagkatapos tumingin sa mga salamin mo?","o":["Lumipat agad ng lane","Ilingon ang ulo mo at tumingin sa likod ng balikat mo","Bumusina","Bumagal hanggang huminto"],"h1":"Hindi kayang ipakita ng mga salamin mo ang bawat lugar sa tabi ng kotse mo.","h2":"Pagkatapos mong tumingin sa mga salamin, ilingon ang ulo mo at tumingin sa likod ng balikat mo, dahil maaaring may kotseng nakatago sa blind spot mo.","p":"Tama. Tumingin sa likod ng balikat mo para suriin ang blind spot mo."},"ar":{"q":"تريد أن تغيّر المسار. ماذا يجب أن تفعل مباشرة بعد أن تنظر في المرايا؟","o":["أغيّر المسار فورًا","أدير رأسي وأنظر من فوق كتفي","أستعمل البوق","أخفف السرعة حتى أتوقف"],"h1":"المرايا لا تستطيع أن تُظهر كل مكان بجانب سيارتك.","h2":"بعد أن تنظر في المرايا، أدر رأسك وانظر من فوق كتفك، لأن سيارة قد تكون مختبئة في النقطة العمياء.","p":"صحيح. انظر من فوق كتفك لتفحص النقطة العمياء."},"ht":{"q":"Ou vle chanje liy. Kisa ou ta dwe fè touswit apre ou fin tcheke retwovizè ou yo?","o":["Chanje liy touswit","Vire tèt ou epi gade pa dèyè zepòl ou","Klaksonnen","Ralanti jiskaske ou kanpe"],"h1":"Retwovizè ou yo pa ka montre tout kote ki bò kote machin ou.","h2":"Apre ou fin tcheke retwovizè ou yo, vire tèt ou epi gade pa dèyè zepòl ou, paske yon machin ka kache nan kwen ou pa wè a.","p":"Wi, se sa. Gade pa dèyè zepòl ou pou tcheke kwen ou pa wè a."},"ref":{"doc":"FL","page":60}},{"id":"speed-lanes-021","scope":"US","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"You need to move over three lanes to reach your exit. How should you do it?","o":["Cross all three lanes in one move","Move one lane at a time and signal each time","Signal once and then cross all lanes","Slow down in your lane and wait for a gap in all lanes"],"h1":"Each lane may have its own traffic and its own blind spot.","h2":"You should move one lane at a time, signaling and checking your blind spot before each move, because every lane can hide a car.","p":"Right. Change one lane at a time and signal each time."},"es":{"q":"Necesita pasar tres carriles para llegar a su salida. ¿Cómo debe hacerlo?","o":["Cruzar los tres carriles de una sola vez","Cambiar un carril a la vez y poner la direccional cada vez","Poner la direccional una vez y cruzar todos los carriles","Frenar en su carril y esperar un espacio en todos los carriles"],"h1":"Cada carril puede tener su propio tráfico y su propio punto ciego.","h2":"Debe cambiar un carril a la vez, poniendo la direccional y revisando el punto ciego antes de cada cambio, porque en cada carril puede haber un carro.","p":"Correcto. Cambie un carril a la vez y ponga la direccional cada vez."},"zh":{"q":"你要跨过三条车道才能到你的出口。你应该怎么做？","o":["一次跨过全部三条车道","一次换一条车道，每次都打转向灯","打一次转向灯，然后跨过所有车道","在你的车道里减速，等所有车道都有空隙"],"h1":"每条车道都可能有自己的车，也有自己的盲区。","h2":"你应该一次换一条车道，每次换道前都打转向灯、检查盲区，因为每条车道都可能藏着一辆车。","p":"对。一次换一条车道，每次都打转向灯。"},"vi":{"q":"Bạn cần chuyển qua ba làn để đến lối ra. Bạn nên làm thế nào?","o":["Chuyển qua cả ba làn một lần","Chuyển từng làn một và bật xi nhan mỗi lần","Bật xi nhan một lần rồi chuyển qua tất cả các làn","Giảm tốc trong làn của bạn và chờ khoảng trống ở tất cả các làn"],"h1":"Mỗi làn có thể có xe riêng và điểm mù riêng.","h2":"Bạn nên chuyển từng làn một, bật xi nhan và kiểm tra điểm mù trước mỗi lần chuyển, vì làn nào cũng có thể có xe bị khuất.","p":"Đúng. Hãy đổi từng làn một và bật xi nhan mỗi lần."},"tl":{"q":"Kailangan mong lumipat nang tatlong lane para marating ang exit mo. Paano mo ito dapat gawin?","o":["Tawirin ang tatlong lane sa isang galaw","Lumipat nang isang lane sa bawat pagkakataon at mag-signal bawat beses","Mag-signal nang isang beses at saka tawirin ang lahat ng lane","Bumagal sa lane mo at maghintay ng puwang sa lahat ng lane"],"h1":"Bawat lane ay maaaring may sariling trapiko at sariling blind spot.","h2":"Dapat kang lumipat nang isang lane sa bawat pagkakataon, nagsi-signal at sumusuri sa blind spot bago ang bawat paglipat, dahil bawat lane ay maaaring may nakatagong kotse.","p":"Tama. Lumipat nang isang lane sa bawat pagkakataon at mag-signal bawat beses."},"ar":{"q":"تحتاج إلى أن تنتقل ثلاثة مسارات لتصل إلى المخرج. كيف تفعل ذلك؟","o":["أعبر المسارات الثلاثة في حركة واحدة","أنتقل مسارًا واحدًا في كل مرة وأشغّل الإشارة كل مرة","أشغّل الإشارة مرة واحدة ثم أعبر كل المسارات","أخفف السرعة في مساري وأنتظر فجوة في كل المسارات"],"h1":"كل مسار قد تكون فيه سيارات خاصة به ونقطة عمياء خاصة به.","h2":"يجب أن تنتقل مسارًا واحدًا في كل مرة، وأن تشغّل الإشارة وتفحص النقطة العمياء قبل كل انتقال، لأن كل مسار قد تختبئ فيه سيارة.","p":"صحيح. غيّر مسارًا واحدًا في كل مرة وشغّل الإشارة كل مرة."},"ht":{"q":"Ou bezwen travèse twa liy pou rive nan sòti ou a. Kijan ou ta dwe fè l?","o":["Travèse twa liy yo yon sèl kou","Chanje yon liy alafwa epi mete siyal chak fwa","Mete siyal yon sèl fwa epi travèse tout liy yo","Ralanti nan liy ou epi tann yon espas nan tout liy yo"],"h1":"Chak liy ka gen pwòp machin pa l ak pwòp kwen ou pa wè.","h2":"Ou ta dwe chanje yon liy alafwa, mete siyal epi tcheke kwen ou pa wè a anvan chak chanjman, paske chak liy ka kache yon machin.","p":"Wi, se sa. Chanje yon liy alafwa epi mete siyal chak fwa."}},{"id":"speed-lanes-022","scope":"US","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"What do broken white lines between lanes mean?","o":["They separate traffic going in opposite directions","You may never cross them","They mark the edge of the road","They separate lanes going the same way, and you may change lanes when safe"],"h1":"Broken lines allow you to do something, but only when it is safe.","h2":"Broken white lines separate lanes that go the same way, and you may cross them to change lanes when it is safe.","p":"Right. Broken white lines let you change lanes when it is safe."},"es":{"q":"¿Qué significan las líneas blancas cortadas entre carriles?","o":["Separan el tráfico que va en sentidos opuestos","Nunca las puede cruzar","Marcan la orilla de la carretera","Separan carriles que van en el mismo sentido, y puede cambiar de carril cuando sea seguro"],"h1":"Las líneas cortadas le permiten hacer algo, pero solo cuando es seguro.","h2":"Las líneas blancas cortadas separan carriles que van en el mismo sentido, y puede cruzarlas para cambiar de carril cuando sea seguro.","p":"Correcto. Las líneas blancas cortadas le permiten cambiar de carril cuando es seguro."},"zh":{"q":"车道之间的白色虚线是什么意思？","o":["它们分开相反方向行驶的车","你永远不能越过它们","它们标出道路的边缘","它们分开同方向的车道，安全时你可以换道"],"h1":"虚线允许你做某件事，但只能在安全的时候。","h2":"白色虚线分开同方向的车道，安全时你可以越过它们换道。","p":"对。白色虚线表示安全时可以换道。"},"vi":{"q":"Vạch trắng đứt quãng giữa các làn có nghĩa là gì?","o":["Chúng tách các xe đi ngược chiều nhau","Bạn không bao giờ được đi qua chúng","Chúng đánh dấu mép đường","Chúng tách các làn cùng chiều, và bạn được đổi làn khi an toàn"],"h1":"Vạch đứt cho phép bạn làm một việc, nhưng chỉ khi an toàn.","h2":"Vạch trắng đứt quãng tách các làn cùng chiều, và bạn được đi qua chúng để đổi làn khi an toàn.","p":"Đúng. Vạch trắng đứt quãng cho phép bạn đổi làn khi an toàn."},"tl":{"q":"Ano ang ibig sabihin ng putol-putol na puting guhit sa pagitan ng mga lane?","o":["Pinaghihiwalay nito ang trapikong magkasalungat ang direksiyon","Hindi mo ito kailanman puwedeng tawirin","Minamarkahan nito ang gilid ng daan","Pinaghihiwalay nito ang mga lane na pareho ang direksiyon, at puwede kang lumipat ng lane kapag ligtas"],"h1":"Pinapayagan ka ng putol-putol na guhit na gumawa ng isang bagay, pero kapag ligtas lang.","h2":"Pinaghihiwalay ng putol-putol na puting guhit ang mga lane na pareho ang direksiyon, at puwede mo itong tawirin para lumipat ng lane kapag ligtas.","p":"Tama. Pinapayagan ka ng putol-putol na puting guhit na lumipat ng lane kapag ligtas."},"ar":{"q":"ماذا تعني الخطوط البيضاء المتقطعة بين المسارات؟","o":["تفصل بين سيارات تسير في اتجاهين متعاكسين","لا يجوز أبدًا أن أعبرها","تحدد طرف الطريق","تفصل بين مسارات في الاتجاه نفسه، ويمكنني أن أغيّر المسار عندما يكون آمنًا"],"h1":"الخطوط المتقطعة تسمح لك بشيء، لكن فقط عندما يكون آمنًا.","h2":"الخطوط البيضاء المتقطعة تفصل بين مسارات تسير في الاتجاه نفسه، ويمكنك أن تعبرها لتغيّر المسار عندما يكون ذلك آمنًا.","p":"صحيح. الخطوط البيضاء المتقطعة تسمح لك بتغيير المسار عندما يكون آمنًا."},"ht":{"q":"Kisa liy blan ki koupe ant liy yo vle di?","o":["Yo separe machin k ap ale nan direksyon opoze","Ou pa janm ka travèse yo","Yo make bò wout la","Yo separe liy k ap ale nan menm direksyon, epi ou ka chanje liy lè li pa danjere"],"h1":"Liy ki koupe pèmèt ou fè yon bagay, men sèlman lè li pa danjere.","h2":"Liy blan ki koupe yo separe liy k ap ale nan menm direksyon, epi ou ka travèse yo pou chanje liy lè li pa danjere.","p":"Wi, se sa. Liy blan ki koupe yo pèmèt ou chanje liy lè li pa danjere."},"ref":{"doc":"FL","page":43}},{"id":"speed-lanes-023","scope":"FL","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Florida, you are on the ramp to enter an expressway. What should you do?","o":["Speed up in the merge lane to match traffic and yield to cars on the expressway","Stop at the end of the ramp and wait","Drive slowly so cars on the expressway can see you","Enter right away, because cars on the expressway must let you in"],"h1":"The merge lane is there to help you reach the speed of traffic.","h2":"Use the merge lane to speed up to the speed of traffic, and yield to the cars already on the expressway before you move in.","p":"Right. Match the traffic speed and yield to cars already on the expressway."},"es":{"q":"En Florida, usted va por la rampa para entrar a una autopista. ¿Qué debe hacer?","o":["Acelerar en el carril de incorporación hasta la velocidad del tráfico y ceder el paso a los carros de la autopista","Detenerse al final de la rampa y esperar","Manejar despacio para que los carros de la autopista lo vean","Entrar enseguida, porque los carros de la autopista deben dejarlo pasar"],"h1":"El carril de incorporación sirve para que alcance la velocidad del tráfico.","h2":"Use el carril de incorporación para acelerar hasta la velocidad del tráfico, y ceda el paso a los carros que ya van por la autopista antes de entrar.","p":"Correcto. Iguale la velocidad del tráfico y ceda el paso a los carros de la autopista."},"zh":{"q":"在 Florida，你在进入快速路的匝道上。你应该怎么做？","o":["在并道车道上加速，跟上车流速度，并让快速路上的车先走","在匝道尽头停下等","慢慢开，让快速路上的车能看到你","马上开进去，因为快速路上的车必须让你进去"],"h1":"并道车道是用来帮你达到车流速度的。","h2":"利用并道车道加速到车流的速度，并在并入之前让已经在快速路上的车先走。","p":"对。跟上车流速度，并让已经在快速路上的车先走。"},"vi":{"q":"Ở Florida, bạn đang ở trên đường dẫn để vào đường cao tốc. Bạn nên làm gì?","o":["Tăng tốc trong làn nhập để bằng tốc độ dòng xe và nhường xe trên đường cao tốc","Dừng ở cuối đường dẫn và chờ","Chạy chậm để xe trên đường cao tốc thấy bạn","Vào ngay, vì xe trên đường cao tốc phải cho bạn vào"],"h1":"Làn nhập có để giúp bạn đạt tốc độ của dòng xe.","h2":"Hãy dùng làn nhập để tăng tốc bằng tốc độ dòng xe, và nhường xe đã ở trên đường cao tốc trước khi bạn nhập vào.","p":"Đúng. Hãy chạy bằng tốc độ dòng xe và nhường xe đã ở trên đường cao tốc."},"tl":{"q":"Sa Florida, nasa ramp ka papasok sa expressway. Ano ang dapat mong gawin?","o":["Bumilis sa merge lane para tumugma sa trapiko at magbigay-daan sa mga kotse sa expressway","Huminto sa dulo ng ramp at maghintay","Magmaneho nang mabagal para makita ka ng mga kotse sa expressway","Pumasok agad, dahil dapat kang papasukin ng mga kotse sa expressway"],"h1":"Nariyan ang merge lane para tulungan kang maabot ang bilis ng trapiko.","h2":"Gamitin ang merge lane para bumilis hanggang sa bilis ng trapiko, at magbigay-daan sa mga kotseng nasa expressway na bago ka pumasok.","p":"Tama. Itugma ang bilis mo sa trapiko at magbigay-daan sa mga kotseng nasa expressway na."},"ar":{"q":"في Florida، أنت على منحدر الدخول إلى طريق سريع (expressway). ماذا يجب أن تفعل؟","o":["أسرع في مسار الاندماج لأصل إلى سرعة السير، وأعطي حق المرور للسيارات على الطريق السريع","أتوقف في آخر المنحدر وأنتظر","أقود ببطء حتى تراني السيارات على الطريق السريع","أدخل فورًا، لأن السيارات على الطريق السريع يجب أن تتركني أدخل"],"h1":"مسار الاندماج موجود ليساعدك على الوصول إلى سرعة السير.","h2":"استعمل مسار الاندماج لتزيد سرعتك حتى تصل إلى سرعة السير، وأعطِ حق المرور للسيارات الموجودة على الطريق السريع قبل أن تدخل.","p":"صحيح. اجعل سرعتك مثل سرعة السير وأعطِ حق المرور للسيارات الموجودة على الطريق السريع."},"ht":{"q":"Nan Florida, ou sou ranp lan pou antre sou yon otowout. Kisa ou ta dwe fè?","o":["Akselere nan liy pou antre a pou ou rive nan vitès machin yo epi kite machin ki sou otowout la pase anvan","Kanpe nan bout ranp lan epi tann","Kondi dousman pou machin ki sou otowout la ka wè ou","Antre touswit, paske machin ki sou otowout la dwe kite ou antre"],"h1":"Liy pou antre a la pou ede ou rive nan vitès machin yo.","h2":"Sèvi ak liy pou antre a pou ou akselere jiskaske ou rive nan vitès machin yo, epi kite machin ki deja sou otowout la pase anvan ou antre.","p":"Wi, se sa. Rive nan vitès machin yo epi kite machin ki deja sou otowout la pase anvan."},"ref":{"doc":"FL","page":63}},{"id":"speed-lanes-024","scope":"FL","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Florida, where should you slow down when you leave an expressway?","o":["In the main lane, before the exit","On the shoulder next to the exit","In the exit lane, after you leave the main lanes","Only after you reach the end of the ramp"],"h1":"Slowing down in the main lanes can surprise the drivers behind you.","h2":"You should move into the exit lane first and then slow down there, so you do not block fast traffic in the main lanes.","p":"Right. Slow down in the exit lane, not on the main road."},"es":{"q":"En Florida, ¿dónde debe bajar la velocidad al salir de una autopista?","o":["En el carril principal, antes de la salida","En el acotamiento junto a la salida","En el carril de salida, después de dejar los carriles principales","Solo al llegar al final de la rampa"],"h1":"Frenar en los carriles principales puede sorprender a los conductores de atrás.","h2":"Primero debe pasarse al carril de salida y luego bajar la velocidad allí, para no frenar al tráfico rápido en los carriles principales.","p":"Correcto. Baje la velocidad en el carril de salida, no en la vía principal."},"zh":{"q":"在 Florida，离开快速路时，你应该在哪里减速？","o":["在主车道上，出口之前","在出口旁边的路肩上","在出口车道上，离开主车道以后","只有到了匝道尽头以后"],"h1":"在主车道上减速可能会让后面的司机措手不及。","h2":"你应该先进入出口车道，然后在那里减速，这样就不会挡住主车道上开得快的车。","p":"对。在出口车道减速，不要在主路上减速。"},"vi":{"q":"Ở Florida, bạn nên giảm tốc ở đâu khi rời khỏi đường cao tốc?","o":["Trong làn chính, trước lối ra","Trên lề cạnh lối ra","Trong làn ra, sau khi bạn rời khỏi các làn chính","Chỉ sau khi bạn đến cuối đường dẫn"],"h1":"Giảm tốc trong các làn chính có thể làm người lái phía sau bất ngờ.","h2":"Bạn nên vào làn ra trước rồi mới giảm tốc ở đó, để không cản trở dòng xe chạy nhanh trong các làn chính.","p":"Đúng. Hãy giảm tốc trong làn ra, không phải trên đường chính."},"tl":{"q":"Sa Florida, saan ka dapat bumagal kapag lalabas ka sa expressway?","o":["Sa pangunahing lane, bago ang exit","Sa shoulder sa tabi ng exit","Sa exit lane, pagkaalis mo sa mga pangunahing lane","Pagdating mo lang sa dulo ng ramp"],"h1":"Ang pagbagal sa mga pangunahing lane ay maaaring makagulat sa mga drayber sa likod mo.","h2":"Dapat ka munang lumipat sa exit lane at saka bumagal doon, para hindi mo maharangan ang mabilis na trapiko sa mga pangunahing lane.","p":"Tama. Bumagal sa exit lane, hindi sa pangunahing daan."},"ar":{"q":"في Florida، أين يجب أن تخفف السرعة عندما تخرج من الطريق السريع (expressway)؟","o":["في المسار الرئيسي، قبل المخرج","على كتف الطريق بجانب المخرج","في مسار الخروج، بعد أن أترك المسارات الرئيسية","فقط بعد أن أصل إلى آخر المنحدر"],"h1":"إذا خففت السرعة في المسارات الرئيسية، قد تفاجئ السائقين الذين خلفك.","h2":"يجب أن تدخل مسار الخروج أولًا ثم تخفف السرعة فيه، حتى لا تعيق السيارات السريعة في المسارات الرئيسية.","p":"صحيح. خفف السرعة في مسار الخروج، وليس على الطريق الرئيسي."},"ht":{"q":"Nan Florida, ki kote ou ta dwe ralanti lè w ap sòti sou yon otowout?","o":["Nan liy prensipal la, anvan sòti a","Sou bò wout la, bò kote sòti a","Nan liy sòti a, apre ou fin kite liy prensipal yo","Sèlman apre ou rive nan bout ranp lan"],"h1":"Si ou ralanti nan liy prensipal yo, ou ka sezi chofè ki dèyè ou yo.","h2":"Ou ta dwe antre nan liy sòti a anvan, epi ralanti la, pou ou pa bloke machin k ap kouri vit nan liy prensipal yo.","p":"Wi, se sa. Ralanti nan liy sòti a, pa sou wout prensipal la."},"ref":{"doc":"FL","page":64}},{"id":"speed-lanes-025","scope":"US","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"You missed your exit on the expressway. What should you do?","o":["Back up on the shoulder to the exit","Make a U-turn across the median","Keep going to the next exit","Stop and wait for traffic to clear"],"h1":"Backing up or turning around on a fast road is very dangerous.","h2":"If you miss your exit, keep driving to the next exit, because backing up or turning around on an expressway can cause a serious crash.","p":"Right. Missed your exit? Just go on to the next one."},"es":{"q":"Se le pasó la salida en la autopista. ¿Qué debe hacer?","o":["Dar reversa por el acotamiento hasta la salida","Dar vuelta en U por la división central","Seguir hasta la próxima salida","Detenerse y esperar a que pase el tráfico"],"h1":"Dar reversa o dar la vuelta en una vía rápida es muy peligroso.","h2":"Si se le pasa la salida, siga hasta la próxima salida, porque dar reversa o dar la vuelta en una autopista puede causar un choque grave.","p":"Correcto. ¿Se le pasó la salida? Siga hasta la próxima."},"zh":{"q":"你在快速路上错过了出口。你应该怎么做？","o":["在路肩上倒车回到出口","穿过中间隔离带掉头","继续开到下一个出口","停下来，等车流过去"],"h1":"在快速道路上倒车或掉头非常危险。","h2":"如果你错过了出口，就继续开到下一个出口，因为在快速路上倒车或掉头可能会造成严重车祸。","p":"对。错过出口了？就开到下一个出口。"},"vi":{"q":"Bạn đã đi lố lối ra trên đường cao tốc. Bạn nên làm gì?","o":["Lùi xe trên lề về lối ra","Quay đầu chữ U qua dải phân cách","Chạy tiếp đến lối ra kế tiếp","Dừng lại và chờ hết xe"],"h1":"Lùi xe hoặc quay đầu trên đường chạy nhanh là rất nguy hiểm.","h2":"Nếu bạn đi lố lối ra, hãy chạy tiếp đến lối ra kế tiếp, vì lùi xe hoặc quay đầu trên đường cao tốc có thể gây tai nạn nghiêm trọng.","p":"Đúng. Đi lố lối ra? Cứ chạy đến lối ra kế tiếp."},"tl":{"q":"Nalampasan mo ang exit mo sa expressway. Ano ang dapat mong gawin?","o":["Umatras sa shoulder papunta sa exit","Mag-U-turn sa kabila ng median","Magpatuloy hanggang sa susunod na exit","Huminto at hintaying lumuwag ang trapiko"],"h1":"Napakadelikado ang pag-atras o pag-ikot pabalik sa mabilis na daan.","h2":"Kung nalampasan mo ang exit mo, magpatuloy hanggang sa susunod na exit, dahil ang pag-atras o pag-ikot pabalik sa expressway ay maaaring magdulot ng malubhang banggaan.","p":"Tama. Nalampasan ang exit? Magpatuloy lang sa susunod."},"ar":{"q":"فاتك المخرج على الطريق السريع. ماذا يجب أن تفعل؟","o":["أرجع إلى الخلف على كتف الطريق حتى المخرج","أقوم بدوران كامل للخلف (U-turn) عبر الفاصل في الوسط","أستمر حتى المخرج التالي","أتوقف وأنتظر حتى يصبح الطريق فارغًا"],"h1":"الرجوع إلى الخلف أو الدوران على طريق سريع خطير جدًا.","h2":"إذا فاتك المخرج، استمر في القيادة حتى المخرج التالي، لأن الرجوع إلى الخلف أو الدوران على الطريق السريع قد يسبب حادثًا خطيرًا.","p":"صحيح. فاتك المخرج؟ استمر ببساطة إلى المخرج التالي."},"ht":{"q":"Ou rate sòti ou a sou otowout la. Kisa ou ta dwe fè?","o":["Fè bak sou bò wout la jis rive nan sòti a","Fè demi-tou atravè separasyon ki nan mitan an","Kontinye jis rive nan pwochen sòti a","Kanpe epi tann sikilasyon an vin lib"],"h1":"Fè bak oswa fè demi-tou sou yon wout rapid trè danjere.","h2":"Si ou rate sòti ou a, kontinye kondi jis rive nan pwochen sòti a, paske fè bak oswa fè demi-tou sou yon otowout ka lakòz yon gwo aksidan.","p":"Wi, se sa. Ou rate sòti ou a? Kontinye jis nan pwochen an."},"ref":{"doc":"FL","page":64}},{"id":"speed-lanes-026","scope":"FL","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Florida, a ramp has a traffic signal (ramp meter) before the expressway. How do you use it?","o":["Wait for green, then one car goes on each green light","All cars in line go on one green light","Ignore it if the expressway looks empty","Go on yellow, stop on green"],"h1":"The signal lets cars onto the expressway a little at a time.","h2":"At a ramp meter, wait for the green light, and then only one car goes for each green unless a sign says otherwise.","p":"Right. At a ramp meter, one car goes on each green light."},"es":{"q":"En Florida, una rampa tiene un semáforo (medidor de rampa) antes de la autopista. ¿Cómo se usa?","o":["Espere la luz verde; pasa un carro con cada luz verde","Todos los carros de la fila pasan con una sola luz verde","Ignórelo si la autopista se ve vacía","Pase con luz amarilla y deténgase con luz verde"],"h1":"El semáforo deja entrar los carros a la autopista poco a poco.","h2":"En un medidor de rampa, espere la luz verde, y luego pasa solo un carro con cada luz verde, a menos que un letrero diga otra cosa.","p":"Correcto. En el medidor de rampa, pasa un carro con cada luz verde."},"zh":{"q":"在 Florida，一条匝道在进入快速路前有一个交通信号灯（匝道信号灯）。你该怎么用它？","o":["等绿灯，每次绿灯走一辆车","排队的所有车在一次绿灯时一起走","如果快速路看起来没车，就不用管它","黄灯走，绿灯停"],"h1":"这个信号灯让车一点一点地进入快速路。","h2":"在匝道信号灯前，要等绿灯，除非有标志另外规定，每次绿灯只走一辆车。","p":"对。在匝道信号灯前，每次绿灯走一辆车。"},"vi":{"q":"Ở Florida, một đường dẫn có đèn giao thông (đèn điều tiết) trước khi vào đường cao tốc. Bạn dùng đèn này thế nào?","o":["Chờ đèn xanh, rồi mỗi lần đèn xanh thì một xe đi","Tất cả các xe đang xếp hàng đi trong một lần đèn xanh","Bỏ qua nếu đường cao tốc trông vắng","Đi khi đèn vàng, dừng khi đèn xanh"],"h1":"Đèn này cho xe vào đường cao tốc từng chút một.","h2":"Tại đèn điều tiết, hãy chờ đèn xanh, và mỗi lần đèn xanh chỉ có một xe đi, trừ khi biển báo nói khác.","p":"Đúng. Tại đèn điều tiết, mỗi lần đèn xanh một xe đi."},"tl":{"q":"Sa Florida, may ilaw trapiko (ramp meter) ang ramp bago ang expressway. Paano mo ito gagamitin?","o":["Hintayin ang berde, at isang kotse ang aandar sa bawat berdeng ilaw","Aandar ang lahat ng kotse sa pila sa isang berdeng ilaw","Huwag pansinin kung mukhang walang laman ang expressway","Umandar sa dilaw, huminto sa berde"],"h1":"Pinapapasok ng ilaw ang mga kotse sa expressway nang paisa-isa.","h2":"Sa ramp meter, hintayin ang berdeng ilaw, at isang kotse lang ang aandar sa bawat berde maliban kung may karatulang nagsasabi ng iba.","p":"Tama. Sa ramp meter, isang kotse ang aandar sa bawat berdeng ilaw."},"ar":{"q":"في Florida، على منحدر الدخول توجد إشارة ضوئية (ramp meter) قبل الطريق السريع. كيف تستعملها؟","o":["أنتظر الضوء الأخضر، ثم تمر سيارة واحدة مع كل ضوء أخضر","كل السيارات في الطابور تمر مع ضوء أخضر واحد","أتجاهلها إذا كان الطريق السريع يبدو فارغًا","أتحرك مع الأصفر، وأتوقف مع الأخضر"],"h1":"هذه الإشارة تُدخل السيارات إلى الطريق السريع قليلًا قليلًا.","h2":"عند إشارة ramp meter، انتظر الضوء الأخضر، ثم تمر سيارة واحدة فقط مع كل ضوء أخضر، إلا إذا قالت علامة غير ذلك.","p":"صحيح. عند إشارة ramp meter، تمر سيارة واحدة مع كل ضوء أخضر."},"ht":{"q":"Nan Florida, yon ranp gen yon limyè (ramp meter) anvan otowout la. Kijan ou sèvi ak li?","o":["Tann limyè vèt la, epi yon sèl machin pase chak fwa limyè a vin vèt","Tout machin ki nan liy lan pase sou yon sèl limyè vèt","Pa okipe l si otowout la sanble vid","Pase sou limyè jòn, kanpe sou limyè vèt"],"h1":"Limyè a kite machin yo antre sou otowout la ti kras pa ti kras.","h2":"Nan yon limyè sou ranp, tann limyè vèt la, epi se yon sèl machin ki pase pou chak limyè vèt, sòf si yon siy di lòt bagay.","p":"Wi, se sa. Nan yon limyè sou ranp, yon sèl machin pase pou chak limyè vèt."},"ref":{"doc":"FL","page":53}},{"id":"speed-lanes-027","scope":"FL","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Florida, you are in the left lane of a multi-lane highway. A faster car comes up behind you. What must you do?","o":["Stay in the left lane at the speed limit","Speed up to stay ahead of it","Tap your brakes to slow it down","Move to the right when it is safe and let it pass"],"h1":"On a highway with several lanes, the left lane is mainly for passing.","h2":"Florida law says that if a faster car is coming up behind you in the left lane, you must move right when it is safe and let it pass.","p":"Right. In the left lane, move right for faster traffic behind you."},"es":{"q":"En Florida, usted va por el carril izquierdo de una carretera de varios carriles. Un carro más rápido se acerca por detrás. ¿Qué debe hacer?","o":["Quedarse en el carril izquierdo al límite de velocidad","Acelerar para seguir delante de él","Frenar un poco para que baje la velocidad","Pasarse a la derecha cuando sea seguro y dejarlo pasar"],"h1":"En una carretera de varios carriles, el carril izquierdo es sobre todo para rebasar.","h2":"La ley de Florida dice que si un carro más rápido se acerca por detrás en el carril izquierdo, debe pasarse a la derecha cuando sea seguro y dejarlo pasar.","p":"Correcto. En el carril izquierdo, muévase a la derecha si viene alguien más rápido."},"zh":{"q":"在 Florida，你在多车道公路的左边车道。一辆更快的车从你后面开过来。你必须怎么做？","o":["以限速留在左边车道","加速，保持在它前面","点一下刹车，让它慢下来","在安全时移到右边，让它超过去"],"h1":"在有好几条车道的公路上，左边车道主要是用来超车的。","h2":"Florida 法律规定，如果在左边车道有一辆更快的车从你后面开过来，你必须在安全时移到右边，让它超过去。","p":"对。在左边车道时，要给后面更快的车让到右边。"},"vi":{"q":"Ở Florida, bạn đang ở làn trái của xa lộ nhiều làn. Một xe nhanh hơn đến phía sau bạn. Bạn phải làm gì?","o":["Ở lại làn trái và chạy đúng giới hạn tốc độ","Tăng tốc để chạy trước xe đó","Đạp nhẹ phanh để xe đó chậm lại","Chuyển sang phải khi an toàn và để xe đó vượt"],"h1":"Trên xa lộ có nhiều làn, làn trái chủ yếu dùng để vượt.","h2":"Luật Florida nói nếu có xe nhanh hơn đến phía sau bạn ở làn trái, bạn phải chuyển sang phải khi an toàn và để xe đó vượt.","p":"Đúng. Ở làn trái, hãy chuyển sang phải cho xe nhanh hơn phía sau."},"tl":{"q":"Sa Florida, nasa kaliwang lane ka ng highway na maraming lane. May mas mabilis na kotseng paparating sa likod mo. Ano ang dapat mong gawin?","o":["Manatili sa kaliwang lane sa speed limit","Bumilis para manatiling nauuna rito","Tapik-tapikin ang preno para pabagalin ito","Lumipat pakanan kapag ligtas at hayaan itong lumampas"],"h1":"Sa highway na maraming lane, ang kaliwang lane ay pangunahing para sa paglampas.","h2":"Sinasabi ng batas ng Florida na kung may mas mabilis na kotseng paparating sa likod mo sa kaliwang lane, dapat kang lumipat pakanan kapag ligtas at hayaan itong lumampas.","p":"Tama. Sa kaliwang lane, lumipat pakanan para sa mas mabilis na trapiko sa likod mo."},"ar":{"q":"في Florida، أنت في المسار الأيسر على طريق سريع فيه عدة مسارات. سيارة أسرع تقترب من خلفك. ماذا يجب أن تفعل؟","o":["أبقى في المسار الأيسر بسرعة الحد","أسرع لأبقى أمامها","أضغط على الفرامل قليلًا لأجعلها تبطئ","أنتقل إلى اليمين عندما يكون آمنًا وأتركها تتجاوزني"],"h1":"على طريق سريع فيه عدة مسارات، المسار الأيسر هو أساسًا للتجاوز.","h2":"يقول قانون Florida إنه إذا اقتربت سيارة أسرع من خلفك في المسار الأيسر، يجب أن تنتقل إلى اليمين عندما يكون آمنًا وتتركها تتجاوزك.","p":"صحيح. في المسار الأيسر، انتقل إلى اليمين للسيارات الأسرع التي خلفك."},"ht":{"q":"Nan Florida, ou nan liy gòch yon gran wout ki gen plizyè liy. Yon machin ki pi rapid rive dèyè ou. Kisa ou dwe fè?","o":["Rete nan liy gòch la a limit vitès la","Akselere pou rete devan l","Peze fren an ti kras pou fè l ralanti","Deplase sou bò dwat lè li pa danjere epi kite l pase"],"h1":"Sou yon gran wout ki gen plizyè liy, liy gòch la se sitou pou double.","h2":"Lwa Florida di si yon machin ki pi rapid ap rive dèyè ou nan liy gòch la, ou dwe deplase sou bò dwat lè li pa danjere epi kite l pase.","p":"Wi, se sa. Nan liy gòch la, deplase sou bò dwat pou machin ki pi rapid dèyè ou."},"ref":{"doc":"FL","page":67}},{"id":"speed-lanes-029","scope":"FL","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Florida, when must your headlights be on?","o":["Only after midnight","From sunset to sunrise","Only on unlit country roads","Only when another car flashes its lights"],"h1":"Think about the hours when it gets dark outside.","h2":"In Florida your headlights must be on from sunset to sunrise, so you can see and others can see you.","p":"Right. Headlights go on from sunset to sunrise."},"es":{"q":"En Florida, ¿cuándo deben estar encendidas las luces delanteras?","o":["Solo después de la medianoche","Desde la puesta del sol hasta la salida del sol","Solo en caminos rurales sin luz","Solo cuando otro carro le hace cambio de luces"],"h1":"Piense en las horas en que oscurece afuera.","h2":"En Florida sus luces delanteras deben estar encendidas desde la puesta del sol hasta la salida del sol, para que usted vea y lo vean.","p":"Correcto. Las luces van encendidas desde la puesta hasta la salida del sol."},"zh":{"q":"在 Florida，什么时候必须开大灯？","o":["只在半夜以后","从日落到日出","只在没有路灯的乡村道路上","只在别的车对你闪灯时"],"h1":"想一想外面天黑的时间。","h2":"在 Florida，从日落到日出你必须开大灯，这样你能看清路，别人也能看到你。","p":"对。从日落到日出要开大灯。"},"vi":{"q":"Ở Florida, khi nào bạn phải bật đèn pha?","o":["Chỉ sau nửa đêm","Từ lúc mặt trời lặn đến lúc mặt trời mọc","Chỉ trên đường quê không có đèn","Chỉ khi xe khác nháy đèn với bạn"],"h1":"Hãy nghĩ đến những giờ trời tối bên ngoài.","h2":"Ở Florida, đèn pha của bạn phải bật từ lúc mặt trời lặn đến lúc mặt trời mọc, để bạn nhìn thấy và người khác thấy bạn.","p":"Đúng. Bật đèn pha từ lúc mặt trời lặn đến lúc mặt trời mọc."},"tl":{"q":"Sa Florida, kailan dapat nakabukas ang headlights mo?","o":["Pagkatapos lang ng hatinggabi","Mula paglubog ng araw hanggang pagsikat ng araw","Sa madidilim na daan lang sa probinsiya","Kapag nag-flash lang ng ilaw ang ibang kotse"],"h1":"Isipin ang mga oras na dumidilim sa labas.","h2":"Sa Florida, dapat nakabukas ang headlights mo mula paglubog ng araw hanggang pagsikat ng araw, para makakita ka at makita ka ng iba.","p":"Tama. Bukas ang headlights mula paglubog hanggang pagsikat ng araw."},"ar":{"q":"في Florida، متى يجب أن تكون المصابيح الأمامية مضاءة؟","o":["فقط بعد منتصف الليل","من غروب الشمس إلى شروقها","فقط على الطرق الريفية غير المضاءة","فقط عندما تومض سيارة أخرى بأضوائها"],"h1":"فكّر في الساعات التي يصبح فيها الجو مظلمًا في الخارج.","h2":"في Florida يجب أن تكون المصابيح الأمامية مضاءة من غروب الشمس إلى شروقها، حتى ترى أنت ويراك الآخرون.","p":"صحيح. المصابيح الأمامية تُضاء من غروب الشمس إلى شروقها."},"ht":{"q":"Nan Florida, kilè limyè devan machin ou dwe limen?","o":["Sèlman apre minwi","Depi solèy kouche jiskaske solèy leve","Sèlman sou wout andeyò ki pa gen limyè","Sèlman lè yon lòt machin flache limyè l"],"h1":"Panse ak lè li fè nwa deyò.","h2":"Nan Florida limyè devan machin ou dwe limen depi solèy kouche jiskaske solèy leve, pou ou ka wè epi pou lòt moun ka wè ou.","p":"Wi, se sa. Limyè devan yo limen depi solèy kouche jiskaske solèy leve."},"ref":{"doc":"FL","page":73}},{"id":"speed-lanes-030","scope":"FL","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Florida, it is daytime but rain, smoke, or fog makes it hard to see. What must you do with your headlights?","o":["Leave them off because it is daytime","Turn on only your parking lights","Turn on your hazard lights and keep driving","Turn them on"],"h1":"Lights help other drivers see you, not only help you see.","h2":"In Florida you must turn on your headlights during rain, smoke, or fog, even in the daytime, so other drivers can see you.","p":"Right. Rain, smoke, or fog means headlights on, even by day."},"es":{"q":"En Florida, es de día pero la lluvia, el humo o la neblina hacen difícil ver. ¿Qué debe hacer con las luces delanteras?","o":["Dejarlas apagadas porque es de día","Encender solo las luces de estacionamiento","Encender las luces intermitentes y seguir manejando","Encenderlas"],"h1":"Las luces ayudan a que otros lo vean, no solo a que usted vea.","h2":"En Florida debe encender las luces delanteras con lluvia, humo o neblina, aunque sea de día, para que los demás conductores lo vean.","p":"Correcto. Con lluvia, humo o neblina, encienda las luces, aunque sea de día."},"zh":{"q":"在 Florida，现在是白天，但下雨、有烟或有雾，看不清楚。你的大灯必须怎么处理？","o":["关着，因为是白天","只开停车灯","开双闪灯，继续开","把大灯打开"],"h1":"车灯不只帮你看清，也帮别的司机看到你。","h2":"在 Florida，下雨、有烟或有雾时，就算是白天，你也必须打开大灯，让别的司机能看到你。","p":"对。下雨、有烟或有雾，就算白天也要开大灯。"},"vi":{"q":"Ở Florida, đang ban ngày nhưng mưa, khói hoặc sương mù làm khó nhìn. Bạn phải làm gì với đèn pha?","o":["Để tắt vì đang là ban ngày","Chỉ bật đèn đậu xe","Bật đèn khẩn cấp và tiếp tục chạy","Bật đèn pha lên"],"h1":"Đèn giúp người lái khác thấy bạn, không chỉ giúp bạn nhìn thấy.","h2":"Ở Florida, bạn phải bật đèn pha khi có mưa, khói hoặc sương mù, kể cả ban ngày, để người lái khác thấy bạn.","p":"Đúng. Mưa, khói hoặc sương mù thì phải bật đèn pha, kể cả ban ngày."},"tl":{"q":"Sa Florida, araw pa pero dahil sa ulan, usok, o fog (hamog) ay mahirap makakita. Ano ang dapat mong gawin sa headlights mo?","o":["Iwanang nakapatay dahil araw pa","Buksan lang ang parking lights mo","Buksan ang hazard lights mo at magpatuloy","Buksan ang mga ito"],"h1":"Tinutulungan ng ilaw ang ibang drayber na makita ka, hindi lang ikaw na makakita.","h2":"Sa Florida, dapat mong buksan ang headlights mo kapag may ulan, usok, o fog, kahit araw pa, para makita ka ng ibang drayber.","p":"Tama. Kapag may ulan, usok, o fog, buksan ang headlights, kahit araw."},"ar":{"q":"في Florida، الوقت نهار، لكن المطر أو الدخان أو الضباب يجعل الرؤية صعبة. ماذا يجب أن تفعل بالمصابيح الأمامية؟","o":["أتركها مطفأة لأن الوقت نهار","أشغّل أضواء الوقوف فقط","أشغّل أضواء الخطر وأستمر في القيادة","أشغّلها"],"h1":"الأضواء تساعد السائقين الآخرين على رؤيتك، وليس فقط تساعدك على الرؤية.","h2":"في Florida يجب أن تشغّل المصابيح الأمامية في المطر أو الدخان أو الضباب، حتى في النهار، حتى يراك السائقون الآخرون.","p":"صحيح. المطر أو الدخان أو الضباب يعني أن تشغّل المصابيح الأمامية، حتى في النهار."},"ht":{"q":"Nan Florida, li fè jou men lapli, lafimen oswa bwouya fè li difisil pou wè. Kisa ou dwe fè ak limyè devan ou yo?","o":["Kite yo etenn paske li fè jou","Limen sèlman ti limyè pakin yo","Limen limyè ijans ou yo (flachè) epi kontinye kondi","Limen yo"],"h1":"Limyè yo ede lòt chofè yo wè ou, se pa sèlman ede ou wè.","h2":"Nan Florida ou dwe limen limyè devan ou yo lè gen lapli, lafimen oswa bwouya, menm lajounen, pou lòt chofè yo ka wè ou.","p":"Wi, se sa. Lapli, lafimen oswa bwouya vle di limen limyè yo, menm lajounen."},"ref":{"doc":"FL","page":71}},{"id":"speed-lanes-031","scope":"FL","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Florida, a car is coming toward you at night. How close can it get before you must dim your high beams?","o":["500 feet","100 feet","200 feet","1,000 feet"],"h1":"Bright lights can blind the other driver from far away.","h2":"In Florida you must switch to low beams when an oncoming car is within 500 feet, so you do not blind its driver.","p":"Right. Dim your high beams within 500 feet of an oncoming car."},"es":{"q":"En Florida, de noche viene un carro de frente. ¿A qué distancia debe cambiar a luces bajas?","o":["500 pies","100 pies","200 pies","1,000 pies"],"h1":"Las luces altas pueden encandilar al otro conductor desde lejos.","h2":"En Florida debe cambiar a luces bajas cuando un carro que viene de frente está a 500 pies o menos, para no encandilar al conductor.","p":"Correcto. Cambie a luces bajas a 500 pies de un carro que viene de frente."},"zh":{"q":"在 Florida，晚上有一辆车迎面开过来。它离你多近时，你必须把远光灯换成近光灯？","o":["500 英尺","100 英尺","200 英尺","1,000 英尺"],"h1":"很亮的灯从很远的地方就能晃到对面的司机。","h2":"在 Florida，当对面来车在 500 英尺以内时，你必须换成近光灯，这样才不会晃到对方司机。","p":"对。对面来车在 500 英尺以内时，要关掉远光灯。"},"vi":{"q":"Ở Florida, ban đêm có một xe đang chạy ngược chiều về phía bạn. Xe đó đến gần bao nhiêu thì bạn phải chuyển đèn pha sang đèn cốt (đèn chiếu gần)?","o":["500 feet","100 feet","200 feet","1,000 feet"],"h1":"Đèn sáng có thể làm người lái kia bị chói từ rất xa.","h2":"Ở Florida, bạn phải chuyển sang đèn cốt khi xe ngược chiều ở trong vòng 500 feet, để không làm người lái đó bị chói mắt.","p":"Đúng. Hãy chuyển sang đèn cốt khi xe ngược chiều ở trong vòng 500 feet."},"tl":{"q":"Sa Florida, may kotseng paparating sa harap mo sa gabi. Gaano ito kalapit bago mo dapat ibaba ang high beams mo?","o":["500 feet","100 feet","200 feet","1,000 feet"],"h1":"Kayang silawin ng malakas na ilaw ang ibang drayber mula sa malayo.","h2":"Sa Florida, dapat kang lumipat sa low beams kapag ang paparating na kotse ay nasa loob ng 500 feet, para hindi mo masilaw ang drayber nito.","p":"Tama. Ibaba ang high beams mo sa loob ng 500 feet ng paparating na kotse."},"ar":{"q":"في Florida، سيارة قادمة نحوك في الليل. كم يمكن أن تقترب قبل أن يجب عليك أن تخفض الأضواء العالية؟","o":["500 قدم","100 قدم","200 قدم","1,000 قدم"],"h1":"الأضواء القوية يمكن أن تُعمي السائق الآخر من مسافة بعيدة.","h2":"في Florida يجب أن تنتقل إلى الأضواء المنخفضة عندما تكون السيارة القادمة نحوك على مسافة 500 قدم أو أقل، حتى لا تُعمي سائقها.","p":"صحيح. اخفض الأضواء العالية عندما تكون السيارة القادمة على مسافة 500 قدم أو أقل."},"ht":{"q":"Nan Florida, yon machin ap vin sou ou lannwit. A ki distans li ka rive anvan ou dwe bese gwo limyè ou yo?","o":["500 pye","100 pye","200 pye","1,000 pye"],"h1":"Gwo limyè yo ka avegle lòt chofè a depi byen lwen.","h2":"Nan Florida ou dwe pase sou ti limyè yo lè yon machin k ap vin sou ou rive nan 500 pye, pou ou pa avegle chofè a.","p":"Wi, se sa. Bese gwo limyè ou yo lè yon machin k ap vin sou ou rive nan 500 pye."},"ref":{"doc":"FL","page":73}},{"id":"speed-lanes-032","scope":"FL","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Florida, you are driving behind another car at night. How close can you get before you must dim your high beams?","o":["50 feet","100 feet","300 feet","700 feet"],"h1":"Your bright lights shine into the other driver's mirrors.","h2":"In Florida you must use low beams when you are within 300 feet of a car ahead of you, so your lights do not blind the driver through the mirrors.","p":"Right. Dim your lights within 300 feet of a car you are following."},"es":{"q":"En Florida, de noche usted va detrás de otro carro. ¿A qué distancia debe cambiar a luces bajas?","o":["50 pies","100 pies","300 pies","700 pies"],"h1":"Sus luces altas se reflejan en los espejos del otro conductor.","h2":"En Florida debe usar luces bajas cuando está a 300 pies o menos del carro de adelante, para no encandilar al conductor por los espejos.","p":"Correcto. Cambie a luces bajas a 300 pies del carro que va adelante."},"zh":{"q":"在 Florida，你晚上跟在另一辆车后面开。你离它多近时，必须把远光灯换成近光灯？","o":["50 英尺","100 英尺","300 英尺","700 英尺"],"h1":"你的远光灯会照进对方司机的后视镜。","h2":"在 Florida，当你离前面的车在 300 英尺以内时，你必须用近光灯，这样你的灯就不会通过后视镜晃到对方司机。","p":"对。跟车在 300 英尺以内时，要换成近光灯。"},"vi":{"q":"Ở Florida, ban đêm bạn đang chạy sau một xe khác. Bạn đến gần bao nhiêu thì phải chuyển đèn pha sang đèn cốt (đèn chiếu gần)?","o":["50 feet","100 feet","300 feet","700 feet"],"h1":"Đèn sáng của bạn chiếu vào gương của người lái kia.","h2":"Ở Florida, bạn phải dùng đèn cốt khi bạn ở trong vòng 300 feet sau một xe phía trước, để đèn của bạn không làm người lái đó bị chói qua gương.","p":"Đúng. Hãy chuyển sang đèn cốt khi ở trong vòng 300 feet sau xe bạn đang theo."},"tl":{"q":"Sa Florida, nagmamaneho ka sa likod ng ibang kotse sa gabi. Gaano ka kalapit bago mo dapat ibaba ang high beams mo?","o":["50 feet","100 feet","300 feet","700 feet"],"h1":"Tumatama ang malakas mong ilaw sa mga salamin ng ibang drayber.","h2":"Sa Florida, dapat kang gumamit ng low beams kapag nasa loob ka ng 300 feet ng kotse sa unahan mo, para hindi masilaw ang drayber dahil sa mga salamin nito.","p":"Tama. Ibaba ang ilaw mo sa loob ng 300 feet ng kotseng sinusundan mo."},"ar":{"q":"في Florida، تقود خلف سيارة أخرى في الليل. كم يمكن أن تقترب منها قبل أن يجب عليك أن تخفض الأضواء العالية؟","o":["50 قدمًا","100 قدم","300 قدم","700 قدم"],"h1":"أضواؤك القوية تلمع في مرايا السائق الآخر.","h2":"في Florida يجب أن تستعمل الأضواء المنخفضة عندما تكون على مسافة 300 قدم أو أقل من سيارة أمامك، حتى لا تُعمي أضواؤك السائق من خلال المرايا.","p":"صحيح. اخفض أضواءك عندما تكون على مسافة 300 قدم أو أقل من سيارة تسير خلفها."},"ht":{"q":"Nan Florida, w ap kondi dèyè yon lòt machin lannwit. A ki distans ou ka rive anvan ou dwe bese gwo limyè ou yo?","o":["50 pye","100 pye","300 pye","700 pye"],"h1":"Gwo limyè ou yo klere nan retwovizè lòt chofè a.","h2":"Nan Florida ou dwe sèvi ak ti limyè yo lè ou nan 300 pye dèyè yon machin ki devan ou, pou limyè ou yo pa avegle chofè a nan retwovizè l.","p":"Wi, se sa. Bese limyè ou yo lè ou nan 300 pye dèyè yon machin w ap swiv."},"ref":{"doc":"FL","page":73}},{"id":"speed-lanes-033","scope":"US","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"You are driving in thick fog. Which lights should you use?","o":["High beams","Parking lights only","Low beams","No lights"],"h1":"Fog reflects strong light back into your eyes.","h2":"In fog you should use low beams, because high beams bounce off the fog and make it harder to see.","p":"Right. Use low beams in fog."},"es":{"q":"Usted maneja con neblina espesa. ¿Qué luces debe usar?","o":["Luces altas","Solo luces de estacionamiento","Luces bajas","Ninguna luz"],"h1":"La neblina refleja la luz fuerte hacia sus ojos.","h2":"Con neblina debe usar luces bajas, porque las luces altas rebotan en la neblina y hacen más difícil ver.","p":"Correcto. Use luces bajas con neblina."},"zh":{"q":"你在浓雾里开车。你应该用哪种灯？","o":["远光灯","只开停车灯","近光灯","不开灯"],"h1":"雾会把强光反射回你的眼睛。","h2":"在雾里你应该用近光灯，因为远光灯会被雾反射回来，让你更看不清。","p":"对。有雾时用近光灯。"},"vi":{"q":"Bạn đang lái xe trong sương mù dày. Bạn nên dùng đèn nào?","o":["Đèn pha (đèn chiếu xa)","Chỉ đèn đậu xe","Đèn cốt (đèn chiếu gần)","Không bật đèn"],"h1":"Sương mù phản chiếu ánh sáng mạnh ngược lại vào mắt bạn.","h2":"Trong sương mù, bạn nên dùng đèn cốt, vì đèn chiếu xa dội lại từ sương mù và làm bạn khó nhìn hơn.","p":"Đúng. Hãy dùng đèn cốt khi có sương mù."},"tl":{"q":"Nagmamaneho ka sa makapal na fog (hamog). Anong ilaw ang dapat mong gamitin?","o":["High beams","Parking lights lang","Low beams","Walang ilaw"],"h1":"Ibinabalik ng fog ang malakas na ilaw sa mga mata mo.","h2":"Sa fog, dapat kang gumamit ng low beams, dahil tumatalbog ang high beams sa fog at lalo kang nahihirapang makakita.","p":"Tama. Gumamit ng low beams sa fog."},"ar":{"q":"تقود في ضباب كثيف. أي أضواء يجب أن تستعمل؟","o":["الأضواء العالية","أضواء الوقوف فقط","الأضواء المنخفضة","بدون أضواء"],"h1":"الضباب يعكس الضوء القوي إلى عينيك.","h2":"في الضباب يجب أن تستعمل الأضواء المنخفضة، لأن الأضواء العالية ترتد عن الضباب وتجعل الرؤية أصعب.","p":"صحيح. استعمل الأضواء المنخفضة في الضباب."},"ht":{"q":"W ap kondi nan yon bwouya ki epè. Ki limyè ou ta dwe sèvi?","o":["Gwo limyè yo","Ti limyè pakin yo sèlman","Ti limyè yo (limyè ba)","Okenn limyè"],"h1":"Bwouya voye limyè ki fò tounen nan je ou.","h2":"Nan bwouya ou ta dwe sèvi ak ti limyè yo, paske gwo limyè yo frape bwouya a epi yo fè li pi difisil pou wè.","p":"Wi, se sa. Sèvi ak ti limyè yo nan bwouya."},"ref":{"doc":"FL","page":72}},{"id":"speed-lanes-034","scope":"FL","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Florida, how close to a fire hydrant may you park?","o":["No closer than 15 feet","No closer than 5 feet","No closer than 10 feet","No closer than 30 feet"],"h1":"Fire trucks need room to connect their hoses.","h2":"In Florida you may not park within 15 feet of a fire hydrant, so firefighters can reach it quickly.","p":"Right. Stay at least 15 feet from a fire hydrant."},"es":{"q":"En Florida, ¿qué tan cerca de un hidrante puede estacionarse?","o":["No a menos de 15 pies","No a menos de 5 pies","No a menos de 10 pies","No a menos de 30 pies"],"h1":"Los bomberos necesitan espacio para conectar las mangueras.","h2":"En Florida no puede estacionarse a menos de 15 pies de un hidrante, para que los bomberos lleguen rápido a él.","p":"Correcto. Estaciónese al menos a 15 pies de un hidrante."},"zh":{"q":"在 Florida，停车时离消防栓最近可以多近？","o":["不能少于 15 英尺","不能少于 5 英尺","不能少于 10 英尺","不能少于 30 英尺"],"h1":"消防车需要空间接上水管。","h2":"在 Florida，你不能停在离消防栓 15 英尺以内的地方，这样消防员才能很快用到它。","p":"对。停车时离消防栓至少 15 英尺。"},"vi":{"q":"Ở Florida, bạn được đậu xe gần trụ nước cứu hỏa đến mức nào?","o":["Không gần hơn 15 feet","Không gần hơn 5 feet","Không gần hơn 10 feet","Không gần hơn 30 feet"],"h1":"Xe cứu hỏa cần chỗ để nối vòi nước.","h2":"Ở Florida, bạn không được đậu xe trong vòng 15 feet từ trụ nước cứu hỏa, để lính cứu hỏa có thể đến đó nhanh.","p":"Đúng. Hãy đậu cách trụ nước cứu hỏa ít nhất 15 feet."},"tl":{"q":"Sa Florida, gaano kalapit sa fire hydrant ka puwedeng pumarada?","o":["Hindi lalapit sa 15 feet","Hindi lalapit sa 5 feet","Hindi lalapit sa 10 feet","Hindi lalapit sa 30 feet"],"h1":"Kailangan ng mga trak ng bumbero ng lugar para ikabit ang kanilang hose.","h2":"Sa Florida, hindi ka puwedeng pumarada sa loob ng 15 feet mula sa fire hydrant, para mabilis itong maabot ng mga bumbero.","p":"Tama. Lumayo nang hindi bababa sa 15 feet sa fire hydrant."},"ar":{"q":"في Florida، كم يمكنك أن تقترب من حنفية إطفاء الحريق عندما تركن سيارتك؟","o":["ليس أقرب من 15 قدمًا","ليس أقرب من 5 أقدام","ليس أقرب من 10 أقدام","ليس أقرب من 30 قدمًا"],"h1":"سيارات الإطفاء تحتاج إلى مكان لتوصل خراطيمها.","h2":"في Florida لا يجوز أن تركن على مسافة أقل من 15 قدمًا من حنفية إطفاء الحريق، حتى يصل إليها رجال الإطفاء بسرعة.","p":"صحيح. ابقَ على مسافة 15 قدمًا على الأقل من حنفية إطفاء الحريق."},"ht":{"q":"Nan Florida, a ki distans de yon bouch dlo ponpye (fire hydrant) ou ka pake?","o":["Pa pi pre pase 15 pye","Pa pi pre pase 5 pye","Pa pi pre pase 10 pye","Pa pi pre pase 30 pye"],"h1":"Kamyon ponpye yo bezwen plas pou konekte tiyo yo.","h2":"Nan Florida ou pa ka pake nan mwens pase 15 pye de yon bouch dlo ponpye, pou ponpye yo ka rive ladan l vit.","p":"Wi, se sa. Rete omwen 15 pye lwen yon bouch dlo ponpye."},"ref":{"doc":"FL","page":66}},{"id":"speed-lanes-035","scope":"FL","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Florida, how close to a crosswalk at an intersection may you park?","o":["No closer than 5 feet","No closer than 10 feet","No closer than 50 feet","No closer than 20 feet"],"h1":"Drivers must be able to see people who are walking across.","h2":"In Florida you may not park within 20 feet of a crosswalk at an intersection, so drivers can see people crossing.","p":"Right. Park at least 20 feet from a crosswalk at an intersection."},"es":{"q":"En Florida, ¿qué tan cerca de un cruce peatonal en una intersección puede estacionarse?","o":["No a menos de 5 pies","No a menos de 10 pies","No a menos de 50 pies","No a menos de 20 pies"],"h1":"Los conductores deben poder ver a las personas que cruzan caminando.","h2":"En Florida no puede estacionarse a menos de 20 pies de un cruce peatonal en una intersección, para que los conductores vean a quienes cruzan.","p":"Correcto. Estaciónese al menos a 20 pies de un cruce peatonal en una intersección."},"zh":{"q":"在 Florida，停车时离路口的人行横道最近可以多近？","o":["不能少于 5 英尺","不能少于 10 英尺","不能少于 50 英尺","不能少于 20 英尺"],"h1":"司机必须能看到正在过马路的人。","h2":"在 Florida，你不能停在离路口人行横道 20 英尺以内的地方，这样司机才能看到过马路的人。","p":"对。停车时离路口的人行横道至少 20 英尺。"},"vi":{"q":"Ở Florida, bạn được đậu xe gần lối qua đường cho người đi bộ tại giao lộ đến mức nào?","o":["Không gần hơn 5 feet","Không gần hơn 10 feet","Không gần hơn 50 feet","Không gần hơn 20 feet"],"h1":"Người lái phải nhìn thấy được người đang đi bộ qua đường.","h2":"Ở Florida, bạn không được đậu xe trong vòng 20 feet từ lối qua đường tại giao lộ, để người lái có thể thấy người đi bộ qua đường.","p":"Đúng. Hãy đậu cách lối qua đường tại giao lộ ít nhất 20 feet."},"tl":{"q":"Sa Florida, gaano kalapit sa crosswalk sa intersection ka puwedeng pumarada?","o":["Hindi lalapit sa 5 feet","Hindi lalapit sa 10 feet","Hindi lalapit sa 50 feet","Hindi lalapit sa 20 feet"],"h1":"Dapat makita ng mga drayber ang mga taong tumatawid.","h2":"Sa Florida, hindi ka puwedeng pumarada sa loob ng 20 feet mula sa crosswalk sa intersection, para makita ng mga drayber ang mga tumatawid.","p":"Tama. Pumarada nang hindi bababa sa 20 feet ang layo sa crosswalk sa intersection."},"ar":{"q":"في Florida، كم يمكنك أن تقترب من ممر مشاة عند تقاطع عندما تركن سيارتك؟","o":["ليس أقرب من 5 أقدام","ليس أقرب من 10 أقدام","ليس أقرب من 50 قدمًا","ليس أقرب من 20 قدمًا"],"h1":"يجب أن يستطيع السائقون رؤية الناس الذين يعبرون.","h2":"في Florida لا يجوز أن تركن على مسافة أقل من 20 قدمًا من ممر مشاة عند تقاطع، حتى يرى السائقون الناس الذين يعبرون.","p":"صحيح. اركن على مسافة 20 قدمًا على الأقل من ممر المشاة عند التقاطع."},"ht":{"q":"Nan Florida, a ki distans de yon pasaj pyeton nan yon kafou ou ka pake?","o":["Pa pi pre pase 5 pye","Pa pi pre pase 10 pye","Pa pi pre pase 50 pye","Pa pi pre pase 20 pye"],"h1":"Chofè yo dwe ka wè moun k ap travèse yo.","h2":"Nan Florida ou pa ka pake nan mwens pase 20 pye de yon pasaj pyeton nan yon kafou, pou chofè yo ka wè moun k ap travèse yo.","p":"Wi, se sa. Pake omwen 20 pye lwen yon pasaj pyeton nan yon kafou."},"ref":{"doc":"FL","page":66}},{"id":"speed-lanes-036","scope":"FL","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Florida, how close to a stop sign may you park?","o":["No closer than 10 feet","No closer than 30 feet","No closer than 15 feet","No closer than 100 feet"],"h1":"A parked car could hide the sign from other drivers.","h2":"In Florida you may not park within 30 feet of a stop sign, so other drivers can see the sign clearly.","p":"Right. Park at least 30 feet from a stop sign."},"es":{"q":"En Florida, ¿qué tan cerca de un letrero de PARE puede estacionarse?","o":["No a menos de 10 pies","No a menos de 30 pies","No a menos de 15 pies","No a menos de 100 pies"],"h1":"Un carro estacionado podría tapar el letrero para otros conductores.","h2":"En Florida no puede estacionarse a menos de 30 pies de un letrero de PARE, para que los demás conductores lo vean bien.","p":"Correcto. Estaciónese al menos a 30 pies de un letrero de PARE."},"zh":{"q":"在 Florida，停车时离停车标志最近可以多近？","o":["不能少于 10 英尺","不能少于 30 英尺","不能少于 15 英尺","不能少于 100 英尺"],"h1":"停着的车可能会挡住标志，让别的司机看不到。","h2":"在 Florida，你不能停在离停车标志 30 英尺以内的地方，这样别的司机才能清楚地看到标志。","p":"对。停车时离停车标志至少 30 英尺。"},"vi":{"q":"Ở Florida, bạn được đậu xe gần biển \"STOP\" đến mức nào?","o":["Không gần hơn 10 feet","Không gần hơn 30 feet","Không gần hơn 15 feet","Không gần hơn 100 feet"],"h1":"Một xe đang đậu có thể che biển báo khỏi tầm nhìn của người lái khác.","h2":"Ở Florida, bạn không được đậu xe trong vòng 30 feet từ biển \"STOP\", để người lái khác thấy rõ biển báo.","p":"Đúng. Hãy đậu cách biển \"STOP\" ít nhất 30 feet."},"tl":{"q":"Sa Florida, gaano kalapit sa stop sign ka puwedeng pumarada?","o":["Hindi lalapit sa 10 feet","Hindi lalapit sa 30 feet","Hindi lalapit sa 15 feet","Hindi lalapit sa 100 feet"],"h1":"Maaaring itago ng nakaparadang kotse ang karatula sa ibang drayber.","h2":"Sa Florida, hindi ka puwedeng pumarada sa loob ng 30 feet mula sa stop sign, para malinaw na makita ng ibang drayber ang karatula.","p":"Tama. Pumarada nang hindi bababa sa 30 feet ang layo sa stop sign."},"ar":{"q":"في Florida، كم يمكنك أن تقترب من علامة \"STOP\" (قف) عندما تركن سيارتك؟","o":["ليس أقرب من 10 أقدام","ليس أقرب من 30 قدمًا","ليس أقرب من 15 قدمًا","ليس أقرب من 100 قدم"],"h1":"السيارة المركونة قد تخفي العلامة عن السائقين الآخرين.","h2":"في Florida لا يجوز أن تركن على مسافة أقل من 30 قدمًا من علامة \"STOP\" (قف)، حتى يرى السائقون الآخرون العلامة بوضوح.","p":"صحيح. اركن على مسافة 30 قدمًا على الأقل من علامة \"STOP\" (قف)."},"ht":{"q":"Nan Florida, a ki distans de yon siy \"STOP\" ou ka pake?","o":["Pa pi pre pase 10 pye","Pa pi pre pase 30 pye","Pa pi pre pase 15 pye","Pa pi pre pase 100 pye"],"h1":"Yon machin ki pake ka kache siy la pou lòt chofè yo pa wè l.","h2":"Nan Florida ou pa ka pake nan mwens pase 30 pye de yon siy \"STOP\", pou lòt chofè yo ka wè siy la byen.","p":"Wi, se sa. Pake omwen 30 pye lwen yon siy \"STOP\"."},"ref":{"doc":"FL","page":66}},{"id":"speed-lanes-037","scope":"FL","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Florida, how close to the nearest rail of a railroad crossing may you park?","o":["No closer than 15 feet","No closer than 50 feet","No closer than 25 feet","No closer than 10 feet"],"h1":"Trains are wide and drivers need a clear view of the tracks.","h2":"In Florida you may not park within 50 feet of the nearest rail of a railroad crossing.","p":"Right. Park at least 50 feet from a railroad crossing."},"es":{"q":"En Florida, ¿qué tan cerca del riel más cercano de un cruce de tren puede estacionarse?","o":["No a menos de 15 pies","No a menos de 50 pies","No a menos de 25 pies","No a menos de 10 pies"],"h1":"Los trenes son anchos y los conductores necesitan ver bien las vías.","h2":"En Florida no puede estacionarse a menos de 50 pies del riel más cercano de un cruce de tren.","p":"Correcto. Estaciónese al menos a 50 pies de un cruce de tren."},"zh":{"q":"在 Florida，停车时离铁路道口最近的铁轨最近可以多近？","o":["不能少于 15 英尺","不能少于 50 英尺","不能少于 25 英尺","不能少于 10 英尺"],"h1":"火车很宽，司机需要清楚地看到铁轨。","h2":"在 Florida，你不能停在离铁路道口最近的铁轨 50 英尺以内的地方。","p":"对。停车时离铁路道口至少 50 英尺。"},"vi":{"q":"Ở Florida, bạn được đậu xe gần thanh ray gần nhất của chỗ giao nhau với đường sắt đến mức nào?","o":["Không gần hơn 15 feet","Không gần hơn 50 feet","Không gần hơn 25 feet","Không gần hơn 10 feet"],"h1":"Tàu hỏa rất rộng và người lái cần nhìn rõ đường ray.","h2":"Ở Florida, bạn không được đậu xe trong vòng 50 feet từ thanh ray gần nhất của chỗ giao nhau với đường sắt.","p":"Đúng. Hãy đậu cách chỗ giao nhau với đường sắt ít nhất 50 feet."},"tl":{"q":"Sa Florida, gaano kalapit sa pinakamalapit na riles ng railroad crossing ka puwedeng pumarada?","o":["Hindi lalapit sa 15 feet","Hindi lalapit sa 50 feet","Hindi lalapit sa 25 feet","Hindi lalapit sa 10 feet"],"h1":"Malapad ang mga tren at kailangan ng mga drayber ng malinaw na tanaw sa riles.","h2":"Sa Florida, hindi ka puwedeng pumarada sa loob ng 50 feet mula sa pinakamalapit na riles ng railroad crossing.","p":"Tama. Pumarada nang hindi bababa sa 50 feet ang layo sa railroad crossing."},"ar":{"q":"في Florida، كم يمكنك أن تقترب من أقرب قضيب في تقاطع سكة حديد عندما تركن سيارتك؟","o":["ليس أقرب من 15 قدمًا","ليس أقرب من 50 قدمًا","ليس أقرب من 25 قدمًا","ليس أقرب من 10 أقدام"],"h1":"القطارات عريضة، والسائقون يحتاجون إلى رؤية واضحة للسكة.","h2":"في Florida لا يجوز أن تركن على مسافة أقل من 50 قدمًا من أقرب قضيب في تقاطع سكة حديد.","p":"صحيح. اركن على مسافة 50 قدمًا على الأقل من تقاطع سكة الحديد."},"ht":{"q":"Nan Florida, a ki distans de ray ki pi pre a nan yon kwazman tren ou ka pake?","o":["Pa pi pre pase 15 pye","Pa pi pre pase 50 pye","Pa pi pre pase 25 pye","Pa pi pre pase 10 pye"],"h1":"Tren yo laj epi chofè yo bezwen wè ray yo byen.","h2":"Nan Florida ou pa ka pake nan mwens pase 50 pye de ray ki pi pre a nan yon kwazman tren.","p":"Wi, se sa. Pake omwen 50 pye lwen yon kwazman tren."},"ref":{"doc":"FL","page":66}},{"id":"speed-lanes-038","scope":"FL","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Florida, you park facing downhill next to a curb. Which way should you turn your front wheels?","o":["Away from the curb","Straight ahead","It does not matter","Toward the curb"],"h1":"Think about where the car would roll if the brakes failed.","h2":"When you park downhill next to a curb, turn your front wheels toward the curb, so the car rolls into the curb if it moves.","p":"Right. Downhill with a curb, turn your wheels toward the curb."},"es":{"q":"En Florida, se estaciona en bajada junto a la orilla de la acera. ¿Hacia dónde debe girar las ruedas delanteras?","o":["Lejos de la acera","Rectas hacia adelante","No importa","Hacia la acera"],"h1":"Piense hacia dónde rodaría el carro si fallaran los frenos.","h2":"Cuando se estaciona en bajada junto a la acera, gire las ruedas delanteras hacia la acera, para que el carro choque con ella si se mueve.","p":"Correcto. En bajada con acera, gire las ruedas hacia la acera."},"zh":{"q":"在 Florida，你在路缘旁边停车，车头朝下坡。你的前轮应该朝哪边转？","o":["朝远离路缘的方向","朝正前方","朝哪边都没关系","朝路缘的方向"],"h1":"想一想，如果刹车失灵，车会往哪里滑。","h2":"在有路缘的下坡停车时，要把前轮转向路缘，这样车如果滑动，就会顶到路缘上。","p":"对。有路缘的下坡，前轮转向路缘。"},"vi":{"q":"Ở Florida, bạn đậu xe hướng xuống dốc, cạnh lề đường. Bạn nên quay bánh trước về hướng nào?","o":["Ra xa lề đường","Thẳng về phía trước","Hướng nào cũng được","Về phía lề đường"],"h1":"Hãy nghĩ xem xe sẽ lăn về đâu nếu phanh bị hỏng.","h2":"Khi đậu xe xuống dốc cạnh lề đường, bạn quay bánh trước về phía lề, để nếu xe lăn thì sẽ chạm vào lề.","p":"Đúng. Xuống dốc có lề đường, quay bánh xe về phía lề."},"tl":{"q":"Sa Florida, pumarada ka nang nakaharap pababa sa tabi ng curb. Saan mo dapat ipihit ang mga gulong sa harap?","o":["Palayo sa curb","Diretso","Hindi mahalaga","Papunta sa curb"],"h1":"Isipin kung saan gugulong ang kotse kung masira ang preno.","h2":"Kapag pumarada ka nang pababa sa tabi ng curb, ipihit ang mga gulong sa harap papunta sa curb, para gumulong ang kotse papunta sa curb kung gumalaw ito.","p":"Tama. Pababa at may curb, ipihit ang mga gulong papunta sa curb."},"ar":{"q":"في Florida، تركن سيارتك ووجهها إلى أسفل المنحدر بجانب رصيف. إلى أي جهة يجب أن تدير العجلات الأمامية؟","o":["بعيدًا عن الرصيف","إلى الأمام مباشرة","لا يهم","نحو الرصيف"],"h1":"فكّر إلى أين ستتدحرج السيارة إذا تعطلت الفرامل.","h2":"عندما تركن ووجه السيارة إلى أسفل المنحدر بجانب رصيف، أدر العجلات الأمامية نحو الرصيف، حتى تتدحرج السيارة إلى الرصيف إذا تحركت.","p":"صحيح. في النزول وبجانب رصيف، أدر العجلات نحو الرصيف."},"ht":{"q":"Nan Florida, ou pake nan yon desant bò kote yon rebò twotwa, devan machin nan bay sou desant lan. Nan ki direksyon ou ta dwe vire wou devan yo?","o":["Lwen rebò twotwa a","Tou dwat","Sa pa fè okenn diferans","Bò kote rebò twotwa a"],"h1":"Panse ak ki kote machin nan ta woule si fren yo pa mache.","h2":"Lè ou pake nan yon desant bò kote yon rebò twotwa, vire wou devan yo bò kote rebò twotwa a, pou si machin nan bouje, li woule frape rebò twotwa a.","p":"Wi, se sa. Nan desant ak yon rebò twotwa, vire wou yo bò kote rebò twotwa a."},"ref":{"doc":"FL","page":66}},{"id":"speed-lanes-039","scope":"FL","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Florida, you park facing uphill next to a curb. Which way should you turn your front wheels?","o":["Away from the curb","Toward the curb","Straight ahead","It does not matter"],"h1":"If the car rolls back, you want the back of the front tire to touch the curb.","h2":"When you park uphill next to a curb, turn your front wheels away from the curb, so the tire catches the curb if the car rolls back.","p":"Right. Uphill with a curb, turn your wheels away from the curb."},"es":{"q":"En Florida, se estaciona en subida junto a la orilla de la acera. ¿Hacia dónde debe girar las ruedas delanteras?","o":["Lejos de la acera","Hacia la acera","Rectas hacia adelante","No importa"],"h1":"Si el carro rueda hacia atrás, quiere que la llanta delantera toque la acera.","h2":"Cuando se estaciona en subida junto a la acera, gire las ruedas delanteras lejos de la acera, para que la llanta se apoye en ella si el carro rueda hacia atrás.","p":"Correcto. En subida con acera, gire las ruedas lejos de la acera."},"zh":{"q":"在 Florida，你在路缘旁边停车，车头朝上坡。你的前轮应该朝哪边转？","o":["朝远离路缘的方向","朝路缘的方向","朝正前方","朝哪边都没关系"],"h1":"如果车往后滑，你希望前轮的后部顶到路缘。","h2":"在有路缘的上坡停车时，要把前轮转离路缘，这样车如果往后滑，轮胎就会被路缘挡住。","p":"对。有路缘的上坡，前轮转离路缘。"},"vi":{"q":"Ở Florida, bạn đậu xe hướng lên dốc, cạnh lề đường. Bạn nên quay bánh trước về hướng nào?","o":["Ra xa lề đường","Về phía lề đường","Thẳng về phía trước","Hướng nào cũng được"],"h1":"Nếu xe lăn về sau, bạn muốn phần sau của bánh trước chạm vào lề.","h2":"Khi đậu xe lên dốc cạnh lề đường, bạn quay bánh trước ra xa lề, để nếu xe lăn về sau thì bánh xe sẽ chặn vào lề.","p":"Đúng. Lên dốc có lề đường, quay bánh xe ra xa lề."},"tl":{"q":"Sa Florida, pumarada ka nang nakaharap paakyat sa tabi ng curb. Saan mo dapat ipihit ang mga gulong sa harap?","o":["Palayo sa curb","Papunta sa curb","Diretso","Hindi mahalaga"],"h1":"Kung umatras ang kotse, gusto mong tumama sa curb ang likod ng gulong sa harap.","h2":"Kapag pumarada ka nang paakyat sa tabi ng curb, ipihit ang mga gulong sa harap palayo sa curb, para sumabit ang gulong sa curb kung umatras ang kotse.","p":"Tama. Paakyat at may curb, ipihit ang mga gulong palayo sa curb."},"ar":{"q":"في Florida، تركن سيارتك ووجهها إلى أعلى المنحدر بجانب رصيف. إلى أي جهة يجب أن تدير العجلات الأمامية؟","o":["بعيدًا عن الرصيف","نحو الرصيف","إلى الأمام مباشرة","لا يهم"],"h1":"إذا رجعت السيارة إلى الخلف، تريد أن يلمس الجزء الخلفي من العجلة الأمامية الرصيف.","h2":"عندما تركن ووجه السيارة إلى أعلى المنحدر بجانب رصيف، أدر العجلات الأمامية بعيدًا عن الرصيف، حتى تمسك العجلة بالرصيف إذا رجعت السيارة إلى الخلف.","p":"صحيح. في الصعود وبجانب رصيف، أدر العجلات بعيدًا عن الرصيف."},"ht":{"q":"Nan Florida, ou pake nan yon monte bò kote yon rebò twotwa, devan machin nan bay sou monte a. Nan ki direksyon ou ta dwe vire wou devan yo?","o":["Lwen rebò twotwa a","Bò kote rebò twotwa a","Tou dwat","Sa pa fè okenn diferans"],"h1":"Si machin nan woule fè bak, ou vle dèyè kawoutchou devan an touche rebò twotwa a.","h2":"Lè ou pake nan yon monte bò kote yon rebò twotwa, vire wou devan yo lwen rebò twotwa a, pou kawoutchou a kenbe sou rebò twotwa a si machin nan woule fè bak.","p":"Wi, se sa. Nan monte ak yon rebò twotwa, vire wou yo lwen rebò twotwa a."},"ref":{"doc":"FL","page":66}},{"id":"speed-lanes-040","scope":"FL","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Florida, when you parallel park next to a curb, how close to the curb must your wheels be?","o":["Within 24 inches","Within 36 inches","Within 12 inches","Within 6 feet"],"h1":"Your car should be close enough that it does not stick out into traffic.","h2":"In Florida your wheels must be within 12 inches of the curb when you parallel park, so your car does not block the lane.","p":"Right. Park with your wheels within 12 inches of the curb."},"es":{"q":"En Florida, al estacionarse en paralelo junto a la acera, ¿qué tan cerca de la acera deben quedar las ruedas?","o":["A 24 pulgadas o menos","A 36 pulgadas o menos","A 12 pulgadas o menos","A 6 pies o menos"],"h1":"Su carro debe quedar lo bastante cerca para no salirse hacia el tráfico.","h2":"En Florida las ruedas deben quedar a 12 pulgadas o menos de la acera al estacionarse en paralelo, para que su carro no tape el carril.","p":"Correcto. Estaciónese con las ruedas a 12 pulgadas o menos de la acera."},"zh":{"q":"在 Florida，你在路缘旁边侧方停车时，车轮离路缘必须多近？","o":["24 英寸以内","36 英寸以内","12 英寸以内","6 英尺以内"],"h1":"你的车应该停得够近，不会伸到车流里。","h2":"在 Florida，侧方停车时，你的车轮必须在离路缘 12 英寸以内，这样你的车就不会挡住车道。","p":"对。停车时车轮离路缘在 12 英寸以内。"},"vi":{"q":"Ở Florida, khi đậu xe song song cạnh lề đường, bánh xe của bạn phải cách lề bao nhiêu?","o":["Trong vòng 24 inch","Trong vòng 36 inch","Trong vòng 12 inch","Trong vòng 6 feet"],"h1":"Xe của bạn nên ở đủ gần để không lấn ra dòng xe.","h2":"Ở Florida, khi đậu xe song song, bánh xe của bạn phải cách lề trong vòng 12 inch, để xe không chắn làn đường.","p":"Đúng. Hãy đậu với bánh xe cách lề trong vòng 12 inch."},"tl":{"q":"Sa Florida, kapag nag-parallel park ka sa tabi ng curb, gaano kalapit sa curb dapat ang mga gulong mo?","o":["Sa loob ng 24 inches","Sa loob ng 36 inches","Sa loob ng 12 inches","Sa loob ng 6 feet"],"h1":"Dapat sapat ang lapit ng kotse mo para hindi ito nakausli sa trapiko.","h2":"Sa Florida, dapat nasa loob ng 12 inches mula sa curb ang mga gulong mo kapag nag-parallel park ka, para hindi maharangan ng kotse mo ang lane.","p":"Tama. Pumarada nang nasa loob ng 12 inches mula sa curb ang mga gulong mo."},"ar":{"q":"في Florida، عندما تركن موازيًا للرصيف، كم يجب أن تكون عجلاتك قريبة من الرصيف؟","o":["في حدود 24 بوصة","في حدود 36 بوصة","في حدود 12 بوصة","في حدود 6 أقدام"],"h1":"يجب أن تكون سيارتك قريبة بما يكفي حتى لا تبرز إلى طريق السيارات.","h2":"في Florida يجب أن تكون عجلاتك على مسافة 12 بوصة أو أقل من الرصيف عندما تركن موازيًا له، حتى لا تسد سيارتك المسار.","p":"صحيح. اركن وعجلاتك على مسافة 12 بوصة أو أقل من الرصيف."},"ht":{"q":"Nan Florida, lè ou pake paralèl bò kote yon rebò twotwa, a ki distans wou ou yo dwe ye de rebò twotwa a?","o":["Nan 24 pous","Nan 36 pous","Nan 12 pous","Nan 6 pye"],"h1":"Machin ou dwe pre ase pou li pa depase nan wout kote machin yo ap pase.","h2":"Nan Florida wou ou yo dwe nan 12 pous de rebò twotwa a lè ou pake paralèl, pou machin ou pa bloke liy lan.","p":"Wi, se sa. Pake ak wou ou yo nan 12 pous de rebò twotwa a."},"ref":{"doc":"FL","page":65}},{"id":"speed-lanes-041","scope":"FL","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Florida, who may park in a space marked for people with disabilities?","o":["Anyone, if it is only for a few minutes","Anyone, if the lot is full","A driver with a valid disabled parking permit or plate shown","Any driver over 65 years old"],"h1":"These spaces are saved for people who have official proof.","h2":"Only a vehicle showing a valid disabled parking permit or license plate may park in a disabled space, even for a short time.","p":"Right. Disabled spaces are only for vehicles with a valid permit or plate."},"es":{"q":"En Florida, ¿quién puede estacionarse en un espacio para personas con discapacidad?","o":["Cualquiera, si es solo por unos minutos","Cualquiera, si el estacionamiento está lleno","Un conductor que muestre un permiso o placa válida de discapacidad","Cualquier conductor mayor de 65 años"],"h1":"Estos espacios son para personas que tienen un comprobante oficial.","h2":"Solo un vehículo que muestre un permiso o una placa válida de discapacidad puede estacionarse en ese espacio, aunque sea por poco tiempo.","p":"Correcto. Los espacios para personas con discapacidad son solo para vehículos con permiso o placa válida."},"zh":{"q":"在 Florida，谁可以停在残疾人专用车位？","o":["任何人，只要只停几分钟","任何人，只要停车场满了","展示有效残疾人停车证或车牌的司机","任何 65 岁以上的司机"],"h1":"这些车位是留给有正式证明的人的。","h2":"只有展示有效残疾人停车证或车牌的车，才可以停在残疾人车位，就算只停很短的时间也一样。","p":"对。残疾人车位只给有有效停车证或车牌的车用。"},"vi":{"q":"Ở Florida, ai được đậu xe ở chỗ dành cho người khuyết tật?","o":["Bất kỳ ai, nếu chỉ đậu vài phút","Bất kỳ ai, nếu bãi đậu xe đã đầy","Người lái có giấy phép đậu xe hoặc biển số xe người khuyết tật còn hiệu lực đang được trưng ra","Bất kỳ người lái nào trên 65 tuổi"],"h1":"Những chỗ này được giữ cho người có giấy tờ chính thức.","h2":"Chỉ xe có trưng giấy phép đậu xe hoặc biển số xe người khuyết tật còn hiệu lực mới được đậu ở chỗ dành cho người khuyết tật, dù chỉ trong thời gian ngắn.","p":"Đúng. Chỗ đậu cho người khuyết tật chỉ dành cho xe có giấy phép hoặc biển số còn hiệu lực."},"tl":{"q":"Sa Florida, sino ang puwedeng pumarada sa espasyong nakalaan para sa mga taong may kapansanan?","o":["Kahit sino, kung ilang minuto lang","Kahit sino, kung puno na ang paradahan","Drayber na may nakapakitang balidong disabled parking permit o plaka","Kahit sinong drayber na higit 65 taong gulang"],"h1":"Nakalaan ang mga espasyong ito para sa mga taong may opisyal na patunay.","h2":"Sasakyan lang na may nakapakitang balidong disabled parking permit o plaka ang puwedeng pumarada sa espasyo para sa may kapansanan, kahit sandali lang.","p":"Tama. Ang espasyo para sa may kapansanan ay para lang sa mga sasakyang may balidong permit o plaka."},"ar":{"q":"في Florida، من يمكنه أن يركن في مكان مخصص للأشخاص ذوي الإعاقة؟","o":["أي شخص، إذا كان لبضع دقائق فقط","أي شخص، إذا كان الموقف ممتلئًا","سائق يُظهر تصريح وقوف لذوي الإعاقة أو لوحة سارية","أي سائق عمره أكثر من 65 سنة"],"h1":"هذه الأماكن محجوزة للأشخاص الذين معهم إثبات رسمي.","h2":"فقط المركبة التي تُظهر تصريح وقوف لذوي الإعاقة أو لوحة سارية يمكنها أن تركن في مكان ذوي الإعاقة، حتى لوقت قصير.","p":"صحيح. أماكن ذوي الإعاقة فقط للمركبات التي معها تصريح أو لوحة سارية."},"ht":{"q":"Nan Florida, kiyès ki ka pake nan yon plas ki make pou moun andikape?","o":["Nenpòt moun, si se pou kèk minit sèlman","Nenpòt moun, si pakin lan plen","Yon chofè ki montre yon pèmi oswa yon plak pakin pou moun andikape ki valab","Nenpòt chofè ki gen plis pase 65 an"],"h1":"Plas sa yo rezève pou moun ki gen yon prèv ofisyèl.","h2":"Se sèlman yon machin ki montre yon pèmi oswa yon plak pakin pou moun andikape ki valab ki ka pake nan yon plas pou moun andikape, menm pou yon ti tan.","p":"Wi, se sa. Plas pou moun andikape yo se sèlman pou machin ki gen yon pèmi oswa yon plak ki valab."},"ref":{"doc":"FL","page":25}},{"id":"speed-lanes-042","scope":"FL","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Florida, can you park on the striped lines next to a disabled parking space?","o":["No, that area must stay clear for wheelchairs and lifts","Yes, if you have a permit","Yes, for up to 15 minutes","Yes, if you stay in the car"],"h1":"Think about what a person in a wheelchair needs to get out of a van.","h2":"You may not park on the striped area next to a disabled space, because it must stay clear for wheelchairs and lifts.","p":"Right. Never park on the striped access aisle."},"es":{"q":"En Florida, ¿puede estacionarse sobre las rayas al lado de un espacio para personas con discapacidad?","o":["No, esa área debe quedar libre para sillas de ruedas y plataformas elevadoras","Sí, si tiene permiso","Sí, hasta 15 minutos","Sí, si se queda dentro del carro"],"h1":"Piense en lo que necesita una persona en silla de ruedas para bajar de una camioneta.","h2":"No puede estacionarse en el área con rayas junto a un espacio para personas con discapacidad, porque debe quedar libre para sillas de ruedas y plataformas elevadoras.","p":"Correcto. Nunca se estacione en el pasillo con rayas."},"zh":{"q":"在 Florida，你可以停在残疾人车位旁边画了斜线的地方吗？","o":["不可以，那个地方必须留空给轮椅和升降设备","可以，只要你有停车证","可以，最多 15 分钟","可以，只要你留在车里"],"h1":"想一想，坐轮椅的人从厢式车里下来需要什么。","h2":"你不能停在残疾人车位旁边画了斜线的地方，因为那里必须留空给轮椅和升降设备。","p":"对。永远不要停在画了斜线的通道上。"},"vi":{"q":"Ở Florida, bạn có được đậu xe trên khu vực kẻ sọc cạnh chỗ đậu cho người khuyết tật không?","o":["Không, khu vực đó phải để trống cho xe lăn và bệ nâng","Có, nếu bạn có giấy phép","Có, tối đa 15 phút","Có, nếu bạn ngồi trong xe"],"h1":"Hãy nghĩ xem một người ngồi xe lăn cần gì để ra khỏi xe van.","h2":"Bạn không được đậu xe trên khu vực kẻ sọc cạnh chỗ đậu cho người khuyết tật, vì khu vực đó phải để trống cho xe lăn và bệ nâng.","p":"Đúng. Không bao giờ đậu xe trên lối đi kẻ sọc dành cho xe lăn."},"tl":{"q":"Sa Florida, puwede ka bang pumarada sa mga guhit-guhit na linya sa tabi ng parking space para sa may kapansanan?","o":["Hindi, dapat manatiling bakante ang lugar na iyon para sa wheelchair at lift","Oo, kung may permit ka","Oo, hanggang 15 minuto","Oo, kung mananatili ka sa loob ng kotse"],"h1":"Isipin ang kailangan ng taong naka-wheelchair para makababa sa van.","h2":"Hindi ka puwedeng pumarada sa lugar na may guhit-guhit sa tabi ng espasyo para sa may kapansanan, dahil dapat itong manatiling bakante para sa wheelchair at lift.","p":"Tama. Huwag kailanman pumarada sa guhit-guhit na daanan (access aisle)."},"ar":{"q":"في Florida، هل يمكنك أن تركن على الخطوط المخططة بجانب مكان وقوف ذوي الإعاقة؟","o":["لا، هذه المنطقة يجب أن تبقى فارغة للكراسي المتحركة والمصاعد","نعم، إذا كان معي تصريح","نعم، حتى 15 دقيقة","نعم، إذا بقيت في السيارة"],"h1":"فكّر ماذا يحتاج شخص على كرسي متحرك لينزل من شاحنة صغيرة.","h2":"لا يجوز أن تركن على المنطقة المخططة بجانب مكان ذوي الإعاقة، لأنها يجب أن تبقى فارغة للكراسي المتحركة والمصاعد.","p":"صحيح. لا تركن أبدًا على الممر المخطط بجانب مكان ذوي الإعاقة."},"ht":{"q":"Nan Florida, èske ou ka pake sou liy bawo ki bò kote yon plas pakin pou moun andikape?","o":["Non, zòn sa a dwe rete lib pou chèz woulant ak asansè machin yo","Wi, si ou gen yon pèmi","Wi, pou jiska 15 minit","Wi, si ou rete nan machin nan"],"h1":"Panse ak sa yon moun nan chèz woulant bezwen pou l sòti nan yon kamyonèt.","h2":"Ou pa ka pake sou zòn ki gen liy bawo bò kote yon plas pou moun andikape, paske li dwe rete lib pou chèz woulant ak asansè machin yo.","p":"Wi, se sa. Pa janm pake sou zòn ki gen liy bawo a."},"ref":{"doc":"FL","page":null}},{"id":"ak-001","scope":"AK","cat":"licensing","sign":null,"c":1,"en":{"q":"In Alaska, what is the youngest age to get an instruction permit?","o":["13 years old","14 years old","15 years old","16 years old"],"h1":"It is two years before the age for a provisional license.","h2":"In Alaska you can get an instruction permit when you turn 14, so you have time to practice before you can drive alone.","p":"Right. Alaska gives instruction permits starting at age 14."},"es":{"q":"En Alaska, ¿cuál es la edad mínima para obtener un permiso de instrucción?","o":["13 años","14 años","15 años","16 años"],"h1":"Es dos años antes de la edad para la licencia provisional.","h2":"En Alaska usted puede obtener el permiso de instrucción al cumplir 14 años, para tener tiempo de practicar antes de manejar solo.","p":"Correcto. Alaska da permisos de instrucción desde los 14 años."},"ref":{"doc":"AK","page":4}},{"id":"ak-002","scope":"AK","cat":"licensing","sign":null,"c":3,"en":{"q":"In Alaska, a driver with an instruction permit must have a licensed driver with them. How old must that driver be?","o":["At least 18 years old","At least 25 years old","At least 16 years old","At least 21 years old"],"h1":"The helper must be old enough to drink alcohol legally.","h2":"The person supervising you must be a licensed driver who is at least 21 years old, so that an experienced adult is beside you.","p":"Right. Your supervising driver must be 21 or older."},"es":{"q":"En Alaska, quien tiene permiso de instrucción debe ir con un conductor con licencia. ¿Qué edad debe tener ese conductor?","o":["Por lo menos 18 años","Por lo menos 25 años","Por lo menos 16 años","Por lo menos 21 años"],"h1":"El acompañante debe tener la edad legal para tomar alcohol.","h2":"La persona que lo supervisa debe ser un conductor con licencia de por lo menos 21 años, para que un adulto con experiencia vaya a su lado.","p":"Correcto. Su acompañante debe tener 21 años o más."},"ref":{"doc":"AK","page":4}},{"id":"ak-003","scope":"AK","cat":"licensing","sign":null,"c":2,"en":{"q":"In Alaska, how much driving experience must the supervising driver of a permit holder have?","o":["No experience is required","At least three months","At least one year in that kind of vehicle","At least five years in any vehicle"],"h1":"It is counted in years, and the type of vehicle matters.","h2":"The supervising driver needs at least one year of driving experience in the same kind of vehicle you are driving, so they know how to guide you.","p":"Right. The supervisor needs at least one year of experience in that kind of vehicle."},"es":{"q":"En Alaska, ¿cuánta experiencia debe tener el conductor que supervisa a quien tiene permiso?","o":["No se requiere experiencia","Por lo menos tres meses","Por lo menos un año en ese tipo de vehículo","Por lo menos cinco años en cualquier vehículo"],"h1":"Se cuenta en años, y el tipo de vehículo importa.","h2":"El conductor que lo supervisa necesita por lo menos un año de experiencia manejando el mismo tipo de vehículo que usted maneja, para saber cómo guiarlo.","p":"Correcto. El supervisor necesita por lo menos un año de experiencia en ese tipo de vehículo."},"ref":{"doc":"AK","page":4}},{"id":"ak-004","scope":"AK","cat":"licensing","sign":null,"c":0,"en":{"q":"In Alaska, where must the supervising driver sit when a permit holder is driving?","o":["In the front passenger seat","In any back seat","Anywhere in the vehicle","In the seat behind the driver"],"h1":"They must be able to reach you and see the road as you do.","h2":"The supervising driver must sit in the front passenger seat the whole time, so they can watch the road and help you right away.","p":"Right. The supervisor always sits in the front passenger seat."},"es":{"q":"En Alaska, ¿dónde debe sentarse el conductor supervisor cuando maneja alguien con permiso?","o":["En el asiento del pasajero de adelante","En cualquier asiento de atrás","En cualquier lugar del vehículo","En el asiento detrás del conductor"],"h1":"Debe poder alcanzarlo a usted y ver el camino como usted.","h2":"El conductor supervisor debe ir todo el tiempo en el asiento del pasajero de adelante, para mirar el camino y ayudarle enseguida.","p":"Correcto. El supervisor siempre va en el asiento del pasajero de adelante."},"ref":{"doc":"AK","page":4}},{"id":"ak-005","scope":"AK","cat":"licensing","sign":null,"c":2,"en":{"q":"In Alaska, how long is an instruction permit valid?","o":["Six months, with no renewal","One year, renewable many times","Two years, renewable one time","Five years, with no renewal"],"h1":"It lasts a little longer than one year, and you get one more chance.","h2":"An Alaska instruction permit is good for two years, and you may renew it one time if you need more practice.","p":"Right. The permit lasts two years and can be renewed once."},"es":{"q":"En Alaska, ¿por cuánto tiempo es válido el permiso de instrucción?","o":["Seis meses, sin renovación","Un año, renovable muchas veces","Dos años, renovable una vez","Cinco años, sin renovación"],"h1":"Dura un poco más de un año, y usted tiene una oportunidad más.","h2":"El permiso de instrucción de Alaska es válido por dos años, y usted puede renovarlo una vez si necesita más práctica.","p":"Correcto. El permiso dura dos años y se puede renovar una vez."},"ref":{"doc":"AK","page":4}},{"id":"ak-006","scope":"AK","cat":"licensing","sign":null,"c":1,"en":{"q":"In Alaska, what must a teen under 18 bring to apply for an instruction permit?","o":["A letter from a teacher","A consent form signed by a parent or guardian","A completed driving school course","Proof of a part-time job"],"h1":"An adult who is responsible for you has to agree.","h2":"A teen under 18 needs a consent form signed by a parent or guardian, because that adult agrees to take responsibility for the new driver.","p":"Right. A parent or guardian must sign a consent form."},"es":{"q":"En Alaska, ¿qué debe llevar un joven menor de 18 años para solicitar el permiso de instrucción?","o":["Una carta de un maestro","Un formulario de consentimiento firmado por su padre, madre o tutor","Un curso de manejo terminado","Prueba de un trabajo de medio tiempo"],"h1":"Un adulto responsable de usted tiene que estar de acuerdo.","h2":"Un joven menor de 18 años necesita un formulario de consentimiento firmado por su padre, madre o tutor, porque ese adulto acepta la responsabilidad del nuevo conductor.","p":"Correcto. Su padre, madre o tutor debe firmar un formulario de consentimiento."},"ref":{"doc":"AK","page":3}},{"id":"ak-007","scope":"AK","cat":"licensing","sign":null,"c":3,"en":{"q":"In Alaska, how long must a teen hold an instruction permit before getting a provisional license?","o":["One month","Three months","One year","Six months"],"h1":"It is half of a year.","h2":"A teen must hold the instruction permit for at least six months before getting a provisional license, so there is enough time to practice.","p":"Right. You must hold the permit for at least six months."},"es":{"q":"En Alaska, ¿cuánto tiempo debe tener un joven el permiso de instrucción antes de obtener la licencia provisional?","o":["Un mes","Tres meses","Un año","Seis meses"],"h1":"Es la mitad de un año.","h2":"Un joven debe tener el permiso de instrucción por lo menos seis meses antes de obtener la licencia provisional, para tener tiempo suficiente de practicar.","p":"Correcto. Debe tener el permiso por lo menos seis meses."},"ref":{"doc":"AK","page":4}},{"id":"ak-008","scope":"AK","cat":"licensing","sign":null,"c":0,"en":{"q":"In Alaska, how many hours of supervised driving must a teen complete before a provisional license?","o":["40 hours","20 hours","60 hours","100 hours"],"h1":"It is more than 30 and less than 50.","h2":"A teen needs at least 40 hours of supervised driving practice before getting a provisional license, to build real experience on the road.","p":"Right. Alaska asks for at least 40 hours of supervised driving."},"es":{"q":"En Alaska, ¿cuántas horas de manejo supervisado debe completar un joven antes de la licencia provisional?","o":["40 horas","20 horas","60 horas","100 horas"],"h1":"Es más de 30 y menos de 50.","h2":"Un joven necesita por lo menos 40 horas de práctica supervisada antes de obtener la licencia provisional, para ganar experiencia real en el camino.","p":"Correcto. Alaska pide por lo menos 40 horas de manejo supervisado."},"ref":{"doc":"AK","page":5}},{"id":"ak-009","scope":"AK","cat":"licensing","sign":null,"c":2,"en":{"q":"In Alaska, how many of the required supervised hours must be in challenging conditions, such as at night or in bad weather?","o":["At least 5 hours","At least 15 hours","At least 10 hours","At least 20 hours"],"h1":"It is one quarter of the total hours.","h2":"At least 10 of the supervised hours must be in harder conditions, such as darkness or bad weather, so a new driver has practiced them with help.","p":"Right. At least 10 hours must be at night or in bad weather."},"es":{"q":"En Alaska, ¿cuántas de las horas supervisadas deben ser en condiciones difíciles, como de noche o con mal tiempo?","o":["Por lo menos 5 horas","Por lo menos 15 horas","Por lo menos 10 horas","Por lo menos 20 horas"],"h1":"Es la cuarta parte del total de horas.","h2":"Por lo menos 10 de las horas supervisadas deben ser en condiciones más difíciles, como de noche o con mal tiempo, para que el conductor nuevo las practique con ayuda.","p":"Correcto. Por lo menos 10 horas deben ser de noche o con mal tiempo."},"ref":{"doc":"AK","page":5}},{"id":"ak-010","scope":"AK","cat":"licensing","sign":null,"c":1,"en":{"q":"In Alaska, what is the youngest age to get a provisional license?","o":["15 years old","16 years old","17 years old","18 years old"],"h1":"It is two years after the youngest permit age.","h2":"You can get a provisional license at 16, after you have held your permit long enough and finished your practice hours.","p":"Right. The provisional license starts at age 16."},"es":{"q":"En Alaska, ¿cuál es la edad mínima para obtener una licencia provisional?","o":["15 años","16 años","17 años","18 años"],"h1":"Es dos años después de la edad mínima del permiso.","h2":"Usted puede obtener la licencia provisional a los 16 años, después de tener el permiso el tiempo necesario y terminar sus horas de práctica.","p":"Correcto. La licencia provisional empieza a los 16 años."},"ref":{"doc":"AK","page":5}},{"id":"ak-011","scope":"AK","cat":"licensing","sign":null,"c":3,"en":{"q":"In Alaska, during which hours may a provisional driver not drive alone, unless driving for work?","o":["10 p.m. to 5 a.m.","11 p.m. to 6 a.m.","Midnight to 6 a.m.","1 a.m. to 5 a.m."],"h1":"The limit starts after midnight and ends before sunrise in most seasons.","h2":"A provisional driver may not drive between 1 a.m. and 5 a.m. unless a licensed driver age 21 or older is in the car or the trip is for work.","p":"Right. Provisional drivers stay off the road from 1 a.m. to 5 a.m."},"es":{"q":"En Alaska, ¿en qué horario no puede manejar un conductor con licencia provisional, salvo por trabajo?","o":["De 10 p.m. a 5 a.m.","De 11 p.m. a 6 a.m.","De medianoche a 6 a.m.","De 1 a.m. a 5 a.m."],"h1":"El límite empieza después de la medianoche y termina antes del amanecer en casi todas las estaciones.","h2":"Un conductor con licencia provisional no puede manejar entre la 1 a.m. y las 5 a.m., salvo que vaya con un conductor con licencia de 21 años o más, o que el viaje sea por trabajo.","p":"Correcto. Los conductores provisionales no manejan de 1 a.m. a 5 a.m."},"ref":{"doc":"AK","page":6}},{"id":"ak-012","scope":"AK","cat":"licensing","sign":null,"c":0,"en":{"q":"In Alaska, which trip is allowed for a provisional driver during the restricted night hours, even with no adult in the car?","o":["Driving to or from a job","Driving to a friend’s house","Driving to a late movie","Driving to a store"],"h1":"The exception is about earning a living.","h2":"A provisional driver may drive during the restricted hours when going to or from work, or as part of a job, using the most direct route.","p":"Right. Driving to or from work is the exception."},"es":{"q":"En Alaska, ¿qué viaje se permite a un conductor provisional en las horas restringidas de la noche, aun sin un adulto en el carro?","o":["Ir o volver del trabajo","Ir a la casa de un amigo","Ir a una película tarde","Ir a una tienda"],"h1":"La excepción tiene que ver con ganarse la vida.","h2":"Un conductor provisional puede manejar en las horas restringidas cuando va o vuelve del trabajo, o como parte de su trabajo, por la ruta más directa.","p":"Correcto. Ir o volver del trabajo es la excepción."},"ref":{"doc":"AK","page":6}},{"id":"ak-013","scope":"AK","cat":"licensing","sign":null,"c":2,"en":{"q":"In Alaska, which passengers may a provisional driver carry with no adult supervisor in the car?","o":["Any friends under 18","Up to three passengers of any age","Passengers 21 or older, and siblings","Only passengers under 16"],"h1":"Young passengers are limited, but family has an exception.","h2":"Unless a parent, guardian, or another person age 21 or older is riding along, a provisional driver may not carry passengers under 21, except brothers and sisters.","p":"Right. Passengers under 21 are not allowed, except siblings."},"es":{"q":"En Alaska, ¿a qué pasajeros puede llevar un conductor provisional sin un adulto supervisor en el carro?","o":["A cualquier amigo menor de 18","Hasta tres pasajeros de cualquier edad","Pasajeros de 21 años o más, y hermanos","Solo pasajeros menores de 16"],"h1":"Los pasajeros jóvenes están limitados, pero la familia tiene una excepción.","h2":"A menos que vaya con usted su padre, madre, tutor u otra persona de 21 años o más, un conductor provisional no puede llevar pasajeros menores de 21 años, excepto a sus hermanos.","p":"Correcto. No se permiten pasajeros menores de 21, excepto hermanos."},"ref":{"doc":"AK","page":6}},{"id":"ak-014","scope":"AK","cat":"licensing","sign":null,"c":1,"en":{"q":"In Alaska, when do the provisional license limits end?","o":["After one month with no crash","At age 18, or after six months with no violations","Only at age 21","After the driver passes a second road test"],"h1":"There are two ways: an age and a clean record.","h2":"The provisional limits end when you turn 18, or after six months on the provisional license with no violations, when you ask the DMV to remove them.","p":"Right. The limits end at 18 or after six clean months."},"es":{"q":"En Alaska, ¿cuándo terminan las restricciones de la licencia provisional?","o":["Después de un mes sin choques","A los 18 años, o después de seis meses sin infracciones","Solo a los 21 años","Después de pasar un segundo examen de manejo"],"h1":"Hay dos caminos: una edad y un récord limpio.","h2":"Las restricciones provisionales terminan cuando usted cumple 18 años, o después de seis meses con la licencia provisional sin infracciones, cuando usted pide al DMV que las quite.","p":"Correcto. Terminan a los 18 o después de seis meses sin infracciones."},"ref":{"doc":"AK","page":6}},{"id":"ak-015","scope":"AK","cat":"licensing","sign":null,"c":2,"en":{"q":"In Alaska, how many questions are on the general knowledge test for a driver license?","o":["10 questions","25 questions","20 questions","30 questions"],"h1":"It is a round number between 15 and 25.","h2":"The Alaska general knowledge test has 20 questions, so each one counts for a lot.","p":"Right. The Alaska knowledge test has 20 questions."},"es":{"q":"En Alaska, ¿cuántas preguntas tiene el examen de conocimientos generales para la licencia?","o":["10 preguntas","25 preguntas","20 preguntas","30 preguntas"],"h1":"Es un número redondo entre 15 y 25.","h2":"El examen de conocimientos generales de Alaska tiene 20 preguntas, así que cada una cuenta mucho.","p":"Correcto. El examen de conocimientos de Alaska tiene 20 preguntas."},"ref":{"doc":"AK","page":null}},{"id":"ak-016","scope":"AK","cat":"licensing","sign":null,"c":0,"en":{"q":"In Alaska, how many correct answers do you need to pass the general knowledge test?","o":["16 correct answers","14 correct answers","18 correct answers","12 correct answers"],"h1":"You need 80 percent of the questions right.","h2":"You must answer at least 16 questions correctly to pass, which is 80 percent of the test.","p":"Right. You need 16 correct answers to pass."},"es":{"q":"En Alaska, ¿cuántas respuestas correctas necesita para aprobar el examen de conocimientos generales?","o":["16 respuestas correctas","14 respuestas correctas","18 respuestas correctas","12 respuestas correctas"],"h1":"Necesita el 80 por ciento de las preguntas bien.","h2":"Usted debe contestar bien por lo menos 16 preguntas para aprobar, que es el 80 por ciento del examen.","p":"Correcto. Necesita 16 respuestas correctas para aprobar."},"ref":{"doc":"AK","page":null}},{"id":"ak-017","scope":"AK","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Alaska, if no sign shows a different limit, what is the top speed in a residential district?","o":["20 mph","25 mph","30 mph","35 mph"],"h1":"It is a little faster than in a business district.","h2":"Unless a sign says otherwise, the top legal speed in a residential district is 25 mph, because children and walkers are often near the road.","p":"Right. The default limit in a residential district is 25 mph."},"es":{"q":"En Alaska, si ninguna señal indica otro límite, ¿cuál es la velocidad máxima en una zona residencial?","o":["20 mph","25 mph","30 mph","35 mph"],"h1":"Es un poco más rápido que en una zona comercial.","h2":"Salvo que una señal diga otra cosa, la velocidad máxima legal en una zona residencial es 25 mph, porque a menudo hay niños y peatones cerca del camino.","p":"Correcto. El límite normal en una zona residencial es 25 mph."},"ref":{"doc":"AK","page":29}},{"id":"ak-018","scope":"AK","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Alaska, if no sign shows a different limit, what is the top speed in a business district?","o":["20 mph","15 mph","30 mph","25 mph"],"h1":"It is slower than a residential district.","h2":"Unless a sign says otherwise, the top legal speed in a business district is 20 mph, because traffic, parking and people on foot are very close together.","p":"Right. The default limit in a business district is 20 mph."},"es":{"q":"En Alaska, si ninguna señal indica otro límite, ¿cuál es la velocidad máxima en una zona comercial?","o":["20 mph","15 mph","30 mph","25 mph"],"h1":"Es más lento que en una zona residencial.","h2":"Salvo que una señal diga otra cosa, la velocidad máxima legal en una zona comercial es 20 mph, porque el tráfico, los carros estacionados y los peatones están muy cerca.","p":"Correcto. El límite normal en una zona comercial es 20 mph."},"ref":{"doc":"AK","page":29}},{"id":"ak-019","scope":"AK","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Alaska, if no sign shows a different limit, what is the top speed in an alley?","o":["5 mph","10 mph","20 mph","15 mph"],"h1":"It is the lowest of the default limits, but more than 10.","h2":"Unless a sign says otherwise, the top legal speed in an alley is 15 mph, because alleys are narrow and you cannot see far.","p":"Right. The default limit in an alley is 15 mph."},"es":{"q":"En Alaska, si ninguna señal indica otro límite, ¿cuál es la velocidad máxima en un callejón?","o":["5 mph","10 mph","20 mph","15 mph"],"h1":"Es el más bajo de los límites normales, pero más de 10.","h2":"Salvo que una señal diga otra cosa, la velocidad máxima legal en un callejón es 15 mph, porque los callejones son angostos y no se ve lejos.","p":"Correcto. El límite normal en un callejón es 15 mph."},"ref":{"doc":"AK","page":29}},{"id":"ak-020","scope":"AK","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Alaska, on a road outside business and residential districts with no speed sign, what is the top legal speed?","o":["45 mph","50 mph","55 mph","65 mph"],"h1":"Higher limits on some highways must be posted on signs.","h2":"When no sign shows a limit on other roads, the top legal speed is 55 mph; faster limits apply only where signs post them.","p":"Right. The default limit on other roads is 55 mph."},"es":{"q":"En Alaska, en un camino fuera de zonas comerciales y residenciales y sin señal de velocidad, ¿cuál es la velocidad máxima legal?","o":["45 mph","50 mph","55 mph","65 mph"],"h1":"Los límites más altos en algunas carreteras deben estar en señales.","h2":"Cuando ninguna señal indica el límite en otros caminos, la velocidad máxima legal es 55 mph; los límites más altos solo aplican donde hay señales.","p":"Correcto. El límite normal en otros caminos es 55 mph."},"ref":{"doc":"AK","page":29}},{"id":"ak-021","scope":"AK","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Alaska, during which time must you have your headlights on?","o":["Only when it is fully dark outside","From half an hour after sunset to half an hour before sunrise","From one hour after sunset to sunrise","Only on highways with more than two lanes"],"h1":"The rule adds a short time around sunset and sunrise.","h2":"You must use your headlights from half an hour after sunset until half an hour before sunrise, so others can see you in low light.","p":"Right. Lights go on half an hour after sunset until half an hour before sunrise."},"es":{"q":"En Alaska, ¿en qué horario debe llevar las luces delanteras encendidas?","o":["Solo cuando está totalmente oscuro","Desde media hora después de la puesta del sol hasta media hora antes del amanecer","Desde una hora después de la puesta del sol hasta el amanecer","Solo en carreteras de más de dos carriles"],"h1":"La regla agrega un rato corto alrededor de la puesta del sol y el amanecer.","h2":"Usted debe usar las luces delanteras desde media hora después de la puesta del sol hasta media hora antes del amanecer, para que otros lo vean con poca luz.","p":"Correcto. Las luces van encendidas desde media hora después de la puesta del sol hasta media hora antes del amanecer."},"ref":{"doc":"AK","page":55}},{"id":"ak-022","scope":"AK","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Alaska, you must also turn on your headlights when you cannot clearly see people or vehicles at what distance?","o":["500 feet","200 feet","1,500 feet","1,000 feet"],"h1":"It is a round number, about three football fields.","h2":"You must turn on your headlights any time fog, snow or low light keeps you from clearly seeing people or vehicles 1,000 feet away.","p":"Right. If you cannot see clearly at 1,000 feet, turn your lights on."},"es":{"q":"En Alaska, también debe encender las luces delanteras cuando no puede ver bien a personas o vehículos. ¿A qué distancia?","o":["500 pies","200 pies","1,500 pies","1,000 pies"],"h1":"Es un número redondo, como tres canchas de fútbol americano.","h2":"Usted debe encender las luces delanteras siempre que la niebla, la nieve o la poca luz no le dejen ver bien a personas o vehículos a 1,000 pies.","p":"Correcto. Si no ve bien a 1,000 pies, encienda las luces."},"ref":{"doc":"AK","page":55}},{"id":"ak-023","scope":"AK","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Alaska, you are driving slowly on a two-lane road outside a city. How many vehicles lined up behind you mean you must pull over at the first safe place?","o":["Two vehicles","Three vehicles","Five vehicles","Ten vehicles"],"h1":"It is the number of fingers on one hand.","h2":"When five or more vehicles are lined up right behind you on a two-lane road outside a city, you must pull off the road at the first safe place to let them by.","p":"Right. Five or more vehicles behind you means you pull over at the first safe place."},"es":{"q":"En Alaska, usted maneja despacio en un camino de dos carriles fuera de la ciudad. ¿Cuántos vehículos en fila detrás de usted lo obligan a orillarse en el primer lugar seguro?","o":["Dos vehículos","Tres vehículos","Cinco vehículos","Diez vehículos"],"h1":"Es el número de dedos de una mano.","h2":"Cuando cinco o más vehículos van en fila justo detrás de usted en un camino de dos carriles fuera de la ciudad, usted debe salirse del camino en el primer lugar seguro para dejarlos pasar.","p":"Correcto. Con cinco o más vehículos detrás, oríllese en el primer lugar seguro."},"ref":{"doc":"AK","page":27}},{"id":"ak-024","scope":"AK","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Alaska, a school bus ahead has stopped with its red lights flashing. How far from the bus must you stop?","o":["At least 30 feet","At least 10 feet","At least 20 feet","At least 50 feet"],"h1":"Alaska asks for more room than many states.","h2":"You must stop at least 30 feet from a school bus with flashing red lights and wait until the lights stop and the bus moves.","p":"Right. Stop at least 30 feet from the bus."},"es":{"q":"En Alaska, un autobús escolar adelante se detuvo con las luces rojas intermitentes. ¿A qué distancia del autobús debe detenerse?","o":["Por lo menos a 30 pies","Por lo menos a 10 pies","Por lo menos a 20 pies","Por lo menos a 50 pies"],"h1":"Alaska pide más espacio que muchos estados.","h2":"Usted debe detenerse por lo menos a 30 pies de un autobús escolar con luces rojas intermitentes y esperar a que se apaguen las luces y el autobús avance.","p":"Correcto. Deténgase por lo menos a 30 pies del autobús."},"ref":{"doc":"AK","page":null}},{"id":"ak-025","scope":"AK","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Alaska, on a road with two lanes going your way, you see a stopped police car with flashing lights. What should you do?","o":["Keep the same lane and speed","Move to the farther lane if it is safe, or else slow down","Stop next to the police car","Speed up to pass it quickly"],"h1":"Give the officer more room, or more time.","h2":"You must move away from the stopped emergency vehicle into another lane when it is safe; if you cannot, you must slow down as you pass.","p":"Right. Move over if it is safe, or slow down."},"es":{"q":"En Alaska, en un camino con dos carriles en su dirección, usted ve un carro de policía detenido con luces intermitentes. ¿Qué debe hacer?","o":["Seguir en el mismo carril y a la misma velocidad","Pasarse al carril más lejano si es seguro, o si no, bajar la velocidad","Detenerse al lado del carro de policía","Acelerar para pasarlo rápido"],"h1":"Déle al oficial más espacio, o más tiempo.","h2":"Usted debe alejarse del vehículo de emergencia detenido pasándose a otro carril cuando sea seguro; si no puede, debe bajar la velocidad al pasar.","p":"Correcto. Cámbiese de carril si es seguro, o baje la velocidad."},"ref":{"doc":"AK","page":64}},{"id":"ak-026","scope":"AK","cat":"signals","sign":null,"c":2,"en":{"q":"In Alaska, you are stopped at a red light and want to turn right. There is no sign about turning. What may you do?","o":["Turn right without stopping","Wait for the light to turn green","Turn right after a full stop, yielding to people and traffic","Turn right only if a police officer waves you on"],"h1":"Alaska allows it, but only after you do one thing first.","h2":"You may turn right on red after you come to a full stop and yield to people walking and to other traffic, unless a sign forbids the turn.","p":"Right. Stop fully, yield, and then you may turn right on red."},"es":{"q":"En Alaska, usted está detenido en una luz roja y quiere doblar a la derecha. No hay señal sobre la vuelta. ¿Qué puede hacer?","o":["Doblar a la derecha sin detenerse","Esperar a que la luz cambie a verde","Doblar a la derecha después de un alto total, cediendo el paso a peatones y tráfico","Doblar a la derecha solo si un policía le hace señas"],"h1":"Alaska lo permite, pero solo después de hacer algo primero.","h2":"Usted puede doblar a la derecha con luz roja después de hacer un alto total y ceder el paso a los peatones y al tráfico, salvo que una señal lo prohíba.","p":"Correcto. Haga un alto total, ceda el paso y luego puede doblar a la derecha con luz roja."},"ref":{"doc":"AK","page":50}},{"id":"ak-027","scope":"AK","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Alaska, what is against the law for every driver while the vehicle is moving?","o":["Reading or typing a text message","Listening to the radio","Talking with a passenger","Using the heater"],"h1":"It means taking your eyes off the road to read or write.","h2":"Alaska forbids any driver from reading or typing a text or other written message on a device while the vehicle is moving, because it pulls your eyes off the road.","p":"Right. Reading or typing texts while moving is against the law."},"es":{"q":"En Alaska, ¿qué está prohibido para todo conductor mientras el vehículo está en movimiento?","o":["Leer o escribir un mensaje de texto","Escuchar la radio","Hablar con un pasajero","Usar la calefacción"],"h1":"Se trata de quitar la vista del camino para leer o escribir.","h2":"Alaska prohíbe a todo conductor leer o escribir un texto u otro mensaje escrito en un aparato mientras el vehículo se mueve, porque le quita la vista del camino.","p":"Correcto. Leer o escribir textos en movimiento va contra la ley."},"ref":{"doc":"AK","page":26}},{"id":"ak-028","scope":"AK","cat":"licensing","sign":null,"c":3,"en":{"q":"In Alaska, a driver age 21 or older is legally drunk at what blood alcohol level?","o":["0.10 percent or more","0.05 percent or more","0.12 percent or more","0.08 percent or more"],"h1":"It is less than one tenth of one percent.","h2":"A driver 21 or older with a blood alcohol level of 0.08 percent or more is considered to be driving under the influence.","p":"Right. The limit for adults is 0.08 percent."},"es":{"q":"En Alaska, ¿con qué nivel de alcohol en la sangre se considera legalmente ebrio a un conductor de 21 años o más?","o":["0.10 por ciento o más","0.05 por ciento o más","0.12 por ciento o más","0.08 por ciento o más"],"h1":"Es menos de una décima de uno por ciento.","h2":"Un conductor de 21 años o más con 0.08 por ciento o más de alcohol en la sangre se considera que maneja bajo la influencia del alcohol.","p":"Correcto. El límite para adultos es 0.08 por ciento."},"ref":{"doc":"AK","page":16}},{"id":"ak-029","scope":"AK","cat":"licensing","sign":null,"c":1,"en":{"q":"In Alaska, how much alcohol may a driver under 21 have in their body?","o":["Up to 0.08 percent","None that can be detected","Up to 0.05 percent","One drink per hour"],"h1":"This is called zero tolerance.","h2":"Alaska has zero tolerance for drivers under 21, so any amount of alcohol that a test can find in their body breaks the law.","p":"Right. Drivers under 21 may have no detectable alcohol."},"es":{"q":"En Alaska, ¿cuánto alcohol puede tener en el cuerpo un conductor menor de 21 años?","o":["Hasta 0.08 por ciento","Nada que se pueda detectar","Hasta 0.05 por ciento","Un trago por hora"],"h1":"Esto se llama tolerancia cero.","h2":"Alaska tiene tolerancia cero para conductores menores de 21 años, así que cualquier cantidad de alcohol que una prueba encuentre en su cuerpo viola la ley.","p":"Correcto. Los menores de 21 no pueden tener alcohol detectable."},"ref":{"doc":"AK","page":16}},{"id":"ak-030","scope":"AK","cat":"licensing","sign":null,"c":0,"en":{"q":"In Alaska, what happens if a driver stopped for drunk driving refuses a breath test?","o":["Refusing is a separate crime with its own penalties","Nothing, because the test is optional","The driver gets a warning only","The driver must take a written test instead"],"h1":"By driving, you already agreed to be tested.","h2":"By driving in Alaska you have already agreed to be tested, so refusing the test is a separate crime, charged on top of drunk driving.","p":"Right. Refusing the test is a crime of its own."},"es":{"q":"En Alaska, ¿qué pasa si un conductor detenido por manejar ebrio se niega a la prueba de aliento?","o":["Negarse es un delito aparte con sus propias sanciones","Nada, porque la prueba es opcional","El conductor recibe solo una advertencia","El conductor debe hacer un examen escrito en su lugar"],"h1":"Al manejar, usted ya aceptó hacerse la prueba.","h2":"Al manejar en Alaska, usted ya aceptó hacerse la prueba, así que negarse es un delito aparte, que se suma al cargo por manejar ebrio.","p":"Correcto. Negarse a la prueba es un delito aparte."},"ref":{"doc":"AK","page":14}},{"id":"ak-031","scope":"AK","cat":"licensing","sign":null,"c":2,"en":{"q":"In Alaska, what is the minimum liability insurance a car owner must carry?","o":["$15,000 / $30,000 / $10,000","$25,000 / $50,000 / $25,000","$50,000 / $100,000 / $25,000","$100,000 / $300,000 / $100,000"],"h1":"Alaska asks for more than many states for injuries.","h2":"Alaska requires at least $50,000 for injury to one person, $100,000 for injuries in one crash, and $25,000 for property damage.","p":"Right. Alaska minimums are 50/100/25."},"es":{"q":"En Alaska, ¿cuál es el seguro mínimo de responsabilidad que debe tener el dueño de un carro?","o":["$15,000 / $30,000 / $10,000","$25,000 / $50,000 / $25,000","$50,000 / $100,000 / $25,000","$100,000 / $300,000 / $100,000"],"h1":"Alaska pide más que muchos estados para lesiones.","h2":"Alaska exige por lo menos $50,000 por lesiones a una persona, $100,000 por lesiones en un choque y $25,000 por daños a la propiedad.","p":"Correcto. Los mínimos en Alaska son 50/100/25."},"ref":{"doc":"AK","page":10}},{"id":"al-001","scope":"AL","cat":"licensing","sign":null,"c":1,"en":{"q":"In Alabama, what is the youngest age to get a Stage I learner license?","o":["14 years old","15 years old","16 years old","17 years old"],"h1":"It comes one year before the age when teens can start driving alone.","h2":"In Alabama you can get a Stage I learner license at age 15, so you can practice for a year before you may drive alone at 16.","p":"Right. The Alabama learner license starts at age 15."},"es":{"q":"En Alabama, ¿cuál es la edad mínima para obtener la licencia de aprendiz Etapa I?","o":["14 años","15 años","16 años","17 años"],"h1":"Es un año antes de la edad en que los jóvenes pueden empezar a manejar solos.","h2":"En Alabama usted puede obtener la licencia de aprendiz Etapa I a los 15 años, para practicar un año antes de poder manejar solo a los 16.","p":"Correcto. La licencia de aprendiz en Alabama empieza a los 15 años."},"ref":{"doc":"AL","page":9}},{"id":"al-002","scope":"AL","cat":"licensing","sign":null,"c":3,"en":{"q":"In Alabama, who may sit beside a 15-year-old with a Stage I learner license while they drive?","o":["Any friend who has a license","Any passenger age 16 or older","A licensed driver age 18 or older","A parent, guardian, or licensed driver age 21+"],"h1":"The helper must be an experienced adult, not a young friend.","h2":"A 15-year-old Alabama learner must drive with a parent, a legal guardian, or a licensed driver who is at least 21 in the front seat, because a new driver needs an experienced adult close by.","p":"Right. The person beside you is a parent, guardian, or licensed driver age 21 or older."},"es":{"q":"En Alabama, ¿quién puede ir sentado al lado de un joven de 15 años con licencia de aprendiz Etapa I mientras maneja?","o":["Cualquier amigo que tenga licencia","Cualquier pasajero de 16 años o más","Un conductor con licencia de 18 años o más","Un padre, tutor o conductor con licencia de 21+"],"h1":"El acompañante debe ser un adulto con experiencia, no un amigo joven.","h2":"En Alabama un aprendiz de 15 años debe manejar con un padre, un tutor legal o un conductor con licencia de por lo menos 21 años en el asiento delantero, porque un conductor nuevo necesita a un adulto con experiencia a su lado.","p":"Correcto. A su lado va un padre, un tutor o un conductor con licencia de 21 años o más."},"ref":{"doc":"AL","page":9}},{"id":"al-003","scope":"AL","cat":"licensing","sign":null,"c":2,"en":{"q":"In Alabama, a driver under 18 must hold a Stage I learner license for how long before applying for Stage II?","o":["At least 1 month","At least 3 months","At least 6 months","At least 12 months"],"h1":"It is half a year.","h2":"In Alabama a driver under 18 must hold the Stage I license for at least six months before applying for Stage II, so there is time to practice with an adult.","p":"Right. Hold the learner license for at least six months first."},"es":{"q":"En Alabama, un conductor menor de 18 años debe tener la licencia de aprendiz Etapa I, ¿por cuánto tiempo antes de solicitar la Etapa II?","o":["Por lo menos 1 mes","Por lo menos 3 meses","Por lo menos 6 meses","Por lo menos 12 meses"],"h1":"Es medio año.","h2":"En Alabama un conductor menor de 18 años debe tener la licencia de Etapa I por lo menos seis meses antes de solicitar la Etapa II, para tener tiempo de practicar con un adulto.","p":"Correcto. Primero debe tener la licencia de aprendiz por lo menos seis meses."},"ref":{"doc":"AL","page":10}},{"id":"al-004","scope":"AL","cat":"licensing","sign":null,"c":0,"en":{"q":"In Alabama, a Stage II (restricted) driver may carry how many passengers who are not parents, guardians, or family members?","o":["No more than one","No more than two","No more than three","Any number with seat belts"],"h1":"The limit is the smallest number above zero.","h2":"An Alabama Stage II driver may not carry more than one passenger besides parents, legal guardians, or family members, because friends in the car raise the risk of a crash for new drivers.","p":"Right. Only one passenger who is not family."},"es":{"q":"En Alabama, un conductor de Etapa II (restringida), ¿cuántos pasajeros puede llevar que no sean padres, tutores ni familiares?","o":["No más de uno","No más de dos","No más de tres","Cualquier número con cinturón"],"h1":"El límite es el número más pequeño mayor que cero.","h2":"En Alabama un conductor de Etapa II no puede llevar más de un pasajero aparte de sus padres, tutores legales o familiares, porque los amigos en el carro aumentan el riesgo de choque para los conductores nuevos.","p":"Correcto. Solo un pasajero que no sea de la familia."},"ref":{"doc":"AL","page":null}},{"id":"al-005","scope":"AL","cat":"licensing","sign":null,"c":2,"en":{"q":"In Alabama, during which hours may a Stage II driver not drive unless a parent, guardian, or licensed adult 21+ is with them (outside the listed exceptions)?","o":["From 9 p.m. to 5 a.m.","From 10 p.m. to 6 a.m.","From midnight to 6 a.m.","From 1 a.m. to 5 a.m."],"h1":"It starts when the date changes and ends at dawn.","h2":"An Alabama Stage II driver may not drive between midnight and 6 a.m. unless a parent, a legal guardian, or a licensed driver age 21 or older is in the car, because late-night driving is the most dangerous for new drivers.","p":"Right. No driving from midnight to 6 a.m. without an adult."},"es":{"q":"En Alabama, ¿en qué horario un conductor de Etapa II no puede manejar si no lo acompaña un padre, tutor o adulto con licencia de 21+ (fuera de las excepciones)?","o":["De 9 p.m. a 5 a.m.","De 10 p.m. a 6 a.m.","De medianoche a 6 a.m.","De 1 a.m. a 5 a.m."],"h1":"Empieza cuando cambia la fecha y termina al amanecer.","h2":"En Alabama un conductor de Etapa II no puede manejar entre la medianoche y las 6 a.m. si no va con él un padre, un tutor legal o un conductor con licencia de 21 años o más, porque manejar de madrugada es lo más peligroso para un conductor nuevo.","p":"Correcto. No se maneja de medianoche a 6 a.m. sin un adulto."},"ref":{"doc":"AL","page":null}},{"id":"al-006","scope":"AL","cat":"licensing","sign":null,"c":0,"en":{"q":"In Alabama, which trip is an exception that lets a Stage II driver drive alone between midnight and 6 a.m.?","o":["Going to or from work","Going to a friend's house","Driving to a restaurant","Practicing on empty roads"],"h1":"Think of a trip that a teen must make, not one for fun.","h2":"An Alabama Stage II driver may drive alone late at night when going to or from work, because the law allows needed trips such as work, school events, religious events, and emergencies.","p":"Right. A trip to or from work is allowed."},"es":{"q":"En Alabama, ¿qué viaje es una excepción que permite a un conductor de Etapa II manejar solo entre la medianoche y las 6 a.m.?","o":["Ir al trabajo o volver de él","Ir a la casa de un amigo","Manejar a un restaurante","Practicar en calles vacías"],"h1":"Piense en un viaje necesario, no en uno por diversión.","h2":"En Alabama un conductor de Etapa II puede manejar solo de noche cuando va al trabajo o vuelve de él, porque la ley permite viajes necesarios como el trabajo, eventos de la escuela, eventos religiosos y emergencias.","p":"Correcto. Ir al trabajo o volver de él está permitido."},"ref":{"doc":"AL","page":null}},{"id":"al-007","scope":"AL","cat":"licensing","sign":null,"c":1,"en":{"q":"In Alabama, what does the Stage II license say about handheld phones while driving?","o":["They are fine at red lights","They may not be used at all","They may be used for short calls","They are fine with one passenger"],"h1":"Stage II drivers have extra limits on phones.","h2":"An Alabama Stage II driver must not use any handheld communication device while driving, because a phone in the hand takes eyes and attention off the road.","p":"Right. No handheld phone at all while driving on a Stage II license."},"es":{"q":"En Alabama, ¿qué dice la licencia de Etapa II sobre los teléfonos en la mano al manejar?","o":["Se pueden usar en los semáforos en rojo","No se pueden usar para nada","Se pueden usar para llamadas cortas","Se pueden usar con un solo pasajero"],"h1":"Los conductores de Etapa II tienen límites extra con el teléfono.","h2":"En Alabama un conductor de Etapa II no debe usar ningún aparato de comunicación en la mano mientras maneja, porque el teléfono en la mano quita la vista y la atención del camino.","p":"Correcto. Nada de teléfono en la mano con licencia de Etapa II."},"ref":{"doc":"AL","page":null}},{"id":"al-008","scope":"AL","cat":"licensing","sign":null,"c":3,"en":{"q":"In Alabama, what happens when a Stage II driver breaks one of the graduated license rules?","o":["A warning letter only","A one-time $10 fee","Nothing, if no one was hurt","The restricted period is extended"],"h1":"The limits do not end as soon as planned.","h2":"In Alabama, breaking a graduated license rule extends the restricted period by six months or until the driver turns 18, so the teen keeps the limits longer.","p":"Right. The limits last longer after a violation."},"es":{"q":"En Alabama, ¿qué pasa cuando un conductor de Etapa II no cumple una regla de la licencia por etapas?","o":["Solo una carta de aviso","Un cargo único de $10","Nada, si nadie se lastimó","Se alarga el período restringido"],"h1":"Los límites no terminan cuando se pensaba.","h2":"En Alabama, si no se cumple una regla de la licencia por etapas, el período restringido se alarga seis meses o hasta que el conductor cumpla 18 años, así que el joven mantiene los límites por más tiempo.","p":"Correcto. Los límites duran más después de una infracción."},"ref":{"doc":"AL","page":null}},{"id":"al-009","scope":"AL","cat":"licensing","sign":null,"c":1,"en":{"q":"In Alabama, a 17-year-old can get an unrestricted Stage III license after holding Stage II for how long?","o":["At least 3 months","At least 6 months","At least 9 months","At least 12 months"],"h1":"It is the same length as the Stage I waiting time.","h2":"In Alabama a 17-year-old must hold a Stage II license for at least six months before getting the unrestricted Stage III license, so the new driver has time alone with limits first.","p":"Right. Six months on Stage II, then Stage III."},"es":{"q":"En Alabama, un joven de 17 años puede obtener la licencia sin restricciones de Etapa III después de tener la Etapa II, ¿por cuánto tiempo?","o":["Por lo menos 3 meses","Por lo menos 6 meses","Por lo menos 9 meses","Por lo menos 12 meses"],"h1":"Es el mismo tiempo de espera que en la Etapa I.","h2":"En Alabama un joven de 17 años debe tener la licencia de Etapa II por lo menos seis meses antes de obtener la licencia sin restricciones de Etapa III, para tener primero un tiempo manejando solo con límites.","p":"Correcto. Seis meses en Etapa II y luego la Etapa III."},"ref":{"doc":"AL","page":null}},{"id":"al-010","scope":"AL","cat":"licensing","sign":null,"c":2,"en":{"q":"In Alabama, how long is a learner license valid before it must be renewed?","o":["One year","Two years","Four years","Eight years"],"h1":"It lasts longer than a typical school year or two.","h2":"An Alabama learner license is valid for four years and can be renewed once, which gives a learner plenty of time to practice.","p":"Right. The learner license is good for four years."},"es":{"q":"En Alabama, ¿por cuánto tiempo es válida la licencia de aprendiz antes de renovarla?","o":["Un año","Dos años","Cuatro años","Ocho años"],"h1":"Dura más que uno o dos años escolares.","h2":"En Alabama la licencia de aprendiz es válida por cuatro años y se puede renovar una vez, lo que le da al aprendiz mucho tiempo para practicar.","p":"Correcto. La licencia de aprendiz dura cuatro años."},"ref":{"doc":"AL","page":9}},{"id":"al-011","scope":"AL","cat":"licensing","sign":null,"c":0,"en":{"q":"In Alabama, can a person take the written knowledge test in Spanish?","o":["Yes, Spanish is offered","No, it is English only","Only with a paid interpreter","Only for commercial licenses"],"h1":"Alabama offers the written test in several languages.","h2":"Alabama offers the written knowledge test in other languages, including Spanish, so people can show what they know in the language they read best.","p":"Right. The Alabama written test is available in Spanish."},"es":{"q":"En Alabama, ¿se puede tomar el examen escrito de conocimientos en español?","o":["Sí, se ofrece en español","No, solo en inglés","Solo con un intérprete pagado","Solo para licencias comerciales"],"h1":"Alabama ofrece el examen escrito en varios idiomas.","h2":"Alabama ofrece el examen escrito de conocimientos en otros idiomas, incluido el español, para que cada persona muestre lo que sabe en el idioma que lee mejor.","p":"Correcto. El examen escrito de Alabama se ofrece en español."},"ref":{"doc":"AL","page":9}},{"id":"al-012","scope":"AL","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Alabama, unless a sign says otherwise, what is the speed limit in an urban district?","o":["25 mph","30 mph","35 mph","40 mph"],"h1":"It is a little higher than a typical school zone speed.","h2":"The Alabama speed limit in an urban district is 30 mph unless a sign shows a different limit, because towns have many people, driveways, and crossings.","p":"Right. Urban districts in Alabama are 30 mph unless posted."},"es":{"q":"En Alabama, si no hay una señal que diga otra cosa, ¿cuál es el límite de velocidad en una zona urbana?","o":["25 mph","30 mph","35 mph","40 mph"],"h1":"Es un poco más alto que la velocidad típica de una zona escolar.","h2":"En Alabama el límite de velocidad en una zona urbana es de 30 mph si no hay una señal con otro límite, porque en los pueblos hay mucha gente, entradas de autos y cruces.","p":"Correcto. En zonas urbanas de Alabama son 30 mph si no hay otra señal."},"ref":{"doc":"AL","page":60}},{"id":"al-013","scope":"AL","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Alabama, what is the highest speed limit allowed by law on an interstate highway?","o":["55 mph","60 mph","65 mph","70 mph"],"h1":"Interstates have the highest limit in the state.","h2":"The highest speed limit on an Alabama interstate is 70 mph, which is higher than the limit on other four-lane highways.","p":"Right. Alabama interstates go up to 70 mph."},"es":{"q":"En Alabama, ¿cuál es el límite de velocidad más alto que permite la ley en una carretera interestatal?","o":["55 mph","60 mph","65 mph","70 mph"],"h1":"Las interestatales tienen el límite más alto del estado.","h2":"En Alabama el límite de velocidad más alto en una interestatal es de 70 mph, más alto que en otras carreteras de cuatro carriles.","p":"Correcto. Las interestatales de Alabama llegan a 70 mph."},"ref":{"doc":"AL","page":60}},{"id":"al-014","scope":"AL","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Alabama, unless posted otherwise, what is the speed limit on a highway with four or more lanes that is not an interstate?","o":["55 mph","60 mph","65 mph","70 mph"],"h1":"It is 5 mph below the interstate limit.","h2":"On an Alabama highway with four or more lanes that is not an interstate, the limit is 65 mph unless posted, which is 5 mph less than on an interstate.","p":"Right. Four-lane highways that are not interstates are 65 mph."},"es":{"q":"En Alabama, si no hay otra señal, ¿cuál es el límite de velocidad en una carretera de cuatro carriles o más que no es interestatal?","o":["55 mph","60 mph","65 mph","70 mph"],"h1":"Es 5 mph menos que el límite de la interestatal.","h2":"En una carretera de Alabama con cuatro carriles o más que no es interestatal, el límite es de 65 mph si no hay otra señal, o sea 5 mph menos que en una interestatal.","p":"Correcto. Las carreteras de cuatro carriles que no son interestatales tienen 65 mph."},"ref":{"doc":"AL","page":null}},{"id":"al-015","scope":"AL","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Alabama, unless posted otherwise, what is the speed limit on a state highway with fewer than four lanes?","o":["55 mph","60 mph","65 mph","70 mph"],"h1":"Smaller highways have a lower limit than four-lane highways.","h2":"An Alabama highway with fewer than four lanes has a 55 mph limit unless a sign says otherwise, because two-lane roads have oncoming traffic close by.","p":"Right. Smaller Alabama highways are 55 mph unless posted."},"es":{"q":"En Alabama, si no hay otra señal, ¿cuál es el límite de velocidad en una carretera estatal de menos de cuatro carriles?","o":["55 mph","60 mph","65 mph","70 mph"],"h1":"Las carreteras más pequeñas tienen un límite más bajo que las de cuatro carriles.","h2":"En Alabama una carretera de menos de cuatro carriles tiene un límite de 55 mph si no hay una señal con otro límite, porque en las carreteras de dos carriles el tráfico contrario pasa muy cerca.","p":"Correcto. Las carreteras pequeñas de Alabama tienen 55 mph si no hay otra señal."},"ref":{"doc":"AL","page":60}},{"id":"al-016","scope":"AL","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Alabama, unless posted otherwise, what is the speed limit on an unpaved road?","o":["25 mph","30 mph","35 mph","45 mph"],"h1":"Dirt and gravel need more care than a paved county road.","h2":"The Alabama limit on an unpaved road is 35 mph unless a sign says otherwise, because loose dirt and gravel make it harder to stop and steer.","p":"Right. Unpaved roads in Alabama are 35 mph."},"es":{"q":"En Alabama, si no hay otra señal, ¿cuál es el límite de velocidad en un camino sin pavimentar?","o":["25 mph","30 mph","35 mph","45 mph"],"h1":"La tierra y la grava piden más cuidado que un camino pavimentado del condado.","h2":"En Alabama el límite en un camino sin pavimentar es de 35 mph si no hay otra señal, porque la tierra suelta y la grava hacen más difícil frenar y girar.","p":"Correcto. Los caminos sin pavimentar en Alabama tienen 35 mph."},"ref":{"doc":"AL","page":60}},{"id":"al-017","scope":"AL","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Alabama, unless posted otherwise, what is the speed limit on a paved county road outside a city or town?","o":["35 mph","45 mph","55 mph","65 mph"],"h1":"It is 10 mph more than on an unpaved road.","h2":"A paved county road outside a city or town in Alabama has a 45 mph limit unless posted, which is 10 mph more than on an unpaved road.","p":"Right. Paved county roads in Alabama are 45 mph unless posted."},"es":{"q":"En Alabama, si no hay otra señal, ¿cuál es el límite de velocidad en un camino pavimentado del condado fuera de una ciudad o pueblo?","o":["35 mph","45 mph","55 mph","65 mph"],"h1":"Es 10 mph más que en un camino sin pavimentar.","h2":"En Alabama un camino pavimentado del condado fuera de una ciudad o pueblo tiene un límite de 45 mph si no hay otra señal, o sea 10 mph más que en un camino sin pavimentar.","p":"Correcto. Los caminos pavimentados del condado en Alabama tienen 45 mph."},"ref":{"doc":"AL","page":60}},{"id":"al-018","scope":"AL","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Alabama, on an interstate, how far may you stay in the far-left lane without completely passing another vehicle?","o":["0.5 miles","1 mile","3 miles","1.5 miles"],"h1":"It is a short distance, between one and two miles.","h2":"On an Alabama interstate you may not stay in the far-left lane for more than 1.5 miles without completely passing a vehicle, because the left lane is for passing.","p":"Right. No more than 1.5 miles in the left lane without passing."},"es":{"q":"En Alabama, en una interestatal, ¿qué distancia puede ir por el carril de la izquierda sin terminar de rebasar a otro vehículo?","o":["0.5 millas","1 milla","3 millas","1.5 millas"],"h1":"Es una distancia corta, entre una y dos millas.","h2":"En una interestatal de Alabama usted no puede ir más de 1.5 millas por el carril de la izquierda sin terminar de rebasar a un vehículo, porque el carril izquierdo es para rebasar.","p":"Correcto. No más de 1.5 millas en el carril izquierdo sin rebasar."},"ref":{"doc":"AL","page":null}},{"id":"al-019","scope":"AL","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Alabama, on a road with two or more lanes in your direction, what should you do when passing a stopped police car with flashing lights?","o":["Move out of the lane next to it if safe","Stop behind it and wait","Honk and keep your speed","Speed up to pass it quickly"],"h1":"Give the stopped vehicle more room.","h2":"Under the Alabama Move Over law you must leave the lane closest to a stopped emergency vehicle when it is safe, and slow down if you cannot, to protect the people working there.","p":"Right. Move over a lane when it is safe."},"es":{"q":"En Alabama, en una vía con dos o más carriles en su dirección, ¿qué debe hacer al pasar junto a una patrulla detenida con luces encendidas?","o":["Salir del carril de al lado si es seguro","Pararse detrás y esperar","Tocar la bocina y seguir igual","Acelerar para pasar rápido"],"h1":"Dé más espacio al vehículo detenido.","h2":"Según la ley de Alabama para apartarse (Move Over), usted debe salir del carril más cercano al vehículo de emergencia detenido cuando sea seguro, y bajar la velocidad si no puede, para proteger a las personas que trabajan allí.","p":"Correcto. Cámbiese de carril cuando sea seguro."},"ref":{"doc":"AL","page":68}},{"id":"al-020","scope":"AL","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Alabama, if you cannot change lanes away from a stopped emergency vehicle and the limit is 25 mph or more, how much should you slow down?","o":["5 mph below the limit","15 mph below the limit","25 mph below the limit","To exactly 20 mph"],"h1":"It is more than 10 mph but less than 20 mph.","h2":"In Alabama, when you cannot move over and the posted limit is 25 mph or more, you must slow to at least 15 mph below the limit so you can react to people near the road.","p":"Right. Slow to 15 mph below the limit."},"es":{"q":"En Alabama, si no puede cambiarse de carril al pasar un vehículo de emergencia detenido y el límite es de 25 mph o más, ¿cuánto debe bajar la velocidad?","o":["5 mph menos que el límite","15 mph menos que el límite","25 mph menos que el límite","Exactamente a 20 mph"],"h1":"Es más de 10 mph pero menos de 20 mph.","h2":"En Alabama, cuando usted no puede apartarse y el límite es de 25 mph o más, debe bajar por lo menos a 15 mph menos que el límite, para poder reaccionar ante las personas cerca del camino.","p":"Correcto. Baje a 15 mph menos que el límite."},"ref":{"doc":"AL","page":68}},{"id":"al-021","scope":"AL","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Alabama, which of these stopped vehicles with flashing lights is also covered by the Move Over law?","o":["A parked delivery van","A car stopped at a red light","A garbage or recycling truck","A bus at a regular bus stop"],"h1":"The law protects many roadside workers, not only police.","h2":"The Alabama Move Over law covers garbage and recycling trucks that are collecting on the roadside, as well as police, emergency, tow, utility, and road work vehicles with flashing lights.","p":"Right. Garbage and recycling trucks are covered."},"es":{"q":"En Alabama, ¿cuál de estos vehículos detenidos con luces intermitentes también está cubierto por la ley Move Over?","o":["Una camioneta de reparto estacionada","Un carro parado en un semáforo en rojo","Un camión de basura o reciclaje","Un autobús en su parada normal"],"h1":"La ley protege a muchos trabajadores en la orilla del camino, no solo a la policía.","h2":"La ley Move Over de Alabama incluye los camiones de basura y de reciclaje que están recogiendo al lado de la calle, además de los vehículos de policía, emergencia, grúa, servicios públicos y obras con luces intermitentes.","p":"Correcto. Los camiones de basura y reciclaje están incluidos."},"ref":{"doc":"AL","page":null}},{"id":"al-022","scope":"AL","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Alabama, a school bus is stopped with red lights flashing on the other side of a four-lane highway divided by a median. What must you do?","o":["Stop until the bus moves","Stop, then pass at 10 mph","Pull onto the shoulder","Continue carefully without stopping"],"h1":"A median between you and the bus changes the rule.","h2":"In Alabama, on a divided highway with a median, only traffic going the same direction as the bus must stop, so you may continue carefully while watching for children.","p":"Right. With a median, opposite traffic continues with care."},"es":{"q":"En Alabama, un autobús escolar está detenido con luces rojas al otro lado de una carretera de cuatro carriles dividida por una mediana. ¿Qué debe hacer?","o":["Parar hasta que el autobús avance","Parar y luego pasar a 10 mph","Salirse al acotamiento","Seguir con cuidado sin parar"],"h1":"Una mediana entre usted y el autobús cambia la regla.","h2":"En Alabama, en una carretera dividida por una mediana, solo debe parar el tráfico que va en la misma dirección que el autobús, así que usted puede seguir con cuidado y atento a los niños.","p":"Correcto. Con mediana, el tráfico contrario sigue con cuidado."},"ref":{"doc":"AL","page":61}},{"id":"al-023","scope":"AL","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Alabama, a school bus stops with red lights flashing on a four-lane road with no median. Who must stop?","o":["Traffic in both directions","Only traffic behind the bus","Only traffic facing the bus","Only trucks and buses"],"h1":"Without a median, children may cross every lane.","h2":"In Alabama, on a four-lane road with no median, traffic in both directions must stop for a school bus with flashing red lights, because children may cross all the lanes.","p":"Right. Without a median, everyone stops."},"es":{"q":"En Alabama, un autobús escolar se detiene con luces rojas en una vía de cuatro carriles sin mediana. ¿Quién debe parar?","o":["El tráfico en ambas direcciones","Solo el tráfico detrás del autobús","Solo el tráfico de frente","Solo camiones y autobuses"],"h1":"Sin mediana, los niños pueden cruzar todos los carriles.","h2":"En Alabama, en una vía de cuatro carriles sin mediana, el tráfico en ambas direcciones debe parar ante un autobús escolar con luces rojas intermitentes, porque los niños pueden cruzar todos los carriles.","p":"Correcto. Sin mediana, todos paran."},"ref":{"doc":"AL","page":61}},{"id":"al-024","scope":"AL","cat":"safe-driving","sign":null,"c":1,"en":{"q":"Under Alabama's hands-free law, when is holding a phone while driving a violation?","o":["Only on interstate highways","When you also drive poorly, like swerving","Only between midnight and 6 a.m.","Never, if you hold it below the window"],"h1":"Police look at how you drive while the phone is in your hand.","h2":"Under the Alabama hands-free law, holding a phone while driving is a violation when you are also seen driving poorly, such as swerving or changing lanes without a signal, so it is safest to keep the phone out of your hand.","p":"Right. Holding a phone breaks the law when you also drive poorly, like swerving."},"es":{"q":"Según la ley de manos libres de Alabama, ¿cuándo es una infracción sostener el teléfono mientras maneja?","o":["Solo en las autopistas interestatales","Cuando además maneja mal, como zigzaguear","Solo entre la medianoche y las 6 a.m.","Nunca, si lo sostiene debajo de la ventana"],"h1":"La policía se fija en cómo maneja usted mientras tiene el teléfono en la mano.","h2":"Según la ley de manos libres de Alabama, sostener el teléfono mientras maneja es una infracción cuando además lo ven manejando mal, por ejemplo zigzagueando o cambiando de carril sin señalar, así que lo más seguro es no tener el teléfono en la mano.","p":"Correcto. Sostener el teléfono es ilegal cuando además maneja mal, como zigzaguear."},"ref":{"doc":"AL","page":16}},{"id":"al-025","scope":"AL","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Alabama, is it legal for an adult driver to read or send a text message while driving?","o":["Yes, on straight roads","Yes, if the car is slow","No, texting is banned","Yes, for short messages"],"h1":"Texting takes your eyes off the road for several seconds.","h2":"Alabama bans writing, sending, or reading text messages while driving for every driver, because texting takes your eyes and mind off the road.","p":"Right. Texting while driving is against the law in Alabama."},"es":{"q":"En Alabama, ¿es legal que un conductor adulto lea o envíe un mensaje de texto mientras maneja?","o":["Sí, en caminos rectos","Sí, si va despacio","No, está prohibido","Sí, si el mensaje es corto"],"h1":"Escribir mensajes le quita la vista del camino varios segundos.","h2":"Alabama prohíbe a todos los conductores escribir, enviar o leer mensajes de texto mientras manejan, porque eso le quita la vista y la atención del camino.","p":"Correcto. En Alabama está prohibido escribir mensajes al manejar."},"ref":{"doc":"AL","page":32}},{"id":"al-026","scope":"AL","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Alabama, a driver under 21 can be charged with DUI at what blood alcohol level?","o":["0.02 percent or more","0.05 percent or more","0.08 percent or more","0.10 percent or more"],"h1":"The limit for young drivers is far below the adult limit.","h2":"In Alabama a driver under 21 can be charged with DUI at a blood alcohol level of 0.02 percent, which is much lower than the adult limit, because young drivers should not drink at all.","p":"Right. Under 21, the limit is 0.02 percent."},"es":{"q":"En Alabama, ¿con qué nivel de alcohol en la sangre se puede acusar de manejar ebrio a un conductor menor de 21 años?","o":["0.02 por ciento o más","0.05 por ciento o más","0.08 por ciento o más","0.10 por ciento o más"],"h1":"El límite para los jóvenes es mucho más bajo que el de los adultos.","h2":"En Alabama a un conductor menor de 21 años se le puede acusar de manejar ebrio con 0.02 por ciento de alcohol en la sangre, mucho menos que el límite de los adultos, porque los jóvenes no deben tomar nada.","p":"Correcto. Para menores de 21, el límite es 0.02 por ciento."},"ref":{"doc":"AL","page":33}},{"id":"al-027","scope":"AL","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Alabama, a driver age 21 or older is legally under the influence at what blood alcohol level?","o":["0.02 percent or more","0.05 percent or more","0.08 percent or more","0.15 percent or more"],"h1":"It is the same adult limit used in most states.","h2":"An Alabama driver age 21 or older is legally under the influence at a blood alcohol level of 0.08 percent or more, although alcohol can affect driving at lower levels too.","p":"Right. The adult limit is 0.08 percent."},"es":{"q":"En Alabama, un conductor de 21 años o más está legalmente bajo los efectos del alcohol, ¿a partir de qué nivel?","o":["0.02 por ciento o más","0.05 por ciento o más","0.08 por ciento o más","0.15 por ciento o más"],"h1":"Es el mismo límite para adultos que usan casi todos los estados.","h2":"En Alabama un conductor de 21 años o más está legalmente bajo los efectos del alcohol con 0.08 por ciento o más, aunque el alcohol puede afectar el manejo con niveles más bajos.","p":"Correcto. El límite para adultos es 0.08 por ciento."},"ref":{"doc":"AL","page":33}},{"id":"al-028","scope":"AL","cat":"licensing","sign":null,"c":3,"en":{"q":"In Alabama, what is the minimum liability insurance for injury to one person in a crash?","o":["$10,000","$15,000","$20,000","$25,000"],"h1":"Alabama uses the same number for one person and for property damage.","h2":"Alabama requires at least $25,000 of liability coverage for injury to one person, as part of the 25/50/25 minimum that every driver must carry.","p":"Right. The minimum is $25,000 per person."},"es":{"q":"En Alabama, ¿cuál es el seguro de responsabilidad mínimo por lesiones a una persona en un choque?","o":["$10,000","$15,000","$20,000","$25,000"],"h1":"Alabama usa el mismo número para una persona y para daños a la propiedad.","h2":"Alabama exige por lo menos $25,000 de cobertura de responsabilidad por lesiones a una persona, como parte del mínimo de 25/50/25 que todo conductor debe tener.","p":"Correcto. El mínimo es $25,000 por persona."},"ref":{"doc":"AL","page":68}},{"id":"al-029","scope":"AL","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Alabama, when must your headlights be on during the day?","o":["Only on interstates","When wipers are on for rain","Only in school zones","When the radio is off"],"h1":"Think about bad weather.","h2":"In Alabama your headlights must be on when you use your windshield wipers because of rain, sleet, or snow, so other drivers can see you.","p":"Right. Wipers on for rain means headlights on."},"es":{"q":"En Alabama, ¿cuándo debe tener las luces delanteras encendidas durante el día?","o":["Solo en las interestatales","Con los limpiaparabrisas por lluvia","Solo en zonas escolares","Cuando el radio está apagado"],"h1":"Piense en el mal tiempo.","h2":"En Alabama usted debe encender las luces delanteras cuando usa los limpiaparabrisas por lluvia, aguanieve o nieve, para que los demás conductores lo vean.","p":"Correcto. Si usa los limpiaparabrisas por lluvia, encienda las luces."},"ref":{"doc":"AL","page":71}},{"id":"ar-001","scope":"AR","cat":"licensing","sign":null,"c":0,"en":{"q":"In Arkansas, what is the youngest age to get a learner's license?","o":["14 years old","15 years old","16 years old","13 years old"],"h1":"Arkansas lets teens start earlier than many other states.","h2":"In Arkansas, the learner's license is for teens who are 14 or 15 years old, so 14 is the youngest age.","p":"Right. The Arkansas learner's license starts at age 14."},"es":{"q":"En Arkansas, ¿cuál es la edad mínima para obtener la licencia de aprendiz?","o":["14 años","15 años","16 años","13 años"],"h1":"Arkansas permite empezar antes que muchos otros estados.","h2":"En Arkansas, la licencia de aprendiz es para jóvenes de 14 o 15 años, así que 14 es la edad mínima.","p":"Correcto. La licencia de aprendiz en Arkansas empieza a los 14 años."},"ref":{"doc":"AR","page":3}},{"id":"ar-002","scope":"AR","cat":"licensing","sign":null,"c":2,"en":{"q":"In Arkansas, a teen with a learner's license must drive with a licensed driver. How old must that driver be?","o":["At least 16 years old","At least 18 years old","At least 21 years old","At least 25 years old"],"h1":"The helper must be an adult who is old enough to buy alcohol legally.","h2":"An Arkansas learner may drive only with a licensed driver who is at least 21 years old, so an experienced adult is always there to guide them.","p":"Right. A learner drives with a licensed driver age 21 or older."},"es":{"q":"En Arkansas, un joven con licencia de aprendiz debe manejar con un conductor con licencia. ¿Qué edad debe tener ese conductor?","o":["Por lo menos 16 años","Por lo menos 18 años","Por lo menos 21 años","Por lo menos 25 años"],"h1":"El acompañante debe ser un adulto con edad suficiente para comprar alcohol legalmente.","h2":"En Arkansas, el aprendiz solo puede manejar con un conductor con licencia que tenga por lo menos 21 años, para que siempre lo guíe un adulto con experiencia.","p":"Correcto. El aprendiz maneja con un conductor con licencia de 21 años o más."},"ref":{"doc":"AR","page":3}},{"id":"ar-003","scope":"AR","cat":"licensing","sign":null,"c":1,"en":{"q":"In Arkansas, at what age can a teen get an intermediate license?","o":["15 years old","16 years old","17 years old","18 years old"],"h1":"It comes right after the learner's license years of 14 and 15.","h2":"In Arkansas, the intermediate license is for drivers who are 16 or 17, so a teen can get it at 16.","p":"Right. The intermediate license starts at age 16."},"es":{"q":"En Arkansas, ¿a qué edad puede un joven obtener la licencia intermedia?","o":["15 años","16 años","17 años","18 años"],"h1":"Viene justo después de los años de la licencia de aprendiz, 14 y 15.","h2":"En Arkansas, la licencia intermedia es para conductores de 16 o 17 años, así que un joven puede obtenerla a los 16.","p":"Correcto. La licencia intermedia empieza a los 16 años."},"ref":{"doc":"AR","page":3}},{"id":"ar-005","scope":"AR","cat":"licensing","sign":null,"c":3,"en":{"q":"In Arkansas, what must a teen's driving record show to get an intermediate license?","o":["Two minor tickets at most in the past year","A completed online safety video","A signed letter from a teacher","No serious violations or at-fault crashes in the past six months"],"h1":"Think about a clean record for a recent period of time.","h2":"To get an Arkansas intermediate license, a teen must have no serious traffic violations and no at-fault crashes during the previous six months.","p":"Right. The record must be clean of serious violations and at-fault crashes for six months."},"es":{"q":"En Arkansas, ¿qué debe mostrar el historial de manejo de un joven para obtener la licencia intermedia?","o":["Como máximo dos multas menores en el último año","Un video de seguridad completado en línea","Una carta firmada por un maestro","Ninguna infracción grave ni choque con culpa en los últimos seis meses"],"h1":"Piense en un historial limpio durante un período reciente.","h2":"Para obtener la licencia intermedia en Arkansas, el joven no debe tener infracciones graves ni choques en los que tuvo la culpa durante los seis meses anteriores.","p":"Correcto. El historial debe estar libre de infracciones graves y choques con culpa por seis meses."},"ref":{"doc":"AR","page":3}},{"id":"ar-006","scope":"AR","cat":"licensing","sign":null,"c":2,"en":{"q":"In Arkansas, at what age can a driver apply for a regular, unrestricted license?","o":["16 years old","17 years old","18 years old","21 years old"],"h1":"It is the age when most people finish high school.","h2":"In Arkansas, a driver can apply for a regular, unrestricted license at 18, as long as the driving record has been clean for the year before.","p":"Right. The unrestricted license comes at age 18."},"es":{"q":"En Arkansas, ¿a qué edad se puede solicitar la licencia regular sin restricciones?","o":["16 años","17 años","18 años","21 años"],"h1":"Es la edad en que la mayoría termina la escuela secundaria.","h2":"En Arkansas, se puede solicitar la licencia regular sin restricciones a los 18 años, siempre que el historial de manejo esté limpio durante el año anterior.","p":"Correcto. La licencia sin restricciones llega a los 18 años."},"ref":{"doc":"AR","page":4}},{"id":"ar-007","scope":"AR","cat":"licensing","sign":null,"c":0,"en":{"q":"In Arkansas, what can let a 16- or 17-year-old get an unrestricted license before turning 18?","o":["Graduating from high school or earning a GED","Passing the written test a second time","Driving 100 hours with a parent","Buying a car in their own name"],"h1":"Think about finishing school early.","h2":"Arkansas lets a 16- or 17-year-old get an unrestricted license early in some cases, such as showing a high school diploma or a GED.","p":"Right. A high school diploma or GED can allow an early unrestricted license."},"es":{"q":"En Arkansas, ¿qué puede permitir que un joven de 16 o 17 años obtenga la licencia sin restricciones antes de cumplir 18?","o":["Graduarse de la secundaria u obtener el GED","Aprobar el examen escrito por segunda vez","Manejar 100 horas con un padre","Comprar un carro a su propio nombre"],"h1":"Piense en terminar la escuela antes de tiempo.","h2":"En algunos casos, Arkansas permite que un joven de 16 o 17 años obtenga la licencia sin restricciones antes, por ejemplo si presenta el diploma de secundaria o el GED.","p":"Correcto. El diploma de secundaria o el GED puede permitir la licencia sin restricciones antes de tiempo."},"ref":{"doc":"AR","page":null}},{"id":"ar-008","scope":"AR","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Arkansas, during which hours may a driver with an intermediate license not drive, unless an exception applies?","o":["11 p.m. to 4 a.m.","9 p.m. to 6 a.m.","Midnight to 6 a.m.","10 p.m. to 5 a.m."],"h1":"The limit starts one hour before midnight.","h2":"An Arkansas intermediate license holder may not drive from 11 p.m. to 4 a.m., unless a licensed driver age 21 or older is along, or the trip is to or from work, a school or church activity, or an emergency.","p":"Right. Intermediate drivers stay off the road from 11 p.m. to 4 a.m."},"es":{"q":"En Arkansas, ¿en qué horario no puede manejar quien tiene licencia intermedia, salvo que aplique una excepción?","o":["De 11 p.m. a 4 a.m.","De 9 p.m. a 6 a.m.","De medianoche a 6 a.m.","De 10 p.m. a 5 a.m."],"h1":"El límite empieza una hora antes de la medianoche.","h2":"Una persona con licencia intermedia en Arkansas no puede manejar de 11 p. m. a 4 a. m., a menos que la acompañe un conductor con licencia de 21 años o más, o que vaya o venga del trabajo, de una actividad escolar o de la iglesia, o por una emergencia.","p":"Correcto. Los conductores con licencia intermedia no manejan de 11 p.m. a 4 a.m."},"ref":{"doc":"AR","page":4}},{"id":"ar-009","scope":"AR","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Arkansas, how many unrelated passengers under 18 may a driver with an intermediate license carry, when no adult driver is along?","o":["None at all","Two","Three","One"],"h1":"Family members do not count toward this limit.","h2":"An Arkansas intermediate license holder may carry only one unrelated passenger under 18, unless a licensed driver age 21 or older sits in the front seat.","p":"Right. Only one unrelated passenger under 18 is allowed."},"es":{"q":"En Arkansas, ¿cuántos pasajeros menores de 18 años, que no sean familiares, puede llevar un conductor con licencia intermedia si no lo acompaña un adulto con licencia?","o":["Ninguno","Dos","Tres","Uno"],"h1":"Los familiares no cuentan para este límite.","h2":"Una persona con licencia intermedia en Arkansas puede llevar solo un pasajero menor de 18 años que no sea familiar, a menos que un conductor con licencia de 21 años o más vaya en el asiento delantero.","p":"Correcto. Solo se permite un pasajero menor de 18 años que no sea familiar."},"ref":{"doc":"AR","page":4}},{"id":"ar-010","scope":"AR","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Arkansas, what is the rule on cell phones for drivers under 18?","o":["They may use a phone only with a hands-free device","They may not use a phone at all, except in an emergency","They may text only at a red light","They may talk only on highways"],"h1":"For the youngest drivers, even hands-free is not allowed.","h2":"In Arkansas, drivers under 18 may not use a cell phone while driving, even hands-free, except in an emergency.","p":"Right. Drivers under 18 may not use a phone, except in an emergency."},"es":{"q":"En Arkansas, ¿cuál es la regla del celular para conductores menores de 18 años?","o":["Pueden usar el teléfono solo con manos libres","No pueden usar el teléfono, salvo en una emergencia","Pueden enviar mensajes solo en un semáforo en rojo","Pueden hablar solo en las autopistas"],"h1":"Para los conductores más jóvenes, ni siquiera se permite el manos libres.","h2":"En Arkansas, los conductores menores de 18 años no pueden usar el celular mientras manejan, ni siquiera con manos libres, salvo en una emergencia.","p":"Correcto. Los menores de 18 no pueden usar el teléfono, salvo en una emergencia."},"ref":{"doc":"AR","page":46}},{"id":"ar-011","scope":"AR","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Arkansas, how may a driver who is 18 to 20 years old talk on a phone while driving?","o":["Only while holding the phone to the ear","Only on roads with no traffic lights","Only with a hands-free device","Only when a passenger holds the phone"],"h1":"The driver's hands must stay free.","h2":"In Arkansas, drivers from 18 to 20 may not use a handheld phone while driving, but they may talk with a hands-free device.","p":"Right. Drivers 18 to 20 may talk only hands-free."},"es":{"q":"En Arkansas, ¿cómo puede hablar por teléfono mientras maneja un conductor de 18 a 20 años?","o":["Solo sosteniendo el teléfono en el oído","Solo en calles sin semáforos","Solo con un dispositivo de manos libres","Solo si un pasajero sostiene el teléfono"],"h1":"Las manos del conductor deben quedar libres.","h2":"En Arkansas, los conductores de 18 a 20 años no pueden usar el teléfono en la mano mientras manejan, pero pueden hablar con un dispositivo de manos libres.","p":"Correcto. Los conductores de 18 a 20 años solo pueden hablar con manos libres."},"ref":{"doc":"AR","page":4}},{"id":"ar-012","scope":"AR","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Arkansas, which drivers are banned from texting while driving?","o":["Drivers of every age","Only drivers under 18","Only drivers under 21","Only commercial truck drivers"],"h1":"This rule does not depend on age.","h2":"Arkansas does not allow any driver, of any age, to send or read text messages while driving.","p":"Right. No driver of any age may text while driving in Arkansas."},"es":{"q":"En Arkansas, ¿a qué conductores se les prohíbe enviar mensajes de texto mientras manejan?","o":["A los conductores de todas las edades","Solo a los menores de 18 años","Solo a los menores de 21 años","Solo a los camioneros comerciales"],"h1":"Esta regla no depende de la edad.","h2":"Arkansas no permite que ningún conductor, de ninguna edad, envíe o lea mensajes de texto mientras maneja.","p":"Correcto. Ningún conductor, de ninguna edad, puede enviar mensajes mientras maneja en Arkansas."},"ref":{"doc":"AR","page":4}},{"id":"ar-014","scope":"AR","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Arkansas, a driver under 21 is considered under the influence at what blood alcohol level?","o":["0.00 percent","0.02 percent or higher","0.05 percent or higher","0.08 percent or higher"],"h1":"It is far lower than the limit for adults.","h2":"In Arkansas, a driver under 21 with a blood alcohol level of 0.02 percent or higher can be charged with underage DUI.","p":"Right. For drivers under 21, the limit is 0.02 percent."},"es":{"q":"En Arkansas, ¿con qué nivel de alcohol en la sangre se considera que un conductor menor de 21 años está bajo la influencia?","o":["0.00 por ciento","0.02 por ciento o más","0.05 por ciento o más","0.08 por ciento o más"],"h1":"Es mucho más bajo que el límite para adultos.","h2":"En Arkansas, un conductor menor de 21 años con un nivel de alcohol en la sangre de 0.02 por ciento o más puede ser acusado de manejar bajo la influencia.","p":"Correcto. Para los menores de 21, el límite es 0.02 por ciento."},"ref":{"doc":"AR","page":75}},{"id":"ar-015","scope":"AR","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Arkansas, at what blood alcohol level can a driver 21 or older be charged with DWI?","o":["0.02 percent or higher","0.05 percent or higher","0.08 percent or higher","0.10 percent or higher"],"h1":"It is the same limit most states use for adults.","h2":"In Arkansas, a driver 21 or older with a blood alcohol level of 0.08 percent or higher can be charged with driving while intoxicated.","p":"Right. For adults, the limit is 0.08 percent."},"es":{"q":"En Arkansas, ¿con qué nivel de alcohol en la sangre se puede acusar de DWI a un conductor de 21 años o más?","o":["0.02 por ciento o más","0.05 por ciento o más","0.08 por ciento o más","0.10 por ciento o más"],"h1":"Es el mismo límite que usa la mayoría de los estados para adultos.","h2":"En Arkansas, un conductor de 21 años o más con un nivel de alcohol en la sangre de 0.08 por ciento o más puede ser acusado de manejar en estado de ebriedad.","p":"Correcto. Para los adultos, el límite es 0.08 por ciento."},"ref":{"doc":"AR","page":74}},{"id":"ar-018","scope":"AR","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Arkansas, the move-over law covers more than police cars and ambulances. Which other stopped vehicles does it cover?","o":["Any parked car with its hood open","Only city buses at a bus stop","Utility trucks and tow trucks with flashing lights","Only delivery vans with hazard lights"],"h1":"Think of work vehicles that stop on the side of the road.","h2":"Arkansas's move-over law also covers stopped utility vehicles, tow trucks and highway department vehicles that show flashing lights.","p":"Right. Utility trucks and tow trucks with flashing lights are covered."},"es":{"q":"En Arkansas, la ley de moverse de carril cubre más que patrullas y ambulancias. ¿Qué otros vehículos detenidos cubre?","o":["Cualquier carro estacionado con el capó abierto","Solo autobuses urbanos en la parada","Camiones de servicios públicos y grúas con luces intermitentes","Solo camionetas de reparto con luces de emergencia"],"h1":"Piense en vehículos de trabajo que se detienen al lado de la carretera.","h2":"La ley de Arkansas también cubre vehículos de servicios públicos, grúas y vehículos del departamento de carreteras que están detenidos con luces intermitentes.","p":"Correcto. Se incluyen los camiones de servicios públicos y las grúas con luces intermitentes."},"ref":{"doc":"AR","page":21}},{"id":"ar-019","scope":"AR","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Arkansas, you approach a stopped emergency vehicle with flashing lights, but you cannot safely move to another lane. What must you do?","o":["Keep your speed and pass quickly","Slow down and pass with caution","Stop in your lane until it leaves","Honk to warn the workers"],"h1":"If you cannot add distance, reduce your speed.","h2":"Under the Arkansas move-over law, if you cannot safely move away from the stopped vehicle, you must slow down and pass with caution.","p":"Right. When you cannot move over, you slow down and use caution."},"es":{"q":"En Arkansas, usted se acerca a un vehículo de emergencia detenido con luces intermitentes, pero no puede cambiarse de carril con seguridad. ¿Qué debe hacer?","o":["Mantener la velocidad y pasar rápido","Reducir la velocidad y pasar con precaución","Detenerse en su carril hasta que se vaya","Tocar la bocina para avisar a los trabajadores"],"h1":"Si no puede alejarse, reduzca la velocidad.","h2":"Según la ley de Arkansas, si usted no puede alejarse con seguridad del vehículo detenido, debe reducir la velocidad y pasar con precaución.","p":"Correcto. Si no puede cambiarse de carril, reduce la velocidad y maneja con cuidado."},"ref":{"doc":"AR","page":21}},{"id":"ar-021","scope":"AR","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Arkansas, how far from a stopped school bus with flashing red lights must you stop?","o":["At least 5 feet","At least 10 feet","At least 15 feet","At least 30 feet"],"h1":"It is about the length of two cars.","h2":"Arkansas law requires you to stop at least 30 feet away from a school bus that is stopped with its red lights flashing.","p":"Right. You stop at least 30 feet from the bus."},"es":{"q":"En Arkansas, ¿a qué distancia de un autobús escolar detenido con luces rojas intermitentes debe detenerse?","o":["Por lo menos 5 pies","Por lo menos 10 pies","Por lo menos 15 pies","Por lo menos 30 pies"],"h1":"Es más o menos el largo de dos carros.","h2":"La ley de Arkansas exige que usted se detenga por lo menos a 30 pies de un autobús escolar detenido con las luces rojas intermitentes.","p":"Correcto. Usted se detiene por lo menos a 30 pies del autobús."},"ref":{"doc":"AR","page":null}},{"id":"ar-022","scope":"AR","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Arkansas, when may a driver going the opposite way keep moving past a stopped school bus?","o":["On any road with four lanes","On any road with a center turn lane","On a divided highway with a median at least 20 feet wide","On any road when no children are visible"],"h1":"The two sides of the road must be separated by a wide strip.","h2":"In Arkansas, a driver going the opposite way may keep going only when a median at least 20 feet wide separates them from the stopped school bus.","p":"Right. Only a wide median of at least 20 feet lets the opposite side keep going."},"es":{"q":"En Arkansas, ¿cuándo puede un conductor que va en sentido contrario seguir adelante al pasar un autobús escolar detenido?","o":["En cualquier vía de cuatro carriles","En cualquier vía con carril central para girar","En una carretera dividida con una franja central de por lo menos 20 pies","En cualquier vía si no se ven niños"],"h1":"Los dos lados de la vía deben estar separados por una franja ancha.","h2":"En Arkansas, un conductor que va en sentido contrario puede seguir solo cuando una franja divisoria de al menos 20 pies de ancho lo separa del autobús escolar detenido.","p":"Correcto. Solo una franja central de por lo menos 20 pies permite que el lado contrario siga."},"ref":{"doc":"AR","page":12}},{"id":"ar-023","scope":"AR","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Arkansas, you are on a four-lane road with a center turn lane and no median. A school bus going the other way stops with red lights flashing. What must you do?","o":["Stop until the red lights turn off","Keep driving because you are going the other way","Slow to 20 mph and pass","Move to the far lane and keep going"],"h1":"A center turn lane is not a median.","h2":"In Arkansas, drivers on two-lane and four-lane roads, including roads with a center turn lane, must stop for a school bus that is loading or unloading children.","p":"Right. Without a wide median, traffic in both directions must stop."},"es":{"q":"En Arkansas, usted va por una vía de cuatro carriles con carril central para girar y sin franja central. Un autobús escolar que va en sentido contrario se detiene con las luces rojas intermitentes. ¿Qué debe hacer?","o":["Detenerse hasta que se apaguen las luces rojas","Seguir porque usted va en sentido contrario","Reducir a 20 mph y pasar","Pasarse al carril más lejano y seguir"],"h1":"Un carril central para girar no es una franja central.","h2":"En Arkansas, los conductores en vías de dos y cuatro carriles, incluso las que tienen carril central para girar, deben detenerse ante un autobús escolar que sube o baja niños.","p":"Correcto. Sin una franja central ancha, el tráfico en ambas direcciones debe detenerse."},"ref":{"doc":"AR","page":13}},{"id":"ar-024","scope":"AR","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Arkansas, what is the highest fine for illegally passing a stopped school bus?","o":["$500","$2,500","$100","$10,000"],"h1":"It is a few thousand dollars, plus court costs.","h2":"Under Arkansas law, illegally passing a stopped school bus can bring a fine of up to $2,500, plus court costs.","p":"Right. The fine can reach $2,500."},"es":{"q":"En Arkansas, ¿cuál es la multa más alta por pasar ilegalmente un autobús escolar detenido?","o":["$500","$2,500","$100","$10,000"],"h1":"Son unos miles de dólares, más los costos del tribunal.","h2":"Según la ley de Arkansas, pasar ilegalmente un autobús escolar detenido puede costar una multa de hasta $2,500, más los costos del tribunal.","p":"Correcto. La multa puede llegar a $2,500."},"ref":{"doc":"AR","page":null}},{"id":"az-001","scope":"AZ","cat":"licensing","sign":null,"c":2,"en":{"q":"In Arizona, what is the youngest age to apply for a regular instruction permit (not one only for a school driving class)?","o":["17 years old","16 years old","15 and a half years old","14 and a half years old"],"h1":"It is half a year past a birthday, before age 16.","h2":"In Arizona you can apply for an instruction permit at 15 years and 6 months, so you can practice before you turn 16.","p":"Right. The Arizona permit starts at 15 and a half."},"es":{"q":"En Arizona, ¿cuál es la edad mínima para solicitar un permiso de aprendizaje normal (no uno solo para una clase de manejo escolar)?","o":["17 años","16 años","15 años y medio","14 años y medio"],"h1":"Es medio año después de un cumpleaños, antes de los 16.","h2":"En Arizona usted puede solicitar el permiso de aprendizaje a los 15 años y 6 meses, para practicar antes de cumplir 16.","p":"Correcto. El permiso en Arizona empieza a los 15 años y medio."},"ref":{"doc":"AZ","page":10}},{"id":"az-002","scope":"AZ","cat":"licensing","sign":null,"c":1,"en":{"q":"In Arizona, a teen who takes no driver education and no driving safety course must have supervised practice. How many hours in total?","o":["10 hours","30 hours","40 hours","50 hours"],"h1":"It is fewer hours than many other states ask for.","h2":"An Arizona teen who skips approved driver education must have a parent or guardian certify at least 30 hours of supervised driving, 10 of them at night, before getting a graduated license.","p":"Right. Arizona asks for 30 supervised hours."},"es":{"q":"En Arizona, un adolescente que no toma ningún curso de manejo ni de seguridad vial debe tener práctica supervisada. ¿Cuántas horas en total?","o":["10 horas","30 horas","40 horas","50 horas"],"h1":"Son menos horas que en muchos otros estados.","h2":"Un adolescente en Arizona que no toma un curso aprobado de educación vial necesita que su padre, madre o tutor certifique por lo menos 30 horas de manejo supervisado, 10 de ellas de noche, antes de obtener la licencia graduada.","p":"Correcto. Arizona pide 30 horas supervisadas."},"ref":{"doc":"AZ","page":11}},{"id":"az-003","scope":"AZ","cat":"licensing","sign":null,"c":0,"en":{"q":"In Arizona, how many of the 30 supervised practice hours must be done at night?","o":["At least 10 hours","At least 5 hours","At least 15 hours","At least 20 hours"],"h1":"It is one third of the 30 total hours.","h2":"At least 10 of the 30 supervised hours must be at night in Arizona, because driving in the dark needs its own practice.","p":"Right. At least 10 of the hours must be at night."},"es":{"q":"En Arizona, ¿cuántas de las 30 horas de práctica supervisada deben ser de noche?","o":["Por lo menos 10 horas","Por lo menos 5 horas","Por lo menos 15 horas","Por lo menos 20 horas"],"h1":"Es la tercera parte de las 30 horas en total.","h2":"En Arizona, por lo menos 10 de las 30 horas supervisadas deben ser de noche, porque manejar en la oscuridad requiere su propia práctica.","p":"Correcto. Por lo menos 10 horas deben ser de noche."},"ref":{"doc":"AZ","page":11}},{"id":"az-004","scope":"AZ","cat":"licensing","sign":null,"c":3,"en":{"q":"In Arizona, how long must a teen hold the instruction permit before getting a graduated license?","o":["1 month","3 months","1 year","6 months"],"h1":"It is half a year.","h2":"An Arizona teen must hold the instruction permit for at least 6 months before getting a graduated license, so there is time to practice.","p":"Right. Hold the permit for at least 6 months."},"es":{"q":"En Arizona, ¿cuánto tiempo debe tener un adolescente el permiso de aprendizaje antes de obtener la licencia graduada?","o":["1 mes","3 meses","1 año","6 meses"],"h1":"Es medio año.","h2":"Un adolescente en Arizona debe tener el permiso de aprendizaje por lo menos 6 meses antes de obtener la licencia graduada, para tener tiempo de practicar.","p":"Correcto. Debe tener el permiso por lo menos 6 meses."},"ref":{"doc":"AZ","page":11}},{"id":"az-005","scope":"AZ","cat":"licensing","sign":null,"c":1,"en":{"q":"In Arizona, where must the licensed driver sit when a permit holder is driving?","o":["In the back seat behind the driver","In the seat beside the driver","Anywhere in the vehicle","In a second car close behind"],"h1":"The helper must be close enough to see the road and help right away.","h2":"The licensed driver must sit in the seat beside an Arizona permit holder, so they can watch the road and help at once.","p":"Right. The supervisor sits beside the permit driver."},"es":{"q":"En Arizona, ¿dónde debe sentarse el conductor con licencia cuando maneja alguien con permiso?","o":["En el asiento de atrás del conductor","En el asiento al lado del conductor","En cualquier lugar del vehículo","En otro carro que va justo detrás"],"h1":"El acompañante debe estar lo bastante cerca para ver la calle y ayudar enseguida.","h2":"El conductor con licencia debe ir sentado al lado de quien maneja con permiso en Arizona, para ver la calle y ayudar de inmediato.","p":"Correcto. El supervisor se sienta al lado del conductor con permiso."},"ref":{"doc":"AZ","page":10}},{"id":"az-006","scope":"AZ","cat":"licensing","sign":null,"c":2,"en":{"q":"In Arizona, during the first six months of a teen's graduated license, when may the teen NOT drive alone?","o":["From 10 p.m. to 6 a.m.","From 9 p.m. to 5 a.m.","From midnight to 5 a.m.","From 11 p.m. to 4 a.m."],"h1":"The limit starts at the very start of a new day.","h2":"For the first six months, an Arizona teen with a graduated license may not drive from midnight to 5 a.m. unless a parent or guardian is in the front seat, because late night driving is the most dangerous.","p":"Right. No driving from midnight to 5 a.m. at first."},"es":{"q":"En Arizona, durante los primeros seis meses de la licencia graduada, ¿en qué horario NO puede manejar solo el adolescente?","o":["De 10 p.m. a 6 a.m.","De 9 p.m. a 5 a.m.","De medianoche a 5 a.m.","De 11 p.m. a 4 a.m."],"h1":"El límite comienza justo al empezar un nuevo día.","h2":"Durante los primeros seis meses, un adolescente con licencia graduada en Arizona no puede manejar de medianoche a 5 a.m. a menos que vaya un padre o tutor en el asiento delantero, porque manejar tarde en la noche es lo más peligroso.","p":"Correcto. Al principio no se maneja de medianoche a 5 a.m."},"ref":{"doc":"AZ","page":11}},{"id":"az-007","scope":"AZ","cat":"licensing","sign":null,"c":0,"en":{"q":"In Arizona, a new teen driver wants to drive at 1 a.m. in the first six months. Who can make this legal by riding along?","o":["A licensed parent or guardian in the front seat","Any friend who is 18 or older","A younger brother or sister","Any passenger who has a permit"],"h1":"It must be an adult who is responsible for the teen.","h2":"In the first six months, an Arizona teen may drive between midnight and 5 a.m. when a licensed parent or guardian sits in the front passenger seat.","p":"Right. A licensed parent or guardian in front makes it legal."},"es":{"q":"En Arizona, un conductor adolescente nuevo quiere manejar a la 1 a.m. en los primeros seis meses. ¿Quién puede hacerlo legal si lo acompaña?","o":["Un padre o tutor con licencia en el asiento delantero","Cualquier amigo de 18 años o más","Un hermano o hermana menor","Cualquier pasajero que tenga permiso"],"h1":"Debe ser un adulto responsable del adolescente.","h2":"En los primeros seis meses, un adolescente en Arizona puede manejar entre medianoche y 5 a.m. si un padre o tutor con licencia va en el asiento delantero.","p":"Correcto. Un padre o tutor con licencia adelante lo hace legal."},"ref":{"doc":"AZ","page":11}},{"id":"az-008","scope":"AZ","cat":"licensing","sign":null,"c":3,"en":{"q":"In Arizona, in the first six months of a graduated license, how many passengers under 18 may a teen carry, not counting brothers and sisters?","o":["None at all","Two","Three","One"],"h1":"It is the smallest number above zero.","h2":"In the first six months, an Arizona teen driver may carry only one passenger under 18 who is not a brother or sister, because friends in the car are a big distraction.","p":"Right. Only one passenger under 18 at first."},"es":{"q":"En Arizona, en los primeros seis meses de la licencia graduada, ¿cuántos pasajeros menores de 18 puede llevar un adolescente, sin contar a sus hermanos?","o":["Ninguno","Dos","Tres","Uno"],"h1":"Es el número más pequeño mayor que cero.","h2":"En los primeros seis meses, un conductor adolescente en Arizona puede llevar solo un pasajero menor de 18 que no sea su hermano o hermana, porque los amigos en el carro distraen mucho.","p":"Correcto. Al principio solo un pasajero menor de 18."},"ref":{"doc":"AZ","page":11}},{"id":"az-009","scope":"AZ","cat":"licensing","sign":null,"c":1,"en":{"q":"In Arizona, how many questions are on the regular written test for a driver license?","o":["20 questions","30 questions","40 questions","50 questions"],"h1":"It is the same number as the supervised practice hours.","h2":"The Arizona written test for a regular license has 30 multiple choice questions about signs, laws and safe driving.","p":"Right. The Arizona written test has 30 questions."},"es":{"q":"En Arizona, ¿cuántas preguntas tiene el examen escrito normal para la licencia de manejo?","o":["20 preguntas","30 preguntas","40 preguntas","50 preguntas"],"h1":"Es el mismo número que las horas de práctica supervisada.","h2":"El examen escrito de Arizona para la licencia normal tiene 30 preguntas de opción múltiple sobre señales, leyes y manejo seguro.","p":"Correcto. El examen escrito de Arizona tiene 30 preguntas."},"ref":{"doc":"AZ","page":null}},{"id":"az-010","scope":"AZ","cat":"licensing","sign":null,"c":2,"en":{"q":"In Arizona, what score do you need to pass the written knowledge test?","o":["60 percent","70 percent","80 percent","90 percent"],"h1":"You must get four out of every five questions right.","h2":"You need at least 80 percent correct to pass the Arizona knowledge test, which is 24 of the 30 questions.","p":"Right. You need 80 percent to pass."},"es":{"q":"En Arizona, ¿qué puntaje necesita para aprobar el examen escrito de conocimientos?","o":["60 por ciento","70 por ciento","80 por ciento","90 por ciento"],"h1":"Debe contestar bien cuatro de cada cinco preguntas.","h2":"Usted necesita por lo menos 80 por ciento de respuestas correctas para aprobar el examen de Arizona, es decir 24 de las 30 preguntas.","p":"Correcto. Necesita 80 por ciento para aprobar."},"ref":{"doc":"AZ","page":null}},{"id":"az-012","scope":"AZ","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Arizona, may a driver with an instruction permit use a cell phone while driving?","o":["Yes, if it is in hands-free mode","No, only in an emergency where stopping is not possible","Yes, but only to read a map","Yes, when stopped at a red light"],"h1":"Permit drivers have a stricter rule than adult drivers.","h2":"An Arizona permit holder may not use a phone or other wireless device while driving, even hands-free, except in a real emergency, so that all attention stays on learning to drive.","p":"Right. Permit drivers may not use a phone except in an emergency."},"es":{"q":"En Arizona, ¿puede un conductor con permiso de aprendizaje usar el celular mientras maneja?","o":["Sí, si está en modo manos libres","No, solo en una emergencia donde no se puede parar","Sí, pero solo para leer un mapa","Sí, cuando está detenido en un semáforo en rojo"],"h1":"Los conductores con permiso tienen una regla más estricta que los adultos.","h2":"Quien tiene permiso de aprendizaje en Arizona no puede usar el celular ni otro aparato inalámbrico mientras maneja, ni siquiera con manos libres, salvo en una emergencia real, para que toda su atención esté en aprender a manejar.","p":"Correcto. Con permiso no se usa el celular, salvo en una emergencia."},"ref":{"doc":"AZ","page":null}},{"id":"az-013","scope":"AZ","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Arizona, how may an adult driver with a full license use a cell phone while driving?","o":["Holding it in one hand","Resting it on the lap","Holding it with the shoulder","Only in hands-free mode"],"h1":"Your hands and body may not hold the phone.","h2":"Arizona's hands-free law lets drivers use a phone only in hands-free mode; you may not hold or support it with any part of your body.","p":"Right. In Arizona the phone must be hands-free."},"es":{"q":"En Arizona, ¿cómo puede un conductor adulto con licencia usar el celular mientras maneja?","o":["Sosteniéndolo con una mano","Apoyándolo en las piernas","Sosteniéndolo con el hombro","Solo en modo manos libres"],"h1":"Ni sus manos ni su cuerpo pueden sostener el teléfono.","h2":"La ley de manos libres de Arizona permite usar el teléfono solo en modo manos libres; usted no puede sostenerlo ni apoyarlo con ninguna parte del cuerpo.","p":"Correcto. En Arizona el teléfono debe ir en manos libres."},"ref":{"doc":"AZ","page":20}},{"id":"az-014","scope":"AZ","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Arizona, you see a stopped tow truck on the shoulder with flashing lights. There are two lanes your way. What should you do?","o":["Keep your lane and speed","Stop behind the tow truck","Move to the lane not next to it, if safe","Honk and pass quickly"],"h1":"Give the people on the shoulder more room.","h2":"Arizona's move over law says to move into a lane that is not next to a stopped vehicle with flashing lights when you can do it safely, to protect people working by the road.","p":"Right. Move over to a lane that is not next to it."},"es":{"q":"En Arizona, ve una grúa detenida en el acotamiento con luces intermitentes. Hay dos carriles en su dirección. ¿Qué debe hacer?","o":["Seguir en su carril y a la misma velocidad","Detenerse detrás de la grúa","Cambiarse al carril que no está junto a ella, si es seguro","Tocar el claxon y pasar rápido"],"h1":"Deles más espacio a las personas en el acotamiento.","h2":"La ley de Arizona de cambiarse de carril dice que debe pasar a un carril que no esté junto al vehículo detenido con luces intermitentes, cuando sea seguro, para proteger a quienes trabajan junto a la vía.","p":"Correcto. Cámbiese a un carril que no esté junto a ella."},"ref":{"doc":"AZ","page":31}},{"id":"az-015","scope":"AZ","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Arizona, you cannot safely change lanes away from a stopped vehicle with flashing lights. What must you do?","o":["Slow down and pass with caution","Keep going at the speed limit","Stop in your lane until it leaves","Drive on the shoulder to pass"],"h1":"If you cannot give more space, give more time.","h2":"When you cannot safely move over in Arizona, you must slow down and pass with care, so you have time to react if someone steps into the road.","p":"Right. If you cannot move over, slow down."},"es":{"q":"En Arizona, no puede cambiarse de carril con seguridad para alejarse de un vehículo detenido con luces intermitentes. ¿Qué debe hacer?","o":["Bajar la velocidad y pasar con cuidado","Seguir al límite de velocidad","Parar en su carril hasta que se vaya","Manejar por el acotamiento para pasar"],"h1":"Si no puede dar más espacio, dé más tiempo.","h2":"Cuando no puede cambiarse de carril con seguridad en Arizona, debe bajar la velocidad y pasar con cuidado, para tener tiempo de reaccionar si alguien entra a la vía.","p":"Correcto. Si no puede cambiarse, baje la velocidad."},"ref":{"doc":"AZ","page":31}},{"id":"az-016","scope":"AZ","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Arizona, which stopped vehicles does the move over law cover?","o":["Only police cars","Only ambulances and fire trucks","Only road work trucks","Any stopped vehicle with flashing lights"],"h1":"Since 2011 the law covers stranded drivers too.","h2":"Arizona's move over law covers any stationary vehicle with its flashing lights on, including a stranded driver on the shoulder, not just emergency vehicles.","p":"Right. It covers any stopped vehicle with flashing lights."},"es":{"q":"En Arizona, ¿a qué vehículos detenidos se aplica la ley de cambiarse de carril?","o":["Solo a patrullas de policía","Solo a ambulancias y bomberos","Solo a camiones de obras viales","A cualquier vehículo detenido con luces intermitentes"],"h1":"Desde 2011 la ley también protege a conductores varados.","h2":"La ley de Arizona se aplica a cualquier vehículo detenido con las luces intermitentes encendidas, incluido un conductor varado en el acotamiento, no solo a vehículos de emergencia.","p":"Correcto. Se aplica a cualquier vehículo detenido con luces intermitentes."},"ref":{"doc":"AZ","page":31}},{"id":"az-017","scope":"AZ","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Arizona, unless a sign says otherwise, what is the speed limit when approaching a school crossing?","o":["10 mph","15 mph","20 mph","25 mph"],"h1":"It is the slowest limit set by state law.","h2":"Arizona law sets 15 mph when approaching a school crossing, because children may step into the street at any moment.","p":"Right. Approaching a school crossing, the limit is 15 mph."},"es":{"q":"En Arizona, si no hay una señal que diga otra cosa, ¿cuál es el límite de velocidad al acercarse a un cruce escolar?","o":["10 mph","15 mph","20 mph","25 mph"],"h1":"Es el límite más bajo que fija la ley estatal.","h2":"La ley de Arizona fija 15 mph al acercarse a un cruce escolar, porque los niños pueden entrar a la calle en cualquier momento.","p":"Correcto. Al acercarse a un cruce escolar, el límite es 15 mph."},"ref":{"doc":"AZ","page":32}},{"id":"az-018","scope":"AZ","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Arizona, unless a sign says otherwise, what is the speed limit in a business or residential district?","o":["15 mph","20 mph","25 mph","35 mph"],"h1":"It is ten more than the school crossing limit.","h2":"Arizona law sets 25 mph in business and residential districts when no other limit is posted, because people, driveways and parked cars are close to the road.","p":"Right. Business and residential districts are 25 mph."},"es":{"q":"En Arizona, si no hay una señal que diga otra cosa, ¿cuál es el límite de velocidad en una zona comercial o residencial?","o":["15 mph","20 mph","25 mph","35 mph"],"h1":"Es diez más que el límite del cruce escolar.","h2":"La ley de Arizona fija 25 mph en zonas comerciales y residenciales cuando no hay otro límite indicado, porque hay personas, entradas de garaje y carros estacionados cerca de la calle.","p":"Correcto. En zonas comerciales y residenciales el límite es 25 mph."},"ref":{"doc":"AZ","page":32}},{"id":"az-019","scope":"AZ","cat":"licensing","sign":null,"c":0,"en":{"q":"In Arizona, what can happen if you get 8 or more points on your record in 12 months?","o":["You may have to attend Traffic Survival School or lose your license","Nothing, points only matter after 5 years","You must buy a new vehicle registration","You must retake only the vision test"],"h1":"Points add up, and the state steps in at 8.","h2":"If you collect 8 or more points within 12 months in Arizona, the MVD can order Traffic Survival School or suspend your license.","p":"Right. 8 points in 12 months can mean Traffic Survival School or suspension."},"es":{"q":"En Arizona, ¿qué puede pasar si acumula 8 puntos o más en su historial en 12 meses?","o":["Puede tener que ir a la Escuela de Supervivencia de Tráfico o perder la licencia","Nada, los puntos solo cuentan después de 5 años","Debe comprar un registro nuevo para el vehículo","Debe repetir solo el examen de la vista"],"h1":"Los puntos se suman y el estado actúa al llegar a 8.","h2":"Si acumula 8 puntos o más en 12 meses en Arizona, la MVD puede ordenarle la Escuela de Supervivencia de Tráfico o suspender su licencia.","p":"Correcto. 8 puntos en 12 meses pueden significar escuela de tráfico o suspensión."},"ref":{"doc":"AZ","page":49}},{"id":"az-020","scope":"AZ","cat":"licensing","sign":null,"c":1,"en":{"q":"In Arizona, which conviction always requires you to complete Traffic Survival School?","o":["A parking ticket","Running a red light","An expired registration","A broken taillight"],"h1":"It is a dangerous moving violation at an intersection.","h2":"In Arizona, a conviction for running a red light, or a flashing red light, always means you must complete Traffic Survival School, on top of paying the fine.","p":"Right. Running a red light means Traffic Survival School."},"es":{"q":"En Arizona, ¿qué infracción siempre le obliga a completar la Escuela de Supervivencia de Tráfico?","o":["Una multa de estacionamiento","Pasarse un semáforo en rojo","Un registro vencido","Una luz trasera rota"],"h1":"Es una infracción peligrosa en una intersección.","h2":"En Arizona, una condena por pasarse un semáforo en rojo, o una luz roja intermitente, siempre le obliga a completar la Escuela de Supervivencia de Tráfico, además de pagar la multa.","p":"Correcto. Pasarse un rojo lleva a la escuela de tráfico."},"ref":{"doc":"AZ","page":30}},{"id":"az-021","scope":"AZ","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Arizona, at what blood alcohol level does a driver face an Extreme DUI charge?","o":["0.02 or more","0.05 or more","0.08 or more","0.15 or more"],"h1":"It is almost twice the normal adult limit.","h2":"Arizona charges Extreme DUI when a driver's blood alcohol is 0.15 or more, and the penalties are harsher than for a regular DUI.","p":"Right. Extreme DUI starts at 0.15."},"es":{"q":"En Arizona, ¿con qué nivel de alcohol en la sangre se acusa a un conductor de DUI Extremo?","o":["0.02 o más","0.05 o más","0.08 o más","0.15 o más"],"h1":"Es casi el doble del límite normal para adultos.","h2":"Arizona acusa de DUI Extremo cuando el alcohol en la sangre del conductor es 0.15 o más, y las sanciones son más duras que en un DUI normal.","p":"Correcto. El DUI Extremo empieza en 0.15."},"ref":{"doc":"AZ","page":52}},{"id":"az-022","scope":"AZ","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Arizona, how much alcohol may a driver under 21 have in their body?","o":["Up to 0.02","None at all","Up to 0.05","Up to 0.08"],"h1":"Arizona has zero tolerance for young drivers.","h2":"A driver under 21 in Arizona may not drive with any alcohol in the body, because the state has a zero tolerance law for young drivers.","p":"Right. Under 21 means no alcohol at all."},"es":{"q":"En Arizona, ¿cuánto alcohol puede tener en el cuerpo un conductor menor de 21 años?","o":["Hasta 0.02","Nada","Hasta 0.05","Hasta 0.08"],"h1":"Arizona tiene tolerancia cero para conductores jóvenes.","h2":"Un conductor menor de 21 años en Arizona no puede manejar con nada de alcohol en el cuerpo, porque el estado tiene una ley de tolerancia cero para conductores jóvenes.","p":"Correcto. Menor de 21 significa nada de alcohol."},"ref":{"doc":"AZ","page":47}},{"id":"az-023","scope":"AZ","cat":"licensing","sign":null,"c":2,"en":{"q":"In Arizona, what is the minimum liability insurance for damage to other people's property in one crash?","o":["$5,000","$10,000","$15,000","$25,000"],"h1":"Arizona's minimum is often written as 25/50/15.","h2":"Arizona requires at least $15,000 of property damage liability for one crash, as part of the 25/50/15 minimum.","p":"Right. The property damage minimum is $15,000."},"es":{"q":"En Arizona, ¿cuál es el seguro mínimo de responsabilidad por daños a la propiedad de otros en un choque?","o":["$5,000","$10,000","$15,000","$25,000"],"h1":"El mínimo de Arizona se escribe a menudo como 25/50/15.","h2":"Arizona exige por lo menos $15,000 de cobertura por daños a la propiedad en un choque, como parte del mínimo 25/50/15.","p":"Correcto. El mínimo por daños a la propiedad es $15,000."},"ref":{"doc":"AZ","page":8}},{"id":"az-024","scope":"AZ","cat":"licensing","sign":null,"c":0,"en":{"q":"In Arizona, what is the minimum liability insurance for injury to one person in a crash?","o":["$25,000","$15,000","$30,000","$50,000"],"h1":"It is the first number in 25/50/15.","h2":"Arizona requires at least $25,000 of bodily injury coverage for one person in a crash, the first number in the 25/50/15 minimum.","p":"Right. The minimum for one injured person is $25,000."},"es":{"q":"En Arizona, ¿cuál es el seguro mínimo de responsabilidad por lesiones a una persona en un choque?","o":["$25,000","$15,000","$30,000","$50,000"],"h1":"Es el primer número de 25/50/15.","h2":"Arizona exige por lo menos $25,000 de cobertura por lesiones a una persona en un choque, el primer número del mínimo 25/50/15.","p":"Correcto. El mínimo por una persona lesionada es $25,000."},"ref":{"doc":"AZ","page":8}},{"id":"ca-001","scope":"CA","cat":"licensing","sign":null,"c":2,"en":{"q":"In California, what is the youngest age to get a provisional instruction permit?","o":["14 years old","15 years old","15 and a half years old","16 years old"],"h1":"It is half a year past a birthday, before you turn 16.","h2":"A California teen can get a provisional instruction permit at 15 and a half, so there is time to practice before the provisional license.","p":"Right. The California permit starts at 15 and a half."},"es":{"q":"En California, ¿cuál es la edad mínima para obtener un permiso de instrucción provisional?","o":["14 años","15 años","15 años y medio","16 años"],"h1":"Es medio año después de un cumpleaños, antes de cumplir 16.","h2":"En California, un adolescente puede obtener el permiso de instrucción provisional a los 15 años y medio, para tener tiempo de practicar antes de la licencia provisional.","p":"Correcto. El permiso en California empieza a los 15 años y medio."},"ref":{"doc":"CA","page":3}},{"id":"ca-002","scope":"CA","cat":"licensing","sign":null,"c":1,"en":{"q":"In California, how many hours of supervised driving practice must a teen complete before a provisional license?","o":["30 hours","50 hours","40 hours","60 hours"],"h1":"It is a round number, more than forty.","h2":"A California teen must complete 50 hours of supervised practice before the provisional license, because new drivers need a lot of time behind the wheel.","p":"Right. California asks for 50 hours of supervised practice."},"es":{"q":"En California, ¿cuántas horas de práctica supervisada debe completar un adolescente antes de la licencia provisional?","o":["30 horas","50 horas","40 horas","60 horas"],"h1":"Es un número redondo, mayor que cuarenta.","h2":"Un adolescente en California debe completar 50 horas de práctica supervisada antes de la licencia provisional, porque un conductor nuevo necesita mucho tiempo al volante.","p":"Correcto. California pide 50 horas de práctica supervisada."},"ref":{"doc":"CA","page":3}},{"id":"ca-003","scope":"CA","cat":"licensing","sign":null,"c":0,"en":{"q":"In California, how many of a teen's supervised practice hours must be driven in darkness?","o":["At least 10 hours","At least 5 hours","At least 20 hours","At least 25 hours"],"h1":"It is one fifth of the total practice time.","h2":"At least 10 of the 50 practice hours must be in darkness, because night driving needs its own practice.","p":"Right. At least 10 practice hours must be at night."},"es":{"q":"En California, ¿cuántas de las horas de práctica supervisada del adolescente deben ser en la oscuridad?","o":["Por lo menos 10 horas","Por lo menos 5 horas","Por lo menos 20 horas","Por lo menos 25 horas"],"h1":"Es la quinta parte del tiempo total de práctica.","h2":"Por lo menos 10 de las 50 horas de práctica deben ser en la oscuridad, porque manejar de noche necesita su propia práctica.","p":"Correcto. Por lo menos 10 horas de práctica deben ser de noche."},"ref":{"doc":"CA","page":3}},{"id":"ca-004","scope":"CA","cat":"licensing","sign":null,"c":3,"en":{"q":"In California, during the first year of a provisional license, when may the teen not drive without a qualified adult?","o":["From 9 p.m. to 6 a.m.","From 10 p.m. to 4 a.m.","From midnight to 6 a.m.","From 11 p.m. to 5 a.m."],"h1":"The limit starts one hour before midnight.","h2":"In the first year, a provisional driver may not drive between 11 p.m. and 5 a.m. without a qualified adult, unless an exception such as school or work applies.","p":"Right. The night limit runs from 11 p.m. to 5 a.m."},"es":{"q":"En California, durante el primer año de la licencia provisional, ¿en qué horario no puede manejar el adolescente sin un adulto calificado?","o":["De 9 p.m. a 6 a.m.","De 10 p.m. a 4 a.m.","De medianoche a 6 a.m.","De 11 p.m. a 5 a.m."],"h1":"El límite empieza una hora antes de la medianoche.","h2":"En el primer año, el conductor provisional no puede manejar entre las 11 p.m. y las 5 a.m. sin un adulto calificado, salvo excepciones como la escuela o el trabajo.","p":"Correcto. El límite nocturno va de las 11 p.m. a las 5 a.m."},"ref":{"doc":"CA","page":4}},{"id":"ca-005","scope":"CA","cat":"licensing","sign":null,"c":1,"en":{"q":"In California, during the first year of a provisional license, the teen may not carry passengers under what age without a qualified adult?","o":["Under 18","Under 20","Under 16","Under 25"],"h1":"The age is just below a new decade of life.","h2":"In the first year, a provisional driver may not carry passengers under 20 unless a qualified adult is in the car, because young passengers raise crash risk.","p":"Right. No passengers under 20 without a qualified adult in the first year."},"es":{"q":"En California, durante el primer año de la licencia provisional, ¿pasajeros menores de qué edad no puede llevar el adolescente sin un adulto calificado?","o":["Menores de 18","Menores de 20","Menores de 16","Menores de 25"],"h1":"La edad está justo antes de una nueva década de vida.","h2":"En el primer año, el conductor provisional no puede llevar pasajeros menores de 20 años sin un adulto calificado en el auto, porque los pasajeros jóvenes aumentan el riesgo de choque.","p":"Correcto. Nada de pasajeros menores de 20 sin un adulto calificado en el primer año."},"ref":{"doc":"CA","page":4}},{"id":"ca-006","scope":"CA","cat":"licensing","sign":null,"c":2,"en":{"q":"In California, a provisional driver in the first year may drive at night with which person?","o":["Any licensed driver age 18 or older","A friend who has had a license for one year","A licensed driver age 25 or older","Any passenger age 21 or older"],"h1":"The adult must be older than in many other states.","h2":"A provisional driver may drive at night or carry young passengers when a licensed parent or guardian, a licensed driver 25 or older, or a certified instructor is with them.","p":"Right. The adult must be a licensed driver 25 or older, a parent or guardian, or an instructor."},"es":{"q":"En California, ¿con qué persona puede manejar de noche un conductor provisional en su primer año?","o":["Cualquier conductor con licencia de 18 años o más","Un amigo que tiene licencia desde hace un año","Un conductor con licencia de 25 años o más","Cualquier pasajero de 21 años o más"],"h1":"El adulto debe ser mayor que en muchos otros estados.","h2":"Un conductor provisional puede manejar de noche o llevar pasajeros jóvenes si va con su padre, madre o tutor con licencia, un conductor con licencia de 25 años o más, o un instructor certificado.","p":"Correcto. El adulto debe ser un conductor con licencia de 25 años o más, un padre o tutor, o un instructor."},"ref":{"doc":"CA","page":4}},{"id":"ca-007","scope":"CA","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In California, may a driver under 18 talk on a phone with a hands-free device while driving?","o":["No, not even hands-free","Yes, if the phone is mounted","Yes, on the freeway only","Yes, if the call is short"],"h1":"The rule for young drivers is stricter than the rule for adults.","h2":"A California driver under 18 may not use a phone while driving, even hands-free, except to call for help in an emergency.","p":"Right. Drivers under 18 may not use a phone, even hands-free."},"es":{"q":"En California, ¿puede un conductor menor de 18 años hablar por teléfono con manos libres mientras maneja?","o":["No, ni siquiera con manos libres","Sí, si el teléfono está montado","Sí, solo en la autopista","Sí, si la llamada es corta"],"h1":"La regla para los conductores jóvenes es más estricta que para los adultos.","h2":"En California, un conductor menor de 18 años no puede usar el teléfono mientras maneja, ni siquiera con manos libres, salvo para pedir ayuda en una emergencia.","p":"Correcto. Los menores de 18 no pueden usar el teléfono, ni con manos libres."},"ref":{"doc":"CA","page":71}},{"id":"ca-008","scope":"CA","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In California, when may a driver under 18 use a phone while driving?","o":["To answer a parent's call","To check a map at a red light","To send a short text","To call police, fire or a doctor in an emergency"],"h1":"Think of a call that could save a life.","h2":"A driver under 18 may use a phone only in an emergency, to reach police, the fire department or a health care provider.","p":"Right. Only an emergency call is allowed for drivers under 18."},"es":{"q":"En California, ¿cuándo puede un conductor menor de 18 años usar el teléfono mientras maneja?","o":["Para contestar una llamada de su padre","Para ver un mapa en un semáforo rojo","Para enviar un mensaje corto","Para llamar a la policía, los bomberos o un médico en una emergencia"],"h1":"Piense en una llamada que podría salvar una vida.","h2":"Un conductor menor de 18 años solo puede usar el teléfono en una emergencia, para comunicarse con la policía, los bomberos o un proveedor de salud.","p":"Correcto. Los menores de 18 solo pueden hacer llamadas de emergencia."},"ref":{"doc":"CA","page":71}},{"id":"ca-009","scope":"CA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In California, a driver under 21 can lose their license with a blood alcohol level of what?","o":["0.05 percent or more","0.01 percent or more","0.08 percent or more","0.04 percent or more"],"h1":"It is the smallest amount a test can measure.","h2":"California has a zero tolerance rule: a driver under 21 with 0.01 percent or more is breaking the law and can lose the license for one year.","p":"Right. For drivers under 21, the limit is 0.01 percent."},"es":{"q":"En California, un conductor menor de 21 años puede perder la licencia con un nivel de alcohol en la sangre de, ¿cuánto?","o":["0.05 por ciento o más","0.01 por ciento o más","0.08 por ciento o más","0.04 por ciento o más"],"h1":"Es la cantidad más pequeña que una prueba puede medir.","h2":"California tiene una regla de tolerancia cero: un conductor menor de 21 años con 0.01 por ciento o más viola la ley y puede perder la licencia por un año.","p":"Correcto. Para menores de 21, el límite es 0.01 por ciento."},"ref":{"doc":"CA","page":73}},{"id":"ca-010","scope":"CA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In California, a driver under 21 can be charged with a crime at what blood alcohol level, even below the adult limit?","o":["0.02 percent","0.03 percent","0.05 percent","0.07 percent"],"h1":"It is a little more than half of the adult limit of 0.08.","h2":"A California driver under 21 can be charged at 0.05 percent, which is lower than the 0.08 percent limit for adults.","p":"Right. Under 21, a charge can start at 0.05 percent."},"es":{"q":"En California, ¿con qué nivel de alcohol en la sangre se puede acusar de un delito a un conductor menor de 21 años, aunque esté por debajo del límite de adultos?","o":["0.02 por ciento","0.03 por ciento","0.05 por ciento","0.07 por ciento"],"h1":"Es un poco más de la mitad del límite de adultos de 0.08.","h2":"En California, a un conductor menor de 21 años se le puede acusar con 0.05 por ciento, que es menos que el límite de 0.08 por ciento para adultos.","p":"Correcto. Para menores de 21, la acusación puede empezar en 0.05 por ciento."},"ref":{"doc":"CA","page":75}},{"id":"ca-011","scope":"CA","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In California, a school bus is stopped with red lights flashing on the other side of a highway with two or more lanes in each direction. What must you do?","o":["Stop until the lights turn off","Stop, then pass at 10 mph","Honk and pass slowly","You do not have to stop"],"h1":"The rule changes when the road is wide enough on each side.","h2":"On a divided or multiple-lane highway with two or more lanes each way, you do not have to stop for a school bus on the other side, but you should still drive with care.","p":"Right. Traffic on the other side of a multiple-lane highway does not have to stop."},"es":{"q":"En California, un autobús escolar está detenido con luces rojas intermitentes al otro lado de una carretera con dos o más carriles en cada dirección. ¿Qué debe hacer usted?","o":["Detenerse hasta que se apaguen las luces","Detenerse y luego pasar a 10 mph","Tocar la bocina y pasar despacio","No tiene que detenerse"],"h1":"La regla cambia cuando la carretera es bastante ancha de cada lado.","h2":"En una carretera dividida o de varios carriles, con dos o más carriles en cada dirección, usted no tiene que detenerse por un autobús escolar del otro lado, pero debe manejar con cuidado.","p":"Correcto. El tráfico del otro lado de una carretera de varios carriles no tiene que detenerse."},"ref":{"doc":"CA","page":51}},{"id":"ca-012","scope":"CA","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In California, a school bus with flashing red lights is stopped across a two-lane road with one lane each way. You are coming toward it. What must you do?","o":["Stop and wait until the lights stop flashing","Slow down and pass with care","Keep going, since you are on the other side","Stop only if children are in the road"],"h1":"One lane each way is not wide enough for the exception.","h2":"On a road with only one lane in each direction, drivers from both directions must stop for a school bus with flashing red lights and wait until the lights turn off.","p":"Right. On a two-lane road, traffic from both directions must stop."},"es":{"q":"En California, un autobús escolar con luces rojas intermitentes está detenido en una carretera de dos carriles, uno en cada dirección. Usted viene hacia él. ¿Qué debe hacer?","o":["Detenerse y esperar hasta que las luces dejen de parpadear","Reducir la velocidad y pasar con cuidado","Seguir, porque usted está del otro lado","Detenerse solo si hay niños en la calle"],"h1":"Un carril en cada dirección no es suficiente para la excepción.","h2":"En una carretera con un solo carril en cada dirección, los conductores de ambos sentidos deben detenerse ante un autobús escolar con luces rojas intermitentes y esperar hasta que se apaguen.","p":"Correcto. En una carretera de dos carriles, el tráfico de ambos sentidos debe detenerse."},"ref":{"doc":"CA","page":51}},{"id":"ca-013","scope":"CA","cat":"signals","sign":null,"c":1,"en":{"q":"In California, may you turn right at a steady red light?","o":["No, never at a red light","Yes, after a full stop, unless a sign says no","Yes, without stopping if no cars come","Only between 9 a.m. and 5 p.m."],"h1":"You must do one thing first, and a sign can forbid it.","h2":"In California you may turn right on a steady red light after a full stop, unless a sign forbids it, and you must yield to people walking and to close traffic.","p":"Right. Stop fully first, then turn right if no sign forbids it."},"es":{"q":"En California, ¿puede usted girar a la derecha con la luz roja fija?","o":["No, nunca con luz roja","Sí, después de detenerse por completo, si no hay un letrero que lo prohíba","Sí, sin detenerse si no vienen autos","Solo entre las 9 a.m. y las 5 p.m."],"h1":"Debe hacer algo primero, y un letrero puede prohibirlo.","h2":"En California usted puede girar a la derecha con la luz roja fija después de detenerse por completo, si no hay un letrero que lo prohíba, y debe ceder el paso a los peatones y al tráfico cercano.","p":"Correcto. Deténgase por completo y luego gire a la derecha si ningún letrero lo prohíbe."},"ref":{"doc":"CA","page":18}},{"id":"ca-014","scope":"CA","cat":"signals","sign":null,"c":2,"en":{"q":"In California, when may you turn left at a steady red light after stopping?","o":["From any street onto a two-way street","Never, left turns on red are banned","From a one-way street onto a one-way street","Only at a red arrow"],"h1":"Both streets must let traffic go only one way.","h2":"In California you may turn left on a steady red light only from a one-way street onto another one-way street, after a full stop and when no sign forbids it.","p":"Right. Left on red is allowed only from one-way to one-way."},"es":{"q":"En California, ¿cuándo puede usted girar a la izquierda con la luz roja fija después de detenerse?","o":["De cualquier calle a una calle de doble sentido","Nunca, los giros a la izquierda en rojo están prohibidos","De una calle de un solo sentido a otra de un solo sentido","Solo con una flecha roja"],"h1":"Las dos calles deben permitir el tráfico en un solo sentido.","h2":"En California usted puede girar a la izquierda con la luz roja fija solo de una calle de un solo sentido a otra de un solo sentido, después de detenerse por completo y si ningún letrero lo prohíbe.","p":"Correcto. A la izquierda en rojo solo de un sentido a un sentido."},"ref":{"doc":"CA","page":20}},{"id":"ca-015","scope":"CA","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In California, what does a red-painted curb mean?","o":["Parking for up to 10 minutes","Loading for trucks only","Parking for people with disabilities","No stopping, standing or parking"],"h1":"Red is the strictest curb color.","h2":"A red curb in California means no stopping, standing or parking at all, except for a bus in a marked bus zone.","p":"Right. Red curb: no stopping, standing or parking."},"es":{"q":"En California, ¿qué significa una acera pintada de rojo?","o":["Estacionamiento hasta 10 minutos","Carga solo para camiones","Estacionamiento para personas con discapacidad","Prohibido detenerse, esperar o estacionarse"],"h1":"El rojo es el color de acera más estricto.","h2":"Una acera roja en California significa que no se puede detener, esperar ni estacionar, salvo un autobús en una zona marcada para autobuses.","p":"Correcto. Acera roja: prohibido detenerse, esperar o estacionarse."},"ref":{"doc":"CA","page":28}},{"id":"ca-016","scope":"CA","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In California, what does a yellow-painted curb mean?","o":["Stop only to load or unload passengers or freight","Park for as long as you like","Emergency vehicles only","Parking for people with disabilities"],"h1":"Think of delivery trucks.","h2":"A yellow curb in California is a loading zone: you may stop only as long as needed to load or unload passengers or freight.","p":"Right. Yellow curb: stop only to load or unload."},"es":{"q":"En California, ¿qué significa una acera pintada de amarillo?","o":["Detenerse solo para subir o bajar pasajeros o carga","Estacionarse todo el tiempo que quiera","Solo vehículos de emergencia","Estacionamiento para personas con discapacidad"],"h1":"Piense en los camiones de reparto.","h2":"Una acera amarilla en California es una zona de carga: usted puede detenerse solo el tiempo necesario para subir o bajar pasajeros o carga.","p":"Correcto. Acera amarilla: deténgase solo para cargar o descargar."},"ref":{"doc":"CA","page":28}},{"id":"ca-017","scope":"CA","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In California, what does a white-painted curb mean?","o":["Parking for people with disabilities","Stop only long enough to pick up or drop off passengers","Parking for a posted time limit","No stopping at any time"],"h1":"It is for very short stops with people, not cargo.","h2":"A white curb in California allows a stop only long enough to pick up or drop off passengers.","p":"Right. White curb: a short stop for passengers."},"es":{"q":"En California, ¿qué significa una acera pintada de blanco?","o":["Estacionamiento para personas con discapacidad","Detenerse solo para recoger o dejar pasajeros","Estacionamiento con límite de tiempo indicado","Prohibido detenerse en todo momento"],"h1":"Es para paradas muy cortas con personas, no con carga.","h2":"Una acera blanca en California permite detenerse solo el tiempo necesario para recoger o dejar pasajeros.","p":"Correcto. Acera blanca: parada corta para pasajeros."},"ref":{"doc":"CA","page":28}},{"id":"ca-018","scope":"CA","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In California, what does a green-painted curb mean?","o":["No parking at any time","Loading for trucks only","Parking for a limited time shown on a sign or the curb","Parking for people with disabilities"],"h1":"Green lets you park, but not forever.","h2":"A green curb in California allows parking only for a limited time, which is posted on a nearby sign or painted on the curb.","p":"Right. Green curb: parking for a limited time."},"es":{"q":"En California, ¿qué significa una acera pintada de verde?","o":["Prohibido estacionarse en todo momento","Carga solo para camiones","Estacionamiento por tiempo limitado, indicado en un letrero o en la acera","Estacionamiento para personas con discapacidad"],"h1":"El verde le permite estacionarse, pero no para siempre.","h2":"Una acera verde en California permite estacionarse solo por un tiempo limitado, que aparece en un letrero cercano o pintado en la acera.","p":"Correcto. Acera verde: estacionamiento por tiempo limitado."},"ref":{"doc":"CA","page":28}},{"id":"ca-019","scope":"CA","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In California, what does a blue-painted curb mean?","o":["Parking for electric cars only","Taxi stand only","Short stop to drop off mail","Parking only for people with a disability placard or plate"],"h1":"This color matches a well-known access symbol.","h2":"A blue curb in California is for people with disabilities, and the vehicle must show a disability placard or special license plate.","p":"Right. Blue curb: disability parking with a placard or plate."},"es":{"q":"En California, ¿qué significa una acera pintada de azul?","o":["Estacionamiento solo para autos eléctricos","Solo parada de taxis","Parada corta para dejar correo","Estacionamiento solo para personas con placa o letrero de discapacidad"],"h1":"Este color coincide con un símbolo conocido de accesibilidad.","h2":"Una acera azul en California es para personas con discapacidad, y el vehículo debe mostrar un letrero o una placa especial de discapacidad.","p":"Correcto. Acera azul: estacionamiento para personas con discapacidad, con letrero o placa."},"ref":{"doc":"CA","page":28}},{"id":"ca-020","scope":"CA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In California, when must you turn on your headlights during the day?","o":["Only in tunnels","When your wipers are on all the time because of rain, snow or fog","Only on freeways","Only after 6 p.m."],"h1":"Think about what your windshield needs in bad weather.","h2":"California requires your low-beam headlights whenever rain, snow or fog makes you use your wipers.","p":"Right. Wipers on all the time means headlights on."},"es":{"q":"En California, ¿cuándo debe encender las luces delanteras durante el día?","o":["Solo en túneles","Cuando usa los limpiaparabrisas todo el tiempo por lluvia, nieve o niebla","Solo en autopistas","Solo después de las 6 p.m."],"h1":"Piense en lo que necesita su parabrisas con mal tiempo.","h2":"California exige las luces bajas cada vez que la lluvia, la nieve o la niebla le obligan a usar los limpiaparabrisas.","p":"Correcto. Limpiaparabrisas todo el tiempo significa luces encendidas."},"ref":{"doc":"CA","page":11}},{"id":"ca-021","scope":"CA","cat":"licensing","sign":null,"c":0,"en":{"q":"In California, since 2025, what is the minimum liability insurance for injury to one person?","o":["$30,000","$15,000","$50,000","$25,000"],"h1":"The old amount was doubled in 2025.","h2":"Since January 1, 2025, California requires at least $30,000 for injury to one person, $60,000 per crash, and $15,000 for property damage.","p":"Right. The minimum is now $30,000 per injured person."},"es":{"q":"En California, desde 2025, ¿cuál es el seguro de responsabilidad mínimo por lesiones a una persona?","o":["$30,000","$15,000","$50,000","$25,000"],"h1":"La cantidad anterior se duplicó en 2025.","h2":"Desde el 1 de enero de 2025, California exige por lo menos $30,000 por lesiones a una persona, $60,000 por choque y $15,000 por daños a la propiedad.","p":"Correcto. El mínimo ahora es $30,000 por persona lesionada."},"ref":{"doc":"CA","page":76}},{"id":"ca-022","scope":"CA","cat":"licensing","sign":null,"c":2,"en":{"q":"In California, since 2025, what is the minimum liability insurance for property damage?","o":["$5,000","$10,000","$15,000","$25,000"],"h1":"It is half of the amount required for injury to one person.","h2":"California requires at least $15,000 of coverage for damage to other people's property.","p":"Right. Property damage coverage must be at least $15,000."},"es":{"q":"En California, desde 2025, ¿cuál es el seguro de responsabilidad mínimo por daños a la propiedad?","o":["$5,000","$10,000","$15,000","$25,000"],"h1":"Es la mitad de la cantidad exigida por lesiones a una persona.","h2":"California exige por lo menos $15,000 de cobertura por daños a la propiedad de otras personas.","p":"Correcto. La cobertura por daños a la propiedad debe ser de por lo menos $15,000."},"ref":{"doc":"CA","page":76}},{"id":"ca-023","scope":"CA","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In California, how close to a fire hydrant may you park when the curb is not painted?","o":["No closer than 5 feet","No closer than 15 feet","No closer than 30 feet","No closer than 10 feet"],"h1":"Firefighters need room for their hoses and truck.","h2":"In California you must stay 15 feet away from a fire hydrant on either side, even when the curb is not painted red.","p":"Right. Park at least 15 feet from a hydrant."},"es":{"q":"En California, ¿a qué distancia de un hidrante puede estacionarse cuando la acera no está pintada?","o":["A no menos de 5 pies","A no menos de 15 pies","A no menos de 30 pies","A no menos de 10 pies"],"h1":"Los bomberos necesitan espacio para sus mangueras y su camión.","h2":"En California usted debe quedarse a 15 pies de un hidrante por cada lado, aunque la acera no esté pintada de rojo.","p":"Correcto. Estaciónese por lo menos a 15 pies de un hidrante."},"ref":{"doc":"CA","page":28}},{"id":"ca-024","scope":"CA","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In California, what is the highest speed limit on most highways, unless a sign shows a different limit?","o":["55 mph","75 mph","70 mph","65 mph"],"h1":"Higher limits apply only where signs say so.","h2":"In California the general maximum is 65 mph; some freeways are posted at 70 mph, and you must follow the signs.","p":"Right. The general maximum is 65 mph unless a sign says 70."},"es":{"q":"En California, ¿cuál es el límite de velocidad más alto en la mayoría de las carreteras, si un letrero no indica otro?","o":["55 mph","75 mph","70 mph","65 mph"],"h1":"Los límites más altos solo valen donde los letreros lo indican.","h2":"En California el máximo general es 65 mph; algunas autopistas tienen un letrero de 70 mph, y usted debe seguir los letreros.","p":"Correcto. El máximo general es 65 mph, salvo que un letrero diga 70."},"ref":{"doc":"CA","page":67}},{"id":"ca-025","scope":"CA","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In California, what is the speed limit on a two-lane undivided highway unless signs show otherwise?","o":["55 mph","45 mph","65 mph","50 mph"],"h1":"It is ten less than the general highway maximum.","h2":"On a two-lane undivided highway in California, the limit is 55 mph unless signs post a higher speed.","p":"Right. Two-lane undivided highways are 55 mph unless posted."},"es":{"q":"En California, ¿cuál es el límite de velocidad en una carretera de dos carriles sin división, si los letreros no indican otro?","o":["55 mph","45 mph","65 mph","50 mph"],"h1":"Es diez menos que el máximo general en carretera.","h2":"En una carretera de dos carriles sin división en California, el límite es 55 mph, salvo que los letreros indiquen una velocidad mayor.","p":"Correcto. En carreteras de dos carriles sin división el límite es 55 mph si no hay letrero."},"ref":{"doc":"CA","page":67}},{"id":"ca-026","scope":"CA","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In California, what is the speed limit in a residential district when no sign is posted?","o":["15 mph","35 mph","25 mph","30 mph"],"h1":"It is the same as the usual school zone limit.","h2":"Unless a sign shows another limit, the speed limit in a California residential or business district is 25 mph.","p":"Right. Residential districts are 25 mph unless posted."},"es":{"q":"En California, ¿cuál es el límite de velocidad en una zona residencial cuando no hay letrero?","o":["15 mph","35 mph","25 mph","30 mph"],"h1":"Es igual al límite usual de una zona escolar.","h2":"Si no hay un letrero con otro límite, la velocidad máxima en una zona residencial o comercial de California es 25 mph.","p":"Correcto. En zonas residenciales el límite es 25 mph si no hay letrero."},"ref":{"doc":"CA","page":52}},{"id":"ca-027","scope":"CA","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In California, what is the speed limit in an alley?","o":["10 mph","15 mph","20 mph","25 mph"],"h1":"Alleys are narrow, so the limit is lower than in a neighborhood.","h2":"The speed limit in a California alley is 15 mph, because alleys are narrow and people and cars can appear suddenly.","p":"Right. Alleys have a 15 mph limit."},"es":{"q":"En California, ¿cuál es el límite de velocidad en un callejón?","o":["10 mph","15 mph","20 mph","25 mph"],"h1":"Los callejones son angostos, así que el límite es menor que en un vecindario.","h2":"El límite de velocidad en un callejón de California es 15 mph, porque los callejones son angostos y pueden aparecer personas o autos de repente.","p":"Correcto. En los callejones el límite es 15 mph."},"ref":{"doc":"CA","page":51}},{"id":"ca-028","scope":"CA","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In California, the \"basic speed law\" means what?","o":["You may always drive at the posted limit","You may go 5 mph over the limit to pass","Only trucks must slow down in rain","You must never drive faster than is safe for conditions"],"h1":"Weather, traffic and the road all matter.","h2":"California's basic speed law says you must never drive faster than is safe for the weather, traffic and road, so you can get a ticket even below the posted limit.","p":"Right. Never drive faster than is safe for conditions."},"es":{"q":"En California, ¿qué significa la \"ley básica de velocidad\"?","o":["Que siempre puede manejar al límite indicado","Que puede ir 5 mph sobre el límite para rebasar","Que solo los camiones deben bajar la velocidad con lluvia","Que nunca debe manejar más rápido de lo seguro para las condiciones"],"h1":"El clima, el tráfico y el camino importan.","h2":"La ley básica de velocidad de California dice que nunca debe manejar más rápido de lo seguro para el clima, el tráfico y el camino, así que le pueden multar aunque vaya por debajo del límite indicado.","p":"Correcto. Nunca maneje más rápido de lo seguro para las condiciones."},"ref":{"doc":"CA","page":67}},{"id":"ca-030","scope":"CA","cat":"licensing","sign":null,"c":2,"en":{"q":"In California, how many tries do you get to pass the knowledge test before you must apply again?","o":["One try","Two tries","Three tries","Five tries"],"h1":"It is more than two and fewer than four.","h2":"California gives you three tries at the knowledge test on one application; after that you must apply and pay again.","p":"Right. You get three tries per application."},"es":{"q":"En California, ¿cuántos intentos tiene para aprobar el examen de conocimientos antes de tener que solicitar de nuevo?","o":["Un intento","Dos intentos","Tres intentos","Cinco intentos"],"h1":"Son más de dos y menos de cuatro.","h2":"California le da tres intentos para el examen de conocimientos con una solicitud; después tiene que solicitar y pagar de nuevo.","p":"Correcto. Tiene tres intentos por solicitud."},"ref":{"doc":"CA","page":5}},{"id":"co-001","scope":"CO","cat":"licensing","sign":null,"c":1,"en":{"q":"In Colorado, what is the youngest age to get an instruction permit?","o":["14 years old","15 years old","16 years old","17 years old"],"h1":"You must first finish a 30-hour driver education course to start this early.","h2":"In Colorado you can get an instruction permit at 15 if you have completed an approved 30-hour driver education course.","p":"Right. A Colorado permit can start at 15, after driver education."},"es":{"q":"En Colorado, ¿cuál es la edad mínima para obtener un permiso de instrucción?","o":["14 años","15 años","16 años","17 años"],"h1":"Primero debe terminar un curso de educación vial de 30 horas para empezar tan temprano.","h2":"En Colorado usted puede obtener un permiso de instrucción a los 15 años si completó un curso aprobado de educación vial de 30 horas.","p":"Correcto. El permiso en Colorado puede empezar a los 15, después de la educación vial."},"ref":{"doc":"CO","page":null}},{"id":"co-002","scope":"CO","cat":"licensing","sign":null,"c":3,"en":{"q":"In Colorado, starting January 1, 2027, what must a new permit applicant aged 15 to 17 complete first?","o":["A 4-hour driver awareness class","A first aid course","Ten hours with a tutor","A 30-hour driver education course"],"h1":"It is the longer of the two courses that used to be allowed.","h2":"From January 1, 2027, Colorado requires applicants aged 15 to 17 to finish an approved 30-hour driver education course, online or in person, before they get a permit.","p":"Right. From 2027, teens need the 30-hour driver education course first."},"es":{"q":"En Colorado, a partir del 1 de enero de 2027, ¿qué debe completar primero quien solicita un permiso entre los 15 y los 17 años?","o":["Una clase de conciencia vial de 4 horas","Un curso de primeros auxilios","Diez horas con un tutor","Un curso de educación vial de 30 horas"],"h1":"Es el más largo de los dos cursos que antes se permitían.","h2":"Desde el 1 de enero de 2027, Colorado exige que los solicitantes de 15 a 17 años terminen un curso aprobado de educación vial de 30 horas, en línea o en persona, antes de recibir el permiso.","p":"Correcto. Desde 2027, los adolescentes necesitan primero el curso de 30 horas."},"ref":{"doc":"CO","page":null}},{"id":"co-003","scope":"CO","cat":"licensing","sign":null,"c":3,"en":{"q":"In Colorado, how long must a driver under 18 hold an instruction permit before getting a license?","o":["3 months","6 months","9 months","12 months"],"h1":"Think of one full year of practice.","h2":"A Colorado driver under 18 must hold the instruction permit for at least 12 months before getting a driver license, so there is a full year of practice.","p":"Right. Under 18, the permit must be held for 12 months."},"es":{"q":"En Colorado, ¿cuánto tiempo debe tener el permiso de instrucción un conductor menor de 18 años antes de obtener la licencia?","o":["3 meses","6 meses","9 meses","12 meses"],"h1":"Piense en un año completo de práctica.","h2":"En Colorado, un conductor menor de 18 años debe tener el permiso de instrucción por lo menos 12 meses antes de obtener la licencia, para tener un año completo de práctica.","p":"Correcto. Si es menor de 18, debe tener el permiso 12 meses."},"ref":{"doc":"CO","page":2}},{"id":"co-004","scope":"CO","cat":"licensing","sign":null,"c":2,"en":{"q":"In Colorado, how many hours of supervised driving must a teen log before getting a license?","o":["20 hours","30 hours","50 hours","70 hours"],"h1":"The log sheet asks for more than 40 hours.","h2":"A Colorado teen must log at least 50 hours of supervised driving before getting a license, so the new driver has real practice on the road.","p":"Right. Colorado asks for 50 logged hours."},"es":{"q":"En Colorado, ¿cuántas horas de manejo supervisado debe registrar un adolescente antes de obtener la licencia?","o":["20 horas","30 horas","50 horas","70 horas"],"h1":"El registro pide más de 40 horas.","h2":"En Colorado, un adolescente debe registrar por lo menos 50 horas de manejo supervisado antes de obtener la licencia, para tener práctica real en la calle.","p":"Correcto. Colorado pide 50 horas registradas."},"ref":{"doc":"CO","page":2}},{"id":"co-005","scope":"CO","cat":"licensing","sign":null,"c":0,"en":{"q":"In Colorado, how many of the teen's logged driving hours must be at night?","o":["10 hours","5 hours","15 hours","20 hours"],"h1":"It is one fifth of the total hours.","h2":"Of the 50 logged hours in Colorado, at least 10 must be driven at night, because driving in the dark is harder and needs practice.","p":"Right. 10 of the 50 hours must be at night."},"es":{"q":"En Colorado, ¿cuántas de las horas registradas por el adolescente deben ser de noche?","o":["10 horas","5 horas","15 horas","20 horas"],"h1":"Es una quinta parte del total de horas.","h2":"De las 50 horas registradas en Colorado, por lo menos 10 deben ser de noche, porque manejar en la oscuridad es más difícil y necesita práctica.","p":"Correcto. 10 de las 50 horas deben ser de noche."},"ref":{"doc":"CO","page":2}},{"id":"co-006","scope":"CO","cat":"licensing","sign":null,"c":1,"en":{"q":"In Colorado, who must ride with a minor who drives on an instruction permit?","o":["Any licensed driver age 18 or older","A licensed driver age 21 or older in the front seat","Any adult sitting in the back seat","A driving instructor only"],"h1":"The person must be old enough to drink alcohol legally and sit close to the driver.","h2":"A Colorado minor with a permit must drive with a licensed driver who is at least 21 and sits in the front passenger seat, so help is always within reach.","p":"Right. The supervisor is licensed, 21 or older, and in the front seat."},"es":{"q":"En Colorado, ¿quién debe acompañar a un menor que maneja con permiso de instrucción?","o":["Cualquier conductor con licencia de 18 años o más","Un conductor con licencia de 21 años o más en el asiento delantero","Cualquier adulto en el asiento trasero","Solamente un instructor de manejo"],"h1":"La persona debe tener edad legal para tomar alcohol y sentarse cerca del conductor.","h2":"En Colorado, un menor con permiso debe manejar con un conductor con licencia que tenga por lo menos 21 años y vaya en el asiento del pasajero delantero, para que la ayuda esté siempre a la mano.","p":"Correcto. El supervisor tiene licencia, 21 años o más, y va adelante."},"ref":{"doc":"CO","page":1}},{"id":"co-007","scope":"CO","cat":"licensing","sign":null,"c":0,"en":{"q":"In Colorado, who usually signs the affidavit of liability for a driver under 18?","o":["A parent or legal guardian","A school principal","A driving school teacher","A police officer"],"h1":"It is the adult who takes financial responsibility for the teen.","h2":"In Colorado the affidavit of liability is usually signed by a parent or legal guardian, and that adult accepts legal responsibility for the teen's driving.","p":"Right. A parent or legal guardian signs it."},"es":{"q":"En Colorado, ¿quién firma normalmente la declaración de responsabilidad de un conductor menor de 18 años?","o":["Un padre, madre o tutor legal","El director de la escuela","Un maestro de manejo","Un agente de policía"],"h1":"Es el adulto que asume la responsabilidad económica del adolescente.","h2":"En Colorado, la declaración jurada de responsabilidad normalmente la firma uno de los padres o el tutor legal, y ese adulto acepta la responsabilidad legal por la manera de manejar del joven.","p":"Correcto. La firma un padre, madre o tutor legal."},"ref":{"doc":"CO","page":2}},{"id":"co-008","scope":"CO","cat":"licensing","sign":null,"c":2,"en":{"q":"In Colorado, during the first year with a license, when may a teen driver not drive?","o":["From 10 p.m. to 5 a.m.","From 11 p.m. to 6 a.m.","From midnight to 5 a.m.","From 1 a.m. to 6 a.m."],"h1":"The limit begins exactly when the date changes.","h2":"A Colorado driver under 18 in the first year of a license may not drive from midnight to 5 a.m., except for allowed reasons such as work, school or a medical emergency.","p":"Right. No driving from midnight to 5 a.m. in the first year."},"es":{"q":"En Colorado, durante el primer año con licencia, ¿cuándo no puede manejar un conductor adolescente?","o":["De 10 p.m. a 5 a.m.","De 11 p.m. a 6 a.m.","De medianoche a 5 a.m.","De 1 a.m. a 6 a.m."],"h1":"El límite empieza justo cuando cambia la fecha.","h2":"En Colorado, un conductor menor de 18 años en su primer año con licencia no puede manejar de medianoche a 5 a.m., salvo por razones permitidas como trabajo, escuela o una emergencia médica.","p":"Correcto. No se maneja de medianoche a 5 a.m. el primer año."},"ref":{"doc":"CO","page":2}},{"id":"co-009","scope":"CO","cat":"licensing","sign":null,"c":3,"en":{"q":"In Colorado, during the first six months with a license, which passengers may a teen driver carry?","o":["Up to two friends of any age","One passenger under 21","Up to three passengers under 21","Only passengers 21 or older"],"h1":"Siblings and medical emergencies are the only exceptions to this strict rule.","h2":"For the first six months with a Colorado license, a teen may carry only passengers who are 21 or older, except brothers and sisters or in a medical emergency.","p":"Right. In the first six months, only passengers 21 or older."},"es":{"q":"En Colorado, durante los primeros seis meses con licencia, ¿qué pasajeros puede llevar un conductor adolescente?","o":["Hasta dos amigos de cualquier edad","Un pasajero menor de 21 años","Hasta tres pasajeros menores de 21 años","Solamente pasajeros de 21 años o más"],"h1":"Los hermanos y las emergencias médicas son las únicas excepciones a esta regla estricta.","h2":"Durante los primeros seis meses con licencia en Colorado, un adolescente solo puede llevar pasajeros de 21 años o más, salvo sus hermanos o en una emergencia médica.","p":"Correcto. Los primeros seis meses, solo pasajeros de 21 años o más."},"ref":{"doc":"CO","page":2}},{"id":"co-010","scope":"CO","cat":"licensing","sign":null,"c":1,"en":{"q":"In Colorado, during the second six months with a license, how many passengers under 21 may a teen driver carry?","o":["None at all","One","Two","Three"],"h1":"The limit loosens a little after the first six months.","h2":"In the second six months with a Colorado license, a teen may carry one passenger under 21, which is a small step up from the first six months.","p":"Right. One passenger under 21 is allowed in the second six months."},"es":{"q":"En Colorado, durante los segundos seis meses con licencia, ¿cuántos pasajeros menores de 21 años puede llevar un conductor adolescente?","o":["Ninguno","Uno","Dos","Tres"],"h1":"El límite se relaja un poco después de los primeros seis meses.","h2":"En los segundos seis meses con licencia en Colorado, un adolescente puede llevar un pasajero menor de 21 años, un pequeño paso más que en los primeros seis meses.","p":"Correcto. En los segundos seis meses se permite un pasajero menor de 21."},"ref":{"doc":"CO","page":2}},{"id":"co-011","scope":"CO","cat":"licensing","sign":null,"c":2,"en":{"q":"In Colorado, which young passengers may ride with a new teen driver at any time?","o":["Classmates","Teammates","The driver's brothers and sisters","Neighbors' children"],"h1":"Think of family who live in the same home.","h2":"Colorado lets a new teen driver carry brothers and sisters at any time, even while other passengers under 21 are limited.","p":"Right. Siblings may ride at any time."},"es":{"q":"En Colorado, ¿qué pasajeros jóvenes pueden viajar con un conductor adolescente nuevo en cualquier momento?","o":["Compañeros de clase","Compañeros de equipo","Los hermanos y hermanas del conductor","Los hijos de los vecinos"],"h1":"Piense en la familia que vive en la misma casa.","h2":"Colorado permite que un conductor adolescente nuevo lleve a sus hermanos y hermanas en cualquier momento, aunque otros pasajeros menores de 21 años estén limitados.","p":"Correcto. Los hermanos pueden ir en cualquier momento."},"ref":{"doc":"CO","page":2}},{"id":"co-012","scope":"CO","cat":"licensing","sign":null,"c":0,"en":{"q":"In Colorado, how many passengers may sit in the front seat when a new teen driver is driving?","o":["Only one","Two, if they are small","As many as fit","None at all"],"h1":"Each front-seat rider needs a seat belt of their own.","h2":"Colorado allows only one passenger in the front seat with a new teen driver, and everyone in the car must wear a seat belt.","p":"Right. Only one passenger may sit in the front."},"es":{"q":"En Colorado, ¿cuántos pasajeros pueden ir en el asiento delantero cuando maneja un adolescente nuevo?","o":["Solamente uno","Dos, si son pequeños","Todos los que quepan","Ninguno"],"h1":"Cada pasajero de adelante necesita su propio cinturón.","h2":"Colorado permite solo un pasajero en el asiento delantero con un conductor adolescente nuevo, y todos en el carro deben usar el cinturón de seguridad.","p":"Correcto. Solo un pasajero puede ir adelante."},"ref":{"doc":"CO","page":null}},{"id":"co-013","scope":"CO","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Colorado, since January 1, 2025, when may a driver hold a phone to talk or text while driving?","o":["Only to call for help in an emergency","When stopped at a red light","When the call is short","When traffic is light"],"h1":"Holding the phone is allowed only when help is needed.","h2":"Since January 1, 2025, a Colorado driver may not hold a phone to talk or text while driving, except to call police, fire or other help in an emergency.","p":"Right. Hold the phone only to call for help in an emergency."},"es":{"q":"En Colorado, desde el 1 de enero de 2025, ¿cuándo puede un conductor sostener el teléfono en la mano para hablar o enviar mensajes mientras maneja?","o":["Solo para pedir ayuda en una emergencia","Cuando está detenido en un semáforo en rojo","Cuando la llamada es corta","Cuando hay poco tráfico"],"h1":"Sostener el teléfono solo se permite cuando se necesita ayuda.","h2":"Desde el 1 de enero de 2025, un conductor en Colorado no puede sostener el teléfono para hablar o enviar mensajes mientras maneja, excepto para llamar a la policía, a los bomberos u otra ayuda en una emergencia.","p":"Correcto. Sostenga el teléfono solo para pedir ayuda en una emergencia."},"ref":{"doc":"CO","page":null}},{"id":"co-014","scope":"CO","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Colorado, since January 1, 2025, how may a driver age 18 or older use a phone while driving?","o":["Holding it at any time","Holding it only on highways","Only with a hands-free accessory","Not at all, even hands-free"],"h1":"The adult's hands must stay free.","h2":"Since January 1, 2025, Colorado drivers 18 and older may not hold or handle a phone while driving; they may use it only with a hands-free accessory.","p":"Right. Adults must use hands-free."},"es":{"q":"En Colorado, desde el 1 de enero de 2025, ¿cómo puede usar el teléfono al manejar un conductor de 18 años o más?","o":["Sosteniéndolo en cualquier momento","Sosteniéndolo solo en las autopistas","Solo con un accesorio de manos libres","De ninguna manera, ni con manos libres"],"h1":"Las manos del adulto deben quedar libres.","h2":"Desde el 1 de enero de 2025, los conductores de 18 años o más en Colorado no pueden sostener ni manipular el teléfono al manejar; solo pueden usarlo con un accesorio de manos libres.","p":"Correcto. Los adultos deben usar manos libres."},"ref":{"doc":"CO","page":null}},{"id":"co-015","scope":"CO","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Colorado, what is the penalty for a first offense of holding a phone while driving?","o":["A warning only","A $75 fine and 2 points","A $500 fine and 6 points","A 30-day suspension"],"h1":"The fine is under one hundred dollars.","h2":"A first offense under Colorado's hands-free law brings a $75 fine and 2 points on the license, and the penalties grow for repeat offenses.","p":"Right. The first offense is $75 and 2 points."},"es":{"q":"En Colorado, ¿cuál es la sanción por la primera vez que se sostiene el teléfono al manejar?","o":["Solo una advertencia","Una multa de $75 y 2 puntos","Una multa de $500 y 6 puntos","Una suspensión de 30 días"],"h1":"La multa es de menos de cien dólares.","h2":"La primera infracción de la ley de manos libres de Colorado tiene una multa de $75 y 2 puntos en la licencia, y las sanciones aumentan si se repite.","p":"Correcto. La primera vez son $75 y 2 puntos."},"ref":{"doc":"CO","page":null}},{"id":"co-016","scope":"CO","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Colorado, a driver under 21 can be charged with underage drinking and driving starting at what blood alcohol level?","o":["0.08 percent","0.05 percent","0.10 percent","0.02 percent"],"h1":"It is the lowest number on the list.","h2":"In Colorado a driver under 21 can be charged with underage drinking and driving at a blood alcohol level of 0.02 percent, far below the adult limit.","p":"Right. Under 21, the limit starts at 0.02."},"es":{"q":"En Colorado, ¿a partir de qué nivel de alcohol en la sangre se puede acusar a un conductor menor de 21 años de manejar después de beber?","o":["0.08 por ciento","0.05 por ciento","0.10 por ciento","0.02 por ciento"],"h1":"Es el número más bajo de la lista.","h2":"En Colorado, a un conductor menor de 21 años se le puede acusar de manejar después de beber con un nivel de alcohol de 0.02 por ciento, muy por debajo del límite para adultos.","p":"Correcto. Para menores de 21, el límite empieza en 0.02."},"ref":{"doc":"CO","page":3}},{"id":"co-017","scope":"CO","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Colorado, driving while ability impaired (DWAI) can be charged at about what blood alcohol level?","o":["0.02 percent","0.05 percent","0.12 percent","0.15 percent"],"h1":"It is lower than the 0.08 DUI level.","h2":"Colorado can charge driving while ability impaired at a blood alcohol level of about 0.05 percent, so you can be in trouble before you reach the 0.08 DUI level.","p":"Right. DWAI starts at about 0.05."},"es":{"q":"En Colorado, ¿con qué nivel aproximado de alcohol en la sangre se puede acusar de manejar con la capacidad disminuida (DWAI)?","o":["0.02 por ciento","0.05 por ciento","0.12 por ciento","0.15 por ciento"],"h1":"Es menor que el nivel de 0.08 de DUI.","h2":"Colorado puede acusar de manejar con la capacidad disminuida con un nivel de alcohol de aproximadamente 0.05 por ciento, así que puede tener problemas antes de llegar al nivel de 0.08 de DUI.","p":"Correcto. El DWAI empieza alrededor de 0.05."},"ref":{"doc":"CO","page":4}},{"id":"co-018","scope":"CO","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Colorado, at what blood alcohol level is a driver 21 or older automatically considered driving under the influence (DUI)?","o":["0.08 percent","0.02 percent","0.05 percent","0.10 percent"],"h1":"It is the most common adult limit in the United States.","h2":"In Colorado a driver 21 or older is automatically considered DUI at a blood alcohol level of 0.08 percent or higher.","p":"Right. The adult DUI level is 0.08."},"es":{"q":"En Colorado, ¿con qué nivel de alcohol en la sangre se considera automáticamente que un conductor de 21 años o más maneja bajo la influencia (DUI)?","o":["0.08 por ciento","0.02 por ciento","0.05 por ciento","0.10 por ciento"],"h1":"Es el límite para adultos más común en Estados Unidos.","h2":"En Colorado, se considera automáticamente DUI a un conductor de 21 años o más con un nivel de alcohol de 0.08 por ciento o más.","p":"Correcto. El nivel de DUI para adultos es 0.08."},"ref":{"doc":"CO","page":3}},{"id":"co-019","scope":"CO","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Colorado, you approach a stopped car on the roadside with its hazard lights flashing. What must you do?","o":["Honk and keep your speed","Stop behind it and wait","Move over one lane if safe; if not, slow down","Slow down only if police are there"],"h1":"The law protects any stopped vehicle that shows hazard lights.","h2":"In Colorado, when you pass a stopped vehicle with flashing hazard lights, you must move over one lane if you safely can; if you cannot, you must slow down to a safe speed.","p":"Right. Move over a lane, or slow down if you cannot."},"es":{"q":"En Colorado, usted se acerca a un carro detenido al lado del camino con las luces de emergencia encendidas. ¿Qué debe hacer?","o":["Tocar la bocina y seguir igual","Pararse detrás y esperar","Cambiarse un carril si es seguro; si no, bajar la velocidad","Bajar la velocidad solo si hay policía"],"h1":"La ley protege a cualquier vehículo detenido con luces de emergencia.","h2":"En Colorado, cuando usted pasa un vehículo detenido con las luces de emergencia encendidas, debe cambiarse un carril si puede hacerlo con seguridad; si no puede, debe bajar a una velocidad segura.","p":"Correcto. Cámbiese de carril, o baje la velocidad si no puede."},"ref":{"doc":"CO","page":null}},{"id":"co-020","scope":"CO","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Colorado, since August 2023, which stopped vehicles does the move-over law protect?","o":["Only police cars","Only tow trucks and ambulances","Only road crew trucks","Any stopped vehicle with hazard lights on"],"h1":"The 2023 change made the rule much wider.","h2":"Since August 2023, Colorado's move-over law covers any stopped vehicle with flashing hazard lights, not only emergency and service vehicles.","p":"Right. It covers any stopped vehicle with hazard lights."},"es":{"q":"En Colorado, desde agosto de 2023, ¿qué vehículos detenidos protege la ley de cambiarse de carril?","o":["Solo los carros de policía","Solo las grúas y ambulancias","Solo los camiones de obras viales","Cualquier vehículo detenido con luces de emergencia"],"h1":"El cambio de 2023 amplió mucho la regla.","h2":"Desde agosto de 2023, la ley de Colorado de cambiarse de carril protege a cualquier vehículo detenido con luces de emergencia, no solo a vehículos de emergencia y de servicio.","p":"Correcto. Protege a cualquier vehículo detenido con luces de emergencia."},"ref":{"doc":"CO","page":null}},{"id":"co-021","scope":"CO","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Colorado, if no sign says otherwise, what is the speed limit in a residence district?","o":["25 mph","30 mph","35 mph","40 mph"],"h1":"It is a little faster than the business district limit.","h2":"Colorado law sets 30 mph as the lawful speed in a residence district when no other limit is posted.","p":"Right. A residence district is 30 mph."},"es":{"q":"En Colorado, si no hay letrero que diga otra cosa, ¿cuál es el límite de velocidad en una zona residencial?","o":["25 mph","30 mph","35 mph","40 mph"],"h1":"Es un poco más rápido que el límite de la zona comercial.","h2":"La ley de Colorado fija 30 mph como velocidad legal en una zona residencial cuando no hay otro límite indicado.","p":"Correcto. Una zona residencial es de 30 mph."},"ref":{"doc":"CO","page":12}},{"id":"co-022","scope":"CO","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Colorado, if no sign says otherwise, what is the speed limit in a business district?","o":["25 mph","30 mph","35 mph","20 mph"],"h1":"It is slower than the residence district limit.","h2":"Colorado law sets 25 mph as the lawful speed in a business district when no other limit is posted, because shops bring many people and cars together.","p":"Right. A business district is 25 mph."},"es":{"q":"En Colorado, si no hay letrero que diga otra cosa, ¿cuál es el límite de velocidad en una zona comercial?","o":["25 mph","30 mph","35 mph","20 mph"],"h1":"Es más lento que el límite de la zona residencial.","h2":"La ley de Colorado fija 25 mph como velocidad legal en una zona comercial cuando no hay otro límite indicado, porque las tiendas reúnen a mucha gente y muchos carros.","p":"Correcto. Una zona comercial es de 25 mph."},"ref":{"doc":"CO","page":11}},{"id":"co-023","scope":"CO","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Colorado, what is the lawful speed on a narrow, winding mountain highway or a blind curve, if no sign says otherwise?","o":["40 mph","30 mph","20 mph","55 mph"],"h1":"It is the lowest number in Colorado's speed law.","h2":"Colorado law sets 20 mph on narrow, winding mountain highways and blind curves when no other limit is posted, because you cannot see far ahead.","p":"Right. Narrow mountain roads and blind curves are 20 mph."},"es":{"q":"En Colorado, ¿cuál es la velocidad legal en una carretera de montaña estrecha y con curvas, o en una curva ciega, si no hay letrero?","o":["40 mph","30 mph","20 mph","55 mph"],"h1":"Es el número más bajo de la ley de velocidad de Colorado.","h2":"La ley de Colorado fija 20 mph en carreteras de montaña estrechas y con curvas, y en curvas ciegas, cuando no hay otro límite indicado, porque no se ve lejos.","p":"Correcto. Las carreteras de montaña estrechas y las curvas ciegas son de 20 mph."},"ref":{"doc":"CO","page":11}},{"id":"co-024","scope":"CO","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Colorado, what is the highest speed limit that may be set on any highway?","o":["65 mph","70 mph","80 mph","75 mph"],"h1":"Only some rural interstate highways are posted this high.","h2":"Colorado law does not allow any highway speed limit above 75 mph, and only some rural interstate stretches are posted that high.","p":"Right. The highest limit in Colorado is 75 mph."},"es":{"q":"En Colorado, ¿cuál es el límite de velocidad más alto que se puede fijar en una carretera?","o":["65 mph","70 mph","80 mph","75 mph"],"h1":"Solo algunas autopistas interestatales rurales tienen este límite.","h2":"La ley de Colorado no permite un límite de velocidad mayor de 75 mph en ninguna carretera, y solo algunos tramos rurales de autopista interestatal lo tienen.","p":"Correcto. El límite más alto en Colorado es de 75 mph."},"ref":{"doc":"CO","page":12}},{"id":"co-025","scope":"CO","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Colorado, on a highway with a speed limit of 65 mph or more, when may you drive in the far left lane?","o":["Only to pass or to turn left","Any time traffic is light","Whenever you drive the speed limit","Only at night"],"h1":"This lane has one main job.","h2":"On Colorado highways with a limit of 65 mph or more, the far left lane is for passing or turning left, unless heavy traffic makes it unsafe to move right.","p":"Right. The far left lane is for passing or turning left."},"es":{"q":"En Colorado, en una carretera con límite de 65 mph o más, ¿cuándo puede manejar en el carril del extremo izquierdo?","o":["Solo para rebasar o para girar a la izquierda","Siempre que haya poco tráfico","Siempre que vaya al límite de velocidad","Solo de noche"],"h1":"Este carril tiene una función principal.","h2":"En las carreteras de Colorado con límite de 65 mph o más, el carril del extremo izquierdo es para rebasar o girar a la izquierda, salvo que el tráfico pesado impida pasarse a la derecha con seguridad.","p":"Correcto. El carril del extremo izquierdo es para rebasar o girar a la izquierda."},"ref":{"doc":"CO","page":null}},{"id":"co-026","scope":"CO","cat":"signals","sign":null,"c":0,"en":{"q":"In Colorado, when may you turn left on a red light after a full stop?","o":["From a one-way street onto another one-way street","From any street onto a two-way street","Only when a police officer waves you on","Never, under any conditions"],"h1":"Both streets must have traffic moving in only one direction.","h2":"Colorado allows a left turn on red after a full stop only from a one-way street onto another one-way street, when no sign forbids it and after yielding.","p":"Right. Left on red is only from one-way onto one-way."},"es":{"q":"En Colorado, ¿cuándo puede girar a la izquierda con luz roja después de parar por completo?","o":["De una calle de un solo sentido a otra de un solo sentido","De cualquier calle a una calle de doble sentido","Solo cuando un policía le indica que pase","Nunca, bajo ninguna condición"],"h1":"Las dos calles deben tener tráfico en una sola dirección.","h2":"Colorado permite girar a la izquierda con luz roja, después de parar por completo, solo de una calle de un solo sentido a otra de un solo sentido, si no hay letrero que lo prohíba y después de ceder el paso.","p":"Correcto. Se gira a la izquierda en rojo solo de un sentido a un sentido."},"ref":{"doc":"CO","page":7}},{"id":"co-027","scope":"CO","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Colorado, when a school bus has its red lights flashing and stop arm out, how far away must you stop?","o":["At least 5 feet","At least 20 feet","At least 50 feet","At least 100 feet"],"h1":"The distance is about the length of a large car and a half.","h2":"In Colorado you must stop at least 20 feet from a school bus that shows flashing red lights and its stop arm, so children have room to cross.","p":"Right. Stop at least 20 feet from the bus."},"es":{"q":"En Colorado, cuando un autobús escolar tiene las luces rojas intermitentes y el brazo de alto extendido, ¿a qué distancia debe parar?","o":["Por lo menos a 5 pies","Por lo menos a 20 pies","Por lo menos a 50 pies","Por lo menos a 100 pies"],"h1":"La distancia es como el largo de un carro grande y medio.","h2":"En Colorado usted debe parar por lo menos a 20 pies de un autobús escolar con luces rojas intermitentes y el brazo de alto, para que los niños tengan espacio para cruzar.","p":"Correcto. Pare por lo menos a 20 pies del autobús."},"ref":{"doc":"CO","page":11}},{"id":"co-028","scope":"CO","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Colorado, on a two-lane road, you meet a school bus from the opposite direction with red lights flashing. What must you do?","o":["Slow down and pass with care","Honk and continue","Stop until the lights turn off","Stop only if children are visible"],"h1":"On a road this narrow, children may cross into your lane.","h2":"On a Colorado two-lane road, drivers coming from either direction must stop for a school bus with flashing red lights and wait until the lights turn off.","p":"Right. On a two-lane road, both directions stop."},"es":{"q":"En Colorado, en un camino de dos carriles, usted encuentra de frente un autobús escolar con luces rojas intermitentes. ¿Qué debe hacer?","o":["Bajar la velocidad y pasar con cuidado","Tocar la bocina y seguir","Parar hasta que se apaguen las luces","Parar solo si ve niños"],"h1":"En un camino tan angosto, los niños pueden cruzar a su carril.","h2":"En un camino de dos carriles en Colorado, los conductores de ambas direcciones deben parar ante un autobús escolar con luces rojas intermitentes y esperar hasta que se apaguen.","p":"Correcto. En un camino de dos carriles, paran las dos direcciones."},"ref":{"doc":"CO","page":20}},{"id":"co-029","scope":"CO","cat":"licensing","sign":null,"c":1,"en":{"q":"In Colorado, how many points within 12 months can lead to suspension for a driver age 17 or younger?","o":["4 points","6 points","9 points","12 points"],"h1":"Young drivers get far fewer points than adults before trouble starts.","h2":"A Colorado driver age 17 or younger can be suspended with 6 or more points in any 12 months, or 7 or more points at any time before turning 18.","p":"Right. Under 18, 6 points in 12 months can mean suspension."},"es":{"q":"En Colorado, ¿cuántos puntos en 12 meses pueden causar la suspensión de un conductor de 17 años o menos?","o":["4 puntos","6 puntos","9 puntos","12 puntos"],"h1":"Los conductores jóvenes acumulan muchos menos puntos que los adultos antes de tener problemas.","h2":"En Colorado, a un conductor de 17 años o menos se le puede suspender con 6 puntos o más en 12 meses, o con 7 puntos o más en cualquier momento antes de cumplir 18.","p":"Correcto. Menores de 18: 6 puntos en 12 meses pueden causar suspensión."},"ref":{"doc":"CO","page":null}},{"id":"co-030","scope":"CO","cat":"licensing","sign":null,"c":2,"en":{"q":"In Colorado, how many points within 12 months can lead to suspension for a driver age 18 to 21?","o":["4 points","6 points","9 points","14 points"],"h1":"It is more than the under-18 limit but less than a dozen.","h2":"A Colorado driver age 18 to 21 can be suspended with 9 or more points in any 12 months, 12 in any 24 months, or 14 at any time between 18 and 21.","p":"Right. Ages 18 to 21: 9 points in 12 months."},"es":{"q":"En Colorado, ¿cuántos puntos en 12 meses pueden causar la suspensión de un conductor de 18 a 21 años?","o":["4 puntos","6 puntos","9 puntos","14 puntos"],"h1":"Es más que el límite para menores de 18, pero menos de una docena.","h2":"En Colorado, a un conductor de 18 a 21 años se le puede suspender con 9 puntos o más en 12 meses, 12 en 24 meses, o 14 en cualquier momento entre los 18 y los 21.","p":"Correcto. De 18 a 21 años: 9 puntos en 12 meses."},"ref":{"doc":"CO","page":null}},{"id":"co-031","scope":"CO","cat":"licensing","sign":null,"c":0,"en":{"q":"In Colorado, what is the minimum liability insurance a driver must carry?","o":["$25,000 / $50,000 / $15,000","$10,000 / $20,000 / $10,000","$50,000 / $100,000 / $25,000","$30,000 / $60,000 / $25,000"],"h1":"The property damage part is $15,000.","h2":"Colorado requires at least $25,000 for injury to one person, $50,000 for injuries in one crash, and $15,000 for property damage.","p":"Right. Colorado's minimum is 25/50/15."},"es":{"q":"En Colorado, ¿cuál es el seguro de responsabilidad mínimo que debe tener un conductor?","o":["$25,000 / $50,000 / $15,000","$10,000 / $20,000 / $10,000","$50,000 / $100,000 / $25,000","$30,000 / $60,000 / $25,000"],"h1":"La parte de daños a la propiedad es de $15,000.","h2":"Colorado exige por lo menos $25,000 por lesiones a una persona, $50,000 por lesiones en un mismo choque y $15,000 por daños a la propiedad.","p":"Correcto. El mínimo en Colorado es 25/50/15."},"ref":{"doc":"CO","page":null}},{"id":"co-032","scope":"CO","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Colorado, when the passenger vehicle chain law is active, which vehicles need chains or another approved traction device?","o":["Only two-wheel-drive cars","Only trucks over 16,000 pounds","Only cars with worn tires","All vehicles, including four-wheel drive"],"h1":"It is the last step before a highway closes.","h2":"When Colorado's passenger vehicle chain law is active, every vehicle needs chains or an approved alternative traction device, even all-wheel and four-wheel drive.","p":"Right. Under the chain law, all vehicles need chains or a traction device."},"es":{"q":"En Colorado, cuando está activa la ley de cadenas para vehículos de pasajeros, ¿qué vehículos necesitan cadenas u otro dispositivo de tracción aprobado?","o":["Solo los carros de tracción en dos ruedas","Solo los camiones de más de 16,000 libras","Solo los carros con llantas gastadas","Todos los vehículos, incluso los de doble tracción"],"h1":"Es el último paso antes de cerrar una carretera.","h2":"Cuando está activa la ley de cadenas en Colorado, todo vehículo necesita cadenas o un dispositivo de tracción aprobado, incluso los de tracción total o doble tracción.","p":"Correcto. Con la ley de cadenas, todos los vehículos necesitan cadenas o tracción."},"ref":{"doc":"CO","page":null}},{"id":"co-033","scope":"CO","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Colorado, during which months must passenger vehicles on I-70 between Dotsero and Morrison be ready to follow the traction law?","o":["December 1 to February 28","November 1 to March 31","September 1 to May 31","All year round"],"h1":"The season covers most of the school year.","h2":"From September 1 to May 31, passenger vehicles on I-70 between Dotsero and Morrison must be ready to meet the traction law whenever the signs turn on.","p":"Right. The I-70 traction season is September 1 to May 31."},"es":{"q":"En Colorado, ¿en qué meses deben estar listos los vehículos de pasajeros en la I-70, entre Dotsero y Morrison, para cumplir la ley de tracción?","o":["Del 1 de diciembre al 28 de febrero","Del 1 de noviembre al 31 de marzo","Del 1 de septiembre al 31 de mayo","Todo el año"],"h1":"La temporada abarca casi todo el año escolar.","h2":"Del 1 de septiembre al 31 de mayo, los vehículos de pasajeros en la I-70 entre Dotsero y Morrison deben estar listos para cumplir la ley de tracción cuando se enciendan los letreros.","p":"Correcto. La temporada de tracción en la I-70 es del 1 de septiembre al 31 de mayo."},"ref":{"doc":"CO","page":null}},{"id":"co-034","scope":"CO","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Colorado, when a driver under 18 is driving, who must wear a seat belt?","o":["Only the driver","Only front-seat riders","Only passengers under 18","The driver and every passenger"],"h1":"Age of the passenger does not matter here.","h2":"When a Colorado driver is under 18, the driver and every passenger, of any age, must wear a seat belt or ride in the right child seat.","p":"Right. The teen driver and every passenger must buckle up."},"es":{"q":"En Colorado, cuando maneja un conductor menor de 18 años, ¿quién debe usar el cinturón de seguridad?","o":["Solo el conductor","Solo los que van adelante","Solo los pasajeros menores de 18","El conductor y todos los pasajeros"],"h1":"Aquí no importa la edad del pasajero.","h2":"Cuando un conductor en Colorado es menor de 18 años, el conductor y todos los pasajeros, de cualquier edad, deben usar el cinturón de seguridad o ir en el asiento infantil adecuado.","p":"Correcto. El conductor joven y todos los pasajeros deben abrocharse."},"ref":{"doc":"CO","page":3}},{"id":"ct-001","scope":"CT","cat":"licensing","sign":null,"c":2,"en":{"q":"In Connecticut, what is the youngest age to get a learner's permit?","o":["14 years old","15 years old","16 years old","17 years old"],"h1":"It is the age when many teens in other states can already get a license.","h2":"In Connecticut you must be at least 16 years old to get a learner's permit.","p":"Right. The Connecticut learner's permit starts at 16."},"es":{"q":"En Connecticut, ¿cuál es la edad mínima para obtener un permiso de aprendiz?","o":["14 años","15 años","16 años","17 años"],"h1":"Es la edad en que muchos jóvenes de otros estados ya pueden obtener la licencia.","h2":"En Connecticut usted debe tener por lo menos 16 años para obtener un permiso de aprendiz.","p":"Correcto. El permiso de aprendiz en Connecticut empieza a los 16."},"ref":{"doc":"CT","page":5}},{"id":"ct-002","scope":"CT","cat":"licensing","sign":null,"c":0,"en":{"q":"In Connecticut, who may ride with a driver who holds a learner's permit?","o":["Only the qualified trainer, and parents or others with a driving instructor","Any friend who has a license","Up to three passengers of any age","Anyone, as long as all wear seat belts"],"h1":"The permit is only for practice with a teacher.","h2":"A Connecticut permit holder may carry only the person giving instruction, plus parents or others riding with a licensed driving instructor.","p":"Right. A permit driver rides only with the trainer and the few people the law allows."},"es":{"q":"En Connecticut, ¿quién puede viajar con un conductor que tiene permiso de aprendiz?","o":["Solo el instructor calificado, y los padres u otras personas con un instructor de manejo","Cualquier amigo que tenga licencia","Hasta tres pasajeros de cualquier edad","Cualquier persona, si todos usan el cinturón"],"h1":"El permiso es solo para practicar con un maestro.","h2":"En Connecticut, quien tiene permiso de aprendiz solo puede llevar a la persona que le enseña, y a los padres u otras personas que viajan con un instructor de manejo con licencia.","p":"Correcto. El aprendiz solo viaja con su instructor y las pocas personas que permite la ley."},"ref":{"doc":"CT","page":6}},{"id":"ct-003","scope":"CT","cat":"licensing","sign":null,"c":3,"en":{"q":"In Connecticut, how old must a non-professional person be to give driving instruction to a permit holder?","o":["At least 18","At least 25","At least 21","At least 20"],"h1":"It is a little younger than the age most states ask for.","h2":"In Connecticut the person who gives instruction must be at least 20 years old, unless it is a licensed driving instructor.","p":"Right. A Connecticut trainer must be 20 or older."},"es":{"q":"En Connecticut, ¿qué edad debe tener una persona que no es instructor profesional para enseñar a manejar a quien tiene permiso?","o":["Por lo menos 18","Por lo menos 25","Por lo menos 21","Por lo menos 20"],"h1":"Es un poco menos que la edad que piden la mayoría de los estados.","h2":"En Connecticut, la persona que enseña debe tener por lo menos 20 años, salvo que sea un instructor de manejo con licencia.","p":"Correcto. En Connecticut el instructor debe tener 20 años o más."},"ref":{"doc":"CT","page":6}},{"id":"ct-004","scope":"CT","cat":"licensing","sign":null,"c":1,"en":{"q":"In Connecticut, for how long must the person teaching a permit holder have held a driver's license?","o":["At least one year","At least four years in a row","At least ten years","Any amount of time"],"h1":"It is more than a few years, with no suspension in that time.","h2":"In Connecticut the trainer must have held a license for at least four years in a row, with no suspension in those four years.","p":"Right. Four clean years of licensing are required."},"es":{"q":"En Connecticut, ¿por cuánto tiempo debe haber tenido licencia la persona que enseña a quien tiene permiso?","o":["Por lo menos un año","Por lo menos cuatro años seguidos","Por lo menos diez años","Cualquier tiempo"],"h1":"Son varios años, sin ninguna suspensión en ese tiempo.","h2":"En Connecticut el instructor debe haber tenido licencia por lo menos cuatro años seguidos, sin suspensión en esos cuatro años.","p":"Correcto. Se requieren cuatro años de licencia sin suspensión."},"ref":{"doc":"CT","page":6}},{"id":"ct-005","scope":"CT","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Connecticut, may a 17-year-old driver talk on a phone with a hands-free device?","o":["Yes, hands-free is always allowed","Yes, but only on highways","No, drivers under 18 may not use a phone at all while driving","Yes, if a parent is in the car"],"h1":"Young drivers have a stricter rule than adults.","h2":"In Connecticut a driver under 18 may not use a cell phone or other mobile electronic device while driving, even with a hands-free accessory.","p":"Right. Under 18, no phone at all while driving."},"es":{"q":"En Connecticut, ¿puede un conductor de 17 años hablar por teléfono con un dispositivo de manos libres?","o":["Sí, manos libres siempre está permitido","Sí, pero solo en carreteras","No, los menores de 18 no pueden usar el teléfono mientras manejan","Sí, si uno de sus padres va en el carro"],"h1":"Los conductores jóvenes tienen una regla más estricta que los adultos.","h2":"En Connecticut un conductor menor de 18 años no puede usar un celular ni otro aparato electrónico móvil mientras maneja, aunque sea con manos libres.","p":"Correcto. Antes de los 18, nada de teléfono al manejar."},"ref":{"doc":"CT","page":8}},{"id":"ct-006","scope":"CT","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Connecticut, what does the law say about adult drivers and hand-held phones?","o":["Using a hand-held phone or device while driving is not allowed","Hand-held phones are allowed at red lights","Hand-held phones are allowed below 30 mph","There is no rule for adults"],"h1":"Adults may still talk, but not with the device in hand.","h2":"In Connecticut no driver may use a hand-held mobile electronic device while driving.","p":"Right. Put the phone down while you drive."},"es":{"q":"En Connecticut, ¿qué dice la ley sobre los conductores adultos y los teléfonos en la mano?","o":["No se permite usar un teléfono o aparato en la mano mientras maneja","Se permite en los semáforos en rojo","Se permite por debajo de 30 mph","No hay ninguna regla para adultos"],"h1":"Los adultos pueden hablar, pero sin tener el aparato en la mano.","h2":"En Connecticut ningún conductor puede usar un aparato electrónico móvil en la mano mientras maneja.","p":"Correcto. Deje el teléfono mientras maneja."},"ref":{"doc":"CT","page":11}},{"id":"ct-008","scope":"CT","cat":"licensing","sign":null,"c":3,"en":{"q":"In Connecticut, during the first six months with a license, who may a 16- or 17-year-old driver carry as passengers?","o":["Up to two friends","Any family member or friend","Anyone over 16","Only a driving instructor, a parent or guardian, or one qualified trainer age 20 or older"],"h1":"It is the same short list as during the permit.","h2":"In Connecticut, for the first six months, a newly licensed 16- or 17-year-old may carry only a driving instructor, a parent or guardian, or one qualified trainer age 20 or older.","p":"Right. The first six months are almost passenger-free."},"es":{"q":"En Connecticut, durante los primeros seis meses con licencia, ¿a quién puede llevar como pasajero un conductor de 16 o 17 años?","o":["Hasta dos amigos","Cualquier familiar o amigo","Cualquier persona mayor de 16","Solo un instructor de manejo, sus padres o tutor, o un instructor calificado de 20 años o más"],"h1":"Es la misma lista corta que durante el permiso.","h2":"En Connecticut, durante los primeros seis meses, un conductor de 16 o 17 años con licencia nueva solo puede llevar a un instructor de manejo, a sus padres o tutor, o a un instructor calificado de 20 años o más.","p":"Correcto. Los primeros seis meses son casi sin pasajeros."},"ref":{"doc":"CT","page":8}},{"id":"ct-009","scope":"CT","cat":"licensing","sign":null,"c":1,"en":{"q":"In Connecticut, in the second six months with a license, who else may a 16- or 17-year-old driver carry?","o":["Up to three friends","Members of the driver's immediate family","Any classmate","No one at all"],"h1":"The rule opens a little, but only for people at home.","h2":"In Connecticut, in the second six months, a 16- or 17-year-old driver may also carry members of their immediate family.","p":"Right. Immediate family may ride in the second six months."},"es":{"q":"En Connecticut, en los segundos seis meses con licencia, ¿a quién más puede llevar un conductor de 16 o 17 años?","o":["Hasta tres amigos","A miembros de su familia inmediata","A cualquier compañero de clase","A nadie"],"h1":"La regla se abre un poco, pero solo para la gente de su casa.","h2":"En Connecticut, en los segundos seis meses, un conductor de 16 o 17 años también puede llevar a miembros de su familia inmediata.","p":"Correcto. La familia inmediata puede viajar en los segundos seis meses."},"ref":{"doc":"CT","page":8}},{"id":"ct-010","scope":"CT","cat":"licensing","sign":null,"c":2,"en":{"q":"In Connecticut, during which hours may a licensed 16- or 17-year-old not drive, except for reasons such as work, school or a medical emergency?","o":["9 p.m. to 6 a.m.","Midnight to 6 a.m.","11 p.m. to 5 a.m.","1 a.m. to 5 a.m."],"h1":"It starts one hour before midnight.","h2":"In Connecticut a licensed 16- or 17-year-old may not drive from 11 p.m. to 5 a.m., except for work, school, religious activities or a medical emergency.","p":"Right. The teen curfew is 11 p.m. to 5 a.m."},"es":{"q":"En Connecticut, ¿en qué horario no puede manejar un joven de 16 o 17 años con licencia, salvo por trabajo, escuela o una emergencia médica?","o":["De 9 p.m. a 6 a.m.","De medianoche a 6 a.m.","De 11 p.m. a 5 a.m.","De 1 a.m. a 5 a.m."],"h1":"Empieza una hora antes de la medianoche.","h2":"En Connecticut un joven de 16 o 17 años con licencia no puede manejar de 11 p.m. a 5 a.m., salvo por trabajo, escuela, actividades religiosas o una emergencia médica.","p":"Correcto. El horario restringido es de 11 p.m. a 5 a.m."},"ref":{"doc":"CT","page":8}},{"id":"ct-011","scope":"CT","cat":"licensing","sign":null,"c":0,"en":{"q":"In Connecticut, what can police do on the spot when a 16- or 17-year-old driver commits certain serious violations?","o":["Take the license for 48 hours and remove the car","Only give a warning","Take away the car for one year","Nothing until a court date"],"h1":"It happens right away, at the side of the road.","h2":"In Connecticut police can take a 16- or 17-year-old driver's license on the spot for 48 hours for certain violations, and they may also remove the car.","p":"Right. The license is taken for 48 hours, and the car can be removed."},"es":{"q":"En Connecticut, ¿qué puede hacer la policía en el momento si un conductor de 16 o 17 años comete ciertas infracciones graves?","o":["Quitarle la licencia por 48 horas y retirar el carro","Solo darle una advertencia","Quitarle el carro por un año","Nada hasta la fecha de la corte"],"h1":"Ocurre de inmediato, al lado de la carretera.","h2":"En Connecticut la policía puede quitarle la licencia en el momento por 48 horas a un conductor de 16 o 17 años por ciertas infracciones, y también puede retirar el carro.","p":"Correcto. Le quitan la licencia por 48 horas y pueden retirar el carro."},"ref":{"doc":"CT","page":null}},{"id":"ct-012","scope":"CT","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Connecticut, at what blood alcohol level is a driver under 21 considered to be driving illegally?","o":["0.08 percent","0.02 percent","0.05 percent","0.10 percent"],"h1":"It is much lower than the adult limit of 0.08.","h2":"In Connecticut a driver under 21 is driving illegally with a blood alcohol level of 0.02 percent or more.","p":"Right. For drivers under 21 the limit is 0.02."},"es":{"q":"En Connecticut, ¿con qué nivel de alcohol en la sangre se considera que un conductor menor de 21 maneja ilegalmente?","o":["0.08 por ciento","0.02 por ciento","0.05 por ciento","0.10 por ciento"],"h1":"Es mucho más bajo que el límite de 0.08 para adultos.","h2":"En Connecticut un conductor menor de 21 años maneja ilegalmente con un nivel de alcohol en la sangre de 0.02 por ciento o más.","p":"Correcto. Para menores de 21 el límite es 0.02."},"ref":{"doc":"CT","page":31}},{"id":"ct-013","scope":"CT","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Connecticut, what must you do when you approach an emergency vehicle stopped on the shoulder and you are in the lane next to it?","o":["Keep the same speed and lane","Stop in your lane until it leaves","Speed up to pass it quickly","Slow down below the speed limit and move over one lane if it is safe"],"h1":"There are two steps: one with your speed, one with your lane.","h2":"In Connecticut you must slow to a safe speed below the posted limit and, if you are in the next lane, move over one lane when it is safe.","p":"Right. Slow down and move over."},"es":{"q":"En Connecticut, ¿qué debe hacer al acercarse a un vehículo de emergencia detenido en el acotamiento si usted va en el carril de al lado?","o":["Seguir a la misma velocidad y en el mismo carril","Detenerse en su carril hasta que se vaya","Acelerar para pasarlo rápido","Bajar la velocidad por debajo del límite y cambiarse un carril si es seguro"],"h1":"Son dos pasos: uno con su velocidad y otro con su carril.","h2":"En Connecticut usted debe bajar a una velocidad segura por debajo del límite y, si va en el carril de al lado, cambiarse un carril cuando sea seguro.","p":"Correcto. Baje la velocidad y cámbiese de carril."},"ref":{"doc":"CT","page":14}},{"id":"ct-014","scope":"CT","cat":"signals","sign":null,"c":0,"en":{"q":"In Connecticut, when may you turn right on a red light?","o":["After a full stop, when it is safe and no sign forbids it","Never","Without stopping, if no one is coming","Only between midnight and 6 a.m."],"h1":"Some intersections have a sign that says you may not.","h2":"In Connecticut you may turn right on red only after a complete stop, when it is safe, and where no sign says \"No Turn on Red.\"","p":"Right. Stop first, then turn if it is safe and allowed."},"es":{"q":"En Connecticut, ¿cuándo puede girar a la derecha con la luz roja?","o":["Después de detenerse por completo, si es seguro y ninguna señal lo prohíbe","Nunca","Sin detenerse, si no viene nadie","Solo de medianoche a 6 a.m."],"h1":"Algunas intersecciones tienen una señal que lo prohíbe.","h2":"En Connecticut usted puede girar a la derecha con luz roja solo después de detenerse por completo, si es seguro y donde ninguna señal diga \"No Turn on Red\".","p":"Correcto. Primero se detiene, y luego gira si es seguro y está permitido."},"ref":{"doc":"CT","page":13}},{"id":"ct-015","scope":"CT","cat":"licensing","sign":null,"c":2,"en":{"q":"In Connecticut, how long must a 16- or 17-year-old who took a commercial or school driver education course wait after getting a permit before applying for a license?","o":["30 days","60 days","120 days","One year"],"h1":"It is about four months.","h2":"In Connecticut a 16- or 17-year-old who took a commercial or high school driver education course must wait at least 120 days after the permit before applying for a license.","p":"Right. The wait is 120 days with a course."},"es":{"q":"En Connecticut, ¿cuánto debe esperar después de recibir el permiso un joven de 16 o 17 años que tomó un curso de manejo comercial o escolar antes de pedir la licencia?","o":["30 días","60 días","120 días","Un año"],"h1":"Son unos cuatro meses.","h2":"En Connecticut un joven de 16 o 17 años que tomó un curso de manejo comercial o de la escuela debe esperar por lo menos 120 días después del permiso para pedir la licencia.","p":"Correcto. La espera es de 120 días con un curso."},"ref":{"doc":"CT","page":6}},{"id":"ct-016","scope":"CT","cat":"licensing","sign":null,"c":1,"en":{"q":"In Connecticut, how long must a 16- or 17-year-old who chose home training wait after getting a permit before applying for a license?","o":["90 days","180 days","120 days","365 days"],"h1":"It is longer than the wait after a driving school course.","h2":"In Connecticut a 16- or 17-year-old who learns through home training must wait at least 180 days after the permit before applying for a license.","p":"Right. Home training means a 180-day wait."},"es":{"q":"En Connecticut, ¿cuánto debe esperar después de recibir el permiso un joven de 16 o 17 años que eligió aprender en casa antes de pedir la licencia?","o":["90 días","180 días","120 días","365 días"],"h1":"Es más tiempo que después de un curso en una escuela de manejo.","h2":"En Connecticut un joven de 16 o 17 años que aprende en casa debe esperar por lo menos 180 días después del permiso para pedir la licencia.","p":"Correcto. Aprender en casa significa esperar 180 días."},"ref":{"doc":"CT","page":6}},{"id":"ct-017","scope":"CT","cat":"licensing","sign":null,"c":3,"en":{"q":"In Connecticut, how many hours of behind-the-wheel training must a 16- or 17-year-old complete?","o":["10 hours","20 hours","30 hours","40 hours"],"h1":"It is more than the 30 hours of classroom study.","h2":"In Connecticut a 16- or 17-year-old must complete 40 hours of behind-the-wheel training, along with 30 hours of classroom study.","p":"Right. 40 hours behind the wheel."},"es":{"q":"En Connecticut, ¿cuántas horas de práctica al volante debe completar un joven de 16 o 17 años?","o":["10 horas","20 horas","30 horas","40 horas"],"h1":"Son más que las 30 horas de estudio en clase.","h2":"En Connecticut un joven de 16 o 17 años debe completar 40 horas de práctica al volante, además de 30 horas de estudio en clase.","p":"Correcto. 40 horas al volante."},"ref":{"doc":"CT","page":6}},{"id":"ct-018","scope":"CT","cat":"licensing","sign":null,"c":0,"en":{"q":"In Connecticut, how many hours of driver education study must a 16- or 17-year-old complete?","o":["30 hours","10 hours","15 hours","50 hours"],"h1":"It is ten hours less than the behind-the-wheel training.","h2":"In Connecticut a 16- or 17-year-old must complete 30 hours of driver education study, which includes the 8-hour safe driving course.","p":"Right. 30 hours of study."},"es":{"q":"En Connecticut, ¿cuántas horas de estudio de manejo debe completar un joven de 16 o 17 años?","o":["30 horas","10 horas","15 horas","50 horas"],"h1":"Son diez horas menos que la práctica al volante.","h2":"En Connecticut un joven de 16 o 17 años debe completar 30 horas de estudio de manejo, que incluyen el curso de manejo seguro de 8 horas.","p":"Correcto. 30 horas de estudio."},"ref":{"doc":"CT","page":6}},{"id":"ct-019","scope":"CT","cat":"licensing","sign":null,"c":2,"en":{"q":"In Connecticut, is there a night curfew for a driver with a learner's permit?","o":["Yes, from 9 p.m. to 6 a.m.","Yes, from 11 p.m. to 5 a.m.","No curfew, but a qualified trainer must always be in the car","No curfew, and the permit driver may drive alone"],"h1":"The permit rule is about who is beside you, not the clock.","h2":"In Connecticut a permit holder has no curfew, but must always drive with a qualified trainer.","p":"Right. No curfew, but never alone."},"es":{"q":"En Connecticut, ¿hay horario de restricción nocturna para quien tiene permiso de aprendiz?","o":["Sí, de 9 p.m. a 6 a.m.","Sí, de 11 p.m. a 5 a.m.","No hay horario, pero siempre debe ir un instructor calificado en el carro","No hay horario, y puede manejar solo"],"h1":"La regla del permiso es sobre quién va a su lado, no sobre la hora.","h2":"En Connecticut quien tiene permiso de aprendiz no tiene horario restringido, pero siempre debe manejar con un instructor calificado.","p":"Correcto. Sin horario, pero nunca solo."},"ref":{"doc":"CT","page":null}},{"id":"ct-020","scope":"CT","cat":"licensing","sign":null,"c":1,"en":{"q":"In Connecticut, who must be with a 16- or 17-year-old when taking the knowledge test, if they do not send a signed consent form?","o":["A teacher","A parent or guardian","A driving instructor","No one"],"h1":"It is the adult responsible for the teen.","h2":"In Connecticut a parent or guardian must come to the knowledge test with an applicant under 18, or fill out a consent form.","p":"Right. A parent or guardian gives consent."},"es":{"q":"En Connecticut, ¿quién debe acompañar a un joven de 16 o 17 años al examen teórico, si no envía un formulario de consentimiento firmado?","o":["Un maestro","Su padre, madre o tutor","Un instructor de manejo","Nadie"],"h1":"Es el adulto responsable del joven.","h2":"En Connecticut el padre, la madre o el tutor debe ir al examen teórico con un solicitante menor de 18, o llenar un formulario de consentimiento.","p":"Correcto. El padre, la madre o el tutor da su consentimiento."},"ref":{"doc":"CT","page":null}},{"id":"dc-001","scope":"DC","cat":"licensing","sign":null,"c":2,"en":{"q":"In the District of Columbia, what is the youngest age to get a learner permit?","o":["14 years old","15 years old","16 years old","18 years old"],"h1":"It is the same age at which many teens get their first job.","h2":"In the District of Columbia, you must be at least 16 years old to get a learner permit.","p":"Right. In DC the learner permit starts at 16."},"es":{"q":"En el Distrito de Columbia, ¿cuál es la edad mínima para obtener un permiso de aprendiz?","o":["14 años","15 años","16 años","18 años"],"h1":"Es la misma edad en que muchos jóvenes consiguen su primer trabajo.","h2":"En el Distrito de Columbia, usted debe tener por lo menos 16 años para obtener un permiso de aprendiz.","p":"Correcto. En DC el permiso de aprendiz empieza a los 16."},"ref":{"doc":"DC","page":14}},{"id":"dc-002","scope":"DC","cat":"licensing","sign":null,"c":0,"en":{"q":"In the District of Columbia, during which hours may a learner permit holder drive?","o":["6:00 a.m. to 9:00 p.m.","5:00 a.m. to midnight","Any time of day","8:00 a.m. to 6:00 p.m."],"h1":"The window starts early in the morning and ends in the evening, before late night.","h2":"In the District of Columbia, a learner permit holder may drive only between 6:00 in the morning and 9:00 at night.","p":"Right. With a DC learner permit you drive from 6 a.m. to 9 p.m."},"es":{"q":"En el Distrito de Columbia, ¿en qué horario puede manejar una persona con permiso de aprendiz?","o":["De 6:00 a.m. a 9:00 p.m.","De 5:00 a.m. a medianoche","A cualquier hora","De 8:00 a.m. a 6:00 p.m."],"h1":"El horario empieza temprano en la mañana y termina en la noche, antes de que sea muy tarde.","h2":"En el Distrito de Columbia, quien tiene permiso de aprendiz solo puede manejar entre las 6:00 de la mañana y las 9:00 de la noche.","p":"Correcto. Con permiso de aprendiz en DC se maneja de 6 a.m. a 9 p.m."},"ref":{"doc":"DC","page":14}},{"id":"dc-003","scope":"DC","cat":"licensing","sign":null,"c":3,"en":{"q":"In the District of Columbia, how many hours of supervised driving must a teen complete before getting a provisional license?","o":["10 hours","20 hours","60 hours","40 hours"],"h1":"It is the same number as a full work week.","h2":"In the District of Columbia, a teen must complete at least 40 hours of supervised driving before moving to a provisional license.","p":"Right. DC asks for 40 supervised hours first."},"es":{"q":"En el Distrito de Columbia, ¿cuántas horas de manejo supervisado debe completar un joven antes de obtener una licencia provisional?","o":["10 horas","20 horas","60 horas","40 horas"],"h1":"Es el mismo número que una semana completa de trabajo.","h2":"En el Distrito de Columbia, un joven debe completar por lo menos 40 horas de manejo supervisado antes de pasar a la licencia provisional.","p":"Correcto. DC pide primero 40 horas supervisadas."},"ref":{"doc":"DC","page":14}},{"id":"dc-004","scope":"DC","cat":"licensing","sign":null,"c":1,"en":{"q":"In the District of Columbia, how many hours of supervised night driving must a provisional driver complete before the next license stage?","o":["5 hours","10 hours","30 hours","50 hours"],"h1":"It is a small, round number.","h2":"In the District of Columbia, a provisional driver must complete at least 10 hours of supervised night driving before moving to the full license with conditions.","p":"Right. DC asks for 10 hours of night practice."},"es":{"q":"En el Distrito de Columbia, ¿cuántas horas de manejo nocturno supervisado debe completar un conductor provisional antes de la siguiente etapa de licencia?","o":["5 horas","10 horas","30 horas","50 horas"],"h1":"Es un número pequeño y redondo.","h2":"En el Distrito de Columbia, un conductor provisional debe completar por lo menos 10 horas de manejo nocturno supervisado antes de pasar a la licencia completa con condiciones.","p":"Correcto. DC pide 10 horas de práctica de noche."},"ref":{"doc":"DC","page":14}},{"id":"dc-005","scope":"DC","cat":"licensing","sign":null,"c":2,"en":{"q":"In the District of Columbia, how long must a teen hold a learner permit before moving to the next stage?","o":["1 month","3 months","6 months","2 years"],"h1":"It is half a year.","h2":"In the District of Columbia, a teen must hold the learner permit for at least 6 months before moving to a provisional license.","p":"Right. Six months with the permit first."},"es":{"q":"En el Distrito de Columbia, ¿cuánto tiempo debe tener un joven el permiso de aprendiz antes de pasar a la siguiente etapa?","o":["1 mes","3 meses","6 meses","2 años"],"h1":"Es medio año.","h2":"En el Distrito de Columbia, un joven debe tener el permiso de aprendiz por lo menos 6 meses antes de pasar a la licencia provisional.","p":"Correcto. Primero seis meses con el permiso."},"ref":{"doc":"DC","page":14}},{"id":"dc-006","scope":"DC","cat":"licensing","sign":null,"c":0,"en":{"q":"In the District of Columbia, what can you do if you turn 21 while you hold a learner permit?","o":["Schedule the road test right away, without waiting out the six months","Drive alone with the permit","Skip the road test","Nothing changes; you still wait six months"],"h1":"Being an adult removes the waiting period, not the test.","h2":"In the District of Columbia, if you turn 21 while holding a learner permit, you may schedule the road test right away, without the driving certification form or the six-month wait.","p":"Right. At 21 the wait is gone, but you still take the road test."},"es":{"q":"En el Distrito de Columbia, ¿qué puede hacer si cumple 21 años mientras tiene un permiso de aprendiz?","o":["Programar el examen de manejo de inmediato, sin esperar los seis meses","Manejar solo con el permiso","No tomar el examen de manejo","Nada cambia; todavía espera seis meses"],"h1":"Ser adulto quita el tiempo de espera, no el examen.","h2":"En el Distrito de Columbia, si usted cumple 21 años con permiso de aprendiz, puede programar el examen de manejo de inmediato, sin el formulario de certificación de manejo ni la espera de seis meses.","p":"Correcto. A los 21 ya no espera, pero sí toma el examen de manejo."},"ref":{"doc":"DC","page":15}},{"id":"dc-007","scope":"DC","cat":"licensing","sign":null,"c":1,"en":{"q":"In the District of Columbia, from September to June, until what time may a provisional driver drive on a Monday through Thursday night?","o":["9:00 p.m.","10:59 p.m.","11:59 p.m.","1:00 a.m."],"h1":"It is one minute before 11 at night.","h2":"In the District of Columbia, from September to June, a provisional driver may drive on Monday through Thursday only until 10:59 at night.","p":"Right. From Monday to Thursday the limit is 10:59 p.m."},"es":{"q":"En el Distrito de Columbia, de septiembre a junio, ¿hasta qué hora puede manejar un conductor provisional de lunes a jueves en la noche?","o":["9:00 p.m.","10:59 p.m.","11:59 p.m.","1:00 a.m."],"h1":"Es un minuto antes de las 11 de la noche.","h2":"En el Distrito de Columbia, de septiembre a junio, un conductor provisional puede manejar de lunes a jueves solo hasta las 10:59 de la noche.","p":"Correcto. De lunes a jueves el límite es 10:59 p.m."},"ref":{"doc":"DC","page":14}},{"id":"dc-008","scope":"DC","cat":"licensing","sign":null,"c":3,"en":{"q":"In the District of Columbia, in July and August, until what time may a provisional driver drive alone?","o":["9:00 p.m. every day","10:59 p.m. every day","There is no limit in summer","11:59 p.m. every day"],"h1":"In summer the latest time is the same every day, just before midnight.","h2":"In the District of Columbia, in July and August, a provisional driver may drive alone every day until 11:59 at night.","p":"Right. Summer nights end at 11:59 p.m."},"es":{"q":"En el Distrito de Columbia, en julio y agosto, ¿hasta qué hora puede manejar solo un conductor provisional?","o":["9:00 p.m. todos los días","10:59 p.m. todos los días","No hay límite en verano","11:59 p.m. todos los días"],"h1":"En verano la hora límite es igual todos los días, justo antes de medianoche.","h2":"En el Distrito de Columbia, en julio y agosto, un conductor provisional puede manejar solo todos los días hasta las 11:59 de la noche.","p":"Correcto. En verano el límite es 11:59 p.m."},"ref":{"doc":"DC","page":14}},{"id":"dc-009","scope":"DC","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In the District of Columbia, what is the speed limit on a street with no speed limit sign?","o":["20 mph","25 mph","30 mph","35 mph"],"h1":"It is lower than in most states, and it has been since 2020.","h2":"In the District of Columbia, the speed limit is 20 miles per hour on any street where no other limit is posted.","p":"Right. The DC default is 20 mph."},"es":{"q":"En el Distrito de Columbia, ¿cuál es el límite de velocidad en una calle que no tiene letrero de límite?","o":["20 mph","25 mph","30 mph","35 mph"],"h1":"Es más bajo que en la mayoría de los estados, y así es desde 2020.","h2":"En el Distrito de Columbia, el límite de velocidad es de 20 millas por hora en cualquier calle donde no haya otro límite indicado.","p":"Correcto. En DC el límite general es 20 mph."},"ref":{"doc":"DC","page":46}},{"id":"dc-010","scope":"DC","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In the District of Columbia, what is the speed limit next to a school at the times shown on the signs?","o":["10 mph","15 mph","20 mph","25 mph"],"h1":"It is lower than the city's usual 20 mph.","h2":"In the District of Columbia, the speed limit on streets next to schools is 15 miles per hour at the times shown on the signs.","p":"Right. 15 mph near schools."},"es":{"q":"En el Distrito de Columbia, ¿cuál es el límite de velocidad junto a una escuela en los horarios indicados en los letreros?","o":["10 mph","15 mph","20 mph","25 mph"],"h1":"Es más bajo que el límite general de 20 mph de la ciudad.","h2":"En el Distrito de Columbia, el límite de velocidad en las calles junto a las escuelas es de 15 millas por hora en los horarios indicados en los letreros.","p":"Correcto. 15 mph cerca de las escuelas."},"ref":{"doc":"DC","page":46}},{"id":"dc-011","scope":"DC","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In the District of Columbia, how may an adult driver talk on a cell phone while the car is moving?","o":["Holding the phone at the ear","Only while stopped at a red light, holding the phone","Only with a hands-free device","Never, not even hands-free"],"h1":"Both hands must be able to stay on the wheel.","h2":"In the District of Columbia, an adult driver may use a cell phone while moving only with a hands-free device.","p":"Right. In DC, adults must use hands-free."},"es":{"q":"En el Distrito de Columbia, ¿cómo puede un conductor adulto hablar por celular mientras el auto está en movimiento?","o":["Sosteniendo el teléfono en el oído","Solo en un semáforo en rojo, sosteniendo el teléfono","Solo con un dispositivo de manos libres","Nunca, ni con manos libres"],"h1":"Las dos manos deben poder quedarse en el volante.","h2":"En el Distrito de Columbia, un conductor adulto solo puede usar el celular en movimiento con un dispositivo de manos libres.","p":"Correcto. En DC los adultos deben usar manos libres."},"ref":{"doc":"DC","page":26}},{"id":"dc-012","scope":"DC","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In the District of Columbia, may a learner permit holder use a hands-free phone while driving?","o":["Yes, hands-free is always allowed","Yes, but only on highways","Yes, if the supervisor agrees","No, only to call for an emergency"],"h1":"The rule for learners is stricter than the rule for adults.","h2":"In the District of Columbia, a learner permit holder may not use a cell phone at all while driving, even hands-free, except to make an emergency call.","p":"Right. Learners in DC put the phone away, hands-free included."},"es":{"q":"En el Distrito de Columbia, ¿puede una persona con permiso de aprendiz usar un teléfono de manos libres mientras maneja?","o":["Sí, manos libres siempre está permitido","Sí, pero solo en autopistas","Sí, si el acompañante está de acuerdo","No, solo para llamar en una emergencia"],"h1":"La regla para aprendices es más estricta que la regla para adultos.","h2":"En el Distrito de Columbia, quien tiene permiso de aprendiz no puede usar el celular mientras maneja, ni con manos libres, excepto para hacer una llamada de emergencia.","p":"Correcto. En DC los aprendices guardan el teléfono, incluso el de manos libres."},"ref":{"doc":"DC","page":15}},{"id":"dc-013","scope":"DC","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In the District of Columbia, how much alcohol may a driver under 21 have in the body?","o":["None; any measurable amount is against the law","Up to 0.02","Up to 0.05","Up to 0.08"],"h1":"Think of the lowest possible amount.","h2":"In the District of Columbia, a driver under 21 may not have any measurable amount of alcohol, and can be arrested for driving while intoxicated.","p":"Right. Under 21 in DC, the limit is zero."},"es":{"q":"En el Distrito de Columbia, ¿cuánto alcohol puede tener en el cuerpo un conductor menor de 21 años?","o":["Nada; cualquier cantidad que se pueda medir es ilegal","Hasta 0.02","Hasta 0.05","Hasta 0.08"],"h1":"Piense en la cantidad más baja posible.","h2":"En el Distrito de Columbia, un conductor menor de 21 años no puede tener ninguna cantidad medible de alcohol, y lo pueden arrestar por manejar intoxicado.","p":"Correcto. Para menores de 21 en DC, el límite es cero."},"ref":{"doc":"DC","page":null}},{"id":"de-001","scope":"DE","cat":"licensing","sign":null,"c":2,"en":{"q":"In Delaware, what is the youngest age to get a Level 1 learner's permit?","o":["14 years old","15 years old","16 years old","17 years old"],"h1":"It is a later age than in many other states.","h2":"In Delaware you can get a Level 1 learner's permit at 16, after you finish an approved driver education course.","p":"Right. Delaware starts the learner's permit at 16."},"es":{"q":"En Delaware, ¿cuál es la edad mínima para obtener el permiso de aprendiz de Nivel 1?","o":["14 años","15 años","16 años","17 años"],"h1":"Es una edad mayor que en muchos otros estados.","h2":"En Delaware usted puede obtener el permiso de aprendiz de Nivel 1 a los 16 años, después de terminar un curso aprobado de educación vial.","p":"Correcto. En Delaware el permiso de aprendiz empieza a los 16."},"ref":{"doc":"DE","page":28}},{"id":"de-002","scope":"DE","cat":"licensing","sign":null,"c":0,"en":{"q":"In Delaware, what must a teen finish before getting a Level 1 learner's permit?","o":["An approved driver education course","A road test","A year of driving on a farm","A first aid course"],"h1":"Think of the classes that teach driving.","h2":"A Delaware teen must finish an approved driver education course before getting the Level 1 learner's permit.","p":"Right. Driver education comes first in Delaware."},"es":{"q":"En Delaware, ¿qué debe terminar un adolescente antes de obtener el permiso de aprendiz de Nivel 1?","o":["Un curso aprobado de educación vial","Un examen de manejo en la calle","Un año de manejo en una granja","Un curso de primeros auxilios"],"h1":"Piense en las clases que enseñan a manejar.","h2":"Un adolescente en Delaware debe terminar un curso aprobado de educación vial antes de obtener el permiso de aprendiz de Nivel 1.","p":"Correcto. En Delaware la educación vial va primero."},"ref":{"doc":"DE","page":28}},{"id":"de-003","scope":"DE","cat":"licensing","sign":null,"c":1,"en":{"q":"In Delaware, for how long does a Level 1 learner's permit let a teen drive?","o":["6 months","12 months","18 months","24 months"],"h1":"It is one full year.","h2":"A Delaware Level 1 learner's permit lets a teen drive under its rules for 12 months.","p":"Right. The Delaware permit lasts 12 months."},"es":{"q":"En Delaware, ¿por cuánto tiempo permite manejar el permiso de aprendiz de Nivel 1?","o":["6 meses","12 meses","18 meses","24 meses"],"h1":"Es un año completo.","h2":"El permiso de aprendiz de Nivel 1 de Delaware permite manejar bajo sus reglas durante 12 meses.","p":"Correcto. El permiso de Delaware dura 12 meses."},"ref":{"doc":"DE","page":30}},{"id":"de-004","scope":"DE","cat":"licensing","sign":null,"c":3,"en":{"q":"In Delaware, a supervisor who is not the teen's parent or guardian must be at least how old?","o":["18","20","21","25"],"h1":"It is older than the age to buy alcohol.","h2":"In Delaware, a supervisor who is not a parent or guardian must be a licensed driver who is at least 25 years old.","p":"Right. The supervisor must be 25 or older."},"es":{"q":"En Delaware, un supervisor que no es el padre, la madre ni el tutor del adolescente debe tener por lo menos ¿qué edad?","o":["18","20","21","25"],"h1":"Es mayor que la edad para comprar alcohol.","h2":"En Delaware, un supervisor que no es padre, madre ni tutor debe ser un conductor con licencia de por lo menos 25 años.","p":"Correcto. El supervisor debe tener 25 años o más."},"ref":{"doc":"DE","page":29}},{"id":"de-005","scope":"DE","cat":"licensing","sign":null,"c":2,"en":{"q":"In Delaware, how long must a supervisor who is not a parent or guardian have held a driver license?","o":["1 year","3 years","5 years","10 years"],"h1":"It is half of ten years.","h2":"In Delaware, a supervisor who is not a parent or guardian must have held a Class D license for at least 5 years.","p":"Right. Five years of license experience is required."},"es":{"q":"En Delaware, ¿cuánto tiempo debe tener su licencia un supervisor que no es padre, madre ni tutor?","o":["1 año","3 años","5 años","10 años"],"h1":"Es la mitad de diez años.","h2":"En Delaware, un supervisor que no es padre, madre ni tutor debe haber tenido una licencia Clase D por lo menos 5 años.","p":"Correcto. Se requieren cinco años con licencia."},"ref":{"doc":"DE","page":29}},{"id":"de-006","scope":"DE","cat":"licensing","sign":null,"c":1,"en":{"q":"In Delaware, how many hours of supervised driving must a permit holder log before driving alone?","o":["30 hours","50 hours","70 hours","100 hours"],"h1":"It is half of one hundred.","h2":"A Delaware permit holder must log at least 50 hours of supervised driving before driving without a supervisor.","p":"Right. Delaware asks for 50 supervised hours."},"es":{"q":"En Delaware, ¿cuántas horas de manejo supervisado debe registrar un aprendiz antes de manejar solo?","o":["30 horas","50 horas","70 horas","100 horas"],"h1":"Es la mitad de cien.","h2":"Un aprendiz en Delaware debe registrar por lo menos 50 horas de manejo supervisado antes de manejar sin supervisor.","p":"Correcto. Delaware pide 50 horas supervisadas."},"ref":{"doc":"DE","page":29}},{"id":"de-007","scope":"DE","cat":"licensing","sign":null,"c":0,"en":{"q":"In Delaware, how many of the supervised practice hours must be at night?","o":["At least 10 hours","At least 2 hours","At least 25 hours","None"],"h1":"It is a round number, a small part of the total.","h2":"In Delaware, at least 10 of the 50 supervised practice hours must be driven at night.","p":"Right. Ten of the hours must be at night."},"es":{"q":"En Delaware, ¿cuántas de las horas de práctica supervisada deben ser de noche?","o":["Por lo menos 10 horas","Por lo menos 2 horas","Por lo menos 25 horas","Ninguna"],"h1":"Es un número redondo, una parte pequeña del total.","h2":"En Delaware, por lo menos 10 de las 50 horas de práctica supervisada deben ser de noche.","p":"Correcto. Diez de las horas deben ser de noche."},"ref":{"doc":"DE","page":29}},{"id":"de-008","scope":"DE","cat":"licensing","sign":null,"c":1,"en":{"q":"In Delaware, for how long at the start of the learner's permit may a teen drive only with a supervisor?","o":["The first month","The first 6 months","The first 9 months","The whole 12 months"],"h1":"It is half of the permit time.","h2":"During the first 6 months of a Delaware learner's permit, the teen may drive only with a qualified supervisor.","p":"Right. The first six months are fully supervised."},"es":{"q":"En Delaware, ¿durante cuánto tiempo al comienzo del permiso de aprendiz puede manejar el adolescente solo con un supervisor?","o":["El primer mes","Los primeros 6 meses","Los primeros 9 meses","Los 12 meses completos"],"h1":"Es la mitad del tiempo del permiso.","h2":"Durante los primeros 6 meses del permiso de aprendiz de Delaware, el adolescente puede manejar solamente con un supervisor calificado.","p":"Correcto. Los primeros seis meses son con supervisión."},"ref":{"doc":"DE","page":29}},{"id":"de-009","scope":"DE","cat":"licensing","sign":null,"c":3,"en":{"q":"In Delaware, after the supervised period, during which hours may a permit holder drive alone?","o":["Any time of day or night","From 5 a.m. to midnight","From 8 a.m. to 8 p.m.","From 6 a.m. to 10 p.m."],"h1":"Driving alone ends at ten at night.","h2":"After the supervised period, a Delaware permit holder may drive alone from 6 a.m. to 10 p.m.","p":"Right. Alone only from 6 a.m. to 10 p.m."},"es":{"q":"En Delaware, después del período supervisado, ¿en qué horario puede manejar solo el aprendiz?","o":["A cualquier hora del día o de la noche","De 5 a.m. a medianoche","De 8 a.m. a 8 p.m.","De 6 a.m. a 10 p.m."],"h1":"Manejar solo termina a las diez de la noche.","h2":"Después del período supervisado, un aprendiz en Delaware puede manejar solo de 6 a.m. a 10 p.m.","p":"Correcto. Solo de 6 a.m. a 10 p.m."},"ref":{"doc":"DE","page":30}},{"id":"de-010","scope":"DE","cat":"licensing","sign":null,"c":2,"en":{"q":"In Delaware, a permit holder in the unsupervised stage wants to drive alone at 11 p.m. Which trip is allowed?","o":["Going to a friend's party","Driving around for fun","Going home from work","Going to the mall"],"h1":"Think of a job.","h2":"In Delaware, a permit holder may drive alone between 10 p.m. and 6 a.m. only for trips to and from work, church or school activities.","p":"Right. Work trips are an exception at night."},"es":{"q":"En Delaware, un aprendiz en la etapa sin supervisión quiere manejar solo a las 11 p.m. ¿Qué viaje está permitido?","o":["Ir a la fiesta de un amigo","Pasear en carro por diversión","Volver a casa del trabajo","Ir al centro comercial"],"h1":"Piense en un empleo.","h2":"En Delaware, un aprendiz puede manejar solo entre las 10 p.m. y las 6 a.m. solamente para ir o volver del trabajo, de la iglesia o de actividades escolares.","p":"Correcto. Los viajes del trabajo son una excepción de noche."},"ref":{"doc":"DE","page":30}},{"id":"de-011","scope":"DE","cat":"licensing","sign":null,"c":0,"en":{"q":"In Delaware, how many passengers may ride with a permit holder, besides the adult supervisor?","o":["One passenger","No passengers","Two passengers","As many as there are seat belts"],"h1":"The number is very small, but not zero.","h2":"A Delaware permit holder may carry no more than one passenger besides the adult supervisor. Immediate family members are the only exception, and only when the adult supervisor is in the car.","p":"Right. Only one other passenger is allowed."},"es":{"q":"En Delaware, ¿cuántos pasajeros pueden viajar con un aprendiz, además del supervisor adulto?","o":["Un pasajero","Ningún pasajero","Dos pasajeros","Tantos como cinturones haya"],"h1":"El número es muy pequeño, pero no es cero.","h2":"Un aprendiz en Delaware puede llevar como máximo un pasajero además del supervisor adulto. Solo los familiares directos son la excepción, y solo cuando el supervisor adulto está en el auto.","p":"Correcto. Solo se permite un pasajero más."},"ref":{"doc":"DE","page":29}},{"id":"de-012","scope":"DE","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Delaware, how may an adult driver talk on a phone while driving?","o":["Holding the phone to the ear","Only with a hands-free device","Only at red lights, holding the phone","Only on highways"],"h1":"Your hands stay off the phone.","h2":"In Delaware, an adult driver may talk on the phone while driving only with a hands-free device.","p":"Right. Delaware bans holding the phone while driving."},"es":{"q":"En Delaware, ¿cómo puede un conductor adulto hablar por teléfono mientras maneja?","o":["Sosteniendo el teléfono en el oído","Solo con un dispositivo de manos libres","Solo en los semáforos en rojo, sosteniendo el teléfono","Solo en las autopistas"],"h1":"Sus manos no tocan el teléfono.","h2":"En Delaware, un conductor adulto puede hablar por teléfono mientras maneja solamente con un dispositivo de manos libres.","p":"Correcto. Delaware prohíbe sostener el teléfono al manejar."},"ref":{"doc":"DE","page":81}},{"id":"de-013","scope":"DE","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Delaware, what blood alcohol level is illegal for a driver under 21?","o":["0.08 percent or more","0.02 percent or more","0.05 percent or more","0.10 percent or more"],"h1":"It is much lower than the adult limit.","h2":"In Delaware, a driver under 21 with a blood alcohol level of 0.02 percent or more loses the license under the zero tolerance law.","p":"Right. The limit under 21 is 0.02 percent."},"es":{"q":"En Delaware, ¿qué nivel de alcohol en la sangre es ilegal para un conductor menor de 21 años?","o":["0.08 por ciento o más","0.02 por ciento o más","0.05 por ciento o más","0.10 por ciento o más"],"h1":"Es mucho más bajo que el límite para adultos.","h2":"En Delaware, un conductor menor de 21 años con un nivel de alcohol en la sangre de 0.02 por ciento o más pierde la licencia por la ley de tolerancia cero.","p":"Correcto. El límite para menores de 21 es 0.02 por ciento."},"ref":{"doc":"DE","page":50}},{"id":"ga-001","scope":"GA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Georgia, what is the youngest age to get a learner's permit (Class CP)?","o":["14 years old","15 years old","16 years old","17 years old"],"h1":"It comes one year before you can take the road test for a Class D license.","h2":"In Georgia you can get a Class CP learner's permit at 15, after you pass the vision and knowledge tests.","p":"Right. The Georgia learner's permit starts at 15."},"es":{"q":"En Georgia, ¿cuál es la edad mínima para obtener el permiso de aprendiz (Clase CP)?","o":["14 años","15 años","16 años","17 años"],"h1":"Es un año antes de poder hacer el examen de manejo para la licencia Clase D.","h2":"En Georgia usted puede obtener el permiso de aprendiz Clase CP a los 15 años, después de aprobar los exámenes de la vista y de conocimientos.","p":"Correcto. El permiso de aprendiz en Georgia empieza a los 15."},"ref":{"doc":"GA","page":8}},{"id":"ga-002","scope":"GA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Georgia, how old must the licensed person beside a learner's permit driver be?","o":["At least 16","At least 18","At least 25","At least 21"],"h1":"The helper must be old enough to buy alcohol legally.","h2":"A Georgia permit driver must have a licensed person who is at least 21 years old in the car.","p":"Right. The person with you must be 21 or older."},"es":{"q":"En Georgia, ¿qué edad debe tener la persona con licencia que acompaña a un conductor con permiso de aprendiz?","o":["Por lo menos 16","Por lo menos 18","Por lo menos 25","Por lo menos 21"],"h1":"El acompañante debe tener edad para comprar alcohol legalmente.","h2":"Un conductor con permiso en Georgia debe llevar en el carro a una persona con licencia de por lo menos 21 años.","p":"Correcto. Su acompañante debe tener 21 años o más."},"ref":{"doc":"GA","page":8}},{"id":"ga-003","scope":"GA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Georgia, where must the supervising adult sit when a learner's permit holder drives?","o":["In the seat next to the driver","In the back seat","Anywhere in the car","In a car following behind"],"h1":"The adult must be close enough to take control of the car.","h2":"In Georgia the supervising adult must sit in the seat next to the driver, ready to take control if needed.","p":"Right. The adult sits next to you."},"es":{"q":"En Georgia, ¿dónde debe sentarse el adulto que supervisa a un conductor con permiso de aprendiz?","o":["En el asiento al lado del conductor","En el asiento de atrás","En cualquier lugar del carro","En otro carro que va detrás"],"h1":"El adulto debe estar lo bastante cerca para tomar el control del carro.","h2":"En Georgia el adulto que supervisa debe sentarse en el asiento al lado del conductor, listo para tomar el control si hace falta.","p":"Correcto. El adulto va sentado a su lado."},"ref":{"doc":"GA","page":8}},{"id":"ga-004","scope":"GA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Georgia, how long must a teen hold the learner's permit before taking the road test for a Class D license?","o":["3 months","6 months","One year and one day","Two years"],"h1":"It is a little more than one full year.","h2":"A Georgia teen must hold the learner's permit for one year and one day before taking the Class D road test.","p":"Right. One year and one day."},"es":{"q":"En Georgia, ¿cuánto tiempo debe tener un adolescente el permiso de aprendiz antes del examen de manejo para la licencia Clase D?","o":["3 meses","6 meses","Un año y un día","Dos años"],"h1":"Es un poco más de un año completo.","h2":"Un adolescente en Georgia debe tener el permiso de aprendiz durante un año y un día antes del examen de manejo para la licencia Clase D.","p":"Correcto. Un año y un día."},"ref":{"doc":"GA","page":8}},{"id":"ga-005","scope":"GA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Georgia, what is the youngest age to take the road test for a Class D license?","o":["15 years old","16 years old","17 years old","18 years old"],"h1":"It is one year after the youngest age for a learner's permit.","h2":"In Georgia you can take the road test for a Class D license once you turn 16 and have held your permit long enough.","p":"Right. The Class D road test starts at 16."},"es":{"q":"En Georgia, ¿cuál es la edad mínima para hacer el examen de manejo para la licencia Clase D?","o":["15 años","16 años","17 años","18 años"],"h1":"Es un año después de la edad mínima para el permiso de aprendiz.","h2":"En Georgia usted puede hacer el examen de manejo para la licencia Clase D cuando cumple 16 años y ha tenido el permiso el tiempo necesario.","p":"Correcto. El examen para la Clase D empieza a los 16."},"ref":{"doc":"GA","page":8}},{"id":"ga-006","scope":"GA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Georgia, how many hours of supervised driving must a 16- or 17-year-old complete for a Class D license?","o":["20 hours","30 hours","40 hours","65 hours"],"h1":"It is more than 30 and less than 50.","h2":"Under Joshua's Law, a Georgia teen needs at least 40 hours of supervised driving before getting a Class D license.","p":"Right. Georgia asks for 40 hours of supervised driving."},"es":{"q":"En Georgia, ¿cuántas horas de manejo supervisado debe completar un joven de 16 o 17 años para la licencia Clase D?","o":["20 horas","30 horas","40 horas","65 horas"],"h1":"Son más de 30 y menos de 50.","h2":"Según la Ley de Joshua, un adolescente en Georgia necesita por lo menos 40 horas de manejo supervisado antes de obtener la licencia Clase D.","p":"Correcto. Georgia pide 40 horas de manejo supervisado."},"ref":{"doc":"GA","page":8}},{"id":"ga-007","scope":"GA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Georgia, how many of the required supervised driving hours must be at night?","o":["6 hours","2 hours","10 hours","20 hours"],"h1":"It is a small part of the total, less than 10.","h2":"Of the 40 supervised hours a Georgia teen needs, at least 6 hours must be driven at night.","p":"Right. At least 6 of the hours are at night."},"es":{"q":"En Georgia, ¿cuántas de las horas de manejo supervisado deben ser de noche?","o":["6 horas","2 horas","10 horas","20 horas"],"h1":"Es una parte pequeña del total, menos de 10.","h2":"De las 40 horas supervisadas que necesita un adolescente en Georgia, por lo menos 6 horas deben ser de noche.","p":"Correcto. Por lo menos 6 horas son de noche."},"ref":{"doc":"GA","page":8}},{"id":"ga-008","scope":"GA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Georgia, how long is the approved driver education course (classroom or online) that Joshua's Law requires?","o":["5 hours","10 hours","20 hours","30 hours"],"h1":"It is the largest number in the list.","h2":"Joshua's Law requires Georgia teens to complete a 30-hour approved driver education course, in a classroom or online.","p":"Right. The course is 30 hours."},"es":{"q":"En Georgia, ¿cuántas horas dura el curso aprobado de educación vial (en clase o en línea) que exige la Ley de Joshua?","o":["5 horas","10 horas","20 horas","30 horas"],"h1":"Es el número más grande de la lista.","h2":"La Ley de Joshua exige que los adolescentes en Georgia completen un curso aprobado de educación vial de 30 horas, en clase o en línea.","p":"Correcto. El curso es de 30 horas."},"ref":{"doc":"GA","page":8}},{"id":"ga-009","scope":"GA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Georgia, besides the driver education course, what behind-the-wheel training does Joshua's Law accept?","o":["1 hour with any adult","6 hours with a certified instructor, or the DDS parent-teen driving guide","A video course only","No behind-the-wheel training is needed"],"h1":"There are two ways to do it: one with a professional, one with a parent.","h2":"Joshua's Law accepts 6 hours of driving with a certified instructor, or completing the DDS parent-teen driving guide.","p":"Right. Six hours with an instructor, or the parent-teen guide."},"es":{"q":"En Georgia, además del curso de educación vial, ¿qué práctica al volante acepta la Ley de Joshua?","o":["1 hora con cualquier adulto","6 horas con un instructor certificado, o la guía de manejo para padres e hijos del DDS","Solo un curso en video","No hace falta práctica al volante"],"h1":"Hay dos maneras: una con un profesional y otra con un padre o madre.","h2":"La Ley de Joshua acepta 6 horas de manejo con un instructor certificado, o completar la guía de manejo para padres e hijos del DDS.","p":"Correcto. Seis horas con instructor, o la guía para padres e hijos."},"ref":{"doc":"GA","page":8}},{"id":"ga-010","scope":"GA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Georgia, how does a teen show that the 40 hours of supervised driving were completed?","o":["The teen sends photos of the drives","A police officer rides along","A parent or guardian confirms it in writing at DDS","Nothing is needed"],"h1":"An adult who knows the teen gives their word in writing.","h2":"In Georgia no driving log is needed: a parent or guardian confirms in writing at DDS that the teen drove the 40 hours, including 6 at night.","p":"Right. A parent or guardian confirms the hours in writing."},"es":{"q":"En Georgia, ¿cómo demuestra un adolescente que completó las 40 horas de manejo supervisado?","o":["El adolescente envía fotos de los viajes","Un policía lo acompaña","Un padre o tutor lo confirma por escrito en el DDS","No hace falta nada"],"h1":"Un adulto que conoce al adolescente lo confirma por escrito.","h2":"En Georgia no se necesita un registro de manejo: un padre o tutor confirma por escrito en el DDS que el adolescente manejó las 40 horas, incluidas 6 de noche.","p":"Correcto. Un padre o tutor confirma las horas por escrito."},"ref":{"doc":"GA","page":8}},{"id":"ga-011","scope":"GA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Georgia, what license must the adult who supervises practice driving hold?","o":["A valid license to drive a regular car (Class C)","A learner's permit","Any license from any country, even expired","No license is needed"],"h1":"It is the full adult license, and it must not be expired.","h2":"In Georgia the adult who supervises practice driving must be at least 21 and hold a valid license to drive a Class C vehicle, a regular car.","p":"Right. The supervisor needs a valid Class C license."},"es":{"q":"En Georgia, ¿qué licencia debe tener el adulto que supervisa la práctica de manejo?","o":["Una licencia vigente para manejar un carro normal (Clase C)","Un permiso de aprendiz","Cualquier licencia de cualquier país, aunque esté vencida","No necesita licencia"],"h1":"Es la licencia completa de adulto, y no puede estar vencida.","h2":"En Georgia el adulto que supervisa la práctica debe tener por lo menos 21 años y una licencia vigente para manejar un vehículo Clase C, un carro normal.","p":"Correcto. El supervisor necesita una licencia Clase C vigente."},"ref":{"doc":"GA","page":8}},{"id":"ga-012","scope":"GA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Georgia, during the first six months with a Class D license, who may ride with the teen driver?","o":["Up to three friends","One friend under 21","Anyone, with no limit","Only immediate family members"],"h1":"At the start, the rule is the strictest it will ever be.","h2":"During the first six months with a Georgia Class D license, the only passengers allowed are immediate family members.","p":"Right. Only immediate family at first."},"es":{"q":"En Georgia, durante los primeros seis meses con licencia Clase D, ¿quién puede ir con el conductor adolescente?","o":["Hasta tres amigos","Un amigo menor de 21 años","Cualquier persona, sin límite","Solo familiares inmediatos"],"h1":"Al principio, la regla es la más estricta de todas.","h2":"Durante los primeros seis meses con licencia Clase D en Georgia, solo pueden ir como pasajeros los familiares inmediatos.","p":"Correcto. Al principio, solo familiares inmediatos."},"ref":{"doc":"GA","page":8}},{"id":"ga-013","scope":"GA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Georgia, during the second six months with a Class D license, how many passengers under 21 who are not family may ride with the teen?","o":["None","One","Two","Five"],"h1":"The limit opens up a little, but only a little.","h2":"In the second six months with a Georgia Class D license, the teen may carry no more than one passenger under 21 who is not family.","p":"Right. One non-family passenger under 21."},"es":{"q":"En Georgia, durante el segundo semestre con licencia Clase D, ¿cuántos pasajeros menores de 21 años que no son familia pueden ir con el adolescente?","o":["Ninguno","Uno","Dos","Cinco"],"h1":"El límite se abre un poco, pero muy poco.","h2":"En el segundo semestre con licencia Clase D en Georgia, el adolescente puede llevar como máximo un pasajero menor de 21 años que no sea familia.","p":"Correcto. Un pasajero menor de 21 que no es familia."},"ref":{"doc":"GA","page":8}},{"id":"ga-014","scope":"GA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Georgia, after one year with a Class D license, how many passengers under 21 who are not family may ride with the teen?","o":["One","Two","Three","Any number"],"h1":"It is more than in the second six months, but there is still a limit.","h2":"After the first year with a Georgia Class D license, the teen may carry up to three passengers under 21 who are not family.","p":"Right. Up to three after the first year."},"es":{"q":"En Georgia, después de un año con licencia Clase D, ¿cuántos pasajeros menores de 21 años que no son familia pueden ir con el adolescente?","o":["Uno","Dos","Tres","Cualquier cantidad"],"h1":"Son más que en el segundo semestre, pero todavía hay un límite.","h2":"Después del primer año con licencia Clase D en Georgia, el adolescente puede llevar hasta tres pasajeros menores de 21 años que no sean familia.","p":"Correcto. Hasta tres después del primer año."},"ref":{"doc":"GA","page":8}},{"id":"ga-015","scope":"GA","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Georgia, what does the hands-free law say about holding a phone while driving?","o":["You may not hold the phone or support it with any part of your body","You may hold it if you drive slowly","You may hold it on city streets only","You may hold it if you are over 21"],"h1":"The law is named after what your hands must be.","h2":"Georgia's hands-free law makes it illegal for any driver to hold a phone or support it with any part of the body while driving.","p":"Right. In Georgia the phone stays out of your hands."},"es":{"q":"En Georgia, ¿qué dice la ley de manos libres sobre sostener el teléfono mientras maneja?","o":["No puede sostener el teléfono ni apoyarlo con ninguna parte del cuerpo","Puede sostenerlo si maneja despacio","Puede sostenerlo solo en calles de la ciudad","Puede sostenerlo si tiene más de 21 años"],"h1":"El nombre de la ley dice cómo deben estar sus manos.","h2":"La ley de manos libres de Georgia prohíbe que cualquier conductor sostenga el teléfono o lo apoye con alguna parte del cuerpo mientras maneja.","p":"Correcto. En Georgia el teléfono no va en la mano."},"ref":{"doc":"GA","page":25}},{"id":"ga-016","scope":"GA","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Georgia, you use your phone for map directions while driving. Which way is allowed under the hands-free law?","o":["Holding it in your lap","Holding it in one hand","Resting it on your shoulder","In a phone holder or mount, without holding it"],"h1":"The phone must stay put without you holding it.","h2":"Georgia's hands-free law lets you use a phone for directions only when it sits in a holder or mount, not in your hand or on your body.","p":"Right. Put the phone in a holder or mount."},"es":{"q":"En Georgia, usted usa su teléfono para ver el mapa mientras maneja. ¿Qué manera permite la ley de manos libres?","o":["Sostenerlo en las piernas","Sostenerlo en una mano","Apoyarlo en el hombro","En un soporte o base, sin sostenerlo"],"h1":"El teléfono debe quedarse fijo sin que usted lo sostenga.","h2":"La ley de manos libres de Georgia le permite usar el teléfono para direcciones solo si está en un soporte o base, no en su mano ni sobre su cuerpo.","p":"Correcto. Ponga el teléfono en un soporte o base."},"ref":{"doc":"GA","page":25}},{"id":"ga-017","scope":"GA","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Georgia, you are driving the opposite way from a stopped school bus with flashing lights and stop signs out, on a divided highway. What must you do?","o":["Stop until the bus moves","Continue with caution; you do not have to stop","Speed up to pass quickly","Turn around"],"h1":"The divided highway is the only exception to the stopping rule.","h2":"In Georgia, drivers going the opposite way on a divided highway do not have to stop for a school bus, but they must drive with caution.","p":"Right. On a divided highway, oncoming traffic continues with caution."},"es":{"q":"En Georgia, usted va en dirección contraria a un autobús escolar detenido con luces intermitentes y señales de alto extendidas, en una carretera dividida. ¿Qué debe hacer?","o":["Detenerse hasta que el autobús avance","Seguir con precaución; no tiene que detenerse","Acelerar para pasar rápido","Dar la vuelta"],"h1":"La carretera dividida es la única excepción a la regla de detenerse.","h2":"En Georgia, los conductores que van en dirección contraria en una carretera dividida no tienen que detenerse por un autobús escolar, pero deben manejar con precaución.","p":"Correcto. En carretera dividida, el tráfico contrario sigue con precaución."},"ref":{"doc":"GA","page":44}},{"id":"ga-018","scope":"GA","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Georgia, on a road that is not divided, a school bus stops with flashing lights and stop signs out. Who must stop?","o":["Traffic in both directions","Only traffic behind the bus","Only traffic coming toward the bus","No one, if no children are seen"],"h1":"On a road with no division, nobody may pass the bus.","h2":"In Georgia, on a road that is not divided, vehicles going in either direction must stop and may not pass a stopped school bus.","p":"Right. Both directions stop."},"es":{"q":"En Georgia, en una calle que no está dividida, un autobús escolar se detiene con luces intermitentes y señales de alto extendidas. ¿Quién debe detenerse?","o":["El tráfico en ambas direcciones","Solo el tráfico detrás del autobús","Solo el tráfico que viene hacia el autobús","Nadie, si no se ven niños"],"h1":"En una calle sin división, nadie puede pasar al autobús.","h2":"En Georgia, en una calle que no está dividida, los vehículos que van en cualquier dirección deben detenerse y no pueden pasar a un autobús escolar detenido.","p":"Correcto. Ambas direcciones se detienen."},"ref":{"doc":"GA","page":44}},{"id":"ga-019","scope":"GA","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Georgia, an emergency vehicle with flashing lights is parked on the shoulder. What does the Move Over Law require first, if it is safe?","o":["Honk to warn the workers","Stop in your lane","Move over one lane, away from the vehicle","Drive on the shoulder"],"h1":"The law's name tells you what to do.","h2":"Georgia's Move Over Law requires you to move over one lane, away from the stopped emergency vehicle, when it is safe to do so.","p":"Right. Move over one lane."},"es":{"q":"En Georgia, un vehículo de emergencia con luces intermitentes está estacionado en el acotamiento. ¿Qué exige primero la Ley de Cambio de Carril (Move Over), si es seguro?","o":["Tocar la bocina para avisar a los trabajadores","Detenerse en su carril","Cambiarse un carril, lejos del vehículo","Manejar por el acotamiento"],"h1":"El nombre de la ley le dice qué hacer.","h2":"La Ley de Cambio de Carril de Georgia exige que usted se cambie un carril, lejos del vehículo de emergencia detenido, cuando sea seguro hacerlo.","p":"Correcto. Cámbiese un carril."},"ref":{"doc":"GA","page":18}},{"id":"ga-020","scope":"GA","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Georgia, traffic is too heavy to move over for a stopped emergency vehicle. What must you do?","o":["Keep your speed","Stop completely on the highway","Change lanes anyway","Slow down below the speed limit and be ready to stop"],"h1":"If you cannot get away from it, pass it gently.","h2":"When you cannot safely move over in Georgia, you must slow down below the posted speed limit and be prepared to stop.","p":"Right. Slow down and be ready to stop."},"es":{"q":"En Georgia, hay demasiado tráfico para cambiarse de carril por un vehículo de emergencia detenido. ¿Qué debe hacer?","o":["Mantener su velocidad","Detenerse por completo en la carretera","Cambiarse de carril de todos modos","Bajar la velocidad por debajo del límite y estar listo para detenerse"],"h1":"Si no puede alejarse, pase con suavidad.","h2":"Cuando no puede cambiarse de carril con seguridad en Georgia, usted debe bajar la velocidad por debajo del límite indicado y estar listo para detenerse.","p":"Correcto. Baje la velocidad y esté listo para detenerse."},"ref":{"doc":"GA","page":18}},{"id":"ga-021","scope":"GA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Georgia, what is the legal blood alcohol limit for drivers under 21?","o":["0.00 percent","0.02 percent","0.05 percent","0.08 percent"],"h1":"It is much lower than the adult limit, but it is not zero.","h2":"In Georgia a driver under 21 is over the limit at a blood alcohol level of 0.02 percent, much lower than the 0.08 limit for adults.","p":"Right. Under 21, the limit is 0.02 percent."},"es":{"q":"En Georgia, ¿cuál es el límite legal de alcohol en la sangre para conductores menores de 21 años?","o":["0.00 por ciento","0.02 por ciento","0.05 por ciento","0.08 por ciento"],"h1":"Es mucho más bajo que el límite para adultos, pero no es cero.","h2":"En Georgia un conductor menor de 21 años pasa el límite con un nivel de alcohol en la sangre de 0.02 por ciento, mucho más bajo que el límite de 0.08 para adultos.","p":"Correcto. Para menores de 21, el límite es 0.02 por ciento."},"ref":{"doc":"GA","page":23}},{"id":"hi-001","scope":"HI","cat":"licensing","sign":null,"c":2,"en":{"q":"In Hawaii, what is the youngest age to get an instruction permit?","o":["14 years old","15 years old","15 and a half years old","16 years old"],"h1":"It is half a year past a birthday.","h2":"In Hawaii you can get an instruction permit at 15 and a half years old.","p":"Right. The Hawaii permit starts at 15 and a half."},"es":{"q":"En Hawái, ¿cuál es la edad mínima para obtener un permiso de instrucción?","o":["14 años","15 años","15 años y medio","16 años"],"h1":"Es medio año después de un cumpleaños.","h2":"En Hawái usted puede obtener el permiso de instrucción a los 15 años y medio.","p":"Correcto. El permiso en Hawái empieza a los 15 años y medio."},"ref":{"doc":"HI","page":13}},{"id":"hi-002","scope":"HI","cat":"licensing","sign":null,"c":1,"en":{"q":"In Hawaii, how old must the licensed driver with a permit holder be?","o":["At least 18","At least 21","At least 25","At least 30"],"h1":"The helper must be old enough to drink alcohol legally.","h2":"A Hawaii permit holder may drive only with a licensed driver who is at least 21 years old.","p":"Right. The adult with you must be 21 or older."},"es":{"q":"En Hawái, ¿qué edad debe tener el conductor con licencia que acompaña a quien tiene permiso?","o":["Por lo menos 18","Por lo menos 21","Por lo menos 25","Por lo menos 30"],"h1":"El acompañante debe tener edad para tomar alcohol legalmente.","h2":"Quien tiene un permiso en Hawái solo puede manejar con un conductor con licencia de por lo menos 21 años.","p":"Correcto. El adulto que lo acompaña debe tener 21 años o más."},"ref":{"doc":"HI","page":11}},{"id":"hi-003","scope":"HI","cat":"licensing","sign":null,"c":0,"en":{"q":"In Hawaii, where must the supervising driver sit when a permit holder drives?","o":["In the front passenger seat","In the back seat behind the driver","Anywhere in the car","In the back seat on the right"],"h1":"The helper needs to see the road and reach the driver quickly.","h2":"The supervising driver must sit in the front passenger seat, beside the Hawaii permit holder.","p":"Right. The helper sits right beside you."},"es":{"q":"En Hawái, ¿dónde debe sentarse el conductor supervisor cuando maneja alguien con permiso?","o":["En el asiento del pasajero delantero","En el asiento trasero detrás del conductor","En cualquier lugar del carro","En el asiento trasero a la derecha"],"h1":"El acompañante necesita ver la vía y alcanzar al conductor rápido.","h2":"El conductor supervisor debe sentarse en el asiento del pasajero delantero, al lado de quien tiene el permiso en Hawái.","p":"Correcto. El acompañante va a su lado."},"ref":{"doc":"HI","page":11}},{"id":"hi-004","scope":"HI","cat":"licensing","sign":null,"c":3,"en":{"q":"In Hawaii, how long must you hold an instruction permit before the road test?","o":["30 days","90 days","1 year","180 days"],"h1":"It is about half a year.","h2":"In Hawaii you must hold your instruction permit for at least 180 days before you take the road test.","p":"Right. You practice for at least 180 days first."},"es":{"q":"En Hawái, ¿cuánto tiempo debe tener el permiso de instrucción antes del examen de manejo?","o":["30 días","90 días","1 año","180 días"],"h1":"Es más o menos medio año.","h2":"En Hawái usted debe tener el permiso de instrucción por lo menos 180 días antes de presentar el examen de manejo.","p":"Correcto. Primero practica por lo menos 180 días."},"ref":{"doc":"HI","page":13}},{"id":"hi-005","scope":"HI","cat":"licensing","sign":null,"c":1,"en":{"q":"In Hawaii, what is the youngest age to get a provisional license?","o":["15 years old","16 years old","17 years old","18 years old"],"h1":"It comes after a half year of practice with a permit from age 15 and a half.","h2":"In Hawaii the provisional license is available from age 16.","p":"Right. The provisional license starts at 16."},"es":{"q":"En Hawái, ¿cuál es la edad mínima para obtener una licencia provisional?","o":["15 años","16 años","17 años","18 años"],"h1":"Llega después de medio año de práctica con un permiso desde los 15 años y medio.","h2":"En Hawái la licencia provisional se puede obtener desde los 16 años.","p":"Correcto. La licencia provisional empieza a los 16."},"ref":{"doc":"HI","page":13}},{"id":"hi-006","scope":"HI","cat":"licensing","sign":null,"c":2,"en":{"q":"In Hawaii, during which hours does a provisional licensee need a parent or guardian in the car?","o":["9 p.m. to 5 a.m.","Midnight to 6 a.m.","11 p.m. to 5 a.m.","10 p.m. to 6 a.m."],"h1":"It starts one hour before midnight.","h2":"A Hawaii provisional licensee who drives between 11 p.m. and 5 a.m. must have a licensed parent or guardian in the seat beside them, unless an exception applies.","p":"Right. The night limit is 11 p.m. to 5 a.m."},"es":{"q":"En Hawái, ¿en qué horas necesita un conductor con licencia provisional a su padre, madre o tutor en el carro?","o":["De 9 p.m. a 5 a.m.","De medianoche a 6 a.m.","De 11 p.m. a 5 a.m.","De 10 p.m. a 6 a.m."],"h1":"Empieza una hora antes de la medianoche.","h2":"Un conductor con licencia provisional en Hawái que maneja entre las 11 p.m. y las 5 a.m. debe llevar al lado a su padre, madre o tutor con licencia, salvo que aplique una excepción.","p":"Correcto. El límite de noche es de 11 p.m. a 5 a.m."},"ref":{"doc":"HI","page":14}},{"id":"hi-007","scope":"HI","cat":"licensing","sign":null,"c":0,"en":{"q":"In Hawaii, who must ride beside a provisional licensee driving late at night?","o":["A licensed parent or guardian","Any passenger over 16","Any licensed friend","A driving school teacher only"],"h1":"It is a family adult who is responsible for the teen.","h2":"In Hawaii, a provisional licensee driving between 11 p.m. and 5 a.m. must have a licensed parent or guardian in the seat beside them.","p":"Right. A licensed parent or guardian rides along."},"es":{"q":"En Hawái, ¿quién debe ir al lado de un conductor con licencia provisional que maneja tarde en la noche?","o":["Su padre, madre o tutor con licencia","Cualquier pasajero mayor de 16","Cualquier amigo con licencia","Solo un instructor de manejo"],"h1":"Es un adulto de la familia que responde por el adolescente.","h2":"En Hawái, un conductor con licencia provisional que maneja entre las 11 p.m. y las 5 a.m. debe llevar al lado a su padre, madre o tutor con licencia.","p":"Correcto. Lo acompaña su padre, madre o tutor con licencia."},"ref":{"doc":"HI","page":14}},{"id":"hi-008","scope":"HI","cat":"licensing","sign":null,"c":3,"en":{"q":"In Hawaii, when may a provisional licensee drive alone after 11 p.m.?","o":["Any time they feel awake","When going to a friend's house","When the roads are empty","Going straight to or from work, with a note from the employer in the car"],"h1":"Think of a trip that has paperwork behind it.","h2":"A Hawaii provisional licensee may drive alone at night when going directly to or from work, with documentation from the employer kept in the vehicle.","p":"Right. Work trips with a note are allowed."},"es":{"q":"En Hawái, ¿cuándo puede un conductor con licencia provisional manejar solo después de las 11 p.m.?","o":["Cuando se sienta despierto","Cuando va a la casa de un amigo","Cuando las calles están vacías","Directo al trabajo o de regreso, con una nota del empleador en el carro"],"h1":"Piense en un viaje que tiene un papel que lo respalda.","h2":"Un conductor con licencia provisional en Hawái puede manejar solo de noche cuando va directo al trabajo o regresa de él, con un documento del empleador dentro del vehículo.","p":"Correcto. Los viajes al trabajo con una nota están permitidos."},"ref":{"doc":"HI","page":14}},{"id":"hi-009","scope":"HI","cat":"licensing","sign":null,"c":1,"en":{"q":"In Hawaii, how many passengers under 18 may a provisional licensee carry without a parent or guardian?","o":["None at all","One, unless the others live in the same household","Two","Three"],"h1":"Count on one hand, and use just one finger.","h2":"Without a parent or guardian along, a Hawaii provisional licensee may carry no more than one person under 18, unless the others are household members.","p":"Right. Only one young passenger from outside the home."},"es":{"q":"En Hawái, ¿cuántos pasajeros menores de 18 puede llevar un conductor con licencia provisional sin su padre, madre o tutor?","o":["Ninguno","Uno, salvo que los demás vivan en la misma casa","Dos","Tres"],"h1":"Cuente con una mano, y use solo un dedo.","h2":"Sin su padre, madre o tutor en el carro, un conductor con licencia provisional en Hawái puede llevar como máximo a una persona menor de 18, salvo que los demás vivan en su misma casa.","p":"Correcto. Solo un pasajero joven de fuera de la casa."},"ref":{"doc":"HI","page":13}},{"id":"hi-010","scope":"HI","cat":"licensing","sign":null,"c":2,"en":{"q":"In Hawaii, which young passengers do not count toward a provisional licensee's passenger limit?","o":["Classmates","Teammates","Members of the driver's household","Neighbors"],"h1":"Think of the people who live under the same roof.","h2":"In Hawaii, passengers under 18 who are members of the provisional licensee's household do not count toward the one-passenger limit.","p":"Right. People from your own home do not count."},"es":{"q":"En Hawái, ¿qué pasajeros jóvenes no cuentan en el límite de pasajeros de un conductor con licencia provisional?","o":["Compañeros de clase","Compañeros de equipo","Personas que viven en la casa del conductor","Vecinos"],"h1":"Piense en las personas que viven bajo el mismo techo.","h2":"En Hawái, los pasajeros menores de 18 que viven en la casa del conductor con licencia provisional no cuentan en el límite de un pasajero.","p":"Correcto. Las personas de su propia casa no cuentan."},"ref":{"doc":"HI","page":13}},{"id":"hi-011","scope":"HI","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Hawaii, may an adult driver hold a phone and use it while driving?","o":["No, using a mobile electronic device while driving is banned","Yes, at any speed","Yes, but only on the highway","Yes, if no police are around"],"h1":"The rule covers every driver, not only teens.","h2":"Hawaii law says no person may drive a motor vehicle while using a mobile electronic device, so you must not hold and use your phone while driving.","p":"Right. Put the phone down while you drive."},"es":{"q":"En Hawái, ¿puede un conductor adulto sostener y usar un teléfono mientras maneja?","o":["No, usar un aparato electrónico móvil mientras maneja está prohibido","Sí, a cualquier velocidad","Sí, pero solo en la autopista","Sí, si no hay policía cerca"],"h1":"La regla es para todos los conductores, no solo los jóvenes.","h2":"La ley de Hawái dice que nadie puede manejar un vehículo mientras usa un aparato electrónico móvil, así que usted no debe sostener ni usar su teléfono al manejar.","p":"Correcto. Deje el teléfono mientras maneja."},"ref":{"doc":"HI","page":null}},{"id":"hi-012","scope":"HI","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Hawaii, may a 17-year-old driver use a hands-free phone while driving?","o":["Yes, any time","Yes, but only for music","Yes, if a parent is in the car","No, drivers under 18 may not use even a hands-free device"],"h1":"The rule for teens is stricter than the rule for adults.","h2":"In Hawaii, a driver under 18 may not use a hands-free mobile electronic device while driving, except to call 911.","p":"Right. Under 18, no phone at all while driving."},"es":{"q":"En Hawái, ¿puede un conductor de 17 años usar un teléfono de manos libres mientras maneja?","o":["Sí, en cualquier momento","Sí, pero solo para música","Sí, si va un padre en el carro","No, los menores de 18 no pueden usar ni siquiera un aparato de manos libres"],"h1":"La regla para jóvenes es más estricta que para adultos.","h2":"En Hawái, un conductor menor de 18 no puede usar un aparato electrónico móvil de manos libres mientras maneja, salvo para llamar al 911.","p":"Correcto. Menor de 18, nada de teléfono al manejar."},"ref":{"doc":"HI","page":null}},{"id":"hi-013","scope":"HI","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Hawaii, for what reason may a driver under 18 use a hands-free phone while driving?","o":["To answer a parent's text","To call 911 in an emergency","To check a map","To talk with a friend"],"h1":"It is the number you call when someone needs help right away.","h2":"A Hawaii driver under 18 may use a hands-free device while driving only to make a 911 emergency call.","p":"Right. Only a 911 emergency call."},"es":{"q":"En Hawái, ¿por qué razón puede un conductor menor de 18 usar un teléfono de manos libres al manejar?","o":["Para contestar un mensaje de sus padres","Para llamar al 911 en una emergencia","Para ver un mapa","Para hablar con un amigo"],"h1":"Es el número al que se llama cuando alguien necesita ayuda de inmediato.","h2":"Un conductor menor de 18 en Hawái solo puede usar un aparato de manos libres al manejar para hacer una llamada de emergencia al 911.","p":"Correcto. Solo una llamada de emergencia al 911."},"ref":{"doc":"HI","page":null}},{"id":"hi-014","scope":"HI","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Hawaii, where is the fine for using a phone while driving higher?","o":["On rural roads","In parking lots","In a school zone or a construction area","On the freeway at night"],"h1":"Think of places where children or road workers are close by.","h2":"In Hawaii, the fine for using a mobile device while driving is higher in a school zone or a construction area.","p":"Right. School zones and work zones cost more."},"es":{"q":"En Hawái, ¿dónde es más alta la multa por usar el teléfono mientras maneja?","o":["En caminos rurales","En estacionamientos","En una zona escolar o una zona de construcción","En la autopista de noche"],"h1":"Piense en lugares donde hay niños o trabajadores cerca.","h2":"En Hawái, la multa por usar un aparato móvil mientras maneja es más alta en una zona escolar o una zona de construcción.","p":"Correcto. Las zonas escolares y de obras cuestan más."},"ref":{"doc":"HI","page":null}},{"id":"hi-015","scope":"HI","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Hawaii, what is the usual fine for using a mobile device while driving?","o":["$300","$25","$50","$1,000"],"h1":"It is a few hundred dollars.","h2":"In Hawaii the usual fine for using a mobile electronic device while driving is $300.","p":"Right. The usual fine is $300."},"es":{"q":"En Hawái, ¿cuál es la multa normal por usar un aparato móvil mientras maneja?","o":["$300","$25","$50","$1,000"],"h1":"Son unos cientos de dólares.","h2":"En Hawái la multa normal por usar un aparato electrónico móvil mientras maneja es de $300.","p":"Correcto. La multa normal es de $300."},"ref":{"doc":"HI","page":null}},{"id":"hi-016","scope":"HI","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Hawaii, what must you do when you approach a stopped emergency vehicle with flashing lights?","o":["Keep your speed and honk","Flash your high beams at it","Speed up to pass it fast","Slow to a safe speed and move to the next lane if it is safe"],"h1":"Give the workers more space and more time.","h2":"Hawaii's move over law says to slow down to a safe and prudent speed and, when it is safe, move into the next lane away from the stopped emergency vehicle.","p":"Right. Slow down and move over."},"es":{"q":"En Hawái, ¿qué debe hacer al acercarse a un vehículo de emergencia detenido con luces intermitentes?","o":["Mantener la velocidad y tocar la bocina","Hacerle cambio de luces altas","Acelerar para pasarlo rápido","Bajar a una velocidad segura y cambiarse al carril de al lado si es seguro"],"h1":"Dé a los trabajadores más espacio y más tiempo.","h2":"La ley de Hawái para moverse de carril dice que debe bajar a una velocidad segura y prudente y, cuando sea seguro, cambiarse al carril de al lado, lejos del vehículo de emergencia detenido.","p":"Correcto. Baje la velocidad y cámbiese de carril."},"ref":{"doc":"HI","page":29}},{"id":"hi-017","scope":"HI","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Hawaii, which of these stopped vehicles with flashing lights is also covered by the move over law?","o":["A parked delivery van with no lights","A tow truck","A bus at a bus stop","A taxi waiting for a rider"],"h1":"Think of a truck that helps cars that break down.","h2":"Hawaii's move over law covers tow trucks as well as police, fire, ambulance and ocean safety vehicles.","p":"Right. Tow trucks are covered too."},"es":{"q":"En Hawái, ¿cuál de estos vehículos detenidos con luces intermitentes también está cubierto por la ley para moverse de carril?","o":["Una camioneta de reparto estacionada sin luces","Una grúa","Un autobús en la parada","Un taxi esperando a un pasajero"],"h1":"Piense en un camión que ayuda a los carros que se descomponen.","h2":"La ley de Hawái para moverse de carril cubre las grúas, además de los vehículos de policía, bomberos, ambulancia y seguridad en el océano.","p":"Correcto. Las grúas también están cubiertas."},"ref":{"doc":"HI","page":null}},{"id":"hi-018","scope":"HI","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Hawaii, what is the lowest blood alcohol level that is against the law for a driver under 21?","o":["0.08 percent","0.05 percent","0.02 percent","0.10 percent"],"h1":"Hawaii calls this rule zero tolerance.","h2":"In Hawaii it is against the law for a driver under 21 to drive with a blood alcohol level of 0.02 percent or more.","p":"Right. Under 21, the limit is 0.02 percent."},"es":{"q":"En Hawái, ¿cuál es el nivel más bajo de alcohol en la sangre que es ilegal para un conductor menor de 21 años?","o":["0.08 por ciento","0.05 por ciento","0.02 por ciento","0.10 por ciento"],"h1":"En Hawái esta regla se llama tolerancia cero.","h2":"En Hawái es ilegal que un conductor menor de 21 años maneje con un nivel de alcohol en la sangre de 0.02 por ciento o más.","p":"Correcto. Para menores de 21, el límite es 0.02 por ciento."},"ref":{"doc":"HI","page":56}},{"id":"hi-020","scope":"HI","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Hawaii, on a road split by a barrier, which drivers must stop for a school bus with flashing red lights?","o":["Only the driver right behind the bus","No one, because the road is divided","Only drivers in the left lane","Drivers in all lanes on the same side as the bus"],"h1":"The barrier protects the other side, not your side.","h2":"In Hawaii, when a road is divided by a barrier, drivers in every lane on the same side as the stopped school bus must stop.","p":"Right. Every lane on the bus's side stops."},"es":{"q":"En Hawái, en una vía dividida por una barrera, ¿qué conductores deben detenerse ante un autobús escolar con luces rojas intermitentes?","o":["Solo el conductor justo detrás del autobús","Nadie, porque la vía está dividida","Solo los del carril izquierdo","Los de todos los carriles del mismo lado del autobús"],"h1":"La barrera protege el otro lado, no su lado.","h2":"En Hawái, cuando una vía está dividida por una barrera, los conductores de todos los carriles del mismo lado del autobús escolar detenido deben detenerse.","p":"Correcto. Todos los carriles del lado del autobús se detienen."},"ref":{"doc":"HI","page":null}},{"id":"ia-001","scope":"IA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Iowa, what is the youngest age to get an instruction permit?","o":["13 years old","14 years old","15 years old","16 years old"],"h1":"Iowa lets teens start practicing earlier than many states.","h2":"In Iowa you can get an instruction permit at 14 years old, with a parent or guardian's consent.","p":"Right. Iowa instruction permits start at 14."},"es":{"q":"En Iowa, ¿cuál es la edad mínima para obtener un permiso de instrucción?","o":["13 años","14 años","15 años","16 años"],"h1":"Iowa permite empezar a practicar antes que muchos estados.","h2":"En Iowa usted puede obtener un permiso de instrucción a los 14 años, con el consentimiento de su padre, madre o tutor.","p":"Correcto. En Iowa el permiso de instrucción empieza a los 14."},"ref":{"doc":"IA","page":null}},{"id":"ia-002","scope":"IA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Iowa, how many hours of supervised driving must a teen complete before an intermediate license?","o":["10 hours","50 hours","20 hours","40 hours"],"h1":"It is a smaller number than in most states.","h2":"An Iowa teen must complete 20 hours of supervised driving before getting an intermediate license, and driver education driving counts toward them.","p":"Right. Iowa asks for 20 supervised hours."},"es":{"q":"En Iowa, ¿cuántas horas de manejo supervisado debe completar un adolescente antes de la licencia intermedia?","o":["10 horas","50 horas","20 horas","40 horas"],"h1":"Es un número más bajo que en la mayoría de los estados.","h2":"Un adolescente en Iowa debe completar 20 horas de manejo supervisado antes de obtener la licencia intermedia, y el manejo en el curso de educación vial cuenta.","p":"Correcto. Iowa pide 20 horas supervisadas."},"ref":{"doc":"IA","page":null}},{"id":"ia-003","scope":"IA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Iowa, how many of the supervised practice hours must be between sunset and sunrise?","o":["At least 2 hours","At least 5 hours","At least 10 hours","None are required"],"h1":"It is a small part of the total.","h2":"At least 2 of the 20 supervised hours in Iowa must be driven between sunset and sunrise.","p":"Right. Two hours must be after dark."},"es":{"q":"En Iowa, ¿cuántas de las horas de práctica supervisada deben ser entre la puesta y la salida del sol?","o":["Por lo menos 2 horas","Por lo menos 5 horas","Por lo menos 10 horas","No se exige ninguna"],"h1":"Es una parte pequeña del total.","h2":"Por lo menos 2 de las 20 horas supervisadas en Iowa deben manejarse entre la puesta y la salida del sol.","p":"Correcto. Dos horas deben ser de noche."},"ref":{"doc":"IA","page":null}},{"id":"ia-004","scope":"IA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Iowa, how long must a teen hold an instruction permit before getting an intermediate license?","o":["3 months","6 months","9 months","12 months"],"h1":"It is a full year of practice.","h2":"An Iowa teen must hold a valid instruction permit for a total of 12 months before applying for an intermediate license.","p":"Right. Twelve months with the permit."},"es":{"q":"En Iowa, ¿cuánto tiempo debe tener un adolescente el permiso de instrucción antes de obtener la licencia intermedia?","o":["3 meses","6 meses","9 meses","12 meses"],"h1":"Es un año completo de práctica.","h2":"Un adolescente en Iowa debe tener un permiso de instrucción válido por un total de 12 meses antes de solicitar la licencia intermedia.","p":"Correcto. Doce meses con el permiso."},"ref":{"doc":"IA","page":null}},{"id":"ia-005","scope":"IA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Iowa, what driving record does a teen need right before applying for an intermediate license?","o":["No record is checked","A clean record for at least 6 months in a row","A clean record for at least 1 month","No more than three tickets"],"h1":"The state looks at the last half year.","h2":"An Iowa teen needs a clean driving record for at least 6 months in a row right before applying for an intermediate license.","p":"Right. Six clean months in a row."},"es":{"q":"En Iowa, ¿qué historial de manejo necesita un adolescente justo antes de solicitar la licencia intermedia?","o":["No se revisa el historial","Un historial limpio por lo menos 6 meses seguidos","Un historial limpio por lo menos 1 mes","No más de tres multas"],"h1":"El estado revisa el último medio año.","h2":"Un adolescente en Iowa necesita un historial de manejo limpio por lo menos 6 meses seguidos justo antes de solicitar la licencia intermedia.","p":"Correcto. Seis meses seguidos sin problemas."},"ref":{"doc":"IA","page":null}},{"id":"ia-006","scope":"IA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Iowa, what is the youngest age for an intermediate license?","o":["15 years old","15 and a half","16 years old","17 years old"],"h1":"It comes two years after the first permit.","h2":"You must be at least 16 years old to get an intermediate license in Iowa.","p":"Right. The intermediate license starts at 16."},"es":{"q":"En Iowa, ¿cuál es la edad mínima para la licencia intermedia?","o":["15 años","15 años y medio","16 años","17 años"],"h1":"Llega dos años después del primer permiso.","h2":"Usted debe tener por lo menos 16 años para obtener la licencia intermedia en Iowa.","p":"Correcto. La licencia intermedia empieza a los 16."},"ref":{"doc":"IA","page":null}},{"id":"ia-007","scope":"IA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Iowa, during which hours may an intermediate license holder not drive without adult supervision?","o":["12:30 a.m. to 5 a.m.","11 p.m. to 5 a.m.","Midnight to 6 a.m.","9 p.m. to 6 a.m."],"h1":"The limit starts a little after midnight.","h2":"An Iowa intermediate license holder may not drive without adult supervision between 12:30 a.m. and 5 a.m., unless a waiver allows it.","p":"Right. 12:30 to 5 in the morning."},"es":{"q":"En Iowa, ¿en qué horario no puede manejar sin supervisión de un adulto quien tiene licencia intermedia?","o":["De 12:30 a.m. a 5 a.m.","De 11 p.m. a 5 a.m.","De medianoche a 6 a.m.","De 9 p.m. a 6 a.m."],"h1":"El límite empieza un poco después de la medianoche.","h2":"Quien tiene licencia intermedia en Iowa no puede manejar sin supervisión de un adulto entre las 12:30 a.m. y las 5 a.m., salvo que tenga una exención.","p":"Correcto. De 12:30 a 5 de la mañana."},"ref":{"doc":"IA","page":null}},{"id":"ia-008","scope":"IA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Iowa, how can an intermediate license holder legally drive alone after 12:30 a.m. for school or work?","o":["Show a school ID","Call a parent before driving","Drive only on city streets","Carry a waiver signed by a parent or guardian"],"h1":"A parent fills out a form for this.","h2":"A parent, guardian or custodian can sign a waiver for school or work driving, and the teen must carry it in the vehicle.","p":"Right. A signed waiver in the vehicle."},"es":{"q":"En Iowa, ¿cómo puede quien tiene licencia intermedia manejar solo después de las 12:30 a.m. por la escuela o el trabajo?","o":["Mostrar su credencial escolar","Llamar a un padre antes de manejar","Manejar solo por calles de la ciudad","Llevar una exención firmada por un padre o tutor"],"h1":"Un padre llena un formulario para esto.","h2":"Un padre, tutor o custodio puede firmar una exención para manejar por la escuela o el trabajo, y el adolescente debe llevarla en el vehículo.","p":"Correcto. Una exención firmada dentro del vehículo."},"ref":{"doc":"IA","page":null}},{"id":"ia-009","scope":"IA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Iowa, during the first 6 months with an intermediate license, how many unrelated passengers under 18 may ride along when no adult supervises?","o":["None","One","Two","Three"],"h1":"Brothers, sisters and household children do not count.","h2":"During the first 6 months, an Iowa intermediate license holder may carry only one unrelated passenger under 18, unless a parent allows more.","p":"Right. Only one unrelated minor."},"es":{"q":"En Iowa, durante los primeros 6 meses con licencia intermedia, ¿cuántos pasajeros menores de 18 años que no son familiares pueden ir con usted sin un adulto supervisando?","o":["Ninguno","Uno","Dos","Tres"],"h1":"Los hermanos y los niños que viven en su casa no cuentan.","h2":"Durante los primeros 6 meses, quien tiene licencia intermedia en Iowa puede llevar solo un pasajero menor de 18 años que no sea familiar, salvo que un padre permita más.","p":"Correcto. Solo un menor que no es familiar."},"ref":{"doc":"IA","page":null}},{"id":"ia-010","scope":"IA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Iowa, what is the youngest age for a minor school license?","o":["14 years old","15 years old","14 and a half","16 years old"],"h1":"It is halfway between two birthdays.","h2":"You can get an Iowa minor school license at 14 and a half, after driver education and six clean months with a permit.","p":"Right. Fourteen and a half."},"es":{"q":"En Iowa, ¿cuál es la edad mínima para la licencia escolar de menor?","o":["14 años","15 años","14 años y medio","16 años"],"h1":"Está a la mitad entre dos cumpleaños.","h2":"Usted puede obtener la licencia escolar de menor en Iowa a los 14 años y medio, después de la educación vial y seis meses limpios con el permiso.","p":"Correcto. Catorce años y medio."},"ref":{"doc":"IA","page":null}},{"id":"ia-011","scope":"IA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Iowa, with a minor school license (special minor's restricted license), how far may a teen drive alone to work?","o":["25 miles or less","Any distance","5 miles or less","100 miles or less"],"h1":"The trip to work has a distance limit.","h2":"With an Iowa special minor's restricted license, a teen may drive alone to work only when the trip is 25 miles or less.","p":"Right. The drive to work must be 25 miles or less."},"es":{"q":"En Iowa, con una licencia escolar para menores (licencia restringida especial para menores), ¿qué distancia puede manejar solo un adolescente para ir al trabajo?","o":["25 millas o menos","Cualquier distancia","5 millas o menos","100 millas o menos"],"h1":"El viaje al trabajo tiene un límite de distancia.","h2":"Con una licencia restringida especial para menores de Iowa, un adolescente puede manejar solo al trabajo únicamente si el viaje es de 25 millas o menos.","p":"Correcto. El viaje al trabajo debe ser de 25 millas o menos."},"ref":{"doc":"IA","page":null}},{"id":"ia-012","scope":"IA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Iowa, how old must a family member be to supervise a teen with an instruction permit?","o":["16 or older","18 or older","25 or older","21 or older"],"h1":"The same age as the legal drinking age.","h2":"In Iowa, an immediate family member who supervises a permit driver must be licensed and at least 21 years old.","p":"Right. A family member must be 21 or older."},"es":{"q":"En Iowa, ¿qué edad debe tener un familiar para supervisar a un adolescente con permiso de instrucción?","o":["16 años o más","18 años o más","25 años o más","21 años o más"],"h1":"Es la misma edad para tomar alcohol legalmente.","h2":"En Iowa, un familiar directo que supervisa a un conductor con permiso debe tener licencia y por lo menos 21 años.","p":"Correcto. El familiar debe tener 21 años o más."},"ref":{"doc":"IA","page":null}},{"id":"ia-013","scope":"IA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Iowa, a supervisor who is not family needs the parent's written permission. How old must that person be?","o":["18 or older","21 or older","25 or older","30 or older"],"h1":"It is older than for a family member.","h2":"In Iowa, a supervisor who is not family must be licensed, at least 25 years old and have written permission from the parent or guardian.","p":"Right. A non-family supervisor must be 25 or older."},"es":{"q":"En Iowa, un supervisor que no es familiar necesita permiso escrito del padre. ¿Qué edad debe tener esa persona?","o":["18 años o más","21 años o más","25 años o más","30 años o más"],"h1":"Es mayor que para un familiar.","h2":"En Iowa, un supervisor que no es familiar debe tener licencia, por lo menos 25 años y permiso escrito del padre o tutor.","p":"Correcto. Un supervisor que no es familiar debe tener 25 años o más."},"ref":{"doc":"IA","page":null}},{"id":"ia-014","scope":"IA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Iowa, what blood alcohol level is illegal for a driver under 21?","o":["0.08 or more","0.02 or more","0.05 or more","0.10 or more"],"h1":"It is much lower than the adult limit.","h2":"In Iowa a driver under 21 breaks the law with a blood alcohol level of 0.02 or more, and can lose their license.","p":"Right. Under 21, the limit is 0.02."},"es":{"q":"En Iowa, ¿qué nivel de alcohol en la sangre es ilegal para un conductor menor de 21 años?","o":["0.08 o más","0.02 o más","0.05 o más","0.10 o más"],"h1":"Es mucho más bajo que el límite para adultos.","h2":"En Iowa un conductor menor de 21 años viola la ley con un nivel de alcohol en la sangre de 0.02 o más, y puede perder su licencia.","p":"Correcto. Para menores de 21, el límite es 0.02."},"ref":{"doc":"IA","page":37}},{"id":"ia-015","scope":"IA","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Iowa, since July 1, 2025, how may an adult driver use a phone while driving?","o":["Any way, if driving slowly","Holding it, for calls only","Texting at red lights only","Only hands-free or by voice"],"h1":"The law is called the hands-free law.","h2":"Since July 1, 2025, Iowa drivers may not hold a phone while driving, and may use it only hands-free or by voice.","p":"Right. Hands-free only."},"es":{"q":"En Iowa, desde el 1 de julio de 2025, ¿cómo puede un conductor adulto usar el teléfono mientras maneja?","o":["De cualquier forma, si maneja despacio","Sosteniéndolo, solo para llamadas","Escribiendo mensajes solo en luz roja","Solo con manos libres o por voz"],"h1":"La ley se llama ley de manos libres.","h2":"Desde el 1 de julio de 2025, en Iowa los conductores no pueden sostener el teléfono mientras manejan, y solo pueden usarlo con manos libres o por voz.","p":"Correcto. Solo manos libres."},"ref":{"doc":"IA","page":36}},{"id":"ia-016","scope":"IA","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Iowa, may a teen with an intermediate license use a phone or tablet while driving?","o":["No, only equipment built into the vehicle is allowed","Yes, if it is hands-free","Yes, for music only","Yes, at red lights"],"h1":"Even hands-free devices are not allowed for this license.","h2":"An Iowa intermediate license holder may not use a phone, tablet or other electronic device while driving; only equipment permanently installed in the vehicle is allowed.","p":"Right. No phones or tablets for teen drivers."},"es":{"q":"En Iowa, ¿puede un adolescente con licencia intermedia usar un teléfono o tableta mientras maneja?","o":["No, solo el equipo instalado en el vehículo","Sí, si es manos libres","Sí, solo para música","Sí, en luz roja"],"h1":"Ni siquiera los aparatos de manos libres están permitidos con esta licencia.","h2":"Quien tiene licencia intermedia en Iowa no puede usar teléfono, tableta ni otro aparato electrónico mientras maneja; solo se permite el equipo instalado de forma permanente en el vehículo.","p":"Correcto. Nada de teléfonos ni tabletas para conductores adolescentes."},"ref":{"doc":"IA","page":36}},{"id":"ia-017","scope":"IA","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Iowa, what must you do when you approach any stopped vehicle on the roadside with its hazard lights on?","o":["Honk and keep your speed","Stop behind it","Change lanes or slow down","Nothing; the law covers only police cars"],"h1":"Iowa's law is named for these two actions.","h2":"In Iowa you must change lanes or slow down when you approach any stopped vehicle with its hazard lights flashing, not only emergency vehicles.","p":"Right. Move over or slow down."},"es":{"q":"En Iowa, ¿qué debe hacer al acercarse a cualquier vehículo detenido al lado del camino con las luces intermitentes de emergencia encendidas?","o":["Tocar la bocina y seguir a la misma velocidad","Detenerse detrás de él","Cambiar de carril o reducir la velocidad","Nada; la ley solo aplica a patrullas"],"h1":"La ley de Iowa lleva el nombre de estas dos acciones.","h2":"En Iowa usted debe cambiar de carril o reducir la velocidad al acercarse a cualquier vehículo detenido con las luces intermitentes encendidas, no solo a vehículos de emergencia.","p":"Correcto. Cambiar de carril o bajar la velocidad."},"ref":{"doc":"IA","page":22}},{"id":"ia-018","scope":"IA","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Iowa, a school bus stops with its stop arm out on a road with two or more lanes in each direction. You come from the opposite direction. What must you do?","o":["Stop until the arm is pulled in","You do not have to stop, but watch for children","Stop only if children are crossing","Stop and wait for the driver's signal"],"h1":"The road is wide enough to separate the two directions.","h2":"On an Iowa road with two or more lanes in each direction, traffic coming from the opposite direction does not have to stop for a school bus, but should still watch for children.","p":"Right. Oncoming traffic on a wide road may pass with care."},"es":{"q":"En Iowa, un autobús escolar se detiene con el brazo de alto extendido en un camino con dos o más carriles en cada sentido. Usted viene en sentido contrario. ¿Qué debe hacer?","o":["Detenerse hasta que recojan el brazo","No tiene que detenerse, pero esté atento a los niños","Detenerse solo si hay niños cruzando","Detenerse y esperar la señal del chofer"],"h1":"El camino es lo bastante ancho para separar los dos sentidos.","h2":"En un camino de Iowa con dos o más carriles en cada sentido, el tráfico que viene en sentido contrario no tiene que detenerse por un autobús escolar, pero debe estar atento a los niños.","p":"Correcto. En un camino ancho, el tráfico contrario puede pasar con cuidado."},"ref":{"doc":"IA","page":20}},{"id":"ia-019","scope":"IA","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Iowa, on a road with three lanes or fewer, who must stop for a school bus with flashing red lights?","o":["Only drivers behind the bus","Only drivers facing the bus","Only drivers in the turning lane","Every vehicle, from both directions"],"h1":"On a narrow road, nobody gets past.","h2":"On an Iowa road with three lanes or fewer, every vehicle from both directions, including turning lanes, must stop for a school bus with flashing red lights.","p":"Right. Everyone stops on a narrow road."},"es":{"q":"En Iowa, en un camino de tres carriles o menos, ¿quién debe detenerse ante un autobús escolar con luces rojas intermitentes?","o":["Solo los conductores detrás del autobús","Solo los conductores de frente al autobús","Solo los conductores en el carril de giro","Todos los vehículos, de los dos sentidos"],"h1":"En un camino angosto, nadie pasa.","h2":"En un camino de Iowa de tres carriles o menos, todos los vehículos de los dos sentidos, incluso los del carril de giro, deben detenerse ante un autobús escolar con luces rojas intermitentes.","p":"Correcto. En un camino angosto todos se detienen."},"ref":{"doc":"IA","page":20}},{"id":"ia-020","scope":"IA","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Iowa, failing to stop for a school bus when required can cost you your license for up to how long?","o":["180 days","7 days","30 days","5 years"],"h1":"It is about half a year.","h2":"In Iowa, not stopping for a school bus when the law requires it can lead to a license suspension of up to 180 days.","p":"Right. Up to 180 days."},"es":{"q":"En Iowa, ¿hasta por cuánto tiempo le pueden suspender la licencia por no detenerse ante un autobús escolar cuando la ley lo exige?","o":["180 días","7 días","30 días","5 años"],"h1":"Es más o menos medio año.","h2":"En Iowa, no detenerse ante un autobús escolar cuando la ley lo exige puede causar una suspensión de la licencia de hasta 180 días.","p":"Correcto. Hasta 180 días."},"ref":{"doc":"IA","page":20}},{"id":"ia-021","scope":"IA","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Iowa, what is the highest posted speed limit on rural interstate highways?","o":["60 mph","65 mph","70 mph","75 mph"],"h1":"Iowa's rural interstates are lower than some western states.","h2":"The highest posted speed limit in Iowa is 70 mph, on rural interstate highways.","p":"Right. 70 mph on rural interstates."},"es":{"q":"En Iowa, ¿cuál es el límite de velocidad más alto en las autopistas interestatales rurales?","o":["60 mph","65 mph","70 mph","75 mph"],"h1":"Las interestatales rurales de Iowa tienen un límite más bajo que algunos estados del oeste.","h2":"El límite de velocidad más alto en Iowa es de 70 millas por hora, en las autopistas interestatales rurales.","p":"Correcto. 70 mph en interestatales rurales."},"ref":{"doc":"IA","page":42}},{"id":"ia-022","scope":"IA","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Iowa, unless a sign says otherwise, what is the speed limit in a business district?","o":["15 mph","20 mph","30 mph","35 mph"],"h1":"Business districts are busy with people on foot.","h2":"Unless a sign shows a different limit, the speed limit in an Iowa business district is 20 mph.","p":"Right. 20 mph in a business district."},"es":{"q":"En Iowa, si no hay una señal que diga otra cosa, ¿cuál es el límite de velocidad en una zona comercial?","o":["15 mph","20 mph","30 mph","35 mph"],"h1":"Las zonas comerciales tienen mucha gente a pie.","h2":"Si no hay una señal con otro límite, el límite de velocidad en una zona comercial de Iowa es de 20 millas por hora.","p":"Correcto. 20 mph en zona comercial."},"ref":{"doc":"IA","page":42}},{"id":"id-001","scope":"ID","cat":"licensing","sign":null,"c":2,"en":{"q":"In Idaho, how many questions are on the written knowledge test?","o":["20 questions","25 questions","40 questions","50 questions"],"h1":"It is more than 25 and fewer than 50.","h2":"The Idaho knowledge test has 40 questions, all taken from the driver's handbook.","p":"Right. The Idaho test has 40 questions."},"es":{"q":"En Idaho, ¿cuántas preguntas tiene el examen escrito de conocimientos?","o":["20 preguntas","25 preguntas","40 preguntas","50 preguntas"],"h1":"Son más de 25 y menos de 50.","h2":"El examen de conocimientos de Idaho tiene 40 preguntas, todas tomadas del manual del conductor.","p":"Correcto. El examen de Idaho tiene 40 preguntas."},"ref":{"doc":"ID","page":32}},{"id":"id-002","scope":"ID","cat":"licensing","sign":null,"c":0,"en":{"q":"In Idaho, how many questions can you miss on the knowledge test and still pass?","o":["Up to 6","Up to 2","Up to 10","Up to 12"],"h1":"You need a high score, about 85 percent.","h2":"On the Idaho knowledge test you can miss up to 6 of the 40 questions, so you need 34 right answers to pass.","p":"Well done. You can miss up to 6 questions."},"es":{"q":"En Idaho, ¿cuántas preguntas puede fallar en el examen de conocimientos y aun así aprobar?","o":["Hasta 6","Hasta 2","Hasta 10","Hasta 12"],"h1":"Se necesita una nota alta, de alrededor del 85 por ciento.","h2":"En el examen de conocimientos de Idaho usted puede fallar hasta 6 de las 40 preguntas, así que necesita 34 respuestas correctas para aprobar.","p":"Muy bien. Puede fallar hasta 6 preguntas."},"ref":{"doc":"ID","page":32}},{"id":"id-003","scope":"ID","cat":"licensing","sign":null,"c":1,"en":{"q":"In Idaho, how long must a teen hold the supervised instruction permit, at a minimum?","o":["3 months","6 months","9 months","12 months"],"h1":"It is half of a year.","h2":"An Idaho teen must hold the supervised instruction permit for at least six months without any violation.","p":"Right. The minimum is six months."},"es":{"q":"En Idaho, ¿por cuánto tiempo como mínimo debe un joven tener el permiso de instrucción supervisada?","o":["3 meses","6 meses","9 meses","12 meses"],"h1":"Es la mitad de un año.","h2":"Un joven en Idaho debe tener el permiso de instrucción supervisada por lo menos seis meses sin ninguna infracción.","p":"Correcto. El mínimo es de seis meses."},"ref":{"doc":"ID","page":19}},{"id":"id-004","scope":"ID","cat":"licensing","sign":null,"c":3,"en":{"q":"In Idaho, how old must the licensed driver beside a permit holder be?","o":["At least 16","At least 18","At least 25","At least 21"],"h1":"The helper must be old enough to buy alcohol legally.","h2":"In Idaho the supervising driver must hold a valid license, be at least 21 years old, and sit in the seat beside the permit holder.","p":"Correct. The supervisor must be 21 or older."},"es":{"q":"En Idaho, ¿qué edad debe tener el conductor con licencia que va al lado de quien tiene el permiso?","o":["Por lo menos 16","Por lo menos 18","Por lo menos 25","Por lo menos 21"],"h1":"El acompañante debe tener la edad para comprar alcohol legalmente.","h2":"En Idaho el conductor que supervisa debe tener licencia válida, por lo menos 21 años, y sentarse al lado de quien tiene el permiso.","p":"Correcto. El supervisor debe tener 21 años o más."},"ref":{"doc":"ID","page":19}},{"id":"id-005","scope":"ID","cat":"licensing","sign":null,"c":2,"en":{"q":"In Idaho, how many hours of supervised driving must a teen complete with the instruction permit?","o":["20 hours","30 hours","50 hours","100 hours"],"h1":"It is more than 30 hours.","h2":"An Idaho teen must complete at least 50 hours of supervised driving while holding the instruction permit.","p":"Right. Idaho requires 50 supervised hours."},"es":{"q":"En Idaho, ¿cuántas horas de manejo supervisado debe completar un joven con el permiso de instrucción?","o":["20 horas","30 horas","50 horas","100 horas"],"h1":"Son más de 30 horas.","h2":"Un joven en Idaho debe completar por lo menos 50 horas de manejo supervisado mientras tiene el permiso de instrucción.","p":"Correcto. Idaho exige 50 horas supervisadas."},"ref":{"doc":"ID","page":19}},{"id":"id-006","scope":"ID","cat":"licensing","sign":null,"c":0,"en":{"q":"In Idaho, how many of the supervised practice hours must be at night?","o":["10 hours","2 hours","5 hours","25 hours"],"h1":"It is a round number, smaller than 20.","h2":"At least 10 of the 50 supervised hours in Idaho must be driven at night.","p":"Correct. Ten of the hours must be at night."},"es":{"q":"En Idaho, ¿cuántas de las horas de práctica supervisada deben ser de noche?","o":["10 horas","2 horas","5 horas","25 horas"],"h1":"Es un número redondo, menor que 20.","h2":"En Idaho, por lo menos 10 de las 50 horas supervisadas deben ser de noche.","p":"Correcto. Diez de las horas deben ser de noche."},"ref":{"doc":"ID","page":19}},{"id":"id-007","scope":"ID","cat":"licensing","sign":null,"c":1,"en":{"q":"In Idaho, what happens if a teen with a supervised instruction permit gets a traffic conviction?","o":["Nothing changes","The permit is canceled and the six months start over","The teen pays a fine and keeps the same permit","The teen gets the license sooner"],"h1":"The violation-free period has to be earned again.","h2":"In Idaho a traffic conviction cancels the supervised instruction permit, and the six-month period starts over with a new permit.","p":"Right. The six months start again."},"es":{"q":"En Idaho, ¿qué pasa si un joven con permiso de instrucción supervisada recibe una condena de tránsito?","o":["No cambia nada","Se cancela el permiso y los seis meses empiezan de nuevo","El joven paga una multa y conserva el mismo permiso","El joven obtiene la licencia antes"],"h1":"El período sin infracciones se tiene que ganar otra vez.","h2":"En Idaho una condena de tránsito cancela el permiso de instrucción supervisada, y el período de seis meses empieza de nuevo con un permiso nuevo.","p":"Correcto. Los seis meses empiezan otra vez."},"ref":{"doc":"ID","page":19}},{"id":"id-008","scope":"ID","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Idaho, who must wear a seat belt while a teen drives with a supervised instruction permit?","o":["Only the driver","Only people in the front seat","Only children","Everyone in the vehicle"],"h1":"Think about every seat in the car.","h2":"While an Idaho teen drives on a supervised instruction permit, everyone in the vehicle must wear a seat belt.","p":"Correct. Everyone must be buckled."},"es":{"q":"En Idaho, ¿quién debe usar cinturón de seguridad mientras un joven maneja con permiso de instrucción supervisada?","o":["Solo el conductor","Solo las personas del asiento delantero","Solo los niños","Todas las personas en el vehículo"],"h1":"Piense en cada asiento del carro.","h2":"Mientras un joven en Idaho maneja con permiso de instrucción supervisada, todas las personas en el vehículo deben usar cinturón de seguridad.","p":"Correcto. Todos deben ir abrochados."},"ref":{"doc":"ID","page":19}},{"id":"id-009","scope":"ID","cat":"licensing","sign":null,"c":2,"en":{"q":"In Idaho, what must a teen have with them while driving on a supervised instruction permit?","o":["A school ID","A passport","The permit itself","A letter from a teacher"],"h1":"It is the document that allows the practice driving.","h2":"An Idaho teen must carry the supervised instruction permit while driving.","p":"Right. Keep the permit with you."},"es":{"q":"En Idaho, ¿qué debe llevar consigo un joven mientras maneja con permiso de instrucción supervisada?","o":["Su identificación escolar","Su pasaporte","El permiso mismo","Una carta de un maestro"],"h1":"Es el documento que le permite practicar.","h2":"Un joven en Idaho debe llevar consigo el permiso de instrucción supervisada mientras maneja.","p":"Correcto. Lleve el permiso con usted."},"ref":{"doc":"ID","page":null}},{"id":"id-010","scope":"ID","cat":"licensing","sign":null,"c":0,"en":{"q":"In Idaho, when may a licensed driver under 16 drive alone?","o":["Only during daylight hours","Only after sunset","Any time of day","Only on weekends"],"h1":"Night driving needs an adult in the front seat.","h2":"In Idaho a licensed driver under 16 may drive only in daylight hours, 5 a.m. to 10 p.m., unless a licensed person 21 or older sits in the front seat.","p":"Correct. Under 16 means daylight only."},"es":{"q":"En Idaho, ¿cuándo puede manejar solo un conductor con licencia menor de 16 años?","o":["Solo durante las horas de luz del día","Solo después de la puesta del sol","A cualquier hora","Solo los fines de semana"],"h1":"Para manejar de noche se necesita un adulto en el asiento delantero.","h2":"En Idaho un conductor con licencia menor de 16 años solo puede manejar en horas de luz del día, de 5 a.m. a 10 p.m., a menos que una persona con licencia de 21 años o más vaya en el asiento delantero.","p":"Correcto. Menor de 16 significa solo de día."},"ref":{"doc":"ID","page":16}},{"id":"id-011","scope":"ID","cat":"licensing","sign":null,"c":3,"en":{"q":"In Idaho, how are daylight hours defined for drivers under 16?","o":["From sunrise to sunset","From half an hour before sunrise to half an hour after sunset","From 6 a.m. to 6 p.m.","From 5 a.m. to 10 p.m."],"h1":"Idaho law sets clock times, not sunrise and sunset.","h2":"In Idaho, daylight hours for a licensed driver under 16 run from 5 a.m. to 10 p.m. local time.","p":"Right. Daylight hours are 5 a.m. to 10 p.m."},"es":{"q":"En Idaho, ¿cómo se definen las horas de luz del día para conductores menores de 16 años?","o":["Desde la salida hasta la puesta del sol","Desde media hora antes de la salida del sol hasta media hora después de la puesta del sol","De 6 a.m. a 6 p.m.","De 5 a.m. a 10 p.m."],"h1":"La ley de Idaho usa horas del reloj, no la salida y la puesta del sol.","h2":"En Idaho, las horas de luz del día para un conductor con licencia menor de 16 años van de 5 a.m. a 10 p.m., hora local.","p":"Correcto. Las horas de luz del día son de 5 a.m. a 10 p.m."},"ref":{"doc":"ID","page":16}},{"id":"id-012","scope":"ID","cat":"licensing","sign":null,"c":1,"en":{"q":"In Idaho, during the first six months of a license, how many passengers under 17 may a driver under 17 carry?","o":["None","One","Two","Three"],"h1":"The limit is the smallest number that is more than zero.","h2":"During the first six months, an Idaho driver under 17 may carry no more than one passenger under 17, not counting relatives.","p":"Correct. Only one passenger under 17."},"es":{"q":"En Idaho, durante los primeros seis meses de la licencia, ¿cuántos pasajeros menores de 17 años puede llevar un conductor menor de 17?","o":["Ninguno","Uno","Dos","Tres"],"h1":"El límite es el número más pequeño que es mayor que cero.","h2":"Durante los primeros seis meses, un conductor menor de 17 años en Idaho no puede llevar más de un pasajero menor de 17, sin contar a sus familiares.","p":"Correcto. Solo un pasajero menor de 17."},"ref":{"doc":"ID","page":16}},{"id":"id-013","scope":"ID","cat":"licensing","sign":null,"c":3,"en":{"q":"In Idaho, which passenger does not count toward the one-passenger limit for a new driver under 17?","o":["A classmate","A teammate","A neighbor","The driver's brother or sister"],"h1":"The rule makes an exception for family.","h2":"In Idaho the one-passenger limit does not apply to passengers related to the driver by blood, adoption or marriage, such as a brother or sister.","p":"Right. Family members do not count."},"es":{"q":"En Idaho, ¿qué pasajero no cuenta para el límite de un pasajero de un conductor nuevo menor de 17 años?","o":["Un compañero de clase","Un compañero de equipo","Un vecino","El hermano o la hermana del conductor"],"h1":"La regla hace una excepción para la familia.","h2":"En Idaho el límite de un pasajero no se aplica a los pasajeros que son familiares del conductor por sangre, adopción o matrimonio, como un hermano o una hermana.","p":"Correcto. Los familiares no cuentan."},"ref":{"doc":"ID","page":16}},{"id":"id-014","scope":"ID","cat":"licensing","sign":null,"c":2,"en":{"q":"In Idaho, who must complete a driver training program to get a driver's license?","o":["Everyone, at any age","Only drivers over 65","Anyone under 17","Only drivers from another state"],"h1":"It depends on how young the applicant is.","h2":"In Idaho anyone under 17 must complete and pass an approved driver training program to get a driver's license.","p":"Correct. Under 17 needs driver training."},"es":{"q":"En Idaho, ¿quién debe completar un programa de educación vial para obtener la licencia de manejo?","o":["Todos, a cualquier edad","Solo los mayores de 65","Cualquier persona menor de 17 años","Solo los conductores de otro estado"],"h1":"Depende de qué tan joven sea la persona.","h2":"En Idaho toda persona menor de 17 años debe completar y aprobar un programa de educación vial aprobado para obtener la licencia de manejo.","p":"Correcto. Menor de 17 necesita educación vial."},"ref":{"doc":"ID","page":19}},{"id":"id-015","scope":"ID","cat":"licensing","sign":null,"c":0,"en":{"q":"In Idaho, how many hours of classroom instruction are in an approved driver training program?","o":["30 hours","6 hours","12 hours","50 hours"],"h1":"It is five times the hours of behind-the-wheel driving, which are 6.","h2":"An approved Idaho driver training program has 30 hours of classroom instruction, plus 6 hours of observation and 6 hours behind the wheel.","p":"Right. Thirty hours in the classroom."},"es":{"q":"En Idaho, ¿cuántas horas de clase en el aula tiene un programa de educación vial aprobado?","o":["30 horas","6 horas","12 horas","50 horas"],"h1":"Es cinco veces las horas de manejo con el instructor, que son 6.","h2":"Un programa de educación vial aprobado en Idaho tiene 30 horas de clase en el aula, además de 6 horas de observación y 6 horas al volante.","p":"Correcto. Treinta horas en el aula."},"ref":{"doc":"ID","page":19}},{"id":"id-016","scope":"ID","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Idaho, when may a driver hold a phone in their hand to use it?","o":["While stopped at a red light","While stopped at a stop sign","When parked out of the travel lanes","While driving slowly"],"h1":"Being stopped in traffic is not enough.","h2":"Idaho's hands-free law covers you even at a red light or stop sign; you may hold the phone only when the vehicle is stopped outside the travel lanes, or in an emergency.","p":"Correct. Park out of traffic first."},"es":{"q":"En Idaho, ¿cuándo puede un conductor tener el teléfono en la mano para usarlo?","o":["Cuando está detenido en un semáforo en rojo","Cuando está detenido en una señal de alto","Cuando está estacionado fuera de los carriles de circulación","Cuando maneja despacio"],"h1":"Estar detenido en el tráfico no es suficiente.","h2":"La ley de manos libres de Idaho se aplica incluso en un semáforo en rojo o en una señal de alto; usted solo puede tener el teléfono en la mano cuando el vehículo está detenido fuera de los carriles de circulación, o en una emergencia.","p":"Correcto. Primero estaciónese fuera del tráfico."},"ref":{"doc":"ID","page":null}},{"id":"id-017","scope":"ID","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Idaho, how may a driver start a phone call while driving?","o":["By typing the full number","With one touch or a voice command","By holding the phone to the ear","Calls are never allowed"],"h1":"The law allows the smallest possible action.","h2":"Idaho's hands-free law lets a driver start or answer a call with one touch or a voice command.","p":"Right. One touch or your voice."},"es":{"q":"En Idaho, ¿cómo puede un conductor hacer una llamada mientras maneja?","o":["Marcando el número completo","Con un solo toque o un comando de voz","Sosteniendo el teléfono junto al oído","Las llamadas nunca se permiten"],"h1":"La ley permite la acción más pequeña posible.","h2":"La ley de manos libres de Idaho permite hacer o contestar una llamada con un solo toque o con un comando de voz.","p":"Correcto. Un toque o su voz."},"ref":{"doc":"ID","page":null}},{"id":"id-018","scope":"ID","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Idaho, what is the fine for a first hands-free law violation, before court costs?","o":["$75","$25","$300","$1,000"],"h1":"The fine doubles for a second offense, to $150.","h2":"A first violation of Idaho's hands-free law is a $75 fine, plus court costs.","p":"Correct. The first fine is $75."},"es":{"q":"En Idaho, ¿cuál es la multa por una primera infracción de la ley de manos libres, sin contar los costos del tribunal?","o":["$75","$25","$300","$1,000"],"h1":"La multa se duplica en la segunda infracción, a $150.","h2":"Una primera infracción de la ley de manos libres en Idaho tiene una multa de $75, más los costos del tribunal.","p":"Correcto. La primera multa es de $75."},"ref":{"doc":"ID","page":null}},{"id":"id-019","scope":"ID","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Idaho, which stopped vehicle with flashing lights is covered by the Move Over law?","o":["Only police cars","Only ambulances","Only fire trucks","Tow trucks and highway incident response vehicles too"],"h1":"Since 2019 the law protects more than just emergency vehicles.","h2":"Idaho's Move Over law covers police and emergency vehicles, and since 2019 also tow trucks and highway incident response vehicles.","p":"Right. Tow trucks are covered too."},"es":{"q":"En Idaho, ¿qué vehículo detenido con luces intermitentes está cubierto por la ley Move Over?","o":["Solo los carros de policía","Solo las ambulancias","Solo los camiones de bomberos","También las grúas y los vehículos de respuesta a incidentes en la carretera"],"h1":"Desde 2019 la ley protege a más que solo los vehículos de emergencia.","h2":"La ley Move Over de Idaho cubre a la policía y los vehículos de emergencia, y desde 2019 también a las grúas y los vehículos de respuesta a incidentes en la carretera.","p":"Correcto. Las grúas también están cubiertas."},"ref":{"doc":"ID","page":95}},{"id":"id-020","scope":"ID","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Idaho, what blood alcohol level is illegal for a driver under 21?","o":["0.08 or more","0.02 or more","0.05 or more","0.10 or more"],"h1":"It is far lower than the adult limit of 0.08.","h2":"In Idaho a driver under 21 breaks the law with a blood alcohol level of 0.02 or more.","p":"Correct. The limit under 21 is 0.02."},"es":{"q":"En Idaho, ¿qué nivel de alcohol en la sangre es ilegal para un conductor menor de 21 años?","o":["0.08 o más","0.02 o más","0.05 o más","0.10 o más"],"h1":"Es mucho más bajo que el límite para adultos, que es 0.08.","h2":"En Idaho un conductor menor de 21 años viola la ley con un nivel de alcohol en la sangre de 0.02 o más.","p":"Correcto. El límite para menores de 21 es 0.02."},"ref":{"doc":"ID","page":131}},{"id":"id-021","scope":"ID","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Idaho, a driver under 21 is convicted for the first time of driving with an alcohol level of 0.02 or more but under 0.08. How long does the court suspend the license?","o":["A warning only","30 days","One year","Two weeks"],"h1":"It is a long time, a full twelve months.","h2":"In Idaho a first conviction for a driver under 21 with an alcohol level from 0.02 to under 0.08 brings a one-year license suspension, and the first 90 days allow no driving at all.","p":"Right. The suspension is one year."},"es":{"q":"En Idaho, un conductor menor de 21 años es condenado por primera vez por manejar con un nivel de alcohol de 0.02 o más, pero menor de 0.08. ¿Por cuánto tiempo suspende la licencia el tribunal?","o":["Solo una advertencia","30 días","Un año","Dos semanas"],"h1":"Es mucho tiempo, doce meses completos.","h2":"En Idaho, una primera condena de un conductor menor de 21 años con un nivel de alcohol de 0.02 a menos de 0.08 trae una suspensión de licencia de un año, y en los primeros 90 días no puede manejar de ninguna manera.","p":"Correcto. La suspensión es de un año."},"ref":{"doc":"ID","page":null}},{"id":"il-003","scope":"IL","cat":"licensing","sign":null,"c":1,"en":{"q":"In Illinois, what is the youngest age to take the written test for an instruction permit?","o":["14 years old","15 years old","16 years old","17 years old"],"h1":"It is one year before the usual age for a first license.","h2":"In Illinois you can take the written test for an instruction permit at 15 years old.","p":"Right. In Illinois you can start at 15."},"es":{"q":"En Illinois, ¿cuál es la edad mínima para presentar el examen escrito del permiso de aprendiz?","o":["14 años","15 años","16 años","17 años"],"h1":"Es un año antes de la edad habitual para la primera licencia.","h2":"En Illinois usted puede presentar el examen escrito del permiso de aprendiz a los 15 años.","p":"Correcto. En Illinois puede empezar a los 15."},"ref":{"doc":"IL","page":16}},{"id":"il-004","scope":"IL","cat":"licensing","sign":null,"c":3,"en":{"q":"In Illinois, how long must a driver under 18 hold the instruction permit before getting a license?","o":["3 months","6 months","12 months","9 months"],"h1":"It is longer than half a year but less than a full year.","h2":"An Illinois driver under 18 must hold the instruction permit for at least nine months before moving to a license.","p":"Right. The Illinois permit must be held for nine months."},"es":{"q":"En Illinois, ¿cuánto tiempo debe tener el permiso de aprendiz un conductor menor de 18 años antes de obtener la licencia?","o":["3 meses","6 meses","12 meses","9 meses"],"h1":"Es más de medio año pero menos de un año completo.","h2":"Un conductor de Illinois menor de 18 años debe tener el permiso de aprendiz por lo menos nueve meses antes de pasar a la licencia.","p":"Correcto. En Illinois el permiso se debe tener nueve meses."},"ref":{"doc":"IL","page":16}},{"id":"il-005","scope":"IL","cat":"licensing","sign":null,"c":2,"en":{"q":"In Illinois, what happens to the nine-month permit period if the permit holder gets a moving violation?","o":["Nothing changes","The permit becomes a license early","A new nine-month wait begins","The holder only pays a fine"],"h1":"The violation sets you back, not forward.","h2":"In Illinois, a moving violation conviction during the permit phase means a new nine-month wait before you can apply for a license.","p":"Right. A violation means a new nine-month wait."},"es":{"q":"En Illinois, ¿qué pasa con el periodo de nueve meses del permiso si el titular recibe una infracción de tránsito en movimiento?","o":["No cambia nada","El permiso se convierte antes en licencia","Empieza una nueva espera de nueve meses","El titular solo paga una multa"],"h1":"La infracción lo hace retroceder, no avanzar.","h2":"En Illinois, una condena por infracción en movimiento durante la etapa del permiso significa una nueva espera de nueve meses antes de poder solicitar la licencia.","p":"Correcto. Una infracción significa una nueva espera de nueve meses."},"ref":{"doc":"IL","page":null}},{"id":"il-006","scope":"IL","cat":"licensing","sign":null,"c":1,"en":{"q":"In Illinois, how many hours of supervised practice must a driver under 18 complete with the permit?","o":["30 hours","50 hours","40 hours","100 hours"],"h1":"It is half of one hundred.","h2":"An Illinois driver under 18 must complete at least 50 hours of supervised practice, including 10 hours at night.","p":"Right. Illinois requires 50 practice hours."},"es":{"q":"En Illinois, ¿cuántas horas de práctica supervisada debe completar con el permiso un conductor menor de 18 años?","o":["30 horas","50 horas","40 horas","100 horas"],"h1":"Es la mitad de cien.","h2":"Un conductor de Illinois menor de 18 años debe completar por lo menos 50 horas de práctica supervisada, de las cuales 10 son de noche.","p":"Correcto. Illinois exige 50 horas de práctica."},"ref":{"doc":"IL","page":16}},{"id":"il-007","scope":"IL","cat":"licensing","sign":null,"c":0,"en":{"q":"In Illinois, how many of the 50 supervised practice hours must be at night?","o":["10 hours","5 hours","20 hours","25 hours"],"h1":"It is one fifth of the total.","h2":"At least 10 of the 50 supervised practice hours in Illinois must be done at night.","p":"Right. Ten hours must be at night."},"es":{"q":"En Illinois, ¿cuántas de las 50 horas de práctica supervisada deben ser de noche?","o":["10 horas","5 horas","20 horas","25 horas"],"h1":"Es la quinta parte del total.","h2":"Por lo menos 10 de las 50 horas de práctica supervisada en Illinois deben hacerse de noche.","p":"Correcto. Diez horas deben ser de noche."},"ref":{"doc":"IL","page":16}},{"id":"il-008","scope":"IL","cat":"licensing","sign":null,"c":3,"en":{"q":"In Illinois, who may supervise a permit holder during practice?","o":["Any licensed driver 16 or older","Any licensed driver 18 or older","Only a driving instructor","A parent or a licensed adult 21 or older"],"h1":"The supervisor must be old enough to drink legally.","h2":"In Illinois a permit holder must practice with a parent or a licensed adult who is at least 21 years old.","p":"Right. The supervisor must be a parent or a licensed adult 21 or older."},"es":{"q":"En Illinois, ¿quién puede supervisar a un conductor con permiso durante la práctica?","o":["Cualquier conductor con licencia de 16 años o más","Cualquier conductor con licencia de 18 años o más","Solo un instructor de manejo","Un padre o un adulto con licencia de 21 años o más"],"h1":"El supervisor debe tener edad para tomar alcohol legalmente.","h2":"En Illinois un conductor con permiso debe practicar con un padre o con un adulto con licencia que tenga por lo menos 21 años.","p":"Correcto. El supervisor debe ser un padre o un adulto con licencia de 21 años o más."},"ref":{"doc":"IL","page":16}},{"id":"il-009","scope":"IL","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Illinois, may a driver under 19 with a permit or graduated license use a hands-free phone while driving?","o":["Yes, hands-free is always allowed","Yes, but only on highways","No, except to call for help in an emergency","Yes, if a parent is in the car"],"h1":"The rule for young drivers is stricter than for adults.","h2":"An Illinois driver under 19 with a permit or graduated license may not use any phone while driving, hands-free included, except to report an emergency.","p":"Right. Young drivers may use a phone only in an emergency."},"es":{"q":"En Illinois, ¿puede un conductor menor de 19 años con permiso o licencia gradual usar un teléfono manos libres mientras maneja?","o":["Sí, el manos libres siempre está permitido","Sí, pero solo en autopistas","No, excepto para pedir ayuda en una emergencia","Sí, si va un padre en el carro"],"h1":"La regla para conductores jóvenes es más estricta que para los adultos.","h2":"Un conductor de Illinois menor de 19 años con permiso o licencia gradual no puede usar ningún teléfono mientras maneja, ni siquiera manos libres, excepto para reportar una emergencia.","p":"Correcto. Los conductores jóvenes solo pueden usar el teléfono en una emergencia."},"ref":{"doc":"IL","page":18}},{"id":"il-010","scope":"IL","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Illinois, what kind of phone use is banned for all drivers while driving?","o":["Hands-free calls","Holding the phone in your hand","Voice commands","Listening to music through the car"],"h1":"Think about where the phone is.","h2":"Illinois bans all drivers from using a hand-held phone while driving. Drivers 19 and older may still use a hands-free phone.","p":"Right. Hand-held phone use is banned for every Illinois driver."},"es":{"q":"En Illinois, ¿qué uso del teléfono está prohibido para todos los conductores mientras manejan?","o":["Llamadas con manos libres","Sostener el teléfono en la mano","Comandos de voz","Escuchar música por el sistema del carro"],"h1":"Piense en dónde está el teléfono.","h2":"Illinois prohíbe a todos los conductores usar el teléfono en la mano mientras manejan. Los conductores de 19 años o más todavía pueden usar un teléfono manos libres.","p":"Correcto. Usar el teléfono en la mano está prohibido para todos en Illinois."},"ref":{"doc":"IL","page":22}},{"id":"il-011","scope":"IL","cat":"licensing","sign":null,"c":3,"en":{"q":"In Illinois, during the first 12 months with a license, how many passengers under 20 may a driver under 18 carry?","o":["None at all","Two","Three","One, not counting brothers, sisters or the driver's children"],"h1":"Family members such as brothers and sisters do not count.","h2":"For the first 12 months of an Illinois license, a driver under 18 may carry only one passenger under 20, not counting siblings or the driver's own children.","p":"Right. Only one young passenger who is not family."},"es":{"q":"En Illinois, durante los primeros 12 meses con licencia, ¿cuántos pasajeros menores de 20 años puede llevar un conductor menor de 18?","o":["Ninguno","Dos","Tres","Uno, sin contar hermanos ni hijos del conductor"],"h1":"Los familiares como hermanos y hermanas no cuentan.","h2":"Durante los primeros 12 meses de licencia en Illinois, un conductor menor de 18 años solo puede llevar un pasajero menor de 20, sin contar hermanos ni sus propios hijos.","p":"Correcto. Solo un pasajero joven que no sea familiar."},"ref":{"doc":"IL","page":18}},{"id":"il-012","scope":"IL","cat":"licensing","sign":null,"c":0,"en":{"q":"In Illinois, from Sunday to Thursday, when may a driver under 18 not drive, apart from the allowed exceptions?","o":["From 10 p.m. to 6 a.m.","From 8 p.m. to 6 a.m.","From midnight to 4 a.m.","From 1 a.m. to 5 a.m."],"h1":"It starts at ten at night on school nights.","h2":"In Illinois, a driver under 18 may not drive from 10 p.m. to 6 a.m., Sunday through Thursday, unless an exception applies, such as driving to or from work.","p":"Right. On weeknights the limit starts at 10 p.m."},"es":{"q":"En Illinois, de domingo a jueves, ¿en qué horario no puede manejar un conductor menor de 18 años, fuera de las excepciones permitidas?","o":["De 10 p.m. a 6 a.m.","De 8 p.m. a 6 a.m.","De medianoche a 4 a.m.","De 1 a.m. a 5 a.m."],"h1":"Empieza a las diez de la noche en días de escuela.","h2":"En Illinois un conductor menor de 18 años no puede manejar de 10 p.m. a 6 a.m., de domingo a jueves, salvo una excepción, como ir o volver del trabajo.","p":"Correcto. Entre semana el límite empieza a las 10 p.m."},"ref":{"doc":"IL","page":18}},{"id":"il-013","scope":"IL","cat":"licensing","sign":null,"c":2,"en":{"q":"In Illinois, on Friday and Saturday nights, when does the night driving limit for drivers under 18 begin?","o":["9 p.m.","10 p.m.","11 p.m.","1 a.m."],"h1":"It is one hour later than on school nights.","h2":"In Illinois the weekend night limit for drivers under 18 runs from 11 p.m. to 6 a.m. on Friday and Saturday nights.","p":"Right. On weekends the limit starts at 11 p.m."},"es":{"q":"En Illinois, los viernes y sábados por la noche, ¿a qué hora empieza el límite de manejo nocturno para menores de 18 años?","o":["9 p.m.","10 p.m.","11 p.m.","1 a.m."],"h1":"Es una hora más tarde que en días de escuela.","h2":"En Illinois el límite nocturno de fin de semana para menores de 18 años va de 11 p.m. a 6 a.m. los viernes y sábados.","p":"Correcto. El fin de semana el límite empieza a las 11 p.m."},"ref":{"doc":"IL","page":18}},{"id":"il-014","scope":"IL","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Illinois, what does Scott's Law tell you to do when you approach a stopped vehicle with flashing emergency or hazard lights?","o":["Speed up to pass quickly","Slow down and change lanes if you safely can","Stop in your lane until it leaves","Honk to warn the people there"],"h1":"This law is also called the Move Over law.","h2":"Scott's Law in Illinois tells you to slow down, change lanes if possible, and pass with caution when a stopped vehicle shows flashing emergency or hazard lights.","p":"Right. Slow down and move over when you safely can."},"es":{"q":"En Illinois, ¿qué le indica la Ley de Scott cuando se acerca a un vehículo detenido con luces de emergencia o intermitentes encendidas?","o":["Acelerar para pasar rápido","Bajar la velocidad y cambiar de carril si puede hacerlo con seguridad","Detenerse en su carril hasta que se vaya","Tocar el claxon para avisar a las personas"],"h1":"Esta ley también se llama ley de \"Move Over\" (cambie de carril).","h2":"La Ley de Scott en Illinois le indica bajar la velocidad, cambiar de carril si es posible y pasar con cuidado cuando un vehículo detenido tiene luces de emergencia o intermitentes.","p":"Correcto. Baje la velocidad y cámbiese de carril si puede hacerlo con seguridad."},"ref":{"doc":"IL","page":25}},{"id":"il-015","scope":"IL","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Illinois, besides police and fire vehicles, which stopped vehicles does Scott's Law cover?","o":["Only tow trucks","Only buses","No other vehicles","Any vehicle with its hazard or warning lights flashing"],"h1":"Think of any car that has its flashers on.","h2":"In Illinois, the move-over rule also covers any stopped vehicle with its hazard or warning lights flashing, including ordinary cars and trucks.","p":"Right. Any stopped vehicle with flashing lights is covered."},"es":{"q":"En Illinois, además de policía y bomberos, ¿qué vehículos detenidos cubre la Ley de Scott?","o":["Solo grúas","Solo autobuses","Ningún otro vehículo","Cualquier vehículo con las luces intermitentes o de advertencia encendidas"],"h1":"Piense en cualquier carro con las luces intermitentes encendidas.","h2":"En Illinois, la regla de moverse a otro carril también cubre cualquier vehículo detenido con las luces intermitentes o de advertencia encendidas, incluidos carros y camiones comunes.","p":"Correcto. Cualquier vehículo detenido con luces intermitentes está cubierto."},"ref":{"doc":"IL","page":45}},{"id":"il-016","scope":"IL","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Illinois, how far from a stopped school bus with its stop arm out must you stop?","o":["At least 20 feet","At least 5 feet","At least 50 feet","At least 100 feet"],"h1":"It is about the length of a large car and a half.","h2":"In Illinois you must stop at least 20 feet before a school bus that has its red lights flashing and stop arm out.","p":"Right. Stop at least 20 feet away."},"es":{"q":"En Illinois, ¿a qué distancia de un autobús escolar detenido con el brazo de alto extendido debe detenerse?","o":["Por lo menos 20 pies","Por lo menos 5 pies","Por lo menos 50 pies","Por lo menos 100 pies"],"h1":"Es más o menos el largo de un carro grande y medio.","h2":"En Illinois usted debe detenerse por lo menos a 20 pies de un autobús escolar que tiene las luces rojas encendidas y el brazo de alto extendido.","p":"Correcto. Deténgase por lo menos a 20 pies."},"ref":{"doc":"IL","page":null}},{"id":"il-017","scope":"IL","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Illinois, a school bus stops on a road with four or more lanes, two going each way. Who must stop?","o":["Everyone in both directions","Only drivers in the lane next to the bus","Only drivers going the same direction as the bus","No one, if the bus is on the shoulder"],"h1":"On a road this wide, the other side of the road is treated differently.","h2":"In Illinois, on a road with at least two lanes going each way, only drivers traveling in the same direction as the school bus must stop.","p":"Right. Only traffic going the same way as the bus must stop."},"es":{"q":"En Illinois, un autobús escolar se detiene en una vía de cuatro carriles o más, con dos en cada sentido. ¿Quién debe detenerse?","o":["Todos, en ambos sentidos","Solo los conductores en el carril junto al autobús","Solo los conductores que van en el mismo sentido que el autobús","Nadie, si el autobús está en el acotamiento"],"h1":"En una vía tan ancha, el otro lado del camino se trata de otra forma.","h2":"En Illinois, en una vía con por lo menos dos carriles en cada sentido, solo los conductores que van en el mismo sentido que el autobús escolar deben detenerse.","p":"Correcto. Solo el tráfico que va en el mismo sentido que el autobús debe detenerse."},"ref":{"doc":"IL","page":32}},{"id":"il-018","scope":"IL","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Illinois, unless a sign says otherwise, what is the speed limit in an urban district?","o":["25 mph","30 mph","35 mph","45 mph"],"h1":"It is a round number between 25 and 35.","h2":"Unless a sign says otherwise, the speed limit in an Illinois urban district is 30 miles per hour.","p":"Right. The Illinois urban limit is 30 mph."},"es":{"q":"En Illinois, si no hay un letrero que diga otra cosa, ¿cuál es el límite de velocidad en una zona urbana?","o":["25 mph","30 mph","35 mph","45 mph"],"h1":"Es un número redondo entre 25 y 35.","h2":"Si no hay un letrero que diga otra cosa, el límite de velocidad en una zona urbana de Illinois es de 30 millas por hora.","p":"Correcto. El límite urbano en Illinois es de 30 mph."},"ref":{"doc":"IL","page":24}},{"id":"il-019","scope":"IL","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Illinois, what is the speed limit in an alley?","o":["5 mph","10 mph","20 mph","15 mph"],"h1":"It is half of the urban limit.","h2":"The speed limit in an Illinois alley is 15 miles per hour.","p":"Right. Alleys in Illinois are 15 mph."},"es":{"q":"En Illinois, ¿cuál es el límite de velocidad en un callejón?","o":["5 mph","10 mph","20 mph","15 mph"],"h1":"Es la mitad del límite urbano.","h2":"El límite de velocidad en un callejón de Illinois es de 15 millas por hora.","p":"Correcto. En Illinois los callejones son de 15 mph."},"ref":{"doc":"IL","page":24}},{"id":"il-020","scope":"IL","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Illinois, outside urban districts, what is the general speed limit on roads that are not designated highways or interstates?","o":["45 mph","50 mph","55 mph","65 mph"],"h1":"It is ten less than the limit on designated four-lane divided highways.","h2":"Outside urban districts in Illinois, the general limit on ordinary roads that are not designated highways or interstates is 55 miles per hour.","p":"Right. Most rural Illinois roads are 55 mph."},"es":{"q":"En Illinois, fuera de las zonas urbanas, ¿cuál es el límite general en caminos que no son carreteras designadas ni interestatales?","o":["45 mph","50 mph","55 mph","65 mph"],"h1":"Es diez menos que el límite en carreteras divididas de cuatro carriles designadas.","h2":"Fuera de las zonas urbanas de Illinois, el límite general en caminos comunes que no son carreteras designadas ni interestatales es de 55 millas por hora.","p":"Correcto. La mayoría de los caminos rurales de Illinois son de 55 mph."},"ref":{"doc":"IL","page":24}},{"id":"il-021","scope":"IL","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Illinois, unless a sign says otherwise, what is the speed limit on interstates and tollways?","o":["70 mph","55 mph","65 mph","75 mph"],"h1":"It is five more than the limit on four-lane highways.","h2":"Unless a sign says otherwise, the speed limit on Illinois interstates and tollways is 70 miles per hour.","p":"Right. Illinois interstates and tollways are 70 mph."},"es":{"q":"En Illinois, a menos que una señal indique otra cosa, ¿cuál es el límite de velocidad en las autopistas interestatales y de peaje?","o":["70 mph","55 mph","65 mph","75 mph"],"h1":"Es cinco más que el límite en las carreteras de cuatro carriles.","h2":"A menos que una señal indique otra cosa, el límite de velocidad en las autopistas interestatales y de peaje de Illinois es de 70 millas por hora.","p":"Correcto. Las interestatales y autopistas de peaje de Illinois son de 70 mph."},"ref":{"doc":"IL","page":24}},{"id":"il-022","scope":"IL","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Illinois, how much alcohol may a driver under 21 have in the blood?","o":["Up to 0.08","Up to 0.05","Up to 0.02","None at all"],"h1":"Illinois calls this zero tolerance.","h2":"Under the Illinois zero tolerance law, a driver under 21 may not drive with any alcohol in the blood.","p":"Right. Under 21, no alcohol at all."},"es":{"q":"En Illinois, ¿cuánto alcohol puede tener en la sangre un conductor menor de 21 años?","o":["Hasta 0.08","Hasta 0.05","Hasta 0.02","Nada de alcohol"],"h1":"Illinois llama a esto tolerancia cero.","h2":"Según la ley de tolerancia cero de Illinois, un conductor menor de 21 años no puede manejar con nada de alcohol en la sangre.","p":"Correcto. Menor de 21, nada de alcohol."},"ref":{"doc":"IL","page":52}},{"id":"il-023","scope":"IL","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Illinois, what is the license suspension for a first zero tolerance violation by a driver under 21?","o":["One week","3 months","2 years","No suspension, only a warning"],"h1":"It is one quarter of a year.","h2":"In Illinois, a driver under 21 found with any alcohol while driving loses the license for at least three months.","p":"Right. A first violation means at least a three-month suspension."},"es":{"q":"En Illinois, ¿cuál es la suspensión de licencia por una primera violación de tolerancia cero de un conductor menor de 21?","o":["Una semana","3 meses","2 años","Ninguna, solo una advertencia"],"h1":"Es la cuarta parte de un año.","h2":"En Illinois, un conductor menor de 21 años que maneja con cualquier cantidad de alcohol pierde la licencia por al menos tres meses.","p":"Correcto. Una primera violación significa al menos tres meses de suspensión."},"ref":{"doc":"IL","page":52}},{"id":"in-001","scope":"IN","cat":"licensing","sign":null,"c":1,"en":{"q":"In Indiana, what is the youngest age to get a learner's permit if you are enrolled in driver education?","o":["14 years old","15 years old","16 years old","17 years old"],"h1":"Driver education lets you start one year before the usual age.","h2":"In Indiana you can get a learner's permit at 15 if you are enrolled in an approved driver education course.","p":"Right. With driver education, the permit starts at 15."},"es":{"q":"En Indiana, ¿cuál es la edad mínima para obtener un permiso de aprendiz si usted está inscrito en educación vial?","o":["14 años","15 años","16 años","17 años"],"h1":"La educación vial le permite empezar un año antes de la edad normal.","h2":"En Indiana usted puede obtener el permiso de aprendiz a los 15 años si está inscrito en un curso aprobado de educación vial.","p":"Correcto. Con educación vial, el permiso empieza a los 15."},"ref":{"doc":"IN","page":3}},{"id":"in-002","scope":"IN","cat":"licensing","sign":null,"c":2,"en":{"q":"In Indiana, how old must you be to get a learner's permit without taking driver education?","o":["14 years old","15 years old","16 years old","18 years old"],"h1":"It is one year later than with driver education.","h2":"In Indiana you must be at least 16 to get a learner's permit without a driver education course.","p":"Correct. Without driver education, you wait until 16."},"es":{"q":"En Indiana, ¿qué edad debe tener para obtener un permiso de aprendiz sin tomar educación vial?","o":["14 años","15 años","16 años","18 años"],"h1":"Es un año más tarde que con educación vial.","h2":"En Indiana usted debe tener por lo menos 16 años para obtener el permiso de aprendiz sin un curso de educación vial.","p":"Correcto. Sin educación vial, hay que esperar hasta los 16."},"ref":{"doc":"IN","page":3}},{"id":"in-003","scope":"IN","cat":"licensing","sign":null,"c":3,"en":{"q":"In Indiana, how old must a relative be to supervise a learner under 18?","o":["At least 18","At least 19","At least 21","At least 25"],"h1":"Indiana asks for an older supervisor than many states do.","h2":"In Indiana a relative who supervises a learner under 18 must be a licensed driver who is at least 25 years old.","p":"Right. The relative must be 25 or older."},"es":{"q":"En Indiana, ¿qué edad debe tener un familiar para supervisar a un aprendiz menor de 18 años?","o":["Por lo menos 18","Por lo menos 19","Por lo menos 21","Por lo menos 25"],"h1":"Indiana pide un supervisor de más edad que muchos otros estados.","h2":"En Indiana, un familiar que supervisa a un aprendiz menor de 18 años debe ser un conductor con licencia de por lo menos 25 años.","p":"Correcto. El familiar debe tener 25 años o más."},"ref":{"doc":"IN","page":4}},{"id":"in-004","scope":"IN","cat":"licensing","sign":null,"c":0,"en":{"q":"In Indiana, a learner's spouse may supervise practice driving. How old must the spouse be?","o":["At least 21","At least 25","At least 18","At least 30"],"h1":"It is younger than the age for other relatives.","h2":"In Indiana a licensed spouse who is at least 21 may supervise a learner, while other relatives must be at least 25.","p":"Correct. A spouse must be 21 or older."},"es":{"q":"En Indiana, el cónyuge de un aprendiz puede supervisar la práctica. ¿Qué edad debe tener el cónyuge?","o":["Por lo menos 21","Por lo menos 25","Por lo menos 18","Por lo menos 30"],"h1":"Es menor que la edad pedida a otros familiares.","h2":"En Indiana, un cónyuge con licencia de por lo menos 21 años puede supervisar a un aprendiz; otros familiares deben tener por lo menos 25.","p":"Correcto. El cónyuge debe tener 21 años o más."},"ref":{"doc":"IN","page":4}},{"id":"in-005","scope":"IN","cat":"licensing","sign":null,"c":1,"en":{"q":"In Indiana, how many hours of supervised driving must a new driver log before getting a license?","o":["20 hours","50 hours","40 hours","100 hours"],"h1":"It is a round number between 40 and 100.","h2":"In Indiana a new driver must log at least 50 hours of supervised driving practice before applying for a license.","p":"Right. Indiana asks for 50 logged hours."},"es":{"q":"En Indiana, ¿cuántas horas de manejo supervisado debe registrar un conductor nuevo antes de obtener la licencia?","o":["20 horas","50 horas","40 horas","100 horas"],"h1":"Es un número redondo entre 40 y 100.","h2":"En Indiana, un conductor nuevo debe registrar por lo menos 50 horas de práctica supervisada antes de solicitar la licencia.","p":"Correcto. Indiana pide 50 horas registradas."},"ref":{"doc":"IN","page":9}},{"id":"in-006","scope":"IN","cat":"licensing","sign":null,"c":2,"en":{"q":"In Indiana, how many of the logged supervised hours must be driven at night?","o":["At least 2 hours","At least 5 hours","At least 10 hours","At least 25 hours"],"h1":"It is one fifth of the total hours.","h2":"In Indiana at least 10 of the 50 supervised practice hours must be driven at night.","p":"Correct. Ten of the hours are at night."},"es":{"q":"En Indiana, ¿cuántas de las horas supervisadas registradas deben ser de noche?","o":["Por lo menos 2 horas","Por lo menos 5 horas","Por lo menos 10 horas","Por lo menos 25 horas"],"h1":"Es la quinta parte del total de horas.","h2":"En Indiana, por lo menos 10 de las 50 horas de práctica supervisada deben ser de noche.","p":"Correcto. Diez de las horas son de noche."},"ref":{"doc":"IN","page":9}},{"id":"in-007","scope":"IN","cat":"licensing","sign":null,"c":3,"en":{"q":"In Indiana, how long must you hold a learner's permit before you can get a probationary license?","o":["30 days","60 days","90 days","180 days"],"h1":"It is about six months.","h2":"In Indiana you must hold your learner's permit for 180 days, about six months, before getting a probationary license.","p":"Right. You hold the permit for 180 days."},"es":{"q":"En Indiana, ¿cuánto tiempo debe tener el permiso de aprendiz antes de obtener una licencia probatoria?","o":["30 días","60 días","90 días","180 días"],"h1":"Son unos seis meses.","h2":"En Indiana usted debe tener el permiso de aprendiz durante 180 días, unos seis meses, antes de obtener la licencia probatoria.","p":"Correcto. Se tiene el permiso por 180 días."},"ref":{"doc":"IN","page":9}},{"id":"in-008","scope":"IN","cat":"licensing","sign":null,"c":0,"en":{"q":"In Indiana, how old must you be to get a probationary license if you did not complete driver education?","o":["16 years and 270 days","16 years exactly","15 years and 180 days","18 years exactly"],"h1":"It is later than 16, but well before 17 and a half.","h2":"In Indiana a driver who did not finish driver education must be at least 16 years and 270 days old for a probationary license.","p":"Correct. Without driver education, it is 16 years and 270 days."},"es":{"q":"En Indiana, ¿qué edad debe tener para obtener una licencia probatoria si no completó educación vial?","o":["16 años y 270 días","16 años exactos","15 años y 180 días","18 años exactos"],"h1":"Es después de los 16, pero bastante antes de los 17 y medio.","h2":"En Indiana, un conductor que no terminó educación vial debe tener por lo menos 16 años y 270 días para la licencia probatoria.","p":"Correcto. Sin educación vial, son 16 años y 270 días."},"ref":{"doc":"IN","page":9}},{"id":"in-009","scope":"IN","cat":"licensing","sign":null,"c":1,"en":{"q":"In Indiana, during the first 180 days of a probationary license, when may you not drive?","o":["From midnight to 5 a.m.","From 10 p.m. to 5 a.m.","From 9 p.m. to 6 a.m.","From 1 a.m. to 5 a.m."],"h1":"The limit starts at a late evening hour, before midnight.","h2":"In Indiana, for the first 180 days of a probationary license, you may not drive between 10 p.m. and 5 a.m.","p":"Right. No driving from 10 p.m. to 5 a.m. at first."},"es":{"q":"En Indiana, durante los primeros 180 días de la licencia probatoria, ¿cuándo no puede manejar?","o":["De medianoche a 5 a.m.","De 10 p.m. a 5 a.m.","De 9 p.m. a 6 a.m.","De 1 a.m. a 5 a.m."],"h1":"El límite empieza en la noche, antes de la medianoche.","h2":"En Indiana, durante los primeros 180 días de la licencia probatoria, usted no puede manejar entre las 10 p.m. y las 5 a.m.","p":"Correcto. Al principio no se maneja de 10 p.m. a 5 a.m."},"ref":{"doc":"IN","page":10}},{"id":"in-010","scope":"IN","cat":"licensing","sign":null,"c":2,"en":{"q":"In Indiana, after the first 180 days of a probationary license and until 18, when may you not drive on Saturday and Sunday mornings?","o":["From 10 p.m. to 5 a.m.","From 11 p.m. to 5 a.m.","From 1 a.m. to 5 a.m.","From midnight to 6 a.m."],"h1":"On weekend mornings, the limit starts after midnight.","h2":"In Indiana, after the first 180 days and until 18, a probationary driver may not drive from 1 a.m. to 5 a.m. on Saturday and Sunday mornings.","p":"Correct. On weekend mornings, no driving from 1 a.m. to 5 a.m."},"es":{"q":"En Indiana, después de los primeros 180 días de la licencia probatoria y hasta los 18, ¿cuándo no puede manejar los sábados y domingos en la madrugada?","o":["De 10 p.m. a 5 a.m.","De 11 p.m. a 5 a.m.","De 1 a.m. a 5 a.m.","De medianoche a 6 a.m."],"h1":"Los fines de semana, el límite empieza después de la medianoche.","h2":"En Indiana, después de los primeros 180 días y hasta los 18, un conductor probatorio no puede manejar de 1 a.m. a 5 a.m. los sábados y domingos en la madrugada.","p":"Correcto. Los fines de semana, no puede manejar de 1 a.m. a 5 a.m."},"ref":{"doc":"IN","page":10}},{"id":"in-011","scope":"IN","cat":"licensing","sign":null,"c":3,"en":{"q":"In Indiana, after the first 180 days of a probationary license and until 18, when does the limit start on Sunday through Thursday nights?","o":["After 9 p.m.","After 10 p.m.","After 1 a.m.","After 11 p.m."],"h1":"It is one hour later than the limit in the first 180 days.","h2":"In Indiana, after the first 180 days and until 18, a probationary driver may not drive after 11 p.m. on Sunday through Thursday nights.","p":"Right. On school nights, the limit is 11 p.m."},"es":{"q":"En Indiana, después de los primeros 180 días de la licencia probatoria y hasta los 18, ¿a qué hora empieza el límite las noches de domingo a jueves?","o":["Después de las 9 p.m.","Después de las 10 p.m.","Después de la 1 a.m.","Después de las 11 p.m."],"h1":"Es una hora más tarde que el límite de los primeros 180 días.","h2":"En Indiana, después de los primeros 180 días y hasta los 18, un conductor probatorio no puede manejar después de las 11 p.m. de domingo a jueves.","p":"Correcto. Entre semana, el límite es a las 11 p.m."},"ref":{"doc":"IN","page":10}},{"id":"in-012","scope":"IN","cat":"licensing","sign":null,"c":0,"en":{"q":"In Indiana, which trip is allowed during the probationary night limits?","o":["Driving to or from work","Driving to a friend's party","Driving to buy snacks","Driving around for fun"],"h1":"The exceptions are for duties, not for fun.","h2":"In Indiana a probationary driver may drive during the night limits to or from work, a school-sanctioned activity or a religious event.","p":"Correct. Work trips are an exception."},"es":{"q":"En Indiana, ¿qué viaje está permitido durante el límite nocturno de la licencia probatoria?","o":["Ir o volver del trabajo","Ir a la fiesta de un amigo","Ir a comprar algo de comer","Dar una vuelta por diversión"],"h1":"Las excepciones son para obligaciones, no para diversión.","h2":"En Indiana, un conductor probatorio puede manejar durante el límite nocturno para ir o volver del trabajo, de una actividad aprobada por la escuela o de un evento religioso.","p":"Correcto. Ir al trabajo es una excepción."},"ref":{"doc":"IN","page":10}},{"id":"in-013","scope":"IN","cat":"licensing","sign":null,"c":1,"en":{"q":"In Indiana, during the first 180 days of a probationary license, when may you carry a friend as a passenger?","o":["Any time during the day","Only when a qualified adult, such as a licensed driver 25 or older, is in the front seat","Only on weekends","Only if the friend has a license"],"h1":"Think of the same adult who could supervise a learner.","h2":"In Indiana, for the first 180 days, a probationary driver may carry passengers only when a qualified adult, such as a licensed driver at least 25 or a spouse at least 21, is in the front seat; some close family members are allowed.","p":"Right. A qualified adult must be in the front seat."},"es":{"q":"En Indiana, durante los primeros 180 días de la licencia probatoria, ¿cuándo puede llevar a un amigo como pasajero?","o":["En cualquier momento de día","Solo cuando un adulto autorizado, como un conductor con licencia de 25 años o más, va en el asiento delantero","Solo los fines de semana","Solo si el amigo tiene licencia"],"h1":"Piense en el mismo adulto que puede supervisar a un aprendiz.","h2":"En Indiana, durante los primeros 180 días, un conductor probatorio solo puede llevar pasajeros si va en el asiento delantero un adulto autorizado, como un conductor con licencia de por lo menos 25 años o un cónyuge de por lo menos 21; algunos familiares cercanos sí están permitidos.","p":"Correcto. Un adulto autorizado debe ir adelante."},"ref":{"doc":"IN","page":10}},{"id":"in-014","scope":"IN","cat":"licensing","sign":null,"c":2,"en":{"q":"In Indiana, when does a probationary driver's license expire?","o":["On your 18th birthday","One year after it is issued","30 days after your 21st birthday","On your 25th birthday"],"h1":"It lasts until a little after you can legally drink.","h2":"In Indiana a probationary driver's license expires 30 days after your 21st birthday, and the renewed license has no probationary limits.","p":"Correct. It ends 30 days after you turn 21."},"es":{"q":"En Indiana, ¿cuándo vence la licencia probatoria?","o":["Al cumplir 18 años","Un año después de recibirla","30 días después de cumplir 21 años","Al cumplir 25 años"],"h1":"Dura hasta poco después de la edad legal para tomar alcohol.","h2":"En Indiana la licencia probatoria vence 30 días después de que usted cumple 21 años, y la licencia renovada ya no tiene límites probatorios.","p":"Correcto. Vence 30 días después de cumplir 21."},"ref":{"doc":"IN","page":10}},{"id":"in-015","scope":"IN","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Indiana, when may a probationary driver use a phone or other device while driving?","o":["Any time, if it is hands-free","Only at red lights","Only to use a map app","Only to call 911 in an emergency"],"h1":"There is only one exception, and it is for emergencies.","h2":"In Indiana a probationary driver may not use any telecommunication device while driving, even hands-free, except to call 911 in an emergency.","p":"Right. Only an emergency 911 call is allowed."},"es":{"q":"En Indiana, ¿cuándo puede un conductor probatorio usar un teléfono u otro aparato mientras maneja?","o":["En cualquier momento, si es manos libres","Solo en los semáforos en rojo","Solo para usar un mapa","Solo para llamar al 911 en una emergencia"],"h1":"Hay una sola excepción, y es para emergencias.","h2":"En Indiana, un conductor probatorio no puede usar ningún aparato de telecomunicación mientras maneja, ni siquiera manos libres, salvo para llamar al 911 en una emergencia.","p":"Correcto. Solo se permite una llamada de emergencia al 911."},"ref":{"doc":"IN","page":10}},{"id":"in-016","scope":"IN","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Indiana, what does the hands-free law say about all drivers and their phones?","o":["You may not hold a phone in your hand while driving","You may hold a phone below the window","You may text at speeds under 25 mph","Only drivers under 18 must be hands-free"],"h1":"The law's name tells you where your hands should be.","h2":"In Indiana no driver may hold a phone or tablet in their hand while driving; hands-free use such as Bluetooth or a speakerphone is allowed.","p":"Correct. Indiana drivers must stay hands-free."},"es":{"q":"En Indiana, ¿qué dice la ley de manos libres sobre todos los conductores y sus teléfonos?","o":["No puede tener el teléfono en la mano mientras maneja","Puede tener el teléfono debajo de la ventana","Puede enviar mensajes a menos de 25 mph","Solo los menores de 18 deben usar manos libres"],"h1":"El nombre de la ley le dice dónde deben estar sus manos.","h2":"En Indiana ningún conductor puede tener un teléfono o tableta en la mano mientras maneja; se permite el uso manos libres, como Bluetooth o altavoz.","p":"Correcto. En Indiana se maneja con manos libres."},"ref":{"doc":"IN","page":45}},{"id":"in-017","scope":"IN","cat":"licensing","sign":null,"c":1,"en":{"q":"In Indiana, what score do you need on the knowledge exam?","o":["70 percent on the whole test","80 percent or higher on each section","60 percent on each section","100 percent on the signs section"],"h1":"There are two sections, and each must be passed on its own.","h2":"In Indiana you must answer at least 80 percent correctly on each section of the knowledge exam to pass.","p":"Right. You need 80 percent on each section."},"es":{"q":"En Indiana, ¿qué calificación necesita en el examen de conocimientos?","o":["70 por ciento en todo el examen","80 por ciento o más en cada sección","60 por ciento en cada sección","100 por ciento en la sección de señales"],"h1":"Hay dos secciones, y cada una se aprueba por separado.","h2":"En Indiana usted debe contestar bien por lo menos el 80 por ciento de cada sección del examen de conocimientos para aprobar.","p":"Correcto. Se necesita 80 por ciento en cada sección."},"ref":{"doc":"IN","page":63}},{"id":"in-018","scope":"IN","cat":"licensing","sign":null,"c":2,"en":{"q":"In Indiana, what two sections make up the knowledge exam?","o":["Vehicle repair and first aid","Parking and car insurance","Traffic rules and traffic signs","Night driving and map reading"],"h1":"One part is about what to do, the other about what you see beside the road.","h2":"In Indiana the knowledge exam has one section on traffic rules and driving maneuvers and one section on traffic signs.","p":"Correct. Rules and signs are the two sections."},"es":{"q":"En Indiana, ¿cuáles son las dos secciones del examen de conocimientos?","o":["Reparación de vehículos y primeros auxilios","Estacionamiento y seguro de auto","Reglas de tránsito y señales de tránsito","Manejo nocturno y lectura de mapas"],"h1":"Una parte trata de qué hacer, y la otra de lo que ve al lado del camino.","h2":"En Indiana el examen de conocimientos tiene una sección sobre reglas de tránsito y maniobras, y otra sobre señales de tránsito.","p":"Correcto. Reglas y señales son las dos secciones."},"ref":{"doc":"IN","page":63}},{"id":"in-019","scope":"IN","cat":"licensing","sign":null,"c":3,"en":{"q":"In Indiana, a 15-year-old in driver education may practice with a parent only after finishing how much of the classroom or online part?","o":["5 hours","10 hours","50 hours","30 hours"],"h1":"It is the same number as the days in most months.","h2":"In Indiana a 15-year-old in driver education must finish 30 hours of the classroom or online part before practicing with a parent or other supervisor.","p":"Right. Thirty hours of classroom or online work come first."},"es":{"q":"En Indiana, un joven de 15 años en educación vial puede practicar con un padre solo después de terminar ¿cuánto de la parte en clase o en línea?","o":["5 horas","10 horas","50 horas","30 horas"],"h1":"Es el mismo número que los días de casi todos los meses.","h2":"En Indiana, un joven de 15 años en educación vial debe terminar 30 horas de la parte en clase o en línea antes de practicar con un padre u otro supervisor.","p":"Correcto. Primero vienen 30 horas de clase o en línea."},"ref":{"doc":"IN","page":null}},{"id":"in-020","scope":"IN","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Indiana, you approach a stopped tow truck with amber flashing lights and you cannot safely change lanes. What must you do?","o":["Slow to 10 mph below the speed limit","Keep your speed and honk","Slow to 5 mph below the speed limit","Stop completely in your lane"],"h1":"Indiana sets a number below the posted limit.","h2":"In Indiana, if you cannot move away from a stopped vehicle with flashing lights, you must slow to 10 mph below the speed limit and drive with caution.","p":"Correct. Slow down by 10 mph."},"es":{"q":"En Indiana, se acerca a una grúa detenida con luces ámbar intermitentes y no puede cambiar de carril con seguridad. ¿Qué debe hacer?","o":["Bajar a 10 mph menos que el límite de velocidad","Mantener la velocidad y tocar la bocina","Bajar a 5 mph menos que el límite","Detenerse por completo en su carril"],"h1":"Indiana fija un número por debajo del límite.","h2":"En Indiana, si no puede alejarse de un vehículo detenido con luces intermitentes, debe bajar a 10 mph menos que el límite de velocidad y manejar con cuidado.","p":"Correcto. Baje 10 mph."},"ref":{"doc":"IN","page":51}},{"id":"in-021","scope":"IN","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Indiana, a school bus is stopped with its stop arm out on the other side of a road divided by a barrier or an unpaved median. What must you do?","o":["Stop and wait until the bus moves","You do not have to stop, but you must drive with care","Stop only if children are visible","Stop and then pass at 10 mph"],"h1":"The median or barrier separates you from the bus.","h2":"In Indiana you do not need to stop for a school bus on the other side of a road divided by a barrier or an unpaved median, but you must drive with care.","p":"Right. The divided highway lets you continue carefully."},"es":{"q":"En Indiana, un autobús escolar está detenido con el brazo de alto extendido al otro lado de una carretera dividida por una barrera o una mediana sin pavimentar. ¿Qué debe hacer?","o":["Detenerse y esperar a que el autobús avance","No tiene que detenerse, pero debe manejar con cuidado","Detenerse solo si ve niños","Detenerse y luego pasar a 10 mph"],"h1":"La mediana o barrera lo separa del autobús.","h2":"En Indiana usted no tiene que detenerse por un autobús escolar al otro lado de una carretera dividida por una barrera o una mediana sin pavimentar, pero debe manejar con cuidado.","p":"Correcto. La carretera dividida le permite seguir con cuidado."},"ref":{"doc":"IN","page":52}},{"id":"in-022","scope":"IN","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Indiana, what blood alcohol level breaks the law for a driver under 21?","o":["0.08 or more","0.05 or more","0.02 or more","0.10 or more"],"h1":"It is much lower than the adult limit.","h2":"In Indiana a driver under 21 breaks the law with a blood alcohol level of 0.02 or more.","p":"Correct. For drivers under 21 the limit is 0.02."},"es":{"q":"En Indiana, ¿qué nivel de alcohol en la sangre viola la ley para un conductor menor de 21 años?","o":["0.08 o más","0.05 o más","0.02 o más","0.10 o más"],"h1":"Es mucho más bajo que el límite para adultos.","h2":"En Indiana, un conductor menor de 21 años viola la ley con un nivel de alcohol en la sangre de 0.02 o más.","p":"Correcto. Para menores de 21 el límite es 0.02."},"ref":{"doc":"IN","page":null}},{"id":"ks-001","scope":"KS","cat":"licensing","sign":null,"c":1,"en":{"q":"In Kansas, what is the youngest age to get an instruction permit?","o":["13 years old","14 years old","15 years old","16 years old"],"h1":"Kansas lets teens start earlier than most states.","h2":"In Kansas you can get an instruction permit at 14, one of the youngest permit ages in the country.","p":"Right. The Kansas permit starts at 14."},"es":{"q":"En Kansas, ¿cuál es la edad mínima para obtener un permiso de instrucción?","o":["13 años","14 años","15 años","16 años"],"h1":"Kansas permite empezar más temprano que la mayoría de los estados.","h2":"En Kansas usted puede obtener el permiso de instrucción a los 14 años, una de las edades más bajas del país.","p":"Correcto. El permiso en Kansas empieza a los 14."},"ref":{"doc":"KS","page":12}},{"id":"ks-002","scope":"KS","cat":"licensing","sign":null,"c":3,"en":{"q":"In Kansas, how old must the licensed adult supervising a permit driver be?","o":["At least 16","At least 18","At least 25","At least 21"],"h1":"The helper must be old enough to drink legally.","h2":"A Kansas permit driver must be supervised by a licensed adult who is at least 21 years old.","p":"Right. The supervising adult must be 21 or older."},"es":{"q":"En Kansas, ¿qué edad debe tener el adulto con licencia que supervisa a un conductor con permiso?","o":["Por lo menos 16","Por lo menos 18","Por lo menos 25","Por lo menos 21"],"h1":"El acompañante debe tener edad para tomar alcohol legalmente.","h2":"En Kansas, un conductor con permiso debe ir supervisado por un adulto con licencia de por lo menos 21 años.","p":"Correcto. El adulto que supervisa debe tener 21 años o más."},"ref":{"doc":"KS","page":12}},{"id":"ks-003","scope":"KS","cat":"licensing","sign":null,"c":0,"en":{"q":"In Kansas, who may sit in the front seat while a permit driver is at the wheel?","o":["Only the supervising driver","Any passenger over 12","Any licensed friend","Nobody, the front seat must be empty"],"h1":"The front seat is for the person who is teaching you.","h2":"In Kansas, no one except the supervising driver may sit in the front seat while a permit holder drives.","p":"Right. Only the supervising driver sits up front."},"es":{"q":"En Kansas, ¿quién puede ir en el asiento delantero mientras maneja un conductor con permiso?","o":["Solo el conductor que supervisa","Cualquier pasajero mayor de 12 años","Cualquier amigo con licencia","Nadie, el asiento delantero debe ir vacío"],"h1":"El asiento delantero es para la persona que le está enseñando.","h2":"En Kansas, nadie más que el conductor que supervisa puede ir en el asiento delantero mientras maneja quien tiene permiso.","p":"Correcto. Solo el supervisor va adelante."},"ref":{"doc":"KS","page":12}},{"id":"ks-004","scope":"KS","cat":"licensing","sign":null,"c":2,"en":{"q":"In Kansas, how long must you hold an instruction permit before you can get a restricted license?","o":["10 days","6 months","One year","Two years"],"h1":"It is a full trip around the calendar.","h2":"In Kansas you must hold your instruction permit for at least one year before you can apply for a restricted license.","p":"Right. Kansas requires a full year on the permit."},"es":{"q":"En Kansas, ¿cuánto tiempo debe tener el permiso de instrucción antes de obtener una licencia restringida?","o":["10 días","6 meses","Un año","Dos años"],"h1":"Es una vuelta completa al calendario.","h2":"En Kansas usted debe tener el permiso de instrucción por lo menos un año antes de solicitar una licencia restringida.","p":"Correcto. Kansas exige un año completo con permiso."},"ref":{"doc":"KS","page":12}},{"id":"ks-005","scope":"KS","cat":"licensing","sign":null,"c":1,"en":{"q":"In Kansas, how many hours of adult-supervised driving does a 15-year-old need before getting a restricted license?","o":["10 hours","25 hours","50 hours","100 hours"],"h1":"It is half of the full amount needed later.","h2":"A 15-year-old in Kansas needs at least 25 hours of adult-supervised driving before getting a restricted license.","p":"Right. At 15, the first step is 25 hours."},"es":{"q":"En Kansas, ¿cuántas horas de manejo supervisado por un adulto necesita una persona de 15 años antes de obtener la licencia restringida?","o":["10 horas","25 horas","50 horas","100 horas"],"h1":"Es la mitad del total que se pide después.","h2":"En Kansas, una persona de 15 años necesita por lo menos 25 horas de manejo supervisado por un adulto antes de obtener la licencia restringida.","p":"Correcto. A los 15, el primer paso son 25 horas."},"ref":{"doc":"KS","page":12}},{"id":"ks-006","scope":"KS","cat":"licensing","sign":null,"c":2,"en":{"q":"In Kansas, how many supervised driving hours does a teen need in total, and how many at night?","o":["25 hours, 5 at night","40 hours, 8 at night","50 hours, 10 at night","60 hours, 20 at night"],"h1":"The night hours are one fifth of the total.","h2":"A Kansas teen needs 50 hours of adult-supervised driving in total, and at least 10 of those hours must be at night.","p":"Right. Fifty hours, with ten at night."},"es":{"q":"En Kansas, ¿cuántas horas de manejo supervisado necesita un adolescente en total, y cuántas de noche?","o":["25 horas, 5 de noche","40 horas, 8 de noche","50 horas, 10 de noche","60 horas, 20 de noche"],"h1":"Las horas de noche son una quinta parte del total.","h2":"En Kansas, un adolescente necesita 50 horas de manejo supervisado en total, y por lo menos 10 de ellas deben ser de noche.","p":"Correcto. Cincuenta horas, con diez de noche."},"ref":{"doc":"KS","page":12}},{"id":"ks-007","scope":"KS","cat":"licensing","sign":null,"c":3,"en":{"q":"In Kansas, do hours driven in a driver education course count toward the 50 supervised hours?","o":["Yes, all course time counts, even watching others drive","Only the night hours count","Only if a parent rides along","Yes, time behind the wheel counts if the instructor is 21 or older"],"h1":"Only real driving time with an adult of the right age counts.","h2":"In Kansas, time you spend behind the wheel in driver education counts toward the 50 hours when the instructor is at least 21, but time spent only watching does not count.","p":"Right. Behind-the-wheel time with an instructor 21 or older counts."},"es":{"q":"En Kansas, ¿cuentan las horas manejadas en un curso de educación vial para las 50 horas supervisadas?","o":["Sí, todo el tiempo del curso cuenta, incluso mirar a otros manejar","Solo cuentan las horas de noche","Solo si el padre va en el carro","Sí, el tiempo al volante cuenta si el instructor tiene 21 años o más"],"h1":"Solo cuenta el tiempo real manejando con un adulto de la edad correcta.","h2":"En Kansas, el tiempo que usted pasa al volante en educación vial cuenta para las 50 horas cuando el instructor tiene por lo menos 21 años, pero el tiempo que solo pasa mirando no cuenta.","p":"Correcto. El tiempo al volante con un instructor de 21 años o más sí cuenta."},"ref":{"doc":"KS","page":null}},{"id":"ks-008","scope":"KS","cat":"licensing","sign":null,"c":0,"en":{"q":"In Kansas, what happens if a teen never turns in the 50-hour affidavit?","o":["The license restrictions continue until age 17","The license is canceled","The teen must retake the knowledge test","Nothing changes"],"h1":"The limits stay in place for a while longer.","h2":"If a Kansas teen does not turn in the 50-hour affidavit, the restrictions on the license stay in place until age 17.","p":"Right. Without the affidavit, the limits last until 17."},"es":{"q":"En Kansas, ¿qué pasa si un adolescente nunca entrega la declaración jurada de las 50 horas?","o":["Las restricciones de la licencia siguen hasta los 17 años","Le cancelan la licencia","Debe repetir el examen de conocimientos","No cambia nada"],"h1":"Los límites siguen por más tiempo.","h2":"Si un adolescente en Kansas no entrega la declaración jurada de las 50 horas, las restricciones de su licencia siguen hasta los 17 años.","p":"Correcto. Sin la declaración, los límites duran hasta los 17."},"ref":{"doc":"KS","page":null}},{"id":"ks-009","scope":"KS","cat":"licensing","sign":null,"c":1,"en":{"q":"In Kansas, what must a 15-year-old complete, besides the permit year, to get a restricted license?","o":["A first aid course","An approved driver education course","A motorcycle course","Nothing else"],"h1":"It is a class about driving.","h2":"A 15-year-old in Kansas must complete an approved driver education course to get a restricted license.","p":"Right. Driver education is required at 15."},"es":{"q":"En Kansas, ¿qué debe completar una persona de 15 años, además del año con permiso, para obtener la licencia restringida?","o":["Un curso de primeros auxilios","Un curso aprobado de educación vial","Un curso de motocicleta","Nada más"],"h1":"Es una clase sobre manejo.","h2":"En Kansas, una persona de 15 años debe completar un curso aprobado de educación vial para obtener la licencia restringida.","p":"Correcto. A los 15 se exige educación vial."},"ref":{"doc":"KS","page":12}},{"id":"ks-010","scope":"KS","cat":"licensing","sign":null,"c":2,"en":{"q":"In Kansas, a 15-year-old with a restricted license may drive alone to school how?","o":["Any route, any day","Only on weekends","By the most direct route on school days","Only with a sibling"],"h1":"Think of the shortest way between home and school.","h2":"A 15-year-old in Kansas with a restricted license may drive alone to school on school days, using the most direct route between home and school.","p":"Right. The direct route, on school days."},"es":{"q":"En Kansas, ¿cómo puede manejar sola a la escuela una persona de 15 años con licencia restringida?","o":["Por cualquier ruta, cualquier día","Solo los fines de semana","Por la ruta más directa en días de clase","Solo con un hermano"],"h1":"Piense en el camino más corto entre la casa y la escuela.","h2":"En Kansas, una persona de 15 años con licencia restringida puede manejar sola a la escuela en días de clase, por la ruta más directa entre la casa y la escuela.","p":"Correcto. La ruta directa, en días de clase."},"ref":{"doc":"KS","page":13}},{"id":"ks-011","scope":"KS","cat":"licensing","sign":null,"c":3,"en":{"q":"In Kansas, may a restricted driver under 16 carry friends who are minors?","o":["Yes, up to three","Yes, one friend","Yes, if the windows are closed","No, only siblings may ride as minor passengers"],"h1":"Brothers and sisters are the exception.","h2":"In Kansas, a restricted driver under 16 may not carry minor passengers who are not brothers or sisters.","p":"Right. Under 16, only sibling minors may ride."},"es":{"q":"En Kansas, ¿puede un conductor con licencia restringida menor de 16 años llevar amigos menores de edad?","o":["Sí, hasta tres","Sí, un amigo","Sí, si las ventanas van cerradas","No, solo hermanos pueden ir como pasajeros menores"],"h1":"Los hermanos son la excepción.","h2":"En Kansas, un conductor con licencia restringida menor de 16 años no puede llevar pasajeros menores de edad que no sean sus hermanos.","p":"Correcto. Antes de los 16, solo hermanos menores."},"ref":{"doc":"KS","page":13}},{"id":"ks-012","scope":"KS","cat":"licensing","sign":null,"c":0,"en":{"q":"In Kansas, a 16-year-old with a restricted license may drive alone during which hours?","o":["5 a.m. to 9 p.m.","6 a.m. to 10 p.m.","Midnight to 5 a.m.","Any time at all"],"h1":"The window closes early in the evening.","h2":"A 16-year-old in Kansas with a restricted license may drive alone from 5 a.m. to 9 p.m., plus trips for work, school activities and religious services.","p":"Right. Five in the morning to nine at night."},"es":{"q":"En Kansas, ¿en qué horario puede manejar solo un joven de 16 años con licencia restringida?","o":["De 5 a.m. a 9 p.m.","De 6 a.m. a 10 p.m.","De medianoche a 5 a.m.","A cualquier hora"],"h1":"El horario termina temprano en la noche.","h2":"En Kansas, un joven de 16 años con licencia restringida puede manejar solo de 5 a.m. a 9 p.m., además de viajes de trabajo, actividades escolares y servicios religiosos.","p":"Correcto. De cinco de la mañana a nueve de la noche."},"ref":{"doc":"KS","page":13}},{"id":"ks-013","scope":"KS","cat":"licensing","sign":null,"c":1,"en":{"q":"In Kansas, how many passengers under 18 who are not family may a newly restricted 16-year-old carry?","o":["None","One","Two","Three"],"h1":"It is the smallest number that is more than zero.","h2":"For the first six months, a 16-year-old in Kansas with a restricted license may carry no more than one passenger under 18 who is not an immediate family member.","p":"Right. Only one non-family passenger under 18."},"es":{"q":"En Kansas, ¿cuántos pasajeros menores de 18 años que no son familia puede llevar un joven de 16 años con licencia restringida reciente?","o":["Ninguno","Uno","Dos","Tres"],"h1":"Es el número más pequeño mayor que cero.","h2":"Durante los primeros seis meses, un joven de 16 años en Kansas con licencia restringida puede llevar como máximo un pasajero menor de 18 años que no sea familiar directo.","p":"Correcto. Solo un pasajero menor de 18 que no sea familia."},"ref":{"doc":"KS","page":12}},{"id":"ks-014","scope":"KS","cat":"licensing","sign":null,"c":2,"en":{"q":"In Kansas, when may a 15-year-old restricted driver drive at any time of day?","o":["On holidays","When another teen with a permit rides along","When a licensed adult sits in the front seat beside them","Never"],"h1":"An experienced adult must be right beside you.","h2":"A 15-year-old in Kansas with a restricted license may drive at any time when a licensed adult sits in the front seat beside them.","p":"Right. Any time, with a licensed adult beside you."},"es":{"q":"En Kansas, ¿cuándo puede manejar a cualquier hora una persona de 15 años con licencia restringida?","o":["En días festivos","Cuando va con otro joven que tiene permiso","Cuando un adulto con licencia va a su lado en el asiento delantero","Nunca"],"h1":"Un adulto con experiencia debe ir a su lado.","h2":"En Kansas, una persona de 15 años con licencia restringida puede manejar a cualquier hora si un adulto con licencia va a su lado en el asiento delantero.","p":"Correcto. A cualquier hora, con un adulto con licencia a su lado."},"ref":{"doc":"KS","page":13}},{"id":"ks-015","scope":"KS","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Kansas, when may a teen with a permit or restricted license use a phone while driving?","o":["At red lights","For short texts","With a hands-free device","Only to report illegal activity or call for emergency help"],"h1":"Only a true emergency or a crime is an exception.","h2":"A Kansas teen with a permit or restricted license may not use a wireless device while driving, except to report illegal activity or call for medical or emergency help.","p":"Right. Only for emergencies or to report a crime."},"es":{"q":"En Kansas, ¿cuándo puede usar el teléfono mientras maneja un adolescente con permiso o licencia restringida?","o":["En los semáforos en rojo","Para mensajes cortos","Con un dispositivo manos libres","Solo para reportar un delito o pedir ayuda de emergencia"],"h1":"Solo una emergencia real o un delito son la excepción.","h2":"En Kansas, un adolescente con permiso o licencia restringida no puede usar un dispositivo inalámbrico mientras maneja, salvo para reportar un delito o pedir ayuda médica o de emergencia.","p":"Correcto. Solo para emergencias o para reportar un delito."},"ref":{"doc":"KS","page":12}},{"id":"ks-016","scope":"KS","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Kansas, a driver under 21 breaks the law at what blood alcohol level?","o":[".02 or higher",".05 or higher",".08 or higher",".10 or higher"],"h1":"It is a very small amount, far below the adult limit.","h2":"In Kansas it is illegal for a driver under 21 to drive with a blood or breath alcohol level of .02 or higher.","p":"Right. Under 21, the limit is .02."},"es":{"q":"En Kansas, ¿con qué nivel de alcohol en la sangre comete una infracción un conductor menor de 21 años?","o":[".02 o más",".05 o más",".08 o más",".10 o más"],"h1":"Es una cantidad muy pequeña, muy por debajo del límite para adultos.","h2":"En Kansas es ilegal que un conductor menor de 21 años maneje con un nivel de alcohol en la sangre o el aliento de .02 o más.","p":"Correcto. Para menores de 21, el límite es .02."},"ref":{"doc":"KS","page":23}},{"id":"ks-017","scope":"KS","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Kansas, how long is the license suspension for a first time a driver under 21 tests between .02 and .08?","o":["7 days","14 days","30 days","One year"],"h1":"It is about one month.","h2":"In Kansas, a first offense by a driver under 21 with a result from .02 up to .08 brings a 30-day suspension.","p":"Right. The first suspension lasts 30 days."},"es":{"q":"En Kansas, ¿cuánto dura la suspensión la primera vez que un conductor menor de 21 años da entre .02 y .08?","o":["7 días","14 días","30 días","Un año"],"h1":"Es más o menos un mes.","h2":"En Kansas, la primera vez que un conductor menor de 21 años da entre .02 y .08, se le suspende la licencia por 30 días.","p":"Correcto. La primera suspensión dura 30 días."},"ref":{"doc":"KS","page":null}},{"id":"ks-018","scope":"KS","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Kansas, what is the speed limit on a county or township road when no other limit is posted?","o":["45 mph","55 mph","65 mph","75 mph"],"h1":"It is ten less than the limit on other open highways.","h2":"In Kansas the speed limit on a county or township road is 55 mph unless a different limit is posted.","p":"Right. County and township roads are 55 mph."},"es":{"q":"En Kansas, ¿cuál es el límite de velocidad en un camino de condado o municipio cuando no hay otro límite indicado?","o":["45 mph","55 mph","65 mph","75 mph"],"h1":"Es diez menos que el límite de otras carreteras abiertas.","h2":"En Kansas el límite de velocidad en un camino de condado o municipio es de 55 mph, a menos que haya otro límite indicado.","p":"Correcto. Los caminos de condado y municipio son de 55 mph."},"ref":{"doc":"KS","page":62}},{"id":"ks-019","scope":"KS","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Kansas, where is 75 mph the speed limit?","o":["On every highway","On all county roads","In school zones at night","On divided multilane highways where it is posted"],"h1":"The highest limit only applies where a sign says so.","h2":"In Kansas, 75 mph is the limit only on divided multilane highways that the state has marked with that limit.","p":"Right. 75 mph only where it is posted."},"es":{"q":"En Kansas, ¿dónde es 75 mph el límite de velocidad?","o":["En todas las carreteras","En todos los caminos de condado","En zonas escolares de noche","En carreteras divididas de varios carriles donde esté indicado"],"h1":"El límite más alto solo aplica donde un letrero lo indica.","h2":"En Kansas, 75 mph es el límite solo en carreteras divididas de varios carriles donde el estado lo ha señalado.","p":"Correcto. 75 mph solo donde esté indicado."},"ref":{"doc":"KS","page":62}},{"id":"ks-020","scope":"KS","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Kansas, which stopped buses with their stop signals on require you to stop?","o":["School buses only","City transit buses","School buses, church buses and day care buses","Tour buses"],"h1":"It is more than just the yellow school bus.","h2":"In Kansas you must stop for a school bus, church bus or day care bus that is stopped to load or unload children.","p":"Right. School, church and day care buses."},"es":{"q":"En Kansas, ¿por cuáles autobuses detenidos con sus señales de parada encendidas debe usted detenerse?","o":["Solo autobuses escolares","Autobuses urbanos","Autobuses escolares, de iglesia y de guardería","Autobuses de turismo"],"h1":"Es más que solo el autobús escolar amarillo.","h2":"En Kansas usted debe detenerse ante un autobús escolar, de iglesia o de guardería que está detenido para subir o bajar niños.","p":"Correcto. Escolares, de iglesia y de guardería."},"ref":{"doc":"KS","page":18}},{"id":"ks-021","scope":"KS","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Kansas, a school bus is stopped on the other side of a divided highway. What must you do?","o":["You do not have to stop, but drive with care","Stop and wait until it moves","Honk and pass quickly","Stop only if children are visible"],"h1":"The divided road separates you from the bus.","h2":"In Kansas, if a school bus is stopped on the opposite roadway of a divided highway, you are not required to stop, though you should watch for children.","p":"Right. On a divided highway, oncoming traffic need not stop."},"es":{"q":"En Kansas, un autobús escolar está detenido al otro lado de una carretera dividida. ¿Qué debe hacer usted?","o":["No tiene que detenerse, pero maneje con cuidado","Detenerse y esperar hasta que avance","Tocar la bocina y pasar rápido","Detenerse solo si ve niños"],"h1":"La carretera dividida lo separa del autobús.","h2":"En Kansas, si un autobús escolar está detenido en el lado opuesto de una carretera dividida, usted no tiene que detenerse, aunque debe estar atento a los niños.","p":"Correcto. En carretera dividida, el tráfico contrario no se detiene."},"ref":{"doc":"KS","page":18}},{"id":"ks-022","scope":"KS","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Kansas, since July 2025, the move-over law covers which stopped vehicles?","o":["Only police cars","Any stopped vehicle with hazard lights on","Only tow trucks","Only school buses"],"h1":"The 2025 change widened the law to every kind of vehicle.","h2":"Since July 1, 2025, the Kansas move-over law covers any stopped vehicle showing hazard warning lights, so you must change lanes or slow down.","p":"Right. Any stopped vehicle with hazard lights."},"es":{"q":"En Kansas, desde julio de 2025, ¿a qué vehículos detenidos aplica la ley de cambiarse de carril?","o":["Solo a patrullas","A cualquier vehículo detenido con luces intermitentes","Solo a grúas","Solo a autobuses escolares"],"h1":"El cambio de 2025 amplió la ley a todo tipo de vehículo.","h2":"Desde el 1 de julio de 2025, la ley de Kansas aplica a cualquier vehículo detenido con luces intermitentes de emergencia, y usted debe cambiarse de carril o bajar la velocidad.","p":"Correcto. Cualquier vehículo detenido con intermitentes."},"ref":{"doc":"KS","page":null}},{"id":"ks-023","scope":"KS","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Kansas, can police stop a car only because the driver or front-seat passenger is not wearing a seat belt?","o":["No, never","Only at night","Only on interstates","Yes, it is a primary offense"],"h1":"Kansas made this rule stronger in 2010.","h2":"In Kansas, police may stop a car just because the driver or front-seat passenger is not wearing a seat belt.","p":"Right. In the front seat, it is a primary offense."},"es":{"q":"En Kansas, ¿puede la policía detener un carro solo porque el conductor o el pasajero de adelante no lleva el cinturón?","o":["No, nunca","Solo de noche","Solo en autopistas","Sí, es una infracción primaria"],"h1":"Kansas hizo esta regla más estricta en 2010.","h2":"En Kansas, la policía puede detener un carro solo porque el conductor o el pasajero de adelante no lleva puesto el cinturón de seguridad.","p":"Correcto. En el asiento delantero es una infracción primaria."},"ref":{"doc":"KS","page":null}},{"id":"ky-001","scope":"KY","cat":"licensing","sign":null,"c":1,"en":{"q":"In Kentucky, what is the youngest age to get an instruction permit?","o":["14 years old","15 years old","16 years old","17 years old"],"h1":"A 2025 law lowered the age by one year, from 16.","h2":"You can get a Kentucky instruction permit at 15, because a 2025 law lowered the age from 16.","p":"Right. In Kentucky the permit starts at 15."},"es":{"q":"En Kentucky, ¿cuál es la edad mínima para obtener un permiso de instrucción?","o":["14 años","15 años","16 años","17 años"],"h1":"Una ley de 2025 bajó la edad un año, desde los 16.","h2":"Usted puede obtener un permiso de instrucción en Kentucky a los 15 años, porque una ley de 2025 bajó la edad desde los 16.","p":"Correcto. En Kentucky el permiso empieza a los 15."},"ref":{"doc":"KY","page":5}},{"id":"ky-002","scope":"KY","cat":"licensing","sign":null,"c":3,"en":{"q":"In Kentucky, how long must a driver under 21 hold the instruction permit before applying for a license?","o":["At least 30 days","At least 60 days","At least one year","At least 180 days"],"h1":"It is about six months.","h2":"A Kentucky driver under 21 must hold the instruction permit for at least 180 days, about six months, before applying for a license.","p":"Right. Under 21, you hold the permit at least 180 days."},"es":{"q":"En Kentucky, ¿cuánto tiempo debe tener el permiso de instrucción un conductor menor de 21 años antes de solicitar la licencia?","o":["Por lo menos 30 días","Por lo menos 60 días","Por lo menos un año","Por lo menos 180 días"],"h1":"Son unos seis meses.","h2":"En Kentucky, un conductor menor de 21 años debe tener el permiso de instrucción por lo menos 180 días, unos seis meses, antes de solicitar la licencia.","p":"Correcto. Si es menor de 21, debe tener el permiso por lo menos 180 días."},"ref":{"doc":"KY","page":5}},{"id":"ky-003","scope":"KY","cat":"licensing","sign":null,"c":0,"en":{"q":"In Kentucky, how long must a permit holder who is 21 or older hold the permit before the road test?","o":["At least 30 days","At least 180 days","At least 7 days","At least one year"],"h1":"Adults wait much less than teens. It is about one month.","h2":"A Kentucky permit holder who is 21 or older must hold the permit for at least 30 days, much less than the 180 days for younger drivers.","p":"Right. Drivers 21 and older wait at least 30 days."},"es":{"q":"En Kentucky, ¿cuánto tiempo debe tener el permiso una persona de 21 años o más antes del examen de manejo?","o":["Por lo menos 30 días","Por lo menos 180 días","Por lo menos 7 días","Por lo menos un año"],"h1":"Los adultos esperan mucho menos que los jóvenes. Es como un mes.","h2":"En Kentucky, una persona de 21 años o más debe tener el permiso por lo menos 30 días, mucho menos que los 180 días de los conductores más jóvenes.","p":"Correcto. Las personas de 21 años o más esperan por lo menos 30 días."},"ref":{"doc":"KY","page":9}},{"id":"ky-004","scope":"KY","cat":"licensing","sign":null,"c":2,"en":{"q":"In Kentucky, what is the youngest age to get an intermediate license?","o":["15 years old","17 years old","16 years old","18 years old"],"h1":"It is one year after the youngest permit age.","h2":"You must be at least 16 to get a Kentucky intermediate license, even if you got your permit at 15.","p":"Right. The intermediate license starts at 16."},"es":{"q":"En Kentucky, ¿cuál es la edad mínima para obtener una licencia intermedia?","o":["15 años","17 años","16 años","18 años"],"h1":"Es un año después de la edad mínima del permiso.","h2":"Usted debe tener por lo menos 16 años para obtener una licencia intermedia en Kentucky, aunque haya sacado el permiso a los 15.","p":"Correcto. La licencia intermedia empieza a los 16."},"ref":{"doc":"KY","page":null}},{"id":"ky-005","scope":"KY","cat":"licensing","sign":null,"c":1,"en":{"q":"In Kentucky, how many hours of supervised driving must a teen complete before the road test?","o":["30 hours","60 hours","40 hours","100 hours"],"h1":"It is more than 50 and less than 70.","h2":"A Kentucky teen must complete 60 hours of supervised driving before the road test.","p":"Right. Kentucky asks for 60 supervised hours."},"es":{"q":"En Kentucky, ¿cuántas horas de manejo supervisado debe completar un joven antes del examen de manejo?","o":["30 horas","60 horas","40 horas","100 horas"],"h1":"Son más de 50 y menos de 70.","h2":"En Kentucky, un joven debe completar 60 horas de manejo supervisado antes del examen de manejo.","p":"Correcto. Kentucky pide 60 horas supervisadas."},"ref":{"doc":"KY","page":5}},{"id":"ky-006","scope":"KY","cat":"licensing","sign":null,"c":3,"en":{"q":"In Kentucky, how many of the supervised practice hours must be at night?","o":["5 hours","15 hours","20 hours","10 hours"],"h1":"It is one sixth of the 60 hours.","h2":"At least 10 of the 60 supervised hours in Kentucky must be driven at night.","p":"Right. Ten of the hours are at night."},"es":{"q":"En Kentucky, ¿cuántas de las horas de práctica supervisada deben ser de noche?","o":["5 horas","15 horas","20 horas","10 horas"],"h1":"Es la sexta parte de las 60 horas.","h2":"En Kentucky, por lo menos 10 de las 60 horas supervisadas deben ser de noche.","p":"Correcto. Diez de las horas son de noche."},"ref":{"doc":"KY","page":5}},{"id":"ky-007","scope":"KY","cat":"licensing","sign":null,"c":0,"en":{"q":"In Kentucky, how old must the licensed driver beside a permit holder be?","o":["At least 21","At least 16","At least 18","At least 25"],"h1":"The helper must be old enough to drink alcohol legally.","h2":"A Kentucky permit holder must drive with a licensed person who is at least 21, sitting in the seat beside them.","p":"Right. The person beside you must be 21 or older."},"es":{"q":"En Kentucky, ¿qué edad debe tener el conductor con licencia que va al lado de quien tiene permiso?","o":["Por lo menos 21","Por lo menos 16","Por lo menos 18","Por lo menos 25"],"h1":"El acompañante debe tener edad para tomar alcohol legalmente.","h2":"En Kentucky, quien tiene permiso debe manejar con una persona con licencia de por lo menos 21 años, sentada a su lado.","p":"Correcto. Su acompañante debe tener 21 años o más."},"ref":{"doc":"KY","page":5}},{"id":"ky-008","scope":"KY","cat":"licensing","sign":null,"c":2,"en":{"q":"In Kentucky, how does a teen show that the supervised practice hours were completed?","o":["With a note from a friend","With photos from a phone","With a practice driving log signed by a parent or guardian","Nothing is needed"],"h1":"It is a written record that a parent signs.","h2":"In Kentucky a parent or guardian signs a practice driving log that lists the 60 hours, and it is needed before the road test.","p":"Right. A practice driving log signed by a parent is needed."},"es":{"q":"En Kentucky, ¿cómo demuestra un joven que completó las horas de práctica supervisada?","o":["Con una nota de un amigo","Con fotos del teléfono","Con un registro de práctica firmado por un padre, madre o tutor","No se necesita nada"],"h1":"Es un registro escrito que firma un padre o una madre.","h2":"En Kentucky, un padre, madre o tutor firma un registro de práctica de manejo con las 60 horas, y se necesita antes del examen de manejo.","p":"Correcto. Se necesita un registro de práctica firmado por un padre o tutor."},"ref":{"doc":"KY","page":6}},{"id":"ky-009","scope":"KY","cat":"licensing","sign":null,"c":1,"en":{"q":"In Kentucky, when may a driver under 18 with an intermediate license not drive without good cause?","o":["Between 9 p.m. and 5 a.m.","Between midnight and 6 a.m.","Between 10 p.m. and 6 a.m.","Between 11 p.m. and 5 a.m."],"h1":"It starts at midnight.","h2":"A Kentucky intermediate license holder under 18 may not drive between midnight and 6 a.m. unless there is good cause, such as school, work or an emergency.","p":"Right. No driving from midnight to 6 a.m. without good cause."},"es":{"q":"En Kentucky, ¿en qué horario no puede manejar sin un buen motivo un menor de 18 años con licencia intermedia?","o":["Entre las 9 p.m. y las 5 a.m.","Entre la medianoche y las 6 a.m.","Entre las 10 p.m. y las 6 a.m.","Entre las 11 p.m. y las 5 a.m."],"h1":"Empieza a la medianoche.","h2":"En Kentucky, quien tiene licencia intermedia y es menor de 18 años no puede manejar entre la medianoche y las 6 a.m., salvo por un buen motivo como la escuela, el trabajo o una emergencia.","p":"Correcto. No se maneja de medianoche a 6 a.m. sin un buen motivo."},"ref":{"doc":"KY","page":6}},{"id":"ky-010","scope":"KY","cat":"licensing","sign":null,"c":3,"en":{"q":"In Kentucky, how many unrelated passengers under 20 may an intermediate license holder carry?","o":["None at all","No more than two","No more than three","No more than one"],"h1":"It is the smallest number that is not zero.","h2":"A Kentucky intermediate license holder may carry no more than one unrelated passenger under 20, unless a driving instructor is in the car.","p":"Right. Only one unrelated passenger under 20."},"es":{"q":"En Kentucky, ¿cuántos pasajeros menores de 20 años que no son familiares puede llevar quien tiene licencia intermedia?","o":["Ninguno","No más de dos","No más de tres","No más de uno"],"h1":"Es el número más pequeño que no es cero.","h2":"En Kentucky, quien tiene licencia intermedia puede llevar no más de un pasajero menor de 20 años que no sea familiar, salvo que vaya un instructor de manejo en el auto.","p":"Correcto. Solo un pasajero menor de 20 que no sea familiar."},"ref":{"doc":"KY","page":7}},{"id":"ky-011","scope":"KY","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Kentucky, when may a driver under 18 use a phone while the car is moving?","o":["Only to report an emergency","When using a hands-free device","When stopped at a red light only","Any time on a highway"],"h1":"The law has no hands-free exception for this age group.","h2":"A Kentucky driver under 18 may not use a phone at all while the car is moving, hands-free included, except to report an emergency.","p":"Right. Under 18, the phone is only for emergencies."},"es":{"q":"En Kentucky, ¿cuándo puede usar el teléfono un conductor menor de 18 años mientras el auto está en movimiento?","o":["Solo para reportar una emergencia","Cuando usa un dispositivo de manos libres","Solo cuando está parado en un semáforo en rojo","En cualquier momento en la autopista"],"h1":"La ley no hace excepción para el manos libres a esta edad.","h2":"En Kentucky, un conductor menor de 18 años no puede usar el teléfono mientras el auto está en movimiento, ni siquiera con manos libres, salvo para reportar una emergencia.","p":"Correcto. Si es menor de 18, el teléfono es solo para emergencias."},"ref":{"doc":"KY","page":null}},{"id":"ky-012","scope":"KY","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Kentucky, at what blood alcohol level is a driver under 21 breaking the law?","o":["0.05 percent","0.08 percent","0.02 percent","0.10 percent"],"h1":"Kentucky calls this zero tolerance. It is the smallest number here.","h2":"A Kentucky driver under 21 breaks the zero tolerance law with a blood alcohol level of 0.02 percent.","p":"Right. Under 21, the limit is 0.02 percent."},"es":{"q":"En Kentucky, ¿con qué nivel de alcohol en la sangre viola la ley un conductor menor de 21 años?","o":["0.05 por ciento","0.08 por ciento","0.02 por ciento","0.10 por ciento"],"h1":"Kentucky lo llama tolerancia cero. Es el número más pequeño.","h2":"En Kentucky, un conductor menor de 21 años viola la ley de tolerancia cero con un nivel de alcohol en la sangre de 0.02 por ciento.","p":"Correcto. Si es menor de 21, el límite es 0.02 por ciento."},"ref":{"doc":"KY","page":26}},{"id":"ky-013","scope":"KY","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Kentucky, what must you do when you approach a stopped emergency vehicle with flashing lights on the side of the road?","o":["Keep the same lane and speed","Move to the next lane away from it, or slow down if you cannot change lanes safely","Stop in your lane until it leaves","Honk to warn the workers"],"h1":"Give the workers more room, or go slower.","h2":"Kentucky law says to move to the lane away from a stopped emergency vehicle with flashing lights, and if that is not safe, to slow down and use caution.","p":"Right. Move over, or slow down."},"es":{"q":"En Kentucky, ¿qué debe hacer al acercarse a un vehículo de emergencia detenido al lado del camino con luces intermitentes?","o":["Seguir en el mismo carril y a la misma velocidad","Pasarse al carril de al lado, lejos de él, o bajar la velocidad si no puede cambiar de carril con seguridad","Detenerse en su carril hasta que se vaya","Tocar la bocina para avisar a los trabajadores"],"h1":"Dele más espacio a los trabajadores, o vaya más despacio.","h2":"La ley de Kentucky dice que debe pasarse al carril más lejano de un vehículo de emergencia detenido con luces intermitentes y, si no es seguro, bajar la velocidad con cuidado.","p":"Correcto. Cámbiese de carril o baje la velocidad."},"ref":{"doc":"KY","page":66}},{"id":"ky-014","scope":"KY","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Kentucky, since July 2026, a school bus is stopped with its stop arm out on the other side of a four-lane road with no median. What must you do?","o":["Keep driving, because the road has four lanes","Slow down and pass with care","Honk and pass","Stop, even though you are going the other way"],"h1":"The old four-lane exception was narrowed in 2026.","h2":"Since a 2026 Kentucky law, you must stop for a stopped school bus even on a four-lane road, unless a raised barrier or an unpaved median separates you from it.","p":"Right. A four-lane road alone is no longer an exception."},"es":{"q":"En Kentucky, desde julio de 2026, un autobús escolar está detenido con el brazo de alto extendido al otro lado de un camino de cuatro carriles sin camellón. ¿Qué debe hacer?","o":["Seguir manejando, porque el camino tiene cuatro carriles","Bajar la velocidad y pasar con cuidado","Tocar la bocina y pasar","Detenerse, aunque usted vaya en la dirección contraria"],"h1":"La antigua excepción de los cuatro carriles se redujo en 2026.","h2":"Desde una ley de Kentucky de 2026, usted debe detenerse ante un autobús escolar detenido aun en un camino de cuatro carriles, salvo que lo separe una barrera elevada o un camellón sin pavimentar.","p":"Correcto. Que el camino tenga cuatro carriles ya no es una excepción."},"ref":{"doc":"KY","page":44}},{"id":"ky-015","scope":"KY","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Kentucky, when may traffic going the other way pass a stopped school bus without stopping?","o":["When a raised barrier or an unpaved median separates the two sides of the road","When the road has four lanes or more","When the bus has no children in sight","When the driver is in a hurry"],"h1":"Something physical must separate the two directions.","h2":"In Kentucky, traffic going the other way may pass a stopped school bus only when a raised barrier or an unpaved median separates the two sides of the road.","p":"Right. Only a barrier or an unpaved median makes it an exception."},"es":{"q":"En Kentucky, ¿cuándo puede el tráfico que va en dirección contraria pasar un autobús escolar detenido sin detenerse?","o":["Cuando una barrera elevada o un camellón sin pavimentar separa los dos lados del camino","Cuando el camino tiene cuatro carriles o más","Cuando no se ven niños cerca del autobús","Cuando el conductor tiene prisa"],"h1":"Algo físico debe separar las dos direcciones.","h2":"En Kentucky, el tráfico en dirección contraria puede pasar un autobús escolar detenido solo cuando una barrera elevada o un camellón sin pavimentar separa los dos lados del camino.","p":"Correcto. Solo una barrera o un camellón sin pavimentar es una excepción."},"ref":{"doc":"KY","page":44}},{"id":"ky-016","scope":"KY","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Kentucky, what is the usual speed limit on interstates when no other limit is posted for that section?","o":["55 mph","75 mph","65 mph","80 mph"],"h1":"Some rural sections are raised by 5 mph above this number.","h2":"Kentucky interstates are usually 65 mph, and some rural sections are posted at 70 mph after a safety study.","p":"Right. The usual interstate limit is 65 mph."},"es":{"q":"En Kentucky, ¿cuál es el límite de velocidad habitual en las autopistas interestatales cuando no hay otro límite para ese tramo?","o":["55 mph","75 mph","65 mph","80 mph"],"h1":"En algunos tramos rurales se sube 5 mph sobre este número.","h2":"Las autopistas interestatales de Kentucky suelen tener un límite de 65 mph, y algunos tramos rurales tienen 70 mph después de un estudio de seguridad.","p":"Correcto. El límite habitual en la interestatal es 65 mph."},"ref":{"doc":"KY","page":49}},{"id":"ky-017","scope":"KY","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Kentucky, what is the highest speed limit posted on some rural interstate sections?","o":["65 mph","70 mph","75 mph","80 mph"],"h1":"It is 5 mph above the usual interstate limit.","h2":"Some rural interstate sections in Kentucky are posted at 70 mph, 5 mph above the usual 65 mph.","p":"Right. Some rural sections allow 70 mph."},"es":{"q":"En Kentucky, ¿cuál es el límite de velocidad más alto en algunos tramos rurales de autopistas interestatales?","o":["65 mph","70 mph","75 mph","80 mph"],"h1":"Son 5 mph más que el límite habitual de la interestatal.","h2":"Algunos tramos rurales de autopistas interestatales en Kentucky tienen un límite de 70 mph, 5 mph más que el habitual de 65 mph.","p":"Correcto. Algunos tramos rurales permiten 70 mph."},"ref":{"doc":"KY","page":49}},{"id":"ky-018","scope":"KY","cat":"licensing","sign":null,"c":3,"en":{"q":"In Kentucky, how long is an instruction permit valid since the 2025 law?","o":["One year","Two years","Three years","Four years"],"h1":"The 2025 law added one year to the old three years.","h2":"Since the 2025 law, a Kentucky instruction permit is valid for four years instead of three.","p":"Right. The permit is now valid for four years."},"es":{"q":"En Kentucky, ¿por cuánto tiempo es válido el permiso de instrucción desde la ley de 2025?","o":["Un año","Dos años","Tres años","Cuatro años"],"h1":"La ley de 2025 sumó un año a los tres años de antes.","h2":"Desde la ley de 2025, el permiso de instrucción de Kentucky es válido por cuatro años en lugar de tres.","p":"Correcto. Ahora el permiso es válido por cuatro años."},"ref":{"doc":"KY","page":null}},{"id":"ky-019","scope":"KY","cat":"licensing","sign":null,"c":0,"en":{"q":"In Kentucky, what score do you need to pass the written permit test?","o":["At least 80 percent","At least 60 percent","At least 70 percent","At least 90 percent"],"h1":"It is four out of every five answers.","h2":"You need at least 80 percent correct to pass the Kentucky written permit test.","p":"Right. The passing score is 80 percent."},"es":{"q":"En Kentucky, ¿qué puntaje necesita para aprobar el examen escrito del permiso?","o":["Por lo menos 80 por ciento","Por lo menos 60 por ciento","Por lo menos 70 por ciento","Por lo menos 90 por ciento"],"h1":"Son cuatro de cada cinco respuestas.","h2":"Usted necesita por lo menos 80 por ciento de respuestas correctas para aprobar el examen escrito del permiso en Kentucky.","p":"Correcto. Se aprueba con 80 por ciento."},"ref":{"doc":"KY","page":11}},{"id":"ky-020","scope":"KY","cat":"licensing","sign":null,"c":2,"en":{"q":"In Kentucky, which agency gives the written and road tests for a driver license?","o":["The county sheriff","The local school district","The Kentucky State Police","A private insurance company"],"h1":"It is a statewide police agency.","h2":"In Kentucky, the Kentucky State Police give the written and road tests for a driver license.","p":"Right. The State Police run driver testing."},"es":{"q":"En Kentucky, ¿qué agencia toma los exámenes escrito y de manejo para la licencia?","o":["El alguacil del condado","El distrito escolar local","La Policía Estatal de Kentucky","Una compañía de seguros privada"],"h1":"Es una policía de todo el estado.","h2":"En Kentucky, la Policía Estatal de Kentucky toma los exámenes escrito y de manejo para la licencia.","p":"Correcto. La Policía Estatal se encarga de los exámenes."},"ref":{"doc":"KY","page":4}},{"id":"ky-021","scope":"KY","cat":"licensing","sign":null,"c":1,"en":{"q":"In Kentucky, can you take the standard written driver test in Spanish?","o":["No, only in English","Yes, it is offered in Spanish","Only with a paid interpreter","Only after failing in English"],"h1":"Kentucky State Police list Spanish among the test languages.","h2":"Yes, the Kentucky State Police offer the standard written driver test in Spanish, and a Spanish driver manual is available too.","p":"Right. The standard test is offered in Spanish."},"es":{"q":"En Kentucky, ¿puede tomar en español el examen escrito estándar de manejo?","o":["No, solo en inglés","Sí, se ofrece en español","Solo con un intérprete pagado","Solo después de reprobar en inglés"],"h1":"La Policía Estatal de Kentucky incluye el español entre los idiomas del examen.","h2":"Sí, la Policía Estatal de Kentucky ofrece el examen escrito estándar de manejo en español, y también hay un manual del conductor en español.","p":"Correcto. El examen estándar se ofrece en español."},"ref":{"doc":"KY","page":11}},{"id":"la-001","scope":"LA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Louisiana, what is the youngest age to get a learner's permit?","o":["14 years old","15 years old","16 years old","17 years old"],"h1":"It is one year before the intermediate license.","h2":"In Louisiana you can get a learner's permit at 15, after a driver education course and the knowledge and vision tests.","p":"Right. The Louisiana learner's permit starts at 15."},"es":{"q":"En Luisiana, ¿cuál es la edad mínima para obtener un permiso de aprendiz?","o":["14 años","15 años","16 años","17 años"],"h1":"Es un año antes de la licencia intermedia.","h2":"En Luisiana usted puede obtener el permiso de aprendiz a los 15 años, después de un curso de manejo y los exámenes teórico y de la vista.","p":"Correcto. El permiso de aprendiz en Luisiana empieza a los 15."},"ref":{"doc":"LA","page":7}},{"id":"la-002","scope":"LA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Louisiana, how long is the approved driver education course a teen must finish before the learner's permit?","o":["8 hours","16 hours","24 hours","38 hours"],"h1":"It is a little under 40 hours.","h2":"In Louisiana a teen must finish a 38-hour driver education course before the learner's permit: 30 hours in class and 8 hours behind the wheel.","p":"Right. The course is 38 hours."},"es":{"q":"En Luisiana, ¿cuántas horas dura el curso de manejo aprobado que un joven debe terminar antes del permiso de aprendiz?","o":["8 horas","16 horas","24 horas","38 horas"],"h1":"Son un poco menos de 40 horas.","h2":"En Luisiana un adolescente debe terminar un curso de manejo de 38 horas antes del permiso de aprendiz: 30 horas en clase y 8 horas al volante.","p":"Correcto. El curso es de 38 horas."},"ref":{"doc":"LA","page":7}},{"id":"la-003","scope":"LA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Louisiana, how long must you hold a learner's permit before you can get an intermediate license?","o":["At least 180 days","At least 30 days","At least 90 days","At least two years"],"h1":"It is about six months.","h2":"In Louisiana you must hold the learner's permit for at least 180 days before you can get an intermediate license.","p":"Right. Hold the permit at least 180 days."},"es":{"q":"En Luisiana, ¿cuánto tiempo debe tener el permiso de aprendiz antes de obtener la licencia intermedia?","o":["Por lo menos 180 días","Por lo menos 30 días","Por lo menos 90 días","Por lo menos dos años"],"h1":"Son unos seis meses.","h2":"En Luisiana usted debe tener el permiso de aprendiz por lo menos 180 días antes de obtener la licencia intermedia.","p":"Correcto. Debe tener el permiso por lo menos 180 días."},"ref":{"doc":"LA","page":7}},{"id":"la-004","scope":"LA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Louisiana, how old must a licensed adult be to supervise a driver with a learner's permit?","o":["At least 18","At least 25","At least 21","At least 30"],"h1":"It is the legal drinking age.","h2":"In Louisiana a learner must drive with a licensed adult who is at least 21, or with a licensed brother or sister who is at least 18.","p":"Right. A supervising adult must be 21 or older."},"es":{"q":"En Luisiana, ¿qué edad debe tener un adulto con licencia para supervisar a un conductor con permiso de aprendiz?","o":["Por lo menos 18","Por lo menos 25","Por lo menos 21","Por lo menos 30"],"h1":"Es la edad legal para tomar alcohol.","h2":"En Luisiana un aprendiz debe manejar con un adulto con licencia de por lo menos 21 años, o con un hermano o hermana con licencia de por lo menos 18.","p":"Correcto. El adulto que supervisa debe tener 21 años o más."},"ref":{"doc":"LA","page":7}},{"id":"la-005","scope":"LA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Louisiana, which family member may supervise a learner even though he or she is younger than 21?","o":["A licensed cousin who is 16","A licensed brother or sister who is at least 18","A grandparent without a license","Any sibling of any age"],"h1":"This person has a license and is an adult, but is not yet 21.","h2":"In Louisiana a licensed brother or sister who is at least 18 may supervise a learner's permit driver.","p":"Right. A licensed sibling 18 or older may ride with you."},"es":{"q":"En Luisiana, ¿qué familiar puede supervisar a un aprendiz aunque tenga menos de 21 años?","o":["Un primo con licencia de 16 años","Un hermano o hermana con licencia de por lo menos 18 años","Un abuelo sin licencia","Cualquier hermano de cualquier edad"],"h1":"Esta persona tiene licencia y es adulta, pero todavía no tiene 21.","h2":"En Luisiana un hermano o hermana con licencia de por lo menos 18 años puede supervisar a un conductor con permiso de aprendiz.","p":"Correcto. Un hermano con licencia de 18 años o más puede acompañarle."},"ref":{"doc":"LA","page":7}},{"id":"la-006","scope":"LA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Louisiana, how many hours of supervised driving must a learner log before the intermediate license?","o":["20 hours","30 hours","40 hours","50 hours"],"h1":"It is the same total many states use, half of one hundred.","h2":"In Louisiana a learner must log 50 hours of supervised driving before getting an intermediate license.","p":"Right. 50 supervised hours."},"es":{"q":"En Luisiana, ¿cuántas horas de manejo supervisado debe registrar un aprendiz antes de la licencia intermedia?","o":["20 horas","30 horas","40 horas","50 horas"],"h1":"Es el mismo total que usan muchos estados, la mitad de cien.","h2":"En Luisiana un aprendiz debe registrar 50 horas de manejo supervisado antes de obtener la licencia intermedia.","p":"Correcto. 50 horas supervisadas."},"ref":{"doc":"LA","page":7}},{"id":"la-007","scope":"LA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Louisiana, how many of the supervised practice hours must be at night?","o":["15 hours","5 hours","10 hours","25 hours"],"h1":"It is a little less than one third of the 50 hours.","h2":"In Louisiana 15 of the 50 supervised practice hours must be driven at night.","p":"Right. 15 of the hours are at night."},"es":{"q":"En Luisiana, ¿cuántas de las horas de práctica supervisada deben ser de noche?","o":["15 horas","5 horas","10 horas","25 horas"],"h1":"Es un poco menos de un tercio de las 50 horas.","h2":"En Luisiana 15 de las 50 horas de práctica supervisada deben ser de noche.","p":"Correcto. 15 de las horas son de noche."},"ref":{"doc":"LA","page":7}},{"id":"la-008","scope":"LA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Louisiana, who may send or read a text message while driving?","o":["Drivers 18 and older","Drivers on a highway only","No driver, of any age","Drivers stopped at a red light"],"h1":"The rule is the same for every age.","h2":"In Louisiana no driver of any age may write, send or read a text message while driving.","p":"Right. No driver may text while driving."},"es":{"q":"En Luisiana, ¿quién puede enviar o leer un mensaje de texto mientras maneja?","o":["Los conductores de 18 años o más","Solo los conductores en la carretera","Ningún conductor, de ninguna edad","Los conductores detenidos en un semáforo en rojo"],"h1":"La regla es igual para todas las edades.","h2":"En Luisiana ningún conductor, de ninguna edad, puede escribir, enviar ni leer un mensaje de texto mientras maneja.","p":"Correcto. Ningún conductor puede enviar textos mientras maneja."},"ref":{"doc":"LA","page":78}},{"id":"la-009","scope":"LA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Louisiana, during which hours may an intermediate license holder not drive without a qualified adult?","o":["9 p.m. to 6 a.m.","11 p.m. to 5 a.m.","Midnight to 6 a.m.","1 a.m. to 5 a.m."],"h1":"It starts one hour before midnight.","h2":"In Louisiana an intermediate license holder may not drive from 11 p.m. to 5 a.m. unless a qualified licensed adult is in the car.","p":"Right. The restricted hours are 11 p.m. to 5 a.m."},"es":{"q":"En Luisiana, ¿en qué horario no puede manejar sin un adulto calificado quien tiene licencia intermedia?","o":["De 9 p.m. a 6 a.m.","De 11 p.m. a 5 a.m.","De medianoche a 6 a.m.","De 1 a.m. a 5 a.m."],"h1":"Empieza una hora antes de la medianoche.","h2":"En Luisiana quien tiene licencia intermedia no puede manejar de 11 p.m. a 5 a.m. salvo que vaya en el carro un adulto con licencia calificado.","p":"Correcto. El horario restringido es de 11 p.m. a 5 a.m."},"ref":{"doc":"LA","page":7}},{"id":"la-010","scope":"LA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Louisiana, who may ride with an intermediate license holder so the teen may drive between 11 p.m. and 5 a.m.?","o":["Any friend over 16","A passenger with a permit","No one; driving at those hours is never allowed","A licensed parent or guardian, a licensed adult 21 or older, or a licensed sibling 18 or older"],"h1":"It is the same kind of person who may supervise a learner.","h2":"In Louisiana an intermediate driver may drive between 11 p.m. and 5 a.m. with a licensed parent or guardian, a licensed adult 21 or older, or a licensed sibling 18 or older.","p":"Right. A qualified licensed adult makes night driving allowed."},"es":{"q":"En Luisiana, ¿quién debe ir con un conductor con licencia intermedia para que pueda manejar entre 11 p.m. y 5 a.m.?","o":["Cualquier amigo mayor de 16","Un pasajero con permiso","Nadie; nunca se permite manejar a esas horas","Su padre, madre o tutor con licencia, un adulto con licencia de 21 años o más, o un hermano con licencia de 18 años o más"],"h1":"Es el mismo tipo de persona que puede supervisar a un aprendiz.","h2":"En Luisiana un conductor con licencia intermedia puede manejar entre 11 p.m. y 5 a.m. con su padre, madre o tutor con licencia, un adulto con licencia de 21 años o más, o un hermano con licencia de 18 años o más.","p":"Correcto. Un adulto calificado con licencia permite manejar de noche."},"ref":{"doc":"LA","page":7}},{"id":"la-011","scope":"LA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Louisiana, between 6 p.m. and 5 a.m., how many passengers under 21 who are not immediate family may an intermediate driver carry?","o":["No more than one","No more than three","Any number","No more than two"],"h1":"The limit applies in the evening and at night.","h2":"In Louisiana an intermediate driver may carry no more than one passenger under 21, not counting immediate family, between 6 p.m. and 5 a.m.","p":"Right. Only one young passenger in the evening and at night."},"es":{"q":"En Luisiana, entre las 6 p.m. y las 5 a.m., ¿cuántos pasajeros menores de 21 que no son familia inmediata puede llevar un conductor con licencia intermedia?","o":["No más de uno","No más de tres","Cualquier cantidad","No más de dos"],"h1":"El límite se aplica en la tarde y de noche.","h2":"En Luisiana un conductor con licencia intermedia no puede llevar más de un pasajero menor de 21, sin contar la familia inmediata, entre las 6 p.m. y las 5 a.m.","p":"Correcto. Solo un pasajero joven en la tarde y de noche."},"ref":{"doc":"LA","page":7}},{"id":"la-012","scope":"LA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Louisiana, at what age can a driver move up to a full Class E license?","o":["16","18","17","21"],"h1":"It is one year after the intermediate license.","h2":"In Louisiana a driver can get a full Class E license at 17.","p":"Right. The full Class E license comes at 17."},"es":{"q":"En Luisiana, ¿a qué edad puede un conductor pasar a la licencia completa Clase E?","o":["16","18","17","21"],"h1":"Es un año después de la licencia intermedia.","h2":"En Luisiana un conductor puede obtener la licencia completa Clase E a los 17 años.","p":"Correcto. La licencia completa Clase E llega a los 17."},"ref":{"doc":"LA","page":7}},{"id":"la-013","scope":"LA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Louisiana, which record must a learner have to move up to an intermediate license?","o":["At least one safe-driving award","No at-fault crashes and no moving violations while on the permit","A perfect score on the knowledge test","At least two years with the permit"],"h1":"Think about what happened on the road during the permit.","h2":"In Louisiana a learner needs no at-fault crashes and no moving violations on the permit to get an intermediate license.","p":"Right. A clean permit record is required."},"es":{"q":"En Luisiana, ¿qué historial debe tener un aprendiz para pasar a la licencia intermedia?","o":["Por lo menos un premio de manejo seguro","Ningún choque por su culpa y ninguna infracción de tránsito con el permiso","Una calificación perfecta en el examen teórico","Por lo menos dos años con el permiso"],"h1":"Piense en lo que pasó en la carretera durante el permiso.","h2":"En Luisiana un aprendiz no debe tener choques por su culpa ni infracciones de tránsito con el permiso para obtener la licencia intermedia.","p":"Correcto. Se requiere un historial limpio con el permiso."},"ref":{"doc":"LA","page":null}},{"id":"la-014","scope":"LA","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Louisiana, at what blood alcohol level is it illegal for a driver under 21 to drive?","o":["0.08 percent","0.10 percent","0.05 percent","0.02 percent"],"h1":"It is much lower than the adult limit of 0.08.","h2":"In Louisiana it is illegal for a driver under 21 to drive with a blood alcohol level of 0.02 percent or more.","p":"Right. For drivers under 21 the limit is 0.02."},"es":{"q":"En Luisiana, ¿con qué nivel de alcohol en la sangre es ilegal que maneje un conductor menor de 21?","o":["0.08 por ciento","0.10 por ciento","0.05 por ciento","0.02 por ciento"],"h1":"Es mucho más bajo que el límite de 0.08 para adultos.","h2":"En Luisiana es ilegal que un conductor menor de 21 maneje con un nivel de alcohol en la sangre de 0.02 por ciento o más.","p":"Correcto. Para menores de 21 el límite es 0.02."},"ref":{"doc":"LA","page":123}},{"id":"la-015","scope":"LA","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Louisiana, what does the law say about adult drivers and phones?","o":["Most phone use is banned while driving, but hands-free calls and navigation are allowed","All phone use is allowed","Texting is allowed below 25 mph","Phones are allowed only on interstates"],"h1":"Your hands should stay off the phone.","h2":"In Louisiana most phone use while driving is banned, but hands-free calls and navigation are still allowed.","p":"Right. Hands off the phone; hands-free is allowed."},"es":{"q":"En Luisiana, ¿qué dice la ley sobre los conductores adultos y los teléfonos?","o":["Se prohíbe casi todo uso del teléfono al manejar, pero se permiten llamadas con manos libres y la navegación","Se permite todo uso del teléfono","Se permite enviar mensajes por debajo de 25 mph","Solo se permite en las autopistas interestatales"],"h1":"Sus manos no deben tocar el teléfono.","h2":"En Luisiana se prohíbe casi todo uso del teléfono mientras maneja, pero todavía se permiten las llamadas con manos libres y la navegación.","p":"Correcto. Sin el teléfono en la mano; manos libres sí está permitido."},"ref":{"doc":"LA","page":78}},{"id":"la-016","scope":"LA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Louisiana, what is the fine for using a hand-held phone while driving outside a school or construction zone, when there is no crash?","o":["$25","$500","$100","$1,000"],"h1":"In a school or construction zone the fine is $250.","h2":"In Louisiana the fine for using a hand-held phone while driving outside a school or construction zone is $100, and it doubles if there is a crash.","p":"Right. The fine is $100 outside those zones."},"es":{"q":"En Luisiana, ¿cuál es la multa por usar un teléfono en la mano mientras maneja fuera de una zona escolar o de construcción, si no hay choque?","o":["$25","$500","$100","$1,000"],"h1":"En una zona escolar o de construcción la multa es de $250.","h2":"En Luisiana la multa por usar un teléfono en la mano mientras maneja fuera de una zona escolar o de construcción es de $100, y se duplica si hay un choque.","p":"Correcto. La multa es de $100 fuera de esas zonas."},"ref":{"doc":"LA","page":null}},{"id":"la-017","scope":"LA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Louisiana, what is the fine for using a hand-held phone while driving in a school or construction zone, when there is no crash?","o":["$75","$250","$50","$2,000"],"h1":"It is more than twice the $100 fine outside those zones.","h2":"In Louisiana the fine for using a hand-held phone while driving in a school or construction zone is $250.","p":"Right. The fine is $250 in a school or work zone."},"es":{"q":"En Luisiana, ¿cuál es la multa por usar un teléfono en la mano mientras maneja en una zona escolar o de construcción, si no hay choque?","o":["$75","$250","$50","$2,000"],"h1":"Es más del doble de la multa de $100 fuera de esas zonas.","h2":"En Luisiana la multa por usar un teléfono en la mano mientras maneja en una zona escolar o de construcción es de $250.","p":"Correcto. La multa es de $250 en una zona escolar o de obras."},"ref":{"doc":"LA","page":null}},{"id":"la-019","scope":"LA","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Louisiana, what should you do under the Move Over law on a two-lane road where you cannot change lanes?","o":["Slow down","Keep the same speed","Honk your horn","Stop in your lane"],"h1":"If you cannot move away, change something else.","h2":"In Louisiana, when you cannot change lanes, such as on a two-lane road, you must slow down as you pass the stopped vehicle.","p":"Right. If you cannot move over, slow down."},"es":{"q":"En Luisiana, según la ley \"Move Over\", ¿qué debe hacer en una carretera de dos carriles donde no puede cambiarse de carril?","o":["Bajar la velocidad","Seguir a la misma velocidad","Tocar la bocina","Detenerse en su carril"],"h1":"Si no puede alejarse, cambie otra cosa.","h2":"En Luisiana, cuando no puede cambiarse de carril, por ejemplo en una carretera de dos carriles, debe bajar la velocidad al pasar el vehículo detenido.","p":"Correcto. Si no puede cambiarse de carril, baje la velocidad."},"ref":{"doc":"LA","page":30}},{"id":"la-020","scope":"LA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Louisiana, what is the youngest age to get an intermediate license?","o":["15","17","16","18"],"h1":"It is one year after the earliest learner's permit.","h2":"In Louisiana you can get an intermediate license at 16, after holding the learner's permit for at least 180 days.","p":"Right. The intermediate license starts at 16."},"es":{"q":"En Luisiana, ¿cuál es la edad mínima para obtener la licencia intermedia?","o":["15","17","16","18"],"h1":"Es un año después de la edad mínima para el permiso de aprendiz.","h2":"En Luisiana usted puede obtener la licencia intermedia a los 16 años, después de tener el permiso de aprendiz por lo menos 180 días.","p":"Correcto. La licencia intermedia empieza a los 16."},"ref":{"doc":"LA","page":7}},{"id":"ma-001","scope":"MA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Massachusetts, what is the youngest age to apply for a learner's permit?","o":["14 years old","15 years old","16 years old","17 years old"],"h1":"It is later than in many other states.","h2":"In Massachusetts you can apply for a learner's permit at age 16, which is later than in many other states.","p":"Right. The Massachusetts learner's permit starts at age 16."},"es":{"q":"En Massachusetts, ¿cuál es la edad mínima para solicitar el permiso de aprendiz?","o":["14 años","15 años","16 años","17 años"],"h1":"Es más tarde que en muchos otros estados.","h2":"En Massachusetts usted puede solicitar el permiso de aprendiz a los 16 años, más tarde que en muchos otros estados.","p":"Correcto. El permiso de aprendiz en Massachusetts empieza a los 16 años."},"ref":{"doc":"MA","page":15}},{"id":"ma-002","scope":"MA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Massachusetts, who must sit beside a learner's permit holder while driving?","o":["A licensed driver 21+ with 1 year of experience","Any licensed driver age 18 or older","Any adult, licensed or not","A licensed driver 25+ with 5 years of experience"],"h1":"The helper must be over 21 and must have driven for some time.","h2":"A Massachusetts permit holder must drive with a licensed driver who is at least 21 and has at least one year of driving experience in the seat beside them, so an experienced adult can help.","p":"Right. The helper is 21 or older with a year of experience."},"es":{"q":"En Massachusetts, ¿quién debe ir sentado al lado de quien tiene permiso de aprendiz?","o":["Un conductor con licencia de 21+ y 1 año de experiencia","Cualquier conductor con licencia de 18 años o más","Cualquier adulto, con o sin licencia","Un conductor con licencia de 25+ y 5 años de experiencia"],"h1":"El acompañante debe tener más de 21 años y haber manejado un tiempo.","h2":"En Massachusetts quien tiene permiso de aprendiz debe manejar con un conductor con licencia de por lo menos 21 años y un año de experiencia en el asiento de al lado, para que un adulto con experiencia lo ayude.","p":"Correcto. El acompañante tiene 21 años o más y un año de experiencia."},"ref":{"doc":"MA","page":18}},{"id":"ma-003","scope":"MA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Massachusetts, a permit holder under 18 may not drive during which hours unless a parent or guardian is in the car?","o":["From 9 p.m. to 5 a.m.","From 10 p.m. to 6 a.m.","From 11 p.m. to 6 a.m.","From midnight to 5 a.m."],"h1":"It starts when the date changes.","h2":"A Massachusetts permit holder under 18 may not drive between midnight and 5 a.m. unless a parent or guardian is with them, because late-night driving is the riskiest for new drivers.","p":"Right. No driving from midnight to 5 a.m. without a parent or guardian."},"es":{"q":"En Massachusetts, ¿en qué horario no puede manejar un aprendiz menor de 18 años si no va con él un padre o tutor?","o":["De 9 p.m. a 5 a.m.","De 10 p.m. a 6 a.m.","De 11 p.m. a 6 a.m.","De medianoche a 5 a.m."],"h1":"Empieza cuando cambia la fecha.","h2":"En Massachusetts un aprendiz menor de 18 años no puede manejar entre la medianoche y las 5 a.m. si no va con él un padre o tutor, porque manejar de madrugada es lo más riesgoso para un conductor nuevo.","p":"Correcto. No se maneja de medianoche a 5 a.m. sin un padre o tutor."},"ref":{"doc":"MA","page":18}},{"id":"ma-004","scope":"MA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Massachusetts, how long is a learner's permit valid?","o":["Up to one year","Up to two years","Up to four years","Up to five years"],"h1":"It lasts longer than one year.","h2":"A Massachusetts learner's permit is valid for up to two years, which gives enough time to finish driver education and practice.","p":"Right. The permit is valid for up to two years."},"es":{"q":"En Massachusetts, ¿por cuánto tiempo es válido el permiso de aprendiz?","o":["Hasta un año","Hasta dos años","Hasta cuatro años","Hasta cinco años"],"h1":"Dura más de un año.","h2":"En Massachusetts el permiso de aprendiz es válido hasta por dos años, lo que da tiempo suficiente para terminar la educación vial y practicar.","p":"Correcto. El permiso es válido hasta por dos años."},"ref":{"doc":"MA","page":15}},{"id":"ma-005","scope":"MA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Massachusetts, how many questions must you answer correctly to pass the 25-question learner's permit exam?","o":["15 questions","16 questions","18 questions","20 questions"],"h1":"It is fewer than 20.","h2":"To pass the Massachusetts learner's permit exam you must answer at least 18 of the 25 questions correctly within the time allowed.","p":"Right. You need 18 correct answers out of 25."},"es":{"q":"En Massachusetts, ¿cuántas preguntas debe contestar bien para aprobar el examen de permiso de aprendiz de 25 preguntas?","o":["15 preguntas","16 preguntas","18 preguntas","20 preguntas"],"h1":"Son menos de 20.","h2":"Para aprobar el examen de permiso de aprendiz de Massachusetts usted debe contestar bien por lo menos 18 de las 25 preguntas dentro del tiempo permitido.","p":"Correcto. Necesita 18 respuestas correctas de 25."},"ref":{"doc":"MA","page":16}},{"id":"ma-006","scope":"MA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Massachusetts, can you take the learner's permit exam in Spanish?","o":["Yes, Spanish is offered","No, it is English only","Only after failing in English","Only with a private tutor"],"h1":"The RMV offers the exam in many languages.","h2":"The Massachusetts learner's permit exam is offered in Spanish and many other languages, so you can take it in the language you read best.","p":"Right. You can take the Massachusetts permit exam in Spanish."},"es":{"q":"En Massachusetts, ¿se puede tomar el examen de permiso de aprendiz en español?","o":["Sí, se ofrece en español","No, solo en inglés","Solo si reprueba en inglés","Solo con un tutor privado"],"h1":"El RMV ofrece el examen en muchos idiomas.","h2":"En Massachusetts el examen de permiso de aprendiz se ofrece en español y en muchos otros idiomas, así que usted puede tomarlo en el idioma que lee mejor.","p":"Correcto. Puede tomar el examen de permiso de Massachusetts en español."},"ref":{"doc":"MA","page":17}},{"id":"ma-007","scope":"MA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Massachusetts, how long must you hold a learner's permit before the road test for a Junior Operator License?","o":["At least 1 month","At least 3 months","At least 12 months","At least 6 months"],"h1":"It is half a year, without a break.","h2":"In Massachusetts you must hold a valid learner's permit for at least six months in a row before the Junior Operator road test, and a suspension starts that time over.","p":"Right. Six months in a row with the permit."},"es":{"q":"En Massachusetts, ¿cuánto tiempo debe tener el permiso de aprendiz antes del examen de manejo para la licencia de operador joven (JOL)?","o":["Por lo menos 1 mes","Por lo menos 3 meses","Por lo menos 12 meses","Por lo menos 6 meses"],"h1":"Es medio año, sin interrupción.","h2":"En Massachusetts usted debe tener un permiso de aprendiz válido por lo menos seis meses seguidos antes del examen de manejo para la JOL, y una suspensión hace que ese tiempo empiece de nuevo.","p":"Correcto. Seis meses seguidos con el permiso."},"ref":{"doc":"MA","page":9}},{"id":"ma-008","scope":"MA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Massachusetts, how many hours of supervised driving must a parent or guardian certify for a Junior Operator License?","o":["20 hours","40 hours","50 hours","60 hours"],"h1":"It is fewer than 50 hours.","h2":"A Massachusetts Junior Operator applicant needs at least 40 hours of supervised driving, certified by a parent or guardian, in addition to driver education.","p":"Right. Forty hours of supervised driving."},"es":{"q":"En Massachusetts, ¿cuántas horas de manejo supervisado debe certificar un padre o tutor para la licencia de operador joven (JOL)?","o":["20 horas","40 horas","50 horas","60 horas"],"h1":"Son menos de 50 horas.","h2":"En Massachusetts quien solicita la JOL necesita por lo menos 40 horas de manejo supervisado, certificadas por un padre o tutor, además de la educación vial.","p":"Correcto. Cuarenta horas de manejo supervisado."},"ref":{"doc":"MA","page":10}},{"id":"ma-009","scope":"MA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Massachusetts, the supervised driving hours drop to how many if the teen completes a driver skills development program?","o":["10 hours","20 hours","30 hours","35 hours"],"h1":"It is 10 hours less than the usual amount.","h2":"In Massachusetts a teen who completes a driver skills development program needs 30 supervised hours instead of 40.","p":"Right. Thirty hours after a driver skills program."},"es":{"q":"En Massachusetts, si el joven completa un programa de desarrollo de destrezas de manejo, ¿a cuántas horas baja el manejo supervisado?","o":["10 horas","20 horas","30 horas","35 horas"],"h1":"Son 10 horas menos de lo normal.","h2":"En Massachusetts un joven que completa un programa de desarrollo de destrezas de manejo necesita 30 horas supervisadas en lugar de 40.","p":"Correcto. Treinta horas después de un programa de destrezas."},"ref":{"doc":"MA","page":10}},{"id":"ma-010","scope":"MA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Massachusetts, how many hours of classroom instruction does driver education include for teens?","o":["20 hours","30 hours","40 hours","12 hours"],"h1":"It is the same number as the reduced supervised hours.","h2":"Massachusetts driver education for teens includes 30 hours of classroom instruction on state traffic law and safe driving.","p":"Right. Thirty hours in the classroom."},"es":{"q":"En Massachusetts, ¿cuántas horas de clase en el aula incluye la educación vial para jóvenes?","o":["20 horas","30 horas","40 horas","12 horas"],"h1":"Es el mismo número que las horas supervisadas reducidas.","h2":"En Massachusetts la educación vial para jóvenes incluye 30 horas de clase en el aula sobre las leyes de tránsito del estado y el manejo seguro.","p":"Correcto. Treinta horas en el aula."},"ref":{"doc":"MA","page":10}},{"id":"ma-011","scope":"MA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Massachusetts, how many hours of behind-the-wheel training with a driving school are required in teen driver education?","o":["12 hours","6 hours","18 hours","30 hours"],"h1":"The on-road part is 18 hours in all, and 6 of those are watching another student.","h2":"Massachusetts teen driver education requires at least 12 hours of behind-the-wheel training, plus 6 hours of watching another student drive.","p":"Right. Twelve hours behind the wheel."},"es":{"q":"En Massachusetts, ¿cuántas horas de práctica al volante con una escuela de manejo exige la educación vial para jóvenes?","o":["12 horas","6 horas","18 horas","30 horas"],"h1":"La parte en la calle suma 18 horas, y 6 de ellas son para observar a otro estudiante.","h2":"En Massachusetts la educación vial para jóvenes exige por lo menos 12 horas al volante, más 6 horas observando a otro estudiante manejar.","p":"Correcto. Doce horas al volante."},"ref":{"doc":"MA","page":10}},{"id":"ma-012","scope":"MA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Massachusetts, what must a parent or guardian of a teen in driver education usually complete?","o":["A written road test","A 10-hour driving course","A first-aid class","A 2-hour parent class"],"h1":"It is a short class about the driver education course.","h2":"In Massachusetts a parent or guardian must take a 2-hour class about the driver education course, unless they took one in the past five years.","p":"Right. Parents take a 2-hour class."},"es":{"q":"En Massachusetts, ¿qué debe completar normalmente el padre o tutor de un joven en educación vial?","o":["Un examen escrito de manejo","Un curso de manejo de 10 horas","Una clase de primeros auxilios","Una clase para padres de 2 horas"],"h1":"Es una clase corta sobre el curso de educación vial.","h2":"En Massachusetts el padre o tutor debe tomar una clase de 2 horas sobre el curso de educación vial, a menos que haya tomado una en los últimos cinco años.","p":"Correcto. Los padres toman una clase de 2 horas."},"ref":{"doc":"MA","page":10}},{"id":"ma-013","scope":"MA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Massachusetts, a Junior Operator License holder may not drive during which hours unless a parent or guardian is in the car?","o":["From midnight to 6 a.m.","From 11 p.m. to 5 a.m.","From 12:30 a.m. to 5 a.m.","From 1 a.m. to 6 a.m."],"h1":"It starts half an hour after midnight.","h2":"A Massachusetts Junior Operator may not drive between 12:30 a.m. and 5 a.m. unless a parent or legal guardian is with them.","p":"Right. No driving from 12:30 to 5 a.m. without a parent or guardian."},"es":{"q":"En Massachusetts, ¿en qué horario no puede manejar quien tiene licencia de operador joven (JOL) si no va con él un padre o tutor?","o":["De medianoche a 6 a.m.","De 11 p.m. a 5 a.m.","De 12:30 a.m. a 5 a.m.","De 1 a.m. a 6 a.m."],"h1":"Empieza media hora después de la medianoche.","h2":"En Massachusetts un operador joven no puede manejar entre las 12:30 a.m. y las 5 a.m. si no va con él un padre o tutor legal.","p":"Correcto. No se maneja de 12:30 a 5 a.m. sin un padre o tutor."},"ref":{"doc":"MA","page":10}},{"id":"ma-014","scope":"MA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Massachusetts, during the first six months with a Junior Operator License, who may not ride with you unless an adult 21+ is beside you?","o":["Passengers under 18 who are not family","Any passenger over age 65","Your brothers and sisters","Any passenger at all"],"h1":"The rule is about young friends, not family.","h2":"For the first six months, a Massachusetts Junior Operator may not carry passengers under 18 who are not immediate family unless a licensed adult age 21 or older is beside them.","p":"Right. No young non-family passengers in the first six months."},"es":{"q":"En Massachusetts, durante los primeros seis meses con licencia de operador joven, ¿quién no puede ir con usted si no hay un adulto de 21+ a su lado?","o":["Pasajeros menores de 18 que no son familia","Cualquier pasajero mayor de 65 años","Sus hermanos y hermanas","Ningún pasajero en absoluto"],"h1":"La regla es sobre amigos jóvenes, no sobre la familia.","h2":"Durante los primeros seis meses, un operador joven en Massachusetts no puede llevar pasajeros menores de 18 que no sean familia directa, a menos que vaya a su lado un adulto con licencia de 21 años o más.","p":"Correcto. Nada de pasajeros jóvenes que no son familia los primeros seis meses."},"ref":{"doc":"MA","page":10}},{"id":"ma-015","scope":"MA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Massachusetts, what is the license suspension for a Junior Operator's first speeding offense?","o":["30 days","60 days","1 year","90 days"],"h1":"It is about three months.","h2":"In Massachusetts a Junior Operator's first speeding offense brings a 90-day license suspension, and a second offense brings one year.","p":"Right. A first speeding offense means 90 days without a license."},"es":{"q":"En Massachusetts, ¿cuánto dura la suspensión de la licencia de un operador joven por su primera multa por exceso de velocidad?","o":["30 días","60 días","1 año","90 días"],"h1":"Son unos tres meses.","h2":"En Massachusetts la primera infracción por exceso de velocidad de un operador joven trae una suspensión de 90 días, y la segunda trae un año.","p":"Correcto. La primera multa por velocidad significa 90 días sin licencia."},"ref":{"doc":"MA","page":11}},{"id":"ma-016","scope":"MA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Massachusetts, what is the suspension for a Junior Operator's first passenger or night-time violation?","o":["30 days","60 days","90 days","180 days"],"h1":"It is two months.","h2":"A Massachusetts Junior Operator who breaks the passenger or night-time rule for the first time loses the license for 60 days.","p":"Right. Sixty days for a first passenger or night violation."},"es":{"q":"En Massachusetts, ¿cuál es la suspensión por la primera infracción de pasajeros o de horario nocturno de un operador joven?","o":["30 días","60 días","90 días","180 días"],"h1":"Son dos meses.","h2":"En Massachusetts un operador joven que no cumple por primera vez la regla de pasajeros o de horario nocturno pierde la licencia por 60 días.","p":"Correcto. Sesenta días por la primera infracción de pasajeros o de noche."},"ref":{"doc":"MA","page":11}},{"id":"ma-017","scope":"MA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Massachusetts, may a driver under 18 talk on a phone in hands-free mode while driving?","o":["Yes, with a headset only","Yes, on the highway only","No, except to report an emergency","Yes, if a parent calls"],"h1":"Drivers under 18 have a stricter rule than adults.","h2":"In Massachusetts a driver under 18 may not use any phone or mobile device while driving, even hands-free, except to report an emergency.","p":"Right. Drivers under 18 may not use a phone at all, except for emergencies."},"es":{"q":"En Massachusetts, ¿puede un conductor menor de 18 años hablar por teléfono en modo manos libres mientras maneja?","o":["Sí, solo con auriculares","Sí, solo en la autopista","No, salvo para reportar una emergencia","Sí, si llaman sus padres"],"h1":"Los menores de 18 tienen una regla más estricta que los adultos.","h2":"En Massachusetts un conductor menor de 18 años no puede usar ningún teléfono ni aparato móvil mientras maneja, ni siquiera con manos libres, salvo para reportar una emergencia.","p":"Correcto. Los menores de 18 no usan el teléfono, salvo en emergencias."},"ref":{"doc":"MA","page":40}},{"id":"ma-018","scope":"MA","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Massachusetts, how may an adult driver use a phone while driving?","o":["Only in hands-free mode","Holding it at red lights","Holding it on quiet streets","Holding it for short calls"],"h1":"Your hands stay on the wheel.","h2":"Massachusetts law lets adult drivers use a phone only in hands-free mode, with the phone mounted, and allows a single touch to start hands-free mode.","p":"Right. Adults may use a phone only hands-free."},"es":{"q":"En Massachusetts, ¿cómo puede un conductor adulto usar el teléfono mientras maneja?","o":["Solo en modo manos libres","Sosteniéndolo en los semáforos","Sosteniéndolo en calles tranquilas","Sosteniéndolo en llamadas cortas"],"h1":"Sus manos se quedan en el volante.","h2":"La ley de Massachusetts permite a los adultos usar el teléfono solo en modo manos libres, con el teléfono sujeto en un soporte, y permite tocarlo una vez para activar ese modo.","p":"Correcto. Los adultos usan el teléfono solo con manos libres."},"ref":{"doc":"MA","page":39}},{"id":"ma-019","scope":"MA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Massachusetts, a blood alcohol level of what amount or more is a violation for a driver under 21?","o":["0.01 percent","0.02 percent","0.05 percent","0.08 percent"],"h1":"It is far below the adult limit.","h2":"In Massachusetts a driver under 21 with a blood alcohol level of 0.02 percent or more faces a license suspension, because young drivers should not drink at all.","p":"Right. Under 21, the limit is 0.02 percent."},"es":{"q":"En Massachusetts, ¿a partir de qué nivel de alcohol en la sangre comete una infracción un conductor menor de 21 años?","o":["0.01 por ciento","0.02 por ciento","0.05 por ciento","0.08 por ciento"],"h1":"Es mucho más bajo que el límite de los adultos.","h2":"En Massachusetts un conductor menor de 21 años con 0.02 por ciento de alcohol en la sangre o más recibe una suspensión de licencia, porque los jóvenes no deben tomar nada.","p":"Correcto. Para menores de 21, el límite es 0.02 por ciento."},"ref":{"doc":"MA","page":73}},{"id":"ma-020","scope":"MA","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Massachusetts, unless a sign says otherwise, what is the speed limit in a thickly settled or business district?","o":["25 mph","30 mph","35 mph","40 mph"],"h1":"Some towns choose a lower limit, but the state default is a little higher.","h2":"The Massachusetts default limit in a thickly settled or business district is 30 mph, although some cities and towns lower it to 25 mph on local roads.","p":"Right. The default in thickly settled areas is 30 mph."},"es":{"q":"En Massachusetts, si no hay una señal que diga otra cosa, ¿cuál es el límite de velocidad en una zona densamente poblada o comercial?","o":["25 mph","30 mph","35 mph","40 mph"],"h1":"Algunos pueblos ponen un límite más bajo, pero el del estado es un poco más alto.","h2":"En Massachusetts el límite normal en una zona densamente poblada o comercial es de 30 mph, aunque algunas ciudades y pueblos lo bajan a 25 mph en calles locales.","p":"Correcto. En zonas densamente pobladas el límite normal es 30 mph."},"ref":{"doc":"MA","page":79}},{"id":"ma-021","scope":"MA","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Massachusetts, unless a sign says otherwise, what is the speed limit in a school zone?","o":["15 mph","25 mph","30 mph","20 mph"],"h1":"It is lower than the limit in a thickly settled district.","h2":"In Massachusetts the speed limit in a school zone is 20 mph, so slow down and watch for children.","p":"Right. School zones are 20 mph."},"es":{"q":"En Massachusetts, si no hay una señal que diga otra cosa, ¿cuál es el límite de velocidad en una zona escolar?","o":["15 mph","25 mph","30 mph","20 mph"],"h1":"Es más bajo que el límite de una zona densamente poblada.","h2":"En Massachusetts el límite de velocidad en una zona escolar es de 20 mph, así que baje la velocidad y esté atento a los niños.","p":"Correcto. Las zonas escolares tienen 20 mph."},"ref":{"doc":"MA","page":80}},{"id":"ma-022","scope":"MA","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Massachusetts, unless posted otherwise, what is the speed limit on a divided highway outside a thickly settled or business district?","o":["40 mph","45 mph","50 mph","55 mph"],"h1":"It is 10 mph more than on an undivided highway in the same kind of area.","h2":"The Massachusetts default limit on a divided highway outside a thickly settled or business district is 50 mph unless a sign shows a different limit.","p":"Right. Divided highways outside town centers default to 50 mph."},"es":{"q":"En Massachusetts, si no hay otra señal, ¿cuál es el límite de velocidad en una carretera dividida fuera de una zona densamente poblada o comercial?","o":["40 mph","45 mph","50 mph","55 mph"],"h1":"Es 10 mph más que en una carretera sin división en el mismo tipo de zona.","h2":"En Massachusetts el límite normal en una carretera dividida fuera de una zona densamente poblada o comercial es de 50 mph si no hay una señal con otro límite.","p":"Correcto. Las carreteras divididas fuera de los centros tienen 50 mph."},"ref":{"doc":"MA","page":79}},{"id":"ma-023","scope":"MA","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Massachusetts, unless posted otherwise, what is the speed limit on an undivided highway outside a thickly settled or business district?","o":["40 mph","45 mph","50 mph","35 mph"],"h1":"It is 10 mph less than on a divided highway in the same kind of area.","h2":"The Massachusetts default limit on an undivided highway outside a thickly settled or business district is 40 mph, because there is nothing between you and oncoming traffic.","p":"Right. Undivided highways outside town centers default to 40 mph."},"es":{"q":"En Massachusetts, si no hay otra señal, ¿cuál es el límite de velocidad en una carretera sin división fuera de una zona densamente poblada o comercial?","o":["40 mph","45 mph","50 mph","35 mph"],"h1":"Es 10 mph menos que en una carretera dividida en el mismo tipo de zona.","h2":"En Massachusetts el límite normal en una carretera sin división fuera de una zona densamente poblada o comercial es de 40 mph, porque no hay nada entre usted y el tráfico contrario.","p":"Correcto. Las carreteras sin división fuera de los centros tienen 40 mph."},"ref":{"doc":"MA","page":79}},{"id":"ma-024","scope":"MA","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Massachusetts, when you enter a rotary, who has the right-of-way?","o":["You, because you are entering","Vehicles already in the rotary","The larger vehicle","The vehicle on your left only if it honks"],"h1":"Think about who is already moving around the circle.","h2":"Massachusetts law says a driver entering a rotary must yield to vehicles already in the rotary, so traffic inside keeps moving safely.","p":"Right. Yield to vehicles already in the rotary."},"es":{"q":"En Massachusetts, al entrar a una rotonda (rotary), ¿quién tiene el derecho de paso?","o":["Usted, porque está entrando","Los vehículos que ya están en la rotonda","El vehículo más grande","El de su izquierda solo si toca la bocina"],"h1":"Piense en quién ya va dando la vuelta.","h2":"La ley de Massachusetts dice que quien entra a una rotonda debe ceder el paso a los vehículos que ya están dentro, para que el tráfico de adentro siga con seguridad.","p":"Correcto. Ceda el paso a los vehículos que ya están en la rotonda."},"ref":{"doc":"MA","page":101}},{"id":"ma-025","scope":"MA","cat":"signals","sign":null,"c":3,"en":{"q":"In Massachusetts, after a full stop at a red light, which turn is allowed if no sign forbids it and you yield?","o":["A left turn onto a two-way street","A U-turn","A left turn from any street","A right turn"],"h1":"Most states allow this same turn on red.","h2":"In Massachusetts you may turn right on a red light after stopping and yielding to people and traffic, unless a sign says no turn on red.","p":"Right. A right turn on red is allowed after a stop, unless a sign forbids it."},"es":{"q":"En Massachusetts, después de parar por completo en un semáforo en rojo, ¿qué giro se permite si ninguna señal lo prohíbe y usted cede el paso?","o":["Girar a la izquierda a una calle de doble sentido","Dar vuelta en U","Girar a la izquierda desde cualquier calle","Girar a la derecha"],"h1":"Casi todos los estados permiten este mismo giro en rojo.","h2":"En Massachusetts usted puede girar a la derecha con la luz roja después de parar y ceder el paso a las personas y al tráfico, a menos que una señal lo prohíba.","p":"Correcto. Se permite girar a la derecha en rojo después de parar, si no hay señal que lo prohíba."},"ref":{"doc":"MA","page":81}},{"id":"ma-026","scope":"MA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Massachusetts, when must your headlights be on?","o":["Only on highways","Only after 10 p.m.","Whenever your wipers are needed","Only in tunnels"],"h1":"Think about rain and snow.","h2":"Massachusetts law says your headlights must be on whenever you need your windshield wipers, and daytime running lights do not count.","p":"Right. Wipers on means headlights on."},"es":{"q":"En Massachusetts, ¿cuándo debe tener las luces delanteras encendidas?","o":["Solo en las autopistas","Solo después de las 10 p.m.","Siempre que necesite los limpiaparabrisas","Solo en los túneles"],"h1":"Piense en la lluvia y la nieve.","h2":"La ley de Massachusetts dice que debe encender las luces delanteras siempre que necesite los limpiaparabrisas, y las luces de circulación diurna no cuentan.","p":"Correcto. Si usa los limpiaparabrisas, encienda las luces."},"ref":{"doc":"MA","page":45}},{"id":"ma-027","scope":"MA","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Massachusetts, when may you drive past a school bus that is stopped with red lights flashing?","o":["When you are going the opposite way on a highway divided by a barrier","When you are going the opposite way on any two-lane road","When no children can be seen","When you honk first"],"h1":"There is only one exception, and it needs something between you and the bus.","h2":"In Massachusetts drivers from both directions must stop for a school bus with flashing red lights, and the only exception is opposite traffic on a highway divided by a physical barrier.","p":"Right. Only a divided highway with a barrier lets opposite traffic continue."},"es":{"q":"En Massachusetts, ¿cuándo puede pasar junto a un autobús escolar detenido con luces rojas intermitentes?","o":["Cuando va en sentido contrario en una carretera dividida por una barrera","Cuando va en sentido contrario en cualquier camino de dos carriles","Cuando no se ve a ningún niño","Cuando toca la bocina antes"],"h1":"Hay una sola excepción, y necesita algo entre usted y el autobús.","h2":"En Massachusetts los conductores de ambas direcciones deben parar ante un autobús escolar con luces rojas intermitentes, y la única excepción es el tráfico contrario en una carretera dividida por una barrera física.","p":"Correcto. Solo en una carretera dividida por una barrera sigue el tráfico contrario."},"ref":{"doc":"MA","page":105}},{"id":"ma-028","scope":"MA","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Massachusetts, how close may you drive behind a school bus?","o":["No closer than 25 feet","No closer than 50 feet","No closer than 200 feet","No closer than 100 feet"],"h1":"It is about the length of six or seven cars.","h2":"Massachusetts law says you may not drive within 100 feet behind a school bus, so you have room to stop when it stops for children.","p":"Right. Stay at least 100 feet behind a school bus."},"es":{"q":"En Massachusetts, ¿qué tan cerca puede manejar detrás de un autobús escolar?","o":["No más cerca de 25 pies","No más cerca de 50 pies","No más cerca de 200 pies","No más cerca de 100 pies"],"h1":"Es más o menos el largo de seis o siete carros.","h2":"La ley de Massachusetts dice que usted no puede manejar a menos de 100 pies detrás de un autobús escolar, para tener espacio para parar cuando se detenga por los niños.","p":"Correcto. Manténgase por lo menos a 100 pies detrás de un autobús escolar."},"ref":{"doc":"MA","page":null}},{"id":"ma-029","scope":"MA","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Massachusetts, what does the Move Over law ask you to do near a stopped emergency vehicle with flashing lights?","o":["Stop in your lane until it leaves","Move to a lane not next to it, or slow down","Flash your lights and keep your speed","Drive on the shoulder past it"],"h1":"You give the vehicle more room, or less speed.","h2":"The Massachusetts Move Over law asks you to change to a lane that is not next to a stopped emergency, maintenance, or tow vehicle, or to slow down if you cannot change lanes safely.","p":"Right. Move over a lane, or slow down if you cannot."},"es":{"q":"En Massachusetts, ¿qué le pide la ley Move Over cerca de un vehículo de emergencia detenido con luces intermitentes?","o":["Parar en su carril hasta que se vaya","Pasar a un carril que no esté al lado, o bajar la velocidad","Hacer cambio de luces y seguir igual","Pasar por el acotamiento"],"h1":"Usted le da más espacio al vehículo, o pasa más despacio.","h2":"La ley Move Over de Massachusetts le pide pasar a un carril que no esté junto a un vehículo de emergencia, de mantenimiento o grúa detenido, o bajar la velocidad si no puede cambiarse de carril con seguridad.","p":"Correcto. Cámbiese de carril, o baje la velocidad si no puede."},"ref":{"doc":"MA","page":104}},{"id":"ma-030","scope":"MA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Massachusetts, which coverage is one of the required parts of every auto insurance policy?","o":["Collision coverage","Comprehensive coverage","Personal injury protection (PIP)","Rental car coverage"],"h1":"Massachusetts is a no-fault state for this coverage.","h2":"Personal injury protection (PIP) is required on every Massachusetts auto policy and pays certain injury costs no matter who caused the crash, while collision and comprehensive are optional.","p":"Right. PIP is required in Massachusetts."},"es":{"q":"En Massachusetts, ¿qué cobertura es una de las partes obligatorias de toda póliza de seguro de auto?","o":["Cobertura de choque (collision)","Cobertura amplia (comprehensive)","Protección por lesiones personales (PIP)","Cobertura de auto de alquiler"],"h1":"Massachusetts es un estado “sin culpa” para esta cobertura.","h2":"La protección por lesiones personales (PIP) es obligatoria en toda póliza de auto de Massachusetts y paga ciertos gastos por lesiones sin importar quién causó el choque, mientras que la de choque y la amplia son opcionales.","p":"Correcto. La PIP es obligatoria en Massachusetts."},"ref":{"doc":"MA","page":null}},{"id":"ma-031","scope":"MA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Massachusetts, what is the fewest surchargeable events within 2 years that means you must take a Driver Retraining course?","o":["3 events","2 events","5 events","7 events"],"h1":"It is a small number, more than two.","h2":"In Massachusetts, 3 surchargeable events within 2 years, such as at-fault crashes or traffic violations, mean you must finish a Driver Retraining course within 90 days or lose your license.","p":"Right. Three surchargeable events in 2 years mean a retraining course, or a suspension."},"es":{"q":"En Massachusetts, ¿cuál es el menor número de incidentes con recargo en 2 años que lo obliga a tomar un curso de reentrenamiento para conductores?","o":["3 incidentes","2 incidentes","5 incidentes","7 incidentes"],"h1":"Es un número pequeño, mayor que dos.","h2":"En Massachusetts, 3 incidentes con recargo en 2 años, como choques con culpa o infracciones de tránsito, lo obligan a terminar un curso de reentrenamiento para conductores en 90 días o perderá su licencia.","p":"Correcto. Tres incidentes con recargo en 2 años significan un curso de reentrenamiento, o una suspensión."},"ref":{"doc":"MA","page":59}},{"id":"md-001","scope":"MD","cat":"licensing","sign":null,"c":2,"en":{"q":"In Maryland, what is the youngest age to get a learner's permit?","o":["15 years old","15 years and 6 months","15 years and 9 months","16 years old"],"h1":"It is three months before the 16th birthday.","h2":"In Maryland, you must be at least 15 years and 9 months old to get a learner's permit.","p":"Right. Maryland starts at 15 years and 9 months."},"es":{"q":"En Maryland, ¿cuál es la edad mínima para obtener un permiso de aprendiz?","o":["15 años","15 años y 6 meses","15 años y 9 meses","16 años"],"h1":"Es tres meses antes de cumplir 16.","h2":"En Maryland, usted debe tener por lo menos 15 años y 9 meses para obtener un permiso de aprendiz.","p":"Correcto. Maryland empieza a los 15 años y 9 meses."},"ref":{"doc":"MD","page":9}},{"id":"md-002","scope":"MD","cat":"licensing","sign":null,"c":1,"en":{"q":"In Maryland, how many of the 25 knowledge test questions must you answer correctly to pass?","o":["18","22","20","25"],"h1":"You may miss no more than three.","h2":"In Maryland, you must answer at least 22 of the 25 knowledge test questions correctly to pass.","p":"Right. 22 out of 25 passes in Maryland."},"es":{"q":"En Maryland, ¿cuántas de las 25 preguntas del examen de conocimientos debe contestar bien para aprobar?","o":["18","22","20","25"],"h1":"Puede fallar como máximo tres.","h2":"En Maryland, usted debe contestar bien por lo menos 22 de las 25 preguntas del examen de conocimientos para aprobar.","p":"Correcto. En Maryland se aprueba con 22 de 25."},"ref":{"doc":"MD","page":null}},{"id":"md-003","scope":"MD","cat":"licensing","sign":null,"c":3,"en":{"q":"In Maryland, who may supervise a driver with a learner's permit?","o":["Any licensed driver 18 or older","Any adult, licensed or not","A licensed driver 25 or older","A driver 21 or older who has held a license for at least 3 years"],"h1":"Both an age and a number of years with a license matter.","h2":"In Maryland, the supervising driver must be at least 21 years old and must have held a valid license for at least 3 years.","p":"Right. 21 or older, with at least 3 years licensed."},"es":{"q":"En Maryland, ¿quién puede supervisar a un conductor con permiso de aprendiz?","o":["Cualquier conductor con licencia de 18 años o más","Cualquier adulto, con o sin licencia","Un conductor con licencia de 25 años o más","Un conductor de 21 años o más que ha tenido licencia por lo menos 3 años"],"h1":"Importan la edad y también los años con licencia.","h2":"En Maryland, el conductor que supervisa debe tener por lo menos 21 años y haber tenido una licencia válida por lo menos 3 años.","p":"Correcto. 21 años o más, con por lo menos 3 años de licencia."},"ref":{"doc":"MD","page":51}},{"id":"md-004","scope":"MD","cat":"licensing","sign":null,"c":0,"en":{"q":"In Maryland, where must the supervising driver sit when a learner is driving?","o":["In the front passenger seat, with no one else in the front","In any back seat","Anywhere in the car","Behind the driver"],"h1":"The supervisor needs to be right beside the learner.","h2":"In Maryland, the supervising driver must sit in the front passenger seat, and no one else may sit in the front.","p":"Right. The supervisor sits up front, beside you."},"es":{"q":"En Maryland, ¿dónde debe sentarse el conductor que supervisa cuando maneja un aprendiz?","o":["En el asiento del pasajero delantero, sin nadie más adelante","En cualquier asiento de atrás","En cualquier lugar del auto","Detrás del conductor"],"h1":"El supervisor debe estar justo al lado del aprendiz.","h2":"En Maryland, el conductor que supervisa debe sentarse en el asiento del pasajero delantero, y nadie más puede ir adelante.","p":"Correcto. El supervisor va adelante, a su lado."},"ref":{"doc":"MD","page":51}},{"id":"md-005","scope":"MD","cat":"licensing","sign":null,"c":2,"en":{"q":"In Maryland, how many hours of supervised practice must a new driver log with a learner's permit?","o":["30 hours, including 5 at night","40 hours, including 10 at night","60 hours, including 10 at night","100 hours, including 20 at night"],"h1":"It is the highest of the usual numbers, with 10 of them at night.","h2":"In Maryland, a learner must log 60 hours of supervised practice, and 10 of those hours must be at night.","p":"Right. 60 hours, 10 at night."},"es":{"q":"En Maryland, ¿cuántas horas de práctica supervisada debe registrar un conductor nuevo con permiso de aprendiz?","o":["30 horas, 5 de ellas de noche","40 horas, 10 de ellas de noche","60 horas, 10 de ellas de noche","100 horas, 20 de ellas de noche"],"h1":"Es el número más alto de los habituales, con 10 de ellas de noche.","h2":"En Maryland, un aprendiz debe registrar 60 horas de práctica supervisada, y 10 de esas horas deben ser de noche.","p":"Correcto. 60 horas, 10 de noche."},"ref":{"doc":"MD","page":10}},{"id":"md-006","scope":"MD","cat":"licensing","sign":null,"c":1,"en":{"q":"In Maryland, which practice hours count as night driving?","o":["From 9:00 p.m. to 6:00 a.m.","From 30 minutes before sunset to 30 minutes after sunrise","From midnight to 5:00 a.m.","Any time the headlights are on"],"h1":"The answer follows the sun, not the clock.","h2":"In Maryland, night practice is driving from 30 minutes before sunset until 30 minutes after sunrise.","p":"Right. Night practice follows sunset and sunrise."},"es":{"q":"En Maryland, ¿qué horas de práctica cuentan como manejo nocturno?","o":["De 9:00 p.m. a 6:00 a.m.","Desde 30 minutos antes de la puesta del sol hasta 30 minutos después del amanecer","De medianoche a 5:00 a.m.","Cualquier momento con las luces encendidas"],"h1":"La respuesta sigue al sol, no al reloj.","h2":"En Maryland, la práctica nocturna es manejar desde 30 minutos antes de la puesta del sol hasta 30 minutos después del amanecer.","p":"Correcto. La práctica nocturna sigue la puesta del sol y el amanecer."},"ref":{"doc":"MD","page":10}},{"id":"md-007","scope":"MD","cat":"licensing","sign":null,"c":3,"en":{"q":"In Maryland, how long must a driver under 18 hold a learner's permit before getting a provisional license?","o":["45 days","3 months","6 months","9 months"],"h1":"It is the longest of the choices, three quarters of a year.","h2":"In Maryland, a driver under 18 must hold the learner's permit for at least 9 months before getting a provisional license.","p":"Right. Nine months for teens in Maryland."},"es":{"q":"En Maryland, ¿cuánto tiempo debe tener un conductor menor de 18 años el permiso de aprendiz antes de obtener una licencia provisional?","o":["45 días","3 meses","6 meses","9 meses"],"h1":"Es la opción más larga, tres cuartos de año.","h2":"En Maryland, un conductor menor de 18 años debe tener el permiso de aprendiz por lo menos 9 meses antes de obtener una licencia provisional.","p":"Correcto. Nueve meses para los jóvenes en Maryland."},"ref":{"doc":"MD","page":10}},{"id":"md-008","scope":"MD","cat":"licensing","sign":null,"c":0,"en":{"q":"In Maryland, how long must a new driver aged 25 or older hold a learner's permit before getting a provisional license?","o":["45 days","9 months","1 year","No waiting period"],"h1":"Older drivers wait much less than teens, but there is still a wait.","h2":"In Maryland, a new driver aged 25 or older must hold the learner's permit for at least 45 days.","p":"Right. 45 days for drivers 25 and older."},"es":{"q":"En Maryland, ¿cuánto tiempo debe tener el permiso de aprendiz un conductor nuevo de 25 años o más antes de obtener una licencia provisional?","o":["45 días","9 meses","1 año","No hay tiempo de espera"],"h1":"Los mayores esperan mucho menos que los jóvenes, pero sí hay una espera.","h2":"En Maryland, un conductor nuevo de 25 años o más debe tener el permiso de aprendiz por lo menos 45 días.","p":"Correcto. 45 días para conductores de 25 años o más."},"ref":{"doc":"MD","page":10}},{"id":"md-009","scope":"MD","cat":"licensing","sign":null,"c":2,"en":{"q":"In Maryland, what happens if a learner is convicted of a moving violation while holding the permit?","o":["Nothing changes","The permit is upgraded early","The waiting time restarts, with at least 9 months from the conviction","Only a fine is paid"],"h1":"The clock does not keep running as before.","h2":"In Maryland, a moving violation conviction restarts the waiting time, so the learner must wait at least 9 months from the date of the conviction.","p":"Right. A violation resets the clock to 9 months."},"es":{"q":"En Maryland, ¿qué pasa si un aprendiz es condenado por una infracción de tránsito en movimiento mientras tiene el permiso?","o":["Nada cambia","El permiso se mejora antes de tiempo","El tiempo de espera vuelve a empezar, con por lo menos 9 meses desde la condena","Solo se paga una multa"],"h1":"El reloj no sigue corriendo como antes.","h2":"En Maryland, una condena por infracción en movimiento reinicia la espera, y el aprendiz debe esperar por lo menos 9 meses desde la fecha de la condena.","p":"Correcto. Una infracción reinicia la cuenta a 9 meses."},"ref":{"doc":"MD","page":10}},{"id":"md-010","scope":"MD","cat":"licensing","sign":null,"c":1,"en":{"q":"In Maryland, how much driver education must a new driver complete?","o":["10 hours in class and 2 hours behind the wheel","30 hours in class and 6 hours behind the wheel","No driver education is required","6 hours in class and 30 hours behind the wheel"],"h1":"The classroom part is much longer than the time behind the wheel.","h2":"In Maryland, the certified driver education program requires at least 30 hours of classroom instruction and 6 hours of behind-the-wheel training.","p":"Right. 30 hours in class and 6 behind the wheel."},"es":{"q":"En Maryland, ¿cuánta educación vial debe completar un conductor nuevo?","o":["10 horas en clase y 2 horas al volante","30 horas en clase y 6 horas al volante","No se requiere educación vial","6 horas en clase y 30 horas al volante"],"h1":"La parte en clase es mucho más larga que el tiempo al volante.","h2":"En Maryland, el programa certificado de educación vial exige por lo menos 30 horas de clase y 6 horas de práctica al volante.","p":"Correcto. 30 horas en clase y 6 al volante."},"ref":{"doc":"MD","page":null}},{"id":"md-011","scope":"MD","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Maryland, may a learner's permit holder use a phone with Bluetooth while driving?","o":["Yes, hands-free is allowed","Yes, for short calls","Yes, if the supervisor allows it","No, only to call 911 in an emergency"],"h1":"The rule for learners covers every kind of phone use.","h2":"In Maryland, a learner's permit holder may not use a phone while driving, even with Bluetooth or hands-free, except to call 911 in an emergency.","p":"Right. Learners in Maryland do not use the phone at all."},"es":{"q":"En Maryland, ¿puede una persona con permiso de aprendiz usar un teléfono con Bluetooth mientras maneja?","o":["Sí, manos libres está permitido","Sí, para llamadas cortas","Sí, si el supervisor lo permite","No, solo para llamar al 911 en una emergencia"],"h1":"La regla para aprendices cubre todo uso del teléfono.","h2":"En Maryland, quien tiene permiso de aprendiz no puede usar el teléfono mientras maneja, ni con Bluetooth ni manos libres, excepto para llamar al 911 en una emergencia.","p":"Correcto. Los aprendices en Maryland no usan el teléfono para nada."},"ref":{"doc":"MD","page":47}},{"id":"md-012","scope":"MD","cat":"licensing","sign":null,"c":0,"en":{"q":"In Maryland, during which hours may a provisional driver under 18 not drive without a supervising driver?","o":["Midnight to 5:00 a.m.","9:00 p.m. to 6:00 a.m.","10:00 p.m. to 5:00 a.m.","There is no night limit"],"h1":"The limit starts at the very start of a new day.","h2":"In Maryland, a provisional driver under 18 may not drive between midnight and 5:00 in the morning without a supervising driver, unless going to or from work, school activities, volunteer programs or sports.","p":"Right. Midnight to 5 a.m. is off limits."},"es":{"q":"En Maryland, ¿en qué horario no puede manejar sin supervisor un conductor provisional menor de 18 años?","o":["De medianoche a 5:00 a.m.","De 9:00 p.m. a 6:00 a.m.","De 10:00 p.m. a 5:00 a.m.","No hay límite de noche"],"h1":"El límite empieza justo al comenzar un nuevo día.","h2":"En Maryland, un conductor provisional menor de 18 años no puede manejar entre la medianoche y las 5:00 de la mañana sin supervisor, salvo para ir o volver del trabajo, actividades escolares, voluntariado o deportes.","p":"Correcto. De medianoche a 5 a.m. no se maneja."},"ref":{"doc":"MD","page":47}},{"id":"md-013","scope":"MD","cat":"licensing","sign":null,"c":1,"en":{"q":"In Maryland, for how long may a provisional driver under 18 not carry passengers under 18 who are not immediate family, without a supervising driver?","o":["The first 30 days","The first 151 days","The first year","Until age 21"],"h1":"It is about five months.","h2":"In Maryland, for the first 151 days, a provisional driver under 18 may not carry passengers under 18 other than immediate family unless a supervising driver is present.","p":"Right. The first 151 days, about five months."},"es":{"q":"En Maryland, ¿durante cuánto tiempo un conductor provisional menor de 18 años no puede llevar pasajeros menores de 18 que no sean familia inmediata, sin un supervisor?","o":["Los primeros 30 días","Los primeros 151 días","El primer año","Hasta los 21 años"],"h1":"Son unos cinco meses.","h2":"En Maryland, durante los primeros 151 días, un conductor provisional menor de 18 años no puede llevar pasajeros menores de 18 que no sean familia inmediata, salvo que vaya un supervisor.","p":"Correcto. Los primeros 151 días, unos cinco meses."},"ref":{"doc":"MD","page":47}},{"id":"md-014","scope":"MD","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Maryland, how much alcohol may a driver under 21 have in the blood while driving?","o":["Up to 0.08","Up to 0.05","None at all","Up to 0.10"],"h1":"People under 21 may not drink alcohol at all.","h2":"In Maryland, a driver under 21 may not drive with any alcohol in the blood.","p":"Right. Under 21, the limit is zero."},"es":{"q":"En Maryland, ¿cuánto alcohol puede tener en la sangre un conductor menor de 21 años mientras maneja?","o":["Hasta 0.08","Hasta 0.05","Nada","Hasta 0.10"],"h1":"Las personas menores de 21 años no pueden tomar nada de alcohol.","h2":"En Maryland, un conductor menor de 21 años no puede manejar con nada de alcohol en la sangre.","p":"Correcto. Si es menor de 21 años, el límite es cero."},"ref":{"doc":"MD","page":33}},{"id":"md-015","scope":"MD","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Maryland, which stopped vehicles does the Move Over law cover?","o":["Only police cars","Only ambulances and fire trucks","Only tow trucks","Any stopped vehicle showing hazard lights, flares or cones"],"h1":"The law covers more than emergency vehicles.","h2":"In Maryland, you must move over, or slow down if you cannot, for any stopped vehicle showing hazard lights, road flares or traffic cones.","p":"Right. Any stopped vehicle with warning signals."},"es":{"q":"En Maryland, ¿qué vehículos detenidos cubre la ley Move Over (cámbiese de carril)?","o":["Solo patrullas de policía","Solo ambulancias y bomberos","Solo grúas","Cualquier vehículo detenido con luces intermitentes, bengalas o conos"],"h1":"La ley cubre más que los vehículos de emergencia.","h2":"En Maryland, usted debe cambiarse de carril, o bajar la velocidad si no puede, ante cualquier vehículo detenido con luces de emergencia, bengalas o conos.","p":"Correcto. Cualquier vehículo detenido con señales de advertencia."},"ref":{"doc":"MD","page":45}},{"id":"md-016","scope":"MD","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Maryland, a school bus stops with red lights flashing on a road split by a physical barrier. Who must stop?","o":["Traffic on the same side of the barrier as the bus","Traffic on both sides of the barrier","Only traffic on the other side of the barrier","No one, because of the barrier"],"h1":"Traffic on the far side of the barrier keeps going.","h2":"In Maryland, on a road divided by a physical barrier, traffic on the bus's side must stop, and traffic on the other side does not stop.","p":"Right. Only traffic on the bus's side of the barrier stops."},"es":{"q":"En Maryland, un autobús escolar se detiene con las luces rojas intermitentes en una carretera dividida por una barrera física. ¿Quién debe detenerse?","o":["El tráfico del mismo lado de la barrera que el autobús","El tráfico de ambos lados de la barrera","Solo el tráfico del otro lado de la barrera","Nadie, por la barrera"],"h1":"El tráfico del otro lado de la barrera sigue su camino.","h2":"En Maryland, en una carretera dividida por una barrera física, el tráfico del lado del autobús debe detenerse, y el tráfico del otro lado no se detiene.","p":"Correcto. Solo se detiene el tráfico del lado del autobús."},"ref":{"doc":"MD","page":39}},{"id":"md-017","scope":"MD","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Maryland, may an adult driver hold a cell phone to talk while driving?","o":["Yes, at any time","No, a hands-free device is required","Yes, but only on local streets","Yes, if driving under 30 mph"],"h1":"Your hands should stay on the wheel.","h2":"In Maryland, an adult driver may not hold a cell phone to talk while driving and must use a hands-free device, except to call 911.","p":"Right. Adults in Maryland must go hands-free."},"es":{"q":"En Maryland, ¿puede un conductor adulto sostener el celular para hablar mientras maneja?","o":["Sí, en cualquier momento","No, se requiere un dispositivo de manos libres","Sí, pero solo en calles locales","Sí, si va a menos de 30 mph"],"h1":"Sus manos deben quedarse en el volante.","h2":"En Maryland, un conductor adulto no puede sostener el celular para hablar mientras maneja y debe usar manos libres, excepto para llamar al 911.","p":"Correcto. Los adultos en Maryland deben usar manos libres."},"ref":{"doc":"MD","page":35}},{"id":"me-001","scope":"ME","cat":"licensing","sign":null,"c":1,"en":{"q":"In Maine, what is the youngest age to get a learner's permit?","o":["14 years old","15 years old","16 years old","17 years old"],"h1":"It is one year before the intermediate license.","h2":"In Maine you can get a learner's permit at 15. If you are under 18, you must also take an approved driver education course.","p":"Right. The Maine learner's permit starts at 15."},"es":{"q":"En Maine, ¿cuál es la edad mínima para obtener el permiso de aprendiz?","o":["14 años","15 años","16 años","17 años"],"h1":"Es un año antes de la licencia intermedia.","h2":"En Maine usted puede obtener el permiso de aprendiz a los 15 años. Si tiene menos de 18 años, también debe tomar un curso aprobado de educación vial.","p":"Correcto. El permiso de aprendiz en Maine empieza a los 15."},"ref":{"doc":"ME","page":"1-2"}},{"id":"me-002","scope":"ME","cat":"licensing","sign":null,"c":2,"en":{"q":"In Maine, how many hours of practice driving must a permit holder under 21 log?","o":["30 hours","50 hours","70 hours","100 hours"],"h1":"It is more than in many states, but less than one hundred.","h2":"A Maine permit holder under 21 must log 70 hours of practice driving.","p":"Right. Maine asks for 70 hours."},"es":{"q":"En Maine, ¿cuántas horas de práctica de manejo debe registrar un aprendiz menor de 21 años?","o":["30 horas","50 horas","70 horas","100 horas"],"h1":"Es más que en muchos estados, pero menos de cien.","h2":"Un aprendiz en Maine menor de 21 años debe registrar 70 horas de práctica de manejo.","p":"Correcto. Maine pide 70 horas."},"ref":{"doc":"ME","page":"1-3"}},{"id":"me-003","scope":"ME","cat":"licensing","sign":null,"c":0,"en":{"q":"In Maine, how many of the 70 practice hours must be driven after dark?","o":["10 hours","5 hours","20 hours","35 hours"],"h1":"It is a round number, a small part of the total.","h2":"In Maine, 10 of the 70 practice hours must be driven after dark.","p":"Right. Ten of the hours must be after dark."},"es":{"q":"En Maine, ¿cuántas de las 70 horas de práctica deben ser después del anochecer?","o":["10 horas","5 horas","20 horas","35 horas"],"h1":"Es un número redondo, una parte pequeña del total.","h2":"En Maine, 10 de las 70 horas de práctica deben ser después del anochecer.","p":"Correcto. Diez de las horas deben ser de noche."},"ref":{"doc":"ME","page":"1-3"}},{"id":"me-004","scope":"ME","cat":"licensing","sign":null,"c":3,"en":{"q":"In Maine, when may the 70 practice hours start to count?","o":["At age 14","After the road test","After the first year of high school","After the learner's permit is issued"],"h1":"You need a permit to drive on the road.","h2":"In Maine, the 70 practice hours must begin after the learner's permit is issued.","p":"Right. Hours count only once you have the permit."},"es":{"q":"En Maine, ¿cuándo empiezan a contar las 70 horas de práctica?","o":["A los 14 años","Después del examen de manejo","Después del primer año de secundaria","Después de recibir el permiso de aprendiz"],"h1":"Usted necesita un permiso para manejar en la calle.","h2":"En Maine, las 70 horas de práctica deben empezar después de recibir el permiso de aprendiz.","p":"Correcto. Las horas cuentan solo cuando ya tiene el permiso."},"ref":{"doc":"ME","page":"1-3"}},{"id":"me-005","scope":"ME","cat":"licensing","sign":null,"c":1,"en":{"q":"In Maine, how long must a permit holder under 21 hold the permit before the road test?","o":["3 months","6 months","9 months","12 months"],"h1":"It is half a year.","h2":"In Maine, a permit holder under 21 must hold the permit for 6 months before applying for the road test.","p":"Right. Six months with the permit first."},"es":{"q":"En Maine, ¿cuánto tiempo debe tener el permiso un aprendiz menor de 21 años antes del examen de manejo?","o":["3 meses","6 meses","9 meses","12 meses"],"h1":"Es medio año.","h2":"En Maine, un aprendiz menor de 21 años debe tener el permiso 6 meses antes de solicitar el examen de manejo.","p":"Correcto. Primero, seis meses con el permiso."},"ref":{"doc":"ME","page":"1-3"}},{"id":"me-006","scope":"ME","cat":"licensing","sign":null,"c":2,"en":{"q":"In Maine, how old must the supervising driver of a permit holder be?","o":["At least 16","At least 18","At least 20","At least 25"],"h1":"It is younger than in many other states.","h2":"In Maine, the supervising driver must be at least 20 years old and have held a license for at least 2 years.","p":"Right. The supervisor must be 20 or older."},"es":{"q":"En Maine, ¿qué edad debe tener el conductor que supervisa a un aprendiz?","o":["Por lo menos 16","Por lo menos 18","Por lo menos 20","Por lo menos 25"],"h1":"Es menor que en muchos otros estados.","h2":"En Maine, el conductor que supervisa debe tener por lo menos 20 años y haber tenido licencia por lo menos 2 años.","p":"Correcto. El supervisor debe tener 20 años o más."},"ref":{"doc":"ME","page":"1-2"}},{"id":"me-007","scope":"ME","cat":"licensing","sign":null,"c":0,"en":{"q":"In Maine, how long must the supervising driver of a permit holder have held a license?","o":["At least 2 years","At least 6 months","At least 5 years","At least 10 years"],"h1":"It is a short number of years.","h2":"In Maine, the supervising driver must have held a license for at least 2 years.","p":"Right. Two years of license experience is required."},"es":{"q":"En Maine, ¿cuánto tiempo debe haber tenido licencia el conductor que supervisa a un aprendiz?","o":["Por lo menos 2 años","Por lo menos 6 meses","Por lo menos 5 años","Por lo menos 10 años"],"h1":"Es un número pequeño de años.","h2":"En Maine, el conductor que supervisa debe haber tenido licencia por lo menos 2 años.","p":"Correcto. Se requieren dos años con licencia."},"ref":{"doc":"ME","page":"1-2"}},{"id":"me-008","scope":"ME","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Maine, may a driver with a learner's permit use a cell phone while driving?","o":["Yes, if it is hands-free","No, a cell phone may not be used","Yes, at red lights","Yes, if the supervisor allows it"],"h1":"Permit holders have a stricter rule than adult drivers.","h2":"In Maine, a driver with a learner's permit may not use a cell phone while driving, not even hands-free.","p":"Right. No cell phone at all while driving on a permit."},"es":{"q":"En Maine, ¿puede un conductor con permiso de aprendiz usar el celular mientras maneja?","o":["Sí, si es de manos libres","No, no puede usar el celular","Sí, en los semáforos en rojo","Sí, si el supervisor lo permite"],"h1":"Los aprendices tienen una regla más estricta que los conductores adultos.","h2":"En Maine, un conductor con permiso de aprendiz no puede usar el celular mientras maneja, ni siquiera con manos libres.","p":"Correcto. Nada de celular al manejar con permiso de aprendiz."},"ref":{"doc":"ME","page":"1-2"}},{"id":"me-009","scope":"ME","cat":"licensing","sign":null,"c":3,"en":{"q":"In Maine, for how long do the intermediate license restrictions last?","o":["90 days","180 days","365 days","270 days"],"h1":"It is about nine months.","h2":"In Maine, the intermediate license restrictions last 270 days from the day the license is issued.","p":"Right. The restrictions last 270 days."},"es":{"q":"En Maine, ¿cuánto duran las restricciones de la licencia intermedia?","o":["90 días","180 días","365 días","270 días"],"h1":"Son unos nueve meses.","h2":"En Maine, las restricciones de la licencia intermedia duran 270 días desde el día en que se emite la licencia.","p":"Correcto. Las restricciones duran 270 días."},"ref":{"doc":"ME","page":"1-4"}},{"id":"me-010","scope":"ME","cat":"licensing","sign":null,"c":2,"en":{"q":"In Maine, who may ride as a passenger with an intermediate license holder when no qualified adult driver is along?","o":["Any friends","Up to two friends","Only immediate family members","Only people over 18"],"h1":"Think of the people in your family.","h2":"In Maine, an intermediate license holder may carry only immediate family members as passengers unless a qualified licensed driver is along.","p":"Right. Only family, unless a qualified driver is along."},"es":{"q":"En Maine, ¿quién puede viajar como pasajero con el titular de una licencia intermedia cuando no va un conductor adulto calificado?","o":["Cualquier amigo","Hasta dos amigos","Solo familiares directos","Solo personas mayores de 18"],"h1":"Piense en las personas de su familia.","h2":"En Maine, el titular de una licencia intermedia puede llevar solo a familiares directos como pasajeros, salvo que vaya un conductor con licencia calificado.","p":"Correcto. Solo familiares, salvo que vaya un conductor calificado."},"ref":{"doc":"ME","page":"1-4"}},{"id":"me-011","scope":"ME","cat":"licensing","sign":null,"c":1,"en":{"q":"In Maine, what happens to intermediate license restrictions after a violation of those rules?","o":["Nothing changes","They are extended by another 270 days","They end right away","They become a fine only"],"h1":"Breaking the rules makes them last longer.","h2":"In Maine, a driver who breaks the intermediate license rules has the restrictions extended by another 270 days.","p":"Right. A violation adds 270 more days."},"es":{"q":"En Maine, ¿qué pasa con las restricciones de la licencia intermedia después de violar esas reglas?","o":["No cambia nada","Se extienden por otros 270 días","Terminan de inmediato","Se convierten solo en una multa"],"h1":"Violar las reglas hace que duren más.","h2":"En Maine, a un conductor que viola las reglas de la licencia intermedia se le extienden las restricciones por otros 270 días.","p":"Correcto. Una violación agrega 270 días más."},"ref":{"doc":"ME","page":"1-4"}},{"id":"me-012","scope":"ME","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Maine, how may an adult driver make a phone call while driving?","o":["Hands-free, without holding the phone","Holding the phone to the ear","Only by texting","Holding the phone at a stop sign"],"h1":"Your hands stay off the device.","h2":"In Maine, a driver 18 or older with a full license may not hold a phone while driving, but may make calls hands-free.","p":"Right. Maine bans holding the phone while driving."},"es":{"q":"En Maine, ¿cómo puede un conductor adulto hacer una llamada mientras maneja?","o":["Con manos libres, sin sostener el teléfono","Sosteniendo el teléfono en el oído","Solo con mensajes de texto","Sosteniendo el teléfono en una señal de alto"],"h1":"Sus manos no tocan el aparato.","h2":"En Maine, un conductor de 18 años o más con licencia completa no puede sostener el teléfono mientras maneja, pero puede hacer llamadas con manos libres.","p":"Correcto. Maine prohíbe sostener el teléfono al manejar."},"ref":{"doc":"ME","page":null}},{"id":"me-013","scope":"ME","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Maine, what happens to a driver under 21 found driving with any measurable amount of alcohol?","o":["Only a warning","A 30-day suspension","Nothing, if below 0.08 percent","The license is suspended for at least one year"],"h1":"Maine has zero tolerance for young drivers.","h2":"In Maine, a driver under 21 with any amount of alcohol loses the license for at least one year.","p":"Right. Under 21, any alcohol means losing the license for at least a year."},"es":{"q":"En Maine, ¿qué le pasa a un conductor menor de 21 años que maneja con cualquier cantidad medible de alcohol?","o":["Solo una advertencia","Una suspensión de 30 días","Nada, si está por debajo de 0.08 por ciento","Se le suspende la licencia por al menos un año"],"h1":"Maine tiene tolerancia cero para los conductores jóvenes.","h2":"En Maine, un conductor menor de 21 años con cualquier cantidad de alcohol pierde la licencia por al menos un año.","p":"Correcto. Menor de 21, cualquier alcohol significa perder la licencia por al menos un año."},"ref":{"doc":"ME","page":"3-14"}},{"id":"mi-001","scope":"MI","cat":"licensing","sign":null,"c":2,"en":{"q":"In Michigan, what is the youngest age to get a Level 1 Learner’s License?","o":["14 years old","14 years and 3 months","14 years and 9 months","15 years and 6 months"],"h1":"It is a few months before the 15th birthday.","h2":"You can get a Michigan Level 1 Learner’s License at 14 years and 9 months, after finishing the first part of driver education.","p":"Right. Level 1 starts at 14 years and 9 months."},"es":{"q":"En Michigan, ¿cuál es la edad mínima para obtener la licencia de aprendiz de Nivel 1?","o":["14 años","14 años y 3 meses","14 años y 9 meses","15 años y 6 meses"],"h1":"Es unos meses antes de cumplir 15 años.","h2":"Usted puede obtener la licencia de aprendiz de Nivel 1 en Michigan a los 14 años y 9 meses, después de terminar la primera parte de la educación vial.","p":"Correcto. El Nivel 1 empieza a los 14 años y 9 meses."},"ref":{"doc":"MI","page":4}},{"id":"mi-002","scope":"MI","cat":"licensing","sign":null,"c":0,"en":{"q":"In Michigan, what must a teen finish before getting a Level 1 Learner’s License?","o":["Segment 1 of an approved driver education course","A road skills test","50 hours of supervised driving","Six months of a part-time job"],"h1":"Michigan splits driver education into parts; this is the first one.","h2":"A teen must finish Segment 1 of an approved driver education course before getting a Level 1 license, so they learn the basics in class first.","p":"Right. Segment 1 of driver education comes first."},"es":{"q":"En Michigan, ¿qué debe terminar un joven antes de obtener la licencia de aprendiz de Nivel 1?","o":["El Segmento 1 de un curso aprobado de educación vial","Un examen práctico de manejo","50 horas de manejo supervisado","Seis meses de un trabajo de medio tiempo"],"h1":"Michigan divide la educación vial en partes; esta es la primera.","h2":"Un joven debe terminar el Segmento 1 de un curso aprobado de educación vial antes de obtener la licencia de Nivel 1, para aprender lo básico en clase primero.","p":"Correcto. Primero va el Segmento 1 de la educación vial."},"ref":{"doc":"MI","page":4}},{"id":"mi-003","scope":"MI","cat":"licensing","sign":null,"c":3,"en":{"q":"In Michigan, who may ride with a Level 1 driver as the supervisor?","o":["Any passenger age 16 or older","Only a certified driving instructor","Any licensed driver age 18 or older","A licensed parent or guardian, or a licensed adult 21 or older they approve"],"h1":"The supervisor must be family, or an older adult the family chose.","h2":"A Level 1 driver may drive only with a licensed parent or guardian, or with a licensed driver 21 or older whom the parent or guardian has approved.","p":"Right. A licensed parent, guardian, or approved adult 21 or older must ride along."},"es":{"q":"En Michigan, ¿quién puede ir como supervisor con un conductor de Nivel 1?","o":["Cualquier pasajero de 16 años o más","Solo un instructor de manejo certificado","Cualquier conductor con licencia de 18 años o más","Su padre, madre o tutor con licencia, o un adulto con licencia de 21 años o más aprobado por ellos"],"h1":"El supervisor debe ser de la familia, o un adulto mayor que la familia eligió.","h2":"Un conductor de Nivel 1 solo puede manejar con su padre, madre o tutor con licencia, o con un conductor con licencia de 21 años o más que ellos hayan aprobado.","p":"Correcto. Debe ir su padre, madre, tutor o un adulto aprobado de 21 años o más con licencia."},"ref":{"doc":"MI","page":5}},{"id":"mi-004","scope":"MI","cat":"licensing","sign":null,"c":1,"en":{"q":"In Michigan, how long must a teen hold a Level 1 license before moving to Level 2?","o":["Three months","Six months","One year","Two years"],"h1":"It is half of a year.","h2":"A teen must drive with a Level 1 license for at least six months before moving to Level 2, to gain supervised experience.","p":"Right. Level 1 lasts at least six months."},"es":{"q":"En Michigan, ¿cuánto tiempo debe tener un joven la licencia de Nivel 1 antes de pasar al Nivel 2?","o":["Tres meses","Seis meses","Un año","Dos años"],"h1":"Es la mitad de un año.","h2":"Un joven debe manejar con licencia de Nivel 1 por lo menos seis meses antes de pasar al Nivel 2, para ganar experiencia supervisada.","p":"Correcto. El Nivel 1 dura por lo menos seis meses."},"ref":{"doc":"MI","page":5}},{"id":"mi-005","scope":"MI","cat":"licensing","sign":null,"c":3,"en":{"q":"In Michigan, how many hours of supervised driving must a teen log before Level 2?","o":["30 hours","40 hours","60 hours","50 hours"],"h1":"It is half of one hundred.","h2":"A teen must log at least 50 hours of supervised driving before a Level 2 license, to build steady skills with an adult beside them.","p":"Right. Michigan asks for at least 50 supervised hours."},"es":{"q":"En Michigan, ¿cuántas horas de manejo supervisado debe registrar un joven antes del Nivel 2?","o":["30 horas","40 horas","60 horas","50 horas"],"h1":"Es la mitad de cien.","h2":"Un joven debe registrar por lo menos 50 horas de manejo supervisado antes de la licencia de Nivel 2, para ganar habilidad con un adulto a su lado.","p":"Correcto. Michigan pide por lo menos 50 horas supervisadas."},"ref":{"doc":"MI","page":5}},{"id":"mi-006","scope":"MI","cat":"licensing","sign":null,"c":0,"en":{"q":"In Michigan, how many of the supervised hours before Level 2 must be at night?","o":["At least 10 hours","At least 2 hours","At least 20 hours","At least 25 hours"],"h1":"It is one fifth of the total hours.","h2":"At least 10 of the 50 supervised hours must be driven at night, because darkness makes driving harder.","p":"Right. At least 10 of the hours must be at night."},"es":{"q":"En Michigan, ¿cuántas de las horas supervisadas antes del Nivel 2 deben ser de noche?","o":["Por lo menos 10 horas","Por lo menos 2 horas","Por lo menos 20 horas","Por lo menos 25 horas"],"h1":"Es la quinta parte del total de horas.","h2":"Por lo menos 10 de las 50 horas supervisadas deben ser de noche, porque la oscuridad hace más difícil manejar.","p":"Correcto. Por lo menos 10 horas deben ser de noche."},"ref":{"doc":"MI","page":5}},{"id":"mi-007","scope":"MI","cat":"licensing","sign":null,"c":2,"en":{"q":"In Michigan, what is the youngest age for a Level 2 Intermediate License?","o":["15 years old","15 and a half years old","16 years old","17 years old"],"h1":"It is the same age many states use for a first license.","h2":"You can get a Michigan Level 2 Intermediate License at 16, after finishing Segment 2 and passing a driving skills test.","p":"Right. Level 2 starts at age 16."},"es":{"q":"En Michigan, ¿cuál es la edad mínima para la licencia intermedia de Nivel 2?","o":["15 años","15 años y medio","16 años","17 años"],"h1":"Es la misma edad que muchos estados usan para la primera licencia.","h2":"Usted puede obtener la licencia intermedia de Nivel 2 en Michigan a los 16 años, después de terminar el Segmento 2 y aprobar el examen práctico de manejo.","p":"Correcto. El Nivel 2 empieza a los 16 años."},"ref":{"doc":"MI","page":5}},{"id":"mi-008","scope":"MI","cat":"licensing","sign":null,"c":1,"en":{"q":"In Michigan, how long must a teen go with no tickets, suspensions or at-fault crashes right before applying for Level 2?","o":["30 days","90 days","180 days","One year"],"h1":"It is about three months.","h2":"A teen needs a clean record for the 90 days just before applying for Level 2, showing they can drive safely.","p":"Right. You need 90 days with a clean record."},"es":{"q":"En Michigan, ¿cuánto tiempo debe pasar un joven sin multas, suspensiones ni choques de los que sea culpable justo antes de solicitar el Nivel 2?","o":["30 días","90 días","180 días","Un año"],"h1":"Son unos tres meses.","h2":"Un joven necesita un récord limpio durante los 90 días justo antes de solicitar el Nivel 2, para mostrar que maneja con seguridad.","p":"Correcto. Necesita 90 días con récord limpio."},"ref":{"doc":"MI","page":5}},{"id":"mi-009","scope":"MI","cat":"licensing","sign":null,"c":0,"en":{"q":"In Michigan, during which hours may a Level 2 driver not drive without an adult, unless an exception applies?","o":["10 p.m. to 5 a.m.","Midnight to 5 a.m.","11 p.m. to 6 a.m.","9 p.m. to 6 a.m."],"h1":"It starts two hours before midnight.","h2":"A Level 2 driver may not drive between 10 p.m. and 5 a.m. unless going to or from work or an approved activity, or with a parent, guardian or approved adult 21 or older.","p":"Right. Level 2 drivers stay off the road from 10 p.m. to 5 a.m."},"es":{"q":"En Michigan, ¿en qué horario no puede manejar un conductor de Nivel 2 sin un adulto, salvo una excepción?","o":["De 10 p.m. a 5 a.m.","De medianoche a 5 a.m.","De 11 p.m. a 6 a.m.","De 9 p.m. a 6 a.m."],"h1":"Empieza dos horas antes de la medianoche.","h2":"Un conductor de Nivel 2 no puede manejar entre las 10 p.m. y las 5 a.m., salvo que vaya o vuelva del trabajo o de una actividad autorizada, o con su padre, madre, tutor o un adulto aprobado de 21 años o más.","p":"Correcto. Los conductores de Nivel 2 no manejan de 10 p.m. a 5 a.m."},"ref":{"doc":"MI","page":5}},{"id":"mi-010","scope":"MI","cat":"licensing","sign":null,"c":2,"en":{"q":"In Michigan, which trip may a Level 2 driver make alone during the night limit hours?","o":["Driving friends home from a party","Driving to a late restaurant","Driving to or from a job","Driving around to practice"],"h1":"The exception is about earning a living.","h2":"A Level 2 driver may drive during the night limit hours when going to or from work, or while working.","p":"Right. Driving to or from work is an exception."},"es":{"q":"En Michigan, ¿qué viaje puede hacer solo un conductor de Nivel 2 en las horas de límite nocturno?","o":["Llevar a amigos a casa después de una fiesta","Ir a un restaurante tarde","Ir o volver del trabajo","Manejar por ahí para practicar"],"h1":"La excepción tiene que ver con ganarse la vida.","h2":"Un conductor de Nivel 2 puede manejar en las horas de límite nocturno cuando va o vuelve del trabajo, o mientras trabaja.","p":"Correcto. Ir o volver del trabajo es una excepción."},"ref":{"doc":"MI","page":5}},{"id":"mi-011","scope":"MI","cat":"licensing","sign":null,"c":3,"en":{"q":"In Michigan, how many passengers under 21 may a Level 2 driver carry, not counting family?","o":["None at all","Two","Three","One"],"h1":"More than zero, but fewer than two.","h2":"A Level 2 driver may carry no more than one passenger under 21, except for members of their own family, because young passengers raise crash risk.","p":"Right. Only one passenger under 21, besides family."},"es":{"q":"En Michigan, ¿cuántos pasajeros menores de 21 años puede llevar un conductor de Nivel 2, sin contar a la familia?","o":["Ninguno","Dos","Tres","Uno"],"h1":"Más que cero, pero menos que dos.","h2":"Un conductor de Nivel 2 no puede llevar más de un pasajero menor de 21 años, sin contar a su familia, porque los pasajeros jóvenes aumentan el riesgo de choque.","p":"Correcto. Solo un pasajero menor de 21, además de la familia."},"ref":{"doc":"MI","page":5}},{"id":"mi-012","scope":"MI","cat":"licensing","sign":null,"c":1,"en":{"q":"In Michigan, what is the youngest age to move to a Level 3 full license?","o":["16 years old","17 years old","18 years old","21 years old"],"h1":"It is one year after the youngest Level 2 age.","h2":"A teen can move up to a Level 3 license at 17 at the earliest, if all requirements are met and a parent agrees.","p":"Right. Level 3 can start at age 17."},"es":{"q":"En Michigan, ¿cuál es la edad mínima para pasar a la licencia completa de Nivel 3?","o":["16 años","17 años","18 años","21 años"],"h1":"Es un año después de la edad mínima del Nivel 2.","h2":"Un joven puede pasar a la licencia de Nivel 3 a los 17 años como mínimo, si cumple todos los requisitos y uno de sus padres está de acuerdo.","p":"Correcto. El Nivel 3 puede empezar a los 17 años."},"ref":{"doc":"MI","page":5}},{"id":"mi-013","scope":"MI","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Michigan, Kelsey’s Law limits cell phone use for which drivers?","o":["All drivers over 65","Drivers of school buses only","Drivers with a Level 1 or Level 2 license","Only drivers with a past crash"],"h1":"It is about the newest drivers.","h2":"Kelsey’s Law limits phone use by drivers who hold a Level 1 or Level 2 license, because new drivers are easily distracted; calls for emergencies are allowed.","p":"Right. Kelsey’s Law covers Level 1 and Level 2 drivers."},"es":{"q":"En Michigan, ¿a qué conductores les limita el uso del celular la Ley de Kelsey?","o":["A todos los conductores mayores de 65","Solo a choferes de autobús escolar","A conductores con licencia de Nivel 1 o Nivel 2","Solo a conductores que ya tuvieron un choque"],"h1":"Se trata de los conductores más nuevos.","h2":"La Ley de Kelsey limita el uso del teléfono a quienes tienen licencia de Nivel 1 o Nivel 2, porque los conductores nuevos se distraen fácilmente; las llamadas de emergencia se permiten.","p":"Correcto. La Ley de Kelsey aplica a conductores de Nivel 1 y Nivel 2."},"ref":{"doc":"MI","page":24}},{"id":"mi-014","scope":"MI","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Michigan, you are stopped at a red light. May you hold your phone in your hand?","o":["No, holding a phone is not allowed even while stopped in traffic","Yes, because the car is not moving","Yes, if you only read messages","Yes, if the light is long"],"h1":"Michigan’s hands-free law does not stop at red lights.","h2":"Michigan law does not let you hold a phone while driving, and that includes waiting at a red light or in stopped traffic.","p":"Right. No holding the phone, even at a red light."},"es":{"q":"En Michigan, usted está detenido en una luz roja. ¿Puede tener el teléfono en la mano?","o":["No, no se permite tener el teléfono en la mano ni detenido en el tráfico","Sí, porque el carro no se mueve","Sí, si solo lee mensajes","Sí, si la luz es larga"],"h1":"La ley de manos libres de Michigan no se detiene en las luces rojas.","h2":"La ley de Michigan no le permite tener el teléfono en la mano mientras maneja, y eso incluye esperar en una luz roja o en tráfico detenido.","p":"Correcto. No puede tener el teléfono en la mano, ni en una luz roja."},"ref":{"doc":"MI","page":null}},{"id":"mi-015","scope":"MI","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Michigan, you pass a stopped emergency vehicle with its lights on and cannot move over. How much must you slow down?","o":["To 5 mph below the speed limit","To at least 10 mph below the speed limit","To 15 mph below the speed limit","To exactly 20 mph"],"h1":"It is a round number, and it is the least you must slow.","h2":"If you cannot move over safely, you must slow to at least 10 mph below the posted speed limit and pass with care.","p":"Right. Slow to at least 10 mph below the limit."},"es":{"q":"En Michigan, usted pasa junto a un vehículo de emergencia detenido con las luces encendidas y no puede cambiarse de carril. ¿Cuánto debe bajar la velocidad?","o":["A 5 mph menos del límite","A por lo menos 10 mph menos del límite","A 15 mph menos del límite","Exactamente a 20 mph"],"h1":"Es un número redondo, y es lo mínimo que debe bajar.","h2":"Si no puede cambiarse de carril con seguridad, debe bajar a por lo menos 10 mph menos del límite indicado y pasar con cuidado.","p":"Correcto. Baje a por lo menos 10 mph menos del límite."},"ref":{"doc":"MI","page":28}},{"id":"mi-016","scope":"MI","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Michigan, besides police, fire and ambulance vehicles, which stopped vehicle with flashing lights must you move over for?","o":["A parked delivery van","A car with a flat tire and no lights","A school bus with no lights on","A garbage truck or utility truck with its lights on"],"h1":"It is a work vehicle using warning lights.","h2":"Michigan’s move-over law also covers tow trucks, road crews, utility trucks and garbage trucks that are stopped with their lights flashing.","p":"Right. Move over for work trucks with flashing lights, too."},"es":{"q":"En Michigan, además de policía, bomberos y ambulancias, ¿por qué vehículo detenido con luces intermitentes debe cambiarse de carril?","o":["Una camioneta de reparto estacionada","Un carro con una llanta ponchada y sin luces","Un autobús escolar sin luces encendidas","Un camión de basura o de servicios públicos con las luces encendidas"],"h1":"Es un vehículo de trabajo que usa luces de aviso.","h2":"La ley de Michigan también cubre grúas, cuadrillas de carreteras, camiones de servicios públicos y camiones de basura detenidos con luces intermitentes.","p":"Correcto. También cámbiese de carril por camiones de trabajo con luces intermitentes."},"ref":{"doc":"MI","page":28}},{"id":"mi-017","scope":"MI","cat":"signals","sign":null,"c":2,"en":{"q":"In Michigan, when may you turn left on a red light?","o":["Never, under any condition","Whenever no cars are coming","After a full stop, onto a one-way street going left, unless a sign forbids it","Only when a green arrow is also shown"],"h1":"The street you turn into must carry traffic only in the direction of your turn.","h2":"You may turn left on red onto a one-way street whose traffic moves to the left, after a full stop and after yielding, unless a sign forbids it.","p":"Right. Left on red is allowed onto a one-way street, after a full stop."},"es":{"q":"En Michigan, ¿cuándo puede doblar a la izquierda con luz roja?","o":["Nunca, en ninguna situación","Siempre que no vengan carros","Después de un alto total, hacia una calle de un solo sentido que va a la izquierda, salvo que una señal lo prohíba","Solo cuando también hay una flecha verde"],"h1":"La calle a la que entra debe llevar tráfico solo en la dirección de su vuelta.","h2":"Usted puede doblar a la izquierda con luz roja hacia una calle de un solo sentido cuyo tráfico va a la izquierda, después de un alto total y de ceder el paso, salvo que una señal lo prohíba.","p":"Correcto. Se permite a la izquierda con luz roja hacia una calle de un solo sentido, después de un alto total."},"ref":{"doc":"MI","page":30}},{"id":"mi-018","scope":"MI","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Michigan, a school bus stops with flashing red lights on the other side of a highway divided by a median or barrier. Who must stop?","o":["Only traffic going the same direction as the bus","Traffic going both directions","No one, because it is a highway","Only trucks and buses"],"h1":"The divider protects the far side.","h2":"On a highway divided by a median or barrier, only traffic going the same way as the bus must stop; traffic on the other side should still drive with care.","p":"Right. On a divided highway, only traffic going the bus’s way stops."},"es":{"q":"En Michigan, un autobús escolar se detiene con luces rojas intermitentes en el otro lado de una carretera dividida por una mediana o barrera. ¿Quién debe detenerse?","o":["Solo el tráfico que va en la misma dirección que el autobús","El tráfico en ambas direcciones","Nadie, porque es una carretera","Solo camiones y autobuses"],"h1":"La división protege el lado de enfrente.","h2":"En una carretera dividida por una mediana o barrera, solo el tráfico que va en la misma dirección que el autobús debe detenerse; el tráfico del otro lado igual debe manejar con cuidado.","p":"Correcto. En una carretera dividida, solo se detiene el tráfico que va en la dirección del autobús."},"ref":{"doc":"MI","page":28}},{"id":"mi-019","scope":"MI","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Michigan, how far from a stopped school bus with flashing red lights must you stop?","o":["At least 10 feet","At least 20 feet","At least 30 feet","At least 50 feet"],"h1":"It is a bit longer than one car.","h2":"You must stop at least 20 feet from a school bus with flashing red lights and wait until it moves or the lights stop.","p":"Right. Stop at least 20 feet from the bus."},"es":{"q":"En Michigan, ¿a qué distancia de un autobús escolar detenido con luces rojas intermitentes debe detenerse?","o":["Por lo menos a 10 pies","Por lo menos a 20 pies","Por lo menos a 30 pies","Por lo menos a 50 pies"],"h1":"Es un poco más largo que un carro.","h2":"Usted debe detenerse por lo menos a 20 pies de un autobús escolar con luces rojas intermitentes y esperar a que avance o se apaguen las luces.","p":"Correcto. Deténgase por lo menos a 20 pies del autobús."},"ref":{"doc":"MI","page":28}},{"id":"mi-020","scope":"MI","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Michigan, on a limited-access freeway with no posted speed limit, what is the top legal speed?","o":["55 mph","60 mph","65 mph","70 mph"],"h1":"It is higher than the limit for ordinary highways with no sign.","h2":"On a limited-access freeway with no posted limit, the top legal speed is 70 mph; some rural freeways are posted higher.","p":"Right. The default freeway limit is 70 mph."},"es":{"q":"En Michigan, en una autopista de acceso limitado sin límite indicado, ¿cuál es la velocidad máxima legal?","o":["55 mph","60 mph","65 mph","70 mph"],"h1":"Es más alta que el límite de carreteras comunes sin señal.","h2":"En una autopista de acceso limitado sin límite indicado, la velocidad máxima legal es 70 mph; algunas autopistas rurales tienen señales con un límite más alto.","p":"Correcto. El límite normal en autopista es 70 mph."},"ref":{"doc":"MI","page":26}},{"id":"mi-021","scope":"MI","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Michigan, on a state or county highway with no posted speed limit, what is the top legal speed?","o":["55 mph","45 mph","65 mph","70 mph"],"h1":"It is lower than the freeway default.","h2":"On a state trunkline or county highway with no posted limit, the top legal speed is 55 mph.","p":"Right. The default on these highways is 55 mph."},"es":{"q":"En Michigan, en una carretera estatal o del condado sin límite indicado, ¿cuál es la velocidad máxima legal?","o":["55 mph","45 mph","65 mph","70 mph"],"h1":"Es más bajo que el límite normal de autopista.","h2":"En una carretera troncal estatal o del condado sin límite indicado, la velocidad máxima legal es 55 mph.","p":"Correcto. El límite normal en estas carreteras es 55 mph."},"ref":{"doc":"MI","page":26}},{"id":"mi-022","scope":"MI","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Michigan, what is the highest speed limit posted on some rural freeways?","o":["65 mph","70 mph","75 mph","80 mph"],"h1":"It is 5 mph above the freeway default.","h2":"Michigan posts a 75 mph limit on some rural freeways; you may go that fast only where the signs say so.","p":"Right. Some rural freeways are posted at 75 mph."},"es":{"q":"En Michigan, ¿cuál es el límite de velocidad más alto indicado en algunas autopistas rurales?","o":["65 mph","70 mph","75 mph","80 mph"],"h1":"Es 5 mph más que el límite normal de autopista.","h2":"Michigan indica un límite de 75 mph en algunas autopistas rurales; usted solo puede ir tan rápido donde las señales lo dicen.","p":"Correcto. Algunas autopistas rurales tienen límite de 75 mph."},"ref":{"doc":"MI","page":null}},{"id":"mi-023","scope":"MI","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Michigan, what is the speed limit in a residential subdivision?","o":["20 mph","25 mph","30 mph","35 mph"],"h1":"It is the same number many states use near homes.","h2":"The speed limit in a residential subdivision is 25 mph, because children and people walking are often near the street.","p":"Right. Residential subdivisions are 25 mph."},"es":{"q":"En Michigan, ¿cuál es el límite de velocidad en un fraccionamiento residencial?","o":["20 mph","25 mph","30 mph","35 mph"],"h1":"Es el mismo número que muchos estados usan cerca de las casas.","h2":"El límite de velocidad en un fraccionamiento residencial es 25 mph, porque a menudo hay niños y peatones cerca de la calle.","p":"Correcto. En fraccionamientos residenciales el límite es 25 mph."},"ref":{"doc":"MI","page":26}},{"id":"mi-024","scope":"MI","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Michigan, what is the speed limit inside a mobile home park?","o":["5 mph","10 mph","20 mph","15 mph"],"h1":"It is lower than a residential subdivision, but more than 10.","h2":"The speed limit inside a mobile home park is 15 mph, because homes and people are very close to the road.","p":"Right. Mobile home parks are 15 mph."},"es":{"q":"En Michigan, ¿cuál es el límite de velocidad dentro de un parque de casas móviles?","o":["5 mph","10 mph","20 mph","15 mph"],"h1":"Es más bajo que en un fraccionamiento residencial, pero más de 10.","h2":"El límite de velocidad dentro de un parque de casas móviles es 15 mph, porque las casas y las personas están muy cerca del camino.","p":"Correcto. En parques de casas móviles el límite es 15 mph."},"ref":{"doc":"MI","page":26}},{"id":"mi-025","scope":"MI","cat":"licensing","sign":null,"c":2,"en":{"q":"In Michigan, at what blood alcohol level does the stricter high-BAC drunk driving law apply?","o":["0.10 percent or more","0.12 percent or more","0.17 percent or more","0.20 percent or more"],"h1":"It is about twice the regular adult limit.","h2":"Michigan’s high-BAC law, sometimes called the super drunk law, applies at 0.17 percent or more and carries harsher penalties than a regular drunk driving charge.","p":"Right. The high-BAC law starts at 0.17 percent."},"es":{"q":"En Michigan, ¿a partir de qué nivel de alcohol en la sangre se aplica la ley más estricta de alto nivel de alcohol?","o":["0.10 por ciento o más","0.12 por ciento o más","0.17 por ciento o más","0.20 por ciento o más"],"h1":"Es casi el doble del límite normal para adultos.","h2":"La ley de alto nivel de alcohol de Michigan, a veces llamada ley de súper ebrio, aplica desde 0.17 por ciento y trae castigos más duros que un cargo normal por manejar ebrio.","p":"Correcto. La ley de alto nivel empieza en 0.17 por ciento."},"ref":{"doc":"MI","page":null}},{"id":"mi-026","scope":"MI","cat":"licensing","sign":null,"c":0,"en":{"q":"In Michigan, a driver 21 or older is legally drunk at what blood alcohol level?","o":["0.08 percent or more","0.05 percent or more","0.10 percent or more","0.15 percent or more"],"h1":"It is less than one tenth of one percent.","h2":"A driver 21 or older breaks Michigan’s drunk driving law at a blood alcohol level of 0.08 percent or more.","p":"Right. The adult limit is 0.08 percent."},"es":{"q":"En Michigan, ¿con qué nivel de alcohol en la sangre se considera legalmente ebrio a un conductor de 21 años o más?","o":["0.08 por ciento o más","0.05 por ciento o más","0.10 por ciento o más","0.15 por ciento o más"],"h1":"Es menos de una décima de uno por ciento.","h2":"Un conductor de 21 años o más viola la ley de Michigan sobre manejar ebrio con 0.08 por ciento o más de alcohol en la sangre.","p":"Correcto. El límite para adultos es 0.08 por ciento."},"ref":{"doc":"MI","page":null}},{"id":"mi-027","scope":"MI","cat":"licensing","sign":null,"c":1,"en":{"q":"In Michigan, how much alcohol may a driver under 21 have in their body?","o":["Up to 0.08 percent","No alcohol from drinking at all","Up to 0.05 percent","Up to 0.10 percent at night"],"h1":"This is called zero tolerance.","h2":"Michigan has zero tolerance for drivers under 21: a level of 0.02 percent, or any alcohol from drinking, breaks the law.","p":"Right. Drivers under 21 may not drive with alcohol from drinking."},"es":{"q":"En Michigan, ¿cuánto alcohol puede tener en el cuerpo un conductor menor de 21 años?","o":["Hasta 0.08 por ciento","Nada de alcohol por haber tomado","Hasta 0.05 por ciento","Hasta 0.10 por ciento de noche"],"h1":"Esto se llama tolerancia cero.","h2":"Michigan tiene tolerancia cero para conductores menores de 21 años: un nivel de 0.02 por ciento, o cualquier alcohol por haber tomado, viola la ley.","p":"Correcto. Los menores de 21 no pueden manejar con alcohol por haber tomado."},"ref":{"doc":"MI","page":14}},{"id":"mi-028","scope":"MI","cat":"licensing","sign":null,"c":3,"en":{"q":"In Michigan, what kind of car insurance must every vehicle owner carry?","o":["Only collision coverage","Only coverage for the other driver’s car","No insurance is required","No-fault insurance that includes personal injury protection"],"h1":"Michigan is known as a no-fault state.","h2":"Michigan is a no-fault state, so every owner must carry no-fault insurance with personal injury protection, which pays your own medical costs after a crash.","p":"Right. Michigan requires no-fault insurance with personal injury protection."},"es":{"q":"En Michigan, ¿qué tipo de seguro de carro debe tener todo dueño de vehículo?","o":["Solo cobertura de choque","Solo cobertura para el carro del otro conductor","No se requiere seguro","Seguro sin culpa que incluye protección por lesiones personales"],"h1":"Michigan es conocido como un estado sin culpa.","h2":"Michigan es un estado sin culpa, así que todo dueño debe tener seguro sin culpa con protección por lesiones personales, que paga sus propios gastos médicos después de un choque.","p":"Correcto. Michigan exige seguro sin culpa con protección por lesiones personales."},"ref":{"doc":"MI","page":null}},{"id":"mn-001","scope":"MN","cat":"licensing","sign":null,"c":1,"en":{"q":"In Minnesota, what is the youngest age to get an instruction permit?","o":["14 years old","15 years old","16 years old","17 years old"],"h1":"It is one year before the provisional license.","h2":"You can get a Minnesota instruction permit at 15 after starting driver education, so you can practice before the provisional license at 16.","p":"Right. The Minnesota permit starts at 15."},"es":{"q":"En Minnesota, ¿cuál es la edad mínima para obtener un permiso de aprendizaje?","o":["14 años","15 años","16 años","17 años"],"h1":"Es un año antes de la licencia provisional.","h2":"Usted puede obtener el permiso de aprendizaje en Minnesota a los 15 años después de empezar la educación vial, para practicar antes de la licencia provisional a los 16.","p":"Correcto. El permiso en Minnesota empieza a los 15."},"ref":{"doc":"MN","page":13}},{"id":"mn-002","scope":"MN","cat":"licensing","sign":null,"c":2,"en":{"q":"In Minnesota, how old must the licensed driver be who supervises a permit holder under 18?","o":["At least 16","At least 18","At least 21","At least 25"],"h1":"The helper must be an adult who can legally drink.","h2":"A Minnesota permit holder under 18 must drive with a licensed driver who is at least 21, so an experienced adult is guiding them.","p":"Right. The supervisor must be 21 or older."},"es":{"q":"En Minnesota, ¿qué edad debe tener el conductor con licencia que supervisa a alguien con permiso menor de 18?","o":["Por lo menos 16","Por lo menos 18","Por lo menos 21","Por lo menos 25"],"h1":"El acompañante debe ser un adulto que ya puede tomar alcohol legalmente.","h2":"Quien tiene permiso en Minnesota y es menor de 18 debe manejar con un conductor con licencia de por lo menos 21 años, para que lo guíe un adulto con experiencia.","p":"Correcto. El supervisor debe tener 21 años o más."},"ref":{"doc":"MN","page":13}},{"id":"mn-003","scope":"MN","cat":"licensing","sign":null,"c":0,"en":{"q":"In Minnesota, where must the supervising driver sit when a permit holder is driving?","o":["In the front passenger seat","In the back seat","Anywhere in the vehicle","Behind the driver"],"h1":"They must be close enough to help at once.","h2":"The supervising driver must sit in the front passenger seat when a Minnesota permit holder drives, so they can see the road and help quickly.","p":"Right. The supervisor sits in the front passenger seat."},"es":{"q":"En Minnesota, ¿dónde debe sentarse el conductor supervisor cuando maneja alguien con permiso?","o":["En el asiento del pasajero delantero","En el asiento de atrás","En cualquier lugar del vehículo","Detrás del conductor"],"h1":"Debe estar lo bastante cerca para ayudar enseguida.","h2":"El conductor supervisor debe sentarse en el asiento del pasajero delantero cuando maneja alguien con permiso en Minnesota, para ver la vía y ayudar rápido.","p":"Correcto. El supervisor va en el asiento delantero."},"ref":{"doc":"MN","page":13}},{"id":"mn-004","scope":"MN","cat":"licensing","sign":null,"c":3,"en":{"q":"In Minnesota, how long must a teen hold an instruction permit before applying for a provisional license?","o":["1 month","3 months","1 year","6 months"],"h1":"It is half a year.","h2":"A Minnesota teen must hold the instruction permit for the six months right before applying, with no serious traffic convictions.","p":"Right. Hold the permit for six months."},"es":{"q":"En Minnesota, ¿cuánto tiempo debe tener un adolescente el permiso de aprendizaje antes de solicitar la licencia provisional?","o":["1 mes","3 meses","1 año","6 meses"],"h1":"Es medio año.","h2":"Un adolescente en Minnesota debe tener el permiso de aprendizaje durante los seis meses justo antes de solicitar, sin condenas graves de tránsito.","p":"Correcto. Debe tener el permiso seis meses."},"ref":{"doc":"MN","page":14}},{"id":"mn-005","scope":"MN","cat":"licensing","sign":null,"c":1,"en":{"q":"In Minnesota, which of these can stop a teen from getting a provisional license after six months on a permit?","o":["Getting a parking ticket","A moving violation conviction","Having a passenger in the car","Driving at night with a parent"],"h1":"The six months must be clean of driving offenses.","h2":"A Minnesota teen must have no convictions for moving violations or alcohol and drug offenses during the six months on the permit.","p":"Right. A moving violation conviction can delay the provisional license."},"es":{"q":"En Minnesota, ¿cuál de estas cosas puede impedir que un adolescente obtenga la licencia provisional después de seis meses con permiso?","o":["Recibir una multa de estacionamiento","Una condena por una infracción en movimiento","Llevar un pasajero en el carro","Manejar de noche con un padre"],"h1":"Los seis meses deben estar limpios de infracciones al manejar.","h2":"Un adolescente en Minnesota no debe tener condenas por infracciones de tránsito en movimiento ni por alcohol o drogas durante los seis meses con el permiso.","p":"Correcto. Una infracción en movimiento puede retrasar la licencia provisional."},"ref":{"doc":"MN","page":14}},{"id":"mn-006","scope":"MN","cat":"licensing","sign":null,"c":0,"en":{"q":"In Minnesota, what is the youngest age to get a provisional license?","o":["16 years old","15 years old","17 years old","18 years old"],"h1":"It comes one year after the instruction permit.","h2":"A Minnesota teen can get a provisional license at 16 after holding an instruction permit for six months.","p":"Right. The provisional license starts at 16."},"es":{"q":"En Minnesota, ¿cuál es la edad mínima para obtener la licencia provisional?","o":["16 años","15 años","17 años","18 años"],"h1":"Viene un año después del permiso de aprendizaje.","h2":"Un adolescente en Minnesota puede obtener la licencia provisional a los 16 años después de tener el permiso de aprendizaje seis meses.","p":"Correcto. La licencia provisional empieza a los 16."},"ref":{"doc":"MN","page":14}},{"id":"mn-007","scope":"MN","cat":"licensing","sign":null,"c":3,"en":{"q":"In Minnesota, if the parent does not take the supplemental parent class, how many supervised hours must a teen log?","o":["30 hours","40 hours","60 hours","50 hours"],"h1":"The parent class lowers this number by ten.","h2":"Without the supplemental parent class, a Minnesota teen must log at least 50 hours of supervised driving, with at least 15 at night.","p":"Right. Without the parent class, the teen logs 50 hours."},"es":{"q":"En Minnesota, si el padre no toma la clase complementaria para padres, ¿cuántas horas supervisadas debe registrar el adolescente?","o":["30 horas","40 horas","60 horas","50 horas"],"h1":"La clase para padres baja este número en diez.","h2":"Sin la clase complementaria para padres, un adolescente en Minnesota debe registrar por lo menos 50 horas de manejo supervisado, con por lo menos 15 de noche.","p":"Correcto. Sin la clase para padres, el adolescente registra 50 horas."},"ref":{"doc":"MN","page":14}},{"id":"mn-008","scope":"MN","cat":"licensing","sign":null,"c":1,"en":{"q":"In Minnesota, if a parent completes the supplemental parent class, how many supervised hours must the teen log?","o":["30 hours","40 hours","50 hours","60 hours"],"h1":"It is ten fewer than without the class.","h2":"When a parent completes the supplemental parent class, a Minnesota teen must log at least 40 hours of supervised driving, with at least 15 at night.","p":"Right. With the parent class, the teen logs 40 hours."},"es":{"q":"En Minnesota, si un padre completa la clase complementaria para padres, ¿cuántas horas supervisadas debe registrar el adolescente?","o":["30 horas","40 horas","50 horas","60 horas"],"h1":"Son diez menos que sin la clase.","h2":"Cuando un padre completa la clase complementaria para padres, un adolescente en Minnesota debe registrar por lo menos 40 horas de manejo supervisado, con por lo menos 15 de noche.","p":"Correcto. Con la clase para padres, el adolescente registra 40 horas."},"ref":{"doc":"MN","page":14}},{"id":"mn-009","scope":"MN","cat":"licensing","sign":null,"c":2,"en":{"q":"In Minnesota, how many of the supervised practice hours must be at night?","o":["5 hours","10 hours","15 hours","20 hours"],"h1":"The number is the same with or without the parent class.","h2":"A Minnesota teen must log at least 15 hours of supervised driving at night, whether or not a parent took the supplemental class.","p":"Right. At least 15 hours must be at night."},"es":{"q":"En Minnesota, ¿cuántas de las horas de práctica supervisada deben ser de noche?","o":["5 horas","10 horas","15 horas","20 horas"],"h1":"El número es el mismo con o sin la clase para padres.","h2":"Un adolescente en Minnesota debe registrar por lo menos 15 horas de manejo supervisado de noche, haya tomado o no un padre la clase complementaria.","p":"Correcto. Por lo menos 15 horas deben ser de noche."},"ref":{"doc":"MN","page":14}},{"id":"mn-010","scope":"MN","cat":"licensing","sign":null,"c":0,"en":{"q":"In Minnesota, during the first six months of a provisional license, when may a teen NOT drive alone?","o":["Midnight to 5 a.m.","10 p.m. to 6 a.m.","9 p.m. to 5 a.m.","11 p.m. to 4 a.m."],"h1":"The limit begins when a new day starts.","h2":"For the first six months of a Minnesota provisional license, a teen may not drive from midnight to 5 a.m., unless a licensed driver 25 or older is along or the trip is for work or a school event.","p":"Right. No driving from midnight to 5 a.m. at first."},"es":{"q":"En Minnesota, durante los primeros seis meses de la licencia provisional, ¿en qué horario NO puede manejar solo el adolescente?","o":["De medianoche a 5 a.m.","De 10 p.m. a 6 a.m.","De 9 p.m. a 5 a.m.","De 11 p.m. a 4 a.m."],"h1":"El límite empieza cuando comienza un nuevo día.","h2":"Durante los primeros seis meses de la licencia provisional en Minnesota, el adolescente no puede manejar de medianoche a las 5 a.m., salvo que lo acompañe un conductor con licencia de 25 años o más o que el viaje sea por trabajo o por un evento escolar.","p":"Correcto. Al principio no se maneja de medianoche a 5 a.m."},"ref":{"doc":"MN","page":14}},{"id":"mn-011","scope":"MN","cat":"licensing","sign":null,"c":2,"en":{"q":"In Minnesota, in the first six months of a provisional license, who can ride along so the teen may drive at 2 a.m.?","o":["Any friend who is 18","A brother who has a permit","A licensed driver age 25 or older","Any adult passenger"],"h1":"The person must be licensed and older than most college students.","h2":"A Minnesota provisional driver may drive between midnight and 5 a.m. in the first six months when a licensed driver who is at least 25 rides along.","p":"Right. A licensed driver 25 or older makes it legal."},"es":{"q":"En Minnesota, en los primeros seis meses de la licencia provisional, ¿quién puede acompañar al adolescente para que maneje a las 2 a.m.?","o":["Cualquier amigo de 18 años","Un hermano que tiene permiso","Un conductor con licencia de 25 años o más","Cualquier pasajero adulto"],"h1":"La persona debe tener licencia y ser mayor que la mayoría de los universitarios.","h2":"Un conductor provisional en Minnesota puede manejar entre medianoche y 5 a.m. en los primeros seis meses si lo acompaña un conductor con licencia de por lo menos 25 años.","p":"Correcto. Un conductor con licencia de 25 años o más lo hace legal."},"ref":{"doc":"MN","page":14}},{"id":"mn-012","scope":"MN","cat":"licensing","sign":null,"c":1,"en":{"q":"In Minnesota, in the first six months of a provisional license, how many passengers under 20 who are not family may the teen carry?","o":["None","One","Two","Three"],"h1":"It is the smallest number above zero.","h2":"For the first six months, a Minnesota provisional driver may carry only one passenger under 20 who is not immediate family, because young passengers distract new drivers.","p":"Right. Only one young passenger who is not family at first."},"es":{"q":"En Minnesota, en los primeros seis meses de la licencia provisional, ¿cuántos pasajeros menores de 20 que no son familia puede llevar el adolescente?","o":["Ninguno","Uno","Dos","Tres"],"h1":"Es el número más pequeño mayor que cero.","h2":"Durante los primeros seis meses, un conductor provisional en Minnesota puede llevar solo un pasajero menor de 20 que no sea familia directa, porque los pasajeros jóvenes distraen a los conductores nuevos.","p":"Correcto. Al principio solo un pasajero joven que no sea familia."},"ref":{"doc":"MN","page":15}},{"id":"mn-013","scope":"MN","cat":"licensing","sign":null,"c":3,"en":{"q":"In Minnesota, in months 7 to 12 of a provisional license, how many passengers under 20 who are not family may the teen carry?","o":["One","Two","Four","Three"],"h1":"The limit grows after the first six months.","h2":"In months 7 to 12, a Minnesota provisional driver may carry up to three passengers under 20 who are not immediate family; after 12 months the limit ends.","p":"Right. Up to three young passengers in months 7 to 12."},"es":{"q":"En Minnesota, en los meses 7 a 12 de la licencia provisional, ¿cuántos pasajeros menores de 20 que no son familia puede llevar el adolescente?","o":["Uno","Dos","Cuatro","Tres"],"h1":"El límite crece después de los primeros seis meses.","h2":"En los meses 7 a 12, un conductor provisional en Minnesota puede llevar hasta tres pasajeros menores de 20 que no sean familia directa; después de 12 meses el límite termina.","p":"Correcto. Hasta tres pasajeros jóvenes en los meses 7 a 12."},"ref":{"doc":"MN","page":15}},{"id":"mn-014","scope":"MN","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Minnesota, may a 16-year-old with a provisional license use a hands-free phone while driving?","o":["Yes, hands-free is always allowed","Yes, but only on freeways","No, not even hands-free","Yes, for calls under one minute"],"h1":"Teen drivers have a stricter rule than adults.","h2":"A Minnesota driver under 18 with a permit or provisional license may not use a phone while the car is moving, hand-held or hands-free.","p":"Right. Under 18, no phone at all while moving."},"es":{"q":"En Minnesota, ¿puede un joven de 16 años con licencia provisional usar el teléfono con manos libres mientras maneja?","o":["Sí, manos libres siempre está permitido","Sí, pero solo en autopistas","No, ni siquiera con manos libres","Sí, para llamadas de menos de un minuto"],"h1":"Los conductores adolescentes tienen una regla más estricta que los adultos.","h2":"Un conductor menor de 18 en Minnesota con permiso o licencia provisional no puede usar el teléfono mientras el carro se mueve, ni en la mano ni con manos libres.","p":"Correcto. Menor de 18, nada de teléfono en movimiento."},"ref":{"doc":"MN","page":14}},{"id":"mn-015","scope":"MN","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Minnesota, how may an adult driver use a cell phone to make a call while driving?","o":["By voice command or one touch, without holding it","Holding it at the ear","Holding it on the steering wheel","Holding it only at stop signs"],"h1":"Minnesota's law is called Hands-Free.","h2":"Minnesota adults may use a phone while driving only by voice command or hands-free mode, never holding it in their hand.","p":"Right. Voice or one touch, never holding the phone."},"es":{"q":"En Minnesota, ¿cómo puede un conductor adulto usar el celular para hacer una llamada mientras maneja?","o":["Con comando de voz o un solo toque, sin sostenerlo","Sosteniéndolo junto al oído","Sosteniéndolo sobre el volante","Sosteniéndolo solo en las señales de alto"],"h1":"La ley de Minnesota se llama Manos Libres.","h2":"En Minnesota, los adultos pueden usar el teléfono al manejar solo con comandos de voz o en modo manos libres, nunca sosteniéndolo en la mano.","p":"Correcto. Con voz o un toque, nunca sosteniendo el teléfono."},"ref":{"doc":"MN","page":null}},{"id":"mn-016","scope":"MN","cat":"licensing","sign":null,"c":3,"en":{"q":"In Minnesota, what score do you need to pass the knowledge test?","o":["60 percent","70 percent","75 percent","80 percent"],"h1":"You must answer four out of every five questions right.","h2":"Minnesota requires at least 80 percent correct to pass the driver knowledge test.","p":"Right. You need 80 percent to pass."},"es":{"q":"En Minnesota, ¿qué puntaje necesita para aprobar el examen de conocimientos?","o":["60 por ciento","70 por ciento","75 por ciento","80 por ciento"],"h1":"Debe contestar bien cuatro de cada cinco preguntas.","h2":"Minnesota exige por lo menos 80 por ciento de respuestas correctas para aprobar el examen de conocimientos.","p":"Correcto. Necesita 80 por ciento para aprobar."},"ref":{"doc":"MN","page":10}},{"id":"mn-017","scope":"MN","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Minnesota, on a road with two lanes your way, you approach a stopped ambulance with flashing lights on the shoulder. What does the law require?","o":["Stay in your lane and keep your speed","Move one full lane away, if safe","Stop on the shoulder behind it","Speed up to pass it quickly"],"h1":"Leave an empty lane between you and the workers.","h2":"Minnesota's Ted Foss Move Over law requires you to move one full lane away from a stopped emergency vehicle with flashing lights; if that is not safe, slow down.","p":"Right. Move one full lane away."},"es":{"q":"En Minnesota, en una vía con dos carriles en su dirección, se acerca a una ambulancia detenida en el acotamiento con luces intermitentes. ¿Qué exige la ley?","o":["Seguir en su carril a la misma velocidad","Alejarse un carril completo, si es seguro","Parar en el acotamiento detrás de ella","Acelerar para pasarla rápido"],"h1":"Deje un carril vacío entre usted y los trabajadores.","h2":"La ley Ted Foss de Minnesota le exige alejarse un carril completo de un vehículo de emergencia detenido con luces intermitentes; si no es seguro, baje la velocidad.","p":"Correcto. Aléjese un carril completo."},"ref":{"doc":"MN","page":44}},{"id":"mn-018","scope":"MN","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Minnesota, the move over law also protects which of these?","o":["A stalled car with its hazard lights on","A parked car in a driveway","A bus at a bus stop","A car waiting at a red light"],"h1":"Think of a driver stuck on the shoulder.","h2":"Minnesota's move over law also covers stalled or disabled vehicles with their warning lights on, so stranded drivers get the same protection.","p":"Right. Stalled cars with hazards on are covered too."},"es":{"q":"En Minnesota, ¿a cuál de estos también protege la ley de cambiarse de carril (Move Over)?","o":["Un carro descompuesto con las luces de emergencia encendidas","Un carro estacionado en una entrada de casa","Un autobús en una parada","Un carro esperando en un semáforo en rojo"],"h1":"Piense en un conductor varado en el acotamiento.","h2":"La ley de cambiarse de carril de Minnesota también protege a los vehículos averiados o detenidos con las luces de advertencia encendidas, para que los conductores varados tengan la misma protección.","p":"Correcto. Los carros descompuestos con luces de emergencia también están protegidos."},"ref":{"doc":"MN","page":44}},{"id":"mn-019","scope":"MN","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Minnesota, how far from a school bus with its stop arm out and red lights flashing must you stop?","o":["At least 5 feet","At least 10 feet","At least 20 feet","At least 50 feet"],"h1":"It is about the length of one car and a half.","h2":"In Minnesota you must stop at least 20 feet from a school bus with its stop arm out and red lights flashing, to give children room to cross.","p":"Right. Stop at least 20 feet away."},"es":{"q":"En Minnesota, ¿a qué distancia de un autobús escolar con el brazo de alto extendido y luces rojas intermitentes debe parar?","o":["Por lo menos 5 pies","Por lo menos 10 pies","Por lo menos 20 pies","Por lo menos 50 pies"],"h1":"Es como el largo de un carro y medio.","h2":"En Minnesota usted debe parar por lo menos a 20 pies de un autobús escolar con el brazo de alto extendido y luces rojas intermitentes, para dar espacio a los niños que cruzan.","p":"Correcto. Pare por lo menos a 20 pies."},"ref":{"doc":"MN","page":42}},{"id":"mn-020","scope":"MN","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Minnesota, when may oncoming traffic keep going past a school bus with its stop arm out?","o":["When the bus is on a two-lane road","When no children are visible","When the road has four lanes but no median","When a raised or depressed median separates the roads"],"h1":"The roads must be truly separated by something built.","h2":"In Minnesota, oncoming drivers need not stop only on a divided road, where a physical barrier or a raised or depressed median separates the two sides.","p":"Right. Only a real median or barrier lets oncoming traffic keep going."},"es":{"q":"En Minnesota, ¿cuándo puede seguir el tránsito que viene en sentido contrario ante un autobús escolar con el brazo de alto extendido?","o":["Cuando el autobús está en una vía de dos carriles","Cuando no se ven niños","Cuando la carretera tiene cuatro carriles pero no tiene división","Cuando un camellón elevado o hundido separa las vías"],"h1":"Las vías deben estar separadas de verdad por algo construido.","h2":"En Minnesota, los conductores que vienen en sentido contrario no tienen que detenerse solo en una carretera dividida, donde una barrera física o una división elevada o hundida separa los dos lados.","p":"Correcto. Solo un camellón o barrera real permite seguir."},"ref":{"doc":"MN","page":42}},{"id":"mn-021","scope":"MN","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Minnesota, under the Not a Drop law, how much alcohol may a driver under 21 have?","o":["Up to 0.02","None at all","Up to 0.05","Up to 0.08"],"h1":"The name of the law gives the answer.","h2":"Minnesota's Not a Drop law makes it illegal for a driver under 21 to drive after drinking any alcohol at all.","p":"Right. Under 21 means not a drop."},"es":{"q":"En Minnesota, según la ley Not a Drop (Ni una gota), ¿cuánto alcohol puede tener un conductor menor de 21?","o":["Hasta 0.02","Nada","Hasta 0.05","Hasta 0.08"],"h1":"El nombre de la ley da la respuesta.","h2":"La ley Not a Drop de Minnesota prohíbe que un conductor menor de 21 maneje después de tomar cualquier cantidad de alcohol.","p":"Correcto. Menor de 21 significa ni una gota."},"ref":{"doc":"MN","page":95}},{"id":"mn-022","scope":"MN","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Minnesota, unless a sign says otherwise, what is the speed limit in an urban district?","o":["30 mph","25 mph","35 mph","40 mph"],"h1":"It is a round number below 35.","h2":"Minnesota law sets 30 mph in an urban district when no other limit is posted, because homes, businesses and people are close to the road.","p":"Right. Urban districts are 30 mph."},"es":{"q":"En Minnesota, si no hay una señal que diga otra cosa, ¿cuál es el límite de velocidad en zona urbana?","o":["30 mph","25 mph","35 mph","40 mph"],"h1":"Es un número redondo menor que 35.","h2":"La ley de Minnesota fija 30 mph en zona urbana cuando no hay otro límite indicado, porque hay casas, negocios y personas cerca de la vía.","p":"Correcto. En zona urbana el límite es 30 mph."},"ref":{"doc":"MN","page":26}},{"id":"mn-023","scope":"MN","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Minnesota, what is the speed limit on an interstate outside a large urban area, unless posted otherwise?","o":["55 mph","65 mph","70 mph","75 mph"],"h1":"Inside big cities the interstate limit is 5 mph lower.","h2":"Minnesota sets 70 mph on interstates outside urbanized areas of more than 50,000 people, and 65 mph inside them.","p":"Right. Rural interstates are 70 mph."},"es":{"q":"En Minnesota, ¿cuál es el límite de velocidad en una interestatal fuera de una zona urbana grande, si no hay otro indicado?","o":["55 mph","65 mph","70 mph","75 mph"],"h1":"Dentro de las ciudades grandes el límite en la interestatal es 5 mph menos.","h2":"Minnesota fija 70 mph en las interestatales fuera de zonas urbanas de más de 50,000 personas, y 65 mph dentro de ellas.","p":"Correcto. Las interestatales rurales son de 70 mph."},"ref":{"doc":"MN","page":null}},{"id":"mn-024","scope":"MN","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Minnesota, when must you turn on your headlights during the day?","o":["Only on the freeway","Whenever it is raining or snowing","Only in a tunnel","Only after 6 p.m."],"h1":"Think about weather that makes cars hard to see.","h2":"Minnesota law requires headlights whenever it is raining, snowing, sleeting or hailing, even in daytime, so other drivers can see you.","p":"Right. Rain or snow means headlights on."},"es":{"q":"En Minnesota, ¿cuándo debe encender los faros durante el día?","o":["Solo en la autopista","Siempre que llueva o nieve","Solo en un túnel","Solo después de las 6 p.m."],"h1":"Piense en el clima que hace difícil ver los carros.","h2":"La ley de Minnesota exige los faros encendidos siempre que llueva, nieve, caiga aguanieve o granizo, aunque sea de día, para que otros conductores lo vean.","p":"Correcto. Con lluvia o nieve, faros encendidos."},"ref":{"doc":"MN","page":23}},{"id":"mn-025","scope":"MN","cat":"licensing","sign":null,"c":3,"en":{"q":"In Minnesota, what type of coverage must every car owner carry because the state has a no-fault system?","o":["Collision coverage","Rental car coverage","Roadside assistance","Personal injury protection (PIP)"],"h1":"It pays your own medical bills no matter who caused the crash.","h2":"Minnesota is a no-fault state, so every owner must carry no-fault insurance, called personal injury protection, which pays your own medical costs and lost wages whoever was at fault.","p":"Right. Minnesota requires personal injury protection."},"es":{"q":"En Minnesota, ¿qué tipo de cobertura debe tener todo dueño de carro porque el estado tiene un sistema sin culpa (no-fault)?","o":["Cobertura de choque","Cobertura de auto de alquiler","Asistencia en el camino","Protección por lesiones personales (PIP)"],"h1":"Paga sus propios gastos médicos sin importar quién causó el choque.","h2":"Minnesota es un estado sin culpa, así que todo dueño debe tener el seguro sin culpa, llamado protección contra lesiones personales, que paga sus propios gastos médicos y salarios perdidos sin importar quién tuvo la culpa.","p":"Correcto. Minnesota exige protección por lesiones personales."},"ref":{"doc":"MN","page":40}},{"id":"mn-026","scope":"MN","cat":"licensing","sign":null,"c":0,"en":{"q":"In Minnesota, what is the minimum liability insurance for damage to other people's property in one crash?","o":["$10,000","$15,000","$25,000","$30,000"],"h1":"It is the last number in 30/60/10.","h2":"Minnesota requires at least $10,000 of property damage liability for one crash, the last number in the 30/60/10 minimum.","p":"Right. The property damage minimum is $10,000."},"es":{"q":"En Minnesota, ¿cuál es el seguro mínimo de responsabilidad por daños a la propiedad de otros en un choque?","o":["$10,000","$15,000","$25,000","$30,000"],"h1":"Es el último número de 30/60/10.","h2":"Minnesota exige por lo menos $10,000 de cobertura por daños a la propiedad en un choque, el último número del mínimo 30/60/10.","p":"Correcto. El mínimo por daños a la propiedad es $10,000."},"ref":{"doc":"MN","page":null}},{"id":"mo-001","scope":"MO","cat":"licensing","sign":null,"c":1,"en":{"q":"In Missouri, what is the youngest age to get an instruction permit?","o":["14 years old","15 years old","16 years old","15 and a half years old"],"h1":"It is one year before the intermediate license.","h2":"You can get a Missouri instruction permit at 15, one year before you can apply for an intermediate license at 16.","p":"Right. The Missouri permit starts at 15."},"es":{"q":"En Missouri, ¿cuál es la edad mínima para obtener un permiso de instrucción?","o":["14 años","15 años","16 años","15 años y medio"],"h1":"Es un año antes de la licencia intermedia.","h2":"Usted puede obtener el permiso de instrucción en Missouri a los 15 años, un año antes de poder solicitar la licencia intermedia a los 16.","p":"Correcto. El permiso en Missouri empieza a los 15."},"ref":{"doc":"MO","page":3}},{"id":"mo-002","scope":"MO","cat":"licensing","sign":null,"c":2,"en":{"q":"In Missouri, how long must a teen hold an instruction permit before getting an intermediate license?","o":["30 days","90 days","At least 182 days, about six months","One full year"],"h1":"It is about half a year.","h2":"A Missouri teen must hold the instruction permit for at least 182 days, about six months, before applying for an intermediate license.","p":"Right. The permit must be held about six months."},"es":{"q":"En Missouri, ¿cuánto tiempo debe tener un adolescente el permiso de instrucción antes de obtener la licencia intermedia?","o":["30 días","90 días","Por lo menos 182 días, unos seis meses","Un año completo"],"h1":"Es más o menos medio año.","h2":"Un adolescente en Missouri debe tener el permiso de instrucción por lo menos 182 días, unos seis meses, antes de solicitar la licencia intermedia.","p":"Correcto. El permiso se debe tener unos seis meses."},"ref":{"doc":"MO","page":16}},{"id":"mo-003","scope":"MO","cat":"licensing","sign":null,"c":0,"en":{"q":"In Missouri, how many hours of driving instruction must a teen complete before an intermediate license?","o":["40 hours","20 hours","50 hours","60 hours"],"h1":"It is less than fifty.","h2":"A Missouri teen must complete 40 hours of driving instruction with a qualified person before getting an intermediate license.","p":"Right. Missouri asks for 40 hours of driving instruction."},"es":{"q":"En Missouri, ¿cuántas horas de instrucción de manejo debe completar un adolescente antes de la licencia intermedia?","o":["40 horas","20 horas","50 horas","60 horas"],"h1":"Es menos de cincuenta.","h2":"Un adolescente en Missouri debe completar 40 horas de instrucción de manejo con una persona calificada antes de obtener la licencia intermedia.","p":"Correcto. Missouri pide 40 horas de instrucción de manejo."},"ref":{"doc":"MO","page":16}},{"id":"mo-004","scope":"MO","cat":"licensing","sign":null,"c":3,"en":{"q":"In Missouri, how many of the 40 required practice hours must be at night?","o":["At least 2 hours","At least 5 hours","At least 20 hours","At least 10 hours"],"h1":"It is one quarter of the total.","h2":"At least 10 of Missouri's 40 required hours of driving instruction must be driven at night.","p":"Right. At least 10 of the hours must be at night."},"es":{"q":"En Missouri, ¿cuántas de las 40 horas de práctica exigidas deben ser de noche?","o":["Por lo menos 2 horas","Por lo menos 5 horas","Por lo menos 20 horas","Por lo menos 10 horas"],"h1":"Es la cuarta parte del total.","h2":"Por lo menos 10 de las 40 horas de instrucción exigidas en Missouri deben ser de noche.","p":"Correcto. Por lo menos 10 de las horas deben ser de noche."},"ref":{"doc":"MO","page":16}},{"id":"mo-005","scope":"MO","cat":"licensing","sign":null,"c":1,"en":{"q":"In Missouri, during which hours may a driver with an intermediate license not drive alone?","o":["Midnight to 6 a.m.","1 a.m. to 5 a.m.","11 p.m. to 5 a.m.","10 p.m. to 6 a.m."],"h1":"The limit starts one hour after midnight.","h2":"A Missouri intermediate license holder may not drive alone from 1 a.m. to 5 a.m., the late night curfew for new drivers.","p":"Right. The curfew is 1 a.m. to 5 a.m."},"es":{"q":"En Missouri, ¿en qué horario no puede manejar solo un conductor con licencia intermedia?","o":["De medianoche a 6 a.m.","De 1 a.m. a 5 a.m.","De 11 p.m. a 5 a.m.","De 10 p.m. a 6 a.m."],"h1":"El límite empieza una hora después de la medianoche.","h2":"Quien tiene licencia intermedia en Missouri no puede manejar solo de 1 a.m. a 5 a.m., el toque de queda nocturno para conductores nuevos.","p":"Correcto. El toque de queda es de 1 a.m. a 5 a.m."},"ref":{"doc":"MO","page":16}},{"id":"mo-006","scope":"MO","cat":"licensing","sign":null,"c":2,"en":{"q":"In Missouri, during the first six months of an intermediate license, how many passengers under 19 who are not family may ride with the driver?","o":["None","Three","One","Two"],"h1":"The limit is as small as it can be without being zero.","h2":"In the first six months, a Missouri intermediate driver may carry no more than one passenger under 19 who is not immediate family.","p":"Right. Only one non-family passenger under 19 at first."},"es":{"q":"En Missouri, durante los primeros seis meses de la licencia intermedia, ¿cuántos pasajeros menores de 19 años que no son familia pueden ir con el conductor?","o":["Ninguno","Tres","Uno","Dos"],"h1":"El límite es lo más pequeño posible sin ser cero.","h2":"En los primeros seis meses, un conductor con licencia intermedia en Missouri puede llevar como máximo un pasajero menor de 19 años que no sea familiar directo.","p":"Correcto. Al principio, solo un pasajero menor de 19 que no sea familia."},"ref":{"doc":"MO","page":16}},{"id":"mo-007","scope":"MO","cat":"licensing","sign":null,"c":3,"en":{"q":"In Missouri, after the first six months of an intermediate license, how many passengers under 19 who are not family may ride with the driver?","o":["One","Two","Five","Three"],"h1":"The limit grows after six months, but it does not disappear.","h2":"After the first six months, a Missouri intermediate driver may carry no more than three passengers under 19 who are not immediate family.","p":"Right. After six months the limit is three."},"es":{"q":"En Missouri, después de los primeros seis meses de la licencia intermedia, ¿cuántos pasajeros menores de 19 años que no son familia pueden ir con el conductor?","o":["Uno","Dos","Cinco","Tres"],"h1":"El límite aumenta después de seis meses, pero no desaparece.","h2":"Después de los primeros seis meses, un conductor con licencia intermedia en Missouri puede llevar como máximo tres pasajeros menores de 19 años que no sean familiares directos.","p":"Correcto. Después de seis meses el límite es tres."},"ref":{"doc":"MO","page":16}},{"id":"mo-008","scope":"MO","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Missouri, who must wear a seat belt when a driver has an intermediate license?","o":["The driver and every passenger","Only the driver","Only front seat riders","Only passengers under 16"],"h1":"The rule covers everyone in the car.","h2":"With a Missouri intermediate license, the driver and all passengers must wear seat belts.","p":"Right. Everyone in the car must buckle up."},"es":{"q":"En Missouri, ¿quién debe usar el cinturón de seguridad cuando el conductor tiene licencia intermedia?","o":["El conductor y todos los pasajeros","Solo el conductor","Solo los del asiento delantero","Solo los pasajeros menores de 16"],"h1":"La regla cubre a todos en el auto.","h2":"Con una licencia intermedia de Missouri, el conductor y todos los pasajeros deben usar el cinturón de seguridad.","p":"Correcto. Todos en el auto deben abrocharse el cinturón."},"ref":{"doc":"MO","page":16}},{"id":"mo-009","scope":"MO","cat":"licensing","sign":null,"c":2,"en":{"q":"In Missouri, how many questions are on the written test for a regular driver license?","o":["20 questions","30 questions","25 questions","40 questions"],"h1":"It is a quarter of one hundred.","h2":"The Missouri written test for a regular license has 25 multiple-choice questions.","p":"Right. The test has 25 questions."},"es":{"q":"En Missouri, ¿cuántas preguntas tiene el examen escrito para la licencia de conducir normal?","o":["20 preguntas","30 preguntas","25 preguntas","40 preguntas"],"h1":"Es la cuarta parte de cien.","h2":"El examen escrito de Missouri para la licencia normal tiene 25 preguntas de opción múltiple.","p":"Correcto. El examen tiene 25 preguntas."},"ref":{"doc":"MO","page":18}},{"id":"mo-010","scope":"MO","cat":"licensing","sign":null,"c":1,"en":{"q":"In Missouri, how many of the 25 written test questions must you answer correctly to pass?","o":["15","20","18","22"],"h1":"You may miss five.","h2":"You must answer 20 of the 25 questions correctly on the Missouri written test, which is 80 percent.","p":"Right. You need 20 correct answers out of 25."},"es":{"q":"En Missouri, ¿cuántas de las 25 preguntas del examen escrito debe contestar bien para aprobar?","o":["15","20","18","22"],"h1":"Puede fallar cinco.","h2":"Usted debe contestar bien 20 de las 25 preguntas del examen escrito de Missouri, es decir, el 80 por ciento.","p":"Correcto. Necesita 20 respuestas correctas de 25."},"ref":{"doc":"MO","page":1}},{"id":"mo-011","scope":"MO","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Missouri, since the hands-free law, which drivers may not hold a phone while driving?","o":["Only drivers under 21","Only commercial drivers","Only drivers in school zones","All drivers"],"h1":"The newer law does not depend on age.","h2":"Missouri's hands-free law applies to all drivers: you may not hold, type on or scroll a phone while driving, and tickets began on January 1, 2025.","p":"Right. No driver may hold a phone while driving."},"es":{"q":"En Missouri, desde la ley de manos libres, ¿qué conductores no pueden sostener el teléfono mientras manejan?","o":["Solo los menores de 21","Solo los conductores comerciales","Solo en zonas escolares","Todos los conductores"],"h1":"La ley más nueva no depende de la edad.","h2":"La ley de manos libres de Missouri se aplica a todos los conductores: no puede sostener, escribir ni desplazarse en el teléfono mientras maneja, y las multas empezaron el 1 de enero de 2025.","p":"Correcto. Ningún conductor puede sostener el teléfono mientras maneja."},"ref":{"doc":"MO","page":93}},{"id":"mo-012","scope":"MO","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Missouri, which way of using a phone is allowed for an adult driver?","o":["Talking with Bluetooth or speaker, hands-free","Holding the phone to your ear","Typing a text at a stop sign","Scrolling a map in your hand"],"h1":"Your hands must stay off the phone.","h2":"Missouri lets drivers use hands-free features such as Bluetooth, speaker or voice-to-text, but not holding or typing on the phone.","p":"Right. Hands-free use is allowed."},"es":{"q":"En Missouri, ¿qué forma de usar el teléfono está permitida para un conductor adulto?","o":["Hablar con Bluetooth o altavoz, sin manos","Sostener el teléfono en la oreja","Escribir un mensaje en un alto","Mover un mapa con la mano"],"h1":"Sus manos no deben tocar el teléfono.","h2":"Missouri permite usar funciones de manos libres como Bluetooth, altavoz o dictado por voz, pero no sostener ni escribir en el teléfono.","p":"Correcto. El uso con manos libres está permitido."},"ref":{"doc":"MO","page":93}},{"id":"mo-013","scope":"MO","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Missouri, at what blood alcohol level can a driver under 21 be charged?","o":["0.08 percent","0.02 percent","0.05 percent","0.10 percent"],"h1":"It is much lower than the adult limit.","h2":"In Missouri, a driver under 21 can be charged with a blood alcohol level of 0.02 percent, far below the adult limit of 0.08.","p":"Right. Under 21, the limit is 0.02 percent."},"es":{"q":"En Missouri, ¿con qué nivel de alcohol en la sangre se puede acusar a un conductor menor de 21 años?","o":["0.08 por ciento","0.02 por ciento","0.05 por ciento","0.10 por ciento"],"h1":"Es mucho menor que el límite para adultos.","h2":"En Missouri, a un conductor menor de 21 años se le puede acusar con 0.02 por ciento de alcohol en la sangre, muy por debajo del límite de 0.08 para adultos.","p":"Correcto. Para menores de 21, el límite es 0.02 por ciento."},"ref":{"doc":"MO","page":67}},{"id":"mo-014","scope":"MO","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Missouri, you approach a stopped emergency vehicle with flashing lights on a highway with two lanes your way. What must you do?","o":["Stop in your lane","Speed up to pass quickly","Change lanes away from it if safe, or slow down","Honk and keep your speed"],"h1":"Give the workers more space.","h2":"Missouri's move over law says to change to a lane away from the stopped vehicle if it is safe, or slow down if you cannot.","p":"Right. Move over, or slow down if you cannot."},"es":{"q":"En Missouri, usted se acerca a un vehículo de emergencia detenido con luces intermitentes en una carretera con dos carriles en su dirección. ¿Qué debe hacer?","o":["Detenerse en su carril","Acelerar para pasar rápido","Cambiarse de carril, alejándose, si es seguro, o reducir la velocidad","Tocar la bocina y mantener la velocidad"],"h1":"Dé más espacio a los trabajadores.","h2":"La ley de Missouri dice que debe cambiarse a un carril lejos del vehículo detenido si es seguro, o reducir la velocidad si no puede.","p":"Correcto. Cámbiese de carril, o reduzca la velocidad si no puede."},"ref":{"doc":"MO","page":23}},{"id":"mo-015","scope":"MO","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Missouri, which stopped vehicles are covered by the move over law besides police, fire and ambulances?","o":["Only school buses","Only mail trucks","Any car parked on the shoulder","MoDOT vehicles with amber lights"],"h1":"Think of highway work trucks with yellow lights.","h2":"Missouri's move over law also covers stopped vehicles showing amber or amber and white lights, such as MoDOT trucks, so road workers get room too.","p":"Right. MoDOT vehicles with amber lights are covered."},"es":{"q":"En Missouri, ¿qué vehículos detenidos cubre la ley de cambiarse de carril, además de policía, bomberos y ambulancias?","o":["Solo los autobuses escolares","Solo los camiones del correo","Cualquier auto en el acotamiento","Los vehículos de MoDOT con luces ámbar"],"h1":"Piense en camiones de trabajo en la carretera con luces amarillas.","h2":"La ley de Missouri también cubre los vehículos detenidos con luces ámbar o ámbar y blancas, como los camiones de MoDOT, para que los trabajadores también tengan espacio.","p":"Correcto. Los vehículos de MoDOT con luces ámbar están cubiertos."},"ref":{"doc":"MO","page":null}},{"id":"mo-016","scope":"MO","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Missouri, when must your headlights be on during the day?","o":["Whenever the weather requires your windshield wipers","Only after sunset","Only on interstates","Only in work zones"],"h1":"Think of rain on your windshield.","h2":"Missouri requires lighted headlights any time the weather makes you use your windshield wipers, and also in fog.","p":"Right. Wipers on means headlights on."},"es":{"q":"En Missouri, ¿cuándo deben estar encendidas las luces delanteras durante el día?","o":["Siempre que el clima exija usar los limpiaparabrisas","Solo después de la puesta del sol","Solo en autopistas interestatales","Solo en zonas de trabajo"],"h1":"Piense en la lluvia sobre su parabrisas.","h2":"Missouri exige las luces delanteras encendidas cada vez que el clima le obliga a usar los limpiaparabrisas, y también con niebla.","p":"Correcto. Limpiaparabrisas encendidos significa luces encendidas."},"ref":{"doc":"MO","page":62}},{"id":"mo-017","scope":"MO","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Missouri, there is fog but you do not need your wipers. Must your headlights be on?","o":["No, only when wipers are on","Only if you drive over 45 mph","Yes, fog also requires headlights","Only after sunset"],"h1":"The law names fog on its own.","h2":"Missouri law requires headlights during fog even when you do not need your windshield wipers.","p":"Right. Fog means headlights on."},"es":{"q":"En Missouri, hay niebla pero no necesita los limpiaparabrisas. ¿Deben estar encendidas las luces delanteras?","o":["No, solo cuando usa los limpiaparabrisas","Solo si maneja a más de 45 mph","Sí, la niebla también exige luces","Solo después de la puesta del sol"],"h1":"La ley menciona la niebla por separado.","h2":"La ley de Missouri exige las luces delanteras con niebla aunque no necesite los limpiaparabrisas.","p":"Correcto. Con niebla, luces encendidas."},"ref":{"doc":"MO","page":null}},{"id":"mo-018","scope":"MO","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Missouri, a school bus with flashing red lights is stopped on the other side of a divided highway with a median. What must you do?","o":["Stop until the lights turn off","You do not have to stop","Stop, then pass at 10 mph","Stop only if you see children"],"h1":"The median separates you from the bus.","h2":"In Missouri, drivers on the opposite side of a divided highway, or of a highway with four or more lanes, do not have to stop for a school bus, but traffic behind the bus must stop.","p":"Right. The other side of a divided highway does not have to stop."},"es":{"q":"En Missouri, un autobús escolar con luces rojas intermitentes está detenido al otro lado de una carretera dividida con camellón. ¿Qué debe hacer usted?","o":["Detenerse hasta que se apaguen las luces","No tiene que detenerse","Detenerse y luego pasar a 10 mph","Detenerse solo si ve niños"],"h1":"El camellón lo separa del autobús.","h2":"En Missouri, los conductores del otro lado de una carretera dividida, o de una carretera de cuatro carriles o más, no tienen que detenerse por un autobús escolar, pero el tráfico detrás del autobús sí debe detenerse.","p":"Correcto. El otro lado de una carretera dividida no tiene que detenerse."},"ref":{"doc":"MO","page":24}},{"id":"mo-019","scope":"MO","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Missouri, you are behind a school bus on a divided highway when it stops with red lights flashing. What must you do?","o":["Pass on the left with care","Pass if no children are near","Slow to 20 mph and pass","Stop and wait"],"h1":"You are on the same side as the bus.","h2":"When you travel in the same direction as a stopped school bus in Missouri, you must stop, even on a divided highway.","p":"Right. Traffic on the same side must stop."},"es":{"q":"En Missouri, usted va detrás de un autobús escolar en una carretera dividida cuando se detiene con luces rojas intermitentes. ¿Qué debe hacer?","o":["Rebasar por la izquierda con cuidado","Rebasar si no hay niños cerca","Bajar a 20 mph y rebasar","Detenerse y esperar"],"h1":"Usted está del mismo lado que el autobús.","h2":"Cuando usted va en la misma dirección que un autobús escolar detenido en Missouri, debe detenerse, aunque sea una carretera dividida.","p":"Correcto. El tráfico del mismo lado debe detenerse."},"ref":{"doc":"MO","page":23}},{"id":"mo-020","scope":"MO","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Missouri, a 2026 law allows up to 75 mph on some rural interstates. What speed must you obey where the sign still says 70 mph?","o":["70 mph, the posted limit","75 mph, the new law","80 mph when traffic is light","65 mph, the expressway limit"],"h1":"The sign on the road tells you the limit.","h2":"You must obey the posted sign: where it says 70 mph, the limit is 70 mph, even though Missouri allows up to 75 mph on some rural interstates.","p":"Right. Always obey the posted limit."},"es":{"q":"En Missouri, una ley de 2026 permite hasta 75 mph en algunas autopistas rurales. ¿Qué velocidad debe respetar donde el letrero todavía dice 70 mph?","o":["70 mph, el límite indicado","75 mph, la nueva ley","80 mph si hay poco tráfico","65 mph, el límite de vía rápida"],"h1":"El letrero en la carretera le dice el límite.","h2":"Usted debe respetar el letrero: donde dice 70 mph, el límite es 70 mph, aunque Missouri permite hasta 75 mph en algunas autopistas rurales.","p":"Correcto. Siempre respete el límite indicado."},"ref":{"doc":"MO","page":50}},{"id":"mo-021","scope":"MO","cat":"licensing","sign":null,"c":2,"en":{"q":"In Missouri, how many points within 18 months lead to a license suspension?","o":["4 points","6 points","8 points","12 points"],"h1":"It is double the number that brings a warning letter.","h2":"In Missouri, 8 points within 18 months lead to a suspension, starting at 30 days for a first time.","p":"Right. Eight points in 18 months means suspension."},"es":{"q":"En Missouri, ¿cuántos puntos en 18 meses llevan a la suspensión de la licencia?","o":["4 puntos","6 puntos","8 puntos","12 puntos"],"h1":"Es el doble del número que trae una carta de aviso.","h2":"En Missouri, 8 puntos en 18 meses llevan a una suspensión, que empieza con 30 días la primera vez.","p":"Correcto. Ocho puntos en 18 meses significan suspensión."},"ref":{"doc":"MO","page":73}},{"id":"mo-022","scope":"MO","cat":"licensing","sign":null,"c":1,"en":{"q":"In Missouri, what happens when a driver gets 4 points within 12 months?","o":["The license is revoked for a year","The Department of Revenue sends a warning letter","The driver must retake the road test","Nothing happens"],"h1":"It is a first step, not a penalty.","h2":"When a Missouri driver gets 4 points in 12 months, the Department of Revenue sends an advisory letter as a warning.","p":"Right. Four points in 12 months brings a warning letter."},"es":{"q":"En Missouri, ¿qué pasa cuando un conductor acumula 4 puntos en 12 meses?","o":["Le revocan la licencia por un año","El Departamento de Ingresos le envía una carta de aviso","Debe repetir el examen de manejo","No pasa nada"],"h1":"Es un primer paso, no un castigo.","h2":"Cuando un conductor en Missouri acumula 4 puntos en 12 meses, el Departamento de Ingresos le envía una carta de aviso.","p":"Correcto. Cuatro puntos en 12 meses traen una carta de aviso."},"ref":{"doc":"MO","page":73}},{"id":"mo-023","scope":"MO","cat":"licensing","sign":null,"c":3,"en":{"q":"In Missouri, what is the minimum liability insurance for property damage?","o":["$5,000","$10,000","$50,000","$25,000"],"h1":"It matches the amount required for injury to one person.","h2":"Since January 1, 2024, Missouri requires at least $25,000 of property damage coverage, with $25,000 per injured person and $50,000 per crash.","p":"Right. Property damage coverage must be at least $25,000."},"es":{"q":"En Missouri, ¿cuál es el seguro de responsabilidad mínimo por daños a la propiedad?","o":["$5,000","$10,000","$50,000","$25,000"],"h1":"Es igual a la cantidad exigida por lesiones a una persona.","h2":"Desde el 1 de enero de 2024, Missouri exige por lo menos $25,000 de cobertura por daños a la propiedad, con $25,000 por persona lesionada y $50,000 por choque.","p":"Correcto. La cobertura por daños a la propiedad debe ser de por lo menos $25,000."},"ref":{"doc":"MO","page":79}},{"id":"mo-024","scope":"MO","cat":"licensing","sign":null,"c":0,"en":{"q":"In Missouri, besides liability, which insurance coverage must every car policy include?","o":["Uninsured motorist coverage","Collision coverage","Rental car coverage","Roadside assistance"],"h1":"It protects you when the other driver has no insurance.","h2":"Missouri requires uninsured motorist coverage for injuries, so you are protected if a driver without insurance hurts you.","p":"Right. Uninsured motorist coverage is required."},"es":{"q":"En Missouri, además de la responsabilidad civil, ¿qué cobertura debe incluir toda póliza de auto?","o":["Cobertura contra conductores sin seguro","Cobertura de choque","Cobertura de auto de alquiler","Asistencia en el camino"],"h1":"Le protege cuando el otro conductor no tiene seguro.","h2":"Missouri exige la cobertura contra conductores sin seguro para lesiones, para protegerle si un conductor sin seguro le lastima.","p":"Correcto. La cobertura contra conductores sin seguro es obligatoria."},"ref":{"doc":"MO","page":79}},{"id":"mo-025","scope":"MO","cat":"licensing","sign":null,"c":1,"en":{"q":"In Missouri, until a permit holder turns 16, which person may ride along as the supervising driver?","o":["Any friend age 18 or older","A grandparent with a valid license","Any licensed sibling","A neighbor age 19 or older"],"h1":"Think of a close family member from an older generation.","h2":"Before age 16, a Missouri permit holder must drive with a parent, grandparent, guardian or certified instructor, or another qualified adult the rules allow.","p":"Right. A grandparent may supervise a permit holder under 16."},"es":{"q":"En Missouri, hasta que el titular del permiso cumple 16 años, ¿qué persona puede acompañarle como conductor supervisor?","o":["Cualquier amigo de 18 años o más","Un abuelo o abuela con licencia válida","Cualquier hermano con licencia","Un vecino de 19 años o más"],"h1":"Piense en un familiar cercano de una generación mayor.","h2":"Antes de los 16 años, el titular de un permiso en Missouri debe manejar con su padre, madre, abuelo, tutor o un instructor certificado, u otro adulto calificado que permitan las reglas.","p":"Correcto. Un abuelo puede supervisar a un titular de permiso menor de 16."},"ref":{"doc":"MO","page":15}},{"id":"ms-001","scope":"MS","cat":"licensing","sign":null,"c":1,"en":{"q":"In Mississippi, what is the youngest age to get a regular learner's permit?","o":["14 years old","15 years old","16 years old","17 years old"],"h1":"It is one year before you can get an intermediate license.","h2":"In Mississippi, you can get a regular learner's permit at 15, one year before you can get an intermediate license at 16.","p":"Right. The regular learner's permit starts at age 15."},"es":{"q":"En Mississippi, ¿cuál es la edad mínima para obtener un permiso de aprendiz regular?","o":["14 años","15 años","16 años","17 años"],"h1":"Es un año antes de poder obtener la licencia intermedia.","h2":"En Mississippi, usted puede obtener un permiso de aprendiz regular a los 15 años, un año antes de poder obtener la licencia intermedia a los 16.","p":"Correcto. El permiso de aprendiz regular empieza a los 15 años."},"ref":{"doc":"MS","page":13}},{"id":"ms-004","scope":"MS","cat":"licensing","sign":null,"c":2,"en":{"q":"In Mississippi, who must sit beside a driver with a learner's permit?","o":["Any passenger who is 16 or older","A licensed driver who is at least 18","A licensed driver who is at least 21","A licensed driver who is at least 25"],"h1":"The helper must be an adult old enough to buy alcohol legally.","h2":"In Mississippi, a learner's permit holder must drive with a licensed adult who is at least 21 years old sitting in the front seat.","p":"Right. A licensed driver 21 or older sits in the front seat."},"es":{"q":"En Mississippi, ¿quién debe sentarse al lado de un conductor con permiso de aprendiz?","o":["Cualquier pasajero de 16 años o más","Un conductor con licencia de por lo menos 18 años","Un conductor con licencia de por lo menos 21 años","Un conductor con licencia de por lo menos 25 años"],"h1":"El acompañante debe ser un adulto con edad suficiente para comprar alcohol legalmente.","h2":"En Mississippi, quien tiene permiso de aprendiz debe manejar con un adulto con licencia de por lo menos 21 años sentado en el asiento delantero.","p":"Correcto. Un conductor con licencia de 21 años o más va en el asiento delantero."},"ref":{"doc":"MS","page":13}},{"id":"ms-008","scope":"MS","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Mississippi, which drivers are banned from texting while driving?","o":["Only drivers with a learner's permit","Only drivers under 18","Drivers of every age","Only drivers of school buses"],"h1":"This rule does not depend on age or license type.","h2":"Mississippi bans all drivers from writing, sending or reading text messages while driving.","p":"Right. No driver of any age may text while driving in Mississippi."},"es":{"q":"En Mississippi, ¿a qué conductores se les prohíbe enviar mensajes de texto mientras manejan?","o":["Solo a quienes tienen permiso de aprendiz","Solo a los menores de 18 años","A los conductores de todas las edades","Solo a los choferes de autobús escolar"],"h1":"Esta regla no depende de la edad ni del tipo de licencia.","h2":"Mississippi prohíbe a todos los conductores escribir, enviar o leer mensajes de texto mientras manejan.","p":"Correcto. Ningún conductor, de ninguna edad, puede enviar mensajes mientras maneja en Mississippi."},"ref":{"doc":"MS","page":23}},{"id":"ms-009","scope":"MS","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Mississippi, which of these does the texting law still allow while driving?","o":["Reading a social media post","Using a hands-free or voice-operated device","Sending a short email","Typing a text at a slow speed"],"h1":"Think about using your voice instead of your hands.","h2":"Mississippi's texting law does not apply to hands-free or voice-operated devices, so a driver may still use them while driving.","p":"Right. Hands-free and voice-operated devices are still allowed."},"es":{"q":"En Mississippi, ¿cuál de estas cosas todavía permite la ley de mensajes de texto mientras se maneja?","o":["Leer una publicación en redes sociales","Usar un dispositivo de manos libres o de voz","Enviar un correo corto","Escribir un mensaje despacio"],"h1":"Piense en usar la voz en lugar de las manos.","h2":"La ley de mensajes de texto de Mississippi no se aplica a los dispositivos de manos libres o de voz, así que el conductor todavía puede usarlos mientras maneja.","p":"Correcto. Los dispositivos de manos libres y de voz todavía están permitidos."},"ref":{"doc":"MS","page":23}},{"id":"ms-010","scope":"MS","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Mississippi, what blood alcohol level is illegal for a driver under 21?","o":["0.02 percent or higher","0.05 percent or higher","0.08 percent or higher","0.10 percent or higher"],"h1":"It is much lower than the limit for adults.","h2":"Under Mississippi's zero tolerance law, a driver under 21 with a blood alcohol level of 0.02 percent or higher breaks the law.","p":"Right. For drivers under 21, the limit is 0.02 percent."},"es":{"q":"En Mississippi, ¿qué nivel de alcohol en la sangre es ilegal para un conductor menor de 21 años?","o":["0.02 por ciento o más","0.05 por ciento o más","0.08 por ciento o más","0.10 por ciento o más"],"h1":"Es mucho más bajo que el límite para adultos.","h2":"Según la ley de tolerancia cero de Mississippi, un conductor menor de 21 años con un nivel de alcohol en la sangre de 0.02 por ciento o más viola la ley.","p":"Correcto. Para los menores de 21, el límite es 0.02 por ciento."},"ref":{"doc":"MS","page":78}},{"id":"ms-011","scope":"MS","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Mississippi, a driver under 21 has a blood alcohol level of 0.08 percent. How is the driver treated?","o":["Only a warning is given","As a minor under the 0.02 rule only","Under the same DUI penalties as adults","Only the parents are fined"],"h1":"At this level, age no longer gives a lighter charge.","h2":"In Mississippi, a driver under 21 with a blood alcohol level of 0.08 percent or higher faces the adult DUI penalties.","p":"Right. At 0.08 percent, a driver under 21 is treated like an adult."},"es":{"q":"En Mississippi, un conductor menor de 21 años tiene un nivel de alcohol en la sangre de 0.08 por ciento. ¿Cómo se le trata?","o":["Solo recibe una advertencia","Solo como menor bajo la regla de 0.02","Con las mismas penas por DUI que los adultos","Solo se multa a los padres"],"h1":"A este nivel, la edad ya no da un cargo más leve.","h2":"En Mississippi, un conductor menor de 21 años con un nivel de alcohol en la sangre de 0.08 por ciento o más recibe las penas de DUI para adultos.","p":"Correcto. Con 0.08 por ciento, el menor de 21 recibe el mismo trato que un adulto."},"ref":{"doc":"MS","page":79}},{"id":"ms-012","scope":"MS","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Mississippi, what is the highest speed limit on interstate highways?","o":["60 mph","65 mph","75 mph","70 mph"],"h1":"It is 5 mph above the limit on four-lane state and U.S. highways.","h2":"The highest speed limit on Mississippi interstates is 70 mph, day and night.","p":"Right. Mississippi interstates top out at 70 mph."},"es":{"q":"En Mississippi, ¿cuál es el límite de velocidad más alto en las autopistas interestatales?","o":["60 mph","65 mph","75 mph","70 mph"],"h1":"Es 5 mph más que el límite de las carreteras estatales y federales de cuatro carriles.","h2":"El límite de velocidad más alto en las interestatales de Mississippi es 70 mph, de día y de noche.","p":"Correcto. En las interestatales de Mississippi, el máximo es 70 mph."},"ref":{"doc":"MS","page":41}},{"id":"ms-013","scope":"MS","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Mississippi, what is the usual maximum speed on a four-lane state or U.S. highway, unless signs show a different limit?","o":["55 mph","65 mph","70 mph","75 mph"],"h1":"It is 10 mph more than on a two-lane highway.","h2":"In Mississippi, the usual maximum speed on a four-lane state or U.S. highway is 65 mph.","p":"Right. Four-lane state and U.S. highways usually have a 65 mph limit."},"es":{"q":"En Mississippi, ¿cuál es la velocidad máxima habitual en una carretera estatal o federal de cuatro carriles, si las señales no indican otra?","o":["55 mph","65 mph","70 mph","75 mph"],"h1":"Es 10 mph más que en una carretera de dos carriles.","h2":"En Mississippi, la velocidad máxima habitual en una carretera estatal o federal de cuatro carriles es 65 mph.","p":"Correcto. Las carreteras estatales y federales de cuatro carriles suelen tener un límite de 65 mph."},"ref":{"doc":"MS","page":41}},{"id":"ms-015","scope":"MS","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Mississippi, you cannot safely change lanes away from a stopped emergency vehicle with flashing lights. What must you do?","o":["Keep your speed and stay in your lane","Stop completely in your lane","Drive onto the shoulder on the other side","Slow down and be ready to stop"],"h1":"If you cannot add distance, reduce your speed.","h2":"Under Mississippi's move-over law, if you cannot change lanes safely, you must slow to a safe speed and be prepared to stop.","p":"Right. When you cannot move over, slow down and be ready to stop."},"es":{"q":"En Mississippi, usted no puede cambiarse de carril con seguridad para alejarse de un vehículo de emergencia detenido con luces intermitentes. ¿Qué debe hacer?","o":["Mantener la velocidad y seguir en su carril","Detenerse por completo en su carril","Pasar por el acotamiento del otro lado","Reducir la velocidad y estar listo para detenerse"],"h1":"Si no puede alejarse, reduzca la velocidad.","h2":"Según la ley de Mississippi, si usted no puede cambiarse de carril con seguridad, debe reducir a una velocidad segura y estar listo para detenerse.","p":"Correcto. Si no puede moverse de carril, reduzca la velocidad y esté listo para detenerse."},"ref":{"doc":"MS","page":67}},{"id":"ms-017","scope":"MS","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Mississippi, how far from a stopped school bus must you stop when it is loading or unloading children?","o":["At least 5 feet","At least 10 feet","At least 30 feet","At least 50 feet"],"h1":"It is about the length of one small car.","h2":"Mississippi law requires you to stop at least 10 feet from a school bus that is stopped to pick up or drop off children.","p":"Right. You stop at least 10 feet from the bus."},"es":{"q":"En Mississippi, ¿a qué distancia de un autobús escolar detenido debe detenerse cuando suben o bajan niños?","o":["Por lo menos 5 pies","Por lo menos 10 pies","Por lo menos 30 pies","Por lo menos 50 pies"],"h1":"Es más o menos el largo de un carro pequeño.","h2":"La ley de Mississippi exige que usted se detenga por lo menos a 10 pies de un autobús escolar detenido para recoger o dejar niños.","p":"Correcto. Usted se detiene por lo menos a 10 pies del autobús."},"ref":{"doc":"MS","page":58}},{"id":"ms-018","scope":"MS","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Mississippi, you are on a divided highway with two lanes in each direction. A school bus on the other side stops with its red lights flashing. What must you do?","o":["You may keep going with care","Stop until the bus moves","Stop, then pass at 10 mph","Move to the left lane and stop"],"h1":"A physical divider separates you from the children's side.","h2":"In Mississippi, on a divided highway with at least two lanes in each direction, drivers on the other side do not have to stop for a stopped school bus, but should still drive with care.","p":"Right. On a divided highway, the opposite side may keep going with care."},"es":{"q":"En Mississippi, usted va por una carretera dividida con dos carriles en cada sentido. Un autobús escolar del otro lado se detiene con las luces rojas intermitentes. ¿Qué debe hacer?","o":["Puede seguir con cuidado","Detenerse hasta que el autobús avance","Detenerse y luego pasar a 10 mph","Pasarse al carril izquierdo y detenerse"],"h1":"Una división física lo separa del lado de los niños.","h2":"En Mississippi, en una carretera dividida con por lo menos dos carriles en cada sentido, los conductores del otro lado no tienen que detenerse ante un autobús escolar detenido, pero deben manejar con cuidado.","p":"Correcto. En una carretera dividida, el lado contrario puede seguir con cuidado."},"ref":{"doc":"MS","page":58}},{"id":"ms-019","scope":"MS","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Mississippi, a school bus stops on a divided highway with a median. You are driving behind it, in the same direction. What must you do?","o":["Pass it on the left with care","Pass it on the right shoulder","Slow to 15 mph and pass","Stop until it moves again"],"h1":"The median protects only the drivers on the other side.","h2":"In Mississippi, when a school bus stops on a divided highway, drivers going the same direction as the bus must stop.","p":"Right. Traffic behind the bus must always stop."},"es":{"q":"En Mississippi, un autobús escolar se detiene en una carretera dividida con una franja central. Usted va detrás, en el mismo sentido. ¿Qué debe hacer?","o":["Pasarlo por la izquierda con cuidado","Pasarlo por el acotamiento derecho","Reducir a 15 mph y pasar","Detenerse hasta que vuelva a avanzar"],"h1":"La franja central solo protege a los conductores del otro lado.","h2":"En Mississippi, cuando un autobús escolar se detiene en una carretera dividida, los conductores que van en el mismo sentido que el autobús deben detenerse.","p":"Correcto. El tráfico que va detrás del autobús siempre debe detenerse."},"ref":{"doc":"MS","page":58}},{"id":"ms-022","scope":"MS","cat":"licensing","sign":null,"c":0,"en":{"q":"In Mississippi, what is the minimum liability insurance a driver must carry?","o":["$25,000 / $50,000 / $25,000","$10,000 / $20,000 / $10,000","$15,000 / $30,000 / $5,000","$50,000 / $100,000 / $50,000"],"h1":"The first and last numbers are the same.","h2":"Mississippi requires at least $25,000 for injury to one person, $50,000 for injuries in one crash, and $25,000 for property damage.","p":"Right. The Mississippi minimum is 25, 50 and 25 thousand dollars."},"es":{"q":"En Mississippi, ¿cuál es el seguro mínimo de responsabilidad civil que debe tener un conductor?","o":["$25,000 / $50,000 / $25,000","$10,000 / $20,000 / $10,000","$15,000 / $30,000 / $5,000","$50,000 / $100,000 / $50,000"],"h1":"El primer número y el último son iguales.","h2":"Mississippi exige por lo menos $25,000 por lesiones a una persona, $50,000 por lesiones en un choque y $25,000 por daños a la propiedad.","p":"Correcto. El mínimo en Mississippi es de 25, 50 y 25 mil dólares."},"ref":{"doc":"MS","page":76}},{"id":"mt-001","scope":"MT","cat":"licensing","sign":null,"c":0,"en":{"q":"In Montana, what is the youngest age to get a learner license if you are enrolled in an approved traffic education course?","o":["14 and a half","15 and a half","16 years old","17 years old"],"h1":"Montana lets students start younger than almost any other state.","h2":"In Montana a teen who is enrolled in an approved traffic education course can get a learner license at 14 and a half.","p":"Right. With traffic education, the learner license starts at 14 and a half."},"es":{"q":"En Montana, ¿cuál es la edad mínima para obtener una licencia de aprendiz si usted está inscrito en un curso aprobado de educación vial?","o":["14 años y medio","15 años y medio","16 años","17 años"],"h1":"Montana permite empezar más joven que casi cualquier otro estado.","h2":"En Montana, un adolescente inscrito en un curso aprobado de educación vial puede obtener la licencia de aprendiz a los 14 años y medio.","p":"Correcto. Con educación vial, la licencia de aprendiz empieza a los 14 años y medio."},"ref":{"doc":"MT","page":8}},{"id":"mt-002","scope":"MT","cat":"licensing","sign":null,"c":2,"en":{"q":"In Montana, how long must a teen hold a learner license before getting a first-year restricted license?","o":["1 month","3 months","6 months","12 months"],"h1":"It is half a year.","h2":"A Montana teen must hold the learner license for at least six months in a row before applying for the first-year restricted license.","p":"Right. The learner license is held for six months."},"es":{"q":"En Montana, ¿cuánto tiempo debe tener un adolescente la licencia de aprendiz antes de obtener la licencia restringida del primer año?","o":["1 mes","3 meses","6 meses","12 meses"],"h1":"Es medio año.","h2":"En Montana, un adolescente debe tener la licencia de aprendiz por lo menos seis meses seguidos antes de solicitar la licencia restringida del primer año.","p":"Correcto. La licencia de aprendiz se tiene seis meses."},"ref":{"doc":"MT","page":8}},{"id":"mt-003","scope":"MT","cat":"licensing","sign":null,"c":3,"en":{"q":"In Montana, how many hours of supervised driving must a teen complete with a learner license?","o":["20 hours","30 hours","40 hours","50 hours"],"h1":"A parent records these hours on a driving log.","h2":"A Montana teen must complete at least 50 hours of supervised driving while holding the learner license, and a parent certifies the log.","p":"Right. Montana asks for 50 supervised hours."},"es":{"q":"En Montana, ¿cuántas horas de manejo supervisado debe completar un adolescente con licencia de aprendiz?","o":["20 horas","30 horas","40 horas","50 horas"],"h1":"Uno de los padres anota estas horas en un registro de manejo.","h2":"En Montana, un adolescente debe completar por lo menos 50 horas de manejo supervisado con la licencia de aprendiz, y uno de los padres certifica el registro.","p":"Correcto. Montana pide 50 horas supervisadas."},"ref":{"doc":"MT","page":7}},{"id":"mt-004","scope":"MT","cat":"licensing","sign":null,"c":1,"en":{"q":"In Montana, how many of the 50 supervised practice hours must be at night?","o":["5 hours","10 hours","20 hours","25 hours"],"h1":"It is one fifth of the total.","h2":"Of the 50 supervised hours in Montana, at least 10 must be driven at night, so the teen learns to drive in the dark.","p":"Right. 10 of the 50 hours are at night."},"es":{"q":"En Montana, ¿cuántas de las 50 horas de práctica supervisada deben ser de noche?","o":["5 horas","10 horas","20 horas","25 horas"],"h1":"Es una quinta parte del total.","h2":"De las 50 horas supervisadas en Montana, por lo menos 10 deben ser de noche, para que el adolescente aprenda a manejar en la oscuridad.","p":"Correcto. 10 de las 50 horas son de noche."},"ref":{"doc":"MT","page":7}},{"id":"mt-005","scope":"MT","cat":"licensing","sign":null,"c":3,"en":{"q":"In Montana, a learner under 18 may drive with a parent or guardian, or with their permission, with whom?","o":["Any passenger of any age","A friend age 16 or older","Only a police officer","A licensed driver age 18 or older"],"h1":"The person must be an adult with a license.","h2":"In Montana a learner under 18 must be supervised by a parent or guardian, or, with the parent's permission, by a licensed driver who is at least 18.","p":"Right. With permission, a licensed driver 18 or older may supervise."},"es":{"q":"En Montana, un aprendiz menor de 18 años puede manejar con su padre, madre o tutor, o con su permiso, ¿con quién?","o":["Cualquier pasajero de cualquier edad","Un amigo de 16 años o más","Solamente un policía","Un conductor con licencia de 18 años o más"],"h1":"La persona debe ser un adulto con licencia.","h2":"En Montana, un aprendiz menor de 18 años debe ir supervisado por su padre, madre o tutor, o, con permiso de ellos, por un conductor con licencia de por lo menos 18 años.","p":"Correcto. Con permiso, puede supervisar un conductor con licencia de 18 años o más."},"ref":{"doc":"MT","page":7}},{"id":"mt-006","scope":"MT","cat":"licensing","sign":null,"c":1,"en":{"q":"In Montana, during the first year with a restricted license, when may a teen not drive unless an exception applies?","o":["From 10 p.m. to 6 a.m.","From 11 p.m. to 5 a.m.","From midnight to 5 a.m.","From 9 p.m. to 5 a.m."],"h1":"It starts one hour before midnight.","h2":"A Montana teen with a first-year restricted license may not drive between 11 p.m. and 5 a.m., unless a listed exception applies, such as an emergency.","p":"Right. No driving from 11 p.m. to 5 a.m. without an exception."},"es":{"q":"En Montana, durante el primer año con licencia restringida, ¿cuándo no puede manejar un adolescente salvo que aplique una excepción?","o":["De 10 p.m. a 6 a.m.","De 11 p.m. a 5 a.m.","De medianoche a 5 a.m.","De 9 p.m. a 5 a.m."],"h1":"Empieza una hora antes de la medianoche.","h2":"En Montana, un adolescente con licencia restringida del primer año no puede manejar entre las 11 p.m. y las 5 a.m., salvo que aplique una excepción de la lista, como una emergencia.","p":"Correcto. No se maneja de 11 p.m. a 5 a.m. sin una excepción."},"ref":{"doc":"MT","page":8}},{"id":"mt-007","scope":"MT","cat":"licensing","sign":null,"c":0,"en":{"q":"In Montana, during the first six months with a restricted license, how many passengers under 18 may a teen carry without an adult supervisor?","o":["No more than one","No more than two","No more than three","As many as there are seat belts"],"h1":"The number is very small at first.","h2":"In the first six months, a Montana restricted licensee may not carry more than one passenger under 18 unless a licensed driver age 18 or older is supervising.","p":"Right. At first, no more than one passenger under 18."},"es":{"q":"En Montana, durante los primeros seis meses con licencia restringida, ¿cuántos pasajeros menores de 18 años puede llevar un adolescente sin un adulto supervisor?","o":["No más de uno","No más de dos","No más de tres","Tantos como cinturones haya"],"h1":"Al principio el número es muy pequeño.","h2":"En los primeros seis meses, quien tiene licencia restringida en Montana no puede llevar más de un pasajero menor de 18 años, salvo que lo supervise un conductor con licencia de 18 años o más.","p":"Correcto. Al principio, no más de un pasajero menor de 18."},"ref":{"doc":"MT","page":8}},{"id":"mt-008","scope":"MT","cat":"licensing","sign":null,"c":2,"en":{"q":"In Montana, how long do the restrictions on a teen's first license last?","o":["Six months, at any age","Two years, or until age 21","One year, or until age 18 if sooner","Until the teen finishes high school"],"h1":"Whichever comes first ends them.","h2":"Montana's first-license restrictions last one year from the date the license is issued, or until the driver turns 18 if that comes first.","p":"Right. One year, or until 18, whichever is first."},"es":{"q":"En Montana, ¿cuánto duran las restricciones de la primera licencia de un adolescente?","o":["Seis meses, a cualquier edad","Dos años, o hasta los 21","Un año, o hasta los 18 si es antes","Hasta que termine la secundaria"],"h1":"Las termina lo que ocurra primero.","h2":"Las restricciones de la primera licencia en Montana duran un año desde que se emite la licencia, o hasta que el conductor cumple 18 años si eso ocurre antes.","p":"Correcto. Un año, o hasta los 18, lo que ocurra primero."},"ref":{"doc":"MT","page":8}},{"id":"mt-009","scope":"MT","cat":"licensing","sign":null,"c":3,"en":{"q":"In Montana, what seat belt rule applies to a teen with a first-year restricted license?","o":["Only the driver must buckle up","Only front-seat riders must buckle up","Belts are needed only on highways","Every rider must be belted, one person per belt"],"h1":"The number of people may not be more than the number of belts.","h2":"A Montana restricted licensee may drive only if every person in the vehicle wears a seat belt or proper restraint, and there are no more riders than belts.","p":"Right. Everyone belted, and no more riders than seat belts."},"es":{"q":"En Montana, ¿qué regla de cinturón de seguridad aplica a un adolescente con licencia restringida del primer año?","o":["Solo el conductor debe abrocharse","Solo los de adelante deben abrocharse","Los cinturones solo se necesitan en carretera","Todos deben usar cinturón, una persona por cinturón"],"h1":"El número de personas no puede ser mayor que el de cinturones.","h2":"En Montana, quien tiene licencia restringida solo puede manejar si cada persona en el vehículo usa cinturón o el sistema de sujeción adecuado, y no hay más personas que cinturones.","p":"Correcto. Todos con cinturón, y no más personas que cinturones."},"ref":{"doc":"MT","page":8}},{"id":"mt-010","scope":"MT","cat":"licensing","sign":null,"c":2,"en":{"q":"In Montana, how long is a learner license valid after you pass the written test?","o":["30 days","6 months","One year","Two years"],"h1":"It lasts long enough for a full season of practice and more.","h2":"A Montana learner license is issued after you pass the written and vision tests, and it is valid for one year.","p":"Right. The learner license is valid for one year."},"es":{"q":"En Montana, ¿cuánto tiempo es válida la licencia de aprendiz después de aprobar el examen escrito?","o":["30 días","6 meses","Un año","Dos años"],"h1":"Dura lo suficiente para una temporada completa de práctica y más.","h2":"En Montana, la licencia de aprendiz se emite después de aprobar el examen escrito y el de la vista, y es válida por un año.","p":"Correcto. La licencia de aprendiz es válida por un año."},"ref":{"doc":"MT","page":8}},{"id":"mt-011","scope":"MT","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Montana, what is the speed limit on an interstate outside a city of 50,000 people or more?","o":["75 mph","80 mph","70 mph","85 mph"],"h1":"It is one of the highest limits in the country.","h2":"Montana law sets 80 mph at all times on interstates outside urbanized areas of 50,000 people or more, unless a lower limit is posted.","p":"Right. Rural Montana interstates are 80 mph."},"es":{"q":"En Montana, ¿cuál es el límite de velocidad en una autopista interestatal fuera de una ciudad de 50,000 habitantes o más?","o":["75 mph","80 mph","70 mph","85 mph"],"h1":"Es uno de los límites más altos del país.","h2":"La ley de Montana fija 80 mph a toda hora en las autopistas interestatales fuera de zonas urbanas de 50,000 habitantes o más, salvo que se indique un límite menor.","p":"Correcto. Las interestatales rurales de Montana son de 80 mph."},"ref":{"doc":"MT","page":null}},{"id":"mt-012","scope":"MT","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Montana, what is the speed limit on an interstate inside an urban area of 50,000 people or more, such as Billings?","o":["55 mph","70 mph","80 mph","65 mph"],"h1":"It is 15 mph lower than on rural interstates.","h2":"Montana law sets 65 mph on interstates inside urbanized areas of 50,000 people or more, because traffic there is heavier.","p":"Right. Urban interstates in Montana are 65 mph."},"es":{"q":"En Montana, ¿cuál es el límite de velocidad en una autopista interestatal dentro de una zona urbana de 50,000 habitantes o más, como Billings?","o":["55 mph","70 mph","80 mph","65 mph"],"h1":"Es 15 mph menos que en las interestatales rurales.","h2":"La ley de Montana fija 65 mph en las autopistas interestatales dentro de zonas urbanas de 50,000 habitantes o más, porque allí hay más tráfico.","p":"Correcto. Las interestatales urbanas de Montana son de 65 mph."},"ref":{"doc":"MT","page":38}},{"id":"mt-013","scope":"MT","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Montana, what is the daytime speed limit for a car on a two-lane highway?","o":["70 mph","60 mph","65 mph","80 mph"],"h1":"The night limit on the same road is 5 mph lower.","h2":"On a Montana two-lane highway, a car may go up to 70 mph in the daytime, unless a sign shows a different limit.","p":"Right. Two-lane highways are 70 mph in the daytime."},"es":{"q":"En Montana, ¿cuál es el límite de velocidad de día para un carro en una carretera de dos carriles?","o":["70 mph","60 mph","65 mph","80 mph"],"h1":"El límite de noche en esa misma carretera es 5 mph menor.","h2":"En una carretera de dos carriles de Montana, un carro puede ir hasta 70 mph de día, salvo que un letrero indique otro límite.","p":"Correcto. Las carreteras de dos carriles son de 70 mph de día."},"ref":{"doc":"MT","page":38}},{"id":"mt-014","scope":"MT","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Montana, what is the nighttime speed limit for a car on a two-lane highway?","o":["55 mph","60 mph","65 mph","70 mph"],"h1":"It is 5 mph lower than the daytime limit.","h2":"On a Montana two-lane highway, a car may go up to 65 mph at night, which is 5 mph lower than in the daytime.","p":"Right. Two-lane highways are 65 mph at night."},"es":{"q":"En Montana, ¿cuál es el límite de velocidad de noche para un carro en una carretera de dos carriles?","o":["55 mph","60 mph","65 mph","70 mph"],"h1":"Es 5 mph menos que el límite de día.","h2":"En una carretera de dos carriles de Montana, un carro puede ir hasta 65 mph de noche, 5 mph menos que de día.","p":"Correcto. Las carreteras de dos carriles son de 65 mph de noche."},"ref":{"doc":"MT","page":38}},{"id":"mt-015","scope":"MT","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Montana, for speed limits, when does \"daytime\" begin and end?","o":["From sunrise to sunset","From 6 a.m. to 6 p.m.","From 7 a.m. to 9 p.m.","From half an hour before sunrise to half an hour after sunset"],"h1":"It adds a little time at each end of the day.","h2":"Montana law defines daytime as from half an hour before sunrise to half an hour after sunset, and every other hour counts as nighttime.","p":"Right. Daytime runs half an hour before sunrise to half an hour after sunset."},"es":{"q":"En Montana, para los límites de velocidad, ¿cuándo empieza y termina el \"día\"?","o":["Desde la salida hasta la puesta del sol","De 6 a.m. a 6 p.m.","De 7 a.m. a 9 p.m.","Desde media hora antes de la salida del sol hasta media hora después de la puesta"],"h1":"Agrega un poco de tiempo a cada extremo del día.","h2":"La ley de Montana define el día como desde media hora antes de la salida del sol hasta media hora después de la puesta, y toda otra hora cuenta como noche.","p":"Correcto. El día va de media hora antes del amanecer a media hora después del atardecer."},"ref":{"doc":"MT","page":null}},{"id":"mt-016","scope":"MT","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Montana, what is the speed limit in an urban district, if no sign says otherwise?","o":["20 mph","25 mph","35 mph","45 mph"],"h1":"It is the same number many states use near homes.","h2":"Montana law sets 25 mph in urban districts unless a different limit is posted, because people and cars are close together there.","p":"Right. Urban districts are 25 mph."},"es":{"q":"En Montana, ¿cuál es el límite de velocidad en una zona urbana, si no hay letrero que diga otra cosa?","o":["20 mph","25 mph","35 mph","45 mph"],"h1":"Es el mismo número que muchos estados usan cerca de las casas.","h2":"La ley de Montana fija 25 mph en zonas urbanas salvo que se indique otro límite, porque allí la gente y los carros están muy cerca.","p":"Correcto. Las zonas urbanas son de 25 mph."},"ref":{"doc":"MT","page":null}},{"id":"mt-017","scope":"MT","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Montana, on a two-lane highway, when may you go up to 10 mph over the limit?","o":["Whenever traffic is light","When you are late for work","Only while passing in a passing zone","Only at night on empty roads"],"h1":"It is a short moment, not a whole trip.","h2":"Montana lets you exceed the limit by up to 10 mph only while passing on a two-lane highway in a passing zone, and you must return safely to the right lane.","p":"Right. Only while passing, in a passing zone."},"es":{"q":"En Montana, en una carretera de dos carriles, ¿cuándo puede ir hasta 10 mph por encima del límite?","o":["Siempre que haya poco tráfico","Cuando va tarde al trabajo","Solo mientras rebasa en una zona de rebase","Solo de noche en caminos vacíos"],"h1":"Es un momento corto, no todo el viaje.","h2":"Montana le permite pasar el límite hasta por 10 mph solo mientras rebasa en una carretera de dos carriles, en una zona de rebase, y debe volver con seguridad al carril derecho.","p":"Correcto. Solo al rebasar, en una zona de rebase."},"ref":{"doc":"MT","page":38}},{"id":"mt-018","scope":"MT","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Montana, a driver under 21 breaks the law with what blood alcohol level or more?","o":["0.08 percent","0.05 percent","0.02 percent","0.10 percent"],"h1":"It is far below the adult limit.","h2":"In Montana it is illegal for a person under 21 to drive with a blood alcohol level of 0.02 percent or more.","p":"Right. Under 21, the limit is 0.02."},"es":{"q":"En Montana, ¿a partir de qué nivel de alcohol en la sangre viola la ley un conductor menor de 21 años?","o":["0.08 por ciento","0.05 por ciento","0.02 por ciento","0.10 por ciento"],"h1":"Está muy por debajo del límite para adultos.","h2":"En Montana es ilegal que una persona menor de 21 años maneje con un nivel de alcohol en la sangre de 0.02 por ciento o más.","p":"Correcto. Para menores de 21, el límite es 0.02."},"ref":{"doc":"MT","page":72}},{"id":"mt-019","scope":"MT","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Montana, what is the legal blood alcohol limit for an adult driving a regular car?","o":["0.05 percent","0.08 percent","0.04 percent","0.10 percent"],"h1":"It is the most common adult limit in the United States.","h2":"In Montana an adult driving a regular car is legally under the influence at a blood alcohol level of 0.08 percent or more.","p":"Right. The adult limit is 0.08."},"es":{"q":"En Montana, ¿cuál es el límite legal de alcohol en la sangre para un adulto que maneja un carro común?","o":["0.05 por ciento","0.08 por ciento","0.04 por ciento","0.10 por ciento"],"h1":"Es el límite para adultos más común en Estados Unidos.","h2":"En Montana, un adulto que maneja un carro común está legalmente bajo la influencia con un nivel de alcohol de 0.08 por ciento o más.","p":"Correcto. El límite para adultos es 0.08."},"ref":{"doc":"MT","page":72}},{"id":"mt-021","scope":"MT","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Montana, can police stop an adult driver only because they are not wearing a seat belt?","o":["No, only for another violation","Yes, at any time","Yes, but only at night","Yes, but only on interstates"],"h1":"For adults, the belt law is enforced together with another stop.","h2":"Montana's adult seat belt law is secondary, so police may ticket for it only after stopping a driver for another violation; you should still always buckle up.","p":"Right. For adults, the seat belt law is secondary."},"es":{"q":"En Montana, ¿puede la policía detener a un conductor adulto solo porque no lleva el cinturón de seguridad?","o":["No, solo por otra infracción","Sí, en cualquier momento","Sí, pero solo de noche","Sí, pero solo en interestatales"],"h1":"Para adultos, la ley del cinturón se aplica junto con otra detención.","h2":"La ley del cinturón para adultos en Montana es secundaria, así que la policía puede multar por ella solo después de detener al conductor por otra infracción; aun así, siempre debe abrocharse.","p":"Correcto. Para adultos, la ley del cinturón es secundaria."},"ref":{"doc":"MT","page":null}},{"id":"mt-022","scope":"MT","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Montana, you come up on a stopped police car, emergency vehicle, or highway work vehicle with its lights flashing. What must you do?","o":["Keep your lane and your speed","Stop next to it until it leaves","Slow down and move to a lane away from it if you safely can","Honk to warn the workers"],"h1":"The law asks you to give workers both space and time.","h2":"In Montana you must slow down when you pass a stopped police, emergency or highway work vehicle with flashing lights, and move to a lane that is not next to it when you safely can.","p":"Right. Slow down and move over when you safely can."},"es":{"q":"En Montana, usted se acerca a un carro de policía, vehículo de emergencia o vehículo de obras viales detenido con las luces intermitentes. ¿Qué debe hacer?","o":["Seguir en su carril y a su velocidad","Pararse a su lado hasta que se vaya","Bajar la velocidad y pasarse a un carril alejado si puede hacerlo con seguridad","Tocar la bocina para avisar a los trabajadores"],"h1":"La ley le pide dar a los trabajadores espacio y tiempo.","h2":"En Montana, usted debe bajar la velocidad al pasar un vehículo de policía, de emergencia o de obras viales detenido con luces intermitentes, y pasarse a un carril que no esté junto a él cuando pueda hacerlo con seguridad.","p":"Correcto. Baje la velocidad y cámbiese de carril cuando sea seguro."},"ref":{"doc":"MT","page":null}},{"id":"mt-023","scope":"MT","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Montana, on a divided highway with a raised median, which drivers must stop for a school bus with flashing red lights?","o":["All drivers in both directions","Drivers going the same direction as the bus","Only drivers in the lane next to the bus","Only drivers going the opposite direction"],"h1":"The raised median keeps children from crossing the far side.","h2":"On a Montana divided highway with a raised median, drivers going the same direction as a stopped school bus must stop, while traffic on the other side does not have to.","p":"Right. With a raised median, same-direction traffic stops."},"es":{"q":"En Montana, en una carretera dividida con camellón elevado, ¿qué conductores deben parar ante un autobús escolar con luces rojas intermitentes?","o":["Todos los conductores en ambas direcciones","Los que van en la misma dirección que el autobús","Solo los del carril junto al autobús","Solo los que van en dirección contraria"],"h1":"El camellón elevado impide que los niños crucen al otro lado.","h2":"En una carretera dividida con camellón elevado en Montana, los conductores que van en la misma dirección que el autobús escolar detenido deben parar, y el tráfico del otro lado no tiene que hacerlo.","p":"Correcto. Con camellón elevado, para el tráfico de la misma dirección."},"ref":{"doc":"MT","page":40}},{"id":"mt-024","scope":"MT","cat":"licensing","sign":null,"c":0,"en":{"q":"In Montana, what is the minimum liability insurance a driver must carry?","o":["$25,000 / $50,000 / $20,000","$25,000 / $50,000 / $15,000","$50,000 / $100,000 / $25,000","$15,000 / $30,000 / $10,000"],"h1":"The property damage part is $20,000.","h2":"Montana requires at least $25,000 for injury to one person, $50,000 for injuries in one crash, and $20,000 for property damage.","p":"Right. Montana's minimum is 25/50/20."},"es":{"q":"En Montana, ¿cuál es el seguro de responsabilidad mínimo que debe tener un conductor?","o":["$25,000 / $50,000 / $20,000","$25,000 / $50,000 / $15,000","$50,000 / $100,000 / $25,000","$15,000 / $30,000 / $10,000"],"h1":"La parte de daños a la propiedad es de $20,000.","h2":"Montana exige por lo menos $25,000 por lesiones a una persona, $50,000 por lesiones en un mismo choque y $20,000 por daños a la propiedad.","p":"Correcto. El mínimo en Montana es 25/50/20."},"ref":{"doc":"MT","page":null}},{"id":"mt-025","scope":"MT","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Montana, cattle are crossing the road ahead of you in open range country. What should you do?","o":["Honk so they move faster","Drive slowly through the herd","Nudge them gently with the bumper","Stop and wait until they have crossed"],"h1":"Animals can slip on pavement when they are scared.","h2":"In Montana's open range, when livestock are crossing the road you should stop and wait, because honking or pushing can make animals panic and fall.","p":"Right. Stop and wait for the animals to cross."},"es":{"q":"En Montana, unas vacas cruzan el camino delante de usted en zona de campo abierto. ¿Qué debe hacer?","o":["Tocar la bocina para que se apuren","Pasar despacio entre el ganado","Empujarlas suavemente con el parachoques","Parar y esperar hasta que hayan cruzado"],"h1":"Los animales pueden resbalar en el pavimento cuando se asustan.","h2":"En el campo abierto de Montana, cuando el ganado cruza el camino usted debe parar y esperar, porque la bocina o los empujones pueden asustar a los animales y hacerlos caer.","p":"Correcto. Pare y espere a que crucen los animales."},"ref":{"doc":"MT","page":67}},{"id":"mt-026","scope":"MT","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Montana, what does \"open range\" mean for drivers?","o":["Roads closed to trucks","Land without a proper fence, where livestock may be on the road","Highways with no speed limit","Areas where hunting is allowed from cars"],"h1":"Think about what a fence keeps off the road.","h2":"In Montana, open range is land not closed in by a fence, including public highways, so cattle and other livestock may be on or near the road.","p":"Right. On open range, expect livestock on the road."},"es":{"q":"En Montana, ¿qué significa \"campo abierto\" (open range) para los conductores?","o":["Caminos cerrados a camiones","Terreno sin una cerca adecuada, donde puede haber ganado en el camino","Carreteras sin límite de velocidad","Zonas donde se permite cazar desde el carro"],"h1":"Piense en lo que una cerca mantiene fuera del camino.","h2":"En Montana, el campo abierto es el terreno que no está cerrado por una cerca, incluidas las carreteras públicas, así que puede haber vacas y otro ganado en el camino o cerca de él.","p":"Correcto. En campo abierto, espere ganado en el camino."},"ref":{"doc":"MT","page":25}},{"id":"nc-001","scope":"NC","cat":"licensing","sign":null,"c":1,"en":{"q":"In North Carolina, what is the youngest age to get a limited learner permit (Level 1)?","o":["14 years old","15 years old","16 years old","18 years old"],"h1":"It is one year before the age for a Level 2 license.","h2":"In North Carolina you can get a Level 1 limited learner permit at 15, after a driver education course.","p":"Right. The Level 1 permit starts at 15."},"es":{"q":"En Carolina del Norte, ¿cuál es la edad mínima para obtener el permiso limitado de aprendiz (Nivel 1)?","o":["14 años","15 años","16 años","18 años"],"h1":"Es un año antes de la edad para la licencia de Nivel 2.","h2":"En Carolina del Norte usted puede obtener el permiso limitado de aprendiz de Nivel 1 a los 15 años, después de un curso de educación vial.","p":"Correcto. El permiso de Nivel 1 empieza a los 15."},"ref":{"doc":"NC","page":12}},{"id":"nc-002","scope":"NC","cat":"licensing","sign":null,"c":0,"en":{"q":"In North Carolina, how many levels does the graduated license for teens have?","o":["Three","Two","Four","Five"],"h1":"Learner permit, limited provisional, then full provisional.","h2":"North Carolina's teen license has three levels: a limited learner permit, a limited provisional license and a full provisional license.","p":"Right. There are three levels."},"es":{"q":"En Carolina del Norte, ¿cuántos niveles tiene la licencia graduada para adolescentes?","o":["Tres","Dos","Cuatro","Cinco"],"h1":"Permiso de aprendiz, provisional limitada y luego provisional completa.","h2":"La licencia para adolescentes en Carolina del Norte tiene tres niveles: permiso limitado de aprendiz, licencia provisional limitada y licencia provisional completa.","p":"Correcto. Son tres niveles."},"ref":{"doc":"NC","page":12}},{"id":"nc-003","scope":"NC","cat":"licensing","sign":null,"c":2,"en":{"q":"In North Carolina, during the first six months of a Level 1 permit, when may the permit holder drive?","o":["Any time, day or night","Only on weekends","Only between 5 a.m. and 9 p.m., with a supervising driver","Only between noon and 6 p.m."],"h1":"The window starts early in the morning and ends in the evening.","h2":"During the first six months of a North Carolina Level 1 permit, you may drive only between 5 a.m. and 9 p.m., and always with a supervising driver.","p":"Right. 5 a.m. to 9 p.m., with a supervisor."},"es":{"q":"En Carolina del Norte, durante los primeros seis meses del permiso de Nivel 1, ¿cuándo puede manejar el titular?","o":["A cualquier hora, de día o de noche","Solo los fines de semana","Solo entre las 5 a.m. y las 9 p.m., con un conductor supervisor","Solo entre el mediodía y las 6 p.m."],"h1":"El horario empieza temprano en la mañana y termina en la noche.","h2":"Durante los primeros seis meses del permiso de Nivel 1 en Carolina del Norte, usted solo puede manejar entre las 5 a.m. y las 9 p.m., y siempre con un conductor supervisor.","p":"Correcto. De 5 a.m. a 9 p.m., con un supervisor."},"ref":{"doc":"NC","page":12}},{"id":"nc-004","scope":"NC","cat":"licensing","sign":null,"c":3,"en":{"q":"In North Carolina, after the first six months of a Level 1 permit, when may the permit holder drive?","o":["Only in daylight","Alone at any time","Never at night","At any time, but only with a supervising driver"],"h1":"The hours open up, but one thing does not change.","h2":"After the first six months, a North Carolina Level 1 permit holder may drive at any time, but still only with a supervising driver.","p":"Right. Any time, but always with a supervisor."},"es":{"q":"En Carolina del Norte, después de los primeros seis meses del permiso de Nivel 1, ¿cuándo puede manejar el titular?","o":["Solo de día","Solo, a cualquier hora","Nunca de noche","A cualquier hora, pero solo con un conductor supervisor"],"h1":"El horario se abre, pero hay algo que no cambia.","h2":"Después de los primeros seis meses, el titular de un permiso de Nivel 1 en Carolina del Norte puede manejar a cualquier hora, pero siempre con un conductor supervisor.","p":"Correcto. A cualquier hora, pero siempre con un supervisor."},"ref":{"doc":"NC","page":12}},{"id":"nc-005","scope":"NC","cat":"licensing","sign":null,"c":1,"en":{"q":"In North Carolina, how long must a supervising driver have been licensed?","o":["At least one year","At least five years","At least ten years","At least 20 years"],"h1":"It is more than a few years, but less than ten.","h2":"In North Carolina a supervising driver must be a licensed driver who has held a license for at least five years.","p":"Right. Licensed for at least five years."},"es":{"q":"En Carolina del Norte, ¿cuánto tiempo debe tener licencia un conductor supervisor?","o":["Por lo menos un año","Por lo menos cinco años","Por lo menos diez años","Por lo menos 20 años"],"h1":"Son más de unos pocos años, pero menos de diez.","h2":"En Carolina del Norte el conductor supervisor debe tener licencia de manejo desde hace por lo menos cinco años.","p":"Correcto. Con licencia desde hace por lo menos cinco años."},"ref":{"doc":"NC","page":12}},{"id":"nc-006","scope":"NC","cat":"licensing","sign":null,"c":0,"en":{"q":"In North Carolina, where must the supervising driver sit while a Level 1 permit holder drives?","o":["In the front seat, beside the driver","In the back seat","Anywhere in the car","In another car nearby"],"h1":"The supervisor must be close enough to help right away.","h2":"In North Carolina the supervising driver must sit in the front seat beside the permit holder whenever the car is moving.","p":"Right. The supervisor sits beside you in front."},"es":{"q":"En Carolina del Norte, ¿dónde debe sentarse el conductor supervisor mientras maneja el titular de un permiso de Nivel 1?","o":["En el asiento delantero, al lado del conductor","En el asiento de atrás","En cualquier lugar del carro","En otro carro cercano"],"h1":"El supervisor debe estar lo bastante cerca para ayudar de inmediato.","h2":"En Carolina del Norte el conductor supervisor debe sentarse en el asiento delantero, al lado del titular del permiso, siempre que el carro esté en movimiento.","p":"Correcto. El supervisor va a su lado, adelante."},"ref":{"doc":"NC","page":null}},{"id":"nc-007","scope":"NC","cat":"licensing","sign":null,"c":2,"en":{"q":"In North Carolina, what is the youngest age for a Level 2 limited provisional license?","o":["15 years old","15 and a half","16 years old","18 years old"],"h1":"It is one year after the youngest age for a Level 1 permit.","h2":"In North Carolina the youngest age for a Level 2 limited provisional license is 16.","p":"Right. Level 2 starts at 16."},"es":{"q":"En Carolina del Norte, ¿cuál es la edad mínima para la licencia provisional limitada de Nivel 2?","o":["15 años","15 años y medio","16 años","18 años"],"h1":"Es un año después de la edad mínima para el permiso de Nivel 1.","h2":"En Carolina del Norte la edad mínima para la licencia provisional limitada de Nivel 2 es de 16 años.","p":"Correcto. El Nivel 2 empieza a los 16."},"ref":{"doc":"NC","page":13}},{"id":"nc-008","scope":"NC","cat":"licensing","sign":null,"c":0,"en":{"q":"In North Carolina, during which hours may a Level 2 driver drive without a supervising driver?","o":["From 5 a.m. to 9 p.m.","From 6 a.m. to midnight","From 7 a.m. to 7 p.m.","Any hour of the day"],"h1":"These are the same hours as the first months of the Level 1 permit.","h2":"A North Carolina Level 2 driver may drive alone from 5 a.m. to 9 p.m.; from 9 p.m. to 5 a.m. a supervising driver is needed, with a few exceptions.","p":"Right. Alone from 5 a.m. to 9 p.m."},"es":{"q":"En Carolina del Norte, ¿en qué horario puede manejar un conductor de Nivel 2 sin un conductor supervisor?","o":["De 5 a.m. a 9 p.m.","De 6 a.m. a medianoche","De 7 a.m. a 7 p.m.","A cualquier hora del día"],"h1":"Es el mismo horario de los primeros meses del permiso de Nivel 1.","h2":"Un conductor de Nivel 2 en Carolina del Norte puede manejar solo de 5 a.m. a 9 p.m.; de 9 p.m. a 5 a.m. necesita un conductor supervisor, con algunas excepciones.","p":"Correcto. Solo, de 5 a.m. a 9 p.m."},"ref":{"doc":"NC","page":13}},{"id":"nc-009","scope":"NC","cat":"licensing","sign":null,"c":3,"en":{"q":"In North Carolina, which trip may a Level 2 driver make alone after 9 p.m.?","o":["Going to a friend's party","Driving around for fun","Going to the movies","Driving directly to or from work"],"h1":"It is a trip with a serious, regular purpose.","h2":"A North Carolina Level 2 driver may drive alone after 9 p.m. when driving directly to or from work; volunteer fire, rescue or EMS trips are also allowed.","p":"Right. Driving straight to or from work is allowed."},"es":{"q":"En Carolina del Norte, ¿qué viaje puede hacer solo un conductor de Nivel 2 después de las 9 p.m.?","o":["Ir a la fiesta de un amigo","Pasear por diversión","Ir al cine","Manejar directo al trabajo o de regreso del trabajo"],"h1":"Es un viaje con un propósito serio y regular.","h2":"Un conductor de Nivel 2 en Carolina del Norte puede manejar solo después de las 9 p.m. cuando va directo al trabajo o regresa de él; también se permiten viajes como voluntario de bomberos, rescate o emergencias médicas.","p":"Correcto. Ir directo al trabajo o regresar está permitido."},"ref":{"doc":"NC","page":13}},{"id":"nc-010","scope":"NC","cat":"licensing","sign":null,"c":2,"en":{"q":"In North Carolina, as a general rule, how many passengers under 21 who are not family may a Level 2 driver carry when no supervising driver is in the car?","o":["None","Three","One","Four"],"h1":"It is the smallest number above zero.","h2":"As a general rule, a North Carolina Level 2 driver without a supervisor may carry only one passenger under 21 who is not from the driver's household; one more student may ride on a trip straight to or from school.","p":"Right. Only one passenger under 21."},"es":{"q":"En Carolina del Norte, como regla general, ¿cuántos pasajeros menores de 21 años que no son de la familia puede llevar un conductor de Nivel 2 cuando no va un conductor supervisor en el carro?","o":["Ninguno","Tres","Uno","Cuatro"],"h1":"Es el número más pequeño mayor que cero.","h2":"Como regla general, un conductor de Nivel 2 en Carolina del Norte sin supervisor solo puede llevar un pasajero menor de 21 años que no sea de su hogar; un estudiante más puede ir en un viaje directo a la escuela o de regreso.","p":"Correcto. Solo un pasajero menor de 21."},"ref":{"doc":"NC","page":13}},{"id":"nc-011","scope":"NC","cat":"licensing","sign":null,"c":1,"en":{"q":"In North Carolina, when does the one-passenger-under-21 limit for Level 2 drivers not apply?","o":["When it is raining","When all the passengers live in the driver's household","When the passengers are over 16","On short trips"],"h1":"Think about who lives under the same roof.","h2":"The North Carolina Level 2 limit of one passenger under 21 does not apply when all the passengers are members of the driver's household.","p":"Right. Household members are the exception."},"es":{"q":"En Carolina del Norte, ¿cuándo no se aplica el límite de un pasajero menor de 21 años para conductores de Nivel 2?","o":["Cuando llueve","Cuando todos los pasajeros viven en el mismo hogar que el conductor","Cuando los pasajeros tienen más de 16 años","En viajes cortos"],"h1":"Piense en quién vive bajo el mismo techo.","h2":"El límite de un pasajero menor de 21 años para el Nivel 2 en Carolina del Norte no se aplica cuando todos los pasajeros son miembros del hogar del conductor.","p":"Correcto. Los miembros del hogar son la excepción."},"ref":{"doc":"NC","page":13}},{"id":"nc-012","scope":"NC","cat":"licensing","sign":null,"c":3,"en":{"q":"In North Carolina, what changes when a teen moves to a Level 3 full provisional license?","o":["Nothing changes","The teen may no longer drive at night","The teen needs a new supervisor","The time, supervision and passenger limits of Levels 1 and 2 no longer apply"],"h1":"Level 3 is the last step before a regular license.","h2":"With a North Carolina Level 3 full provisional license, the time, supervision and passenger limits of Levels 1 and 2 no longer apply.","p":"Right. Level 3 lifts those limits."},"es":{"q":"En Carolina del Norte, ¿qué cambia cuando un adolescente pasa a la licencia provisional completa de Nivel 3?","o":["No cambia nada","Ya no puede manejar de noche","Necesita un nuevo supervisor","Ya no se aplican los límites de horario, supervisión y pasajeros de los Niveles 1 y 2"],"h1":"El Nivel 3 es el último paso antes de una licencia regular.","h2":"Con la licencia provisional completa de Nivel 3 en Carolina del Norte, ya no se aplican los límites de horario, supervisión y pasajeros de los Niveles 1 y 2.","p":"Correcto. El Nivel 3 quita esos límites."},"ref":{"doc":"NC","page":13}},{"id":"nc-013","scope":"NC","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In North Carolina, may a driver under 18 talk on a hands-free phone while driving?","o":["Yes, hands-free is always allowed","Yes, but only on highways","No, drivers under 18 may not use a phone at all, hands-free included","Yes, if a friend is in the car"],"h1":"For teens, the rule is stricter than for adults.","h2":"In North Carolina a driver under 18 may not use a mobile phone while driving, even a hands-free one, except for a few emergency and family calls.","p":"Right. Under 18, no phone, even hands-free."},"es":{"q":"En Carolina del Norte, ¿puede un conductor menor de 18 años hablar por teléfono con manos libres mientras maneja?","o":["Sí, el manos libres siempre está permitido","Sí, pero solo en carreteras","No, los menores de 18 no pueden usar el teléfono, ni siquiera con manos libres","Sí, si va un amigo en el carro"],"h1":"Para los adolescentes, la regla es más estricta que para los adultos.","h2":"En Carolina del Norte un conductor menor de 18 años no puede usar el teléfono mientras maneja, ni siquiera con manos libres, salvo algunas llamadas de emergencia y de familia.","p":"Correcto. Menores de 18: nada de teléfono, ni con manos libres."},"ref":{"doc":"NC","page":41}},{"id":"nc-014","scope":"NC","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In North Carolina, which phone call may a driver under 18 make while driving?","o":["A call to a friend","A call to a parent, legal guardian or spouse","A call to order food","Any call shorter than one minute"],"h1":"The exception is for emergencies and close family.","h2":"A North Carolina driver under 18 may call a parent, legal guardian or spouse, or emergency services, while driving; other calls are not allowed.","p":"Right. A parent, guardian or spouse is allowed."},"es":{"q":"En Carolina del Norte, ¿qué llamada puede hacer un conductor menor de 18 años mientras maneja?","o":["Una llamada a un amigo","Una llamada a su padre, madre, tutor legal o cónyuge","Una llamada para pedir comida","Cualquier llamada de menos de un minuto"],"h1":"La excepción es para emergencias y familia cercana.","h2":"Un conductor menor de 18 años en Carolina del Norte puede llamar a su padre, madre, tutor legal o cónyuge, o a servicios de emergencia, mientras maneja; otras llamadas no están permitidas.","p":"Correcto. Puede llamar a su padre, madre, tutor o cónyuge."},"ref":{"doc":"NC","page":12}},{"id":"nc-015","scope":"NC","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In North Carolina, may an adult driver read a text message while the car is moving?","o":["No, no driver may text or read texts while the car is moving","Yes, if the message is short","Yes, on empty roads","Yes, if the driver is over 21"],"h1":"This rule applies to drivers of every age.","h2":"North Carolina bans all drivers, of any age, from texting or reading a text message while the vehicle is moving.","p":"Right. No texting while moving, at any age."},"es":{"q":"En Carolina del Norte, ¿puede un conductor adulto leer un mensaje de texto mientras el carro está en movimiento?","o":["No, ningún conductor puede escribir ni leer mensajes mientras el carro está en movimiento","Sí, si el mensaje es corto","Sí, en calles vacías","Sí, si el conductor tiene más de 21 años"],"h1":"Esta regla es para conductores de todas las edades.","h2":"Carolina del Norte prohíbe a todos los conductores, de cualquier edad, escribir o leer mensajes de texto mientras el vehículo está en movimiento.","p":"Correcto. Nada de mensajes en movimiento, a ninguna edad."},"ref":{"doc":"NC","page":41}},{"id":"nc-016","scope":"NC","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In North Carolina, a school bus stops with its stop arm out on a two-lane road with a center turn lane. Who must stop?","o":["Only traffic behind the bus","Only traffic coming toward the bus","No one, because the turn lane separates traffic","Traffic in both directions"],"h1":"On a road with only two lanes, the turn lane does not change the rule.","h2":"In North Carolina, on a two-lane road with a center turn lane, traffic in both directions must stop for a stopped school bus.","p":"Right. Both directions stop."},"es":{"q":"En Carolina del Norte, un autobús escolar se detiene con el brazo de alto extendido en una calle de dos carriles con un carril central para girar. ¿Quién debe detenerse?","o":["Solo el tráfico detrás del autobús","Solo el tráfico que viene hacia el autobús","Nadie, porque el carril para girar separa el tráfico","El tráfico en ambas direcciones"],"h1":"En una calle de solo dos carriles, el carril para girar no cambia la regla.","h2":"En Carolina del Norte, en una calle de dos carriles con carril central para girar, el tráfico en ambas direcciones debe detenerse por un autobús escolar detenido.","p":"Correcto. Ambas direcciones se detienen."},"ref":{"doc":"NC","page":48}},{"id":"nc-017","scope":"NC","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In North Carolina, a school bus stops on a four-lane road with no median, only painted lines. Who must stop?","o":["Only traffic behind the bus","Only the lane next to the bus","Traffic in both directions","No one"],"h1":"Painted lines do not separate the two sides.","h2":"In North Carolina, on a four-lane road with no median, all traffic in both directions must stop for a stopped school bus.","p":"Right. With no median, everyone stops."},"es":{"q":"En Carolina del Norte, un autobús escolar se detiene en una calle de cuatro carriles sin mediana, solo con líneas pintadas. ¿Quién debe detenerse?","o":["Solo el tráfico detrás del autobús","Solo el carril al lado del autobús","El tráfico en ambas direcciones","Nadie"],"h1":"Las líneas pintadas no separan los dos lados.","h2":"En Carolina del Norte, en una calle de cuatro carriles sin mediana, todo el tráfico en ambas direcciones debe detenerse por un autobús escolar detenido.","p":"Correcto. Sin mediana, todos se detienen."},"ref":{"doc":"NC","page":48}},{"id":"nc-018","scope":"NC","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In North Carolina, a school bus stops on a divided highway with a median. Who must stop?","o":["Traffic in both directions","Only traffic following the bus","Only traffic coming toward the bus","No one"],"h1":"A median protects the other side of the road.","h2":"In North Carolina, on a divided highway with a median, only the traffic following the bus must stop.","p":"Right. Only traffic behind the bus stops."},"es":{"q":"En Carolina del Norte, un autobús escolar se detiene en una carretera dividida con mediana. ¿Quién debe detenerse?","o":["El tráfico en ambas direcciones","Solo el tráfico que va detrás del autobús","Solo el tráfico que viene hacia el autobús","Nadie"],"h1":"Una mediana protege el otro lado de la carretera.","h2":"En Carolina del Norte, en una carretera dividida con mediana, solo el tráfico que va detrás del autobús debe detenerse.","p":"Correcto. Solo se detiene el tráfico detrás del autobús."},"ref":{"doc":"NC","page":48}},{"id":"nc-019","scope":"NC","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In North Carolina, what does the Move Over Law require when you approach an emergency vehicle stopped on the side of the road with lights flashing?","o":["Keep your speed and lane","Stop behind it","Honk and pass quickly","Move over a lane, or slow down and be ready to stop if you cannot"],"h1":"There is a first choice, and a second choice when the first is not possible.","h2":"North Carolina's Move Over Law requires you to move over a lane, or, if you cannot, slow down to a speed that lets you stop if needed.","p":"Right. Move over, or slow down."},"es":{"q":"En Carolina del Norte, ¿qué exige la Ley de Cambio de Carril (Move Over) cuando usted se acerca a un vehículo de emergencia detenido al lado de la carretera con luces intermitentes?","o":["Mantener su velocidad y su carril","Detenerse detrás de él","Tocar la bocina y pasar rápido","Cambiarse un carril o, si no puede, bajar la velocidad y estar listo para detenerse"],"h1":"Hay una primera opción, y una segunda cuando la primera no es posible.","h2":"La Ley de Cambio de Carril de Carolina del Norte exige que usted se cambie un carril o, si no puede, que baje a una velocidad que le permita detenerse si hace falta.","p":"Correcto. Cámbiese de carril o baje la velocidad."},"ref":{"doc":"NC","page":49}},{"id":"nc-020","scope":"NC","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In North Carolina, how much alcohol may a driver under 21 have in their body while driving?","o":["None at all","Up to 0.02 percent","Up to 0.05 percent","Up to 0.08 percent"],"h1":"For drivers under 21, the rule is the strictest possible.","h2":"In North Carolina a driver under 21 may not have any alcohol in their body while driving; the 0.08 limit is only for drivers 21 and older.","p":"Right. Under 21, no alcohol at all."},"es":{"q":"En Carolina del Norte, ¿cuánto alcohol puede tener en el cuerpo un conductor menor de 21 años mientras maneja?","o":["Nada","Hasta 0.02 por ciento","Hasta 0.05 por ciento","Hasta 0.08 por ciento"],"h1":"Para menores de 21, la regla es la más estricta posible.","h2":"En Carolina del Norte un conductor menor de 21 años no puede tener nada de alcohol en el cuerpo mientras maneja; el límite de 0.08 es solo para conductores de 21 años o más.","p":"Correcto. Menores de 21: nada de alcohol."},"ref":{"doc":"NC","page":33}},{"id":"nd-001","scope":"ND","cat":"licensing","sign":null,"c":0,"en":{"q":"In North Dakota, what is the youngest age to get an instruction permit?","o":["14 years old","15 years old","16 years old","17 years old"],"h1":"North Dakota lets teens start younger than most states.","h2":"In North Dakota you can get an instruction permit at 14 years old.","p":"Right. North Dakota permits start at 14."},"es":{"q":"En Dakota del Norte, ¿cuál es la edad mínima para obtener un permiso de instrucción?","o":["14 años","15 años","16 años","17 años"],"h1":"Dakota del Norte deja empezar más joven que la mayoría de los estados.","h2":"En Dakota del Norte usted puede obtener un permiso de instrucción a los 14 años.","p":"Correcto. El permiso en Dakota del Norte empieza a los 14."},"ref":{"doc":"ND","page":3}},{"id":"nd-004","scope":"ND","cat":"licensing","sign":null,"c":1,"en":{"q":"In North Dakota, how old must the licensed adult with a permit holder be?","o":["At least 16","At least 18","At least 21","At least 25"],"h1":"It is the age when a person becomes a legal adult.","h2":"A North Dakota permit holder must drive with a licensed adult who is at least 18 years old.","p":"Right. The adult with you must be 18 or older."},"es":{"q":"En Dakota del Norte, ¿qué edad debe tener el adulto con licencia que acompaña a quien tiene permiso?","o":["Por lo menos 16","Por lo menos 18","Por lo menos 21","Por lo menos 25"],"h1":"Es la edad en que una persona se vuelve adulta ante la ley.","h2":"Quien tiene un permiso en Dakota del Norte debe manejar con un adulto con licencia de por lo menos 18 años.","p":"Correcto. El adulto que lo acompaña debe tener 18 años o más."},"ref":{"doc":"ND","page":3}},{"id":"nd-005","scope":"ND","cat":"licensing","sign":null,"c":3,"en":{"q":"In North Dakota, how much driving experience must the adult supervising a permit holder have?","o":["None","6 months","1 year","At least 3 years"],"h1":"It is more than a couple of years.","h2":"The adult supervising a North Dakota permit holder must have at least three years of driving experience.","p":"Right. The helper needs three years of experience."},"es":{"q":"En Dakota del Norte, ¿cuánta experiencia de manejo debe tener el adulto que supervisa a quien tiene permiso?","o":["Ninguna","6 meses","1 año","Por lo menos 3 años"],"h1":"Es más de un par de años.","h2":"El adulto que supervisa a quien tiene permiso en Dakota del Norte debe tener por lo menos tres años de experiencia manejando.","p":"Correcto. El acompañante necesita tres años de experiencia."},"ref":{"doc":"ND","page":3}},{"id":"nd-006","scope":"ND","cat":"licensing","sign":null,"c":2,"en":{"q":"In North Dakota, a teen gets an instruction permit at 14. How long must they hold it before the road test?","o":["30 days","3 months","1 year","2 years"],"h1":"It is a full trip around the calendar.","h2":"A 14-year-old in North Dakota must hold the instruction permit for 12 months, which is one year, before the road test.","p":"Right. At 14, you hold the permit for one year."},"es":{"q":"En Dakota del Norte, un adolescente obtiene el permiso de instrucción a los 14 años. ¿Cuánto tiempo debe tenerlo antes del examen de manejo?","o":["30 días","3 meses","1 año","2 años"],"h1":"Es una vuelta completa al calendario.","h2":"Un joven de 14 años en Dakota del Norte debe tener el permiso de instrucción por 12 meses, es decir un año, antes del examen de manejo.","p":"Correcto. A los 14, tiene el permiso por un año."},"ref":{"doc":"ND","page":3}},{"id":"nd-007","scope":"ND","cat":"licensing","sign":null,"c":0,"en":{"q":"In North Dakota, how long must a 16-year-old hold an instruction permit before a license?","o":["6 months","1 month","1 year","18 months"],"h1":"It is half as long as the rule for younger teens.","h2":"A 16-year-old in North Dakota must hold the instruction permit for six months before getting a license.","p":"Right. At 16, the wait is six months."},"es":{"q":"En Dakota del Norte, ¿cuánto tiempo debe tener el permiso de instrucción una persona de 16 años antes de la licencia?","o":["6 meses","1 mes","1 año","18 meses"],"h1":"Es la mitad del tiempo que deben esperar los más jóvenes.","h2":"Una persona de 16 años en Dakota del Norte debe tener el permiso de instrucción seis meses antes de obtener la licencia.","p":"Correcto. A los 16, la espera es de seis meses."},"ref":{"doc":"ND","page":3}},{"id":"nd-008","scope":"ND","cat":"licensing","sign":null,"c":3,"en":{"q":"In North Dakota, how many hours of supervised driving must a permit holder under 16 complete?","o":["10 hours","20 hours","100 hours","50 hours"],"h1":"It is half of one hundred.","h2":"A North Dakota permit holder under 16 must complete at least 50 hours of supervised practice driving.","p":"Right. Under 16, you need 50 hours."},"es":{"q":"En Dakota del Norte, ¿cuántas horas de manejo supervisado debe completar un joven con permiso menor de 16 años?","o":["10 horas","20 horas","100 horas","50 horas"],"h1":"Es la mitad de cien.","h2":"Un joven con permiso menor de 16 años en Dakota del Norte debe completar por lo menos 50 horas de práctica de manejo supervisado.","p":"Correcto. Menor de 16, necesita 50 horas."},"ref":{"doc":"ND","page":3}},{"id":"nd-009","scope":"ND","cat":"licensing","sign":null,"c":1,"en":{"q":"In North Dakota, what is the youngest age to get a restricted license?","o":["14 years old","15 years old","16 years old","17 years old"],"h1":"It is one year after the permit age of 14.","h2":"In North Dakota the restricted license is available from age 15.","p":"Right. The restricted license starts at 15."},"es":{"q":"En Dakota del Norte, ¿cuál es la edad mínima para obtener una licencia restringida?","o":["14 años","15 años","16 años","17 años"],"h1":"Es un año después de la edad del permiso, que es 14.","h2":"En Dakota del Norte la licencia restringida se puede obtener desde los 15 años.","p":"Correcto. La licencia restringida empieza a los 15."},"ref":{"doc":"ND","page":6}},{"id":"nd-010","scope":"ND","cat":"licensing","sign":null,"c":2,"en":{"q":"In North Dakota, when may a 15-year-old with a restricted license not drive without a parent, guardian or adult 18 or older?","o":["From 6 p.m. to 6 a.m.","From midnight to 4 a.m.","From 9 p.m. to 5 a.m.","On weekends"],"h1":"The limit starts in the evening, earlier than midnight.","h2":"A 15-year-old with a North Dakota restricted license may not drive from 9 p.m., or sunset if that is later, until 5 a.m. without a parent, guardian or adult 18 or older, except straight to or from work, school activities or religious activities.","p":"Right. No driving alone from 9 p.m. to 5 a.m."},"es":{"q":"En Dakota del Norte, ¿cuándo no puede manejar un joven de 15 años con licencia restringida sin su padre, madre, tutor o un adulto de 18 años o más?","o":["De 6 p.m. a 6 a.m.","De medianoche a 4 a.m.","De 9 p.m. a 5 a.m.","Los fines de semana"],"h1":"El límite empieza en la noche, antes de la medianoche.","h2":"Un joven de 15 años con licencia restringida en Dakota del Norte no puede manejar desde las 9 p.m., o la puesta del sol si es más tarde, hasta las 5 a.m. sin su padre, madre, tutor o un adulto de 18 años o más, salvo para ir directo al trabajo, a actividades escolares o religiosas, o volver de ellos.","p":"Correcto. No maneja solo de 9 p.m. a 5 a.m."},"ref":{"doc":"ND","page":6}},{"id":"nd-011","scope":"ND","cat":"licensing","sign":null,"c":0,"en":{"q":"In North Dakota, whose car may a young driver with a restricted license drive?","o":["Only a car that belongs to a parent, guardian, grandparent, brother, sister, aunt or uncle","Any car with insurance","A friend's car","A rental car"],"h1":"The car must belong to the teen's close family.","h2":"A young North Dakota driver with a restricted license may drive only a car that belongs to a parent, guardian, grandparent, brother, sister, aunt or uncle.","p":"Right. Only a car owned by close family."},"es":{"q":"En Dakota del Norte, ¿el carro de quién puede manejar un joven con licencia restringida?","o":["Solo un carro de su padre, madre, tutor, abuelo, abuela, hermano, hermana, tía o tío","Cualquier carro con seguro","El carro de un amigo","Un carro alquilado"],"h1":"El carro debe ser de su familia cercana.","h2":"Un joven con licencia restringida en Dakota del Norte solo puede manejar un carro que sea de su padre, madre, tutor, abuelo, abuela, hermano, hermana, tía o tío.","p":"Correcto. Solo un carro de su familia cercana."},"ref":{"doc":"ND","page":6}},{"id":"nd-012","scope":"ND","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In North Dakota, may a driver under 18 use a cell phone while driving?","o":["No, drivers under 18 may not use any electronic communication device","Yes, for calls only","Yes, at red lights","Yes, if the call is short"],"h1":"Young drivers have a stricter rule than adults.","h2":"North Dakota law says drivers under 18 may not use any electronic communication device, including a cell phone, while driving.","p":"Right. Under 18, no phone while driving."},"es":{"q":"En Dakota del Norte, ¿puede un conductor menor de 18 usar el celular mientras maneja?","o":["No, los menores de 18 no pueden usar ningún aparato de comunicación electrónica","Sí, solo para llamadas","Sí, en los semáforos en rojo","Sí, si la llamada es corta"],"h1":"Los conductores jóvenes tienen una regla más estricta que los adultos.","h2":"La ley de Dakota del Norte dice que los conductores menores de 18 no pueden usar ningún aparato de comunicación electrónica, incluido el celular, mientras manejan.","p":"Correcto. Menor de 18, nada de teléfono al manejar."},"ref":{"doc":"ND","page":6}},{"id":"nd-013","scope":"ND","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In North Dakota, who is banned from texting while driving?","o":["Only drivers under 18","Only bus drivers","Only drivers with a permit","All drivers"],"h1":"The texting rule does not depend on age.","h2":"In North Dakota, text messaging while driving is banned for all drivers.","p":"Right. No one may text while driving."},"es":{"q":"En Dakota del Norte, ¿a quién se le prohíbe enviar mensajes de texto mientras maneja?","o":["Solo a los menores de 18","Solo a los choferes de autobús","Solo a quienes tienen permiso","A todos los conductores"],"h1":"La regla de los mensajes no depende de la edad.","h2":"En Dakota del Norte, enviar mensajes de texto mientras maneja está prohibido para todos los conductores.","p":"Correcto. Nadie puede enviar mensajes al manejar."},"ref":{"doc":"ND","page":30}},{"id":"nd-014","scope":"ND","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In North Dakota, what is the fine for texting while driving?","o":["$20","$100","$500","$1,000"],"h1":"It is a round number in the hundreds.","h2":"The fine for texting while driving in North Dakota is $100.","p":"Right. The fine is $100."},"es":{"q":"En Dakota del Norte, ¿cuál es la multa por enviar mensajes de texto mientras maneja?","o":["$20","$100","$500","$1,000"],"h1":"Es un número redondo de cientos.","h2":"La multa por enviar mensajes de texto mientras maneja en Dakota del Norte es de $100.","p":"Correcto. La multa es de $100."},"ref":{"doc":"ND","page":30}},{"id":"nd-015","scope":"ND","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In North Dakota, what is the legal alcohol limit for a driver under 21?","o":["0.08 percent","0.05 percent","0.02 percent","0.10 percent"],"h1":"It is much lower than the adult limit.","h2":"In North Dakota the alcohol limit for a driver under 21 is 0.02 percent.","p":"Right. Under 21, the limit is 0.02."},"es":{"q":"En Dakota del Norte, ¿cuál es el límite legal de alcohol para un conductor menor de 21?","o":["0.08 por ciento","0.05 por ciento","0.02 por ciento","0.10 por ciento"],"h1":"Es mucho más bajo que el límite para adultos.","h2":"En Dakota del Norte el límite de alcohol para un conductor menor de 21 es de 0.02 por ciento.","p":"Correcto. Menor de 21, el límite es 0.02."},"ref":{"doc":"ND","page":36}},{"id":"nd-016","scope":"ND","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In North Dakota, what is the legal alcohol limit for a driver 21 or older?","o":["0.08 percent","0.02 percent","0.10 percent","0.12 percent"],"h1":"It is the same limit used in most states.","h2":"In North Dakota the alcohol limit for a driver 21 or older is 0.08 percent.","p":"Right. For adults, the limit is 0.08."},"es":{"q":"En Dakota del Norte, ¿cuál es el límite legal de alcohol para un conductor de 21 años o más?","o":["0.08 por ciento","0.02 por ciento","0.10 por ciento","0.12 por ciento"],"h1":"Es el mismo límite que usan la mayoría de los estados.","h2":"En Dakota del Norte el límite de alcohol para un conductor de 21 años o más es de 0.08 por ciento.","p":"Correcto. Para adultos, el límite es 0.08."},"ref":{"doc":"ND","page":36}},{"id":"nd-017","scope":"ND","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In North Dakota, on a multi-lane highway, what must you do when you pass a stopped vehicle with flashing lights?","o":["Honk to warn them","Stop behind it","Keep the same lane and speed","Change lanes if it is safe, or slow down if you cannot"],"h1":"Give the people on the shoulder more room.","h2":"North Dakota's move over law says to change to a lane away from the stopped vehicle if it is safe, and to slow down if you cannot change lanes.","p":"Right. Move over, or slow down."},"es":{"q":"En Dakota del Norte, en una carretera de varios carriles, ¿qué debe hacer al pasar un vehículo detenido con luces intermitentes?","o":["Tocar la bocina para avisar","Detenerse detrás de él","Seguir en el mismo carril y a la misma velocidad","Cambiarse de carril si es seguro, o bajar la velocidad si no puede"],"h1":"Dé más espacio a las personas en el acotamiento.","h2":"La ley de Dakota del Norte para moverse de carril dice que debe cambiarse a un carril lejos del vehículo detenido si es seguro, y bajar la velocidad si no puede cambiarse.","p":"Correcto. Cámbiese de carril o baje la velocidad."},"ref":{"doc":"ND","page":32}},{"id":"nd-018","scope":"ND","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In North Dakota, on an interstate or multi-lane highway outside a city, which stopped vehicles does the move over rule cover?","o":["Only police cars","Any vehicle showing flashing hazard lights","Only ambulances and fire trucks","Only school buses"],"h1":"It is not only for emergency vehicles.","h2":"In North Dakota, the move over rule also covers any vehicle stopped on an interstate or multi-lane highway outside a city with its flashing hazard lights on.","p":"Right. Any vehicle with hazard lights is covered."},"es":{"q":"En Dakota del Norte, en una interestatal o carretera de varios carriles fuera de una ciudad, ¿qué vehículos detenidos cubre la regla para moverse de carril?","o":["Solo carros de policía","Cualquier vehículo con luces de emergencia intermitentes","Solo ambulancias y bomberos","Solo autobuses escolares"],"h1":"No es solo para vehículos de emergencia.","h2":"En Dakota del Norte, la regla para moverse de carril también cubre cualquier vehículo detenido en una interestatal o carretera de varios carriles fuera de una ciudad con sus luces de emergencia intermitentes encendidas.","p":"Correcto. Cualquier vehículo con luces de emergencia está cubierto."},"ref":{"doc":"ND","page":32}},{"id":"nd-019","scope":"ND","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In North Dakota, on a two-way road with no median, who must stop for a school bus with its stop arm out?","o":["Traffic in both directions","Only traffic behind the bus","Only trucks","No one, if the road is clear"],"h1":"On an undivided road, the children may cross toward either side.","h2":"In North Dakota, when a school bus stops with red lights flashing and the stop arm out on an undivided road, traffic in both directions must stop.","p":"Right. Both directions stop."},"es":{"q":"En Dakota del Norte, en una vía de doble sentido sin división, ¿quién debe detenerse ante un autobús escolar con el brazo de alto extendido?","o":["El tráfico en ambos sentidos","Solo el tráfico detrás del autobús","Solo los camiones","Nadie, si la vía está libre"],"h1":"En una vía sin división, los niños pueden cruzar hacia cualquier lado.","h2":"En Dakota del Norte, cuando un autobús escolar se detiene con luces rojas intermitentes y el brazo de alto extendido en una vía sin división, el tráfico en ambos sentidos debe detenerse.","p":"Correcto. Ambos sentidos se detienen."},"ref":{"doc":"ND","page":20}},{"id":"nd-020","scope":"ND","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In North Dakota, when may oncoming drivers keep going past a stopped school bus with its stop arm out?","o":["When they are in a hurry","When the bus is yellow","When a physical median or barrier divides the highway","When they honk first"],"h1":"Something solid must separate your side from the bus's side.","h2":"In North Dakota, oncoming drivers do not have to stop for a school bus only when the highway has separate roadways, divided by a median or barrier, and the bus is on the other roadway.","p":"Right. A physical median makes the difference."},"es":{"q":"En Dakota del Norte, ¿cuándo pueden seguir los conductores que vienen de frente ante un autobús escolar detenido con el brazo de alto extendido?","o":["Cuando tienen prisa","Cuando el autobús es amarillo","Cuando una división física o barrera separa la carretera","Cuando tocan la bocina primero"],"h1":"Algo sólido debe separar su lado del lado del autobús.","h2":"En Dakota del Norte, los conductores que vienen de frente no tienen que detenerse ante un autobús escolar solo cuando la carretera tiene calzadas separadas por una división o barrera y el autobús está en la otra calzada.","p":"Correcto. La división física hace la diferencia."},"ref":{"doc":"ND","page":null}},{"id":"ne-001","scope":"NE","cat":"licensing","sign":null,"c":2,"en":{"q":"In Nebraska, what is the youngest age to get a learner's permit (LPD)?","o":["13 years old","14 years old","15 years old","16 years old"],"h1":"It is one year before the provisional permit.","h2":"In Nebraska you can get a learner's permit (LPD) at 15 years old.","p":"Right. The LPD starts at 15."},"es":{"q":"En Nebraska, ¿cuál es la edad mínima para obtener el permiso de aprendiz (LPD)?","o":["13 años","14 años","15 años","16 años"],"h1":"Es un año antes del permiso provisional.","h2":"En Nebraska puede obtener un permiso de aprendiz (LPD) a los 15 años.","p":"Correcto. El LPD empieza a los 15."},"ref":{"doc":"NE","page":3}},{"id":"ne-002","scope":"NE","cat":"licensing","sign":null,"c":1,"en":{"q":"In Nebraska, what is the youngest age for a school learner's permit (LPE), used to practice for driving to school?","o":["13 years old","14 years old","15 years old","16 years old"],"h1":"It comes one year before the regular learner's permit.","h2":"In Nebraska a teen can get a school learner's permit (LPE) at 14, so they can practice for driving to school.","p":"Right. The school learner's permit starts at 14."},"es":{"q":"En Nebraska, ¿cuál es la edad mínima para el permiso escolar de aprendiz (LPE), que sirve para practicar para manejar a la escuela?","o":["13 años","14 años","15 años","16 años"],"h1":"Llega un año antes del permiso de aprendiz normal.","h2":"En Nebraska un adolescente puede obtener el permiso escolar de aprendiz (LPE) a los 14 años, para practicar para manejar a la escuela.","p":"Correcto. El permiso escolar de aprendiz empieza a los 14."},"ref":{"doc":"NE","page":2}},{"id":"ne-003","scope":"NE","cat":"licensing","sign":null,"c":3,"en":{"q":"In Nebraska, who must sit in the front passenger seat when a teen drives with a learner's permit (LPD)?","o":["Any passenger with a permit","A licensed driver 18 or older","Any adult, licensed or not","A licensed driver 21 or older"],"h1":"The helper must be an adult who can legally drink.","h2":"A Nebraska LPD holder must always drive with a licensed adult who is at least 21 in the front passenger seat.","p":"Right. A licensed adult 21 or older beside you."},"es":{"q":"En Nebraska, ¿quién debe ir en el asiento delantero del pasajero cuando un adolescente maneja con permiso de aprendiz (LPD)?","o":["Cualquier pasajero con permiso","Un conductor con licencia de 18 años o más","Cualquier adulto, con o sin licencia","Un conductor con licencia de 21 años o más"],"h1":"El acompañante debe ser un adulto que ya puede tomar alcohol legalmente.","h2":"Quien tiene un LPD en Nebraska siempre debe manejar con un adulto con licencia de por lo menos 21 años en el asiento delantero del pasajero.","p":"Correcto. Un adulto con licencia de 21 años o más a su lado."},"ref":{"doc":"NE","page":4}},{"id":"ne-004","scope":"NE","cat":"licensing","sign":null,"c":0,"en":{"q":"In Nebraska, what is the youngest age for a provisional operator's permit (POP), which lets a teen drive alone?","o":["16 years old","15 years old","17 years old","18 years old"],"h1":"It is the most common age for a first license.","h2":"In Nebraska you must be at least 16 to get a provisional operator's permit (POP).","p":"Right. The POP starts at 16."},"es":{"q":"En Nebraska, ¿cuál es la edad mínima para el permiso provisional de operador (POP), que permite manejar solo?","o":["16 años","15 años","17 años","18 años"],"h1":"Es la edad más común para la primera licencia.","h2":"En Nebraska usted debe tener por lo menos 16 años para obtener el permiso provisional de operador (POP).","p":"Correcto. El POP empieza a los 16."},"ref":{"doc":"NE","page":4}},{"id":"ne-005","scope":"NE","cat":"licensing","sign":null,"c":1,"en":{"q":"In Nebraska, how long must a teen hold a learner's permit before getting a provisional operator's permit (POP)?","o":["3 months","6 months","9 months","12 months"],"h1":"It is half a year.","h2":"A Nebraska teen must hold a learner's permit for at least 6 months before getting a provisional operator's permit.","p":"Right. Six months with the permit."},"es":{"q":"En Nebraska, ¿cuánto tiempo debe tener un adolescente el permiso de aprendiz antes del permiso provisional de operador (POP)?","o":["3 meses","6 meses","9 meses","12 meses"],"h1":"Es medio año.","h2":"Un adolescente en Nebraska debe tener el permiso de aprendiz por lo menos 6 meses antes de obtener el permiso provisional de operador.","p":"Correcto. Seis meses con el permiso."},"ref":{"doc":"NE","page":4}},{"id":"ne-006","scope":"NE","cat":"licensing","sign":null,"c":2,"en":{"q":"In Nebraska, if a teen does not take an approved driver safety course, how many hours of supervised driving must be logged for a POP?","o":["20 hours","30 hours","50 hours","100 hours"],"h1":"It is the same as a full work week plus ten.","h2":"A Nebraska teen who skips the approved driver safety course must log 50 hours of supervised driving to get a provisional operator's permit.","p":"Right. 50 logged hours."},"es":{"q":"En Nebraska, si un adolescente no toma un curso aprobado de seguridad vial, ¿cuántas horas de manejo supervisado debe registrar para el POP?","o":["20 horas","30 horas","50 horas","100 horas"],"h1":"Es lo mismo que una semana completa de trabajo más diez.","h2":"Un adolescente en Nebraska que no toma el curso aprobado de seguridad vial debe registrar 50 horas de manejo supervisado para obtener el permiso provisional de operador.","p":"Correcto. 50 horas registradas."},"ref":{"doc":"NE","page":4}},{"id":"ne-007","scope":"NE","cat":"licensing","sign":null,"c":3,"en":{"q":"In Nebraska, who must sign the 50-hour driving log for a provisional operator's permit?","o":["The teen driver","A teacher at school","A DMV examiner","A licensed driver at least 21 years old"],"h1":"It is the same kind of person who supervises practice.","h2":"The Nebraska 50-hour driving form must be signed by a parent, a guardian, or a licensed driver who is at least 21 years old.","p":"Right. A licensed driver 21 or older signs it."},"es":{"q":"En Nebraska, ¿quién debe firmar el registro de 50 horas de manejo para el permiso provisional de operador?","o":["El conductor adolescente","Un maestro de la escuela","Un examinador del DMV","Un conductor con licencia de por lo menos 21 años"],"h1":"Es el mismo tipo de persona que supervisa la práctica.","h2":"El formulario de 50 horas de manejo en Nebraska debe firmarlo uno de los padres, un tutor o un conductor con licencia de por lo menos 21 años.","p":"Correcto. Lo firma un conductor con licencia de 21 años o más."},"ref":{"doc":"NE","page":4}},{"id":"ne-008","scope":"NE","cat":"licensing","sign":null,"c":0,"en":{"q":"In Nebraska, during which hours may a POP holder not drive alone, except for work or school activities?","o":["Midnight to 6 a.m.","10 p.m. to 5 a.m.","11 p.m. to 6 a.m.","1 a.m. to 5 a.m."],"h1":"The limit starts exactly at midnight.","h2":"A Nebraska POP holder may not drive alone between midnight and 6 a.m., except to or from work or a school activity.","p":"Right. No solo driving from midnight to 6 a.m."},"es":{"q":"En Nebraska, ¿en qué horario no puede manejar solo quien tiene POP, salvo para el trabajo o actividades escolares?","o":["De medianoche a 6 a.m.","De 10 p.m. a 5 a.m.","De 11 p.m. a 6 a.m.","De 1 a.m. a 5 a.m."],"h1":"El límite empieza justo a la medianoche.","h2":"Quien tiene POP en Nebraska no puede manejar solo entre la medianoche y las 6 a.m., salvo para ir o volver del trabajo o de una actividad escolar.","p":"Correcto. No puede manejar solo de medianoche a 6 a.m."},"ref":{"doc":"NE","page":4}},{"id":"ne-009","scope":"NE","cat":"licensing","sign":null,"c":2,"en":{"q":"In Nebraska, a POP holder wants to drive at 1 a.m. to visit a friend. When is this allowed?","o":["Never","Only on weekends","When a licensed driver 21 or older is in the car","When the friend is under 19"],"h1":"An experienced adult in the car changes the rule.","h2":"A Nebraska POP holder may drive between midnight and 6 a.m. when a licensed driver who is 21 or older rides along.","p":"Right. With a licensed adult 21 or older."},"es":{"q":"En Nebraska, quien tiene POP quiere manejar a la 1 a.m. para visitar a un amigo. ¿Cuándo está permitido?","o":["Nunca","Solo los fines de semana","Cuando va en el carro un conductor con licencia de 21 años o más","Cuando el amigo es menor de 19 años"],"h1":"Un adulto con experiencia en el carro cambia la regla.","h2":"Quien tiene POP en Nebraska puede manejar entre la medianoche y las 6 a.m. cuando lo acompaña un conductor con licencia de 21 años o más.","p":"Correcto. Con un adulto con licencia de 21 años o más."},"ref":{"doc":"NE","page":4}},{"id":"ne-010","scope":"NE","cat":"licensing","sign":null,"c":1,"en":{"q":"In Nebraska, during the first 6 months with a POP, how many passengers under 19 who are not family may ride along?","o":["None","No more than one","No more than two","No more than three"],"h1":"The limit is very small.","h2":"During the first 6 months with a POP, a Nebraska teen may carry no more than one passenger under 19 who is not immediate family.","p":"Right. Only one non-family passenger under 19."},"es":{"q":"En Nebraska, durante los primeros 6 meses con POP, ¿cuántos pasajeros menores de 19 años que no son familiares pueden ir con usted?","o":["Ninguno","No más de uno","No más de dos","No más de tres"],"h1":"El límite es muy pequeño.","h2":"Durante los primeros 6 meses con POP, un adolescente en Nebraska puede llevar no más de un pasajero menor de 19 años que no sea familiar directo.","p":"Correcto. Solo un pasajero menor de 19 que no es familiar."},"ref":{"doc":"NE","page":4}},{"id":"ne-011","scope":"NE","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Nebraska, may a POP holder talk or text on a wireless phone while driving?","o":["Yes, if hands-free","Yes, for calls only","Yes, at stop signs","No, interactive wireless devices are not allowed"],"h1":"The POP has a stricter rule than for adults.","h2":"A Nebraska POP holder may not use an interactive wireless device, such as a phone, while driving.","p":"Right. No phones for POP drivers."},"es":{"q":"En Nebraska, ¿puede quien tiene POP hablar o escribir mensajes en un teléfono inalámbrico mientras maneja?","o":["Sí, con manos libres","Sí, solo para llamadas","Sí, en las señales de alto","No, no se permiten aparatos inalámbricos interactivos"],"h1":"El POP tiene una regla más estricta que la de los adultos.","h2":"Quien tiene POP en Nebraska no puede usar un aparato inalámbrico interactivo, como un teléfono, mientras maneja.","p":"Correcto. Nada de teléfonos para conductores con POP."},"ref":{"doc":"NE","page":1}},{"id":"ne-012","scope":"NE","cat":"licensing","sign":null,"c":2,"en":{"q":"In Nebraska, when can a POP holder move up to a full operator's license?","o":["At 16, after 3 months","At 16 and a half, after 6 months","At 17, after holding the POP for 12 months","At 18 only"],"h1":"It takes a full year on the POP.","h2":"A Nebraska POP holder can get a full operator's license at 17, after holding the POP for 12 months with a good record.","p":"Right. Age 17 and 12 months on the POP."},"es":{"q":"En Nebraska, ¿cuándo puede quien tiene POP pasar a la licencia de operador completa?","o":["A los 16, después de 3 meses","A los 16 y medio, después de 6 meses","A los 17, después de tener el POP 12 meses","Solo a los 18"],"h1":"Se necesita un año completo con el POP.","h2":"Quien tiene POP en Nebraska puede obtener la licencia de operador completa a los 17 años, después de tener el POP 12 meses con buen historial.","p":"Correcto. A los 17 y 12 meses con el POP."},"ref":{"doc":"NE","page":5}},{"id":"ne-013","scope":"NE","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Nebraska, what blood alcohol level is illegal for a driver under 21?","o":["0.02 or more","0.08 or more","0.05 or more","0.10 or more"],"h1":"It is much lower than the adult limit.","h2":"In Nebraska it is against the law for a driver under 21 to drive with a blood alcohol level of 0.02 or more.","p":"Right. Under 21, the limit is 0.02."},"es":{"q":"En Nebraska, ¿qué nivel de alcohol en la sangre es ilegal para un conductor menor de 21 años?","o":["0.02 o más","0.08 o más","0.05 o más","0.10 o más"],"h1":"Es mucho más bajo que el límite para adultos.","h2":"En Nebraska es ilegal que un conductor menor de 21 años maneje con un nivel de alcohol en la sangre de 0.02 o más.","p":"Correcto. Para menores de 21, el límite es 0.02."},"ref":{"doc":"NE","page":24}},{"id":"ne-014","scope":"NE","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Nebraska, may a driver read or send a text on a handheld phone while the car is moving?","o":["Yes, on rural roads","No, it is against the law","Yes, below 30 mph","Yes, at night"],"h1":"Texting takes your eyes off the road.","h2":"No. In Nebraska it is against the law to read, type, or send a text on a handheld phone while driving.","p":"Right. No texting while you drive."},"es":{"q":"En Nebraska, ¿puede un conductor leer o enviar un mensaje de texto en un teléfono en la mano mientras el carro está en movimiento?","o":["Sí, en caminos rurales","No, es ilegal","Sí, a menos de 30 mph","Sí, de noche"],"h1":"Escribir mensajes le quita la vista del camino.","h2":"No. En Nebraska es ilegal leer, escribir o enviar un mensaje de texto en un teléfono en la mano mientras maneja.","p":"Correcto. Nada de mensajes mientras maneja."},"ref":{"doc":"NE","page":65}},{"id":"ne-015","scope":"NE","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Nebraska, on an interstate, you come up to a stopped car on the shoulder with people near it. What must you do?","o":["Nothing; the law covers only police cars","Stop next to it","Honk to warn the people","Move one lane over, or slow down if you cannot"],"h1":"Give the people on the shoulder more room.","h2":"On a Nebraska interstate, you must move one lane away from a stopped vehicle with people in or near it, or slow down if you cannot move over.","p":"Right. Move over, or slow down."},"es":{"q":"En Nebraska, en una interestatal, usted se acerca a un carro detenido en el acotamiento con personas cerca. ¿Qué debe hacer?","o":["Nada; la ley solo aplica a patrullas","Detenerse junto a él","Tocar la bocina para avisar","Pasarse un carril, o bajar la velocidad si no puede"],"h1":"Deles más espacio a las personas en el acotamiento.","h2":"En una interestatal de Nebraska, usted debe pasarse a un carril más lejos de un vehículo detenido con personas dentro o cerca, o bajar la velocidad si no puede cambiarse.","p":"Correcto. Cambiar de carril, o bajar la velocidad."},"ref":{"doc":"NE","page":null}},{"id":"ne-016","scope":"NE","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Nebraska, on a road divided by a median, a school bus stops with its red lights flashing and stop arm out. Who must stop?","o":["Every vehicle, from both directions","Only traffic coming toward the bus","Only traffic going the same direction as the bus","No one, if no child is crossing"],"h1":"The median separates the two sides of the road.","h2":"On a Nebraska road divided by a median, only traffic going the same direction as the school bus must stop.","p":"Right. Only the same direction stops."},"es":{"q":"En Nebraska, en un camino dividido por un camellón, un autobús escolar se detiene con las luces rojas encendidas y el brazo de alto extendido. ¿Quién debe detenerse?","o":["Todos los vehículos, de los dos sentidos","Solo el tráfico que viene hacia el autobús","Solo el tráfico que va en el mismo sentido que el autobús","Nadie, si ningún niño está cruzando"],"h1":"El camellón separa los dos lados del camino.","h2":"En un camino de Nebraska dividido por un camellón, solo el tráfico que va en el mismo sentido que el autobús escolar debe detenerse.","p":"Correcto. Solo se detiene el mismo sentido."},"ref":{"doc":"NE","page":70}},{"id":"ne-017","scope":"NE","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Nebraska, what is the usual posted speed limit on most rural interstates?","o":["75 mph","65 mph","70 mph","80 mph"],"h1":"It is higher than in many eastern states.","h2":"The speed limit on most rural interstates in Nebraska is 75 mph; city stretches are lower.","p":"Right. 75 mph on most rural interstates."},"es":{"q":"En Nebraska, ¿cuál es el límite de velocidad usual en la mayoría de las interestatales rurales?","o":["75 mph","65 mph","70 mph","80 mph"],"h1":"Es más alto que en muchos estados del este.","h2":"El límite de velocidad en la mayoría de las interestatales rurales de Nebraska es de 75 millas por hora; los tramos en la ciudad son más bajos.","p":"Correcto. 75 mph en la mayoría de las interestatales rurales."},"ref":{"doc":"NE","page":52}},{"id":"ne-018","scope":"NE","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Nebraska, can police stop an adult driver only for not wearing a seat belt?","o":["Yes, it is a primary offense","Yes, but only at night","Yes, but only on interstates","No, it is a secondary law"],"h1":"The ticket comes only with another violation.","h2":"Nebraska's adult seat belt law is secondary, so a driver gets a seat belt ticket only when stopped for another violation. You should still always buckle up.","p":"Right. For adults it is a secondary law, but buckle up anyway."},"es":{"q":"En Nebraska, ¿puede la policía detener a un conductor adulto solo por no usar el cinturón de seguridad?","o":["Sí, es una infracción primaria","Sí, pero solo de noche","Sí, pero solo en interestatales","No, es una ley secundaria"],"h1":"La multa llega solo junto con otra infracción.","h2":"La ley de cinturón de seguridad para adultos en Nebraska es secundaria, así que el conductor recibe esa multa solo cuando lo detienen por otra infracción. Aun así, abróchese siempre.","p":"Correcto. Para adultos es una ley secundaria, pero abróchese de todos modos."},"ref":{"doc":"NE","page":26}},{"id":"ne-019","scope":"NE","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Nebraska, on a road divided by a median, you meet a stopped school bus on the other side. What must you do?","o":["You do not have to stop, but watch for children","Stop until the bus moves","Stop only if children are near the bus","Pull onto the shoulder"],"h1":"The median separates you from the bus.","h2":"On a Nebraska road divided by a median, traffic coming from the opposite direction does not have to stop for a stopped school bus, but should watch for children.","p":"Right. Oncoming traffic on a divided highway may pass with care."},"es":{"q":"En Nebraska, en un camino dividido por un camellón, usted se encuentra con un autobús escolar detenido del otro lado. ¿Qué debe hacer?","o":["No tiene que detenerse, pero esté atento a los niños","Detenerse hasta que el autobús avance","Detenerse solo si hay niños cerca del autobús","Orillarse al acotamiento"],"h1":"El camellón lo separa del autobús.","h2":"En un camino de Nebraska dividido por un camellón, el tráfico que viene en sentido contrario no tiene que detenerse por un autobús escolar detenido, pero debe estar atento a los niños.","p":"Correcto. En una carretera dividida, el tráfico contrario puede pasar con cuidado."},"ref":{"doc":"NE","page":70}},{"id":"ne-020","scope":"NE","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Nebraska, who must wear a seat belt by law?","o":["Only the driver","The driver, every front-seat passenger, and all children under 18","Only passengers under 16","Only people on interstates"],"h1":"The law covers the front seat and all children.","h2":"Nebraska law requires the driver and each front-seat passenger to buckle up, and every child under 18 must ride in a seat belt or a child safety seat.","p":"Right. The front seat, plus every child under 18."},"es":{"q":"En Nebraska, ¿quién debe usar el cinturón de seguridad por ley?","o":["Solo el conductor","El conductor, cada pasajero del asiento delantero y todos los niños menores de 18 años","Solo los pasajeros menores de 16 años","Solo quienes van en interestatales"],"h1":"La ley cubre el asiento delantero y a todos los niños.","h2":"La ley de Nebraska exige que el conductor y cada pasajero del asiento delantero usen el cinturón, y todo niño menor de 18 años debe ir con cinturón o en un asiento de seguridad para niños.","p":"Correcto. El asiento delantero, y todos los niños menores de 18."},"ref":{"doc":"NE","page":26}},{"id":"nh-001","scope":"NH","cat":"licensing","sign":null,"c":2,"en":{"q":"In New Hampshire, what score do you need to pass a knowledge test?","o":["60 percent","70 percent","80 percent","90 percent"],"h1":"It is the same as getting 4 out of 5 right.","h2":"Every New Hampshire knowledge test requires a passing grade of 80 percent.","p":"Right. You need 80 percent."},"es":{"q":"En New Hampshire, ¿qué puntaje necesita para aprobar un examen de conocimientos?","o":["60 por ciento","70 por ciento","80 por ciento","90 por ciento"],"h1":"Es lo mismo que acertar 4 de cada 5.","h2":"Todos los exámenes de conocimientos en New Hampshire exigen una nota mínima del 80 por ciento.","p":"Correcto. Necesita el 80 por ciento."},"ref":{"doc":"NH","page":2}},{"id":"nh-002","scope":"NH","cat":"licensing","sign":null,"c":1,"en":{"q":"In New Hampshire, what is the youngest age to practice driving on public roads with a licensed adult?","o":["15","15 and a half","16","14 and a half"],"h1":"It is six months before the age of 16.","h2":"In New Hampshire a teen may start practice driving at 15 and a half, with a licensed adult in the front seat.","p":"Correct. Practice starts at 15 and a half."},"es":{"q":"En New Hampshire, ¿cuál es la edad mínima para practicar manejo en las calles con un adulto con licencia?","o":["15 años","15 años y medio","16 años","14 años y medio"],"h1":"Es seis meses antes de cumplir 16 años.","h2":"En New Hampshire un joven puede empezar a practicar a los 15 años y medio, con un adulto con licencia en el asiento delantero.","p":"Correcto. La práctica empieza a los 15 años y medio."},"ref":{"doc":"NH","page":2}},{"id":"nh-004","scope":"NH","cat":"licensing","sign":null,"c":3,"en":{"q":"In New Hampshire, how old must the licensed adult be who supervises a teen's practice driving?","o":["At least 18","At least 19","At least 21","At least 25"],"h1":"It is older than the drinking age.","h2":"In New Hampshire the adult who supervises practice driving must be licensed and at least 25 years old.","p":"Correct. The adult must be 25 or older."},"es":{"q":"En New Hampshire, ¿qué edad debe tener el adulto con licencia que supervisa la práctica de un joven?","o":["Por lo menos 18","Por lo menos 19","Por lo menos 21","Por lo menos 25"],"h1":"Es mayor que la edad legal para tomar alcohol.","h2":"En New Hampshire el adulto que supervisa la práctica debe tener licencia y por lo menos 25 años.","p":"Correcto. El adulto debe tener 25 años o más."},"ref":{"doc":"NH","page":1}},{"id":"nh-005","scope":"NH","cat":"licensing","sign":null,"c":2,"en":{"q":"In New Hampshire, who must take driver education to get a license?","o":["Everyone, at any age","Only drivers over 65","Applicants under 18","Only drivers from another country"],"h1":"It depends on the applicant's age.","h2":"In New Hampshire driver education is required for anyone under 18 who applies for a driver license.","p":"Right. Under 18 needs driver education."},"es":{"q":"En New Hampshire, ¿quién debe tomar un curso de educación vial para obtener la licencia?","o":["Todos, a cualquier edad","Solo los mayores de 65","Los solicitantes menores de 18 años","Solo los conductores de otro país"],"h1":"Depende de la edad de la persona.","h2":"En New Hampshire el curso de educación vial es obligatorio para toda persona menor de 18 años que solicita una licencia.","p":"Correcto. Menor de 18 necesita educación vial."},"ref":{"doc":"NH","page":1}},{"id":"nh-006","scope":"NH","cat":"licensing","sign":null,"c":1,"en":{"q":"In New Hampshire, how many hours of supervised driving must a student log, on top of driver education?","o":["20 hours","40 hours","50 hours","60 hours"],"h1":"It is less than 50.","h2":"A New Hampshire student must log 40 hours of supervised driving with a parent, guardian or other responsible adult before applying for a license.","p":"Correct. Forty supervised hours."},"es":{"q":"En New Hampshire, ¿cuántas horas de manejo supervisado debe registrar un estudiante, además del curso de educación vial?","o":["20 horas","40 horas","50 horas","60 horas"],"h1":"Son menos de 50.","h2":"Un estudiante en New Hampshire debe registrar 40 horas de manejo supervisado con su padre, madre, tutor u otro adulto responsable antes de solicitar la licencia.","p":"Correcto. Cuarenta horas supervisadas."},"ref":{"doc":"NH","page":1}},{"id":"nh-007","scope":"NH","cat":"licensing","sign":null,"c":0,"en":{"q":"In New Hampshire, how many of the 40 supervised hours must be at night?","o":["At least 10","At least 2","At least 20","None"],"h1":"It is one quarter of the total.","h2":"At least 10 of the 40 supervised hours in New Hampshire must be driven at night.","p":"Right. Ten hours at night."},"es":{"q":"En New Hampshire, ¿cuántas de las 40 horas supervisadas deben ser de noche?","o":["Por lo menos 10","Por lo menos 2","Por lo menos 20","Ninguna"],"h1":"Es la cuarta parte del total.","h2":"En New Hampshire, por lo menos 10 de las 40 horas supervisadas deben ser de noche.","p":"Correcto. Diez horas de noche."},"ref":{"doc":"NH","page":1}},{"id":"nh-009","scope":"NH","cat":"licensing","sign":null,"c":2,"en":{"q":"In New Hampshire, when does a Youth Operator License expire?","o":["On the 18th birthday","After one year","On the 21st birthday","After six months"],"h1":"It ends when the driver becomes a full adult in the eyes of most laws.","h2":"A New Hampshire Youth Operator License expires on the holder's 21st birthday.","p":"Right. It expires at 21."},"es":{"q":"En New Hampshire, ¿cuándo vence la licencia de conductor joven (Youth Operator License)?","o":["Al cumplir 18 años","Después de un año","Al cumplir 21 años","Después de seis meses"],"h1":"Termina cuando el conductor llega a la edad adulta para la mayoría de las leyes.","h2":"La licencia de conductor joven de New Hampshire vence el día que su titular cumple 21 años.","p":"Correcto. Vence a los 21."},"ref":{"doc":"NH","page":4}},{"id":"nh-010","scope":"NH","cat":"licensing","sign":null,"c":1,"en":{"q":"In New Hampshire, during which hours may a Youth Operator License holder not drive?","o":["Midnight to 5 a.m.","1 a.m. to 4 a.m.","11 p.m. to 5 a.m.","10 p.m. to 6 a.m."],"h1":"The window is only three hours long.","h2":"A New Hampshire Youth Operator License holder may not drive between 1 a.m. and 4 a.m.","p":"Correct. No driving from 1 to 4 a.m."},"es":{"q":"En New Hampshire, ¿en qué horario no puede manejar el titular de una licencia de conductor joven?","o":["De medianoche a 5 a.m.","De 1 a.m. a 4 a.m.","De 11 p.m. a 5 a.m.","De 10 p.m. a 6 a.m."],"h1":"El período dura solo tres horas.","h2":"El titular de una licencia de conductor joven en New Hampshire no puede manejar entre la 1 a.m. y las 4 a.m.","p":"Correcto. No se maneja de 1 a 4 a.m."},"ref":{"doc":"NH","page":4}},{"id":"nh-011","scope":"NH","cat":"licensing","sign":null,"c":0,"en":{"q":"In New Hampshire, during the first six months of a Youth Operator License, how many non-family passengers under 25 may the driver carry?","o":["One","None","Two","Three"],"h1":"The limit is more than zero but very small.","h2":"During the first six months, a New Hampshire youth operator may carry no more than one passenger under 25 who is not a family member.","p":"Right. Only one."},"es":{"q":"En New Hampshire, durante los primeros seis meses de la licencia de conductor joven, ¿cuántos pasajeros menores de 25 años que no son familiares puede llevar el conductor?","o":["Uno","Ninguno","Dos","Tres"],"h1":"El límite es mayor que cero, pero muy pequeño.","h2":"Durante los primeros seis meses, un conductor joven en New Hampshire no puede llevar más de un pasajero menor de 25 años que no sea de su familia.","p":"Correcto. Solo uno."},"ref":{"doc":"NH","page":4}},{"id":"nh-012","scope":"NH","cat":"licensing","sign":null,"c":3,"en":{"q":"In New Hampshire, when may a new youth operator carry more than one non-family passenger under 25 in the first six months?","o":["On weekends","On roads with a low speed limit","During daylight","When a licensed adult at least 25 years old is in the car"],"h1":"An experienced adult has to be with them.","h2":"In New Hampshire the one-passenger limit does not apply when a licensed responsible adult at least 25 years old rides along.","p":"Correct. A licensed adult 25 or older lifts the limit."},"es":{"q":"En New Hampshire, ¿cuándo puede un conductor joven nuevo llevar más de un pasajero menor de 25 años que no sea familiar en los primeros seis meses?","o":["Los fines de semana","En calles con límite de velocidad bajo","Durante el día","Cuando lo acompaña un adulto con licencia de por lo menos 25 años"],"h1":"Debe ir con un adulto con experiencia.","h2":"En New Hampshire el límite de un pasajero no se aplica cuando lo acompaña un adulto responsable con licencia de por lo menos 25 años.","p":"Correcto. Un adulto con licencia de 25 años o más quita el límite."},"ref":{"doc":"NH","page":4}},{"id":"nh-013","scope":"NH","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In New Hampshire, how many people may ride with a youth operator?","o":["Any number","No more than four","No more than there are seat belts","Only one"],"h1":"Every person needs a place to buckle up.","h2":"A New Hampshire youth operator may not carry more people than the vehicle has seat belts.","p":"Right. One seat belt for each person."},"es":{"q":"En New Hampshire, ¿cuántas personas pueden ir con un conductor joven?","o":["Cualquier número","No más de cuatro","No más que el número de cinturones de seguridad","Solo una"],"h1":"Cada persona necesita un lugar donde abrocharse.","h2":"Un conductor joven en New Hampshire no puede llevar más personas que el número de cinturones de seguridad del vehículo.","p":"Correcto. Un cinturón para cada persona."},"ref":{"doc":"NH","page":4}},{"id":"nh-014","scope":"NH","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In New Hampshire, may a driver under 18 talk on a phone using a hands-free device?","o":["Yes, any time","No, only to report an emergency","Yes, but only at a red light","Yes, if the call is short"],"h1":"Younger drivers have a stricter rule than adults.","h2":"In New Hampshire a driver under 18 may not use a phone or other mobile device at all while driving, even hands-free, except to report an emergency.","p":"Correct. Under 18, no phone except emergencies."},"es":{"q":"En New Hampshire, ¿puede un conductor menor de 18 años hablar por teléfono con un dispositivo de manos libres?","o":["Sí, en cualquier momento","No, solo para reportar una emergencia","Sí, pero solo en un semáforo en rojo","Sí, si la llamada es corta"],"h1":"Los conductores más jóvenes tienen una regla más estricta que los adultos.","h2":"En New Hampshire un conductor menor de 18 años no puede usar un teléfono ni otro dispositivo móvil mientras maneja, ni siquiera con manos libres, excepto para reportar una emergencia.","p":"Correcto. Menor de 18, nada de teléfono salvo emergencias."},"ref":{"doc":"NH","page":4}},{"id":"nh-015","scope":"NH","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In New Hampshire, how may an adult driver make a phone call while driving?","o":["With a Bluetooth or other hands-free device","Holding the phone to the ear","Holding the phone while stopped in traffic","Typing the number on the screen in the hand"],"h1":"The law bans hand-held use, even when stopped in traffic.","h2":"New Hampshire bans hand-held phone use while driving, even when stopped in traffic, but an adult may use a Bluetooth or other hands-free device.","p":"Right. Hands-free only."},"es":{"q":"En New Hampshire, ¿cómo puede un conductor adulto hacer una llamada mientras maneja?","o":["Con un dispositivo Bluetooth u otro de manos libres","Sosteniendo el teléfono junto al oído","Sosteniendo el teléfono cuando está detenido en el tráfico","Marcando el número en la pantalla con el teléfono en la mano"],"h1":"La ley prohíbe usar el teléfono en la mano, aun detenido en el tráfico.","h2":"New Hampshire prohíbe usar el teléfono en la mano mientras se maneja, aun detenido en el tráfico, pero un adulto puede usar un dispositivo Bluetooth u otro de manos libres.","p":"Correcto. Solo manos libres."},"ref":{"doc":"NH","page":7}},{"id":"nh-017","scope":"NH","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In New Hampshire, which drivers must wear a seat belt by law?","o":["Only drivers on the highway","Only drivers over 65","Drivers under 18","Only taxi drivers"],"h1":"The rule is about young drivers.","h2":"New Hampshire law says a person under 18 may not drive unless wearing a properly fastened seat belt.","p":"Right. Drivers under 18 must buckle up."},"es":{"q":"En New Hampshire, ¿qué conductores deben usar cinturón de seguridad por ley?","o":["Solo los que manejan en la autopista","Solo los mayores de 65","Los conductores menores de 18 años","Solo los taxistas"],"h1":"La regla se refiere a los conductores jóvenes.","h2":"La ley de New Hampshire dice que una persona menor de 18 años no puede manejar sin el cinturón de seguridad bien abrochado.","p":"Correcto. Los menores de 18 deben abrocharse."},"ref":{"doc":"NH","page":11}},{"id":"nh-018","scope":"NH","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In New Hampshire, which passengers must the driver make sure are wearing a seat belt?","o":["Only the front-seat passenger","Every passenger under 18","Only passengers over 65","No one but the driver"],"h1":"The driver is responsible for young passengers.","h2":"In New Hampshire a driver may not carry a passenger under 18 who is not wearing a properly fastened seat belt.","p":"Correct. Every passenger under 18."},"es":{"q":"En New Hampshire, ¿qué pasajeros debe asegurarse el conductor de que usen cinturón de seguridad?","o":["Solo el pasajero del asiento delantero","Todo pasajero menor de 18 años","Solo los pasajeros mayores de 65","Nadie más que el conductor"],"h1":"El conductor es responsable de los pasajeros jóvenes.","h2":"En New Hampshire un conductor no puede llevar a un pasajero menor de 18 años que no tenga el cinturón de seguridad bien abrochado.","p":"Correcto. Todo pasajero menor de 18."},"ref":{"doc":"NH","page":11}},{"id":"nh-019","scope":"NH","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In New Hampshire, at what blood alcohol level is a driver under 21 legally intoxicated?","o":["0.02 or more","0.05 or more","0.08 or more","0.10 or more"],"h1":"It is much lower than the adult limit of 0.08.","h2":"In New Hampshire a driver under 21 is legally intoxicated at a blood alcohol level of 0.02 or more.","p":"Right. The limit under 21 is 0.02."},"es":{"q":"En New Hampshire, ¿con qué nivel de alcohol en la sangre se considera legalmente intoxicado a un conductor menor de 21 años?","o":["0.02 o más","0.05 o más","0.08 o más","0.10 o más"],"h1":"Es mucho más bajo que el límite para adultos, que es 0.08.","h2":"En New Hampshire un conductor menor de 21 años está legalmente intoxicado con un nivel de alcohol en la sangre de 0.02 o más.","p":"Correcto. El límite para menores de 21 es 0.02."},"ref":{"doc":"NH","page":6}},{"id":"nh-020","scope":"NH","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In New Hampshire, when does the Move Over law ask you to slow down and give extra space?","o":["Only for police cars with sirens","Only on interstate highways","Only at night","For a stopped vehicle showing flashing blue, red or amber lights, such as police, fire, tow or road crews"],"h1":"Think of the flashing lights on emergency and work vehicles.","h2":"New Hampshire's Move Over law asks drivers to slow down and move over, when safe, for a stopped vehicle showing flashing blue, red or amber lights, such as police, fire, tow or road crews.","p":"Correct. Stopped vehicles with flashing blue, red or amber lights."},"es":{"q":"En New Hampshire, ¿cuándo le pide la ley Move Over que reduzca la velocidad y deje más espacio?","o":["Solo con carros de policía con sirena","Solo en las autopistas interestatales","Solo de noche","Con un vehículo detenido con luces intermitentes azules, rojas o ámbar, como policía, bomberos, grúas o equipos de carretera"],"h1":"Piense en las luces intermitentes de los vehículos de emergencia y de trabajo.","h2":"La ley Move Over de New Hampshire pide a los conductores reducir la velocidad y cambiarse de carril, cuando sea seguro, ante un vehículo detenido con luces intermitentes azules, rojas o ámbar, como policía, bomberos, grúas o equipos de carretera.","p":"Correcto. Vehículos detenidos con luces intermitentes azules, rojas o ámbar."},"ref":{"doc":"NH","page":40}},{"id":"nj-001","scope":"NJ","cat":"licensing","sign":null,"c":3,"en":{"q":"In New Jersey, how many questions are on the knowledge test?","o":["20 questions","25 questions","35 questions","50 questions"],"h1":"It is half of one hundred.","h2":"The New Jersey knowledge test has 50 multiple-choice questions.","p":"Right. The New Jersey test has 50 questions."},"es":{"q":"En New Jersey, ¿cuántas preguntas tiene el examen de conocimientos?","o":["20 preguntas","25 preguntas","35 preguntas","50 preguntas"],"h1":"Es la mitad de cien.","h2":"El examen de conocimientos de New Jersey tiene 50 preguntas de opción múltiple.","p":"Correcto. El examen de New Jersey tiene 50 preguntas."},"ref":{"doc":"NJ","page":30}},{"id":"nj-002","scope":"NJ","cat":"licensing","sign":null,"c":1,"en":{"q":"In New Jersey, how many knowledge test questions must you answer correctly to pass?","o":["30","40","35","45"],"h1":"You need 80 percent of the 50 questions.","h2":"You must answer at least 40 of the 50 New Jersey test questions correctly, which is 80 percent.","p":"Right. You need 40 correct answers."},"es":{"q":"En New Jersey, ¿cuántas preguntas del examen de conocimientos debe contestar bien para aprobar?","o":["30","40","35","45"],"h1":"Necesita el 80 por ciento de las 50 preguntas.","h2":"Usted debe contestar bien por lo menos 40 de las 50 preguntas del examen de New Jersey, que es el 80 por ciento.","p":"Correcto. Necesita 40 respuestas correctas."},"ref":{"doc":"NJ","page":31}},{"id":"nj-003","scope":"NJ","cat":"licensing","sign":null,"c":2,"en":{"q":"In New Jersey, if you fail the knowledge test, how long must you wait to take it again?","o":["The same day","One day","7 days","30 days"],"h1":"It is one week.","h2":"In New Jersey you must wait 7 days before you can retake a failed knowledge test.","p":"Right. You wait seven days to try again."},"es":{"q":"En New Jersey, si no aprueba el examen de conocimientos, ¿cuánto debe esperar para presentarlo otra vez?","o":["El mismo día","Un día","7 días","30 días"],"h1":"Es una semana.","h2":"En New Jersey usted debe esperar 7 días antes de volver a presentar un examen de conocimientos que no aprobó.","p":"Correcto. Se esperan siete días para intentarlo de nuevo."},"ref":{"doc":"NJ","page":null}},{"id":"nj-004","scope":"NJ","cat":"licensing","sign":null,"c":0,"en":{"q":"In New Jersey, what lets a 16-year-old get a special learner's permit?","o":["Being enrolled in a behind-the-wheel driver training course","Having a parent with a license","Passing a road test first","Owning a car"],"h1":"It is connected to driving lessons.","h2":"A New Jersey 16-year-old can get a special learner's permit by enrolling in a behind-the-wheel driver training course at a high school or a licensed driving school.","p":"Right. Driver training opens the permit at 16."},"es":{"q":"En New Jersey, ¿qué le permite a un joven de 16 años obtener un permiso especial de aprendiz?","o":["Estar inscrito en un curso de manejo práctico al volante","Tener un padre con licencia","Aprobar primero un examen de manejo","Ser dueño de un carro"],"h1":"Tiene que ver con clases de manejo.","h2":"Un joven de 16 años en New Jersey puede obtener un permiso especial de aprendiz si se inscribe en un curso de manejo práctico al volante en una escuela secundaria o en una escuela de manejo con licencia.","p":"Correcto. El curso de manejo abre el permiso a los 16."},"ref":{"doc":"NJ","page":19}},{"id":"nj-005","scope":"NJ","cat":"licensing","sign":null,"c":1,"en":{"q":"In New Jersey, at what age can you get an examination permit without a driver training course?","o":["16","17","18","21"],"h1":"It is one year after the age for the special learner's permit.","h2":"In New Jersey you can get an examination permit at 17 without taking a driver training course.","p":"Right. At 17 no driver training course is needed."},"es":{"q":"En New Jersey, ¿a qué edad puede obtener un permiso de examen sin un curso de manejo?","o":["16","17","18","21"],"h1":"Es un año después de la edad del permiso especial de aprendiz.","h2":"En New Jersey usted puede obtener un permiso de examen a los 17 años sin tomar un curso de manejo.","p":"Correcto. A los 17 no se necesita curso de manejo."},"ref":{"doc":"NJ","page":20}},{"id":"nj-006","scope":"NJ","cat":"licensing","sign":null,"c":3,"en":{"q":"In New Jersey, how much driving experience must the adult supervising a permit holder have?","o":["At least 1 year","At least 6 months","At least 10 years","At least 3 years"],"h1":"It is more than two years but less than five.","h2":"The supervising driver in New Jersey must be at least 21, hold a valid New Jersey license, and have at least three years of driving experience.","p":"Right. The supervisor needs three years of experience."},"es":{"q":"En New Jersey, ¿cuánta experiencia de manejo debe tener el adulto que supervisa a un conductor con permiso?","o":["Por lo menos 1 año","Por lo menos 6 meses","Por lo menos 10 años","Por lo menos 3 años"],"h1":"Es más de dos años pero menos de cinco.","h2":"El conductor supervisor en New Jersey debe tener por lo menos 21 años, una licencia válida de New Jersey y por lo menos tres años de experiencia manejando.","p":"Correcto. El supervisor necesita tres años de experiencia."},"ref":{"doc":"NJ","page":18}},{"id":"nj-007","scope":"NJ","cat":"licensing","sign":null,"c":2,"en":{"q":"In New Jersey, where must the supervising driver sit when a permit holder drives?","o":["In the back seat","Anywhere in the car","In the front seat","In a separate car following behind"],"h1":"The supervisor must be close enough to help right away.","h2":"In New Jersey the adult supervising driver must sit in the front seat next to the permit holder.","p":"Right. The supervisor sits in the front seat."},"es":{"q":"En New Jersey, ¿dónde debe sentarse el conductor supervisor cuando maneja alguien con permiso?","o":["En el asiento de atrás","En cualquier lugar del carro","En el asiento de adelante","En otro carro que va detrás"],"h1":"El supervisor debe estar lo bastante cerca para ayudar de inmediato.","h2":"En New Jersey el adulto supervisor debe sentarse en el asiento de adelante, al lado del conductor con permiso.","p":"Correcto. El supervisor va en el asiento de adelante."},"ref":{"doc":"NJ","page":18}},{"id":"nj-008","scope":"NJ","cat":"licensing","sign":null,"c":0,"en":{"q":"In New Jersey, how long must a permit holder under 21 drive only with a supervising adult before the road test?","o":["At least 6 months","At least 1 month","At least 2 years","No set time"],"h1":"It is half a year.","h2":"In New Jersey a permit holder under 21 must drive with a supervising adult for at least six months before passing the road test.","p":"Right. Six months of supervised driving come first."},"es":{"q":"En New Jersey, ¿cuánto tiempo debe manejar solo con un adulto supervisor un conductor con permiso menor de 21 años antes del examen de manejo?","o":["Por lo menos 6 meses","Por lo menos 1 mes","Por lo menos 2 años","No hay tiempo fijo"],"h1":"Es medio año.","h2":"En New Jersey un conductor con permiso menor de 21 años debe manejar con un adulto supervisor por lo menos seis meses antes de aprobar el examen de manejo.","p":"Correcto. Primero vienen seis meses de manejo supervisado."},"ref":{"doc":"NJ","page":15}},{"id":"nj-009","scope":"NJ","cat":"licensing","sign":null,"c":1,"en":{"q":"In New Jersey, between which hours may a probationary driver under 21 not drive?","o":["10:00 p.m. to 6:00 a.m.","11:01 p.m. to 5:00 a.m.","Midnight to 4:00 a.m.","9:00 p.m. to 5:00 a.m."],"h1":"It starts just after eleven at night.","h2":"In New Jersey a probationary driver under 21 may not drive from 11:01 p.m. to 5:00 a.m., unless they carry a letter showing they must drive then for work or religion.","p":"Right. No driving from 11:01 p.m. to 5:00 a.m."},"es":{"q":"En New Jersey, ¿entre qué horas no puede manejar un conductor con licencia probatoria menor de 21 años?","o":["10:00 p.m. a 6:00 a.m.","11:01 p.m. a 5:00 a.m.","Medianoche a 4:00 a.m.","9:00 p.m. a 5:00 a.m."],"h1":"Empieza justo después de las once de la noche.","h2":"En New Jersey un conductor con licencia probatoria menor de 21 años no puede manejar de 11:01 p.m. a 5:00 a.m., a menos que lleve una carta que muestre que debe manejar a esa hora por trabajo o por religión.","p":"Correcto. No se maneja de 11:01 p.m. a 5:00 a.m."},"ref":{"doc":"NJ","page":18}},{"id":"nj-010","scope":"NJ","cat":"licensing","sign":null,"c":3,"en":{"q":"In New Jersey, how many passengers may a probationary driver under 21 carry when no parent or guardian is in the car?","o":["None","Two","Three","One, plus the driver's own dependents"],"h1":"The driver's own dependents do not count.","h2":"A New Jersey probationary driver under 21 may carry only one passenger, plus the driver's own dependents, unless a parent or guardian is in the car.","p":"Right. One passenger, plus the driver's dependents."},"es":{"q":"En New Jersey, ¿cuántos pasajeros puede llevar un conductor con licencia probatoria menor de 21 años si no va un padre o tutor en el carro?","o":["Ninguno","Dos","Tres","Uno, más los dependientes del conductor"],"h1":"Los dependientes del propio conductor no cuentan.","h2":"Un conductor con licencia probatoria menor de 21 años en New Jersey solo puede llevar un pasajero, más sus propios dependientes, a menos que vaya un padre o tutor en el carro.","p":"Correcto. Un pasajero, más los dependientes del conductor."},"ref":{"doc":"NJ","page":18}},{"id":"nj-011","scope":"NJ","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In New Jersey, may a probationary driver use a hands-free phone while driving?","o":["No, hand-held and hands-free are both banned","Yes, hands-free is allowed","Yes, but only at red lights","Yes, if the call is short"],"h1":"The rule for new drivers covers every kind of phone use.","h2":"A New Jersey probationary driver may not use any wireless device while driving, hand-held or hands-free.","p":"Right. No phone at all for probationary drivers."},"es":{"q":"En New Jersey, ¿puede un conductor con licencia probatoria usar un teléfono manos libres mientras maneja?","o":["No, están prohibidos el teléfono en la mano y el manos libres","Sí, el manos libres está permitido","Sí, pero solo en semáforos en rojo","Sí, si la llamada es corta"],"h1":"La regla para conductores nuevos cubre todo uso del teléfono.","h2":"Un conductor con licencia probatoria en New Jersey no puede usar ningún aparato inalámbrico mientras maneja, ni en la mano ni con manos libres.","p":"Correcto. Nada de teléfono para conductores con licencia probatoria."},"ref":{"doc":"NJ","page":86}},{"id":"nj-012","scope":"NJ","cat":"licensing","sign":null,"c":2,"en":{"q":"In New Jersey, how many reflective decals must a permit or probationary driver under 21 display on the vehicle?","o":["None","One","Two","Four"],"h1":"It is more than one but fewer than three.","h2":"A New Jersey permit or probationary driver under 21 must display two red reflective decals, one on the front license plate and one on the rear plate.","p":"Right. Two decals are displayed."},"es":{"q":"En New Jersey, ¿cuántas calcomanías reflectantes debe mostrar en el vehículo un conductor con permiso o licencia probatoria menor de 21 años?","o":["Ninguna","Una","Dos","Cuatro"],"h1":"Es más de una pero menos de tres.","h2":"En New Jersey, un conductor con permiso o licencia probatoria menor de 21 años debe mostrar dos calcomanías rojas reflectantes, una en la placa delantera y otra en la placa trasera.","p":"Correcto. Se muestran dos calcomanías."},"ref":{"doc":"NJ","page":19}},{"id":"nj-013","scope":"NJ","cat":"licensing","sign":null,"c":1,"en":{"q":"In New Jersey, what is the fine for a permit or probationary driver under 21 who drives without the required decals?","o":["$25","$100","$500","There is no fine"],"h1":"It is a round number with three digits.","h2":"In New Jersey, breaking a graduated license rule, such as driving without the required decals, can bring a $100 fine.","p":"Right. Missing decals can cost $100."},"es":{"q":"En New Jersey, ¿cuál es la multa para un conductor con permiso o licencia probatoria menor de 21 años que maneja sin las calcomanías obligatorias?","o":["$25","$100","$500","No hay multa"],"h1":"Es un número redondo de tres cifras.","h2":"En New Jersey, no cumplir una regla de la licencia gradual, como manejar sin las calcomanías obligatorias, puede costar una multa de $100.","p":"Correcto. No llevar las calcomanías puede costar $100."},"ref":{"doc":"NJ","page":14}},{"id":"nj-014","scope":"NJ","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In New Jersey, what is the fine range for a first offense of using a hand-held phone while driving?","o":["$25 to $50","$50 to $100","$1,000 to $2,000","$200 to $400"],"h1":"It starts at two hundred dollars.","h2":"A first offense for using a hand-held phone while driving in New Jersey carries a fine of $200 to $400.","p":"Right. A first offense costs $200 to $400."},"es":{"q":"En New Jersey, ¿cuál es el rango de la multa por una primera vez de usar el teléfono en la mano mientras maneja?","o":["$25 a $50","$50 a $100","$1,000 a $2,000","$200 a $400"],"h1":"Empieza en doscientos dólares.","h2":"Una primera infracción por usar el teléfono en la mano mientras maneja en New Jersey tiene una multa de $200 a $400.","p":"Correcto. Una primera infracción cuesta de $200 a $400."},"ref":{"doc":"NJ","page":86}},{"id":"nj-015","scope":"NJ","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In New Jersey, you are on the opposite side of a highway divided by a raised median from a stopped school bus. What must you do?","o":["Stop until the bus moves","Keep your normal speed","Slow to no more than 10 mph while passing","Honk and pass"],"h1":"You do not have to stop, but you must go very slowly.","h2":"In New Jersey, if a safety island or raised median separates you from a stopped school bus on the other side, you must slow to no more than 10 miles per hour while passing.","p":"Right. Slow to 10 mph or less."},"es":{"q":"En New Jersey, usted va por el lado opuesto de una carretera dividida por un camellón elevado y hay un autobús escolar detenido. ¿Qué debe hacer?","o":["Detenerse hasta que el autobús avance","Mantener su velocidad normal","Bajar a no más de 10 mph al pasar","Tocar el claxon y pasar"],"h1":"No tiene que detenerse, pero debe ir muy despacio.","h2":"En New Jersey, si una isla de seguridad o un camellón elevado lo separa de un autobús escolar detenido del otro lado, usted debe bajar a no más de 10 millas por hora al pasar.","p":"Correcto. Baje a 10 mph o menos."},"ref":{"doc":"NJ","page":77}},{"id":"nj-016","scope":"NJ","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In New Jersey, when may you drive in the left lane of a multi-lane highway?","o":["When passing or turning left","Whenever you like","Only at night","Only when going the speed limit"],"h1":"New Jersey has a keep right law.","h2":"New Jersey law says to keep to the right lane and use the left lane only to pass another vehicle or to turn left.","p":"Right. Keep right, and pass on the left."},"es":{"q":"En New Jersey, ¿cuándo puede manejar en el carril izquierdo de una carretera de varios carriles?","o":["Cuando rebasa o va a dar vuelta a la izquierda","Siempre que quiera","Solo de noche","Solo si va al límite de velocidad"],"h1":"New Jersey tiene una ley de mantenerse a la derecha.","h2":"La ley de New Jersey dice que debe mantenerse en el carril derecho y usar el carril izquierdo solo para rebasar a otro vehículo o para dar vuelta a la izquierda.","p":"Correcto. Manténgase a la derecha y rebase por la izquierda."},"ref":{"doc":"NJ","page":65}},{"id":"nj-017","scope":"NJ","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In New Jersey, what is the fine range for breaking the Move Over law?","o":["$25 to $50","$100 to $500","$1,000 to $5,000","There is only a warning"],"h1":"It starts at one hundred dollars.","h2":"Breaking the New Jersey Move Over law carries a fine of $100 to $500.","p":"Right. The fine is $100 to $500."},"es":{"q":"En New Jersey, ¿cuál es el rango de la multa por no cumplir la ley de \"Move Over\" (cambie de carril)?","o":["$25 a $50","$100 a $500","$1,000 a $5,000","Solo hay una advertencia"],"h1":"Empieza en cien dólares.","h2":"No cumplir la ley de \"Move Over\" en New Jersey tiene una multa de $100 a $500.","p":"Correcto. La multa es de $100 a $500."},"ref":{"doc":"NJ","page":78}},{"id":"nj-018","scope":"NJ","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In New Jersey, besides emergency, tow and road crew vehicles, what else does the Move Over law cover?","o":["Only parked school buses","Only police on foot","Nothing else","Disabled vehicles with their hazard lights on"],"h1":"A car with flashing hazard lights on the shoulder counts too.","h2":"The New Jersey Move Over law now also covers disabled vehicles that have their hazard lights on.","p":"Right. Disabled cars with hazard lights are covered."},"es":{"q":"En New Jersey, además de vehículos de emergencia, grúas y cuadrillas de carretera, ¿qué más cubre la ley de \"Move Over\"?","o":["Solo autobuses escolares estacionados","Solo policías a pie","Nada más","Vehículos descompuestos con las luces intermitentes encendidas"],"h1":"Un carro en el acotamiento con luces intermitentes también cuenta.","h2":"La ley de \"Move Over\" de New Jersey ahora también cubre vehículos descompuestos que tienen las luces intermitentes encendidas.","p":"Correcto. Los carros descompuestos con luces intermitentes están cubiertos."},"ref":{"doc":"NJ","page":78}},{"id":"nj-019","scope":"NJ","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In New Jersey, you pass a person walking or biking on the road and cannot change lanes or leave 4 feet. What must you do?","o":["Honk and pass quickly","Pass at the posted speed","Slow to 25 mph and be ready to stop","Stop and wait for them to leave the road"],"h1":"There is a set speed for this case.","h2":"In New Jersey, if you cannot change lanes or leave 4 feet when passing a pedestrian or bicyclist, you must slow to 25 miles per hour and be ready to stop.","p":"Right. Slow to 25 mph and be ready to stop."},"es":{"q":"En New Jersey, usted va a rebasar a una persona que camina o va en bicicleta por la calle y no puede cambiar de carril ni dejar 4 pies. ¿Qué debe hacer?","o":["Tocar el claxon y pasar rápido","Pasar al límite de velocidad","Bajar a 25 mph y estar listo para detenerse","Detenerse y esperar a que salga de la calle"],"h1":"Hay una velocidad fija para este caso.","h2":"En New Jersey, si no puede cambiar de carril ni dejar 4 pies al rebasar a un peatón o ciclista, debe bajar a 25 millas por hora y estar listo para detenerse.","p":"Correcto. Baje a 25 mph y esté listo para detenerse."},"ref":{"doc":"NJ","page":150}},{"id":"nj-020","scope":"NJ","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In New Jersey, at what blood alcohol level can a driver under 21 be charged?","o":["0.01","0.05","0.08","0.10"],"h1":"Even a very small amount counts.","h2":"New Jersey has zero tolerance for drivers under 21, so a blood alcohol level of just 0.01 can lead to a charge.","p":"Right. Under 21, 0.01 is already too much."},"es":{"q":"En New Jersey, ¿con qué nivel de alcohol en la sangre se puede acusar a un conductor menor de 21 años?","o":["0.01","0.05","0.08","0.10"],"h1":"Incluso una cantidad muy pequeña cuenta.","h2":"New Jersey tiene tolerancia cero para conductores menores de 21 años, así que un nivel de alcohol en la sangre de apenas 0.01 puede llevar a una acusación.","p":"Correcto. Menor de 21, 0.01 ya es demasiado."},"ref":{"doc":"NJ","page":115}},{"id":"nm-001","scope":"NM","cat":"licensing","sign":null,"c":1,"en":{"q":"In New Mexico, what is the youngest age to apply for an instruction permit?","o":["14 years old","15 years old","16 years old","17 years old"],"h1":"It is one year younger than 16.","h2":"In New Mexico you can apply for an instruction permit at 15 if you are in or have finished an approved driver education course.","p":"Right. The New Mexico permit starts at 15."},"es":{"q":"En Nuevo México, ¿cuál es la edad mínima para solicitar un permiso de instrucción?","o":["14 años","15 años","16 años","17 años"],"h1":"Es un año menos que 16.","h2":"En Nuevo México usted puede solicitar un permiso de instrucción a los 15 años si está tomando o ya terminó un curso aprobado de educación vial.","p":"Correcto. El permiso en Nuevo México empieza a los 15."},"ref":{"doc":"NM","page":1}},{"id":"nm-002","scope":"NM","cat":"licensing","sign":null,"c":2,"en":{"q":"In New Mexico, what must the driver education course include for a teen to get an instruction permit?","o":["A car repair class","A first aid certificate","A DWI prevention and education part","A night driving test"],"h1":"It is about drinking and driving.","h2":"In New Mexico the approved driver education course must include a DWI prevention and education part.","p":"Correct. The course includes DWI education."},"es":{"q":"En Nuevo México, ¿qué debe incluir el curso de educación vial para que un joven obtenga el permiso de instrucción?","o":["Una clase de mecánica","Un certificado de primeros auxilios","Una parte de prevención y educación sobre manejar bajo la influencia (DWI)","Un examen de manejo nocturno"],"h1":"Tiene que ver con tomar alcohol y manejar.","h2":"En Nuevo México, el curso aprobado de educación vial debe incluir una parte de prevención y educación sobre manejar bajo la influencia (DWI).","p":"Correcto. El curso incluye educación sobre DWI."},"ref":{"doc":"NM","page":1}},{"id":"nm-003","scope":"NM","cat":"licensing","sign":null,"c":3,"en":{"q":"In New Mexico, how old must the licensed driver beside an instruction permit holder be?","o":["16 or older","18 or older","25 or older","21 or older"],"h1":"The helper must be old enough to drink legally.","h2":"In New Mexico an instruction permit holder must drive with a licensed driver who is 21 or older in the seat beside them.","p":"Right. The supervisor must be 21 or older."},"es":{"q":"En Nuevo México, ¿qué edad debe tener el conductor con licencia que va al lado de quien tiene permiso de instrucción?","o":["16 años o más","18 años o más","25 años o más","21 años o más"],"h1":"El acompañante debe tener edad para tomar alcohol legalmente.","h2":"En Nuevo México, quien tiene permiso de instrucción debe manejar con un conductor con licencia de 21 años o más sentado a su lado.","p":"Correcto. El supervisor debe tener 21 años o más."},"ref":{"doc":"NM","page":1}},{"id":"nm-004","scope":"NM","cat":"licensing","sign":null,"c":0,"en":{"q":"In New Mexico, how long must the supervising driver have been licensed?","o":["At least three years","At least six months","At least one year","At least ten years"],"h1":"It is more than one year but less than five.","h2":"In New Mexico the supervising driver must have been licensed for at least three years, in New Mexico or another state.","p":"Correct. Three years of licensed driving are required."},"es":{"q":"En Nuevo México, ¿cuánto tiempo debe tener licencia el conductor que supervisa?","o":["Por lo menos tres años","Por lo menos seis meses","Por lo menos un año","Por lo menos diez años"],"h1":"Es más de un año, pero menos de cinco.","h2":"En Nuevo México, el conductor que supervisa debe tener licencia desde hace por lo menos tres años, en Nuevo México o en otro estado.","p":"Correcto. Se piden tres años con licencia."},"ref":{"doc":"NM","page":1}},{"id":"nm-005","scope":"NM","cat":"licensing","sign":null,"c":1,"en":{"q":"In New Mexico, where must the supervising driver sit?","o":["In any back seat","In the seat beside the driver","Anywhere in the vehicle","In a car following behind"],"h1":"They need to see the road and help right away.","h2":"In New Mexico the supervising driver must sit in the seat beside the permit holder.","p":"Right. The supervisor sits beside you."},"es":{"q":"En Nuevo México, ¿dónde debe sentarse el conductor que supervisa?","o":["En cualquier asiento de atrás","En el asiento al lado del conductor","En cualquier lugar del vehículo","En otro auto que va detrás"],"h1":"Necesita ver el camino y ayudar de inmediato.","h2":"En Nuevo México, el conductor que supervisa debe ir sentado al lado de quien tiene el permiso.","p":"Correcto. El supervisor va a su lado."},"ref":{"doc":"NM","page":1}},{"id":"nm-006","scope":"NM","cat":"licensing","sign":null,"c":2,"en":{"q":"In New Mexico, how long must you hold an instruction permit before a provisional license?","o":["At least one month","At least three months","At least six months","At least two years"],"h1":"It is half a year.","h2":"In New Mexico you must hold an instruction permit for at least six months before getting a provisional license.","p":"Correct. Six months is the minimum."},"es":{"q":"En Nuevo México, ¿cuánto tiempo debe tener el permiso de instrucción antes de la licencia provisional?","o":["Por lo menos un mes","Por lo menos tres meses","Por lo menos seis meses","Por lo menos dos años"],"h1":"Es medio año.","h2":"En Nuevo México usted debe tener el permiso de instrucción por lo menos seis meses antes de obtener la licencia provisional.","p":"Correcto. Seis meses es el mínimo."},"ref":{"doc":"NM","page":1}},{"id":"nm-007","scope":"NM","cat":"licensing","sign":null,"c":3,"en":{"q":"In New Mexico, what happens to the permit waiting period if you get a traffic violation while driving on a permit?","o":["Nothing changes","It starts over from zero","It grows by one year","It grows by 30 days for each violation"],"h1":"Each ticket adds about one month.","h2":"In New Mexico the six-month permit period is extended by 30 days for each traffic violation committed while driving on the permit.","p":"Right. Each violation adds 30 days."},"es":{"q":"En Nuevo México, ¿qué pasa con el período de espera del permiso si comete una infracción de tránsito mientras maneja con permiso?","o":["No cambia nada","Empieza otra vez desde cero","Aumenta un año","Aumenta 30 días por cada infracción"],"h1":"Cada multa agrega más o menos un mes.","h2":"En Nuevo México, el período de seis meses con permiso se alarga 30 días por cada infracción de tránsito cometida mientras maneja con el permiso.","p":"Correcto. Cada infracción agrega 30 días."},"ref":{"doc":"NM","page":null}},{"id":"nm-008","scope":"NM","cat":"licensing","sign":null,"c":0,"en":{"q":"In New Mexico, how many hours of supervised driving practice do you need before a provisional license?","o":["50 hours","20 hours","30 hours","100 hours"],"h1":"It is a round number between 30 and 100.","h2":"In New Mexico you need a total of 50 hours of supervised driving practice before a provisional license.","p":"Correct. New Mexico asks for 50 hours."},"es":{"q":"En Nuevo México, ¿cuántas horas de práctica supervisada necesita antes de la licencia provisional?","o":["50 horas","20 horas","30 horas","100 horas"],"h1":"Es un número redondo entre 30 y 100.","h2":"En Nuevo México usted necesita un total de 50 horas de práctica supervisada antes de la licencia provisional.","p":"Correcto. Nuevo México pide 50 horas."},"ref":{"doc":"NM","page":1}},{"id":"nm-009","scope":"NM","cat":"licensing","sign":null,"c":1,"en":{"q":"In New Mexico, how many of the supervised practice hours must be at night?","o":["At least 2 hours","At least 10 hours","At least 5 hours","At least 20 hours"],"h1":"It is one fifth of the total.","h2":"In New Mexico at least 10 of the 50 supervised practice hours must be at night.","p":"Right. Ten hours must be at night."},"es":{"q":"En Nuevo México, ¿cuántas de las horas de práctica supervisada deben ser de noche?","o":["Por lo menos 2 horas","Por lo menos 10 horas","Por lo menos 5 horas","Por lo menos 20 horas"],"h1":"Es la quinta parte del total.","h2":"En Nuevo México, por lo menos 10 de las 50 horas de práctica supervisada deben ser de noche.","p":"Correcto. Diez horas deben ser de noche."},"ref":{"doc":"NM","page":1}},{"id":"nm-010","scope":"NM","cat":"licensing","sign":null,"c":2,"en":{"q":"In New Mexico, who must certify in writing that the supervised practice hours are done?","o":["A school teacher","Any friend over 18","A parent or guardian","The permit holder alone"],"h1":"It is the adult legally responsible for the teen.","h2":"In New Mexico a parent or guardian must certify in writing that the 50 supervised practice hours are complete.","p":"Correct. A parent or guardian signs for the hours."},"es":{"q":"En Nuevo México, ¿quién debe certificar por escrito que se completaron las horas de práctica supervisada?","o":["Un maestro de la escuela","Cualquier amigo mayor de 18","Un padre o tutor","Solo quien tiene el permiso"],"h1":"Es el adulto legalmente responsable del joven.","h2":"En Nuevo México, un padre o tutor debe certificar por escrito que se completaron las 50 horas de práctica supervisada.","p":"Correcto. Un padre o tutor firma por las horas."},"ref":{"doc":"NM","page":1}},{"id":"nm-011","scope":"NM","cat":"licensing","sign":null,"c":3,"en":{"q":"In New Mexico, during which hours is a provisional license holder not allowed to drive, unless an exception applies?","o":["9 p.m. to 5 a.m.","10 p.m. to 6 a.m.","11 p.m. to 4 a.m.","Midnight to 5 a.m."],"h1":"The limit starts when the date changes.","h2":"In New Mexico a provisional license holder may not drive from midnight to 5 a.m. unless an exception applies, such as a licensed driver 21 or older in the vehicle.","p":"Right. No driving from midnight to 5 a.m."},"es":{"q":"En Nuevo México, ¿en qué horario no puede manejar quien tiene licencia provisional, salvo una excepción?","o":["De 9 p.m. a 5 a.m.","De 10 p.m. a 6 a.m.","De 11 p.m. a 4 a.m.","De medianoche a 5 a.m."],"h1":"El límite empieza cuando cambia la fecha.","h2":"En Nuevo México, quien tiene licencia provisional no puede manejar de medianoche a 5 a.m., salvo una excepción, como ir con un conductor con licencia de 21 años o más.","p":"Correcto. No se maneja de medianoche a 5 a.m."},"ref":{"doc":"NM","page":1}},{"id":"nm-012","scope":"NM","cat":"licensing","sign":null,"c":0,"en":{"q":"In New Mexico, a provisional license holder wants to drive at 1 a.m. Which situation allows it?","o":["A licensed driver 21 or older is in the vehicle","A friend 18 years old is in the vehicle","The driver feels wide awake","The roads are empty"],"h1":"Think of the same kind of adult who supervises a permit holder.","h2":"In New Mexico a provisional license holder may drive between midnight and 5 a.m. when a licensed driver 21 or older is in the vehicle.","p":"Correct. An adult driver 21 or older makes it allowed."},"es":{"q":"En Nuevo México, alguien con licencia provisional quiere manejar a la 1 a.m. ¿Qué situación lo permite?","o":["Va en el vehículo un conductor con licencia de 21 años o más","Va en el vehículo un amigo de 18 años","El conductor se siente bien despierto","Las calles están vacías"],"h1":"Piense en el mismo tipo de adulto que supervisa a quien tiene permiso.","h2":"En Nuevo México, quien tiene licencia provisional puede manejar entre medianoche y 5 a.m. si va en el vehículo un conductor con licencia de 21 años o más.","p":"Correcto. Un conductor adulto de 21 años o más lo permite."},"ref":{"doc":"NM","page":2}},{"id":"nm-013","scope":"NM","cat":"licensing","sign":null,"c":1,"en":{"q":"In New Mexico, how many passengers under 21 who are not immediate family may a provisional driver carry?","o":["None at all","No more than one","No more than two","No more than three"],"h1":"It is the smallest number that is not zero.","h2":"In New Mexico a provisional driver may carry no more than one passenger under 21 who is not immediate family, unless a licensed driver 21 or older is in the vehicle.","p":"Right. Only one young non-family passenger."},"es":{"q":"En Nuevo México, ¿cuántos pasajeros menores de 21 años que no son familia directa puede llevar un conductor provisional?","o":["Ninguno","No más de uno","No más de dos","No más de tres"],"h1":"Es el número más pequeño que no es cero.","h2":"En Nuevo México, un conductor provisional no puede llevar más de un pasajero menor de 21 años que no sea familia directa, salvo que vaya un conductor con licencia de 21 años o más.","p":"Correcto. Solo un pasajero joven que no sea familia."},"ref":{"doc":"NM","page":1}},{"id":"nm-014","scope":"NM","cat":"licensing","sign":null,"c":2,"en":{"q":"In New Mexico, how long must you hold a provisional license before applying for a full license?","o":["At least 3 months","At least 6 months","At least 12 months","At least 3 years"],"h1":"It is one full year.","h2":"In New Mexico you must hold a provisional license for at least 12 months before applying for a full license.","p":"Correct. It takes at least one year."},"es":{"q":"En Nuevo México, ¿cuánto tiempo debe tener la licencia provisional antes de solicitar la licencia completa?","o":["Por lo menos 3 meses","Por lo menos 6 meses","Por lo menos 12 meses","Por lo menos 3 años"],"h1":"Es un año completo.","h2":"En Nuevo México usted debe tener la licencia provisional por lo menos 12 meses antes de solicitar la licencia completa.","p":"Correcto. Se necesita por lo menos un año."},"ref":{"doc":"NM","page":2}},{"id":"nm-015","scope":"NM","cat":"licensing","sign":null,"c":3,"en":{"q":"In New Mexico, what score do you need to pass the written test for a car license?","o":["50 percent or better","60 percent or better","90 percent or better","70 percent or better"],"h1":"It is the same as a passing grade of C in many schools.","h2":"In New Mexico you need a score of 70 percent or better to pass the written test.","p":"Right. You need 70 percent."},"es":{"q":"En Nuevo México, ¿qué calificación necesita para aprobar el examen escrito para licencia de auto?","o":["50 por ciento o más","60 por ciento o más","90 por ciento o más","70 por ciento o más"],"h1":"Es como una nota de aprobado en muchas escuelas.","h2":"En Nuevo México usted necesita 70 por ciento o más para aprobar el examen escrito.","p":"Correcto. Se necesita 70 por ciento."},"ref":{"doc":"NM","page":null}},{"id":"nm-016","scope":"NM","cat":"licensing","sign":null,"c":0,"en":{"q":"In New Mexico, in which languages can you take the written knowledge test?","o":["English, Spanish and several other languages","English only","English and Spanish only on weekends","Spanish only at the border"],"h1":"New Mexico offers more than two choices.","h2":"In New Mexico the written test is offered in English, Spanish and several other languages.","p":"Correct. Spanish and other languages are offered."},"es":{"q":"En Nuevo México, ¿en qué idiomas puede tomar el examen escrito de conocimientos?","o":["Inglés, español y varios idiomas más","Solo en inglés","Inglés y español solo los fines de semana","Español solo en la frontera"],"h1":"Nuevo México ofrece más de dos opciones.","h2":"En Nuevo México el examen escrito se ofrece en inglés, español y varios idiomas más.","p":"Correcto. Se ofrece en español y en otros idiomas."},"ref":{"doc":"NM","page":null}},{"id":"nm-017","scope":"NM","cat":"licensing","sign":null,"c":1,"en":{"q":"In New Mexico, who does not need to take the written test when getting a first New Mexico license?","o":["Anyone over 18","Someone with a current license from another state","Anyone who owns a car","Anyone with a permit from another country"],"h1":"They already hold a valid license from a US state.","h2":"In New Mexico the written test is not required if you hold a current driver license from another state.","p":"Right. A current out-of-state license skips the written test."},"es":{"q":"En Nuevo México, ¿quién no necesita tomar el examen escrito al sacar su primera licencia de Nuevo México?","o":["Cualquier persona mayor de 18","Alguien con una licencia vigente de otro estado","Cualquiera que tenga carro propio","Cualquiera con permiso de otro país"],"h1":"Esa persona ya tiene una licencia válida de un estado del país.","h2":"En Nuevo México no se exige el examen escrito si usted tiene una licencia de manejo vigente de otro estado.","p":"Correcto. Con licencia vigente de otro estado no hace falta el examen escrito."},"ref":{"doc":"NM","page":null}},{"id":"nm-018","scope":"NM","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In New Mexico, what blood or breath alcohol level is illegal for a driver under 21?","o":["0.08 or more","0.05 or more","0.02 or more","0.10 or more"],"h1":"It is far below the adult limit.","h2":"In New Mexico it is illegal for a driver under 21 to drive with an alcohol level of 0.02 or more.","p":"Correct. Under 21, the limit is 0.02."},"es":{"q":"En Nuevo México, ¿qué nivel de alcohol en la sangre o el aliento es ilegal para un conductor menor de 21 años?","o":["0.08 o más","0.05 o más","0.02 o más","0.10 o más"],"h1":"Es mucho más bajo que el límite para adultos.","h2":"En Nuevo México es ilegal que un conductor menor de 21 años maneje con un nivel de alcohol de 0.02 o más.","p":"Correcto. Para menores de 21, el límite es 0.02."},"ref":{"doc":"NM","page":29}},{"id":"nm-019","scope":"NM","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In New Mexico, a school bus is stopped with red lights flashing on the opposite side of a road with no median. What must you do?","o":["Keep going, because the bus is on the other side","Slow to 20 mph and pass","Honk and pass carefully","Stop, because you must stop on either side of an undivided road"],"h1":"Only a median or barrier would change the rule.","h2":"In New Mexico you must stop for a school bus with flashing red lights even on the opposite side, unless a median or physical barrier separates you from it.","p":"Right. Without a median, everyone stops."},"es":{"q":"En Nuevo México, un autobús escolar está detenido con luces rojas intermitentes al otro lado de una calle sin mediana. ¿Qué debe hacer?","o":["Seguir, porque el autobús está del otro lado","Bajar a 20 mph y pasar","Tocar la bocina y pasar con cuidado","Detenerse, porque en una calle sin división se detiene de los dos lados"],"h1":"Solo una mediana o barrera cambiaría la regla.","h2":"En Nuevo México debe detenerse ante un autobús escolar con luces rojas intermitentes aunque esté del otro lado, salvo que lo separe una mediana o barrera física.","p":"Correcto. Sin mediana, todos se detienen."},"ref":{"doc":"NM","page":12}},{"id":"nm-020","scope":"NM","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In New Mexico, when do you not have to stop for a school bus with flashing red lights?","o":["When it is coming toward you and a median or barrier separates the roads","When you are behind it","When it is at an intersection ahead","When you are late for work"],"h1":"It depends on the bus's direction and what lies between you.","h2":"In New Mexico you do not have to stop when the school bus is traveling toward you on a road separated by a median or other physical barrier.","p":"Correct. A median and opposite direction mean no stop."},"es":{"q":"En Nuevo México, ¿cuándo no tiene que detenerse por un autobús escolar con luces rojas intermitentes?","o":["Cuando viene hacia usted y una mediana o barrera separa los carriles","Cuando usted va detrás de él","Cuando está en una intersección adelante","Cuando usted va tarde al trabajo"],"h1":"Depende de la dirección del autobús y de lo que hay entre ustedes.","h2":"En Nuevo México no tiene que detenerse cuando el autobús escolar viene hacia usted por una vía separada por una mediana u otra barrera física.","p":"Correcto. Con mediana y en dirección contraria, no se detiene."},"ref":{"doc":"NM","page":12}},{"id":"nm-021","scope":"NM","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In New Mexico, what does state law say about texting while driving?","o":["It is allowed at speeds under 30 mph","It is against the law to read or type text messages while driving","It is allowed on rural roads","It is only a warning, never a fine"],"h1":"It carries a fine.","h2":"In New Mexico it is against the law to read, view or type text messages on a phone while driving, and it carries a fine.","p":"Right. Texting while driving is illegal."},"es":{"q":"En Nuevo México, ¿qué dice la ley estatal sobre los mensajes de texto al manejar?","o":["Se permite a menos de 30 mph","Es ilegal leer o escribir mensajes de texto mientras maneja","Se permite en caminos rurales","Es solo una advertencia, nunca una multa"],"h1":"Tiene una multa.","h2":"En Nuevo México es ilegal leer, ver o escribir mensajes de texto en un teléfono mientras maneja, y tiene una multa.","p":"Correcto. Escribir mensajes al manejar es ilegal."},"ref":{"doc":"NM","page":null}},{"id":"nv-001","scope":"NV","cat":"licensing","sign":null,"c":2,"en":{"q":"In Nevada, what is the youngest age to get an instruction permit?","o":["14 years old","15 years old","15 and a half years old","16 years old"],"h1":"It is a half year past a birthday.","h2":"In Nevada you can get an instruction permit at 15 and a half years old.","p":"Right. Nevada permits start at 15 and a half."},"es":{"q":"En Nevada, ¿cuál es la edad mínima para obtener un permiso de instrucción?","o":["14 años","15 años","15 años y medio","16 años"],"h1":"Es medio año después de un cumpleaños.","h2":"En Nevada usted puede obtener el permiso de instrucción a los 15 años y medio.","p":"Correcto. El permiso en Nevada empieza a los 15 años y medio."},"ref":{"doc":"NV","page":15}},{"id":"nv-002","scope":"NV","cat":"licensing","sign":null,"c":1,"en":{"q":"In Nevada, how long is an instruction permit valid?","o":["Six months","One year","Two years","Until age 18"],"h1":"It lasts one trip around the calendar.","h2":"A Nevada instruction permit is valid for one year.","p":"Right. The permit lasts one year."},"es":{"q":"En Nevada, ¿por cuánto tiempo es válido el permiso de instrucción?","o":["Seis meses","Un año","Dos años","Hasta los 18 años"],"h1":"Dura una vuelta completa al calendario.","h2":"En Nevada, el permiso de instrucción es válido por un año.","p":"Correcto. El permiso dura un año."},"ref":{"doc":"NV","page":15}},{"id":"nv-003","scope":"NV","cat":"licensing","sign":null,"c":0,"en":{"q":"In Nevada, how many supervised driving hours must a teen complete, and how many at night?","o":["50 hours, 10 at night","30 hours, 5 at night","40 hours, 15 at night","100 hours, 20 at night"],"h1":"The night hours are one fifth of the total.","h2":"A Nevada teen must complete at least 50 hours of supervised driving, and 10 of those hours must be at night.","p":"Right. Fifty hours, ten at night."},"es":{"q":"En Nevada, ¿cuántas horas de manejo supervisado debe completar un adolescente, y cuántas de noche?","o":["50 horas, 10 de noche","30 horas, 5 de noche","40 horas, 15 de noche","100 horas, 20 de noche"],"h1":"Las horas de noche son una quinta parte del total.","h2":"En Nevada, un adolescente debe completar por lo menos 50 horas de manejo supervisado, y 10 de ellas deben ser de noche.","p":"Correcto. Cincuenta horas, diez de noche."},"ref":{"doc":"NV","page":14}},{"id":"nv-004","scope":"NV","cat":"licensing","sign":null,"c":3,"en":{"q":"In Nevada, who may supervise a teen's practice driving?","o":["Any person with a permit","Any adult over 18","A licensed driver over 25 only","A licensed driver at least 21 who has been licensed at least one year"],"h1":"There is a rule about age and a rule about experience.","h2":"In Nevada, a teen may practice with any licensed driver who is at least 21 and has held a license for at least one year.","p":"Right. At least 21, and licensed for at least a year."},"es":{"q":"En Nevada, ¿quién puede supervisar la práctica de manejo de un adolescente?","o":["Cualquier persona con permiso","Cualquier adulto mayor de 18","Solo un conductor con licencia mayor de 25","Un conductor con licencia de por lo menos 21 años y con licencia desde hace por lo menos un año"],"h1":"Hay una regla de edad y otra de experiencia.","h2":"En Nevada, un adolescente puede practicar con cualquier conductor con licencia que tenga por lo menos 21 años y haya tenido licencia por lo menos un año.","p":"Correcto. Por lo menos 21 años y un año con licencia."},"ref":{"doc":"NV","page":15}},{"id":"nv-005","scope":"NV","cat":"licensing","sign":null,"c":1,"en":{"q":"In Nevada, where must the experienced driver sit while a beginner practices?","o":["In the back seat","In the seat next to the beginner","Anywhere in the car","In a car following behind"],"h1":"They need to be close enough to help right away.","h2":"In Nevada, the experienced driver must sit in the seat next to the beginning driver.","p":"Right. The helper sits right beside you."},"es":{"q":"En Nevada, ¿dónde debe sentarse el conductor con experiencia mientras practica un principiante?","o":["En el asiento de atrás","En el asiento junto al principiante","En cualquier lugar del carro","En otro carro detrás"],"h1":"Debe estar lo bastante cerca para ayudar de inmediato.","h2":"En Nevada, el conductor con experiencia debe ir sentado en el asiento junto al conductor principiante.","p":"Correcto. El acompañante va a su lado."},"ref":{"doc":"NV","page":15}},{"id":"nv-006","scope":"NV","cat":"licensing","sign":null,"c":2,"en":{"q":"In Nevada, how do a teen and parent prove the supervised driving hours?","o":["They take a photo of the car","No proof is needed","They keep a log of the dates and times of practice","They send text messages to the DMV"],"h1":"It is a written record.","h2":"In Nevada, the teen and a parent or guardian must keep a log of the dates and times of the supervised driving.","p":"Right. Keep a written log of your practice."},"es":{"q":"En Nevada, ¿cómo comprueban un adolescente y su padre las horas de manejo supervisado?","o":["Toman una foto del carro","No se necesita prueba","Llevan un registro de las fechas y horas de práctica","Mandan mensajes de texto al DMV"],"h1":"Es un registro escrito.","h2":"En Nevada, el adolescente y su padre, madre o tutor deben llevar un registro de las fechas y horas del manejo supervisado.","p":"Correcto. Lleve un registro escrito de su práctica."},"ref":{"doc":"NV","page":13}},{"id":"nv-007","scope":"NV","cat":"licensing","sign":null,"c":0,"en":{"q":"In Nevada, is driver education required to get an instruction permit?","o":["No, it is not required for the permit","Yes, always","Only for adults","Only in Las Vegas"],"h1":"It is required later, but not at the very first step.","h2":"In Nevada, driver education is not required to get an instruction permit.","p":"Right. The permit does not require driver education."},"es":{"q":"En Nevada, ¿se exige educación vial para obtener el permiso de instrucción?","o":["No, no se exige para el permiso","Sí, siempre","Solo para adultos","Solo en Las Vegas"],"h1":"Se exige más adelante, pero no en el primer paso.","h2":"En Nevada, no se exige educación vial para obtener el permiso de instrucción.","p":"Correcto. El permiso no exige educación vial."},"ref":{"doc":"NV","page":15}},{"id":"nv-008","scope":"NV","cat":"licensing","sign":null,"c":3,"en":{"q":"In Nevada, what must a parent or guardian sign when a teen applies for a permit?","o":["A school report card","A car title","A medical form","A financial responsibility statement"],"h1":"It is about who pays if something goes wrong.","h2":"In Nevada, a parent or guardian must be present to sign a financial responsibility statement for the teen's permit.","p":"Right. The parent signs for financial responsibility."},"es":{"q":"En Nevada, ¿qué debe firmar el padre, madre o tutor cuando un adolescente solicita el permiso?","o":["Una boleta de calificaciones","El título del carro","Un formulario médico","Una declaración de responsabilidad financiera"],"h1":"Tiene que ver con quién paga si algo sale mal.","h2":"En Nevada, el padre, madre o tutor debe estar presente para firmar una declaración de responsabilidad financiera para el permiso del adolescente.","p":"Correcto. El padre firma la responsabilidad financiera."},"ref":{"doc":"NV","page":null}},{"id":"nv-009","scope":"NV","cat":"licensing","sign":null,"c":1,"en":{"q":"In Nevada, during which hours may a licensed driver under 18 not drive, unless going to or from a scheduled event?","o":["Midnight to 6 a.m.","10 p.m. to 5 a.m.","9 p.m. to 6 a.m.","11 p.m. to 4 a.m."],"h1":"It starts at ten at night.","h2":"In Nevada, a licensed driver under 18 may not drive between 10 p.m. and 5 a.m. unless going to or from a scheduled event such as work or school.","p":"Right. No driving from 10 p.m. to 5 a.m."},"es":{"q":"En Nevada, ¿en qué horario no puede manejar un conductor con licencia menor de 18 años, salvo para ir o volver de un evento programado?","o":["De medianoche a 6 a.m.","De 10 p.m. a 5 a.m.","De 9 p.m. a 6 a.m.","De 11 p.m. a 4 a.m."],"h1":"Empieza a las diez de la noche.","h2":"En Nevada, un conductor con licencia menor de 18 años no puede manejar entre las 10 p.m. y las 5 a.m., salvo para ir o volver de un evento programado como el trabajo o la escuela.","p":"Correcto. No se maneja de 10 p.m. a 5 a.m."},"ref":{"doc":"NV","page":15}},{"id":"nv-010","scope":"NV","cat":"licensing","sign":null,"c":2,"en":{"q":"In Nevada, for how long after getting a license may a teen not carry passengers under 18 who are not family?","o":["One month","Three months","Six months","Two years"],"h1":"It is half a year.","h2":"In Nevada, a new teen driver may not carry passengers under 18, except immediate family, for the first six months after getting a license.","p":"Right. The first six months."},"es":{"q":"En Nevada, ¿por cuánto tiempo después de obtener la licencia no puede un adolescente llevar pasajeros menores de 18 años que no sean familia?","o":["Un mes","Tres meses","Seis meses","Dos años"],"h1":"Es medio año.","h2":"En Nevada, un conductor adolescente nuevo no puede llevar pasajeros menores de 18 años, salvo familiares directos, durante los primeros seis meses con licencia.","p":"Correcto. Los primeros seis meses."},"ref":{"doc":"NV","page":15}},{"id":"nv-011","scope":"NV","cat":"licensing","sign":null,"c":1,"en":{"q":"In Nevada, how many questions are on the car knowledge test, and how many must you answer correctly?","o":["20 questions, 15 correct","25 questions, 20 correct","40 questions, 30 correct","50 questions, 40 correct"],"h1":"You need 80 percent.","h2":"The Nevada knowledge test has 25 multiple-choice questions, and you must answer 20 correctly, which is 80 percent.","p":"Right. 20 out of 25."},"es":{"q":"En Nevada, ¿cuántas preguntas tiene el examen de conocimientos para carro, y cuántas debe contestar bien?","o":["20 preguntas, 15 correctas","25 preguntas, 20 correctas","40 preguntas, 30 correctas","50 preguntas, 40 correctas"],"h1":"Necesita el 80 por ciento.","h2":"El examen de conocimientos de Nevada tiene 25 preguntas de opción múltiple, y usted debe contestar 20 bien, que es el 80 por ciento.","p":"Correcto. 20 de 25."},"ref":{"doc":"NV","page":null}},{"id":"nv-013","scope":"NV","cat":"licensing","sign":null,"c":3,"en":{"q":"In Nevada, how long is a passed knowledge test result valid?","o":["30 days","90 days","Six months","One year"],"h1":"It matches how long the permit lasts.","h2":"In Nevada, a passed knowledge test result is valid for one year from the date you pass.","p":"Right. The result is good for one year."},"es":{"q":"En Nevada, ¿por cuánto tiempo es válido el resultado de un examen de conocimientos aprobado?","o":["30 días","90 días","Seis meses","Un año"],"h1":"Coincide con lo que dura el permiso.","h2":"En Nevada, el resultado de un examen de conocimientos aprobado es válido por un año desde la fecha en que lo aprueba.","p":"Correcto. El resultado vale un año."},"ref":{"doc":"NV","page":null}},{"id":"nv-014","scope":"NV","cat":"licensing","sign":null,"c":2,"en":{"q":"In Nevada, in which languages can you take the car knowledge test?","o":["English only","Spanish only","English or Spanish","Any language you choose"],"h1":"This app uses the same two languages.","h2":"In Nevada you can take the car knowledge test in English or in Spanish.","p":"Right. English or Spanish."},"es":{"q":"En Nevada, ¿en qué idiomas puede tomar el examen de conocimientos para carro?","o":["Solo inglés","Solo español","Inglés o español","Cualquier idioma que elija"],"h1":"Esta aplicación usa los mismos dos idiomas.","h2":"En Nevada usted puede tomar el examen de conocimientos para carro en inglés o en español.","p":"Correcto. Inglés o español."},"ref":{"doc":"NV","page":12}},{"id":"nv-015","scope":"NV","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Nevada, what is the blood alcohol limit for drivers under 21?","o":[".02 percent",".05 percent",".08 percent",".10 percent"],"h1":"It is a tiny fraction of the adult limit.","h2":"In Nevada the blood alcohol limit for drivers under 21 is .02 percent, much lower than the adult limit of .08.","p":"Right. Under 21, the limit is .02."},"es":{"q":"En Nevada, ¿cuál es el límite de alcohol en la sangre para conductores menores de 21 años?","o":[".02 por ciento",".05 por ciento",".08 por ciento",".10 por ciento"],"h1":"Es una fracción muy pequeña del límite para adultos.","h2":"En Nevada el límite de alcohol en la sangre para conductores menores de 21 años es .02 por ciento, mucho menor que el límite de .08 para adultos.","p":"Correcto. Para menores de 21, el límite es .02."},"ref":{"doc":"NV","page":79}},{"id":"nv-016","scope":"NV","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Nevada, the move-over law covers more than emergency vehicles. Which of these does it also cover?","o":["Parked cars at a mall","A stalled vehicle or debris on the road","Bicycles in a bike lane","Buses at a bus stop"],"h1":"The law also covers hazards on the road itself.","h2":"In Nevada the move-over law also covers traffic incidents, such as a crash, a stalled vehicle or debris on the road.","p":"Right. Stalled cars and debris count too."},"es":{"q":"En Nevada, la ley de cambiarse de carril cubre más que los vehículos de emergencia. ¿Qué otra cosa también cubre?","o":["Carros estacionados en un centro comercial","Un vehículo averiado o escombros en la vía","Bicicletas en una ciclovía","Autobuses en una parada"],"h1":"La ley también cubre peligros en la misma vía.","h2":"En Nevada la ley de cambiarse de carril también cubre incidentes de tráfico, como un choque, un vehículo averiado o escombros en la vía.","p":"Correcto. Los vehículos averiados y los escombros también cuentan."},"ref":{"doc":"NV","page":null}},{"id":"nv-017","scope":"NV","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Nevada, what must you do when passing an emergency vehicle stopped on the shoulder with its lights flashing?","o":["Speed up to pass quickly","Stop in your lane","Honk to warn them","Slow down and, if you can, use a lane that is not next to it"],"h1":"Give them more space and less speed.","h2":"In Nevada you must slow down below the posted limit, drive with care, be ready to stop and, if you can, use a lane that is not next to the stopped emergency vehicle.","p":"Right. Slow down and move over."},"es":{"q":"En Nevada, ¿qué debe hacer al pasar un vehículo de emergencia detenido en el acotamiento con las luces encendidas?","o":["Acelerar para pasar rápido","Detenerse en su carril","Tocar la bocina para avisar","Bajar la velocidad y, si puede, usar un carril que no esté al lado"],"h1":"Deles más espacio y vaya más despacio.","h2":"En Nevada usted debe bajar la velocidad por debajo del límite indicado, manejar con cuidado, estar listo para detenerse y, si puede, usar un carril que no esté al lado del vehículo de emergencia detenido.","p":"Correcto. Baje la velocidad y cámbiese de carril."},"ref":{"doc":"NV","page":61}},{"id":"nv-018","scope":"NV","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Nevada, when do you not have to stop for a stopped school bus with flashing red lights?","o":["When you are in a hurry","When no children are visible","When the bus is on the other roadway of a divided highway","When you are on a two-lane road"],"h1":"A barrier or dividing section separates you from the bus.","h2":"In Nevada, on a divided highway, you need not stop for a school bus that is on the other roadway; traffic going the same way as the bus must stop.","p":"Right. Only the divided highway exception applies."},"es":{"q":"En Nevada, ¿cuándo no tiene que detenerse ante un autobús escolar detenido con luces rojas intermitentes?","o":["Cuando tiene prisa","Cuando no se ven niños","Cuando el autobús está en el otro lado de una carretera dividida","Cuando va por una carretera de dos carriles"],"h1":"Una barrera o franja divisoria lo separa del autobús.","h2":"En Nevada, en una carretera dividida, usted no tiene que detenerse por un autobús escolar que está en la otra calzada; el tráfico que va en la misma dirección que el autobús sí debe detenerse.","p":"Correcto. Solo aplica la excepción de la carretera dividida."},"ref":{"doc":"NV","page":64}},{"id":"nv-019","scope":"NV","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Nevada, how may an adult driver talk on a cell phone while driving?","o":["Only with a hands-free device","Holding the phone in one hand","Only at speeds under 25 mph","Any way they like"],"h1":"Your hands must stay free for the wheel.","h2":"In Nevada it is illegal to hold a phone to talk while driving, so an adult may only talk using a hands-free device.","p":"Right. Hands-free only."},"es":{"q":"En Nevada, ¿cómo puede un conductor adulto hablar por celular mientras maneja?","o":["Solo con un dispositivo manos libres","Sosteniendo el teléfono en una mano","Solo a menos de 25 mph","Como quiera"],"h1":"Sus manos deben quedar libres para el volante.","h2":"En Nevada es ilegal sostener el teléfono para hablar mientras maneja, así que un adulto solo puede hablar con un dispositivo manos libres.","p":"Correcto. Solo manos libres."},"ref":{"doc":"NV","page":43}},{"id":"nv-020","scope":"NV","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Nevada, what is the fine for a first handheld phone or texting offense in seven years?","o":["$25","$50","$250","$500"],"h1":"It is the lowest step of three: then $100, then $250.","h2":"In Nevada, the fine for a first handheld phone or texting offense in seven years is $50, and it can double in a work zone.","p":"Right. The first fine is $50."},"es":{"q":"En Nevada, ¿cuál es la multa por la primera infracción de usar el teléfono en la mano o enviar mensajes en siete años?","o":["$25","$50","$250","$500"],"h1":"Es el escalón más bajo de tres: luego $100, luego $250.","h2":"En Nevada, la multa por la primera infracción de teléfono en la mano o mensajes en siete años es de $50, y puede duplicarse en una zona de obras.","p":"Correcto. La primera multa es de $50."},"ref":{"doc":"NV","page":null}},{"id":"nv-021","scope":"NV","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Nevada, what is the highest speed limit the state may post on its highways?","o":["65 mph","70 mph","75 mph","80 mph"],"h1":"It matches the name of a big interstate across northern Nevada.","h2":"Nevada may post a speed limit of up to 80 mph on state highways, and only where a sign shows it.","p":"Right. The top posted limit is 80 mph."},"es":{"q":"En Nevada, ¿cuál es el límite de velocidad más alto que el estado puede indicar en sus carreteras?","o":["65 mph","70 mph","75 mph","80 mph"],"h1":"Coincide con el nombre de una autopista grande en el norte de Nevada.","h2":"Nevada puede indicar un límite de hasta 80 mph en carreteras estatales, y solo donde un letrero lo muestre.","p":"Correcto. El límite más alto es 80 mph."},"ref":{"doc":"NV","page":null}},{"id":"ny-001","scope":"NY","cat":"licensing","sign":null,"c":2,"en":{"q":"In New York, what is the youngest age to apply for a learner permit?","o":["14 years old","15 years old","16 years old","17 years old"],"h1":"It is the same age many states use for a first license.","h2":"You must be at least 16 to apply for a New York learner permit.","p":"Right. In New York the permit starts at 16."},"es":{"q":"En Nueva York, ¿cuál es la edad mínima para solicitar un permiso de aprendiz?","o":["14 años","15 años","16 años","17 años"],"h1":"Es la misma edad que muchos estados usan para la primera licencia.","h2":"Usted debe tener por lo menos 16 años para solicitar un permiso de aprendiz en Nueva York.","p":"Correcto. En Nueva York el permiso empieza a los 16."},"ref":{"doc":"NY","page":11}},{"id":"ny-002","scope":"NY","cat":"licensing","sign":null,"c":0,"en":{"q":"In New York, how many of the 20 questions on the written permit test must you answer correctly?","o":["At least 14","At least 10","At least 16","At least 18"],"h1":"You may miss up to six questions.","h2":"To pass the New York written permit test you must answer at least 14 of the 20 questions correctly.","p":"Right. You need at least 14 out of 20."},"es":{"q":"En Nueva York, ¿cuántas de las 20 preguntas del examen escrito del permiso debe contestar bien?","o":["Por lo menos 14","Por lo menos 10","Por lo menos 16","Por lo menos 18"],"h1":"Puede equivocarse hasta en seis preguntas.","h2":"Para aprobar el examen escrito del permiso en Nueva York debe contestar bien por lo menos 14 de las 20 preguntas.","p":"Correcto. Necesita por lo menos 14 de 20."},"ref":{"doc":"NY","page":10}},{"id":"ny-003","scope":"NY","cat":"licensing","sign":null,"c":3,"en":{"q":"In New York, what else must you get right on the written permit test, besides 14 of 20 questions?","o":["All four road sign questions","The first five questions","Every question about alcohol","At least two of the four road sign questions"],"h1":"It is half of the sign questions.","h2":"On the New York written permit test you must also answer at least two of the four road sign questions correctly, or you fail.","p":"Right. You need two of the four sign questions."},"es":{"q":"En Nueva York, además de 14 de 20 preguntas, ¿qué más debe contestar bien en el examen escrito del permiso?","o":["Las cuatro preguntas sobre señales de tránsito","Las primeras cinco preguntas","Todas las preguntas sobre alcohol","Por lo menos dos de las cuatro preguntas sobre señales de tránsito"],"h1":"Es la mitad de las preguntas sobre señales.","h2":"En el examen escrito del permiso de Nueva York también debe contestar bien por lo menos dos de las cuatro preguntas sobre señales de tránsito, o no aprueba.","p":"Correcto. Necesita dos de las cuatro preguntas sobre señales."},"ref":{"doc":"NY","page":10}},{"id":"ny-004","scope":"NY","cat":"licensing","sign":null,"c":1,"en":{"q":"In New York, can you take the Class D written permit test in Spanish?","o":["No, only in English","Yes, it is offered in Spanish and many other languages","Only in New York City","Only with a paid interpreter"],"h1":"The DMV offers the test in about 20 languages.","h2":"Yes, the New York DMV offers the Class D written permit test in Spanish and many other languages.","p":"Right. You can take it in Spanish."},"es":{"q":"En Nueva York, ¿puede tomar en español el examen escrito del permiso clase D?","o":["No, solo en inglés","Sí, se ofrece en español y en muchos otros idiomas","Solo en la ciudad de Nueva York","Solo con un intérprete pagado"],"h1":"El DMV ofrece el examen en unos 20 idiomas.","h2":"Sí, el DMV de Nueva York ofrece el examen escrito del permiso clase D en español y en muchos otros idiomas.","p":"Correcto. Puede tomarlo en español."},"ref":{"doc":"NY","page":10}},{"id":"ny-005","scope":"NY","cat":"licensing","sign":null,"c":1,"en":{"q":"In New York, how many hours of supervised driving must a teen complete before the road test?","o":["30 hours","50 hours","40 hours","60 hours"],"h1":"It is half of one hundred.","h2":"A New York teen must complete at least 50 hours of supervised practice driving before the road test.","p":"Right. New York asks for 50 supervised hours."},"es":{"q":"En Nueva York, ¿cuántas horas de manejo supervisado debe completar un joven antes del examen de manejo?","o":["30 horas","50 horas","40 horas","60 horas"],"h1":"Es la mitad de cien.","h2":"En Nueva York, un joven debe completar por lo menos 50 horas de práctica de manejo supervisada antes del examen de manejo.","p":"Correcto. Nueva York pide 50 horas supervisadas."},"ref":{"doc":"NY","page":13}},{"id":"ny-006","scope":"NY","cat":"licensing","sign":null,"c":3,"en":{"q":"In New York, how many of the 50 supervised hours must be driven after sunset?","o":["5 hours","10 hours","20 hours","15 hours"],"h1":"It is more than 10 and less than 20.","h2":"At least 15 of the 50 supervised hours in New York must be driven after sunset.","p":"Right. Fifteen of the hours are after sunset."},"es":{"q":"En Nueva York, ¿cuántas de las 50 horas supervisadas deben ser después de la puesta del sol?","o":["5 horas","10 horas","20 horas","15 horas"],"h1":"Son más de 10 y menos de 20.","h2":"En Nueva York, por lo menos 15 de las 50 horas supervisadas deben ser después de la puesta del sol.","p":"Correcto. Quince de las horas son después de la puesta del sol."},"ref":{"doc":"NY","page":13}},{"id":"ny-007","scope":"NY","cat":"licensing","sign":null,"c":0,"en":{"q":"In New York, what must a teen bring to every road test to show the supervised hours?","o":["A Certification of Supervised Driving signed by a parent or guardian","A letter from a teacher","A copy of the learner permit test","Nothing, the DMV checks online"],"h1":"It is a DMV form that a parent signs.","h2":"A New York teen must bring a Certification of Supervised Driving, signed by a parent or guardian, each time they take the road test.","p":"Right. Bring the signed certification every time."},"es":{"q":"En Nueva York, ¿qué debe llevar un joven a cada examen de manejo para demostrar las horas supervisadas?","o":["Una Certificación de Manejo Supervisado firmada por un padre, madre o tutor","Una carta de un maestro","Una copia del examen del permiso","Nada, el DMV lo revisa en línea"],"h1":"Es un formulario del DMV que firma un padre.","h2":"En Nueva York, un joven debe llevar una Certificación de Manejo Supervisado, firmada por un padre, madre o tutor, cada vez que toma el examen de manejo.","p":"Correcto. Lleve la certificación firmada cada vez."},"ref":{"doc":"NY","page":14}},{"id":"ny-008","scope":"NY","cat":"licensing","sign":null,"c":2,"en":{"q":"In New York, how old must the supervising driver of a learner permit holder be?","o":["At least 16","At least 18","At least 21","At least 25"],"h1":"The supervisor must be old enough to drink alcohol legally.","h2":"In New York the supervising driver must be at least 21 and hold a valid license for the type of vehicle being driven.","p":"Right. The supervisor must be 21 or older."},"es":{"q":"En Nueva York, ¿qué edad debe tener el conductor que supervisa a quien tiene permiso de aprendiz?","o":["Por lo menos 16","Por lo menos 18","Por lo menos 21","Por lo menos 25"],"h1":"El supervisor debe tener edad para tomar alcohol legalmente.","h2":"En Nueva York, el conductor supervisor debe tener por lo menos 21 años y una licencia válida para el tipo de vehículo que se maneja.","p":"Correcto. El supervisor debe tener 21 años o más."},"ref":{"doc":"NY","page":11}},{"id":"ny-009","scope":"NY","cat":"licensing","sign":null,"c":1,"en":{"q":"In New York, how long must a teen hold the learner permit before taking the road test?","o":["At least one month","At least six months","At least three months","At least one year"],"h1":"It is half a year.","h2":"A New York teen must hold the learner permit for at least six months before taking the road test.","p":"Right. Hold the permit at least six months."},"es":{"q":"En Nueva York, ¿cuánto tiempo debe tener un joven el permiso de aprendiz antes del examen de manejo?","o":["Por lo menos un mes","Por lo menos seis meses","Por lo menos tres meses","Por lo menos un año"],"h1":"Es medio año.","h2":"En Nueva York, un joven debe tener el permiso de aprendiz por lo menos seis meses antes del examen de manejo.","p":"Correcto. Tenga el permiso por lo menos seis meses."},"ref":{"doc":"NY","page":14}},{"id":"ny-010","scope":"NY","cat":"licensing","sign":null,"c":3,"en":{"q":"In New York, who may sit in the front seat when a junior permit holder is driving?","o":["Any passenger over 16","Any family member","Anyone wearing a seat belt","Only the supervising driver"],"h1":"The seat beside the learner is saved for one person.","h2":"When a New York junior permit holder drives, no one may sit in the front seat except the supervising driver.","p":"Right. Only the supervisor sits in front."},"es":{"q":"En Nueva York, ¿quién puede ir en el asiento delantero cuando maneja alguien con permiso de aprendiz juvenil?","o":["Cualquier pasajero mayor de 16","Cualquier familiar","Cualquiera que use el cinturón","Solo el conductor supervisor"],"h1":"El asiento al lado del aprendiz es para una sola persona.","h2":"Cuando maneja en Nueva York alguien con permiso de aprendiz juvenil, nadie puede ir en el asiento delantero excepto el conductor supervisor.","p":"Correcto. Solo el supervisor va adelante."},"ref":{"doc":"NY","page":13}},{"id":"ny-011","scope":"NY","cat":"licensing","sign":null,"c":0,"en":{"q":"In New York City, when may a junior permit holder (under 18) never drive?","o":["Between 9 p.m. and 5 a.m.","Between midnight and 6 a.m.","Between 10 p.m. and 4 a.m.","Between 11 p.m. and 5 a.m."],"h1":"It starts at 9 in the evening.","h2":"A junior permit holder may never drive in the five boroughs of New York City between 9 p.m. and 5 a.m.","p":"Right. No junior permit driving in the city from 9 p.m. to 5 a.m."},"es":{"q":"En la ciudad de Nueva York, ¿en qué horario no puede manejar nunca quien tiene un permiso juvenil (menor de 18 años)?","o":["Entre las 9 p.m. y las 5 a.m.","Entre la medianoche y las 6 a.m.","Entre las 10 p.m. y las 4 a.m.","Entre las 11 p.m. y las 5 a.m."],"h1":"Empieza a las 9 de la noche.","h2":"Quien tiene un permiso juvenil nunca puede manejar en los cinco condados de la ciudad de Nueva York entre las 9 p.m. y las 5 a.m.","p":"Correcto. Con permiso juvenil no se maneja en la ciudad de 9 p.m. a 5 a.m."},"ref":{"doc":"NY","page":12}},{"id":"ny-012","scope":"NY","cat":"licensing","sign":null,"c":2,"en":{"q":"In New York City, what kind of car must a junior permit holder (under 18) use during the day?","o":["Any car with four doors","A car with automatic transmission","A car with dual controls","A car with a backup camera"],"h1":"The supervisor must be able to brake too.","h2":"In New York City a junior permit holder may drive during the day only in a car with dual controls, so the supervisor can brake too.","p":"Right. In the city, the car must have dual controls."},"es":{"q":"En la ciudad de Nueva York, ¿qué tipo de auto debe usar de día quien tiene un permiso juvenil (menor de 18 años)?","o":["Cualquier auto de cuatro puertas","Un auto con transmisión automática","Un auto con doble control","Un auto con cámara de reversa"],"h1":"El supervisor también debe poder frenar.","h2":"En la ciudad de Nueva York, quien tiene un permiso juvenil solo puede manejar de día en un auto con doble control, para que el supervisor también pueda frenar.","p":"Correcto. En la ciudad, el auto debe tener doble control."},"ref":{"doc":"NY","page":12}},{"id":"ny-013","scope":"NY","cat":"licensing","sign":null,"c":1,"en":{"q":"In New York, where may a junior license holder never drive?","o":["On Long Island","In New York City","On rural roads","In parking lots"],"h1":"It is the largest city in the state.","h2":"A New York junior license holder may not drive in New York City under any circumstances.","p":"Right. A junior license does not allow driving in New York City."},"es":{"q":"En Nueva York, ¿dónde nunca puede manejar quien tiene licencia juvenil?","o":["En Long Island","En la ciudad de Nueva York","En caminos rurales","En estacionamientos"],"h1":"Es la ciudad más grande del estado.","h2":"En Nueva York, quien tiene licencia juvenil no puede manejar en la ciudad de Nueva York bajo ninguna circunstancia.","p":"Correcto. La licencia juvenil no permite manejar en la ciudad de Nueva York."},"ref":{"doc":"NY","page":16}},{"id":"ny-014","scope":"NY","cat":"licensing","sign":null,"c":3,"en":{"q":"In New York, how many passengers under 21 who are not close family may a junior license holder carry without a supervisor?","o":["None at all","No more than two","No more than three","No more than one"],"h1":"It is the smallest number that is not zero.","h2":"A New York junior license holder driving without a supervisor may carry no more than one passenger under 21 who is not an immediate family member.","p":"Right. Only one passenger under 21 who is not family."},"es":{"q":"En Nueva York, ¿cuántos pasajeros menores de 21 años que no son familiares cercanos puede llevar sin supervisor quien tiene licencia juvenil?","o":["Ninguno","No más de dos","No más de tres","No más de uno"],"h1":"Es el número más pequeño que no es cero.","h2":"En Nueva York, quien tiene licencia juvenil y maneja sin supervisor puede llevar no más de un pasajero menor de 21 años que no sea familiar cercano.","p":"Correcto. Solo un pasajero menor de 21 que no sea familiar."},"ref":{"doc":"NY","page":15}},{"id":"ny-015","scope":"NY","cat":"licensing","sign":null,"c":0,"en":{"q":"In upstate New York (outside New York City and Long Island), between what hours may a junior license holder not drive alone, except straight between home and work or school?","o":["Between 9 p.m. and 5 a.m.","Between midnight and 6 a.m.","Between 11 p.m. and 5 a.m.","Between 10 p.m. and 6 a.m."],"h1":"It starts at 9 in the evening.","h2":"In upstate New York a junior license holder may not drive alone between 9 p.m. and 5 a.m., except straight between home and work or a school course.","p":"Right. Upstate, no driving alone from 9 p.m. to 5 a.m., except to work or school."},"es":{"q":"En el norte del estado de Nueva York (fuera de la ciudad de Nueva York y de Long Island), ¿en qué horario no puede manejar solo quien tiene licencia juvenil, salvo directo entre la casa y el trabajo o la escuela?","o":["Entre las 9 p.m. y las 5 a.m.","Entre la medianoche y las 6 a.m.","Entre las 11 p.m. y las 5 a.m.","Entre las 10 p.m. y las 6 a.m."],"h1":"Empieza a las 9 de la noche.","h2":"En el norte del estado de Nueva York, quien tiene licencia juvenil no puede manejar solo entre las 9 p.m. y las 5 a.m., salvo directo entre la casa y el trabajo o un curso escolar.","p":"Correcto. En el norte del estado no se maneja solo de 9 p.m. a 5 a.m., salvo al trabajo o la escuela."},"ref":{"doc":"NY","page":16}},{"id":"ny-016","scope":"NY","cat":"licensing","sign":null,"c":2,"en":{"q":"In New York, what course must most new drivers complete before the road test?","o":["A 1-hour online video","A 20-hour defensive driving course","A 5-hour pre-licensing course","A first aid course"],"h1":"It is a short classroom course of a few hours.","h2":"Most new drivers in New York must complete a 5-hour pre-licensing course before the road test, unless they finished a high school or college driver education program.","p":"Right. Most new drivers take the 5-hour course."},"es":{"q":"En Nueva York, ¿qué curso deben completar la mayoría de los conductores nuevos antes del examen de manejo?","o":["Un video en línea de 1 hora","Un curso de manejo defensivo de 20 horas","Un curso previo a la licencia de 5 horas","Un curso de primeros auxilios"],"h1":"Es un curso corto de pocas horas en un salón.","h2":"La mayoría de los conductores nuevos en Nueva York deben completar un curso previo a la licencia de 5 horas antes del examen de manejo, salvo que hayan terminado un programa de educación vial en la escuela secundaria o la universidad.","p":"Correcto. La mayoría toma el curso de 5 horas."},"ref":{"doc":"NY","page":8}},{"id":"ny-017","scope":"NY","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In New York, a school bus with flashing red lights is stopped on the other side of a divided highway. What must you do?","o":["Keep driving, because the highway is divided","Stop, even though you are on the other side","Slow down to 20 mph and pass","Honk and pass with care"],"h1":"In New York this rule has no exception for divided highways.","h2":"In New York you must stop for a school bus with flashing red lights even when it is on the other side of a divided highway.","p":"Right. In New York, traffic on both sides stops."},"es":{"q":"En Nueva York, un autobús escolar con luces rojas intermitentes está detenido al otro lado de una carretera dividida. ¿Qué debe hacer?","o":["Seguir manejando, porque la carretera está dividida","Detenerse, aunque usted esté del otro lado","Bajar a 20 mph y pasar","Tocar la bocina y pasar con cuidado"],"h1":"En Nueva York esta regla no tiene excepción para carreteras divididas.","h2":"En Nueva York usted debe detenerse ante un autobús escolar con luces rojas intermitentes aunque esté al otro lado de una carretera dividida.","p":"Correcto. En Nueva York se detiene el tráfico de los dos lados."},"ref":{"doc":"NY","page":40}},{"id":"ny-018","scope":"NY","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In New York, how far from a stopped school bus with flashing red lights should you stop?","o":["At least 5 feet","At least 10 feet","Right next to the bus","At least 20 feet"],"h1":"It is a bit more than the length of a car.","h2":"In New York you should stop at least 20 feet away from a school bus with flashing red lights.","p":"Right. Stay at least 20 feet back."},"es":{"q":"En Nueva York, ¿a qué distancia de un autobús escolar detenido con luces rojas intermitentes debe detenerse?","o":["Por lo menos a 5 pies","Por lo menos a 10 pies","Justo al lado del autobús","Por lo menos a 20 pies"],"h1":"Es un poco más que el largo de un auto.","h2":"En Nueva York usted debe detenerse por lo menos a 20 pies de un autobús escolar con luces rojas intermitentes.","p":"Correcto. Quédese por lo menos a 20 pies."},"ref":{"doc":"NY","page":40}},{"id":"ny-019","scope":"NY","cat":"signals","sign":null,"c":2,"en":{"q":"In New York City, may you turn right on a red light after a full stop?","o":["Yes, always after a full stop","Yes, but only at night","No, unless a sign says it is allowed","Yes, if no police officer is present"],"h1":"The city has the opposite rule from the rest of the state.","h2":"In New York City you may not turn right on a red light unless a sign says it is allowed.","p":"Right. No turn on red in the city without a sign."},"es":{"q":"En la ciudad de Nueva York, ¿puede dar vuelta a la derecha con la luz roja después de detenerse por completo?","o":["Sí, siempre después de detenerse","Sí, pero solo de noche","No, salvo que una señal lo permita","Sí, si no hay un policía"],"h1":"La ciudad tiene la regla contraria al resto del estado.","h2":"En la ciudad de Nueva York no puede dar vuelta a la derecha con la luz roja, salvo que una señal lo permita.","p":"Correcto. En la ciudad no se da vuelta con la luz roja sin una señal."},"ref":{"doc":"NY","page":31}},{"id":"ny-020","scope":"NY","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In New York, when must you turn on your headlights during the day?","o":["Whenever the weather makes you use your windshield wipers","Only inside tunnels","Only on highways","Never during the day"],"h1":"Think about rain, snow, sleet or fog.","h2":"New York law says you must turn on your headlights whenever the weather makes you use your windshield wipers, and daytime running lights do not count.","p":"Right. Wipers on, headlights on."},"es":{"q":"En Nueva York, ¿cuándo debe encender los faros durante el día?","o":["Siempre que el clima le obligue a usar los limpiaparabrisas","Solo dentro de los túneles","Solo en las autopistas","Nunca durante el día"],"h1":"Piense en lluvia, nieve, aguanieve o niebla.","h2":"La ley de Nueva York dice que debe encender los faros siempre que el clima le obligue a usar los limpiaparabrisas, y las luces de circulación diurna no cuentan.","p":"Correcto. Si usa los limpiaparabrisas, encienda los faros."},"ref":{"doc":"NY","page":63}},{"id":"ny-021","scope":"NY","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In New York State, outside New York City, what is the speed limit when no limit is posted?","o":["45 mph","60 mph","65 mph","55 mph"],"h1":"It is the same number used on many expressways in the state.","h2":"In New York State, when no speed limit is posted, you may not drive faster than 55 mph.","p":"Right. With no sign, the limit is 55 mph."},"es":{"q":"En el estado de Nueva York, fuera de la ciudad de Nueva York, ¿cuál es el límite de velocidad cuando no hay uno indicado?","o":["45 mph","60 mph","65 mph","55 mph"],"h1":"Es el mismo número de muchas autopistas del estado.","h2":"En el estado de Nueva York, cuando no hay un límite indicado, no puede manejar a más de 55 mph.","p":"Correcto. Sin señal, el límite es 55 mph."},"ref":{"doc":"NY","page":47}},{"id":"ny-022","scope":"NY","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In New York City, what is the speed limit when no other limit is posted?","o":["20 mph","25 mph","30 mph","35 mph"],"h1":"It is lower than the 30 mph used in many towns.","h2":"In New York City the speed limit is 25 mph unless a sign shows a different limit.","p":"Right. The city default is 25 mph."},"es":{"q":"En la ciudad de Nueva York, ¿cuál es el límite de velocidad cuando no hay otro indicado?","o":["20 mph","25 mph","30 mph","35 mph"],"h1":"Es más bajo que las 30 mph de muchos pueblos.","h2":"En la ciudad de Nueva York el límite de velocidad es 25 mph, salvo que una señal indique otro límite.","p":"Correcto. En la ciudad, el límite general es 25 mph."},"ref":{"doc":"NY","page":47}},{"id":"ny-023","scope":"NY","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In New York, on a parkway or expressway, the Move Over law also covers which stopped vehicles?","o":["Only police cars","Only ambulances and fire trucks","Any vehicle stopped on the shoulder or in the road","Only tow trucks"],"h1":"It is not only emergency vehicles.","h2":"On a New York parkway or expressway, the Move Over law covers any vehicle stopped on the shoulder or in the road, so you slow down and move over when it is safe.","p":"Right. On those roads it covers every stopped vehicle."},"es":{"q":"En Nueva York, en una autopista o parkway, ¿qué vehículos detenidos también cubre la ley de cambiar de carril (Move Over)?","o":["Solo las patrullas de policía","Solo las ambulancias y los camiones de bomberos","Cualquier vehículo detenido en el acotamiento o en el camino","Solo las grúas"],"h1":"No son solo los vehículos de emergencia.","h2":"En una autopista o parkway de Nueva York, la ley de cambiar de carril cubre cualquier vehículo detenido en el acotamiento o en el camino, así que usted baja la velocidad y se cambia de carril cuando sea seguro.","p":"Correcto. En esas vías cubre a todo vehículo detenido."},"ref":{"doc":"NY","page":35}},{"id":"ny-024","scope":"NY","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In New York, what blood alcohol level breaks the Zero Tolerance law for a driver under 21?","o":["0.02 to 0.07 percent","0.08 percent or more","Only 0.10 percent or more","Any level is legal under 21 with a permit"],"h1":"It starts at the smallest amount a test can reliably measure.","h2":"In New York a driver under 21 breaks the Zero Tolerance law with a blood alcohol level from 0.02 to 0.07 percent, and a higher level is a criminal charge.","p":"Right. Zero Tolerance covers 0.02 to 0.07 percent."},"es":{"q":"En Nueva York, ¿qué nivel de alcohol en la sangre viola la ley de Tolerancia Cero para un conductor menor de 21 años?","o":["De 0.02 a 0.07 por ciento","0.08 por ciento o más","Solo 0.10 por ciento o más","Con permiso, cualquier nivel es legal para menores de 21"],"h1":"Empieza en la cantidad más pequeña que una prueba puede medir con seguridad.","h2":"En Nueva York, un conductor menor de 21 años viola la ley de Tolerancia Cero con un nivel de alcohol en la sangre de 0.02 a 0.07 por ciento, y un nivel más alto es un delito.","p":"Correcto. Tolerancia Cero cubre de 0.02 a 0.07 por ciento."},"ref":{"doc":"NY","page":57}},{"id":"ny-025","scope":"NY","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In New York, what happens after a first Zero Tolerance violation by a driver under 21?","o":["Only a written warning","A 30-day suspension","A fine with no suspension","The license is suspended for six months"],"h1":"It is half a year without a license.","h2":"After a first Zero Tolerance violation in New York, the driver under 21 has the license suspended for six months.","p":"Right. A first violation means a six-month suspension."},"es":{"q":"En Nueva York, ¿qué pasa después de una primera violación de Tolerancia Cero de un conductor menor de 21 años?","o":["Solo una advertencia por escrito","Una suspensión de 30 días","Una multa sin suspensión","Le suspenden la licencia por seis meses"],"h1":"Es medio año sin licencia.","h2":"Después de una primera violación de Tolerancia Cero en Nueva York, al conductor menor de 21 años le suspenden la licencia por seis meses.","p":"Correcto. La primera violación trae una suspensión de seis meses."},"ref":{"doc":"NY","page":57}},{"id":"ny-026","scope":"NY","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In New York, Driving While Ability Impaired by alcohol (DWAI) starts at what blood alcohol level?","o":["More than 0.01 percent","More than 0.05 percent","More than 0.08 percent","More than 0.10 percent"],"h1":"It is below the 0.08 level for Driving While Intoxicated.","h2":"In New York, Driving While Ability Impaired by alcohol starts at a blood alcohol level of more than 0.05 percent, below the 0.08 percent level for Driving While Intoxicated.","p":"Right. DWAI starts above 0.05 percent."},"es":{"q":"En Nueva York, ¿a partir de qué nivel de alcohol en la sangre se considera manejar con la capacidad disminuida por alcohol (DWAI)?","o":["Más de 0.01 por ciento","Más de 0.05 por ciento","Más de 0.08 por ciento","Más de 0.10 por ciento"],"h1":"Está por debajo del nivel de 0.08 de manejar en estado de ebriedad.","h2":"En Nueva York, manejar con la capacidad disminuida por alcohol empieza con un nivel de alcohol en la sangre de más de 0.05 por ciento, por debajo del 0.08 por ciento de manejar en estado de ebriedad.","p":"Correcto. DWAI empieza con más de 0.05 por ciento."},"ref":{"doc":"NY","page":58}},{"id":"ny-027","scope":"NY","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In New York, what happens to a junior permit or license holder after a first conviction for using a phone or texting while driving?","o":["A warning letter only","A 30-day suspension","The permit or license is suspended for 120 days","Points only, with no suspension"],"h1":"It is about four months.","h2":"In New York, a first phone or texting conviction suspends a junior permit or license for 120 days.","p":"Right. A first conviction means a 120-day suspension."},"es":{"q":"En Nueva York, ¿qué le pasa a quien tiene permiso o licencia juvenil después de una primera condena por usar el teléfono o enviar mensajes mientras maneja?","o":["Solo una carta de advertencia","Una suspensión de 30 días","Le suspenden el permiso o la licencia por 120 días","Solo puntos, sin suspensión"],"h1":"Son unos cuatro meses.","h2":"En Nueva York, una primera condena por usar el teléfono o enviar mensajes suspende el permiso o la licencia juvenil por 120 días.","p":"Correcto. La primera condena trae una suspensión de 120 días."},"ref":{"doc":"NY","page":19}},{"id":"oh-001","scope":"OH","cat":"licensing","sign":null,"c":2,"en":{"q":"In Ohio, what is the youngest age to get a temporary instruction permit?","o":["14 years old","15 years old","15 and a half years old","16 years old"],"h1":"It is half a year before the probationary license age.","h2":"In Ohio you can get a temporary instruction permit at 15 and a half years old.","p":"Right. The Ohio permit starts at 15 and a half."},"es":{"q":"En Ohio, ¿cuál es la edad mínima para obtener un permiso temporal de aprendizaje?","o":["14 años","15 años","15 años y medio","16 años"],"h1":"Es medio año antes de la edad para la licencia probatoria.","h2":"En Ohio usted puede obtener un permiso temporal de aprendizaje a los 15 años y medio.","p":"Correcto. El permiso en Ohio empieza a los 15 años y medio."},"ref":{"doc":"OH","page":"§1"}},{"id":"oh-002","scope":"OH","cat":"licensing","sign":null,"c":0,"en":{"q":"In Ohio, how long is a temporary instruction permit valid?","o":["One year","Six months","Two years","Four years"],"h1":"It lasts long enough to cover the holding period twice.","h2":"In Ohio a temporary instruction permit is valid for one year.","p":"Right. The permit is valid for one year."},"es":{"q":"En Ohio, ¿por cuánto tiempo es válido un permiso temporal de aprendizaje?","o":["Un año","Seis meses","Dos años","Cuatro años"],"h1":"Dura lo suficiente para cubrir dos veces el período de espera.","h2":"En Ohio un permiso temporal de aprendizaje es válido por un año.","p":"Correcto. El permiso es válido por un año."},"ref":{"doc":"OH","page":null}},{"id":"oh-003","scope":"OH","cat":"licensing","sign":null,"c":1,"en":{"q":"In Ohio, how long must a teen hold a temporary instruction permit before getting a probationary license?","o":["One month","At least six months","At least one year","At least two years"],"h1":"It is half a year.","h2":"In Ohio a teen must hold a temporary instruction permit for at least six months before getting a probationary license.","p":"Right. Hold the permit at least six months."},"es":{"q":"En Ohio, ¿cuánto tiempo debe tener un joven el permiso temporal antes de obtener la licencia probatoria?","o":["Un mes","Por lo menos seis meses","Por lo menos un año","Por lo menos dos años"],"h1":"Es medio año.","h2":"En Ohio un joven debe tener el permiso temporal de aprendizaje por lo menos seis meses antes de obtener la licencia probatoria.","p":"Correcto. Debe tener el permiso por lo menos seis meses."},"ref":{"doc":"OH","page":"§1"}},{"id":"oh-004","scope":"OH","cat":"licensing","sign":null,"c":3,"en":{"q":"In Ohio, what is the youngest age to get a probationary driver's license?","o":["15","17","18","16"],"h1":"It is six months after the earliest permit age.","h2":"In Ohio you can get a probationary driver's license at 16, after holding a permit for at least six months.","p":"Right. The probationary license starts at 16."},"es":{"q":"En Ohio, ¿cuál es la edad mínima para obtener una licencia de conducir probatoria?","o":["15","17","18","16"],"h1":"Es seis meses después de la edad mínima para el permiso.","h2":"En Ohio usted puede obtener la licencia probatoria a los 16 años, después de tener el permiso por lo menos seis meses.","p":"Correcto. La licencia probatoria empieza a los 16."},"ref":{"doc":"OH","page":null}},{"id":"oh-005","scope":"OH","cat":"licensing","sign":null,"c":2,"en":{"q":"In Ohio, how many hours of supervised driving must a teen complete before a probationary license?","o":["20 hours","30 hours","50 hours","100 hours"],"h1":"It is half of one hundred.","h2":"In Ohio a teen must complete 50 hours of supervised driving before getting a probationary license.","p":"Right. 50 supervised hours."},"es":{"q":"En Ohio, ¿cuántas horas de manejo supervisado debe completar un joven antes de la licencia probatoria?","o":["20 horas","30 horas","50 horas","100 horas"],"h1":"Es la mitad de cien.","h2":"En Ohio un joven debe completar 50 horas de manejo supervisado antes de obtener la licencia probatoria.","p":"Correcto. 50 horas supervisadas."},"ref":{"doc":"OH","page":"§1"}},{"id":"oh-006","scope":"OH","cat":"licensing","sign":null,"c":0,"en":{"q":"In Ohio, how many of the supervised driving hours must be at night?","o":["10 hours","5 hours","15 hours","25 hours"],"h1":"It is one fifth of the total.","h2":"In Ohio 10 of the 50 supervised driving hours must be at night.","p":"Right. 10 hours at night."},"es":{"q":"En Ohio, ¿cuántas de las horas de manejo supervisado deben ser de noche?","o":["10 horas","5 horas","15 horas","25 horas"],"h1":"Es la quinta parte del total.","h2":"En Ohio 10 de las 50 horas de manejo supervisado deben ser de noche.","p":"Correcto. 10 horas de noche."},"ref":{"doc":"OH","page":"§1"}},{"id":"oh-007","scope":"OH","cat":"licensing","sign":null,"c":1,"en":{"q":"In Ohio, who certifies a teen's supervised driving hours?","o":["The driving test examiner","A parent or guardian, by signing an affidavit","A police officer","The teen alone"],"h1":"It is the adult responsible for the teen.","h2":"In Ohio a parent or guardian signs an affidavit that the teen completed the supervised hours, and lying on it can bring a fine or jail.","p":"Right. A parent or guardian signs for the hours."},"es":{"q":"En Ohio, ¿quién certifica las horas de manejo supervisado de un joven?","o":["El examinador de la prueba de manejo","Su padre, madre o tutor, firmando una declaración jurada","Un policía","El joven solo"],"h1":"Es el adulto responsable del joven.","h2":"En Ohio el padre, la madre o el tutor firma una declaración jurada de que el joven completó las horas supervisadas, y mentir en ella puede causar una multa o cárcel.","p":"Correcto. El padre, la madre o el tutor firma por las horas."},"ref":{"doc":"OH","page":null}},{"id":"oh-008","scope":"OH","cat":"licensing","sign":null,"c":3,"en":{"q":"In Ohio, during the first 12 months with a probationary license, when may a teen not drive unless a parent or guardian is along?","o":["9 p.m. to 6 a.m.","11 p.m. to 5 a.m.","1 a.m. to 5 a.m.","Midnight to 6 a.m."],"h1":"It starts at midnight.","h2":"In Ohio, during the first 12 months, a probationary driver may not drive from midnight to 6 a.m. unless a parent or guardian is in the car, with a few exceptions such as work or school.","p":"Right. Midnight to 6 a.m. in the first year."},"es":{"q":"En Ohio, durante los primeros 12 meses con licencia probatoria, ¿en qué horario no puede manejar un joven sin uno de sus padres o tutor?","o":["De 9 p.m. a 6 a.m.","De 11 p.m. a 5 a.m.","De 1 a.m. a 5 a.m.","De medianoche a 6 a.m."],"h1":"Empieza a la medianoche.","h2":"En Ohio, durante los primeros 12 meses, un conductor con licencia probatoria no puede manejar de medianoche a 6 a.m. sin su padre, madre o tutor en el carro, con algunas excepciones como el trabajo o la escuela.","p":"Correcto. De medianoche a 6 a.m. el primer año."},"ref":{"doc":"OH","page":"§12"}},{"id":"oh-009","scope":"OH","cat":"licensing","sign":null,"c":2,"en":{"q":"In Ohio, after holding a probationary license for 12 months, which hours are still restricted unless a parent or guardian is along?","o":["Midnight to 6 a.m.","11 p.m. to 5 a.m.","1 a.m. to 5 a.m.","No hours are restricted"],"h1":"The window becomes shorter at both ends.","h2":"In Ohio, after 12 months with a probationary license, a teen may not drive from 1 a.m. to 5 a.m. unless a parent or guardian is along.","p":"Right. After a year the limit is 1 a.m. to 5 a.m."},"es":{"q":"En Ohio, después de 12 meses con licencia probatoria, ¿qué horario sigue restringido sin uno de sus padres o tutor?","o":["De medianoche a 6 a.m.","De 11 p.m. a 5 a.m.","De 1 a.m. a 5 a.m.","Ningún horario"],"h1":"El horario se acorta por los dos lados.","h2":"En Ohio, después de 12 meses con licencia probatoria, un joven no puede manejar de 1 a.m. a 5 a.m. sin su padre, madre o tutor.","p":"Correcto. Después de un año el límite es de 1 a.m. a 5 a.m."},"ref":{"doc":"OH","page":"§12"}},{"id":"oh-010","scope":"OH","cat":"licensing","sign":null,"c":0,"en":{"q":"In Ohio, what must a probationary driver carry to drive to or from work during restricted night hours?","o":["Written documentation from the employer","A pay stub from last year","A note from a friend","Nothing; work is always allowed"],"h1":"It is a paper from the job.","h2":"In Ohio a probationary driver going to or from work during restricted hours must have written documentation from the employer with them.","p":"Right. Carry the paper from your employer."},"es":{"q":"En Ohio, ¿qué debe llevar un conductor con licencia probatoria para ir o volver del trabajo en el horario nocturno restringido?","o":["Un documento escrito del empleador","Un recibo de pago del año pasado","Una nota de un amigo","Nada; ir al trabajo siempre está permitido"],"h1":"Es un papel del trabajo.","h2":"En Ohio un conductor con licencia probatoria que va o vuelve del trabajo en el horario restringido debe llevar consigo un documento escrito del empleador.","p":"Correcto. Lleve el documento de su empleador."},"ref":{"doc":"OH","page":"§12"}},{"id":"oh-011","scope":"OH","cat":"licensing","sign":null,"c":1,"en":{"q":"In Ohio, during the first year with a probationary license, how many passengers who are not family may a teen carry without a parent or guardian?","o":["None","One","Two","Three"],"h1":"It is the smallest number above zero.","h2":"In Ohio, during the first year, a probationary driver may carry no more than one passenger who is not a family member, unless a parent or guardian is in the car.","p":"Right. Only one non-family passenger in the first year."},"es":{"q":"En Ohio, durante el primer año con licencia probatoria, ¿cuántos pasajeros que no son de la familia puede llevar un joven sin uno de sus padres o tutor?","o":["Ninguno","Uno","Dos","Tres"],"h1":"Es el número más pequeño después del cero.","h2":"En Ohio, durante el primer año, un conductor con licencia probatoria no puede llevar más de un pasajero que no sea de su familia, salvo que vaya su padre, madre o tutor.","p":"Correcto. Solo un pasajero que no es de la familia el primer año."},"ref":{"doc":"OH","page":"§12"}},{"id":"oh-012","scope":"OH","cat":"licensing","sign":null,"c":3,"en":{"q":"In Ohio, once a permit holder turns 16, who may supervise them while they drive?","o":["Any passenger over 16","Only a driving instructor","A licensed driver who is at least 18","A licensed driver who is at least 21, in the front passenger seat"],"h1":"The helper must be old enough to drink legally, and sit beside you.","h2":"In Ohio a permit holder who is 16 or older may drive with any licensed driver who is at least 21 and sits in the front passenger seat.","p":"Right. A licensed driver 21 or older beside you."},"es":{"q":"En Ohio, cuando quien tiene permiso cumple 16 años, ¿quién puede supervisarle al manejar?","o":["Cualquier pasajero mayor de 16","Solo un instructor de manejo","Un conductor con licencia de por lo menos 18 años","Un conductor con licencia de por lo menos 21 años, en el asiento del pasajero delantero"],"h1":"El acompañante debe tener edad para tomar alcohol legalmente, y sentarse a su lado.","h2":"En Ohio quien tiene permiso y tiene 16 años o más puede manejar con cualquier conductor con licencia de por lo menos 21 años que vaya en el asiento del pasajero delantero.","p":"Correcto. Un conductor con licencia de 21 años o más a su lado."},"ref":{"doc":"OH","page":"§1"}},{"id":"oh-013","scope":"OH","cat":"licensing","sign":null,"c":0,"en":{"q":"In Ohio, how many classroom hours of driver education must a teen complete?","o":["24 hours","8 hours","38 hours","50 hours"],"h1":"It is one full day of hours.","h2":"In Ohio a teen must complete 24 hours of driver education in the classroom, plus 8 hours of driving with an instructor.","p":"Right. 24 classroom hours."},"es":{"q":"En Ohio, ¿cuántas horas de clase de manejo debe completar un joven?","o":["24 horas","8 horas","38 horas","50 horas"],"h1":"Son las horas de un día completo.","h2":"En Ohio un joven debe completar 24 horas de clase de manejo, más 8 horas de manejo con un instructor.","p":"Correcto. 24 horas de clase."},"ref":{"doc":"OH","page":"§1"}},{"id":"oh-014","scope":"OH","cat":"licensing","sign":null,"c":2,"en":{"q":"In Ohio, how many hours of behind-the-wheel training with a driving instructor must a teen complete?","o":["2 hours","24 hours","8 hours","50 hours"],"h1":"It is one third of the classroom hours.","h2":"In Ohio a teen must complete 8 hours of behind-the-wheel training with a driving instructor.","p":"Right. 8 hours with an instructor."},"es":{"q":"En Ohio, ¿cuántas horas de práctica al volante con un instructor de manejo debe completar un joven?","o":["2 horas","24 horas","8 horas","50 horas"],"h1":"Es la tercera parte de las horas de clase.","h2":"En Ohio un joven debe completar 8 horas de práctica al volante con un instructor de manejo.","p":"Correcto. 8 horas con un instructor."},"ref":{"doc":"OH","page":"§1"}},{"id":"oh-015","scope":"OH","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Ohio, can police stop a driver only for holding a phone while driving?","o":["No, only if there is another violation","Yes, it is a primary offense","Only on interstates","Only at night"],"h1":"The law changed in April 2023 to make this stronger.","h2":"In Ohio, since April 4, 2023, using a hand-held phone while driving is a primary offense, so police can stop you for that alone.","p":"Right. Holding the phone is enough to be stopped."},"es":{"q":"En Ohio, ¿puede la policía detener a un conductor solo por tener el teléfono en la mano mientras maneja?","o":["No, solo si hay otra infracción","Sí, es una infracción principal","Solo en las autopistas interestatales","Solo de noche"],"h1":"La ley cambió en abril de 2023 para ser más fuerte.","h2":"En Ohio, desde el 4 de abril de 2023, usar el teléfono en la mano al manejar es una infracción principal, y la policía puede detenerle solo por eso.","p":"Correcto. Tener el teléfono en la mano basta para que le detengan."},"ref":{"doc":"OH","page":"§3"}},{"id":"oh-016","scope":"OH","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Ohio, how much may an adult driver touch a phone while driving, in most cases?","o":["As much as needed at a red light","Only to send short texts","Not at all, even to answer a call","A single touch or swipe"],"h1":"It is the smallest possible action.","h2":"In Ohio, in most cases, a driver may use only a single touch or swipe on a phone; anything more is against the law.","p":"Right. One touch or swipe at most."},"es":{"q":"En Ohio, en la mayoría de los casos, ¿cuánto puede tocar el teléfono un conductor adulto mientras maneja?","o":["Lo que necesite en un semáforo en rojo","Solo para enviar mensajes cortos","Nada, ni siquiera para contestar una llamada","Un solo toque o deslizamiento"],"h1":"Es la acción más pequeña posible.","h2":"En Ohio, en la mayoría de los casos, un conductor solo puede dar un toque o un deslizamiento en el teléfono; más que eso va contra la ley.","p":"Correcto. Un toque o deslizamiento como máximo."},"ref":{"doc":"OH","page":"§3"}},{"id":"oh-017","scope":"OH","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Ohio, what is the penalty for a first hand-held phone offense?","o":["Up to a $150 fine and 2 points, or a distracted driving course instead","A $25 fine","Loss of the license for one year","Only a warning, always"],"h1":"There is a choice between paying and learning.","h2":"In Ohio a first hand-held phone offense brings 2 points and a fine of up to $150, but a distracted driving course can let you avoid the fine and points.","p":"Right. Up to $150 and 2 points, or a distracted driving course."},"es":{"q":"En Ohio, ¿cuál es la sanción por la primera vez que se usa el teléfono en la mano al manejar?","o":["Una multa de hasta $150 y 2 puntos, o un curso sobre manejo distraído en su lugar","Una multa de $25","Perder la licencia por un año","Siempre solo una advertencia"],"h1":"Hay que elegir entre pagar o aprender.","h2":"En Ohio la primera infracción por usar el teléfono en la mano trae 2 puntos y una multa de hasta $150, pero un curso sobre manejo distraído le permite evitar la multa y los puntos.","p":"Correcto. Hasta $150 y 2 puntos, o un curso sobre manejo distraído."},"ref":{"doc":"OH","page":"§3"}},{"id":"oh-018","scope":"OH","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Ohio, which stopped vehicles with warning lights on must you move over for?","o":["Only police cars","Only ambulances and fire trucks","Police, emergency, tow, road crew and garbage trucks","Only tow trucks"],"h1":"The law covers more than police and fire. Think of road workers too.","h2":"In Ohio you must move one lane away from stopped police and emergency vehicles, tow trucks, road maintenance trucks and garbage trucks with warning lights on, or slow down if you cannot move over safely.","p":"Right. Emergency, tow, road crew and garbage trucks all count."},"es":{"q":"En Ohio, ¿ante qué vehículos detenidos con luces de advertencia encendidas debe cambiarse de carril?","o":["Solo patrullas de policía","Solo ambulancias y camiones de bomberos","Policía, emergencias, grúas, equipos de carreteras y camiones de basura","Solo grúas"],"h1":"La ley cubre más que la policía y los bomberos. Piense también en los trabajadores de carreteras.","h2":"En Ohio usted debe alejarse un carril de los vehículos de policía y emergencias, grúas, camiones de mantenimiento de carreteras y camiones de basura que estén detenidos con luces de advertencia, o bajar la velocidad si no puede cambiarse con seguridad.","p":"Correcto. Emergencias, grúas, equipos de carreteras y camiones de basura cuentan."},"ref":{"doc":"OH","page":"§9"}},{"id":"oh-019","scope":"OH","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Ohio, on a road with four or more lanes, who must stop for a school bus loading or unloading students?","o":["All traffic in both directions","Only traffic moving in the same direction as the bus","Only traffic coming toward the bus","No one"],"h1":"On a wide road, the bus lets students out only on the side where they live.","h2":"In Ohio, on a road with four or more lanes, only traffic moving in the same direction as the school bus must stop.","p":"Right. Only the same direction stops on four or more lanes."},"es":{"q":"En Ohio, en una carretera de cuatro carriles o más, ¿quién debe detenerse ante un autobús escolar que sube o baja estudiantes?","o":["Todo el tráfico en los dos sentidos","Solo el tráfico que va en el mismo sentido que el autobús","Solo el tráfico que viene hacia el autobús","Nadie"],"h1":"En una carretera ancha, el autobús deja a los estudiantes solo del lado donde viven.","h2":"En Ohio, en una carretera de cuatro carriles o más, solo el tráfico que va en el mismo sentido que el autobús escolar debe detenerse.","p":"Correcto. En cuatro carriles o más, solo se detiene el mismo sentido."},"ref":{"doc":"OH","page":"§5"}},{"id":"oh-020","scope":"OH","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Ohio, what is the legal blood alcohol limit for a driver under 21?","o":["0.08 percent","0.10 percent","0.04 percent","0.02 percent"],"h1":"It is much lower than the adult limit of 0.08.","h2":"In Ohio a driver under 21 breaks the law with a blood alcohol level of 0.02 percent or more.","p":"Right. For drivers under 21 the limit is 0.02."},"es":{"q":"En Ohio, ¿cuál es el límite legal de alcohol en la sangre para un conductor menor de 21?","o":["0.08 por ciento","0.10 por ciento","0.04 por ciento","0.02 por ciento"],"h1":"Es mucho más bajo que el límite de 0.08 para adultos.","h2":"En Ohio un conductor menor de 21 viola la ley con un nivel de alcohol en la sangre de 0.02 por ciento o más.","p":"Correcto. Para menores de 21 el límite es 0.02."},"ref":{"doc":"OH","page":"§6"}},{"id":"ok-001","scope":"OK","cat":"licensing","sign":null,"c":1,"en":{"q":"In Oklahoma, how many questions are on the written exam for a learner permit?","o":["10","20","30","50"],"h1":"It is a short test, fewer than in many states.","h2":"In Oklahoma, the written exam for a learner permit has 20 questions.","p":"Right. The Oklahoma written exam has 20 questions."},"es":{"q":"En Oklahoma, ¿cuántas preguntas tiene el examen escrito para el permiso de aprendiz?","o":["10","20","30","50"],"h1":"Es un examen corto, con menos preguntas que en muchos estados.","h2":"En Oklahoma, el examen escrito para el permiso de aprendiz tiene 20 preguntas.","p":"Correcto. El examen escrito de Oklahoma tiene 20 preguntas."},"ref":{"doc":"OK","page":null}},{"id":"ok-002","scope":"OK","cat":"licensing","sign":null,"c":3,"en":{"q":"In Oklahoma, what must a 15-year-old be doing to get a learner permit?","o":["Working a part-time job","Nothing extra; age is enough","Holding a high school diploma","Taking an approved driver education course"],"h1":"At 15 you are still learning in a class.","h2":"In Oklahoma, a 15-year-old must be enrolled in and taking an approved driver education course, and must pass the written exam, to get a learner permit.","p":"Right. At 15, driver education comes first."},"es":{"q":"En Oklahoma, ¿qué debe estar haciendo un joven de 15 años para obtener un permiso de aprendiz?","o":["Tener un trabajo de medio tiempo","Nada más; la edad es suficiente","Tener diploma de secundaria","Tomar un curso aprobado de educación vial"],"h1":"A los 15 años usted todavía está aprendiendo en una clase.","h2":"En Oklahoma, un joven de 15 años debe estar inscrito y tomando un curso aprobado de educación vial, y aprobar el examen escrito, para obtener el permiso de aprendiz.","p":"Correcto. A los 15, primero va la educación vial."},"ref":{"doc":"OK","page":6}},{"id":"ok-003","scope":"OK","cat":"licensing","sign":null,"c":0,"en":{"q":"In Oklahoma, is driver education required for a 16-year-old to get a learner permit?","o":["No, it is optional at 16","Yes, always","Yes, and you must pass the road test first","No, and you may drive alone right away"],"h1":"At 16 one requirement drops away.","h2":"In Oklahoma, driver education is optional at 16. You still pass the written exam, unless a finished driver education course lets you skip it.","p":"Right. At 16, driver education is optional."},"es":{"q":"En Oklahoma, ¿se requiere educación vial para que un joven de 16 años obtenga un permiso de aprendiz?","o":["No, es opcional a los 16","Sí, siempre","Sí, y primero debe aprobar el examen de manejo","No, y puede manejar solo de inmediato"],"h1":"A los 16 se quita un requisito.","h2":"En Oklahoma, la educación vial es opcional a los 16 años. Usted todavía debe aprobar el examen escrito, a menos que un curso de educación vial terminado le permita omitirlo.","p":"Correcto. A los 16, la educación vial es opcional."},"ref":{"doc":"OK","page":6}},{"id":"ok-004","scope":"OK","cat":"licensing","sign":null,"c":2,"en":{"q":"In Oklahoma, during which hours may a learner permit holder drive?","o":["Any time of day","6:00 a.m. to 9:00 p.m.","5:00 a.m. to 10:00 p.m.","Daylight hours only"],"h1":"The window starts very early and ends at ten.","h2":"In Oklahoma, a learner permit holder may drive between 5:00 in the morning and 10:00 at night, with a licensed driver at least 21 years old.","p":"Right. Oklahoma learners drive from 5 a.m. to 10 p.m."},"es":{"q":"En Oklahoma, ¿en qué horario puede manejar una persona con permiso de aprendiz?","o":["A cualquier hora","De 6:00 a.m. a 9:00 p.m.","De 5:00 a.m. a 10:00 p.m.","Solo con luz del día"],"h1":"El horario empieza muy temprano y termina a las diez.","h2":"En Oklahoma, quien tiene permiso de aprendiz puede manejar entre las 5:00 de la mañana y las 10:00 de la noche, con un conductor con licencia de por lo menos 21 años.","p":"Correcto. Los aprendices en Oklahoma manejan de 5 a.m. a 10 p.m."},"ref":{"doc":"OK","page":null}},{"id":"ok-005","scope":"OK","cat":"licensing","sign":null,"c":1,"en":{"q":"In Oklahoma, how old must the licensed driver with a learner permit holder be?","o":["At least 18","At least 21","At least 25","At least 30"],"h1":"The supervisor must be old enough to drink legally.","h2":"In Oklahoma, a learner permit holder must drive with a licensed driver who is at least 21 years old.","p":"Right. The supervisor must be 21 or older."},"es":{"q":"En Oklahoma, ¿qué edad debe tener el conductor con licencia que acompaña a quien tiene permiso de aprendiz?","o":["Por lo menos 18","Por lo menos 21","Por lo menos 25","Por lo menos 30"],"h1":"El supervisor debe tener edad para tomar alcohol legalmente.","h2":"En Oklahoma, quien tiene permiso de aprendiz debe manejar con un conductor con licencia de por lo menos 21 años.","p":"Correcto. El supervisor debe tener 21 años o más."},"ref":{"doc":"OK","page":6}},{"id":"ok-006","scope":"OK","cat":"licensing","sign":null,"c":3,"en":{"q":"In Oklahoma, how many hours of supervised driving must a teen complete before the intermediate license?","o":["20 hours, including 5 at night","30 hours, including 10 at night","60 hours, including 15 at night","50 hours, including 10 at night"],"h1":"It is half of one hundred, with 10 of them at night.","h2":"In Oklahoma, a teen must complete 50 hours of supervised driving, including 10 hours at night, before getting an intermediate license.","p":"Right. 50 hours, 10 at night."},"es":{"q":"En Oklahoma, ¿cuántas horas de manejo supervisado debe completar un joven antes de la licencia intermedia?","o":["20 horas, 5 de ellas de noche","30 horas, 10 de ellas de noche","60 horas, 15 de ellas de noche","50 horas, 10 de ellas de noche"],"h1":"Es la mitad de cien, con 10 de ellas de noche.","h2":"En Oklahoma, un joven debe completar 50 horas de manejo supervisado, 10 de ellas de noche, antes de obtener la licencia intermedia.","p":"Correcto. 50 horas, 10 de noche."},"ref":{"doc":"OK","page":null}},{"id":"ok-007","scope":"OK","cat":"licensing","sign":null,"c":0,"en":{"q":"In Oklahoma, how long must a teen hold a learner permit before getting an intermediate license?","o":["About 6 months (180 days)","30 days","1 year","2 years"],"h1":"It is half a year.","h2":"In Oklahoma, a teen must hold the learner permit for at least 180 days, about six months, before getting an intermediate license.","p":"Right. 180 days with the permit first."},"es":{"q":"En Oklahoma, ¿cuánto tiempo debe tener un joven el permiso de aprendiz antes de obtener la licencia intermedia?","o":["Unos 6 meses (180 días)","30 días","1 año","2 años"],"h1":"Es medio año.","h2":"En Oklahoma, un joven debe tener el permiso de aprendiz por lo menos 180 días, unos seis meses, antes de obtener la licencia intermedia.","p":"Correcto. Primero 180 días con el permiso."},"ref":{"doc":"OK","page":6}},{"id":"ok-008","scope":"OK","cat":"licensing","sign":null,"c":2,"en":{"q":"In Oklahoma, during which hours may an intermediate license holder not drive alone, unless an exception applies?","o":["Midnight to 5:00 a.m.","9:00 p.m. to 6:00 a.m.","10:00 p.m. to 5:00 a.m.","There is no night limit"],"h1":"It starts at the same hour the learner permit day ends.","h2":"In Oklahoma, an intermediate license holder may not drive alone between 10:00 at night and 5:00 in the morning, unless an exception such as work, school or church applies.","p":"Right. No solo driving from 10 p.m. to 5 a.m."},"es":{"q":"En Oklahoma, ¿en qué horario no puede manejar solo quien tiene licencia intermedia, salvo una excepción?","o":["De medianoche a 5:00 a.m.","De 9:00 p.m. a 6:00 a.m.","De 10:00 p.m. a 5:00 a.m.","No hay límite de noche"],"h1":"Empieza a la misma hora en que termina el día del permiso de aprendiz.","h2":"En Oklahoma, quien tiene licencia intermedia no puede manejar solo entre las 10:00 de la noche y las 5:00 de la mañana, salvo una excepción como trabajo, escuela o iglesia.","p":"Correcto. No se maneja solo de 10 p.m. a 5 a.m."},"ref":{"doc":"OK","page":14}},{"id":"ok-009","scope":"OK","cat":"licensing","sign":null,"c":1,"en":{"q":"In Oklahoma, how many passengers who do not live in the driver's home may an intermediate license holder carry, without a supervising driver?","o":["None","One","Two","Three"],"h1":"Think of one friend, not a carload.","h2":"In Oklahoma, an intermediate license holder may carry only one passenger who does not live in the driver's home, unless a licensed driver 21 or older sits in the front seat.","p":"Right. Only one passenger from outside the home."},"es":{"q":"En Oklahoma, ¿cuántos pasajeros que no viven en la casa del conductor puede llevar alguien con licencia intermedia, sin un conductor supervisor?","o":["Ninguno","Uno","Dos","Tres"],"h1":"Piense en un amigo, no en un carro lleno.","h2":"En Oklahoma, quien tiene licencia intermedia puede llevar solo un pasajero que no vive en su casa, a menos que un conductor con licencia de 21 años o más vaya en el asiento delantero.","p":"Correcto. Solo un pasajero de fuera de la casa."},"ref":{"doc":"OK","page":14}},{"id":"ok-010","scope":"OK","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Oklahoma, may a driver read or send a text message on a hand-held phone while driving?","o":["Yes, at a slow speed","Yes, on rural roads","Yes, if the message is short","No, it is against the law"],"h1":"Since 2015, the answer is the same for all drivers.","h2":"In Oklahoma, it is against the law to text on a hand-held phone while driving.","p":"Right. Texting while driving is against the law in Oklahoma."},"es":{"q":"En Oklahoma, ¿puede un conductor leer o enviar un mensaje de texto con el teléfono en la mano mientras maneja?","o":["Sí, a baja velocidad","Sí, en caminos rurales","Sí, si el mensaje es corto","No, es ilegal"],"h1":"Desde 2015, la respuesta es la misma para todos los conductores.","h2":"En Oklahoma, es ilegal enviar o leer mensajes de texto en un teléfono en la mano mientras maneja.","p":"Correcto. En Oklahoma es ilegal enviar mensajes de texto mientras maneja."},"ref":{"doc":"OK","page":61}},{"id":"ok-011","scope":"OK","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Oklahoma, what is the fine for a first violation of the Move Over law?","o":["$1,000","$50","$100","$250"],"h1":"Since late 2023 the fine is very high, with four digits.","h2":"In Oklahoma, a first violation of the Move Over law carries a fine of $1,000.","p":"Right. $1,000 for a first offense."},"es":{"q":"En Oklahoma, ¿cuál es la multa por una primera infracción de la ley Move Over (cámbiese de carril)?","o":["$1,000","$50","$100","$250"],"h1":"Desde finales de 2023 la multa es muy alta, de cuatro cifras.","h2":"En Oklahoma, una primera infracción de la ley Move Over tiene una multa de $1,000.","p":"Correcto. $1,000 por la primera infracción."},"ref":{"doc":"OK","page":null}},{"id":"ok-013","scope":"OK","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Oklahoma, a school bus stops with red lights flashing on a road with a median. What must traffic going the opposite way do?","o":["Stop until the lights go off","Keep moving with caution","Stop, then pass at once","Change lanes toward the bus"],"h1":"The median separates the two sides of the road.","h2":"In Oklahoma, when a road has a median, traffic going the opposite way from the school bus may keep moving with caution, while traffic going the same way must stop.","p":"Right. With a median, oncoming traffic may continue with care."},"es":{"q":"En Oklahoma, un autobús escolar se detiene con luces rojas intermitentes en una calle con camellón. ¿Qué debe hacer el tráfico que va en dirección contraria?","o":["Detenerse hasta que se apaguen las luces","Seguir con precaución","Detenerse y luego pasar de inmediato","Cambiarse de carril hacia el autobús"],"h1":"El camellón separa los dos lados de la calle.","h2":"En Oklahoma, cuando la calle tiene camellón, el tráfico que va en dirección contraria al autobús escolar puede seguir con precaución, y el que va en la misma dirección debe detenerse.","p":"Correcto. Con camellón, el tráfico de frente puede seguir con cuidado."},"ref":{"doc":"OK","page":30}},{"id":"or-001","scope":"OR","cat":"licensing","sign":null,"c":1,"en":{"q":"In Oregon, what is the youngest age to get an instruction permit?","o":["14 years old","15 years old","16 years old","17 years old"],"h1":"It is one year before the provisional license.","h2":"In Oregon you can get an instruction permit at 15.","p":"Right. The Oregon instruction permit starts at 15."},"es":{"q":"En Oregon, ¿cuál es la edad mínima para obtener el permiso de instrucción?","o":["14 años","15 años","16 años","17 años"],"h1":"Es un año antes de la licencia provisional.","h2":"En Oregon usted puede obtener el permiso de instrucción a los 15 años.","p":"Correcto. El permiso de instrucción en Oregon empieza a los 15."},"ref":{"doc":"OR","page":89}},{"id":"or-002","scope":"OR","cat":"licensing","sign":null,"c":2,"en":{"q":"In Oregon, how old must the licensed person beside a permit driver be?","o":["At least 16","At least 18","At least 21","At least 30"],"h1":"It is the age when an adult may legally buy alcohol.","h2":"An Oregon permit driver must have a licensed person who is at least 21 years old in the seat beside them.","p":"Right. The person beside you must be 21 or older."},"es":{"q":"En Oregon, ¿qué edad debe tener la persona con licencia que va al lado de un conductor con permiso?","o":["Por lo menos 16","Por lo menos 18","Por lo menos 21","Por lo menos 30"],"h1":"Es la edad en que un adulto ya puede comprar alcohol legalmente.","h2":"Un conductor con permiso en Oregon debe llevar al lado a una persona con licencia de por lo menos 21 años.","p":"Correcto. Su acompañante debe tener 21 años o más."},"ref":{"doc":"OR","page":90}},{"id":"or-003","scope":"OR","cat":"licensing","sign":null,"c":0,"en":{"q":"In Oregon, how long must the adult beside a permit driver have held a valid license?","o":["At least 3 years","At least 1 month","At least 10 years","At least 20 years"],"h1":"It is a few years, fewer than five.","h2":"In Oregon, the adult beside a permit driver must have held a valid license for at least 3 years.","p":"Right. Three years of license experience is required."},"es":{"q":"En Oregon, ¿cuánto tiempo debe haber tenido una licencia válida el adulto que va al lado de un conductor con permiso?","o":["Por lo menos 3 años","Por lo menos 1 mes","Por lo menos 10 años","Por lo menos 20 años"],"h1":"Son pocos años, menos de cinco.","h2":"En Oregon, el adulto que va al lado de un conductor con permiso debe haber tenido una licencia válida por lo menos 3 años.","p":"Correcto. Se requieren tres años con licencia."},"ref":{"doc":"OR","page":90}},{"id":"or-004","scope":"OR","cat":"licensing","sign":null,"c":3,"en":{"q":"In Oregon, how many supervised driving hours does a teen need if they took an approved driver education course?","o":["20 hours","30 hours","100 hours","50 hours"],"h1":"It is half of what a teen without the course needs.","h2":"An Oregon teen who completes an approved driver education course needs 50 hours of supervised driving.","p":"Right. With driver education, Oregon asks for 50 hours."},"es":{"q":"En Oregon, ¿cuántas horas de manejo supervisado necesita un adolescente que tomó un curso aprobado de educación vial?","o":["20 horas","30 horas","100 horas","50 horas"],"h1":"Es la mitad de lo que necesita un adolescente sin el curso.","h2":"Un adolescente en Oregon que termina un curso aprobado de educación vial necesita 50 horas de manejo supervisado.","p":"Correcto. Con educación vial, Oregon pide 50 horas."},"ref":{"doc":"OR","page":90}},{"id":"or-005","scope":"OR","cat":"licensing","sign":null,"c":2,"en":{"q":"In Oregon, how many supervised driving hours does a teen need without a driver education course?","o":["50 hours","70 hours","100 hours","150 hours"],"h1":"It is twice the number needed with the course.","h2":"An Oregon teen who does not take an approved driver education course needs 100 hours of supervised driving.","p":"Right. Without driver education, Oregon asks for 100 hours."},"es":{"q":"En Oregon, ¿cuántas horas de manejo supervisado necesita un adolescente sin curso de educación vial?","o":["50 horas","70 horas","100 horas","150 horas"],"h1":"Es el doble de lo que se necesita con el curso.","h2":"Un adolescente en Oregon que no toma un curso aprobado de educación vial necesita 100 horas de manejo supervisado.","p":"Correcto. Sin educación vial, Oregon pide 100 horas."},"ref":{"doc":"OR","page":90}},{"id":"or-006","scope":"OR","cat":"licensing","sign":null,"c":1,"en":{"q":"In Oregon, how long must a teen hold an instruction permit before getting a provisional license?","o":["1 month","6 months","2 years","No minimum time"],"h1":"It is half a year.","h2":"An Oregon teen must hold the instruction permit for at least 6 months before getting a provisional license.","p":"Right. Six months with the permit first."},"es":{"q":"En Oregon, ¿cuánto tiempo debe tener un adolescente el permiso de instrucción antes de obtener la licencia provisional?","o":["1 mes","6 meses","2 años","No hay tiempo mínimo"],"h1":"Es medio año.","h2":"Un adolescente en Oregon debe tener el permiso de instrucción por lo menos 6 meses antes de obtener la licencia provisional.","p":"Correcto. Primero, seis meses con el permiso."},"ref":{"doc":"OR","page":90}},{"id":"or-007","scope":"OR","cat":"licensing","sign":null,"c":0,"en":{"q":"In Oregon, during the first 6 months of a provisional license, who may ride as a passenger under age 20?","o":["Only immediate family members","Up to three friends","Any one friend","Anyone with a seat belt"],"h1":"Think of the people you live with.","h2":"During the first 6 months of an Oregon provisional license, passengers under 20 must be immediate family members.","p":"Right. Only family under 20 at first."},"es":{"q":"En Oregon, durante los primeros 6 meses de la licencia provisional, ¿quién puede viajar como pasajero menor de 20 años?","o":["Solo familiares directos","Hasta tres amigos","Un amigo cualquiera","Cualquiera con cinturón"],"h1":"Piense en las personas con quienes vive.","h2":"Durante los primeros 6 meses de la licencia provisional de Oregon, los pasajeros menores de 20 años deben ser familiares directos.","p":"Correcto. Al principio, solo familiares menores de 20."},"ref":{"doc":"OR","page":null}},{"id":"or-008","scope":"OR","cat":"licensing","sign":null,"c":2,"en":{"q":"In Oregon, during the second 6 months of a provisional license, how many passengers under 20 who are not family may ride along?","o":["None","One","No more than three","No limit"],"h1":"The limit loosens, but there is still a limit.","h2":"During the second 6 months of an Oregon provisional license, the driver may carry no more than three passengers under 20 who are not family.","p":"Right. Up to three in the second six months."},"es":{"q":"En Oregon, durante los segundos 6 meses de la licencia provisional, ¿cuántos pasajeros menores de 20 años que no son familiares pueden viajar?","o":["Ninguno","Uno","No más de tres","Sin límite"],"h1":"El límite se afloja, pero todavía hay un límite.","h2":"Durante los segundos 6 meses de la licencia provisional de Oregon, el conductor puede llevar como máximo tres pasajeros menores de 20 años que no son familiares.","p":"Correcto. Hasta tres en los segundos seis meses."},"ref":{"doc":"OR","page":null}},{"id":"or-009","scope":"OR","cat":"licensing","sign":null,"c":3,"en":{"q":"In Oregon, during which hours may a provisional driver in the first year not drive, unless an exception applies?","o":["9 p.m. to 6 a.m.","10 p.m. to 5 a.m.","11 p.m. to 4 a.m.","Midnight to 5 a.m."],"h1":"It starts at the very start of a new day.","h2":"In the first year, an Oregon provisional driver may not drive from midnight to 5 a.m. unless an exception applies.","p":"Right. Midnight to 5 a.m. is off limits."},"es":{"q":"En Oregon, ¿en qué horario no puede manejar un conductor provisional en su primer año, salvo una excepción?","o":["De 9 p.m. a 6 a.m.","De 10 p.m. a 5 a.m.","De 11 p.m. a 4 a.m.","De medianoche a 5 a.m."],"h1":"Empieza justo al comienzo de un nuevo día.","h2":"En el primer año, un conductor provisional en Oregon no puede manejar de medianoche a 5 a.m., salvo una excepción.","p":"Correcto. De medianoche a 5 a.m. no se maneja."},"ref":{"doc":"OR","page":null}},{"id":"or-010","scope":"OR","cat":"licensing","sign":null,"c":1,"en":{"q":"In Oregon, a provisional driver may drive between midnight and 5 a.m. when riding with a licensed driver of what age?","o":["At least 18","At least 25","At least 21","At least 65"],"h1":"It is older than the usual permit supervisor.","h2":"An Oregon provisional driver may drive between midnight and 5 a.m. when a licensed driver who is at least 25 years old is along.","p":"Right. A licensed driver 25 or older makes it allowed."},"es":{"q":"En Oregon, un conductor provisional puede manejar entre medianoche y 5 a.m. si lo acompaña un conductor con licencia de ¿qué edad?","o":["Por lo menos 18","Por lo menos 25","Por lo menos 21","Por lo menos 65"],"h1":"Es mayor que la edad del supervisor normal del permiso.","h2":"Un conductor provisional en Oregon puede manejar entre medianoche y 5 a.m. si va con un conductor con licencia de por lo menos 25 años.","p":"Correcto. Con un conductor de 25 años o más, está permitido."},"ref":{"doc":"OR","page":null}},{"id":"or-011","scope":"OR","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Oregon, may a driver under 18 talk on a cell phone with a hands-free device?","o":["No, not even hands-free","Yes, hands-free is always allowed","Yes, but only on highways","Yes, but only during the day"],"h1":"The rule for teens is stricter than for adults.","h2":"In Oregon, a driver under 18 may not use a cell phone while driving, not even with a hands-free device.","p":"Right. No phone at all for drivers under 18."},"es":{"q":"En Oregon, ¿puede un conductor menor de 18 años hablar por celular con un dispositivo de manos libres?","o":["No, ni siquiera con manos libres","Sí, manos libres siempre está permitido","Sí, pero solo en autopistas","Sí, pero solo de día"],"h1":"La regla para adolescentes es más estricta que para adultos.","h2":"En Oregon, un conductor menor de 18 años no puede usar el celular mientras maneja, ni siquiera con un dispositivo de manos libres.","p":"Correcto. Nada de teléfono para menores de 18."},"ref":{"doc":"OR","page":80}},{"id":"or-012","scope":"OR","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Oregon, you approach a stopped emergency vehicle with lights flashing and cannot change lanes safely. What must you do?","o":["Keep your speed","Stop in your lane","Slow to at least 5 mph below the posted speed","Speed up to pass quickly"],"h1":"You must lower your speed by a set amount.","h2":"In Oregon, if you cannot safely move over, you must slow to at least 5 mph below the posted speed.","p":"Right. Slow down at least 5 mph below the limit."},"es":{"q":"En Oregon, usted se acerca a un vehículo de emergencia detenido con luces encendidas y no puede cambiar de carril con seguridad. ¿Qué debe hacer?","o":["Mantener su velocidad","Detenerse en su carril","Bajar a por lo menos 5 mph menos que la velocidad indicada","Acelerar para pasar rápido"],"h1":"Debe bajar su velocidad una cantidad fija.","h2":"En Oregon, si no puede cambiarse de carril con seguridad, debe bajar a por lo menos 5 mph menos que la velocidad indicada.","p":"Correcto. Baje por lo menos 5 mph del límite."},"ref":{"doc":"OR","page":null}},{"id":"or-013","scope":"OR","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Oregon, for which stopped vehicles on the shoulder must you move over or slow down?","o":["Only police cars","Only ambulances","Only tow trucks","Any vehicle showing hazard lights, flares or an emergency sign"],"h1":"The law was expanded to cover more than emergency vehicles.","h2":"In Oregon, you must move over or slow down for any vehicle stopped on the shoulder that shows hazard lights, flares or an emergency sign.","p":"Right. The rule covers any stopped vehicle with warning signs."},"es":{"q":"En Oregon, ¿por cuáles vehículos detenidos en el acotamiento debe cambiarse de carril o bajar la velocidad?","o":["Solo patrullas de policía","Solo ambulancias","Solo grúas","Cualquier vehículo con luces de emergencia, bengalas o un letrero de emergencia"],"h1":"La ley se amplió para incluir más que vehículos de emergencia.","h2":"En Oregon, debe cambiarse de carril o bajar la velocidad por cualquier vehículo detenido en el acotamiento que tenga luces de emergencia, bengalas o un letrero de emergencia.","p":"Correcto. La regla incluye cualquier vehículo detenido con señales de aviso."},"ref":{"doc":"OR","page":null}},{"id":"or-014","scope":"OR","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Oregon, what is the speed limit in a business district when no other limit is posted?","o":["20 mph","25 mph","30 mph","35 mph"],"h1":"It is the same as in a school zone.","h2":"In Oregon, the speed limit in a business district is 20 mph unless another limit is posted.","p":"Right. Business districts are 20 mph."},"es":{"q":"En Oregon, ¿cuál es el límite de velocidad en una zona comercial cuando no hay otro límite indicado?","o":["20 mph","25 mph","30 mph","35 mph"],"h1":"Es igual que en una zona escolar.","h2":"En Oregon, el límite de velocidad en una zona comercial es 20 mph, salvo que haya otro límite indicado.","p":"Correcto. Las zonas comerciales son de 20 mph."},"ref":{"doc":"OR","page":19}},{"id":"or-015","scope":"OR","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Oregon, what is the speed limit in a residential district when no other limit is posted?","o":["15 mph","25 mph","35 mph","45 mph"],"h1":"It is a little faster than a business district.","h2":"In Oregon, the speed limit in a residential district is 25 mph unless another limit is posted.","p":"Right. Residential districts are 25 mph."},"es":{"q":"En Oregon, ¿cuál es el límite de velocidad en una zona residencial cuando no hay otro límite indicado?","o":["15 mph","25 mph","35 mph","45 mph"],"h1":"Es un poco más rápido que en una zona comercial.","h2":"En Oregon, el límite de velocidad en una zona residencial es 25 mph, salvo que haya otro límite indicado.","p":"Correcto. Las zonas residenciales son de 25 mph."},"ref":{"doc":"OR","page":19}},{"id":"or-016","scope":"OR","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Oregon, what is the speed limit in an alley?","o":["25 mph","20 mph","15 mph","5 mph"],"h1":"It is the slowest of the usual city limits.","h2":"In Oregon, the speed limit in an alley is 15 mph.","p":"Right. Alleys are 15 mph."},"es":{"q":"En Oregon, ¿cuál es el límite de velocidad en un callejón?","o":["25 mph","20 mph","15 mph","5 mph"],"h1":"Es el más lento de los límites comunes de la ciudad.","h2":"En Oregon, el límite de velocidad en un callejón es 15 mph.","p":"Correcto. Los callejones son de 15 mph."},"ref":{"doc":"OR","page":19}},{"id":"or-017","scope":"OR","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Oregon, how much alcohol may a driver under 21 have in their body?","o":["Up to 0.08 percent","Up to 0.05 percent","Up to 0.02 percent","None at all"],"h1":"Oregon has zero tolerance for young drivers.","h2":"In Oregon, a driver under 21 may not drive with any amount of alcohol in their body.","p":"Right. Under 21, no alcohol at all."},"es":{"q":"En Oregon, ¿cuánto alcohol puede tener en el cuerpo un conductor menor de 21 años?","o":["Hasta 0.08 por ciento","Hasta 0.05 por ciento","Hasta 0.02 por ciento","Nada"],"h1":"Oregon tiene tolerancia cero para los conductores jóvenes.","h2":"En Oregon, un conductor menor de 21 años no puede manejar con ninguna cantidad de alcohol en el cuerpo.","p":"Correcto. Menores de 21, nada de alcohol."},"ref":{"doc":"OR","page":83}},{"id":"pa-001","scope":"PA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Pennsylvania, what is the youngest age to apply for a learner's permit?","o":["14 years old","15 years old","16 years old","17 years old"],"h1":"It is later than in many other states.","h2":"In Pennsylvania you can apply for a learner's permit once you turn 16, with a parent or guardian's consent.","p":"Right. The Pennsylvania permit starts at 16."},"es":{"q":"En Pensilvania, ¿cuál es la edad mínima para solicitar el permiso de aprendiz?","o":["14 años","15 años","16 años","17 años"],"h1":"Es más tarde que en muchos otros estados.","h2":"En Pensilvania usted puede solicitar el permiso de aprendiz al cumplir 16 años, con el consentimiento de su padre, madre o tutor.","p":"Correcto. El permiso en Pensilvania empieza a los 16."},"ref":{"doc":"PA","page":1}},{"id":"pa-002","scope":"PA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Pennsylvania, how many questions are on the learner's permit knowledge test?","o":["10 questions","18 questions","25 questions","50 questions"],"h1":"It is fewer than 20.","h2":"The Pennsylvania knowledge test has 18 multiple-choice questions.","p":"Right. The test has 18 questions."},"es":{"q":"En Pensilvania, ¿cuántas preguntas tiene el examen de conocimientos para el permiso de aprendiz?","o":["10 preguntas","18 preguntas","25 preguntas","50 preguntas"],"h1":"Son menos de 20.","h2":"El examen de conocimientos de Pensilvania tiene 18 preguntas de opción múltiple.","p":"Correcto. El examen tiene 18 preguntas."},"ref":{"doc":"PA","page":5}},{"id":"pa-003","scope":"PA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Pennsylvania, how many questions must you answer correctly to pass the knowledge test?","o":["9","12","18","15"],"h1":"You may miss only three.","h2":"To pass the Pennsylvania knowledge test you must answer 15 of the 18 questions correctly.","p":"Right. You need 15 correct answers."},"es":{"q":"En Pensilvania, ¿cuántas preguntas debe contestar bien para aprobar el examen de conocimientos?","o":["9","12","18","15"],"h1":"Solo puede fallar tres.","h2":"Para aprobar el examen de conocimientos de Pensilvania debe contestar bien 15 de las 18 preguntas.","p":"Correcto. Necesita 15 respuestas correctas."},"ref":{"doc":"PA","page":5}},{"id":"pa-004","scope":"PA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Pennsylvania, if you are under 18, how long must you wait after getting your learner's permit before taking the road test?","o":["Six months","One month","Three months","Two years"],"h1":"It is half a year.","h2":"In Pennsylvania a driver under 18 may not take the road test until six months after receiving the learner's permit.","p":"Right. Wait six months."},"es":{"q":"En Pensilvania, si usted es menor de 18 años, ¿cuánto tiempo debe esperar después de obtener el permiso de aprendiz para hacer el examen de manejo?","o":["Seis meses","Un mes","Tres meses","Dos años"],"h1":"Es medio año.","h2":"En Pensilvania un conductor menor de 18 años no puede hacer el examen de manejo hasta seis meses después de recibir el permiso de aprendiz.","p":"Correcto. Debe esperar seis meses."},"ref":{"doc":"PA","page":2}},{"id":"pa-005","scope":"PA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Pennsylvania, how many hours of supervised behind-the-wheel practice must a driver under 18 complete before the road test?","o":["30 hours","50 hours","65 hours","100 hours"],"h1":"It is more than 60 and less than 70.","h2":"In Pennsylvania a driver under 18 must complete at least 65 hours of supervised behind-the-wheel practice before the road test.","p":"Right. Pennsylvania asks for 65 hours."},"es":{"q":"En Pensilvania, ¿cuántas horas de práctica supervisada al volante debe completar un conductor menor de 18 años antes del examen de manejo?","o":["30 horas","50 horas","65 horas","100 horas"],"h1":"Son más de 60 y menos de 70.","h2":"En Pensilvania un conductor menor de 18 años debe completar por lo menos 65 horas de práctica supervisada al volante antes del examen de manejo.","p":"Correcto. Pensilvania pide 65 horas."},"ref":{"doc":"PA","page":2}},{"id":"pa-006","scope":"PA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Pennsylvania, how many of the 65 practice hours must be driven at night?","o":["5 hours","10 hours","20 hours","30 hours"],"h1":"It is twice the number of bad-weather hours.","h2":"Of the 65 practice hours in Pennsylvania, at least 10 must be nighttime driving.","p":"Right. At least 10 hours at night."},"es":{"q":"En Pensilvania, ¿cuántas de las 65 horas de práctica deben ser de noche?","o":["5 horas","10 horas","20 horas","30 horas"],"h1":"Es el doble de las horas con mal tiempo.","h2":"De las 65 horas de práctica en Pensilvania, por lo menos 10 deben ser de manejo nocturno.","p":"Correcto. Por lo menos 10 horas de noche."},"ref":{"doc":"PA","page":2}},{"id":"pa-007","scope":"PA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Pennsylvania, how many of the 65 practice hours must be driven in bad weather?","o":["None","1 hour","15 hours","5 hours"],"h1":"It is half the number of night hours.","h2":"Of the 65 practice hours in Pennsylvania, at least 5 must be driven in bad weather, such as rain, snow or fog.","p":"Right. At least 5 hours in bad weather."},"es":{"q":"En Pensilvania, ¿cuántas de las 65 horas de práctica deben ser con mal tiempo?","o":["Ninguna","1 hora","15 horas","5 horas"],"h1":"Es la mitad de las horas de noche.","h2":"De las 65 horas de práctica en Pensilvania, por lo menos 5 deben ser con mal tiempo, como lluvia, nieve o niebla.","p":"Correcto. Por lo menos 5 horas con mal tiempo."},"ref":{"doc":"PA","page":2}},{"id":"pa-008","scope":"PA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Pennsylvania, who signs the form saying a teen finished the 65 hours of practice?","o":["A parent or guardian","The teen alone","A friend from school","Nobody; no form is needed"],"h1":"It is the adult responsible for the teen.","h2":"In Pennsylvania a parent or guardian signs the certification form saying the teen completed the 65 hours of supervised driving.","p":"Right. A parent or guardian signs it."},"es":{"q":"En Pensilvania, ¿quién firma el formulario que dice que un adolescente completó las 65 horas de práctica?","o":["Un padre, madre o tutor","El adolescente solo","Un amigo de la escuela","Nadie; no hace falta formulario"],"h1":"Es el adulto responsable del adolescente.","h2":"En Pensilvania un padre, madre o tutor firma el formulario de certificación que dice que el adolescente completó las 65 horas de manejo supervisado.","p":"Correcto. Lo firma un padre, madre o tutor."},"ref":{"doc":"PA","page":5}},{"id":"pa-009","scope":"PA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Pennsylvania, during which hours may a junior license holder not drive, unless a parent, guardian or spouse 18 or older is in the car?","o":["9 p.m. to 6 a.m.","Midnight to 6 a.m.","11 p.m. to 5 a.m.","10 p.m. to 4 a.m."],"h1":"It starts one hour before midnight.","h2":"In Pennsylvania a junior license holder may not drive between 11 p.m. and 5 a.m. unless a parent, guardian or spouse 18 or older is with them, or an exception applies.","p":"Right. Not from 11 p.m. to 5 a.m."},"es":{"q":"En Pensilvania, ¿en qué horario no puede manejar el titular de una licencia junior, a menos que vaya con él su padre, madre, tutor o cónyuge de 18 años o más?","o":["De 9 p.m. a 6 a.m.","De medianoche a 6 a.m.","De 11 p.m. a 5 a.m.","De 10 p.m. a 4 a.m."],"h1":"Empieza una hora antes de la medianoche.","h2":"En Pensilvania el titular de una licencia junior no puede manejar entre las 11 p.m. y las 5 a.m., a menos que vaya con él su padre, madre, tutor o cónyuge de 18 años o más, o que se aplique una excepción.","p":"Correcto. No de 11 p.m. a 5 a.m."},"ref":{"doc":"PA","page":3}},{"id":"pa-010","scope":"PA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Pennsylvania, which reason lets a junior license holder drive alone between 11 p.m. and 5 a.m.?","o":["Working during those hours, with proper documentation","Visiting friends","Going out to eat","Driving to practice for the road test"],"h1":"It is a duty, not a social outing.","h2":"A Pennsylvania junior license holder may drive between 11 p.m. and 5 a.m. for a job, public or charitable service, or a volunteer fire company, carrying proper documentation.","p":"Right. Work or volunteer service is an exception."},"es":{"q":"En Pensilvania, ¿qué razón permite que el titular de una licencia junior maneje solo entre las 11 p.m. y las 5 a.m.?","o":["Trabajar en ese horario, con la documentación correcta","Visitar a amigos","Salir a comer","Practicar para el examen de manejo"],"h1":"Es una obligación, no una salida social.","h2":"El titular de una licencia junior en Pensilvania puede manejar entre las 11 p.m. y las 5 a.m. por su trabajo, por servicio público o caritativo, o como bombero voluntario, si lleva la documentación correcta.","p":"Correcto. El trabajo o el voluntariado son una excepción."},"ref":{"doc":"PA","page":3}},{"id":"pa-011","scope":"PA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Pennsylvania, during the first six months with a junior license, how many passengers under 18 who are not immediate family may ride with the driver?","o":["None","One","Two","Three"],"h1":"It is the smallest number above zero.","h2":"During the first six months with a Pennsylvania junior license, the driver may carry only one passenger under 18 who is not immediate family, unless a parent or guardian is in the car.","p":"Right. Only one non-family passenger under 18."},"es":{"q":"En Pensilvania, durante los primeros seis meses con licencia junior, ¿cuántos pasajeros menores de 18 años que no son familia inmediata pueden ir con el conductor?","o":["Ninguno","Uno","Dos","Tres"],"h1":"Es el número más pequeño mayor que cero.","h2":"Durante los primeros seis meses con licencia junior en Pensilvania, el conductor solo puede llevar un pasajero menor de 18 años que no sea familia inmediata, a menos que vaya su padre, madre o tutor.","p":"Correcto. Solo un pasajero menor de 18 que no es familia."},"ref":{"doc":"PA","page":4}},{"id":"pa-012","scope":"PA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Pennsylvania, after six months with a junior license and a clean record, how many passengers under 18 who are not family may ride with the driver?","o":["One","Two","Any number","Three"],"h1":"The limit goes up, but there is still a limit.","h2":"After six months with a Pennsylvania junior license, with no at-fault crash and no driving conviction, the limit rises to three passengers under 18 who are not family.","p":"Right. The limit rises to three."},"es":{"q":"En Pensilvania, después de seis meses con licencia junior y un historial limpio, ¿cuántos pasajeros menores de 18 años que no son familia pueden ir con el conductor?","o":["Uno","Dos","Cualquier cantidad","Tres"],"h1":"El límite sube, pero todavía hay un límite.","h2":"Después de seis meses con licencia junior en Pensilvania, sin choques por su culpa y sin condenas de tránsito, el límite sube a tres pasajeros menores de 18 años que no sean familia.","p":"Correcto. El límite sube a tres."},"ref":{"doc":"PA","page":4}},{"id":"pa-013","scope":"PA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Pennsylvania, what is the most passengers a junior license holder may ever carry?","o":["Five, in any car","As many as fit","No more than the number of seat belts in the car","Two"],"h1":"Every passenger needs something to wear.","h2":"In Pennsylvania a junior driver may never carry more passengers than there are seat belts in the vehicle.","p":"Right. No more passengers than seat belts."},"es":{"q":"En Pensilvania, ¿cuál es el número máximo de pasajeros que puede llevar el titular de una licencia junior?","o":["Cinco, en cualquier carro","Todos los que quepan","No más que la cantidad de cinturones de seguridad del carro","Dos"],"h1":"Cada pasajero necesita algo que ponerse.","h2":"En Pensilvania un conductor con licencia junior nunca puede llevar más pasajeros que cinturones de seguridad tiene el vehículo.","p":"Correcto. No más pasajeros que cinturones."},"ref":{"doc":"PA","page":3}},{"id":"pa-014","scope":"PA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Pennsylvania, when does the junior license limit on passengers under 18 not apply?","o":["When a parent or legal guardian is in the car","On weekends","When driving under 25 mph","When the passengers are 17"],"h1":"Think about which adult could be riding along.","h2":"The Pennsylvania junior license limit on passengers under 18 does not apply when a parent or legal guardian is in the vehicle.","p":"Right. A parent or guardian in the car lifts the limit."},"es":{"q":"En Pensilvania, ¿cuándo no se aplica el límite de pasajeros menores de 18 años de la licencia junior?","o":["Cuando va en el carro su padre, madre o tutor legal","Los fines de semana","Cuando maneja a menos de 25 mph","Cuando los pasajeros tienen 17 años"],"h1":"Piense en qué adulto podría ir con usted.","h2":"El límite de pasajeros menores de 18 años de la licencia junior en Pensilvania no se aplica cuando va en el vehículo su padre, madre o tutor legal.","p":"Correcto. Si va su padre, madre o tutor, no hay límite."},"ref":{"doc":"PA","page":4}},{"id":"pa-015","scope":"PA","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Pennsylvania, you are on the opposite side of a divided highway, with a guide rail or grass median between you and a stopped school bus. What must you do?","o":["Stop until the bus moves","Honk to warn the children","Speed up to pass quickly","You do not have to stop, but slow down and drive with caution"],"h1":"A physical divider protects the other side of the road.","h2":"In Pennsylvania, on the opposite side of a divided highway, you do not have to stop for a school bus, but you must slow down and drive with caution.","p":"Right. No stop needed, but slow down with caution."},"es":{"q":"En Pensilvania, usted va del lado contrario de una carretera dividida, con una barrera o una mediana de pasto entre usted y un autobús escolar detenido. ¿Qué debe hacer?","o":["Detenerse hasta que el autobús avance","Tocar la bocina para avisar a los niños","Acelerar para pasar rápido","No tiene que detenerse, pero debe bajar la velocidad y manejar con precaución"],"h1":"Una división física protege el otro lado de la carretera.","h2":"En Pensilvania, del lado contrario de una carretera dividida, usted no tiene que detenerse por un autobús escolar, pero debe bajar la velocidad y manejar con precaución.","p":"Correcto. No se detiene, pero baja la velocidad con precaución."},"ref":{"doc":"PA","page":58}},{"id":"pa-016","scope":"PA","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Pennsylvania, what happens to your license if you fail to stop for a school bus with red lights flashing and the stop arm out?","o":["Nothing happens to the license","A 60-day license suspension","A one-week suspension","Only a warning"],"h1":"It is about two months.","h2":"In Pennsylvania, failing to stop for a school bus with red lights flashing and the stop arm out brings a 60-day license suspension, five points and a fine.","p":"Right. A 60-day suspension."},"es":{"q":"En Pensilvania, ¿qué pasa con su licencia si no se detiene por un autobús escolar con luces rojas intermitentes y el brazo de alto extendido?","o":["No le pasa nada a la licencia","Una suspensión de la licencia por 60 días","Una suspensión de una semana","Solo una advertencia"],"h1":"Son unos dos meses.","h2":"En Pensilvania, no detenerse por un autobús escolar con luces rojas intermitentes y el brazo de alto extendido trae una suspensión de la licencia por 60 días, cinco puntos y una multa.","p":"Correcto. Una suspensión de 60 días."},"ref":{"doc":"PA","page":58}},{"id":"pa-017","scope":"PA","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Pennsylvania, how many points go on your driving record for failing to stop for a school bus?","o":["Five points","One point","Two points","No points"],"h1":"It is more than four and less than six.","h2":"In Pennsylvania, failing to stop for a school bus adds five points to your driving record, along with a suspension and a fine.","p":"Right. Five points."},"es":{"q":"En Pensilvania, ¿cuántos puntos se agregan a su historial de manejo por no detenerse por un autobús escolar?","o":["Cinco puntos","Un punto","Dos puntos","Ningún punto"],"h1":"Es más de cuatro y menos de seis.","h2":"En Pensilvania, no detenerse por un autobús escolar agrega cinco puntos a su historial de manejo, además de una suspensión y una multa.","p":"Correcto. Cinco puntos."},"ref":{"doc":"PA","page":58}},{"id":"pa-018","scope":"PA","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Pennsylvania, what does the Move Over law ask you to do near an emergency response area?","o":["Stop and wait until it is cleared","Turn on your hazard lights and keep going","Move into a lane that is not next to it, or slow down if you cannot","Use the shoulder to pass"],"h1":"The law's name tells you the first step.","h2":"Pennsylvania's Move Over law requires you to move into a lane that is not next to an emergency response area, or, if you cannot move over, to slow down to at least 20 mph below the speed limit.","p":"Right. Move over, or slow down if you cannot."},"es":{"q":"En Pensilvania, ¿qué le pide la ley Move Over (muévase al otro carril) cerca de un área de respuesta a emergencias?","o":["Detenerse y esperar hasta que se despeje","Encender las luces de emergencia y seguir","Pasarse a un carril que no esté junto a la zona o, si no puede, bajar la velocidad","Usar el acotamiento para pasar"],"h1":"El nombre de la ley le dice el primer paso.","h2":"La ley Move Over de Pensilvania le exige pasarse a un carril que no esté junto a un área de respuesta a emergencias o, si no puede cambiarse de carril, bajar la velocidad a por lo menos 20 mph por debajo del límite.","p":"Correcto. Cámbiese de carril, o baje la velocidad si no puede."},"ref":{"doc":"PA","page":59}},{"id":"pa-019","scope":"PA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Pennsylvania, may you hold your phone while stopped at a red light?","o":["Yes, if the car is stopped","No, holding a phone is banned even when stopped in traffic or at a red light","Yes, for less than one minute","Yes, if you are over 21"],"h1":"Stopping for a moment still counts as driving.","h2":"Pennsylvania's Paul Miller's Law bans holding a phone while driving, even when stopped for a moment in traffic or at a red light; hands-free use is allowed.","p":"Right. No phone in your hand, even at a red light."},"es":{"q":"En Pensilvania, ¿puede sostener su teléfono mientras está detenido en un semáforo en rojo?","o":["Sí, si el carro está detenido","No, sostener el teléfono está prohibido aunque esté detenido en el tráfico o en un semáforo en rojo","Sí, por menos de un minuto","Sí, si tiene más de 21 años"],"h1":"Detenerse un momento todavía cuenta como manejar.","h2":"La Ley Paul Miller de Pensilvania prohíbe sostener el teléfono mientras maneja, incluso cuando se detiene un momento en el tráfico o en un semáforo en rojo; el uso con manos libres está permitido.","p":"Correcto. Nada de teléfono en la mano, ni en el semáforo."},"ref":{"doc":"PA","page":null}},{"id":"pa-020","scope":"PA","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Pennsylvania, what blood alcohol level is illegal for a driver under 21?","o":["0.08 percent or more","0.05 percent or more","0.10 percent or more","0.02 percent or more"],"h1":"It is far lower than the adult limit.","h2":"In Pennsylvania a driver under 21 breaks the law at a blood alcohol level of 0.02 percent or more, far below the 0.08 adult limit.","p":"Right. Under 21, the limit is 0.02 percent."},"es":{"q":"En Pensilvania, ¿qué nivel de alcohol en la sangre es ilegal para un conductor menor de 21 años?","o":["0.08 por ciento o más","0.05 por ciento o más","0.10 por ciento o más","0.02 por ciento o más"],"h1":"Es mucho más bajo que el límite para adultos.","h2":"En Pensilvania un conductor menor de 21 años viola la ley con un nivel de alcohol en la sangre de 0.02 por ciento o más, muy por debajo del límite de 0.08 para adultos.","p":"Correcto. Para menores de 21, el límite es 0.02 por ciento."},"ref":{"doc":"PA","page":33}},{"id":"ri-001","scope":"RI","cat":"licensing","sign":null,"c":2,"en":{"q":"In Rhode Island, what is the youngest age to get a limited instruction permit?","o":["14 years old","15 years old","16 years old","17 years old"],"h1":"Rhode Island starts later than many states.","h2":"In Rhode Island you can get a limited instruction permit at 16 years old.","p":"Right. The Rhode Island permit starts at 16."},"es":{"q":"En Rhode Island, ¿cuál es la edad mínima para obtener un permiso de instrucción limitado?","o":["14 años","15 años","16 años","17 años"],"h1":"Rhode Island empieza más tarde que muchos estados.","h2":"En Rhode Island usted puede obtener un permiso de instrucción limitado a los 16 años.","p":"Correcto. El permiso en Rhode Island empieza a los 16."},"ref":{"doc":"RI","page":10}},{"id":"ri-002","scope":"RI","cat":"licensing","sign":null,"c":1,"en":{"q":"In Rhode Island, how long is the driver education course a teen must finish for a permit?","o":["10 hours","33 hours","6 hours","100 hours"],"h1":"It is a little more than thirty hours.","h2":"A Rhode Island teen must complete a 33-hour driver education course to qualify for a limited instruction permit.","p":"Right. The course is 33 hours."},"es":{"q":"En Rhode Island, ¿cuántas horas dura el curso de educación vial que un adolescente debe terminar para el permiso?","o":["10 horas","33 horas","6 horas","100 horas"],"h1":"Son un poco más de treinta horas.","h2":"Un adolescente en Rhode Island debe completar un curso de educación vial de 33 horas para obtener el permiso de instrucción limitado.","p":"Correcto. El curso es de 33 horas."},"ref":{"doc":"RI","page":10}},{"id":"ri-003","scope":"RI","cat":"licensing","sign":null,"c":3,"en":{"q":"In Rhode Island, where can a teen take the permit knowledge test?","o":["At any police station","Online at home","At the high school office","In the CCRI driver education course, or at the DMV in Cranston"],"h1":"One place is a college, the other is the DMV headquarters.","h2":"In Rhode Island the permit knowledge test is part of the CCRI driver education course; otherwise you take it at the DMV headquarters in Cranston.","p":"Right. CCRI or the Cranston DMV."},"es":{"q":"En Rhode Island, ¿dónde puede un adolescente presentar el examen de conocimientos para el permiso?","o":["En cualquier estación de policía","En línea desde la casa","En la oficina de la escuela secundaria","En el curso de educación vial de CCRI, o en el DMV de Cranston"],"h1":"Un lugar es un colegio comunitario y el otro es la sede del DMV.","h2":"En Rhode Island el examen de conocimientos para el permiso es parte del curso de educación vial de CCRI; si no, se presenta en la sede del DMV en Cranston.","p":"Correcto. CCRI o el DMV de Cranston."},"ref":{"doc":"RI","page":10}},{"id":"ri-004","scope":"RI","cat":"licensing","sign":null,"c":0,"en":{"q":"In Rhode Island, who must come to the DMV to co-sign a teen's permit application?","o":["A parent, guardian or adult spouse","A teacher","Any adult friend","No one"],"h1":"It is an adult who is legally responsible for the teen.","h2":"In Rhode Island a parent, guardian or adult spouse must come to the DMV and co-sign the teen's permit application.","p":"Right. A parent, guardian or adult spouse signs too."},"es":{"q":"En Rhode Island, ¿quién debe ir al DMV a firmar junto con el adolescente la solicitud del permiso?","o":["Su padre, madre, tutor o cónyuge adulto","Un maestro","Cualquier amigo adulto","Nadie"],"h1":"Es un adulto que responde legalmente por el adolescente.","h2":"En Rhode Island su padre, madre, tutor o cónyuge adulto debe ir al DMV y firmar también la solicitud del permiso del adolescente.","p":"Correcto. Su padre, madre, tutor o cónyuge adulto también firma."},"ref":{"doc":"RI","page":11}},{"id":"ri-005","scope":"RI","cat":"licensing","sign":null,"c":2,"en":{"q":"In Rhode Island, how long must a teen hold the instruction permit before a limited provisional license?","o":["30 days","3 months","6 months","1 year"],"h1":"It is half a year.","h2":"A Rhode Island teen must hold the instruction permit for at least six months before applying for a limited provisional license.","p":"Right. You hold the permit six months."},"es":{"q":"En Rhode Island, ¿cuánto tiempo debe tener un adolescente el permiso de instrucción antes de la licencia provisional limitada?","o":["30 días","3 meses","6 meses","1 año"],"h1":"Es medio año.","h2":"Un adolescente en Rhode Island debe tener el permiso de instrucción por lo menos seis meses antes de solicitar la licencia provisional limitada.","p":"Correcto. Tiene el permiso seis meses."},"ref":{"doc":"RI","page":12}},{"id":"ri-006","scope":"RI","cat":"licensing","sign":null,"c":1,"en":{"q":"In Rhode Island, how many hours of supervised driving must a parent certify for a teen under 18?","o":["20 hours","50 hours","30 hours","100 hours"],"h1":"It is half of one hundred.","h2":"A Rhode Island parent or guardian must sign a statement that a teen under 18 has driven at least 50 supervised hours.","p":"Right. The teen needs 50 hours."},"es":{"q":"En Rhode Island, ¿cuántas horas de manejo supervisado debe certificar un padre para un adolescente menor de 18?","o":["20 horas","50 horas","30 horas","100 horas"],"h1":"Es la mitad de cien.","h2":"En Rhode Island, el padre, la madre o el tutor debe firmar que el adolescente menor de 18 ha manejado por lo menos 50 horas supervisadas.","p":"Correcto. El adolescente necesita 50 horas."},"ref":{"doc":"RI","page":12}},{"id":"ri-007","scope":"RI","cat":"licensing","sign":null,"c":3,"en":{"q":"In Rhode Island, how many of the 50 supervised hours must be at night?","o":["None","5 hours","25 hours","10 hours"],"h1":"It is one fifth of the total.","h2":"At least 10 of the 50 supervised driving hours for a Rhode Island teen must be at night.","p":"Right. Ten hours at night."},"es":{"q":"En Rhode Island, ¿cuántas de las 50 horas supervisadas deben ser de noche?","o":["Ninguna","5 horas","25 horas","10 horas"],"h1":"Es la quinta parte del total.","h2":"Por lo menos 10 de las 50 horas de manejo supervisado de un adolescente en Rhode Island deben ser de noche.","p":"Correcto. Diez horas de noche."},"ref":{"doc":"RI","page":12}},{"id":"ri-008","scope":"RI","cat":"licensing","sign":null,"c":0,"en":{"q":"In Rhode Island, during which hours may a limited provisional licensee not drive without a qualified adult?","o":["1 a.m. to 5 a.m.","9 p.m. to 5 a.m.","11 p.m. to 6 a.m.","Midnight to 6 a.m."],"h1":"It starts one hour after midnight.","h2":"A Rhode Island limited provisional licensee may not drive between 1 a.m. and 5 a.m. unless a qualified adult is in the car.","p":"Right. The limit is 1 a.m. to 5 a.m."},"es":{"q":"En Rhode Island, ¿en qué horas no puede manejar sin un adulto calificado quien tiene licencia provisional limitada?","o":["De 1 a.m. a 5 a.m.","De 9 p.m. a 5 a.m.","De 11 p.m. a 6 a.m.","De medianoche a 6 a.m."],"h1":"Empieza una hora después de la medianoche.","h2":"Quien tiene licencia provisional limitada en Rhode Island no puede manejar entre la 1 a.m. y las 5 a.m., salvo que vaya un adulto calificado en el carro.","p":"Correcto. El límite es de 1 a.m. a 5 a.m."},"ref":{"doc":"RI","page":14}},{"id":"ri-009","scope":"RI","cat":"licensing","sign":null,"c":2,"en":{"q":"In Rhode Island, which trip is allowed alone during the 1 a.m. to 5 a.m. limit?","o":["Driving friends home from a party","Going out for food","Driving to or from work","Practicing on empty roads"],"h1":"Think of a trip you need for your job.","h2":"A Rhode Island limited provisional licensee may drive alone between 1 a.m. and 5 a.m. when driving to or from work.","p":"Right. A trip to or from work is allowed."},"es":{"q":"En Rhode Island, ¿qué viaje se permite manejar solo durante el límite de 1 a.m. a 5 a.m.?","o":["Llevar a los amigos a casa después de una fiesta","Salir a comprar comida","Manejar hacia o desde el trabajo","Practicar en calles vacías"],"h1":"Piense en un viaje que necesita para su empleo.","h2":"Quien tiene licencia provisional limitada en Rhode Island puede manejar solo entre la 1 a.m. y las 5 a.m. cuando va hacia o desde el trabajo.","p":"Correcto. Se permite ir o volver del trabajo."},"ref":{"doc":"RI","page":14}},{"id":"ri-010","scope":"RI","cat":"licensing","sign":null,"c":1,"en":{"q":"In Rhode Island, how many passengers under 21 may a new limited provisional licensee carry?","o":["None","One","Two","Three"],"h1":"Count on one hand, and use just one finger.","h2":"During the first 12 months of a Rhode Island limited provisional license, the driver may carry no more than one passenger under 21, not counting immediate family.","p":"Right. Only one passenger under 21."},"es":{"q":"En Rhode Island, ¿cuántos pasajeros menores de 21 puede llevar quien acaba de recibir la licencia provisional limitada?","o":["Ninguno","Uno","Dos","Tres"],"h1":"Cuente con una mano, y use solo un dedo.","h2":"Durante los primeros 12 meses de la licencia provisional limitada en Rhode Island, el conductor puede llevar como máximo a un pasajero menor de 21, sin contar a su familia inmediata.","p":"Correcto. Solo un pasajero menor de 21."},"ref":{"doc":"RI","page":14}},{"id":"ri-011","scope":"RI","cat":"licensing","sign":null,"c":3,"en":{"q":"In Rhode Island, how long does the passenger limit last on a limited provisional license?","o":["1 month","3 months","6 months","The first 12 months"],"h1":"It lasts a full year.","h2":"The Rhode Island passenger limit applies during the first 12 months of the limited provisional license.","p":"Right. It lasts the first 12 months."},"es":{"q":"En Rhode Island, ¿cuánto dura el límite de pasajeros en la licencia provisional limitada?","o":["1 mes","3 meses","6 meses","Los primeros 12 meses"],"h1":"Dura un año completo.","h2":"El límite de pasajeros en Rhode Island se aplica durante los primeros 12 meses de la licencia provisional limitada.","p":"Correcto. Dura los primeros 12 meses."},"ref":{"doc":"RI","page":14}},{"id":"ri-012","scope":"RI","cat":"licensing","sign":null,"c":0,"en":{"q":"In Rhode Island, which young passengers do not count toward the provisional passenger limit?","o":["Immediate family members","Classmates","Teammates","Coworkers"],"h1":"Think of brothers and sisters.","h2":"In Rhode Island, immediate family members do not count toward the one-passenger limit on a limited provisional license.","p":"Right. Immediate family does not count."},"es":{"q":"En Rhode Island, ¿qué pasajeros jóvenes no cuentan en el límite de pasajeros de la licencia provisional?","o":["Los familiares inmediatos","Los compañeros de clase","Los compañeros de equipo","Los compañeros de trabajo"],"h1":"Piense en hermanos y hermanas.","h2":"En Rhode Island, los familiares inmediatos no cuentan en el límite de un pasajero de la licencia provisional limitada.","p":"Correcto. La familia inmediata no cuenta."},"ref":{"doc":"RI","page":14}},{"id":"ri-013","scope":"RI","cat":"licensing","sign":null,"c":2,"en":{"q":"In Rhode Island, who may supervise a teen driving with an instruction permit?","o":["Any licensed driver over 18","Any passenger over 16","A licensed adult over 21 who has been licensed for five years","Only a police officer"],"h1":"The helper needs both age and years behind the wheel.","h2":"A Rhode Island permit holder must drive with a licensed adult over 21 who has held a license for at least five years.","p":"Right. Over 21 and licensed five years."},"es":{"q":"En Rhode Island, ¿quién puede supervisar a un adolescente que maneja con permiso de instrucción?","o":["Cualquier conductor con licencia mayor de 18","Cualquier pasajero mayor de 16","Un adulto mayor de 21 que tiene licencia desde hace cinco años","Solo un policía"],"h1":"El acompañante necesita edad y también años de manejo.","h2":"Quien tiene permiso en Rhode Island debe manejar con un adulto mayor de 21 que tenga licencia desde hace por lo menos cinco años.","p":"Correcto. Mayor de 21 y con licencia desde hace cinco años."},"ref":{"doc":"RI","page":11}},{"id":"ri-014","scope":"RI","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Rhode Island, may a driver read a text message while the car is moving?","o":["Yes, if it is short","No, texting while driving is banned","Yes, on the highway","Yes, if no one is in the car"],"h1":"Reading counts the same as writing.","h2":"Rhode Island bans texting while driving, which includes writing, sending or reading messages while the car is moving.","p":"Right. No reading or writing texts while driving."},"es":{"q":"En Rhode Island, ¿puede un conductor leer un mensaje de texto mientras el carro está en movimiento?","o":["Sí, si es corto","No, enviar o leer mensajes al manejar está prohibido","Sí, en la autopista","Sí, si no hay nadie en el carro"],"h1":"Leer cuenta igual que escribir.","h2":"Rhode Island prohíbe los mensajes de texto al manejar, lo que incluye escribir, enviar o leer mensajes mientras el carro está en movimiento.","p":"Correcto. Nada de leer ni escribir mensajes al manejar."},"ref":{"doc":"RI","page":36}},{"id":"ri-015","scope":"RI","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Rhode Island, how may an adult driver talk on a phone while driving?","o":["Holding the phone to the ear","On speaker, held in the hand","Any way they like","Only hands-free"],"h1":"Your hands must stay free for the wheel.","h2":"In Rhode Island an adult driver may talk on a phone while driving only hands-free, never holding it.","p":"Right. Only hands-free."},"es":{"q":"En Rhode Island, ¿cómo puede un conductor adulto hablar por teléfono mientras maneja?","o":["Con el teléfono en la oreja","En altavoz, con el teléfono en la mano","Como quiera","Solo con manos libres"],"h1":"Sus manos deben quedar libres para el volante.","h2":"En Rhode Island un conductor adulto solo puede hablar por teléfono al manejar con manos libres, nunca sosteniéndolo.","p":"Correcto. Solo con manos libres."},"ref":{"doc":"RI","page":null}},{"id":"ri-016","scope":"RI","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Rhode Island, what is the legal alcohol limit for a driver under 21?","o":["0.02 percent","0.08 percent","0.05 percent","0.10 percent"],"h1":"It is much lower than the adult limit.","h2":"In Rhode Island the alcohol limit for a driver under 21 is 0.02 percent.","p":"Right. Under 21, the limit is 0.02."},"es":{"q":"En Rhode Island, ¿cuál es el límite legal de alcohol para un conductor menor de 21?","o":["0.02 por ciento","0.08 por ciento","0.05 por ciento","0.10 por ciento"],"h1":"Es mucho más bajo que el límite para adultos.","h2":"En Rhode Island el límite de alcohol para un conductor menor de 21 es de 0.02 por ciento.","p":"Correcto. Menor de 21, el límite es 0.02."},"ref":{"doc":"RI","page":58}},{"id":"ri-017","scope":"RI","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Rhode Island, what is the legal alcohol limit for a driver 21 or older?","o":["0.02 percent","0.10 percent","0.08 percent","0.12 percent"],"h1":"It is the same limit used in most states.","h2":"In Rhode Island the alcohol limit for a driver 21 or older is 0.08 percent.","p":"Right. For adults, the limit is 0.08."},"es":{"q":"En Rhode Island, ¿cuál es el límite legal de alcohol para un conductor de 21 años o más?","o":["0.02 por ciento","0.10 por ciento","0.08 por ciento","0.12 por ciento"],"h1":"Es el mismo límite que usan la mayoría de los estados.","h2":"En Rhode Island el límite de alcohol para un conductor de 21 años o más es de 0.08 por ciento.","p":"Correcto. Para adultos, el límite es 0.08."},"ref":{"doc":"RI","page":58}},{"id":"ri-018","scope":"RI","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Rhode Island, what must you do when you approach a stopped police car with its lights on?","o":["Speed up to pass quickly","Change lanes away from it or slow down","Stop in your lane","Flash your high beams"],"h1":"Give the officer more room or more time.","h2":"Rhode Island's move over law says to change to a lane away from the stopped vehicle, or slow down, when it shows its emergency lights.","p":"Right. Move over or slow down."},"es":{"q":"En Rhode Island, ¿qué debe hacer al acercarse a un carro de policía detenido con las luces encendidas?","o":["Acelerar para pasar rápido","Cambiarse a un carril lejos de él o bajar la velocidad","Detenerse en su carril","Encender las luces altas"],"h1":"Dé al oficial más espacio o más tiempo.","h2":"La ley de Rhode Island para moverse de carril dice que debe cambiarse a un carril lejos del vehículo detenido, o bajar la velocidad, cuando tiene encendidas sus luces de emergencia.","p":"Correcto. Cámbiese de carril o baje la velocidad."},"ref":{"doc":"RI","page":null}},{"id":"ri-019","scope":"RI","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Rhode Island, does the move over law apply to an ordinary car stopped on the shoulder?","o":["No, only police cars","No, only tow trucks","Only at night","Yes, move over or slow down for it too"],"h1":"Since 2023 the law protects more than emergency vehicles.","h2":"Yes. Rhode Island's move over law also covers any vehicle stopped on the shoulder or breakdown lane, so you move over or slow down for it.","p":"Right. Move over or slow down for any car stopped on the shoulder."},"es":{"q":"En Rhode Island, ¿la ley para moverse de carril se aplica a un carro común detenido en el acotamiento?","o":["No, solo a los carros de policía","No, solo a las grúas","Solo de noche","Sí, también debe cambiar de carril o bajar la velocidad"],"h1":"Desde 2023 la ley protege a más vehículos que los de emergencia.","h2":"Sí. La ley de Rhode Island para moverse de carril también cubre cualquier vehículo detenido en el acotamiento o carril de emergencia, así que usted debe cambiar de carril o bajar la velocidad.","p":"Correcto. Cambie de carril o baje la velocidad ante cualquier carro detenido en el acotamiento."},"ref":{"doc":"RI","page":null}},{"id":"ri-020","scope":"RI","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Rhode Island, on a highway with a median strip, must you stop for a school bus stopped on the other side?","o":["No, you do not have to stop","Yes, always","Only if children are visible","Only on school days"],"h1":"The median separates you from the children.","h2":"Under Rhode Island law, you do not have to stop for a school bus that is stopped on the other side of a divided highway.","p":"Right. The other side of a divided highway need not stop."},"es":{"q":"En Rhode Island, en una carretera con franja divisoria, ¿debe detenerse ante un autobús escolar detenido del otro lado?","o":["No, no tiene que detenerse","Sí, siempre","Solo si se ven niños","Solo en días de clases"],"h1":"La franja divisoria lo separa de los niños.","h2":"Según la ley de Rhode Island, usted no tiene que detenerse ante un autobús escolar detenido del otro lado de una carretera dividida.","p":"Correcto. El otro lado de una carretera dividida no tiene que detenerse."},"ref":{"doc":"RI","page":51}},{"id":"ri-021","scope":"RI","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Rhode Island, on a road with no median, which drivers must stop for a school bus with flashing red lights?","o":["Only drivers behind the bus","Only drivers in the right lane","All drivers coming from either direction","No one, if the road is wide"],"h1":"On an undivided road, children may cross toward either side.","h2":"In Rhode Island, on a road with no median, drivers coming from either direction must stop for a school bus with flashing red lights.","p":"Right. Traffic from both directions stops."},"es":{"q":"En Rhode Island, en una vía sin división, ¿qué conductores deben detenerse ante un autobús escolar con luces rojas intermitentes?","o":["Solo los conductores detrás del autobús","Solo los del carril derecho","Todos los conductores que vienen de cualquier dirección","Nadie, si la vía es ancha"],"h1":"En una vía sin división, los niños pueden cruzar hacia cualquier lado.","h2":"En Rhode Island, en una vía sin división, los conductores que vienen de cualquier dirección deben detenerse ante un autobús escolar con luces rojas intermitentes.","p":"Correcto. El tráfico de ambos sentidos se detiene."},"ref":{"doc":"RI","page":51}},{"id":"sc-001","scope":"SC","cat":"licensing","sign":null,"c":1,"en":{"q":"In South Carolina, what is the youngest age to get a beginner's permit?","o":["14 years old","15 years old","16 years old","17 years old"],"h1":"It is one year before the special restricted license.","h2":"In South Carolina you can get a beginner's permit at 15, after you pass the vision and knowledge tests.","p":"Right. The beginner's permit starts at 15."},"es":{"q":"En Carolina del Sur, ¿cuál es la edad mínima para obtener el permiso de principiante?","o":["14 años","15 años","16 años","17 años"],"h1":"Es un año antes de la licencia restringida especial.","h2":"En Carolina del Sur usted puede obtener el permiso de principiante a los 15 años, después de aprobar el examen de la vista y el examen de conocimientos.","p":"Correcto. El permiso de principiante empieza a los 15."},"ref":{"doc":"SC","page":"1-4"}},{"id":"sc-002","scope":"SC","cat":"licensing","sign":null,"c":3,"en":{"q":"In South Carolina, who must supervise a driver with a beginner's permit?","o":["Any passenger 16 or older","Any adult with a car","A licensed driver 18 or older","A licensed driver 21 or older with at least one year of driving experience"],"h1":"The helper must be an adult with some experience behind the wheel.","h2":"A South Carolina permit holder must be supervised by a licensed driver who is at least 21 and has at least one year of driving experience.","p":"Right. 21 or older, with a year of experience."},"es":{"q":"En Carolina del Sur, ¿quién debe supervisar a un conductor con permiso de principiante?","o":["Cualquier pasajero de 16 años o más","Cualquier adulto con carro","Un conductor con licencia de 18 años o más","Un conductor con licencia de 21 años o más con por lo menos un año de experiencia"],"h1":"El acompañante debe ser un adulto con algo de experiencia al volante.","h2":"Quien tiene permiso en Carolina del Sur debe estar supervisado por un conductor con licencia de por lo menos 21 años y con por lo menos un año de experiencia manejando.","p":"Correcto. 21 años o más, con un año de experiencia."},"ref":{"doc":"SC","page":"1-4"}},{"id":"sc-003","scope":"SC","cat":"licensing","sign":null,"c":0,"en":{"q":"In South Carolina, a permit holder wants to practice at 1 a.m. Who must be the supervisor?","o":["A licensed parent or guardian","Any licensed adult 21 or older","A driving instructor only","No one; practice is not allowed"],"h1":"Late at night, the rule is about family.","h2":"In South Carolina, a permit holder driving between midnight and 6 a.m. must be supervised by a licensed parent or guardian, or another adult the law allows, such as one with notarized permission from a parent.","p":"Right. A licensed parent or guardian after midnight."},"es":{"q":"En Carolina del Sur, quien tiene permiso quiere practicar a la 1 a.m. ¿Quién debe ser el supervisor?","o":["Un padre, madre o tutor con licencia","Cualquier adulto con licencia de 21 años o más","Solo un instructor de manejo","Nadie; no se permite practicar"],"h1":"De madrugada, la regla tiene que ver con la familia.","h2":"En Carolina del Sur, quien tiene permiso y maneja entre la medianoche y las 6 a.m. debe estar supervisado por su padre, madre o tutor con licencia, u otro adulto que la ley permite, como uno con permiso notariado de un padre.","p":"Correcto. Un padre o tutor con licencia después de la medianoche."},"ref":{"doc":"SC","page":"1-4"}},{"id":"sc-004","scope":"SC","cat":"licensing","sign":null,"c":2,"en":{"q":"In South Carolina, how long must a teen hold a beginner's permit before taking the road test?","o":["30 days","90 days","180 days","365 days"],"h1":"It is about six months.","h2":"A South Carolina driver with no experience must hold the beginner's permit for 180 days before the road test, unless they are 18 or older.","p":"Right. 180 days with the permit."},"es":{"q":"En Carolina del Sur, ¿cuánto tiempo debe tener un adolescente el permiso de principiante antes del examen de manejo?","o":["30 días","90 días","180 días","365 días"],"h1":"Son unos seis meses.","h2":"En Carolina del Sur, un conductor sin experiencia debe tener el permiso de principiante 180 días antes del examen de manejo, salvo que tenga 18 años o más.","p":"Correcto. 180 días con el permiso."},"ref":{"doc":"SC","page":"1-4"}},{"id":"sc-005","scope":"SC","cat":"licensing","sign":null,"c":1,"en":{"q":"In South Carolina, how many hours of supervised practice must a teen complete before a conditional license?","o":["20 hours","40 hours","50 hours","60 hours"],"h1":"It is less than a full week of work hours.","h2":"A South Carolina teen must complete at least 40 hours of supervised practice before a conditional license.","p":"Right. 40 hours of practice."},"es":{"q":"En Carolina del Sur, ¿cuántas horas de práctica supervisada debe completar un adolescente antes de la licencia condicional?","o":["20 horas","40 horas","50 horas","60 horas"],"h1":"Son menos que una semana completa de horas de trabajo.","h2":"Un adolescente en Carolina del Sur debe completar por lo menos 40 horas de práctica supervisada antes de la licencia condicional.","p":"Correcto. 40 horas de práctica."},"ref":{"doc":"SC","page":"1-6"}},{"id":"sc-006","scope":"SC","cat":"licensing","sign":null,"c":3,"en":{"q":"In South Carolina, how many of the 40 practice hours must be driven in darkness?","o":["None","2 hours","5 hours","10 hours"],"h1":"It is one quarter of the total.","h2":"At least 10 of the 40 practice hours in South Carolina must be driven in darkness.","p":"Right. Ten hours after dark."},"es":{"q":"En Carolina del Sur, ¿cuántas de las 40 horas de práctica deben manejarse en la oscuridad?","o":["Ninguna","2 horas","5 horas","10 horas"],"h1":"Es la cuarta parte del total.","h2":"Por lo menos 10 de las 40 horas de práctica en Carolina del Sur deben manejarse en la oscuridad.","p":"Correcto. Diez horas de noche."},"ref":{"doc":"SC","page":"1-6"}},{"id":"sc-007","scope":"SC","cat":"licensing","sign":null,"c":2,"en":{"q":"In South Carolina, until what time may a conditional license holder drive alone in standard time (not daylight saving time)?","o":["Midnight","9 p.m.","6 p.m.","10 p.m."],"h1":"It is early in the evening.","h2":"A South Carolina conditional license holder may drive alone from 6 a.m. until 6 p.m. in standard time.","p":"Right. Alone until 6 p.m."},"es":{"q":"En Carolina del Sur, ¿hasta qué hora puede manejar solo quien tiene licencia condicional en horario normal (no de verano)?","o":["Medianoche","9 p.m.","6 p.m.","10 p.m."],"h1":"Es temprano por la tarde.","h2":"Quien tiene licencia condicional en Carolina del Sur puede manejar solo de 6 a.m. a 6 p.m. en horario normal.","p":"Correcto. Solo hasta las 6 p.m."},"ref":{"doc":"SC","page":"1-7"}},{"id":"sc-008","scope":"SC","cat":"licensing","sign":null,"c":0,"en":{"q":"In South Carolina, during daylight saving time, until what time may a conditional license holder drive alone?","o":["8 p.m.","6 p.m.","10 p.m.","Midnight"],"h1":"It is two hours later than in winter.","h2":"During daylight saving time, a South Carolina conditional license holder may drive alone until 8 p.m.","p":"Right. Until 8 p.m. in daylight saving time."},"es":{"q":"En Carolina del Sur, durante el horario de verano, ¿hasta qué hora puede manejar solo quien tiene licencia condicional?","o":["8 p.m.","6 p.m.","10 p.m.","Medianoche"],"h1":"Son dos horas más tarde que en invierno.","h2":"Durante el horario de verano, quien tiene licencia condicional en Carolina del Sur puede manejar solo hasta las 8 p.m.","p":"Correcto. Hasta las 8 p.m. en horario de verano."},"ref":{"doc":"SC","page":"1-7"}},{"id":"sc-009","scope":"SC","cat":"licensing","sign":null,"c":1,"en":{"q":"In South Carolina, a conditional license holder wants to drive at 9 p.m. Who must be in the car?","o":["A friend with a permit","A licensed driver 21 or older","Any passenger 18 or older","No one; driving after dark is banned"],"h1":"An experienced adult driver allows evening driving.","h2":"After the evening limit, a South Carolina conditional license holder may drive until midnight with a licensed driver 21 or older in the car.","p":"Right. A licensed driver 21 or older."},"es":{"q":"En Carolina del Sur, quien tiene licencia condicional quiere manejar a las 9 p.m. ¿Quién debe ir en el carro?","o":["Un amigo con permiso","Un conductor con licencia de 21 años o más","Cualquier pasajero de 18 años o más","Nadie; está prohibido manejar de noche"],"h1":"Un conductor adulto con experiencia permite manejar por la noche.","h2":"Después del límite de la tarde, quien tiene licencia condicional en Carolina del Sur puede manejar hasta la medianoche con un conductor con licencia de 21 años o más en el carro.","p":"Correcto. Un conductor con licencia de 21 años o más."},"ref":{"doc":"SC","page":"1-8"}},{"id":"sc-010","scope":"SC","cat":"licensing","sign":null,"c":3,"en":{"q":"In South Carolina, a conditional license holder drives between midnight and 6 a.m. Who must be in the car?","o":["Any licensed adult","A friend over 18","A police officer","A licensed parent or guardian"],"h1":"Late at night, the rule is about family.","h2":"Between midnight and 6 a.m., a South Carolina conditional license holder may drive only with a licensed parent or guardian, or another adult the law allows, in the car.","p":"Right. A licensed parent or guardian."},"es":{"q":"En Carolina del Sur, quien tiene licencia condicional maneja entre la medianoche y las 6 a.m. ¿Quién debe ir en el carro?","o":["Cualquier adulto con licencia","Un amigo mayor de 18","Un policía","Un padre, madre o tutor con licencia"],"h1":"De madrugada, la regla tiene que ver con la familia.","h2":"Entre la medianoche y las 6 a.m., quien tiene licencia condicional en Carolina del Sur solo puede manejar con su padre, madre o tutor con licencia, u otro adulto que la ley permite, en el carro.","p":"Correcto. Un padre o tutor con licencia."},"ref":{"doc":"SC","page":"1-8"}},{"id":"sc-011","scope":"SC","cat":"licensing","sign":null,"c":2,"en":{"q":"In South Carolina, how many passengers under 21 may a conditional license holder carry without an adult, not counting family or students going to school?","o":["None","One","Two","Four"],"h1":"It is a small number, but more than one.","h2":"A South Carolina conditional license holder may carry no more than two passengers under 21, unless a licensed adult 21 or older rides along or the riders are family or students going to or from school.","p":"Right. No more than two."},"es":{"q":"En Carolina del Sur, ¿cuántos pasajeros menores de 21 años puede llevar sin un adulto quien tiene licencia condicional, sin contar familiares ni estudiantes que van a la escuela?","o":["Ninguno","Uno","Dos","Cuatro"],"h1":"Es un número pequeño, pero más de uno.","h2":"Quien tiene licencia condicional en Carolina del Sur puede llevar no más de dos pasajeros menores de 21 años, salvo que lo acompañe un adulto con licencia de 21 años o más, o que sean familiares o estudiantes que van o vuelven de la escuela.","p":"Correcto. No más de dos."},"ref":{"doc":"SC","page":"1-7"}},{"id":"sc-012","scope":"SC","cat":"licensing","sign":null,"c":0,"en":{"q":"In South Carolina, at what age can a teen who meets the conditional license rules get a special restricted license instead?","o":["16 years old","15 years old","17 years old","18 years old"],"h1":"The only difference from the conditional license is age.","h2":"A South Carolina teen who is 16 but not yet 17 and meets the conditional license rules can get a special restricted license.","p":"Right. The special restricted license is for age 16."},"es":{"q":"En Carolina del Sur, ¿a qué edad puede un adolescente que cumple las reglas de la licencia condicional obtener la licencia restringida especial?","o":["16 años","15 años","17 años","18 años"],"h1":"La única diferencia con la licencia condicional es la edad.","h2":"Un adolescente en Carolina del Sur que tiene 16 años pero todavía no 17 y cumple las reglas de la licencia condicional puede obtener la licencia restringida especial.","p":"Correcto. La licencia restringida especial es para los 16 años."},"ref":{"doc":"SC","page":"1-8"}},{"id":"sc-013","scope":"SC","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In South Carolina, what blood alcohol level breaks the zero tolerance law for a driver under 21?","o":["0.08","0.02","0.05","0.10"],"h1":"It is much lower than the adult limit.","h2":"In South Carolina a driver under 21 with a blood alcohol level of 0.02 breaks the zero tolerance law.","p":"Right. Under 21, the limit is 0.02."},"es":{"q":"En Carolina del Sur, ¿qué nivel de alcohol en la sangre viola la ley de tolerancia cero para un conductor menor de 21 años?","o":["0.08","0.02","0.05","0.10"],"h1":"Es mucho más bajo que el límite para adultos.","h2":"En Carolina del Sur un conductor menor de 21 años con un nivel de alcohol en la sangre de 0.02 viola la ley de tolerancia cero.","p":"Correcto. Para menores de 21, el límite es 0.02."},"ref":{"doc":"SC","page":"3-7"}},{"id":"sc-014","scope":"SC","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In South Carolina, what happens on a first zero tolerance offense for a driver under 21?","o":["Only a warning","A one-week suspension","A five-year suspension","A suspension of at least three months"],"h1":"It is a few months.","h2":"In South Carolina, a driver under 21 with a blood alcohol level of 0.02 or more loses the right to drive right away, for at least three months.","p":"Right. At least three months without driving."},"es":{"q":"En Carolina del Sur, ¿qué pasa en la primera infracción de tolerancia cero de un conductor menor de 21 años?","o":["Solo una advertencia","Una suspensión de una semana","Una suspensión de cinco años","Una suspensión de por lo menos tres meses"],"h1":"Son unos pocos meses.","h2":"En Carolina del Sur, un conductor menor de 21 años con un nivel de alcohol en la sangre de 0.02 o más pierde el derecho a manejar de inmediato, por lo menos por tres meses.","p":"Correcto. Por lo menos tres meses sin manejar."},"ref":{"doc":"SC","page":"3-7"}},{"id":"sc-015","scope":"SC","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In South Carolina, can police stop a driver only for holding a phone while driving?","o":["No, only with another violation","Only on interstates","Yes, it is a primary offense","Only in school zones"],"h1":"The hands-free law is enforced on its own.","h2":"South Carolina's hands-free law is a primary offense, so police can stop a driver they clearly see holding a phone, with no other reason.","p":"Right. Holding a phone is enough for a stop."},"es":{"q":"En Carolina del Sur, ¿puede la policía detener a un conductor solo por sostener el teléfono mientras maneja?","o":["No, solo con otra infracción","Solo en interestatales","Sí, es una infracción primaria","Solo en zonas escolares"],"h1":"La ley de manos libres se aplica por sí sola.","h2":"La ley de manos libres de Carolina del Sur es una infracción primaria, así que la policía puede detener a un conductor que ve claramente con el teléfono en la mano, sin otra razón.","p":"Correcto. Sostener el teléfono basta para que lo detengan."},"ref":{"doc":"SC","page":null}},{"id":"sc-016","scope":"SC","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In South Carolina, how may you make a phone call while driving?","o":["Hands-free, such as a car speaker or earpiece","Holding the phone to your ear","Holding the phone on speaker","Holding the phone, if you drive slowly"],"h1":"Your hands stay on the wheel.","h2":"South Carolina allows phone calls while driving only hands-free, such as through the car's speaker or an earpiece.","p":"Right. Hands-free calls only."},"es":{"q":"En Carolina del Sur, ¿cómo puede hacer una llamada mientras maneja?","o":["Con manos libres, como la bocina del carro o un audífono","Sosteniendo el teléfono en la oreja","Sosteniendo el teléfono en altavoz","Sosteniendo el teléfono, si maneja despacio"],"h1":"Sus manos se quedan en el volante.","h2":"Carolina del Sur permite llamadas mientras maneja solo con manos libres, como la bocina del carro o un audífono.","p":"Correcto. Solo llamadas con manos libres."},"ref":{"doc":"SC","page":"3-5"}},{"id":"sc-017","scope":"SC","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In South Carolina, you approach a stopped emergency vehicle with flashing lights. What should you do if it is safe?","o":["Keep your speed and lane","Slow down and change to a lane not next to it","Stop in your lane","Use the shoulder to pass"],"h1":"Give it a whole lane of space.","h2":"In South Carolina you must slow down and, if possible, change to a lane that is not next to a stopped emergency vehicle with flashing lights.","p":"Right. Slow down and move over."},"es":{"q":"En Carolina del Sur, se acerca a un vehículo de emergencia detenido con luces intermitentes. ¿Qué debe hacer si es seguro?","o":["Mantener su velocidad y su carril","Bajar la velocidad y cambiarse a un carril que no esté junto a él","Detenerse en su carril","Usar el acotamiento para pasar"],"h1":"Déjele un carril completo de espacio.","h2":"En Carolina del Sur usted debe bajar la velocidad y, si es posible, cambiarse a un carril que no esté junto al vehículo de emergencia detenido con luces intermitentes.","p":"Correcto. Bajar la velocidad y cambiarse de carril."},"ref":{"doc":"SC","page":"10-15"}},{"id":"sc-018","scope":"SC","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In South Carolina, you cannot safely change lanes away from a stopped emergency vehicle. What must you do?","o":["Speed up to pass quickly","Stop completely","Honk as you pass","Slow down and keep a safe speed"],"h1":"If moving over is not possible, there is still one thing to do.","h2":"In South Carolina, when you cannot safely change lanes, you must slow down and keep a safe speed as you pass a stopped emergency vehicle.","p":"Right. Slow down when you cannot move over."},"es":{"q":"En Carolina del Sur, no puede cambiarse de carril con seguridad para alejarse de un vehículo de emergencia detenido. ¿Qué debe hacer?","o":["Acelerar para pasar rápido","Detenerse por completo","Tocar la bocina al pasar","Bajar la velocidad y mantener una velocidad segura"],"h1":"Si no puede cambiarse, todavía hay algo que hacer.","h2":"En Carolina del Sur, cuando no puede cambiarse de carril con seguridad, debe bajar la velocidad y mantener una velocidad segura al pasar un vehículo de emergencia detenido.","p":"Correcto. Bajar la velocidad cuando no puede cambiarse."},"ref":{"doc":"SC","page":"10-15"}},{"id":"sc-019","scope":"SC","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In South Carolina, on a highway with at least two lanes in each direction, you meet a stopped school bus coming the other way. What must you do?","o":["Stop until the bus moves","Stop only if there is no median","You do not have to stop, but go with caution","Stop and wait for the driver's signal"],"h1":"The number of lanes matters more than the median.","h2":"On a South Carolina highway with at least two lanes in each direction, traffic going the opposite way does not have to stop for a school bus, whatever the median, but should go with caution.","p":"Right. Oncoming traffic may pass with caution."},"es":{"q":"En Carolina del Sur, en una carretera con por lo menos dos carriles en cada sentido, usted se encuentra con un autobús escolar detenido que viene en sentido contrario. ¿Qué debe hacer?","o":["Detenerse hasta que el autobús avance","Detenerse solo si no hay camellón","No tiene que detenerse, pero avance con cuidado","Detenerse y esperar la señal del chofer"],"h1":"El número de carriles importa más que el camellón.","h2":"En una carretera de Carolina del Sur con por lo menos dos carriles en cada sentido, el tráfico en sentido contrario no tiene que detenerse por un autobús escolar, haya o no camellón, pero debe avanzar con cuidado.","p":"Correcto. El tráfico contrario puede pasar con cuidado."},"ref":{"doc":"SC","page":"7-10"}},{"id":"sc-020","scope":"SC","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In South Carolina, on a four-lane highway, you are behind a school bus that stops with its red lights flashing. What must you do?","o":["Pass it carefully on the left","Stop","Slow to 15 mph and pass","Stop only if a child is in the road"],"h1":"Traffic going the same way as the bus never passes it.","h2":"On a South Carolina four-lane highway, traffic going the same direction as a stopped school bus must stop.","p":"Right. You stop behind the bus."},"es":{"q":"En Carolina del Sur, en una carretera de cuatro carriles, usted va detrás de un autobús escolar que se detiene con las luces rojas intermitentes. ¿Qué debe hacer?","o":["Rebasarlo con cuidado por la izquierda","Detenerse","Bajar a 15 mph y pasar","Detenerse solo si hay un niño en el camino"],"h1":"El tráfico que va en el mismo sentido que el autobús nunca lo rebasa.","h2":"En una carretera de cuatro carriles de Carolina del Sur, el tráfico que va en el mismo sentido que un autobús escolar detenido debe detenerse.","p":"Correcto. Usted se detiene detrás del autobús."},"ref":{"doc":"SC","page":"7-9"}},{"id":"sc-021","scope":"SC","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In South Carolina, what is the highest speed limit on interstate highways?","o":["55 mph","60 mph","75 mph","70 mph"],"h1":"It is lower than in some western states.","h2":"The highest speed limit on South Carolina interstate highways is 70 mph, where signs show it.","p":"Right. 70 mph on interstates."},"es":{"q":"En Carolina del Sur, ¿cuál es el límite de velocidad más alto en las autopistas interestatales?","o":["55 mph","60 mph","75 mph","70 mph"],"h1":"Es más bajo que en algunos estados del oeste.","h2":"El límite de velocidad más alto en las autopistas interestatales de Carolina del Sur es de 70 millas por hora, donde las señales lo indican.","p":"Correcto. 70 mph en las interestatales."},"ref":{"doc":"SC","page":null}},{"id":"sd-001","scope":"SD","cat":"licensing","sign":null,"c":0,"en":{"q":"In South Dakota, what is the youngest age to get an instruction permit?","o":["14 years old","15 years old","16 years old","15 and a half"],"h1":"South Dakota lets teens start earlier than most states.","h2":"In South Dakota you can get an instruction permit at age 14, which is earlier than in most states.","p":"Right. The South Dakota instruction permit starts at age 14."},"es":{"q":"En Dakota del Sur, ¿cuál es la edad mínima para obtener el permiso de instrucción?","o":["14 años","15 años","16 años","15 años y medio"],"h1":"Dakota del Sur deja empezar antes que la mayoría de los estados.","h2":"En Dakota del Sur usted puede obtener el permiso de instrucción a los 14 años, antes que en la mayoría de los estados.","p":"Correcto. El permiso de instrucción en Dakota del Sur empieza a los 14 años."},"ref":{"doc":"SD","page":8}},{"id":"sd-002","scope":"SD","cat":"licensing","sign":null,"c":2,"en":{"q":"In South Dakota, during which hours may an instruction permit holder drive with any qualified licensed adult beside them?","o":["6 a.m. to 8 p.m.","5 a.m. to midnight","6 a.m. to 10 p.m.","6 a.m. to 6 p.m."],"h1":"It ends in the late evening, before midnight.","h2":"A South Dakota instruction permit allows driving from 6 a.m. to 10 p.m. with a qualified licensed adult beside you; from 10 p.m. to 6 a.m. it must be your parent or guardian.","p":"Right. Instruction permit driving is from 6 a.m. to 10 p.m."},"es":{"q":"En Dakota del Sur, ¿en qué horario puede manejar quien tiene permiso de instrucción con cualquier adulto con licencia autorizado a su lado?","o":["De 6 a.m. a 8 p.m.","De 5 a.m. a medianoche","De 6 a.m. a 10 p.m.","De 6 a.m. a 6 p.m."],"h1":"Termina tarde en la noche, antes de la medianoche.","h2":"En Dakota del Sur el permiso de instrucción permite manejar de 6 a.m. a 10 p.m. con un adulto con licencia autorizado a su lado; de 10 p.m. a 6 a.m. debe ser su padre, madre o tutor.","p":"Correcto. Con permiso de instrucción se maneja de 6 a.m. a 10 p.m."},"ref":{"doc":"SD","page":null}},{"id":"sd-003","scope":"SD","cat":"licensing","sign":null,"c":1,"en":{"q":"In South Dakota, who may sit beside an instruction permit holder while driving?","o":["Any passenger age 16 or older","A parent, guardian, or licensed adult with 1+ year of experience","Any licensed driver, even a new one","Only a certified driving instructor"],"h1":"The helper needs a license and some driving experience.","h2":"A South Dakota instruction permit holder must drive with a parent, a guardian, or another licensed adult with at least one year of driving experience seated beside them.","p":"Right. The helper is a parent, guardian, or experienced licensed adult."},"es":{"q":"En Dakota del Sur, ¿quién puede ir sentado al lado de quien tiene permiso de instrucción mientras maneja?","o":["Cualquier pasajero de 16 años o más","Un padre, tutor o adulto con licencia y 1+ año de experiencia","Cualquier conductor con licencia, aunque sea nuevo","Solo un instructor de manejo certificado"],"h1":"El acompañante necesita licencia y algo de experiencia manejando.","h2":"En Dakota del Sur quien tiene permiso de instrucción debe manejar con un padre, un tutor u otro adulto con licencia y por lo menos un año de experiencia sentado a su lado.","p":"Correcto. El acompañante es un padre, tutor o adulto con licencia y experiencia."},"ref":{"doc":"SD","page":8}},{"id":"sd-004","scope":"SD","cat":"licensing","sign":null,"c":3,"en":{"q":"In South Dakota, how long must a teen hold an instruction permit before applying for a restricted minor's permit, without driver education?","o":["90 days","180 days","365 days","275 days"],"h1":"It is about nine months.","h2":"A South Dakota teen without approved driver education must hold the instruction permit for at least 275 days before applying for a restricted minor's permit.","p":"Right. Without driver education, the wait is 275 days."},"es":{"q":"En Dakota del Sur, ¿cuánto tiempo debe tener un joven el permiso de instrucción antes de solicitar el permiso restringido de menor, sin educación vial?","o":["90 días","180 días","365 días","275 días"],"h1":"Son unos nueve meses.","h2":"En Dakota del Sur un joven sin educación vial aprobada debe tener el permiso de instrucción por lo menos 275 días antes de solicitar el permiso restringido de menor.","p":"Correcto. Sin educación vial, la espera es de 275 días."},"ref":{"doc":"SD","page":8}},{"id":"sd-005","scope":"SD","cat":"licensing","sign":null,"c":1,"en":{"q":"In South Dakota, if a teen passes an approved driver education course, how long must they hold the instruction permit?","o":["90 days","180 days","275 days","30 days"],"h1":"It is about six months.","h2":"In South Dakota a teen who passes an approved driver education course needs to hold the instruction permit for only 180 days instead of 275.","p":"Right. With driver education, the wait is 180 days."},"es":{"q":"En Dakota del Sur, si un joven aprueba un curso de educación vial aprobado, ¿cuánto tiempo debe tener el permiso de instrucción?","o":["90 días","180 días","275 días","30 días"],"h1":"Son unos seis meses.","h2":"En Dakota del Sur un joven que aprueba un curso de educación vial aprobado solo necesita tener el permiso de instrucción 180 días en lugar de 275.","p":"Correcto. Con educación vial, la espera es de 180 días."},"ref":{"doc":"SD","page":8}},{"id":"sd-006","scope":"SD","cat":"licensing","sign":null,"c":2,"en":{"q":"In South Dakota, how many hours of supervised driving must a teen complete on an instruction permit?","o":["20 hours","40 hours","50 hours","60 hours"],"h1":"It is a round number between 40 and 60.","h2":"A South Dakota teen must complete at least 50 hours of supervised driving on an instruction permit, and a parent or guardian confirms it in writing.","p":"Right. Fifty hours of supervised driving."},"es":{"q":"En Dakota del Sur, ¿cuántas horas de manejo supervisado debe completar un joven con el permiso de instrucción?","o":["20 horas","40 horas","50 horas","60 horas"],"h1":"Es un número redondo entre 40 y 60.","h2":"En Dakota del Sur un joven debe completar por lo menos 50 horas de manejo supervisado con el permiso de instrucción, y un padre o tutor lo confirma por escrito.","p":"Correcto. Cincuenta horas de manejo supervisado."},"ref":{"doc":"SD","page":8}},{"id":"sd-007","scope":"SD","cat":"licensing","sign":null,"c":0,"en":{"q":"In South Dakota, of the required supervised hours, how many must be in bad weather and how many at night?","o":["At least 10 of each","At least 5 of each","At least 20 of each","At least 15 of each"],"h1":"It is the same small number for both.","h2":"In South Dakota at least 10 of the supervised hours must be in bad weather and at least 10 at night, so new drivers practice in hard conditions with an adult.","p":"Right. At least 10 hours in bad weather and 10 at night."},"es":{"q":"En Dakota del Sur, de las horas supervisadas que se exigen, ¿cuántas deben ser con mal tiempo y cuántas de noche?","o":["Por lo menos 10 de cada una","Por lo menos 5 de cada una","Por lo menos 20 de cada una","Por lo menos 15 de cada una"],"h1":"Es el mismo número pequeño para las dos.","h2":"En Dakota del Sur por lo menos 10 de las horas supervisadas deben ser con mal tiempo y por lo menos 10 de noche, para que el conductor nuevo practique en condiciones difíciles con un adulto.","p":"Correcto. Por lo menos 10 horas con mal tiempo y 10 de noche."},"ref":{"doc":"SD","page":8}},{"id":"sd-008","scope":"SD","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In South Dakota, what is the rule about phones for instruction permit holders while driving?","o":["Hands-free calls are allowed","Texting is allowed when stopped","Calls to parents are allowed","No wireless device may be used"],"h1":"The rule for permit holders is strict.","h2":"A South Dakota instruction permit holder may not use any kind of wireless communication device while driving, so all attention stays on learning to drive.","p":"Right. Permit holders may not use any wireless device while driving."},"es":{"q":"En Dakota del Sur, ¿cuál es la regla sobre el teléfono para quien tiene permiso de instrucción mientras maneja?","o":["Se permiten llamadas con manos libres","Se permite escribir mensajes parado","Se permiten llamadas a los padres","No se puede usar ningún aparato inalámbrico"],"h1":"La regla para los aprendices es estricta.","h2":"En Dakota del Sur quien tiene permiso de instrucción no puede usar ningún tipo de aparato de comunicación inalámbrico mientras maneja, para que toda la atención esté en aprender a manejar.","p":"Correcto. Con permiso de instrucción no se usa ningún aparato inalámbrico al manejar."},"ref":{"doc":"SD","page":8}},{"id":"sd-009","scope":"SD","cat":"licensing","sign":null,"c":1,"en":{"q":"In South Dakota, during which hours may a restricted minor's permit holder drive alone with a parent's permission?","o":["5 a.m. to 9 p.m.","6 a.m. to 10 p.m.","7 a.m. to 11 p.m.","6 a.m. to midnight"],"h1":"They are the same hours as the instruction permit.","h2":"A South Dakota restricted minor's permit holder may drive alone between 6 a.m. and 10 p.m. with a parent's permission; at other hours a parent or guardian must ride along, with some exceptions.","p":"Right. Alone from 6 a.m. to 10 p.m."},"es":{"q":"En Dakota del Sur, ¿en qué horario puede manejar solo quien tiene permiso restringido de menor, con permiso de sus padres?","o":["De 5 a.m. a 9 p.m.","De 6 a.m. a 10 p.m.","De 7 a.m. a 11 p.m.","De 6 a.m. a medianoche"],"h1":"Es el mismo horario del permiso de instrucción.","h2":"En Dakota del Sur quien tiene permiso restringido de menor puede manejar solo entre las 6 a.m. y las 10 p.m. con permiso de sus padres; en otras horas debe ir un padre o tutor, con algunas excepciones.","p":"Correcto. Solo de 6 a.m. a 10 p.m."},"ref":{"doc":"SD","page":8}},{"id":"sd-010","scope":"SD","cat":"licensing","sign":null,"c":2,"en":{"q":"In South Dakota, which trip lets a restricted minor's permit holder drive alone after 10 p.m., by the most direct route?","o":["Going to a friend's party","Going to a late movie","Going to or from work","Going for a practice drive"],"h1":"Think of a needed trip, not one for fun.","h2":"A South Dakota restricted minor's permit holder may drive alone after 10 p.m. by the most direct route to or from work, school or church events, or farm work.","p":"Right. A direct trip to or from work is allowed."},"es":{"q":"En Dakota del Sur, ¿qué viaje permite a quien tiene permiso restringido de menor manejar solo después de las 10 p.m., por la ruta más directa?","o":["Ir a la fiesta de un amigo","Ir al cine tarde","Ir al trabajo o volver de él","Salir a practicar manejo"],"h1":"Piense en un viaje necesario, no en uno por diversión.","h2":"En Dakota del Sur quien tiene permiso restringido de menor puede manejar solo después de las 10 p.m. por la ruta más directa para ir o volver del trabajo, de eventos de la escuela o la iglesia, o de trabajo en el campo.","p":"Correcto. Un viaje directo al trabajo o desde él está permitido."},"ref":{"doc":"SD","page":8}},{"id":"sd-011","scope":"SD","cat":"licensing","sign":null,"c":0,"en":{"q":"In South Dakota, during the first six months of a restricted minor's permit, who may ride as a passenger?","o":["Only immediate family or household members","Up to two friends under 18","Any passenger with a seat belt","Only passengers age 21 or older"],"h1":"The rule keeps friends out of the car at first.","h2":"For the first six months, a South Dakota restricted minor's permit holder may carry only immediate family or members of the same household, because friends in the car raise crash risk.","p":"Right. Only family or household members for the first six months."},"es":{"q":"En Dakota del Sur, durante los primeros seis meses del permiso restringido de menor, ¿quién puede ir como pasajero?","o":["Solo familia directa o personas de su hogar","Hasta dos amigos menores de 18","Cualquier pasajero con cinturón","Solo pasajeros de 21 años o más"],"h1":"La regla deja a los amigos fuera del carro al principio.","h2":"Durante los primeros seis meses, quien tiene permiso restringido de menor en Dakota del Sur solo puede llevar a su familia directa o a personas de su mismo hogar, porque los amigos en el carro aumentan el riesgo de choque.","p":"Correcto. Solo familia o personas del hogar los primeros seis meses."},"ref":{"doc":"SD","page":8}},{"id":"sd-012","scope":"SD","cat":"licensing","sign":null,"c":3,"en":{"q":"In South Dakota, after the first six months of a restricted minor's permit, how many non-family passengers under 18 may ride along?","o":["None at all","Two","Three","One"],"h1":"The limit is the smallest number above zero.","h2":"After six months, a South Dakota restricted minor's permit holder may carry no more than one passenger under 18 who is not family or from the same household.","p":"Right. Only one young non-family passenger."},"es":{"q":"En Dakota del Sur, después de los primeros seis meses del permiso restringido de menor, ¿cuántos pasajeros menores de 18 que no son familia pueden ir?","o":["Ninguno","Dos","Tres","Uno"],"h1":"El límite es el número más pequeño mayor que cero.","h2":"Después de seis meses, quien tiene permiso restringido de menor en Dakota del Sur puede llevar como máximo un pasajero menor de 18 que no sea de su familia ni de su hogar.","p":"Correcto. Solo un pasajero joven que no sea de la familia."},"ref":{"doc":"SD","page":null}},{"id":"sd-013","scope":"SD","cat":"licensing","sign":null,"c":2,"en":{"q":"In South Dakota, what is the youngest age for a full operator's license?","o":["15 years old","15 and a half","16 years old","17 years old"],"h1":"It comes two years after the instruction permit age.","h2":"A South Dakota teen can get a full operator's license at 16, after holding a restricted minor's permit for six months with no traffic convictions.","p":"Right. The full license starts at age 16."},"es":{"q":"En Dakota del Sur, ¿cuál es la edad mínima para la licencia de operador completa?","o":["15 años","15 años y medio","16 años","17 años"],"h1":"Es dos años después de la edad del permiso de instrucción.","h2":"En Dakota del Sur un joven puede obtener la licencia de operador completa a los 16 años, después de tener el permiso restringido de menor seis meses sin infracciones de tránsito.","p":"Correcto. La licencia completa empieza a los 16 años."},"ref":{"doc":"SD","page":8}},{"id":"sd-014","scope":"SD","cat":"licensing","sign":null,"c":1,"en":{"q":"In South Dakota, a teen may not get a restricted minor's permit if they had a traffic conviction within the past how many months?","o":["3 months","6 months","12 months","24 months"],"h1":"It is half a year.","h2":"A South Dakota teen must have no traffic convictions in the six months before applying for a restricted minor's permit, which shows safe driving first.","p":"Right. No traffic convictions in the past six months."},"es":{"q":"En Dakota del Sur, ¿cuántos meses seguidos sin infracciones de tránsito necesita un joven antes de obtener el permiso restringido de menor?","o":["3 meses","6 meses","12 meses","24 meses"],"h1":"Es medio año.","h2":"En Dakota del Sur un joven no debe tener infracciones de tránsito en los seis meses antes de solicitar el permiso restringido de menor, para mostrar primero que maneja con seguridad.","p":"Correcto. Sin infracciones en los últimos seis meses."},"ref":{"doc":"SD","page":8}},{"id":"sd-015","scope":"SD","cat":"licensing","sign":null,"c":0,"en":{"q":"In South Dakota, what happens to a permit holder under 16 who is convicted of a traffic violation or breaks the permit limits?","o":["A 30-day suspension","Only a written warning","A free safety video","Nothing until age 18"],"h1":"The driver loses the right to drive for a short time.","h2":"In South Dakota a permit holder under 16 who is convicted of a traffic violation or breaks the permit limits has the permit suspended for 30 days.","p":"Right. It means a 30-day suspension."},"es":{"q":"En Dakota del Sur, ¿qué le pasa a quien tiene un permiso y es menor de 16 años si lo condenan por una infracción de tránsito o no cumple los límites del permiso?","o":["Una suspensión de 30 días","Solo una advertencia escrita","Un video gratis de seguridad","Nada hasta cumplir 18"],"h1":"El conductor pierde el derecho de manejar por un tiempo corto.","h2":"En Dakota del Sur, si una persona menor de 16 años con permiso es condenada por una infracción de tránsito o no cumple los límites del permiso, su permiso se suspende por 30 días.","p":"Correcto. Significa una suspensión de 30 días."},"ref":{"doc":"SD","page":null}},{"id":"sd-016","scope":"SD","cat":"licensing","sign":null,"c":3,"en":{"q":"In South Dakota, what score do you need to pass the knowledge test?","o":["60 percent or higher","70 percent or higher","75 percent or higher","80 percent or higher"],"h1":"It is four out of every five questions.","h2":"To pass the South Dakota knowledge test you need a score of 80 percent or higher.","p":"Right. You need 80 percent to pass."},"es":{"q":"En Dakota del Sur, ¿qué puntaje necesita para aprobar el examen de conocimientos?","o":["60 por ciento o más","70 por ciento o más","75 por ciento o más","80 por ciento o más"],"h1":"Son cuatro de cada cinco preguntas.","h2":"Para aprobar el examen de conocimientos de Dakota del Sur usted necesita un puntaje de 80 por ciento o más.","p":"Correcto. Necesita 80 por ciento para aprobar."},"ref":{"doc":"SD","page":null}},{"id":"sd-017","scope":"SD","cat":"licensing","sign":null,"c":1,"en":{"q":"In South Dakota, in which languages does state law say the written knowledge test must be offered?","o":["English only","English or Spanish","English, French, or German","Any language with a fee"],"h1":"State law names one language besides English.","h2":"South Dakota law says applicants may take the written knowledge test in English or Spanish.","p":"Right. The written test is offered in English or Spanish."},"es":{"q":"En Dakota del Sur, ¿en qué idiomas dice la ley del estado que se debe ofrecer el examen escrito de conocimientos?","o":["Solo en inglés","En inglés o en español","En inglés, francés o alemán","En cualquier idioma, pagando"],"h1":"La ley del estado nombra un idioma además del inglés.","h2":"La ley de Dakota del Sur dice que se puede tomar el examen escrito de conocimientos en inglés o en español.","p":"Correcto. El examen escrito se ofrece en inglés o en español."},"ref":{"doc":"SD","page":null}},{"id":"sd-018","scope":"SD","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In South Dakota, what is the highest posted speed limit on rural stretches of interstate?","o":["65 mph","70 mph","75 mph","80 mph"],"h1":"It is higher than in most states.","h2":"Since 2015, South Dakota law allows up to 80 mph on interstates, and rural stretches may be posted at 80 mph, though the limit is lower near towns.","p":"Right. Rural South Dakota interstates go up to 80 mph."},"es":{"q":"En Dakota del Sur, ¿cuál es el límite de velocidad más alto en los tramos rurales de las interestatales?","o":["65 mph","70 mph","75 mph","80 mph"],"h1":"Es más alto que en la mayoría de los estados.","h2":"Desde 2015, la ley de Dakota del Sur permite hasta 80 mph en las interestatales, y los tramos rurales pueden tener un límite de 80 mph, aunque el límite es más bajo cerca de los pueblos.","p":"Correcto. Las interestatales rurales de Dakota del Sur llegan a 80 mph."},"ref":{"doc":"SD","page":null}},{"id":"sd-019","scope":"SD","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In South Dakota, on a two-lane highway, how much must you slow down for a vehicle on the shoulder with warning lights (limit above 20 mph)?","o":["At least 20 mph below the limit","At least 5 mph below the limit","At least 10 mph below the limit","To exactly 15 mph"],"h1":"The number is the same as the speed in the 20 mph exception.","h2":"Under the South Dakota Move Over law, on a two-lane highway you must slow to at least 20 mph below the posted limit before passing a vehicle with warning lights on the shoulder.","p":"Right. Slow to at least 20 mph below the limit."},"es":{"q":"En Dakota del Sur, en una carretera de dos carriles, ¿cuánto debe bajar la velocidad ante un vehículo en el acotamiento con luces de advertencia (límite mayor de 20 mph)?","o":["Por lo menos 20 mph menos que el límite","Por lo menos 5 mph menos que el límite","Por lo menos 10 mph menos que el límite","Exactamente a 15 mph"],"h1":"Es el mismo número de la excepción de 20 mph.","h2":"Según la ley Move Over de Dakota del Sur, en una carretera de dos carriles usted debe bajar por lo menos a 20 mph menos que el límite antes de pasar junto a un vehículo con luces de advertencia en el acotamiento.","p":"Correcto. Baje por lo menos a 20 mph menos que el límite."},"ref":{"doc":"SD","page":2}},{"id":"sd-020","scope":"SD","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In South Dakota, on a highway with two or more lanes in your direction, when must you move to the lane farthest from a vehicle with warning lights?","o":["Only when you are beside it","Within 50 feet of it","At least 300 feet before it","After you pass it"],"h1":"Start early, about the length of a football field.","h2":"The South Dakota Move Over law says to move into the lane farthest from the vehicle at least 300 feet before reaching it, then proceed with caution.","p":"Right. Move over at least 300 feet before the vehicle."},"es":{"q":"En Dakota del Sur, en una carretera con dos o más carriles en su dirección, ¿cuándo debe pasarse al carril más lejano de un vehículo con luces de advertencia?","o":["Solo cuando esté a su lado","A menos de 50 pies de él","Por lo menos 300 pies antes","Después de pasarlo"],"h1":"Empiece temprano, como a la distancia de una cancha de fútbol americano.","h2":"La ley Move Over de Dakota del Sur dice que usted debe pasarse al carril más lejano del vehículo por lo menos 300 pies antes de llegar a él, y seguir con cuidado.","p":"Correcto. Cámbiese de carril por lo menos 300 pies antes."},"ref":{"doc":"SD","page":2}},{"id":"sd-021","scope":"SD","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In South Dakota, since July 2025, the Move Over law covers vehicles with which lights?","o":["Only red and blue police lights","Amber, yellow, or blue warning lights","Only white headlights","Only lights on fire trucks"],"h1":"The law grew to cover road crews and tow trucks too.","h2":"Since July 2025, the South Dakota Move Over law covers any vehicle on the shoulder showing amber, yellow, or blue warning lights, not only emergency vehicles.","p":"Right. Amber, yellow, and blue warning lights are covered."},"es":{"q":"En Dakota del Sur, desde julio de 2025, la ley Move Over incluye vehículos con ¿qué luces?","o":["Solo luces rojas y azules de policía","Luces de advertencia ámbar, amarillas o azules","Solo luces delanteras blancas","Solo las luces de los bomberos"],"h1":"La ley se amplió para incluir a cuadrillas de carretera y grúas.","h2":"Desde julio de 2025, la ley Move Over de Dakota del Sur incluye a cualquier vehículo en el acotamiento con luces de advertencia ámbar, amarillas o azules, no solo a los vehículos de emergencia.","p":"Correcto. Se incluyen las luces ámbar, amarillas y azules."},"ref":{"doc":"SD","page":2}},{"id":"sd-023","scope":"SD","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In South Dakota, a driver under 21 breaks the law when driving with what blood alcohol level?","o":["0.01 percent or more","0.02 percent or more","0.05 percent or more","0.08 percent or more"],"h1":"It is far below the adult limit.","h2":"In South Dakota a driver under 21 may not drive with a blood alcohol level of 0.02 percent or more, because young drivers should not drink at all.","p":"Right. Under 21, the limit is 0.02 percent."},"es":{"q":"En Dakota del Sur, un conductor menor de 21 años viola la ley si maneja con ¿qué nivel de alcohol en la sangre?","o":["0.01 por ciento o más","0.02 por ciento o más","0.05 por ciento o más","0.08 por ciento o más"],"h1":"Es mucho más bajo que el límite de los adultos.","h2":"En Dakota del Sur un conductor menor de 21 años no puede manejar con 0.02 por ciento de alcohol en la sangre o más, porque los jóvenes no deben tomar nada.","p":"Correcto. Para menores de 21, el límite es 0.02 por ciento."},"ref":{"doc":"SD","page":20}},{"id":"sd-024","scope":"SD","cat":"licensing","sign":null,"c":2,"en":{"q":"In South Dakota, how long is an instruction permit valid?","o":["One year","Two years","Five years","Ten years"],"h1":"It lasts several years.","h2":"A South Dakota instruction permit is valid for five years, so a learner has plenty of time to complete the requirements.","p":"Right. The instruction permit is valid for five years."},"es":{"q":"En Dakota del Sur, ¿por cuánto tiempo es válido el permiso de instrucción?","o":["Un año","Dos años","Cinco años","Diez años"],"h1":"Dura varios años.","h2":"En Dakota del Sur el permiso de instrucción es válido por cinco años, así que el aprendiz tiene mucho tiempo para cumplir los requisitos.","p":"Correcto. El permiso de instrucción es válido por cinco años."},"ref":{"doc":"SD","page":8}},{"id":"tn-001","scope":"TN","cat":"licensing","sign":null,"c":1,"en":{"q":"In Tennessee, what is the youngest age to get a learner permit?","o":["14 years old","15 years old","16 years old","17 years old"],"h1":"It is one year before you can get an intermediate license.","h2":"You can get a Tennessee learner permit at 15 after passing the written and vision tests.","p":"Right. The learner permit starts at age 15."},"es":{"q":"En Tennessee, ¿cuál es la edad mínima para obtener un permiso de aprendiz?","o":["14 años","15 años","16 años","17 años"],"h1":"Es un año antes de poder obtener la licencia intermedia.","h2":"Usted puede obtener el permiso de aprendiz en Tennessee a los 15 años, después de aprobar los exámenes escrito y de la vista.","p":"Correcto. El permiso de aprendiz empieza a los 15 años."},"ref":{"doc":"TN","page":14}},{"id":"tn-002","scope":"TN","cat":"licensing","sign":null,"c":2,"en":{"q":"In Tennessee, who must be in the car when a learner permit holder drives?","o":["Any passenger age 16 or older","A licensed driver 18 or older in the back seat","A licensed driver 21 or older in the front seat","No one, during daylight hours"],"h1":"The helper must be an adult who can reach you and see the road.","h2":"A learner permit holder must always have a licensed driver who is 21 or older sitting in the front seat.","p":"Right. A licensed driver 21 or older must sit in the front seat."},"es":{"q":"En Tennessee, ¿quién debe ir en el carro cuando maneja alguien con permiso de aprendiz?","o":["Cualquier pasajero de 16 años o más","Un conductor con licencia de 18 años o más en el asiento de atrás","Un conductor con licencia de 21 años o más en el asiento de adelante","Nadie, durante el día"],"h1":"El acompañante debe ser un adulto que pueda alcanzarlo y ver el camino.","h2":"Quien tiene permiso de aprendiz siempre debe ir con un conductor con licencia de 21 años o más sentado en el asiento de adelante.","p":"Correcto. Un conductor con licencia de 21 años o más debe ir adelante."},"ref":{"doc":"TN","page":14}},{"id":"tn-003","scope":"TN","cat":"licensing","sign":null,"c":0,"en":{"q":"In Tennessee, during which hours may a learner permit holder not drive?","o":["10 p.m. to 6 a.m.","Midnight to 5 a.m.","11 p.m. to 6 a.m.","9 p.m. to 5 a.m."],"h1":"It starts two hours before midnight.","h2":"A learner permit holder may not drive between 10 p.m. and 6 a.m., even with an adult, because night driving is harder for beginners.","p":"Right. Learners do not drive from 10 p.m. to 6 a.m."},"es":{"q":"En Tennessee, ¿en qué horario no puede manejar quien tiene permiso de aprendiz?","o":["De 10 p.m. a 6 a.m.","De medianoche a 5 a.m.","De 11 p.m. a 6 a.m.","De 9 p.m. a 5 a.m."],"h1":"Empieza dos horas antes de la medianoche.","h2":"Quien tiene permiso de aprendiz no puede manejar entre las 10 p.m. y las 6 a.m., aun con un adulto, porque manejar de noche es más difícil para los principiantes.","p":"Correcto. Los aprendices no manejan de 10 p.m. a 6 a.m."},"ref":{"doc":"TN","page":14}},{"id":"tn-004","scope":"TN","cat":"licensing","sign":null,"c":3,"en":{"q":"In Tennessee, how long must a teen hold a learner permit before getting an intermediate restricted license?","o":["90 days","30 days","One year","180 days"],"h1":"It is about half a year.","h2":"A teen must hold the learner permit for at least 180 days before moving up to the intermediate restricted license.","p":"Right. You must hold the permit for 180 days."},"es":{"q":"En Tennessee, ¿cuánto tiempo debe tener un joven el permiso de aprendiz antes de obtener la licencia intermedia restringida?","o":["90 días","30 días","Un año","180 días"],"h1":"Es más o menos medio año.","h2":"Un joven debe tener el permiso de aprendiz por lo menos 180 días antes de pasar a la licencia intermedia restringida.","p":"Correcto. Debe tener el permiso 180 días."},"ref":{"doc":"TN","page":14}},{"id":"tn-005","scope":"TN","cat":"licensing","sign":null,"c":1,"en":{"q":"In Tennessee, how many hours of driving practice must a teen complete before an intermediate restricted license?","o":["30 hours","50 hours","40 hours","100 hours"],"h1":"It is half of one hundred.","h2":"A teen needs 50 hours of behind-the-wheel practice before an intermediate restricted license, signed off by a parent, guardian or driving instructor.","p":"Right. Tennessee asks for 50 hours of practice."},"es":{"q":"En Tennessee, ¿cuántas horas de práctica de manejo debe completar un joven antes de la licencia intermedia restringida?","o":["30 horas","50 horas","40 horas","100 horas"],"h1":"Es la mitad de cien.","h2":"Un joven necesita 50 horas de práctica al volante antes de la licencia intermedia restringida, certificadas por su padre, madre, tutor o instructor de manejo.","p":"Correcto. Tennessee pide 50 horas de práctica."},"ref":{"doc":"TN","page":14}},{"id":"tn-006","scope":"TN","cat":"licensing","sign":null,"c":2,"en":{"q":"In Tennessee, how many of the required practice hours must be at night?","o":["2 hours","5 hours","10 hours","25 hours"],"h1":"It is one fifth of the total.","h2":"At least 10 of the 50 practice hours must be at night, so the teen has practiced in the dark with help.","p":"Right. At least 10 hours must be at night."},"es":{"q":"En Tennessee, ¿cuántas de las horas de práctica requeridas deben ser de noche?","o":["2 horas","5 horas","10 horas","25 horas"],"h1":"Es la quinta parte del total.","h2":"Por lo menos 10 de las 50 horas de práctica deben ser de noche, para que el joven haya practicado en la oscuridad con ayuda.","p":"Correcto. Por lo menos 10 horas deben ser de noche."},"ref":{"doc":"TN","page":14}},{"id":"tn-007","scope":"TN","cat":"licensing","sign":null,"c":0,"en":{"q":"In Tennessee, what is the youngest age for an intermediate restricted license?","o":["16 years old","15 years old","17 years old","18 years old"],"h1":"It is one year after the learner permit age.","h2":"You can get an intermediate restricted license at 16, after holding your permit 180 days, finishing your practice hours and passing a road test.","p":"Right. The intermediate restricted license starts at 16."},"es":{"q":"En Tennessee, ¿cuál es la edad mínima para la licencia intermedia restringida?","o":["16 años","15 años","17 años","18 años"],"h1":"Es un año después de la edad del permiso de aprendiz.","h2":"Usted puede obtener la licencia intermedia restringida a los 16 años, después de tener el permiso 180 días, terminar sus horas de práctica y aprobar el examen de manejo.","p":"Correcto. La licencia intermedia restringida empieza a los 16."},"ref":{"doc":"TN","page":14}},{"id":"tn-008","scope":"TN","cat":"licensing","sign":null,"c":3,"en":{"q":"In Tennessee, who may sign the form that certifies a teen’s 50 hours of practice?","o":["Any friend who is 18","A school principal","A police officer","A parent, guardian or driving instructor"],"h1":"It is an adult who rode along and is responsible for the teen’s training.","h2":"A parent, legal guardian or driving instructor signs the 50-hour certification form to confirm the teen’s practice.","p":"Right. A parent, guardian or driving instructor signs the form."},"es":{"q":"En Tennessee, ¿quién puede firmar el formulario que certifica las 50 horas de práctica de un joven?","o":["Cualquier amigo de 18 años","El director de la escuela","Un policía","Su padre, madre, tutor o instructor de manejo"],"h1":"Es un adulto que lo acompañó y es responsable de su práctica.","h2":"Su padre, madre, tutor legal o instructor de manejo firma el formulario de certificación de 50 horas para confirmar la práctica del joven.","p":"Correcto. Firma su padre, madre, tutor o instructor de manejo."},"ref":{"doc":"TN","page":14}},{"id":"tn-009","scope":"TN","cat":"licensing","sign":null,"c":2,"en":{"q":"In Tennessee, during which hours may an intermediate restricted driver not drive without a parent or an adult 21 or older?","o":["10 p.m. to 6 a.m.","Midnight to 5 a.m.","11 p.m. to 6 a.m.","9 p.m. to 5 a.m."],"h1":"It is one hour later than the learner permit limit.","h2":"An intermediate restricted driver may not drive from 11 p.m. to 6 a.m. unless a parent, guardian or other allowed adult is in the car, or another exception in the law applies.","p":"Right. Intermediate drivers stay off the road from 11 p.m. to 6 a.m."},"es":{"q":"En Tennessee, ¿en qué horario no puede manejar un conductor con licencia intermedia restringida sin su padre, madre o un adulto de 21 años o más?","o":["De 10 p.m. a 6 a.m.","De medianoche a 5 a.m.","De 11 p.m. a 6 a.m.","De 9 p.m. a 5 a.m."],"h1":"Es una hora más tarde que el límite del permiso de aprendiz.","h2":"Un conductor con licencia intermedia restringida no puede manejar de 11 p.m. a 6 a.m., salvo que vaya su padre, madre, tutor u otro adulto permitido, o que aplique otra excepción de la ley.","p":"Correcto. Los conductores intermedios no manejan de 11 p.m. a 6 a.m."},"ref":{"doc":"TN","page":19}},{"id":"tn-010","scope":"TN","cat":"licensing","sign":null,"c":0,"en":{"q":"In Tennessee, how many passengers may an intermediate restricted driver carry when no licensed adult 21 or older is in the car?","o":["One passenger","No passengers","Two passengers","Three passengers"],"h1":"More than zero, but fewer than two.","h2":"An intermediate restricted driver may carry only one passenger unless a licensed driver 21 or older is in the car, because more young passengers raise crash risk.","p":"Right. Only one passenger without an adult."},"es":{"q":"En Tennessee, ¿cuántos pasajeros puede llevar un conductor con licencia intermedia restringida si no va un adulto con licencia de 21 años o más?","o":["Un pasajero","Ningún pasajero","Dos pasajeros","Tres pasajeros"],"h1":"Más que cero, pero menos que dos.","h2":"Un conductor con licencia intermedia restringida solo puede llevar un pasajero, salvo que vaya un conductor con licencia de 21 años o más, porque más pasajeros jóvenes aumentan el riesgo de choque.","p":"Correcto. Solo un pasajero sin un adulto."},"ref":{"doc":"TN","page":19}},{"id":"tn-011","scope":"TN","cat":"licensing","sign":null,"c":3,"en":{"q":"In Tennessee, how long must a driver hold the intermediate restricted license before moving to the intermediate unrestricted license?","o":["Three months","Six months","Two years","One year"],"h1":"It is twelve months.","h2":"A driver must hold the intermediate restricted license for one year, without disqualifying violations, before moving up to the unrestricted license.","p":"Right. The restricted license is held for one year."},"es":{"q":"En Tennessee, ¿cuánto tiempo debe tener un conductor la licencia intermedia restringida antes de pasar a la licencia intermedia sin restricciones?","o":["Tres meses","Seis meses","Dos años","Un año"],"h1":"Son doce meses.","h2":"Un conductor debe tener la licencia intermedia restringida por un año, sin infracciones que lo descalifiquen, antes de pasar a la licencia sin restricciones.","p":"Correcto. La licencia restringida se tiene por un año."},"ref":{"doc":"TN","page":14}},{"id":"tn-012","scope":"TN","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Tennessee, what is the rule on phones for drivers with a learner permit or an intermediate license?","o":["They may text only at red lights","They may not use a cell phone while driving","They may use a phone if it is on speaker","They may call only family members"],"h1":"The rule for new drivers is stricter than for adults.","h2":"Drivers with a learner permit or an intermediate license may not use a cell phone while driving, so all their attention stays on the road.","p":"Right. New Tennessee drivers may not use a phone while driving."},"es":{"q":"En Tennessee, ¿cuál es la regla sobre teléfonos para conductores con permiso de aprendiz o licencia intermedia?","o":["Pueden escribir textos solo en luces rojas","No pueden usar el celular mientras manejan","Pueden usar el teléfono si está en altavoz","Pueden llamar solo a familiares"],"h1":"La regla para conductores nuevos es más estricta que para adultos.","h2":"Los conductores con permiso de aprendiz o licencia intermedia no pueden usar el celular mientras manejan, para que toda su atención esté en el camino.","p":"Correcto. Los conductores nuevos en Tennessee no pueden usar el teléfono al manejar."},"ref":{"doc":"TN","page":18}},{"id":"tn-013","scope":"TN","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Tennessee, what does the hands-free law forbid for all drivers?","o":["Using a phone mounted on the dashboard","Making a call with an earpiece","Holding a phone with any part of the body","Calling 911 in an emergency"],"h1":"Your hands, and even your shoulder, must stay free of the phone.","h2":"Tennessee’s hands-free law forbids every driver from holding a phone with any part of the body while driving.","p":"Right. Drivers may not hold a phone with any part of the body."},"es":{"q":"En Tennessee, ¿qué prohíbe la ley de manos libres a todos los conductores?","o":["Usar un teléfono montado en el tablero","Hacer una llamada con un audífono","Sostener el teléfono con cualquier parte del cuerpo","Llamar al 911 en una emergencia"],"h1":"Sus manos, y hasta su hombro, deben quedar libres del teléfono.","h2":"La ley de manos libres de Tennessee prohíbe a todo conductor sostener un teléfono con cualquier parte del cuerpo mientras maneja.","p":"Correcto. No puede sostener el teléfono con ninguna parte del cuerpo."},"ref":{"doc":"TN","page":30}},{"id":"tn-014","scope":"TN","cat":"licensing","sign":null,"c":0,"en":{"q":"In Tennessee, how many questions are on the knowledge test for a learner permit?","o":["30 questions","20 questions","25 questions","50 questions"],"h1":"It is a round number between 25 and 50.","h2":"The Tennessee knowledge test has 30 questions about road rules and signs.","p":"Right. The Tennessee test has 30 questions."},"es":{"q":"En Tennessee, ¿cuántas preguntas tiene el examen de conocimientos para el permiso de aprendiz?","o":["30 preguntas","20 preguntas","25 preguntas","50 preguntas"],"h1":"Es un número redondo entre 25 y 50.","h2":"El examen de conocimientos de Tennessee tiene 30 preguntas sobre reglas de tránsito y señales.","p":"Correcto. El examen de Tennessee tiene 30 preguntas."},"ref":{"doc":"TN","page":null}},{"id":"tn-015","scope":"TN","cat":"licensing","sign":null,"c":3,"en":{"q":"In Tennessee, what score do you need to pass the knowledge test?","o":["At least 60 percent","At least 70 percent","At least 90 percent","At least 80 percent"],"h1":"You can miss only one question in five.","h2":"You need at least 80 percent to pass, which means 24 correct answers out of 30.","p":"Right. You need 80 percent, or 24 of 30."},"es":{"q":"En Tennessee, ¿qué puntaje necesita para aprobar el examen de conocimientos?","o":["Por lo menos 60 por ciento","Por lo menos 70 por ciento","Por lo menos 90 por ciento","Por lo menos 80 por ciento"],"h1":"Solo puede fallar una pregunta de cada cinco.","h2":"Necesita por lo menos 80 por ciento para aprobar, es decir, 24 respuestas correctas de 30.","p":"Correcto. Necesita 80 por ciento, o 24 de 30."},"ref":{"doc":"TN","page":null}},{"id":"tn-016","scope":"TN","cat":"licensing","sign":null,"c":1,"en":{"q":"In Tennessee, in which languages can you take the online knowledge test?","o":["English only","English and Spanish","Spanish only","Any language you choose"],"h1":"One of them is the language of this sentence.","h2":"The online knowledge test in Tennessee is offered in English and in Spanish.","p":"Right. The online test is in English and Spanish."},"es":{"q":"En Tennessee, ¿en qué idiomas puede hacer el examen de conocimientos en línea?","o":["Solo en inglés","En inglés y en español","Solo en español","En cualquier idioma que elija"],"h1":"Uno de ellos es el idioma de esta oración.","h2":"El examen de conocimientos en línea de Tennessee se ofrece en inglés y en español.","p":"Correcto. El examen en línea está en inglés y en español."},"ref":{"doc":"TN","page":null}},{"id":"tn-017","scope":"TN","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Tennessee, you approach a stopped emergency vehicle with flashing lights. What does the move-over law require?","o":["Honk to warn the crew","Stop completely in your lane","Move to a lane farther away if safe, or else slow down","Pass at the same speed in the next lane"],"h1":"Give the crew more room, or more time.","h2":"You must move into a lane away from the stopped vehicle when it is safe; if you cannot, you must slow down as you pass.","p":"Right. Move over if it is safe, or slow down."},"es":{"q":"En Tennessee, usted se acerca a un vehículo de emergencia detenido con luces intermitentes. ¿Qué exige la ley de cambio de carril?","o":["Tocar la bocina para avisar al equipo","Detenerse por completo en su carril","Pasarse a un carril más lejano si es seguro, o si no, bajar la velocidad","Pasar a la misma velocidad en el carril de al lado"],"h1":"Déle al equipo más espacio, o más tiempo.","h2":"Usted debe pasarse a un carril alejado del vehículo detenido cuando sea seguro; si no puede, debe bajar la velocidad al pasar.","p":"Correcto. Cámbiese de carril si es seguro, o baje la velocidad."},"ref":{"doc":"TN","page":55}},{"id":"tn-018","scope":"TN","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Tennessee, besides emergency vehicles, which of these must you move over or slow down for?","o":["Any stopped vehicle with its flashing lights on","Only police cars","Only tow trucks","Only vehicles parked in a driveway"],"h1":"Since 2017 the law covers more than work vehicles.","h2":"Tennessee’s move-over law covers tow trucks, road crews, utility and garbage trucks, and also any stopped vehicle with its flashing lights on.","p":"Right. Move over or slow down for any stopped vehicle with flashing lights."},"es":{"q":"En Tennessee, además de los vehículos de emergencia, ¿por cuál de estos debe cambiarse de carril o bajar la velocidad?","o":["Cualquier vehículo detenido con sus luces intermitentes encendidas","Solo carros de policía","Solo grúas","Solo vehículos estacionados en una entrada de casa"],"h1":"Desde 2017 la ley cubre más que vehículos de trabajo.","h2":"La ley de Tennessee cubre grúas, cuadrillas de carreteras, camiones de servicios públicos y de basura, y también cualquier vehículo detenido con luces intermitentes.","p":"Correcto. Cámbiese de carril o baje la velocidad por cualquier vehículo detenido con luces intermitentes."},"ref":{"doc":"TN","page":72}},{"id":"tn-019","scope":"TN","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Tennessee, a school bus stops with flashing red lights on the other side of a highway divided by a median. What should you do?","o":["Stop until the bus moves","Speed up to pass quickly","Stop only if children are outside","Keep going with caution; you do not need to stop"],"h1":"The median separates you from the children.","h2":"On a highway divided by a median or barrier, traffic going the other way does not need to stop for the bus but must drive with care; traffic behind the bus must stop.","p":"Right. On the far side of a divided highway, go on with caution."},"es":{"q":"En Tennessee, un autobús escolar se detiene con luces rojas intermitentes en el otro lado de una carretera dividida por un camellón. ¿Qué debe hacer?","o":["Detenerse hasta que el autobús avance","Acelerar para pasar rápido","Detenerse solo si hay niños afuera","Seguir con precaución; no necesita detenerse"],"h1":"El camellón lo separa de los niños.","h2":"En una carretera dividida por un camellón o barrera, el tráfico que va en sentido contrario no necesita detenerse por el autobús, pero debe manejar con cuidado; el tráfico detrás del autobús sí debe detenerse.","p":"Correcto. Del otro lado de una carretera dividida, siga con precaución."},"ref":{"doc":"TN","page":51}},{"id":"tn-020","scope":"TN","cat":"licensing","sign":null,"c":1,"en":{"q":"In Tennessee, a driver 21 or older is legally drunk at what blood alcohol level?","o":["0.05 percent or more","0.08 percent or more","0.10 percent or more","0.12 percent or more"],"h1":"It is less than one tenth of one percent.","h2":"A driver 21 or older breaks Tennessee’s drunk driving law at a blood alcohol level of 0.08 percent or more.","p":"Right. The adult limit is 0.08 percent."},"es":{"q":"En Tennessee, ¿con qué nivel de alcohol en la sangre se considera legalmente ebrio a un conductor de 21 años o más?","o":["0.05 por ciento o más","0.08 por ciento o más","0.10 por ciento o más","0.12 por ciento o más"],"h1":"Es menos de una décima de uno por ciento.","h2":"Un conductor de 21 años o más viola la ley de Tennessee sobre manejar ebrio con 0.08 por ciento o más de alcohol en la sangre.","p":"Correcto. El límite para adultos es 0.08 por ciento."},"ref":{"doc":"TN","page":81}},{"id":"tn-021","scope":"TN","cat":"licensing","sign":null,"c":0,"en":{"q":"In Tennessee, a driver under 21 breaks the law at what blood alcohol level?","o":["0.02 percent or more","0.05 percent or more","0.08 percent or more","0.10 percent or more"],"h1":"It is a very small amount, far below the adult limit.","h2":"Tennessee’s underage law makes it illegal for a driver under 21 to drive with a blood alcohol level of 0.02 percent or more.","p":"Right. The limit under 21 is 0.02 percent."},"es":{"q":"En Tennessee, ¿con qué nivel de alcohol en la sangre viola la ley un conductor menor de 21 años?","o":["0.02 por ciento o más","0.05 por ciento o más","0.08 por ciento o más","0.10 por ciento o más"],"h1":"Es una cantidad muy pequeña, muy por debajo del límite de adultos.","h2":"La ley de Tennessee para menores prohíbe manejar a un conductor menor de 21 años con 0.02 por ciento o más de alcohol en la sangre.","p":"Correcto. El límite para menores de 21 es 0.02 por ciento."},"ref":{"doc":"TN","page":83}},{"id":"tn-022","scope":"TN","cat":"licensing","sign":null,"c":2,"en":{"q":"In Tennessee, what is the minimum liability insurance a driver must carry?","o":["$15,000 / $30,000 / $5,000","$50,000 / $100,000 / $25,000","$25,000 / $50,000 / $25,000","$100,000 / $300,000 / $50,000"],"h1":"The first and last numbers are the same.","h2":"Tennessee requires at least $25,000 for injury to one person, $50,000 for injuries in one crash, and $25,000 for property damage.","p":"Right. Tennessee minimums are 25/50/25."},"es":{"q":"En Tennessee, ¿cuál es el seguro mínimo de responsabilidad que debe tener un conductor?","o":["$15,000 / $30,000 / $5,000","$50,000 / $100,000 / $25,000","$25,000 / $50,000 / $25,000","$100,000 / $300,000 / $50,000"],"h1":"El primer y el último número son iguales.","h2":"Tennessee exige por lo menos $25,000 por lesiones a una persona, $50,000 por lesiones en un choque y $25,000 por daños a la propiedad.","p":"Correcto. Los mínimos en Tennessee son 25/50/25."},"ref":{"doc":"TN","page":null}},{"id":"tx-001","scope":"TX","cat":"licensing","sign":null,"c":1,"en":{"q":"In Texas, what is the youngest age to get a learner license?","o":["14 years old","15 years old","16 years old","17 years old"],"h1":"It is one year before you can get a provisional license.","h2":"You can get a Texas learner license at 15, which lets you practice for a year before the provisional license at 16.","p":"Right. The Texas learner license starts at 15."},"es":{"q":"En Texas, ¿cuál es la edad mínima para obtener una licencia de aprendiz?","o":["14 años","15 años","16 años","17 años"],"h1":"Es un año antes de poder obtener la licencia provisional.","h2":"Usted puede obtener la licencia de aprendiz en Texas a los 15 años, lo que le permite practicar un año antes de la licencia provisional a los 16.","p":"Correcto. La licencia de aprendiz en Texas empieza a los 15."},"ref":{"doc":"TX","page":1}},{"id":"tx-002","scope":"TX","cat":"licensing","sign":null,"c":3,"en":{"q":"In Texas, how old must the licensed person beside a learner driver be?","o":["At least 16","At least 18","At least 25","At least 21"],"h1":"The helper must be an adult who can legally drink.","h2":"A Texas learner must drive with a licensed person who is at least 21 years old, so an experienced adult is guiding them.","p":"Right. The person beside you must be 21 or older."},"es":{"q":"En Texas, ¿qué edad debe tener la persona con licencia que va al lado de un conductor aprendiz?","o":["Por lo menos 16","Por lo menos 18","Por lo menos 25","Por lo menos 21"],"h1":"El acompañante debe ser un adulto que ya puede tomar alcohol legalmente.","h2":"Un aprendiz en Texas debe manejar con una persona con licencia de por lo menos 21 años, para que lo guíe un adulto con experiencia.","p":"Correcto. Su acompañante debe tener 21 años o más."},"ref":{"doc":"TX","page":1}},{"id":"tx-003","scope":"TX","cat":"licensing","sign":null,"c":0,"en":{"q":"In Texas, how much driving experience must the person supervising a learner have?","o":["At least one year","At least one month","At least five years","At least ten years"],"h1":"It is the shortest period that still means real experience.","h2":"The adult with a Texas learner must have at least one year of driving experience, so they know the road well enough to guide a beginner.","p":"Right. The supervisor needs at least one year of experience."},"es":{"q":"En Texas, ¿cuánta experiencia de manejo debe tener la persona que supervisa a un aprendiz?","o":["Por lo menos un año","Por lo menos un mes","Por lo menos cinco años","Por lo menos diez años"],"h1":"Es el periodo más corto que todavía significa experiencia real.","h2":"El adulto que acompaña a un aprendiz en Texas debe tener por lo menos un año de experiencia manejando, para conocer bien la vía y guiar a un principiante.","p":"Correcto. El supervisor necesita por lo menos un año de experiencia."},"ref":{"doc":"TX","page":1}},{"id":"tx-004","scope":"TX","cat":"licensing","sign":null,"c":2,"en":{"q":"In Texas, where must the supervising adult sit when a learner is driving?","o":["In any back seat","Anywhere in the vehicle","In the seat beside the driver","In the middle of the back seat"],"h1":"They must be able to reach and help right away.","h2":"The supervising adult must sit in the seat beside a Texas learner, so they can see the road and help quickly.","p":"Right. The supervisor sits beside the learner."},"es":{"q":"En Texas, ¿dónde debe sentarse el adulto supervisor cuando maneja un aprendiz?","o":["En cualquier asiento de atrás","En cualquier lugar del vehículo","En el asiento al lado del conductor","En el centro del asiento de atrás"],"h1":"Debe poder alcanzar y ayudar enseguida.","h2":"El adulto supervisor debe sentarse al lado del aprendiz en Texas, para ver la vía y ayudar rápido.","p":"Correcto. El supervisor se sienta al lado del aprendiz."},"ref":{"doc":"TX","page":1}},{"id":"tx-005","scope":"TX","cat":"licensing","sign":null,"c":1,"en":{"q":"In Texas, what must a teen finish before getting a learner license?","o":["A full year of supervised driving","The classroom part of driver education","A road test with an examiner","A first aid course"],"h1":"It happens in a classroom or a parent-taught course, before the wheel.","h2":"A Texas teen must finish the classroom part of an approved driver education course and pass the knowledge test before getting a learner license.","p":"Right. Finish the classroom part of driver education first."},"es":{"q":"En Texas, ¿qué debe terminar un adolescente antes de obtener la licencia de aprendiz?","o":["Un año completo de manejo supervisado","La parte de clases de la educación vial","Un examen de manejo con un examinador","Un curso de primeros auxilios"],"h1":"Se hace en un salón o en un curso enseñado por los padres, antes de manejar.","h2":"Un adolescente en Texas debe terminar la parte de clases de un curso aprobado de educación vial y aprobar el examen de conocimientos antes de obtener la licencia de aprendiz.","p":"Correcto. Primero se termina la parte de clases de educación vial."},"ref":{"doc":"TX","page":1}},{"id":"tx-006","scope":"TX","cat":"licensing","sign":null,"c":2,"en":{"q":"In Texas, how long must a teen hold a learner license before getting a provisional license?","o":["1 month","3 months","6 months","2 years"],"h1":"It is half a year.","h2":"A Texas teen must hold the learner license for at least 6 months before applying for a provisional license.","p":"Right. Hold the learner license for at least 6 months."},"es":{"q":"En Texas, ¿cuánto tiempo debe tener un adolescente la licencia de aprendiz antes de obtener la licencia provisional?","o":["1 mes","3 meses","6 meses","2 años"],"h1":"Es medio año.","h2":"Un adolescente en Texas debe tener la licencia de aprendiz por lo menos 6 meses antes de solicitar la licencia provisional.","p":"Correcto. Debe tenerla por lo menos 6 meses."},"ref":{"doc":"TX","page":2}},{"id":"tx-007","scope":"TX","cat":"licensing","sign":null,"c":0,"en":{"q":"In Texas, what is the youngest age to get a provisional license?","o":["16 years old","15 years old","17 years old","18 years old"],"h1":"It comes one year after the learner license.","h2":"A Texas teen can get a provisional license at 16 after holding a learner license for at least 6 months.","p":"Right. The provisional license starts at 16."},"es":{"q":"En Texas, ¿cuál es la edad mínima para obtener la licencia provisional?","o":["16 años","15 años","17 años","18 años"],"h1":"Viene un año después de la licencia de aprendiz.","h2":"Un adolescente en Texas puede obtener la licencia provisional a los 16 años, después de tener la licencia de aprendiz por lo menos 6 meses.","p":"Correcto. La licencia provisional empieza a los 16."},"ref":{"doc":"TX","page":3}},{"id":"tx-008","scope":"TX","cat":"licensing","sign":null,"c":1,"en":{"q":"In Texas, how many hours of supervised driving must a teen log, including night driving?","o":["20 hours","30 hours","40 hours","50 hours"],"h1":"Ten of these hours are at night.","h2":"A Texas teen must log 30 hours of supervised driving, including 10 hours at night, before the provisional license.","p":"Right. Texas asks for 30 supervised hours."},"es":{"q":"En Texas, ¿cuántas horas de manejo supervisado debe registrar un adolescente, incluidas las de noche?","o":["20 horas","30 horas","40 horas","50 horas"],"h1":"Diez de estas horas son de noche.","h2":"Un adolescente en Texas debe registrar 30 horas de manejo supervisado, incluidas 10 horas de noche, antes de la licencia provisional.","p":"Correcto. Texas pide 30 horas supervisadas."},"ref":{"doc":"TX","page":null}},{"id":"tx-009","scope":"TX","cat":"licensing","sign":null,"c":3,"en":{"q":"In Texas, how many of the supervised practice hours must be at night?","o":["2 hours","5 hours","15 hours","10 hours"],"h1":"It is one third of the 30 hours.","h2":"At least 10 of the 30 supervised hours in Texas must be at night, because driving in the dark is different and needs practice.","p":"Right. 10 of the hours must be at night."},"es":{"q":"En Texas, ¿cuántas de las horas de práctica supervisada deben ser de noche?","o":["2 horas","5 horas","15 horas","10 horas"],"h1":"Es la tercera parte de las 30 horas.","h2":"Por lo menos 10 de las 30 horas supervisadas en Texas deben ser de noche, porque manejar en la oscuridad es distinto y necesita práctica.","p":"Correcto. 10 de las horas deben ser de noche."},"ref":{"doc":"TX","page":null}},{"id":"tx-010","scope":"TX","cat":"licensing","sign":null,"c":2,"en":{"q":"In Texas, what video course must a teen finish within 90 days before the road test?","o":["Texas Safe Teens","Drive Smart Texas","Impact Texas Teen Drivers","Texas Road Ready"],"h1":"Its name includes the word Impact.","h2":"A Texas teen must complete the Impact Texas Teen Drivers course within 90 days before the driving test.","p":"Right. The course is Impact Texas Teen Drivers."},"es":{"q":"En Texas, ¿qué curso en video debe terminar un adolescente dentro de los 90 días antes del examen de manejo?","o":["Texas Safe Teens","Drive Smart Texas","Impact Texas Teen Drivers","Texas Road Ready"],"h1":"Su nombre incluye la palabra Impact.","h2":"Un adolescente en Texas debe completar el curso Impact Texas Teen Drivers dentro de los 90 días antes del examen de manejo.","p":"Correcto. El curso es Impact Texas Teen Drivers."},"ref":{"doc":"TX","page":null}},{"id":"tx-011","scope":"TX","cat":"licensing","sign":null,"c":0,"en":{"q":"In Texas, a driver under 18 with a provisional license may not drive during which hours?","o":["Midnight to 5 a.m.","10 p.m. to 6 a.m.","9 p.m. to 5 a.m.","11 p.m. to 4 a.m."],"h1":"The limit starts when a new day begins.","h2":"A Texas driver under 18 with a provisional license may not drive from midnight to 5 a.m., except for work, a school activity or a medical emergency.","p":"Right. No driving from midnight to 5 a.m."},"es":{"q":"En Texas, un conductor menor de 18 con licencia provisional no puede manejar en ¿qué horario?","o":["De medianoche a 5 a.m.","De 10 p.m. a 6 a.m.","De 9 p.m. a 5 a.m.","De 11 p.m. a 4 a.m."],"h1":"El límite empieza cuando comienza un nuevo día.","h2":"Un conductor menor de 18 con licencia provisional en Texas no puede manejar de medianoche a 5 a.m., salvo por trabajo, una actividad escolar o una emergencia médica.","p":"Correcto. No se maneja de medianoche a 5 a.m."},"ref":{"doc":"TX","page":3}},{"id":"tx-012","scope":"TX","cat":"licensing","sign":null,"c":3,"en":{"q":"In Texas, a 16-year-old with a provisional license wants to drive at 1 a.m. Which reason is allowed?","o":["Going to a party","Getting fast food","Visiting a friend","Driving home from work"],"h1":"Only work, school activities and medical emergencies count.","h2":"A Texas provisional driver under 18 may drive between midnight and 5 a.m. only for work, a school-related activity or a medical emergency, so driving home from work is allowed.","p":"Right. Driving for work is one of the allowed reasons."},"es":{"q":"En Texas, un joven de 16 años con licencia provisional quiere manejar a la 1 a.m. ¿Qué motivo está permitido?","o":["Ir a una fiesta","Comprar comida rápida","Visitar a un amigo","Regresar a casa del trabajo"],"h1":"Solo cuentan el trabajo, las actividades escolares y las emergencias médicas.","h2":"Un conductor provisional menor de 18 en Texas puede manejar entre medianoche y 5 a.m. solo por trabajo, una actividad escolar o una emergencia médica, así que regresar del trabajo está permitido.","p":"Correcto. Manejar por trabajo es uno de los motivos permitidos."},"ref":{"doc":"TX","page":3}},{"id":"tx-013","scope":"TX","cat":"licensing","sign":null,"c":1,"en":{"q":"In Texas, how many passengers under 21 who are not family may a provisional driver under 18 carry?","o":["None","One","Two","Three"],"h1":"It is the smallest number above zero.","h2":"A Texas provisional driver under 18 may carry no more than one passenger under 21 who is not a family member, because young passengers distract new drivers.","p":"Right. Only one young passenger who is not family."},"es":{"q":"En Texas, ¿cuántos pasajeros menores de 21 que no son familiares puede llevar un conductor provisional menor de 18?","o":["Ninguno","Uno","Dos","Tres"],"h1":"Es el número más pequeño mayor que cero.","h2":"Un conductor provisional menor de 18 en Texas puede llevar como máximo un pasajero menor de 21 que no sea familiar, porque los pasajeros jóvenes distraen a los conductores nuevos.","p":"Correcto. Solo un pasajero joven que no sea familiar."},"ref":{"doc":"TX","page":3}},{"id":"tx-014","scope":"TX","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Texas, may a driver under 18 talk on a phone using a hands-free device while driving?","o":["Yes, hands-free is always allowed","Yes, but only on the highway","No, only in an emergency","Yes, if the call is short"],"h1":"Teen drivers have a stricter rule than adults.","h2":"A Texas driver under 18 may not use any wireless device while driving, hands-free included, except to call for help in an emergency.","p":"Right. Under 18, no phone at all except in an emergency."},"es":{"q":"En Texas, ¿puede un conductor menor de 18 hablar por teléfono con manos libres mientras maneja?","o":["Sí, manos libres siempre está permitido","Sí, pero solo en la autopista","No, solo en una emergencia","Sí, si la llamada es corta"],"h1":"Los conductores adolescentes tienen una regla más estricta que los adultos.","h2":"Un conductor menor de 18 en Texas no puede usar ningún aparato inalámbrico mientras maneja, ni siquiera con manos libres, salvo para pedir ayuda en una emergencia.","p":"Correcto. Menor de 18, nada de teléfono salvo en emergencia."},"ref":{"doc":"TX","page":3}},{"id":"tx-015","scope":"TX","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Texas, is it legal for an adult driver to text while driving?","o":["No, texting while driving is illegal statewide","Yes, outside of school zones","Yes, below 30 mph","Yes, on rural roads only"],"h1":"The rule covers every driver, everywhere in Texas.","h2":"Texas law makes it illegal for every driver to read, write or send text messages while driving, anywhere in the state.","p":"Right. Texting while driving is illegal in all of Texas."},"es":{"q":"En Texas, ¿es legal que un conductor adulto envíe mensajes de texto mientras maneja?","o":["No, es ilegal en todo el estado","Sí, fuera de las zonas escolares","Sí, a menos de 30 mph","Sí, solo en caminos rurales"],"h1":"La regla es para todos los conductores, en todo Texas.","h2":"La ley de Texas prohíbe a todos los conductores leer, escribir o enviar mensajes de texto mientras manejan, en cualquier parte del estado.","p":"Correcto. Enviar textos al manejar es ilegal en todo Texas."},"ref":{"doc":"TX","page":54}},{"id":"tx-016","scope":"TX","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Texas, what is the rule for hand-held phones in an active school zone?","o":["They are allowed below 20 mph","Drivers may not use them","They are allowed for short calls","Only teens are banned"],"h1":"Children are crossing nearby.","h2":"Texas drivers may not use a hand-held phone in an active school zone, so their eyes and hands stay ready for children; hands-free use and emergency calls are exceptions.","p":"Right. No hand-held phone in an active school zone."},"es":{"q":"En Texas, ¿cuál es la regla para los teléfonos en la mano en una zona escolar activa?","o":["Se permiten a menos de 20 mph","Los conductores no pueden usarlos","Se permiten para llamadas cortas","Solo están prohibidos para adolescentes"],"h1":"Hay niños cruzando cerca.","h2":"En Texas los conductores no pueden usar un teléfono en la mano en una zona escolar activa, para tener la vista y las manos listas por los niños; el uso con manos libres y las llamadas de emergencia son excepciones.","p":"Correcto. No se usa el teléfono en la mano en una zona escolar activa."},"ref":{"doc":"TX","page":31}},{"id":"tx-017","scope":"TX","cat":"licensing","sign":null,"c":2,"en":{"q":"In Texas, what score do you need to pass the driver license knowledge test?","o":["60 percent","65 percent","70 percent","80 percent"],"h1":"It is lower than in many other states.","h2":"Texas requires a score of 70 percent or better on the knowledge test to qualify for a license.","p":"Right. You need 70 percent to pass in Texas."},"es":{"q":"En Texas, ¿qué puntaje necesita para aprobar el examen de conocimientos para la licencia?","o":["60 por ciento","65 por ciento","70 por ciento","80 por ciento"],"h1":"Es más bajo que en muchos otros estados.","h2":"Texas exige 70 por ciento o más en el examen de conocimientos para obtener la licencia.","p":"Correcto. Necesita 70 por ciento para aprobar en Texas."},"ref":{"doc":"TX","page":7}},{"id":"tx-019","scope":"TX","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Texas, you are on a road with a 60 mph limit and you cannot leave the lane next to a stopped police car with flashing lights. How fast may you pass?","o":["40 mph or slower","50 mph or slower","55 mph or slower","60 mph or slower"],"h1":"Take 20 away from the speed limit.","h2":"Texas law says that if you cannot move out of the lane next to a stopped emergency vehicle, you must slow to 20 mph below the limit, so 40 mph on a 60 mph road.","p":"Right. Slow to 20 below the limit, so 40 mph."},"es":{"q":"En Texas, va por una vía con límite de 60 mph y no puede salir del carril junto a una patrulla detenida con luces intermitentes. ¿A qué velocidad puede pasar?","o":["A 40 mph o menos","A 50 mph o menos","A 55 mph o menos","A 60 mph o menos"],"h1":"Réstele 20 al límite de velocidad.","h2":"La ley de Texas dice que si no puede salir del carril junto a un vehículo de emergencia detenido, debe bajar a 20 mph menos que el límite, o sea 40 mph en una vía de 60 mph.","p":"Correcto. Baje a 20 menos que el límite: 40 mph."},"ref":{"doc":"TX","page":23}},{"id":"tx-020","scope":"TX","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Texas, the speed limit is 25 mph. You pass a stopped emergency vehicle with flashing lights and cannot move out of the lane next to it. How fast may you go?","o":["15 mph","5 mph","10 mph","20 mph"],"h1":"Take 20 away from the speed limit.","h2":"On a Texas road posted 25 mph, you must slow to 20 mph below the limit, which is 5 mph, when you pass a stopped emergency vehicle with its lights on.","p":"Right. At a 25 mph limit, pass at 5 mph."},"es":{"q":"En Texas, el límite es 25 mph. Usted pasa junto a un vehículo de emergencia detenido con luces intermitentes y no puede salir del carril de al lado. ¿A qué velocidad puede ir?","o":["15 mph","5 mph","10 mph","20 mph"],"h1":"Réstele 20 al límite de velocidad.","h2":"En una vía de Texas con límite de 25 mph, debe bajar a 20 mph menos que el límite, es decir 5 mph, al pasar junto a un vehículo de emergencia detenido con las luces encendidas.","p":"Correcto. Con límite de 25 mph, pase a 5 mph."},"ref":{"doc":"TX","page":23}},{"id":"tx-021","scope":"TX","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Texas, a school bus with flashing red lights is stopped on the other side of a road divided only by a center left-turn lane. What must you do?","o":["Keep going, the turn lane divides the road","Slow to 20 mph and pass","Stop, because a turn lane does not divide the road","Honk and pass with care"],"h1":"A turn lane is not a barrier.","h2":"In Texas a center left-turn lane does not make separate roadways, so drivers going both ways must stop for a school bus with flashing red lights.","p":"Right. A turn lane does not count; you must stop."},"es":{"q":"En Texas, un autobús escolar con luces rojas intermitentes está detenido al otro lado de una vía dividida solo por un carril central para girar a la izquierda. ¿Qué debe hacer?","o":["Seguir, el carril de giro divide la vía","Bajar a 20 mph y pasar","Parar, porque un carril de giro no divide la vía","Tocar el claxon y pasar con cuidado"],"h1":"Un carril de giro no es una barrera.","h2":"En Texas un carril central para girar a la izquierda no crea vías separadas, así que los conductores en ambos sentidos deben parar ante un autobús escolar con luces rojas intermitentes.","p":"Correcto. El carril de giro no cuenta; debe parar."},"ref":{"doc":"TX","page":null}},{"id":"tx-022","scope":"TX","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Texas, when may you keep going past a stopped school bus with flashing red lights coming the other way?","o":["When no children are in sight","When you are late for work","When the bus is more than 50 feet away","When a physical barrier or median separates the roads"],"h1":"The two directions must be truly separated.","h2":"In Texas you need not stop for a school bus on the other roadway only when the roads are separated by a physical barrier or a space where cars cannot drive.","p":"Right. Only a real barrier or median lets you keep going."},"es":{"q":"En Texas, ¿cuándo puede seguir adelante si viene en sentido contrario a un autobús escolar detenido con luces rojas intermitentes?","o":["Cuando no se ven niños","Cuando va tarde al trabajo","Cuando el autobús está a más de 50 pies","Cuando una barrera física o un camellón separa las vías"],"h1":"Los dos sentidos deben estar realmente separados.","h2":"En Texas no tiene que parar ante un autobús escolar en la otra vía solo cuando las vías están separadas por una barrera física o un espacio por donde no pueden pasar carros.","p":"Correcto. Solo una barrera o un camellón real le permite seguir."},"ref":{"doc":"TX","page":23}},{"id":"tx-023","scope":"TX","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Texas, what fine range applies for a first offense of passing a stopped school bus illegally?","o":["$500 to $1,250","$50 to $200","$100 to $500","$2,000 to $5,000"],"h1":"It starts at five hundred dollars.","h2":"In Texas a first offense of illegally passing a stopped school bus carries a fine of $500 to $1,250, and repeat offenses cost more.","p":"Right. A first offense costs $500 to $1,250."},"es":{"q":"En Texas, ¿qué rango de multa se aplica la primera vez que se pasa ilegalmente un autobús escolar detenido?","o":["De $500 a $1,250","De $50 a $200","De $100 a $500","De $2,000 a $5,000"],"h1":"Empieza en quinientos dólares.","h2":"En Texas, la primera vez que se pasa ilegalmente un autobús escolar detenido la multa es de $500 a $1,250, y si se repite cuesta más.","p":"Correcto. La primera vez cuesta de $500 a $1,250."},"ref":{"doc":"TX","page":23}},{"id":"tx-024","scope":"TX","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Texas, unless a sign says otherwise, what is the speed limit on a street in an urban district?","o":["25 mph","30 mph","35 mph","40 mph"],"h1":"It is a round number that is lower than 35.","h2":"Texas law sets 30 mph as the speed limit on streets in an urban district when no other limit is posted.","p":"Right. The urban district limit is 30 mph."},"es":{"q":"En Texas, si no hay una señal que diga otra cosa, ¿cuál es el límite de velocidad en una calle de zona urbana?","o":["25 mph","30 mph","35 mph","40 mph"],"h1":"Es un número redondo menor que 35.","h2":"La ley de Texas fija 30 mph como límite en las calles de zona urbana cuando no hay otro límite indicado.","p":"Correcto. El límite en zona urbana es 30 mph."},"ref":{"doc":"TX","page":46}},{"id":"tx-025","scope":"TX","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Texas, how much alcohol may a driver under 21 have in their system?","o":["Less than 0.08","Less than 0.05","Less than 0.02","None that can be detected"],"h1":"Texas has zero tolerance for young drivers.","h2":"A Texas driver under 21 commits an offense with any detectable amount of alcohol, even below the adult limit of 0.08.","p":"Right. Under 21 means no detectable alcohol."},"es":{"q":"En Texas, ¿cuánto alcohol puede tener en el cuerpo un conductor menor de 21 años?","o":["Menos de 0.08","Menos de 0.05","Menos de 0.02","Nada que se pueda detectar"],"h1":"Texas tiene tolerancia cero para conductores jóvenes.","h2":"Un conductor menor de 21 en Texas comete un delito con cualquier cantidad de alcohol que se pueda detectar, aunque esté por debajo del límite de 0.08 para adultos.","p":"Correcto. Menor de 21 significa nada de alcohol detectable."},"ref":{"doc":"TX","page":56}},{"id":"tx-026","scope":"TX","cat":"licensing","sign":null,"c":2,"en":{"q":"In Texas, what is the minimum liability insurance for injury to one person in a crash?","o":["$15,000","$25,000","$30,000","$50,000"],"h1":"It is the first number in 30/60/25.","h2":"Texas requires at least $30,000 of bodily injury coverage for one person in a crash, the first number in the 30/60/25 minimum.","p":"Right. The minimum for one injured person is $30,000."},"es":{"q":"En Texas, ¿cuál es el seguro mínimo de responsabilidad por lesiones a una persona en un choque?","o":["$15,000","$25,000","$30,000","$50,000"],"h1":"Es el primer número de 30/60/25.","h2":"Texas exige por lo menos $30,000 de cobertura por lesiones a una persona en un choque, el primer número del mínimo 30/60/25.","p":"Correcto. El mínimo por una persona lesionada es $30,000."},"ref":{"doc":"TX","page":18}},{"id":"tx-027","scope":"TX","cat":"licensing","sign":null,"c":1,"en":{"q":"In Texas, what is the minimum liability insurance for damage to other people's property in one crash?","o":["$10,000","$25,000","$30,000","$60,000"],"h1":"It is the last number in 30/60/25.","h2":"Texas requires at least $25,000 of property damage liability for one crash, the last number in the 30/60/25 minimum.","p":"Right. The property damage minimum is $25,000."},"es":{"q":"En Texas, ¿cuál es el seguro mínimo de responsabilidad por daños a la propiedad de otros en un choque?","o":["$10,000","$25,000","$30,000","$60,000"],"h1":"Es el último número de 30/60/25.","h2":"Texas exige por lo menos $25,000 de cobertura por daños a la propiedad en un choque, el último número del mínimo 30/60/25.","p":"Correcto. El mínimo por daños a la propiedad es $25,000."},"ref":{"doc":"TX","page":18}},{"id":"ut-001","scope":"UT","cat":"licensing","sign":null,"c":1,"en":{"q":"In Utah, what is the youngest age to get a learner permit?","o":["14 years old","15 years old","16 years old","17 years old"],"h1":"It is one year before you can get a driver license.","h2":"In Utah, you can get a learner permit when you are at least 15 years old, one year before you can get a license at 16.","p":"Right. A Utah learner permit starts at age 15."},"es":{"q":"En Utah, ¿cuál es la edad mínima para obtener un permiso de aprendiz?","o":["14 años","15 años","16 años","17 años"],"h1":"Es un año antes de poder obtener la licencia de conducir.","h2":"En Utah, usted puede obtener el permiso de aprendiz cuando tiene por lo menos 15 años, un año antes de poder obtener la licencia a los 16.","p":"Correcto. El permiso de aprendiz en Utah empieza a los 15 años."},"ref":{"doc":"UT","page":7}},{"id":"ut-002","scope":"UT","cat":"licensing","sign":null,"c":2,"en":{"q":"In Utah, how long is a learner permit valid?","o":["6 months","12 months","18 months","24 months"],"h1":"It is a year and a half.","h2":"Utah law says a learner permit is valid for 18 months, which gives a new driver time to practice and finish the requirements.","p":"Right. A Utah learner permit lasts 18 months."},"es":{"q":"En Utah, ¿cuánto tiempo es válido el permiso de aprendiz?","o":["6 meses","12 meses","18 meses","24 meses"],"h1":"Es un año y medio.","h2":"La ley de Utah dice que el permiso de aprendiz es válido por 18 meses, lo que le da tiempo al nuevo conductor para practicar y cumplir los requisitos.","p":"Correcto. El permiso de aprendiz en Utah dura 18 meses."},"ref":{"doc":"UT","page":7}},{"id":"ut-003","scope":"UT","cat":"licensing","sign":null,"c":2,"en":{"q":"In Utah, how many hours of supervised driving must a teen log before getting a license?","o":["20 hours","30 hours","40 hours","60 hours"],"h1":"Ten of these hours must be at night.","h2":"In Utah, a teen must log at least 40 hours of supervised driving, including at least 10 hours at night, before getting a license.","p":"Right. Utah requires 40 supervised hours."},"es":{"q":"En Utah, ¿cuántas horas de manejo supervisado debe registrar un joven antes de obtener la licencia?","o":["20 horas","30 horas","40 horas","60 horas"],"h1":"Diez de estas horas deben ser de noche.","h2":"En Utah, un joven debe registrar por lo menos 40 horas de manejo supervisado, incluidas por lo menos 10 horas de noche, antes de obtener la licencia.","p":"Correcto. Utah exige 40 horas supervisadas."},"ref":{"doc":"UT","page":6}},{"id":"ut-004","scope":"UT","cat":"licensing","sign":null,"c":0,"en":{"q":"In Utah, how many of a teen's supervised practice hours must be at night?","o":["At least 10 hours","At least 2 hours","At least 5 hours","At least 20 hours"],"h1":"It is a small part of the 40 total hours, but more than a few.","h2":"Of the 40 supervised hours Utah requires, at least 10 must be driven at night so the teen gains experience in the dark.","p":"Right. At least 10 of the hours must be at night."},"es":{"q":"En Utah, ¿cuántas de las horas de práctica supervisada de un joven deben ser de noche?","o":["Por lo menos 10 horas","Por lo menos 2 horas","Por lo menos 5 horas","Por lo menos 20 horas"],"h1":"Es una parte pequeña de las 40 horas en total, pero más que unas pocas.","h2":"De las 40 horas supervisadas que exige Utah, por lo menos 10 deben ser de noche para que el joven gane experiencia en la oscuridad.","p":"Correcto. Por lo menos 10 de las horas deben ser de noche."},"ref":{"doc":"UT","page":6}},{"id":"ut-005","scope":"UT","cat":"licensing","sign":null,"c":3,"en":{"q":"In Utah, how long must a 16- or 17-year-old hold a learner permit before getting a license?","o":["30 days","90 days","One year","Six months"],"h1":"It is half of a year.","h2":"In Utah, a driver who is 16 or 17 must hold the learner permit for at least six months before getting a driver license.","p":"Right. Drivers who are 16 or 17 hold the permit for at least six months."},"es":{"q":"En Utah, ¿cuánto tiempo debe tener el permiso de aprendiz un joven de 16 o 17 años antes de obtener la licencia?","o":["30 días","90 días","Un año","Seis meses"],"h1":"Es la mitad de un año.","h2":"En Utah, un conductor de 16 o 17 años debe tener el permiso de aprendiz por lo menos seis meses antes de obtener la licencia de conducir.","p":"Correcto. Los conductores de 16 o 17 años tienen el permiso por lo menos seis meses."},"ref":{"doc":"UT","page":7}},{"id":"ut-006","scope":"UT","cat":"licensing","sign":null,"c":1,"en":{"q":"In Utah, how long must a driver who is 19 or older hold a learner permit before getting a license?","o":["30 days","90 days","Six months","One year"],"h1":"It is shorter than the time for teens, about three months.","h2":"In Utah, a driver who is 19 or older must hold the learner permit for at least 90 days, unless they finish an approved driver education course.","p":"Right. Drivers 19 and older hold the permit for at least 90 days."},"es":{"q":"En Utah, ¿cuánto tiempo debe tener el permiso de aprendiz un conductor de 19 años o más antes de obtener la licencia?","o":["30 días","90 días","Seis meses","Un año"],"h1":"Es menos tiempo que para los jóvenes, unos tres meses.","h2":"En Utah, un conductor de 19 años o más debe tener el permiso de aprendiz por lo menos 90 días, a menos que termine un curso aprobado de educación vial.","p":"Correcto. Los conductores de 19 años o más tienen el permiso por lo menos 90 días."},"ref":{"doc":"UT","page":7}},{"id":"ut-007","scope":"UT","cat":"licensing","sign":null,"c":0,"en":{"q":"In Utah, a driver under 18 with a learner permit must have a qualified adult in which seat?","o":["The seat beside the driver","Any back seat","The seat behind the driver","Any seat in the car"],"h1":"The adult must be close enough to help right away.","h2":"In Utah, a learner under 18 may drive only when a parent or guardian, a driving instructor, or a responsible adult who signed for them sits in the seat beside them.","p":"Right. The adult sits in the seat beside the learner."},"es":{"q":"En Utah, un conductor menor de 18 años con permiso de aprendiz debe llevar a un adulto autorizado. ¿En qué asiento?","o":["En el asiento al lado del conductor","En cualquier asiento trasero","En el asiento detrás del conductor","En cualquier asiento del carro"],"h1":"El adulto debe estar lo bastante cerca para ayudar de inmediato.","h2":"En Utah, un aprendiz menor de 18 años solo puede manejar si un padre o tutor, un instructor de manejo o un adulto responsable que firmó por él va sentado a su lado.","p":"Correcto. El adulto va sentado al lado del aprendiz."},"ref":{"doc":"UT","page":6}},{"id":"ut-008","scope":"UT","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Utah, during which hours may a young driver with a provisional license not drive, unless an exception applies?","o":["10 p.m. to 5 a.m.","11 p.m. to 6 a.m.","9 p.m. to 6 a.m.","Midnight to 5 a.m."],"h1":"The limit starts at the very start of a new day.","h2":"In Utah, a young provisional license holder may not drive from midnight to 5 a.m., unless with a licensed adult 21 or older in front, going to or from work, for a school activity, for farm work, or in an emergency.","p":"Right. Young provisional drivers stay off the road from midnight to 5 a.m."},"es":{"q":"En Utah, ¿en qué horario no puede manejar un conductor joven con licencia provisional, salvo que aplique una excepción?","o":["De 10 p.m. a 5 a.m.","De 11 p.m. a 6 a.m.","De 9 p.m. a 6 a.m.","De medianoche a 5 a.m."],"h1":"El límite empieza justo al inicio de un nuevo día.","h2":"En Utah, un joven con licencia provisional no puede manejar de medianoche a 5 a.m., salvo con un adulto con licencia de 21 años o más en el asiento delantero, para ir o volver del trabajo, por una actividad escolar, por trabajo agrícola o en una emergencia.","p":"Correcto. Los conductores jóvenes con licencia provisional no manejan de medianoche a 5 a.m."},"ref":{"doc":"UT","page":8}},{"id":"ut-009","scope":"UT","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Utah, for how long after getting a provisional license may a teen carry only immediate family members as passengers, unless an exception applies?","o":["The first month","The first six months","The first year","Until age 21"],"h1":"It is half of a year.","h2":"In Utah, for the first six months with a provisional license, a teen may carry only immediate family members, unless a licensed driver 21 or older is in the front seat, the trip is for farm work, or there is an emergency.","p":"Right. For the first six months, only family members may ride along."},"es":{"q":"En Utah, ¿durante cuánto tiempo después de obtener la licencia provisional puede un joven llevar solo a familiares directos como pasajeros, salvo que aplique una excepción?","o":["El primer mes","Los primeros seis meses","El primer año","Hasta los 21 años"],"h1":"Es la mitad de un año.","h2":"En Utah, durante los primeros seis meses con licencia provisional, un joven puede llevar solo a familiares directos, salvo que vaya un conductor con licencia de 21 años o más en el asiento delantero, el viaje sea por trabajo agrícola o haya una emergencia.","p":"Correcto. Durante los primeros seis meses, solo los familiares pueden ir como pasajeros."},"ref":{"doc":"UT","page":8}},{"id":"ut-010","scope":"UT","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Utah, a teen got a provisional license two months ago. When may the teen carry a friend as a passenger?","o":["When the passenger is under 16","When the trip is under 10 miles","When a licensed driver 21 or older is in the front seat","When the teen drives only in daylight"],"h1":"An experienced adult changes the rule.","h2":"In Utah, during the first six months a teen may carry friends only when a licensed driver 21 or older sits in the front seat, or for farm work or an emergency.","p":"Right. A licensed driver 21 or older in front lifts the passenger limit."},"es":{"q":"En Utah, un joven obtuvo la licencia provisional hace dos meses. ¿Cuándo puede llevar a un amigo como pasajero?","o":["Cuando el pasajero es menor de 16 años","Cuando el viaje es de menos de 10 millas","Cuando va un conductor con licencia de 21 años o más en el asiento delantero","Cuando maneja solo de día"],"h1":"Un adulto con experiencia cambia la regla.","h2":"En Utah, durante los primeros seis meses un joven puede llevar amigos solo cuando un conductor con licencia de 21 años o más va en el asiento delantero, o por trabajo agrícola o una emergencia.","p":"Correcto. Un conductor con licencia de 21 años o más adelante quita el límite de pasajeros."},"ref":{"doc":"UT","page":8}},{"id":"ut-011","scope":"UT","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Utah, what is the rule on talking on a cell phone for drivers under 18?","o":["They may not use a wireless phone to talk while driving","They may talk only with a hands-free device","They may talk only on roads under 45 mph","They may talk if the call is short"],"h1":"For the youngest drivers, the rule is stricter than for adults.","h2":"In Utah, a driver younger than 18 may not use a phone while driving, except in an emergency, to report a hazard or a crime, or to talk with a parent or guardian.","p":"Right. Drivers under 18 may not talk on a phone while driving."},"es":{"q":"En Utah, ¿cuál es la regla sobre hablar por celular para conductores menores de 18 años?","o":["No pueden usar un teléfono inalámbrico para hablar mientras manejan","Pueden hablar solo con manos libres","Pueden hablar solo en calles de menos de 45 mph","Pueden hablar si la llamada es corta"],"h1":"Para los conductores más jóvenes, la regla es más estricta que para los adultos.","h2":"En Utah, un conductor menor de 18 años no puede usar el teléfono mientras maneja, salvo en una emergencia, para reportar un peligro o un delito, o para hablar con su padre, madre o tutor.","p":"Correcto. Los menores de 18 no pueden hablar por teléfono mientras manejan."},"ref":{"doc":"UT","page":59}},{"id":"ut-012","scope":"UT","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Utah, which of these may an adult driver do with a handheld phone while driving?","o":["Write a text message","Read an email","Watch a video","Talk on a call started by voice command"],"h1":"Typing, reading and watching are not allowed.","h2":"In Utah, a driver 18 or older may not type, read, browse or watch video on a handheld phone, but may talk on a call that was started by voice command.","p":"Right. An adult may talk on a call started by voice command."},"es":{"q":"En Utah, ¿cuál de estas cosas puede hacer un conductor adulto con el teléfono en la mano mientras maneja?","o":["Escribir un mensaje de texto","Leer un correo","Ver un video","Hablar en una llamada iniciada con comandos de voz"],"h1":"Escribir, leer y ver videos no está permitido.","h2":"En Utah, un conductor de 18 años o más no puede escribir, leer, navegar ni ver videos en el teléfono en la mano, pero puede hablar en una llamada iniciada con comandos de voz.","p":"Correcto. Un adulto puede hablar en una llamada iniciada con comandos de voz."},"ref":{"doc":"UT","page":59}},{"id":"ut-013","scope":"UT","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Utah, at what blood alcohol level can a driver 21 or older be charged with DUI?","o":["0.02 percent or higher","0.08 percent or higher","0.05 percent or higher","0.10 percent or higher"],"h1":"Utah's limit is lower than the one most states use.","h2":"In Utah, a driver 21 or older breaks the DUI law with a blood alcohol level of 0.05 percent or higher.","p":"Right. Utah's adult limit is 0.05 percent."},"es":{"q":"En Utah, ¿con qué nivel de alcohol en la sangre se puede acusar de DUI a un conductor de 21 años o más?","o":["0.02 por ciento o más","0.08 por ciento o más","0.05 por ciento o más","0.10 por ciento o más"],"h1":"El límite de Utah es más bajo que el de la mayoría de los estados.","h2":"En Utah, un conductor de 21 años o más viola la ley de DUI con un nivel de alcohol en la sangre de 0.05 por ciento o más.","p":"Correcto. El límite para adultos en Utah es 0.05 por ciento."},"ref":{"doc":"UT","page":52}},{"id":"ut-015","scope":"UT","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Utah, how much alcohol may a driver under 21 have in their body while driving?","o":["None at all","Up to 0.02 percent","Up to 0.05 percent","Up to 0.08 percent"],"h1":"Utah calls this rule \"not a drop.\"","h2":"Utah does not allow a driver under 21 to drive with any measurable alcohol in their body.","p":"Right. Under 21, the limit is not a drop."},"es":{"q":"En Utah, ¿cuánto alcohol puede tener en el cuerpo un conductor menor de 21 años mientras maneja?","o":["Nada en absoluto","Hasta 0.02 por ciento","Hasta 0.05 por ciento","Hasta 0.08 por ciento"],"h1":"En Utah esta regla se conoce como \"ni una gota\".","h2":"Utah no permite que un conductor menor de 21 años maneje con alcohol medible en el cuerpo.","p":"Correcto. Para menores de 21, el límite es ni una gota."},"ref":{"doc":"UT","page":52}},{"id":"ut-016","scope":"UT","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Utah, what is the highest speed limit posted on some rural interstate stretches?","o":["65 mph","70 mph","75 mph","80 mph"],"h1":"It is higher than in most states.","h2":"Utah allows speed limits up to 80 mph on some rural interstate highways, where signs show it.","p":"Right. Some rural Utah interstates allow 80 mph."},"es":{"q":"En Utah, ¿cuál es el límite de velocidad más alto en algunos tramos rurales de interestatales?","o":["65 mph","70 mph","75 mph","80 mph"],"h1":"Es más alto que en la mayoría de los estados.","h2":"Utah permite límites de hasta 80 mph en algunas carreteras interestatales rurales, donde las señales lo indican.","p":"Correcto. Algunas interestatales rurales de Utah permiten 80 mph."},"ref":{"doc":"UT","page":44}},{"id":"ut-017","scope":"UT","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Utah, when should you drive in the left lane of a multi-lane highway?","o":["Whenever you drive at the speed limit","Whenever traffic is light","To pass slower vehicles, then move back right","Whenever you plan to exit soon"],"h1":"The left lane is not a lane to stay in.","h2":"In Utah, the left lane of a multi-lane road is for passing slower vehicles, and you must move right when someone comes up behind you.","p":"Right. Use the left lane to pass, then move back right."},"es":{"q":"En Utah, ¿cuándo debe usar el carril izquierdo de una carretera de varios carriles?","o":["Siempre que maneje al límite de velocidad","Siempre que haya poco tráfico","Para rebasar a vehículos más lentos y luego volver a la derecha","Siempre que piense salir pronto"],"h1":"El carril izquierdo no es un carril para quedarse.","h2":"En Utah, el carril izquierdo de una carretera de varios carriles es para rebasar a vehículos más lentos, y usted debe pasarse a la derecha cuando alguien se acerca por detrás.","p":"Correcto. Use el carril izquierdo para rebasar y luego vuelva a la derecha."},"ref":{"doc":"UT","page":34}},{"id":"ut-018","scope":"UT","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Utah, which stopped vehicles does the move-over law cover?","o":["Only police cars with red and blue lights","Any stopped vehicle by the road with flashing lights, including hazard lights","Only ambulances carrying a patient","Only cars parked in a legal parking area"],"h1":"It is not only for police and emergency vehicles.","h2":"Utah's move-over law covers any vehicle stopped by the road with flashing lights, including a car with its hazard lights on, unless it is in a legal parking area.","p":"Right. The law covers any stopped vehicle with flashing lights, even hazard lights."},"es":{"q":"En Utah, ¿qué vehículos detenidos cubre la ley de moverse de carril?","o":["Solo patrullas con luces rojas y azules","Cualquier vehículo detenido junto a la carretera con luces intermitentes, incluso luces de emergencia","Solo ambulancias que llevan a un paciente","Solo carros estacionados en un lugar legal"],"h1":"No es solo para la policía y los vehículos de emergencia.","h2":"La ley de Utah de moverse de carril cubre cualquier vehículo detenido junto a la carretera con luces intermitentes, incluso un carro con las luces de emergencia encendidas, salvo que esté en un lugar legal de estacionamiento.","p":"Correcto. La ley cubre cualquier vehículo detenido con luces intermitentes, incluso luces de emergencia."},"ref":{"doc":"UT","page":77}},{"id":"ut-019","scope":"UT","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Utah, you cannot safely move over a lane for a stopped tow truck with flashing amber lights. What must you do?","o":["Slow down and leave as much space as you can","Keep your speed and pass quickly","Stop in your lane until it leaves","Flash your headlights and pass"],"h1":"If you cannot add a lane, add space and reduce speed.","h2":"Under Utah's move-over law, if you cannot safely change lanes, you must slow down and give the stopped vehicle as much space as you can.","p":"Right. Slow down and give as much space as possible."},"es":{"q":"En Utah, usted no puede cambiarse de carril con seguridad ante una grúa detenida con luces ámbar intermitentes. ¿Qué debe hacer?","o":["Reducir la velocidad y dejar todo el espacio que pueda","Mantener la velocidad y pasar rápido","Detenerse en su carril hasta que se vaya","Hacer cambio de luces y pasar"],"h1":"Si no puede cambiar de carril, deje espacio y reduzca la velocidad.","h2":"Según la ley de Utah, si usted no puede cambiarse de carril con seguridad, debe reducir la velocidad y dejar al vehículo detenido todo el espacio que pueda.","p":"Correcto. Reduzca la velocidad y deje todo el espacio posible."},"ref":{"doc":"UT","page":77}},{"id":"ut-020","scope":"UT","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Utah, what must a driver do after being convicted of breaking the move-over law?","o":["Pay a $25 fine only","Retake the driving skills test","Take a four-hour live defensive driving class within 90 days","Lose your license for one year"],"h1":"It is a class you attend in person.","h2":"In Utah, a driver convicted of breaking the move-over law must take a four-hour live defensive driving class within 90 days, or the license is suspended for 90 days.","p":"Right. The driver must take a four-hour defensive driving class within 90 days."},"es":{"q":"En Utah, ¿qué debe hacer un conductor declarado culpable de no cumplir la ley de moverse de carril?","o":["Pagar solo una multa de $25","Volver a tomar el examen práctico de manejo","Tomar una clase presencial de manejo defensivo de cuatro horas dentro de 90 días","Perder la licencia por un año"],"h1":"Es una clase a la que se asiste en persona.","h2":"En Utah, un conductor declarado culpable de no cumplir la ley de moverse de carril debe tomar una clase presencial de manejo defensivo de cuatro horas dentro de 90 días, o su licencia se suspende por 90 días.","p":"Correcto. El conductor debe tomar una clase de manejo defensivo de cuatro horas dentro de 90 días."},"ref":{"doc":"UT","page":77}},{"id":"ut-021","scope":"UT","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Utah, you are on a divided highway with four or more lanes and a median. A school bus stops on the other side with red lights flashing. What must you do?","o":["Stop until the lights turn off","Stop, then pass at 10 mph","You do not need to stop, but stay alert","Honk and keep your speed"],"h1":"A median separates you from the bus and the children.","h2":"In Utah, on a divided highway with four or more lanes and a median, drivers coming toward a stopped school bus do not need to stop, but drivers behind the bus must stop.","p":"Right. On a divided highway, oncoming traffic does not need to stop."},"es":{"q":"En Utah, usted va por una carretera dividida de cuatro carriles o más con franja central. Un autobús escolar se detiene del otro lado con las luces rojas intermitentes. ¿Qué debe hacer?","o":["Detenerse hasta que se apaguen las luces","Detenerse y luego pasar a 10 mph","No necesita detenerse, pero debe estar atento","Tocar la bocina y mantener la velocidad"],"h1":"Una franja central lo separa del autobús y de los niños.","h2":"En Utah, en una carretera dividida de cuatro carriles o más con franja central, los conductores que vienen de frente a un autobús escolar detenido no necesitan detenerse, pero los que van detrás del autobús sí deben detenerse.","p":"Correcto. En una carretera dividida, el tráfico que viene de frente no necesita detenerse."},"ref":{"doc":"UT","page":36}},{"id":"ut-025","scope":"UT","cat":"licensing","sign":null,"c":2,"en":{"q":"In Utah, how many questions are on the written knowledge test for a person who has never had a license?","o":["20 questions","25 questions","50 questions","100 questions"],"h1":"Drivers who had a license before take a shorter test.","h2":"In Utah, a person who has never been licensed takes a 50-question knowledge test, while a previously licensed driver takes a 25-question test.","p":"Right. New drivers answer 50 questions."},"es":{"q":"En Utah, ¿cuántas preguntas tiene el examen escrito para una persona que nunca ha tenido licencia?","o":["20 preguntas","25 preguntas","50 preguntas","100 preguntas"],"h1":"Quienes ya tuvieron licencia hacen un examen más corto.","h2":"En Utah, una persona que nunca ha tenido licencia hace un examen de 50 preguntas, mientras que quien ya tuvo licencia hace un examen de 25 preguntas.","p":"Correcto. Los conductores nuevos responden 50 preguntas."},"ref":{"doc":"UT","page":null}},{"id":"ut-026","scope":"UT","cat":"licensing","sign":null,"c":1,"en":{"q":"In Utah, what score do you need to pass the written knowledge test?","o":["70 percent","80 percent","75 percent","90 percent"],"h1":"It is the same passing score many states use.","h2":"Utah requires you to answer at least 80 percent of the knowledge test questions correctly, which is 40 out of 50.","p":"Right. You need 80 percent to pass."},"es":{"q":"En Utah, ¿qué puntaje necesita para aprobar el examen escrito?","o":["70 por ciento","80 por ciento","75 por ciento","90 por ciento"],"h1":"Es el mismo puntaje que usan muchos estados para aprobar.","h2":"Utah exige que usted conteste bien por lo menos el 80 por ciento de las preguntas del examen, es decir, 40 de 50.","p":"Correcto. Necesita 80 por ciento para aprobar."},"ref":{"doc":"UT","page":23}},{"id":"va-001","scope":"VA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Virginia, what is the youngest age to get a learner's permit?","o":["14 years old","15 years old","15 years and 6 months","16 years old"],"h1":"It is halfway between two birthdays.","h2":"In Virginia you can get a learner's permit when you are at least 15 years and 6 months old.","p":"Right. The Virginia permit starts at 15 and a half."},"es":{"q":"En Virginia, ¿cuál es la edad mínima para obtener un permiso de aprendiz?","o":["14 años","15 años","15 años y 6 meses","16 años"],"h1":"Está a mitad de camino entre dos cumpleaños.","h2":"En Virginia usted puede obtener un permiso de aprendiz cuando tiene por lo menos 15 años y 6 meses.","p":"Correcto. El permiso en Virginia empieza a los 15 años y medio."},"ref":{"doc":"VA","page":null}},{"id":"va-002","scope":"VA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Virginia, how long must a teen hold a learner's permit before getting a license?","o":["6 months","9 months","12 months","3 months"],"h1":"It is three quarters of a year.","h2":"A Virginia teen must hold the learner's permit for at least nine months before getting a driver's license.","p":"Right. The permit is held for nine months."},"es":{"q":"En Virginia, ¿cuánto tiempo debe tener un adolescente el permiso de aprendiz antes de obtener la licencia?","o":["6 meses","9 meses","12 meses","3 meses"],"h1":"Son tres cuartas partes de un año.","h2":"En Virginia, un adolescente debe tener el permiso de aprendiz por lo menos nueve meses antes de obtener la licencia de manejar.","p":"Correcto. El permiso se tiene nueve meses."},"ref":{"doc":"VA","page":null}},{"id":"va-003","scope":"VA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Virginia, how many hours of supervised driving must a teen complete before getting a license?","o":["20 hours","30 hours","50 hours","45 hours"],"h1":"It is a little less than 50.","h2":"A Virginia teen must complete at least 45 hours of supervised driving practice before getting a license.","p":"Right. Virginia asks for 45 supervised hours."},"es":{"q":"En Virginia, ¿cuántas horas de manejo supervisado debe completar un adolescente antes de obtener la licencia?","o":["20 horas","30 horas","50 horas","45 horas"],"h1":"Es un poco menos de 50.","h2":"En Virginia, un adolescente debe completar por lo menos 45 horas de práctica de manejo supervisado antes de obtener la licencia.","p":"Correcto. Virginia pide 45 horas supervisadas."},"ref":{"doc":"VA","page":null}},{"id":"va-004","scope":"VA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Virginia, how many of the 45 supervised hours must be driven at night?","o":["15 hours","5 hours","10 hours","20 hours"],"h1":"It is one third of the total.","h2":"Of the 45 supervised hours in Virginia, at least 15 must be driven at night, so the teen practices in the dark.","p":"Right. 15 of the 45 hours are at night."},"es":{"q":"En Virginia, ¿cuántas de las 45 horas supervisadas deben ser de noche?","o":["15 horas","5 horas","10 horas","20 horas"],"h1":"Es una tercera parte del total.","h2":"De las 45 horas supervisadas en Virginia, por lo menos 15 deben ser de noche, para que el adolescente practique en la oscuridad.","p":"Correcto. 15 de las 45 horas son de noche."},"ref":{"doc":"VA","page":null}},{"id":"va-005","scope":"VA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Virginia, how old must the licensed driver beside a learner usually be?","o":["At least 16","At least 18","At least 21","At least 25"],"h1":"A legal guardian or a brother or sister may be younger than the usual age.","h2":"A Virginia learner must drive with a licensed driver seated beside them who is at least 21, or with a parent, a legal guardian, or a brother or sister who is at least 18.","p":"Right. The supervisor is usually 21 or older."},"es":{"q":"En Virginia, ¿qué edad debe tener normalmente el conductor con licencia que va al lado del aprendiz?","o":["Por lo menos 16","Por lo menos 18","Por lo menos 21","Por lo menos 25"],"h1":"Un tutor legal o un hermano puede ser menor que la edad habitual.","h2":"En Virginia, el aprendiz debe manejar con un conductor con licencia sentado a su lado que tenga por lo menos 21 años, o con su padre o madre, su tutor legal, o un hermano o hermana de por lo menos 18 años.","p":"Correcto. El supervisor normalmente tiene 21 años o más."},"ref":{"doc":"VA","page":31}},{"id":"va-006","scope":"VA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Virginia, how many passengers under 21 who are not family may ride with a learner's permit holder?","o":["None at all","No more than one","No more than two","No more than three"],"h1":"Think of just one friend.","h2":"A Virginia learner's permit holder may carry no more than one passenger under 21 who is not a family member.","p":"Right. With a permit, only one passenger under 21 who is not family."},"es":{"q":"En Virginia, ¿cuántos pasajeros menores de 21 años que no son familiares pueden viajar con alguien que tiene permiso de aprendiz?","o":["Ninguno","No más de uno","No más de dos","No más de tres"],"h1":"Piense en un solo amigo.","h2":"En Virginia, quien tiene permiso de aprendiz puede llevar como máximo un pasajero menor de 21 años que no sea familiar.","p":"Correcto. Con permiso, solo un pasajero menor de 21 años que no sea familiar."},"ref":{"doc":"VA","page":null}},{"id":"va-007","scope":"VA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Virginia, when may a driver under 18 with a driver's license not drive, unless an exception applies?","o":["From 10 p.m. to 5 a.m.","From 11 p.m. to 5 a.m.","From 9 p.m. to 6 a.m.","From midnight to 4 a.m."],"h1":"It starts at midnight.","h2":"A Virginia driver under 18 with a license may not drive from midnight to 4 a.m., except for reasons such as work, a supervised school activity or an emergency. A learner's permit holder may not drive in those hours at all.","p":"Right. No driving from midnight to 4 a.m. under 18."},"es":{"q":"En Virginia, ¿cuándo no puede manejar un conductor menor de 18 años con licencia de manejar, salvo que aplique una excepción?","o":["De 10 p.m. a 5 a.m.","De 11 p.m. a 5 a.m.","De 9 p.m. a 6 a.m.","De medianoche a 4 a.m."],"h1":"Empieza a la medianoche.","h2":"En Virginia, un conductor menor de 18 años con licencia no puede manejar de la medianoche a las 4 a.m., salvo por razones como el trabajo, una actividad escolar supervisada o una emergencia. Quien tiene permiso de aprendiz no puede manejar en esas horas.","p":"Correcto. No se maneja de medianoche a 4 a.m. si es menor de 18."},"ref":{"doc":"VA","page":null}},{"id":"va-008","scope":"VA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Virginia, which trip is allowed between midnight and 4 a.m. for a driver under 18 with a driver's license?","o":["Driving to or from a job","Driving home from a party","Driving a friend to the store","Driving to practice for the road test"],"h1":"It is a trip connected to earning money.","h2":"Virginia lets a licensed driver under 18 drive between midnight and 4 a.m. to or from a job, and for a few other listed reasons such as an emergency.","p":"Right. Driving to or from work is allowed."},"es":{"q":"En Virginia, ¿qué viaje se permite entre la medianoche y las 4 a.m. a un conductor menor de 18 años con licencia de manejar?","o":["Ir o volver del trabajo","Volver a casa de una fiesta","Llevar a un amigo a la tienda","Practicar para el examen de manejo"],"h1":"Es un viaje relacionado con ganar dinero.","h2":"Virginia permite que un conductor menor de 18 años con licencia maneje entre la medianoche y las 4 a.m. para ir o volver del trabajo, y por otras pocas razones, como una emergencia.","p":"Correcto. Se permite ir o volver del trabajo."},"ref":{"doc":"VA","page":null}},{"id":"va-009","scope":"VA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Virginia, during the first year with a license, how many passengers under 21 may a driver under 18 carry?","o":["None at all","Two","One","Three"],"h1":"Family members do not count toward this limit.","h2":"In the first year with a Virginia license, a driver under 18 may carry only one passenger under 21 who is not a family member.","p":"Right. One passenger under 21 in the first year."},"es":{"q":"En Virginia, durante el primer año con licencia, ¿cuántos pasajeros menores de 21 años puede llevar un conductor menor de 18?","o":["Ninguno","Dos","Uno","Tres"],"h1":"Los familiares no cuentan para este límite.","h2":"En el primer año con licencia en Virginia, un conductor menor de 18 años solo puede llevar un pasajero menor de 21 años que no sea familiar.","p":"Correcto. Un pasajero menor de 21 el primer año."},"ref":{"doc":"VA","page":null}},{"id":"va-010","scope":"VA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Virginia, after holding a license for one year, how many passengers under 21 may a driver under 18 carry in limited situations, such as going to a school activity?","o":["Two","Up to three","Up to five","Any number"],"h1":"The number goes up after the first year, but only for certain trips.","h2":"After one year with a license, a Virginia driver under 18 may carry up to three passengers under 21 in limited situations, such as a trip to or from a school activity.","p":"Right. Up to three, in limited situations."},"es":{"q":"En Virginia, después de tener la licencia un año, ¿cuántos pasajeros menores de 21 años puede llevar un conductor menor de 18 en situaciones limitadas, como ir a una actividad escolar?","o":["Dos","Hasta tres","Hasta cinco","Cualquier número"],"h1":"El número sube después del primer año, pero solo para ciertos viajes.","h2":"Después de un año con licencia, un conductor menor de 18 años en Virginia puede llevar hasta tres pasajeros menores de 21 en situaciones limitadas, como ir o volver de una actividad escolar.","p":"Correcto. Hasta tres, en situaciones limitadas."},"ref":{"doc":"VA","page":null}},{"id":"va-012","scope":"VA","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Virginia, since January 1, 2021, what is illegal for every driver while the car is moving?","o":["Holding a phone in your hand","Listening to the radio","Using a hands-free phone","Talking to passengers"],"h1":"The law is about where the phone is.","h2":"Since January 1, 2021, Virginia drivers may not hold a hand-held phone or other communication device while driving, except in an emergency or when lawfully stopped or parked.","p":"Right. Holding a phone while driving is illegal."},"es":{"q":"En Virginia, desde el 1 de enero de 2021, ¿qué es ilegal para todo conductor mientras el carro está en movimiento?","o":["Sostener el teléfono en la mano","Escuchar la radio","Usar el teléfono con manos libres","Hablar con los pasajeros"],"h1":"La ley trata de dónde está el teléfono.","h2":"Desde el 1 de enero de 2021, los conductores en Virginia no pueden sostener un teléfono u otro dispositivo de comunicación al manejar, salvo en una emergencia o cuando están detenidos o estacionados legalmente.","p":"Correcto. Sostener el teléfono al manejar es ilegal."},"ref":{"doc":"VA","page":24}},{"id":"va-013","scope":"VA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Virginia, what is the fine for a first offense of holding a phone while driving?","o":["$25","$50","$125","$500"],"h1":"It is more than one hundred dollars.","h2":"A first offense of holding a phone while driving in Virginia carries a $125 fine.","p":"Right. The first offense is $125."},"es":{"q":"En Virginia, ¿cuál es la multa por la primera vez que se sostiene el teléfono al manejar?","o":["$25","$50","$125","$500"],"h1":"Es más de cien dólares.","h2":"La primera infracción por sostener el teléfono al manejar en Virginia tiene una multa de $125.","p":"Correcto. La primera vez son $125."},"ref":{"doc":"VA","page":null}},{"id":"va-014","scope":"VA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Virginia, what is the fine for holding a phone while driving in a highway work zone?","o":["$125","$250","$75","$1,000"],"h1":"It is the same as the fine for a second offense.","h2":"Holding a phone while driving in a Virginia highway work zone, or a second offense, carries a $250 fine, double the first-offense fine.","p":"Right. In a work zone the fine is $250."},"es":{"q":"En Virginia, ¿cuál es la multa por sostener el teléfono al manejar en una zona de trabajos en la carretera?","o":["$125","$250","$75","$1,000"],"h1":"Es igual a la multa por una segunda infracción.","h2":"Sostener el teléfono al manejar en una zona de trabajos en una carretera de Virginia, o una segunda infracción, tiene una multa de $250, el doble que la primera vez.","p":"Correcto. En una zona de trabajos la multa es $250."},"ref":{"doc":"VA","page":null}},{"id":"va-015","scope":"VA","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Virginia, a driver under 21 who has been drinking breaks the law at what blood alcohol level?","o":["0.08 percent","0.05 percent","0.10 percent","0.02 percent"],"h1":"It is the lowest number on the list.","h2":"In Virginia a driver under 21 who drives after drinking alcohol breaks the law with a blood alcohol level of 0.02 percent or more.","p":"Right. Under 21, the limit is 0.02."},"es":{"q":"En Virginia, ¿con qué nivel de alcohol en la sangre viola la ley un conductor menor de 21 años que ha bebido?","o":["0.08 por ciento","0.05 por ciento","0.10 por ciento","0.02 por ciento"],"h1":"Es el número más bajo de la lista.","h2":"En Virginia, un conductor menor de 21 años que maneja después de beber viola la ley con un nivel de alcohol de 0.02 por ciento o más.","p":"Correcto. Para menores de 21, el límite es 0.02."},"ref":{"doc":"VA","page":24}},{"id":"va-016","scope":"VA","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Virginia, what happens to the license of a driver under 21 convicted of driving after drinking?","o":["It is lost for one year","It gets a warning stamp","It is lost for one week","Nothing happens to it"],"h1":"The loss lasts a full year.","h2":"A driver under 21 convicted of driving after drinking in Virginia loses the license for one year and must also pay at least $500 or do 50 hours of community service.","p":"Right. The license is lost for one year."},"es":{"q":"En Virginia, ¿qué le pasa a la licencia de un conductor menor de 21 años condenado por manejar después de beber?","o":["La pierde por un año","Recibe un sello de advertencia","La pierde por una semana","No le pasa nada"],"h1":"La pérdida dura un año completo.","h2":"En Virginia, un conductor menor de 21 años condenado por manejar después de beber pierde la licencia por un año y además debe pagar por lo menos $500 o hacer 50 horas de servicio comunitario.","p":"Correcto. Pierde la licencia por un año."},"ref":{"doc":"VA","page":30}},{"id":"va-017","scope":"VA","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Virginia, driving how much over the speed limit counts as reckless driving?","o":["5 mph or more","10 mph or more","20 mph or more","30 mph or more"],"h1":"In Virginia this is a crime, not just a ticket.","h2":"In Virginia, driving 20 mph or more over the speed limit is reckless driving, a serious offense.","p":"Right. 20 mph or more over the limit is reckless driving."},"es":{"q":"En Virginia, ¿cuánto por encima del límite de velocidad se considera manejo imprudente (reckless driving)?","o":["5 mph o más","10 mph o más","20 mph o más","30 mph o más"],"h1":"En Virginia esto es un delito, no solo una multa.","h2":"En Virginia, manejar 20 mph o más por encima del límite es manejo imprudente, una infracción grave.","p":"Correcto. 20 mph o más sobre el límite es manejo imprudente."},"ref":{"doc":"VA","page":14}},{"id":"va-018","scope":"VA","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Virginia, above what speed is driving always reckless, whatever the posted limit?","o":["75 mph","85 mph","80 mph","100 mph"],"h1":"It is 15 mph above the top interstate limit.","h2":"In Virginia, driving faster than 85 mph is reckless driving no matter what the posted speed limit is.","p":"Right. Over 85 mph is always reckless driving."},"es":{"q":"En Virginia, ¿a partir de qué velocidad es siempre manejo imprudente, sin importar el límite indicado?","o":["75 mph","85 mph","80 mph","100 mph"],"h1":"Es 15 mph más que el límite máximo de las interestatales.","h2":"En Virginia, manejar a más de 85 mph es manejo imprudente sin importar el límite de velocidad indicado.","p":"Correcto. Más de 85 mph es siempre manejo imprudente."},"ref":{"doc":"VA","page":14}},{"id":"va-019","scope":"VA","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Virginia, what is the highest speed limit on rural interstates?","o":["55 mph","60 mph","65 mph","70 mph"],"h1":"It is lower than in many western states.","h2":"The highest posted limit on Virginia's rural interstates is 70 mph; always follow the posted signs.","p":"Right. Rural interstates in Virginia go up to 70 mph."},"es":{"q":"En Virginia, ¿cuál es el límite de velocidad más alto en las interestatales rurales?","o":["55 mph","60 mph","65 mph","70 mph"],"h1":"Es más bajo que en muchos estados del oeste.","h2":"El límite más alto en las interestatales rurales de Virginia es de 70 mph; siempre siga los letreros.","p":"Correcto. Las interestatales rurales de Virginia llegan a 70 mph."},"ref":{"doc":"VA","page":null}},{"id":"va-020","scope":"VA","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Virginia, on a highway with two lanes in your direction, you approach a stopped vehicle with flashing lights. What should you do?","o":["Change to a lane not next to it, or slow down if that is unsafe","Stop in your lane until it leaves","Speed up to pass it quickly","Flash your lights and keep going"],"h1":"First try to give it a whole lane of space.","h2":"Virginia's move-over law asks you to change to a lane not next to the stopped vehicle when safe, and if you cannot, to slow down and pass with care.","p":"Right. Move over, or slow down if you cannot."},"es":{"q":"En Virginia, en una carretera con dos carriles en su dirección, usted se acerca a un vehículo detenido con luces intermitentes. ¿Qué debe hacer?","o":["Pasarse a un carril que no esté junto a él, o bajar la velocidad si no es seguro","Pararse en su carril hasta que se vaya","Acelerar para pasarlo rápido","Hacer cambio de luces y seguir"],"h1":"Primero trate de dejarle un carril completo de espacio.","h2":"La ley de Virginia le pide pasarse a un carril que no esté junto al vehículo detenido cuando sea seguro, y si no puede, bajar la velocidad y pasar con cuidado.","p":"Correcto. Cámbiese de carril, o baje la velocidad si no puede."},"ref":{"doc":"VA","page":16}},{"id":"va-021","scope":"VA","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Virginia, the move-over law also covers which stopped vehicles?","o":["Only police cars","Only school buses","Any vehicle with hazard lights, flares or warning signs","Only vehicles from the power company"],"h1":"Think of an ordinary car with its flashers on.","h2":"Virginia's move-over law also covers any stopped vehicle that shows hazard lights, flares or warning signs, not only emergency vehicles.","p":"Right. It covers any vehicle with hazard lights, flares or warning signs."},"es":{"q":"En Virginia, ¿qué otros vehículos detenidos protege también la ley de cambiarse de carril?","o":["Solo los carros de policía","Solo los autobuses escolares","Cualquier vehículo con luces de emergencia, bengalas o señales de aviso","Solo los vehículos de la compañía eléctrica"],"h1":"Piense en un carro común con las luces intermitentes encendidas.","h2":"En Virginia, la ley de cambiarse de carril también protege a cualquier vehículo detenido que muestre luces de emergencia, bengalas o señales de advertencia, no solo a los vehículos de emergencia.","p":"Correcto. Protege a cualquier vehículo con luces de emergencia, bengalas o señales."},"ref":{"doc":"VA","page":16}},{"id":"va-022","scope":"VA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Virginia, for policies issued or renewed since January 1, 2025, what is the minimum liability insurance?","o":["$30,000 / $60,000 / $20,000","$50,000 / $100,000 / $25,000","$25,000 / $50,000 / $20,000","$100,000 / $300,000 / $100,000"],"h1":"The amounts went up in 2025 from 30/60/20.","h2":"Virginia policies issued or renewed since January 1, 2025 must have at least $50,000 for injury to one person, $100,000 per crash and $25,000 for property damage.","p":"Right. Virginia's minimum is now 50/100/25."},"es":{"q":"En Virginia, para las pólizas emitidas o renovadas desde el 1 de enero de 2025, ¿cuál es el seguro de responsabilidad mínimo?","o":["$30,000 / $60,000 / $20,000","$50,000 / $100,000 / $25,000","$25,000 / $50,000 / $20,000","$100,000 / $300,000 / $100,000"],"h1":"Los montos subieron en 2025 desde 30/60/20.","h2":"Las pólizas de Virginia emitidas o renovadas desde el 1 de enero de 2025 deben tener por lo menos $50,000 por lesiones a una persona, $100,000 por choque y $25,000 por daños a la propiedad.","p":"Correcto. El mínimo en Virginia ahora es 50/100/25."},"ref":{"doc":"VA","page":null}},{"id":"va-023","scope":"VA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Virginia, since July 1, 2024, what must a vehicle owner have to register a car?","o":["A $500 uninsured motor vehicle fee","A clean driving record","A safety course certificate","Insurance that meets the state minimum"],"h1":"Paying a fee instead is no longer an option.","h2":"Since July 1, 2024, Virginia no longer lets owners pay a fee to drive uninsured, so every registered vehicle must carry insurance that meets the state minimum.","p":"Right. Insurance is now required to register."},"es":{"q":"En Virginia, desde el 1 de julio de 2024, ¿qué debe tener el dueño de un vehículo para registrarlo?","o":["La cuota de $500 por vehículo sin seguro","Un historial de manejo limpio","Un certificado de curso de seguridad","Un seguro que cumpla el mínimo del estado"],"h1":"Pagar una cuota en su lugar ya no es una opción.","h2":"Desde el 1 de julio de 2024, Virginia ya no permite pagar una cuota para manejar sin seguro, así que todo vehículo registrado debe tener un seguro que cumpla el mínimo del estado.","p":"Correcto. Ahora se necesita seguro para registrar."},"ref":{"doc":"VA","page":null}},{"id":"va-024","scope":"VA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Virginia, how many of the 10 road sign questions on the knowledge exam must you answer correctly?","o":["All 10","8 of them","7 of them","5 of them"],"h1":"Not a single mistake is allowed in this part.","h2":"On the Virginia knowledge exam you must answer all 10 road sign questions correctly before the general knowledge part is scored.","p":"Right. All 10 sign questions must be correct."},"es":{"q":"En Virginia, ¿cuántas de las 10 preguntas sobre señales del examen de conocimientos debe contestar bien?","o":["Las 10","8 de ellas","7 de ellas","5 de ellas"],"h1":"En esta parte no se permite ni un solo error.","h2":"En el examen de conocimientos de Virginia usted debe contestar bien las 10 preguntas sobre señales antes de que se califique la parte de conocimientos generales.","p":"Correcto. Las 10 preguntas sobre señales deben estar bien."},"ref":{"doc":"VA","page":3}},{"id":"va-025","scope":"VA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Virginia, the general knowledge part of the exam has 30 questions. How many must you answer correctly?","o":["18","20","24","28"],"h1":"You need 80 percent.","h2":"To pass the general knowledge part of the Virginia exam you must answer at least 24 of the 30 questions correctly, which is 80 percent.","p":"Right. You need 24 of 30."},"es":{"q":"En Virginia, la parte de conocimientos generales del examen tiene 30 preguntas. ¿Cuántas debe contestar bien?","o":["18","20","24","28"],"h1":"Necesita el 80 por ciento.","h2":"Para aprobar la parte de conocimientos generales del examen de Virginia debe contestar bien por lo menos 24 de las 30 preguntas, es decir, el 80 por ciento.","p":"Correcto. Necesita 24 de 30."},"ref":{"doc":"VA","page":null}},{"id":"va-026","scope":"VA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Virginia, what must you do after failing the knowledge exam three times?","o":["Wait one full year","Pay a $500 fine","Bring a lawyer to the next test","Complete a driver education classroom course"],"h1":"The state wants you to study with a teacher first.","h2":"After three failed knowledge exams in Virginia, you must complete a driver education classroom course before you may take the exam again.","p":"Right. After three failures, take a classroom course first."},"es":{"q":"En Virginia, ¿qué debe hacer después de reprobar tres veces el examen de conocimientos?","o":["Esperar un año completo","Pagar una multa de $500","Llevar un abogado al próximo examen","Completar un curso de educación vial en el aula"],"h1":"El estado quiere que primero estudie con un maestro.","h2":"Después de reprobar tres veces el examen de conocimientos en Virginia, usted debe completar un curso de educación vial en el aula antes de volver a presentarlo.","p":"Correcto. Después de tres fallos, primero tome un curso en el aula."},"ref":{"doc":"VA","page":3}},{"id":"va-027","scope":"VA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Virginia, can you take the driver knowledge exam in Spanish?","o":["No, only in English","Yes, Spanish is one of the offered languages","Only with your own translator","Only in large cities"],"h1":"The DMV offers it in many languages.","h2":"The Virginia DMV offers the driver knowledge exam in Spanish and other languages, and translators may not be used for the languages that are offered.","p":"Right. The exam is offered in Spanish."},"es":{"q":"En Virginia, ¿puede presentar el examen de conocimientos de manejo en español?","o":["No, solo en inglés","Sí, el español es uno de los idiomas ofrecidos","Solo con su propio traductor","Solo en las ciudades grandes"],"h1":"El DMV lo ofrece en muchos idiomas.","h2":"El DMV de Virginia ofrece el examen de conocimientos en español y en otros idiomas, y no se permiten traductores para los idiomas que se ofrecen.","p":"Correcto. El examen se ofrece en español."},"ref":{"doc":"VA","page":null}},{"id":"vt-001","scope":"VT","cat":"licensing","sign":null,"c":1,"en":{"q":"In Vermont, what is the youngest age to get a learner's permit?","o":["14 years old","15 years old","16 years old","15 and a half years old"],"h1":"It is one year before the junior operator's license.","h2":"You can get a Vermont learner's permit at 15, then practice for at least a year before a junior operator's license.","p":"Right. The Vermont permit starts at 15."},"es":{"q":"En Vermont, ¿cuál es la edad mínima para obtener un permiso de aprendiz?","o":["14 años","15 años","16 años","15 años y medio"],"h1":"Es un año antes de la licencia de operador menor.","h2":"Usted puede obtener el permiso de aprendiz en Vermont a los 15 años y luego practicar por lo menos un año antes de la licencia de operador menor.","p":"Correcto. El permiso en Vermont empieza a los 15."},"ref":{"doc":"VT","page":12}},{"id":"vt-002","scope":"VT","cat":"licensing","sign":null,"c":3,"en":{"q":"In Vermont, a learner's permit holder may drive with which licensed person in the front seat?","o":["Any licensed driver age 18 or older","A licensed friend age 21 or older","Any passenger with a permit","A parent or guardian, a driving instructor, or a licensed adult age 25 or older"],"h1":"The adult must be older than in many other states, or a parent or teacher.","h2":"A Vermont permit holder must drive with a licensed parent or guardian, a certified driving instructor, or a licensed adult at least 25 years old beside them.","p":"Right. The supervisor must be a parent, guardian, instructor, or licensed adult 25 or older."},"es":{"q":"En Vermont, el titular de un permiso de aprendiz puede manejar con, ¿qué persona con licencia en el asiento delantero?","o":["Cualquier conductor con licencia de 18 años o más","Un amigo con licencia de 21 años o más","Cualquier pasajero con permiso","Su padre, madre o tutor, un instructor de manejo, o un adulto con licencia de 25 años o más"],"h1":"El adulto debe ser mayor que en muchos otros estados, o ser un padre o un maestro.","h2":"Quien tiene permiso en Vermont debe manejar con su padre, madre o tutor con licencia, un instructor de manejo certificado o un adulto con licencia de por lo menos 25 años a su lado.","p":"Correcto. El supervisor debe ser un padre, tutor, instructor o adulto con licencia de 25 años o más."},"ref":{"doc":"VT","page":13}},{"id":"vt-003","scope":"VT","cat":"licensing","sign":null,"c":0,"en":{"q":"In Vermont, how long must a teen hold a learner's permit before getting a junior operator's license?","o":["At least one year","At least 3 months","At least 6 months","At least 2 years"],"h1":"It is longer than in many states.","h2":"A Vermont teen must hold a learner's permit for at least one year before getting a junior operator's license.","p":"Right. The permit must be held at least one year."},"es":{"q":"En Vermont, ¿cuánto tiempo debe tener un adolescente el permiso de aprendiz antes de obtener la licencia de operador menor?","o":["Por lo menos un año","Por lo menos 3 meses","Por lo menos 6 meses","Por lo menos 2 años"],"h1":"Es más tiempo que en muchos estados.","h2":"Un adolescente en Vermont debe tener el permiso de aprendiz por lo menos un año antes de obtener la licencia de operador menor.","p":"Correcto. El permiso se debe tener por lo menos un año."},"ref":{"doc":"VT","page":13}},{"id":"vt-004","scope":"VT","cat":"licensing","sign":null,"c":2,"en":{"q":"In Vermont, how many hours of supervised driving must a teen complete before a junior operator's license?","o":["20 hours","30 hours","40 hours","60 hours"],"h1":"It is less than fifty.","h2":"A Vermont teen must complete at least 40 hours of supervised driving before a junior operator's license.","p":"Right. Vermont asks for 40 hours of practice."},"es":{"q":"En Vermont, ¿cuántas horas de manejo supervisado debe completar un adolescente antes de la licencia de operador menor?","o":["20 horas","30 horas","40 horas","60 horas"],"h1":"Es menos de cincuenta.","h2":"Un adolescente en Vermont debe completar por lo menos 40 horas de manejo supervisado antes de la licencia de operador menor.","p":"Correcto. Vermont pide 40 horas de práctica."},"ref":{"doc":"VT","page":13}},{"id":"vt-005","scope":"VT","cat":"licensing","sign":null,"c":1,"en":{"q":"In Vermont, how many of the 40 practice hours must be driven at night?","o":["At least 5 hours","At least 10 hours","At least 15 hours","At least 20 hours"],"h1":"It is one quarter of the total.","h2":"At least 10 of the 40 practice hours in Vermont must be at night, because driving in the dark needs its own practice.","p":"Right. At least 10 hours must be at night."},"es":{"q":"En Vermont, ¿cuántas de las 40 horas de práctica deben ser de noche?","o":["Por lo menos 5 horas","Por lo menos 10 horas","Por lo menos 15 horas","Por lo menos 20 horas"],"h1":"Es la cuarta parte del total.","h2":"Por lo menos 10 de las 40 horas de práctica en Vermont deben ser de noche, porque manejar en la oscuridad necesita su propia práctica.","p":"Correcto. Por lo menos 10 horas deben ser de noche."},"ref":{"doc":"VT","page":13}},{"id":"vt-006","scope":"VT","cat":"licensing","sign":null,"c":3,"en":{"q":"In Vermont, what course must a teen pass before getting a junior operator's license?","o":["A first aid course","A car repair course","A defensive driving course for adults","A state-approved driver education course"],"h1":"It is taught to new drivers, often in high school.","h2":"A Vermont teen must finish a state-approved driver education course before getting a junior operator's license.","p":"Right. Driver education is required."},"es":{"q":"En Vermont, ¿qué curso debe aprobar un adolescente antes de obtener la licencia de operador menor?","o":["Un curso de primeros auxilios","Un curso de reparación de autos","Un curso de manejo defensivo para adultos","Un curso de educación vial aprobado por el estado"],"h1":"Se enseña a conductores nuevos, muchas veces en la secundaria.","h2":"Un adolescente en Vermont debe terminar un curso de educación vial aprobado por el estado antes de obtener la licencia de operador menor.","p":"Correcto. La educación vial es obligatoria."},"ref":{"doc":"VT","page":13}},{"id":"vt-007","scope":"VT","cat":"licensing","sign":null,"c":2,"en":{"q":"In Vermont, during the first three months of a junior operator's license, who may ride with the driver?","o":["Any friends, if they wear seat belts","Only brothers and sisters","No one, or a parent, guardian, instructor, or licensed adult age 25 or older","Up to two friends under 18"],"h1":"In the first months, the driver is alone or with a qualified adult.","h2":"For the first three months, a Vermont junior operator may drive only alone or with a parent or guardian, a driving instructor, or a licensed adult 25 or older.","p":"Right. At first, drive alone or with a qualified adult."},"es":{"q":"En Vermont, durante los primeros tres meses de la licencia de operador menor, ¿quién puede ir con el conductor?","o":["Cualquier amigo, si usa cinturón","Solo hermanos y hermanas","Nadie, o un padre, tutor, instructor o adulto con licencia de 25 años o más","Hasta dos amigos menores de 18"],"h1":"En los primeros meses, el conductor va solo o con un adulto calificado.","h2":"Durante los primeros tres meses, un operador menor en Vermont solo puede manejar solo o con su padre, madre o tutor, un instructor de manejo o un adulto con licencia de 25 años o más.","p":"Correcto. Al principio, maneje solo o con un adulto calificado."},"ref":{"doc":"VT","page":15}},{"id":"vt-008","scope":"VT","cat":"licensing","sign":null,"c":0,"en":{"q":"In Vermont, during months four to six of a junior operator's license, who else may the driver carry?","o":["Family members","Any friend over 18","Up to three classmates","Anyone with a learner's permit"],"h1":"Think of the people you live with.","h2":"During the second three months, a Vermont junior operator may also carry family members, but not other young passengers without a qualified adult.","p":"Right. Family members may ride in months four to six."},"es":{"q":"En Vermont, durante los meses cuatro a seis de la licencia de operador menor, ¿a quién más puede llevar el conductor?","o":["A familiares","A cualquier amigo mayor de 18","Hasta tres compañeros de clase","A cualquiera con permiso de aprendiz"],"h1":"Piense en las personas con quienes vive.","h2":"Durante los segundos tres meses, un operador menor en Vermont también puede llevar a familiares, pero no a otros pasajeros jóvenes sin un adulto calificado.","p":"Correcto. Los familiares pueden ir en los meses cuatro a seis."},"ref":{"doc":"VT","page":15}},{"id":"vt-009","scope":"VT","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Vermont, a junior operator may never carry more passengers than what?","o":["Two people","The number of seat belts in the car","Four people","The number of doors on the car"],"h1":"Every rider needs something to buckle.","h2":"A Vermont junior operator may never carry more passengers than there are seat belts in the vehicle.","p":"Right. No more passengers than seat belts."},"es":{"q":"En Vermont, un operador menor nunca puede llevar más pasajeros que, ¿qué?","o":["Dos personas","El número de cinturones de seguridad del auto","Cuatro personas","El número de puertas del auto"],"h1":"Cada pasajero necesita algo para abrocharse.","h2":"Un operador menor en Vermont nunca puede llevar más pasajeros que cinturones de seguridad hay en el vehículo.","p":"Correcto. No más pasajeros que cinturones."},"ref":{"doc":"VT","page":15}},{"id":"vt-010","scope":"VT","cat":"licensing","sign":null,"c":3,"en":{"q":"In Vermont, what happens if a junior operator breaks the passenger rules?","o":["Only a warning","A one-year suspension","A new road test","The license is recalled for 90 days"],"h1":"The license is taken back for about three months.","h2":"Breaking the passenger rules in Vermont leads to a 90-day recall of the junior operator's license.","p":"Right. The penalty is a 90-day recall."},"es":{"q":"En Vermont, ¿qué pasa si un operador menor no cumple las reglas de pasajeros?","o":["Solo una advertencia","Una suspensión de un año","Un nuevo examen de manejo","Le retiran la licencia por 90 días"],"h1":"Le quitan la licencia unos tres meses.","h2":"No cumplir las reglas de pasajeros en Vermont lleva a que le retiren la licencia de operador menor por 90 días.","p":"Correcto. El castigo es retirar la licencia por 90 días."},"ref":{"doc":"VT","page":null}},{"id":"vt-011","scope":"VT","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Vermont, may a driver under 18 use a phone hands-free while driving?","o":["Yes, if it is on speaker","Yes, on roads under 40 mph","No, not even hands-free","Yes, after six months of driving"],"h1":"The rule for young drivers is stricter than for adults.","h2":"A Vermont driver under 18 may not use any portable electronic device while driving, even hands-free, except to reach police or emergency services in an emergency.","p":"Right. Drivers under 18 may not use a phone, even hands-free."},"es":{"q":"En Vermont, ¿puede un conductor menor de 18 años usar el teléfono con manos libres mientras maneja?","o":["Sí, si está en altavoz","Sí, en caminos de menos de 40 mph","No, ni siquiera con manos libres","Sí, después de seis meses manejando"],"h1":"La regla para conductores jóvenes es más estricta que para los adultos.","h2":"Un conductor menor de 18 años en Vermont no puede usar ningún aparato electrónico portátil mientras maneja, ni con manos libres, salvo para comunicarse con la policía o los servicios de emergencia en una emergencia.","p":"Correcto. Los menores de 18 no pueden usar el teléfono, ni con manos libres."},"ref":{"doc":"VT","page":null}},{"id":"vt-012","scope":"VT","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Vermont, may an adult driver hold a phone while stopped at a red light?","o":["No, the ban applies even when stopped","Yes, the car is not moving","Yes, for a short text only","Yes, if the engine is idling"],"h1":"Stopping in traffic does not end the rule.","h2":"Vermont bans holding a phone while driving, and the ban still applies when you are stopped at a red light or stop sign.","p":"Right. No handheld phone, even at a red light."},"es":{"q":"En Vermont, ¿puede un conductor adulto sostener el teléfono mientras está detenido en un semáforo rojo?","o":["No, la prohibición vale aunque esté detenido","Sí, el auto no se mueve","Sí, solo para un mensaje corto","Sí, si el motor está encendido"],"h1":"Detenerse en el tráfico no termina la regla.","h2":"Vermont prohíbe sostener el teléfono mientras maneja, y la prohibición sigue cuando está detenido en un semáforo rojo o en un alto.","p":"Correcto. Nada de teléfono en la mano, ni en el semáforo rojo."},"ref":{"doc":"VT","page":55}},{"id":"vt-013","scope":"VT","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Vermont, which phone use is allowed for a driver age 18 or older?","o":["Typing a text at low speed","Talking hands-free, without holding the phone","Holding the phone on speaker","Watching a video at a stop"],"h1":"Your hands must stay off the phone.","h2":"Vermont lets adult drivers use a phone only hands-free, without holding it in either hand.","p":"Right. Adults may use a phone hands-free."},"es":{"q":"En Vermont, ¿qué uso del teléfono está permitido para un conductor de 18 años o más?","o":["Escribir un mensaje a baja velocidad","Hablar con manos libres, sin sostener el teléfono","Sostener el teléfono en altavoz","Ver un video en un alto"],"h1":"Sus manos no deben tocar el teléfono.","h2":"Vermont permite a los conductores adultos usar el teléfono solo con manos libres, sin sostenerlo en ninguna mano.","p":"Correcto. Los adultos pueden usar el teléfono con manos libres."},"ref":{"doc":"VT","page":null}},{"id":"vt-014","scope":"VT","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Vermont, a driver under 21 breaks the law with a blood alcohol level of what?","o":["0.08 or more","0.05 or more","0.10 or more","0.02 or more"],"h1":"It is much lower than the adult limit.","h2":"In Vermont, a driver under 21 with a blood alcohol level of 0.02 or more commits a violation, far below the adult limit of 0.08.","p":"Right. Under 21, the limit is 0.02."},"es":{"q":"En Vermont, un conductor menor de 21 años viola la ley con un nivel de alcohol en la sangre de, ¿cuánto?","o":["0.08 o más","0.05 o más","0.10 o más","0.02 o más"],"h1":"Es mucho menor que el límite para adultos.","h2":"En Vermont, un conductor menor de 21 años con 0.02 o más de alcohol en la sangre comete una infracción, muy por debajo del límite de 0.08 para adultos.","p":"Correcto. Para menores de 21, el límite es 0.02."},"ref":{"doc":"VT","page":52}},{"id":"vt-015","scope":"VT","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Vermont, what happens the first time a driver under 21 is caught at 0.02 or more?","o":["A warning letter only","A 30-day suspension","A 90-day license suspension","A one-week suspension"],"h1":"It lasts about three months.","h2":"Since July 2025, a Vermont driver under 21 caught at 0.02 or more loses the license for 90 days the first time, and for 180 days if they do not finish the required youth alcohol program.","p":"Right. A first violation means a 90-day suspension."},"es":{"q":"En Vermont, ¿qué pasa la primera vez que encuentran a un conductor menor de 21 años con 0.02 o más?","o":["Solo una carta de aviso","Una suspensión de 30 días","Una suspensión de la licencia de 90 días","Una suspensión de una semana"],"h1":"Dura unos tres meses.","h2":"Desde julio de 2025, un conductor menor de 21 años en Vermont con 0.02 o más pierde la licencia por 90 días la primera vez, y por 180 días si no termina el programa obligatorio para jóvenes sobre el alcohol.","p":"Correcto. La primera infracción significa una suspensión de 90 días."},"ref":{"doc":"VT","page":null}},{"id":"vt-016","scope":"VT","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Vermont, what is the highest speed allowed when no sign shows a different limit?","o":["50 mph","55 mph","45 mph","65 mph"],"h1":"It is lower than in many states.","h2":"Vermont law sets 50 mph as the maximum speed unless a different limit is posted, and you must go slower when conditions require.","p":"Right. Without a sign, the maximum is 50 mph."},"es":{"q":"En Vermont, ¿cuál es la velocidad máxima permitida cuando ningún letrero indica otro límite?","o":["50 mph","55 mph","45 mph","65 mph"],"h1":"Es menor que en muchos estados.","h2":"La ley de Vermont fija 50 mph como velocidad máxima si no hay otro límite indicado, y usted debe ir más despacio cuando las condiciones lo exigen.","p":"Correcto. Sin letrero, el máximo es 50 mph."},"ref":{"doc":"VT","page":28}},{"id":"vt-017","scope":"VT","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Vermont, what is the highest speed limit on an Interstate?","o":["55 mph","75 mph","70 mph","65 mph"],"h1":"It is lower than in many western states.","h2":"The highest speed on a Vermont Interstate is 65 mph, unless a sign shows a lower limit.","p":"Right. Vermont Interstates top out at 65 mph."},"es":{"q":"En Vermont, ¿cuál es el límite de velocidad más alto en una autopista interestatal?","o":["55 mph","75 mph","70 mph","65 mph"],"h1":"Es menor que en muchos estados del oeste.","h2":"La velocidad más alta en una autopista interestatal de Vermont es 65 mph, a menos que un letrero indique un límite menor.","p":"Correcto. En Vermont el máximo en las interestatales es 65 mph."},"ref":{"doc":"VT","page":28}},{"id":"vt-018","scope":"VT","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Vermont, you approach a stopped police car, ambulance or tow truck with flashing lights. What must you do?","o":["Keep your speed and lane","Slow down and, if safe, move out of the lane next to it","Stop behind it until it leaves","Speed up to pass quickly"],"h1":"Give the people at the roadside more space and time.","h2":"Vermont's move over law says to slow down and, when it is safe, leave the lane closest to a stopped emergency or tow vehicle with flashing lights.","p":"Right. Slow down and move over when safe."},"es":{"q":"En Vermont, usted se acerca a una patrulla, ambulancia o grúa detenida con luces intermitentes. ¿Qué debe hacer?","o":["Mantener su velocidad y carril","Reducir la velocidad y, si es seguro, salir del carril junto a ella","Detenerse detrás hasta que se vaya","Acelerar para pasar rápido"],"h1":"Dé más espacio y tiempo a las personas al lado del camino.","h2":"La ley de Vermont dice que debe reducir la velocidad y, cuando sea seguro, salir del carril más cercano a un vehículo de emergencia o grúa detenido con luces intermitentes.","p":"Correcto. Reduzca la velocidad y cámbiese de carril si es seguro."},"ref":{"doc":"VT","page":31}},{"id":"vt-019","scope":"VT","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Vermont, how long must you stay stopped for a school bus with flashing red lights?","o":["Until the red lights stop flashing","For 30 seconds","Until the door closes","Until you see no children"],"h1":"Watch the bus lights, not a clock.","h2":"In Vermont you must stay stopped as long as the school bus's red lights are flashing.","p":"Right. Stay stopped while the red lights flash."},"es":{"q":"En Vermont, ¿cuánto tiempo debe quedarse detenido ante un autobús escolar con luces rojas intermitentes?","o":["Hasta que las luces rojas dejen de parpadear","Durante 30 segundos","Hasta que se cierre la puerta","Hasta que no vea niños"],"h1":"Mire las luces del autobús, no el reloj.","h2":"En Vermont usted debe quedarse detenido mientras las luces rojas del autobús escolar estén parpadeando.","p":"Correcto. Quédese detenido mientras parpadean las luces rojas."},"ref":{"doc":"VT","page":39}},{"id":"vt-020","scope":"VT","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Vermont, a school bus with flashing red lights is stopped on the other roadway of a divided highway. What must you do?","o":["Stop until the lights turn off","Stop, then pass at 10 mph","You do not have to stop","Honk and pass slowly"],"h1":"A divided highway has separate roadways for each direction.","h2":"In Vermont, you do not have to stop for a school bus that is on a different roadway of a divided highway, but drive with care.","p":"Right. The other roadway of a divided highway does not have to stop."},"es":{"q":"En Vermont, un autobús escolar con luces rojas intermitentes está detenido en la otra calzada de una carretera dividida. ¿Qué debe hacer usted?","o":["Detenerse hasta que se apaguen las luces","Detenerse y luego pasar a 10 mph","No tiene que detenerse","Tocar la bocina y pasar despacio"],"h1":"Una carretera dividida tiene calzadas separadas para cada dirección.","h2":"En Vermont, usted no tiene que detenerse por un autobús escolar que está en otra calzada de una carretera dividida, pero maneje con cuidado.","p":"Correcto. La otra calzada de una carretera dividida no tiene que detenerse."},"ref":{"doc":"VT","page":40}},{"id":"vt-021","scope":"VT","cat":"licensing","sign":null,"c":1,"en":{"q":"In Vermont, how many points within two years start a license suspension?","o":["5 points","10 points","8 points","12 points"],"h1":"It is a round number.","h2":"In Vermont, 10 or more points within two years lead the Commissioner to suspend your license.","p":"Right. Ten points in two years starts a suspension."},"es":{"q":"En Vermont, ¿cuántos puntos en dos años inician una suspensión de la licencia?","o":["5 puntos","10 puntos","8 puntos","12 puntos"],"h1":"Es un número redondo.","h2":"En Vermont, 10 puntos o más en dos años llevan a que el Comisionado suspenda su licencia.","p":"Correcto. Diez puntos en dos años inician una suspensión."},"ref":{"doc":"VT","page":64}},{"id":"vt-022","scope":"VT","cat":"licensing","sign":null,"c":3,"en":{"q":"In Vermont, how long is the suspension for reaching 10 points?","o":["One year","90 days","30 days","10 days"],"h1":"The number of days matches the number of points.","h2":"Reaching 10 points in Vermont brings a 10-day suspension, and the time grows as points go up.","p":"Right. Ten points means a 10-day suspension."},"es":{"q":"En Vermont, ¿cuánto dura la suspensión por llegar a 10 puntos?","o":["Un año","90 días","30 días","10 días"],"h1":"El número de días es igual al número de puntos.","h2":"Llegar a 10 puntos en Vermont trae una suspensión de 10 días, y el tiempo aumenta con más puntos.","p":"Correcto. Diez puntos significan una suspensión de 10 días."},"ref":{"doc":"VT","page":null}},{"id":"vt-023","scope":"VT","cat":"licensing","sign":null,"c":2,"en":{"q":"In Vermont, what is the minimum liability insurance for property damage?","o":["$5,000","$25,000","$10,000","$15,000"],"h1":"It is the smallest of the three required amounts.","h2":"Vermont requires at least $10,000 for property damage, with $25,000 per injured person and $50,000 per crash.","p":"Right. Property damage coverage must be at least $10,000."},"es":{"q":"En Vermont, ¿cuál es el seguro de responsabilidad mínimo por daños a la propiedad?","o":["$5,000","$25,000","$10,000","$15,000"],"h1":"Es la menor de las tres cantidades exigidas.","h2":"Vermont exige por lo menos $10,000 por daños a la propiedad, con $25,000 por persona lesionada y $50,000 por choque.","p":"Correcto. La cobertura por daños a la propiedad debe ser de por lo menos $10,000."},"ref":{"doc":"VT","page":67}},{"id":"vt-024","scope":"VT","cat":"licensing","sign":null,"c":0,"en":{"q":"In Vermont, how many of the 20 questions on the learner's permit test must you answer correctly?","o":["16","14","18","12"],"h1":"You may miss four.","h2":"To pass the Vermont learner's permit test, you must answer at least 16 of the 20 questions correctly, which is 80 percent.","p":"Right. You need 16 correct answers out of 20."},"es":{"q":"En Vermont, ¿cuántas de las 20 preguntas del examen del permiso de aprendiz debe contestar bien?","o":["16","14","18","12"],"h1":"Puede fallar cuatro.","h2":"Para aprobar el examen del permiso de aprendiz en Vermont, debe contestar bien por lo menos 16 de las 20 preguntas, es decir, el 80 por ciento.","p":"Correcto. Necesita 16 respuestas correctas de 20."},"ref":{"doc":"VT","page":18}},{"id":"wa-001","scope":"WA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Washington, how many questions are on the knowledge test?","o":["25 questions","40 questions","50 questions","20 questions"],"h1":"It is a round number between 30 and 50.","h2":"The Washington knowledge test has 40 questions.","p":"Right. The test has 40 questions."},"es":{"q":"En Washington, ¿cuántas preguntas tiene el examen de conocimientos?","o":["25 preguntas","40 preguntas","50 preguntas","20 preguntas"],"h1":"Es un número redondo entre 30 y 50.","h2":"El examen de conocimientos de Washington tiene 40 preguntas.","p":"Correcto. El examen tiene 40 preguntas."},"ref":{"doc":"WA","page":null}},{"id":"wa-002","scope":"WA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Washington, how many correct answers do you need to pass the knowledge test?","o":["20","28","35","32"],"h1":"It is 80 percent of 40.","h2":"To pass the Washington knowledge test you need 32 correct answers out of 40, which is 80 percent.","p":"Correct. You need 32 right answers."},"es":{"q":"En Washington, ¿cuántas respuestas correctas necesita para aprobar el examen de conocimientos?","o":["20","28","35","32"],"h1":"Es el 80 por ciento de 40.","h2":"Para aprobar el examen de conocimientos de Washington necesita 32 respuestas correctas de 40, que es el 80 por ciento.","p":"Correcto. Necesita 32 respuestas correctas."},"ref":{"doc":"WA","page":null}},{"id":"wa-003","scope":"WA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Washington, how long is a passing knowledge test score good for?","o":["2 years","30 days","6 months","Forever"],"h1":"It lasts more than one year.","h2":"A passing score on the Washington knowledge test stays valid for 2 years.","p":"Right. It is good for 2 years."},"es":{"q":"En Washington, ¿por cuánto tiempo es válido un puntaje aprobado en el examen de conocimientos?","o":["2 años","30 días","6 meses","Para siempre"],"h1":"Dura más de un año.","h2":"Un puntaje aprobado en el examen de conocimientos de Washington sigue siendo válido por 2 años.","p":"Correcto. Es válido por 2 años."},"ref":{"doc":"WA","page":"§1.8"}},{"id":"wa-004","scope":"WA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Washington, what is the youngest age to get an instruction permit if you are enrolled in driver training?","o":["14","14 and a half","15","16"],"h1":"Without a course you would wait six months longer.","h2":"In Washington you can get an instruction permit at 15 if you are enrolled in an approved driver training course.","p":"Correct. Age 15 with driver training."},"es":{"q":"En Washington, ¿cuál es la edad mínima para obtener un permiso de instrucción si está inscrito en un curso de manejo?","o":["14 años","14 años y medio","15 años","16 años"],"h1":"Sin curso tendría que esperar seis meses más.","h2":"En Washington usted puede obtener un permiso de instrucción a los 15 años si está inscrito en un curso de manejo aprobado.","p":"Correcto. A los 15 con curso de manejo."},"ref":{"doc":"WA","page":"§1.8"}},{"id":"wa-005","scope":"WA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Washington, what is the youngest age to get an instruction permit without enrolling in driver training?","o":["15","15 and a half","16","17"],"h1":"It is half a year later than with a course.","h2":"In Washington a teen who is not in a driver training course must be 15 and a half to get an instruction permit.","p":"Right. 15 and a half without a course."},"es":{"q":"En Washington, ¿cuál es la edad mínima para obtener un permiso de instrucción sin inscribirse en un curso de manejo?","o":["15 años","15 años y medio","16 años","17 años"],"h1":"Es medio año más tarde que con un curso.","h2":"En Washington un joven que no está en un curso de manejo debe tener 15 años y medio para obtener un permiso de instrucción.","p":"Correcto. 15 años y medio sin curso."},"ref":{"doc":"WA","page":"§1.8"}},{"id":"wa-006","scope":"WA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Washington, who may supervise a driver with an instruction permit?","o":["Any person 16 or older","Any passenger with a car","A driver licensed for at least 1 year","A driver licensed for at least 5 years"],"h1":"The rule is about years of driving experience, not age.","h2":"A Washington permit holder must drive with a driving instructor or a licensed driver who has at least 5 years of driving experience.","p":"Correct. Licensed for 5 years or more."},"es":{"q":"En Washington, ¿quién puede supervisar a un conductor con permiso de instrucción?","o":["Cualquier persona de 16 años o más","Cualquier pasajero que tenga carro","Un conductor con licencia desde hace por lo menos 1 año","Un conductor con licencia desde hace por lo menos 5 años"],"h1":"La regla se refiere a los años de experiencia, no a la edad.","h2":"En Washington, quien tiene permiso debe manejar con un instructor de manejo o con un conductor con licencia que tenga por lo menos 5 años de experiencia.","p":"Correcto. Con licencia desde hace 5 años o más."},"ref":{"doc":"WA","page":"§1.8"}},{"id":"wa-007","scope":"WA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Washington, where must the supervising driver sit when a permit holder drives?","o":["In the seat beside the driver","In the back seat","Anywhere in the car","In another car following behind"],"h1":"The helper must be close enough to help right away.","h2":"In Washington the supervising driver must sit in the seat beside the permit holder.","p":"Right. Beside the driver."},"es":{"q":"En Washington, ¿dónde debe sentarse el conductor que supervisa cuando maneja alguien con permiso?","o":["En el asiento al lado del conductor","En el asiento de atrás","En cualquier lugar del carro","En otro carro que va detrás"],"h1":"El acompañante debe estar lo bastante cerca para ayudar de inmediato.","h2":"En Washington el conductor que supervisa debe sentarse en el asiento al lado de quien tiene el permiso.","p":"Correcto. Al lado del conductor."},"ref":{"doc":"WA","page":null}},{"id":"wa-008","scope":"WA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Washington, how long is an instruction permit valid?","o":["30 days","6 months","1 year","5 years"],"h1":"It can be renewed for a fee when it runs out.","h2":"A Washington instruction permit is valid for 1 year and can be renewed for a fee.","p":"Correct. One year."},"es":{"q":"En Washington, ¿por cuánto tiempo es válido un permiso de instrucción?","o":["30 días","6 meses","1 año","5 años"],"h1":"Se puede renovar pagando una tarifa cuando vence.","h2":"Un permiso de instrucción en Washington es válido por 1 año y se puede renovar pagando una tarifa.","p":"Correcto. Un año."},"ref":{"doc":"WA","page":"§1.8"}},{"id":"wa-009","scope":"WA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Washington, what must a teen do to get a driver license before turning 18?","o":["Nothing extra","Take a driver training course","Pass a test in another state","Wait until a parent turns 40"],"h1":"Without it, the teen must wait until 18.","h2":"In Washington a teen who wants a driver license before 18 must take a driver training course.","p":"Right. Driver training is required before 18."},"es":{"q":"En Washington, ¿qué debe hacer un joven para obtener la licencia antes de cumplir 18 años?","o":["Nada adicional","Tomar un curso de manejo","Aprobar un examen en otro estado","Esperar a que su padre o madre cumpla 40"],"h1":"Sin esto, el joven debe esperar hasta los 18.","h2":"En Washington un joven que quiere la licencia antes de los 18 años debe tomar un curso de manejo.","p":"Correcto. El curso de manejo es obligatorio antes de los 18."},"ref":{"doc":"WA","page":"§1.8"}},{"id":"wa-010","scope":"WA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Washington, how long must a teen hold an instruction permit before getting an intermediate license?","o":["At least 6 months","At least 1 month","At least 2 years","No minimum"],"h1":"It is half a year.","h2":"A Washington teen must hold an instruction permit for at least 6 months before getting an intermediate license.","p":"Correct. At least 6 months."},"es":{"q":"En Washington, ¿por cuánto tiempo debe un joven tener el permiso de instrucción antes de obtener la licencia intermedia?","o":["Por lo menos 6 meses","Por lo menos 1 mes","Por lo menos 2 años","No hay un mínimo"],"h1":"Es medio año.","h2":"Un joven en Washington debe tener el permiso de instrucción por lo menos 6 meses antes de obtener la licencia intermedia.","p":"Correcto. Por lo menos 6 meses."},"ref":{"doc":"WA","page":"§1.8"}},{"id":"wa-011","scope":"WA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Washington, how many hours of supervised daytime driving does a teen need before an intermediate license?","o":["10 hours","20 hours","30 hours","40 hours"],"h1":"Add 10 night hours to it and you get 50.","h2":"A Washington teen needs at least 40 hours of supervised daytime driving, plus 10 hours at night, before an intermediate license.","p":"Right. Forty daytime hours."},"es":{"q":"En Washington, ¿cuántas horas de manejo supervisado de día necesita un joven antes de la licencia intermedia?","o":["10 horas","20 horas","30 horas","40 horas"],"h1":"Si le suma 10 horas de noche, da 50.","h2":"Un joven en Washington necesita por lo menos 40 horas de manejo supervisado de día, más 10 horas de noche, antes de la licencia intermedia.","p":"Correcto. Cuarenta horas de día."},"ref":{"doc":"WA","page":"§1.8"}},{"id":"wa-012","scope":"WA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Washington, how many hours of supervised night driving does a teen need before an intermediate license?","o":["2 hours","5 hours","10 hours","40 hours"],"h1":"It is a round number, a quarter of the daytime hours.","h2":"A Washington teen needs at least 10 hours of supervised night driving before an intermediate license.","p":"Correct. Ten night hours."},"es":{"q":"En Washington, ¿cuántas horas de manejo supervisado de noche necesita un joven antes de la licencia intermedia?","o":["2 horas","5 horas","10 horas","40 horas"],"h1":"Es un número redondo, la cuarta parte de las horas de día.","h2":"Un joven en Washington necesita por lo menos 10 horas de manejo supervisado de noche antes de la licencia intermedia.","p":"Correcto. Diez horas de noche."},"ref":{"doc":"WA","page":"§1.8"}},{"id":"wa-013","scope":"WA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Washington, what is the youngest age to apply for an intermediate license?","o":["15","16","17","18"],"h1":"It comes after holding a permit for at least six months.","h2":"In Washington you can apply for an intermediate license at 16.","p":"Right. Age 16."},"es":{"q":"En Washington, ¿cuál es la edad mínima para solicitar una licencia intermedia?","o":["15 años","16 años","17 años","18 años"],"h1":"Llega después de tener el permiso por lo menos seis meses.","h2":"En Washington usted puede solicitar una licencia intermedia a los 16 años.","p":"Correcto. A los 16 años."},"ref":{"doc":"WA","page":"§1.8"}},{"id":"wa-014","scope":"WA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Washington, during which hours may an intermediate license holder not drive, unless an exception applies?","o":["1 a.m. to 5 a.m.","Midnight to 6 a.m.","10 p.m. to 5 a.m.","11 p.m. to 4 a.m."],"h1":"The window is four hours long and starts after midnight.","h2":"A Washington intermediate license holder may not drive between 1 a.m. and 5 a.m., unless an exception applies.","p":"Correct. No driving from 1 to 5 a.m."},"es":{"q":"En Washington, ¿en qué horario no puede manejar el titular de una licencia intermedia, salvo una excepción?","o":["De 1 a.m. a 5 a.m.","De medianoche a 6 a.m.","De 10 p.m. a 5 a.m.","De 11 p.m. a 4 a.m."],"h1":"El período dura cuatro horas y empieza después de medianoche.","h2":"El titular de una licencia intermedia en Washington no puede manejar entre la 1 a.m. y las 5 a.m., salvo una excepción.","p":"Correcto. No se maneja de 1 a 5 a.m."},"ref":{"doc":"WA","page":"§1.8"}},{"id":"wa-015","scope":"WA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Washington, which of these lets an intermediate license holder drive between 1 a.m. and 5 a.m.?","o":["Driving to a party","Driving with a friend who is 18","Driving on an empty road","Driving with a licensed driver who is at least 25"],"h1":"An older, experienced driver must be in the car, or the trip is for school, religion or work.","h2":"In Washington an intermediate license holder may drive between 1 a.m. and 5 a.m. with a licensed driver at least 25, or for school, religious or work activities.","p":"Right. A licensed driver 25 or older."},"es":{"q":"En Washington, ¿cuál de estas opciones permite al titular de una licencia intermedia manejar entre la 1 a.m. y las 5 a.m.?","o":["Ir a una fiesta","Manejar con un amigo de 18 años","Manejar por una calle vacía","Manejar con un conductor con licencia de por lo menos 25 años"],"h1":"Debe ir un conductor mayor con experiencia, o el viaje debe ser por escuela, religión o trabajo.","h2":"En Washington el titular de una licencia intermedia puede manejar entre la 1 a.m. y las 5 a.m. con un conductor con licencia de por lo menos 25 años, o para actividades escolares, religiosas o de trabajo.","p":"Correcto. Un conductor con licencia de 25 años o más."},"ref":{"doc":"WA","page":"§1.8"}},{"id":"wa-016","scope":"WA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Washington, during the first six months of an intermediate license, which passengers under 20 may ride with the driver?","o":["Only immediate family members","Up to three friends","One friend","Anyone"],"h1":"Friends under 20 have to wait.","h2":"During the first six months, a Washington intermediate license holder may carry no passengers under 20 except immediate family members.","p":"Correct. Only immediate family."},"es":{"q":"En Washington, durante los primeros seis meses de la licencia intermedia, ¿qué pasajeros menores de 20 años pueden ir con el conductor?","o":["Solo familiares directos","Hasta tres amigos","Un amigo","Cualquier persona"],"h1":"Los amigos menores de 20 tienen que esperar.","h2":"Durante los primeros seis meses, el titular de una licencia intermedia en Washington no puede llevar pasajeros menores de 20 años, excepto familiares directos.","p":"Correcto. Solo familiares directos."},"ref":{"doc":"WA","page":"§1.8"}},{"id":"wa-017","scope":"WA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Washington, after the first six months of an intermediate license, how many non-family passengers under 20 may the driver carry?","o":["None","One","Up to three","Up to five"],"h1":"The limit goes up after six months, but it is still a small number.","h2":"After the first six months, a Washington intermediate license holder may carry no more than three passengers under 20 who are not immediate family.","p":"Right. Up to three."},"es":{"q":"En Washington, después de los primeros seis meses de la licencia intermedia, ¿cuántos pasajeros menores de 20 años que no son familiares puede llevar el conductor?","o":["Ninguno","Uno","Hasta tres","Hasta cinco"],"h1":"El límite sube después de seis meses, pero sigue siendo pequeño.","h2":"Después de los primeros seis meses, el titular de una licencia intermedia en Washington no puede llevar más de tres pasajeros menores de 20 años que no sean familiares directos.","p":"Correcto. Hasta tres."},"ref":{"doc":"WA","page":"§1.8"}},{"id":"wa-018","scope":"WA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Washington, may a driver with an instruction permit or intermediate license use a phone hands-free?","o":["Yes, any time","No, only in an emergency","Yes, at red lights","Yes, for short calls"],"h1":"New drivers have a stricter rule than other drivers.","h2":"In Washington permit and intermediate license holders may not use a wireless device at all, even hands-free, except in an emergency.","p":"Correct. No phone except in an emergency."},"es":{"q":"En Washington, ¿puede un conductor con permiso de instrucción o licencia intermedia usar el teléfono con manos libres?","o":["Sí, en cualquier momento","No, solo en una emergencia","Sí, en los semáforos en rojo","Sí, para llamadas cortas"],"h1":"Los conductores nuevos tienen una regla más estricta que los demás.","h2":"En Washington quienes tienen permiso o licencia intermedia no pueden usar ningún dispositivo inalámbrico, ni siquiera con manos libres, excepto en una emergencia.","p":"Correcto. Nada de teléfono salvo en una emergencia."},"ref":{"doc":"WA","page":"§1.8"}},{"id":"wa-019","scope":"WA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Washington, may any driver hold a phone while stopped at a red light?","o":["Yes, while the light is red","Yes, if the engine is running","No, not even when stopped in traffic or at a light","Yes, to read a text"],"h1":"Being stopped in traffic still counts as driving.","h2":"Washington's distracted driving law says a driver may not hold a phone even when stopped in traffic or at a light.","p":"Right. Not even at a red light."},"es":{"q":"En Washington, ¿puede cualquier conductor sostener el teléfono mientras está detenido en un semáforo en rojo?","o":["Sí, mientras la luz está en rojo","Sí, si el motor está encendido","No, ni siquiera detenido en el tráfico o en un semáforo","Sí, para leer un mensaje"],"h1":"Estar detenido en el tráfico todavía cuenta como manejar.","h2":"La ley de manejo distraído de Washington dice que un conductor no puede sostener el teléfono ni siquiera detenido en el tráfico o en un semáforo.","p":"Correcto. Ni siquiera en un semáforo en rojo."},"ref":{"doc":"WA","page":"§3.4"}},{"id":"wa-020","scope":"WA","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Washington, if you cannot move over a lane for a stopped emergency vehicle, how much must you slow down?","o":["5 mph below the limit","To 15 mph","Not at all","At least 10 mph below the posted limit"],"h1":"It is a round number of miles per hour below the limit.","h2":"In Washington, if you cannot safely move over one lane, you must slow to at least 10 mph below the posted speed limit.","p":"Correct. At least 10 mph slower."},"es":{"q":"En Washington, si no puede cambiarse de carril por un vehículo de emergencia detenido, ¿cuánto debe reducir la velocidad?","o":["5 mph menos que el límite","Hasta 15 mph","Nada","Por lo menos 10 mph menos que el límite indicado"],"h1":"Es un número redondo de millas por hora menos que el límite.","h2":"En Washington, si no puede cambiarse un carril con seguridad, debe bajar la velocidad por lo menos 10 mph por debajo del límite indicado.","p":"Correcto. Por lo menos 10 mph menos."},"ref":{"doc":"WA","page":"§4.17"}},{"id":"wa-021","scope":"WA","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Washington, how far before and after a stopped emergency vehicle does the Move Over zone reach?","o":["50 feet","200 feet","500 feet","One mile"],"h1":"It is a few car lengths more than 100 feet.","h2":"In Washington the Move Over zone covers 200 feet before and 200 feet after the stopped emergency or work vehicle.","p":"Right. 200 feet each way."},"es":{"q":"En Washington, ¿hasta qué distancia antes y después de un vehículo de emergencia detenido llega la zona de Move Over?","o":["50 pies","200 pies","500 pies","Una milla"],"h1":"Es unos cuantos carros más que 100 pies.","h2":"En Washington la zona de Move Over cubre 200 pies antes y 200 pies después del vehículo de emergencia o de trabajo detenido.","p":"Correcto. 200 pies en cada dirección."},"ref":{"doc":"WA","page":null}},{"id":"wa-022","scope":"WA","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Washington, at what blood alcohol level is a driver under 21 breaking the law?","o":["0.02 or more","0.05 or more","0.08 or more","0.10 or more"],"h1":"It is much lower than the adult limit of 0.08.","h2":"In Washington a driver under 21 breaks the law with a blood alcohol level of 0.02 or more.","p":"Correct. The limit under 21 is 0.02."},"es":{"q":"En Washington, ¿con qué nivel de alcohol en la sangre un conductor menor de 21 años infringe la ley?","o":["0.02 o más","0.05 o más","0.08 o más","0.10 o más"],"h1":"Es mucho más bajo que el límite para adultos, que es 0.08.","h2":"En Washington un conductor menor de 21 años infringe la ley con un nivel de alcohol en la sangre de 0.02 o más.","p":"Correcto. El límite para menores de 21 es 0.02."},"ref":{"doc":"WA","page":"§1.15"}},{"id":"wa-023","scope":"WA","cat":"signals","sign":null,"c":2,"en":{"q":"In Washington, after a full stop at a red light, when may you turn left on red if no sign forbids it?","o":["Never","Only from a one-way street onto a two-way street","From a one-way or two-way street onto a one-way street going left","From any street onto any street"],"h1":"The street you turn into must carry traffic in only one direction, the way you are turning.","h2":"In Washington, after stopping and yielding, you may turn left on red from a one-way or two-way street onto a one-way street that carries traffic to the left, unless a sign forbids it.","p":"Right. Only onto a one-way street."},"es":{"q":"En Washington, después de detenerse por completo en un semáforo en rojo, ¿cuándo puede dar vuelta a la izquierda en rojo si ningún letrero lo prohíbe?","o":["Nunca","Solo de una calle de un sentido a una calle de doble sentido","De una calle de un sentido o de doble sentido a una calle de un sentido que va hacia la izquierda","De cualquier calle a cualquier calle"],"h1":"La calle a la que entra debe tener tráfico en un solo sentido, hacia donde usted da la vuelta.","h2":"En Washington, después de detenerse y ceder el paso, usted puede dar vuelta a la izquierda en rojo de una calle de un sentido o de doble sentido a una calle de un sentido con tráfico hacia la izquierda, a menos que un letrero lo prohíba.","p":"Correcto. Solo hacia una calle de un sentido."},"ref":{"doc":"WA","page":"§4.11"}},{"id":"wi-001","scope":"WI","cat":"licensing","sign":null,"c":3,"en":{"q":"In Wisconsin, how many questions are on the knowledge test?","o":["20 questions","25 questions","35 questions","50 questions"],"h1":"It is half of one hundred.","h2":"The Wisconsin knowledge test has 50 questions.","p":"Right. The Wisconsin test has 50 questions."},"es":{"q":"En Wisconsin, ¿cuántas preguntas tiene el examen de conocimientos?","o":["20 preguntas","25 preguntas","35 preguntas","50 preguntas"],"h1":"Es la mitad de cien.","h2":"El examen de conocimientos de Wisconsin tiene 50 preguntas.","p":"Correcto. El examen de Wisconsin tiene 50 preguntas."},"ref":{"doc":"WI","page":1}},{"id":"wi-002","scope":"WI","cat":"licensing","sign":null,"c":0,"en":{"q":"In Wisconsin, how many knowledge test questions must you answer correctly to pass?","o":["40","30","35","45"],"h1":"You need 80 percent of the 50 questions.","h2":"You must answer at least 40 of the 50 Wisconsin knowledge test questions correctly, which is 80 percent.","p":"Right. You need 40 correct answers."},"es":{"q":"En Wisconsin, ¿cuántas preguntas del examen de conocimientos debe contestar bien para aprobar?","o":["40","30","35","45"],"h1":"Necesita el 80 por ciento de las 50 preguntas.","h2":"Usted debe contestar bien por lo menos 40 de las 50 preguntas del examen de conocimientos de Wisconsin, que es el 80 por ciento.","p":"Correcto. Necesita 40 respuestas correctas."},"ref":{"doc":"WI","page":1}},{"id":"wi-003","scope":"WI","cat":"signs","sign":null,"c":2,"en":{"q":"In Wisconsin, how many questions are on the separate road signs test?","o":["5 questions","10 questions","15 questions","25 questions"],"h1":"It is between 10 and 20.","h2":"Wisconsin gives a separate road signs test with 15 questions, and you must answer at least 12 correctly.","p":"Right. The signs test has 15 questions."},"es":{"q":"En Wisconsin, ¿cuántas preguntas tiene el examen separado de señales de tránsito?","o":["5 preguntas","10 preguntas","15 preguntas","25 preguntas"],"h1":"Está entre 10 y 20.","h2":"Wisconsin hace un examen separado de señales de tránsito con 15 preguntas, y usted debe contestar bien por lo menos 12.","p":"Correcto. El examen de señales tiene 15 preguntas."},"ref":{"doc":"WI","page":1}},{"id":"wi-004","scope":"WI","cat":"licensing","sign":null,"c":1,"en":{"q":"In Wisconsin, how many hours of driving practice does an applicant under 18 need before a probationary license?","o":["30 hours","50 hours","20 hours","100 hours"],"h1":"The number went up in 2021.","h2":"A Wisconsin applicant under 18 needs 50 hours of driving practice, 10 of them at night, before a probationary license.","p":"Right. Wisconsin requires 50 hours."},"es":{"q":"En Wisconsin, ¿cuántas horas de práctica de manejo necesita un solicitante menor de 18 años antes de la licencia probatoria?","o":["30 horas","50 horas","20 horas","100 horas"],"h1":"El número subió en 2021.","h2":"Un solicitante de Wisconsin menor de 18 años necesita 50 horas de práctica de manejo, 10 de ellas de noche, antes de la licencia probatoria.","p":"Correcto. Wisconsin exige 50 horas."},"ref":{"doc":"WI","page":6}},{"id":"wi-005","scope":"WI","cat":"licensing","sign":null,"c":0,"en":{"q":"In Wisconsin, how many of the required practice hours must be at night?","o":["10 hours","5 hours","15 hours","25 hours"],"h1":"It is one fifth of 50.","h2":"At least 10 of the 50 practice hours required in Wisconsin must be driven at night.","p":"Right. Ten hours must be at night."},"es":{"q":"En Wisconsin, ¿cuántas de las horas de práctica obligatorias deben ser de noche?","o":["10 horas","5 horas","15 horas","25 horas"],"h1":"Es la quinta parte de 50.","h2":"Por lo menos 10 de las 50 horas de práctica que exige Wisconsin deben manejarse de noche.","p":"Correcto. Diez horas deben ser de noche."},"ref":{"doc":"WI","page":6}},{"id":"wi-006","scope":"WI","cat":"licensing","sign":null,"c":3,"en":{"q":"In Wisconsin, how long must you hold an instruction permit, violation free, before a probationary license?","o":["1 month","3 months","12 months","6 months"],"h1":"It is half a year.","h2":"In Wisconsin you must hold an instruction permit for at least six months and be violation free for those six months before a probationary license.","p":"Right. Six months, with no violations."},"es":{"q":"En Wisconsin, ¿cuánto tiempo debe tener el permiso de aprendiz, sin infracciones, antes de la licencia probatoria?","o":["1 mes","3 meses","12 meses","6 meses"],"h1":"Es medio año.","h2":"En Wisconsin usted debe tener el permiso de aprendiz por lo menos seis meses y no tener infracciones en esos seis meses antes de la licencia probatoria.","p":"Correcto. Seis meses, sin infracciones."},"ref":{"doc":"WI","page":6}},{"id":"wi-007","scope":"WI","cat":"licensing","sign":null,"c":2,"en":{"q":"In Wisconsin, besides driver education, what else does a teen need to apply for a probationary license?","o":["A car in their own name","A part-time job","An adult sponsor","A high school diploma"],"h1":"An adult must take responsibility for the teen driver.","h2":"A Wisconsin teen applying for a probationary license must be at least 16, finish an approved driver education course, and have an adult sponsor.","p":"Right. An adult sponsor is required."},"es":{"q":"En Wisconsin, además del curso de manejo, ¿qué más necesita un joven para solicitar la licencia probatoria?","o":["Un carro a su nombre","Un trabajo de medio tiempo","Un adulto patrocinador","Un diploma de secundaria"],"h1":"Un adulto debe hacerse responsable del joven conductor.","h2":"Un joven de Wisconsin que solicita la licencia probatoria debe tener por lo menos 16 años, terminar un curso de manejo aprobado y tener un adulto patrocinador.","p":"Correcto. Se necesita un adulto patrocinador."},"ref":{"doc":"WI","page":3}},{"id":"wi-008","scope":"WI","cat":"licensing","sign":null,"c":1,"en":{"q":"In Wisconsin, during daylight, how old must the licensed adult be who rides with an instruction permit holder, when not a parent or instructor?","o":["18","21","16","30"],"h1":"The adult must be old enough to drink legally.","h2":"In Wisconsin a permit holder may practice by day with a licensed adult who is at least 21 and has at least two years of driving experience; after dark the adult must be at least 25.","p":"Right. The adult must be 21 or older."},"es":{"q":"En Wisconsin, de día, ¿qué edad debe tener el adulto con licencia que acompaña a un conductor con permiso, si no es un padre ni un instructor?","o":["18","21","16","30"],"h1":"El adulto debe tener edad para tomar alcohol legalmente.","h2":"En Wisconsin un conductor con permiso puede practicar de día con un adulto con licencia que tenga por lo menos 21 años y por lo menos dos años de experiencia manejando; de noche el adulto debe tener por lo menos 25 años.","p":"Correcto. El adulto debe tener 21 años o más."},"ref":{"doc":"WI","page":5}},{"id":"wi-009","scope":"WI","cat":"licensing","sign":null,"c":3,"en":{"q":"In Wisconsin, who may ride with a probationary driver under 18 who is driving alone?","o":["No passengers at all","Only one family member","Up to three friends","Any number of immediate family and one other person"],"h1":"Family is treated differently from friends.","h2":"A Wisconsin probationary driver under 18 may carry any number of immediate family members and one other person; a qualified licensed adult may also ride along.","p":"Right. Immediate family plus one other person."},"es":{"q":"En Wisconsin, ¿quién puede viajar con un conductor con licencia probatoria menor de 18 años que maneja solo?","o":["Ningún pasajero","Solo un familiar","Hasta tres amigos","Cualquier número de familiares directos y una persona más"],"h1":"La familia se trata diferente que los amigos.","h2":"Un conductor con licencia probatoria menor de 18 años en Wisconsin puede llevar a cualquier número de familiares directos y a una persona más; también puede ir un adulto con licencia que cumpla los requisitos.","p":"Correcto. Familiares directos y una persona más."},"ref":{"doc":"WI","page":6}},{"id":"wi-010","scope":"WI","cat":"licensing","sign":null,"c":0,"en":{"q":"In Wisconsin, between midnight and 5 a.m., where may a probationary driver under 18 drive alone?","o":["Only between home, school and work","Anywhere","Only on highways","Nowhere, even for work"],"h1":"Think of the places a teen must get to.","h2":"A Wisconsin probationary driver under 18 may drive alone from midnight to 5 a.m. only between home, school and work.","p":"Right. Only between home, school and work."},"es":{"q":"En Wisconsin, entre medianoche y las 5 a.m., ¿a dónde puede manejar solo un conductor con licencia probatoria menor de 18 años?","o":["Solo entre la casa, la escuela y el trabajo","A cualquier lugar","Solo por autopistas","A ningún lugar, ni siquiera al trabajo"],"h1":"Piense en los lugares a los que un joven tiene que llegar.","h2":"Un conductor con licencia probatoria menor de 18 años en Wisconsin puede manejar solo de medianoche a 5 a.m. únicamente entre la casa, la escuela y el trabajo.","p":"Correcto. Solo entre la casa, la escuela y el trabajo."},"ref":{"doc":"WI","page":7}},{"id":"wi-011","scope":"WI","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Wisconsin, may a driver with an instruction permit or probationary license use a hands-free phone while driving?","o":["Yes, hands-free is allowed","No, except to report an emergency","Yes, but only on highways","Yes, if a parent says so"],"h1":"The rule covers every kind of phone, not only hand-held.","h2":"A Wisconsin driver with an instruction permit or probationary license may not use any phone while driving, hand-held or hands-free, except to report an emergency.","p":"Right. Only for an emergency."},"es":{"q":"En Wisconsin, ¿puede un conductor con permiso de aprendiz o licencia probatoria usar un teléfono manos libres mientras maneja?","o":["Sí, el manos libres está permitido","No, excepto para reportar una emergencia","Sí, pero solo en autopistas","Sí, si un padre lo autoriza"],"h1":"La regla cubre todo tipo de teléfono, no solo en la mano.","h2":"Un conductor de Wisconsin con permiso de aprendiz o licencia probatoria no puede usar ningún teléfono mientras maneja, ni en la mano ni con manos libres, excepto para reportar una emergencia.","p":"Correcto. Solo en una emergencia."},"ref":{"doc":"WI","page":49}},{"id":"wi-012","scope":"WI","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Wisconsin, on a road with two or more lanes going your way, what does the Move Over law tell you to do for a stopped emergency vehicle with flashing lights?","o":["Stop behind it","Keep your lane and speed","Move out of the lane closest to it, or slow down if you cannot","Turn on your hazard lights and pass"],"h1":"Give the stopped vehicle a whole empty lane if you can.","h2":"Wisconsin's Move Over law says to move out of the lane closest to a stopped emergency or maintenance vehicle with flashing lights, or to slow down if you cannot move over safely.","p":"Right. Move over, or slow down if you cannot."},"es":{"q":"En Wisconsin, en un camino con dos o más carriles en su sentido, ¿qué le indica la ley de \"Move Over\" ante un vehículo de emergencia detenido con luces encendidas?","o":["Detenerse detrás de él","Seguir en su carril y a su velocidad","Salir del carril más cercano a él, o bajar la velocidad si no puede","Encender sus luces intermitentes y pasar"],"h1":"Si puede, déjele un carril completo libre al vehículo detenido.","h2":"La ley de \"Move Over\" de Wisconsin dice que debe salir del carril más cercano a un vehículo de emergencia o mantenimiento detenido con luces encendidas, o bajar la velocidad si no puede cambiarse con seguridad.","p":"Correcto. Cámbiese de carril, o baje la velocidad si no puede."},"ref":{"doc":"WI","page":51}},{"id":"wi-013","scope":"WI","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Wisconsin, what was added to the Move Over law by 2025 Wisconsin Act 54?","o":["Disabled vehicles","Parked bicycles","Mail trucks only","Nothing was added"],"h1":"Think of a car stopped on the shoulder after breaking down.","h2":"Since 2025 Wisconsin Act 54, the Move Over law also protects disabled vehicles stopped along the road.","p":"Right. Disabled vehicles are now covered."},"es":{"q":"En Wisconsin, ¿qué se agregó a la ley de \"Move Over\" con la Ley 54 de Wisconsin de 2025?","o":["Vehículos descompuestos","Bicicletas estacionadas","Solo camiones del correo","No se agregó nada"],"h1":"Piense en un carro detenido en el acotamiento porque se descompuso.","h2":"Desde la Ley 54 de Wisconsin de 2025, la ley de \"Move Over\" también protege a los vehículos descompuestos detenidos a un lado del camino.","p":"Correcto. Los vehículos descompuestos ahora están cubiertos."},"ref":{"doc":"WI","page":null}},{"id":"wi-014","scope":"WI","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Wisconsin, how much alcohol may a driver under 21 have in the blood?","o":["Up to 0.08","Up to 0.04","Up to 0.02","None at all"],"h1":"Wisconsin calls this the absolute sobriety law.","h2":"Under Wisconsin's absolute sobriety law, a driver under 21 may not drive with any alcohol in the blood.","p":"Right. Under 21, no alcohol at all."},"es":{"q":"En Wisconsin, ¿cuánto alcohol puede tener en la sangre un conductor menor de 21 años?","o":["Hasta 0.08","Hasta 0.04","Hasta 0.02","Nada de alcohol"],"h1":"Wisconsin llama a esto la ley de sobriedad absoluta.","h2":"Según la ley de sobriedad absoluta de Wisconsin, un conductor menor de 21 años no puede manejar con nada de alcohol en la sangre.","p":"Correcto. Menor de 21, nada de alcohol."},"ref":{"doc":"WI","page":49}},{"id":"wi-015","scope":"WI","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Wisconsin, what is the penalty for breaking the absolute sobriety law?","o":["A warning only","A 3-month suspension, a $200 forfeiture and 4 points","Ten years in prison","A $5 fine"],"h1":"It includes a suspension of a quarter of a year.","h2":"Breaking Wisconsin's absolute sobriety law brings a three-month suspension, a $200 forfeiture and four points on your record.","p":"Right. Three months, $200 and four points."},"es":{"q":"En Wisconsin, ¿cuál es la sanción por no cumplir la ley de sobriedad absoluta?","o":["Solo una advertencia","Una suspensión de 3 meses, una multa de $200 y 4 puntos","Diez años de cárcel","Una multa de $5"],"h1":"Incluye una suspensión de la cuarta parte de un año.","h2":"No cumplir la ley de sobriedad absoluta de Wisconsin trae una suspensión de tres meses, una multa de $200 y cuatro puntos en su historial.","p":"Correcto. Tres meses, $200 y cuatro puntos."},"ref":{"doc":"WI","page":null}},{"id":"wi-016","scope":"WI","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Wisconsin, how is a first drunk driving (OWI) offense with no aggravating factors treated?","o":["As a felony","As a misdemeanor crime","As a civil violation, not a crime","It is not punished"],"h1":"Wisconsin is unusual among the states on this point.","h2":"In Wisconsin a first OWI offense is a civil violation rather than a crime, but it still brings a forfeiture and loss of your license.","p":"Right. A first OWI is a civil violation in Wisconsin."},"es":{"q":"En Wisconsin, ¿cómo se trata una primera infracción de manejar bajo los efectos del alcohol (OWI) sin agravantes?","o":["Como delito grave","Como delito menor","Como infracción civil, no como delito","No se castiga"],"h1":"Wisconsin es poco común entre los estados en este punto.","h2":"En Wisconsin una primera infracción OWI es una infracción civil y no un delito, pero aun así trae una multa y la pérdida de la licencia.","p":"Correcto. Una primera OWI es una infracción civil en Wisconsin."},"ref":{"doc":"WI","page":null}},{"id":"wi-017","scope":"WI","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Wisconsin, unless posted otherwise, what is the speed limit when passing a school while children are going to or from school?","o":["25 mph","30 mph","20 mph","15 mph"],"h1":"It is lower than 20.","h2":"Unless a different limit is posted, Wisconsin sets 15 miles per hour when passing a school while children are going to or from school or playing near it.","p":"Right. 15 mph near schools when children are present."},"es":{"q":"En Wisconsin, si no hay otro límite indicado, ¿cuál es el límite al pasar por una escuela mientras los niños llegan o salen?","o":["25 mph","30 mph","20 mph","15 mph"],"h1":"Es menos de 20.","h2":"Si no hay otro límite indicado, Wisconsin fija 15 millas por hora al pasar por una escuela mientras los niños llegan, salen o juegan cerca.","p":"Correcto. 15 mph cerca de escuelas cuando hay niños."},"ref":{"doc":"WI","page":10}},{"id":"wi-018","scope":"WI","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Wisconsin, what is the highest speed limit that may be posted on some freeways?","o":["65 mph","70 mph","75 mph","80 mph"],"h1":"It is five more than 65.","h2":"Wisconsin law allows a speed limit of 70 miles per hour on freeways where signs post it.","p":"Right. Some Wisconsin freeways are posted at 70 mph."},"es":{"q":"En Wisconsin, ¿cuál es el límite de velocidad más alto que se puede indicar en algunas autopistas?","o":["65 mph","70 mph","75 mph","80 mph"],"h1":"Es cinco más que 65.","h2":"La ley de Wisconsin permite un límite de 70 millas por hora en las autopistas donde las señales lo indican.","p":"Correcto. Algunas autopistas de Wisconsin están indicadas a 70 mph."},"ref":{"doc":"WI","page":null}},{"id":"wv-001","scope":"WV","cat":"licensing","sign":null,"c":1,"en":{"q":"In West Virginia, what is the youngest age for a Level 1 instruction permit?","o":["14 years old","15 years old","16 years old","17 years old"],"h1":"It is one year before the Level 2 license.","h2":"In West Virginia you can get a Level 1 instruction permit at 15.","p":"Right. Level 1 starts at 15."},"es":{"q":"En Virginia Occidental, ¿cuál es la edad mínima para el permiso de instrucción de Nivel 1?","o":["14 años","15 años","16 años","17 años"],"h1":"Es un año antes de la licencia de Nivel 2.","h2":"En Virginia Occidental usted puede obtener el permiso de instrucción de Nivel 1 a los 15 años.","p":"Correcto. El Nivel 1 empieza a los 15."},"ref":{"doc":"WV","page":9}},{"id":"wv-002","scope":"WV","cat":"licensing","sign":null,"c":2,"en":{"q":"In West Virginia, who must sign the permit application of someone under 18?","o":["A school principal","Any adult friend","A parent or legal guardian","Nobody, the teen signs alone"],"h1":"It is the adult responsible for the teen.","h2":"In West Virginia a parent or legal guardian must sign the application of an applicant under 18 before testing.","p":"Correct. A parent or guardian signs."},"es":{"q":"En Virginia Occidental, ¿quién debe firmar la solicitud de permiso de un menor de 18 años?","o":["El director de la escuela","Cualquier amigo adulto","Un padre o tutor legal","Nadie, el joven firma solo"],"h1":"Es el adulto responsable del joven.","h2":"En Virginia Occidental, un padre o tutor legal debe firmar la solicitud de un menor de 18 años antes del examen.","p":"Correcto. Firma un padre o tutor."},"ref":{"doc":"WV","page":9}},{"id":"wv-003","scope":"WV","cat":"licensing","sign":null,"c":3,"en":{"q":"In West Virginia, how old must the licensed driver supervising a Level 1 permit holder be?","o":["16 or older","18 or older","25 or older","21 or older"],"h1":"The supervisor must be old enough to drink legally.","h2":"In West Virginia a Level 1 permit holder must be supervised by a licensed driver who is 21 or older, or by a driving instructor.","p":"Right. The supervisor must be 21 or older."},"es":{"q":"En Virginia Occidental, ¿qué edad debe tener el conductor con licencia que supervisa a quien tiene permiso de Nivel 1?","o":["16 años o más","18 años o más","25 años o más","21 años o más"],"h1":"El supervisor debe tener edad para tomar alcohol legalmente.","h2":"En Virginia Occidental, quien tiene permiso de Nivel 1 debe ir supervisado por un conductor con licencia de 21 años o más, o por un instructor de manejo.","p":"Correcto. El supervisor debe tener 21 años o más."},"ref":{"doc":"WV","page":9}},{"id":"wv-004","scope":"WV","cat":"licensing","sign":null,"c":0,"en":{"q":"In West Virginia, who else may sit in the front seat while a Level 1 permit holder drives?","o":["Only the supervising driver","Any friend","A younger brother or sister","Nobody may sit in front"],"h1":"The front seat is for the person in charge of the lesson.","h2":"In West Virginia the supervising driver must be the only other person in the front seat while a Level 1 permit holder drives.","p":"Correct. Only the supervisor sits in front."},"es":{"q":"En Virginia Occidental, ¿quién más puede ir en el asiento delantero mientras maneja alguien con permiso de Nivel 1?","o":["Solo el conductor que supervisa","Cualquier amigo","Un hermano menor","Nadie puede ir adelante"],"h1":"El asiento delantero es para quien está a cargo de la práctica.","h2":"En Virginia Occidental, el conductor que supervisa debe ser la única otra persona en el asiento delantero mientras maneja alguien con permiso de Nivel 1.","p":"Correcto. Solo el supervisor va adelante."},"ref":{"doc":"WV","page":null}},{"id":"wv-005","scope":"WV","cat":"licensing","sign":null,"c":1,"en":{"q":"In West Virginia, during which hours may a Level 1 permit holder drive?","o":["Between 6 a.m. and 9 p.m.","Between 5 a.m. and 10 p.m.","Between 5 a.m. and midnight","At any hour with a supervisor"],"h1":"The window ends in the late evening, before midnight.","h2":"In West Virginia a Level 1 permit holder may drive only between 5 a.m. and 10 p.m.","p":"Right. Level 1 driving is from 5 a.m. to 10 p.m."},"es":{"q":"En Virginia Occidental, ¿en qué horario puede manejar quien tiene permiso de Nivel 1?","o":["Entre las 6 a.m. y las 9 p.m.","Entre las 5 a.m. y las 10 p.m.","Entre las 5 a.m. y la medianoche","A cualquier hora con supervisor"],"h1":"El horario termina en la noche, antes de la medianoche.","h2":"En Virginia Occidental, quien tiene permiso de Nivel 1 solo puede manejar entre las 5 a.m. y las 10 p.m.","p":"Correcto. El Nivel 1 maneja de 5 a.m. a 10 p.m."},"ref":{"doc":"WV","page":10}},{"id":"wv-006","scope":"WV","cat":"licensing","sign":null,"c":2,"en":{"q":"In West Virginia, how many passengers besides the supervisor may ride with a Level 1 permit holder, not counting family?","o":["None","No more than one","No more than two","No more than four"],"h1":"It is a small number, more than one.","h2":"In West Virginia a Level 1 permit holder may carry no more than two additional passengers unless they are family members.","p":"Correct. Up to two extra passengers."},"es":{"q":"En Virginia Occidental, ¿cuántos pasajeros, además del supervisor, pueden ir con alguien con permiso de Nivel 1, sin contar a la familia?","o":["Ninguno","No más de uno","No más de dos","No más de cuatro"],"h1":"Es un número pequeño, mayor que uno.","h2":"En Virginia Occidental, quien tiene permiso de Nivel 1 no puede llevar más de dos pasajeros adicionales, salvo que sean familiares.","p":"Correcto. Hasta dos pasajeros más."},"ref":{"doc":"WV","page":10}},{"id":"wv-007","scope":"WV","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In West Virginia, what blood alcohol level is allowed for a Level 1 permit holder?","o":["Below 0.02","Below 0.05","Below 0.08","None at all"],"h1":"This is called zero tolerance.","h2":"In West Virginia a Level 1 permit holder must drive with no measurable alcohol in the blood at all.","p":"Right. Zero alcohol for permit holders."},"es":{"q":"En Virginia Occidental, ¿qué nivel de alcohol en la sangre se permite a quien tiene permiso de Nivel 1?","o":["Menos de 0.02","Menos de 0.05","Menos de 0.08","Nada en absoluto"],"h1":"Esto se llama tolerancia cero.","h2":"En Virginia Occidental, quien tiene permiso de Nivel 1 debe manejar sin ninguna cantidad medible de alcohol en la sangre.","p":"Correcto. Cero alcohol con permiso."},"ref":{"doc":"WV","page":10}},{"id":"wv-008","scope":"WV","cat":"licensing","sign":null,"c":0,"en":{"q":"In West Virginia, how many hours of supervised driving are needed for a Level 2 license if you did not take driver education?","o":["50 hours","20 hours","30 hours","100 hours"],"h1":"It is a round number between 30 and 100.","h2":"In West Virginia you need 50 hours of supervised behind-the-wheel driving for a Level 2 license unless you completed driver education.","p":"Correct. Fifty hours are needed."},"es":{"q":"En Virginia Occidental, ¿cuántas horas de manejo supervisado se necesitan para la licencia de Nivel 2 si no tomó educación vial?","o":["50 horas","20 horas","30 horas","100 horas"],"h1":"Es un número redondo entre 30 y 100.","h2":"En Virginia Occidental usted necesita 50 horas de manejo supervisado para la licencia de Nivel 2, salvo que haya completado educación vial.","p":"Correcto. Se necesitan 50 horas."},"ref":{"doc":"WV","page":10}},{"id":"wv-009","scope":"WV","cat":"licensing","sign":null,"c":1,"en":{"q":"In West Virginia, how many of the 50 supervised hours must be at night?","o":["At least 2 hours","At least 10 hours","At least 5 hours","At least 25 hours"],"h1":"It is one fifth of the total.","h2":"In West Virginia at least 10 of the 50 supervised driving hours must be at night.","p":"Right. Ten hours are at night."},"es":{"q":"En Virginia Occidental, ¿cuántas de las 50 horas supervisadas deben ser de noche?","o":["Por lo menos 2 horas","Por lo menos 10 horas","Por lo menos 5 horas","Por lo menos 25 horas"],"h1":"Es la quinta parte del total.","h2":"En Virginia Occidental, por lo menos 10 de las 50 horas de manejo supervisado deben ser de noche.","p":"Correcto. Diez horas son de noche."},"ref":{"doc":"WV","page":10}},{"id":"wv-010","scope":"WV","cat":"licensing","sign":null,"c":2,"en":{"q":"In West Virginia, how long must you hold a Level 1 permit without a conviction before applying for Level 2?","o":["30 days","90 days","180 days","One year"],"h1":"It is about six months.","h2":"In West Virginia you must hold your Level 1 permit conviction-free for the 180 days before you apply for a Level 2 license.","p":"Correct. It is 180 days without a conviction."},"es":{"q":"En Virginia Occidental, ¿cuánto tiempo debe tener el permiso de Nivel 1 sin condenas antes de solicitar el Nivel 2?","o":["30 días","90 días","180 días","Un año"],"h1":"Son unos seis meses.","h2":"En Virginia Occidental usted debe tener el permiso de Nivel 1 sin condenas durante los 180 días antes de solicitar la licencia de Nivel 2.","p":"Correcto. Son 180 días sin condenas."},"ref":{"doc":"WV","page":10}},{"id":"wv-011","scope":"WV","cat":"licensing","sign":null,"c":3,"en":{"q":"In West Virginia, when may a Level 2 driver drive alone without a supervisor?","o":["Between 6 a.m. and 9 p.m.","Between 5 a.m. and midnight","Only on school days","Between 5 a.m. and 10 p.m."],"h1":"It is the same window as for a Level 1 permit.","h2":"In West Virginia a Level 2 driver may drive unsupervised between 5 a.m. and 10 p.m.; later hours need a licensed driver 21 or older, except for work, school, religious events or emergencies.","p":"Right. Alone from 5 a.m. to 10 p.m."},"es":{"q":"En Virginia Occidental, ¿cuándo puede un conductor de Nivel 2 manejar solo, sin supervisor?","o":["Entre las 6 a.m. y las 9 p.m.","Entre las 5 a.m. y la medianoche","Solo los días de escuela","Entre las 5 a.m. y las 10 p.m."],"h1":"Es el mismo horario que el del permiso de Nivel 1.","h2":"En Virginia Occidental, un conductor de Nivel 2 puede manejar solo entre las 5 a.m. y las 10 p.m.; más tarde necesita un conductor con licencia de 21 años o más, salvo por trabajo, escuela, eventos religiosos o emergencias.","p":"Correcto. Solo, de 5 a.m. a 10 p.m."},"ref":{"doc":"WV","page":10}},{"id":"wv-012","scope":"WV","cat":"licensing","sign":null,"c":0,"en":{"q":"In West Virginia, during the first six months of a Level 2 license, how many passengers under 20 who are not family may you carry?","o":["None","One","Two","Three"],"h1":"The first months are the strictest.","h2":"In West Virginia, for the first six months of a Level 2 license, you may not carry any passengers under 20 unless they are family members.","p":"Correct. No young non-family passengers at first."},"es":{"q":"En Virginia Occidental, durante los primeros seis meses de la licencia de Nivel 2, ¿cuántos pasajeros menores de 20 años que no son familia puede llevar?","o":["Ninguno","Uno","Dos","Tres"],"h1":"Los primeros meses son los más estrictos.","h2":"En Virginia Occidental, durante los primeros seis meses de la licencia de Nivel 2, no puede llevar pasajeros menores de 20 años, salvo que sean familiares.","p":"Correcto. Al principio, ningún pasajero joven que no sea familia."},"ref":{"doc":"WV","page":11}},{"id":"wv-013","scope":"WV","cat":"licensing","sign":null,"c":1,"en":{"q":"In West Virginia, during the second six months of a Level 2 license, how many passengers under 20 who are not family may you carry?","o":["None","No more than one","No more than two","No more than three"],"h1":"The limit opens up by just one.","h2":"In West Virginia, for the second six months of a Level 2 license, you may not carry more than one passenger under 20 who is not a family member.","p":"Right. Only one passenger under 20."},"es":{"q":"En Virginia Occidental, durante los segundos seis meses de la licencia de Nivel 2, ¿cuántos pasajeros menores de 20 años que no son familiares puede llevar?","o":["Ninguno","No más de uno","No más de dos","No más de tres"],"h1":"El límite se abre solo en uno.","h2":"En Virginia Occidental, durante los segundos seis meses de la licencia de Nivel 2, no puede llevar más de un pasajero menor de 20 años que no sea familiar.","p":"Correcto. Solo un pasajero menor de 20."},"ref":{"doc":"WV","page":11}},{"id":"wv-014","scope":"WV","cat":"licensing","sign":null,"c":2,"en":{"q":"In West Virginia, what is the youngest age for a Level 3 full license?","o":["16 years old","18 years old","17 years old","21 years old"],"h1":"It is one year after the youngest Level 2 age.","h2":"In West Virginia you can get a Level 3 full license at 17 after holding a Level 2 license for 12 months without a conviction.","p":"Correct. Level 3 starts at 17."},"es":{"q":"En Virginia Occidental, ¿cuál es la edad mínima para la licencia completa de Nivel 3?","o":["16 años","18 años","17 años","21 años"],"h1":"Es un año después de la edad mínima del Nivel 2.","h2":"En Virginia Occidental usted puede obtener la licencia completa de Nivel 3 a los 17 años, después de tener la licencia de Nivel 2 por 12 meses sin condenas.","p":"Correcto. El Nivel 3 empieza a los 17."},"ref":{"doc":"WV","page":12}},{"id":"wv-015","scope":"WV","cat":"licensing","sign":null,"c":3,"en":{"q":"In West Virginia, how long must you hold a Level 2 license without a conviction before Level 3?","o":["3 months","6 months","24 months","12 months"],"h1":"It is one full year.","h2":"In West Virginia you must hold a Level 2 license conviction-free for 12 months before applying for Level 3.","p":"Right. One year without a conviction."},"es":{"q":"En Virginia Occidental, ¿cuánto tiempo debe tener la licencia de Nivel 2 sin condenas antes del Nivel 3?","o":["3 meses","6 meses","24 meses","12 meses"],"h1":"Es un año completo.","h2":"En Virginia Occidental usted debe tener la licencia de Nivel 2 sin condenas durante 12 meses antes de solicitar el Nivel 3.","p":"Correcto. Un año sin condenas."},"ref":{"doc":"WV","page":12}},{"id":"wv-016","scope":"WV","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In West Virginia, when may a driver under 18 with a permit or Level 2 license use a phone while driving?","o":["Only to call 911","Any time, if it is hands-free","Only at red lights","Only to text a parent"],"h1":"There is only one exception, and it is for emergencies.","h2":"In West Virginia a driver under 18 with a permit or Level 2 license may not use a phone or other wireless device while driving, except to call 911.","p":"Correct. Only a 911 call is allowed."},"es":{"q":"En Virginia Occidental, ¿cuándo puede un conductor menor de 18 años con permiso o licencia de Nivel 2 usar el teléfono mientras maneja?","o":["Solo para llamar al 911","En cualquier momento, si es manos libres","Solo en los semáforos en rojo","Solo para escribirle a un padre"],"h1":"Hay una sola excepción, y es para emergencias.","h2":"En Virginia Occidental, un conductor menor de 18 años con permiso o licencia de Nivel 2 no puede usar un teléfono ni otro aparato inalámbrico mientras maneja, salvo para llamar al 911.","p":"Correcto. Solo se permite llamar al 911."},"ref":{"doc":"WV","page":11}},{"id":"wv-017","scope":"WV","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In West Virginia, what does the law say about adult drivers and phones?","o":["You may text if traffic is slow","You may not hold the phone; calls must be hands-free","You may hold the phone on rural roads","There is no phone law for adults"],"h1":"Your hands belong on the wheel.","h2":"In West Virginia no driver may hold a phone while driving, and calls are allowed only with hands-free or voice-operated features.","p":"Right. Adults must be hands-free too."},"es":{"q":"En Virginia Occidental, ¿qué dice la ley sobre los conductores adultos y el teléfono?","o":["Puede escribir mensajes si el tráfico es lento","No puede sostener el teléfono; las llamadas deben ser manos libres","Puede sostener el teléfono en caminos rurales","No hay ley de teléfonos para adultos"],"h1":"Sus manos deben estar en el volante.","h2":"En Virginia Occidental ningún conductor puede sostener un teléfono mientras maneja, y las llamadas solo se permiten con manos libres o por voz.","p":"Correcto. Los adultos también deben usar manos libres."},"ref":{"doc":"WV","page":17}},{"id":"wv-018","scope":"WV","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In West Virginia, what blood alcohol level is a crime for a driver under 21?","o":["0.08 or more","0.05 or more","0.02 or more","0.10 or more"],"h1":"It is far below the adult limit.","h2":"In West Virginia a driver under 21 commits a misdemeanor by driving with a blood alcohol level of 0.02 or more.","p":"Correct. Under 21, the limit is 0.02."},"es":{"q":"En Virginia Occidental, ¿qué nivel de alcohol en la sangre es un delito para un conductor menor de 21 años?","o":["0.08 o más","0.05 o más","0.02 o más","0.10 o más"],"h1":"Es mucho más bajo que el límite para adultos.","h2":"En Virginia Occidental, un conductor menor de 21 años comete un delito menor si maneja con un nivel de alcohol en la sangre de 0.02 o más.","p":"Correcto. Para menores de 21, el límite es 0.02."},"ref":{"doc":"WV","page":null}},{"id":"wv-019","scope":"WV","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In West Virginia, which stopped vehicle with flashing lights is covered by the move over law?","o":["Only police cars","Only fire trucks","Only ambulances","All of these: police cars, ambulances and tow trucks"],"h1":"The law covers any stopped vehicle that shows warning lights.","h2":"In West Virginia the move over law covers every stopped vehicle with flashing or hazard lights, including police cars, ambulances and tow trucks, so you move over if it is safe or slow down.","p":"Right. The law covers all of them."},"es":{"q":"En Virginia Occidental, ¿qué vehículo detenido con luces intermitentes está cubierto por la ley de cambiarse de carril (move over)?","o":["Solo patrullas","Solo camiones de bomberos","Solo ambulancias","Todos estos: patrullas, ambulancias y grúas"],"h1":"La ley cubre a cualquier vehículo detenido que muestre luces de advertencia.","h2":"En Virginia Occidental, la ley de cambiarse de carril cubre a todo vehículo detenido con luces intermitentes o de emergencia, incluidas patrullas, ambulancias y grúas, así que usted se cambia de carril si es seguro o reduce la velocidad.","p":"Correcto. La ley los cubre a todos."},"ref":{"doc":"WV","page":null}},{"id":"wv-020","scope":"WV","cat":"licensing","sign":null,"c":0,"en":{"q":"In West Virginia, if you fail the permit knowledge test, how long must you wait to try again?","o":["Seven days","One day","Thirty days","Six months"],"h1":"It is one week.","h2":"In West Virginia you must wait seven days before retaking a failed knowledge test.","p":"Correct. You wait one week."},"es":{"q":"En Virginia Occidental, si no aprueba el examen de conocimientos del permiso, ¿cuánto debe esperar para intentarlo otra vez?","o":["Siete días","Un día","Treinta días","Seis meses"],"h1":"Es una semana.","h2":"En Virginia Occidental usted debe esperar siete días antes de repetir un examen de conocimientos que no aprobó.","p":"Correcto. Se espera una semana."},"ref":{"doc":"WV","page":26}},{"id":"wv-021","scope":"WV","cat":"licensing","sign":null,"c":1,"en":{"q":"In West Virginia, what do you need to take the permit knowledge test online?","o":["Only a smartphone","A computer with a mouse and a webcam","A tablet with no camera","A printed paper test"],"h1":"A phone will not work for this test.","h2":"In West Virginia the online knowledge test needs a computer with a mouse and a webcam; phones and touch screens do not work.","p":"Right. You need a computer with a camera."},"es":{"q":"En Virginia Occidental, ¿qué necesita para tomar en línea el examen de conocimientos del permiso?","o":["Solo un teléfono inteligente","Una computadora con ratón y cámara web","Una tableta sin cámara","Un examen impreso en papel"],"h1":"Un teléfono no sirve para este examen.","h2":"En Virginia Occidental, el examen de conocimientos en línea necesita una computadora con ratón y cámara web; los teléfonos y las pantallas táctiles no sirven.","p":"Correcto. Necesita una computadora con cámara."},"ref":{"doc":"WV","page":null}},{"id":"wy-001","scope":"WY","cat":"licensing","sign":null,"c":1,"en":{"q":"In Wyoming, what is the youngest age to get a learner's permit?","o":["14 years old","15 years old","15 and a half years old","16 years old"],"h1":"It is one year before the intermediate permit.","h2":"In Wyoming you can get a learner's permit at 15 years old.","p":"Right. The Wyoming learner's permit starts at 15."},"es":{"q":"En Wyoming, ¿cuál es la edad mínima para obtener un permiso de aprendiz?","o":["14 años","15 años","15 años y medio","16 años"],"h1":"Es un año antes del permiso intermedio.","h2":"En Wyoming usted puede obtener el permiso de aprendiz a los 15 años.","p":"Correcto. El permiso de aprendiz en Wyoming empieza a los 15."},"ref":{"doc":"WY","page":7}},{"id":"wy-002","scope":"WY","cat":"licensing","sign":null,"c":0,"en":{"q":"In Wyoming, how long must you hold a learner's permit before you can get an intermediate permit?","o":["At least 10 days","At least 6 months","At least one year","At least two years"],"h1":"Wyoming's waiting time is much shorter than in most states.","h2":"In Wyoming you must hold your learner's permit for at least 10 days before you can get an intermediate permit.","p":"Right. Only 10 days in Wyoming."},"es":{"q":"En Wyoming, ¿cuánto tiempo debe tener el permiso de aprendiz antes de obtener el permiso intermedio?","o":["Por lo menos 10 días","Por lo menos 6 meses","Por lo menos un año","Por lo menos dos años"],"h1":"En Wyoming la espera es mucho más corta que en la mayoría de los estados.","h2":"En Wyoming usted debe tener el permiso de aprendiz por lo menos 10 días antes de obtener el permiso intermedio.","p":"Correcto. Solo 10 días en Wyoming."},"ref":{"doc":"WY","page":null}},{"id":"wy-003","scope":"WY","cat":"licensing","sign":null,"c":2,"en":{"q":"In Wyoming, what is the youngest age to get an intermediate permit?","o":["14 years old","15 years old","16 years old","17 years old"],"h1":"It is one year after the learner's permit age.","h2":"In Wyoming you must be at least 16 to get an intermediate permit.","p":"Right. The intermediate permit starts at 16."},"es":{"q":"En Wyoming, ¿cuál es la edad mínima para obtener el permiso intermedio?","o":["14 años","15 años","16 años","17 años"],"h1":"Es un año después de la edad del permiso de aprendiz.","h2":"En Wyoming usted debe tener por lo menos 16 años para obtener el permiso intermedio.","p":"Correcto. El permiso intermedio empieza a los 16."},"ref":{"doc":"WY","page":7}},{"id":"wy-004","scope":"WY","cat":"licensing","sign":null,"c":3,"en":{"q":"In Wyoming, how many hours behind the wheel must you complete before the intermediate permit, and how many at night?","o":["25 hours, 5 at night","30 hours, 10 at night","40 hours, 15 at night","50 hours, 10 at night"],"h1":"The night hours are one fifth of the total.","h2":"In Wyoming you must complete 50 hours behind the wheel, including 10 hours at night, before getting an intermediate permit.","p":"Right. Fifty hours, ten at night."},"es":{"q":"En Wyoming, ¿cuántas horas al volante debe completar antes del permiso intermedio, y cuántas de noche?","o":["25 horas, 5 de noche","30 horas, 10 de noche","40 horas, 15 de noche","50 horas, 10 de noche"],"h1":"Las horas de noche son una quinta parte del total.","h2":"En Wyoming usted debe completar 50 horas al volante, con 10 horas de noche, antes de obtener el permiso intermedio.","p":"Correcto. Cincuenta horas, diez de noche."},"ref":{"doc":"WY","page":14}},{"id":"wy-005","scope":"WY","cat":"licensing","sign":null,"c":1,"en":{"q":"In Wyoming, who must certify that a teen finished the practice driving hours?","o":["The teen alone","A parent or guardian","A police officer","A school teacher"],"h1":"It is the adult who is responsible for the teen.","h2":"In Wyoming, a parent or guardian must certify that the teen completed the practice driving hours.","p":"Right. A parent or guardian signs for the hours."},"es":{"q":"En Wyoming, ¿quién debe certificar que un adolescente terminó las horas de práctica?","o":["El adolescente solo","El padre, madre o tutor","Un policía","Un maestro de la escuela"],"h1":"Es el adulto responsable del adolescente.","h2":"En Wyoming, el padre, madre o tutor debe certificar que el adolescente completó las horas de práctica de manejo.","p":"Correcto. El padre, madre o tutor firma por las horas."},"ref":{"doc":"WY","page":14}},{"id":"wy-006","scope":"WY","cat":"licensing","sign":null,"c":0,"en":{"q":"In Wyoming, during which hours may an intermediate permit holder drive?","o":["5 a.m. to 11 p.m.","6 a.m. to 9 p.m.","7 a.m. to 10 p.m.","Any time"],"h1":"The window ends late in the evening.","h2":"In Wyoming, an intermediate permit holder may drive only between 5 a.m. and 11 p.m., unless an exception applies.","p":"Right. Five in the morning to eleven at night."},"es":{"q":"En Wyoming, ¿en qué horario puede manejar quien tiene permiso intermedio?","o":["De 5 a.m. a 11 p.m.","De 6 a.m. a 9 p.m.","De 7 a.m. a 10 p.m.","A cualquier hora"],"h1":"El horario termina tarde en la noche.","h2":"En Wyoming, quien tiene permiso intermedio solo puede manejar entre las 5 a.m. y las 11 p.m., salvo que aplique una excepción.","p":"Correcto. De cinco de la mañana a once de la noche."},"ref":{"doc":"WY","page":14}},{"id":"wy-007","scope":"WY","cat":"licensing","sign":null,"c":2,"en":{"q":"In Wyoming, an intermediate permit holder drives at night for work. What is needed?","o":["Nothing at all","A note from a friend","A signed exception form","A police escort"],"h1":"Wyoming has a special paper for this.","h2":"In Wyoming, driving outside the allowed hours for work, school, sports or religious activities requires a signed exception form.","p":"Right. You need the signed exception form."},"es":{"q":"En Wyoming, quien tiene permiso intermedio maneja de noche por trabajo. ¿Qué necesita?","o":["Nada","Una nota de un amigo","Un formulario de excepción firmado","Una escolta de policía"],"h1":"Wyoming tiene un papel especial para esto.","h2":"En Wyoming, para manejar fuera del horario permitido por trabajo, escuela, deportes o actividades religiosas se necesita un formulario de excepción firmado.","p":"Correcto. Necesita el formulario de excepción firmado."},"ref":{"doc":"WY","page":14}},{"id":"wy-008","scope":"WY","cat":"licensing","sign":null,"c":3,"en":{"q":"In Wyoming, an intermediate permit holder drives to the hospital at night for a medical emergency. Is an exception form needed?","o":["Yes, always","Yes, signed by a doctor","Yes, signed by the police","No, a medical emergency does not need the form"],"h1":"In a real emergency, paperwork comes second.","h2":"In Wyoming, a trip to the hospital for a medical emergency does not require the exception form.","p":"Right. A medical emergency needs no form."},"es":{"q":"En Wyoming, quien tiene permiso intermedio maneja de noche al hospital por una emergencia médica. ¿Necesita el formulario de excepción?","o":["Sí, siempre","Sí, firmado por un médico","Sí, firmado por la policía","No, una emergencia médica no necesita el formulario"],"h1":"En una emergencia real, los papeles van después.","h2":"En Wyoming, un viaje al hospital por una emergencia médica no requiere el formulario de excepción.","p":"Correcto. Una emergencia médica no necesita formulario."},"ref":{"doc":"WY","page":null}},{"id":"wy-009","scope":"WY","cat":"licensing","sign":null,"c":1,"en":{"q":"In Wyoming, how many passengers under 18 who are not immediate family may an intermediate permit holder carry?","o":["None","One","Two","Three"],"h1":"It is the smallest number that is more than zero.","h2":"In Wyoming, an intermediate permit holder may carry no more than one passenger under 18 who is not an immediate family member.","p":"Right. Only one non-family passenger under 18."},"es":{"q":"En Wyoming, ¿cuántos pasajeros menores de 18 años que no son familia directa puede llevar quien tiene permiso intermedio?","o":["Ninguno","Uno","Dos","Tres"],"h1":"Es el número más pequeño mayor que cero.","h2":"En Wyoming, quien tiene permiso intermedio puede llevar como máximo un pasajero menor de 18 años que no sea familiar directo.","p":"Correcto. Solo un pasajero menor de 18 que no sea familia."},"ref":{"doc":"WY","page":14}},{"id":"wy-010","scope":"WY","cat":"licensing","sign":null,"c":0,"en":{"q":"In Wyoming, when does the passenger limit for an intermediate permit holder not apply?","o":["When a licensed adult age 18 or older sits in the front seat","On weekends","On rural roads","When the radio is off"],"h1":"An experienced adult beside you changes the rule.","h2":"In Wyoming, the passenger limit does not apply when a licensed adult who is at least 18 rides in the front seat.","p":"Right. A licensed adult in the front seat lifts the limit."},"es":{"q":"En Wyoming, ¿cuándo no aplica el límite de pasajeros para quien tiene permiso intermedio?","o":["Cuando un adulto con licencia de 18 años o más va en el asiento delantero","Los fines de semana","En caminos rurales","Cuando el radio está apagado"],"h1":"Un adulto con experiencia a su lado cambia la regla.","h2":"En Wyoming, el límite de pasajeros no aplica cuando un adulto con licencia de por lo menos 18 años va en el asiento delantero.","p":"Correcto. Un adulto con licencia adelante quita el límite."},"ref":{"doc":"WY","page":14}},{"id":"wy-011","scope":"WY","cat":"licensing","sign":null,"c":2,"en":{"q":"In Wyoming, how long must you hold an intermediate permit?","o":["30 days","3 months","Six months or until age 17","Until age 18"],"h1":"It is half a year, unless a birthday comes first.","h2":"In Wyoming you must hold the intermediate permit for at least six months or until you turn 17.","p":"Right. Six months or until 17."},"es":{"q":"En Wyoming, ¿cuánto tiempo debe tener el permiso intermedio?","o":["30 días","3 meses","Seis meses o hasta los 17 años","Hasta los 18 años"],"h1":"Es medio año, a menos que llegue antes un cumpleaños.","h2":"En Wyoming usted debe tener el permiso intermedio por lo menos seis meses o hasta cumplir 17 años.","p":"Correcto. Seis meses o hasta los 17."},"ref":{"doc":"WY","page":7}},{"id":"wy-012","scope":"WY","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Wyoming, what is the highest speed limit on interstate highways?","o":["65 mph","70 mph","80 mph","90 mph"],"h1":"Some interstate parts are 75 mph. The top limit is a little higher.","h2":"In Wyoming the highest interstate speed limit is 80 mph, and some interstate sections are 75 mph, so always obey the posted sign.","p":"Right. The top limit on Wyoming interstates is 80 mph."},"es":{"q":"En Wyoming, ¿cuál es el límite de velocidad más alto en las autopistas interestatales?","o":["65 mph","70 mph","80 mph","90 mph"],"h1":"Algunas partes de la interestatal son de 75 mph. El límite más alto es un poco mayor.","h2":"En Wyoming el límite más alto en las interestatales es de 80 mph, y algunas partes son de 75 mph, así que siempre obedezca el letrero.","p":"Correcto. El límite más alto en las interestatales de Wyoming es de 80 mph."},"ref":{"doc":"WY","page":41}},{"id":"wy-013","scope":"WY","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Wyoming, what is the speed limit on a state highway that is not an interstate, when no other limit is posted?","o":["55 mph","70 mph","75 mph","80 mph"],"h1":"It is ten less than the interstate limit.","h2":"In Wyoming the speed limit on a state highway that is not an interstate is 70 mph unless another limit is posted.","p":"Right. State highways that are not interstates are 70 mph."},"es":{"q":"En Wyoming, ¿cuál es el límite de velocidad en una carretera estatal que no es interestatal, cuando no hay otro límite indicado?","o":["55 mph","70 mph","75 mph","80 mph"],"h1":"Es diez menos que el límite de la interestatal.","h2":"En Wyoming el límite de velocidad en una carretera estatal que no es interestatal es de 70 mph, a menos que haya otro límite indicado.","p":"Correcto. Las carreteras estatales que no son interestatales son de 70 mph."},"ref":{"doc":"WY","page":41}},{"id":"wy-014","scope":"WY","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Wyoming, what is the speed limit on an unpaved road when no other limit is posted?","o":["55 mph","45 mph","65 mph","70 mph"],"h1":"It is fifteen less than on a paved road.","h2":"In Wyoming the speed limit on an unpaved road is 55 mph unless another limit is posted.","p":"Right. Unpaved roads are 55 mph."},"es":{"q":"En Wyoming, ¿cuál es el límite de velocidad en un camino sin pavimentar cuando no hay otro límite indicado?","o":["55 mph","45 mph","65 mph","70 mph"],"h1":"Es quince menos que en un camino pavimentado.","h2":"En Wyoming el límite de velocidad en un camino sin pavimentar es de 55 mph, a menos que haya otro límite indicado.","p":"Correcto. Los caminos sin pavimentar son de 55 mph."},"ref":{"doc":"WY","page":null}},{"id":"wy-015","scope":"WY","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Wyoming, what is the speed limit in an urban area when no other limit is posted?","o":["20 mph","25 mph","30 mph","35 mph"],"h1":"It is ten more than a school zone.","h2":"In Wyoming the speed limit in urban areas is 30 mph unless another limit is posted.","p":"Right. Urban areas are 30 mph."},"es":{"q":"En Wyoming, ¿cuál es el límite de velocidad en una zona urbana cuando no hay otro límite indicado?","o":["20 mph","25 mph","30 mph","35 mph"],"h1":"Es diez más que en una zona escolar.","h2":"En Wyoming el límite de velocidad en zonas urbanas es de 30 mph, a menos que haya otro límite indicado.","p":"Correcto. Las zonas urbanas son de 30 mph."},"ref":{"doc":"WY","page":41}},{"id":"wy-016","scope":"WY","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Wyoming, what is the speed limit in a signed school zone with a reduced limit?","o":["20 mph","15 mph","25 mph","30 mph"],"h1":"It is ten less than the urban limit.","h2":"In Wyoming the speed limit in a school zone with signs showing the reduced limit is 20 mph.","p":"Right. School zones are 20 mph."},"es":{"q":"En Wyoming, ¿cuál es el límite de velocidad en una zona escolar señalizada con límite reducido?","o":["20 mph","15 mph","25 mph","30 mph"],"h1":"Es diez menos que el límite urbano.","h2":"En Wyoming el límite de velocidad en una zona escolar con letreros de límite reducido es de 20 mph.","p":"Correcto. Las zonas escolares son de 20 mph."},"ref":{"doc":"WY","page":41}},{"id":"wy-017","scope":"WY","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Wyoming, a driver under 21 may not drive with a blood alcohol level of what amount or more?","o":[".05 percent",".02 percent",".08 percent",".10 percent"],"h1":"It is a tiny fraction of the adult limit.","h2":"In Wyoming a driver under 21 may not drive with a blood alcohol level of .02 percent or more.","p":"Right. Under 21, the limit is .02."},"es":{"q":"En Wyoming, ¿a partir de qué nivel de alcohol en la sangre no puede manejar un conductor menor de 21 años?","o":[".05 por ciento",".02 por ciento",".08 por ciento",".10 por ciento"],"h1":"Es una fracción muy pequeña del límite para adultos.","h2":"En Wyoming un conductor menor de 21 años no puede manejar con un nivel de alcohol en la sangre de .02 por ciento o más.","p":"Correcto. Para menores de 21, el límite es .02."},"ref":{"doc":"WY","page":22}},{"id":"wy-018","scope":"WY","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Wyoming, how long is the license suspension when a driver under 21 is found driving at .02 or more?","o":["7 days","30 days","One year","90 days"],"h1":"It is about three months.","h2":"In Wyoming, a driver under 21 caught driving at .02 or more has the license suspended for 90 days.","p":"Right. The suspension is 90 days."},"es":{"q":"En Wyoming, ¿cuánto dura la suspensión de la licencia cuando un conductor menor de 21 años maneja con .02 o más?","o":["7 días","30 días","Un año","90 días"],"h1":"Son unos tres meses.","h2":"En Wyoming, a un conductor menor de 21 años que maneja con .02 o más se le suspende la licencia por 90 días.","p":"Correcto. La suspensión es de 90 días."},"ref":{"doc":"WY","page":22}},{"id":"wy-019","scope":"WY","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Wyoming, which speeding tickets always go on your driving record?","o":["Only tickets on interstates","Only tickets at night","Speeding in a school zone or construction zone","None of them"],"h1":"Think of places where children or workers may be near the road.","h2":"In Wyoming, a speeding violation in a school zone or a construction zone always goes on your driving record.","p":"Right. School and construction zones go on the record."},"es":{"q":"En Wyoming, ¿qué multas por exceso de velocidad siempre quedan en su historial de manejo?","o":["Solo las de autopistas interestatales","Solo las de noche","Las de exceso de velocidad en zona escolar o zona de obras","Ninguna"],"h1":"Piense en lugares donde puede haber niños o trabajadores cerca de la vía.","h2":"En Wyoming, una infracción por exceso de velocidad en una zona escolar o zona de obras siempre queda en su historial de manejo.","p":"Correcto. Las zonas escolares y de obras quedan en el historial."},"ref":{"doc":"WY","page":null}},{"id":"wy-020","scope":"WY","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Wyoming, is texting while driving allowed?","o":["Yes, on rural roads","No, texting while driving is banned","Yes, if you are over 21","Only at speeds under 30 mph"],"h1":"Reading or sending a message takes your eyes off the road.","h2":"Wyoming bans texting while driving, so you may not write, send or read a text message while driving on a public road.","p":"Right. Texting while driving is banned."},"es":{"q":"En Wyoming, ¿se permite enviar mensajes de texto mientras maneja?","o":["Sí, en caminos rurales","No, está prohibido enviar mensajes mientras maneja","Sí, si es mayor de 21 años","Solo a menos de 30 mph"],"h1":"Leer o enviar un mensaje le quita la vista de la vía.","h2":"Wyoming prohíbe enviar mensajes de texto mientras maneja, así que usted no puede escribir, enviar ni leer un mensaje mientras maneja en una vía pública.","p":"Correcto. Está prohibido enviar mensajes mientras maneja."},"ref":{"doc":"WY","page":89}}];
